Object.assign(window.DEEP = window.DEEP || {}, {
 "Adieu": {"pos":"n.m. 阳性名词，复数 adieux（常用复数）","s":"永别；告别。adieu 带「很难再见」的分量，比 au revoir 重得多。常用复数：faire ses adieux = 道别。也可作感叹词 Adieu !。","ipa":"[a.djø]","ph":"a [a]；ieu [jø]：先滑音 [j] 再发 [ø]；结尾 u 不单独发音。","pi":"别当成普通的「再见」：日常说 au revoir 或 salut。复数是 adieux（加 x）。","et":"由 à Dieu 合成，原意是「托付给上帝」。","ex":[["Ils se sont dit adieu.","他们互道永别。"],["Elle lui a fait ses adieux à la gare.","她在车站向他道别。"]],"co":[["faire ses adieux à quelqu'un","向某人道别"],["dire adieu à","告别……"],["un mot d'adieu","告别的话"]],"sy":[["au revoir","courant","再见（普通说法）"],["salut","familier","拜拜"]],"fq":"中频，书面和情感场合用。","me":"à Dieu：交给上帝，也许不再见。","tr":{"zh":"她在车站向我们道别。","fr":"Elle nous a fait ses adieux à la gare.","alt":"À la gare, elle nous a dit adieu.","note":"faire ses adieux 用复数；dire adieu 用单数。"}},
 "L'allaitement": {"pos":"n.m. 阳性名词，复数 allaitements","s":"哺乳；喂奶（母乳喂养）。allaitement maternel = 母乳喂养。动词是 allaiter。","ipa":"[a.lɛt.mɑ̃]","ph":"ai [ɛ]；-ement 读 [mɑ̃]，中间的 e 不发音；t 要读出来；l'a- 连读省音。","pi":"ai 读 [ɛ]，不是 [ai]；结尾 -ment 读鼻音 [mɑ̃]，不发 m 和 t。","et":"来自动词 allaiter（à + lait「奶」+ -er），再加后缀 -ment 变名词。","ex":[["L'allaitement maternel est recommandé.","推荐母乳喂养。"],["Elle a arrêté l'allaitement à six mois.","她在六个月时停止了哺乳。"]],"co":[["l'allaitement maternel","母乳喂养"],["allaiter un bébé","给婴儿喂奶"],["arrêter l'allaitement","断奶；停止哺乳"]],"sy":[["le biberon","courant","奶瓶喂养（相对）"],["le sevrage","courant","断奶"]],"fq":"中频，医疗和育儿话题。","me":"al-lait-ement：里面藏着 lait（奶）。","tr":{"zh":"医生推荐母乳喂养。","fr":"Le médecin recommande l'allaitement maternel.","alt":"Le médecin conseille d'allaiter le bébé.","note":"recommander + 名词；也可用 conseiller de + 动词原形。"}},
 "L'isolement": {"pos":"n.m. 阳性名词，复数 isolements","s":"孤立；隔离；孤独。可指人的孤立（l'isolement social），也指医学隔离、地点偏僻，或电、热的绝缘。","ipa":"[i.zɔl.mɑ̃]","ph":"s 在两个元音之间读 [z]；o 读开口的 [ɔ]；-ement 读 [mɑ̃]，e 不发音。","pi":"s 读 [z]，不是 [s]；结尾不发 t 以外的字母，-ment 读 [mɑ̃]。","et":"来自动词 isoler（借自意大利语 isolare，来自 isola「岛」），加后缀 -ment。字面意思是「变成孤岛」。","ex":[["L'isolement social est un problème grave.","社会孤立是一个严重的问题。"],["Le malade est en isolement.","病人正在隔离。"]],"co":[["l'isolement social","社会孤立"],["être en isolement","被隔离"],["souffrir d'isolement","饱受孤独之苦"]],"sy":[["la solitude","courant","孤独（感受，不一定是坏事）"],["l'isolation","courant","绝缘；隔热（物体）"]],"fq":"中高频，新闻和社会话题常见。","me":"isol- 来自 île：变成一座小岛。","tr":{"zh":"老年人的孤立是个大问题。","fr":"L'isolement des personnes âgées est un grand problème.","alt":"Les personnes âgées se sentent souvent très isolées.","note":"isolement 是名词；形容词是 isolé(e)。"}},
 "Le classique": {"pos":"n.m. 阳性名词，复数 classiques","s":"古典音乐；经典（作品）。口语中 du classique = 古典音乐（la musique classique 的简称）。也指文学、电影、时尚里的「经典」。classique 还是形容词：经典的，传统的。","ipa":"[kla.sik]","ph":"cl- [kl]；ss 读 [s]；qu 读 [k]；结尾 -que 的 e 不发音。","pi":"qu 读 [k]，不读 [kw]；ss 读清音 [s]。这个名词是阳性。","et":"来自拉丁语 classicus（属于最高等级的），与 classe 同源。","ex":[["Elle écoute souvent du classique.","她经常听古典音乐。"],["Ce film est un classique du cinéma.","这部电影是电影史上的经典。"]],"co":[["écouter du classique","听古典音乐"],["un classique du cinéma","电影经典"],["c'est un classique !","这是老套路！（常见情况）"]],"sy":[["la musique classique","courant","古典音乐（完整说法）"],["un chef-d'œuvre","courant","杰作"]],"fq":"中高频，日常常用。","me":"classique：属于「头等舱」(classe) 的作品。","tr":{"zh":"我开车时喜欢听古典音乐。","fr":"J'aime écouter du classique en voiture.","alt":"En voiture, j'écoute souvent de la musique classique.","note":"écouter du + 名词：听某类音乐，用部分冠词。"}},
 "Le confinement": {"pos":"n.m. 阳性名词，复数 confinements","s":"封城；居家隔离；封闭。新冠期间指全国居家令：le confinement。一般意义是「被限制在某个范围内」。","ipa":"[kɔ̃.fin.mɑ̃]","ph":"on 读鼻化 [ɔ̃]；i 读 [i]；n 要读出来；结尾 -ment 读 [mɑ̃]。","pi":"con- 和 -ment 都是鼻音，但中间的 -fine- 里的 n 不是鼻音，要单独读 [n]。","et":"来自动词 confiner（关在界限内），源于 confins「边界」；加后缀 -ment。","ex":[["Le confinement a été long.","封城持续了很久。"],["Pendant le confinement, nous restions chez nous.","封城期间，我们待在家里。"]],"co":[["le premier confinement","第一次封城"],["être en confinement","处于居家隔离"],["lever le confinement","解除封城"]],"sy":[["la quarantaine","courant","隔离（检疫）"],["l'isolement","courant","隔离；孤立"]],"fq":"2020 年后高频，新闻常用。","me":"con + fin：被关在「边界」(fin) 里面。","tr":{"zh":"封城期间我们都在家工作。","fr":"Pendant le confinement, nous travaillions tous à la maison.","alt":"Durant le confinement, on télétravaillait tous.","note":"pendant + 名词表示持续的时间段；过去持续用未完成过去时。"}},
 "Le COVID-19": {"pos":"n.m. 阳性名词（也有人用阴性 la covid），不变","s":"新冠肺炎。由 co(rona) + vi(rus) + d(isease) + 2019 组成。口语常说 le covid，学术界推荐用阴性 la covid（因为 maladie 是阴性），两种都能听到。","ipa":"[kɔ.vid.diz.nœf]","ph":"按字母读：covid [kɔ.vid]，d 要读出来；19 读 dix-neuf [diz.nœf]，其中 x 读 [z]。","pi":"不要读成英语的 [ˈkoʊvɪd]；法语重音在最后。性别有两种用法：le covid 最常见。","et":"缩略词：CO-rona VI-rus D-isease 2019（英语 coronavirus disease 2019）。","ex":[["Le COVID-19 a changé nos vies.","新冠改变了我们的生活。"],["Il a eu le covid l'an dernier.","他去年得过新冠。"]],"co":[["attraper le covid","感染新冠"],["un test de covid","新冠检测"],["le vaccin contre le covid","新冠疫苗"]],"sy":[["le coronavirus","courant","冠状病毒（更宽泛）"],["la pandémie","courant","大流行"]],"fq":"2020 年后高频，日常和新闻常用。","me":"CO-VI-D：三个词头加上 19，读 dix-neuf。","tr":{"zh":"新冠改变了我们的日常生活。","fr":"Le COVID-19 a changé notre vie quotidienne.","alt":"Le covid a changé notre quotidien.","note":"a changé：passé composé，动词 changer 用 avoir。"}},
 "Le destin": {"pos":"n.m. 阳性名词，复数 destins","s":"命运；天命。指人无法控制、冥冥中注定的走向。也指一个人的人生轨迹（le destin d'un peuple）。比 la chance（运气）更宏大、更有宿命感。","ipa":"[dɛs.tɛ̃]","ph":"des [dɛs]：e 读 [ɛ]，s 要读出来；-in 读鼻化 [ɛ̃]；结尾 n 不发音。","pi":"des 里的 s 要发音，不是 dé；-in 是鼻音 [ɛ̃]，别读成 [in]。","et":"来自动词 destiner（拉丁语 destinare「固定，决定」）的名词形式。同族：destination。","ex":[["C'est le destin qui les a réunis.","是命运让他们相遇。"],["On ne peut pas échapper à son destin.","人逃不过自己的命运。"]],"co":[["croire au destin","相信命运"],["un destin tragique","悲惨的命运"],["maîtriser son destin","掌握自己的命运"],["le destin d'un peuple","一个民族的命运"]],"sy":[["le sort","courant","命运（更偏运气、结果）"],["la fatalité","soutenu","宿命；厄运"]],"fq":"中频，书面和谈论人生时用。","me":"dest- 来自 destiner：命中「注定」要去的地方 = destination。","tr":{"zh":"我相信每个人都有自己的命运。","fr":"Je crois que chacun a son destin.","alt":"Je crois au destin : chacun a le sien.","note":"croire au destin 用 à；croire que + 直陈式。"}},
 "Le jazz": {"pos":"n.m. 阳性名词，不变（jazz 无复数形式）","s":"爵士乐。借自英语 jazz。可以说 du jazz（听／演奏爵士），也可以说 le jazz（泛指这种音乐）。作定语时用 de jazz：un club de jazz。","ipa":"[dʒaz]","ph":"j 在这个借词里读 [dʒ]，像英语 jazz；zz 读一个 [z]；a [a]。","pi":"不是 [ʒaz]（法语 j 的发音），而是 [dʒaz]，保持英语读法。","et":"借自美国英语 jazz；英语词本身的来源不确定。","ex":[["Le jazz est une musique très relaxante.","爵士乐是一种非常放松的音乐。"],["Il joue du jazz dans un petit club.","他在一家小俱乐部演奏爵士。"]],"co":[["jouer du jazz","演奏爵士"],["un club de jazz","爵士俱乐部"],["un festival de jazz","爵士音乐节"]],"sy":[["le blues","courant","蓝调（相近）"],["le swing","courant","摇摆乐（爵士的一种风格）"]],"fq":"中频，日常常用。","me":"听起来和英语一样：[dʒaz]。","tr":{"zh":"晚上我喜欢听爵士乐。","fr":"Le soir, j'aime écouter du jazz.","alt":"Le soir, je mets du jazz.","note":"écouter du jazz：部分冠词 du。"}},
 "Le lâcher-prise": {"pos":"n.m. 阳性名词，复数 lâcher-prises（少用）","s":"放手；放下；不再执着。心理和生活方式词汇，指学会不去控制一切。来自动词短语 lâcher prise（松手，放开抓着的东西）。","ipa":"[la.ʃe.pʁiz]","ph":"â 读 [a]（现代口语不再区分长短）；ch [ʃ]；r 是小舌音 [ʁ]；结尾 se 读 [z]，e 不发音。","pi":"prise 的 s 读 [z]；中间有连字符，是一个复合名词。动词短语写作 lâcher prise，没有连字符。","et":"由 lâcher（松开）+ prise（抓握，来自 prendre）构成。lâcher 来自拉丁语 laxare「放松」。","ex":[["Le yoga favorise le lâcher-prise.","瑜伽有助于放下。"],["Il a lâché prise et s'est senti libre.","他放下了，感到自由。"]],"co":[["apprendre le lâcher-prise","学会放手"],["lâcher prise","松手；放手"],["un exercice de lâcher-prise","放下的练习"]],"sy":[["l'acceptation","courant","接受（现实）"],["le détachement","soutenu","超脱"]],"fq":"中频，心理、瑜伽、生活方式话题常见。","me":"lâcher + prise：松开你的「抓握」。","tr":{"zh":"学会放手并不容易。","fr":"Apprendre le lâcher-prise n'est pas facile.","alt":"C'est pas facile d'apprendre à lâcher prise.","note":"动词短语 lâcher prise 无连字符；名词有连字符。"}},
 "Le rap": {"pos":"n.m. 阳性名词，不变","s":"说唱（音乐）。借自英语 rap。法国说唱很流行，常说 le rap français。说唱歌手：un rappeur / une rappeuse。","ipa":"[ʁap]","ph":"r 是小舌音 [ʁ]；a [a]；结尾 p 在这个词里要读出来 [p]。","pi":"结尾 p 要发音；r 是喉咙里的音，不是英语的 r，也不是中文的 r。","et":"借自英语 rap。派生词：rappeur（说唱歌手）。","ex":[["Il écrit des textes de rap.","他写说唱歌词。"],["Le rap français est très populaire.","法国说唱非常受欢迎。"]],"co":[["écouter du rap","听说唱"],["un rappeur / une rappeuse","说唱歌手"],["un concert de rap","说唱演唱会"]],"sy":[["le hip-hop","courant","嘻哈（更大的文化）"],["la chanson","courant","歌曲（泛指）"]],"fq":"中高频，日常常用。","me":"和 rock 一样要用小舌音 [ʁ]。","tr":{"zh":"我弟弟每天听说唱。","fr":"Mon frère écoute du rap tous les jours.","alt":"Mon frère passe son temps à écouter du rap.","note":"écouter du rap：部分冠词。"}},
 "Le rock": {"pos":"n.m. 阳性名词，不变","s":"摇滚乐。借自英语 rock。le rock 泛指这种音乐，也常见 rock'n'roll。形容词：rock（不变），如 une chanson rock。","ipa":"[ʁɔk]","ph":"r 小舌音 [ʁ]；o 读开口 [ɔ]；ck 读 [k]。","pi":"o 读 [ɔ]，不是英语的 [ɒ] 或中文的「欧」；r 是喉咙里的音。","et":"借自英语 rock（rock and roll 的简称）。","ex":[["Mon frère adore écouter du rock.","我哥哥爱听摇滚。"],["Ce groupe fait du rock français.","这个乐队玩的是法国摇滚。"]],"co":[["écouter du rock","听摇滚"],["un groupe de rock","摇滚乐队"],["un concert de rock","摇滚演唱会"]],"sy":[["le rock'n'roll","courant","摇滚乐（完整说法）"],["le métal","courant","金属乐（更重的一种）"]],"fq":"中高频，日常常用。","me":"和英语 rock 同形，但 r 要换成喉咙里的 [ʁ]。","tr":{"zh":"我喜欢听摇滚，不爱听古典。","fr":"J'aime le rock, mais pas le classique.","alt":"Moi, j'écoute du rock, pas de classique.","note":"表达喜好时用定冠词：aimer le rock。"}},
 "Le succès": {"pos":"n.m. 阳性名词，单复数同形 succès","s":"成功；成绩；受欢迎。avoir du succès = 受欢迎，成功。注意它是名词，动词是 réussir，不是 succéder（后者是「继承；接着」）。","ipa":"[syk.sɛ]","ph":"u 读 [y]；cc 在 è 前读 [ks]；è 读 [ɛ]；结尾 s 不发音。","pi":"cc 读 [ks]，不是 [k]。结尾 s 不读，所以单复数听起来一样。别把 succès 和英语 success [səkˈsɛs] 的读法混淆。","et":"来自拉丁语 successus（结果），与 succéder 同源。","ex":[["Son dernier livre est un grand succès.","他的最新著作大获成功。"],["Ce film a eu beaucoup de succès.","这部电影很受欢迎。"]],"co":[["avoir du succès","受欢迎；成功"],["un grand succès","大获成功"],["avec succès","成功地"],["Bon succès !","祝你成功！"]],"sy":[["la réussite","courant","成功（偏个人结果）"],["le triomphe","soutenu","大胜；大获成功"]],"fq":"极高频，日常常用。","me":"suc-cès：两个 c 连起来读 [ks]，像「叔克赛」。","tr":{"zh":"这家餐厅很受欢迎。","fr":"Ce restaurant a beaucoup de succès.","alt":"Ce restaurant marche très bien.","note":"avoir du succès / beaucoup de succès。"}},
 "Le système": {"pos":"n.m. 阳性名词，复数 systèmes","s":"制度；系统；体系。le système éducatif = 教育制度；le système informatique = 信息系统；le système solaire = 太阳系。有时带贬义：le système = 「体制」。","ipa":"[sis.tɛm]","ph":"y 读 [i]；s 在词首读 [s]，第二个 s 也是 [s]；è 读 [ɛ]；结尾 -me 的 e 不发音。","pi":"y 读 [i]，不是 [y] 也不是英语的 [ɪ]。注意这个词是阳性：le système，虽然以 -e 结尾。","et":"来自希腊语 systema（组合在一起的整体），经拉丁语进入法语。","ex":[["Le système éducatif doit être réformé.","教育制度需要改革。"],["Le système ne fonctionne plus.","系统不能用了。"]],"co":[["le système éducatif","教育制度"],["le système solaire","太阳系"],["un système informatique","计算机系统"],["le système D","自己想办法（口语）"]],"sy":[["l'organisation","courant","组织；结构"],["le régime","courant","政权；制度（政治）"]],"fq":"高频，日常和书面都常用。","me":"sys-tème：y 读 i，和 sis 一样。","tr":{"zh":"这个系统不太好用。","fr":"Ce système ne marche pas très bien.","alt":"Ce système est pas terrible.","note":"marcher / fonctionner 都可表示「运作」。"}},
 "Le talent": {"pos":"n.m. 阳性名词，复数 talents","s":"才能；天赋。可以指某方面的天分（un talent pour le dessin），也可以指有才华的人（un jeune talent）。","ipa":"[ta.lɑ̃]","ph":"ta [ta]；len 读鼻化 [lɑ̃]；结尾 t 不发音。","pi":"-ent 读 [ɑ̃]；结尾 t 不发音，别读成 [talɛnt]。介词常用 pour：talent pour。","et":"来自拉丁语 talentum，源于希腊语 talanton（古代重量和钱币单位）。「才能」的意义来自《圣经》中「talents」的寓言。","ex":[["Elle a un talent incroyable pour le dessin.","她有惊人的绘画天赋。"],["C'est un jeune talent du football.","他是足球界的年轻天才。"]],"co":[["avoir du talent","有才华"],["un talent pour + 名词","在……方面的天赋"],["un talent caché","隐藏的才能"],["découvrir un talent","发现人才"]],"sy":[["le don","courant","天赋"],["l'aptitude","soutenu","能力；资质"]],"fq":"中高频，日常常用。","me":"talent 读成「塔朗」，最后没有 t。","tr":{"zh":"他对音乐很有天赋。","fr":"Il a beaucoup de talent pour la musique.","alt":"Il est vraiment doué pour la musique.","note":"talent pour + 名词；形容词 doué pour 更口语。"}},
 "Un amateur": {"pos":"n.m. 阳性名词，复数 amateurs（也可用于女性：une amateur）","s":"业余爱好者；外行。也有「爱好者，行家」的意思：un amateur de jazz = 爵士迷。作形容词时：业余的。注意 travail d'amateur 有贬义（做得不专业）。","ipa":"[a.ma.tœʁ]","ph":"a-ma-teur：三个音节；eu 读 [œ]；结尾 r 要读出来 [ʁ]。","pi":"结尾的 r 要发 [ʁ]；eu 读 [œ]（嘴比 [ø] 开一点）。女性常说 une amateur。","et":"来自拉丁语 amator（爱好者），源于 amare「爱」。同族：amour。","ex":[["C'est un travail d'amateur.","这是外行的作品。"],["C'est un grand amateur de cinéma.","他是个影迷。"]],"co":[["un amateur de + 名词","……爱好者"],["un travail d'amateur","外行的活儿"],["un photographe amateur","业余摄影师"],["en amateur","以业余身份"]],"sy":[["le débutant","courant","新手"],["le passionné","courant","狂热者"],["le profane","soutenu","外行"]],"fq":"中频，日常常用。","me":"amat- 来自 amare：因为「爱」所以做，不为钱。","tr":{"zh":"他是一个业余摄影师。","fr":"C'est un photographe amateur.","alt":"Il fait de la photo en amateur.","note":"amateur 作形容词，放在名词后，不变。"}},
 "Un ancêtre": {"pos":"n.m. 阳性名词，复数 ancêtres（男女同形：une ancêtre 也可）","s":"祖先；先人。常用复数 les ancêtres。也可指事物的前身：l'ancêtre de l'ordinateur = 计算机的前身。","ipa":"[ɑ̃.sɛtʁ]","ph":"an 读 [ɑ̃]；c 在 e 前读 [s]；ê 读 [ɛ]；结尾 -tre 读 [tʁ]，e 不发音。","pi":"ê 读 [ɛ]，不是 [e]。c 在这里读 [s]。别和 ancien（古老的）混淆，虽然两者同源。","et":"来自拉丁语 antecessor（走在前面的人）。同族：ancien（古老的）。","ex":[["Ses ancêtres venaient d'Irlande.","他的祖先来自爱尔兰。"],["Le boulier est l'ancêtre de la calculatrice.","算盘是计算器的前身。"]],"co":[["nos ancêtres","我们的祖先"],["l'ancêtre de + 名词","……的前身"],["un ancêtre commun","共同的祖先"]],"sy":[["l'aïeul","littéraire","祖先（书面）"],["le précurseur","soutenu","先驱"]],"fq":"中频，日常和书面都用。","me":"ancêtre ← ancien：「很早以前」的人。","tr":{"zh":"我的祖先来自中国。","fr":"Mes ancêtres venaient de Chine.","alt":"Mes ancêtres sont chinois.","note":"venir de + 国家；注意 Chine 是阴性，不加冠词。"}},
 "Un annuaire": {"pos":"n.m. 阳性名词，复数 annuaires","s":"电话簿；名录；年鉴。过去指纸质电话本（l'annuaire téléphonique）。今天也指通讯录、目录、校友录。","ipa":"[a.nɥɛʁ]","ph":"nn 读一个 [n]；u 在 a 前读半元音 [ɥ]；aire 读 [ɛʁ]。","pi":"ai 读 [ɛ]，不读成 [ai]；结尾 r 要读 [ʁ]。nn 只发一个 n。","et":"由 annuel（每年的）派生，来自拉丁语 annus「年」。原指每年出版一次的册子。","ex":[["J'ai cherché son numéro dans l'annuaire.","我在电话簿里找他的号码。"],["L'annuaire de l'école est en ligne.","学校的通讯录在网上。"]],"co":[["l'annuaire téléphonique","电话簿"],["chercher dans l'annuaire","在电话簿里查"],["un annuaire en ligne","在线名录"]],"sy":[["le répertoire","courant","通讯录；目录"],["le bottin","familier","电话簿（老一辈用语）"]],"fq":"中低频，如今日常用得少。","me":"annu- 来自 année：每年出版一本。","tr":{"zh":"我在电话簿里找到了他的号码。","fr":"J'ai trouvé son numéro dans l'annuaire.","alt":"J'ai son numéro, je l'ai trouvé dans l'annuaire.","note":"trouver：passé composé，用 avoir。"}},
 "Un atelier": {"pos":"n.m. 阳性名词，复数 ateliers","s":"工作室；车间；作坊。画家、工匠的工作场所；也指培训班、工作坊：un atelier d'écriture = 写作工作坊。","ipa":"[a.tə.lje]","ph":"a [a]；te 读弱化的 [tə]；lier 读 [lje]（i 是半元音 [j]）；结尾 r 不发音。","pi":"结尾 -ier 读 [je]，r 不发音。中间 e 很轻，快读时常省略成 [a.tlje]。","et":"来自古法语 astelier（木匠作坊），与 astelle「木片」有关。","ex":[["L'artiste travaille dans son atelier.","艺术家在他的工作室工作。"],["Je participe à un atelier de théâtre.","我参加一个戏剧工作坊。"]],"co":[["un atelier d'artiste","艺术家工作室"],["un atelier d'écriture","写作工作坊"],["un atelier de réparation","维修车间"],["un atelier de cuisine","烹饪工作坊"]],"sy":[["l'usine","courant","工厂（更大）"],["le studio","courant","工作室；单间公寓"],["le séminaire","soutenu","研讨班"]],"fq":"中高频，日常常用。","me":"atelier 的 -ier 读 [je]，和 cahier 一样。","tr":{"zh":"周六我去参加绘画工作坊。","fr":"Samedi, je vais à un atelier de peinture.","alt":"Samedi, j'ai un atelier de peinture.","note":"aller à + 地点／活动；周六不加冠词：samedi。"}},
 "Un banc": {"pos":"n.m. 阳性名词，复数 bancs","s":"长椅；长凳。公园、车站常见。也指：un banc de poissons = 鱼群；un banc de sable = 沙洲；un banc d'essai = 试验台。","ipa":"[bɑ̃]","ph":"b [b]；an 读鼻化 [ɑ̃]；结尾 c 不发音。","pi":"结尾 c 不发音：banc [bɑ̃]。别和 bain（洗澡）[bɛ̃] 混淆：an 与 ain 的鼻音不同。","et":"借自日耳曼语（法兰克语 bank），与英语 bank、bench 同源。","ex":[["Nous nous sommes assis sur un banc.","我们坐在长椅上。"],["Le banc est libre, on s'assoit ?","长椅是空的，我们坐一会儿？"]],"co":[["un banc public","公共长椅"],["un banc de poissons","鱼群"],["un banc de sable","沙洲"],["s'asseoir sur un banc","坐在长椅上"]],"sy":[["la chaise","courant","椅子（有靠背，单人）"],["la banquette","courant","长座椅（车、咖啡馆）"]],"fq":"中频，日常常用。","me":"banc = 「棒」：和 bank、bench 是亲戚。","tr":{"zh":"我们在公园的长椅上休息。","fr":"Nous nous reposons sur un banc du parc.","alt":"On se repose sur un banc dans le parc.","note":"se reposer 是代词式动词；sur un banc。"}},
 "Un cabaret": {"pos":"n.m. 阳性名词，复数 cabarets","s":"歌舞表演场；夜总会式小剧场。巴黎的 Moulin Rouge 就是 cabaret。有吃喝、歌舞、小品表演。旧义是小酒馆。","ipa":"[ka.ba.ʁɛ]","ph":"ca [ka]；ba [ba]；ret 读 [ʁɛ]，结尾 t 不发音。","pi":"结尾 t 不发音：cabaret [ka.ba.ʁɛ]。r 是小舌音。","et":"来源不确定（可能来自中古荷兰语或皮卡第语）。","ex":[["Nous avons passé la soirée dans un cabaret.","我们在歌舞厅度过了晚上。"],["Le cabaret de Montmartre est célèbre.","蒙马特的歌舞厅很有名。"]],"co":[["aller au cabaret","去歌舞厅"],["un spectacle de cabaret","歌舞表演"],["un cabaret parisien","巴黎歌舞厅"]],"sy":[["la boîte de nuit","courant","夜总会"],["le music-hall","courant","歌舞杂耍剧场"]],"fq":"中低频，文化和旅游话题。","me":"cabaret 里 t 不读，像 « cabaré »。","tr":{"zh":"我们想去巴黎的歌舞厅。","fr":"Nous voulons aller dans un cabaret à Paris.","alt":"On aimerait sortir dans un cabaret parisien.","note":"vouloir + 动词原形；aller dans un cabaret。"}},
 "Un chevalet": {"pos":"n.m. 阳性名词，复数 chevalets","s":"画架；支架。画家用来支撑画布的三脚架或框架。也指小提琴的琴马、锯木的支架。","ipa":"[ʃə.va.lɛ]","ph":"ch [ʃ]；e 弱读 [ə]；va [va]；let 读 [lɛ]，t 不发音。","pi":"ch 读 [ʃ]，不是 [tʃ]。结尾 t 不发音。","et":"由 cheval（马）+ 指小后缀 -et 构成：「小马」，因为架子像马的形状。","ex":[["Le peintre a installé son chevalet.","画家支好了画架。"],["Elle pose sa toile sur le chevalet.","她把画布放到画架上。"]],"co":[["installer son chevalet","支起画架"],["peindre au chevalet","在画架前作画"],["un chevalet de peintre","画家的画架"]],"sy":[["le support","courant","支架（泛指）"],["le trépied","courant","三脚架"]],"fq":"中低频，艺术话题用。","me":"cheval + -et：一匹「小马」帮你托住画布。","tr":{"zh":"画家把画布放在画架上。","fr":"Le peintre pose sa toile sur le chevalet.","alt":"Le peintre met sa toile sur son chevalet.","note":"poser / mettre sur + 名词。"}},
 "Un engagement": {"pos":"n.m. 阳性名词，复数 engagements","s":"承诺；投入；参与。可指承诺（tenir ses engagements）、社会或政治参与（l'engagement associatif）、聘用。注意：英语 engagement 里的「订婚」在法语是 fiançailles。","ipa":"[ɑ̃.ɡaʒ.mɑ̃]","ph":"en 读 [ɑ̃]；ga 读 [ɡa]（g 是硬音）；ge 读 [ʒ]，e 不发音；-ment 读 [mɑ̃]。","pi":"前一个 g 读 [ɡ]，后一个 g 读 [ʒ]，要分清；-ment 读鼻音，不发 t。","et":"来自动词 engager（en + gage「抵押」），加后缀 -ment。字面是「把自己押上」。","ex":[["C'est un engagement important.","这是一个重要的承诺。"],["Il tient toujours ses engagements.","他总是信守承诺。"]],"co":[["prendre un engagement","做出承诺"],["tenir ses engagements","信守承诺"],["l'engagement politique","政治参与"],["sans engagement","无需承诺"]],"sy":[["la promesse","courant","诺言"],["l'implication","soutenu","投入"]],"fq":"中高频，日常和书面都用。","me":"en + gage：把自己「押」上去 = 承诺。","tr":{"zh":"他总是信守他的承诺。","fr":"Il tient toujours ses engagements.","alt":"Il tient toujours parole.","note":"tenir ses engagements：固定搭配；engagement 用复数。"}},
 "Un leader": {"pos":"n.m. 阳性名词，复数 leaders（男女通用：une leader）","s":"领袖；领头者；龙头。用于政治、团队、公司：le leader du marché = 市场领导者。借自英语，口语和新闻都用，可指人或企业、产品。","ipa":"[li.dœʁ]","ph":"ea 读 [i]；d [d]；er 读 [œʁ]，类似 leur；结尾 r 要发音 [ʁ]。","pi":"不是英语的 [ˈliːdər]，法语结尾是 [dœʁ]。r 是小舌音。","et":"借自英语 leader。法语也有自己的词 chef、dirigeant。","ex":[["Il est le leader de ce groupe.","他是这个团体的领袖。"],["Cette entreprise est leader sur son marché.","这家企业是市场的龙头。"]],"co":[["le leader du parti","党的领袖"],["un leader d'opinion","意见领袖"],["être leader sur le marché","在市场上领先"],["un leadership fort","强有力的领导力"]],"sy":[["le chef","courant","领导；首领"],["le dirigeant","courant","领导人；管理者"],["le meneur","soutenu","带头人"]],"fq":"高频，新闻和职场常用。","me":"和英语 leader 同形，结尾换成 [dœʁ]。","tr":{"zh":"她是我们团队的领头人。","fr":"Elle est la leader de notre équipe.","alt":"C'est elle qui dirige notre équipe.","note":"leader 可以用阴性冠词：la leader。"}},
 "Un micro-trottoir": {"pos":"n.m. 阳性名词，复数 micros-trottoirs","s":"街头采访。记者拿着话筒在街上随机采访路人，请大家发表看法。也说 faire un micro-trottoir。","ipa":"[mi.kʁo.tʁɔ.twaʁ]","ph":"mi-cro：o 读 [o]；trot-toir：tt 读一个 [t]，o 读 [ɔ]；-oir 读 [waʁ]，r 要发音。","pi":"trottoir 里 oi 读 [wa]；r 小舌音；复数两部分都加 s：micros-trottoirs。","et":"由 micro（microphone 的缩写）+ trottoir（人行道）构成。trottoir 来自 trotter「小跑」。","ex":[["Le journaliste fait un micro-trottoir.","记者在做街头采访。"],["Le micro-trottoir interroge les passants.","街头采访向路人提问。"]],"co":[["faire un micro-trottoir","做街头采访"],["un micro-trottoir sur + 话题","关于……的街头采访"],["interroger les passants","采访路人"]],"sy":[["le sondage","courant","民意调查（更正式，有统计）"],["l'interview","courant","采访"]],"fq":"中低频，媒体话题常见。","me":"话筒 (micro) + 人行道 (trottoir) = 在街上采访。","tr":{"zh":"记者在街上采访路人。","fr":"Le journaliste fait un micro-trottoir dans la rue.","alt":"Le journaliste interroge les passants dans la rue.","note":"faire un micro-trottoir：固定搭配。"}},
 "Un moyen": {"pos":"n.m. 阳性名词，复数 moyens（常用复数）","s":"方法；手段；办法。常用复数 les moyens = 经济能力：avoir les moyens。il y a moyen de... = 有办法……。注意 moyen 还是形容词：中等的，平均的。","ipa":"[mwa.jɛ̃]","ph":"oy 读 [waj]，y 相当于两个 i：moi-yen；-en 读鼻化 [jɛ̃]。","pi":"oyen 要读成 [waj.ɛ̃]：中间多一个 [j]。-en 读 [ɛ̃]，不读 [ɑ̃]。","et":"来自晚期拉丁语 medianus（居中的），与 milieu、médian 同族：居中的东西，即「中介」→ 手段。","ex":[["C'est un bon moyen d'apprendre.","这是个学习的好方法。"],["Je n'ai pas les moyens de payer ça.","我付不起这个。"]],"co":[["un moyen de + 动词原形","……的方法"],["avoir les moyens","有钱；有条件"],["il y a moyen de + 动词","有办法……"],["un moyen de transport","交通工具"]],"sy":[["la méthode","courant","方法（系统性）"],["la manière","courant","方式"],["le procédé","soutenu","手段；做法"]],"fq":"极高频，日常常用。","me":"moyen：中间的东西，连接目标的「中介」。","tr":{"zh":"我们需要找到解决办法。","fr":"Nous devons trouver un moyen de résoudre ça.","alt":"Il faut trouver un moyen de régler ça.","note":"un moyen de + 动词原形。"}},
 "Un pédiatre": {"pos":"n.m. 阳性名词，复数 pédiatres（男女同形：une pédiatre）","s":"儿科医生。孩子生病时看的医生。形容词：pédiatrique；学科：la pédiatrie。","ipa":"[pe.djatʁ]","ph":"pé [pe]；dia 读 [dja]；结尾 -tre 读 [tʁ]，e 不发音。","pi":"é 是闭口 [e]；-atre 读 [atʁ]，e 不发音，所以只有两个音节。","et":"来自希腊语 pais, paidos（孩子）+ iatros（医生）。","ex":[["Le pédiatre a examiné l'enfant.","儿科医生检查了孩子。"],["Nous avons rendez-vous chez le pédiatre.","我们约了儿科医生。"]],"co":[["aller chez le pédiatre","去看儿科医生"],["prendre rendez-vous chez le pédiatre","预约儿科医生"],["un service de pédiatrie","儿科病房"]],"sy":[["le médecin","courant","医生（泛指）"],["le généraliste","courant","全科医生"]],"fq":"中频，育儿和医疗话题。","me":"péd- = 孩子（希腊语 pais）：pédiatre = 孩子的医生。","tr":{"zh":"我明天带女儿去看儿科医生。","fr":"Demain, j'emmène ma fille chez le pédiatre.","alt":"Demain, je vais chez le pédiatre avec ma fille.","note":"chez + 医生；emmener 带人去。"}},
 "Un piano": {"pos":"n.m. 阳性名词，复数 pianos","s":"钢琴。jouer du piano = 弹钢琴（乐器前用 de + 冠词）。un piano droit = 立式钢琴；un piano à queue = 三角钢琴。","ipa":"[pja.no]","ph":"pi 与 a 连成 [pja]；no 读 [no]；一共两个音节。","pi":"不是三个音节 pi-a-no，而是 [pja.no]。乐器前用 jouer DE：jouer du piano。","et":"来自意大利语 pianoforte「轻柔又强劲」的缩略，piano 本义是「轻柔」。","ex":[["Il joue du piano tous les jours.","他每天弹钢琴。"],["Elle prend des cours de piano.","她在上钢琴课。"]],"co":[["jouer du piano","弹钢琴"],["un piano à queue","三角钢琴"],["un cours de piano","钢琴课"],["un pianiste / une pianiste","钢琴家"]],"sy":[["le clavier","courant","键盘（电子琴）"],["l'orgue","courant","管风琴"]],"fq":"中高频，日常常用。","me":"piano：[pja.no]，两拍，别拆成三拍。","tr":{"zh":"我女儿每周上钢琴课。","fr":"Ma fille prend un cours de piano chaque semaine.","alt":"Ma fille fait du piano une fois par semaine.","note":"jouer DU piano / faire DU piano。"}},
 "Un pote": {"pos":"n.m. 阳性名词，复数 potes（女性：une pote）","s":"哥们儿；朋友。非常口语（familier），年轻人之间常用。比 un ami 随意，和 un copain 相近。不要用在正式场合。","ipa":"[pɔt]","ph":"p [p]；o 读开口 [ɔ]；结尾 t 要读出来 [t]；e 不发音。","pi":"t 要发音：pote [pɔt]。别和 pot（罐子，t 不发音）混淆。pote 带 e，所以 t 读出来。","et":"来源不确定（口语词，可能与 pot、copain 的构词有关）。","ex":[["Je vais voir un pote ce soir.","今晚我去见个哥们儿。"],["C'est mon meilleur pote.","他是我最好的哥们儿。"]],"co":[["un bon pote","好哥们儿"],["mon pote","我哥们儿（称呼）"],["sortir avec des potes","和朋友们出去玩"]],"sy":[["un copain","familier","朋友；伙伴"],["un ami","courant","朋友"],["un camarade","courant","同学；同伴"]],"fq":"中高频，口语很常见，书面少见。","me":"pote = 哥们，听起来短促，像「破特」。","tr":{"zh":"周末我和哥们儿去踢球。","fr":"Ce week-end, je joue au foot avec des potes.","alt":"Ce week-end, je fais un foot avec mes potes.","note":"jouer au foot；avec des potes 复数。"}},
 "Un proche": {"pos":"n.m. 阳性名词，复数 proches（常用复数；形容词 proche 阴阳同形）","s":"亲近的人；亲人。通常指家人和好友，常用复数 ses proches。形容词 proche = 近的，邻近的。","ipa":"[pʁɔʃ]","ph":"pr [pʁ]，r 小舌音；o 读开口 [ɔ]；ch 读 [ʃ]；结尾 e 不发音。","pi":"o 读 [ɔ]；ch 读 [ʃ]；整个词只有一个音节。","et":"来自晚期拉丁语，与拉丁语 prope「近」同源。","ex":[["Il a perdu un proche récemment.","他最近失去了一位亲人。"],["Prévenez vos proches.","请通知您的亲友。"]],"co":[["ses proches","他的亲友"],["perdre un proche","失去亲人"],["un proche de + 人","……的亲近的人"],["proche de","靠近……"]],"sy":[["la famille","courant","家人"],["l'entourage","courant","周围的人"],["l'intime","soutenu","知己"]],"fq":"中高频，日常和新闻常用。","me":"proche：离你「近」的人。","tr":{"zh":"他的亲友都来了。","fr":"Tous ses proches sont venus.","alt":"Tous ses proches étaient là.","note":"tous + 复数名词；venir 用 être。"}},
 "Un refuge": {"pos":"n.m. 阳性名词，复数 refuges","s":"避难所；庇护所；避风港。也指山中小屋：un refuge de montagne。比喻：安全、安静的地方。","ipa":"[ʁə.fyʒ]","ph":"re 读弱化 [ʁə]；fu 读 [fy]（u 嘴圆）；ge 读 [ʒ]。","pi":"u 读 [y]，不是 [u]；g 在 e 前读 [ʒ]；结尾 e 不发音。","et":"来自拉丁语 refugium（re- 返回 + fugere 逃跑）。同族：réfugié（难民）。","ex":[["Cet endroit est mon refuge.","这个地方是我的避风港。"],["Nous avons dormi dans un refuge de montagne.","我们睡在山中小屋里。"]],"co":[["chercher refuge","寻求庇护"],["un refuge de montagne","山中小屋"],["un refuge pour animaux","动物收容所"],["trouver refuge","找到避难处"]],"sy":[["l'abri","courant","遮蔽处"],["l'asile","soutenu","庇护所；收容"],["le havre","littéraire","港湾"]],"fq":"中频，日常和书面都用。","me":"re-fuge：回头 (re) 逃跑 (fuir) 的地方。","tr":{"zh":"我的花园是我的避风港。","fr":"Mon jardin est mon refuge.","alt":"C'est dans mon jardin que je me sens à l'abri.","note":"être mon refuge：用物主形容词。"}},
 "Un réseau": {"pos":"n.m. 阳性名词，复数 réseaux（-eau 的复数加 x）","s":"网络；人脉；网状系统。le réseau social = 社交网络；le réseau de transport = 交通网；avoir un bon réseau = 人脉广。","ipa":"[ʁe.zo]","ph":"ré [ʁe]；s 在两个元音之间读 [z]；eau 读 [o]。","pi":"s 读 [z]，不是 [s]。复数是 réseaux，不是 réseaus。","et":"来自古法语 resel，源于拉丁语 retiolum（小网），来自 rete「网」。","ex":[["Il a un grand réseau professionnel.","他有很大的职业人脉。"],["Je n'ai pas de réseau ici.","这里没有信号。"]],"co":[["les réseaux sociaux","社交网络"],["un réseau de transport","交通网"],["se faire un réseau","拓展人脉"],["pas de réseau","没信号"]],"sy":[["le contact","courant","人脉；联系"],["la toile","courant","（互联网）网"],["le maillage","soutenu","网状分布"]],"fq":"极高频，日常常用。","me":"réseau ← 一张小「网」。","tr":{"zh":"我在这里没有手机信号。","fr":"Je n'ai pas de réseau ici.","alt":"Ici, ça ne capte pas.","note":"pas de réseau：否定后 de 不加冠词。"}},
 "Un sein": {"pos":"n.m. 阳性名词，复数 seins","s":"胸；乳房。也指怀中、内部：au sein de = 在……之内（组织、团体）。le sein 比 la poitrine 更具体指乳房。","ipa":"[sɛ̃]","ph":"s [s]；ein 读鼻化 [ɛ̃]；结尾没有别的音。","pi":"和 sain（健康的）、saint（神圣的）、cinq（五，读 [sɛ̃k]）同音或近音，注意拼写和性别。","et":"来自拉丁语 sinus（弯曲，褶皱，怀抱）。","ex":[["Le bébé tète le sein de sa mère.","婴儿吮吸母亲的乳房。"],["Il travaille au sein d'une grande équipe.","他在一个大团队里工作。"]],"co":[["au sein de","在……内部"],["donner le sein","喂奶"],["le cancer du sein","乳腺癌"],["allaiter au sein","母乳喂养"]],"sy":[["la poitrine","courant","胸部"],["le buste","courant","上半身"],["le giron","littéraire","怀抱"]],"fq":"中频，医疗和书面都会用到。","me":"sein / sain / saint：同音，意思三不同。","tr":{"zh":"他在一家大公司里工作。","fr":"Il travaille au sein d'une grande entreprise.","alt":"Il bosse dans une grande boîte.","note":"au sein de = 在内部，书面感较强。"}},
 "Un soutien": {"pos":"n.m. 阳性名词，复数 soutiens","s":"支持；支柱；援助。可指精神或物质上的支持：apporter son soutien。une personne de soutien = 依靠的人。注意 soutien-gorge = 胸罩。","ipa":"[su.tjɛ̃]","ph":"sou [su]；tien 读 [tjɛ̃]；t 在这里读 [t]，不是 [s]。","pi":"-tien 读 [tjɛ̃]，不是 [sjɛ̃]。结尾不发 n。","et":"来自动词 soutenir（sous「下」+ tenir「握，支撑」）。","ex":[["Il a été un grand soutien pour moi.","他是我的重要支持。"],["Merci pour ton soutien.","谢谢你的支持。"]],"co":[["apporter son soutien à","给予支持"],["un soutien moral","精神支持"],["un soutien financier","经济援助"],["le soutien scolaire","课后辅导"]],"sy":[["l'appui","courant","支援"],["l'aide","courant","帮助"],["le support","familier","支持（受英语影响）"]],"fq":"高频，日常常用。","me":"sou-tien：从下 (sous) 托住 (tenir)。","tr":{"zh":"谢谢你一直支持我。","fr":"Merci pour ton soutien.","alt":"Merci de m'avoir toujours soutenu.","note":"merci pour + 名词；merci de + 完成式动词。"}},
 "Un tabou": {"pos":"n.m. 阳性名词，复数 tabous（形容词 tabou 阴阳同形）","s":"禁忌；忌讳的话题。le tabou de la mort = 死亡的禁忌。作形容词：un sujet tabou = 忌讳的话题。","ipa":"[ta.bu]","ph":"ta [ta]；bou 读 [bu]；ou = [u]。","pi":"ou 读 [u]；重音在最后一个音节。结尾 u 不要读成 [y]。","et":"借自波利尼西亚语（汤加语 tapu），经英语 taboo 进入法语。","ex":[["L'argent est souvent un tabou.","钱常常是个禁忌话题。"],["La mort reste un tabou.","死亡依然是个禁忌。"]],"co":[["un sujet tabou","忌讳的话题"],["briser un tabou","打破禁忌"],["lever un tabou","解除禁忌"],["un tabou social","社会禁忌"]],"sy":[["l'interdit","courant","禁止的事"],["l'interdiction","courant","禁令"]],"fq":"中频，书面和讨论话题时用。","me":"tabou：来自海岛语 tapu，被「禁止」碰的东西。","tr":{"zh":"在我们家，钱是个禁忌话题。","fr":"Chez nous, l'argent est un sujet tabou.","alt":"Chez nous, on ne parle jamais d'argent.","note":"un sujet tabou：tabou 作形容词。"}},
 "De l'attraction": {"pos":"n.f. 阴性名词，复数 attractions","s":"吸引力；吸引。物理上指引力：l'attraction terrestre = 地心引力。游乐园的 une attraction = 游乐设施或景点。对人的吸引更常说 l'attirance。","ipa":"[a.tʁak.sjɔ̃]","ph":"tt 读一个 [t]；tr [tʁ]；ct 读 [k]（t 不发音）；-tion 读 [sjɔ̃]。","pi":"-tion 读 [sjɔ̃]，不是 [tjɔ̃]。词中 ct 里 t 不发音，是 [ak.sjɔ̃]。","et":"来自拉丁语 attractio，源于 attrahere（拉向自己）。同族：attirer（吸引）、attrait。","ex":[["Il ressent de l'attraction pour elle.","他对她有吸引力。"],["La tour Eiffel est une attraction touristique.","埃菲尔铁塔是旅游景点。"]],"co":[["l'attraction terrestre","地心引力"],["une attraction touristique","旅游景点"],["un parc d'attractions","游乐园"],["ressentir de l'attraction","感到被吸引"]],"sy":[["l'attirance","courant","吸引（对人）"],["l'attrait","soutenu","魅力"]],"fq":"中频，日常和书面都用。","me":"attraction ← attirer：把人「拉」过来。","tr":{"zh":"孩子们喜欢这个游乐设施。","fr":"Les enfants adorent cette attraction.","alt":"Cette attraction plaît beaucoup aux enfants.","note":"adorer + 名词；attraction 此处指游乐设施。"}},
 "De l'inquiétude": {"pos":"n.f. 阴性名词，复数 inquiétudes","s":"担忧；不安。对未来或某人的忧虑：avoir de l'inquiétude pour quelqu'un。动词是 s'inquiéter，形容词是 inquiet / inquiète。","ipa":"[ɛ̃.kje.tyd]","ph":"in 读鼻化 [ɛ̃]；qui 读 [kje]（q 读 [k]，u 不发音）；é [e]；tude 读 [tyd]。","pi":"qu 读 [k]，不是 [kw]；tu 读 [ty]（u 嘴圆）；结尾 e 不发音。","et":"来自拉丁语 inquietudo，in-（不）+ quies（平静）。字面是「不平静」。","ex":[["Je lis de l'inquiétude dans ses yeux.","我在他眼里读到担忧。"],["Son silence m'a causé de l'inquiétude.","他的沉默让我担心。"]],"co":[["avoir de l'inquiétude","感到担忧"],["causer de l'inquiétude","让人担心"],["une vive inquiétude","深深的忧虑"],["sans inquiétude","不用担心"]],"sy":[["le souci","courant","担心；烦恼"],["l'angoisse","soutenu","焦虑；极度不安"],["l'anxiété","soutenu","焦虑"]],"fq":"中频，日常和书面都用。","me":"in + quiet：不「安静」，心不平静。","tr":{"zh":"她的沉默让我很担心。","fr":"Son silence me cause de l'inquiétude.","alt":"Son silence m'inquiète.","note":"m'inquiète：inquiéter 是及物动词，me 是宾语。"}},
 "De la grêle": {"pos":"n.f. 阴性名词，不可数（一颗冰雹：un grêlon）","s":"冰雹。指天气现象，不可数：la grêle。动词 grêler：il grêle = 下冰雹。一粒冰雹是 un grêlon。形容词 grêle 另有「细瘦的」意思（une voix grêle）。","ipa":"[ɡʁɛl]","ph":"g 读硬 [ɡ]；r 小舌音 [ʁ]；ê 读 [ɛ]；l 要读出来 [l]；e 不发音。","pi":"ê 是 [ɛ]；l 要读出来；g 不是 [ʒ]。","et":"来源不确定；词族：grêler（下冰雹），grêlon（冰雹粒）。","ex":[["Il est tombé de la grêle cet après-midi.","今天下午下了冰雹。"],["La grêle a abîmé les voitures.","冰雹砸坏了汽车。"]],"co":[["il grêle","下冰雹"],["un orage de grêle","冰雹雷暴"],["un grêlon","一粒冰雹"],["tomber de la grêle","下冰雹"]],"sy":[["la pluie","courant","雨"],["la neige","courant","雪"],["le grésil","soutenu","冰粒；霰"]],"fq":"中低频，天气话题。","me":"grêle：天上砸下来的「小冰球」。","tr":{"zh":"昨天下了冰雹，车被砸坏了。","fr":"Hier, il a grêlé et les voitures ont été abîmées.","alt":"Hier, il est tombé de la grêle sur les voitures.","note":"il grêle：非人称动词，只有 il。"}},
 "L'amitié": {"pos":"n.f. 阴性名词，复数 amitiés","s":"友谊；友情。信末结尾常写 Amitiés（致以友好的问候）。amitiés 复数也可用于问候：Mes amitiés à ta mère。","ipa":"[a.mi.tje]","ph":"a-mi-tié：ti 读 [tj]，é 读 [e]；l' 与 a 连读省音。","pi":"ti 读 [t]，不是 [s]：和 -tion 不同。é 结尾要读出 [e]。","et":"来自拉丁语 amicitas，源于 amicus「朋友」。同族：ami、amical。","ex":[["L'amitié est très importante pour moi.","友谊对我很重要。"],["Leur amitié dure depuis dix ans.","他们的友谊已有十年。"]],"co":[["une amitié sincère","真诚的友谊"],["se lier d'amitié avec","与……交朋友"],["par amitié","出于友情"],["Amitiés","（信末）顺祝安好"]],"sy":[["la camaraderie","courant","同伴情谊"],["l'affection","soutenu","感情；喜爱"]],"fq":"高频，日常常用。","me":"amitié ← ami + -tié：朋友之间的情。","tr":{"zh":"我们的友谊已有十年了。","fr":"Notre amitié dure depuis dix ans.","alt":"On est amis depuis dix ans.","note":"depuis + 时间段，现在时。"}},
 "L'écoute": {"pos":"n.f. 阴性名词，复数 écoutes","s":"倾听；收听。être à l'écoute de = 留心听，关注。一个人很会倾听：avoir une bonne écoute。les écoutes téléphoniques = 电话窃听。","ipa":"[e.kut]","ph":"é [e]；ou 读 [u]；t 要读出来 [t]；结尾 e 不发音。","pi":"t 要读 [t]：écoute [e.kut]。别把 ou 读成 [o]。","et":"来自动词 écouter，源于拉丁语 auscultare（听）。","ex":[["Elle a une grande capacité d'écoute.","她很会倾听。"],["Restez à l'écoute de notre radio.","请继续收听我们的电台。"]],"co":[["être à l'écoute","用心倾听"],["une capacité d'écoute","倾听能力"],["l'écoute active","积极倾听"],["heure de grande écoute","黄金时段"]],"sy":[["l'attention","courant","注意"],["l'audition","soutenu","听觉；试听"]],"fq":"中频，日常和职场用。","me":"écoute：动词 écouter 的「名词版」。","tr":{"zh":"好老师要会倾听学生。","fr":"Un bon professeur est à l'écoute de ses élèves.","alt":"Un bon prof sait écouter ses élèves.","note":"être à l'écoute de + 人。"}},
 "L'empathie": {"pos":"n.f. 阴性名词，复数 empathies（少用）","s":"同理心；共情。能体会他人的感受。比 la sympathie（好感，友好）更强调「设身处地」；比 la compassion 少「怜悯」的色彩。","ipa":"[ɑ̃.pa.ti]","ph":"em 读鼻化 [ɑ̃]；pa [pa]；th 读 [t]；ie 读 [i]。","pi":"th 读 [t]，不是 [θ] 也不是 [s]；em 读 [ɑ̃]，别读成 [ɛm]。","et":"来自希腊语 empatheia（en 「在内」+ pathos「感受」），经德语和英语传入。","ex":[["Il manque d'empathie.","他缺乏同理心。"],["Une bonne infirmière fait preuve d'empathie.","好护士会表现出同理心。"]],"co":[["avoir de l'empathie","有同理心"],["manquer d'empathie","缺乏同理心"],["faire preuve d'empathie","表现出同理心"]],"sy":[["la sympathie","courant","好感；友善"],["la compassion","courant","同情"]],"fq":"中频，心理和职场话题。","me":"em-pathie：走进 (en) 别人的情感 (pathos)。","tr":{"zh":"好医生要有同理心。","fr":"Un bon médecin doit avoir de l'empathie.","alt":"Un bon médecin sait se mettre à la place des autres.","note":"devoir + 动词原形；avoir de l'empathie。"}},
 "L'inspiration": {"pos":"n.f. 阴性名词，复数 inspirations","s":"灵感；启发。也指吸气（与 l'expiration「呼气」相对）：inspirer / expirer。avoir de l'inspiration = 有灵感。","ipa":"[ɛ̃.spi.ʁa.sjɔ̃]","ph":"in 读鼻化 [ɛ̃]；sp 连读 [sp]；ra [ʁa]；-tion 读 [sjɔ̃]。","pi":"-tion 读 [sjɔ̃]；in 在 s 前仍是鼻音 [ɛ̃]。","et":"来自拉丁语 inspiratio，源于 inspirare（吹入，赋予生气）。","ex":[["Je cherche l'inspiration pour mon livre.","我在为我的书找灵感。"],["Respirez : inspiration, expiration.","呼吸：吸气，呼气。"]],"co":[["chercher l'inspiration","找灵感"],["manquer d'inspiration","缺乏灵感"],["une source d'inspiration","灵感来源"],["s'inspirer de","从……获得灵感"]],"sy":[["l'idée","courant","想法"],["la muse","littéraire","缪斯"],["l'élan","soutenu","冲动；灵感"]],"fq":"中高频，日常和书面都用。","me":"inspiration：把气 (spirare) 「吹入」心里。","tr":{"zh":"我今天一点灵感也没有。","fr":"Je n'ai aucune inspiration aujourd'hui.","alt":"Aujourd'hui, je manque d'inspiration.","note":"ne… aucun(e) + 名词；manquer de + 名词。"}},
 "La cantine": {"pos":"n.f. 阴性名词，复数 cantines","s":"食堂（学校、公司的）。manger à la cantine = 在食堂吃饭。学校食堂说 la cantine scolaire。也指士兵的箱子，但很少见。","ipa":"[kɑ̃.tin]","ph":"can 读鼻化 [kɑ̃]；ti 读 [ti]；n 要读出来 [n]；结尾 e 不发音。","pi":"can- 是鼻音 [ɑ̃]，但 -tine 里的 n 要单独读 [n]。","et":"借自意大利语 cantina（地窖，酒窖）。","ex":[["Je mange à la cantine à midi.","中午我在食堂吃饭。"],["Les enfants déjeunent à la cantine.","孩子们在食堂吃午饭。"]],"co":[["manger à la cantine","在食堂吃饭"],["la cantine scolaire","学校食堂"],["un repas de cantine","食堂饭菜"]],"sy":[["le restaurant d'entreprise","courant","公司餐厅"],["le self","familier","自助食堂"],["le réfectoire","soutenu","饭堂（学校、修道院）"]],"fq":"中频，日常常用。","me":"cantine：在食堂排队拿「罐」(cant-) 饭。","tr":{"zh":"孩子们中午在食堂吃饭。","fr":"Les enfants mangent à la cantine à midi.","alt":"À midi, les enfants déjeunent à la cantine.","note":"à la cantine：à + la。"}},
 "La compassion": {"pos":"n.f. 阴性名词，复数 compassions（少用）","s":"同情心；怜悯。看到别人受苦时的关切与心疼。avoir de la compassion pour quelqu'un。比 la pitié 更温和，比 l'empathie 更多「想要帮助」。","ipa":"[kɔ̃.pa.sjɔ̃]","ph":"com 读鼻化 [kɔ̃]；pa [pa]；ss 读 [s]；-ion 读 [jɔ̃]。","pi":"ss 读 [s]（不是 [z]）；com- 是鼻音 [ɔ̃]，别读成 [kɔm]。","et":"来自拉丁语 compassio，com-（一起）+ pati（承受，受苦）。同族：passion。","ex":[["Elle a montré beaucoup de compassion.","她表现出很多同情。"],["Il a agi par compassion.","他出于同情而行动。"]],"co":[["avoir de la compassion","有同情心"],["montrer de la compassion","表现出同情"],["par compassion","出于同情"],["sans compassion","毫无怜悯"]],"sy":[["la pitié","courant","怜悯（可能带居高临下）"],["la sympathie","courant","同情；好感"],["la miséricorde","soutenu","仁慈"]],"fq":"中频，书面和谈论情感时用。","me":"com + passion：与人「一同」承受苦。","tr":{"zh":"她对病人很有同情心。","fr":"Elle a beaucoup de compassion pour les malades.","alt":"Elle est très compatissante avec les malades.","note":"compassion pour + 人；形容词是 compatissant。"}},
 "La cour de récréation": {"pos":"n.f. 阴性名词，复数 cours de récréation","s":"操场（学校课间玩耍的院子）。口语常简称 la cour 或 la récré。cour 是院子；récréation 是课间休息。","ipa":"[kuʁ də ʁe.kʁe.a.sjɔ̃]","ph":"cour 读 [kuʁ]；de 弱读 [də]；ré-cré-a-tion：-tion 读 [sjɔ̃]。","pi":"cour / cours / court 同音 [kuʁ]：cour = 院子，cours = 课，court = 短的。-tion 读 [sjɔ̃]。","et":"cour（院子）+ de + récréation（休息，来自拉丁语 recreatio）。","ex":[["Ils courent dans la cour de récréation.","他们在操场上跑。"],["La cloche sonne, les enfants sortent dans la cour.","铃响了，孩子们走到操场上。"]],"co":[["jouer dans la cour de récréation","在操场上玩"],["la récré","课间休息（口语）"],["l'heure de la récréation","课间时间"]],"sy":[["la cour","courant","院子（简称）"],["la récré","familier","课间休息"],["le préau","courant","操场的有盖部分"]],"fq":"中频，学校话题常用。","me":"cour + récréation：为「再创造」精力而玩的院子。","tr":{"zh":"课间，孩子们在操场上玩。","fr":"À la récréation, les enfants jouent dans la cour.","alt":"À la récré, les enfants jouent dehors.","note":"à la récréation：à + la。"}},
 "La critique": {"pos":"n.f. 阴性名词，复数 critiques（作人时：le/la critique 指评论家）","s":"批评；评论；影评。可以是负面批评，也可以是中性的评论：une critique de film。le critique = 评论家。形容词 critique = 关键的；危急的。","ipa":"[kʁi.tik]","ph":"cr [kʁ]；i [i]；ti 读 [ti]；qu 读 [k]；结尾 e 不发音。","pi":"qu 读 [k]。别把 critique（批评）读成英语 critic [ˈkrɪtɪk] 的重音。名词有阴性和阳性之分，注意区分。","et":"来自希腊语 kritikos（能判断的），源于 krinein「判断」。","ex":[["Le film a reçu une mauvaise critique.","这部电影得到了差评。"],["Elle accepte mal la critique.","她很难接受批评。"]],"co":[["faire une critique","写评论；提出批评"],["une critique positive / négative","好评 / 差评"],["une critique de film","影评"],["accepter la critique","接受批评"]],"sy":[["le reproche","courant","责备"],["l'avis","courant","意见"],["la recension","soutenu","书评"]],"fq":"高频，日常和媒体常用。","me":"critique：由 krinein「判断」而来，判断有好有坏。","tr":{"zh":"这本书得到了很好的评价。","fr":"Ce livre a reçu de très bonnes critiques.","alt":"Les critiques sur ce livre sont très bonnes.","note":"recevoir une critique；复数 de très bonnes critiques。"}},
 "La gloire": {"pos":"n.f. 阴性名词，复数 gloires","s":"荣耀；名声；荣誉。指因伟大成就而获得的盛名：la gloire éternelle。比 la célébrité 更有崇高感。","ipa":"[ɡlwaʁ]","ph":"g 读硬 [ɡ]；l [l]；oi 读 [wa]；r 小舌音 [ʁ]；一个音节。","pi":"oi 读 [wa]；一个音节：[ɡlwaʁ]，别拆成两个。","et":"来自拉丁语 gloria（荣誉，名声）。","ex":[["Il a connu la gloire très jeune.","他年纪轻轻就成名了。"],["Elle rêve de gloire et de succès.","她梦想着荣耀和成功。"]],"co":[["connaître la gloire","享有盛名"],["à la gloire de","为了荣耀……"],["la gloire et la fortune","名利"],["se couvrir de gloire","载誉而归"]],"sy":[["la célébrité","courant","名气"],["la renommée","soutenu","声誉"],["l'honneur","courant","荣誉"]],"fq":"中频，书面和叙述中用。","me":"gloire：和英语 glory 同族，把 y 换成 -oire。","tr":{"zh":"他很年轻就获得了盛名。","fr":"Il a connu la gloire très jeune.","alt":"Il est devenu célèbre très jeune.","note":"connaître la gloire：固定搭配。"}},
 "La jalousie": {"pos":"n.f. 阴性名词，复数 jalousies","s":"嫉妒；吃醋。爱情或友情里都可用：La jalousie est un vilain défaut。形容词是 jaloux / jalouse。une jalousie 还指百叶窗（少见）。","ipa":"[ʒa.lu.zi]","ph":"j 读 [ʒ]；ou 读 [u]；s 在元音间读 [z]；ie 读 [i]。","pi":"j 读 [ʒ]，不是英语的 [dʒ]；s 读 [z]；ou 读 [u]。","et":"来自 jaloux（古法语 jalous），源于拉丁语 zelosus，再追溯到希腊语 zelos「热忱，嫉妒」。","ex":[["La jalousie peut détruire un couple.","嫉妒会毁掉一对情侣。"],["Il a agi par jalousie.","他出于嫉妒而行动。"]],"co":[["une crise de jalousie","醋意大发"],["par jalousie","出于嫉妒"],["éprouver de la jalousie","感到嫉妒"],["être mort de jalousie","嫉妒得要命"]],"sy":[["l'envie","courant","羡慕（想拥有别人的东西）"],["le dépit","soutenu","懊恼"]],"fq":"中高频，日常常用。","me":"jalousie：和 jaloux（嫉妒的）是一家。","tr":{"zh":"嫉妒会毁掉友谊。","fr":"La jalousie peut détruire une amitié.","alt":"Être jaloux peut gâcher une amitié.","note":"pouvoir + 动词原形。"}},
 "La maternité": {"pos":"n.f. 阴性名词，复数 maternités","s":"母亲身份；怀孕生子；产科医院。à la maternité = 在产科医院。congé de maternité = 产假。le mot 既指状态，也指地点。","ipa":"[ma.tɛʁ.ni.te]","ph":"ma [ma]；ter 读 [tɛʁ]；ni [ni]；té 读 [te]；r 要发音。","pi":"ter 里 e 读 [ɛ]，r 要发；结尾 é 读 [e]。与 paternité 只差一个字母，别混。","et":"来自拉丁语 maternitas，源于 mater「母亲」。同族：maternel、mère。","ex":[["La maternité est une belle aventure.","做母亲是一次美好的冒险。"],["Elle est à la maternité pour accoucher.","她在产科医院生孩子。"]],"co":[["un congé de maternité","产假"],["à la maternité","在产科医院"],["la maternité et la carrière","母亲身份与事业"],["une maternité tardive","晚育"]],"sy":[["la mère","courant","母亲"],["l'accouchement","courant","分娩"]],"fq":"中频，日常和医疗话题。","me":"mater + -nité：mater = 母亲。","tr":{"zh":"她正在休产假。","fr":"Elle est en congé de maternité.","alt":"Elle est en congé mat.","note":"être en congé de maternité。"}},
 "La paternité": {"pos":"n.f. 阴性名词，复数 paternités（少用）","s":"父亲身份；做父亲；亲子关系（法律上）。congé de paternité = 陪产假。一个男人成为父亲后的状态和责任。","ipa":"[pa.tɛʁ.ni.te]","ph":"pa [pa]；ter 读 [tɛʁ]；ni [ni]；té 读 [te]；r 要发音。","pi":"和 maternité 只差第一个字母：pa- 对 ma-。ter 里的 r 要读。","et":"来自拉丁语 paternitas，源于 pater「父亲」。同族：paternel、père。","ex":[["La paternité change la vie d'un homme.","当爸爸改变一个男人的生活。"],["Il a pris un congé de paternité.","他休了陪产假。"]],"co":[["un congé de paternité","陪产假"],["une action en recherche de paternité","亲子鉴定诉讼"],["la paternité responsable","负责任的为人父"]],"sy":[["le père","courant","父亲"],["la filiation","soutenu","亲子关系"]],"fq":"中低频，日常和法律话题。","me":"pater + -nité：pater = 父亲，对应 maternité。","tr":{"zh":"他正在休陪产假。","fr":"Il est en congé de paternité.","alt":"Il a pris son congé paternité.","note":"être en / prendre un congé de paternité。"}},
 "La pop": {"pos":"n.f. 阴性名词，不变（la pop = la musique pop）","s":"流行音乐。借自英语 pop（popular 的缩写）。la pop 是 la musique pop 的简称，所以是阴性。也说 la variété（法国流行歌曲）。","ipa":"[pɔp]","ph":"p [p]；o 读开口 [ɔ]；结尾 p 要读出来 [p]。","pi":"o 读 [ɔ]；结尾 p 要发音。因为省略了 musique，所以用阴性 la pop。","et":"借自英语 pop，是 popular（流行的）的缩写。","ex":[["La pop anglaise est très populaire.","英国流行音乐很受欢迎。"],["J'aime la pop et le rock.","我喜欢流行乐和摇滚。"]],"co":[["écouter de la pop","听流行乐"],["la musique pop","流行音乐"],["une chanson pop","流行歌曲"],["la pop française","法国流行音乐"]],"sy":[["la variété","courant","（法国）流行歌曲"],["la chanson","courant","歌曲"]],"fq":"中频，日常常用。","me":"pop ← popular：大家都爱听。","tr":{"zh":"我喜欢听英国流行乐。","fr":"J'aime écouter de la pop anglaise.","alt":"J'écoute souvent de la pop anglaise.","note":"écouter de la pop：部分冠词 de la。"}},
 "La récréation": {"pos":"n.f. 阴性名词，复数 récréations","s":"课间休息（学校里的休息时间）。口语常缩成 la récré。也可泛指「消遣、放松」，但这个义项很少用。","ipa":"[ʁe.kʁe.a.sjɔ̃]","ph":"r 是小舌音 [ʁ]；ré [ʁe]，cré [kʁe]，a 单独一个音节；-tion 读 [sjɔ̃]。","pi":"-tion 读 [sjɔ̃]，不是 [ʃən]；é 和 a 要分成两个音节，不要连成一个音。","et":"拉丁语 recreatio（恢复、消遣），来自 recreare（re- 再 + creare 创造）。","ex":[["Les enfants jouent pendant la récréation.","孩子们在课间玩耍。"],["À la récré, on mange une pomme.","课间休息时我们吃个苹果。"]],"co":[["la cour de récréation","学校操场"],["pendant la récréation","在课间"],["la récré","课间（口语）"]],"sy":[["la pause","courant","一般的休息，不限于学校"],["la récré","familier","récréation 的口语缩写"]],"fq":"中频，学校场景常用。","me":"re-création：休息一下，重新「创造」精力。","tr":{"zh":"孩子们在操场上玩，因为现在是课间休息。","fr":"Les enfants jouent dans la cour parce que c'est la récréation.","alt":"Les enfants jouent dehors, c'est la récré !","note":"cour de récréation = 学校操场。"}},
 "La sincérité": {"pos":"n.f. 阴性名词，复数 sincérités（很少用复数）","s":"真诚；坦率。形容词是 sincère。常见说法 en toute sincérité（完全坦诚地）。","ipa":"[sɛ̃.se.ʁi.te]","ph":"sin [sɛ̃] 鼻化；cé 中 c 在 é 前读 [s]；ri [ʁi]；té [te]。","pi":"sin 是鼻化元音，不发 n；结尾 -té 读 [te]。以 -té 结尾的抽象名词几乎都是阴性。","et":"拉丁语 sinceritas，来自 sincerus（纯净的、真实的）。同族：sincère（真诚的）。","ex":[["J'apprécie sa sincérité.","我欣赏他的真诚。"],["Je te le dis en toute sincérité.","我完全真心地告诉你。"]],"co":[["en toute sincérité","完全坦诚地"],["manquer de sincérité","不够真诚"],["la sincérité d'un sentiment","感情的真挚"]],"sy":[["l'honnêteté","courant","诚实，侧重不撒谎"],["la franchise","courant","坦率，说话直接"],["la droiture","soutenu","正直"]],"fq":"中频，书面和日常都用。","me":"sincère → sincérité：-ère 变 -érité。","tr":{"zh":"我很欣赏你的真诚。","fr":"J'apprécie ta sincérité.","alt":"Ça me touche, ta sincérité.","note":"apprécier + 名词；ta 对应 tu。"}},
 "La solidarité": {"pos":"n.f. 阴性名词，复数 solidarités","s":"团结；互助；连带。指人们在困难时互相帮助。形容词 solidaire：Je suis solidaire de toi（我和你站在一起）。","ipa":"[sɔ.li.da.ʁi.te]","ph":"so [sɔ]；li [li]；da [da]；ri [ʁi]；té [te]。五个音节，重音在最后。","pi":"o 读开口 [ɔ]；全词有五个音节，别漏掉 da。词尾是 -arité。","et":"来自 solidaire，源于法律用语（拉丁语 in solidum，「共同负全责」）。","ex":[["La solidarité est essentielle en temps de crise.","危机时期团结至关重要。"],["Il y a eu un grand élan de solidarité.","掀起了一股强大的互助热潮。"]],"co":[["un élan de solidarité","一股互助热潮"],["par solidarité","出于团结"],["la solidarité entre générations","代际互助"]],"sy":[["l'entraide","courant","互相帮助，更具体"],["l'union","courant","联合、团结"],["la fraternité","soutenu","博爱、兄弟情"]],"fq":"中频，新闻和社会话题常见。","me":"solide + 人：大家像一块「固体」连在一起。","tr":{"zh":"在困难时期，团结很重要。","fr":"En temps difficile, la solidarité est importante.","alt":"Quand ça va mal, il faut être solidaires.","note":"en temps de crise / en temps difficile：不加冠词。"}},
 "La solitude": {"pos":"n.f. 阴性名词，复数 solitudes（多用单数）","s":"孤独；独处。可以是不好的「孤单」，也可以是自愿的「清静」。和 la seule（独自）、isolement（隔绝）有别。","ipa":"[sɔ.li.tyd]","ph":"so [sɔ]；li [li]；tu 读 [ty]（圆唇）；d 要发 [d]。","pi":"u 读 [y]，不是 [u]；结尾 d 要读出来 [tyd]，e 不发音。","et":"拉丁语 solitudo，来自 solus（独自的）。同族：seul, solitaire。","ex":[["La solitude peut être difficile à vivre.","孤独可能很难承受。"],["Il aime la solitude et le silence.","他喜欢独处和安静。"]],"co":[["souffrir de solitude","为孤独所苦"],["rompre la solitude","打破孤独"],["aimer la solitude","喜欢独处"]],"sy":[["l'isolement","courant","与外界隔离的状态"],["l'esseulement","littéraire","孤零零的感觉"],["la compagnie","courant","反义：陪伴"]],"fq":"中频，日常和文学里都有。","me":"solus（独）+ -itude：独自的状态。","tr":{"zh":"有些人觉得孤独很难受。","fr":"Certaines personnes souffrent de la solitude.","alt":"Pour certains, la solitude est dure à vivre.","note":"souffrir de + 名词。"}},
 "La variété française": {"pos":"n.f. 阴性名词，复数 variétés（此义常用 la variété 单数）","s":"法国流行歌曲，即 la chanson de variété：面向大众的轻松流行乐。la variété 单独也可指「种类、多样性」，表示音乐时多半指「法式流行歌曲」。","ipa":"[va.ʁje.te fʁɑ̃.sɛz]","ph":"va [va]；rié 读 [ʁje]；té [te]；fran [fʁɑ̃] 鼻化；çaise [sɛz]，ç = [s]，ai = [ɛ]，s 读 [z]。","pi":"rié 是一个音节 [ʁje]；française 的 ç 读 [s]，结尾 s 读 [z]；ai 读 [ɛ]，不是 [e]。","et":"variété 来自拉丁语 varietas（多样），源自 varius（各种各样的）。","ex":[["Mes parents écoutent de la variété française.","我父母听法国流行歌曲。"],["Elle chante de la variété depuis vingt ans.","她唱流行歌曲已经二十年了。"]],"co":[["écouter de la variété","听流行歌曲"],["une chanson de variété","一首流行歌曲"],["une grande variété de + 名词","种类繁多的……"]],"sy":[["la chanson française","courant","法语歌曲，范围更广"],["la pop","courant","流行音乐，国际范围"],["la diversité","courant","多样性（泛指）"]],"fq":"中频，谈音乐时常用。","me":"variety show：各种风格混在一起的「综艺」歌曲。","tr":{"zh":"我外婆喜欢法国流行歌曲。","fr":"Ma grand-mère aime la variété française.","alt":"Ma grand-mère adore la variété française.","note":"aimer + 定冠词表示泛指喜欢。"}},
 "Une alarme": {"pos":"n.f. 阴性名词，复数 alarmes","s":"警报；警报器。une alarme d'incendie 火警警报；l'alarme du réveil 闹钟铃声。donner l'alarme = 报警、拉响警报。","ipa":"[a.laʁm]","ph":"a [a]；lar [laʁ]；me 轻读，几乎不发音：[laʁm]。两个音节。","pi":"结尾 -me 的 e 不发音，r 和 m 要连着读 [ʁm]。不要读成三个音节。","et":"来自意大利语 all'arme（「拿起武器！」），原是战场上的号令。同族：alarmer（使惊慌）。","ex":[["J'ai entendu l'alarme ce matin.","今早我听到了警报声。"],["L'alarme s'est déclenchée toute seule.","警报器自己响了。"]],"co":[["déclencher l'alarme","触发警报"],["donner l'alarme","发出警报"],["une alarme incendie","火警警报"],["un signal d'alarme","警报信号"]],"sy":[["l'alerte","courant","预警；警戒状态"],["la sirène","courant","警笛"],["le réveil","courant","闹钟，不要和 alarme 混用"]],"fq":"中频，日常常用。","me":"all'arme! = 「拿起武器！」→ 警报。","tr":{"zh":"昨晚警报突然响了。","fr":"L'alarme a sonné soudainement hier soir.","alt":"Hier soir, l'alarme s'est mise à sonner d'un coup.","note":"alarme 是阴性，l'alarme 的省音不改变性别。"}},
 "Une application de rencontre": {"pos":"n.f. 阴性名词，复数 applications de rencontre","s":"交友软件，约会应用（如 Tinder 之类）。口语常说 une appli de rencontre。application 单独指手机应用，口语缩成 une appli。","ipa":"[a.pli.ka.sjɔ̃ də ʁɑ̃.kɔ̃tʁ]","ph":"application：-tion 读 [sjɔ̃]；de 弱读 [də]；rencontre：ren [ʁɑ̃] 鼻化，con [kɔ̃] 鼻化，结尾 -tre 轻读 [tʁ]，e 不发音。","pi":"application 里 pp 只读一个 [p]；-tion 是 [sjɔ̃]；rencontre 末尾 e 不发音，不要加音节。","et":"application：拉丁语 applicatio（附着、运用）；rencontre：来自动词 rencontrer（re- + encontrer，「迎面相遇」）。","ex":[["Il a rencontré sa femme sur une application de rencontre.","他在交友软件上认识了他的妻子。"],["Elle a supprimé son appli de rencontre.","她删掉了她的交友软件。"]],"co":[["télécharger une application","下载应用"],["s'inscrire sur une appli de rencontre","注册交友软件"],["rencontrer quelqu'un en ligne","在网上认识某人"]],"sy":[["une appli","familier","application 的缩写"],["un site de rencontre","courant","交友网站"]],"fq":"中频，年轻人和日常对话里常用。","me":"appli + rencontre：用来「遇见」人的 app。","tr":{"zh":"很多人用交友软件认识新朋友。","fr":"Beaucoup de gens utilisent une application de rencontre pour faire connaissance.","alt":"Plein de gens se rencontrent via des applis de rencontre.","note":"faire connaissance = 结识；plein de = 很多（口语）。"}},
 "Une bande": {"pos":"n.f. 阴性名词，复数 bandes","s":"一伙人，一帮（朋友、孩子，也可指团伙）；也指长条、带子、磁带。une bande de copains = 一群朋友；une bande de voyous 带贬义，是「一帮流氓」。bande dessinée = 漫画。","ipa":"[bɑ̃d]","ph":"b [b]；an 鼻化 [ɑ̃]；结尾 d 要发音 [d]。","pi":"bande 的 d 要读出来 [bɑ̃d]，对比 banc [bɑ̃]（d 的有无是区别）。","et":"来源不确定（可能与日耳曼语有关）。词族：bande dessinée（漫画）、bande-annonce（预告片）、bande originale（原声）。","ex":[["Il traîne avec sa bande de copains.","他和他那帮朋友混在一起。"],["Elle a mis une bande autour de son poignet.","她在手腕上绑了一条绷带。"]],"co":[["une bande de copains","一群朋友"],["une bande dessinée (BD)","漫画"],["la bande-annonce","预告片"],["faire bande à part","不合群、自成一派"]],"sy":[["un groupe","courant","中性的「一组人」"],["une équipe","courant","有共同目标的团队"],["une troupe","soutenu","一队人"]],"fq":"高频，日常常用。","me":"bande 的 d 要读出来，像一伙人手拉手的「带」。","tr":{"zh":"我和我那帮朋友周末去看电影。","fr":"Je vais au cinéma avec ma bande de copains ce week-end.","alt":"Ce week-end, on va au ciné entre potes.","note":"une bande de + 名词（无冠词）。"}},
 "Une couche": {"pos":"n.f. 阴性名词，复数 couches","s":"尿布，纸尿裤；还有「层」之义：une couche de peinture（一层油漆）、la couche d'ozone（臭氧层）。口语 en rajouter une couche = 变本加厉、再添一笔（familier）。","ipa":"[kuʃ]","ph":"ou [u]；ch [ʃ]；e 不发音。一个音节。","pi":"ou 读 [u]，不是 [ɔ]；ch 读 [ʃ]。别和 coucher（躺下）、douche（淋浴）混淆。","et":"是动词 coucher 的派生词，源自拉丁语 collocare（安放）。「层」指一层层铺放。","ex":[["Il faut changer la couche du bébé.","得给宝宝换尿布。"],["Elle a mis deux couches de peinture.","她刷了两层油漆。"]],"co":[["changer une couche","换尿布"],["une couche de peinture","一层油漆"],["la couche d'ozone","臭氧层"],["une couche-culotte","纸尿裤"]],"sy":[["une couche-culotte","courant","纸尿裤（成品）"],["une épaisseur","courant","「厚度」，不是「一层」"],["un lange","littéraire","旧式襁褓布"]],"fq":"中频，育儿时很常用。","me":"couche = 躺下 (coucher) 垫在身下的一层。","tr":{"zh":"我得给宝宝换尿布。","fr":"Je dois changer la couche du bébé.","alt":"Il faut que je change le bébé, sa couche est pleine.","note":"changer 后直接接宾语：changer la couche。"}},
 "Une fréquentation": {"pos":"n.f. 阴性名词，复数 fréquentations","s":"交往的人；交往、来往。多用复数 les fréquentations：de bonnes / mauvaises fréquentations（好/坏的交往对象）。也可指到访人数、客流量：la fréquentation d'un musée。","ipa":"[fʁe.kɑ̃.ta.sjɔ̃]","ph":"fré [fʁe]；quen 中 qu = [k]，en 鼻化 [ɑ̃]；ta [ta]；-tion [sjɔ̃]。","pi":"qu 读 [k]，不读 [kw]；en 是 [ɑ̃]，不是 [ɛ̃]。","et":"拉丁语 frequentatio，来自 frequentare（常去、常来）。动词：fréquenter（常去；交往）。","ex":[["Ses mauvaises fréquentations l'ont conduit à l'échec.","不良的交往使他失败了。"],["La fréquentation du musée a augmenté.","博物馆的参观人数增加了。"]],"co":[["de mauvaises fréquentations","坏朋友、不良交往"],["avoir de bonnes fréquentations","交往的人不错"],["la fréquentation d'un lieu","某地的客流量"]],"sy":[["les relations","courant","各种人际关系"],["l'entourage","courant","身边的人"],["l'affluence","soutenu","人潮、客流"]],"fq":"中频，常见于谈论教育和社交。","me":"fréquent + -ation：经常往来的人。","tr":{"zh":"他父母担心他的交往对象。","fr":"Ses parents s'inquiètent de ses fréquentations.","alt":"Ses parents n'aiment pas les gens qu'il fréquente.","note":"s'inquiéter de + 名词。"}},
 "Une gazette": {"pos":"n.f. 阴性名词，复数 gazettes","s":"小报；报纸（偏老式或地方性）；也指内部通讯、时事通讯。现在多带点老派或幽默的色彩，例如 la gazette du quartier（街区小报）。","ipa":"[ɡa.zɛt]","ph":"g [ɡ]；a [a]；z [z]；-ette 读 [ɛt]，tt 只读一个 [t]，e 不发音。","pi":"z 读 [z]，不是 [ts]；结尾 -ette 读 [ɛt]，不是 [ɛtə]。","et":"来自意大利语 gazzetta（原指威尼斯的一种小钱币，后指报纸）。","ex":[["J'ai lu cela dans la gazette locale.","我在当地小报上读到的。"],["La gazette de l'école sort chaque mois.","学校的校刊每月出一期。"]],"co":[["la gazette locale","地方小报"],["la gazette de l'école","校刊"],["lire la gazette","读报纸"]],"sy":[["un journal","courant","最常用的「报纸」"],["un quotidien","courant","日报"],["un canard","familier","报纸（口语）"]],"fq":"中低频，偏老派或地方色彩。","me":"gazette ← 威尼斯小钱币：买一份报要花一枚。","tr":{"zh":"我每周都读街区的小报。","fr":"Je lis la gazette du quartier chaque semaine.","alt":"Chaque semaine, je regarde la gazette du coin.","note":"chaque + 单数名词。"}},
 "Une génération": {"pos":"n.f. 阴性名词，复数 générations","s":"一代人；世代；产生、生成。la génération Z；de génération en génération（代代相传）。","ipa":"[ʒe.ne.ʁa.sjɔ̃]","ph":"g 在 é 前读 [ʒ]；gé [ʒe]；né [ne]；ra [ʁa]；-tion [sjɔ̃]。","pi":"g 读 [ʒ]，不是 [ɡ]；-tion 读 [sjɔ̃]。五个音节，不要漏掉 né。","et":"拉丁语 generatio，来自 generare（产生）。同族：genre, général。","ex":[["La nouvelle génération est très connectée.","新一代人高度联网。"],["Trois générations vivent dans cette maison.","这栋房子里住着三代人。"]],"co":[["de génération en génération","代代相传"],["la nouvelle génération","新一代"],["le conflit des générations","代沟、代际冲突"],["la génération d'avant","上一代"]],"sy":[["l'époque","courant","时代"],["la classe d'âge","courant","同龄人群体"],["la lignée","soutenu","世系、血统"]],"fq":"高频，日常和新闻都常见。","me":"génér- 是「生」：一代人生出下一代。","tr":{"zh":"我这一代人不太看电视。","fr":"Ma génération ne regarde pas beaucoup la télévision.","alt":"Les gens de ma génération regardent peu la télé.","note":"ne… pas beaucoup / peu 表示「不太」。"}},
 "Une hanche": {"pos":"n.f. 阴性名词，复数 hanches","s":"臀部两侧的「胯」，髋部。不是整个屁股（fesses）。常用于 les mains sur les hanches（双手叉腰）、le tour de hanches（臀围）。","ipa":"[ɑ̃ʃ]","ph":"h 不发音；an 鼻化 [ɑ̃]；ch [ʃ]；e 不发音。只有一个音节。","pi":"这是「有声 h」(h aspiré)：les hanches 不连诵，读 [le ɑ̃ʃ]，不要读成 [lez‿ɑ̃ʃ]。","et":"来自日耳曼语（法兰克语），不是拉丁语。","ex":[["Elle a les mains sur les hanches.","她双手叉腰。"],["Il s'est cassé la hanche en tombant.","他摔倒时摔断了髋骨。"]],"co":[["les mains sur les hanches","双手叉腰"],["le tour de hanches","臀围"],["se déhancher","扭胯"],["une prothèse de hanche","髋关节假体"]],"sy":[["le bassin","courant","骨盆"],["les fesses","courant","臀部（后面）"],["la taille","courant","腰部"]],"fq":"中频，身体部位词。","me":"hanche = 腰两侧的「胯」，想想扭胯 (se déhancher)。","tr":{"zh":"她双手叉腰站着。","fr":"Elle se tient debout, les mains sur les hanches.","alt":"Elle est là, les mains sur les hanches.","note":"绝对结构 les mains sur les hanches。"}},
 "Une inégalité": {"pos":"n.f. 阴性名词，复数 inégalités","s":"不平等；不均衡；差距。une inégalité salariale 薪酬不平等；les inégalités sociales 社会不平等。反义词 l'égalité（平等）。","ipa":"[i.ne.ɡa.li.te]","ph":"i [i]；né [ne]；ga [ɡa]；li [li]；té [te]。","pi":"in- 在此不是鼻化音：n 要读出来，是 [i.ne]，不是 [ɛ̃]（对比 inconnu）。","et":"in-（否定）+ égalité（拉丁语 aequalitas，来自 aequus「平的」）。","ex":[["Il y a une inégalité salariale entre les hommes et les femmes.","男女之间存在薪酬不平等。"],["Les inégalités augmentent dans ce pays.","这个国家的不平等在加剧。"]],"co":[["les inégalités sociales","社会不平等"],["réduire les inégalités","减少不平等"],["une inégalité de traitement","待遇不平等"],["lutter contre les inégalités","反对不平等"]],"sy":[["la différence","courant","区别，不一定不公平"],["la discrimination","courant","歧视，有明确针对性"],["l'injustice","courant","不公正"]],"fq":"中频，新闻、社会话题常见。","me":"in + égalité：不 + 平等。","tr":{"zh":"社会不平等是一个大问题。","fr":"Les inégalités sociales sont un grand problème.","alt":"Les inégalités sociales, c'est un vrai problème.","note":"主语是复数 les inégalités，所以用 sont。"}},
 "Une librairie": {"pos":"n.f. 阴性名词，复数 librairies","s":"书店。注意：这是「卖书」的地方，不是图书馆！图书馆是 une bibliothèque。","ipa":"[li.bʁɛ.ʁi]","ph":"li [li]；brai 读 [bʁɛ]；rie [ʁi]。三个音节。","pi":"librairie 不是图书馆（bibliothèque），这是中文学习者最常犯的错；ai 读 [ɛ]。","et":"来自 libraire（书商），拉丁语 librarius，源自 liber（书）。","ex":[["Je vais à la librairie pour acheter un livre.","我去书店买书。"],["Cette librairie vend aussi des BD.","这家书店也卖漫画。"]],"co":[["aller à la librairie","去书店"],["une librairie indépendante","独立书店"],["une librairie en ligne","网上书店"]],"sy":[["la bibliothèque","courant","图书馆，借书不买书"],["la boutique de livres","courant","卖书的小店，较少用"],["le bouquiniste","courant","旧书商"]],"fq":"中频，日常常用。","me":"libr- = 书 (livre)；librairie 卖书，bibliothèque 借书。","tr":{"zh":"我想去书店给你买本书。","fr":"Je veux aller à la librairie pour t'acheter un livre.","alt":"Je passe à la librairie pour te prendre un livre.","note":"acheter qqch à qqn：t' 是间接宾语。"}},
 "Une maison de retraite": {"pos":"n.f. 阴性名词，复数 maisons de retraite","s":"养老院。官方名称是 un EHPAD。retraite 本义是「退休」，所以这里是「退休后住的地方」。","ipa":"[mɛ.zɔ̃ də ʁə.tʁɛt]","ph":"mai [mɛ]；s 在元音间读 [z]：son [zɔ̃] 鼻化；de 弱读 [də]；re [ʁə]；traite [tʁɛt]。","pi":"maison 的 s 读 [z]，on 鼻化；de 常弱读；retraite 的 ai 读 [ɛ]，-e 不发音。","et":"maison（拉丁语 mansio「住处」）+ retraite（来自 retraire / retirer「退出」）。","ex":[["Sa grand-mère vit dans une maison de retraite.","她的外婆住在养老院。"],["Il rend visite à son père à la maison de retraite.","他去养老院看望他父亲。"]],"co":[["vivre en maison de retraite","住在养老院"],["être à la retraite","已退休"],["prendre sa retraite","退休"],["un EHPAD","老年护理院（官方）"]],"sy":[["un foyer pour personnes âgées","courant","老年之家，较少用"],["un EHPAD","courant","正式名称"],["un hospice","littéraire","旧式收容所，今已少用"]],"fq":"中频，谈论老年话题时常见。","me":"retraite = 退休；退休后住的 maison。","tr":{"zh":"我外公住在养老院。","fr":"Mon grand-père vit dans une maison de retraite.","alt":"Mon grand-père est en maison de retraite.","note":"vivre dans / être en maison de retraite。"}},
 "Une médaille": {"pos":"n.f. 阴性名词，复数 médailles","s":"奖牌；纪念章；奖章。une médaille d'or / d'argent / de bronze 金牌 / 银牌 / 铜牌。也指项链上的圣牌吊坠。","ipa":"[me.daj]","ph":"mé [me]；-aille 读 [aj]，ll 在此读 [j]，e 不发音。两个音节。","pi":"-aille 读 [aj]，不是 [ɛl]；d 要读清楚 [d]，不是 [t]。","et":"来自意大利语 medaglia。","ex":[["Il a gagné une médaille d'or.","他赢得了一枚金牌。"],["Elle porte une médaille autour du cou.","她脖子上戴着一枚吊坠。"]],"co":[["gagner une médaille","赢得奖牌"],["une médaille d'or","金牌"],["remporter la médaille d'argent","夺得银牌"],["le revers de la médaille","事物的另一面（成语）"]],"sy":[["un trophée","courant","奖杯"],["une décoration","soutenu","勋章"],["une breloque","familier","小挂饰"]],"fq":"中频，体育和比赛常用。","me":"médaille 结尾 -aille 读 [aj]：想想奖牌闪闪发光。","tr":{"zh":"她在比赛中得了一枚银牌。","fr":"Elle a gagné une médaille d'argent à la compétition.","alt":"Elle est repartie avec une médaille d'argent.","note":"gagner une médaille，médaille 阴性所以用 une。"}},
 "Une nuit blanche": {"pos":"n.f. 阴性名词，复数 nuits blanches","s":"不眠之夜；通宵。字面是「白色的夜」。passer une nuit blanche = 彻夜未眠（不一定是失眠，也可能是工作或聚会）。","ipa":"[nɥi blɑ̃ʃ]","ph":"nuit：u 是半元音 [ɥ]，后接 i，t 不发音；blanche：bl [bl]，an 鼻化 [ɑ̃]，ch [ʃ]，e 不发音。","pi":"nuit 的 t 不发音；u 要圆唇读 [ɥ]，后接 i。blanche 的 -che 是 [ʃ]。","et":"nuit（拉丁语 nox, noctis）+ blanc（日耳曼语来源）。blanche 是阴性形式。","ex":[["J'ai passé une nuit blanche à travailler.","我工作了一整夜。"],["Après une nuit blanche, je suis épuisé.","熬了个通宵之后，我累极了。"]],"co":[["passer une nuit blanche","熬通宵"],["faire une nuit blanche","熬通宵"],["une nuit blanche avant l'examen","考试前的不眠夜"]],"sy":[["une nuit sans sommeil","courant","无眠之夜（更直白）"],["une insomnie","courant","失眠"],["veiller","soutenu","守夜、熬夜（动词）"]],"fq":"中频，日常常用。","me":"nuit blanche = 白夜：天亮了还没睡。","tr":{"zh":"昨晚我整夜没睡。","fr":"Hier soir, j'ai passé une nuit blanche.","alt":"J'ai pas fermé l'œil de la nuit.","note":"passer une nuit blanche；不要写成 une blanche nuit。"}},
 "Une sage-femme": {"pos":"n.f. 阴性名词，复数 sages-femmes（sage 也变复数）","s":"助产士。现在男助产士也可说 un sage-femme（词仍保留 femme）。她们负责孕期检查和接生。","ipa":"[saʒ.fam]","ph":"sage [saʒ]；femme 读 [fam]，e 在此读 [a]；连字号两个词。","pi":"femme 读 [fam]，不是 [fɛm]；g 在 e 前读 [ʒ]。复数是 des sages-femmes。","et":"sage 这里是旧义「有经验的、有智慧的」+ femme。意思是「有经验的女人」。","ex":[["La sage-femme l'a aidée pendant l'accouchement.","助产士在分娩时帮助了她。"],["Elle veut devenir sage-femme.","她想当助产士。"]],"co":[["devenir sage-femme","成为助产士"],["consulter une sage-femme","找助产士咨询"],["le suivi par une sage-femme","助产士跟踪随访"]],"sy":[["un accoucheur","courant","男产科医生，旧称"],["un obstétricien","soutenu","产科医生"],["une gynécologue","courant","妇科医生"]],"fq":"中低频，医疗场景。","me":"sage-femme = 「有智慧的女人」帮你接生。","tr":{"zh":"助产士在医院里工作。","fr":"La sage-femme travaille à l'hôpital.","alt":"Ma sage-femme travaille à la maternité.","note":"职业前通常省略冠词：elle est sage-femme。"}},
 "Une tempête": {"pos":"n.f. 阴性名词，复数 tempêtes","s":"风暴；暴风雨。une tempête de neige 暴风雪。也可比喻「风波、争议」：une tempête politique。","ipa":"[tɑ̃.pɛt]","ph":"tem 读 [tɑ̃]，鼻化；pê 读 [pɛ]；te 不发音。两个音节。","pi":"tem 读 [tɑ̃]，不是 [tɛm]；ê 读开口 [ɛ]；结尾 t 要读出来，e 不发音。","et":"拉丁语 tempestas（天气、时节，后指风暴），同族于 temps（时间；天气）。","ex":[["Une violente tempête approche.","一场猛烈的风暴正在逼近。"],["La tempête a arraché des arbres.","风暴刮倒了好几棵树。"]],"co":[["une tempête de neige","暴风雪"],["une tempête de sable","沙尘暴"],["en pleine tempête","风暴正猛时"],["une tempête dans un verre d'eau","小题大做（成语）"]],"sy":[["un orage","courant","雷雨，侧重雷电"],["un ouragan","courant","飓风"],["une bourrasque","soutenu","阵风、狂风"]],"fq":"中频，天气报道中常见。","me":"tempête ← temps：天气变坏就是 tempête。","tr":{"zh":"明天会有一场大风暴。","fr":"Il y aura une grosse tempête demain.","alt":"Demain, une grosse tempête arrive.","note":"il y aura = 将会有（il y a 的将来时）。"}},
 "Une toile": {"pos":"n.f. 阴性名词，复数 toiles","s":"画布；油画；布料（帆布）；网。une toile d'araignée 蜘蛛网；la Toile（大写）= 互联网。一幅画也常说 une toile。","ipa":"[twal]","ph":"toi 读 [twa]（oi = [wa]）；l 要读出来；-e 不发音。一个音节。","pi":"oi 读 [wa]，不是 [oi]；l 要读出来 [twal]，不要漏掉。","et":"拉丁语 tela（织物、网）。","ex":[["L'artiste peint sur une grande toile.","艺术家在大画布上作画。"],["Une araignée a fait sa toile dans le coin.","一只蜘蛛在角落里结了网。"]],"co":[["peindre sur toile","在画布上作画"],["une toile d'araignée","蜘蛛网"],["une toile cirée","桌上的防水桌布"],["surfer sur la Toile","上网"]],"sy":[["un tableau","courant","一幅画（成品）"],["un tissu","courant","布料"],["le web","courant","网络"]],"fq":"中频。","me":"toile 读 [twal]：画布就是一块「布」。","tr":{"zh":"他在一块大画布上作画。","fr":"Il peint sur une grande toile.","alt":"Il est en train de peindre une grande toile.","note":"peindre sur + 名词。"}},
 "Des fringues": {"pos":"n.f.pl. 阴性复数名词（口语）","s":"衣服（口语、非正式）。几乎总是复数：mes fringues。se fringuer = 穿衣打扮（口语）。","ipa":"[fʁɛ̃ɡ]","ph":"fr [fʁ]；in 鼻化 [ɛ̃]；-gues 读 [ɡ]，u 和 e 都不发音。一个音节。","pi":"gu 在 e 前的 u 不发音，g 读 [ɡ]：fringues 读 [fʁɛ̃ɡ]；in 鼻化，不要读 [fʁiŋɡ]。","et":"来源不确定（口语词），可能和 fringuer（穿衣打扮）有关。","ex":[["J'ai acheté de nouvelles fringues hier.","我昨天买了新衣服。"],["Range tes fringues, c'est le bazar !","把你的衣服收好，乱七八糟的！"]],"co":[["acheter des fringues","买衣服"],["de nouvelles fringues","新衣服"],["se fringuer","穿衣打扮（口语）"]],"sy":[["des vêtements","courant","衣服（标准说法）"],["des habits","courant","衣服"],["des fringues","familier","口语，不用于正式场合"]],"fq":"高频口语，不宜用于正式场合。","me":"fringues 是 fringuer（穿衣）的名词：就是「身上穿的行头」。","tr":{"zh":"我周末要去买新衣服。","fr":"Je vais acheter des fringues ce week-end.","alt":"Ce week-end, je vais faire les magasins pour des fringues.","note":"fringues 是口语，正式场合用 vêtements。"}},
 "Des genoux": {"pos":"n.m.pl. 阳性复数名词，单数 genou，复数 genoux（-ou 加 x）","s":"膝盖。à genoux = 跪着；sur les genoux de qqn = 坐在某人大腿上（注意：不是「在膝盖上」）。","ipa":"[ʒə.nu]","ph":"ge [ʒə]（弱读，口语常省略）；-noux 读 [nu]，x 不发音。","pi":"复数 -x 不发音，所以 genou 和 genoux 读音相同；g 在 e 前读 [ʒ]。","et":"拉丁语 genuculum（genu 的指小形式）。同族：s'agenouiller（跪下）。","ex":[["Il a mal aux genoux après avoir couru.","跑步后他膝盖疼。"],["L'enfant s'assoit sur les genoux de sa mère.","孩子坐在妈妈的腿上。"]],"co":[["à genoux","跪着"],["s'agenouiller","跪下"],["sur les genoux de qqn","在某人腿上"],["avoir mal aux genoux","膝盖疼"]],"sy":[["la jambe","courant","整条腿，不是膝盖"],["la rotule","courant","髌骨"],["les cuisses","courant","大腿"]],"fq":"中频，身体部位词。","me":"genou 复数多一个 x：genoux。","tr":{"zh":"跑步后我的膝盖很疼。","fr":"Après avoir couru, j'ai mal aux genoux.","alt":"J'ai les genoux qui font mal après la course.","note":"avoir mal à + 部位：aux genoux。"}},
 "Des peines, des chagrins": {"pos":"n.f.pl. peines（阴性）/ n.m.pl. chagrins（阳性）","s":"peine：痛苦、悲伤，也指「刑罚」或「费力」（avoir de la peine à = 很难做到）。chagrin：悲伤、伤心，多指心里的难过。两词连用 = 种种悲痛。","ipa":"[pɛn, ʃa.ɡʁɛ̃]","ph":"peine [pɛn]：ei = [ɛ]，e 不发音；chagrin：ch [ʃ]，gr [ɡʁ]，in 鼻化 [ɛ̃]。","pi":"chagrin 的 in 鼻化 [ɛ̃]，n 不发音；ch 读 [ʃ]。peines 的复数 -s 不发音。peine 是阴性，chagrin 是阳性。","et":"peine：拉丁语 poena（惩罚）。chagrin：来源不确定。","ex":[["Il a connu beaucoup de peines.","他经历过很多痛苦。"],["Elle a eu un grand chagrin d'amour.","她经历了一场伤心的失恋。"]],"co":[["avoir du chagrin","伤心"],["un chagrin d'amour","失恋之痛"],["avoir de la peine","难过"],["faire de la peine à qqn","让某人难过"]],"sy":[["la tristesse","courant","悲伤（最常用）"],["la douleur","soutenu","痛苦（强烈）"],["le malheur","courant","不幸"]],"fq":"中频，书面和日常都用。","me":"peine = 痛苦，chagrin = 心里的伤，一对近义词。","tr":{"zh":"他经历过许多痛苦和悲伤。","fr":"Il a connu beaucoup de peines et de chagrins.","alt":"Il en a vu, des peines et des chagrins.","note":"beaucoup de + 复数名词；peine 阴性，chagrin 阳性。"}},
 "Des soucis": {"pos":"n.m.pl. 阳性复数名词，单数 souci","s":"烦恼；忧虑；麻烦。avoir des soucis (d'argent / de santé)。口语 Pas de souci ! = 没问题！","ipa":"[su.si]","ph":"sou [su]；ci [si]；复数 -s 不发音。两个音节。","pi":"ou 读 [u]；ci 读 [si]；复数 s 不发音，单复数读音相同。","et":"来自动词 soucier（担心），拉丁语 sollicitare（扰动、使不安）。","ex":[["Il a beaucoup de soucis en ce moment.","他最近有很多烦恼。"],["Pas de souci, je m'en occupe.","没问题，我来处理。"]],"co":[["avoir des soucis","有烦恼 / 有麻烦"],["se faire du souci","担心"],["pas de souci","没问题（口语）"],["des soucis d'argent","金钱烦恼"]],"sy":[["des ennuis","courant","麻烦、困扰"],["des problèmes","courant","问题"],["des tracas","soutenu","小烦恼"]],"fq":"高频，日常常用。","me":"souci = 「所有的」小事压心上。","tr":{"zh":"我最近有很多烦恼。","fr":"J'ai beaucoup de soucis en ce moment.","alt":"Ces temps-ci, j'ai plein de soucis.","note":"beaucoup de + 复数名词。"}},
 "Les affaires": {"pos":"n.f.pl. 阴性复数名词，单数 affaire","s":"个人物品，东西（mes affaires）；事务；生意。les affaires de classe 学习用品；faire des affaires 做生意；Ce ne sont pas tes affaires. = 不关你的事。","ipa":"[a.fɛʁ]","ph":"a [a]；ff 读一个 [f]；aire 读 [ɛʁ]；les affaires 连诵 [le.za.fɛʁ]。","pi":"ff 只读一个 f；les affaires 要连诵，s 读 [z]；ai 读 [ɛ]。","et":"à + faire：「要做的事」，后来引申为事务、物品。","ex":[["Il a oublié ses affaires à l'école.","他把东西忘在学校了。"],["Range tes affaires dans ta chambre.","把你的东西收到房间里去。"]],"co":[["ranger ses affaires","收拾东西"],["faire des affaires","做生意"],["les affaires de classe","学习用品"],["Ce ne sont pas tes affaires.","这不关你的事。"]],"sy":[["des objets","courant","物品，更泛指"],["des choses","courant","东西（很口语）"],["des effets personnels","soutenu","个人物品（正式）"]],"fq":"极高频，日常常用。","me":"à faire：要整理的「东西」和「事」。","tr":{"zh":"请把你的东西带上。","fr":"Prends tes affaires, s'il te plaît.","alt":"N'oublie pas tes affaires !","note":"affaires 的物主形容词用复数：tes affaires。"}},
 "Un chercheur / Une chercheuse": {"pos":"n. 名词，阳 chercheur / 阴 chercheuse，复数 chercheurs / chercheuses","s":"研究员；研究者。chercheur d'emploi 是求职者；chercheur d'or 是淘金者。动词 chercher = 寻找。","ipa":"[ʃɛʁ.ʃœʁ]","ph":"cher 读 [ʃɛʁ]；cheur 读 [ʃœʁ]；两个 ch 都读 [ʃ]；阴性 chercheuse [ʃɛʁ.ʃøz]。","pi":"eu 在 -eur 里读 [œ]；阴性 -euse 变成 [øz]，音也变。ch 不是 [k]。","et":"chercher（拉丁语 circare「四处转」）+ -eur（做……的人）。","ex":[["Ce chercheur travaille sur un nouveau vaccin.","这位研究员在研究一种新疫苗。"],["Elle est chercheuse au CNRS.","她是法国国家科研中心的研究员。"]],"co":[["un chercheur en biologie","生物学研究员"],["une équipe de chercheurs","研究团队"],["un chercheur d'emploi","求职者"],["un chercheur d'or","淘金者"]],"sy":[["un scientifique","courant","科学家，更泛指"],["un universitaire","courant","大学学者"],["un savant","soutenu","学者、博学之人"]],"fq":"中频，科研话题常见。","me":"chercher + -eur：「寻找」答案的人。","tr":{"zh":"我姐姐是研究员。","fr":"Ma sœur est chercheuse.","alt":"Ma sœur travaille comme chercheuse.","note":"职业不加冠词：elle est chercheuse。"}},
 "Un chômeur / Une chômeuse": {"pos":"n. 名词，阳 chômeur / 阴 chômeuse，复数 chômeurs / chômeuses","s":"失业者。le chômage = 失业；être au chômage = 失业中。chômeur 指找不到工作的人，和退休者 retraité 不同。","ipa":"[ʃo.mœʁ]","ph":"chô [ʃo]；meur [mœʁ]；ô 读闭口 [o]；阴性 chômeuse [ʃo.møz]。","pi":"ô 读 [o]；eu 在 -eur 里读 [œ]，在 -euse 里读 [ø]。","et":"chômer（歇工、不工作）+ -eur。同族：chômage（失业）。","ex":[["Il est chômeur depuis un an.","他失业一年了。"],["Elle est chômeuse depuis la fermeture de l'usine.","自工厂关闭以来她一直失业。"]],"co":[["être au chômage","失业"],["un chômeur de longue durée","长期失业者"],["s'inscrire comme chômeur","登记失业"],["le taux de chômage","失业率"]],"sy":[["un demandeur d'emploi","soutenu","求职者（正式名称）"],["un sans-emploi","courant","无业者"],["un travailleur","courant","反义：劳动者"]],"fq":"中频，新闻、社会话题常见。","me":"chômer = 歇着没活干 → chômeur。","tr":{"zh":"我邻居已经失业两年了。","fr":"Mon voisin est chômeur depuis deux ans.","alt":"Mon voisin est au chômage depuis deux ans.","note":"depuis + 时间：持续到现在用现在时。"}},
 "Un compositeur / Une compositrice": {"pos":"n. 名词，阳 compositeur / 阴 compositrice，复数 compositeurs / compositrices","s":"作曲家。动词 composer = 作曲；组成。la composition = 作曲；构成；作文。","ipa":"[kɔ̃.po.zi.tœʁ]","ph":"com [kɔ̃] 鼻化；po [po]；si [zi]（s 在元音间读 [z]）；teur [tœʁ]。","pi":"composer 的 s 读 [z]；阴性 compositrice 读 [kɔ̃.po.zi.tʁis]，与阳性后缀不同。","et":"拉丁语 compositor，来自 componere（放在一起）。同族：composer, composition。","ex":[["Mozart est un célèbre compositeur.","莫扎特是著名的作曲家。"],["Cette compositrice a écrit la musique du film.","这位女作曲家为这部电影写了配乐。"]],"co":[["un compositeur de musique","作曲家"],["un compositeur classique","古典作曲家"],["une compositrice de films","电影配乐作曲家"]],"sy":[["un musicien","courant","音乐家，更泛指"],["un auteur-compositeur","courant","词曲创作人"],["un chef d'orchestre","courant","指挥，不同职业"]],"fq":"中低频，音乐话题。","me":"composer 作曲，compositeur 是「组合音符的人」。","tr":{"zh":"我最喜欢的作曲家是德彪西。","fr":"Mon compositeur préféré est Debussy.","alt":"Mon compositeur favori, c'est Debussy.","note":"préféré / favori：形容词放在名词后。"}},
 "Un indépendant / Une indépendante": {"pos":"n. 名词（也作形容词），阳 indépendant / 阴 indépendante，复数 indépendants / indépendantes","s":"自由职业者；个体经营者。travailler en indépendant / à son compte。作形容词意思是「独立的」。","ipa":"[ɛ̃.de.pɑ̃.dɑ̃]","ph":"in [ɛ̃]；dé [de]；pen [pɑ̃]；dant [dɑ̃]；阴性 indépendante [ɛ̃.de.pɑ̃.dɑ̃t]。","pi":"三个鼻化元音 [ɛ̃] [ɑ̃] [ɑ̃]，别把 in 读成 [in]；-ant 和 -ent 的鼻化音相同 [ɑ̃]。","et":"in-（否定）+ dépendant（拉丁语 dependere「悬挂在……上」）。","ex":[["Elle travaille comme indépendante.","她是自由职业者。"],["Les indépendants paient leurs propres charges.","个体经营者要自己缴纳费用。"]],"co":[["travailler en indépendant","做自由职业"],["travailler à son compte","自己做生意"],["un travailleur indépendant","独立劳动者"],["l'indépendance","独立"]],"sy":[["un freelance","familier","自由职业者（英语借词）"],["un travailleur indépendant","courant","标准说法"],["un auto-entrepreneur","courant","个体经营者（法国制度）"]],"fq":"中频，工作话题常见。","me":"in + dépendant：不依赖别人的人。","tr":{"zh":"我哥哥是自由职业者。","fr":"Mon frère est indépendant.","alt":"Mon frère travaille à son compte.","note":"职业词 indépendant 作表语时不加冠词。"}},
 "Un libraire / Une libraire": {"pos":"n. 名词，阴阳同形：un libraire / une libraire，复数 libraires","s":"书商；书店老板或店员。librairie 才是书店。注意：不是图书管理员，那是 un bibliothécaire。","ipa":"[li.bʁɛʁ]","ph":"li [li]；braire 读 [bʁɛʁ]；ai 读 [ɛ]，结尾 r 要读出来。","pi":"结尾 r 要读 [ʁ]；不要和 bibliothécaire（图书管理员）混淆。阳阴同形，只改冠词。","et":"拉丁语 librarius，来自 liber（书）。同族：librairie, livre。","ex":[["Le libraire m'a conseillé ce roman.","书商给我推荐了这本小说。"],["Ma tante est libraire à Lyon.","我姑姑在里昂当书商。"]],"co":[["demander conseil au libraire","向书商咨询"],["un libraire indépendant","独立书商"],["être libraire","做书商"]],"sy":[["un bouquiniste","courant","旧书商"],["un vendeur","courant","店员，泛指"],["un bibliothécaire","courant","图书管理员，不同职业"]],"fq":"中低频。","me":"libraire 卖书，bibliothécaire 管书。","tr":{"zh":"书商给我推荐了一本好书。","fr":"Le libraire m'a recommandé un bon livre.","alt":"Le libraire m'a conseillé un bouquin.","note":"recommander / conseiller qqch à qqn。"}},
 "Un ouvrier / Une ouvrière": {"pos":"n. 名词，阳 ouvrier / 阴 ouvrière，复数 ouvriers / ouvrières","s":"工人（体力劳动者）。ouvrier qualifié 熟练工；la classe ouvrière 工人阶级。形容词 ouvrier / ouvrière = 工人的。","ipa":"[u.vʁi.je]","ph":"ou [u]；vri [vʁi]；-ier 读 [je]；三个音节。阴性 ouvrière [u.vʁi.jɛʁ]。","pi":"-ier 读 [je]，r 不发音；阴性 -ière 读 [jɛʁ]，r 要发。别把 ou 读成 [o]。","et":"拉丁语 operarius（做工的），来自 opus, operis（工作）。同族：œuvre, opérer。","ex":[["Cet ouvrier travaille à l'usine.","这名工人在工厂工作。"],["Les ouvrières ont fait grève hier.","女工们昨天罢工了。"]],"co":[["un ouvrier qualifié","熟练工"],["la classe ouvrière","工人阶级"],["un ouvrier agricole","农业工人"],["un ouvrier d'usine","工厂工人"]],"sy":[["un travailleur","courant","劳动者，泛指"],["un employé","courant","雇员（办公室等）"],["un prolo","familier","工人（口语，略带贬义）"]],"fq":"中频，社会和工作话题。","me":"ouvrier 与 ouvrir（打开）无关，来自 œuvre：做工的人。","tr":{"zh":"这家工厂有两百名工人。","fr":"Cette usine emploie deux cents ouvriers.","alt":"Il y a deux cents ouvriers dans cette usine.","note":"cent 前有数字且后接名词时加 s：deux cents ouvriers。"}},
 "Un pianiste / Une pianiste": {"pos":"n. 名词，阴阳同形：un pianiste / une pianiste，复数 pianistes","s":"钢琴家；弹钢琴的人。jouer du piano = 弹钢琴（du）。","ipa":"[pja.nist]","ph":"pia 读 [pja]；ni [ni]；ste 读 [st]；两个音节。","pi":"pia 要连成一个音节 [pja]；阳阴同形，只改冠词。","et":"piano + -iste（做……的人）。piano 来自意大利语 pianoforte 的缩略。","ex":[["Ce pianiste est très talentueux.","这位钢琴家很有才华。"],["Elle est pianiste dans un orchestre.","她是乐团里的钢琴家。"]],"co":[["un pianiste de jazz","爵士钢琴家"],["un pianiste classique","古典钢琴家"],["jouer du piano","弹钢琴"]],"sy":[["un musicien","courant","音乐家，泛指"],["un virtuose","soutenu","名家"],["un claviériste","courant","键盘手"]],"fq":"中低频，音乐话题。","me":"piano + -iste：弹 piano 的人。","tr":{"zh":"我最喜欢的钢琴家是肖邦。","fr":"Mon pianiste préféré est Chopin.","alt":"Mon pianiste favori, c'est Chopin.","note":"préféré 放在名词后。"}},
 "Un tremblement de terre / un séisme": {"pos":"n.m. 阳性名词，复数 tremblements de terre / séismes","s":"地震。tremblement de terre 日常常用；séisme 更正式，常见于新闻和科学。secousse = 震动；une réplique = 余震。","ipa":"[tʁɑ̃.blə.mɑ̃ də tɛʁ], [se.ism]","ph":"tremblement：trem [tʁɑ̃]，ble [blə]，ment [mɑ̃]；de [də]；terre [tɛʁ]。séisme：sé [se]，i [i]，sme [ism]（s 读 [s]，e 不发音）。","pi":"-ment 读 [mɑ̃]，t 不发音；terre 的 rr 只读一个 [ʁ]；séisme 的 é 与 i 要分开读。","et":"tremblement：trembler + -ment（拉丁语 tremulare）；séisme：希腊语 seismos（震动）。","ex":[["Il y a eu un tremblement de terre hier.","昨天发生了地震。"],["Un séisme de magnitude 6 a frappé la région.","一场六级地震袭击了该地区。"]],"co":[["un tremblement de terre","地震"],["un séisme de magnitude 5","五级地震"],["l'épicentre du séisme","震中"],["une réplique","余震"]],"sy":[["une secousse","courant","震动、一次摇晃"],["un séisme","soutenu","正式用词"],["une catastrophe naturelle","courant","自然灾害"]],"fq":"中频，新闻常见。","me":"tremble + terre：土地在颤抖。","tr":{"zh":"昨晚这个地区发生了地震。","fr":"Il y a eu un tremblement de terre dans la région hier soir.","alt":"Hier soir, la région a été secouée par un séisme.","note":"il y a eu = 发生了（复合过去时）。"}},
 "Un/Une pédopsychiatre": {"pos":"n. 名词，阴阳同形：un / une pédopsychiatre","s":"儿童精神科医生，专门治疗儿童和青少年的心理问题。常缩写作 pédopsy（口语）。","ipa":"[pe.do.psi.kjatʁ]","ph":"pé [pe]；do [do]；psy 中 p 要发音 [psi]；chia 中 ch 读 [k]：[kja]；-tre 轻读 [tʁ]。","pi":"psy- 中 p 要读出来 [ps]；ch 读 [k]，不是 [ʃ]；结尾 -tre 的 e 不发音。","et":"pédo-（希腊语 pais, paidos「孩子」）+ psychiatre（psukhē「灵魂」+ iatros「医生」）。","ex":[["Le pédopsychiatre aide les enfants en difficulté.","儿童精神科医生帮助有困难的孩子。"],["Elle a consulté un pédopsychiatre pour son fils.","她带儿子去看了儿童精神科医生。"]],"co":[["consulter un pédopsychiatre","看儿童精神科"],["un service de pédopsychiatrie","儿童精神科"],["être suivi par un pédopsychiatre","接受儿童精神科治疗"]],"sy":[["un psychiatre","courant","精神科医生（成人）"],["un psychologue","courant","心理学家，不开药"],["un pédiatre","courant","儿科医生，不同专业"]],"fq":"低频，医疗专业词。","me":"pédo（孩子）+ psychiatre。","tr":{"zh":"医生建议她去看儿童精神科医生。","fr":"Le médecin lui a conseillé de voir un pédopsychiatre.","alt":"Le docteur lui a dit d'aller voir un pédopsychiatre.","note":"conseiller à qqn de + 不定式。"}},
 "Un/Une psychiatre": {"pos":"n. 名词，阴阳同形：un / une psychiatre","s":"精神科医生（可以开药）。和 un psychologue（心理学家，不能开药）不同。口语缩写 psy 既可指精神科医生也可指心理医生。","ipa":"[psi.kjatʁ]","ph":"psy 中 p 要读出来 [psi]；chia 中 ch 读 [k]：[kja]；-tre 轻读 [tʁ]。","pi":"p 不能省；ch 读 [k]；结尾 -tre 的 e 不发音。别把 psychiatre 和 psychologue 混用。","et":"希腊语 psukhē（灵魂）+ iatros（医生）。同族：psychologie, pédiatre。","ex":[["Il consulte un psychiatre.","他去看精神科医生。"],["Ma sœur est psychiatre à l'hôpital.","我姐姐是医院的精神科医生。"]],"co":[["consulter un psychiatre","看精神科"],["être suivi par un psychiatre","接受精神科治疗"],["un hôpital psychiatrique","精神病医院"]],"sy":[["un psychologue","courant","心理学家，不开药"],["un psy","familier","口语：心理医生或精神科医生"],["un thérapeute","courant","治疗师"]],"fq":"中低频，医疗话题。","me":"psy + iatre：医治心灵的医生。","tr":{"zh":"他需要去看精神科医生。","fr":"Il a besoin de voir un psychiatre.","alt":"Il doit aller voir un psychiatre.","note":"avoir besoin de + 不定式。"}},
 "Un/Une documentariste": {"pos":"n. 名词，阴阳同形：un / une documentariste","s":"纪录片导演（或制作人）。documentaire = 纪录片；document = 文件、资料。","ipa":"[dɔ.ky.mɑ̃.ta.ʁist]","ph":"do [dɔ]；cu [ky]；men [mɑ̃]；ta [ta]；riste [ʁist]。五个音节，重音在最后。","pi":"u 读 [y]（圆唇），不是 [u]；men 是鼻化 [mɑ̃]；-iste 的 e 不发音。","et":"documentaire + -iste；document 来自拉丁语 documentum（教训、证据）。","ex":[["Ce documentariste a filmé des lions.","这位纪录片导演拍过狮子。"],["Elle est documentariste pour la télévision.","她为电视台拍纪录片。"]],"co":[["un documentariste célèbre","著名的纪录片导演"],["tourner un documentaire","拍纪录片"],["un film documentaire","纪录片"]],"sy":[["un réalisateur","courant","导演（泛指）"],["un cinéaste","soutenu","电影人"],["un reporter","courant","记者、摄影记者"]],"fq":"低频，影视话题。","me":"documentaire + -iste：拍纪录片的人。","tr":{"zh":"她是一位纪录片导演。","fr":"C'est une documentariste.","alt":"Elle fait des documentaires.","note":"c'est + une + 名词：介绍某人的职业。"}},
 "Un/Une virtuose": {"pos":"n. 名词（也作形容词），阴阳同形：un / une virtuose","s":"名家；演奏大师（技艺精湛的人，多指音乐）。也可作形容词：un jeu virtuose。une virtuose du violon = 小提琴大师。","ipa":"[viʁ.tɥoz]","ph":"vir [viʁ]；tuo 读 [tɥo]（u 是半元音 [ɥ]）；se 读 [z]。","pi":"tuo 里 u 读 [ɥ]；结尾 -se 读 [z]；r 要读 [ʁ]。别读成英语的 virtuoso。","et":"来自意大利语 virtuoso，源自拉丁语 virtus（美德、才能）。","ex":[["C'est une virtuose du violon.","她是小提琴大师。"],["Ce virtuose joue sans partition.","这位大师不看谱子演奏。"]],"co":[["un virtuose du piano","钢琴大师"],["une virtuose du violon","小提琴大师"],["un jeu virtuose","精湛的演奏"],["la virtuosité","高超的技艺"]],"sy":[["un maître","soutenu","大师"],["un prodige","courant","天才、奇才"],["un as","familier","高手"]],"fq":"低中频，音乐和艺术话题。","me":"virtuose ← virtus：有「德」有「才」的名家。","tr":{"zh":"她是一位钢琴大师。","fr":"C'est une virtuose du piano.","alt":"Elle joue du piano comme une virtuose.","note":"virtuose 阴阳同形；du piano 表示乐器。"}},
 "Abandonner": {"pos":"v. 动词，第一组（-er），助动词 avoir；过去分词 abandonné","s":"放弃；抛弃；遗弃。abandonner un projet 放弃计划；abandonner son chien 遗弃狗；s'abandonner à = 沉溺于。","ipa":"[a.bɑ̃.dɔ.ne]","ph":"a [a]；ban [bɑ̃] 鼻化；do [dɔ]；ner [ne]。-onner 中 on 不鼻化，因为 nn 双写。","pi":"abandonner 中的 on 不鼻化：是 [dɔ.ne]，不是 [dɔ̃]；ban 才是鼻化音。","et":"来自古法语 à bandon（「任凭处置」），bandon 意为「权力、控制」。","ex":[["Il ne faut jamais abandonner.","永远不要放弃。"],["Ils ont abandonné leur chien sur l'autoroute.","他们把狗遗弃在高速公路上。"]],"co":[["abandonner un projet","放弃计划"],["abandonner ses études","辍学"],["abandonner quelqu'un","抛弃某人"],["ne jamais abandonner","永不放弃"]],"sy":[["renoncer (à)","courant","放弃（renoncer à qqch）"],["laisser tomber","familier","算了、放弃"],["délaisser","soutenu","冷落、弃置"]],"fq":"高频，日常常用。","me":"à bandon：任人处置 → 放手、放弃。","tr":{"zh":"不要放弃，你快成功了。","fr":"N'abandonne pas, tu y es presque.","alt":"Lâche pas, t'y es presque !","note":"否定命令式：N'abandonne pas。"}},
 "Accoucher": {"pos":"v. 动词，第一组（-er），助动词 avoir；过去分词 accouché","s":"生孩子；分娩。elle a accouché d'une fille = 她生了个女儿。口语 Accouche ! = 「快说！」（familier）。","ipa":"[a.ku.ʃe]","ph":"a [a]；cc 在 ou 前读一个 [k]；ou [u]；ch [ʃ]；-er [e]。","pi":"cc 在 a/o/u 前读 [k]，不是 [ks]（对比 accident [ak.si.dɑ̃]）；ch 读 [ʃ]。","et":"à + coucher（躺下）：原指「躺下准备生产」。同族：coucher, couche。","ex":[["Elle va accoucher le mois prochain.","她下个月要生了。"],["Elle a accouché d'un garçon hier.","她昨天生了个男孩。"]],"co":[["accoucher d'un garçon / d'une fille","生下男孩 / 女孩"],["accoucher à l'hôpital","在医院分娩"],["un accouchement","分娩"],["Accouche !","快说！（口语）"]],"sy":[["mettre au monde","courant","生下（孩子）"],["donner naissance à","soutenu","诞下"],["enfanter","littéraire","生育"]],"fq":"中频，日常和医疗场景。","me":"à + coucher：躺下来生孩子。","tr":{"zh":"她预计下个月生孩子。","fr":"Elle doit accoucher le mois prochain.","alt":"Elle va accoucher dans un mois.","note":"devoir + 不定式可表示「预计」。"}},
 "Accrocher": {"pos":"v. 动词，第一组（-er），助动词 avoir；过去分词 accroché","s":"挂；钩住；勾住。accrocher une veste 把外套挂起来；s'accrocher à = 紧紧抓住。也指撞到、刮到：accrocher une voiture。口语 ça accroche = 合得来。","ipa":"[a.kʁɔ.ʃe]","ph":"a [a]；cc 读 [k]；cro 读 [kʁɔ]（开口 o）；-cher 读 [ʃe]。","pi":"cc 读 [k]，o 在 cro 中是开口 [ɔ]；别和 raccrocher（挂断电话）混淆。","et":"croc（钩子，日耳曼语）+ à：「用钩子钩住」。","ex":[["Je vais accrocher ce tableau au mur.","我要把这幅画挂在墙上。"],["Il s'accroche à la rampe.","他紧紧抓住扶手。"]],"co":[["accrocher un tableau","挂画"],["s'accrocher à","紧抓、坚持"],["accrocher quelqu'un","引人注意；碰撞"],["raccrocher","挂断电话"]],"sy":[["suspendre","soutenu","悬挂"],["pendre","courant","吊起、挂"],["fixer","courant","固定"]],"fq":"中频，日常常用。","me":"ac + croc：用钩子 (croc) 钩上去。","tr":{"zh":"你可以把外套挂在这儿。","fr":"Tu peux accrocher ta veste ici.","alt":"Mets ta veste là, au crochet.","note":"accrocher qqch à / sur + 地点。"}},
 "Alarmer": {"pos":"v. 动词，第一组（-er），助动词 avoir；过去分词 alarmé","s":"使惊慌；使担忧。s'alarmer (de) = 担心起来、惊慌。形容词 alarmant(e) = 令人担忧的。","ipa":"[a.laʁ.me]","ph":"a [a]；lar [laʁ]；mer [me]。词尾 -er 读 [e]。","pi":"-er 在词尾读 [e]，r 不发音；ar 里 r 读 [ʁ]。别和 alarme（警报）的读音弄混。","et":"来自 alarme（意大利语 all'arme「拿起武器」）+ -er。","ex":[["Je ne veux pas vous alarmer.","我不想吓到你们。"],["Ne vous alarmez pas, ce n'est rien.","别慌，没什么事。"]],"co":[["alarmer les gens","让人惊慌"],["s'alarmer pour rien","无故惊慌"],["une nouvelle alarmante","令人担忧的消息"]],"sy":[["inquiéter","courant","使担心，更常用"],["effrayer","courant","吓到"],["affoler","courant","使慌乱"]],"fq":"中低频，偏书面。","me":"alarme → alarmer：响起警报，让人惊慌。","tr":{"zh":"我不想让你担心。","fr":"Je ne veux pas t'alarmer.","alt":"Je ne veux pas te faire peur.","note":"ne… pas + vouloir；alarmer 后接直接宾语。"}},
 "Allaiter": {"pos":"v. 动词，第一组（-er），助动词 avoir；过去分词 allaité","s":"哺乳；母乳喂养。allaiter son enfant。也说 donner le sein / nourrir au sein。lait（奶）同源。","ipa":"[a.lɛ.te]","ph":"a [a]；ll 读 [l]；ai [ɛ]；ter [te]。三个音节。","pi":"这里 ll 读 [l]，不是 [j]（对比 médaille）；ai 读 [ɛ]。","et":"拉丁语 allactare，来自 lac, lactis（奶）。同族：lait, lactose。","ex":[["Elle a choisi d'allaiter son bébé.","她选择母乳喂养。"],["Elle allaite encore sa fille.","她还在给女儿喂奶。"]],"co":[["allaiter un bébé","哺乳婴儿"],["l'allaitement maternel","母乳喂养"],["donner le sein","喂母乳"],["sevrer un bébé","给婴儿断奶"]],"sy":[["nourrir au sein","courant","用母乳喂养"],["donner le biberon","courant","用奶瓶喂（反义）"],["téter","courant","吮吸（婴儿）"]],"fq":"中低频，育儿话题。","me":"al + lait：给孩子喂 lait。","tr":{"zh":"她决定母乳喂养她的宝宝。","fr":"Elle a décidé d'allaiter son bébé.","alt":"Elle va donner le sein à son bébé.","note":"décider de + 不定式。"}},
 "Blesser": {"pos":"v. 动词，第一组（-er），助动词 avoir；过去分词 blessé","s":"弄伤；伤害（身体上或感情上）。Il s'est blessé au genou = 他膝盖受伤了。Ses mots m'ont blessé = 他的话伤了我。blessé 作形容词或名词：受伤的 / 伤者。","ipa":"[blɛ.se]","ph":"bl [bl]；e 读 [ɛ]（因为后有 ss）；ss 读 [s]；-er [e]。","pi":"ss 读清音 [s]，不是 [z]；blessé 阳性，blessée 阴性读音相同。","et":"来源不确定（可能来自日耳曼语）。词族：blessure（伤口）、blessé。","ex":[["Ses mots m'ont beaucoup blessé.","他的话深深伤了我。"],["Il s'est blessé en jouant au foot.","他踢球时受伤了。"]],"co":[["se blesser à la main","手受伤"],["blesser quelqu'un","伤害某人"],["une blessure grave","重伤"],["être blessé dans son orgueil","自尊受伤"]],"sy":[["faire mal à","courant","弄疼"],["vexer","courant","冒犯、伤自尊"],["froisser","soutenu","使不快"]],"fq":"高频，日常常用。","me":"blesser = 伤 (blessure)：身体与感情都能伤。","tr":{"zh":"我踢球时膝盖受伤了。","fr":"Je me suis blessé au genou en jouant au foot.","alt":"Je me suis fait mal au genou en jouant au foot.","note":"se blesser 用 être 构成复合时；au genou 表示部位。"}},
 "Cesser": {"pos":"v. 动词，第一组（-er），助动词 avoir；过去分词 cessé","s":"停止；中止。cesser de + 不定式 = 不再……（cesser de pleuvoir 雨停了）；ne cesse de + 不定式 = 不停地。比 arrêter 书面。","ipa":"[sɛ.se]","ph":"ce [sɛ]（因后有 ss，e 读 [ɛ]）；ss 读 [s]；ser [se]。","pi":"接不定式用 cesser de，不是 cesser à；ss 读清音 [s]；注意 c 读 [s]。","et":"拉丁语 cessare（停下、懈怠）。同族：sans cesse（不停地）、incessant。","ex":[["La pluie a enfin cessé.","雨终于停了。"],["Il ne cesse de parler.","他说个不停。"]],"co":[["cesser de + 不定式","不再……"],["ne cesser de + 不定式","不停地……"],["sans cesse","不停地"],["cesser le travail","停工"]],"sy":[["arrêter","courant","停止，更口语常用"],["s'arrêter","courant","停下来（自己）"],["terminer","courant","结束"]],"fq":"中频，偏书面。","me":"cesser：想到 sans cesse，「没有停」的反面。","tr":{"zh":"雨终于停了。","fr":"La pluie a enfin cessé.","alt":"Il a enfin arrêté de pleuvoir.","note":"cesser de + 不定式；il pleut → il a cessé de pleuvoir。"}},
 "Devoir": {"pos":"v. 动词，不规则（第三组），助动词 avoir；je dois, tu dois, il doit, nous devons, ils doivent；过去分词 dû","s":"三种常用意思：必须、应该（Je dois partir）；大概、估计（Il doit être malade；Je dois faire environ 70 kilos）；欠（devoir de l'argent à qqn）。作名词 le devoir = 义务；les devoirs = 作业。","ipa":"[də.vwaʁ]","ph":"de 弱读 [də]；voir [vwaʁ]，oi = [wa]。je dois, il doit 读音相同 [dwa]。","pi":"je dois 和 il doit 读音一样，s、t 不发音；ils doivent 读 [dwav]，-ent 不发音。","et":"拉丁语 debere（欠、应该）。同族：dette（债务）。","ex":[["Je dois faire environ 70 kilos.","我大概有七十公斤。"],["Je dois partir à six heures.","我六点必须走。"],["Il me doit dix euros.","他欠我十欧元。"]],"co":[["devoir + 不定式","必须 / 应该……"],["devoir de l'argent à qqn","欠某人钱"],["faire ses devoirs","做作业"],["Il doit être là.","他应该已经到了。"]],"sy":[["falloir","courant","il faut，非人称的「必须」"],["avoir à","soutenu","有……要做"],["être obligé de","courant","不得不"]],"fq":"极高频，日常最常用的助动词之一。","me":"devoir = 欠 (dette)：欠下就得做。","tr":{"zh":"我必须在六点前回家。","fr":"Je dois rentrer avant six heures.","alt":"Il faut que je rentre avant six heures.","note":"devoir + 不定式；je dois 与 il faut que 同义。"}},
 "Encourager": {"pos":"v. 动词，第一组（-er），助动词 avoir；过去分词 encouragé；nous encourageons（保留 e）","s":"鼓励；促使；给……加油。encourager qqn à + 不定式 = 鼓励某人去做某事。encourager une équipe = 给球队加油。","ipa":"[ɑ̃.ku.ʁa.ʒe]","ph":"en 读 [ɑ̃]；cou [ku]；ra [ʁa]；ge 读 [ʒe]；-er [e]。","pi":"en- 是鼻化 [ɑ̃]，不是 [ɛn]；g 在 e 前读 [ʒ]；nous encourageons 要加 e 保持 [ʒ]。","et":"en- + courage（拉丁语 cor「心」）：给人「心」的力量。","ex":[["Je veux t'encourager à continuer.","我想鼓励你继续。"],["Les parents encouragent leur fille.","父母鼓励他们的女儿。"]],"co":[["encourager qqn à + 不定式","鼓励某人做……"],["encourager une équipe","给球队加油"],["un mot d'encouragement","鼓励的话"],["les encouragements","鼓励"]],"sy":[["motiver","courant","激励"],["soutenir","courant","支持"],["stimuler","soutenu","激发"]],"fq":"中频，日常常用。","me":"en + courage：给人注入勇气。","tr":{"zh":"老师鼓励我继续学法语。","fr":"Le professeur m'encourage à continuer le français.","alt":"Le prof m'encourage à continuer d'apprendre le français.","note":"encourager qqn à + 不定式。"}},
 "Enfermer": {"pos":"v. 动词，第一组（-er），助动词 avoir；过去分词 enfermé","s":"关起来；锁起来；囚禁。s'enfermer = 把自己关起来。Il est enfermé dans sa chambre = 他把自己关在房间里。","ipa":"[ɑ̃.fɛʁ.me]","ph":"en [ɑ̃]；fer 读 [fɛʁ]（词中的 er 读 [ɛʁ]）；mer [me]（词尾 -er 读 [e]）。","pi":"en 鼻化 [ɑ̃]；中间的 -er- 读 [ɛʁ]，只有词尾 -er 才读 [e]。","et":"en- + fermer（拉丁语 firmare「使牢固」）。同族：fermer, ferme。","ex":[["Il a oublié d'enfermer le chien.","他忘了把狗关起来。"],["Elle s'est enfermée dans sa chambre.","她把自己关在房间里。"]],"co":[["enfermer quelqu'un","把某人关起来"],["s'enfermer dans sa chambre","把自己关在房间里"],["enfermer à clé","锁起来"],["enfermé(e)","被关着的"]],"sy":[["emprisonner","courant","监禁"],["boucler","familier","关起来"],["séquestrer","soutenu","非法拘禁"]],"fq":"中频，日常常用。","me":"en + fermer：关在里面。","tr":{"zh":"别把猫关在房间里。","fr":"N'enferme pas le chat dans la chambre.","alt":"Ne laisse pas le chat enfermé dans la chambre.","note":"否定命令式；dans + 地点。"}},
 "Épauler": {"pos":"v. 动词，第一组（-er），助动词 avoir；过去分词 épaulé","s":"支持；帮助；扶持（字面义：把枪托靠在肩上，épaule 是「肩」）。épauler qqn = 帮某人一把。也指把枪架到肩上。","ipa":"[e.po.le]","ph":"é [e]；pau 读 [po]（au = [o]）；ler [le]。","pi":"au 读 [o]，不是 [au]；词尾 -er 读 [e]。","et":"来自 épaule（肩，拉丁语 spatula）+ -er：「用肩膀扶住」。","ex":[["Elle m'a épaulé pendant cette épreuve.","她在这次考验中支持了我。"],["Il épaule son frère dans son travail.","他在工作中扶持他弟弟。"]],"co":[["épauler qqn","支持某人"],["se faire épauler","得到别人的帮助"],["épauler un fusil","把枪架到肩上"],["une épaule","肩膀"]],"sy":[["soutenir","courant","支持"],["aider","courant","帮助"],["appuyer","courant","支持、靠着"]],"fq":"中低频，偏书面。","me":"épaule → épauler：用肩膀扛着你。","tr":{"zh":"我的朋友们在困难时期支持了我。","fr":"Mes amis m'ont épaulé dans les moments difficiles.","alt":"Mes amis m'ont soutenu quand ça n'allait pas.","note":"épauler 带直接宾语：m'ont épaulé（说话人是女性可写 épaulée）。"}},
 "Exagérer": {"pos":"v. 动词，第一组（-er），助动词 avoir；过去分词 exagéré；变位有重音变化：j'exagère","s":"夸大；夸张；做得过分。Tu exagères ! = 你太过分了 / 你夸张了。exagérer les choses = 把事情说得过头。","ipa":"[ɛɡ.za.ʒe.ʁe]","ph":"ex- 在元音前读 [ɛɡz]；a [a]；gé [ʒe]；rer [ʁe]。变位 j'exagère [ɛɡ.za.ʒɛʁ]。","pi":"ex- 读 [ɛɡz]，不是 [ɛks]；g 在 é 前读 [ʒ]；变位时 é 变 è：j'exagère [ɛɡ.za.ʒɛʁ]。","et":"拉丁语 exaggerare（堆高，夸大），来自 ex- + agger（土堆）。","ex":[["Tu as tendance à exagérer les choses.","你总爱夸大其词。"],["Tu exagères, ce n'est pas si grave !","你太夸张了，没那么严重！"]],"co":[["exagérer les choses","夸大事情"],["Tu exagères !","你太过分了！"],["sans exagérer","毫不夸张地说"],["avoir tendance à exagérer","爱夸张"]],"sy":[["en rajouter","familier","添油加醋"],["grossir","courant","夸大"],["abuser","courant","过分"]],"fq":"高频，日常常用。","me":"ex + agger（堆高）：把事情越堆越高。","tr":{"zh":"你夸张了，事情没那么严重。","fr":"Tu exagères, ce n'est pas si grave.","alt":"Tu en fais trop, ce n'est pas si grave.","note":"pas si + 形容词 = 没那么……。"}},
 "Féliciter": {"pos":"v.t. 及物动词，-er 规则动词，助动词 avoir","s":"祝贺，表示恭喜。结构：féliciter qqn de / pour qqch（为某事祝贺某人）。复数名词 félicitations ! = 「恭喜！」。","ipa":"[fe.li.si.te]","ph":"é [e]；i [i]；c 在 i 前读 [s]；结尾 -er 读 [e]，r 不发音。","pi":"c 读 [s] 不是 [k]；结尾 -er 的 r 不发音；说「恭喜」要用名词复数 félicitations !，不是 félicitation。","et":"来自拉丁语 felicitare（使幸福），源于 felix（幸运的，幸福的）。同源：félicité、félicitations。","ex":[["Je tiens à vous féliciter pour votre travail.","我要祝贺您的工作。"],["Je te félicite d'avoir réussi ton examen.","祝贺你通过了考试。"],["Tout le monde l'a félicité.","大家都向他道贺。"]],"co":[["féliciter qqn de / pour qqch","为某事祝贺某人"],["féliciter chaleureusement","热烈祝贺"],["Je vous félicite !","恭喜您！"],["se féliciter de qqch","为某事感到庆幸"]],"sy":[["complimenter","courant","称赞，夸奖（偏重夸），语气比 féliciter 轻"],["applaudir","courant","鼓掌；赞许"],["critiquer","courant","批评（反义）"]],"fq":"中高频，日常和工作场合常用。","me":"féliciter ← felix（幸福）：让对方「感到幸福」，就是恭喜。","tr":{"zh":"我们要祝贺她升职。","fr":"Nous voulons la féliciter pour sa promotion.","alt":"On veut la féliciter pour sa promotion.","note":"féliciter qqn pour qqch，宾语直接接人，不加 à。"}},
 "Former": {"pos":"v.t. 及物动词，-er 规则动词，助动词 avoir","s":"培训，培养（人）；组成，形成（事物）。former des étudiants = 培养学生；former un groupe = 组成一个小组；former un cercle = 围成一个圈。pronominal：se former = 接受培训，形成。","ipa":"[fɔʁ.me]","ph":"o 在 -or- 前读开口的 [ɔ]；r 是小舌音 [ʁ]；结尾 -er 读 [e]。","pi":"former 的 o 读 [ɔ]，不是 [o]；别和 informer（通知）混淆：former 没有 in-。","et":"来自拉丁语 formare，源于 forma（形状）。同源：forme、formation、formateur、informer、réformer。","ex":[["Ce professeur va former les nouveaux élèves.","这位老师将培训新学生。"],["Ils ont formé un groupe de musique.","他们组了一个乐队。"],["Elle se forme au métier d'infirmière.","她正在接受护士职业培训。"]],"co":[["former des jeunes / des employés","培训年轻人 / 员工"],["former un groupe / une équipe","组建小组 / 团队"],["se former à un métier","学习一门职业"],["la formation professionnelle","职业培训"]],"sy":[["entraîner","courant","训练（偏体能、技能练习）"],["éduquer","courant","教育（偏品德、成长）"],["créer","courant","创造；成立"]],"fq":"高频，日常和工作中常用。","me":"former = 给人一个「形」(forme)，把新人塑造成材。","tr":{"zh":"公司培训新员工。","fr":"L'entreprise forme les nouveaux employés.","alt":"La boîte forme ses nouveaux employés.","note":"former qqn：人直接作宾语；培训课程叫 une formation。"}},
 "Fuir": {"pos":"v.t./v.i. 不规则动词（第三组），助动词 avoir，过去分词 fui","s":"逃跑，逃离；躲避。可以不带宾语（Il a fui.），也可以带宾语（fuir son pays 逃离祖国，fuir la ville 躲开城市）。也指液体泄漏：Le robinet fuit = 水龙头漏水。","ipa":"[fɥiʁ]","ph":"u 读 [ɥ]（嘴唇收圆的半元音，接着是 i）；结尾 r 读 [ʁ]。","pi":"fuir 只有一个音节 [fɥiʁ]，不是 [fu.iʁ]；变位不规则：je fuis, nous fuyons, ils fuient；名词是 la fuite。","et":"来自拉丁语 fugere（逃跑）。同源：fuite（逃跑；泄漏）、fugitif（逃犯）、s'enfuir（逃走）。","ex":[["Il a dû fuir son pays.","他不得不逃离自己的国家。"],["Les habitants fuient la guerre.","居民们在逃避战争。"],["Le tuyau fuit depuis hier.","水管从昨天起就在漏水。"]],"co":[["fuir son pays / la guerre","逃离祖国 / 躲避战争"],["fuir devant le danger","面对危险逃跑"],["fuir ses responsabilités","逃避责任"],["s'enfuir","逃走，溜走"]],"sy":[["s'enfuir","courant","逃走（强调「离开」这个动作）"],["s'échapper","courant","逃脱，逃出"],["éviter","courant","避免，躲开"]],"fq":"中高频，新闻和日常都用。","me":"fuir [fɥiʁ]：像 fuite，一溜烟「fu！」跑掉。","tr":{"zh":"他们为了逃避战争而离开了。","fr":"Ils sont partis pour fuir la guerre.","alt":"Ils ont quitté le pays pour échapper à la guerre.","note":"fuir 直接带宾语，不加介词。"}},
 "Garder": {"pos":"v.t. 及物动词，-er 规则动词，助动词 avoir","s":"保留，留着；保管，看管；照看（孩子）；保持。garder un secret = 保守秘密；garder les enfants = 看孩子；garder le silence = 保持沉默；garder la forme = 保持健康状态。pronominal：se garder de + inf = 小心别做。","ipa":"[ɡaʁ.de]","ph":"g 在 a 前读 [ɡ]；r 读小舌音 [ʁ]；结尾 -er 读 [e]。","pi":"g 在 a 前读硬音 [ɡ]；别把 garder（保留）和 regarder（看）混淆；r 后面还要接 d，要读清 [ɡaʁ.de]。","et":"来自法兰克语（日耳曼语）*wardōn（看守），和英语 ward、guard 同源。同源：garde、gardien（看守人）、regarder。","ex":[["Je vais garder ce secret pour moi.","我会保守这个秘密。"],["Tu peux garder la monnaie.","零钱你留着吧。"],["Ma voisine garde mon chat pendant les vacances.","假期里我的邻居帮我照看猫。"]],"co":[["garder un secret","保守秘密"],["garder les enfants","照看孩子"],["garder le contact","保持联系"],["garder la forme","保持好状态"]],"sy":[["conserver","soutenu","保存（偏书面，如保存食物、文件）"],["retenir","courant","留住；记住"],["jeter","courant","扔掉（反义）"]],"fq":"极高频，日常常用。","me":"garder ≈ guard：「守住」不让它走。","tr":{"zh":"请把这张票留好。","fr":"Gardez bien ce billet, s'il vous plaît.","alt":"Vous pouvez garder ce billet ?","note":"命令式 gardez 对 vous；对 tu 用 garde。"}},
 "Immigrer": {"pos":"v.i. 不及物动词，-er 规则动词，助动词 avoir（也可 être，较少见）","s":"移民，迁入（来到一个国家定居）。立场是「迁入地」：immigrer en France / au Canada。反义词 émigrer = 迁出（离开祖国）。名词：un immigré / une immigrée（移民者），l'immigration（移民潮）。","ipa":"[i.mi.ɡʁe]","ph":"两个 i 都读 [i]；mm 只读一个 [m]；g 在 r 前读 [ɡ]，不是 [ʒ]；结尾 -er 读 [e]。","pi":"g 读 [ɡ] 而不是 [ʒ]；immigrer（迁入）和 émigrer（迁出）只差一个开头字母，容易搞混：im- = 进入，é- = 出去。","et":"来自拉丁语 immigrare，由 in-（进入）+ migrare（迁移）构成。同源：migration、migrant、émigrer。","ex":[["Ses parents ont immigré en France.","他的父母移民到了法国。"],["Beaucoup de gens immigrent pour trouver du travail.","很多人为了找工作而移民。"],["Elle a immigré au Canada en 2010.","她2010年移民到加拿大。"]],"co":[["immigrer en France / au Canada","移民到法国 / 加拿大"],["un immigré","（外来）移民者"],["l'immigration","移民（现象），入境"],["immigrer illégalement","非法移民"]],"sy":[["émigrer","courant","迁出（站在原国家的角度，反义）"],["s'installer","courant","定居"],["migrer","courant","迁徙（鸟类、人群）"]],"fq":"中频，新闻、社会话题常见。","me":"im- = 进入（像 import）；é- = 出去（像 exit）。","tr":{"zh":"我叔叔十年前移民到了加拿大。","fr":"Mon oncle a immigré au Canada il y a dix ans.","alt":"Mon oncle est parti vivre au Canada il y a dix ans.","note":"国家名前：阴性国家用 en，阳性国家用 au。"}},
 "Imposer": {"pos":"v.t. 及物动词，-er 规则动词，助动词 avoir","s":"强加；规定；强制推行。imposer qqch à qqn = 把某事强加给某人。也指征税（imposer un produit）。pronominal：s'imposer = 脱颖而出，成为必须。en imposer = 令人敬畏。","ipa":"[ɛ̃.po.ze]","ph":"im- 读鼻化元音 [ɛ̃]，m 不单独发音；s 在两个元音之间读 [z]；结尾 -er 读 [e]。","pi":"im- 是鼻化音 [ɛ̃]，不要读成 [im]；s 读 [z]，不是 [s]。","et":"来自拉丁语 imponere（放在上面，强加），和 poser（放）同源。同源：imposition、impôt（税）、exposer、proposer。","ex":[["Le gouvernement veut imposer de nouvelles règles.","政府想强制推行新规定。"],["Il m'a imposé ses idées.","他把自己的想法强加给我。"],["Cette actrice s'impose dans le cinéma français.","这位女演员在法国电影界站稳了脚跟。"]],"co":[["imposer une règle / une amende","强制实行规定 / 处以罚款"],["imposer son avis à qqn","把自己的意见强加给某人"],["s'imposer","脱颖而出；势在必行"],["imposer le silence","要求保持安静"]],"sy":[["obliger","courant","迫使（obliger qqn à faire）"],["exiger","courant","要求，强烈要求"],["suggérer","courant","建议（语气温和，对比）"]],"fq":"中高频，新闻和书面中常见。","me":"im- + poser：把东西「压在」别人身上。","tr":{"zh":"老板不能把这个决定强加给我们。","fr":"Le patron ne peut pas nous imposer cette décision.","alt":"Le patron ne peut pas nous forcer à accepter ça.","note":"imposer qqch à qqn：人前面用 à（代词用 nous、lui 等）。"}},
 "Imprimer": {"pos":"v.t. 及物动词，-er 规则动词，助动词 avoir","s":"打印；印刷。imprimer un document = 打印文件；un livre imprimé = 印刷的书。也指留下印记（imprimer sa marque）。名词：une imprimante（打印机），l'impression（印刷；印象）。","ipa":"[ɛ̃.pʁi.me]","ph":"im- 读鼻化元音 [ɛ̃]；pr 读 [pʁ]；i [i]；结尾 -er 读 [e]。","pi":"开头 im- 是鼻化音 [ɛ̃]，m 不单独读；中间的 m 才读 [m]；别和 immigrer（imm-）的拼写混淆，这里是 imp-。","et":"来自拉丁语 imprimere（压上，按上去），由 in- + premere（压）构成。同源：presse、pression、exprimer。","ex":[["Peux-tu imprimer ce document ?","你能打印这份文件吗？"],["Je dois imprimer mon billet de train.","我得打印我的火车票。"],["Ce journal est imprimé à Lyon.","这份报纸在里昂印刷。"]],"co":[["imprimer un document / une photo","打印文件 / 照片"],["une imprimante","打印机"],["un texte imprimé","印刷文本"],["imprimer en couleur","彩色打印"]],"sy":[["tirer","courant","冲印；印出（tirer une photo）"],["éditer","soutenu","出版（编辑出版，和印刷不同）"]],"fq":"中高频，办公、学校常用。","me":"im-primer：用力「压」(press) 出字迹，所以是印刷。","tr":{"zh":"请把这些表格打印出来。","fr":"Imprimez ces formulaires, s'il vous plaît.","alt":"Tu peux m'imprimer ces formulaires ?","note":"imprimer 的过去分词是 imprimé。"}},
 "Influencer": {"pos":"v.t. 及物动词，-er 规则动词，助动词 avoir（c → ç：nous influençons）","s":"影响（人、决定、看法）。influencer qqn / qqch：对某人或某事产生影响。名词：l'influence（影响），un(e) influenceur / influenceuse（网红，网络博主）。","ipa":"[ɛ̃.fly.ɑ̃.se]","ph":"in- 读鼻化元音 [ɛ̃]；u 读 [y]；-en- 读 [ɑ̃]；c 在 e 前读 [s]。","pi":"u 读 [y]（嘴唇收圆发 i），不是 [u]；-en- 读 [ɑ̃]；nous 变位要写 ç：nous influençons。","et":"来自 influence，源自拉丁语 influentia（流入），由 influere（in- + fluere 流动）而来。同源：fluide、affluent。","ex":[["Ce livre m'a beaucoup influencé.","这本书对我影响很大。"],["Les réseaux sociaux influencent les jeunes.","社交网络影响着年轻人。"],["Je ne veux pas t'influencer.","我不想影响你的选择。"]],"co":[["influencer une décision","影响一个决定"],["se laisser influencer","容易受影响"],["avoir de l'influence sur qqn","对某人有影响力"],["un influenceur","网络红人"]],"sy":[["agir sur","courant","对……起作用"],["marquer","courant","给……留下深刻印象"],["manipuler","courant","操纵（含贬义）"]],"fq":"中高频，新闻、网络上常用。","me":"influencer ← in + fluer：把想法「流进」对方心里。","tr":{"zh":"朋友们影响了我的选择。","fr":"Mes amis ont influencé mon choix.","alt":"Mes amis m'ont influencé dans mon choix.","note":"influencer 直接带宾语，不加 sur。"}},
 "Interpréter": {"pos":"v.t. 及物动词，-er 规则动词（变位 é 变 è：j'interprète），助动词 avoir","s":"表演，饰演（角色）；演奏、演唱；解释，理解（含义）；口译。interpréter un rôle = 饰演角色；interpréter une chanson = 演唱歌曲；mal interpréter = 误解。名词：un interprète = 口译员。","ipa":"[ɛ̃.tɛʁ.pʁe.te]","ph":"in- 读 [ɛ̃]；ter 读 [tɛʁ]；pré 读 [pʁe]；最后 -ter 读 [te]。","pi":"有两个 é/è：第二个 é 在 tr 之后读 [e]，变位时变 è：j'interprète, nous interprétons；别忘了 -pr-。","et":"来自拉丁语 interpretari（解释，翻译），源于 interpres（中间人，译员）。同源：interprétation、interprète。","ex":[["Elle va interpréter le rôle principal.","她将饰演主角。"],["Il interprète cette chanson avec beaucoup d'émotion.","他饱含感情地演唱这首歌。"],["Tu as mal interprété ma phrase.","你误解了我的话。"]],"co":[["interpréter un rôle","饰演一个角色"],["interpréter un morceau","演奏一首曲子"],["mal interpréter qqch","误解某事"],["un interprète","译员；表演者"]],"sy":[["jouer","courant","扮演，演出（更日常）"],["expliquer","courant","解释"],["traduire","courant","翻译（对比：interpréter 偏口译、诠释）"]],"fq":"中频，文艺和书面中较常见。","me":"interpréter：站在「中间」(inter) 的人，把意思传出去、演出来。","tr":{"zh":"这位歌手演唱了一首老歌。","fr":"Le chanteur a interprété une vieille chanson.","alt":"Le chanteur a chanté une vieille chanson.","note":"过去分词 interprété，不要写成 interpreté。"}},
 "Jouer de / Jouer à / Jouer dans / ...": {"pos":"v.i./v.t. 规则动词（-er），助动词 avoir；介词搭配随对象变化","s":"玩；演奏；出演；比赛。核心搭配：jouer à + 游戏 / 运动（jouer au foot）；jouer de + 乐器（jouer de la guitare）；jouer dans + 电影 / 戏剧（jouer dans un film）；jouer un rôle = 饰演；jouer avec = 玩弄、摆弄。","ipa":"[ʒwe]","ph":"j [ʒ]；ou 在元音前读半元音 [w]；结尾 -er 读 [e]。","pi":"最大陷阱是介词：运动用 à（jouer au tennis），乐器用 de（jouer du piano），不能混；jouer au piano 是错的。ou + e 要连成 [wa]/[we]，不要拆成两个音节。","et":"来自拉丁语 iocari（开玩笑，玩耍），源于 iocus（玩笑，游戏）。同源：jeu（游戏）、joueur（玩家）、jouet（玩具）。","ex":[["Elle aime jouer de la guitare.","她喜欢弹吉他。"],["Les enfants jouent au foot dans le jardin.","孩子们在花园里踢足球。"],["Il a joué dans plusieurs films.","他演过好几部电影。"]],"co":[["jouer à + jeu / sport (jouer aux cartes)","玩游戏 / 运动（打牌）"],["jouer de + instrument (jouer du violon)","演奏乐器（拉小提琴）"],["jouer dans un film / une pièce","出演电影 / 话剧"],["jouer un rôle","饰演角色；起作用"]],"sy":[["s'amuser","courant","玩乐，开心（不带宾语）"],["interpréter","soutenu","饰演，演奏（更书面）"],["se divertir","soutenu","消遣，娱乐"]],"fq":"极高频，日常常用。","me":"运动 / 游戏 = à；乐器 = de：「à le ballon，de la musique」。","tr":{"zh":"我儿子在学拉小提琴，也喜欢踢球。","fr":"Mon fils apprend à jouer du violon et aime jouer au foot.","alt":"Mon fils fait du violon et joue au foot.","note":"jouer du + 乐器；jouer au + 运动（à + le = au）。"}},
 "Loger": {"pos":"v.t./v.i. 规则动词（-er；g → ge：nous logeons），助动词 avoir","s":"提供住宿，让……住下（及物）；住，借宿（不及物）。loger qqn = 让某人住；Je loge chez un ami = 我住在朋友家。名词：un logement（住房），se loger = 找房子住。","ipa":"[lɔ.ʒe]","ph":"o 读开口 [ɔ]；g 在 e 前读 [ʒ]；结尾 -er 读 [e]。","pi":"nous 变位要加 e：nous logeons，保持 [ʒ] 音；别把 loger（住宿）和 louer（租）搞混。","et":"来自 loge，源于法兰克语 *laubja（凉亭，遮蔽处）。同源：logement、logis、déloger。","ex":[["Je peux te loger ce soir.","今晚我可以让你住下。"],["Ils logent chez des amis.","他们住在朋友家。"],["L'hôtel peut loger cent personnes.","这家酒店能容纳一百人。"]],"co":[["loger qqn chez soi","让某人住在自己家"],["loger à l'hôtel","住酒店"],["être logé et nourri","管吃管住"],["se loger","找到住处"]],"sy":[["héberger","courant","收留，提供住处（更常用于朋友、难民）"],["habiter","courant","居住（长期）"],["accueillir","courant","接待，迎接"]],"fq":"中频，旅行和租房时常用。","me":"loger 和 logement 同族：给人一个「窝」(loge)。","tr":{"zh":"我的朋友来巴黎时，我可以让他住在我家。","fr":"Quand mon ami vient à Paris, je peux le loger chez moi.","alt":"Quand mon ami vient à Paris, il peut dormir chez moi.","note":"loger qqn：人直接作宾语；chez moi = 在我家。"}},
 "Materner": {"pos":"v.t. 及物动词，-er 规则动词，助动词 avoir","s":"像母亲一样照顾；过分呵护，溺爱（常含一点贬义）。materner qqn = 对某人关怀备至，把对方当小孩。常带「管太多」的意味。较书面或口语化的少见词。","ipa":"[ma.tɛʁ.ne]","ph":"a [a]；ter 读 [tɛʁ]；结尾 -er 读 [e]，r 不发音。","pi":"词中的 er 读 [ɛʁ]，只有结尾的 -er 读 [e]；别和 maternel（母亲的，形容词）混用。","et":"来自 maternel，源自拉丁语 maternus，由 mater（母亲）而来；同源：maternité、maternel、mère。","ex":[["Elle a tendance à materner ses amis.","她习惯像母亲一样照顾朋友。"],["Arrête de me materner, je suis adulte !","别再把我当小孩照顾了，我已经是成年人了！"],["Il se laisse materner par sa sœur.","他任由姐姐把他当孩子一样照顾。"]],"co":[["materner qqn","像妈妈一样照顾某人"],["avoir tendance à materner","习惯于过度呵护"],["se laisser materner","任人照顾、宠着"],["un instinct maternel","母性本能"]],"sy":[["dorloter","courant","细心呵护，宠爱"],["chouchouter","familier","宠着，偏爱"],["couver","courant","过度保护（像母鸡孵蛋）"]],"fq":"低频，口语和文章里偶尔出现。","me":"materner ← mater / mère：「当妈」的动词。","tr":{"zh":"她总想把同事当孩子一样照顾。","fr":"Elle veut toujours materner ses collègues.","alt":"Elle a toujours envie de materner ses collègues.","note":"materner 带有轻微的批评意味。"}},
 "Monter (un projet)": {"pos":"v.t. 及物动词（本义的 monter 作不及物时用 être），-er 规则动词","s":"筹划，组织，办起来（项目、公司、活动、戏剧）。monter un projet / une entreprise / une pièce = 筹办项目 / 创办公司 / 排演话剧。本义：monter = 上楼，上升，爬上；monter qqch = 把东西搬上去，组装。","ipa":"[mɔ̃.te]","ph":"on 读鼻化元音 [ɔ̃]，n 不单独读；t [t]；结尾 -er 读 [e]。","pi":"on 是鼻化音 [ɔ̃]，不要读成 [mon]；monter 作「上去」时用 être（je suis monté），带宾语时用 avoir（j'ai monté les valises）。","et":"来自通俗拉丁语 *montare，源于拉丁语 mons, montis（山）。同源：montagne、monter、montée、amont。","ex":[["Ils veulent monter un projet ensemble.","他们想一起筹办一个项目。"],["Elle a monté sa propre entreprise.","她创办了自己的公司。"],["Ils montent une pièce de théâtre au lycée.","他们在高中排演一出话剧。"]],"co":[["monter un projet / une entreprise","筹办项目 / 创办公司"],["monter une pièce de théâtre","排演话剧"],["monter un meuble","组装家具"],["monter les escaliers","上楼梯"]],"sy":[["créer","courant","创建，创造"],["organiser","courant","组织，安排"],["lancer","courant","发起，推出"]],"fq":"极高频（本义），做「筹办」用法为中频。","me":"monter = 往「山」(mont) 上走；筹办项目 = 把事情「搭起来」。","tr":{"zh":"我想和朋友们一起办一个小公司。","fr":"Je veux monter une petite entreprise avec mes amis.","alt":"J'aimerais monter ma boîte avec des amis.","note":"monter une entreprise = 创业；une boîte 是口语的「公司」。"}},
 "Paterner": {"pos":"v.t. 及物动词，-er 规则动词，助动词 avoir（少见词）","s":"像父亲一样照顾、庇护（对别人表现出父亲式的关怀，有时有点居高临下）。常见搭配：paterner qqn。是 materner 的对应词，使用很少，多见于口语或玩笑。","ipa":"[pa.tɛʁ.ne]","ph":"a [a]；ter 读 [tɛʁ]；结尾 -er 读 [e]。","pi":"这是少见的词，考试和日常中更常用 materner / protéger；别和 paternel（父亲的）混淆，paterner 是动词。","et":"来自 paternel，源自拉丁语 paternus，由 pater（父亲）而来；同源：paternité、patron、père。作为动词是少见的仿造词（与 materner 对应）。","ex":[["Il aime paterner les nouveaux employés.","他喜欢像父亲一样照顾新员工。"],["Le directeur paterne toute l'équipe.","主任像父亲一样照顾整个团队。"],["Ne me paterne pas, j'ai trente ans !","别把我当孩子，我都三十岁了！"]],"co":[["paterner qqn","像父亲一样照顾某人"],["un geste paternel","父亲般的举动"],["un ton paternaliste","家长式的口气"],["le paternalisme","家长式作风"]],"sy":[["protéger","courant","保护"],["materner","courant","像母亲一样照顾（对应词）"],["chaperonner","courant","陪同照看"]],"fq":"低频，少见词。","me":"pater（父）→ paterner；mater（母）→ materner。","tr":{"zh":"他像父亲一样照顾年轻的同事。","fr":"Il paterne ses jeunes collègues.","alt":"Il joue le rôle de père avec ses jeunes collègues.","note":"paterner 少见；更自然的说法是 jouer le père。"}},
 "Poser (pour une photo, un dessin)": {"pos":"v.i./v.t. 规则动词（-er），助动词 avoir","s":"摆姿势，当模特（poser pour une photo / un peintre）。基本义：poser qqch = 放下，放置；poser une question = 提问；se poser = 停落，降落。也指装修（poser du carrelage）。","ipa":"[po.ze]","ph":"o [o]；s 在两个元音之间读 [z]；结尾 -er 读 [e]。","pi":"s 读 [z] 不是 [s]；别把 poser une question（提问）和 demander（请求）混淆；pose 一词与英语 pose 近似但变位不同。","et":"来自拉丁语 pausare（停下），因与 ponere（放）混淆而得到「放置」义。同源：pause、position、déposer、proposer。","ex":[["Elle a posé pour un célèbre peintre.","她为一位著名画家做过模特。"],["Pose ton sac sur la table.","把你的包放在桌子上。"],["Je peux te poser une question ?","我可以问你一个问题吗？"]],"co":[["poser pour un peintre / pour une photo","给画家 / 照片当模特"],["poser une question","提出一个问题"],["poser son sac / son manteau","放下包 / 外套"],["se poser (un oiseau, un avion)","降落，停落"]],"sy":[["mettre","courant","放，放置（更常用）"],["placer","courant","安放，摆放"],["déposer","soutenu","放下；提交"]],"fq":"极高频，日常常用。","me":"poser ≈ pose：站定不动，等着被拍。","tr":{"zh":"孩子们站在海边摆姿势拍照。","fr":"Les enfants posent pour une photo au bord de la mer.","alt":"Les enfants prennent la pose près de la mer.","note":"poser pour qqch / qqn：摆姿势给……拍或画。"}},
 "Pouffer (de rire)": {"pos":"v.i. 不及物动词，-er 规则动词，助动词 avoir","s":"忍不住笑出声，扑哧一笑（常是憋不住地笑出来）。几乎总说 pouffer de rire；也可以单独用 pouffer。比 rire 更突然、更压抑。","ipa":"[pu.fe]","ph":"ou [u]；ff 只读一个 [f]；结尾 -er 读 [e]。","pi":"ou 读 [u]；ff 是双写字母，只读一个 [f]；别写成 poufer。","et":"拟声词（模仿憋不住的笑声「pouf」）。同源：pouf（扑通声）。","ex":[["Elle n'a pas pu s'empêcher de pouffer de rire.","她忍不住扑哧笑了出来。"],["Les élèves ont pouffé quand le professeur a trébuché.","老师绊了一下，学生们忍不住笑出声。"],["Il pouffe dès qu'il me regarde.","他一看我就忍不住笑。"]],"co":[["pouffer de rire","扑哧一笑"],["pouffer dans sa main","捂着嘴偷笑"],["ne pas pouvoir s'empêcher de pouffer","忍不住笑出来"],["un fou rire","止不住的大笑"]],"sy":[["éclater de rire","courant","放声大笑"],["ricaner","courant","窃笑，冷笑"],["glousser","courant","咯咯笑"]],"fq":"低频，故事和口语里常见。","me":"pouffer：听起来像憋不住时发出的「噗」声。","tr":{"zh":"他一听这个笑话就忍不住笑出声。","fr":"Il a pouffé de rire en entendant cette blague.","alt":"Il n'a pas pu s'empêcher de rire à cette blague.","note":"pouffer de rire：固定搭配，de 后面是名词 rire。"}},
 "Rayer": {"pos":"v.t. 及物动词，-er 规则动词（je raie / raye），助动词 avoir","s":"划伤，刮花（表面）；划掉，勾掉（文字、名字）。rayer une voiture = 刮花车；rayer un mot = 划掉一个词；rayer qqn d'une liste = 把某人从名单上除名。名词：une rayure（划痕；条纹）。","ipa":"[ʁɛ.je]","ph":"r 小舌音 [ʁ]；ay 读 [ɛj]，所以整词 [ʁɛ.je]（也可读 [ʁe.je]）；结尾 -er 读 [e]。","pi":"ay 读 [ɛj]（不是 [aj]）；变位可写 je raie 或 je raye，现代以 raie 较常见；注意区别 rayure（划痕）和 rayon（光线；货架）。","et":"来自 raie（线，条纹），原义是「划上线条」。同源：rayure、rayé（有条纹的）。更早的来源不确定。","ex":[["Fais attention à ne pas rayer la voiture.","小心别刮到车。"],["Il a rayé son nom de la liste.","他把自己的名字从名单上划掉了。"],["Ce CD est rayé, il ne marche plus.","这张光盘被刮花了，放不了了。"]],"co":[["rayer une voiture / un disque","刮花车 / 唱片"],["rayer un mot / un nom","划掉一个词 / 名字"],["rayer de la liste","从名单上除名"],["une rayure","划痕；条纹"]],"sy":[["griffer","courant","抓伤，划伤"],["effacer","courant","擦掉，删除"],["barrer","courant","划掉（用线）"]],"fq":"中频，日常偶尔用到。","me":"rayer ← raie（线）：在表面划出一条「线」。","tr":{"zh":"别用钥匙划桌子，会划伤的。","fr":"Ne raye pas la table avec tes clés.","alt":"Ne raye pas la table avec tes clés, tu vas l'abîmer.","note":"否定命令式：ne + 动词 + pas。"}},
 "Rechigner à...": {"pos":"v.i. 不及物动词，-er 规则动词，助动词 avoir；常与 à + 不定式 / 名词连用","s":"不情愿（做某事），勉强，面露难色。rechigner à faire qqch = 不愿意做；也可以单用 sans rechigner = 毫无怨言地。带有「皱眉、嘟囔」的感觉。","ipa":"[ʁə.ʃi.ɲe]","ph":"re [ʁə]；ch 读 [ʃ]；gn 读 [ɲ]（像「尼」的鼻音）；结尾 -er 读 [e]。","pi":"gn 读 [ɲ]，不是 [ɡn]；ch 读 [ʃ]；后面接 à：rechigner à faire，不是 de 或 pour。","et":"来自古法语 rechignier，由 re- 加上一个表示「皱眉」的词构成；更早的来源不确定。","ex":[["Il rechigne à faire ses devoirs.","他不愿意做作业。"],["Elle a accepté sans rechigner.","她毫无怨言地答应了。"],["Les enfants rechignent à se lever le matin.","孩子们早上不愿起床。"]],"co":[["rechigner à faire qqch","不情愿做某事"],["sans rechigner","毫无怨言地"],["rechigner à la tâche","不愿干活"],["rechigner devant l'effort","遇到费力的事就不乐意"]],"sy":[["renâcler","soutenu","不情愿，勉强（更书面）"],["hésiter","courant","犹豫"],["accepter volontiers","courant","乐意接受（反义）"]],"fq":"中低频，口语和书面都有。","me":"rechigner：皱着眉头 (chi-gn-er) 不想干。","tr":{"zh":"我儿子总不愿意收拾房间。","fr":"Mon fils rechigne toujours à ranger sa chambre.","alt":"Mon fils n'a jamais envie de ranger sa chambre.","note":"rechigner à + 不定式。"}},
 "Réciter": {"pos":"v.t. 及物动词，-er 规则动词（é → è：je récite），助动词 avoir","s":"背诵，朗诵（背熟的内容）。réciter un poème / une leçon / une prière = 背诗 / 课文 / 祷词。强调「凭记忆说出」，不同于 lire（读）。名词：une récitation（背诵课文）。","ipa":"[ʁe.si.te]","ph":"é [e]；c 在 i 前读 [s]；结尾 -er 读 [e]。","pi":"c 读 [s]；注意只有 réciter 的开头有 é，第二个 e 在 -er 里不发音；别把 réciter（背诵）和 raconter（讲述）混淆。","et":"来自拉丁语 recitare（大声朗读），由 re- + citare（召唤，引用）构成。同源：citer（引用）、citation、réciter。","ex":[["L'enfant doit réciter un poème.","孩子得背一首诗。"],["Je ne peux pas réciter ma leçon sans erreur.","我背不出没有错误的课文。"],["Il a récité la fable devant la classe.","他在全班面前背了那则寓言。"]],"co":[["réciter un poème / une leçon","背诗 / 背课文"],["réciter par cœur","背下来"],["réciter une prière","念祷词"],["réciter sa leçon","背课文；说套话"]],"sy":[["déclamer","littéraire","朗诵（带表情，书面）"],["répéter","courant","重复"],["apprendre par cœur","courant","背熟（学习阶段）"]],"fq":"中频，学校和文化场合常用。","me":"réciter ≈ recite：把 cité（引用的话）再说一遍。","tr":{"zh":"老师让我们背一首诗。","fr":"Le professeur nous demande de réciter un poème.","alt":"La prof nous fait réciter un poème.","note":"demander à qqn de + 不定式。"}},
 "Reconnaître": {"pos":"v.t. 及物动词，不规则动词（第三组），助动词 avoir，过去分词 reconnu","s":"认出，辨认出；承认。reconnaître qqn = 认出某人；reconnaître son erreur = 承认错误。pronominal：se reconnaître = 认出自己；se reconnaître coupable = 承认有罪。","ipa":"[ʁə.kɔ.nɛtʁ]","ph":"re [ʁə]；c 在 o 前读 [k]；-aî- 读 [ɛ]；结尾 -tre 读 [tʁ]，e 不发音。","pi":"il reconnaît 的 î 只出现在 t 前；nous reconnaissons 没有 î，要加 ss；c 读 [k]；过去分词是 reconnu。","et":"来自拉丁语 recognoscere，由 re- + cognoscere（认识）构成。同源：connaître、connaissance、reconnaissance（认出；感谢）。","ex":[["J'ai eu du mal à le reconnaître.","我很难认出他。"],["Il a reconnu son erreur.","他承认了自己的错误。"],["Tu me reconnais ?","你认得我吗？"]],"co":[["reconnaître qqn à sa voix / à son visage","凭声音 / 脸认出某人"],["reconnaître une erreur","承认错误"],["reconnaître que + 句子","承认……"],["la reconnaissance","感谢；认可"]],"sy":[["identifier","courant","辨认，识别"],["avouer","courant","坦白，招认"],["admettre","courant","承认；接受"]],"fq":"高频，日常和书面都常用。","me":"re-connaître：「再次认识」= 认出来。","tr":{"zh":"二十年后我还是能认出她。","fr":"Vingt ans après, je la reconnais encore.","alt":"Même vingt ans après, je la reconnaîtrais.","note":"reconnaître 的代词作直接宾语，放在动词前。"}},
 "Relire": {"pos":"v.t. 及物动词，不规则动词（第三组，同 lire），助动词 avoir，过去分词 relu","s":"重读，再读一遍；校对，检查（写完的东西）。relire un texte = 重读 / 检查文章；relire avant d'envoyer = 发之前再看一遍。pronominal：se relire = 重读自己写的东西。","ipa":"[ʁə.liʁ]","ph":"re [ʁə]；i [i]；结尾 r 读 [ʁ]。","pi":"r 在词尾要发音：[ʁə.liʁ]；变位像 lire：vous relisez，ils relisent（s 读 [z]）；过去分词是 relu，不要写成 relit。","et":"由 re-（再）+ lire 构成；lire 来自拉丁语 legere（读）。同源：lecture、lecteur、relecture。","ex":[["Je dois relire mon texte.","我得重读我的文章。"],["Relis ton message avant de l'envoyer.","发之前先把你的消息再读一遍。"],["J'aime relire mes livres préférés.","我喜欢重读我最爱的书。"]],"co":[["relire un texte / un message","重读文章 / 消息"],["relire avant d'envoyer","发送前检查"],["une relecture","校对；重读"],["se relire","重读自己写的东西"]],"sy":[["corriger","courant","改正，批改"],["vérifier","courant","检查，核对"],["revoir","courant","复习；再看"]],"fq":"中频，工作和学习中常用。","me":"re + lire：再 (re) 读 (lire) 一遍。","tr":{"zh":"你交作业之前再读一遍吧。","fr":"Relis ton devoir avant de le rendre.","alt":"Relis bien ton devoir avant de le donner.","note":"命令式 relis（tu）；代词 le 放在动词后面前面：avant de le rendre。"}},
 "Remarquer": {"pos":"v.t. 及物动词，-er 规则动词，助动词 avoir","s":"注意到，发觉；指出，提到。remarquer qqch / que + 句子。Remarque, ... = 「不过呢，……」（口语中补充一句）。pronominal：se faire remarquer = 引人注目（常含贬义）。","ipa":"[ʁə.maʁ.ke]","ph":"re [ʁə]；ar 读 [aʁ]；qu 读 [k]；结尾 -er 读 [e]。","pi":"qu 读 [k]，不是 [kw]；别和 regarder（看）混淆：remarquer 是「看见并留意」，不是主动去看。","et":"由 re- + marquer 构成；marquer 来自日耳曼语 *markōn（作标记）。同源：marque、remarque、remarquable。","ex":[["J'ai remarqué son absence.","我注意到他不在。"],["Tu as remarqué qu'elle a changé de coiffure ?","你注意到她换了发型吗？"],["Il se fait toujours remarquer en classe.","他在课堂上总是很引人注目。"]],"co":[["remarquer un détail","留意到一个细节"],["remarquer que + 句子","注意到……"],["se faire remarquer","惹人注目"],["faire remarquer qqch à qqn","向某人指出某事"]],"sy":[["constater","soutenu","确认，发现（偏书面）"],["apercevoir","courant","瞥见"],["observer","courant","观察"]],"fq":"高频，日常常用。","me":"re + marquer：给它「再加一个标记」，所以注意到了。","tr":{"zh":"你注意到他今天没有来吗？","fr":"Tu as remarqué qu'il n'est pas venu aujourd'hui ?","alt":"T'as vu qu'il n'est pas venu aujourd'hui ?","note":"remarquer que + 直陈式。"}},
 "Résider": {"pos":"v.i. 不及物动词，-er 规则动词（é → è：je réside），助动词 avoir","s":"居住，定居（比 habiter 更正式、书面，用于行政、证件）。résider à / en + 地点。也有「在于」的意思：Le problème réside dans ... = 问题在于……。名词：un résident（居民），une résidence（住所，公寓）。","ipa":"[ʁe.zi.de]","ph":"é [e]；s 在两个元音之间读 [z]；结尾 -er 读 [e]。","pi":"s 读 [z]；résider 比 habiter 更书面，日常聊天用 habiter 更自然；别写成 residér。","et":"来自拉丁语 residere（坐下，留下），由 re- + sedere（坐）构成。同源：résidence、résident、assidu、présider。","ex":[["Il réside à Paris.","他住在巴黎。"],["Elle réside en France depuis dix ans.","她在法国居住已有十年。"],["La difficulté réside dans la prononciation.","难点在于发音。"]],"co":[["résider à Paris / en France","居住在巴黎 / 法国"],["résider à l'étranger","旅居国外"],["un résident","居民"],["la résidence principale","主要住所"]],"sy":[["habiter","courant","住（日常说法）"],["demeurer","soutenu","居住，停留（书面）"],["vivre","courant","生活，居住"]],"fq":"中频，行政、新闻中常见。","me":"résider：re + sit（坐下）：「坐」在某地不动，就是住下。","tr":{"zh":"我的祖父母住在乡下。","fr":"Mes grands-parents résident à la campagne.","alt":"Mes grands-parents habitent à la campagne.","note":"日常口语更常说 habiter。"}},
 "Retoucher": {"pos":"v.t. 及物动词，-er 规则动词，助动词 avoir","s":"修饰，润色，修改（照片、图片、衣服、文章）。retoucher une photo = 修图；retoucher un vêtement = 改衣服；retoucher un texte = 润色文章。名词：une retouche（修改；修图）。","ipa":"[ʁə.tu.ʃe]","ph":"re [ʁə]；ou [u]；ch [ʃ]；结尾 -er 读 [e]。","pi":"ou 读 [u]；ch 读 [ʃ]；别和 toucher（碰、感动）混淆：retoucher 有「再次」和「修改」两层意思。","et":"由 re- + toucher 构成；toucher 来自通俗拉丁语 *toccare（碰，敲），一般认为是拟声词。同源：retouche、touche。","ex":[["Le photographe va retoucher les images.","摄影师要修这些照片。"],["Il faut retoucher cette robe, elle est trop longue.","这条裙子要改一下，太长了。"],["Elle a retouché son texte avant de l'envoyer.","她发出去之前润色了文章。"]],"co":[["retoucher une photo","修图"],["retoucher une robe / un pantalon","改裙子 / 裤子"],["une retouche","修改；修图"],["retoucher un texte","润色文章"]],"sy":[["modifier","courant","修改"],["améliorer","courant","改进，改善"],["corriger","courant","改正，修正"]],"fq":"中频，摄影、裁缝、写作时常用。","me":"re + toucher：再「碰」一下它，改几笔。","tr":{"zh":"我想修一下这张照片。","fr":"Je voudrais retoucher cette photo.","alt":"Je veux retoucher un peu cette photo.","note":"voudrais 比 veux 更委婉。"}},
 "Revenir sur": {"pos":"v.i. 不及物动词，不规则动词（同 venir），助动词 être，过去分词 revenu","s":"重新考虑，回头再看（决定、话题）；食物或事情「再谈」。revenir sur une décision = 重新考虑 / 收回决定；revenir sur un sujet = 回到一个话题。本义：revenir = 回来，返回。","ipa":"[ʁəv.niʁ]","ph":"re [ʁə]；v [v]；en 在这里读 [ə]（轻读）；结尾 r 读 [ʁ]。","pi":"revenir 用 être：Je suis revenu；变位像 venir：je reviens，nous revenons；revenir sur 后面接「想法 / 决定」；别和 retourner（回去）混淆：revenir 是「回到说话者这边」。","et":"来自拉丁语 revenire，由 re- + venire（来）构成。同源：venir、devenir、revenu（收入）、souvenir。","ex":[["Nous devons revenir sur cette décision.","我们得重新考虑这个决定。"],["Je voudrais revenir sur ce point.","我想再谈谈这一点。"],["Il ne veut pas revenir sur sa parole.","他不想食言。"]],"co":[["revenir sur une décision","重新考虑 / 改变决定"],["revenir sur un sujet","回到某个话题"],["revenir sur sa parole","食言，反悔"],["revenir à","回到……；归结为"]],"sy":[["reconsidérer","soutenu","重新考虑（书面）"],["annuler","courant","取消"],["se rétracter","soutenu","收回，撤回"]],"fq":"中高频，讨论和工作场合常用。","me":"re-venir sur：脚步「回到」同一个点上，再看一遍。","tr":{"zh":"老板不会改变他的决定。","fr":"Le patron ne reviendra pas sur sa décision.","alt":"Le patron ne changera pas d'avis.","note":"revenir sur + 名词；将来时 reviendra。"}},
 "Se mettre à": {"pos":"v. pronominal 代词式动词，不规则动词（第三组，同 mettre），助动词 être，过去分词 mis","s":"开始（做某事）：se mettre à + 不定式 / 名词。Il se met à pleuvoir = 开始下雨。也表示「开始从事 / 学习某事」：se mettre au sport / à la peinture / au français。强调「动手开始」的瞬间。","ipa":"[sə.mɛtʁ a]","ph":"se [sə]；mettre 读 [mɛtʁ]，-tt- 只读一个 [t]，结尾 -re 的 e 不发音；à [a]。","pi":"mettre 的 e 读 [ɛ]；tt 读单个 [t]；助动词用 être：Il s'est mis à courir；过去分词 mis（不是 mettu）。","et":"来自拉丁语 mittere（放，送）。se mettre à 字面意思是「把自己放到……上」，即「着手」。同源：mettre、permettre、promettre。","ex":[["Il vient de se mettre à la peinture.","他刚开始画画。"],["Il s'est mis à pleuvoir.","开始下雨了。"],["Je me mets au sport la semaine prochaine.","我下周开始做运动。"]],"co":[["se mettre à + 不定式 (se mettre à courir)","开始跑起来"],["se mettre au sport / au travail","开始运动 / 工作"],["se mettre à table","入座吃饭"],["se mettre en route","出发"]],"sy":[["commencer à","courant","开始（更中性）"],["entreprendre","soutenu","着手，从事"],["s'arrêter de","courant","停止做（反义）"]],"fq":"极高频，日常常用。","me":"se mettre à = 把自己「放上去」去做：动手！","tr":{"zh":"她三个月前开始学法语。","fr":"Elle s'est mise au français il y a trois mois.","alt":"Elle a commencé le français il y a trois mois.","note":"女性主语：s'est mise（过去分词与主语一致）。"}},
 "Sembler": {"pos":"v.i. 不及物动词，-er 规则动词，助动词 avoir","s":"似乎，看起来；好像。sembler + 形容词（Il semble fatigué）；sembler + 不定式；il semble que + 虚拟式（Il semble que ce soit vrai）。语气比 être 委婉，不完全肯定。","ipa":"[sɑ̃.ble]","ph":"s [s]；em 读 [ɑ̃]（m 不发音）；bl 连读；结尾 -er 读 [e]。","pi":"em 在 b 前读鼻化音 [ɑ̃]，m 不单读；il semble que 后面接虚拟式；il me semble que（我觉得）后接直陈式；别和 ressembler（像）混淆。","et":"来自拉丁语 similare（相似），源于 similis（相似的）。同源：ressembler、ensemble、semblable。","ex":[["Il semble fatigué aujourd'hui.","他今天看起来很累。"],["Il me semble que tu as raison.","我觉得你是对的。"],["Ça semble difficile, mais c'est possible.","看起来很难，但是可能的。"]],"co":[["sembler + 形容词","看起来……"],["il me semble que + 直陈式","我觉得……"],["il semble que + 虚拟式","似乎……"],["à ce qu'il semble","看来"]],"sy":[["paraître","soutenu","显得，似乎"],["avoir l'air","courant","看起来（日常，avoir l'air fatigué）"],["ressembler à","courant","像（对比：外形相似）"]],"fq":"极高频，日常常用。","me":"sembler ≈ resemble：「像是」这样。","tr":{"zh":"这个问题似乎很简单。","fr":"Cette question semble très simple.","alt":"Cette question a l'air très simple.","note":"sembler + 形容词，形容词与主语一致。"}},
 "Servir de...": {"pos":"v.i. 不及物动词，不规则动词（第三组），助动词 avoir，过去分词 servi","s":"用作……，充当……：servir de + 无冠词名词。Ce canapé sert de lit = 这个沙发可以当床。另有 servir à + 不定式 = 用来做……（Ça sert à couper）。","ipa":"[sɛʁ.viʁ]","ph":"ser 读 [sɛʁ]；vir 读 [viʁ]；两个 r 都读 [ʁ]。","pi":"servir de + 名词（充当什么），servir à + 动词（用来做什么），两个介词不能混；de 后面名词通常不带冠词：servir de guide。","et":"来自拉丁语 servire（做仆人，服务），源于 servus（仆人）。同源：service、serveur、serviette、serviable。","ex":[["Ce canapé peut servir de lit.","这个沙发可以当床用。"],["Cette boîte me sert de table.","这个箱子被我当桌子用。"],["Ce couteau sert à couper le pain.","这把刀是用来切面包的。"]],"co":[["servir de + 名词 (servir de guide)","充当向导"],["servir à + 动词原形","用来做……"],["ne servir à rien","没有任何用处"],["À quoi ça sert ?","这有什么用？"]],"sy":[["faire office de","soutenu","充当，起……作用"],["tenir lieu de","soutenu","代替"],["remplacer","courant","代替，取代"]],"fq":"极高频，日常常用。","me":"servir de = 当作；servir à = 用来：「de = 身份，à = 目的」。","tr":{"zh":"这张旧桌子可以当书桌用。","fr":"Cette vieille table peut servir de bureau.","alt":"Cette vieille table me sert de bureau.","note":"servir de + 无冠词名词。"}},
 "Songer à": {"pos":"v.i. 不及物动词，-er 规则动词（g → ge：nous songeons），助动词 avoir","s":"考虑，想到，惦记：songer à + 名词 / 不定式。songer à partir = 考虑离开；songer à qqn = 想着某人。也可以接 que：songer que ...（想到……）。比 penser à 更书面。","ipa":"[sɔ̃.ʒe]","ph":"on 读鼻化元音 [ɔ̃]；g 在 e 前读 [ʒ]；结尾 -er 读 [e]。","pi":"nous songeons（要加 e）；songer à + 不定式，不要写成 songer de；songe（名词）= 梦（书面）。","et":"来自拉丁语 somniare（做梦），源于 somnium（梦）。同源：songe（梦，书面）、somnoler（打瞌睡）。","ex":[["Je commence à songer à mes vacances.","我开始考虑我的假期。"],["Elle songe à changer de travail.","她在考虑换工作。"],["Songez que le temps passe vite.","想想看，时间过得很快。"]],"co":[["songer à + 名词 / 不定式","考虑……"],["songer que + 句子","想到……"],["Songez-y !","好好想想！"],["sans songer à mal","没有恶意地"]],"sy":[["penser à","courant","想到，考虑（日常）"],["envisager","soutenu","设想，考虑（更正式）"],["réfléchir à","courant","思考，反思"]],"fq":"中频，偏书面。","me":"songer ← songe（梦）：脑子里「做梦」般在想。","tr":{"zh":"我在考虑明年去法国学习。","fr":"Je songe à partir étudier en France l'année prochaine.","alt":"Je pense à aller étudier en France l'année prochaine.","note":"songer à + 不定式。"}},
 "S'adresser à": {"pos":"v. pronominal 代词式动词，-er 规则动词，助动词 être，过去分词 adressé","s":"向……求助，找……咨询；对……说话。s'adresser à qqn = 找某人询问 / 对某人说话；Adressez-vous à ... = 请找……；Ce livre s'adresse aux débutants = 这本书面向初学者。","ipa":"[sa.dʁe.se]","ph":"s'a 连读 [sa]；dr 读 [dʁ]；e 读 [e]；结尾 -er 读 [e]。","pi":"adresser 与英语 address 外形相近，但用法不同：「向某人求助」要说 s'adresser à，不能说 adresser qqn；dd 在法语中只有一个 d。","et":"由 à + dresser 构成，来自通俗拉丁语 *directiare（使直，朝向），源于 directus。同源：adresse、dresser、direct。","ex":[["Vous devez vous adresser au directeur.","您得向主任咨询。"],["Pour les billets, adressez-vous à l'accueil.","买票请找前台。"],["Ce film s'adresse aux enfants.","这部电影面向儿童。"]],"co":[["s'adresser à qqn","找某人（咨询、求助）"],["s'adresser à l'accueil / au guichet","去前台 / 窗口咨询"],["Adressez-vous à ...","请找……"],["s'adresser à un public","面向某类观众"]],"sy":[["demander à","courant","向……询问"],["contacter","courant","联系"],["consulter","courant","咨询"]],"fq":"中高频，办事、客服场景常用。","me":"s'adresser à = 把话「导向」某人，直接找他。","tr":{"zh":"如果有问题，请找我同事。","fr":"Si vous avez un problème, adressez-vous à ma collègue.","alt":"En cas de problème, vous pouvez vous adresser à ma collègue.","note":"命令式 adressez-vous：动词 + 代词。"}},
 "S'enregistrer": {"pos":"v. pronominal 代词式动词，-er 规则动词，助动词 être","s":"办理登记，办理值机；报到；录下自己。s'enregistrer à l'aéroport / à l'accueil = 在机场值机 / 前台登记；s'enregistrer en ligne = 在线值机。也可指给自己录音 / 录像。名词：l'enregistrement（登记；录音）。","ipa":"[sɑ̃.ʁə.ʒis.tʁe]","ph":"s'en 读 [sɑ̃]；re [ʁə]；g 在 i 前读 [ʒ]；str 读 [stʁ]；结尾 -er 读 [e]。","pi":"en- 读鼻化音 [ɑ̃]；g 读 [ʒ]；中间的 e 没有重音：enregistrer；「注册账号、报名」常说 s'inscrire，s'enregistrer 多用于值机或报到。","et":"由 en- + registre 构成，registre 来自中世纪拉丁语 registrum / regesta（记录）。同源：registre、enregistreur、enregistrement。","ex":[["Vous devez vous enregistrer à l'accueil.","您必须在前台登记。"],["Je me suis enregistré en ligne hier soir.","我昨晚在线办了值机。"],["Elle s'enregistre en train de chanter.","她在录下自己唱歌的声音。"]],"co":[["s'enregistrer à l'aéroport","在机场值机"],["s'enregistrer en ligne","在线值机；在线登记"],["s'enregistrer à l'hôtel","办理酒店入住登记"],["l'enregistrement des bagages","行李托运登记"]],"sy":[["s'inscrire","courant","报名，注册（课程、网站）"],["faire le check-in","courant","办理入住 / 值机（外来词）"],["se déclarer","soutenu","申报，登记（行政）"]],"fq":"中频，旅行和办事常用。","me":"en-registre-r：把自己「写进登记簿」(registre)。","tr":{"zh":"你得在飞机起飞前两小时办理值机。","fr":"Vous devez vous enregistrer deux heures avant le décollage.","alt":"Il faut s'enregistrer deux heures avant le décollage.","note":"vous devez + 代词式动词不定式：vous enregistrer。"}},
 "S'inquiéter": {"pos":"v. pronominal 代词式动词，-er 规则动词（é → è：je m'inquiète），助动词 être，过去分词 inquiété","s":"担心，担忧，不放心。s'inquiéter pour qqn / de qqch = 为某人 / 某事担心。命令式很常见：Ne t'inquiète pas ! = 别担心！形容词：inquiet / inquiète（担心的）。","ipa":"[sɛ̃.kje.te]","ph":"s'in 读 [sɛ̃]；qu 读 [k]；ié 读 [je]；结尾 -er 读 [e]。","pi":"qu 读 [k]；in 读鼻化 [ɛ̃]；变位要换音符：je m'inquiète，nous nous inquiétons；否定命令式 Ne t'inquiète pas。","et":"来自拉丁语 inquietare（使不安），由 in- + quietus（平静的）构成。同源：inquiet、inquiétude、quiétude（宁静）。","ex":[["Elle s'inquiète pour son avenir.","她为自己的未来担心。"],["Ne t'inquiète pas, tout va bien.","别担心，一切都好。"],["Ses parents s'inquiètent de son silence.","他的父母为他的沉默感到不安。"]],"co":[["s'inquiéter pour qqn","为某人担心"],["s'inquiéter de qqch","为某事担心"],["Ne t'inquiète pas !","别担心！"],["Il n'y a pas de quoi s'inquiéter.","没什么好担心的。"]],"sy":[["se faire du souci","courant","操心，担忧（日常）"],["s'angoisser","courant","焦虑"],["s'alarmer","soutenu","惊慌，警觉（更书面）"]],"fq":"极高频，日常常用。","me":"in-quiet：失去了「安静」(quiet) = 担心。","tr":{"zh":"别为考试担心，你准备得很好。","fr":"Ne t'inquiète pas pour l'examen, tu es bien préparé.","alt":"T'inquiète pas pour l'examen, t'es bien préparé.","note":"口语常省略 ne：T'inquiète pas。"}},
 "Se méfier de...": {"pos":"v. pronominal 代词式动词，-er 规则动词，助动词 être，过去分词 méfié","s":"提防，不信任，当心。se méfier de qqn / qqch = 提防某人 / 某物。Méfie-toi ! = 小心点！形容词：méfiant（多疑的），名词：la méfiance（戒心，不信任）。","ipa":"[sə.me.fje]","ph":"se [sə]；mé [me]；fi [fj]（i 变成半元音）；结尾 -er 读 [e]。","pi":"不要说 se méfier à；要接 de：se méfier de ...；与 se fier à（信任）相反，别搞混；注意不是 se méfier pour。","et":"由 mé-（否定）+ se fier 构成，fier 来自拉丁语 fidare（相信）。同源：fier、confiance、méfiance、défier。","ex":[["Il faut se méfier des apparences.","要提防表象。"],["Méfie-toi de ce site, il est peut-être faux.","小心这个网站，它可能是假的。"],["Je me méfie des inconnus.","我对陌生人保持警惕。"]],"co":[["se méfier de qqn / qqch","提防某人 / 某事"],["Méfiez-vous !","当心！"],["se méfier des apparences","不要被表象迷惑"],["la méfiance","不信任，戒心"]],"sy":[["se défier de","soutenu","不信任（书面）"],["faire attention","courant","小心"],["se fier à","courant","信任（反义）"]],"fq":"中高频，日常常用。","me":"mé- + fier：把「信任」(fier) 否定掉 = 提防。","tr":{"zh":"你要提防这种推销电话。","fr":"Il faut se méfier de ce genre d'appels.","alt":"Méfie-toi de ces appels de vendeurs.","note":"se méfier de + 名词；命令式 méfie-toi。"}},
 "Se passer": {"pos":"v. pronominal 代词式动词，-er 规则动词，助动词 être，过去分词 passé","s":"发生，进行（事情）：Que se passe-t-il ? = 发生什么了？Tout s'est bien passé = 一切顺利。常用第三人称。另有 se passer de qqch = 不要……也行，没有……也过得去。","ipa":"[sə.pa.se]","ph":"se [sə]；pa [pa]；ss 读 [s]；结尾 -er 读 [e]。","pi":"ss 读 [s]，不是 [z]；作「发生」时一般只用 il / ça / ce；与 arriver 同义；与 se passer de 搭配的意思完全不同（没有……也行）。","et":"来自 passer，源自通俗拉丁语 *passare，由 passus（步，脚步）而来。同源：pas、passage、passeport、dépasser。","ex":[["Que va-t-il se passer ?","会发生什么？"],["Qu'est-ce qui s'est passé hier ?","昨天发生了什么？"],["Je ne peux pas me passer de mon téléphone.","我离不开我的手机。"]],"co":[["Que se passe-t-il ?","发生什么事了？"],["Ça s'est bien passé.","一切顺利。"],["Qu'est-ce qui se passe ?","怎么回事？（口语）"],["se passer de qqch","没有……也行"]],"sy":[["arriver","courant","发生（日常）"],["se produire","soutenu","发生，出现"],["avoir lieu","courant","举行，发生（活动）"]],"fq":"极高频，日常常用。","me":"se passer = 事情「走过去了」，也就是发生了。","tr":{"zh":"昨晚的聚会怎么样？一切顺利吗？","fr":"Comment s'est passée la soirée d'hier ? Tout s'est bien passé ?","alt":"La soirée d'hier, ça s'est bien passé ?","note":"se passer 的过去分词 passé，主语若是阴性要加 e：la soirée s'est passée。"}},
 "Se préoccuper de": {"pos":"v. pronominal 代词式动词，-er 规则动词，助动词 être，过去分词 préoccupé","s":"关心，操心，在意：se préoccuper de qqn / qqch。强调把某事放在心上，有些担忧。préoccupé = 忧心忡忡的；une préoccupation = 关切，烦心事。","ipa":"[sə.pʁe.ɔ.ky.pe]","ph":"pré [pʁe]；é 与 o 分开读 [e.ɔ]；cc 只读一个 [k]；u 读 [y]；结尾 -er 读 [e]。","pi":"oc 读 [ɔk]：cc 双写但只读一个 [k]；拼写是 préoccuper（两个 c、两个 o），不要写成 préocuper；后面接 de。","et":"来自拉丁语 praeoccupare（预先占据），由 prae-（先）+ occupare（占据）构成。同源：occuper、occupation、préoccupation。","ex":[["Il faut se préoccuper de sa santé.","必须关心他的健康。"],["Elle se préoccupe beaucoup de l'avenir de ses enfants.","她非常关心孩子们的未来。"],["Ne te préoccupe pas de ça.","别为那个操心。"]],"co":[["se préoccuper de qqn / qqch","关心某人 / 某事"],["être préoccupé par qqch","为某事忧心"],["une préoccupation","关切，挂心的事"],["Ne vous préoccupez pas de moi.","不用管我。"]],"sy":[["s'occuper de","courant","照顾，负责"],["s'inquiéter de","courant","担心"],["se soucier de","soutenu","在意，挂念（书面）"]],"fq":"中频，偏书面。","me":"pré + occuper：事情提前「占据」了你的脑子。","tr":{"zh":"他们不太关心环境问题。","fr":"Ils ne se préoccupent pas assez de l'environnement.","alt":"Ils s'occupent peu de l'environnement.","note":"se préoccuper de + 名词。"}},
 "Se rapprocher de": {"pos":"v. pronominal 代词式动词，-er 规则动词，助动词 être，过去分词 rapproché","s":"靠近，走近；（关系上）更亲近，更接近。se rapprocher de qqn / qqch：位置上靠近，或与人修复关系。Ça se rapproche de la vérité = 这更接近真相。","ipa":"[sə.ʁa.pʁɔ.ʃe]","ph":"ra 读 [ʁa]；pr 读 [pʁ]；o 读 [ɔ]；ch 读 [ʃ]；结尾 -er 读 [e]。","pi":"ch 读 [ʃ]；o 读开口音 [ɔ]；rapprocher 里 pp 只读一个 [p]；不是 se rapprocher à。","et":"由 re- + approcher 构成，approcher 来自晚期拉丁语 appropiare（靠近），源于 prope（近）。同源：approcher、proche、prochain、rapprochement。","ex":[["Il essaie de se rapprocher de sa famille.","他试图和家人更亲近。"],["Rapproche-toi du feu, il fait froid.","靠近火堆来，天冷。"],["Ces deux pays veulent se rapprocher.","这两个国家想拉近关系。"]],"co":[["se rapprocher de qqn","靠近 / 亲近某人"],["se rapprocher du but","接近目标"],["rapprocher deux choses","使两样东西靠近 / 对比"],["le rapprochement","靠近；和解"]],"sy":[["s'approcher de","courant","走近（侧重位置）"],["se réconcilier","courant","和好"],["s'éloigner de","courant","远离（反义）"]],"fq":"中频，日常和书面都有。","me":"se rapprocher：re + proche：让自己再「靠近」一些。","tr":{"zh":"我想搬到离我父母近一点的地方。","fr":"Je voudrais me rapprocher de mes parents.","alt":"J'aimerais habiter plus près de mes parents.","note":"vouloir + se rapprocher：代词 me 随主语变化。"}},
 "Se rendre compte de": {"pos":"v. pronominal 代词式动词，不规则动词（第三组，同 rendre），助动词 être，过去分词 rendu","s":"意识到，发觉，明白：se rendre compte de qqch / que + 句子。Tu te rends compte ! = 你想想看！（惊讶）。不要和 rendre compte à（向……汇报）混淆。","ipa":"[sə.ʁɑ̃dʁ kɔ̃t]","ph":"rendre 读 [ʁɑ̃dʁ]（en 读 [ɑ̃]，结尾 e 不发音）；compte 读 [kɔ̃t]（p 不发音）。","pi":"compte 的 p 不发音；rendre 的 e 不发音；se rendre compte de + 名词，se rendre compte que + 句子；不要用 réaliser 代替它（法语 réaliser 通常是「实现」，不是「意识到」）。","et":"由 rendre（交还，使成为）+ compte（账，数目）构成：字面意思是「把账算清」。rendre 来自拉丁语 reddere，compte 来自 computare。","ex":[["Il vient de se rendre compte de son erreur.","他刚意识到自己的错误。"],["Je me rends compte que j'ai oublié mes clés.","我发现我忘带钥匙了。"],["Tu te rends compte ? Il a gagné !","你想想看！他赢了！"]],"co":[["se rendre compte de qqch","意识到某事"],["se rendre compte que + 句子","意识到……"],["Tu te rends compte !","你想想看！"],["sans s'en rendre compte","不知不觉地"]],"sy":[["comprendre","courant","明白，理解"],["s'apercevoir de","courant","察觉到"],["réaliser","familier","意识到（受英语影响，部分人认为不规范）"]],"fq":"极高频，日常常用。","me":"se rendre compte：把「账」(compte) 算给自己看，就明白了。","tr":{"zh":"我没有意识到时间已经这么晚了。","fr":"Je ne me suis pas rendu compte qu'il était si tard.","alt":"Je n'ai pas vu l'heure passer.","note":"se rendre compte que 后接直陈式；过去时用 s'est rendu。"}},
 "Se renseigner": {"pos":"v. pronominal 代词式动词，-er 规则动词，助动词 être，过去分词 renseigné","s":"打听，咨询，了解信息：se renseigner sur qqch / auprès de qqn。Je vais me renseigner = 我去问一问。名词：un renseignement = 一条信息；des renseignements = 咨询信息。","ipa":"[sə.ʁɑ̃.sɛ.ɲe]","ph":"ren 读 [ʁɑ̃]；sei 读 [sɛ]；gn 读 [ɲ]；结尾 -er 读 [e]。","pi":"gn 读 [ɲ]；ei 读 [ɛ]；不要把 renseigner 和 enseigner（教）搞混，它们同源但意思不同；se renseigner sur（关于），auprès de（向谁）。","et":"由 re- + enseigner 构成，enseigner 来自晚期拉丁语 insignare（标明，教），源于 signum（标记）。同源：enseigner、renseignement、signe。","ex":[["Je vais me renseigner sur ce sujet.","我去打听一下这个话题。"],["Renseignez-vous auprès de l'office de tourisme.","请向旅游局咨询。"],["Elle s'est renseignée avant de partir.","她出发前先打听了情况。"]],"co":[["se renseigner sur qqch","了解某事"],["se renseigner auprès de qqn","向某人咨询"],["un renseignement","一条信息，一个咨询"],["les renseignements","咨询台；信息"]],"sy":[["s'informer","courant","获取信息（更广，也用于新闻）"],["demander","courant","问，询问"],["se documenter","courant","查阅资料"]],"fq":"高频，办事、旅行常用。","me":"renseigner ← 再 (re) + enseigner：别人再给你「指点」一下。","tr":{"zh":"我想去打听一下火车时间。","fr":"Je vais me renseigner sur les horaires de train.","alt":"Je vais demander les horaires de train.","note":"se renseigner sur qqch：sur 引出话题。"}},
 "Se reposer sur (quelqu'un)": {"pos":"v. pronominal 代词式动词，-er 规则动词，助动词 être，过去分词 reposé","s":"依靠，指望（某人）：se reposer sur qqn = 把事情交给某人，相信他会做好。Tu peux te reposer sur moi = 你可以靠我。另一义：se reposer = 休息，没有 sur 时就是「休息」。","ipa":"[sə.ʁə.po.ze]","ph":"se [sə]；re [ʁə]；po [po]；s 在两个元音之间读 [z]；结尾 -er 读 [e]。","pi":"s 读 [z]；se reposer（休息）和 se reposer sur（依靠）意思不同，要看有没有 sur；别和 compter sur 混用语法。","et":"由 re- + poser 构成，poser 来自拉丁语 pausare（停下）。同源：repos、poser、pause。","ex":[["Tu peux te reposer sur moi.","你可以依靠我。"],["Je me repose un peu après le travail.","下班后我休息一会儿。"],["Il se repose trop sur ses collègues.","他太依赖同事了。"]],"co":[["se reposer sur qqn","依靠某人"],["se reposer un peu","稍微休息一下"],["se reposer sur ses lauriers","吃老本，满足于已有成就"],["Repose-toi bien !","好好休息！"]],"sy":[["compter sur","courant","指望，依靠"],["faire confiance à","courant","信任"],["s'appuyer sur","courant","依靠，倚仗"]],"fq":"高频，日常常用。","me":"re-poser sur：把重量「放」在别人身上，歇口气。","tr":{"zh":"你可以放心，我会把这件事做好。","fr":"Tu peux te reposer sur moi, je vais m'en occuper.","alt":"Compte sur moi, je m'en occupe.","note":"se reposer sur + 人；s'en occuper = 负责这件事。"}},
 "Alarmant": {"pos":"adj. 形容词，阴性 alarmante，复数 alarmants / alarmantes","s":"令人担忧的，令人警觉的。situation alarmante = 令人担忧的局势；chiffres alarmants = 令人惊心的数字。比 inquiétant 更强，带有「危急」的意味。动词：alarmer；名词：une alarme。","ipa":"[a.laʁ.mɑ̃]","ph":"a [a]；lar 读 [laʁ]；-ant 读鼻化音 [ɑ̃]，t 不发音。","pi":"结尾 -ant 读 [ɑ̃]，t 不发音；阴性 alarmante 中 t 才发音：[a.laʁ.mɑ̃t]；不要写成 allarmant（只有一个 l）。","et":"来自意大利语 all'arme（拿起武器！），经由 alarme 而来；alarmant 是 alarmer 的现在分词。同源：alarme、alarmer、arme。","ex":[["La situation est très alarmante.","情况非常令人担忧。"],["Les résultats sont alarmants.","结果令人担忧。"],["C'est une nouvelle alarmante.","这是一条令人不安的消息。"]],"co":[["une situation alarmante","令人担忧的局面"],["des chiffres alarmants","触目惊心的数据"],["un signe alarmant","危险的信号"],["tirer la sonnette d'alarme","拉响警报"]],"sy":[["inquiétant","courant","令人担心的（较温和）"],["préoccupant","courant","令人忧虑的"],["rassurant","courant","令人放心的（反义）"]],"fq":"中频，新闻、报告里常见。","me":"alarmant ≈ alarming：听到「警报」(alarme) 的感觉。","tr":{"zh":"最近的消息让人担忧。","fr":"Les dernières nouvelles sont alarmantes.","alt":"Les nouvelles de ces jours-ci ne sont pas rassurantes.","note":"形容词与名词一致：nouvelles → alarmantes。"}},
 "Amical": {"pos":"adj. 形容词，阴性 amicale，阳性复数 amicaux，阴性复数 amicales","s":"友好的，友善的，友谊的。un conseil amical = 友好的建议；un match amical = 友谊赛；un sourire amical = 友善的微笑。amicalement = 友好地，也是信件结尾常用的「祝好」。","ipa":"[a.mi.kal]","ph":"a [a]；mi [mi]；c 在 a 前读 [k]；结尾 -al 读 [al]，l 要发音。","pi":"阳性复数是 amicaux（不是 amicals）；结尾 l 要发音；别和 ami（朋友）、amitié（友谊）弄混。","et":"来自拉丁语 amicalis，源于 amicus（朋友）。同源：ami、amitié、amiable。","ex":[["Il m'a donné un conseil amical.","他给了我一个友好的建议。"],["Nous avons joué un match amical.","我们踢了一场友谊赛。"],["Elle m'a accueilli avec un sourire amical.","她带着友善的微笑迎接我。"]],"co":[["un conseil amical","友好的建议"],["un match amical","友谊赛"],["un ton amical","友好的语气"],["Amicalement,","祝好（信尾）"]],"sy":[["sympathique","courant","和蔼的，讨人喜欢的"],["cordial","soutenu","亲切的，热忱的"],["hostile","courant","敌对的（反义）"]],"fq":"中频，书信和日常都有。","me":"amical ← ami：朋友 (ami) 式的，所以是友好。","tr":{"zh":"我们昨天和他们踢了一场友谊赛。","fr":"Hier, nous avons joué un match amical contre eux.","alt":"Hier, on a fait un match amical avec eux.","note":"amical 修饰阳性名词 match，不变化。"}},
 "Bimensuel": {"pos":"adj. 形容词，阴性 bimensuelle，复数 bimensuels；也可作名词 un bimensuel（半月刊）","s":"每月两次的，半月一次的（半月刊）。un magazine bimensuel = 每月出两期的杂志。小心：bimestriel = 每两个月一次，两个词很容易混。法语中表示「每两个月一次」要用 bimestriel 或 tous les deux mois。","ipa":"[bi.mɑ̃.sɥɛl]","ph":"bi [bi]；men 读 [mɑ̃]；su 读 [sɥ]；-el 读 [ɛl]。","pi":"bimensuel（半月）≠ bimestriel（两个月），也和英语 bimonthly（有歧义）不同；阴性 bimensuelle 双写 l；men 读 [mɑ̃]，不读 [mɛn]。","et":"由 bi-（二）+ mensuel（每月的）构成；mensuel 来自拉丁语 mensis（月）。同源：mensuel、mois、semestre、trimestre。","ex":[["Ce magazine est bimensuel.","这本杂志是半月刊。"],["Nous avons une réunion bimensuelle.","我们每月开两次会。"],["Le journal devient bimensuel en septembre.","这份报纸九月起改为半月刊。"]],"co":[["une revue bimensuelle","半月刊"],["un magazine bimensuel","半月刊杂志"],["une réunion bimensuelle","每月两次的会议"],["un bimensuel","半月刊（刊物）"]],"sy":[["bimestriel","courant","每两个月一次（易混淆）"],["mensuel","courant","每月一次的"],["hebdomadaire","courant","每周的"]],"fq":"低频，出版和行政场合常见。","me":"bi（二）+ mensuel（月）：每月 (mois) 两次。","tr":{"zh":"我们的会议每月召开两次。","fr":"Nos réunions sont bimensuelles.","alt":"On a deux réunions par mois.","note":"bimensuel 与名词一致：réunions → bimensuelles。"}},
 "Bouleversé": {"pos":"adj. 形容词（动词 bouleverser 的过去分词），阴性 bouleversée，复数 bouleversés","s":"深受震撼的，心烦意乱的，悲痛欲绝的（强烈的情绪冲击，好坏都可以）。être bouleversé par une nouvelle = 被消息震撼。也可指事物被彻底打乱：Mes plans sont bouleversés。","ipa":"[bul.vɛʁ.se]","ph":"ou [u]；l 读 [l]；ver 读 [vɛʁ]；结尾 -é 读 [e]。","pi":"ou 读 [u]；bouleversé 里的 s 读 [s]（r 后面），不读 [z]；阴性加 e：bouleversée。","et":"来自动词 bouleverser，由 boule（球）+ verser（翻倒）构成，字面是「把球翻过来」。同源：bouleversement、verser。","ex":[["Il était complètement bouleversé par la nouvelle.","这个消息让他彻底崩溃了。"],["Elle est bouleversée par ce film.","她被这部电影深深震撼了。"],["Ma vie a été bouleversée.","我的生活被彻底打乱了。"]],"co":[["être bouleversé par qqch","被某事震撼"],["un visage bouleversé","悲痛欲绝的脸"],["complètement bouleversé","彻底崩溃"],["un bouleversement","剧变"]],"sy":[["ému","courant","感动的（较轻）"],["choqué","courant","受到打击的"],["secoué","familier","被震动的，受打击的"]],"fq":"中频，描述强烈情绪时常用。","me":"boule + verser：被「翻倒」的人，心都乱了。","tr":{"zh":"听到这个消息，她心烦意乱。","fr":"Elle était bouleversée en apprenant la nouvelle.","alt":"La nouvelle l'a bouleversée.","note":"过去分词作形容词，与主语一致：bouleversée。"}},
 "Complémentaire": {"pos":"adj. 形容词，阴阳性同形，复数 complémentaires","s":"互补的，补充的。des compétences complémentaires = 互补的能力；une information complémentaire = 补充信息；une mutuelle complémentaire = 补充医疗保险。名词：un complément（补充；补语）。","ipa":"[kɔ̃.ple.mɑ̃.tɛʁ]","ph":"com 读 [kɔ̃]；plé 读 [ple]；men 读 [mɑ̃]；taire 读 [tɛʁ]。","pi":"com- 读鼻化音 [kɔ̃]；拼写易错：complémentaire（有 é）≠ complimentaire（赞美的），写 e 还是 i 要分清；阴阳性同形。","et":"来自拉丁语 complementum（补足），源于 complere（补满）。同源：complet、compléter、complément。","ex":[["Leurs compétences sont complémentaires.","他们的能力是互补的。"],["J'ai besoin d'informations complémentaires.","我需要补充信息。"],["Elle a une assurance complémentaire.","她有补充保险。"]],"co":[["des informations complémentaires","补充信息"],["des couleurs complémentaires","互补色"],["une assurance complémentaire","补充保险"],["être complémentaires","互补"]],"sy":[["supplémentaire","courant","额外的，追加的"],["additionnel","soutenu","附加的"],["contraire","courant","相反的（对比）"]],"fq":"中频，学习、工作和保险场景常用。","me":"com-plément-aire：两样东西「补满」成一个完整。","tr":{"zh":"我们的两个团队互相补充。","fr":"Nos deux équipes sont complémentaires.","alt":"Nos deux équipes se complètent bien.","note":"complémentaire 阴阳性同形，复数加 s。"}},
 "Épuisé": {"pos":"adj. 形容词（动词 épuiser 的过去分词），阴性 épuisée，复数 épuisés","s":"筋疲力尽的；用完的，售罄的。Je suis épuisé = 我累坏了。un livre épuisé = 售罄的书；des stocks épuisés = 库存告罄。比 fatigué 强得多。","ipa":"[e.pɥi.ze]","ph":"é [e]；pui 读 [pɥi]（u 变半元音 [ɥ]）；结尾 -sé 读 [ze]。","pi":"uis 读 [ɥi]，不是 [ui]；s 在元音间读 [z]；开头有重音 é；阴性加 e：épuisée。","et":"来自动词 épuiser，源于古法语，由 é-（出）+ puits（井）构成，字面是「把井抽干」。同源：puits、épuisement。","ex":[["Je suis épuisé après cette longue journée.","漫长的一天后我精疲力尽。"],["Ce livre est épuisé chez l'éditeur.","这本书出版社已经售罄。"],["Elle semblait épuisée.","她看起来筋疲力尽。"]],"co":[["être épuisé","筋疲力尽"],["complètement épuisé","累得不行"],["un livre épuisé","售罄的书"],["épuisé par le travail","被工作累垮"]],"sy":[["fatigué","courant","累的（较轻）"],["crevé","familier","累死了"],["exténué","soutenu","精疲力竭（书面）"]],"fq":"高频，日常常用。","me":"é + puits：像井被抽干了，一点力气都不剩。","tr":{"zh":"跑完步后，我累得筋疲力尽。","fr":"Après la course, je suis épuisé.","alt":"Après avoir couru, je suis crevé.","note":"女性说 épuisée，发音相同。"}},
 "Familial": {"pos":"adj. 形容词，阴性 familiale，阳性复数 familiaux，阴性复数 familiales","s":"家庭的，家人的。un repas familial = 家庭聚餐；la vie familiale = 家庭生活；une voiture familiale = 家用大车。名词：la famille；形容词：familier 是「熟悉的 / 随意的」，不是同一个意思。","ipa":"[fa.mi.ljal]","ph":"fa [fa]；mi [mi]；lia 读 [ljal]（l 与 i 合成 [lj]）；结尾 l 要发音。","pi":"阳性复数是 familiaux；注意 familial ≠ familier（熟悉的，不拘礼节的）；l 在结尾要发音。","et":"来自拉丁语 familialis，源于 familia（家庭，家族）。同源：famille、familier、familiariser。","ex":[["C'est un repas familial.","这是一顿家庭聚餐。"],["Ils ont un problème familial.","他们有家庭问题。"],["Nous cherchons une voiture familiale.","我们在找一辆家用车。"]],"co":[["un repas familial","家庭聚餐"],["la vie familiale","家庭生活"],["un problème familial","家庭问题"],["les allocations familiales","家庭补助"]],"sy":[["domestique","courant","家里的（家务的）"],["parental","soutenu","父母的"],["familier","courant","熟悉的；随意的（易混）"]],"fq":"高频，日常常用。","me":"familial ← famille：家 (famille) 的，家里的。","tr":{"zh":"周日我们有家庭聚餐。","fr":"Dimanche, nous avons un repas familial.","alt":"Dimanche, on déjeune en famille.","note":"repas 是阳性，所以用 familial。"}},
 "Féroce": {"pos":"adj. 形容词，阴阳性同形，复数 féroces","s":"凶猛的，凶残的；激烈的。un animal féroce = 凶猛的动物；une concurrence féroce = 激烈的竞争；un appétit féroce = 巨大的胃口。副词：férocement（凶猛地）。","ipa":"[fe.ʁɔs]","ph":"é [e]；r 读 [ʁ]；o 读 [ɔ]；c 在词尾读 [s]（因为 c 后接 e，e 不发音）。","pi":"féroce 里的 c 读 [s]，不是 [k]；重音 é 在第一个音节；阴阳性同形；féroce 和英语 ferocious 相近，但结尾不同。","et":"来自拉丁语 ferox, ferocis（凶猛的），源于 ferus（野生的，野蛮的）。同源：férocité（凶猛）。","ex":[["C'est un animal féroce.","这是一种凶猛的动物。"],["La concurrence est féroce.","竞争非常激烈。"],["Il a un appétit féroce.","他胃口大得惊人。"]],"co":[["un animal féroce","凶猛的动物"],["une concurrence féroce","激烈的竞争"],["un appétit féroce","惊人的胃口"],["une lutte féroce","殊死搏斗"]],"sy":[["sauvage","courant","野生的，野蛮的"],["cruel","courant","残忍的"],["doux","courant","温和的（反义）"]],"fq":"中频，描述动物、竞争时常用。","me":"féroce ≈ ferocious：两者词根都是 ferus（野兽）。","tr":{"zh":"两个公司之间的竞争非常激烈。","fr":"La concurrence entre les deux entreprises est féroce.","alt":"La concurrence entre les deux boîtes est très dure.","note":"féroce 阴阳性同形，concurrence 是阴性但不变形。"}},
 "Formidable": {"pos":"adj. 形容词，阴阳性同形，复数 formidables","s":"太棒了的，了不起的，极好的（口语中非常常见的赞美）。C'est formidable ! = 太棒了！本义是「令人惊惧的，可怕的」，现代日常几乎只作褒义。也可以指规模巨大（un progrès formidable）。","ipa":"[fɔʁ.mi.dabl]","ph":"for 读 [fɔʁ]；mi [mi]；dable 读 [dabl]，结尾 -le 的 e 不发音。","pi":"结尾 -able 读 [abl]，e 不发音；formidable 在日常里是「太棒了」，不是「可怕」；阴阳性同形。","et":"来自拉丁语 formidabilis（令人害怕的），源于 formido（恐惧）。原义「可怕」，后来变成「惊人的」，再变成「太棒了」。","ex":[["C'est une idée formidable !","这个主意太棒了！"],["Nous avons passé un week-end formidable.","我们度过了一个美好的周末。"],["Elle est formidable avec les enfants.","她对孩子们太好了。"]],"co":[["C'est formidable !","太棒了！"],["une idée formidable","绝妙的主意"],["un type formidable","很棒的人"],["Formidable !","太好了！"]],"sy":[["génial","familier","太棒了（口语）"],["super","familier","超棒"],["excellent","courant","极好的"]],"fq":"高频，日常常用。","me":"formidable：由「可怕」变成「太棒了」：好到让人吓一跳。","tr":{"zh":"你的新工作太棒了，我为你高兴！","fr":"Ton nouveau travail est formidable, je suis content pour toi !","alt":"Ton nouveau boulot, c'est génial, je suis content pour toi !","note":"être content pour qqn：为某人高兴。"}},
 "Hebdomadaire": {"pos":"adj. 形容词，阴阳性同形；也可作名词 un hebdomadaire（周刊），常缩写为 un hebdo","s":"每周的，每周一次的。une réunion hebdomadaire = 每周例会；un magazine hebdomadaire = 周刊。口语常缩写为 hebdo：le menu hebdo。副词：chaque semaine / toutes les semaines 是更口语的说法。","ipa":"[ɛb.dɔ.ma.dɛʁ]","ph":"heb 读 [ɛb]；h 不发音；do 读 [dɔ]；ma 读 [ma]；daire 读 [dɛʁ]。","pi":"开头 h 不发音，读 [ɛb]；拼写长、容易写错：h-e-b-d-o-m-a-d-a-i-r-e；bd 连读 [bd]；日常口语更常说 chaque semaine。","et":"来自希腊语 hebdomas（七，一周七天），经拉丁语 hebdomadarius 传入法语。","ex":[["C'est une réunion hebdomadaire.","这是每周一次的会议。"],["Je lis un hebdomadaire sur l'actualité.","我读一份时事周刊。"],["Le cours est hebdomadaire.","这门课每周一次。"]],"co":[["une réunion hebdomadaire","每周例会"],["un magazine hebdomadaire","周刊杂志"],["un horaire hebdomadaire","每周作息 / 周课时"],["un hebdo","周刊（简称）"]],"sy":[["chaque semaine","courant","每周（日常说法）"],["mensuel","courant","每月的（对比）"],["quotidien","courant","每日的（对比）"]],"fq":"中频，书面、媒体常见。","me":"hebdo ← 希腊语「七」(hepta)：七天 = 一周。","tr":{"zh":"我们每周开一次会。","fr":"Nous avons une réunion hebdomadaire.","alt":"On se réunit chaque semaine.","note":"réunion 是阴性，但 hebdomadaire 阴阳性同形。"}},
 "Horrible": {"pos":"adj. 形容词，阴阳性同形，复数 horribles","s":"可怕的，糟糕透顶的；难看的，极坏的。un cauchemar horrible = 可怕的噩梦；un temps horrible = 糟糕的天气；Il a été horrible avec moi = 他对我很差劲。口语中常用作强调：C'est horrible ! = 太糟了！","ipa":"[ɔ.ʁibl]","ph":"h 不发音；o 读 [ɔ]；rr 只有一个 r，读 [ʁ]；结尾 -ble 读 [bl]，e 不发音。","pi":"开头 h 不发音，所以 un horrible 要连读，读作 [œ̃.nɔ.ʁibl]；只有一个 r；结尾 e 不发音。","et":"来自拉丁语 horribilis，源于 horrere（颤抖，毛发竖立）。同源：horreur、horrifier、abhorrer。","ex":[["J'ai fait un cauchemar horrible.","我做了一个可怕的噩梦。"],["Il fait un temps horrible aujourd'hui.","今天天气糟透了。"],["Ce film est horrible, je n'ai pas aimé.","这部电影太糟糕了，我不喜欢。"]],"co":[["un cauchemar horrible","可怕的噩梦"],["un temps horrible","糟糕的天气"],["C'est horrible !","太糟了！"],["une douleur horrible","剧烈的疼痛"]],"sy":[["affreux","courant","可怕的，糟糕的"],["terrible","courant","可怕的；（口语）极好"],["épouvantable","soutenu","骇人的"]],"fq":"高频，日常常用。","me":"horrible ≈ horror：h 不发音，直接 [ɔ]。","tr":{"zh":"这家餐厅的服务糟透了。","fr":"Le service de ce restaurant est horrible.","alt":"Le service dans ce resto, c'est affreux.","note":"horrible 阴阳性同形；service 是阳性。"}},
 "Maternel": {"pos":"adj. 形容词，阴性 maternelle，阳复 maternels","s":"母亲的；母性的；母系的。常见搭配：l'instinct maternel（母性本能）、la langue maternelle（母语）、l'école maternelle（幼儿园）。","ipa":"[ma.tɛʁ.nɛl]","ph":"ter 读 [tɛʁ]；r 是喉音 [ʁ]；结尾 -el 读 [ɛl]，l 要发出来。","pi":"阴性 maternelle 要双写 l；注意 la langue maternelle = 母语，不是「妈妈的语言」。","et":"来自拉丁语 maternus，源于 mater（母亲）。同族：mère、maternité。","ex":[["Elle a un instinct maternel très fort.","她的母性本能很强。"],["Le français est ma langue maternelle.","法语是我的母语。"],["Mon grand-père maternel habite à Lyon.","我的外公住在里昂。"]],"co":[["l'instinct maternel","母性本能"],["la langue maternelle","母语"],["l'école maternelle","幼儿园"],["l'amour maternel","母爱"]],"sy":[["de mère","courant","「母亲的」较中性说法"],["paternel","courant","反义：父亲的"]],"fq":"中频，日常和书面都用。","me":"mater（母）+ -nel：maternel ↔ paternel，只差 ma / pa。","tr":{"zh":"我外婆给了我很多母爱。","fr":"Ma grand-mère m'a donné beaucoup d'amour maternel.","alt":"Ma grand-mère m'a beaucoup aimé, comme une mère.","note":"形容词放在名词后面，并和名词性数一致。"}},
 "Méfiant": {"pos":"adj. 形容词，阴性 méfiante，阳复 méfiants","s":"不信任的；警惕的；多疑的。形容人，表示不轻易相信别人。常说 être méfiant envers / à l'égard de qqn。","ipa":"[me.fjɑ̃]","ph":"é [e]；f 要发；-ant 读鼻化音 [ɑ̃]，t 不发。","pi":"结尾 -ant 读 [ɑ̃]，t 不发；阴性 méfiante 才发 [t]。注意重音符号 é。","et":"来自动词 se méfier（mé- 表示否定，加 fier「信任」）+ -ant。","ex":[["Il est très méfiant envers les inconnus.","他对陌生人很警惕。"],["Elle est méfiante, elle vérifie tout.","她很多疑，什么都要检查。"],["Les chats sont souvent méfiants.","猫常常很警惕。"]],"co":[["être méfiant envers qqn","对某人不信任"],["un regard méfiant","怀疑的目光"],["se méfier de qqn","提防某人"]],"sy":[["soupçonneux","soutenu","猜疑的，更书面"],["prudent","courant","谨慎的（不含不信任）"],["confiant","courant","反义：信任的"]],"fq":"中频，日常常用。","me":"mé-（不）+ fier（信任）= 不信任。","tr":{"zh":"我的狗对陌生人很警惕。","fr":"Mon chien est méfiant avec les inconnus.","alt":"Mon chien se méfie des inconnus.","note":"méfiant 是形容词，se méfier de 是动词，意思相近。"}},
 "Mensuel": {"pos":"adj. 形容词，阴性 mensuelle，阳复 mensuels","s":"每月的；按月的。可指每月一次（une réunion mensuelle），也可指月度金额（un salaire mensuel，月薪）。","ipa":"[mɑ̃.sɥɛl]","ph":"men 读鼻化音 [mɑ̃]；su 读半元音 [sɥ]；结尾 el 读 [ɛl]。","pi":"men- 的 en 读 [ɑ̃]，不是 [ɛn]；阴性 mensuelle 双写 l。","et":"来自拉丁语 mensualis，源于 mensis（月）。同族：mois 的拉丁词根。","ex":[["Il paie un abonnement mensuel.","他交月费订阅。"],["Mon salaire mensuel est de deux mille euros.","我的月薪是两千欧元。"],["Nous avons une réunion mensuelle.","我们每月开一次会。"]],"co":[["un abonnement mensuel","月度订阅"],["un salaire mensuel","月薪"],["une revue mensuelle","月刊"],["le loyer mensuel","月租"]],"sy":[["par mois","courant","每个月（口语更自然）"],["hebdomadaire","courant","每周的（对比）"],["annuel","courant","每年的（对比）"]],"fq":"中频，工作、账单中常见。","me":"mensuel 和 mois 同根：月 → 每月的。","tr":{"zh":"你的月租是多少？","fr":"Quel est ton loyer mensuel ?","alt":"Tu paies combien de loyer par mois ?","note":"「每月」做形容词用 mensuel，做状语用 par mois。"}},
 "Moral": {"pos":"adj. 形容词，阴性 morale，阳复 moraux","s":"精神上的；道德的。le soutien moral = 精神支持；un principe moral = 道德原则。注意：le moral（名词）= 情绪、士气；la morale = 道德、寓意。","ipa":"[mɔ.ʁal]","ph":"o 读开口 [ɔ]；r [ʁ]；结尾 l 要发出来。","pi":"阳性复数是 moraux，不是 morals；le moral 与 la morale 不同，注意性。","et":"来自拉丁语 moralis，源于 mos, moris（习俗、品行）。","ex":[["Il a le soutien moral de sa famille.","他得到了家人的精神支持。"],["C'est un devoir moral.","这是一种道德义务。"],["Elle n'a pas le moral aujourd'hui.","她今天情绪不好。"]],"co":[["le soutien moral","精神支持"],["avoir le moral","情绪好，有精神"],["un devoir moral","道德义务"],["la morale","道德；寓意"]],"sy":[["éthique","soutenu","伦理的"],["psychologique","courant","心理的"],["immoral","courant","反义：不道德的"]],"fq":"中高频，日常常用。","me":"moral → moraux：和 animal → animaux 一样变复数。","tr":{"zh":"我今天情绪很低落。","fr":"Je n'ai pas le moral aujourd'hui.","alt":"Je suis un peu déprimé aujourd'hui.","note":"avoir le moral 里的 moral 是名词，阳性。"}},
 "Nu": {"pos":"adj. 形容词，阴性 nue，复数 nus / nues","s":"裸体的；光秃的；没有遮盖的。pieds nus = 光着脚；à l'œil nu = 肉眼。也可作名词 un nu（裸体画）。","ipa":"[ny]","ph":"u 读 [y]，嘴唇圆而紧，类似「吕」的韵母；不发辅音。","pi":"u [y] 不是「乌」[u]，容易与 nous [nu] 混淆；复数 nus 的 s 不发。","et":"来自拉丁语 nudus（裸的）。同族：nudité。","ex":[["Le modèle était nu.","模特是裸体的。"],["Les enfants courent pieds nus sur la plage.","孩子们光着脚在海滩上跑。"],["On voit cette étoile à l'œil nu.","这颗星用肉眼就能看见。"]],"co":[["pieds nus","光着脚"],["tête nue","光着头"],["à l'œil nu","用肉眼"],["mettre à nu","揭露，暴露"]],"sy":[["dénudé","soutenu","裸露的，光秃的"],["déshabillé","courant","没穿衣服的"],["habillé","courant","反义：穿好衣服的"]],"fq":"中频，常用于固定搭配。","me":"nu [ny] ≠ nous [nu]：「裸」的 u 要圆唇。","tr":{"zh":"不要光脚走路，地板很冷。","fr":"Ne marche pas pieds nus, le sol est froid.","alt":"Mets des chaussons, le sol est glacé.","note":"pieds nus 里 nu 与 pieds 配合，复数加 s。"}},
 "Paternel": {"pos":"adj. 形容词，阴性 paternelle，阳复 paternels","s":"父亲的；父系的；像父亲的。grand-père paternel = 爷爷（父亲一方）；l'autorité paternelle = 父亲的权威。","ipa":"[pa.tɛʁ.nɛl]","ph":"ter 读 [tɛʁ]；-nel 读 [nɛl]，l 要发出来。","pi":"阴性 paternelle 双写 l；注意 pa- 不是 pe-。","et":"来自拉丁语 paternus，源于 pater（父亲）。同族：père、paternité。","ex":[["Son grand-père paternel vient d'Italie.","他的祖父（父亲一方）来自意大利。"],["Il a un côté très paternel.","他有很像父亲的一面。"],["Ma famille paternelle habite à Marseille.","我父亲那边的家人住在马赛。"]],"co":[["le grand-père paternel","爷爷"],["la ligne paternelle","父系"],["l'amour paternel","父爱"],["un geste paternel","像父亲一样的举动"]],"sy":[["maternel","courant","反义：母亲的"],["protecteur","courant","保护性的"]],"fq":"中频，家庭话题常用。","me":"pa-ternel ↔ ma-ternel：pa 是父，ma 是母。","tr":{"zh":"我爷爷是在法国出生的。","fr":"Mon grand-père paternel est né en France.","alt":"Le père de mon père est né en France.","note":"法语区分爷爷（paternel）和外公（maternel）。"}},
 "Profond": {"pos":"adj. 形容词，阴性 profonde，阳复 profonds","s":"深的；深刻的；深厚的。可指物理上的深度（un lac profond），也可指感情和思想（un profond respect、une réflexion profonde）。","ipa":"[pʁɔ.fɔ̃]","ph":"pro [pʁɔ]；-fond 读鼻化音 [fɔ̃]，d 不发。阴性 profonde 读 [pʁɔ.fɔ̃d]，d 要发。","pi":"阳性结尾 -d 不发音，阴性才发 [d]；鼻化元音 [ɔ̃] 不要读成 on。","et":"来自拉丁语 profundus（pro- 向前 + fundus 底部）。同族：profondeur、fond。","ex":[["Il a un profond respect pour elle.","他对她有深深的敬意。"],["Ce lac est très profond.","这个湖很深。"],["Elle dort d'un sommeil profond.","她睡得很沉。"]],"co":[["un sommeil profond","沉睡"],["un profond respect","深深的敬意"],["une voix profonde","低沉的声音"],["au plus profond de","在……的最深处"]],"sy":[["intense","courant","强烈的"],["superficiel","courant","反义：肤浅的"],["creux","courant","凹陷的，空的"]],"fq":"高频，日常常用。","me":"pro + fond：往「底部」去 = 深。","tr":{"zh":"这条河不太深。","fr":"Cette rivière n'est pas très profonde.","alt":"Il n'y a pas beaucoup de fond dans cette rivière.","note":"profond 修饰 rivière（阴性），所以写 profonde。"}},
 "Psychologique": {"pos":"adj. 形容词，阴阳同形，复数 psychologiques","s":"心理的；心理学的。une aide psychologique = 心理援助；un problème psychologique = 心理问题；le test psychologique = 心理测试。","ipa":"[psi.kɔ.lɔ.ʒik]","ph":"ps 开头，p 要发 [ps]；y 读 [i]；-gique 读 [ʒik]，g 在 i 前读 [ʒ]，que 读 [k]。","pi":"开头 ps- 的 p 要发出来，不要省略；-que 结尾读 [k]，不是 [kə]。","et":"来自希腊语 psukhē（灵魂）+ logos（学说）。同族：psychologie、psychologue。","ex":[["Ce livre aborde l'aspect psychologique du problème.","这本书谈到了问题的心理方面。"],["Il a besoin d'un soutien psychologique.","他需要心理支持。"],["C'est un film psychologique.","这是一部心理片。"]],"co":[["un soutien psychologique","心理支持"],["un test psychologique","心理测试"],["la guerre psychologique","心理战"],["un effet psychologique","心理作用"]],"sy":[["mental","courant","精神上的"],["moral","courant","精神上的，道德的"],["physique","courant","反义：身体的"]],"fq":"中频，书面和新闻常用。","me":"psycho（心灵）+ logique（学说）：心理的。","tr":{"zh":"他得到了心理上的帮助。","fr":"Il a reçu une aide psychologique.","alt":"On l'a aidé sur le plan psychologique.","note":"阴阳同形，直接放在名词后。"}},
 "Ravi(e)": {"pos":"adj. 形容词，阳性 ravi，阴性 ravie","s":"很高兴的；欣喜的。较礼貌，常说 Je suis ravi(e) de vous rencontrer / de faire votre connaissance。也有「高兴极了」的意思，比 content 更强。","ipa":"[ʁa.vi]","ph":"r [ʁ]；a [a]；v [v]；i [i]。阴性 ravie 读 [ʁa.vi]，发音相同。","pi":"阳性 ravi 和阴性 ravie 读音一样，只是拼写不同，说话人是女性要写 ravie。","et":"是动词 ravir（使欣喜，也有「夺走」义）的过去分词，来自拉丁语 rapere（夺取）。","ex":[["Je suis ravi de vous rencontrer.","很高兴认识您。"],["Elle est ravie de son cadeau.","她对礼物欣喜万分。"],["Nous sommes ravis de vous accueillir.","我们很高兴欢迎您。"]],"co":[["ravi(e) de + inf.","很高兴做……"],["ravi(e) de faire votre connaissance","很高兴认识您"],["être ravi(e) que + subj.","很高兴……"]],"sy":[["enchanté","courant","幸会，介绍时说"],["content","courant","高兴，较普通"],["ravi","soutenu","更书面，更有礼貌"]],"fq":"中频，礼貌场合常用。","me":"ravi：被「夺走」烦恼，只剩高兴。","tr":{"zh":"我很高兴来这里。","fr":"Je suis ravie d'être ici.","alt":"Ça me fait plaisir d'être là.","note":"女性说话人写 ravie，后面接 de + 不定式。"}},
 "Réparateur": {"pos":"adj. 形容词，阴性 réparatrice，阳复 réparateurs","s":"恢复精力的；修复的。作形容词常说 un sommeil réparateur（能恢复精力的睡眠）。作名词 un réparateur / une réparatrice = 修理工。","ipa":"[ʁe.pa.ʁa.tœʁ]","ph":"ré [ʁe]；pa [pa]；ra [ʁa]；-teur 读 [tœʁ]，r 要发。","pi":"-eur 读 [œʁ]，不是「欧」；阴性是 réparatrice，不是 réparateuse。","et":"来自拉丁语 reparare（修复），réparer + -ateur 构成。同族：réparation、réparer。","ex":[["J'ai besoin d'un sommeil réparateur.","我需要一个能恢复精力的睡眠。"],["Le réparateur arrive à midi.","修理工中午到。"],["Une sieste réparatrice, ça fait du bien.","来个恢复精力的小睡很舒服。"]],"co":[["un sommeil réparateur","恢复精力的睡眠"],["une sieste réparatrice","恢复精力的午睡"],["un repos réparateur","能恢复体力的休息"],["un réparateur de vélos","自行车修理工"]],"sy":[["reposant","courant","让人放松的"],["fatigant","courant","反义：累人的"]],"fq":"中低频，多见于固定搭配。","me":"réparer（修）+ -ateur：睡一觉，把自己「修」好。","tr":{"zh":"一次好的睡眠很能恢复精力。","fr":"Une bonne nuit est très réparatrice.","alt":"Une bonne nuit, ça répare vraiment.","note":"修饰阴性名词用 réparatrice。"}},
 "Seul": {"pos":"adj. 形容词，阴性 seule，复数 seuls / seules","s":"孤单的；独自的；唯一的。位置不同意思不同：Il vit seul = 他独自生活；le seul homme = 唯一的男人（放名词前）。注意 seul 不一定含孤独的情绪，孤独感可用 se sentir seul。","ipa":"[sœl]","ph":"eu 读 [œ]（后面有辅音时开口）；结尾 l 要发。","pi":"eu 在这里是 [œ]，不是 [ø]；seul 的 l 发音，复数 seuls 的 s 不发。","et":"来自拉丁语 solus（单独的）。同族：solitaire、solo、seulement。","ex":[["Il vit seul dans son appartement.","他一个人住在公寓里。"],["C'est le seul restaurant ouvert.","这是唯一开着的餐厅。"],["Elle se sent seule le soir.","晚上她觉得孤单。"]],"co":[["vivre seul(e)","独居"],["tout(e) seul(e)","完全独自，自己一个人"],["le seul / la seule","唯一的"],["se sentir seul(e)","感到孤单"]],"sy":[["isolé","courant","孤立的，偏僻的"],["unique","courant","唯一的"],["solitaire","courant","喜欢独处的"]],"fq":"极高频，日常常用。","me":"seul ← solus：像 solo，一个人。","tr":{"zh":"我喜欢一个人看电影。","fr":"J'aime regarder des films seul.","alt":"J'aime bien aller au cinéma tout seul.","note":"女性写 seule；tout seul 更强调「完全自己」。"}},
 "Sincère": {"pos":"adj. 形容词，阴阳同形，复数 sincères","s":"真诚的；诚恳的。形容人或感情：un ami sincère、des excuses sincères。礼貌用语 Mes sincères condoléances = 深表哀悼。","ipa":"[sɛ̃.sɛʁ]","ph":"sin 读鼻化音 [sɛ̃]；cère 读 [sɛʁ]，c 在 e 前读 [s]；r 要发。","pi":"-ère 读 [ɛʁ]，注意 è 的重音；sincère 不是 sincer。","et":"来自拉丁语 sincerus（纯的，不掺杂的）。同族：sincérité、sincèrement。","ex":[["C'est un ami sincère.","他是一个真诚的朋友。"],["Elle a fait des excuses sincères.","她诚恳地道了歉。"],["Soyez sincère avec moi.","对我坦诚点。"]],"co":[["un ami sincère","真诚的朋友"],["des excuses sincères","诚恳的道歉"],["Mes sincères condoléances.","深表哀悼。"],["être sincère avec qqn","对某人坦诚"]],"sy":[["honnête","courant","诚实的"],["franc","courant","坦率的"],["hypocrite","courant","反义：虚伪的"]],"fq":"中高频，日常常用。","me":"sincère：像英语 sincere，但要读 [sɛ̃.sɛʁ]。","tr":{"zh":"我想说句真心话。","fr":"Je veux être sincère avec toi.","alt":"Je vais être honnête avec toi.","note":"être sincère avec qqn = 对某人坦诚。"}},
 "Solitaire": {"pos":"adj. 形容词，阴阳同形，复数 solitaires","s":"孤僻的；独居的；喜欢独处的。也作名词：un solitaire = 独来独往的人；un solitaire 还指单颗钻石戒指。","ipa":"[sɔ.li.tɛʁ]","ph":"so 读开口 [sɔ]；li [li]；taire 读 [tɛʁ]，ai 读 [ɛ]，r 要发。","pi":"-aire 读 [ɛʁ]，不是「爱」；solitaire 中 o 读 [ɔ]。","et":"来自拉丁语 solitarius，源于 solus（单独的）。同族：seul、solo、solitude。","ex":[["C'est un homme très solitaire.","他是个很孤僻的人。"],["Elle mène une vie solitaire à la campagne.","她在乡下过着孤独的生活。"],["Le loup solitaire chasse la nuit.","孤狼在夜里捕猎。"]],"co":[["une vie solitaire","孤独的生活"],["un loup solitaire","孤狼"],["un voyageur solitaire","独行的旅人"],["en solitaire","独自（做某事）"]],"sy":[["isolé","courant","与外界隔绝的"],["sociable","courant","反义：好交际的"],["ermite","littéraire","隐士"]],"fq":"中低频，描写性格时用。","me":"soli（独）+ taire：一个人像 solo。","tr":{"zh":"他是个喜欢独处的人。","fr":"C'est un homme solitaire.","alt":"Il aime être seul, c'est un solitaire.","note":"solitaire 阴阳同形，既能作形容词也能作名词。"}},
 "Centenaire": {"pos":"adj. 形容词，阴阳同形，复数 centenaires","s":"百岁的；有一百年历史的。也作名词：un centenaire = 百岁老人（阳性）；un centenaire 也指一百周年纪念。","ipa":"[sɑ̃t.nɛʁ]","ph":"cen 读鼻化音 [sɑ̃]；t 读 [t]，常连读成 [sɑ̃t.nɛʁ]；-aire 读 [ɛʁ]。","pi":"cent 的 t 在 centenaire 中要发；不要读成 [sɑ̃.nɛʁ]。","et":"来自拉丁语 centenarius，源于 centum（一百）。同族：cent、centime、centimètre。","ex":[["Cet arbre est centenaire.","这棵树有一百岁了。"],["Ma voisine est centenaire.","我的邻居已经一百岁了。"],["Cette maison est centenaire.","这栋房子有百年历史。"]],"co":[["un arbre centenaire","百年老树"],["une maison centenaire","百年老屋"],["un centenaire","百岁老人；百年纪念"],["fêter son centenaire","庆祝一百岁生日"]],"sy":[["séculaire","soutenu","百年的，悠久的"],["ancien","courant","古老的"]],"fq":"低频，多见于新闻和描写。","me":"cent 是一百，centenaire 就是「满一百」。","tr":{"zh":"那棵树有一百多年了。","fr":"Cet arbre a plus de cent ans.","alt":"Cet arbre est centenaire.","note":"说年龄用 avoir ... ans，说「百岁的」用 centenaire。"}},
 "Enfin": {"pos":"adv. 副词（不变）","s":"终于；最后；总之。enfin 表示等待之后的结果（Nous sommes enfin arrivés）；也用来换话头或自我修正（Enfin, bref），或表示无奈（Enfin !）。","ipa":"[ɑ̃.fɛ̃]","ph":"en 读 [ɑ̃]；fin 读 [fɛ̃]；两个都是鼻化音，n 不发。","pi":"两个鼻化元音不同：en [ɑ̃]，in [ɛ̃]，不要读成一样。","et":"由 en + fin 构成，字面是「到末尾」。同族：fin、finir、finalement。","ex":[["Nous sommes enfin arrivés.","我们终于到了。"],["Enfin, je ne sais pas.","总之，我不知道。"],["Enfin, tu es là !","你终于来了！"]],"co":[["Enfin !","终于！（也可表示不耐烦）"],["Enfin, bref","总之"],["Enfin seul(e)","终于独处了"],["et enfin","最后"]],"sy":[["finalement","courant","最终，结果"],["à la fin","courant","最后"],["bref","courant","总之，简而言之"]],"fq":"极高频，日常常用。","me":"en + fin：走到「尽头」，终于了。","tr":{"zh":"周末终于到了！","fr":"Enfin le week-end !","alt":"Ça y est, c'est le week-end !","note":"enfin 可放句首，表示等待后的轻松。"}},
 "Extrêmement": {"pos":"adv. 副词（不变）","s":"极其；非常。比 très 更强，放在形容词或副词前：extrêmement important、extrêmement bien。","ipa":"[ɛk.stʁɛm.mɑ̃]","ph":"ex 读 [ɛk]；str 读 [stʁ]；ê 读 [ɛ]；-ment 读 [mɑ̃]，t 不发；m 常常双发。","pi":"-ment 读 [mɑ̃]，不是「门特」；拼写有 ê 和双 m 的变化。","et":"由 extrême（来自拉丁语 extremus「最外面的」）+ -ment 构成。","ex":[["Ce livre est extrêmement intéressant.","这本书极其有趣。"],["Il fait extrêmement chaud aujourd'hui.","今天热极了。"],["Elle court extrêmement vite.","她跑得极快。"]],"co":[["extrêmement important","极其重要"],["extrêmement difficile","极其困难"],["extrêmement fatigué","累极了"],["extrêmement bien","好极了"]],"sy":[["très","courant","很，普通强度"],["super","familier","超级，口语"],["terriblement","soutenu","极其，很"]],"fq":"中高频，较书面，口语也用。","me":"extrême + -ment：走到「最极端」。","tr":{"zh":"这个问题极其重要。","fr":"Ce problème est extrêmement important.","alt":"Ce problème est vraiment très important.","note":"extrêmement 修饰形容词，放在其前面。"}},
 "Forcément": {"pos":"adv. 副词（不变）","s":"必然地；一定。常用于否定句：pas forcément = 不一定。也可单独回答 Forcément. = 那当然 / 难怪。","ipa":"[fɔʁ.se.mɑ̃]","ph":"for 读 [fɔʁ]；cé 读 [se]；-ment 读 [mɑ̃]。","pi":"c 在 é 前读 [s]；注意 -ment 是鼻化音，t 不发。","et":"由 forcé（被迫的，来自 force）+ -ment 构成。同族：force、forcer、forcé。","ex":[["Ce n'est pas forcément vrai.","这不一定是真的。"],["Il va forcément venir.","他一定会来的。"],["Les riches ne sont pas forcément heureux.","有钱人不一定幸福。"]],"co":[["pas forcément","不一定"],["pas forcément ça","不一定是那样"],["Forcément !","那当然！"],["pas toujours forcément","不见得总是"]],"sy":[["nécessairement","soutenu","必然地"],["obligatoirement","courant","必须地"],["évidemment","courant","当然"]],"fq":"高频，口语常用。","me":"forcé + ment：被「力」逼着，必然如此。","tr":{"zh":"贵的东西不一定好。","fr":"Ce qui est cher n'est pas forcément bon.","alt":"Cher, ça ne veut pas dire bon.","note":"pas forcément 放在动词后面，表示部分否定。"}},
 "Franchement": {"pos":"adv. 副词（不变）","s":"坦率地说；说实话；真的。放在句首表示说真话（Franchement, je ne sais pas），也可作强调：C'est franchement bien.（真的很不错）。","ipa":"[fʁɑ̃ʃ.mɑ̃]","ph":"fran 读 [fʁɑ̃]；ch 读 [ʃ]；-ment 读 [mɑ̃]；franche 中的 e 不发。","pi":"ch 读 [ʃ]，不是 [k]；an 是鼻化音 [ɑ̃]，n 不发。","et":"由 franc（直率的，来自 Franc「法兰克人」，指自由人）+ -e + -ment 构成。","ex":[["Franchement, je ne sais pas.","说实话，我不知道。"],["Franchement, c'est nul.","老实说，这真差劲。"],["C'est franchement bon !","真的很好吃！"]],"co":[["Franchement,","说实话，"],["franchement bien","真的不错"],["parler franchement","坦率地讲"],["Franchement !","真是的！"]],"sy":[["honnêtement","courant","老实说"],["sincèrement","courant","真诚地"],["vraiment","courant","真的"]],"fq":"高频，口语常用。","me":"franc（坦率）+ -ment：franchement 就是「直说」。","tr":{"zh":"说实话，我不喜欢这部电影。","fr":"Franchement, je n'aime pas ce film.","alt":"Honnêtement, ce film ne me plaît pas.","note":"franchement 放在句首，后面加逗号。"}},
 "Grandement": {"pos":"adv. 副词（不变）","s":"极大地；大大地；很。多与动词连用，表示程度：grandement contribuer、grandement apprécier。比 beaucoup 更书面。","ipa":"[gʁɑ̃d.mɑ̃]","ph":"gran 读 [gʁɑ̃]；d 在这里要读出 [d]；-ment 读 [mɑ̃]。","pi":"grand 的 d 平时不发，但在 grandement 里要发 [d]；g 读 [g]。","et":"由 grande + -ment 构成；grand 来自拉丁语 grandis。","ex":[["Il a grandement contribué au projet.","他对这个项目贡献很大。"],["J'apprécie grandement votre aide.","我非常感谢您的帮助。"],["Ce problème a grandement changé.","这个问题已经大大改变。"]],"co":[["grandement apprécier","非常欣赏"],["grandement contribuer","大大有助于"],["avoir grandement besoin de","非常需要"],["grandement facilité","大大简化了"]],"sy":[["beaucoup","courant","很多，最常用"],["énormément","courant","非常大量地"],["considérablement","soutenu","显著地"]],"fq":"中频，较书面。","me":"grande + ment：变大了，所以是「大大地」。","tr":{"zh":"你的帮助让我们轻松了许多。","fr":"Votre aide nous a grandement facilité la tâche.","alt":"Ton aide nous a beaucoup aidés.","note":"grandement 放在助动词和过去分词之间。"}},
 "Hyper": {"pos":"adv. 副词（口语，不变）","s":"超级；非常。口语里放在形容词前：hyper intéressant、hyper fatigué。比 très 更随意，年轻人常说。","ipa":"[i.pɛʁ]","ph":"h 不发音；y 读 [i]；per 读 [pɛʁ]，r 要发。","pi":"h 是哑音，开头只读 [i]；不要把 y 读成 [j]。","et":"来自希腊语前缀 hyper-（超过），在口语中独立成副词。同族：hypermarché、hyperactif。","ex":[["Ce film est hyper intéressant.","这部电影超级有意思。"],["Je suis hyper fatigué.","我累坏了。"],["Elle est hyper gentille.","她超级友善。"]],"co":[["hyper bien","超级好"],["hyper content","超级高兴"],["hyper cher","超级贵"],["un hypermarché","大型超市"]],"sy":[["très","courant","很"],["super","familier","超级"],["vachement","familier","特别，口语"]],"fq":"高频，口语常用。","me":"hyper = 「超」，和英语 hyper- 一样。","tr":{"zh":"我今天超级忙。","fr":"Je suis hyper occupé aujourd'hui.","alt":"Aujourd'hui, j'ai un emploi du temps de fou.","note":"hyper 不变形，放在形容词前，口语用。"}},
 "Malheureusement": {"pos":"adv. 副词（不变）","s":"不幸地；很遗憾。表示说话人对结果的遗憾，放在句首或动词后：Malheureusement, il n'est pas venu.","ipa":"[ma.lœ.ʁøz.mɑ̃]","ph":"heu 在 malheureux 中读 [lœ]；eu 在 -euse 中读 [ø]；s 读 [z]；-ment 读 [mɑ̃]。","pi":"拼写最长，注意 heureusement：h 不发，eu + s；中间 -ement 是 [mɑ̃]。","et":"由 malheureux（mal + heur「运气」）+ -e + -ment 构成。反义：heureusement。","ex":[["Malheureusement, il a raté son train.","不幸的是，他错过了火车。"],["Malheureusement, je ne peux pas venir.","很遗憾，我来不了。"],["Il pleut, malheureusement.","很遗憾，下雨了。"]],"co":[["Malheureusement,","很遗憾，"],["malheureusement pour moi","对我来说很不幸"],["malheureusement non","遗憾，不行"],["Heureusement !","幸好！（反义）"]],"sy":[["hélas","soutenu","唉，可惜"],["par malheur","littéraire","不幸地"],["heureusement","courant","反义：幸好"]],"fq":"高频，口语和书面都常用。","me":"mal + heureusement = 不「幸运」地。","tr":{"zh":"很遗憾，商店已经关门了。","fr":"Malheureusement, le magasin est déjà fermé.","alt":"Dommage, le magasin est déjà fermé.","note":"malheureusement 放句首，后面加逗号。"}},
 "Régulièrement": {"pos":"adv. 副词（不变）","s":"定期地；有规律地；经常。régulièrement 可表示有规律（每周一次）或笼统地「常常」：Je fais du sport régulièrement.","ipa":"[ʁe.gy.ljɛʁ.mɑ̃]","ph":"ré [ʁe]；gu 在 u 前读 [gy]；-lière 读 [ljɛʁ]；-ment 读 [mɑ̃]。","pi":"gu 读 [gy]，u 不要吞掉；ière 读 [jɛʁ]，注意重音符号。","et":"由 régulier（来自拉丁语 regularis，源于 regula「规则」）+ -ment 构成。同族：règle、régulier。","ex":[["Je fais du sport régulièrement.","我定期做运动。"],["Il appelle sa mère régulièrement.","他定期给妈妈打电话。"],["Les trains passent régulièrement.","火车定时经过。"]],"co":[["très régulièrement","非常有规律地"],["régulièrement par semaine","每周定期"],["faire régulièrement du sport","定期锻炼"],["se réunir régulièrement","定期聚会"]],"sy":[["souvent","courant","经常，但不一定有规律"],["périodiquement","soutenu","周期性地"],["irrégulièrement","courant","反义：不规律地"]],"fq":"中高频，日常常用。","me":"règle（规则）→ 按「规矩」来 = 定期。","tr":{"zh":"我每周定期去游泳。","fr":"Je vais régulièrement à la piscine.","alt":"Je vais nager toutes les semaines.","note":"régulièrement 放在动词后面。"}},
 "Seulement": {"pos":"adv. 副词（不变）","s":"仅仅；只；才。seulement 放在数量前表示少：Il y a seulement trois élèves。也表示「才」：Il est seulement huit heures。口语还有「不过」义：Seulement, il pleut.","ipa":"[sœl.mɑ̃]","ph":"seul 读 [sœl]，l 要发；-ement 读 [mɑ̃]，e 不发。","pi":"eu 读 [œ]，不是 [ø]；-ment 是鼻化音；seulement 的 l 不能漏。","et":"由 seul（拉丁语 solus）+ -e + -ment 构成。","ex":[["J'ai seulement besoin de cinq minutes.","我只需要五分钟。"],["Il est seulement huit heures.","才八点。"],["Pas seulement lui, mais aussi elle.","不仅是他，还有她。"]],"co":[["pas seulement ... mais aussi","不仅……而且"],["non seulement ... mais encore","不但……而且"],["si seulement","要是……就好了"],["seulement si","只有当……"]],"sy":[["uniquement","courant","仅仅，较正式"],["juste","familier","就，口语"],["rien que","courant","只有……"]],"fq":"极高频，日常常用。","me":"seul + ment：只有「一个」= 仅仅。","tr":{"zh":"我只想喝一杯水。","fr":"Je veux seulement un verre d'eau.","alt":"Je voudrais juste un verre d'eau.","note":"seulement 放在它所限定的词之前或动词之后。"}},
 "Systématiquement": {"pos":"adv. 副词（不变）","s":"系统性地；总是；每次都。多用来批评或强调规律：Il refuse systématiquement mes propositions.（他每次都拒绝）。","ipa":"[sis.te.ma.tik.mɑ̃]","ph":"sys 读 [sis]；té 读 [te]；ma 读 [ma]；-tique 读 [tik]；-ment 读 [mɑ̃]。","pi":"y 读 [i]；-tique 的 t 读 [t]；这个词长，分音节慢慢读。","et":"由 systématique（来自希腊语 sustēma「系统」）+ -ment 构成。同族：système。","ex":[["Il refuse systématiquement mes propositions.","他总是拒绝我的提议。"],["Elle vérifie systématiquement ses mails.","她每次都检查邮件。"],["Je ferme systématiquement la porte à clé.","我每次都锁门。"]],"co":[["refuser systématiquement","一律拒绝"],["vérifier systématiquement","每次都检查"],["systématiquement en retard","总是迟到"],["de façon systématique","有系统地"]],"sy":[["toujours","courant","总是，最常用"],["automatiquement","courant","自动地"],["régulièrement","courant","定期地"]],"fq":"中频，较书面。","me":"système + -atique + -ment：像系统一样，每次都这样。","tr":{"zh":"他每次都迟到。","fr":"Il arrive systématiquement en retard.","alt":"Il est toujours en retard.","note":"systématiquement 常用于抱怨，放在动词后。"}},
 "Soi-même": {"pos":"pron. 代词，反身强调（不变）","s":"自己；自己本人。泛指的「自己」，常与 on、chacun、il faut 等连用：Il faut le faire soi-même。具体的人要用 moi-même、toi-même、lui-même 等。","ipa":"[swa.mɛm]","ph":"soi 读 [swa]；même 读 [mɛm]，ê 的 è 读 [ɛ]，m 要发。","pi":"oi 读 [wa]，不是「奥伊」；même 的 e 不发，结尾读 [mɛm]。","et":"由 soi（来自拉丁语 sibi/se，反身代词）+ même 构成。","ex":[["Il faut le faire soi-même.","必须自己做。"],["On est toujours content de soi-même.","人总是对自己满意。"],["Connais-toi toi-même.","认识你自己。"]],"co":[["faire qqch soi-même","自己做某事"],["être soi-même","做自己"],["chacun pour soi-même","各人为自己"],["moi-même / toi-même / lui-même","我自己 / 你自己 / 他自己"]],"sy":[["moi-même","courant","我自己（具体的人）"],["tout seul","familier","自己一个人"],["personnellement","courant","亲自地"]],"fq":"中频，书面和格言中常见。","me":"soi（自己）+ même：自己本人。","tr":{"zh":"最好自己去看一看。","fr":"Le mieux est d'aller voir soi-même.","alt":"Le mieux, c'est d'aller voir par soi-même.","note":"soi-même 与泛指主语 on / chacun / 不定式搭配。"}},
 "Dès / Dès que": {"pos":"conj. / prép. 连词、介词（不变）","s":"dès + 名词 = 从……起（dès demain）；dès que + 从句 = 一……就……。dès que 后常用将来时或将来完成时，不能用现在时代替将来：Dès que j'arriverai.","ipa":"[dɛ] / [dɛ.kə]","ph":"dès 读 [dɛ]，s 不发；dès que 读 [dɛ.kə]，que 弱化为 [kə]。","pi":"dès 的 s 不发；dès que 后的时态要用将来时（说将来的事）。","et":"来源不确定；dès 是表示「从那时起」的短介词。同族表达：dès lors、dès à présent。","ex":[["Je t'appellerai dès que j'arriverai.","我一到就给你打电话。"],["Dès demain, je commence mon régime.","从明天起，我开始节食。"],["Dès qu'il pleut, je reste à la maison.","一下雨我就待在家里。"]],"co":[["dès que + 将来时","一……就……（将来）"],["dès demain","从明天起"],["dès maintenant","从现在起"],["dès le début","从一开始"]],"sy":[["aussitôt que","soutenu","一……就（更书面）"],["à partir de","courant","从……起"],["depuis","courant","自从（过去）"]],"fq":"高频，日常常用。","me":"dès que ≈ 英语 as soon as：一……就……。","tr":{"zh":"我一到家就给你发信息。","fr":"Je t'enverrai un message dès que je serai rentré.","alt":"Dès que je rentre, je t'écris.","note":"dès que 表将来时，后面用将来时或将来完成时。"}},
 "Jusque": {"pos":"prép. 介词（元音前变 jusqu'）","s":"直到；一直到。几乎总与另一个词连用：jusqu'à（到某处 / 某时）、jusqu'en（直到某月 / 某年）、jusqu'ici（到这里）、jusqu'à ce que + 虚拟式（直到……为止）。","ipa":"[ʒysk]","ph":"j 读 [ʒ]；u 读 [y]；s 和 q 连读 [sk]；e 不发。","pi":"jusque 单独用较少，常变为 jusqu'à；u 读 [y]；后接元音要省音。","et":"来自古法语，源于拉丁语 usque（直到），加 de。","ex":[["Il a couru jusque chez lui.","他一直跑到家。"],["Je reste ici jusqu'à six heures.","我在这里待到六点。"],["Attends jusqu'à ce que je revienne.","等我回来。"]],"co":[["jusqu'à","到……为止"],["jusqu'ici","到目前为止"],["jusqu'à ce que + subj.","直到……"],["jusqu'en + 年份","直到某年"]],"sy":[["à","courant","到，较笼统"],["pendant","courant","在……期间"],["d'ici à","courant","从现在到"]],"fq":"极高频，日常常用。","me":"jusqu'à：像 up to，「一路到」。","tr":{"zh":"我们一直走到公园。","fr":"On marche jusqu'au parc.","alt":"Nous allons à pied jusqu'au parc.","note":"jusque 常与 à 合写为 jusqu'à，再加 le → jusqu'au。"}},
 "Via": {"pos":"prép. 介词（不变）","s":"通过；经由。既可指路线（via Paris，经巴黎），也指方式 / 渠道（via Internet、via les réseaux sociaux）。","ipa":"[vja]","ph":"v [v]；ia 连成一个音节 [ja]；不发多余的音。","pi":"只有一个音节 [vja]，不要拆成 vi-a 两个音节。","et":"来自拉丁语 via（路，道）。同族：voie、voyage。","ex":[["Il m'a contacté via les réseaux sociaux.","他通过社交网络联系了我。"],["Je vais à Rome via Nice.","我经尼斯去罗马。"],["Vous pouvez payer via Internet.","您可以在网上付款。"]],"co":[["via Internet","通过网络"],["via les réseaux sociaux","通过社交网络"],["passer via Paris","经过巴黎"],["envoyer via e-mail","通过邮件发送"]],"sy":[["par","courant","通过"],["par le biais de","soutenu","借助……"],["grâce à","courant","多亏"]],"fq":"中高频，网络和交通中常用。","me":"via = 路：通过一条「路」。","tr":{"zh":"我们通过电子邮件联系。","fr":"Nous communiquons via e-mail.","alt":"On s'écrit par mail.","note":"via 后不加冠词时更常见。"}},
 "À la fois... et...": {"pos":"loc. 短语（不变）","s":"既……又……；同时。连接两个并列的成分（形容词、名词、动词）：à la fois beau et triste。和 à la fois 单用时表示「同时」。","ipa":"[a.la.fwa.e]","ph":"à la 读 [a.la]；fois 读 [fwa]，s 不发；et 读 [e]。","pi":"fois 的 s 不发，读 [fwa]；et 读 [e]，不是 [ɛt]。","et":"由 à + la + fois（一次，来自拉丁语 vices）构成，字面是「在同一次」。","ex":[["C'est à la fois beau et triste.","既美丽又悲伤。"],["Il est à la fois drôle et sérieux.","他既幽默又认真。"],["Elle chante à la fois en français et en anglais.","她同时用法语和英语唱歌。"]],"co":[["à la fois A et B","既 A 又 B"],["à la fois simple et efficace","既简单又有效"],["tout à la fois","同时全部"],["faire deux choses à la fois","同时做两件事"]],"sy":[["et ... et ...","courant","既……又……"],["aussi bien ... que ...","soutenu","无论……还是……"],["en même temps","courant","同时"]],"fq":"中高频，日常和书面都用。","me":"à la fois = 英语 both ... and ...，一次两样。","tr":{"zh":"这个城市既古老又现代。","fr":"Cette ville est à la fois ancienne et moderne.","alt":"Cette ville est ancienne et moderne en même temps.","note":"à la fois 连接两个并列的成分，后面接 et。"}},
 "À partir de...": {"pos":"loc. 短语（不变）","s":"从……起；以……为起点。时间：à partir de demain；数量：à partir de dix euros（十欧元起）；材料：à partir de lait（用牛奶做成）。","ipa":"[a.paʁ.tiʁ.də]","ph":"à [a]；par 读 [paʁ]；tir 读 [tiʁ]；de 弱化为 [də]；r 要发。","pi":"partir 中 r 要发出；t 在这里读 [t]，不是不发音。","et":"由 à + partir（出发）+ de 构成，字面是「从……出发」。同族：départ、partie。","ex":[["À partir de demain, je fais du sport.","从明天起我开始运动。"],["Le métro est gratuit à partir de vingt heures.","晚上八点以后地铁免费。"],["Ce fromage est fait à partir de lait de chèvre.","这种奶酪用山羊奶做成。"]],"co":[["à partir de demain","从明天起"],["à partir de maintenant","从现在起"],["à partir de dix euros","十欧元起"],["fait à partir de","用……做成"]],"sy":[["dès","courant","从……起"],["depuis","courant","自从（过去）"],["à compter de","soutenu","自……起（行政用语）"]],"fq":"高频，日常常用。","me":"à partir de = 英语 starting from。","tr":{"zh":"从下周一起我开始上班。","fr":"À partir de lundi prochain, je commence à travailler.","alt":"Dès lundi prochain, je commence le travail.","note":"à partir de 后接时间点、数量或材料。"}},
 "À portée de main": {"pos":"loc. 短语（不变）","s":"触手可及；在手边。字面是「在手能够到的范围内」：avoir qqch à portée de main = 手边有……。也可比喻某件事快要实现了。","ipa":"[a.pɔʁ.te.də.mɛ̃]","ph":"portée 读 [pɔʁ.te]；de 弱读 [də]；main 读 [mɛ̃]，ain 是鼻化音，n 不发。","pi":"main 的 ain 读 [ɛ̃]，不是「买」；portée 的 é 读 [e]。","et":"由 portée（动词 porter 的名词，「范围」）+ main（手，来自拉丁语 manus）构成。","ex":[["J'ai toujours un stylo à portée de main.","我手边总有一支笔。"],["Garde ton téléphone à portée de main.","把手机放在手边。"],["Le succès est à portée de main.","成功触手可及。"]],"co":[["avoir qqch à portée de main","手边有某物"],["à portée de voix","在喊得到的距离内"],["hors de portée","够不着，超出范围"],["à portée de clic","一点就到"]],"sy":[["sous la main","courant","就在手边"],["à disposition","courant","供使用"],["hors de portée","courant","反义：够不着"]],"fq":"中频，日常常用。","me":"portée（范围）+ main（手）：手能够到的范围。","tr":{"zh":"把你的钥匙放在手边。","fr":"Garde tes clés à portée de main.","alt":"Mets tes clés sous la main.","note":"à portée de main 常与 garder / avoir 连用。"}},
 "Au bout de...": {"pos":"loc. 短语（不变）","s":"过了……之后；到……的尽头。时间：au bout de deux heures（两小时后）；空间：au bout de la rue（在街的尽头）。","ipa":"[o.bu.də]","ph":"au 读 [o]；bout 读 [bu]，t 不发；de 弱读 [də]。","pi":"bout 的 t 不发；不要读成 [but]。","et":"由 à + le + bout（末端，古法语）构成。同族：bouter、aboutir。","ex":[["Au bout de deux heures, il est parti.","两个小时后他走了。"],["Le café est au bout de la rue.","咖啡馆在街的尽头。"],["Au bout d'un moment, elle a souri.","过了一会儿她笑了。"]],"co":[["au bout de + 时间","……之后"],["au bout de la rue","在街的尽头"],["au bout du compte","归根结底"],["au bout d'un moment","过了一会儿"]],"sy":[["après","courant","之后"],["à la fin de","courant","在……结束时"],["au terme de","soutenu","到……终了"]],"fq":"高频，日常常用。","me":"bout（末端）：走到「尽头」，时间也是。","tr":{"zh":"过了十分钟，公共汽车来了。","fr":"Au bout de dix minutes, le bus est arrivé.","alt":"Dix minutes après, le bus est arrivé.","note":"au bout de 后接时间长度，表示「经过了多久」。"}},
 "Avoir l'impression que...": {"pos":"loc. 短语（动词 avoir，que 后接直陈式）","s":"感觉……；觉得……。表示主观印象，不是确定的事实。肯定句 que 后用直陈式（J'ai l'impression qu'il va pleuvoir）；否定或疑问时有时用虚拟式。","ipa":"[a.vwaʁ.lɛ̃.pʁɛ.sjɔ̃.kə]","ph":"avoir 读 [a.vwaʁ]；l'impression 读 [lɛ̃.pʁɛ.sjɔ̃]；ss 读 [s]；-ion 读 [jɔ̃]。","pi":"impression 开头 im- 读鼻化音 [ɛ̃]；ss 读 [s]，不是 [z]；que 弱读 [kə]。","et":"由 avoir + impression（来自拉丁语 impressio「压印」）+ que 构成。","ex":[["J'ai l'impression qu'il va pleuvoir.","我觉得要下雨了。"],["J'ai l'impression de rêver.","我感觉像在做梦。"],["Tu as l'impression que c'est facile ?","你觉得这很容易吗？"]],"co":[["avoir l'impression que + ind.","感觉……"],["avoir l'impression de + inf.","感觉自己在……"],["donner l'impression de","给人……的印象"],["faire bonne impression","给人留下好印象"]],"sy":[["avoir le sentiment que","soutenu","有……的感觉"],["penser que","courant","认为"],["il me semble que","courant","我觉得"]],"fq":"高频，日常常用。","me":"impression ≈ 英语 impression：压在心里的「感觉」。","tr":{"zh":"我觉得他有点累。","fr":"J'ai l'impression qu'il est un peu fatigué.","alt":"Il a l'air un peu fatigué, non ?","note":"que 后用直陈式；主语相同时用 de + 不定式。"}},
 "Briser la glace": {"pos":"loc. 短语（动词 briser，第一组）","s":"打破僵局；打破尴尬。字面是「打碎冰」，比喻在初次见面或气氛冷淡时说话、开玩笑让大家放松。","ipa":"[bʁi.ze.la.glas]","ph":"bri 读 [bʁi]；ser 读 [ze]，s 在两个元音间读 [z]；glace 读 [glas]。","pi":"briser 里的 s 读 [z]；glace 里的 c 读 [s]；ce 结尾 e 不发。","et":"briser 来自古法语（可能为高卢语词）；glace 来自拉丁语 glacies。比喻义与英语 break the ice 相同。","ex":[["Il a raconté une blague pour briser la glace.","他讲了个笑话来打破僵局。"],["Pour briser la glace, elle a offert du café.","为了打破尴尬，她请大家喝咖啡。"],["Un sourire suffit pour briser la glace.","一个微笑就能打破僵局。"]],"co":[["briser la glace avec qqn","和某人打破僵局"],["pour briser la glace","为了打破僵局"],["un jeu pour briser la glace","破冰游戏"],["rompre la glace","打破沉默（同义）"]],"sy":[["rompre la glace","soutenu","打破僵局（略书面）"],["détendre l'atmosphère","courant","缓和气氛"]],"fq":"中频，日常常用。","me":"briser 「打碎」+ glace「冰」：和英语 break the ice 一样。","tr":{"zh":"他先开玩笑，打破了僵局。","fr":"Il a fait une blague pour briser la glace.","alt":"Sa blague a détendu l'ambiance.","note":"briser la glace 是固定表达，glace 前用定冠词。"}},
 "Ce n'est pas la peine de...": {"pos":"loc. 短语（后接不定式）","s":"没必要……；不值得……。委婉地让对方别做某事：Ce n'est pas la peine de crier。可省成 Pas la peine !（不用了）。","ipa":"[sə.nɛ.pa.la.pɛn.də]","ph":"ce n'est 读 [sə.nɛ]；pas 读 [pa]；la peine 读 [la.pɛn]；de 弱读 [də]；n 连读。","pi":"peine 读 [pɛn]，ei 读 [ɛ]；ce n'est 里 s 不发，t 不发。","et":"peine 来自拉丁语 poena（惩罚），后来引申为「辛苦、费力」。","ex":[["Ce n'est pas la peine de crier.","没必要大喊大叫。"],["Ce n'est pas la peine de venir.","不用来了。"],["Pas la peine ! Je peux le faire.","不用了！我能做。"]],"co":[["Ce n'est pas la peine de + inf.","没必要做……"],["Pas la peine !","不用了！"],["Ce n'est pas la peine que + subj.","没必要……"],["valoir la peine","值得"]],"sy":[["Inutile de + inf.","courant","没必要"],["Ça ne sert à rien de","courant","做……没用"],["Ce n'est pas nécessaire","courant","不必要"]],"fq":"高频，口语常用。","me":"peine = 麻烦：没必要自找麻烦。","tr":{"zh":"不用等我，你先走吧。","fr":"Ce n'est pas la peine de m'attendre, partez.","alt":"Pas la peine de m'attendre, allez-y.","note":"后面接不定式，或用 que + 虚拟式。"}},
 "Du tonnerre !": {"pos":"loc. 短语（感叹，口语）","s":"太棒了！非常好！字面是「雷一样的」，作感叹语或形容词短语：une fête du tonnerre、un temps du tonnerre。口语，轻松随意。","ipa":"[dy.tɔ.nɛʁ]","ph":"du 读 [dy]；ton 读 [tɔ]（o 读开口，不是鼻化音）；nerre 读 [nɛʁ]，r 要发。","pi":"tonnerre 中 on 不是鼻化音：读 [tɔ.nɛʁ]；两个 n 一个 r 的拼写要记牢。","et":"tonnerre 来自拉丁语 tonitrus（雷）。「du tonnerre」是借「雷的声势」来形容很棒。","ex":[["C'était une fête du tonnerre !","那是一场精彩的派对！"],["On a passé des vacances du tonnerre.","我们度过了一个很棒的假期。"],["Ton idée est du tonnerre !","你的主意太棒了！"]],"co":[["une fête du tonnerre","精彩的派对"],["un temps du tonnerre","好天气（也可指雷雨）"],["un bruit de tonnerre","雷鸣般的响声"],["Tonnerre !","天哪！（老式感叹）"]],"sy":[["génial","familier","太棒了"],["super","familier","超棒"],["formidable","courant","了不起，好极了"]],"fq":"中频，口语。","me":"像打雷一样「轰」——炸裂的好。","tr":{"zh":"我们昨晚玩得太开心了！","fr":"On a passé une soirée du tonnerre hier !","alt":"Hier soir, c'était génial !","note":"du tonnerre 放在名词后，作形容语。"}},
 "En compagnie de...": {"pos":"loc. 短语（不变）","s":"在……陪伴下；和……一起。比 avec 更书面一点：en compagnie de ses amis、en bonne compagnie。","ipa":"[ɑ̃.kɔ̃.pa.ɲi.də]","ph":"en [ɑ̃]；com 读 [kɔ̃]；pa [pa]；gnie 读 [ɲi]，gn 是鼻音 [ɲ]；de 弱读 [də]。","pi":"gn 读 [ɲ]，像「宁」中的声母，不是 g + n；en 与 com 都是鼻化音。","et":"由 compagnie（来自拉丁语 cum panis「共吃面包」，同吃饭的伙伴）构成。同族：copain、compagnon。","ex":[["Je suis en compagnie de mes amis.","我和朋友们在一起。"],["Elle voyage en compagnie de sa sœur.","她和姐姐一起旅行。"],["Il a dîné en compagnie du directeur.","他和主任一起吃了晚饭。"]],"co":[["en compagnie de qqn","与某人在一起"],["en bonne compagnie","有好伙伴相伴"],["tenir compagnie à qqn","陪伴某人"],["fausser compagnie à qqn","不辞而别"]],"sy":[["avec","courant","和，最常用"],["accompagné de","courant","由……陪同"],["aux côtés de","soutenu","在……身边"]],"fq":"中频，较书面。","me":"compagnie ← 一起吃面包的人：陪伴。","tr":{"zh":"她和朋友们一起去了海边。","fr":"Elle est allée à la mer en compagnie de ses amis.","alt":"Elle est allée à la mer avec ses amis.","note":"en compagnie de 后接人，口语多用 avec。"}},
 "Être en contact": {"pos":"loc. 短语（动词 être）","s":"保持联系；有联系。être en contact avec qqn = 与某人保持联系。也指接触（物理）：être en contact avec l'eau。","ipa":"[ɛtʁ.ɑ̃.kɔ̃.takt]","ph":"être 读 [ɛtʁ]；en [ɑ̃]；contact 读 [kɔ̃.takt]，结尾 ct 都发。","pi":"contact 的结尾 ct 要读出来 [kt]，别漏；con 读鼻化音 [kɔ̃]。","et":"contact 来自拉丁语 contactus（接触），contingere 的名词。同族：contacter、contagieux。","ex":[["Nous sommes toujours en contact.","我们一直保持联系。"],["Je suis en contact avec lui par mail.","我通过邮件和他保持联系。"],["Ne reste pas en contact avec ce produit.","不要接触这个产品。"]],"co":[["être en contact avec qqn","与某人保持联系"],["rester en contact","保持联系"],["entrer en contact avec","与……取得联系"],["perdre le contact","失去联系"]],"sy":[["garder le contact","courant","保持联络"],["être en relation","courant","有联系"],["se tenir au courant","courant","保持沟通"]],"fq":"高频，日常常用。","me":"contact 和英语 contact 一样，要念出结尾 -ct。","tr":{"zh":"我们一直通过短信保持联系。","fr":"Nous restons en contact par SMS.","alt":"On s'écrit des SMS régulièrement.","note":"être en contact avec qqn；être 可以换成 rester。"}},
 "Être mis de côté": {"pos":"loc. 短语（被动态，être + mis）","s":"被冷落；被排除在外；被搁置。mettre qqn de côté = 把某人晾在一边。mettre de l'argent de côté 则是「把钱存起来」，意思不同。","ipa":"[ɛtʁ.mi.də.ko.te]","ph":"être [ɛtʁ]；mis 读 [mi]，s 不发；de [də]；côté 读 [ko.te]。","pi":"mis 的 s 不发；côté 有两个重音：ô [o]，é [e]；被动态的过去分词随主语变化（mise / mis）。","et":"由 mettre（放）的过去分词 mis + de côté（到旁边）构成，字面是「被放到一边」。","ex":[["Il a peur d'être mis de côté.","他害怕被边缘化。"],["Elle s'est sentie mise de côté.","她觉得被冷落了。"],["Je ne veux pas être mis de côté.","我不想被排除在外。"]],"co":[["être mis(e) de côté","被冷落"],["mettre qqn de côté","把某人晾在一边"],["laisser de côté","撇开不管"],["mettre de l'argent de côté","存钱"]],"sy":[["être écarté","courant","被排除"],["être exclu","courant","被排斥"],["être oublié","courant","被遗忘"]],"fq":"中频，日常常用。","me":"mis de côté = 被放在「旁边」，没人理。","tr":{"zh":"我不想被团队冷落。","fr":"Je ne veux pas être mis de côté par l'équipe.","alt":"Je n'ai pas envie qu'on me laisse de côté.","note":"女性写 mise；用 par 引出施动者。"}},
 "Faire des efforts": {"pos":"loc. 短语（动词 faire）","s":"努力；费力气。faire des efforts pour + 不定式 = 为了……而努力。单数 faire un effort = 作一次努力。","ipa":"[fɛʁ.de.zɛ.fɔʁ]","ph":"faire [fɛʁ]；des 与 efforts 连读 [de.zɛ.fɔʁ]；effort 读 [ɛ.fɔʁ]，ff 读 [f]。","pi":"des 与 efforts 之间要连读出 [z]；effort 的 t 不发。","et":"effort 来自动词 efforcer（来自拉丁语 fortis「强」）。同族：fort、force。","ex":[["Il faut faire des efforts pour réussir.","必须努力才能成功。"],["Fais un effort, s'il te plaît.","请努力一下。"],["Elle fait beaucoup d'efforts en français.","她在法语上很努力。"]],"co":[["faire des efforts pour + inf.","为了……而努力"],["faire un effort","作一次努力"],["sans effort","毫不费力"],["redoubler d'efforts","加倍努力"]],"sy":[["s'efforcer de","soutenu","竭力做"],["essayer","courant","尝试"],["se donner du mal","courant","费心去做"]],"fq":"高频，日常常用。","me":"effort 和英语 effort 相似：faire des efforts = make efforts。","tr":{"zh":"你得多努力学法语。","fr":"Tu dois faire des efforts en français.","alt":"Il faut que tu t'accroches en français.","note":"des efforts 复数；单数用 un effort。"}},
 "Faire du bien": {"pos":"loc. 短语（动词 faire）","s":"对……有益；使人舒服。Ça me fait du bien. = 这对我有好处。也可指做好事：faire du bien à qqn = 帮助某人。","ipa":"[fɛʁ.dy.bjɛ̃]","ph":"faire [fɛʁ]；du [dy]；bien 读 [bjɛ̃]，ien 是 [jɛ̃]，n 不发。","pi":"du 里 u 是 [y]；bien 的 en 读 [ɛ̃]，不是 [ɑ̃]。","et":"bien 来自拉丁语 bene（好）。faire du bien 字面是「做出好」。","ex":[["Le sport me fait du bien.","运动对我有好处。"],["Une bonne douche te fera du bien.","冲个澡会让你舒服些。"],["Ça fait du bien de se reposer.","休息一下感觉真好。"]],"co":[["faire du bien à qqn","对某人有益"],["Ça fait du bien !","真舒服！"],["ça fait du bien de + inf.","做……感觉真好"],["faire du mal","对……有害（反义）"]],"sy":[["soulager","courant","使缓解"],["réconforter","soutenu","安慰"],["faire du mal","courant","反义：伤害"]],"fq":"高频，日常常用。","me":"faire + du bien：做出「好」的事。","tr":{"zh":"喝杯热茶对你有好处。","fr":"Une tasse de thé chaud te fera du bien.","alt":"Un thé chaud, ça fait du bien.","note":"faire du bien à qqn，du 是部分冠词，不是缩合。"}},
 "Faire du mal": {"pos":"loc. 短语（动词 faire）","s":"伤害；对……有害；弄疼。faire du mal à qqn = 伤害某人；Ça fait mal. = 疼。注意与 faire mal à qqn（弄疼）相近但语感略有不同。","ipa":"[fɛʁ.dy.mal]","ph":"faire [fɛʁ]；du [dy]；mal 读 [mal]，l 要发。","pi":"mal 的 l 要发，不是 [ma]；du 的 u 读 [y]。","et":"mal 来自拉丁语 male（坏地）。faire du mal 字面是「做出坏事」。","ex":[["Il ne voulait pas te faire du mal.","他不想伤害你。"],["Trop de sucre fait du mal à la santé.","糖太多对健康有害。"],["Ça ne fait pas de mal !","这没坏处！"]],"co":[["faire du mal à qqn","伤害某人"],["Ça ne fait pas de mal.","没坏处。"],["faire mal à qqn","弄疼某人"],["se faire du mal","伤到自己"]],"sy":[["blesser","courant","弄伤"],["nuire à","soutenu","有损于"],["faire du bien","courant","反义：有益"]],"fq":"高频，日常常用。","me":"faire du mal ↔ faire du bien：一好一坏。","tr":{"zh":"我不想伤害你的感情。","fr":"Je ne veux pas te faire du mal.","alt":"Je ne veux pas te blesser.","note":"faire du mal à qqn；否定句时 du 变 de：Ça ne fait pas de mal。"}},
 "Faire le pas": {"pos":"loc. 短语（动词 faire）","s":"迈出一步；下定决心。指在犹豫之后真正做出决定，如搬家、辞职、表白。常说 faire le premier pas（先迈出第一步）。","ipa":"[fɛʁ.lə.pa]","ph":"faire [fɛʁ]；le 弱读 [lə]；pas 读 [pa]，s 不发。","pi":"pas 的 s 不发；pas 也是否定词 ne ... pas，别混淆。","et":"pas 来自拉丁语 passus（步）。比喻义「迈出一步 = 做出决定」。","ex":[["Il a enfin décidé de faire le pas.","他终于决定迈出这一步。"],["Elle n'ose pas faire le pas.","她不敢迈出这一步。"],["C'est à toi de faire le premier pas.","该由你先迈出第一步。"]],"co":[["faire le pas","迈出这一步"],["faire le premier pas","迈出第一步"],["franchir le pas","跨出这一步（更常用）"],["un pas en avant","向前一步"]],"sy":[["franchir le pas","courant","跨出一步，更常见"],["se décider","courant","下决心"],["se lancer","courant","投身其中"]],"fq":"中频，日常常用。","me":"pas = 步：迈出那一「步」。","tr":{"zh":"他终于决定去法国生活。","fr":"Il a enfin fait le pas d'aller vivre en France.","alt":"Il a franchi le pas : il part vivre en France.","note":"faire le pas 之后常接 de + 不定式。"}},
 "Faire preuve de mesure": {"pos":"loc. 短语（动词 faire）","s":"表现得有分寸；有节制。faire preuve de + 名词 = 表现出（某种品质）：faire preuve de courage、de patience。mesure 在这里指「分寸、适度」。","ipa":"[fɛʁ.pʁœv.də.mə.zyʁ]","ph":"preuve 读 [pʁœv]；de [də]；mesure 读 [mə.zyʁ]，s 在元音间读 [z]。","pi":"preuve 中 eu 读 [œ]；mesure 的 s 读 [z]，u 读 [y]。","et":"preuve 来自拉丁语 proba；mesure 来自拉丁语 mensura（衡量）。同族：mesurer、dimension。","ex":[["Il faut faire preuve de mesure dans ses propos.","说话要有分寸。"],["Elle fait toujours preuve de mesure.","她总是很有分寸。"],["Faites preuve de mesure avec l'alcool.","饮酒要节制。"]],"co":[["faire preuve de + 名词","表现出……"],["faire preuve de courage","表现出勇气"],["avec mesure","有节制地"],["sans mesure","毫无节制"]],"sy":[["se modérer","courant","节制"],["faire preuve de retenue","soutenu","克制"],["exagérer","courant","反义：夸张"]],"fq":"中低频，较书面。","me":"preuve（证明）+ mesure（分寸）：证明你有分寸。","tr":{"zh":"在会议上要有分寸。","fr":"Il faut faire preuve de mesure pendant la réunion.","alt":"Pendant la réunion, il faut rester mesuré.","note":"faire preuve de + 无冠词名词。"}},
 "Faire un tour": {"pos":"loc. 短语（动词 faire）","s":"转一转；兜一圈；逛逛。可以步行、骑车、开车：faire un tour en ville / à vélo / en voiture。时间短，随意。","ipa":"[fɛʁ.œ̃.tuʁ]","ph":"faire [fɛʁ]；un 读鼻化音 [œ̃]，与 faire 连读；tour 读 [tuʁ]，r 要发。","pi":"tour 读 [tuʁ]，ou 读 [u]；un 读 [œ̃]，不是 [ɑ̃]。","et":"tour 来自拉丁语 tornus（车床，圆）。同族：tourner、tourisme。","ex":[["Je vais faire un tour en ville.","我去城里转转。"],["On fait un tour à vélo ?","我们骑车兜一圈吧？"],["Il est parti faire un tour dehors.","他出去转了转。"]],"co":[["faire un tour en ville","去城里逛逛"],["faire un tour à vélo","骑车兜一圈"],["faire un tour en voiture","开车兜风"],["faire le tour de","绕……一圈"]],"sy":[["se promener","courant","散步"],["faire une balade","courant","散步，更轻松"],["se balader","familier","闲逛"]],"fq":"高频，日常常用。","me":"tour = 一圈：兜一圈就回来。","tr":{"zh":"晚饭后我们去公园转一转吧。","fr":"Après le dîner, faisons un tour au parc.","alt":"Après manger, on va se balader au parc ?","note":"faire un tour 后可加 à / en / dans 表示去哪里或怎么去。"}},
 "Faire une balade": {"pos":"loc. 短语（动词 faire）","s":"散步；闲逛；出去走走。比 une promenade 更轻松随意：faire une balade en forêt / à la campagne / à vélo。","ipa":"[fɛʁ.yn.ba.lad]","ph":"faire [fɛʁ]；une 与 faire 连读 [yn]；balade 读 [ba.lad]，d 要发。","pi":"balade 结尾 -de 的 d 要发，e 不发；une 的 n 与后面连读。","et":"balade 来自动词 balader（可能源于普罗旺斯语 balar「跳舞」，词源不太确定）。","ex":[["Nous allons faire une balade en forêt.","我们去森林里散步。"],["On fait une balade après le déjeuner ?","午饭后去散个步吧？"],["J'aime faire une balade à vélo.","我喜欢骑车出去逛逛。"]],"co":[["faire une balade en forêt","到森林里散步"],["faire une balade à vélo","骑车逛逛"],["une balade en bateau","坐船游玩"],["partir en balade","出去逛逛"]],"sy":[["faire une promenade","courant","散步，较中性"],["se balader","familier","闲逛"],["flâner","soutenu","漫步"]],"fq":"高频，口语常用。","me":"balade：像「晃悠」，没有目的地。","tr":{"zh":"周末我们去海边散步吧。","fr":"Ce week-end, on fait une balade au bord de la mer ?","alt":"Samedi, on va se balader à la mer ?","note":"une balade 是阴性名词，冠词用 une。"}},
 "Laisser la place à ...": {"pos":"loc. 短语（动词 laisser，第一组）","s":"给……让位；让出位置。可以是真的座位（laisser sa place à une dame），也可以是比喻：让年轻人接班、让新事物取代旧事物。","ipa":"[le.se.la.plas.a]","ph":"laisser 读 [le.se]，ai 读 [e]；ss 读 [s]；la place 读 [la.plas]；à 读 [a]。","pi":"laisser 里 ai 读 [e]；place 的 c 读 [s]，e 不发。","et":"place 来自拉丁语 platea（宽街）。laisser 来自拉丁语 laxare（放松，松开）。","ex":[["Il faut laisser la place aux jeunes.","必须给年轻人让位。"],["Il a laissé sa place à une vieille dame.","他把座位让给了一位老太太。"],["La pluie laisse la place au soleil.","雨过天晴。"]],"co":[["laisser la place à qqn","给某人让位"],["laisser sa place","让座"],["céder la place à","让位给（同义）"],["laisser place à","让位于，由……取代"]],"sy":[["céder la place à","soutenu","让位给"],["faire de la place à","courant","给……腾地方"],["prendre la place de","courant","取代（反义角度）"]],"fq":"中频，日常和新闻中常用。","me":"laisser + place：留出一个位置给别人。","tr":{"zh":"他在地铁里给老人让了座。","fr":"Il a laissé sa place à une personne âgée dans le métro.","alt":"Il a cédé sa place à une personne âgée.","note":"laisser la place à qqn；à 后接人，aux 是 à + les 的缩合。"}},
 "Ne jurer que par...": {"pos":"loc. 短语（动词 jurer，第一组）","s":"只信……；奉为圭臬；非……不可。表示对某人 / 某事物极度信赖或推崇：Il ne jure que par son médecin。注意 jurer 本义是「发誓」。","ipa":"[nə.ʒy.ʁe.kə.paʁ]","ph":"ne 弱读 [nə]；jurer 读 [ʒy.ʁe]，j 读 [ʒ]；que 弱读 [kə]；par 读 [paʁ]。","pi":"j 读 [ʒ]，不是 [dʒ]；jurer 结尾 -er 读 [e]；ne ... que 表示「只」，不是否定。","et":"jurer 来自拉丁语 jurare（发誓），源于 jus（法律）。字面是「只对……发誓」。","ex":[["Elle ne jure que par les produits bio.","她只相信有机产品。"],["Il ne jure que par son nouveau téléphone.","他对新手机赞不绝口。"],["Mon père ne jure que par le football.","我爸爸满脑子都是足球。"]],"co":[["ne jurer que par qqn / qqch","只信某人 / 某物"],["ne jurer que par + 名词","非……不可"],["jurer de dire la vérité","发誓说实话"],["Je te jure !","我向你保证！"]],"sy":[["ne croire qu'en","courant","只信"],["ne vouloir que","courant","只想要"],["adorer","courant","热爱"]],"fq":"中频，日常常用。","me":"只对它「发誓」，别的都不认。","tr":{"zh":"我姐姐只用这个牌子的面霜。","fr":"Ma sœur ne jure que par cette marque de crème.","alt":"Ma sœur n'utilise que cette marque de crème.","note":"ne ... que 表示「只」，不是否定。"}},
 "Ouvrir les bras à...": {"pos":"loc. 短语（动词 ouvrir，第三组）","s":"张开双臂欢迎；热情接纳。字面是「向……张开双臂」，也可真的张开双臂。比喻对人或新事物完全接受。","ipa":"[u.vʁiʁ.le.bʁa.a]","ph":"ouvrir 读 [u.vʁiʁ]；les 读 [le]；bras 读 [bʁa]，s 不发；à 读 [a]。","pi":"ouvrir 里 ou 读 [u]，r 要发；bras 的 s 不发。","et":"ouvrir 来自拉丁语 aperire；bras 来自拉丁语 bracchium（手臂）。字面表达与英语 open arms 对应。","ex":[["Ils ont ouvert les bras aux réfugiés.","他们张开双臂欢迎难民。"],["Ma mère m'a ouvert les bras.","妈妈张开双臂迎接我。"],["La ville ouvre les bras aux touristes.","这座城市热情欢迎游客。"]],"co":[["ouvrir les bras à qqn","张开双臂欢迎某人"],["accueillir à bras ouverts","张开双臂迎接"],["avec les bras ouverts","张着双臂"],["se jeter dans les bras de qqn","扑进某人怀里"]],"sy":[["accueillir à bras ouverts","courant","热情迎接"],["accueillir","courant","接待"],["accepter","courant","接受"]],"fq":"中低频，较书面。","me":"张开双臂：欢迎的最直接动作。","tr":{"zh":"她张开双臂欢迎我们。","fr":"Elle nous a ouvert les bras.","alt":"Elle nous a accueillis à bras ouverts.","note":"ouvrir 的过去分词是 ouvert；à 后接受欢迎的人。"}},
 "Plein de": {"pos":"loc. 短语（不变，口语）","s":"很多的……；一大堆。口语里 plein de + 名词，名词前不加冠词：plein de gens、plein de choses。形容词 plein(e) de 则是「装满……的」。","ipa":"[plɛ̃.də]","ph":"plein 读 [plɛ̃]，ein 是鼻化音，n 不发；de 弱读 [də]。","pi":"plein 的 ein 读 [ɛ̃]，不是 [ɑ̃]；后面不加冠词，直接 plein de + 名词。","et":"plein 来自拉丁语 plenus（满的）。plein de 在口语中成为表示「很多」的数量短语。","ex":[["Il y a plein de gens dans la rue.","街上有好多人。"],["J'ai plein de choses à faire.","我有一大堆事要做。"],["Elle a plein d'amis.","她有很多朋友。"]],"co":[["plein de + 名词","很多……"],["plein de gens","很多人"],["plein de choses","很多东西 / 事情"],["en avoir plein le dos","受够了"]],"sy":[["beaucoup de","courant","很多，更中性"],["énormément de","courant","大量的"],["une tonne de","familier","一大堆"]],"fq":"高频，口语常用。","me":"plein = 满：满满的一堆。","tr":{"zh":"我昨天买了很多东西。","fr":"J'ai acheté plein de choses hier.","alt":"Hier, j'ai fait plein d'achats.","note":"plein de 后不加冠词，常用于口语。"}},
 "Que ce soit...": {"pos":"loc. 固定短语（后接虚拟式 soit）","s":"「无论是……还是……」。常用结构：Que ce soit A ou B, …，表示不管是 A 还是 B 结果都一样。soit 是 être 的虚拟式，所以这里一定用 soit，不能用 est。","ipa":"[kə.sə.swa]","ph":"Que [kə]；ce [sə]；soit 读 [swa]，t 不发音。","pi":"soit 的 t 不发音；不要写成 Que c'est。句首的 Que 后面要用虚拟式。","et":"que（连词）+ ce + soit（être 的虚拟式现在时第三人称单数）。是语法组合，不是独立的词。","ex":[["Que ce soit lui ou elle, quelqu'un doit le faire.","无论是他还是她，总得有人去做。"],["Que ce soit en train ou en voiture, c'est long.","不管坐火车还是开车，都要很久。"]],"co":[["que ce soit A ou B","无论是 A 还是 B"],["que ce soit pour le travail ou pour les loisirs","无论是为了工作还是娱乐"],["que ce soit maintenant ou plus tard","无论是现在还是以后"]],"sy":[["peu importe que","courant","不管；后接虚拟式"],["qu'il s'agisse de","soutenu","无论涉及……（更正式）"]],"fq":"高频，书面和口语都常用。","me":"soit = 「是」的虚拟式：que ce soit，像说「就算是……」。","tr":{"zh":"无论是咖啡还是茶，我都喜欢。","fr":"Que ce soit du café ou du thé, j'aime ça.","alt":"Café ou thé, peu importe, j'aime les deux.","note":"Que ce soit + 名词 + ou + 名词；soit 是虚拟式。"}},
 "Tendre la main à...": {"pos":"loc.v. 动词短语（tendre 规则动词，第三组 -re）","s":"字面是「向某人伸出手」，比喻「向某人伸出援手、主动帮忙或示好」。也可以真的是伸手去握手、递东西。后面接人，用 à。","ipa":"[tɑ̃dʁ.la.mɛ̃.a]","ph":"tendre [tɑ̃dʁ]，en/an 读鼻化 [ɑ̃]；main [mɛ̃]，ai 在鼻音前读 [ɛ̃]；tendre 的 -dre 只发 [dʁ]，结尾 e 不发音。","pi":"main 是阴性（la main），别写成 le main；main 的 n 不单独发音。tendre 的 e 在词尾 -re 前很轻。","et":"tendre（来自拉丁语 tendere，伸展）+ la main（拉丁语 manus，手）。","ex":[["Il faut tendre la main aux personnes en difficulté.","要向有困难的人伸出援手。"],["Elle m'a tendu la main pour m'aider à monter.","她向我伸出手，扶我上去。"]],"co":[["tendre la main à quelqu'un","向某人伸出手；帮助某人"],["une main tendue","伸出的援手"],["tendre la perche à quelqu'un","给某人一个机会、递台阶"]],"sy":[["aider","courant","帮助；最普通的说法"],["donner un coup de main","familier","搭把手，帮个忙"]],"fq":"中频，常见于谈社会、团结的语境。","me":"tendre = 伸直；伸直手 = 想拉人一把。","tr":{"zh":"他向我伸出了援手。","fr":"Il m'a tendu la main.","alt":"Il m'a aidé quand j'étais en difficulté.","note":"tendre 的过去分词是 tendu；人称代词 me 放在助动词前。"}},
 "Tirer vers le bas": {"pos":"loc.v. 动词短语（tirer 第一组 -er，规则动词）","s":"字面是「往下拉」。比喻义是「拖后腿、拉低水平」：某人或某情况使整体变差。主语可以是人、情况、结果、平均分等。","ipa":"[ti.ʁe.vɛʁ.lə.ba]","ph":"tirer [ti.ʁe]，词尾 -er 读 [e]；vers [vɛʁ]，s 不发音；le [lə]；bas [ba]，s 不发音。","pi":"vers 和 verre（杯子）、vert（绿色）发音相近，注意看上下文；bas 的 s 不发音。","et":"tirer（来源不确定，早期法语已有）+ vers（拉丁语 versus，朝向）+ bas（拉丁语 bassus，矮的）。","ex":[["Cette situation nous tire vers le bas.","这种情况把我们往下拉。"],["Une seule mauvaise note tire la moyenne vers le bas.","只有一个差的分数就会拉低平均分。"]],"co":[["tirer la moyenne vers le bas","拉低平均分"],["tirer quelqu'un vers le haut","带动某人向上"],["tirer les prix vers le bas","把价格压低"]],"sy":[["plomber","familier","拖累，压垮（气氛、预算等）"],["pénaliser","courant","使吃亏，不利于"]],"fq":"中频，口语和报道里都有。","me":"tirer（拉）+ bas（下）：像有人抓着你的脚往下拽。","tr":{"zh":"他的坏心情把整个团队往下拉。","fr":"Sa mauvaise humeur tire toute l'équipe vers le bas.","alt":"Sa mauvaise humeur plombe l'ambiance de l'équipe.","note":"反义说法：tirer vers le haut（向上带动）。"}},
 "À l'unisson": {"pos":"loc.adv. 副词短语","s":"「齐声地、一致地」。原指唱歌或乐器同音，引申为大家同时、同步、想法一致。","ipa":"[a.ly.ni.sɔ̃]","ph":"l'u 连读成 [ly]；u 读 [y]（嘟起嘴的 i）；ss 在两个元音间读 [s]；on 读鼻化 [ɔ̃]。","pi":"u 是 [y]，不是 [u]；unisson 的 ss 读 [s]，不是 [z]；结尾 n 不单独发音。","et":"拉丁语 unus（一）+ sonus（声音）：「一个声音」。","ex":[["Ils ont chanté à l'unisson.","他们齐声合唱。"],["Tout le monde a répondu à l'unisson : « Oui ! »","所有人齐声回答：「好！」"]],"co":[["chanter à l'unisson","齐声唱"],["répondre à l'unisson","异口同声地回答"],["vibrer à l'unisson","产生共鸣，心心相印"]],"sy":[["en chœur","courant","齐声，异口同声"],["ensemble","courant","一起（更宽泛）"]],"fq":"中低频，书面和日常都能见到。","me":"uni + son：同一个声音。","tr":{"zh":"孩子们齐声喊了起来。","fr":"Les enfants ont crié à l'unisson.","alt":"Les enfants ont crié tous ensemble.","note":"à l'unisson 放在动词后面，作方式状语。"}},
 "Au hasard": {"pos":"loc.adv. 副词短语（hasard 阳性）","s":"「随机地、随便地、碰运气地」，没有计划、没有选择标准。au hasard de + 名词 = 凭……的机缘。par hasard 则是「碰巧」，意思不同。","ipa":"[o.a.zaʁ]","ph":"au [o]；hasard 的 h 不发音，但它是「嘘音 h」，所以 au 和 hasard 之间不连读，有极短停顿：[o.a.zaʁ]；s 读 [z]；结尾 d 不发音。","pi":"hasard 的 h 不发音，d 也不发音：[a.zaʁ]。注意 au hasard（随便）和 par hasard（碰巧）不要混用。","et":"来自阿拉伯语 az-zahr（骰子），经西班牙语 azar 传入法语。","ex":[["J'ai choisi un livre au hasard.","我随便选了一本书。"],["Il a ouvert une page au hasard.","他随便翻开一页。"]],"co":[["choisir au hasard","随机选"],["tirer au hasard","随机抽取"],["au hasard de la conversation","在聊天中偶然提到"]],"sy":[["par hasard","courant","碰巧（是结果），不是方式"],["n'importe comment","familier","随便地，马马虎虎"]],"fq":"高频，日常常用。","me":"hasard 来自「骰子」：au hasard = 像掷骰子一样随便。","tr":{"zh":"我随便点了一道菜。","fr":"J'ai commandé un plat au hasard.","alt":"J'ai pris un plat un peu au hasard.","note":"au hasard 修饰动作；par hasard 说「碰巧」。"}},
 "Du coup": {"pos":"loc.adv. 副词短语（口语连接词）","s":"「所以、结果、这样一来」，口语里非常常用的结果连接词，放在句首或句中。比 donc 更随意，有时只是口头禅。","ipa":"[dy.ku]","ph":"du [dy]，u 读 [y]；coup 读 [ku]，p 不发音。","pi":"coup 的 p 不发音；du 的 u 是 [y]，不是 [u]。书面正式文章里一般用 donc。","et":"du = de + le；coup 本义是「一击、一下」。整体是固定口语搭配，字面「由这一下（而来）」。","ex":[["Il pleuvait, du coup nous sommes restés chez nous.","下雨了，所以我们待在家。"],["Du coup, on fait quoi ?","那现在我们怎么办？"]],"co":[["du coup, …","所以……；这样一来……"],["et du coup","于是，结果"],["du coup je n'ai pas pu venir","结果我没能来"]],"sy":[["donc","courant","所以；更通用、更正式"],["alors","courant","那么，于是"],["par conséquent","soutenu","因此（书面）"]],"fq":"极高频，日常口语。","me":"du coup = 因为这一下，所以……","tr":{"zh":"我错过了公交车，所以迟到了。","fr":"J'ai raté le bus, du coup je suis arrivé en retard.","alt":"J'ai raté le bus, alors je suis arrivé en retard.","note":"du coup 后面通常接结果。"}},
 "En détails": {"pos":"loc.adv. 副词短语（détail 阳性）","s":"「详细地、一项一项地」。更常见的写法是单数 en détail，两种拼写都可见。表示把每个细节都讲清楚。","ipa":"[ɑ̃.de.taj]","ph":"en [ɑ̃]；dé [de]；tail 读 [taj]，ail 是 [aj]；结尾 s 不发音。","pi":"détail 里的 ail 读 [aj]，不要读成 [ɛl]；结尾 s 不发音。en détail 和 en détails 发音相同。","et":"détail 来自动词 détailler（de- + tailler，切成小块）。","ex":[["Il m'a raconté l'histoire en détails.","他详细地给我讲了这件事。"],["Peux-tu m'expliquer le projet en détail ?","你能详细地给我讲讲这个项目吗？"]],"co":[["expliquer en détail","详细解释"],["raconter en détail","详细讲述"],["entrer dans les détails","深入细节"]],"sy":[["de façon détaillée","soutenu","详细地（更书面）"],["en gros","familier","大致上；反义"]],"fq":"高频，日常和书面都常用。","me":"dé-tail：把东西「切成小块」逐块说。","tr":{"zh":"请详细地给我解释一下。","fr":"Expliquez-moi ça en détail, s'il vous plaît.","alt":"Tu peux me détailler ça ?","note":"en détail 与 en détails 都对，单数更常用。"}},
 "Faire ses débuts": {"pos":"loc.v. 动词短语（faire 不规则；débuts 常用复数）","s":"「首次亮相、初次登台、起步」。用于演员、运动员、歌手、新人刚开始职业生涯。ses 随主语变：faire mes débuts, faire tes débuts…","ipa":"[fɛʁ.se.de.by]","ph":"faire [fɛʁ]，ai 读 [ɛ]；ses [se]，s 不发音；débuts [de.by]，u 读 [y]，ts 不发音。","pi":"débuts 要用复数，而且结尾 t、s 都不发音；u 是 [y]。faire 里的 ai 读 [ɛ]，不读 [e]。","et":"débuts 来自动词 débuter（de- + but，目标）：「离开起点、开始」。","ex":[["Elle va faire ses débuts sur scène.","她将首次登台。"],["Ce joueur a fait ses débuts à 18 ans.","这位球员 18 岁时首次亮相。"]],"co":[["faire ses débuts au cinéma","在电影中首次亮相"],["à ses débuts","在起步阶段"],["des débuts prometteurs","令人期待的开端"]],"sy":[["débuter","courant","开始，起步"],["se lancer","courant","投身，开始做"]],"fq":"中频，常见于新闻、体育和文化话题。","me":"début + s：第一次站到舞台上。","tr":{"zh":"这位年轻歌手明年首次登台。","fr":"Cette jeune chanteuse fera ses débuts sur scène l'an prochain.","alt":"Cette jeune chanteuse va monter sur scène pour la première fois l'an prochain.","note":"ses 要和主语一致；débuts 用复数。"}},
 "Faire un malheur !": {"pos":"loc.v. 动词短语（口语，faire 不规则）","s":"口语，「大获成功、一炮而红、引起轰动」。用于歌曲、产品、演出等。注意：在另一语境里也能字面指「闯祸、出大事」，要看语气和上下文。","ipa":"[fɛʁ.œ̃.ma.lœʁ]","ph":"faire un 连读为 [fɛ.ʁœ̃]；malheur [ma.lœʁ]，h 不发音，eu 读 [œ]；结尾 r 要发。","pi":"malheur 的 h 不发音；eu 读 [œ]（不是 [u]）。「faire un malheur」大多是好事，别当成倒霉。","et":"malheur = mal + heur（古法语，运气，来自拉丁语 augurium）；「坏运气」。这个短语的好义是后来口语发展出的用法。","ex":[["Ce nouveau produit va faire un malheur !","这个新产品会大卖！"],["Sa chanson a fait un malheur cet été.","他的歌今年夏天红极一时。"]],"co":[["faire un malheur","大获成功"],["ça va faire un malheur","这会大受欢迎"],["faire un tabac","大受欢迎（近义）"]],"sy":[["faire un tabac","familier","大获成功，意思相近"],["avoir un succès fou","courant","大获成功，更中性"]],"fq":"中低频，口语。","me":"malheur 本来是坏事，反着用：「红得吓人」。","tr":{"zh":"这首歌肯定会大红。","fr":"Cette chanson va faire un malheur.","alt":"Cette chanson va faire un tabac.","note":"口语；正式文章里用 avoir beaucoup de succès。"}},
 "Ne pas payer de mine": {"pos":"loc.v. 动词短语（payer 第一组，-ayer 动词）","s":"「其貌不扬、不起眼」：外表看起来一般，但实际很好或不错。常和 mais（但是）连用：Ça ne paie pas de mine, mais…。","ipa":"[nə.pa.pe.je.də.min]","ph":"ne [nə]；pas [pa]，s 不发音；payer [pe.je]；de [də]；mine [min]，结尾 e 不发音。","pi":"payer 有两种拼写：il paie / il paye，都对。mine 的 i 读 [i]，别读成英语 mine。","et":"mine 指「外表、神态」（来源不确定）；payer 来自拉丁语 pacare（使满意、平息），后指「付款」。整个短语：「外表不值钱」。","ex":[["Ce restaurant ne paye pas de mine mais c'est délicieux.","这家餐厅不起眼，但很好吃。"],["Cette maison ne paie pas de mine, mais elle est confortable.","这房子看起来一般，但很舒服。"]],"co":[["ne pas payer de mine","其貌不扬"],["avoir bonne mine","气色好"],["avoir mauvaise mine","脸色不好"]],"sy":[["avoir l'air modeste","courant","看起来朴素"],["faire simple","courant","看起来简单"]],"fq":"中频，口语。","me":"不用付出「外表的钱」= 看起来没价值，其实有。","tr":{"zh":"这家小店看起来不起眼，但东西很好吃。","fr":"Ce petit magasin ne paie pas de mine, mais tout est bon.","alt":"Il n'a l'air de rien, ce petit magasin, mais tout est bon.","note":"否定句里 de 后不加冠词：ne pas payer de mine。"}},
 "Prendre sous son aile": {"pos":"loc.v. 动词短语（prendre 第三组，不规则）","s":"「庇护、提携、照顾」：像鸟用翅膀护着雏鸟，指资深者带新人、保护弱者。son 随主语变：prendre sous mon aile, sous ton aile…。","ipa":"[pʁɑ̃dʁ.su.sɔ̃.nɛl]","ph":"prendre [pʁɑ̃dʁ]；sous [su]，s 不发音；son aile 连读成 [sɔ̃.nɛl]；aile 读 [ɛl]。","pi":"aile 是阴性（l'aile），但 son aile 因为元音开头用 son 而不是 sa。ai 读 [ɛ]。","et":"aile 来自拉丁语 ala（翼）。prendre 来自拉丁语 prehendere（抓住）。","ex":[["Le directeur l'a pris sous son aile.","主任提携了他。"],["Elle prend les nouveaux sous son aile.","她照顾新来的人。"]],"co":[["prendre quelqu'un sous son aile","把某人置于自己庇护之下"],["sous l'aile de quelqu'un","在某人的庇护下"],["un protégé / une protégée","被提携的人"]],"sy":[["protéger","courant","保护"],["parrainer","soutenu","做某人的引路人、担保人"]],"fq":"中低频，用于职场、学校。","me":"母鸟把雏鸟拢到翅膀下。","tr":{"zh":"老同事把我带在身边。","fr":"Un ancien collègue m'a pris sous son aile.","alt":"Un collègue plus expérimenté m'a pris en main.","note":"复合过去时：m'a pris；son 用于阴性元音开头词。"}},
 "Un smiley": {"pos":"n.m. 阳性名词，复数 smileys（也见 smilies）","s":"笑脸表情符号，如 :-) 或 😊。短信、聊天、邮件里常用。也可以说 un émoji；un émoticône 指用符号拼出的表情。","ipa":"[smaj.le]","ph":"smi 读 [smaj]，像英语 smile；ley 读 [le]。","pi":"借自英语，但读法是法语化的 [smajle]。复数是 smileys（或 smilies）。","et":"来自英语 smiley（smile 微笑 + -y），20 世纪后期进入法语。","ex":[["Il a ajouté un smiley à son message.","他在消息里加了个笑脸。"],["J'ai reçu un smiley pour toute réponse.","我得到的唯一回复是一个笑脸。"]],"co":[["envoyer un smiley","发一个笑脸"],["mettre un smiley","加一个笑脸"],["un smiley qui sourit","一个微笑的笑脸"]],"sy":[["un émoji","courant","表情符号（通称）"],["une émoticône","courant","用字符拼出的表情"]],"fq":"中频，网络聊天常用。","me":"smile + y：会笑的小脸。","tr":{"zh":"我在短信末尾加了个笑脸。","fr":"J'ai mis un smiley à la fin de mon message.","alt":"J'ai ajouté un petit smiley à mon SMS.","note":"mettre / ajouter un smiley à + 名词。"}},
 "Un cadre": {"pos":"n.m. 阳性名词，复数 cadres","s":"框架；画框；环境、背景。也指公司「管理人员」(un cadre)，也可以说 une cadre（女性）。dans le cadre de = 在……范围内、在……框架下。","ipa":"[kadʁ]","ph":"c 在 a 前读 [k]；结尾 -dre 读 [dʁ]，e 不发音，不是两个音节。","pi":"只有一个音节 [kadʁ]，别读成 ca-dre 两个音节。注意 un cadre 有「画框」和「管理人员」两个常见意思。","et":"借自意大利语 quadro，来自拉丁语 quadrum（方形）。","ex":[["La politesse est le cadre dans lequel on peut avoir une conversation.","礼貌是交谈得以进行的框架。"],["Il travaille comme cadre dans une banque.","他在银行当管理人员。"],["Le cadre de cette ville est magnifique.","这座城市的环境很美。"]],"co":[["dans le cadre de","在……框架内；作为……的一部分"],["un cadre photo","相框"],["un cadre supérieur","高级管理人员"],["le cadre de vie","居住环境"]],"sy":[["contexte","courant","背景、上下文"],["environnement","courant","环境"],["manager","familier","经理（借自英语）"]],"fq":"极高频，日常和职场都常用。","me":"quadro = 方形：框就是四条边围起来的方形。","tr":{"zh":"这次活动是在学校的框架下组织的。","fr":"Cet événement est organisé dans le cadre de l'école.","alt":"L'école organise cet événement dans son cadre habituel.","note":"dans le cadre de + 名词，常用于正式场合。"}},
 "Le respect": {"pos":"n.m. 阳性名词，复数 respects（很少用）","s":"尊重、敬意。respect de/pour + 人或事物：对……的尊重。le respect des règles = 遵守规则。也说 par respect pour… 出于对……的尊重。","ipa":"[ʁɛs.pɛ]","ph":"r 是小舌音 [ʁ]；e 读 [ɛ]；结尾 ct 不发音，所以 respect 读 [ʁɛspɛ]。","pi":"结尾的 c 和 t 都不发音，不是 [ʁɛspɛkt]。和英语 respect 拼写相同，读音不同。","et":"拉丁语 respectus（回头看、顾虑），来自 respicere。同源词：respecter, respectueux。","ex":[["Il faut montrer du respect aux aînés.","要尊敬长辈。"],["Le respect des règles est important.","遵守规则很重要。"]],"co":[["avoir du respect pour quelqu'un","尊重某人"],["manquer de respect à quelqu'un","对某人无礼"],["par respect pour","出于对……的尊重"],["le respect de l'environnement","对环境的尊重"]],"sy":[["considération","soutenu","敬重，看重"],["égard","soutenu","关照，敬意"],["irrespect","courant","反义：不尊重"]],"fq":"高频，日常和书面都常用。","me":"respect 的 ct 全哑，读起来像「雷斯佩」。","tr":{"zh":"对老师要有礼貌，要尊重他。","fr":"Il faut avoir du respect pour son professeur.","alt":"On doit respecter son professeur.","note":"avoir du respect pour + 人；du 是部分冠词。"}},
 "L'irrespect": {"pos":"n.m. 阳性名词，复数 irrespects（很少用）","s":"不尊重、无礼。比 le manque de respect 更书面，日常更常说 manquer de respect。形容词是 irrespectueux（不尊敬的）。","ipa":"[i.ʁɛs.pɛ]","ph":"l'i 缩合；ir 在这里读 [i.ʁ]，r 要发；re [ʁɛ]；结尾 ct 不发音。","pi":"ir- 的 r 和后面的 r 不是双写，读成 [i.ʁɛs.pɛ]；结尾 c 和 t 不发音。","et":"前缀 ir-（= in-，否定）+ respect（拉丁语 respectus）。前缀 in- 在 r 前变成 ir-。","ex":[["Je ne tolère pas l'irrespect.","我不能容忍不尊重。"],["Son irrespect envers les professeurs est inacceptable.","他对老师不敬，这无法接受。"]],"co":[["l'irrespect des règles","不遵守规则"],["un geste d'irrespect","一个无礼的举动"],["tolérer l'irrespect","容忍无礼"]],"sy":[["manque de respect","courant","缺乏尊重（更常说）"],["insolence","soutenu","傲慢无礼"]],"fq":"中低频，书面为主。","me":"ir-（不）+ respect（尊重）= 不尊重。","tr":{"zh":"他的无礼让我很生气。","fr":"Son irrespect m'a mis en colère.","alt":"Son manque de respect m'a vraiment énervé.","note":"日常口语常用 manque de respect 代替 irrespect。"}},
 "Un reproche": {"pos":"n.m. 阳性名词，复数 reproches","s":"责备、指责、埋怨（口头上说出来的不满）。faire un reproche à quelqu'un = 责备某人。语气比 critique（批评）更带个人情绪。","ipa":"[ʁə.pʁɔʃ]","ph":"re [ʁə]；pro 读 [pʁɔ]；ch 读 [ʃ]。","pi":"ch 读 [ʃ]，像「是」；o 是开口的 [ɔ]。别把 reproche 读成英语 reproach 的音。","et":"来自动词 reprocher；词源不确定，故记为同族词：reprocher（责备）。","ex":[["Il m'a fait un reproche justifié.","他对我的责备是有道理的。"],["Elle lui a fait des reproches sur son retard.","她为他迟到责备了他。"]],"co":[["faire un reproche à quelqu'un","责备某人"],["un reproche justifié","有道理的指责"],["sans reproche","无可指责"],["un ton de reproche","责备的语气"]],"sy":[["critique","courant","批评"],["blâme","soutenu","谴责"],["remarque","courant","意见，评语"]],"fq":"中频，日常和书面都有。","me":"re- + proche：把事情重新「拉近」到某人面前。","tr":{"zh":"我对他没有什么可责备的。","fr":"Je n'ai aucun reproche à lui faire.","alt":"Je n'ai rien à lui reprocher.","note":"faire un reproche à + 人；reprocher qqch à qqn 是动词形式。"}},
 "Un point de vue": {"pos":"n.m. 阳性名词，复数 points de vue（point 变复数，vue 不变）","s":"观点、看法、角度。du point de vue de… = 从……的角度看。也指字面上的视角，如一个观景点。","ipa":"[pwɛ̃.də.vy]","ph":"point 读 [pwɛ̃]，结尾 t 不发音；de [də]；vue 读 [vy]，u 读 [y]。","pi":"point 的 t 不发音；vue 的 u 是 [y]。复数写成 des points de vue，不是 point de vues。","et":"point（拉丁语 punctum，点）+ de + vue（voir 的名词形式）。","ex":[["Quel est ton point de vue sur la question ?","你对这个问题怎么看？"],["Du point de vue économique, c'est une bonne idée.","从经济角度看，这是个好主意。"]],"co":[["du point de vue de","从……的角度"],["changer de point de vue","改变看法"],["à mon point de vue","依我看"],["partager le point de vue de quelqu'un","赞同某人的观点"]],"sy":[["avis","courant","意见"],["opinion","courant","看法"],["perspective","soutenu","视角，前景"]],"fq":"极高频，日常和讨论时常用。","me":"point（点）+ vue（看）：你站的那个看的点。","tr":{"zh":"从我的角度看，这个计划不错。","fr":"De mon point de vue, ce plan est bon.","alt":"Pour moi, c'est un bon plan.","note":"de mon point de vue 放在句首作状语。"}},
 "Le savoir-vivre": {"pos":"n.m. 阳性名词，不变（一般不加复数）","s":"礼仪、教养、待人接物的规矩。指在社会上举止得体、懂得礼节。avoir du savoir-vivre = 有教养。","ipa":"[sa.vwaʁ.vivʁ]","ph":"sa [sa]；voir 读 [vwaʁ]；vivre [vivʁ]，结尾 -re 只发 [ʁ]，e 不发音。","pi":"由两个动词组成：savoir + vivre；写时要有连字符。vivre 只有一个音节 [vivʁ]。","et":"savoir（知道）+ vivre（生活）：「知道如何生活」。savoir 来自拉丁语 sapere，vivre 来自拉丁语 vivere。","ex":[["Le savoir-vivre est essentiel en société.","礼仪在社会中很重要。"],["Il manque de savoir-vivre, il parle trop fort.","他缺乏教养，说话太大声。"]],"co":[["avoir du savoir-vivre","有教养"],["manquer de savoir-vivre","缺乏教养"],["les règles du savoir-vivre","礼仪规矩"]],"sy":[["politesse","courant","礼貌"],["éducation","courant","教养（avoir de l'éducation）"],["étiquette","soutenu","礼节，宫廷礼仪"]],"fq":"中频，常用于谈社会礼节。","me":"知道（savoir）+ 生活（vivre）：知道怎么与人相处。","tr":{"zh":"他很有教养，总是说谢谢。","fr":"Il a du savoir-vivre, il dit toujours merci.","alt":"Il est bien élevé, il dit toujours merci.","note":"avoir du savoir-vivre；du = 部分冠词。"}},
 "Un tiers-lieux": {"pos":"n.m. 阳性名词（单数更规范写 un tiers-lieu，复数 des tiers-lieux）","s":"「第三空间」：既不是家，也不是工作单位的公共场所，如共享办公室、咖啡馆、社区空间、创客空间。近年在法国很常说，多用于社区和城市话题。","ipa":"[tjɛʁ.ljø]","ph":"tiers 读 [tjɛʁ]，ie 读 [jɛ]，s 不发音；lieux 读 [ljø]，x 不发音。","pi":"tiers 的 s 不发音；lieux 的 x 也不发音，且 eux 读 [ø]。单数 un tiers-lieu 与复数 des tiers-lieux 读音一样。","et":"tiers（第三，拉丁语 tertius）+ lieu（地方，拉丁语 locus）：「第三个地方」。概念来自社会学。","ex":[["C'est un tiers-lieu très animé.","这是个很热闹的第三空间。"],["Les tiers-lieux accueillent des artistes et des télétravailleurs.","第三空间接待艺术家和远程办公者。"]],"co":[["ouvrir un tiers-lieu","开一个第三空间"],["un tiers-lieu culturel","文化类第三空间"],["le tiers-lieu entre le travail et la maison","介于工作与家之间的空间"]],"sy":[["espace de coworking","courant","共享办公空间"],["lieu de rencontre","courant","聚会场所"]],"fq":"中低频，在新闻和社区话题里常见。","me":"家是第一个地方，公司是第二个，这里是第三个。","tr":{"zh":"我常常在附近的第三空间工作。","fr":"Je travaille souvent dans un tiers-lieu près de chez moi.","alt":"Je bosse souvent dans un tiers-lieu du quartier.","note":"单数写 tiers-lieu，有连字符。"}},
 "Un tiers": {"pos":"n.m. 阳性名词，复数 tiers","s":"三分之一；第三者、外人。un tiers de = 三分之一的……。注意：tiers 作名词时常指「第三方、局外人」，如 un tiers = une tierce personne。","ipa":"[tjɛʁ]","ph":"ti 读 [tj]；ers 读 [ɛʁ]；s 不发音，只发 r。","pi":"tiers 的 s 不发音：[tjɛʁ]，不要读成 [tjɛʁs]。分数「三分之一」是 un tiers，不是 un troisième。","et":"拉丁语 tertius（第三）。同源词：tierce（阴性），tiers-monde。","ex":[["Un tiers, c'est 1 divisé par 3.","三分之一就是一除以三。"],["Un tiers des élèves est absent.","三分之一的学生缺席。"]],"co":[["un tiers de + 名词","……的三分之一"],["les deux tiers","三分之二"],["un tiers payant","第三方付费（医保直接付款）"],["le tiers monde","第三世界"]],"sy":[["troisième","courant","第三（序数词）"],["tierce personne","soutenu","第三方"]],"fq":"高频，数学和日常都常见。","me":"tiers ← tertius：第三，三份中的一份。","tr":{"zh":"我把三分之一的工资存起来。","fr":"J'épargne un tiers de mon salaire.","alt":"Je mets un tiers de mon salaire de côté.","note":"un tiers de + 名词；「三分之一」就是 un tiers。"}},
 "Un accès": {"pos":"n.m. 阳性名词，复数 accès（单复数同形）","s":"通道、入口；进入的权利，也指「（病的）发作」。accès à + 名词 = 能够使用、到达。accès interdit = 禁止入内。","ipa":"[ak.sɛ]","ph":"cc 读 [ks]，因为后面是 e：ac-cès = [ak.sɛ]；è 读 [ɛ]；结尾 s 不发音。","pi":"两个 c 读 [ks]；结尾 s 不发音。单复数同形：un accès, des accès。","et":"拉丁语 accessus（接近），来自 accedere。同源词：accessible（可到达的）。","ex":[["L'accès est interdit.","禁止入内。"],["Tu as accès à internet ici ?","你在这里能上网吗？"],["Il a eu un accès de colère.","他发了一阵火。"]],"co":[["avoir accès à","能够进入、使用"],["donner accès à","使能够进入"],["un accès de colère / de fièvre","一阵怒火 / 发烧"],["facile d'accès","容易到达"]],"sy":[["entrée","courant","入口"],["passage","courant","通道"],["droit d'entrée","soutenu","进入权"]],"fq":"高频，日常和公共场所常见。","me":"accès：接近（ac-）+ 走（cès）：走近、能进去。","tr":{"zh":"你能进这栋楼吗？","fr":"Tu as accès à ce bâtiment ?","alt":"Tu peux entrer dans ce bâtiment ?","note":"avoir accès à + 名词。"}},
 "Un débat": {"pos":"n.m. 阳性名词，复数 débats","s":"辩论、讨论、争论。可以是电视上的正式辩论，也可以是朋友间的讨论。ouvrir le débat = 展开讨论；c'est un sujet de débat = 这是有争议的话题。","ipa":"[de.ba]","ph":"dé [de]；bat 读 [ba]，t 不发音。","pi":"结尾 t 不发音：[deba]。别写成 débas，也别读成英语 debate。","et":"来自动词 débattre（dé- + battre，击打、争斗）。","ex":[["Le débat était très animé.","辩论非常热烈。"],["Il y a un débat à la télévision ce soir.","今晚电视上有一场辩论。"]],"co":[["un débat public","公开辩论"],["ouvrir / clore le débat","开始 / 结束讨论"],["un débat animé","热烈的讨论"],["sujet à débat","有争议的"]],"sy":[["discussion","courant","讨论，较为平和"],["polémique","courant","争论，带火药味"],["controverse","soutenu","争议"]],"fq":"高频，日常和新闻都常用。","me":"dé + bat：你来我往地「打」嘴仗。","tr":{"zh":"我们昨天就这个话题展开了辩论。","fr":"Hier, nous avons eu un débat sur ce sujet.","alt":"On a débattu de ce sujet hier.","note":"avoir un débat sur + 话题；动词 débattre de。"}},
 "Le bien-être": {"pos":"n.m. 阳性名词，不变（复数罕用）","s":"幸福感、安适、福祉（身体和心理上感觉良好）。le bien-être des employés = 员工的福祉。也常用于 bien-être animal（动物福利）。","ipa":"[bjɛ̃.nɛtʁ]","ph":"bien 读 [bjɛ̃]；ê 读 [ɛ]；tre 读 [tʁ]。整体连着读，bien 与 être 之间会带出一个轻的 [n]：[bjɛ̃.nɛtʁ]。","pi":"bien 的鼻化韵母 [ɛ̃]，不要读出 n；写 bien-être 时有连字符，ê 有重音符。","et":"bien（副词，拉丁语 bene）+ être（动词，拉丁语 esse）：「好好地存在」。","ex":[["Le bien-être de mes employés est ma priorité.","员工的福祉是我的首要考虑。"],["Faire du sport améliore le bien-être.","运动能提高幸福感。"]],"co":[["le bien-être au travail","职场幸福感"],["le bien-être animal","动物福利"],["une sensation de bien-être","舒适感"],["un centre de bien-être","养生中心"]],"sy":[["confort","courant","舒适"],["santé","courant","健康"],["mal-être","courant","反义：不适、焦虑"]],"fq":"高频，健康和社会话题都很常见。","me":"bien + être = 好好地存在。","tr":{"zh":"他很重视孩子的幸福。","fr":"Il attache beaucoup d'importance au bien-être de ses enfants.","alt":"Le bien-être de ses enfants compte beaucoup pour lui.","note":"bien-être 要写连字符。"}},
 "Un écart": {"pos":"n.m. 阳性名词，复数 écarts","s":"差距、间隔、偏差。un écart d'âge = 年龄差。也指「失态、出格行为」：faire un écart。à l'écart = 在一旁、远离。","ipa":"[e.kaʁ]","ph":"é 读 [e]；car 读 [kaʁ]；结尾 t 不发音，r 要发。","pi":"结尾 t 不发音：[ekaʁ]，不要把 t 读出来。和 écharpe（围巾）无关。","et":"来自动词 écarter（把……分开）。词源细节不确定，故记为同族词：écarter, à l'écart。","ex":[["Il y a un grand écart d'âge entre eux.","他们年龄差很大。"],["Il reste à l'écart des autres.","他离其他人远远的。"]],"co":[["un écart d'âge / de prix","年龄差 / 价格差"],["à l'écart (de)","在一旁；远离"],["faire un écart","出格；突然拐弯"],["l'écart entre A et B","A 和 B 之间的差距"]],"sy":[["différence","courant","差别"],["distance","courant","距离"],["fossé","courant","鸿沟"]],"fq":"高频，在数据和社会话题里常见。","me":"é-car-t：像把两样东西拉开一段距离。","tr":{"zh":"两家商店的价格差别很大。","fr":"Il y a un gros écart de prix entre ces deux magasins.","alt":"Les prix sont très différents entre ces deux magasins.","note":"un écart de + 名词；un écart entre A et B。"}},
 "Un organisme": {"pos":"n.m. 阳性名词，复数 organismes","s":"机构、组织（官方或公益性质）；也指生物体、有机体。un organisme public = 公共机构；un organisme vivant = 生物。","ipa":"[ɔʁ.ga.nism]","ph":"or 读 [ɔʁ]；ga [ga]；nisme 读 [nism]，结尾 e 不发音。","pi":"结尾 -isme 读 [ism]，e 不发音。g 在 a 前读 [g]。别和 organisation（组织、活动）混淆：organisme 更偏向「机构」。","et":"来自 organe（拉丁语 organum，器官）+ 后缀 -isme。","ex":[["Cet organisme français produit des statistiques.","这家法国机构制作统计数据。"],["Le corps humain est un organisme complexe.","人体是一个复杂的有机体。"]],"co":[["un organisme public","公共机构"],["un organisme de formation","培训机构"],["un organisme vivant","生物体"],["un organisme de crédit","信贷机构"]],"sy":[["institution","courant","机构，机关"],["organisation","courant","组织"],["établissement","courant","单位，机构"]],"fq":"中高频，新闻和行政文件里常见。","me":"organ + isme：有各种「器官」分工协作的整体。","tr":{"zh":"这个机构帮助年轻人找工作。","fr":"Cet organisme aide les jeunes à trouver un emploi.","alt":"Cet organisme aide les jeunes à chercher du travail.","note":"aider qqn à + 动词原形。"}},
 "Le corps enseignant": {"pos":"n.m. 阳性名词（集体名词，复数 corps enseignants 少用）","s":"教师队伍、全体教师（作为一个群体）。指一所学校或整个教育系统的教师。le corps = 团体、群体。","ipa":"[kɔʁ.ɑ̃.sɛ.ɲɑ̃]","ph":"corps 读 [kɔʁ]，p、s 不发音；enseignant 读 [ɑ̃.sɛ.ɲɑ̃]，gn 读 [ɲ]，ant 读 [ɑ̃]。","pi":"corps 的 ps 不发音；enseignant 的 gn 读 [ɲ]（像「尼」），-ant 读鼻化 [ɑ̃]，t 不发音。","et":"corps（拉丁语 corpus，身体、团体）+ enseignant（enseigner 的现在分词，教）。","ex":[["Le corps enseignant est en grève.","教师队伍在罢工。"],["Le corps enseignant de cette école est très compétent.","这所学校的教师队伍很专业。"]],"co":[["le corps enseignant","教师队伍"],["le corps médical","医务人员"],["le corps diplomatique","外交使团"]],"sy":[["les enseignants","courant","教师们"],["le personnel enseignant","soutenu","教职员工"]],"fq":"中频，新闻和教育话题里常见。","me":"corps = 一个整体；全体老师是一个「教学之体」。","tr":{"zh":"全体教师都参加了这次会议。","fr":"Tout le corps enseignant a participé à la réunion.","alt":"Tous les profs ont participé à la réunion.","note":"corps enseignant 是单数，动词也用单数。"}},
 "Un droit": {"pos":"n.m. 阳性名词，复数 droits","s":"权利；法律（le droit）；费用、税（les droits d'inscription）。avoir le droit de + 动词原形 = 有权做某事、被允许。别和形容词 droit（直的）混淆。","ipa":"[dʁwa]","ph":"d 加 r 连读 [dʁ]；oi 读 [wa]；结尾 t 不发音。","pi":"结尾 t 不发音：[dʁwa]。也别和 droite（右边）搞混，droit 没有 e。","et":"拉丁语 directum（直的，法律上的）。同源词：direct, diriger。","ex":[["L'éducation est un droit fondamental.","教育是一项基本权利。"],["Tu as le droit de dire non.","你有权说不。"]],"co":[["avoir le droit de + inf.","有权……；被允许"],["les droits de l'homme","人权"],["un droit fondamental","基本权利"],["faire son droit","学法律"]],"sy":[["autorisation","courant","许可"],["liberté","courant","自由"],["devoir","courant","反义：义务"]],"fq":"极高频，日常和法律语境都常用。","me":"droit = 直 = 正当的：「站得直」的权利。","tr":{"zh":"每个孩子都有权上学。","fr":"Chaque enfant a le droit d'aller à l'école.","alt":"Tous les enfants ont droit à l'école.","note":"avoir le droit de + 原形；avoir droit à + 名词。"}},
 "Un devoir": {"pos":"n.m. 阳性名词，复数 devoirs","s":"义务、责任；作业（les devoirs，常用复数）；考试、书面作业（un devoir）。faire ses devoirs = 做作业。注意 devoir 同时是动词（必须、应该）。","ipa":"[də.vwaʁ]","ph":"de 读 [də]；voir 读 [vwaʁ]，oi 读 [wa]，r 要发。","pi":"做「作业」时通常用复数 les devoirs；表示「义务」时常用单数。结尾的 r 要发音。","et":"来自动词 devoir（拉丁语 debere，欠、应该）。同源词：dette（债）。","ex":[["C'est mon devoir de t'aider.","帮助你是我的责任。"],["J'ai beaucoup de devoirs ce soir.","我今晚有很多作业。"]],"co":[["faire ses devoirs","做作业"],["un devoir de + 名词","……的义务"],["avoir le devoir de + inf.","有义务做……"],["les droits et les devoirs","权利与义务"]],"sy":[["obligation","courant","义务，强制"],["responsabilité","courant","责任"],["tâche","courant","任务"]],"fq":"极高频，日常和学校语境都常用。","me":"devoir：你「欠」的东西，也是你该做的事。","tr":{"zh":"我得先做完作业才能出去。","fr":"Je dois finir mes devoirs avant de sortir.","alt":"Je finis mes devoirs d'abord, puis je sors.","note":"作业用复数：mes devoirs。"}},
 "Un concept": {"pos":"n.m. 阳性名词，复数 concepts","s":"概念、理念。也用于商业，如产品或店铺的设计理念、定位：un nouveau concept de restaurant。","ipa":"[kɔ̃.sɛpt]","ph":"con 读鼻化 [kɔ̃]；cept 读 [sɛpt]，这里 p 和 t 都要发。","pi":"词尾 -pt 要发音 [pt]，不同于 compter（数）里的 p 不发音。别和 concert（音乐会）混淆。","et":"拉丁语 conceptus（概念），来自 concipere（理解，怀胎）。同源词：concevoir, conception。","ex":[["C'est un concept difficile à comprendre.","这是个难以理解的概念。"],["Ce restaurant a un concept original.","这家餐厅的定位很独特。"]],"co":[["un concept clair","清晰的概念"],["le concept de + 名词","……这个概念"],["un concept original","独特的理念"]],"sy":[["idée","courant","想法"],["notion","courant","概念，观念"],["principe","courant","原理，原则"]],"fq":"高频，学术和商业常用。","me":"con-cept：concevoir（构想）的名词。","tr":{"zh":"这是个很有意思的概念。","fr":"C'est un concept très intéressant.","alt":"Ce concept est vraiment intéressant.","note":"concept 的 pt 要发音。"}},
 "Un acte": {"pos":"n.m. 阳性名词，复数 actes","s":"行为、举动；（戏剧的）一幕；证书、文书（un acte de naissance = 出生证明）。les actes = 行动（与 les paroles 言语相对）。","ipa":"[akt]","ph":"a [a]；ct 读 [kt]，c 和 t 都要发；结尾 e 不发音。","pi":"ct 要发 [kt]，不要省略；一个音节。别和 action（行动、动作）混淆：acte 强调具体的一个行为。","et":"拉丁语 actus（行动、一幕），来自 agere（做）。同源词：action, acteur。","ex":[["Il ne faut pas que les paroles contredisent les actes.","言行不能自相矛盾。"],["C'était un acte courageux.","那是一个勇敢的举动。"]],"co":[["un acte de courage","勇敢的举动"],["un acte de naissance","出生证明"],["passer à l'acte","付诸行动"],["prendre acte de","确认；记录下"]],"sy":[["action","courant","行动，动作"],["geste","courant","举动，姿势"],["fait","courant","事实，行为"]],"fq":"高频，日常和法律语境都有。","me":"acte = act（做）：做出来的那件事。","tr":{"zh":"这是一个很善良的举动。","fr":"C'est un acte très gentil.","alt":"C'est vraiment un geste gentil.","note":"un acte + 形容词；形容词放在名词后。"}},
 "Un raisonnement": {"pos":"n.m. 阳性名词，复数 raisonnements","s":"推理、推论；论证过程。指从前提到结论的思路。un raisonnement logique = 合乎逻辑的推理；un raisonnement faux = 错误的推理。","ipa":"[ʁɛ.zɔn.mɑ̃]","ph":"rai 读 [ʁɛ]；s 在元音间读 [z]；on 读 [ɔn]（后面跟 n，不鼻化）；-ment 读 [mɑ̃]。","pi":"raisonn- 里 on 后面有双写的 nn，所以读 [ɔn] 而不是鼻化 [ɔ̃]；-ment 读 [mɑ̃]，t 不发音。","et":"来自动词 raisonner（raison 理性 + -er），再加后缀 -ment。raison 来自拉丁语 ratio。","ex":[["Son raisonnement est très clair.","他的推理很清晰。"],["Je ne suis pas ton raisonnement.","我没跟上你的思路。"]],"co":[["un raisonnement logique","逻辑推理"],["suivre un raisonnement","跟上思路"],["un raisonnement faux","错误的推理"],["un raisonnement par l'absurde","反证法"]],"sy":[["logique","courant","逻辑"],["argument","courant","论点"],["démonstration","soutenu","论证"]],"fq":"中频，学习和讨论时常用。","me":"raison（理性）+ nement：把「理性」走一遍。","tr":{"zh":"我不同意你的推理。","fr":"Je ne suis pas d'accord avec votre raisonnement.","alt":"Ton raisonnement ne me convainc pas.","note":"être d'accord avec + 名词。"}},
 "Un fossile": {"pos":"n.m. 阳性名词，复数 fossiles","s":"化石。比喻义（口语）：「老古董」，指过时的人或事物。形容词：fossile（化石的），如 énergie fossile = 化石能源。","ipa":"[fɔ.sil]","ph":"fo 读 [fɔ]；ss 读 [s]；ile 读 [il]，e 不发音。","pi":"ss 读 [s]；结尾 -ile 读 [il]，l 要发。别和 facile 混淆。","et":"拉丁语 fossilis（挖出来的），来自 fodere（挖）。","ex":[["Les enfants ont trouvé un fossile.","孩子们找到了一块化石。"],["Le charbon est un combustible fossile.","煤是一种化石燃料。"]],"co":[["un fossile de dinosaure","恐龙化石"],["les énergies fossiles","化石能源"],["un combustible fossile","化石燃料"]],"sy":[["vestige","soutenu","遗迹"],["dinosaure","familier","（喻）老古董"]],"fq":"中频，科学和能源话题里常见。","me":"fossile：从地里「挖」出来的东西（fosse 坑）。","tr":{"zh":"博物馆里有很多恐龙化石。","fr":"Il y a beaucoup de fossiles de dinosaures dans ce musée.","alt":"Ce musée expose beaucoup de fossiles de dinosaures.","note":"fossiles de dinosaures：de + 名词复数。"}},
 "Un manuel scolaire": {"pos":"n.m. 阳性名词，复数 manuels scolaires","s":"教科书（学校用书）。也可简称 un manuel。manuel 还可作形容词，意为「手工的」：travail manuel（体力劳动）。","ipa":"[ma.nɥɛl.skɔ.lɛʁ]","ph":"manuel 读 [ma.nɥɛl]，ue 读 [ɥɛ]；scolaire 读 [skɔ.lɛʁ]，sc 读 [sk]，aire 读 [ɛʁ]。","pi":"scolaire 里 sc 读 [sk]，不是 [s]；manuel 里 u 读半元音 [ɥ]。","et":"manuel 来自拉丁语 manualis（手的，手边的），manus 是「手」；scolaire 来自 école（学校）一系，拉丁语 schola。","ex":[["Les élèves doivent acheter ce manuel scolaire.","学生们必须买这本教科书。"],["J'ai oublié mon manuel scolaire à la maison.","我把教科书忘在家里了。"]],"co":[["un manuel de français","法语课本"],["un manuel d'utilisation","使用说明书"],["ouvrir son manuel à la page 10","把课本翻到第 10 页"]],"sy":[["livre de classe","courant","课本"],["manuel","courant","教材（简称）"],["bouquin","familier","书（口语）"]],"fq":"中频，学校语境常见。","me":"manuel = 手边的书（manus 手）。","tr":{"zh":"请把教科书翻到第十页。","fr":"Ouvrez votre manuel scolaire à la page dix.","alt":"Ouvrez votre livre à la page 10.","note":"祈使句 ouvrez；à la page + 数字。"}},
 "Un rôle": {"pos":"n.m. 阳性名词，复数 rôles","s":"角色（戏剧、电影）；作用；职责。jouer un rôle = 扮演角色，也可以指起作用。le rôle de = ……的作用。","ipa":"[ʁol]","ph":"r 是小舌音 [ʁ]；ô 读 [o]；l 要发。","pi":"ô 有长音符，读 [o]；别和 roule（滚动）混淆。","et":"来自古法语 rolle，指写着演员台词的纸卷（rouleau），后来指演员所演的「角色」。","ex":[["Il joue un rôle important dans le film.","他在电影里扮演重要角色。"],["Le rôle des parents est essentiel.","父母的作用至关重要。"]],"co":[["jouer un rôle","扮演角色；起作用"],["le rôle principal","主角"],["un jeu de rôle","角色扮演游戏"],["le rôle de + 名词","……的作用、职责"]],"sy":[["personnage","courant","人物（故事中的）"],["fonction","courant","职能"],["mission","courant","任务"]],"fq":"极高频，日常常用。","me":"rôle ← rouleau：演员手里的「台词卷」。","tr":{"zh":"老师在孩子的成长中起着重要作用。","fr":"Le professeur joue un rôle important dans la vie des enfants.","alt":"Les profs comptent beaucoup dans la vie des enfants.","note":"jouer un rôle dans + 名词。"}},
 "L'ADN": {"pos":"n.m. 阳性名词，缩写词，无复数","s":"DNA（脱氧核糖核酸），法语缩写 ADN (acide désoxyribonucléique)。可喻指「基本特质、核心价值」：l'ADN d'une entreprise。","ipa":"[a.de.ɛn]","ph":"逐个字母读：A [a]、D [de]、N [ɛn]；L' 缩合。","pi":"法语缩写是 ADN，不是英语的 DNA。读成字母名：a-dé-èn。","et":"acide désoxyribonucléique 的缩写：acide（酸）+ désoxyribo-（脱氧核糖）+ nucléique（核的）。","ex":[["L'ADN est unique pour chaque individu.","每个人的 DNA 都是独一无二的。"],["Le test ADN a confirmé leur lien de parenté.","DNA 检测证实了他们的亲属关系。"]],"co":[["un test ADN","DNA 检测"],["l'ADN d'une entreprise","一家公司的基因（核心特质）"],["analyser l'ADN","分析 DNA"]],"sy":[["gène","courant","基因（不同于 DNA 整体）"],["génome","soutenu","基因组"]],"fq":"中频，科学和新闻里常见。","me":"ADN = DNA 倒过来：A-D-N。","tr":{"zh":"警察用 DNA 找到了小偷。","fr":"La police a trouvé le voleur grâce à l'ADN.","alt":"Grâce à l'ADN, la police a retrouvé le voleur.","note":"grâce à + 名词，表示好的原因。"}},
 "Un hypermarché": {"pos":"n.m. 阳性名词，复数 hypermarchés","s":"大型超市（面积很大，有食品、日用品、衣服等）。比 supermarché 更大，通常在市郊。口语常简称 un hyper。","ipa":"[i.pɛʁ.maʁ.ʃe]","ph":"hy 读 [i]，h 不发音；per 读 [pɛʁ]；mar 读 [maʁ]；ché 读 [ʃe]。","pi":"hy 读 [i]；ch 读 [ʃ]。结尾是 é，读 [e]，不要漏掉重音符。","et":"希腊语前缀 hyper-（超过）+ marché（市场，拉丁语 mercatus）。","ex":[["Je fais mes courses dans un hypermarché.","我在大型超市购物。"],["L'hypermarché est ouvert jusqu'à 22 heures.","大型超市营业到晚上十点。"]],"co":[["faire ses courses à l'hypermarché","去大型超市买东西"],["un hypermarché en périphérie","郊区的大型超市"],["un caddie d'hypermarché","大超市的购物车"]],"sy":[["supermarché","courant","超市（较小）"],["grande surface","courant","大型商场"],["épicerie","courant","杂货店（更小）"]],"fq":"中频，购物时常说。","me":"hyper（超级）+ marché（市场）= 超级市场。","tr":{"zh":"周末我们去大型超市买东西。","fr":"Le week-end, on va faire les courses à l'hypermarché.","alt":"Ce week-end, on va à l'hyper faire les courses.","note":"faire les courses = 购物。"}},
 "Le principe": {"pos":"n.m. 阳性名词，复数 principes","s":"原则、原理、准则。en principe = 原则上、按理说；par principe = 出于原则；une question de principe = 原则问题。","ipa":"[pʁɛ̃.sip]","ph":"pr [pʁ]；in 读鼻化 [ɛ̃]；ci 读 [si]；pe 读 [p]，e 不发音。","pi":"结尾 -pe 读 [p]，e 不发音；in 读鼻化 [ɛ̃]，不是 [in]。","et":"拉丁语 principium（开始，起源），来自 princeps（第一的）。同源词：prince, principal。","ex":[["C'est une question de principe.","这是原则问题。"],["En principe, le magasin ouvre à neuf heures.","按理说，商店九点开门。"]],"co":[["en principe","原则上；按理说"],["par principe","出于原则"],["un principe de base","基本原则"],["avoir des principes","有原则"]],"sy":[["règle","courant","规则"],["valeur","courant","价值观"],["loi","courant","法则"]],"fq":"高频，日常和书面都常用。","me":"principe ← princeps：最先的东西，最根本的规则。","tr":{"zh":"我出于原则不接受这个提议。","fr":"Par principe, je refuse cette proposition.","alt":"Je dis non, par principe.","note":"par principe + 句子，表示理由。"}},
 "Un article": {"pos":"n.m. 阳性名词，复数 articles","s":"物品、商品；文章（报纸、网络）；语法里的冠词；法律条文。具体意思要看语境：un article de journal = 报纸文章；un article de sport = 运动用品。","ipa":"[aʁ.tikl]","ph":"ar 读 [aʁ]；ti 读 [ti]；cle 读 [kl]，e 不发音，不是单独的音节。","pi":"结尾 -cle 读 [kl]，e 不发音。别按英语 article 读 [ɑːtɪkl]。","et":"拉丁语 articulus（小关节、部分），是 artus（关节）的指小词。","ex":[["Je pose mes articles à la caisse.","我把商品放在收银台。"],["J'ai lu un article intéressant sur ce sujet.","我读了一篇关于这个话题的有趣文章。"]],"co":[["un article de journal","报纸文章"],["un article de sport","运动用品"],["l'article défini / indéfini","定冠词 / 不定冠词"],["à l'article 3","根据第 3 条"]],"sy":[["produit","courant","产品"],["objet","courant","物品"],["texte","courant","文本"]],"fq":"极高频，日常和购物都常用。","me":"article：一件一件分开的「小关节」。","tr":{"zh":"这件商品现在打折。","fr":"Cet article est en solde en ce moment.","alt":"Cet article est en promo en ce moment.","note":"être en solde = 打折。"}},
 "Un contre-pied": {"pos":"n.m. 阳性名词，复数 contre-pieds","s":"反着来、对立的做法；出其不意。prendre qqn à contre-pied = 打人一个措手不及（原指足球里让守门员或对手判断错方向）。prendre le contre-pied de = 取相反的立场或做法。","ipa":"[kɔ̃tʁ.pje]","ph":"contre 读 [kɔ̃tʁ]，on 鼻化，e 不发音；pied 读 [pje]，d 不发音。","pi":"pied 的 d 不发音：[pje]；contre 的 e 不发音，读 [kɔ̃tʁ]。","et":"contre（拉丁语 contra，相反）+ pied（拉丁语 pes，脚）：「踩反的脚」。","ex":[["Il a pris tout le monde à contre-pied.","他打了所有人一个措手不及。"],["Elle a pris le contre-pied de ce qu'on attendait.","她做了与大家预期完全相反的事。"]],"co":[["prendre à contre-pied","使措手不及"],["prendre le contre-pied de","与……反着来"],["à contre-pied","反方向地"]],"sy":[["opposé","courant","相反的"],["contraire","courant","相反"],["surprendre","courant","使惊讶"]],"fq":"中低频，体育和报道里常见。","me":"contre（反）+ pied（脚）：踩错脚，被带得反方向走。","tr":{"zh":"这个决定让所有人都措手不及。","fr":"Cette décision a pris tout le monde à contre-pied.","alt":"Cette décision a surpris tout le monde.","note":"prendre qqn à contre-pied。"}},
 "Le temps libre": {"pos":"n.m. 阳性名词，不加复数","s":"空闲时间、业余时间。pendant mon temps libre = 在我的空闲时间。也说 le temps de loisir。","ipa":"[tɑ̃.libʁ]","ph":"temps 读 [tɑ̃]，ps 不发音；libre 读 [libʁ]，e 不发音，只有一个音节。","pi":"temps 的 ps 不发音；libre 的 -re 里 e 不发音。别写成 le tant libre。","et":"temps（拉丁语 tempus）+ libre（拉丁语 liber，自由）。","ex":[["Que fais-tu pendant ton temps libre ?","你空闲时间做什么？"],["Je n'ai pas beaucoup de temps libre.","我没有多少空闲时间。"]],"co":[["pendant son temps libre","在空闲时间"],["avoir du temps libre","有空闲时间"],["occuper son temps libre","打发空闲时间"]],"sy":[["loisirs","courant","休闲活动"],["moment libre","courant","空闲时刻"],["temps perso","familier","个人时间"]],"fq":"高频，日常常用。","me":"时间（temps）+ 自由（libre）= 自由的时间。","tr":{"zh":"我空闲时间喜欢读书。","fr":"Pendant mon temps libre, j'aime lire.","alt":"Quand j'ai du temps libre, je lis.","note":"pendant + 名词表示一段时间。"}},
 "Le nettoyage": {"pos":"n.m. 阳性名词，复数 nettoyages","s":"清洁、清扫。le nettoyage de printemps = 春季大扫除。也用于 nettoyage à sec（干洗）。动词是 nettoyer。","ipa":"[nɛ.twa.jaʒ]","ph":"net 读 [nɛ]；t 与 oy 连成 [twa]；oy 读 [waj]，后半 [j] 与 -age 连成 [jaʒ]；g 在 e 前读 [ʒ]。","pi":"oy 读 [waj]：nettoyage = [nɛ.twa.jaʒ]。别把 t 省略；ge 读 [ʒ]，不读 [g]。","et":"nettoyer（net 干净，拉丁语 nitidus）+ 后缀 -age。","ex":[["Le nettoyage de printemps est terminé.","春季大扫除结束了。"],["Le nettoyage des vitres prend du temps.","擦窗户很费时间。"]],"co":[["le nettoyage de printemps","春季大扫除"],["un produit de nettoyage","清洁用品"],["le nettoyage à sec","干洗"],["une entreprise de nettoyage","保洁公司"]],"sy":[["ménage","courant","家务清洁"],["lavage","courant","洗，清洗"],["propreté","courant","干净"]],"fq":"中高频，日常常用。","me":"net（干净）+ oyer + age：把东西变干净的过程。","tr":{"zh":"大扫除要花一整天。","fr":"Le grand nettoyage prend toute la journée.","alt":"Le ménage de printemps dure toute la journée.","note":"toute la journée = 一整天。"}},
 "Le bénévolat": {"pos":"n.m. 阳性名词，不加复数","s":"志愿服务、义工活动（不拿报酬，通常在协会、公益组织）。faire du bénévolat = 做志愿者。人是 un bénévole / une bénévole。","ipa":"[be.ne.vɔ.la]","ph":"bé [be]；né [ne]；vo 读 [vɔ]；la 读 [la]；结尾 t 不发音。","pi":"结尾 -at 的 t 不发音：[la]。bénévolat 和 bénévole（志愿者）发音相近但词尾不同。","et":"bénévole（拉丁语 benevolus，好意的：bene 好 + velle 愿意）+ 后缀 -at。","ex":[["Elle fait du bénévolat le week-end.","她周末做志愿服务。"],["Le bénévolat aide beaucoup les associations.","志愿服务对协会帮助很大。"]],"co":[["faire du bénévolat","做志愿服务"],["travailler comme bénévole","做志愿者"],["une association de bénévoles","志愿者协会"]],"sy":[["volontariat","courant","志愿服务（更长期、有框架）"],["engagement associatif","soutenu","参与公益活动"]],"fq":"中频，社会话题里常见。","me":"bene（好）+ vol（想要）：好心、自愿。","tr":{"zh":"我每周六做志愿服务。","fr":"Je fais du bénévolat tous les samedis.","alt":"Tous les samedis, je suis bénévole dans une association.","note":"faire du bénévolat；du = 部分冠词。"}},
 "Le volontariat": {"pos":"n.m. 阳性名词，不加复数","s":"志愿服务；志愿者身份（常指有固定期限、有简单补贴的长期志愿工作，如国际志愿者 VIE）。和 bénévolat 区别：bénévolat 完全无报酬，volontariat 常有正式身份。","ipa":"[vɔ.lɔ̃.ta.ʁja]","ph":"vo 读 [vɔ]；lon 读鼻化 [lɔ̃]；ta 读 [ta]；riat 读 [ʁja]，结尾 t 不发音。","pi":"结尾 -iat 读 [ja]，t 不发音；on 读鼻化，不要读出 n。","et":"volontaire（拉丁语 voluntarius，自愿的，来自 voluntas 意愿）+ 后缀 -at。","ex":[["Il s'est engagé dans le volontariat international.","他参与了国际志愿服务。"],["Le volontariat dure souvent un an.","志愿服务期通常是一年。"]],"co":[["le volontariat international","国际志愿服务"],["s'engager dans le volontariat","投身志愿服务"],["un contrat de volontariat","志愿服务合同"]],"sy":[["bénévolat","courant","义务工作（完全无偿）"],["volontaire","courant","志愿者（人）"]],"fq":"中低频，行政和社会话题里出现。","me":"volontaire（自愿的人）+ -at：自愿者的状态。","tr":{"zh":"他想在国外做一年志愿者。","fr":"Il veut faire un an de volontariat à l'étranger.","alt":"Il veut partir un an à l'étranger comme volontaire.","note":"faire un an de + 名词。"}},
 "Un emploi du temps": {"pos":"n.m. 阳性名词，复数 emplois du temps（emploi 变复数，du temps 不变）","s":"日程表、课程表、时间安排。学校的课表也是 un emploi du temps。avoir un emploi du temps chargé = 日程很满。","ipa":"[ɑ̃.plwa.dy.tɑ̃]","ph":"em 读鼻化 [ɑ̃]；ploi 读 [plwa]；du [dy]；temps 读 [tɑ̃]，ps 不发音。","pi":"emploi 的 oi 读 [wa]；temps 的 ps 不发音。复数是 des emplois du temps。","et":"emploi（employer 的名词，拉丁语 implicare）+ du temps：「时间的运用」。","ex":[["Mon emploi du temps est très chargé.","我的日程很满。"],["Voici l'emploi du temps de la semaine.","这是这一周的课程表。"]],"co":[["un emploi du temps chargé","满满当当的日程"],["organiser son emploi du temps","安排自己的时间"],["changer l'emploi du temps","调整日程"],["l'emploi du temps scolaire","学校课表"]],"sy":[["agenda","courant","日程本、日程"],["planning","courant","计划表"],["calendrier","courant","日历"]],"fq":"高频，学校和工作中常用。","me":"emploi（使用）+ du temps（时间）：怎么用时间。","tr":{"zh":"我的课程表这周变了。","fr":"Mon emploi du temps a changé cette semaine.","alt":"J'ai un nouvel emploi du temps cette semaine.","note":"emploi du temps 也指课表。"}},
 "Un créneau": {"pos":"n.m. 阳性名词，复数 créneaux（-eau 复数加 x）","s":"时间段、空档（预约用的）；（城堡墙上的）垛口；一种倒车入位的停车方式（faire un créneau = 侧方停车）。","ipa":"[kʁe.no]","ph":"cré 读 [kʁe]；neau 读 [no]，eau 读 [o]。","pi":"复数是 créneaux，不是 créneaus；eau 读 [o]。","et":"来自 crenel（城墙上的缺口），后来引申为「缺口、空档」。同源词：créneler。","ex":[["J'ai un créneau libre à 14h.","我下午两点有空档。"],["Il a fait un créneau pour se garer.","他侧方停车。"]],"co":[["un créneau horaire","时间段"],["un créneau libre","空档"],["faire un créneau","侧方停车"],["trouver un créneau","找到合适的时段"]],"sy":[["plage horaire","courant","时间段"],["rendez-vous","courant","约会，预约"],["disponibilité","soutenu","空闲"]],"fq":"高频，预约和日程中常用。","me":"城墙上的缺口：日程里的一个缺口。","tr":{"zh":"你明天有空档吗？","fr":"Tu as un créneau demain ?","alt":"T'es libre à un moment demain ?","note":"avoir un créneau：有可用时段。"}},
 "Un employé municipal": {"pos":"n.m. 阳性名词（阴性 une employée municipale），复数 employés municipaux","s":"市政人员、市政府雇员（在市政厅或城市部门工作，如清洁工、园艺工、办事员）。municipal 的阳性复数不规则：municipaux。","ipa":"[ɑ̃.plwa.je.my.ni.si.pal]","ph":"employé 读 [ɑ̃.plwa.je]；municipal 读 [my.ni.si.pal]，u 读 [y]。","pi":"employé 的 oy 读 [waj]，é 读 [e]；municipal 复数是 municipaux，不是 municipals。","et":"employé（employer，拉丁语 implicare）+ municipal（拉丁语 municipalis，来自 municipium 自治市）。","ex":[["Un employé municipal nettoie la rue.","一位市政员工在打扫街道。"],["Les employés municipaux sont en grève.","市政人员在罢工。"]],"co":[["un employé de mairie","市政厅职员"],["les employés municipaux","市政人员"],["la police municipale","市政警察"]],"sy":[["agent municipal","courant","市政工作人员"],["fonctionnaire","courant","公务员"]],"fq":"中频，新闻和日常对话里出现。","me":"employé（雇员）+ municipal（城市的）。","tr":{"zh":"市政人员每天早上清扫街道。","fr":"Les employés municipaux nettoient la rue tous les matins.","alt":"Tous les matins, des agents de la mairie nettoient la rue.","note":"municipal 的复数是 municipaux。"}},
 "Un antidépresseur": {"pos":"n.m. 阳性名词，复数 antidépresseurs","s":"抗抑郁药。医学用语，药物名。常在医生处方下使用：prescrire un antidépresseur = 开抗抑郁药。","ipa":"[ɑ̃.ti.de.pʁɛ.sœʁ]","ph":"an 读 [ɑ̃]；ti 读 [ti]；dé [de]；pres 读 [pʁɛ]；seur 读 [sœʁ]，ss 读 [s]。","pi":"an- 读 [ɑ̃]，不是 [an]；-esseur 读 [ɛsœʁ]；ss 读 [s]。","et":"anti-（希腊语 anti，反对）+ dépresseur（déprimer 的施动词，拉丁语 deprimere）。","ex":[["Le médecin lui a prescrit un antidépresseur.","医生给他开了抗抑郁药。"],["Elle prend un antidépresseur depuis un mois.","她吃抗抑郁药已经一个月了。"]],"co":[["prendre un antidépresseur","服用抗抑郁药"],["prescrire un antidépresseur","开抗抑郁药"],["arrêter un antidépresseur","停用抗抑郁药"]],"sy":[["médicament","courant","药"],["anxiolytique","soutenu","抗焦虑药"],["calmant","courant","镇静剂"]],"fq":"中低频，医疗话题里出现。","me":"anti（反）+ dépresseur（压低）：对抗情绪低落。","tr":{"zh":"医生建议他吃抗抑郁药。","fr":"Le médecin lui a conseillé un antidépresseur.","alt":"Le médecin lui a recommandé de prendre un antidépresseur.","note":"conseiller qqch à qqn。"}},
 "Un antidote": {"pos":"n.m. 阳性名词，复数 antidotes","s":"解毒剂、解药。比喻义：治病良方、对付坏事的办法。un antidote contre le stress = 对付压力的良方。","ipa":"[ɑ̃.ti.dɔt]","ph":"an 读 [ɑ̃]；ti 读 [ti]；dote 读 [dɔt]，o 开口，t 要发，e 不发音。","pi":"an- 读 [ɑ̃]；-ote 的 t 要发音 [dɔt]。别和 dote 混淆。","et":"希腊语 antidoton（反着给的东西）：anti（反对）+ didonai（给）。","ex":[["Il faut trouver l'antidote à ce poison.","必须找到这种毒药的解药。"],["Le sport est un bon antidote contre le stress.","运动是对付压力的好办法。"]],"co":[["un antidote contre le poison","解毒剂"],["trouver un antidote","找到解药"],["un antidote au stress","解压良方"]],"sy":[["remède","courant","药，疗法"],["contrepoison","soutenu","解毒剂"],["solution","courant","办法"]],"fq":"中低频，医学和比喻里出现。","me":"anti（反）+ dote（给）：反着给你一剂药。","tr":{"zh":"音乐是对付压力的好办法。","fr":"La musique est un bon antidote contre le stress.","alt":"La musique aide bien à lutter contre le stress.","note":"antidote contre / à + 名词。"}},
 "La politesse": {"pos":"n.f. 阴性名词，复数 politesses","s":"礼貌、客气。par politesse = 出于礼貌；les politesses 指客套话、寒暄；formule de politesse = 书信结尾的客套话。","ipa":"[pɔ.li.tɛs]","ph":"po 读 [pɔ]；li [li]；tesse 读 [tɛs]，ss 读 [s]，结尾 e 不发音。","pi":"ss 读 [s]，不是 [z]；结尾 e 不发音。和 poli（礼貌的）同族。","et":"poli（有礼貌的，原义「磨光的」，拉丁语 politus）+ 后缀 -esse。","ex":[["La politesse est importante en société.","礼貌在社会中很重要。"],["Il a dit oui par politesse.","他出于礼貌说了好。"]],"co":[["par politesse","出于礼貌"],["une formule de politesse","客套话；信件结尾敬语"],["les règles de politesse","礼貌规矩"],["manquer de politesse","不礼貌"]],"sy":[["courtoisie","soutenu","彬彬有礼"],["savoir-vivre","courant","礼仪，教养"],["impolitesse","courant","反义：无礼"]],"fq":"高频，日常常用。","me":"poli（磨光）+ -esse：打磨得光滑的行为。","tr":{"zh":"说「请」和「谢谢」是礼貌。","fr":"Dire « s'il vous plaît » et « merci », c'est de la politesse.","alt":"Dire « s'il vous plaît » et « merci », c'est être poli.","note":"de la politesse：部分冠词。"}},
 "L'impolitesse": {"pos":"n.f. 阴性名词，复数 impolitesses","s":"无礼、不礼貌；也指无礼的举动。反义词是 politesse。形容词是 impoli（无礼的）。","ipa":"[ɛ̃.pɔ.li.tɛs]","ph":"im 读鼻化 [ɛ̃]；po 读 [pɔ]；li [li]；tesse 读 [tɛs]。","pi":"im- 在 p 前读鼻化 [ɛ̃]，不要读成 [im]；ss 读 [s]。","et":"前缀 im-（= in-，否定，在 p 前变 im-）+ politesse。","ex":[["Son impolitesse a choqué tout le monde.","他的无礼让所有人震惊。"],["Couper la parole est une impolitesse.","打断别人说话是不礼貌的。"]],"co":[["commettre une impolitesse","做出不礼貌的事"],["c'est une impolitesse de + inf.","……是不礼貌的"],["l'impolitesse des gens","人们的无礼"]],"sy":[["grossièreté","courant","粗鲁"],["insolence","soutenu","傲慢无礼"],["manque de respect","courant","缺乏尊重"]],"fq":"中频，日常评论他人时用。","me":"im-（不）+ politesse（礼貌）。","tr":{"zh":"不回答人家的问候是不礼貌的。","fr":"Ne pas répondre à un bonjour est une impolitesse.","alt":"C'est impoli de ne pas répondre quand on dit bonjour.","note":"c'est une impolitesse de + 原形。"}},
 "Une conversation": {"pos":"n.f. 阴性名词，复数 conversations","s":"交谈；对话。指两人或几人之间轻松、自然的谈话。也可指电话交谈（une conversation téléphonique）。比 discussion 更日常、更随意。","ipa":"[kɔ̃.vɛʁ.sa.sjɔ̃]","ph":"con 读鼻化音 [ɔ̃]；ver 读 [vɛʁ]；-tion 读 [sjɔ̃]（不是 [ʃən]）；结尾 n 不发音。","pi":"-tion 读 [sjɔ̃]，不要读成英语的 [ʃən]；con 和 -tion 都是鼻化音，n 不发。","et":"来自拉丁语 conversatio（共同生活、交往）。同源动词 converser（交谈）。","ex":[["Nous avons eu une longue conversation.","我们进行了一次长谈。"],["J'ai une conversation importante avec mon chef.","我要和老板进行一次重要的谈话。"],["Elle est en pleine conversation au téléphone.","她正在打电话聊天。"]],"co":[["avoir une conversation","进行交谈"],["engager la conversation","开始交谈"],["une conversation téléphonique","电话交谈"],["faire la conversation","闲聊（陪人说话）"]],"sy":[["discussion","courant","讨论；更偏向交换意见"],["entretien","soutenu","会谈；面谈"],["causette","familier","闲聊"]],"fq":"高频，日常常用。","me":"con-vers-ation：大家「一起（con）转向（vers）」对方说话。","tr":{"zh":"昨天我们聊了很久。","fr":"Hier, nous avons eu une longue conversation.","alt":"Hier, on a beaucoup discuté.","note":"avoir une conversation = 进行交谈；复合过去时用 avoir。"}},
 "Une discussion": {"pos":"n.f. 阴性名词，复数 discussions","s":"讨论；谈论；有时也指争论、争吵（avoir une discussion avec quelqu'un 可能带一点火气）。比 conversation 更偏重交换意见、谈具体话题。","ipa":"[dis.ky.sjɔ̃]","ph":"dis 读 [dis]，s 发音；-ssion 读 [sjɔ̃]；结尾 n 不发。","pi":"dis 中的 s 要读出来；u 读 [y]；-ssion 读 [sjɔ̃]。动词是 discuter，名词是 discussion，别混用。","et":"来自拉丁语 discussio（审查、讨论），动词 discuter 同源。","ex":[["C'était une discussion très intéressante.","这是一场很有趣的讨论。"],["Il y a eu une discussion animée au conseil.","会上有一场热烈的讨论。"],["Pas de discussion, tu y vas !","没得商量，你去！"]],"co":[["avoir une discussion","进行讨论"],["une discussion animée","热烈的讨论"],["sans discussion possible","毫无争议"],["engager une discussion","展开讨论"]],"sy":[["débat","courant","辩论；公开讨论"],["conversation","courant","交谈，更随意"],["dispute","courant","争吵，带怒气"]],"fq":"高频，日常和工作中常用。","me":"discuss + ion：和 discuss（讨论）几乎一样，只是加 -ion。","tr":{"zh":"我们有一场很重要的讨论。","fr":"Nous avons une discussion très importante.","alt":"On doit avoir une discussion importante.","note":"discussion 阴性，所以用 une / très importante（阴性形容词）。"}},
 "Une marque": {"pos":"n.f. 阴性名词，复数 marques","s":"品牌；商标；也指记号、痕迹（une marque sur le mur）。une grande marque = 名牌。动词是 marquer（做记号；得分）。","ipa":"[maʁk]","ph":"ar 读 [aʁ]；qu 读 [k]；结尾 e 不发音，但 k 要发出来。","pi":"qu 读 [k]，不是 [kw]；结尾 e 不发音。一个音节：[maʁk]。","et":"来自动词 marquer；词源是日耳曼语（与英语 mark 同源）。","ex":[["Adidas est une marque de vêtements de sports.","阿迪达斯是运动服饰品牌。"],["Quelle est ta marque de téléphone préférée ?","你最喜欢哪个手机品牌？"],["Il y a une marque sur la table.","桌子上有个痕迹。"]],"co":[["une grande marque","名牌"],["une marque de voiture","汽车品牌"],["à vos marques !","各就各位！"],["marque déposée","注册商标"]],"sy":[["enseigne","courant","店铺招牌；连锁店"],["label","courant","标签；品质认证"],["trace","courant","痕迹"]],"fq":"高频，日常常用。","me":"marque 和英语 mark 同源：在商品上做的「标记」。","tr":{"zh":"这个牌子很有名。","fr":"Cette marque est très connue.","alt":"C'est une marque très connue.","note":"marque 阴性：cette marque。"}},
 "Une sphère": {"pos":"n.f. 阴性名词，复数 sphères","s":"球体；引申为领域、范围，如 la sphère privée（私人领域）、la sphère politique（政治领域）。后一种用法在书面和新闻中很常见。","ipa":"[sfɛʁ]","ph":"sph 读 [sf]；è 读 [ɛ]；结尾 re 中 r 读 [ʁ]，e 不发音。","pi":"ph 读 [f]；一个音节 [sfɛʁ]，不要在 s 后加元音。","et":"来自希腊语 sphaira（球），经拉丁语 sphaera 进入法语。","ex":[["Cela relève de la sphère privée.","这属于私人领域。"],["La Terre est une sphère presque parfaite.","地球是一个近乎完美的球体。"],["Il travaille dans la sphère économique.","他在经济领域工作。"]],"co":[["la sphère privée","私人领域"],["la sphère publique","公共领域"],["la sphère d'influence","势力范围"],["une sphère d'activité","活动领域"]],"sy":[["domaine","courant","领域，更常用"],["champ","soutenu","范围；领域"],["boule","courant","球（日常）"]],"fq":"中频，书面和媒体中较多。","me":"sphère 像英语 sphere：圆球，引申为「圈子」。","tr":{"zh":"这属于他的私人领域。","fr":"Cela relève de sa sphère privée.","alt":"C'est dans sa vie privée.","note":"relever de = 属于……范围。"}},
 "La puissance": {"pos":"n.f. 阴性名词，复数 puissances","s":"力量；权力；功率（moteur 的功率）；强国（une grande puissance）。形容词是 puissant(e)。数学中还表示「乘方」。","ipa":"[pɥi.sɑ̃s]","ph":"ui 读半元音加元音 [ɥi]；ss 读 [s]；an 读鼻化音 [ɑ̃]；结尾 ce 读 [s]。","pi":"ui 读 [ɥi]，口型从圆唇滑到 i，不是 [wi]；an 是鼻化音，不发 n。","et":"来自 puissant（pouvoir 的现在分词形式）加后缀 -ance。同源：pouvoir（能够）。","ex":[["La puissance de ce moteur est impressionnante.","这台发动机的功率令人印象深刻。"],["La France est une grande puissance.","法国是一个大国。"],["Il a la puissance d'un lion.","他有狮子般的力量。"]],"co":[["une grande puissance","大国；强国"],["la puissance d'un moteur","发动机功率"],["en puissance","潜在的"],["la puissance de feu","火力"]],"sy":[["force","courant","力气；力量"],["pouvoir","courant","权力；能力"],["énergie","courant","能量；精力"]],"fq":"中高频，日常和新闻中常见。","me":"puissance = pouvoir + -ance：「能做到的程度」。","tr":{"zh":"这辆车的功率很大。","fr":"Cette voiture a beaucoup de puissance.","alt":"Cette voiture est très puissante.","note":"avoir de la puissance；puissant 是形容词。"}},
 "La familiarité": {"pos":"n.f. 阴性名词，复数 familiarités","s":"亲昵；熟络；随便。有时是中性的（熟悉感），但常带贬义：对不熟的人太随便、不够尊重。le tutoiement 也可能被看作过分的 familiarité。","ipa":"[fa.mi.ljaʁ.i.te]","ph":"fa-mi-lia-ri-té，五个音节；li 后接 a，读 [lja]；r 读 [ʁ]；é 读 [e]。","pi":"中间 lia 要读成 [lja]，然后才是 [ʁi]；不要漏掉音节。","et":"来自拉丁语 familiaritas，源于 familia（家庭）。同族词：famille、familier。","ex":[["Il me parle avec trop de familiarité.","他对我说话太随便了。"],["Elle traite ses élèves avec familiarité.","她对学生很亲切随和。"],["Je ne supporte pas sa familiarité.","我受不了他的过分亲昵。"]],"co":[["avec familiarité","亲昵地；随便地"],["une familiarité excessive","过分亲昵"],["se permettre des familiarités","放肆；动手动脚"],["la familiarité avec un sujet","对某个主题的熟悉"]],"sy":[["intimité","courant","亲密关系"],["désinvolture","soutenu","随便；不拘礼节"],["proximité","courant","接近；亲近"]],"fq":"中低频，常见于书面或评价他人态度时。","me":"familiarité ← famille：把外人当「家人」一样随便。","tr":{"zh":"他对老板说话太随便了。","fr":"Il parle à son chef avec trop de familiarité.","alt":"Il est trop familier avec son chef.","note":"avec + 名词 = 以……方式；trop de + 名词。"}},
 "La conduite": {"pos":"n.f. 阴性名词，复数 conduites","s":"行为；举止（la conduite d'un enfant）；驾驶（la conduite d'une voiture）；管道。le permis de conduire = 驾照，conduite accompagnée = 陪同驾驶学习。","ipa":"[kɔ̃.dɥit]","ph":"con 读 [kɔ̃]；du 在这里读 [dɥi]，ui 是半元音加 i；结尾 te 中 t 要发，e 不发。","pi":"ui 读 [ɥi]，不是 [ɥ] 加 [u]；con 的 n 不发音。","et":"来自动词 conduire（带领），拉丁语 conducere；conduite 是它的过去分词名词化。","ex":[["Quelles sont les règles de conduite de base ?","基本的行为规范是什么？"],["Il a une très bonne conduite.","他表现得非常好。"],["La conduite de nuit est fatigante.","夜间驾驶很累人。"]],"co":[["une règle de conduite","行为规范"],["la conduite à gauche","靠左行驶"],["bonne / mauvaise conduite","表现良好 / 恶劣"],["en conduite accompagnée","陪同驾驶学习"]],"sy":[["comportement","courant","行为；表现"],["attitude","courant","态度"],["conduire","courant","动词：驾驶；带领"]],"fq":"中高频，日常常用。","me":"conduite ← conduire：「怎么开自己的生活」，也是「怎么开车」。","tr":{"zh":"他的行为很好。","fr":"Sa conduite est très bonne.","alt":"Il se comporte très bien.","note":"conduite 阴性；se comporter 是更口语的动词说法。"}},
 "Une routine": {"pos":"n.f. 阴性名词，复数 routines","s":"日常惯例；固定的生活节奏，如 la routine du matin（晨间习惯）。也可略带贬义，指单调乏味（tomber dans la routine）。","ipa":"[ʁu.tin]","ph":"r 读小舌音 [ʁ]；ou 读 [u]；结尾 ine 读 [in]，e 不发。","pi":"ou 读 [u]，r 读小舌音 [ʁ]；重音落在最后一个音节 [tin]。","et":"来自 route（路），指「走惯了的路」。英语 routine 借自法语。","ex":[["J'aime ma petite routine du matin.","我喜欢我的晨间小习惯。"],["On tombe vite dans la routine.","人很容易陷入千篇一律。"],["Il faut casser la routine.","要打破常规。"]],"co":[["la routine quotidienne","日常惯例"],["tomber dans la routine","陷入一成不变"],["casser la routine","打破常规"],["un contrôle de routine","例行检查"]],"sy":[["habitude","courant","习惯"],["train-train","familier","老一套的日子"],["rituel","courant","固定仪式"]],"fq":"中高频，日常常用。","me":"routine ← route：每天都走的同一条路。","tr":{"zh":"我有自己的晨间习惯。","fr":"J'ai ma propre routine du matin.","alt":"J'ai mes petites habitudes le matin.","note":"routine du matin 中 matin 前用 du。"}},
 "Une dédicace": {"pos":"n.f. 阴性名词，复数 dédicaces","s":"题词；签名题赠（书上的献词，如作家签名）。une séance de dédicaces = 签售会。也指歌曲、广播中的点歌献词。","ipa":"[de.di.kas]","ph":"dé 读 [de]；di 读 [di]；c 在 e 前读 [s]；结尾 e 不发音。","pi":"c 读 [s]（因为后面是 e），不是 [k]；注意两个 é 的重音符号只有第一个音节有。","et":"来自拉丁语 dedicatio（奉献），同源动词 dédicacer（题赠）和 dédier。","ex":[["L'auteur a fait une dédicace sur mon livre.","作者在我的书上签了名。"],["Il y a une séance de dédicaces à la librairie.","书店里有一场签售会。"],["Cette chanson est une dédicace pour toi.","这首歌是献给你的。"]],"co":[["une séance de dédicaces","签售会"],["faire une dédicace","题词签名"],["dédicacer un livre","在书上签名"],["une dédicace spéciale","特别献词"]],"sy":[["autographe","courant","亲笔签名"],["signature","courant","签名"],["hommage","soutenu","致敬"]],"fq":"中低频，和书、歌、广播相关时常见。","me":"dédicace ≈ 英语 dedicate：献给某人的话。","tr":{"zh":"她给我的书签了名。","fr":"Elle a dédicacé mon livre.","alt":"Elle m'a fait une dédicace sur mon livre.","note":"动词 dédicacer 比名词更常用；复合过去时用 avoir。"}},
 "Une fracture": {"pos":"n.f. 阴性名词，复数 fractures","s":"骨折（une fracture du bras）；引申为断层、裂痕，如 une fracture sociale（社会裂痕）、une fracture générationnelle（代际断层）。","ipa":"[fʁak.tyʁ]","ph":"fr 读 [fʁ]；c 在 t 前读 [k]；u 读 [y]（圆唇 i）；r 读 [ʁ]；结尾 e 不发音。","pi":"u 读 [y]，不是 [u]；ct 都要读出来：[ktyʁ]。","et":"来自拉丁语 fractura，源于 frangere（打断）。同族词：fragile、fraction。","ex":[["Aujourd'hui, il y a une fracture générationnelle.","如今存在代际断层。"],["Il a une fracture à la jambe.","他的腿骨折了。"],["On parle d'une fracture sociale en France.","人们谈论法国的社会裂痕。"]],"co":[["une fracture du bras / de la jambe","手臂 / 腿骨折"],["une fracture sociale","社会裂痕"],["une fracture numérique","数字鸿沟"],["se faire une fracture","骨折了"]],"sy":[["cassure","courant","断裂；裂缝"],["rupture","courant","决裂；中断"],["fossé","courant","鸿沟"]],"fq":"中频，医疗和新闻中常见。","me":"fracture ≈ 英语 fracture；frag-/frac- 都是「断」。","tr":{"zh":"他的手臂骨折了。","fr":"Il a une fracture au bras.","alt":"Il s'est cassé le bras.","note":"fracture 在日常口语里常被 se casser 取代。"}},
 "Une injustice": {"pos":"n.f. 阴性名词，复数 injustices","s":"不公平；不公正的事。常说 c'est une injustice 表示「这不公平」。反义词是 la justice（公正）。","ipa":"[ɛ̃.ʒys.tis]","ph":"in 读鼻化音 [ɛ̃]；j 读 [ʒ]；u 读 [y]；st 读 [st]；ce 读 [s]。","pi":"in 是鼻化音 [ɛ̃]，n 不单独发音；u 读 [y]；结尾 ce 读 [s]。","et":"拉丁语 injustitia，由否定前缀 in- 加 justitia（公正）构成。","ex":[["C'est une profonde injustice.","这是一种深刻的不公。"],["Je ne supporte pas l'injustice.","我无法忍受不公平。"],["Il a été victime d'une injustice.","他成了不公的受害者。"]],"co":[["une profonde injustice","深刻的不公"],["réparer une injustice","纠正不公"],["lutter contre l'injustice","与不公作斗争"],["une injustice sociale","社会不公"]],"sy":[["iniquité","soutenu","不公；不义"],["inégalité","courant","不平等"],["justice","courant","反义：公正"]],"fq":"中频，日常和新闻中常见。","me":"in- + justice：「不」+「公正」。","tr":{"zh":"这太不公平了。","fr":"C'est une vraie injustice.","alt":"C'est vraiment injuste.","note":"名词 injustice，形容词 injuste。"}},
 "Une lettre d'information (une newsletter)": {"pos":"n.f. 阴性名词，复数 lettres d'information","s":"电子简报；订阅通讯。公司或网站定期发给订阅者的邮件。日常多说 une newsletter（来自英语，阴性），正式场合用 une lettre d'information。","ipa":"[lɛtʁ.dɛ̃.fɔʁ.ma.sjɔ̃]","ph":"lettre 读 [lɛtʁ]，e 不发；d'information 连读，in 读 [ɛ̃]，-tion 读 [sjɔ̃]。newsletter 读 [njuz.lɛ.tœʁ] 或 [njuz.lɛ.tɛʁ]。","pi":"information 开头是鼻化音 [ɛ̃]，lettre 结尾的 e 不发；-tion 读 [sjɔ̃]。","et":"lettre 来自拉丁语 littera（字母；信）；information 来自拉丁语 informatio。newsletter 借自英语。","ex":[["Abonnez-vous à notre lettre d'information.","订阅我们的电子简报。"],["Je reçois la newsletter tous les lundis.","我每周一收到这份简报。"],["Je me suis désabonné de cette newsletter.","我已取消订阅这份简报。"]],"co":[["s'abonner à la newsletter","订阅简报"],["se désabonner","取消订阅"],["envoyer une newsletter","发送简报"],["la lettre d'information mensuelle","月度简报"]],"sy":[["newsletter","courant","更常用，借自英语"],["bulletin","soutenu","通报；会刊"],["infolettre","courant","加拿大魁北克的说法"]],"fq":"中频，网络和营销中常见。","me":"lettre d'information = 「信息之信」，就是 newsletter。","tr":{"zh":"我订阅了这家商店的简报。","fr":"Je suis abonné à la newsletter de ce magasin.","alt":"Je reçois la lettre d'information de ce magasin.","note":"être abonné à = 订阅了；newsletter 视为阴性名词。"}},
 "Une statistique": {"pos":"n.f. 阴性名词，复数 statistiques","s":"统计数据；统计数字（une statistique officielle）。复数 les statistiques 也可指统计学。作形容词时 statistique = 统计的。","ipa":"[sta.tis.tik]","ph":"sta 读 [sta]；ti 读 [ti]，这里 t 读 [t]，不读 [s]；qu 读 [k]；结尾 e 不发。","pi":"ti 在这里读 [ti]，不是 [si]；qu 读 [k]。","et":"与 état（状态；国家）同源，指国家的数据；词形经德语 Statistik 进入法语。","ex":[["Cette statistique est inquiétante.","这个统计数字令人担忧。"],["Selon les statistiques, il pleut peu ici.","根据统计，这里很少下雨。"],["Je n'aime pas les statistiques.","我不喜欢统计学。"]],"co":[["selon les statistiques","根据统计"],["une statistique officielle","官方统计数据"],["les statistiques du chômage","失业统计"],["faire des statistiques","做统计"]],"sy":[["chiffre","courant","数字"],["donnée","courant","数据"],["pourcentage","courant","百分比"]],"fq":"中高频，新闻和学习中常用。","me":"statistique ≈ 英语 statistic：数字背后的「国家」数据。","tr":{"zh":"根据官方统计，失业率下降了。","fr":"Selon les statistiques officielles, le chômage baisse.","alt":"D'après les chiffres officiels, le chômage baisse.","note":"selon / d'après + 名词 = 根据。"}},
 "La rémunération": {"pos":"n.f. 阴性名词，复数 rémunérations","s":"报酬；薪酬。指劳动换来的钱，正式用语，常用于合同、人力资源。口语多说 le salaire 或 la paie。动词是 rémunérer。","ipa":"[ʁe.my.ne.ʁa.sjɔ̃]","ph":"ré 读 [ʁe]；mu 读 [my]，u 读 [y]；né 读 [ne]；-tion 读 [sjɔ̃]。五个音节。","pi":"u 读 [y]，不是 [u]；两个 r 都读 [ʁ]；-tion 读 [sjɔ̃]。","et":"来自拉丁语 remunerari（报偿），源于 munus（礼物，职责）。","ex":[["Sa rémunération est très attractive.","他的报酬很有吸引力。"],["La rémunération dépend de l'expérience.","薪酬取决于经验。"],["Cette tâche mérite une juste rémunération.","这项任务值得合理的报酬。"]],"co":[["une juste rémunération","合理报酬"],["une rémunération attractive","有吸引力的薪酬"],["la rémunération annuelle","年薪"],["rémunérer quelqu'un","给某人付报酬"]],"sy":[["salaire","courant","工资，最常用"],["paie","courant","工资；发薪"],["traitement","soutenu","公务员薪金"]],"fq":"中频，正式和职场语境常见。","me":"ré-munér-ation：munus（礼物）+ 回报，像给「回礼」。","tr":{"zh":"这份工作的薪酬很不错。","fr":"La rémunération de ce poste est très bonne.","alt":"Ce poste est bien payé.","note":"bien payé 是更口语的说法。"}},
 "Une discrimination": {"pos":"n.f. 阴性名词，复数 discriminations","s":"歧视；区别对待（不公平地对待某类人）。常见：discrimination raciale（种族歧视）、discrimination à l'embauche（招聘歧视）。","ipa":"[dis.kʁi.mi.na.sjɔ̃]","ph":"dis 读 [dis]；cri 读 [kʁi]；mi 读 [mi]；na 读 [na]；-tion 读 [sjɔ̃]。","pi":"-tion 读 [sjɔ̃]；c 在 r 前读 [k]；五个音节，别漏掉中间的 mi-na。","et":"来自拉丁语 discriminatio（区分），源于 discriminare。注意：法语中该词多带「歧视」的含义。","ex":[["La discrimination à l'embauche est illégale.","招聘歧视是违法的。"],["Il a été victime de discrimination.","他曾遭受歧视。"],["Nous luttons contre toutes les discriminations.","我们反对一切歧视。"]],"co":[["une discrimination raciale","种族歧视"],["lutter contre la discrimination","反对歧视"],["être victime de discrimination","遭受歧视"],["la discrimination positive","积极的差别待遇（平权行动）"]],"sy":[["ségrégation","soutenu","隔离"],["racisme","courant","种族主义"],["inégalité","courant","不平等"]],"fq":"中频，新闻和社会话题中常见。","me":"discrimination ≈ 英语 discrimination，意思基本一样。","tr":{"zh":"歧视是不可接受的。","fr":"La discrimination est inacceptable.","alt":"On ne peut pas accepter la discrimination.","note":"抽象名词前常用定冠词 la。"}},
 "Une augmentation": {"pos":"n.f. 阴性名词，复数 augmentations","s":"增加；上涨（une augmentation des prix）；加薪（une augmentation de salaire），口语常简称 une augmentation。动词是 augmenter。","ipa":"[og.mɑ̃.ta.sjɔ̃]","ph":"au 读 [o]；g 读 [g]；en 读鼻化音 [ɑ̃]；-tion 读 [sjɔ̃]。","pi":"au 读 [o]，不是 [au]；aug- 的 g 要读出来：[og]；en 读 [ɑ̃]。","et":"来自拉丁语 augmentatio，源于 augere（增加）。同族词：auteur、auguste。","ex":[["Je vais demander une augmentation à mon chef.","我要向老板要求加薪。"],["Il y a une augmentation des prix.","物价上涨了。"],["Elle a eu une augmentation de dix pour cent.","她加薪了百分之十。"]],"co":[["demander une augmentation","要求加薪"],["une augmentation de salaire","加薪"],["une augmentation des prix","物价上涨"],["en augmentation","在上升"]],"sy":[["hausse","courant","上涨，常用于价格"],["croissance","courant","增长"],["diminution","courant","反义：减少"]],"fq":"高频，日常常用。","me":"augment 像英语 augment：「增加」。","tr":{"zh":"我想要求加薪。","fr":"Je voudrais demander une augmentation.","alt":"J'aimerais être augmenté.","note":"demander une augmentation = 要求加薪；augmenter 也可作及物动词。"}},
 "La culpabilisation": {"pos":"n.f. 阴性名词，复数 culpabilisations","s":"让人产生内疚感；一味指责（对方不够好、做错了）。常用于教育和心理话题。动词 culpabiliser，形容词 coupable（有罪的；内疚的）。","ipa":"[kyl.pa.bi.li.za.sjɔ̃]","ph":"cul 读 [kyl]，u 读 [y]；pa-bi-li 逐个读；sa 中 s 读 [z]；-tion 读 [sjɔ̃]。","pi":"u 读 [y]；culpa- 中 l 要发；s 在元音间读 [z]；七个音节较长，慢慢分开读。","et":"来自动词 culpabiliser，由 coupable（拉丁语 culpa，过错）加后缀构成。","ex":[["La culpabilisation ne résout rien.","一味让人内疚解决不了问题。"],["Arrête de me culpabiliser !","别再让我内疚了！"],["Il se sent coupable.","他觉得内疚。"]],"co":[["culpabiliser quelqu'un","让某人内疚"],["se culpabiliser","自责"],["un sentiment de culpabilité","内疚感"],["la culpabilisation des parents","对父母的指责"]],"sy":[["culpabilité","courant","内疚（感受本身）"],["reproche","courant","责备"],["accusation","courant","指控"]],"fq":"中低频，教育、心理话题中常见。","me":"culpa（过错）+ -bilisation：让人「觉得有错」。","tr":{"zh":"别再让孩子内疚了。","fr":"Il ne faut pas culpabiliser les enfants.","alt":"Arrête de culpabiliser les enfants.","note":"culpabiliser 是及物动词，直接带宾语。"}},
 "Une politique": {"pos":"n.f. 阴性名词，复数 politiques","s":"政策；方针（une politique économique）；政治（la politique，作整体概念）。注意：un politique / un homme politique = 政治家；形容词 politique = 政治的。","ipa":"[pɔ.li.tik]","ph":"po 读 [pɔ]；li 读 [li]；ti 读 [ti]；qu 读 [k]；结尾 e 不发。","pi":"qu 读 [k]；une politique（政策）与 le politique（政治家，阳性）词性不同，意思也不同。","et":"来自希腊语 politikos，源于 polis（城邦）。同族词：police、polis（古希腊城邦）。","ex":[["Faut-il des politiques publiques pour diminuer l'écart salarial entre les hommes et les femmes ?","是否需要公共政策来缩小男女薪酬差距？"],["Le gouvernement change de politique.","政府改变了政策。"],["Je ne m'intéresse pas à la politique.","我对政治不感兴趣。"]],"co":[["une politique publique","公共政策"],["une politique économique","经济政策"],["faire de la politique","从政；参与政治"],["un homme / une femme politique","政治家"]],"sy":[["stratégie","courant","战略"],["réglementation","soutenu","法规"],["politicien","courant","政客（常带贬义）"]],"fq":"极高频，新闻中常用。","me":"politique ← polis：和「城邦」有关的事，就是政策与政治。","tr":{"zh":"政府要改变它的经济政策。","fr":"Le gouvernement veut changer sa politique économique.","alt":"Le gouvernement va revoir sa politique économique.","note":"politique économique：形容词放在名词后。"}},
 "Une proposition": {"pos":"n.f. 阴性名词，复数 propositions","s":"提议；建议；提案。也是语法术语：une proposition = 从句（une proposition subordonnée）。动词是 proposer。","ipa":"[pʁɔ.pɔ.zi.sjɔ̃]","ph":"pro 读 [pʁɔ]；po 读 [pɔ]；si 中 s 读 [z]；-tion 读 [sjɔ̃]。","pi":"si 在元音之间读 [zi]，不是 [si]；-tion 读 [sjɔ̃]。","et":"来自拉丁语 propositio，由 pro-（向前）和 ponere（放置）而来。","ex":[["J'ai une proposition à te faire.","我有个提议要告诉你。"],["Il a refusé notre proposition.","他拒绝了我们的提议。"],["Merci pour votre proposition d'aide.","谢谢您提出帮忙。"]],"co":[["faire une proposition","提出建议"],["accepter / refuser une proposition","接受 / 拒绝提议"],["une proposition d'emploi","工作邀约"],["sur la proposition de","应……之提议"]],"sy":[["suggestion","courant","建议，比较温和"],["offre","courant","提供的条件；优惠"],["projet","courant","计划"]],"fq":"高频，日常和工作中常用。","me":"pro + position：把想法「放到前面」给大家。","tr":{"zh":"我有个好提议。","fr":"J'ai une bonne proposition.","alt":"J'ai une idée à te proposer.","note":"faire une proposition = 提出建议；proposer 是对应动词。"}},
 "Une prédominance": {"pos":"n.f. 阴性名词，复数 prédominances","s":"优势；占主导地位。多指某种东西在数量或影响上占上风，较书面。动词是 prédominer，形容词 prédominant(e)。","ipa":"[pʁe.dɔ.mi.nɑ̃s]","ph":"pré 读 [pʁe]；do 读 [dɔ]；mi 读 [mi]；nance 中 an 读鼻化音 [ɑ̃]，ce 读 [s]。","pi":"an 读 [ɑ̃]，n 不单独发音；结尾 ce 读 [s]；é 读 [e]。","et":"由前缀 pré-（在前）加 dominance 构成；dominance 来自拉丁语 dominari（统治）。","ex":[["Il y a une prédominance de la couleur bleue.","蓝色占主导。"],["On note la prédominance des femmes dans ce métier.","这个行业中女性占多数。"],["Cette langue a une prédominance dans la région.","这种语言在该地区占主导。"]],"co":[["la prédominance de","……占主导"],["une nette prédominance","明显占优"],["noter la prédominance","注意到优势"],["prédominance masculine / féminine","男性 / 女性占多数"]],"sy":[["suprématie","soutenu","至高无上"],["majorité","courant","多数"],["domination","courant","支配"]],"fq":"低频，书面和报告中出现。","me":"pré- + dominance：先「压过」别人一头。","tr":{"zh":"这个地区以蓝色为主。","fr":"Il y a une prédominance de bleu dans la région.","alt":"Le bleu domine dans la région.","note":"prédominance de + 名词；口语用动词 dominer。"}},
 "La conscience": {"pos":"n.f. 阴性名词，复数 consciences","s":"良心；意识；觉悟。avoir la conscience tranquille = 问心无愧；avoir conscience de = 意识到；perdre conscience = 失去知觉。","ipa":"[kɔ̃.sjɑ̃s]","ph":"con 读鼻化音 [kɔ̃]；science 读 [sjɑ̃s]，sc 读 [s]，ie 读 [jɑ̃]，en 读 [ɑ̃]。","pi":"sc 读 [s]，不是 [sk]；ien 读 [jɑ̃]；两个鼻化音（con 和 -ien-）。","et":"来自拉丁语 conscientia，由 con-（一起）加 scire（知道）构成。同族词：science、conscient。","ex":[["J'ai la conscience tranquille.","我问心无愧。"],["Il a perdu conscience après le choc.","他受到撞击后失去了知觉。"],["Nous avons conscience du problème.","我们意识到了这个问题。"]],"co":[["avoir la conscience tranquille","问心无愧"],["avoir conscience de","意识到"],["prendre conscience de","开始意识到"],["perdre / reprendre conscience","失去 / 恢复知觉"]],"sy":[["conscient","courant","形容词：有意识的"],["morale","courant","道德"],["lucidité","soutenu","清醒；明智"]],"fq":"高频，日常常用。","me":"con + science：与「知道」（scire）有关，一个人「知道」自己在做什么。","tr":{"zh":"我意识到这个问题。","fr":"J'ai conscience du problème.","alt":"Je me rends compte du problème.","note":"avoir conscience de + 名词 = 意识到。"}},
 "L'éducation": {"pos":"n.f. 阴性名词，复数 éducations","s":"教育；教养。包括家庭教育和学校教育：l'éducation des enfants（孩子的教育）。avoir de l'éducation = 有教养。l'Éducation nationale = 国民教育部。","ipa":"[e.dy.ka.sjɔ̃]","ph":"é 读 [e]；du 读 [dy]，u 读 [y]；ca 读 [ka]；-tion 读 [sjɔ̃]。l'éducation 中 l' 与后面元音连读（省音）。","pi":"u 读 [y]；-tion 读 [sjɔ̃]；éducation 与英语 education 拼写很像，注意重音符。","et":"来自拉丁语 educatio，源于 educare（培养，抚育）。","ex":[["L'éducation des enfants est primordiale.","儿童教育至关重要。"],["Il a reçu une bonne éducation.","他受过良好的教养。"],["Elle travaille dans l'éducation.","她在教育行业工作。"]],"co":[["l'éducation des enfants","儿童教育"],["recevoir une bonne éducation","受良好教养"],["l'éducation physique","体育课"],["l'Éducation nationale","法国国民教育部"]],"sy":[["enseignement","courant","教学；教育体系"],["instruction","soutenu","知识教育"],["formation","courant","培训"]],"fq":"高频，日常和新闻中常用。","me":"éducation ← educare：把孩子「引导出来」。","tr":{"zh":"孩子的教育很重要。","fr":"L'éducation des enfants est très importante.","alt":"Éduquer ses enfants, c'est très important.","note":"l'éducation des enfants：de + 复数名词。"}},
 "Une fondation": {"pos":"n.f. 阴性名词，复数 fondations","s":"基础；地基（常用复数 les fondations 指房子的地基）；创立；基金会（une fondation）。比喻义为「基础」。动词是 fonder（创立；建立）。","ipa":"[fɔ̃.da.sjɔ̃]","ph":"fon 读鼻化音 [fɔ̃]；da 读 [da]；-tion 读 [sjɔ̃]。","pi":"第一个 on 读 [ɔ̃]，n 不发音；-tion 读 [sjɔ̃]。","et":"来自拉丁语 fundatio，源于 fundus（底部）。同族词：fond（底部）、fonder。","ex":[["La communication est la fondation d'une bonne relation.","沟通是良好关系的基础。"],["Les fondations de la maison sont solides.","这座房子的地基很牢固。"],["Elle travaille pour une fondation.","她在一家基金会工作。"]],"co":[["les fondations d'une maison","房屋的地基"],["la fondation d'une entreprise","公司的创立"],["une fondation caritative","慈善基金会"],["poser les fondations","打下基础"]],"sy":[["base","courant","基础"],["fondement","soutenu","根基；依据"],["création","courant","创建"]],"fq":"中频，日常和新闻中常见。","me":"fond（底部）+ -ation：房子的「底」。","tr":{"zh":"信任是友谊的基础。","fr":"La confiance est la fondation de l'amitié.","alt":"L'amitié repose sur la confiance.","note":"比喻义也可说 la base；repose sur = 建立在……之上。"}},
 "Une théorie": {"pos":"n.f. 阴性名词，复数 théories","s":"理论；学说。en théorie = 理论上，常和 en pratique（实际上）对比。也指对事情的猜想（Il a sa théorie sur la question.）。","ipa":"[te.ɔ.ʁi]","ph":"th 读 [t]；é 读 [e]；o 读 [ɔ]；rie 读 [ʁi]。三个音节。","pi":"th 读 [t]，不是英语的 [θ]；o 和 e 之间要分开读：[te.ɔ.ʁi]。","et":"来自希腊语 theoria（观察，思考），经拉丁语进入法语。","ex":[["En théorie, c'est possible.","理论上这是可能的。"],["J'ai ma propre théorie sur ce sujet.","我对这个话题有自己的看法。"],["Cette théorie est controversée.","这个理论有争议。"]],"co":[["en théorie","理论上"],["une théorie scientifique","科学理论"],["la théorie et la pratique","理论与实践"],["une théorie du complot","阴谋论"]],"sy":[["hypothèse","courant","假设"],["doctrine","soutenu","学说；教义"],["idée","courant","想法"]],"fq":"中高频，日常和学习中常用。","me":"théorie ≈ 英语 theory：th 都读 [t]。","tr":{"zh":"理论上，这很简单。","fr":"En théorie, c'est facile.","alt":"Sur le papier, c'est facile.","note":"en théorie 放句首，后接逗号。"}},
 "Une contribution": {"pos":"n.f. 阴性名词，复数 contributions","s":"贡献；出资；投稿。如 apporter sa contribution（做出贡献）；une contribution financière（资金捐助）。动词是 contribuer à。","ipa":"[kɔ̃.tʁi.by.sjɔ̃]","ph":"con 读 [kɔ̃]；tri 读 [tʁi]；bu 读 [by]，u 读 [y]；-tion 读 [sjɔ̃]。","pi":"u 读 [y]，不是 [u]；-tion 读 [sjɔ̃]；contribuer 的后接介词是 à。","et":"来自拉丁语 contributio，由 con-（共同）加 tribuere（分配）构成。同族词：tribut、attribuer。","ex":[["Merci pour votre précieuse contribution.","感谢您宝贵的贡献。"],["Chacun apporte sa contribution.","每个人都做出自己的贡献。"],["Il demande une contribution de dix euros.","他要求每人出十欧元。"]],"co":[["apporter sa contribution","做出贡献"],["une contribution financière","资金捐助"],["contribuer à","有助于；促成"],["une précieuse contribution","宝贵的贡献"]],"sy":[["participation","courant","参与；出资"],["apport","soutenu","投入；贡献"],["don","courant","捐赠"]],"fq":"中高频，工作和新闻中常用。","me":"con-tribu：大家「一起（con）出力」。","tr":{"zh":"每个人都做出了贡献。","fr":"Chacun a apporté sa contribution.","alt":"Tout le monde a participé.","note":"chacun 配 sa / son；apporter sa contribution。"}},
 "L'attention": {"pos":"n.f. 阴性名词，复数 attentions","s":"注意；关注；专心。faire attention = 小心、注意；Attention ! = 小心！。复数 des attentions = 体贴的小举动。","ipa":"[a.tɑ̃.sjɔ̃]","ph":"a 读 [a]；tten 读 [tɑ̃]，tt 只读一个 [t]，en 读鼻化音 [ɑ̃]；-tion 读 [sjɔ̃]。","pi":"tt 读一个 [t]；en 读 [ɑ̃]，ion 读 [jɔ̃]，两个鼻化音不同；faire attention 之后用 à 或 de。","et":"来自拉丁语 attentio，源于 attendere（朝向……拉伸）。同族词：attendre（等待）。","ex":[["Merci pour votre attention.","感谢您的关注。"],["Fais attention à la marche !","小心台阶！"],["Elle fait très attention à sa santé.","她非常注意自己的健康。"]],"co":[["faire attention (à)","注意；小心"],["attirer l'attention","引起注意"],["prêter attention à","留意"],["À l'attention de","致（信封上，某人收）"]],"sy":[["concentration","courant","专注"],["vigilance","soutenu","警觉"],["soin","courant","用心；小心"]],"fq":"极高频，日常常用。","me":"attention ← attendre：把心思「伸向」某个对象。","tr":{"zh":"过马路要小心。","fr":"Fais attention en traversant la rue.","alt":"Attention quand tu traverses !","note":"faire attention + en + 现在分词 = 做……时要小心。"}},
 "L'affection": {"pos":"n.f. 阴性名词，复数 affections","s":"感情；喜爱；眷恋（对人或动物温暖的感情）。avoir de l'affection pour = 对……有感情。注意：在医学中也指「疾病」（une affection grave）。","ipa":"[a.fɛk.sjɔ̃]","ph":"a 读 [a]；ff 读一个 [f]；ec 读 [ɛk]；-tion 读 [sjɔ̃]。","pi":"ff 只读一个 [f]；c 在 t 前读 [k]；-tion 读 [sjɔ̃]。","et":"来自拉丁语 affectio（影响；倾向），源于 afficere。同族词：affecter、affectueux。","ex":[["Il a beaucoup d'affection pour son chien.","他对他的狗很有感情。"],["Elle manque d'affection.","她缺少关爱。"],["Je te dis toute mon affection.","谨致我所有的爱意。"]],"co":[["avoir de l'affection pour","对……有感情"],["manquer d'affection","缺少关爱"],["témoigner de l'affection","表达感情"],["une affection de la peau","一种皮肤疾病"]],"sy":[["tendresse","courant","温柔"],["amour","courant","爱，比 affection 更强"],["attachement","soutenu","依恋"]],"fq":"中频，日常和书信中常见。","me":"affection ≈ 英语 affection：温暖的「喜爱」。","tr":{"zh":"孩子们需要关爱。","fr":"Les enfants ont besoin d'affection.","alt":"Les enfants ont besoin qu'on les aime.","note":"avoir besoin de + 名词；抽象名词前用 d'。"}},
 "Une crise": {"pos":"n.f. 阴性名词，复数 crises","s":"危机；发作。une crise économique（经济危机）；une crise de nerfs（情绪失控）；une crise cardiaque（心脏病发作）。口语 faire une crise = 发脾气。","ipa":"[kʁiz]","ph":"cr 读 [kʁ]；i 读 [i]；s 读 [z]；结尾 e 不发音。一个音节。","pi":"s 读 [z]，不是 [s]；只有一个音节 [kʁiz]。","et":"来自希腊语 krisis（判断，转折点），经拉丁语进入法语。","ex":[["Le pays traverse une crise économique.","该国正经历经济危机。"],["Il fait une crise de colère.","他在大发脾气。"],["Elle a eu une crise d'asthme.","她哮喘发作了。"]],"co":[["une crise économique","经济危机"],["une crise cardiaque","心脏病发作"],["faire une crise","发脾气；大闹"],["en pleine crise","正值危机"]],"sy":[["problème","courant","问题"],["scène","familier","吵闹；发作"],["catastrophe","courant","灾难"]],"fq":"高频，日常和新闻中常用。","me":"crise 读 [kʁiz]，s 读 z，就像 crisis 里的 s。","tr":{"zh":"这个国家正处于危机中。","fr":"Le pays est en pleine crise.","alt":"Le pays traverse une crise.","note":"en pleine crise = 正处于危机之中。"}},
 "L'implication": {"pos":"n.f. 阴性名词，复数 implications","s":"投入；参与（程度）；牵连；含义。avoir de l'implication = 全情投入；implication dans une affaire = 涉入一件案子。动词 impliquer。","ipa":"[ɛ̃.pli.ka.sjɔ̃]","ph":"im 读鼻化音 [ɛ̃]；pli 读 [pli]；ca 读 [ka]；-tion 读 [sjɔ̃]。","pi":"im 读 [ɛ̃]，m 不单独发音；-tion 读 [sjɔ̃]；l'implication 中 l' 与元音相连。","et":"来自拉丁语 implicatio，由 in- 加 plicare（折叠）而来。同族词：compliqué、expliquer。","ex":[["Son implication dans le projet est totale.","他对项目全情投入。"],["Son implication dans l'affaire est prouvée.","他卷入此案已被证实。"],["Quelles sont les implications de cette décision ?","这个决定有哪些影响？"]],"co":[["une forte implication","高度投入"],["l'implication dans","投入于；牵涉到"],["les implications de","……的影响"],["manquer d'implication","缺乏投入"]],"sy":[["engagement","courant","投入；承诺"],["participation","courant","参与"],["conséquence","courant","后果"]],"fq":"中频，职场和新闻中常见。","me":"im-plic-ation：像英语 implication，把你「折」进事情里。","tr":{"zh":"他对工作非常投入。","fr":"Il a une forte implication dans son travail.","alt":"Il s'investit beaucoup dans son travail.","note":"s'investir 是更口语的说法。"}},
 "Une vigne": {"pos":"n.f. 阴性名词，复数 vignes","s":"葡萄藤；葡萄园（多指种在地里的葡萄株）。les vignes 常指一大片葡萄园。较大的葡萄园也叫 un vignoble。","ipa":"[viɲ]","ph":"v 读 [v]；i 读 [i]；gn 读 [ɲ]（类似「尼」音）；结尾 e 不发音。","pi":"gn 读 [ɲ]，不是 [gn]；g 不单独发音；结尾 e 不发音。","et":"来自拉丁语 vinea（葡萄园，葡萄藤），源于 vinum（酒）。同族词：vin、vigneron、vignoble。","ex":[["Cette région est couverte de vignes.","这个地区遍布葡萄园。"],["Mon grand-père a une petite vigne.","我爷爷有一小块葡萄园。"],["Les vignes sont magnifiques en automne.","秋天的葡萄园很美。"]],"co":[["une vigne en fleur","开花的葡萄藤"],["cultiver la vigne","种植葡萄"],["les vignes de Bourgogne","勃艮第的葡萄园"],["un pied de vigne","一株葡萄树"]],"sy":[["vignoble","courant","葡萄种植区"],["raisin","courant","葡萄（果实）"],["vin","courant","葡萄酒"]],"fq":"中低频，谈到葡萄酒和乡村时常见。","me":"vigne ← vin：长出「酒」的藤。","tr":{"zh":"他在乡下有一块葡萄园。","fr":"Il a une vigne à la campagne.","alt":"Il possède des vignes à la campagne.","note":"à la campagne = 在乡下。"}},
 "Une falaise": {"pos":"n.f. 阴性名词，复数 falaises","s":"悬崖；陡峭的海边崖壁（如诺曼底的 les falaises d'Étretat）。比 une montagne 更陡，常指海边的白色峭壁。","ipa":"[fa.lɛz]","ph":"fa 读 [fa]；lai 读 [lɛ]；se 中 s 在元音间读 [z]；结尾 e 不发音。","pi":"s 读 [z]，不是 [s]；ai 读 [ɛ]。","et":"来自古法语 falise，源于法兰克语（日耳曼语）。","ex":[["Ils se promènent au bord de la falaise.","他们在悬崖边散步。"],["Les falaises d'Étretat sont célèbres.","埃特勒塔的悬崖很有名。"],["Attention, la falaise est dangereuse !","小心，悬崖很危险！"]],"co":[["au bord de la falaise","在悬崖边"],["une falaise de craie","白垩峭壁"],["tomber d'une falaise","从悬崖上掉下来"],["une falaise abrupte","陡峭的悬崖"]],"sy":[["rocher","courant","岩石"],["précipice","soutenu","深渊；绝壁"],["à-pic","soutenu","绝壁"]],"fq":"中低频，旅游和风景描写中常见。","me":"falaise 读 [fa.lɛz]：想像「海边的白色峭壁」。","tr":{"zh":"我们沿着悬崖散步。","fr":"Nous nous promenons le long de la falaise.","alt":"On se balade au bord de la falaise.","note":"le long de = 沿着；se balader 是口语。"}},
 "La discipline": {"pos":"n.f. 阴性名词，复数 disciplines","s":"纪律；自律；学科（une discipline scolaire / sportive 即学科或运动项目）。avoir de la discipline = 有纪律。","ipa":"[di.si.plin]","ph":"di 读 [di]；sci 读 [si]，sc 读 [s]；pline 读 [plin]，e 不发音。","pi":"sc 在 i 前读 [s]，不是 [sk]；三个音节：di-si-plin。","et":"来自拉丁语 disciplina（教导，训练），源于 discipulus（学生）。","ex":[["Il manque de discipline.","他缺乏纪律。"],["Le judo demande beaucoup de discipline.","柔道需要很强的自律。"],["Quelle est votre discipline sportive ?","您的运动项目是什么？"]],"co":[["manquer de discipline","缺乏纪律"],["la discipline scolaire","校规；学校纪律"],["une discipline sportive","运动项目"],["une discipline de fer","铁一般的纪律"]],"sy":[["rigueur","courant","严谨"],["ordre","courant","秩序"],["matière","courant","学科（课程）"]],"fq":"中高频，日常和学校语境常用。","me":"discipline ← discipulus：「学生」应守的规矩。","tr":{"zh":"孩子们需要纪律。","fr":"Les enfants ont besoin de discipline.","alt":"Il faut de la discipline avec les enfants.","note":"avoir besoin de + 无冠词的抽象名词。"}},
 "Une observation": {"pos":"n.f. 阴性名词，复数 observations","s":"观察；意见；评语。faire une observation = 提出意见；也可指老师或上级的批评（faire des observations）。动词是 observer。","ipa":"[ɔp.sɛʁ.va.sjɔ̃]","ph":"ob 读 [ɔp]，b 在 s 前读 [p]；ser 读 [sɛʁ]；va 读 [va]；-tion 读 [sjɔ̃]。","pi":"b 读 [p]，所以是 [ɔp]，不是 [ɔb]；-tion 读 [sjɔ̃]。","et":"来自拉丁语 observatio，源于 observare（注视，遵守）。同族词：observer、observatoire。","ex":[["J'ai fait une observation intéressante.","我做了一个有趣的观察。"],["Le professeur m'a fait une observation.","老师批评了我。"],["Avez-vous des observations à faire ?","您有什么意见要提吗？"]],"co":[["faire une observation","提出意见；做观察"],["sous observation","在观察之下"],["l'observation des étoiles","观星"],["un esprit d'observation","观察力"]],"sy":[["remarque","courant","评语；意见"],["constat","soutenu","确认；确认的结果"],["critique","courant","批评"]],"fq":"中高频，日常和学习中常用。","me":"ob-serv-ation ≈ 英语 observation，ob 读 [ɔp]。","tr":{"zh":"我有一个意见要提。","fr":"J'ai une observation à faire.","alt":"Je voudrais faire une remarque.","note":"une observation à faire：à + 不定式表示要做的事。"}},
 "Une enseigne": {"pos":"n.f. 阴性名词，复数 enseignes","s":"招牌；店名；连锁店（une grande enseigne = 大连锁品牌）。注意：和动词 enseigner（教）同源，但这里指「标志」。常见搭配：une enseigne lumineuse（霓虹招牌）。","ipa":"[ɑ̃.sɛɲ]","ph":"en 读鼻化音 [ɑ̃]；ei 读 [ɛ]；gn 读 [ɲ]；结尾 e 不发音。","pi":"ei 读 [ɛ]；gn 读 [ɲ]，不是 [gn]；en 读 [ɑ̃]，n 不发。","et":"来自拉丁语 insignia（标志，徽章）。同族词：enseigner（教，原义「指出」）。","ex":[["C'est une grande enseigne de bricolage.","这是一家大型建材连锁店。"],["L'enseigne du magasin est très lumineuse.","这家商店的招牌很亮。"],["Cette enseigne ouvre de nouveaux magasins.","这个连锁品牌正在开新店。"]],"co":[["une grande enseigne","大型连锁品牌"],["une enseigne lumineuse","霓虹招牌"],["l'enseigne d'un magasin","商店招牌"],["à l'enseigne de","以……为店名"]],"sy":[["marque","courant","品牌"],["panneau","courant","牌子"],["chaîne","courant","连锁（店）"]],"fq":"中频，购物和商业语境常见。","me":"enseigne ← insignia：挂在店门口的「标志」。","tr":{"zh":"这是一家有名的连锁店。","fr":"C'est une enseigne très connue.","alt":"C'est une grande chaîne de magasins.","note":"enseigne 阴性：une enseigne。"}},
 "La grande distribution": {"pos":"n.f. 阴性名词（固定词组，一般用单数）","s":"大型零售业；超市和大卖场这类大型零售行业（如 Carrefour、Leclerc）。指整个行业，不指单个商店。","ipa":"[gʁɑ̃d.dis.tʁi.by.sjɔ̃]","ph":"grande 读 [gʁɑ̃d]，d 要读；distribution 读 [dis.tʁi.by.sjɔ̃]，u 读 [y]；-tion 读 [sjɔ̃]。","pi":"阴性形容词 grande 的 d 要发音 [gʁɑ̃d]；u 读 [y]；distribution 五个音节。","et":"grand（拉丁语 grandis）+ distribution（拉丁语 distributio，分发）。是商业术语。","ex":[["Il travaille dans la grande distribution.","他在大型零售业工作。"],["La grande distribution domine le marché.","大型零售业主导着市场。"],["Les prix sont plus bas dans la grande distribution.","大型零售店的价格更低。"]],"co":[["travailler dans la grande distribution","在大型零售业工作"],["les enseignes de la grande distribution","大型零售连锁品牌"],["un supermarché de la grande distribution","大型零售超市"],["la distribution alimentaire","食品零售"]],"sy":[["supermarché","courant","超市"],["commerce","courant","商业"],["hypermarché","courant","大卖场"]],"fq":"中频，新闻和职场话题中常见。","me":"grande + distribution：把商品「大规模分发」给顾客。","tr":{"zh":"我妹妹在大型零售业工作。","fr":"Ma sœur travaille dans la grande distribution.","alt":"Ma sœur est employée dans un supermarché.","note":"dans + 行业名称：dans la grande distribution。"}},
 "Une initiative": {"pos":"n.f. 阴性名词，复数 initiatives","s":"倡议；主动精神；创举。prendre l'initiative de = 主动做某事；de sa propre initiative = 自己主动地；avoir de l'initiative = 有主见、有行动力。","ipa":"[i.ni.sja.tiv]","ph":"i 读 [i]；ni 读 [ni]；tia 读 [sja]，t 读 [s]；tive 读 [tiv]，e 不发。","pi":"ti 在这里读 [sj]，不是 [ti]（与 -tion 同类）；注意结尾 v 要读出来。","et":"来自拉丁语 initium（开始），经 initier 派生。同族词：initial、initiation。","ex":[["C'est une excellente initiative.","这是一个很好的倡议。"],["Il a pris l'initiative d'appeler le directeur.","他主动给主管打了电话。"],["Elle manque d'initiative.","她缺乏主动性。"]],"co":[["prendre l'initiative de","主动做……"],["de sa propre initiative","自己主动地"],["une bonne initiative","好主意；好倡议"],["à l'initiative de","由……发起"]],"sy":[["idée","courant","主意"],["démarche","courant","行动；做法"],["entreprise","soutenu","举措"]],"fq":"中高频，工作和新闻中常用。","me":"initiative ← initium：「开头」的人，就是主动的人。","tr":{"zh":"他主动提出帮忙。","fr":"Il a pris l'initiative de proposer son aide.","alt":"Il a proposé son aide de lui-même.","note":"prendre l'initiative de + 不定式。"}},
 "De l'humanité": {"pos":"n.f. 阴性名词（此处为部分冠词形式 de l'）","s":"人性；人情味；人类。de l'humanité 表示「一些人情味」，用法是不可数。l'humanité 也指整个人类。avec humanité = 以仁慈的方式。","ipa":"[y.ma.ni.te]","ph":"h 不发音，不连读；u 读 [y]；ma 读 [ma]；ni 读 [ni]；té 读 [te]。四个音节。","pi":"h 是哑音，l' 省音，所以是 l'humanité；u 读 [y]；不要读成英语 humanity 的音。","et":"来自拉丁语 humanitas，源于 humanus（人的）。同族词：humain、humaniste。","ex":[["Les gens isolés souhaitent retrouver plus d'humanité.","孤立的人想找回更多人情味。"],["Il traite les animaux avec humanité.","他很有同情心地对待动物。"],["L'humanité doit protéger la planète.","人类应该保护地球。"]],"co":[["avec humanité","仁慈地"],["manquer d'humanité","缺乏人情味"],["faire preuve d'humanité","展现同情心"],["l'humanité entière","全人类"]],"sy":[["bonté","soutenu","善良"],["compassion","soutenu","同情"],["l'humain","courant","人性（中性词）"]],"fq":"中频，书面和新闻中常见。","me":"humanité ← humain：人身上的「人味」。","tr":{"zh":"我们需要更多人情味。","fr":"Nous avons besoin de plus d'humanité.","alt":"On a besoin de plus d'humain.","note":"besoin de + plus d' + 名词。"}},
 "La gentillesse": {"pos":"n.f. 阴性名词，复数 gentillesses","s":"善良；亲切；好意。une gentillesse 也可以指一句体贴的话或一个小善举。形容词是 gentil(le)。注意 gentil 不是「温柔」，更像「友善、好心」。","ipa":"[ʒɑ̃.ti.jɛs]","ph":"g 在 e 前读 [ʒ]；en 读 [ɑ̃]；ti 读 [ti]；lle 读 [j]（这里 ill 读 [j]）；esse 读 [ɛs]。","pi":"gentil 的 l 不单独发音，是 [ʒɑ̃.ti]；gentillesse 中 ll 读 [j]：[ʒɑ̃.ti.jɛs]，ss 读 [s]。","et":"由 gentil（拉丁语 gentilis，出身良好的）加后缀 -esse 构成。-esse 用来构成抽象名词。","ex":[["Merci pour votre gentillesse.","谢谢您的好意。"],["Elle a une grande gentillesse.","她非常善良。"],["Il m'a dit des gentillesses.","他对我说了些好听的话。"]],"co":[["avec gentillesse","亲切地"],["par gentillesse","出于好心"],["avoir la gentillesse de","好心地……"],["une grande gentillesse","极大的善良"]],"sy":[["bonté","soutenu","善良"],["amabilité","soutenu","和蔼"],["sympathie","courant","好感；亲切"]],"fq":"高频，日常常用。","me":"gentil + -esse：「gentil 的状态」，像 tendre → tendresse。","tr":{"zh":"谢谢你的好意。","fr":"Merci pour ta gentillesse.","alt":"C'est très gentil de ta part.","note":"对朋友用 ta，对不熟的人用 votre。"}},
 "Une brigade": {"pos":"n.f. 阴性名词，复数 brigades","s":"小队；分队；旅（军队编制）。如 la brigade des mineurs（未成年人警察队）；une brigade de cuisine（厨房团队）。brigadier 是班长或警察的一个级别。","ipa":"[bʁi.gad]","ph":"br 读 [bʁ]；i 读 [i]；ga 读 [ga]，g 在 a 前读 [g]；de 中 d 要读，e 不发。","pi":"g 在 a 前读 [g]；结尾 de 的 d 要读出来：[gad]。","et":"来自意大利语 brigata（队伍），经法语使用。","ex":[["La brigade d'intervention est sur place.","干预小队已经到场。"],["Il travaille dans la brigade de cuisine.","他在厨房团队工作。"],["La brigade des pompiers est arrivée.","消防队来了。"]],"co":[["une brigade de police","警察分队"],["la brigade des stupéfiants","缉毒队"],["la brigade des pompiers","消防队"],["une brigade de cuisine","厨房团队"]],"sy":[["équipe","courant","团队"],["unité","courant","单位；分队"],["escouade","soutenu","小队"]],"fq":"中低频，警察、军队和餐厅语境常见。","me":"brigade ≈ 英语 brigade：一小队人。","tr":{"zh":"警察小队很快就到了。","fr":"La brigade de police est arrivée vite.","alt":"La police est vite arrivée.","note":"arriver 用 être：est arrivée，与阴性主语一致。"}},
 "La souplesse": {"pos":"n.f. 阴性名词（一般用单数）","s":"柔软；灵活；变通。可以指身体柔软（la souplesse du corps）或做事灵活（la souplesse d'un horaire）。形容词是 souple。","ipa":"[su.plɛs]","ph":"sou 读 [su]；ou 读 [u]；ple 读 [plɛs] 中 p-l 连读为 [pl]；esse 读 [ɛs]。","pi":"ou 读 [u]；ss 读 [s]；souple 只有两个音节 [su.pl]，souplesse 三个音节 [su.plɛs]，不要加元音。","et":"由 souple（拉丁语 supplex，弯曲的）加 -esse 构成。-esse 用于构成抽象名词。","ex":[["Ce métier demande beaucoup de souplesse.","这个职业需要很大的灵活性。"],["La gymnastique demande de la souplesse.","体操需要柔韧性。"],["Les horaires offrent plus de souplesse.","工作时间提供更多弹性。"]],"co":[["avec souplesse","灵活地"],["manquer de souplesse","缺乏弹性"],["la souplesse des horaires","时间弹性"],["faire preuve de souplesse","表现出灵活性"]],"sy":[["flexibilité","courant","灵活性，更常用"],["agilité","courant","敏捷"],["rigidité","courant","反义：僵硬"]],"fq":"中频，工作和运动语境常见。","me":"souple + -esse：souple（软）→ souplesse（柔软度）。","tr":{"zh":"这份工作需要灵活性。","fr":"Ce travail demande de la souplesse.","alt":"Il faut être souple dans ce travail.","note":"demander de la + 抽象名词。"}},
 "La disponibilité": {"pos":"n.f. 阴性名词，复数 disponibilités","s":"有空；可用；随时待命。Merci pour votre disponibilité = 谢谢您抽出时间。也指商品「有货」。复数 les disponibilités 指可动用的资金。","ipa":"[dis.pɔ.ni.bi.li.te]","ph":"dis 读 [dis]；po 读 [pɔ]；ni 读 [ni]；bi 读 [bi]；li 读 [li]；té 读 [te]。六个音节。","pi":"音节较多，逐个读：dis-po-ni-bi-li-té；s 在 dis 中读 [s]；é 读 [e]。","et":"由 disponible（可使用的，源于拉丁语 disponere，分配）加后缀 -ité 构成。","ex":[["Merci pour votre disponibilité.","谢谢您抽出时间。"],["Quelles sont vos disponibilités cette semaine ?","您这周什么时候有空？"],["Nous vérifions la disponibilité du produit.","我们正在核对产品是否有货。"]],"co":[["selon vos disponibilités","根据您的时间"],["la disponibilité d'un produit","产品供货情况"],["en fonction de ma disponibilité","按我的时间而定"],["une grande disponibilité","随时待命"]],"sy":[["temps libre","courant","空闲时间"],["accessibilité","soutenu","可及性"],["libre","courant","形容词：空闲的"]],"fq":"中高频，工作和预约中常用。","me":"disponible + -ité：「可用」的状态。","tr":{"zh":"请告诉我你什么时候有空。","fr":"Dites-moi quelles sont vos disponibilités.","alt":"Dites-moi quand vous êtes libre.","note":"disponibilités 常用复数，指可以的时间段。"}},
 "Une commune": {"pos":"n.f. 阴性名词，复数 communes","s":"市镇；法国最小的行政区（由 le maire 管理）。J'habite dans une petite commune = 我住在一个小镇。注意：La Commune de Paris 是历史事件（巴黎公社）。","ipa":"[kɔ.myn]","ph":"co 读 [kɔ]；mmu 中 mm 读一个 [m]，u 读 [y]；结尾 ne 读 [n]，e 不发音。","pi":"u 读 [y]；mm 只读一个 [m]；注意 commune 与形容词 commun(e)（共同的）同形，commune 作名词时是阴性。","et":"来自拉丁语 communis（共同的）。同族词：commun、communauté、communiquer。","ex":[["J'habite dans une petite commune.","我住在一个小镇。"],["La mairie de la commune est ouverte le lundi.","镇政府周一开门。"],["La commune a organisé une fête.","市镇办了一场庆祝活动。"]],"co":[["une petite commune","小镇"],["la mairie de la commune","镇政府"],["le maire de la commune","镇长"],["la Commune de Paris","巴黎公社"]],"sy":[["ville","courant","城市"],["village","courant","村庄"],["municipalité","soutenu","市政当局"]],"fq":"中频，行政和新闻语境常见。","me":"commune ← commun：「共同」生活的一群人。","tr":{"zh":"我们镇有三千居民。","fr":"Notre commune a trois mille habitants.","alt":"Dans notre commune, il y a trois mille habitants.","note":"avoir + 数字 + habitants。"}},
 "La morosité": {"pos":"n.f. 阴性名词（一般用单数）","s":"阴郁；沉闷；低迷。指气氛、情绪或经济不景气，如 la morosité ambiante（弥漫的低落情绪）、la morosité économique。形容词是 morose。","ipa":"[mɔ.ʁo.zi.te]","ph":"mo 读 [mɔ]；ro 读 [ʁo]；si 中 s 在元音间读 [z]；té 读 [te]。四个音节。","pi":"s 读 [z]，不是 [s]；第一个 o 读 [ɔ]，第二个 o 读 [o]。","et":"由 morose（拉丁语 morosus，乖僻的）加后缀 -ité 构成。","ex":[["L'ambiance générale est à la morosité.","总体气氛很沉闷。"],["La morosité économique inquiète les gens.","经济低迷让人们担忧。"],["Il faut sortir de cette morosité.","要走出这种低落的状态。"]],"co":[["la morosité ambiante","弥漫的低落气氛"],["la morosité économique","经济低迷"],["sortir de la morosité","走出低落"],["sombrer dans la morosité","陷入沉闷"]],"sy":[["tristesse","courant","悲伤"],["grisaille","courant","灰暗；沉闷"],["déprime","familier","情绪低落"]],"fq":"低频，新闻和书面语中出现。","me":"morose + -ité：像一天「灰蒙蒙」的心情。","tr":{"zh":"最近大家情绪都很低落。","fr":"Il y a de la morosité en ce moment.","alt":"L'ambiance est morose en ce moment.","note":"il y a de la + 抽象名词。"}},
 "Une trompette": {"pos":"n.f. 阴性名词，复数 trompettes","s":"小号（铜管乐器）。jouer de la trompette = 吹小号。trompettiste 是吹小号的人。也可指喇叭形的东西。","ipa":"[tʁɔ̃.pɛt]","ph":"trom 读 [tʁɔ̃]，om 是鼻化音；pe 读 [pɛ]；tte 读 [t]，e 不发。","pi":"om 在 p 前读鼻化音 [ɔ̃]，m 不单独发音；tt 只读一个 [t]；结尾 e 不发音。","et":"由 trompe（号角，源于日耳曼语的拟声词）加指小后缀 -ette 构成：「小号角」。","ex":[["Il joue de la trompette.","他吹小号。"],["Elle apprend la trompette depuis deux ans.","她学小号已经两年了。"],["J'entends une trompette dans la rue.","我听见街上有人吹小号。"]],"co":[["jouer de la trompette","吹小号"],["un joueur de trompette","小号手"],["une trompette de jazz","爵士小号"],["sonner de la trompette","吹响喇叭"]],"sy":[["cor","courant","圆号"],["clairon","courant","军号"],["trombone","courant","长号"]],"fq":"中低频，谈音乐时常见。","me":"trompe + -ette：小的「喇叭」。","tr":{"zh":"我弟弟吹小号。","fr":"Mon frère joue de la trompette.","alt":"Mon frère est trompettiste.","note":"jouer de + 乐器（de la / du / de l'）。"}},
 "Une guerre": {"pos":"n.f. 阴性名词，复数 guerres","s":"战争。la Première / Seconde Guerre mondiale = 第一次 / 第二次世界大战；比喻义：une guerre des prix（价格战）。guerre 的形容词是 guerrier。","ipa":"[gɛʁ]","ph":"gu 读 [g]，u 不发音；e 读 [ɛ]；rre 读 [ʁ]，结尾 e 不发。一个音节。","pi":"gu 读 [g]，不是 [gy]；rr 只读一个 [ʁ]。","et":"来自法兰克语（日耳曼语）werra，意为「混乱，争斗」。英语 war 同源。","ex":[["La guerre a détruit le pays.","战争摧毁了这个国家。"],["Mon grand-père a connu la guerre.","我爷爷经历过战争。"],["Ils sont en guerre depuis longtemps.","他们已经交战很久了。"]],"co":[["faire la guerre","打仗"],["déclarer la guerre","宣战"],["en temps de guerre","战时"],["la guerre froide","冷战"]],"sy":[["conflit","courant","冲突"],["bataille","courant","战役"],["paix","courant","反义：和平"]],"fq":"高频，日常和新闻中常见。","me":"guerre 与英语 war 同源（gu = w）。","tr":{"zh":"战争持续了很多年。","fr":"La guerre a duré plusieurs années.","alt":"La guerre a duré des années.","note":"durer 复合过去时用 avoir。"}},
 "Un utilisateur / Une utilisatrice": {"pos":"n. 名词，阳性 utilisateur / 阴性 utilisatrice（复数 utilisateurs / utilisatrices）","s":"用户；使用者（软件、网站、应用、设备等）。utilisateur 是阳性，utilisatrice 是阴性。动词是 utiliser。","ipa":"[y.ti.li.za.tœʁ]","ph":"u 读 [y]；ti 读 [ti]；li 读 [li]；sa 中 s 读 [z]；-teur 读 [tœʁ]；阴性 utilisatrice 读 [y.ti.li.za.tʁis]。","pi":"第一个 u 读 [y]；s 读 [z]；-eur 读 [œʁ]，r 要发；ti 读 [ti] 不是 [si]。","et":"由动词 utiliser（使用）加后缀 -eur 构成；utiliser 来自拉丁语 utilis（有用的）。","ex":[["Ce logiciel est facile pour l'utilisateur.","这个软件对用户来说很容易。"],["Chaque utilisatrice reçoit un code.","每位女用户会收到一个代码。"],["Les utilisateurs sont très satisfaits.","用户们非常满意。"]],"co":[["un utilisateur régulier","常用用户"],["un nouvel utilisateur","新用户"],["le nom d'utilisateur","用户名"],["l'expérience utilisateur","用户体验"]],"sy":[["usager","courant","使用者（公共服务）"],["client","courant","客户"],["consommateur","courant","消费者"]],"fq":"中高频，科技和日常中常用。","me":"utilis + -ateur：「用东西的人」。","tr":{"zh":"每位用户都有一个账号。","fr":"Chaque utilisateur a un compte.","alt":"Tous les utilisateurs ont un compte.","note":"chaque 后接单数名词。"}},
 "Un(e) économiste": {"pos":"n. 名词，阳性、阴性同形 économiste（复数 économistes）","s":"经济学家；研究经济的人。un économiste（男）/ une économiste（女），形式相同，只改冠词。","ipa":"[e.kɔ.nɔ.mist]","ph":"é 读 [e]；co 读 [kɔ]；no 读 [nɔ]；miste 读 [mist]，e 不发音，但 s、t 都读。","pi":"-iste 的 s 和 t 都要读出来 [mist]；é 读 [e]。","et":"由 économie（希腊语 oikonomia，家政管理）加后缀 -iste 构成。","ex":[["Cet économiste est très célèbre.","这位经济学家很有名。"],["Cette économiste travaille à la banque centrale.","这位女经济学家在央行工作。"],["Les économistes prévoient une hausse.","经济学家预计会上涨。"]],"co":[["un économiste reconnu","知名经济学家"],["un économiste de la banque","银行经济学家"],["selon les économistes","据经济学家称"],["un économiste en chef","首席经济学家"]],"sy":[["analyste","courant","分析师"],["expert","courant","专家"],["financier","courant","金融家"]],"fq":"中频，新闻中常见。","me":"économie + -iste：研究「家政」的人，后来是经济。","tr":{"zh":"这位经济学家写了一本书。","fr":"Cet économiste a écrit un livre.","alt":"Cette économiste a écrit un livre.","note":"économiste 阴阳同形，由冠词或指示词判断性别。"}},
 "Un(e) militant(e)": {"pos":"n. 名词，阳性 militant / 阴性 militante（复数 militants / militantes）","s":"积极分子；活动人士；党员或社团活跃成员。militant 不一定指好战或暴力，多指为某种理念积极行动的人，如 un militant écologiste（环保活动人士）。也可作形容词。","ipa":"[mi.li.tɑ̃]","ph":"mi 读 [mi]；li 读 [li]；tant 读 [tɑ̃]，an 是鼻化音，结尾 t 不发音；阴性 militante 读 [mi.li.tɑ̃t]，t 发音。","pi":"阳性结尾 -ant 读 [ɑ̃]，t 不发音；阴性 -ante 读 [ɑ̃t]，t 要发。","et":"来自动词 militer（斗争），拉丁语 militare（当兵），源于 miles（士兵）。","ex":[["C'est un militant pour les droits de l'homme.","他是人权活动人士。"],["Cette militante défend l'environnement.","这位女活动人士保护环境。"],["Les militants distribuent des tracts.","活动人士在发传单。"]],"co":[["un militant écologiste","环保活动人士"],["un militant du parti","党员；党的积极分子"],["militer pour / contre","为……/反对……而奔走"],["un militant associatif","社团活动人士"]],"sy":[["activiste","courant","积极分子"],["adhérent","courant","会员"],["partisan","courant","支持者"]],"fq":"中频，新闻中常见。","me":"militant ← militaire：为理念「战斗」，但是用行动不是武器。","tr":{"zh":"她是一位环保活动人士。","fr":"C'est une militante écologiste.","alt":"Elle milite pour l'environnement.","note":"militante 阴性，e 使 t 发音。"}},
 "Un(e) soignant(e)": {"pos":"n. 名词，阳性 soignant / 阴性 soignante（复数 soignants / soignantes）","s":"医护人员；护理人员（护士、护工、医生等照顾病人的人）。是 soigner（照料；治疗）的现在分词名词化，疫情期间使用很多。","ipa":"[swa.ɲɑ̃]","ph":"soi 读 [swa]；gn 读 [ɲ]；ant 读 [ɑ̃]，结尾 t 不发音；阴性 soignante 读 [swa.ɲɑ̃t]。","pi":"oi 读 [wa]；gn 读 [ɲ]，不是 [gn]；阳性结尾 t 不发音。","et":"来自动词 soigner（照料）的现在分词 soignant。","ex":[["Les soignants font un travail formidable.","医护人员做着了不起的工作。"],["Cette soignante travaille la nuit.","这位女护理人员上夜班。"],["On manque de soignants dans les hôpitaux.","医院里缺少医护人员。"]],"co":[["le personnel soignant","医护人员"],["applaudir les soignants","为医护人员鼓掌"],["un soignant à domicile","上门护理人员"],["manquer de soignants","缺少医护人员"]],"sy":[["infirmier / infirmière","courant","护士"],["médecin","courant","医生"],["aide-soignant","courant","护理员"]],"fq":"中频，新闻和医疗话题中常见。","me":"soigner → soignant：「正在照顾别人的人」。","tr":{"zh":"医护人员今天很忙。","fr":"Les soignants sont très occupés aujourd'hui.","alt":"Le personnel soignant a beaucoup de travail aujourd'hui.","note":"les soignants 泛指一群人，不分性别。"}},
 "Un citoyen / Une citoyenne": {"pos":"n. 名词，阳性 citoyen / 阴性 citoyenne（复数 citoyens / citoyennes）","s":"公民；市民。指有权利和义务的国家成员。一个国家的 citoyen 有选举权。形容词 citoyen(ne) = 有公民意识的（un geste citoyen）。","ipa":"[si.twa.jɛ̃]","ph":"ci 读 [si]；toy 读 [twa]，oy 读 [wa]；en 读 [jɛ̃]（ien 为 [jɛ̃]）。阴性 citoyenne 读 [si.twa.jɛn]。","pi":"-yen 读 [jɛ̃]，n 不单独发音；阴性 -yenne 读 [jɛn]，n 发音。","et":"来自古法语 citeien，源于 cité（城邦，拉丁语 civitas）。同族词：civil、civique。","ex":[["Chaque citoyen a le droit de voter.","每位公民都有投票权。"],["Cette citoyenne s'engage dans sa ville.","这位女市民积极参与城市事务。"],["Les citoyens demandent plus de transparence.","公民们要求更高的透明度。"]],"co":[["un citoyen français","法国公民"],["un simple citoyen","普通市民"],["un geste citoyen","有公民意识的举动"],["les droits du citoyen","公民权利"]],"sy":[["habitant","courant","居民"],["ressortissant","soutenu","国民；侨民"],["concitoyen","soutenu","同胞"]],"fq":"中高频，新闻和政治话题中常用。","me":"citoyen ← cité：城里（cité）的人。","tr":{"zh":"每个公民都应该投票。","fr":"Chaque citoyen devrait voter.","alt":"Tous les citoyens devraient voter.","note":"devrait：条件式，表示建议。"}},
 "Un éducateur / Une éducatrice": {"pos":"n.m./n.f. 名词，阴阳性不同：éducateur / éducatrice，复数 éducateurs / éducatrices","s":"教育工作者，常指在福利机构、儿童之家、托幼机构里陪伴和教育孩子或青少年的专业人员。注意：它不是学校老师，老师说 enseignant / professeur。","ipa":"[e.dy.ka.tœʁ] / [e.dy.ka.tʁis]","ph":"é [e]；u 读 [y]（嘴唇圆起，发「衣」的音）；-eur [œʁ]，-rice [ʁis]。","pi":"u 不是「乌」[u]，而是 [y]；结尾 -eur 的 r 要发；阴性 -trice 读 [tʁis]，不是 -teuse。","et":"来自拉丁语 educare（抚养、教育）；同族：éducation、éduquer。后缀 -teur / -trice 表示做某事的人。","ex":[["C'est un excellent éducateur.","他是出色的教育者。"],["Ma sœur est éducatrice dans un foyer pour enfants.","我姐姐在一家儿童之家当教育工作者。"]],"co":[["un éducateur spécialisé","特殊教育工作者"],["un éducateur de jeunes enfants","幼儿教育工作者"],["un éducateur sportif","体育教练"]],"sy":[["enseignant","courant","教师（在学校授课）"],["professeur","courant","中学或大学的老师"],["animateur","courant","活动带领者（夏令营等）"]],"fq":"中频，职业与社会话题常用。","me":"éduquer 的人 = éducateur：和 éducation 连在一起记。","tr":{"zh":"我姐姐是特殊教育工作者。","fr":"Ma sœur est éducatrice spécialisée.","alt":"Ma sœur travaille comme éducatrice spécialisée.","note":"说明职业时，être 后面通常不加冠词。"}},
 "Un caissier / Une caissière": {"pos":"n.m./n.f. 名词：caissier / caissière，复数 caissiers / caissières","s":"收银员，在超市、商店收款的人；银行里的出纳也叫 caissier。来自 caisse（收银台；钱箱）。","ipa":"[kɛ.sje] / [kɛ.sjɛʁ]","ph":"ai [ɛ]；ss [s]；-ier [je]（结尾 r 不发）；阴性 -ière [jɛʁ]（r 要发）。","pi":"阳性 caissier 结尾 r 不发，阴性 caissière 的 r 要发；ai 读 [ɛ]，不是「艾」。","et":"来自 caisse（钱箱、收银台）加后缀 -ier（表示从事某职业的人）。同族：caisse。","ex":[["Le caissier m'a rendu la monnaie.","收银员找了我零钱。"],["La caissière scanne les articles.","收银员在扫描商品。"]],"co":[["passer à la caisse","去收银台结账"],["une caisse automatique","自助收银机"],["le caissier du supermarché","超市收银员"]],"sy":[["hôte de caisse","courant","超市里的正式叫法"],["vendeur","courant","售货员，不一定收钱"],["guichetier","courant","窗口办事员（银行、邮局）"]],"fq":"中频，购物场景常用。","me":"caisse（钱箱）+ -ier：守着钱箱的人。","tr":{"zh":"收银员给了我发票。","fr":"La caissière m'a donné le ticket de caisse.","alt":"La caissière m'a donné mon ticket.","note":"ticket de caisse = 购物小票；donner à qqn 用间接宾语 m'。"}},
 "Un hôte de caisse / Une hôtesse de caisse": {"pos":"n.m./n.f. 名词词组：hôte de caisse / hôtesse de caisse，复数 hôtes de caisse / hôtesses de caisse","s":"收银员，超市里 caissier / caissière 的比较「正式」的新叫法，强调还要接待顾客。hôte 本义是「主人」，也可指「客人」。","ipa":"[ot.də.kɛs] / [o.tɛs.də.kɛs]","ph":"hôte 的 h 不发音，ô [o]；de 轻读 [də]；caisse [kɛs]，ai 读 [ɛ]，结尾 e 不发。","pi":"h 不发音：hôte [ot]；注意阴性 hôtesse 的 -sse 读 [s]，e 不发音在最后：[o.tɛs]。","et":"hôte 来自拉丁语 hospes（主人；客人），同族：hôtel、hôpital、hospitalité。","ex":[["L'hôtesse de caisse est très souriante.","收银员总是笑容满面。"],["Un hôte de caisse m'a aidé à payer.","一位收银员帮我付了款。"]],"co":[["un hôte de caisse","收银员（超市）"],["une hôtesse de l'air","空姐"],["une hôtesse d'accueil","前台接待员"]],"sy":[["caissier / caissière","courant","最常用的说法"],["employé de caisse","courant","收银岗位的员工"]],"fq":"中低频，多见于超市招聘和公告。","me":"hôte 是「接待你的人」：连收银时也在接待顾客。","tr":{"zh":"超市在招收银员。","fr":"Le supermarché recrute des hôtes de caisse.","alt":"Le supermarché cherche des hôtesses de caisse.","note":"recruter = 招聘；复数 hôtes de caisse 只有 hôtes 加 s。"}},
 "Un(e) responsable (un manager)": {"pos":"n.m./n.f. 名词，阴阳同形：un responsable / une responsable，复数 responsables","s":"负责人，主管，经理。可指团队、部门或某项任务的负责人，如 un responsable des ventes。也是形容词：responsable de qqch = 对……负责。un manager 是借自英语的说法，更偏企业。","ipa":"[ʁɛs.pɔ̃.sabl]","ph":"r 是小舌音 [ʁ]；on [ɔ̃] 鼻音；结尾 -able 读 [abl]，e 不发音。","pi":"on 是鼻化元音 [ɔ̃]，n 不单独发；阴阳同形，只靠冠词 un / une 区分；只有一个 s，但夹在 [ɛs] 里读 [s]。","et":"来自拉丁语 respondere（回答）：负责人就是要「回应、承担」后果的人。同族：responsabilité、répondre。","ex":[["Demandez à voir le responsable.","请叫负责人来。"],["Elle est responsable du service client.","她是客服部门的负责人。"]],"co":[["le responsable de + 名词","……的负责人"],["être responsable de qqch","对某事负责"],["un responsable des ressources humaines","人力资源主管"]],"sy":[["chef","courant","领导，较随意"],["directeur / directrice","courant","主任、总监"],["patron","familier","老板"]],"fq":"高频，工作和日常生活里常用。","me":"responsable = 能「回应」(répondre) 问题的人。","tr":{"zh":"我想和负责人说话。","fr":"Je voudrais parler au responsable, s'il vous plaît.","alt":"Je peux voir le responsable ?","note":"parler à qqn；au = à + le。"}},
 "Un(e) bénévole": {"pos":"n.m./n.f. 名词，阴阳同形：un bénévole / une bénévole，复数 bénévoles；也是形容词","s":"志愿者，不拿报酬、出于自愿为协会或公益活动做事的人。也可作形容词：un travail bénévole（义务工作）。「做志愿工作」是 le bénévolat。","ipa":"[be.ne.vɔl]","ph":"每个 é 读 [e]；o 读开口的 [ɔ]；结尾 -le 的 e 不发音。","pi":"三个音节都是短促清晰的元音，别读成「be-ne-vo-le」四个音节；o 是 [ɔ]，不是 [o]。","et":"来自拉丁语 benevolus（好意的）：bene（好）+ volo（我愿意）。同族：bénévolat（志愿服务）、benêt 不同源，别混淆。","ex":[["Les bénévoles ont distribué des repas.","志愿者分发了饭菜。"],["Elle est bénévole dans une association.","她在一个协会当志愿者。"]],"co":[["être bénévole dans une association","在协会做志愿者"],["faire du bénévolat","做志愿工作"],["un travail bénévole","义务工作"]],"sy":[["volontaire","courant","自愿的人，也指志愿兵或国际志愿者"],["militant","courant","积极分子，带有立场"]],"fq":"中频，公益、社会话题里常用。","me":"bene（好）+ vole（愿意）：愿意做好事的人。","tr":{"zh":"周末我在食物银行当志愿者。","fr":"Le week-end, je suis bénévole à la banque alimentaire.","alt":"Le week-end, je fais du bénévolat à la banque alimentaire.","note":"说明身份时 être bénévole，不加冠词。"}},
 "Un(e) consultant(e)": {"pos":"n.m./n.f. 名词：un consultant / une consultante，复数 consultants / consultantes","s":"顾问，为企业或机构提供专业意见的人，常指自由职业或咨询公司的人员。也有「受邀发表意见的专家」的意思，如电视里的 consultant sportif。","ipa":"[kɔ̃.syl.tɑ̃]","ph":"con- 读鼻音 [kɔ̃]；u 读 [y]；-ant 读 [ɑ̃]，t 不发音。","pi":"con- 的 n 不单独发；u 是 [y] 不是「乌」；阴性 consultante 的 t 要发：[kɔ̃.syl.tɑ̃t]。","et":"来自动词 consulter（咨询），源于拉丁语 consultare。后缀 -ant 表示做某事的人。同族：consultation。","ex":[["Elle travaille comme consultante.","她担任顾问。"],["Nous avons engagé un consultant en informatique.","我们聘请了一位信息技术顾问。"]],"co":[["un consultant en + 领域","……领域的顾问"],["travailler comme consultant","当顾问"],["un cabinet de consultants","咨询公司"]],"sy":[["conseiller","courant","给建议的人，更泛指"],["expert","courant","专家"]],"fq":"中频，职场和商业用语。","me":"consulter 的人：被「咨询」的那位。","tr":{"zh":"他是一位信息技术顾问。","fr":"Il est consultant en informatique.","alt":"C'est un consultant en informatique.","note":"说明职业时不加冠词：Il est consultant。"}},
 "Un(e) élu(e)": {"pos":"n.m./n.f. 名词，阴阳同音：un élu / une élue，复数 élus / élues；也是 élire 的过去分词","s":"民选代表，指通过选举产生的人，如市长、议员、市政委员。也可作形容词「当选的」。宗教里 les élus 指「被选中的人」。","ipa":"[e.ly]","ph":"é [e]；u [y]（嘴唇圆起，发「衣」的音）；阴性 élue 读音完全相同。","pi":"élu 与 élue 读音一样，靠冠词区分性别；u 是 [y]，不是 [u]。","et":"是动词 élire（选举）的过去分词，源于拉丁语 eligere（挑选）。同族：élection、électeur。","ex":[["Madame Thomas est une élue parisienne.","托马斯女士是巴黎的民选官员。"],["Les élus locaux se réunissent demain.","地方民选官员明天开会。"]],"co":[["un élu local","地方民选官员"],["les élus du peuple","人民选出的代表"],["être élu maire","当选市长"]],"sy":[["député","courant","国民议会议员"],["maire","courant","市长，也是 élu"],["représentant","courant","代表"]],"fq":"中频，新闻和政治话题常见。","me":"élu = élire 的结果：被选出来的人。","tr":{"zh":"市长是民选官员。","fr":"Le maire est un élu.","alt":"Le maire est élu par les habitants.","note":"un élu 是名词；être élu 是被动式。"}},
 "Un fondateur / Une fondatrice": {"pos":"n.m./n.f. 名词：fondateur / fondatrice，复数 fondateurs / fondatrices","s":"创始人，创办公司、协会、城市或学派的人。也作形容词：le membre fondateur（创始成员）。","ipa":"[fɔ̃.da.tœʁ] / [fɔ̃.da.tʁis]","ph":"fon- 读鼻音 [fɔ̃]；d [d]；-eur [œʁ]，-rice [tʁis]。","pi":"on 是鼻化元音 [ɔ̃]，n 不发；-teur 的 r 要发；阴性是 fondatrice，不是 fondateuse。","et":"来自动词 fonder（创立），源于拉丁语 fundare；fundus 意为「底部、基础」。同族：fondation、fondement、fond。","ex":[["C'est le fondateur de l'entreprise.","他是公司的创始人。"],["La fondatrice de l'école vit encore.","学校的创始人还健在。"]],"co":[["le fondateur de + 名词","……的创始人"],["un membre fondateur","创始成员"],["les pères fondateurs","开国元勋"]],"sy":[["créateur","courant","创造者，范围更广"],["initiateur","soutenu","发起人"]],"fq":"中频，商业和历史话题常见。","me":"fonder 的人；fond（底部）= 打下基础的人。","tr":{"zh":"她是这家协会的创始人。","fr":"Elle est la fondatrice de cette association.","alt":"C'est elle qui a fondé cette association.","note":"la fondatrice de + 名词；c'est elle qui 用来强调。"}},
 "Les bonnes manières": {"pos":"n.f.pl. 名词词组（常用复数）：les bonnes manières，单数 une bonne manière 较少用","s":"礼貌，礼仪，得体的举止，如不打断别人、说谢谢、好好吃饭。manière 单数还有「方式」的意思：de cette manière = 这样。","ipa":"[bɔn.ma.njɛʁ]","ph":"bonnes 的 -nn- 和 -es 使它读 [bɔn]，s 不发；manières 读 [ma.njɛʁ]，ni 读 [nj]，结尾 s 不发。","pi":"bon 是鼻音 [bɔ̃]，但阴性 bonne 的 n 要发音 [bɔn]；复数 s 不发音。","et":"manière 与 main（手）同源，源于拉丁语 manus：本义是「用手处理事情的方式」。bonne 来自拉丁语 bonus。","ex":[["Il a appris les bonnes manières.","他学会了礼仪。"],["Elle a de très bonnes manières.","她很有礼貌。"]],"co":[["avoir de bonnes manières","有礼貌"],["apprendre les bonnes manières","学礼仪"],["de cette manière","这样"],["de toute manière","无论如何"]],"sy":[["politesse","courant","礼貌，更泛指"],["savoir-vivre","courant","懂规矩，会待人接物"],["étiquette","soutenu","正式场合的礼节"]],"fq":"中频，日常和教育话题常用。","me":"manières 里有 main（手）：用手做事的「方式」。","tr":{"zh":"在法国，孩子要学会礼仪。","fr":"En France, les enfants doivent apprendre les bonnes manières.","alt":"En France, on apprend aux enfants les bonnes manières.","note":"avoir de bonnes manières 中 de 替代 des（形容词在名词前）。"}},
 "Des algues": {"pos":"n.f.pl. 阴性名词，复数：une algue / des algues","s":"海藻；藻类。可以是海边的 algues（沙滩上的海藻），也可指池塘里的藻类。紫菜、海带等食用的海藻也叫 algues。","ipa":"[alg]","ph":"a [a]；l [l]；gu 在 e 前读 [g]（u 不发音）；结尾 -es 不发。单数 une algue 也读 [alg]。","pi":"gu 读 [g]，不是「古」；单数和复数发音相同；阴性名词，不是 le algue。","et":"来自拉丁语 alga（海藻）。英语 algae 与它同源。","ex":[["Il y a beaucoup d'algues sur la plage.","海滩上有很多海藻。"],["Elle mange des algues dans sa soupe.","她在汤里放了海藻。"]],"co":[["des algues marines","海藻"],["des algues vertes","绿藻（海岸常见污染现象）"],["un rouleau de sushi aux algues","紫菜寿司卷"]],"sy":[["varech","soutenu","海带类海藻，岸上冲上来的"],["goémon","littéraire","海边的大型海藻（布列塔尼）"]],"fq":"中低频，沙滩、饮食和环境话题里会出现。","me":"algue 和英语 algae 像：两个 g 都发 [g]。","tr":{"zh":"沙滩上有很多海藻。","fr":"Il y a beaucoup d'algues sur la plage.","alt":"La plage est pleine d'algues.","note":"beaucoup de 后面省略冠词；de + a → d'。"}},
 "Les droits de ...": {"pos":"n.m.pl. 阳性名词，复数：le droit / les droits；常见结构 les droits de + 名词","s":"……的权利。后面接名词表示谁的权利：les droits de l'homme（人权），les droits des enfants（儿童权利）。单数 le droit 还指「法律；法学」。","ipa":"[dʁwa]","ph":"d [d]；r [ʁ]；oi 读 [wa]；结尾 -ts 不发音。","pi":"结尾 -oits 完全不读；oi 是 [wa]，不是「奥衣」；de + les = des，de + le = du，别漏掉缩合。","et":"来自拉丁语 directus（笔直的、正的）。同族：droit（右；直的）、direct、diriger。","ex":[["Les droits des femmes.","妇女的权利。"],["Chacun a le droit de parler.","人人都有发言的权利。"]],"co":[["les droits de l'homme","人权"],["les droits des femmes / des enfants","妇女 / 儿童的权利"],["avoir le droit de + 动词原形","有权做某事"],["défendre ses droits","维护自己的权利"]],"sy":[["libertés","courant","自由，与权利相关但不同"],["devoirs","courant","义务，反义"],["privilège","soutenu","特权"]],"fq":"高频，社会、法律话题常见。","me":"droit = 「直」：直直地站在法律这边。","tr":{"zh":"我们要保护儿童的权利。","fr":"Nous devons défendre les droits des enfants.","alt":"Il faut protéger les droits des enfants.","note":"de + les enfants → des enfants。"}},
 "Les soins": {"pos":"n.m.pl. 阳性名词，复数：le soin / les soins","s":"护理，治疗，照料。les soins médicaux = 医疗护理；les soins du visage = 面部护理。单数 le soin 还有「细心」的意思：avec soin = 仔细地。","ipa":"[swɛ̃]","ph":"s [s]；oi + n 读 [wɛ̃]（注意不是 [wa]）；结尾 -ns 不发。","pi":"soin 读 [swɛ̃]，不是 [swa]；结尾 s 不发，单复数同音；avec soin 单数，les soins 复数，意思不同。","et":"来源不确定（古法语 soing，可能来自法兰克语）。同族：soigner（照顾；治疗）、soigneux（细心的）。","ex":[["Ce patient a besoin de soins intensifs.","这位病人需要重症护理。"],["Elle fait attention aux soins de la peau.","她注意皮肤护理。"]],"co":[["les soins médicaux","医疗护理"],["les premiers soins","急救"],["des soins intensifs","重症监护"],["avec soin","仔细地"]],"sy":[["traitement","courant","治疗（针对疾病的方案）"],["santé","courant","健康，更泛指"],["attention","courant","关注，用心"]],"fq":"高频，医疗和日常话题常用。","me":"soigner 的名词：soins 是「照料」的动作。","tr":{"zh":"医生给他做了治疗。","fr":"Le médecin lui a donné des soins.","alt":"Le médecin l'a soigné.","note":"donner des soins à qqn；lui 是间接宾语，soigner 则用 l'。"}},
 "Des équipements": {"pos":"n.m.pl. 阳性名词，复数：un équipement / des équipements","s":"设备；设施；装备。可指运动器材、公共设施（学校、体育馆）或家电。注意它常用复数，指一组设备。","ipa":"[e.kip.mɑ̃]","ph":"é [e]；qu 读 [k]；i [i]；-ment 读鼻音 [mɑ̃]，t 不发；复数 s 不发。","pi":"qu 读 [k]；结尾 -ment 的 e 和 n 不是「门特」，而是 [mɑ̃]；équipement 是阳性。","et":"équiper + 后缀 -ment；équiper 本义是为船只配备装备，源于日耳曼语（古诺尔斯语 skipa）一说，细节不确定。同族：équipe、équiper。","ex":[["Les équipements sportifs sont neufs.","体育设施是新的。"],["Cette salle manque d'équipements.","这个房间缺少设备。"]],"co":[["des équipements sportifs","体育设施"],["des équipements publics","公共设施"],["l'équipement de sécurité","安全装备"]],"sy":[["matériel","courant","设备、器材（更偏物件）"],["installations","courant","设施（固定的）"],["infrastructures","soutenu","基础设施"]],"fq":"中频，城市、体育和工作话题常见。","me":"équipe + -ment：团队需要的东西。","tr":{"zh":"这个城市有很多体育设施。","fr":"Cette ville a beaucoup d'équipements sportifs.","alt":"Il y a beaucoup d'équipements sportifs dans cette ville.","note":"beaucoup de + 名词，省略冠词。"}},
 "Assurer": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；过去分词 assuré","s":"保证，确保：assurer à qqn que… = 向某人保证……；也有「负责；承担」的意思：assurer un service。口语中 assurer ! 还表示「做得好」。","ipa":"[a.sy.ʁe]","ph":"a [a]；ss 在两个元音之间读 [s]；u [y]；结尾 -er 读 [e]。","pi":"u 读 [y]；ss 读 [s]，不是 [z]；结尾 -er 不发 r；assurer 也有「给……投保」的意思（assurance）。","et":"由 a- + sûr（可靠）构成，源于拉丁语 securus。同族：sûr、sécurité、assurance。","ex":[["Je t'assure que c'est vrai !","我向你保证这是真的！"],["Il assure la sécurité du magasin.","他负责商店的安全。"]],"co":[["assurer à qqn que…","向某人保证……"],["assurer la sécurité / le service","确保安全 / 提供服务"],["s'assurer que + 从句","确认……"]],"sy":[["garantir","courant","保证（更正式，有担保）"],["promettre","courant","承诺"],["certifier","soutenu","证明；郑重保证"]],"fq":"高频，日常和职场都常用。","me":"a-sûr-er：让人「放心」(sûr)。","tr":{"zh":"我向你保证，一切都会好的。","fr":"Je t'assure que tout ira bien.","alt":"Crois-moi, tout ira bien.","note":"assurer que 后接陈述式（直陈式）。"}},
 "Respecter": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；过去分词 respecté","s":"尊重；遵守。respecter les règles / la loi = 遵守规则 / 法律；respecter qqn = 尊重某人。","ipa":"[ʁɛs.pɛk.te]","ph":"r 小舌音；e 读 [ɛ]；c 在 t 前读 [k]；结尾 -er 读 [e]。","pi":"不要说成「resprecter」；c 读 [k]；respecter 后直接接宾语，不加介词 à。","et":"来自拉丁语 respectare（反复回头看），源于 respicere。同族：respect、respectueux、inspecter。","ex":[["Il faut respecter les règles.","必须遵守规则。"],["Je respecte ton choix.","我尊重你的选择。"]],"co":[["respecter les règles / la loi","遵守规则 / 法律"],["respecter qqn","尊重某人"],["respecter un délai","遵守期限"],["se faire respecter","让人尊重自己"]],"sy":[["obéir à","courant","服从（后接 à）"],["honorer","soutenu","尊敬；履行"],["mépriser","courant","轻视（反义）"]],"fq":"高频，日常和规范用语。","me":"respect + -er：和英语 respect 几乎一样。","tr":{"zh":"请遵守规则。","fr":"Merci de respecter les règles.","alt":"Respectez les règles, s'il vous plaît.","note":"Merci de + 动词原形 = 请……（告示用语）。"}},
 "Lancer": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；nous lançons；过去分词 lancé","s":"发起；推出；投掷。lancer un projet / un produit = 启动项目 / 推出产品；lancer une balle = 扔球。se lancer = 投身；开始尝试。","ipa":"[lɑ̃.se]","ph":"an 读鼻音 [ɑ̃]；c 在 e 前读 [s]；结尾 -er 读 [e]。","pi":"nous lançons 要加软音符 ç，因为 c 在 o 前仍要读 [s]；an 是鼻音，n 不单发。","et":"来自 lance（长矛），源于拉丁语 lancea：lancer 本义是「投掷长矛」。","ex":[["Nous venons de lancer ce nouveau projet.","我们刚启动了这个新项目。"],["Il a lancé la balle trop loin.","他把球扔得太远了。"]],"co":[["lancer un projet / un produit","启动项目 / 推出产品"],["lancer une balle","扔球"],["se lancer dans + 名词","投身于……"],["lancer une idée","提出一个想法"]],"sy":[["jeter","courant","扔，较随便"],["démarrer","courant","开始；启动"],["inaugurer","soutenu","举行落成典礼；首次启用"]],"fq":"高频，日常和商业都常用。","me":"lance（矛）→ lancer：往前「投」出去。","tr":{"zh":"公司下个月推出新产品。","fr":"L'entreprise lance un nouveau produit le mois prochain.","alt":"L'entreprise va lancer un nouveau produit le mois prochain.","note":"现在时可表示近将来；aller + 原形也可以。"}},
 "Diverger": {"pos":"v.i. 不及物动词，第一组（-er），助动词 avoir；nous divergeons；过去分词 divergé","s":"出现分歧；分道扬镳。多用于意见、观点、道路：Nos opinions divergent。反义词是 converger。","ipa":"[di.vɛʁ.ʒe]","ph":"d [d]；i [i]；ver 读 [vɛʁ]；g 在 e 前读 [ʒ]；结尾 -er 读 [e]。","pi":"g 读 [ʒ]；nous divergeons 保留 e，是为了让 g 保持 [ʒ]；与 diverger 相近的 divers、diversifier 不同义。","et":"来自拉丁语 divergere（di- 分开 + vergere 转向）。同族：divergent、convergent、divergence。","ex":[["Nos opinions commencent à diverger.","我们的意见开始出现分歧。"],["Les routes divergent après le village.","过了村子，路分成了两条。"]],"co":[["des opinions qui divergent","意见不一"],["diverger sur + 名词","在……上有分歧"],["des points de vue divergents","不同的观点"]],"sy":[["différer","courant","不同"],["s'opposer","courant","对立"],["converger","soutenu","汇聚（反义）"]],"fq":"中低频，书面和讨论中常见。","me":"di-（分开）+ verger：向不同方向「转」。","tr":{"zh":"我们对这个问题意见不同。","fr":"Nos opinions divergent sur ce sujet.","alt":"On n'est pas d'accord sur ce sujet.","note":"diverger 通常不加宾语，而用 sur 引出主题。"}},
 "Bosser": {"pos":"v.i./v.t. 第一组（-er），助动词 avoir；过去分词 bossé；口语","s":"干活，工作，努力用功（口语）。bosser dur = 拼命干活；也可指学习：bosser un examen = 备考。名词 un bosseur 指勤快的人。","ipa":"[bɔ.se]","ph":"b [b]；o 读开口的 [ɔ]；ss 读 [s]；结尾 -er 读 [e]。","pi":"o 是 [ɔ]，不是 [o]；这是口语词，写正式文章或与长辈说话时多用 travailler。","et":"来源不确定。同族：bosseur（勤快的人）；不要与 bosse（隆起）混淆。","ex":[["J'ai beaucoup bossé aujourd'hui.","我今天干了很多活。"],["Il bosse dans un restaurant.","他在一家餐厅干活。"]],"co":[["bosser dur","拼命干活"],["bosser un examen","备考"],["bosser à + 地点","在某地打工"]],"sy":[["travailler","courant","工作（中性说法）"],["trimer","argot","辛苦干活"],["étudier","courant","学习"]],"fq":"高频口语，年轻人和同事之间常用。","me":"bosser = travailler 的口语：朋友间随口说。","tr":{"zh":"我周末要备考。","fr":"Ce week-end, je dois bosser pour mon examen.","alt":"Ce week-end, je révise mon examen.","note":"bosser 是口语；正式场合用 travailler 或 réviser。"}},
 "Se conduire": {"pos":"v.pr. 代词式动词，不规则（第三组），复合时态助动词 être；je me suis conduit(e)；过去分词 conduit","s":"表现，举止：se conduire bien / mal = 表现好 / 不好。注意区分：conduire = 驾驶；se conduire = 举止行为。","ipa":"[sə.kɔ̃.dɥiʁ]","ph":"se 轻读 [sə]；con 读鼻音 [kɔ̃]；ui 读 [ɥi]（先圆唇再 i）；r 要发音。","pi":"ui 是 [ɥi]，不是「乌衣」；与 conduire（开车）搭配不同：il conduit une voiture，il se conduit mal；代动词要加 me / te / se。","et":"来自拉丁语 conducere（con- 一起 + ducere 带领）。同族：conducteur、conduite（行为；驾驶）。","ex":[["Il faut bien se conduire en classe.","在课堂上要表现得体。"],["Elle s'est mal conduite hier.","她昨天表现不好。"]],"co":[["se conduire bien / mal","表现好 / 不好"],["se conduire en adulte","表现得像个成年人"],["savoir se conduire","懂得怎样行事"]],"sy":[["se comporter","courant","行为，表现（更常用）"],["agir","courant","行动"],["se tenir","courant","举止；站相坐相"]],"fq":"中频，描述行为时常用。","me":"se conduire = 「驾驶自己」：管好自己的行为。","tr":{"zh":"孩子们在课堂上表现得很好。","fr":"Les enfants se sont bien conduits en classe.","alt":"Les enfants se comportent bien en classe.","note":"代动词的过去分词与主语（反身宾语在前）一致：conduits。"}},
 "Sympathiser": {"pos":"v.i. 不及物动词，第一组（-er），助动词 avoir；过去分词 sympathisé","s":"意气相投，一见如故。sympathiser avec qqn = 与某人投缘、成为朋友。也可表示「同情」，但在日常多指关系变好。","ipa":"[sɛ̃.pa.ti.ze]","ph":"sym 读鼻音 [sɛ̃]；p [p]；th 读 [t]；s 在元音间读 [z]；结尾 -er 读 [e]。","pi":"th 读 [t]，不是 [θ]；y 与 m 构成鼻音 [ɛ̃]；注意 sympathique（友善的）不能写作 sympathic。","et":"来自 sympathie（希腊语 sympatheia：syn- 一起 + pathos 感受）加后缀 -iser。同族：sympathique、sympathie。","ex":[["Nous avons tout de suite sympathisé.","我们一见如故。"],["Elle a sympathisé avec ses voisins.","她和邻居成了朋友。"]],"co":[["sympathiser avec qqn","与某人投缘"],["tout de suite","马上"],["sympathiser très vite","很快就成为朋友"]],"sy":[["s'entendre bien","courant","相处得好（更常用）"],["se lier d'amitié","soutenu","结为朋友"],["copiner","familier","交朋友（口语）"]],"fq":"中低频，描述人际关系时用。","me":"sympa（好人）+ -iser：变得「很 sympa」。","tr":{"zh":"我和新同事一见如故。","fr":"J'ai tout de suite sympathisé avec mon nouveau collègue.","alt":"Avec mon nouveau collègue, on s'est bien entendus tout de suite.","note":"sympathiser avec qqn，介词用 avec。"}},
 "Convaincre": {"pos":"v.t. 及物动词，不规则（第三组），助动词 avoir；je convaincs, nous convainquons；过去分词 convaincu","s":"说服，使信服：convaincre qqn de + 原形 = 说服某人做……。se laisser convaincre = 被说服。名词是 conviction（信念）。","ipa":"[kɔ̃.vɛ̃kʁ]","ph":"con 读鼻音 [kɔ̃]；vain 读 [vɛ̃]；-cre 读 [kʁ]。结尾 -aincre 的 e 不发音。","pi":"第一人称是 je convaincs（带 s，不发音），复数 nous convainquons 里 qu 读 [k]；过去分词 convaincu；不要和 vaincre（战胜）混为一谈，但二者同源。","et":"来自拉丁语 convincere（con- 完全 + vincere 战胜）：本义是「彻底战胜对方的疑虑」。同族：vaincre、convaincant。","ex":[["J'essaie de le convaincre de venir.","我试着说服他来。"],["Ses arguments m'ont convaincu.","他的论据说服了我。"]],"co":[["convaincre qqn de + 原形","说服某人做……"],["être convaincu(e) que…","确信……"],["un argument convaincant","有说服力的论据"]],"sy":[["persuader","courant","劝说（更偏感情）"],["inciter","soutenu","促使"],["dissuader","soutenu","劝阻（反义）"]],"fq":"中频，讨论和说理中常用。","me":"con + vaincre：「战胜」对方的怀疑。","tr":{"zh":"我没能说服他。","fr":"Je n'ai pas réussi à le convaincre.","alt":"Je n'ai pas pu le convaincre.","note":"réussir à + 动词原形；convaincre 直接带宾语。"}},
 "Rejoindre": {"pos":"v.t. 及物动词，不规则（第三组），助动词 avoir；je rejoins, nous rejoignons；过去分词 rejoint","s":"加入；与……会合；赶上。rejoindre qqn = 去找某人；rejoindre un groupe = 加入团体。注意：英语 join 常对应 rejoindre 或 joindre。","ipa":"[ʁə.ʒwɛ̃dʁ]","ph":"re 轻读 [ʁə]；j [ʒ]；oin 读 [wɛ̃]；结尾 -dre 读 [dʁ]。","pi":"oin 读 [wɛ̃]，不是 [wa]；第一人称复数 nous rejoignons 里 -gn- 读 [ɲ]；rejoindre 和 joindre（联系；连接）意思不同。","et":"由 re- + joindre 构成，源于拉丁语 jungere（连接）。同族：joindre、jonction、jumeau（不同源，别混淆）。","ex":[["Tu peux nous rejoindre plus tard.","你可以晚点来找我们。"],["Elle a rejoint l'équipe en septembre.","她九月加入了团队。"]],"co":[["rejoindre qqn à + 地点","在某地与某人会合"],["rejoindre une équipe","加入团队"],["on se rejoint où ?","我们在哪儿碰头？"]],"sy":[["retrouver","courant","与某人见面（约好）"],["intégrer","courant","加入；融入"],["adhérer à","soutenu","加入（协会）"]],"fq":"高频，约见朋友时很常用。","me":"re + joindre：「再次」连在一起。","tr":{"zh":"我晚点去找你们。","fr":"Je vous rejoins plus tard.","alt":"Je vous retrouve plus tard.","note":"rejoindre 直接带宾语，不加介词。"}},
 "S'occuper de": {"pos":"v.pr. 代词式动词，第一组（-er），复合时态助动词 être；je me suis occupé(e) de；常与 de 搭配","s":"照顾；负责；处理。s'occuper de qqn = 照顾某人；s'occuper de qqch = 负责某事。s'occuper 单独用也可表示「找事做」。","ipa":"[sɔ.ky.pe]","ph":"o [ɔ]；cc 读 [k]；u [y]；结尾 -er 读 [e]；s' 与后面的元音连读。","pi":"cc 只读一个 [k]；u 是 [y]；de 不能省：s'occuper de；后面接人要加 de（le → du）：Je m'occupe du bébé。","et":"来自拉丁语 occupare（占据，抢先占有）。同族：occupé、occupation、occuper。","ex":[["Je dois m'occuper de mon petit frère.","我得照顾我弟弟。"],["Qui s'occupe de la réservation ?","谁负责预订？"]],"co":[["s'occuper de qqn","照顾某人"],["s'occuper de qqch","负责某事"],["Occupe-toi de tes affaires.","管好你自己的事。"]],"sy":[["prendre soin de","courant","照顾，精心看护"],["se charger de","courant","负责，承担"],["gérer","courant","管理；处理"]],"fq":"极高频，日常常用。","me":"occupé 的代动词：把自己「占在」某事上。","tr":{"zh":"我来负责饮料。","fr":"Je m'occupe des boissons.","alt":"Je me charge des boissons.","note":"de + les = des；s'occuper de + 名词。"}},
 "Entreprendre": {"pos":"v.t. 及物动词，不规则（第三组），助动词 avoir；j'entreprends, nous entreprenons；过去分词 entrepris","s":"着手进行，开始做（较大的事）：entreprendre des études / des travaux = 开始求学 / 开工。entreprendre de + 原形 = 着手做……。名词 entreprise 指企业。","ipa":"[ɑ̃.tʁə.pʁɑ̃dʁ]","ph":"en 读 [ɑ̃]；tre 读 [tʁə]（e 轻读）；pren 读 [pʁɑ̃]；-dre 读 [dʁ]。","pi":"两个鼻音 [ɑ̃] 要读清楚；变位同 prendre：il entreprend，d 不发音；entreprendre 的 e 在 tre 中轻读，别漏。","et":"由 entre- + prendre 构成：古法语 entreprendre，本义「抓住，着手」。同族：entreprise、entrepreneur。","ex":[["Il a décidé d'entreprendre de grandes études.","他决定开始攻读高深的学业。"],["Elle entreprend un long voyage.","她开始一次长途旅行。"]],"co":[["entreprendre des études","开始求学"],["entreprendre des travaux","开始施工"],["entreprendre de + 原形","着手做……"]],"sy":[["commencer","courant","开始（最常用）"],["se lancer dans","courant","投身于"],["s'engager dans","soutenu","投入到"]],"fq":"中频，书面语和正式场合常用。","me":"entre + prendre：「拿起」一件大事。","tr":{"zh":"她打算开始一个新项目。","fr":"Elle va entreprendre un nouveau projet.","alt":"Elle se lance dans un nouveau projet.","note":"aller + 原形 表示近将来。"}},
 "Dénoncer": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；nous dénonçons；过去分词 dénoncé","s":"揭发；谴责；告发。dénoncer qqn à la police = 向警方告发某人；dénoncer une injustice = 公开谴责不公。小心：带贬义时像「告密」。","ipa":"[de.nɔ̃.se]","ph":"dé [de]；non 读鼻音 [nɔ̃]；c 在 e 前读 [s]；结尾 -er 读 [e]。","pi":"nous dénonçons 要加 ç；non 是鼻音，n 不单发；不要和 annoncer（宣布）混淆。","et":"来自拉丁语 denuntiare（de- + nuntiare 宣告）。同族：dénonciation、annoncer、prononcer。","ex":[["Elle a décidé de dénoncer ces pratiques.","她决定揭发这些做法。"],["Ce journal dénonce la corruption.","这家报纸谴责腐败。"]],"co":[["dénoncer une injustice","谴责不公"],["dénoncer qqn à la police","向警方告发某人"],["dénoncer des abus","揭发滥用行为"]],"sy":[["accuser","courant","指控"],["révéler","courant","揭露"],["balancer","argot","告密、出卖"]],"fq":"中频，新闻和社会话题常见。","me":"dé- + annoncer：把坏事大声「宣布」出来。","tr":{"zh":"他公开谴责这种不公平。","fr":"Il dénonce publiquement cette injustice.","alt":"Il a dénoncé cette injustice devant tout le monde.","note":"dénoncer + 直接宾语。"}},
 "Évaluer": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；过去分词 évalué","s":"评估；估价；评定。évaluer les dégâts = 评估损失；évaluer un élève = 给学生打分。名词是 évaluation。","ipa":"[e.va.lɥe]","ph":"é [e]；va [va]；lu 读 [lɥ]（半元音 ɥ）；结尾 -er 读 [e]。","pi":"lu 里的 u 是半元音 [ɥ]，口型先圆后展，不是「卢」；读成三个音节 é-va-lué，而不是四个。","et":"由 é-（ex）+ valeur（价值）构成，与 valoir（值）同源，拉丁语 valere。同族：valeur、évaluation。","ex":[["Il est difficile d'évaluer les dégâts.","很难评估损失。"],["Le professeur évalue les élèves chaque mois.","老师每月评估学生。"]],"co":[["évaluer les dégâts / les risques","评估损失 / 风险"],["évaluer un projet","评估项目"],["une évaluation","评估；测验"]],"sy":[["estimer","courant","估计，估价"],["apprécier","soutenu","估价；欣赏"],["juger","courant","判断"]],"fq":"中频，工作和学习常用。","me":"é + valeur：算出「价值」(valeur)。","tr":{"zh":"我们得评估一下风险。","fr":"Nous devons évaluer les risques.","alt":"Il faut évaluer les risques.","note":"devoir + 动词原形；il faut + 原形 更口语。"}},
 "Permettre": {"pos":"v.t. 及物动词，不规则（第三组），助动词 avoir；je permets, nous permettons；过去分词 permis","s":"允许；使……成为可能：permettre à qqn de + 原形 = 允许某人做……。se permettre = 冒昧；负担得起。名词 permis 指许可证，如 permis de conduire。","ipa":"[pɛʁ.mɛtʁ]","ph":"per 读 [pɛʁ]（r 发音）；mett 读 [mɛt]；结尾 -tre 读 [tʁ]。","pi":"结构是 permettre à qqn de faire，不能说 permettre qqn de；过去分词是 permis，不是 permettu；je permets 的 s 不发音。","et":"来自拉丁语 permittere（per- 通过 + mittere 放，送）。同族：permission、permis、mettre。","ex":[["Ce badge vous permet d'entrer.","这个徽章允许您进入。"],["Son salaire lui permet de voyager.","他的工资让他能够去旅行。"]],"co":[["permettre à qqn de + 原形","允许某人做……"],["Permettez-moi de…","请允许我……"],["se permettre de + 原形","冒昧……"],["permettre que + 虚拟式","允许……（正式）"]],"sy":[["autoriser","courant","批准，授权"],["laisser","courant","让，允许（口语）"],["interdire","courant","禁止（反义）"]],"fq":"极高频，日常常用。","me":"per + mettre：让某事「通过」。","tr":{"zh":"请允许我自我介绍。","fr":"Permettez-moi de me présenter.","alt":"Je me présente, si vous permettez.","note":"permettre à qqn de + 原形；me 是间接宾语。"}},
 "Refuser": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；过去分词 refusé","s":"拒绝：refuser une offre = 拒绝一个提议；refuser de + 原形 = 拒绝做某事。refuser un candidat = 不录取。名词是 refus。","ipa":"[ʁə.fy.ze]","ph":"re 轻读 [ʁə]；fu 读 [fy]（u 是 [y]）；s 在元音间读 [z]；结尾 -er 读 [e]。","pi":"s 读 [z]，不是 [s]；u 是 [y]；refuser de + 原形，不要用 à；与 recevoir 无关，反义词是 accepter。","et":"来源不确定（古法语 refuser）。同族：refus、refusé、s'excuser 不同源。","ex":[["Il a refusé mon invitation.","他拒绝了我的邀请。"],["Elle refuse de partir.","她拒绝离开。"]],"co":[["refuser une offre / une invitation","拒绝提议 / 邀请"],["refuser de + 原形","拒绝做……"],["un refus net","断然拒绝"]],"sy":[["décliner","soutenu","婉拒"],["rejeter","courant","拒绝，驳回"],["accepter","courant","接受（反义）"]],"fq":"极高频，日常常用。","me":"re + fuser：把东西「推回去」。","tr":{"zh":"我不能拒绝这份工作。","fr":"Je ne peux pas refuser ce travail.","alt":"Je ne peux pas dire non à ce travail.","note":"ne… pas 夹住 peux；refuser 后面直接接宾语。"}},
 "Oser": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；过去分词 osé","s":"敢于：oser + 动词原形，后面不加介词。Je n'ose pas = 我不敢。也可单独用：oser tout = 什么都敢做。形容词 osé(e) = 大胆的，有点出格的。","ipa":"[o.ze]","ph":"o 读 [o]；s 在元音间读 [z]；结尾 -er 读 [e]。","pi":"s 读 [z]；oser + 原形 中间不加 de；否定常见 ne pas oser；复合时态 j'ai osé / je n'ai pas osé。","et":"来自通俗拉丁语 *ausare，与 audere（敢）有关。同族：audace、osé。","ex":[["Je n'ai pas osé lui dire la vérité.","我没敢告诉他真相。"],["Il n'ose pas parler en public.","他不敢在公众面前讲话。"]],"co":[["oser + 动词原形","敢于……"],["Je n'ose pas…","我不敢……"],["Si j'ose dire…","如果我可以这么说……"],["une question osée","一个大胆的问题"]],"sy":[["risquer","courant","冒险"],["avoir le courage de","courant","有勇气去……"],["s'aventurer","soutenu","冒险前往"]],"fq":"中频，日常也会用。","me":"osé = 「敢」的过去分词，形容有点「大胆」的事。","tr":{"zh":"我不敢问他。","fr":"Je n'ose pas lui demander.","alt":"Je n'ose pas le lui demander.","note":"oser + 原形，中间无介词；lui 是间接宾语。"}},
 "Rappeler": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；je rappelle, nous rappelons；过去分词 rappelé","s":"提醒；使想起；回电话。rappeler qqch à qqn = 提醒某人某事；rappeler qqn = 给某人回电话。se rappeler qqch = 记得某事（代动词）。","ipa":"[ʁa.pə.le]","ph":"ra 读 [ʁa]；ppe 中 pp 只读一个 [p]；e 轻读 [ə]；结尾 -er 读 [e]。","pi":"pp 只读一个 [p]；变位时 ll 双写：je rappelle；用法：rappeler à qqn（提醒）与 se rappeler（记得）不同，别混用。","et":"由 re- + appeler 构成，appeler 源于拉丁语 appellare（呼唤）。同族：appel、appeler、rappel。","ex":[["Je voudrais rappeler ce problème à tout le monde.","我想向大家重提这个问题。"],["Rappelle-moi demain matin.","明天早上给我回电话。"]],"co":[["rappeler qqch à qqn","提醒某人某事"],["rappeler qqn","给某人回电话"],["Ça me rappelle quelque chose.","这让我想起一些事。"],["se rappeler que…","记得……"]],"sy":[["se souvenir","courant","记得，想起"],["évoquer","soutenu","唤起；提及"],["recontacter","courant","再次联系"]],"fq":"极高频，日常常用。","me":"re + appeler：再「呼叫」一次。","tr":{"zh":"请提醒我明天打电话。","fr":"Rappelle-moi de téléphoner demain.","alt":"N'oublie pas de me rappeler de téléphoner demain.","note":"rappeler à qqn de + 原形；祈使句中 me 变 moi。"}},
 "Représenter": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；过去分词 représenté","s":"代表；表现；表示。représenter un pays = 代表一个国家；Ce tableau représente un paysage = 这幅画表现的是风景。也有「占比」的意思：représenter 20 % = 占百分之二十。","ipa":"[ʁə.pʁe.zɑ̃.te]","ph":"re 轻读 [ʁə]；pré 读 [pʁe]；sen 读鼻音 [zɑ̃]；s 读 [z]；结尾 -er 读 [e]。","pi":"sen 里的 s 夹在 é 与 an 之间读 [z]；中间 an 是鼻音 [ɑ̃]，别读成 [ɛn]；re- 在这里读 [ʁə]。","et":"来自拉丁语 repraesentare（使呈现在眼前）。同族：représentant、représentation、présent。","ex":[["Ce tableau représente un paysage.","这幅画表现的是风景。"],["Il représente l'entreprise à Paris.","他在巴黎代表公司。"]],"co":[["représenter un pays / une entreprise","代表一个国家 / 公司"],["représenter x %","占百分之 x"],["ce que cela représente","这意味着什么"]],"sy":[["symboliser","courant","象征"],["incarner","soutenu","体现"],["figurer","soutenu","出现；描绘"]],"fq":"高频，艺术和商业常用。","me":"re + présenter：再次让它「呈现」。","tr":{"zh":"这个标志代表和平。","fr":"Ce symbole représente la paix.","alt":"Ce symbole veut dire la paix.","note":"représenter + 直接宾语。"}},
 "Voter": {"pos":"v.i./v.t. 第一组（-er），助动词 avoir；过去分词 voté","s":"投票：voter pour qqn = 投票给某人；voter une loi = 表决通过一项法律。名词是 le vote（投票）、un électeur（选民）。","ipa":"[vɔ.te]","ph":"v [v]；o 读开口的 [ɔ]；结尾 -er 读 [e]。","pi":"o 是 [ɔ]，不是英语 vote [vəʊt]；结尾 -er 的 r 不发；介词用 pour（赞成）或 contre（反对）。","et":"来自 vote；英语 vote 与它同源于拉丁语 votum（誓愿，愿望）。同族：vote、voeu。","ex":[["Les citoyens vont voter demain.","公民们明天去投票。"],["J'ai voté pour elle.","我投了她的票。"]],"co":[["voter pour / contre","投赞成 / 反对票"],["voter une loi","表决通过法律"],["un bulletin de vote","选票"],["le droit de vote","选举权"]],"sy":[["élire","courant","选举（选出人）"],["se prononcer","soutenu","表态"],["choisir","courant","选择"]],"fq":"高频，选举时常用。","me":"voter ← vote：英语 vote 的法语动词。","tr":{"zh":"你明天去投票吗？","fr":"Tu vas voter demain ?","alt":"Tu votes demain ?","note":"aller + 动词原形表示近将来。"}},
 "Revaloriser": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；过去分词 revalorisé","s":"提高价值；提高待遇：revaloriser les salaires = 提高工资；revaloriser un métier = 提高职业的地位。名词是 revalorisation。","ipa":"[ʁə.va.lɔ.ʁi.ze]","ph":"re 轻读 [ʁə]；va [va]；lo 读 [lɔ]；ri [ʁi]；s 读 [z]；结尾 -er 读 [e]。","pi":"有五个音节，慢慢念：re-va-lo-ri-ser；o 是 [ɔ]；s 夹在元音间读 [z]；不要与 valoriser（提升价值）混淆，re- 表示「再次」。","et":"由 re- + valoriser 构成；valoriser 来自 valeur（价值），拉丁语 valere。同族：valeur、valoir。","ex":[["Il faut revaloriser ces métiers.","必须提高这些职业的待遇。"],["Le gouvernement veut revaloriser les salaires.","政府想提高工资。"]],"co":[["revaloriser les salaires","提高工资"],["revaloriser un métier","提高职业地位"],["revaloriser les retraites","上调养老金"]],"sy":[["valoriser","courant","提升价值"],["augmenter","courant","增加"],["réévaluer","soutenu","重新评估；上调"]],"fq":"中低频，新闻和社会话题常见。","me":"re + valeur + -iser：让价值「再升高」。","tr":{"zh":"应当提高教师的待遇。","fr":"Il faut revaloriser le métier d'enseignant.","alt":"On doit mieux payer les enseignants.","note":"il faut + 原形 表示「必须」。"}},
 "Paraître": {"pos":"v.i. 不规则（第三组），助动词 avoir；je parais, nous paraissons；过去分词 paru","s":"出现；出版；看起来。Ce livre vient de paraître = 这本书刚出版。il paraît que… = 据说……。paraître + 形容词 = 看起来……，和 sembler 近似。","ipa":"[pa.ʁɛtʁ]","ph":"pa [pa]；raî 读 [ʁɛ]；-tre 读 [tʁ]，结尾 e 不发音。","pi":"î 只表示长音，读 [ɛ]；变位中 nous paraissons 里 ss 读 [s]；il paraît 里 t 不发音；与 apparaître（出现）区分：paraître 偏「出版；看来」。","et":"来自拉丁语 parescere（出现），源于 parere。同族：apparaître、apparence、comparaître。","ex":[["Ce livre vient de paraître.","这本书刚出版。"],["Il paraît fatigué.","他看起来很累。"]],"co":[["il paraît que…","据说……"],["paraître + 形容词","看起来……"],["venir de paraître","刚出版"],["à ce qu'il paraît","据说"]],"sy":[["sembler","courant","似乎（更常用）"],["apparaître","courant","出现"],["publier","courant","出版（及物）"]],"fq":"中频，书面和日常都见。","me":"paraître 与 apparaître 同族：「亮相」、出现。","tr":{"zh":"他的新书下个月出版。","fr":"Son nouveau livre paraît le mois prochain.","alt":"Son nouveau livre sort le mois prochain.","note":"paraître 不及物；sortir 更口语。"}},
 "Nécessiter": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；过去分词 nécessité","s":"需要，要求：nécessiter du temps / de l'attention = 需要时间 / 注意力。主语通常是事物，不是人。名词是 nécessité。","ipa":"[ne.sɛ.si.te]","ph":"né [ne]；ce 读 [sɛ]；ssi 读 [si]；结尾 -er 读 [e]。","pi":"只有一个 c，两个 ss 的位置别记错：nécessiter；主语常是事物；人要做某事说 avoir besoin de。","et":"来自 nécessité，源于拉丁语 necessitas（必要）。同族：nécessaire、nécessité。","ex":[["Ce projet nécessite beaucoup de temps.","这个项目需要很多时间。"],["La situation nécessite une réponse rapide.","形势需要迅速回应。"]],"co":[["nécessiter du temps","需要时间"],["nécessiter une réponse","需要答复"],["si nécessaire","如有必要"]],"sy":[["exiger","soutenu","要求"],["demander","courant","需要"],["avoir besoin de","courant","需要（用于人）"]],"fq":"中频，正式书面语。","me":"nécessaire + -iser 的动词：「需要」。","tr":{"zh":"这项工作需要很多耐心。","fr":"Ce travail nécessite beaucoup de patience.","alt":"Ce travail demande beaucoup de patience.","note":"nécessiter 偏正式，日常用 demander。"}},
 "Se manifester": {"pos":"v.pr. 代词式动词，第一组（-er），复合时态助动词 être；il s'est manifesté；过去分词 manifesté","s":"表现出来；显现；联系对方（出声）：La maladie se manifeste par une forte fièvre。Il ne s'est pas manifesté = 他没露面，没来联系。","ipa":"[sə.ma.ni.fɛs.te]","ph":"se 轻读 [sə]；ma [ma]；ni [ni]；fes 读 [fɛs]；te [te]。","pi":"共五个音节；st 在 fes-te 中分开：[fɛs.te]；与 manifestation（示威）相关，但意思不同。","et":"来自拉丁语 manifestare（使明显），源于 manifestus。同族：manifeste、manifestation。","ex":[["La maladie se manifeste par une forte fièvre.","疾病表现为高烧。"],["Personne ne s'est manifesté.","没人露面。"]],"co":[["se manifester par + 名词","以……表现出来"],["se manifester auprès de qqn","与某人联系"],["la maladie se manifeste","疾病发作"]],"sy":[["apparaître","courant","出现"],["se révéler","soutenu","显露"],["se montrer","courant","露面"]],"fq":"中低频，书面和医学话题常见。","me":"manifest（明显）+ -er：自己「显出来」。","tr":{"zh":"症状在几天后出现。","fr":"Les symptômes se manifestent après quelques jours.","alt":"Les symptômes apparaissent après quelques jours.","note":"主语是复数 symptômes，所以动词用 se manifestent。"}},
 "Contredire": {"pos":"v.t. 及物动词，不规则（第三组），助动词 avoir；je contredis, vous contredisez；过去分词 contredit","s":"反驳；与……矛盾：contredire qqn = 反驳某人；se contredire = 自相矛盾。名词是 contradiction。","ipa":"[kɔ̃.tʁə.diʁ]","ph":"con 读鼻音 [kɔ̃]；tre 读 [tʁə]；di [di]；-re 读 [ʁ]。","pi":"vous contredisez（不是 contredites，与 dire 不同）；过去分词 contredit，t 不发音；con 的 n 不单发。","et":"由 contre- + dire 构成，源于拉丁语 contradicere。同族：contradiction、dire、contre。","ex":[["Il aime toujours me contredire.","他总爱反驳我。"],["Les faits contredisent sa version.","事实与他的说法相矛盾。"]],"co":[["contredire qqn","反驳某人"],["se contredire","自相矛盾"],["contredire une information","否定一条消息"]],"sy":[["réfuter","soutenu","驳倒"],["démentir","soutenu","否认"],["approuver","courant","赞同（反义）"]],"fq":"中频，争论时常用。","me":"contre + dire：「反着说」。","tr":{"zh":"你别总是反驳我。","fr":"Ne me contredis pas tout le temps.","alt":"Arrête de me contredire tout le temps.","note":"祈使句否定：ne + 动词 + pas；me 在动词前。"}},
 "Citer": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；过去分词 cité","s":"引用；举出：citer un auteur = 引用作者；citer un exemple = 举例。也可指「传唤」。名词是 une citation（引文）。","ipa":"[si.te]","ph":"c 在 i 前读 [s]；i [i]；t [t]；结尾 -er 读 [e]。","pi":"c 读 [s]；与 cité（城市；小区）同形不同义；结尾 r 不发。","et":"来自拉丁语 citare（召唤，引证）。同族：citation、cité、excitant。","ex":[["Il a cité un auteur célèbre.","他引用了一位著名作家。"],["Peux-tu citer un exemple ?","你能举个例子吗？"]],"co":[["citer un auteur / une phrase","引用作者 / 一句话"],["citer un exemple","举例"],["sans citer de noms","不点名"]],"sy":[["mentionner","courant","提到"],["évoquer","soutenu","提及"],["reprendre","courant","重述"]],"fq":"中频，学习和写作常用。","me":"cit(e) → citation：引用。","tr":{"zh":"请举一个例子。","fr":"Citez un exemple, s'il vous plaît.","alt":"Donnez un exemple, s'il vous plaît.","note":"vous 命令式：-ez。"}},
 "Dédier": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；过去分词 dédié","s":"献给；题献：dédier un livre à qqn = 把书献给某人；dédier sa vie à qqch = 把一生献给某事。","ipa":"[de.dje]","ph":"dé [de]；dié 读 [dje]（i 为半元音）；结尾 -er 读 [e]。","pi":"只有两个音节 dé-dié；dédier à qqn（献给）而不是 dédier pour；与 dédicace（题词）相关。","et":"来自拉丁语 dedicare（奉献）。同族：dédicace、dédicacer、dédicatoire。","ex":[["Il a dédié sa vie à la science.","他把一生献给了科学。"],["L'auteur dédie ce livre à sa mère.","作者把这本书献给他的母亲。"]],"co":[["dédier qqch à qqn","把某物献给某人"],["dédier sa vie à + 名词","把一生献给……"],["une dédicace","题词；签名"]],"sy":[["consacrer","courant","奉献，投入"],["offrir","courant","赠送"],["vouer","soutenu","献身"]],"fq":"中低频，书面语为主。","me":"dé-dié：把书「献给」你。","tr":{"zh":"她把这首歌献给她的朋友。","fr":"Elle dédie cette chanson à son ami.","alt":"Elle offre cette chanson à son ami.","note":"dédier qqch à qqn。"}},
 "S'imprégner": {"pos":"v.pr. 代词式动词，第一组（-er），复合时态助动词 être；je me suis imprégné(e)；过去分词 imprégné","s":"沉浸于；浸透：s'imprégner de la culture locale = 融入当地文化。s'imprégner de qqch 也指被气味、声音浸染。本义：被液体浸透。","ipa":"[sɛ̃.pʁe.ɲe]","ph":"s'im 读鼻音 [sɛ̃]（im 在 p 前读 [ɛ̃]）；pré [pʁe]；gn 读 [ɲ]；结尾 -er 读 [e]。","pi":"gn 读 [ɲ]，像「宁」；im 是鼻音 [ɛ̃]；过去分词 imprégné，爱用 de。","et":"来自晚期拉丁语（in- + praegnans，怀孕的），本义是使「充满」。同族：imprégner、imprégnation。","ex":[["Il faut s'imprégner de la culture locale.","必须融入当地文化。"],["Mes vêtements se sont imprégnés de fumée.","我的衣服沾满了烟味。"]],"co":[["s'imprégner de + 名词","沉浸于……"],["s'imprégner d'une culture","融入一种文化"],["imprégné de + 名词","充满……的"]],"sy":[["s'immerger","soutenu","沉浸"],["s'imbiber","courant","浸透"],["se familiariser avec","courant","熟悉"]],"fq":"中低频，书面语。","me":"im-prég-né：充满、被「浸透」。","tr":{"zh":"在法国，你会沉浸在当地文化里。","fr":"En France, tu t'imprègnes de la culture locale.","alt":"En France, tu t'immerges dans la culture locale.","note":"tu t'imprègnes：g 前 è，不是 é。"}},
 "Explorer": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；过去分词 exploré","s":"探索；考察：explorer une forêt = 探索森林；explorer une idée = 探讨一个想法。名词是 un explorateur（探险家）。","ipa":"[ɛk.splɔ.ʁe]","ph":"ex 读 [ɛk]；pl 读 [spl] 的 s 要连读；o 读开口的 [ɔ]；结尾 -er 读 [e]。","pi":"x 读 [ks]，所以 ex-plorer 读 [ɛk.splɔ.ʁe]；o 是 [ɔ]；explorer 和英语 explore 很像。","et":"来自拉丁语 explorare（探查，察看）。同族：exploration、explorateur。","ex":[["Nous allons explorer cette forêt.","我们要探索这片森林。"],["Il explore plusieurs possibilités.","他在探讨几种可能性。"]],"co":[["explorer une région","考察一个地区"],["explorer une idée","探讨想法"],["explorer les fonds marins","探索海底"]],"sy":[["parcourir","courant","走遍"],["découvrir","courant","发现"],["étudier","courant","研究"]],"fq":"中频，旅游和科学常用。","me":"explorer = 英语 explore：几乎一样。","tr":{"zh":"我们明天探索这座城市。","fr":"Nous allons explorer la ville demain.","alt":"On va explorer la ville demain.","note":"nous allons / on va 都表示近将来。"}},
 "Se presser": {"pos":"v.pr. 代词式动词，第一组（-er），复合时态助动词 être；je me suis pressé(e)；过去分词 pressé","s":"赶紧，快点：Ne vous pressez pas = 别着急。也有「挤；拥挤」的意思：la foule se presse。形容词 pressé(e) = 匆忙的。","ipa":"[sə.pʁe.se]","ph":"se 轻读 [sə]；pre 读 [pʁe]；ss 读 [s]；结尾 -er 读 [e]。","pi":"ss 读 [s]；se presser 常用祈使句：Presse-toi ! / Pressons-nous !；与 appuyer（按压）不同。","et":"来自拉丁语 pressare（压，挤），源于 premere。同族：presse、pression、exprimer。","ex":[["Ne vous pressez pas, nous avons le temps.","别着急，我们有时间。"],["Presse-toi, le train part dans cinq minutes !","快点，火车五分钟后开！"]],"co":[["Ne te presse pas.","别着急。"],["Pressons-nous !","我们快点！"],["être pressé(e)","赶时间"]],"sy":[["se dépêcher","courant","赶紧（最常用）"],["se hâter","soutenu","赶快"],["filer","familier","快走，溜"]],"fq":"中频，日常催促时常用。","me":"press（压）：自己「压紧时间」。","tr":{"zh":"快点，我们要迟到了！","fr":"Presse-toi, on va être en retard !","alt":"Dépêche-toi, on va être en retard !","note":"祈使句里 te 变 toi。"}},
 "Bavarder": {"pos":"v.i. 不及物动词，第一组（-er），助动词 avoir；过去分词 bavardé","s":"聊天，闲谈：bavarder avec qqn = 与某人聊天。有时略带「说个不停」的意味。形容词/名词 bavard(e) = 爱说话的（人）。","ipa":"[ba.vaʁ.de]","ph":"ba [ba]；var 读 [vaʁ]（r 发音）；结尾 -er 读 [e]。","pi":"中间 r 要发音：[vaʁ]；结尾 -er 的 r 不发；avec 加人，bavarder de 加话题。","et":"由 bavard（爱说话的）+ -er 构成；bavard 来自 bave（口水），本义「流口水地说话」。","ex":[["J'aime bavarder avec mes amis.","我喜欢和朋友聊天。"],["Les élèves bavardent en classe.","学生们在课堂上讲话。"]],"co":[["bavarder avec qqn","与某人聊天"],["bavarder de tout et de rien","东拉西扯"],["arrêter de bavarder","别聊了"]],"sy":[["discuter","courant","讨论，聊"],["papoter","familier","闲聊"],["causer","familier","聊天（口语）"]],"fq":"中频，日常常用。","me":"bave + -ard：「口水」多的人 = 话多。","tr":{"zh":"我们边喝咖啡边聊天。","fr":"Nous bavardons en buvant un café.","alt":"On discute en prenant un café.","note":"en + 现在分词表示同时进行。"}},
 "Papoter": {"pos":"v.i. 不及物动词，第一组（-er），助动词 avoir；过去分词 papoté；口语","s":"闲聊，说闲话（口语）：papoter avec qqn。语气轻松、亲切，常指聊琐事。名词是 un papotage。","ipa":"[pa.pɔ.te]","ph":"pa-pa-po-te，p 都读 [p]；o 读开口的 [ɔ]；结尾 -er 读 [e]。","pi":"o 是 [ɔ]；只有一个 t；与 bavarder 近似，但更亲切、更口语。","et":"来源不确定，可能是拟声词（像小声说话的声音）。同族：papotage。","ex":[["Elles ont passé l'après-midi à papoter.","她们聊了一下午。"],["Je papote souvent avec ma voisine.","我常和邻居聊天。"]],"co":[["papoter avec qqn","与某人闲聊"],["passer l'après-midi à papoter","聊一下午"],["papoter au téléphone","打电话闲聊"]],"sy":[["bavarder","courant","聊天"],["discuter","courant","聊，讨论"],["jacasser","familier","喋喋不休"]],"fq":"中低频，口语为主。","me":"pa-pa-pote：像「叭叭叭」地聊。","tr":{"zh":"周末我们喜欢在咖啡馆闲聊。","fr":"Le week-end, on aime papoter au café.","alt":"Le week-end, on bavarde volontiers au café.","note":"on 在口语里常代替 nous。"}},
 "Régler": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；je règle, nous réglons；过去分词 réglé","s":"付款，结账；调整；解决：régler l'addition = 结账；régler un problème = 解决问题；régler le volume = 调音量。","ipa":"[ʁe.gle]","ph":"ré 读 [ʁe]；gl 读 [gl]；结尾 -er 读 [e]。","pi":"变位时 é 变 è：je règle，但 nous réglons 回到 é；g 读 [g]；régler 与 règle（规则）、règlement 同族。","et":"来自拉丁语 regulare（使合乎规则），源于 regula（规则）。同族：règle、règlement、régulier。","ex":[["Le client règle ses achats.","顾客结账。"],["Il faut régler ce problème rapidement.","必须尽快解决这个问题。"]],"co":[["régler l'addition","结账"],["régler un problème","解决问题"],["régler par carte","刷卡付款"],["régler le volume","调音量"]],"sy":[["payer","courant","付钱（最常用）"],["résoudre","courant","解决"],["ajuster","courant","调整"]],"fq":"高频，餐厅和购物场景常用。","me":"règle（规则）→ régler：让事情「合乎规则」。","tr":{"zh":"您想刷卡付款吗？","fr":"Vous réglez par carte ?","alt":"Vous payez par carte ?","note":"régler par carte；par 表示方式。"}},
 "Diversifier": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；过去分词 diversifié","s":"使多样化：diversifier ses activités / ses produits = 使业务 / 产品多元化。se diversifier = 变得多样。名词是 diversification。","ipa":"[di.vɛʁ.si.fje]","ph":"di [di]；ver 读 [vɛʁ]；si [si]；fier 读 [fje]；r 不发。","pi":"ver 中的 r 要读；结尾 -fier 读 [fje]；英语 diversify 很像，别漏 i。","et":"来自 divers（各种的）+ -ifier（使成为），源于拉丁语 diversus。同族：divers、diversité、diversification。","ex":[["L'entreprise doit diversifier ses activités.","公司必须使业务多元化。"],["Il faut diversifier son alimentation.","要让饮食多样化。"]],"co":[["diversifier ses activités","使业务多元化"],["diversifier son alimentation","让饮食多样化"],["se diversifier","变得多样"]],"sy":[["varier","courant","使变化，使多样"],["élargir","courant","扩大"],["uniformiser","soutenu","使统一（反义）"]],"fq":"中频，商业和饮食话题常用。","me":"divers + -ifier：让它变得「各种各样」。","tr":{"zh":"你应该让饮食更多样。","fr":"Tu devrais diversifier ton alimentation.","alt":"Tu devrais manger de manière plus variée.","note":"devrais 是条件式，表示建议。"}},
 "Entamer": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；过去分词 entamé","s":"开始，着手：entamer des négociations = 开始谈判；entamer une conversation = 开启对话。本义是切下第一片、动第一口：entamer un pain / une bouteille。","ipa":"[ɑ̃.ta.me]","ph":"en 读鼻音 [ɑ̃]；ta [ta]；me [me]；结尾 -er 读 [e]。","pi":"en 是鼻音 [ɑ̃]；与 entamer 形近的 entraîner（训练）要分清；多用于书面和正式场合。","et":"来源不确定。同族：entame（头一片、第一刀）。","ex":[["Nous allons entamer de nouvelles négociations.","我们将开始新的谈判。"],["Il a entamé la bouteille de vin.","他开了那瓶酒。"]],"co":[["entamer des négociations","开始谈判"],["entamer une conversation","开启对话"],["entamer un pain","切开面包"]],"sy":[["commencer","courant","开始（最常用）"],["débuter","courant","开始"],["amorcer","soutenu","着手，启动"]],"fq":"中频，新闻与正式文本常见。","me":"en-tamer：从「第一口」开始。","tr":{"zh":"他们开始了新的对话。","fr":"Ils ont entamé une nouvelle conversation.","alt":"Ils ont commencé une nouvelle conversation.","note":"entamer 比 commencer 更正式。"}},
 "Saluer": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；过去分词 salué","s":"问候，打招呼；欢迎；赞扬：saluer qqn = 向某人打招呼；saluer une décision = 欢迎一项决定。Salut ! 是熟人间的「你好 / 再见」。","ipa":"[sa.lɥe]","ph":"sa [sa]；lu 读 [lɥ]（半元音 ɥ）；结尾 -er 读 [e]。","pi":"lu 里的 u 是半元音 [ɥ]，只有两个音节 sa-lué；与英语 salute 不同，不是「敬礼」为主；不要把 saluer 与 salir（弄脏）混淆。","et":"来自拉丁语 salutare（问候），源于 salus（健康）。同族：salut、salutation。","ex":[["Les clients ont salué cette initiative.","顾客们对这项倡议表示欢迎。"],["Il m'a salué de la main.","他朝我挥手打招呼。"]],"co":[["saluer qqn","向某人打招呼"],["saluer une décision / une initiative","欢迎一项决定 / 倡议"],["saluer de la main","挥手致意"],["Salut !","你好！/ 再见！"]],"sy":[["accueillir","courant","迎接；接待"],["féliciter","courant","祝贺"],["dire bonjour","courant","打招呼"]],"fq":"高频，日常和新闻都常用。","me":"salut（你好）→ saluer：说「Salut」的动作。","tr":{"zh":"他向邻居打了招呼。","fr":"Il a salué ses voisins.","alt":"Il a dit bonjour à ses voisins.","note":"saluer 直接带宾语；dire bonjour 要加 à。"}},
 "S'attarder": {"pos":"v.pr. 代词式动词，第一组（-er），复合时态助动词 être；je me suis attardé(e)；过去分词 attardé","s":"逗留，耽搁：s'attarder quelque part = 在某处久留；s'attarder sur qqch = 在某事上多停留，多讲。通常用于否定：Je ne vais pas m'attarder。","ipa":"[sa.taʁ.de]","ph":"s'a [sa]；t [t]；ar 读 [aʁ]；结尾 -er 读 [e]。","pi":"s'attarder 里 tt 只读一个 [t]；ar 里的 r 要发；attardé 也作形容词，意为「落后的」，要小心。","et":"由 a- + tard（晚）构成，源于拉丁语 tardus；动词 tarder（耽搁）。同族：tard、retard、tarder。","ex":[["Je ne vais pas m'attarder ce soir.","今晚我不久留了。"],["Elle s'est attardée au bureau.","她在办公室待到很晚。"]],"co":[["s'attarder sur + 名词","在……上多停留"],["s'attarder chez qqn","在某人家久留"],["ne pas s'attarder","不久留"]],"sy":[["rester","courant","待，留"],["traîner","familier","磨蹭"],["s'éterniser","courant","没完没了地待着"]],"fq":"中低频，书面和日常都见。","me":"a-tard-er：越来越「晚」(tard)。","tr":{"zh":"别在这里耽搁太久。","fr":"Ne vous attardez pas ici.","alt":"Ne traînez pas ici.","note":"否定祈使句：Ne vous… pas。"}},
 "Aspirer à": {"pos":"v.t.ind. 间接及物动词，第一组（-er），助动词 avoir；过去分词 aspiré；后接介词 à","s":"渴望，向往：aspirer à + 名词 / 动词原形 = 渴望得到……。无 à 时 aspirer qqch 指「吸入」，如吸尘器 aspirateur。","ipa":"[as.pi.ʁe]","ph":"as 读 [as]；pi [pi]；r 读 [ʁ]；结尾 -er 读 [e]。","pi":"渴望时必须带 à：aspirer à la paix；不带 à 是「吸入；吸尘」；h 不在这里，不要写成 haspirer。","et":"来自拉丁语 aspirare（吹向，渴望），由 ad- + spirare（呼吸）构成。同族：respirer、inspirer、aspirateur。","ex":[["Il aspire à une vie plus calme.","他渴望更平静的生活。"],["Beaucoup de jeunes aspirent à devenir artistes.","许多年轻人渴望成为艺术家。"]],"co":[["aspirer à la paix / au calme","渴望和平 / 平静"],["aspirer à + 动词原形","渴望做……"],["aspirer à un changement","渴望改变"]],"sy":[["désirer","courant","想要"],["rêver de","courant","梦想"],["ambitionner","soutenu","怀有抱负"]],"fq":"中低频，书面、表达愿望。","me":"a-spirer：向着目标「呼吸」= 渴望。","tr":{"zh":"她渴望自由。","fr":"Elle aspire à la liberté.","alt":"Elle rêve de liberté.","note":"aspirer à + 名词，à + la = à la。"}},
 "Rassurer": {"pos":"v.t. 及物动词（第一组 -er，助动词 avoir）；se rassurer = 放下心来","s":"使放心，使安心。rassurer qqn = 安抚某人；se rassurer = 自己放心。Rassure-toi ! =「别担心！」。反义词是 inquiéter。","ipa":"[ʁa.sy.ʁe]","ph":"ss 读 [s]；u [y]；-er 读 [e]，r 不发音。","pi":"ss 是清音 [s]，不是 [z]；结尾 -er 的 r 不发。","et":"re- + assurer（使确信），assurer 来自 sûr（可靠的）。同族：assurance, rassurant。","ex":[["J'essaie de la rassurer.","我试着让她安心。"],["Rassure-toi, tout va bien.","放心吧，一切都好。"],["Cette nouvelle m'a rassuré.","这个消息让我放心了。"]],"co":[["rassurer quelqu'un","让某人放心"],["se rassurer","自己宽心"],["Je suis rassuré.","我放心了。"],["un ton rassurant","让人安心的语气"]],"sy":[["apaiser","courant","安抚、平息情绪"],["tranquilliser","courant","使安心，稍偏医学"],["inquiéter","courant","反义：使担心"]],"fq":"中高频，日常常用。","me":"re- + assurer：再给一次「保证」，人就安心了。","tr":{"zh":"我想让孩子们放心。","fr":"Je veux rassurer les enfants.","alt":"Je veux que les enfants soient rassurés.","note":"vouloir + 不定式；主语不同时用 que + 虚拟式。"}},
 "Agir": {"pos":"v.i. 不及物动词（第二组 -ir，助动词 avoir）；s'agir de 只用 il s'agit de","s":"行动，采取行动；表现、行事；（药等）起作用：agir sur。Il s'agit de… =「说的是……、关键是……」，只有无人称用法。","ipa":"[a.ʒiʁ]","ph":"a [a]；g 在 i 前读 [ʒ]；结尾 r 要发 [ʁ]。","pi":"第二组动词：nous agissons, ils agissent；不要变成 *nous agons。","et":"拉丁语 agere（做、推动）。同族：acte, action, agent, réagir。","ex":[["Il est temps d'agir !","是行动的时候了！"],["Il a agi sans réfléchir.","他没想就行动了。"],["De quoi s'agit-il ?","这说的是什么事？"]],"co":[["agir vite","迅速行动"],["agir sur quelque chose","对某事起作用"],["il s'agit de + 名词/不定式","说的是……；要做的是……"],["agir en adulte","像成年人一样行事"]],"sy":[["faire","courant","做，范围更宽"],["réagir","courant","作出反应"],["se comporter","courant","（某种）举止表现"]],"fq":"高频，日常和书面都常用。","me":"agir → action, agent：都围绕「做事」。","tr":{"zh":"我们必须马上行动。","fr":"Nous devons agir tout de suite.","alt":"Il faut agir maintenant.","note":"devoir / il faut + 不定式。"}},
 "Suffire (Il suffit de)": {"pos":"v.i. 不规则动词（助动词 avoir）；过去分词 suffi；il suffit, ils suffisent","s":"足够。Il suffit de + 不定式 =「只要……就行」；Il suffit que + 虚拟式；Ça suffit ! =「够了！」（叫人住手）。","ipa":"[sy.fiʁ]","ph":"u [y]；ff 读一个 [f]；il suffit 的 t 不发 [il sy.fi]。","pi":"ff 只读一个 [f]；变位：je suffis, ils suffisent，过去分词 suffi 没有 -t-。","et":"拉丁语 sufficere（sub + facere，供给、够用）。同族：suffisant, insuffisant, suffisamment。","ex":[["Il suffit de demander.","只要开口问就行。"],["Dix euros suffisent.","十欧元就够了。"],["Ça suffit, arrête !","够了，住手！"]],"co":[["il suffit de + 不定式","只要……就行"],["il suffit que + 虚拟式","只要……就够了"],["Ça suffit !","够了！"],["Cela suffira.","这就够了。"]],"sy":[["suffisant","courant","形容词：足够的"],["il y a assez de","courant","「有足够的……」，更口语"],["il faut juste","courant","「只需要……」"]],"fq":"高频，Il suffit de 和 Ça suffit 很常用。","me":"suffit = suffisant 的动词形式，「足够了」。","tr":{"zh":"你只要按这个按钮就行。","fr":"Il suffit d'appuyer sur ce bouton.","alt":"Tu n'as qu'à appuyer sur ce bouton.","note":"Il suffit de + 不定式；ne… que 是常见替代说法。"}},
 "Se fâcher": {"pos":"v. pr. 代词式动词（助动词 être）：je me fâche, elle s'est fâchée","s":"生气，发火。se fâcher contre qqn = 对某人发火；se fâcher avec qqn = 和某人闹翻。fâché(e) = 生气的；闹翻了的。","ipa":"[sə fɑ.ʃe]","ph":"â [ɑ]（很多人读 [a]）；ch [ʃ]；-er 读 [e]。","pi":"复合时态过去分词与主语配合：elle s'est fâchée。ch 读 [ʃ]，不是 [tʃ]。","et":"来源不确定。同族：fâché, fâcheux（令人烦恼的）。","ex":[["Il ne faut pas se fâcher pour si peu.","不必为这点小事生气。"],["Elle s'est fâchée contre son frère.","她生她弟弟的气了。"],["Ils se sont fâchés pour une histoire d'argent.","他们为了钱的事闹翻了。"]],"co":[["se fâcher contre quelqu'un","对某人发火"],["se fâcher avec quelqu'un","和某人闹翻"],["se fâcher tout rouge","气得满脸通红，大发脾气"],["Ne te fâche pas.","别生气。"]],"sy":[["se mettre en colère","courant","发怒，最通用"],["s'énerver","courant","恼火、变得烦躁"],["râler","familier","发牢骚、抱怨"]],"fq":"中高频，日常口语常用。","me":"fâcher 有个帽子 â：头顶冒烟，气得冒火。","tr":{"zh":"别生气，我只是开玩笑。","fr":"Ne te fâche pas, je plaisante.","alt":"Ne t'énerve pas, je rigole.","note":"否定命令式：Ne te fâche pas。"}},
 "Se moquer de": {"pos":"v. pr. 代词式动词（助动词 être）+ de","s":"嘲笑，取笑某人：se moquer de qqn。也表示「毫不在乎」：Je me moque de l'argent = 我不在乎钱。Tu te moques de moi ? =「你在耍我吗？」","ipa":"[sə mɔ.ke də]","ph":"o 开口 [ɔ]；qu 读 [k]；-er 读 [e]；de 读 [də]。","pi":"必须带 de。复合时态过去分词与主语配合：elle s'est moquée de moi。","et":"来源不确定（古法语 mocquer）。同族：moqueur, moquerie。","ex":[["Il ne faut pas se moquer des autres.","不要嘲笑别人。"],["Ils se moquent de son accent.","他们嘲笑他的口音。"],["Je me moque de ce que les gens pensent.","我不在乎别人怎么想。"]],"co":[["se moquer de quelqu'un","嘲笑某人"],["se moquer de tout","什么都不在乎"],["Tu te moques de moi ?","你在耍我吗？"],["se moquer du monde","太不像话，不把别人放在眼里"]],"sy":[["railler","soutenu","讥笑、嘲弄"],["se foutre de","argot","（粗）毫不在乎；嘲笑"],["taquiner","courant","善意地逗弄"]],"fq":"中高频，日常常用。","me":"moquer ≈ 发出 mo-mo 的嘲笑声，总要接 de。","tr":{"zh":"孩子们取笑他的帽子。","fr":"Les enfants se moquent de son chapeau.","alt":"Les gamins se moquent de son chapeau.","note":"se moquer de + 名词；复合时态：ils se sont moqués de lui。"}},
 "Souffrir": {"pos":"v.i. 不规则动词（助动词 avoir）；过去分词 souffert","s":"受苦；疼痛；患（病）。souffrir de + 病/名词 = 患有……、苦于……。faire souffrir qqn = 让某人受苦。否定式 ne pas pouvoir souffrir qqn = 受不了某人（偏书面）。","ipa":"[su.fʁiʁ]","ph":"ou [u]；ff 读一个 [f]；-frir 读 [fʁiʁ]，r 要发。","pi":"变位像 ouvrir：je souffre, tu souffres, il souffre；过去分词 souffert 的 t 不发。","et":"拉丁语 sufferre（sub + ferre，承受）。同族：souffrance, souffrant（身体不适的）。","ex":[["Il souffre d'une grave maladie.","他患有严重的疾病。"],["J'ai mal, je souffre beaucoup.","我很痛，非常难受。"],["Elle souffre de la chaleur.","她受不了这种热。"]],"co":[["souffrir de + 名词","患……；苦于……"],["souffrir en silence","默默忍受"],["souffrir le martyre","痛苦万分"],["faire souffrir quelqu'un","让某人受苦"]],"sy":[["avoir mal","courant","疼、难受，最日常"],["endurer","soutenu","忍受"],["pâtir","littéraire","遭受损害"]],"fq":"中高频，日常和书面都常用。","me":"souffrir ↔ offrir：两个都是 -frir，变位一样（je souffre / j'offre）。","tr":{"zh":"我爷爷患有糖尿病。","fr":"Mon grand-père souffre de diabète.","alt":"Mon grand-père a du diabète.","note":"souffrir de + 名词（病名常不加冠词）。"}},
 "Familier / Familière": {"pos":"adj. 形容词，阴性 familière；复数 familiers / familières","s":"①熟悉的、常见的：un visage familier；②（语言）口语的、随便的：un langage familier，字典里缩写 fam.；③亲昵的，有时过于随便。反义：inconnu / soutenu。","ipa":"[fa.mi.lje] / [fa.mi.ljɛʁ]","ph":"阳性 -ier 读 [lje]，r 不发；阴性 -ière 读 [ljɛʁ]，r 要发。","pi":"阳性 r 不发，阴性 r 要发；不要把 familier 读成英语 familiar。","et":"拉丁语 familiaris，来自 familia（家庭）。同族：famille, familiarité, se familiariser。","ex":[["Ce langage est trop familier.","这种说法太随便了。"],["Ce visage m'est familier.","这张脸我觉得眼熟。"],["Il est trop familier avec ses clients.","他对顾客太随便了。"]],"co":[["un langage familier","口语、随便的说法"],["un visage familier","熟悉的面孔"],["un mot familier","口语词"],["être familier avec quelque chose","熟悉某事物"]],"sy":[["connu","courant","熟悉的、知名的"],["décontracté","courant","轻松随意的"],["soutenu","courant","反义：高雅、书面的语体"]],"fq":"中频，谈语体时常见。","me":"family → familier：像一家人一样，不拘礼节。","tr":{"zh":"这个词太随便了，别对老师说。","fr":"Ce mot est trop familier, ne le dis pas au professeur.","alt":"Ce mot est un peu familier : évite de le dire au prof.","note":"mot 是阳性，所以用 familier。"}},
 "Poli(e)": {"pos":"adj. 形容词，阴性 polie；复数 polis / polies","s":"有礼貌的。être poli avec qqn = 对某人有礼貌；C'est poli de… =「……是有礼貌的」。poli 另有「光滑的、抛光的」之义：une pierre polie。","ipa":"[pɔ.li]","ph":"o 开口 [ɔ]；l 单个；i [i]；阴阳同音。","pi":"阴性 polie 读音和阳性相同；不要和 polonais（波兰人）混淆。","et":"拉丁语 politus（打磨光滑的），来自 polire（磨光）。同族：polir, poliment, politesse。","ex":[["Il est toujours très poli.","他总是很有礼貌。"],["Dis bonjour, sois poli !","打招呼，要有礼貌！"],["Elle m'a répondu poliment.","她礼貌地回答了我。"]],"co":[["poli avec les clients","对顾客有礼貌"],["une réponse polie","客气的回答"],["Sois poli !","放礼貌点！"],["la politesse","礼貌（名词）"]],"sy":[["courtois","soutenu","彬彬有礼的"],["aimable","courant","和蔼、亲切的"],["correct","courant","得体、规矩的"]],"fq":"高频，日常常用。","me":"poli ← 打磨光滑：待人接物「磨去了棱角」。","tr":{"zh":"请对客人有礼貌。","fr":"Sois poli avec les invités.","alt":"Sois gentil et poli avec les invités.","note":"poli avec qqn；对一个人说话用命令式 sois。"}},
 "Impoli(e)": {"pos":"adj. 形容词，阴性 impolie；复数 impolis / impolies","s":"不礼貌的，没礼貌的。C'est impoli de + 不定式 =「……是不礼貌的」。口语也常说 malpoli；mal élevé 更偏指「没教养」。","ipa":"[ɛ̃.pɔ.li]","ph":"im- 读鼻化元音 [ɛ̃]，m 不单独发音；p [p]；o 开口 [ɔ]；li [li]。","pi":"im- 的 m 不发音，但 p 要读出来；p 前拼 im- 不拼 in-。","et":"拉丁语 impolitus：否定前缀 in-（在 p 前变 im-）+ politus。同族：poli, poliment。","ex":[["C'est impoli de couper la parole.","打断别人说话是不礼貌的。"],["Il est impoli de ne pas dire merci.","不说谢谢是不礼貌的。"],["Il m'a répondu de façon impolie.","他很不客气地回答了我。"]],"co":[["un geste impoli","不礼貌的举动"],["une réponse impolie","无礼的回答"],["C'est impoli de + 不定式","……是不礼貌的"],["être impoli avec quelqu'un","对某人无礼"]],"sy":[["malpoli","courant","最常用的口语近义词"],["grossier","courant","粗鲁，比 impoli 更重"],["insolent","courant","无礼放肆"]],"fq":"中频，日常常用。","me":"im- = 不；im + poli = 不「打磨」，粗糙。","tr":{"zh":"打断别人说话很不礼貌。","fr":"C'est impoli d'interrompre les gens.","alt":"Ça ne se fait pas d'interrompre les gens.","note":"C'est + 形容词 + de + 不定式。"}},
 "Formel / Formelle": {"pos":"adj. 形容词，阴性 formelle；复数 formels / formelles","s":"①正式的（会议、场合）；②明确的、断然的：un refus formel, un ordre formel，没有商量余地；③形式上的。说「正式的服装/场合」也常用 officiel, habillé。","ipa":"[fɔʁ.mɛl]","ph":"o 开口 [ɔ]；r 要发 [ʁ]；-el 和 -elle 都读 [ɛl]。","pi":"阴阳同音；formel 常表示「明确的」，不要只当作「正式」。","et":"拉丁语 formalis，来自 forma（形状）。同族：forme, formalité, formellement。","ex":[["Cette réunion est très formelle.","这次会议很正式。"],["Il est formel : il n'a rien vu.","他斩钉截铁：他什么也没看见。"],["J'ai reçu un ordre formel.","我接到了明确的命令。"]],"co":[["une réunion formelle","正式会议"],["un refus formel","断然拒绝"],["une interdiction formelle","明令禁止"],["être formel","非常肯定"]],"sy":[["officiel","courant","官方的、正式的"],["catégorique","courant","断然的"],["solennel","soutenu","庄严隆重的"]],"fq":"中频，书面和会议场合常见。","me":"forme → formel：合乎「形式」，所以正式；也就板上钉钉。","tr":{"zh":"老板的拒绝是明确的。","fr":"Le refus du patron est formel.","alt":"Le patron a dit non, c'est formel.","note":"formel = 明确、不容置疑；「正式场合」多用 officiel。"}},
 "Informel / Informelle": {"pos":"adj. 形容词，阴性 informelle；复数 informels / informelles","s":"非正式的，不拘礼节的：une réunion informelle。也指「非官方的」：l'économie informelle（非正规经济）。","ipa":"[ɛ̃.fɔʁ.mɛl]","ph":"in- 读鼻化元音 [ɛ̃]，n 不发；fɔʁ [fɔʁ]；-el/-elle 读 [ɛl]。","pi":"n 不发音；不要和 informé（被告知的）混淆。","et":"in-（否定）+ formel。","ex":[["Nous aurons une rencontre informelle.","我们将有一次非正式见面。"],["On a discuté de façon informelle.","我们是私下聊的。"],["Il travaille dans le secteur informel.","他在非正规行业工作。"]],"co":[["une réunion informelle","非正式会议"],["un ton informel","随意的语气"],["une rencontre informelle","非正式见面"],["le secteur informel","非正规部门"]],"sy":[["décontracté","courant","轻松随意的"],["familier","courant","（语言）随便的"],["officieux","courant","非官方的"]],"fq":"中频，工作和新闻里常见。","me":"in- + formel：没有「形式」的约束。","tr":{"zh":"今晚有一场非正式的聚会。","fr":"Il y a une soirée informelle ce soir.","alt":"C'est juste une soirée entre amis, sans cérémonie.","note":"soirée 是阴性，所以用 informelle。"}},
 "Rare": {"pos":"adj. 形容词，阴阳同形；复数 rares","s":"稀有的，罕见的，稀少的。可放名词前：de rares occasions = 难得的几次机会。Il est rare de + 不定式 / Il est rare que + 虚拟式 =「很少……」。","ipa":"[ʁaʁ]","ph":"r [ʁ]；a [a]；词尾 r 发音，e 不发。","pi":"末尾 r 要发出来；r 是小舌音，不是中文的 r。","et":"拉丁语 rarus（稀疏的）。同族：rarement, rareté, raréfier。","ex":[["C'est une maladie très rare.","这是一种很罕见的疾病。"],["Il est rare de voir de la neige ici.","在这里很少见到雪。"],["Cet oiseau est de plus en plus rare.","这种鸟越来越少见了。"]],"co":[["une maladie rare","罕见疾病"],["de rares occasions","难得的机会"],["il est rare que + 虚拟式","很少……"],["se faire rare","变得难得一见"]],"sy":[["exceptionnel","courant","特别的、非同一般的"],["peu courant","courant","不常见的"],["fréquent","courant","反义：常见的"]],"fq":"中高频，日常常用。","me":"rare 读起来像 r-a-r：两头都是 r，「稀少」。","tr":{"zh":"在这里下雪很少见。","fr":"Il est rare qu'il neige ici.","alt":"Ici, la neige est rare.","note":"il est rare que 后接虚拟式。"}},
 "Respectueux / Respectueuse": {"pos":"adj. 形容词，阴性 respectueuse；复数 respectueux / respectueuses","s":"尊重人的，恭敬的。respectueux envers / de qqn。respectueux de la loi = 守法的。书信敬语：Veuillez agréer mes respectueuses salutations。","ipa":"[ʁɛs.pɛk.tɥø]","ph":"ec 读 [ɛk]；tu 读 [tɥ]（u 变成短半元音）；-eux 读 [ø]，x 不发；阴性 -euse 读 [øz]。","pi":"阳性 x 不发，阴性 z 要发；阳性复数形式不变。","et":"respect（拉丁语 respectus，回头看、顾及）+ 后缀 -eux。","ex":[["Soyez respectueux envers les autres.","要尊重他人。"],["Il est respectueux des règles.","他遵守规则。"],["Elle parle à ses parents de façon respectueuse.","她对父母说话很恭敬。"]],"co":[["respectueux envers quelqu'un","对某人恭敬"],["respectueux de l'environnement","爱护环境的"],["des salutations respectueuses","敬礼"],["rester respectueux","保持尊重"]],"sy":[["poli","courant","有礼貌的"],["déférent","soutenu","恭敬顺从的"],["irrespectueux","courant","反义：不尊重人的"]],"fq":"中频，日常和书面都常见。","me":"respect + -eux：充满「respect」的人。","tr":{"zh":"孩子们应该尊重长辈。","fr":"Les enfants doivent être respectueux envers les personnes âgées.","alt":"Les enfants doivent respecter les personnes âgées.","note":"être respectueux envers + 人；动词是 respecter。"}},
 "Irrespectueux / Irrespectueuse": {"pos":"adj. 形容词，阴性 irrespectueuse；复数 irrespectueux / irrespectueuses","s":"不尊重人的，无礼的。irrespectueux envers qqn / à l'égard de qqn。也指无视规则：irrespectueux de la loi。","ipa":"[i.ʁɛs.pɛk.tɥø]","ph":"ir- + respectueux；rr 只读一个 [ʁ]；-eux 读 [ø]，阴性 -euse 读 [øz]。","pi":"拼写有两个 r（ir + r），读音只有一个 [ʁ]；阳性 x 不发，阴性 z 要发。","et":"ir-（in- 在 r 前变 ir-，表否定）+ respectueux。","ex":[["Son comportement était irrespectueux.","他的行为很不尊重人。"],["Ne sois pas irrespectueux avec ton professeur.","别对老师无礼。"],["Cette remarque est irrespectueuse.","这句话很不尊重人。"]],"co":[["un comportement irrespectueux","无礼的行为"],["irrespectueux envers quelqu'un","对某人不敬"],["une remarque irrespectueuse","不敬的话"],["un ton irrespectueux","无礼的语气"]],"sy":[["impoli","courant","不礼貌的"],["insolent","courant","放肆无礼的"],["grossier","courant","粗鲁的，更重"]],"fq":"中频，比 impoli 更偏书面。","me":"ir- = 不；irrespectueux = 没有 respect。","tr":{"zh":"他对老师说话很无礼。","fr":"Il parle de façon irrespectueuse à son professeur.","alt":"Il est irrespectueux avec son prof.","note":"irrespectueux avec / envers qqn。"}},
 "Basique": {"pos":"adj. 形容词，阴阳同形；复数 basiques","s":"基础的，基本的：les règles basiques。口语里也带「太简单、没特色」的意味：Ce film est un peu basique。说「基础的」也常用 de base：le salaire de base。","ipa":"[ba.zik]","ph":"s 在元音之间读 [z]；qu 读 [k]；词尾 e 不发。","pi":"s 读 [z]，不是 [s]；-ique 读 [ik]。","et":"base + -ique；base 来自拉丁语 basis，源于希腊语 basis（基础）。","ex":[["C'est un principe basique.","这是一个基本原则。"],["Il faut connaître les règles basiques.","必须知道基本规则。"],["J'ai besoin d'un ordinateur basique.","我需要一台普通的电脑。"]],"co":[["un principe basique","基本原则"],["les règles basiques","基本规则"],["un niveau basique","初级水平"],["de base","基础的（近义说法）"]],"sy":[["élémentaire","courant","初级的、最基本的"],["fondamental","courant","根本的，分量更重"],["simpliste","courant","过于简单（贬义）"]],"fq":"中高频，日常常用。","me":"base → basique：只要记住 s 读 [z]。","tr":{"zh":"这只是一个很基础的问题。","fr":"C'est juste une question basique.","alt":"C'est une question de base.","note":"basique 常可换成 de base。"}},
 "Désagréable": {"pos":"adj. 形容词，阴阳同形；复数 désagréables","s":"令人不快的：气味、天气、人、感觉都可以。une personne désagréable = 不好相处的人。反义 agréable。","ipa":"[de.za.gʁe.abl]","ph":"dé [de]；sa → [za]（s 在元音间读 [z]）；gré [gʁe]；-able 读 [abl]。","pi":"s 读 [z]；é 与 a 分开读，不连成一个音。","et":"dés-（否定）+ agréable（à gré，合意）。同族：agréer, gré。","ex":[["Cette odeur est très désagréable.","这股气味很难闻。"],["Il a été très désagréable avec moi.","他对我很不友善。"],["Il fait un temps désagréable.","天气很糟糕。"]],"co":[["une odeur désagréable","难闻的气味"],["un goût désagréable","难吃的味道"],["être désagréable avec quelqu'un","对某人不客气"],["il est désagréable de + 不定式","……很让人不舒服"]],"sy":[["pénible","courant","难受、烦人的"],["déplaisant","soutenu","不讨喜的"],["agréable","courant","反义：令人愉快的"]],"fq":"中高频，日常常用。","me":"dés- + agréable：从「令人愉快」里拿掉。","tr":{"zh":"这个房间有一股难闻的味道。","fr":"Il y a une odeur désagréable dans cette pièce.","alt":"Ça sent mauvais dans cette pièce.","note":"désagréable 阴阳同形。"}},
 "Réservé à": {"pos":"adj. 形容词（réserver 的过去分词），阴性 réservée；常与 à 连用","s":"专供……的，仅限……：réservé aux employés。也指「已订好的」：une table réservée；还可指人「内向、矜持」：Il est réservé。","ipa":"[ʁe.zɛʁ.ve a]","ph":"ré [ʁe]；s 在元音间读 [z]；er 读 [ɛʁ]；vé [ve]；à 读 [a]。","pi":"à + les = aux：réservé aux employés，不说 *à les；à 带重音，与 a（有）不同。","et":"动词 réserver（拉丁语 reservare，re- + servare 保存）的过去分词。同族：réservation, réserve。","ex":[["Ce parking est réservé aux employés.","这个停车场仅限员工使用。"],["La table est déjà réservée.","这张桌子已经订出去了。"],["Il est très réservé, il parle peu.","他很内向，话很少。"]],"co":[["réservé à quelqu'un","专供某人"],["réservé aux adultes","仅限成人"],["une place réservée","预留的座位"],["tous droits réservés","版权所有"]],"sy":[["destiné à","courant","面向……，不一定排他"],["privé","courant","私人的，不对外"],["ouvert à","courant","反义：对……开放"]],"fq":"中高频，标牌和说明里常见。","me":"réservé = 给你「留着」的，别人不能用。","tr":{"zh":"这些座位仅限孩子使用。","fr":"Ces places sont réservées aux enfants.","alt":"Ces places, c'est seulement pour les enfants.","note":"过去分词配合 places：réservées；à + les = aux。"}},
 "Destiné à": {"pos":"adj. 形容词（destiner 的过去分词），阴性 destinée；常用 destiné à + 名词 / 不定式","s":"旨在……；给……的，面向……的：Ce livre est destiné aux enfants。destiné à + 不定式 = 注定会……：Il est destiné à devenir célèbre。","ipa":"[dɛs.ti.ne a]","ph":"des [dɛs]；s 读 [s]；ti [ti]；né [ne]；à 读 [a]。","pi":"后面用 à，不用 pour；à + les = aux；阴性 destinée 读音与阳性相同。","et":"拉丁语 destinare（固定、决定）。同族：destin, destinée, destination, destinataire。","ex":[["Ce message est destiné à tout le monde.","这条消息是发给所有人的。"],["Cette crème est destinée aux peaux sèches.","这款面霜适合干性皮肤。"],["Ce projet est destiné à aider les jeunes.","这个项目旨在帮助年轻人。"]],"co":[["destiné à quelqu'un","给某人的"],["destiné à + 不定式","旨在……；注定……"],["un message destiné à…","发给……的消息"],["être destiné à","是为……准备的"]],"sy":[["réservé à","courant","专供"],["prévu pour","courant","为……准备的"],["voué à","soutenu","注定要……"]],"fq":"中频，说明和书面语常见。","me":"destiné ← destin：事先已经「定好去向」。","tr":{"zh":"这本书是写给初学者的。","fr":"Ce livre est destiné aux débutants.","alt":"Ce livre est fait pour les débutants.","note":"destiné à + 名词（人）；aux = à + les。"}},
 "Épanoui(e)": {"pos":"adj. 形容词，阴性 épanouie；复数 épanouis / épanouies","s":"（人）心情舒畅、生活充实、状态很好；（花）盛开。se sentir épanoui = 觉得很满足、活出了自己。un sourire épanoui = 灿烂的笑容。","ipa":"[e.pa.nwi]","ph":"é [e]；pa [pa]；noui 读 [nwi]（n + 半元音 w + i）。","pi":"oui 读 [wi]，不是 [u.i]；动词 épanouir 变位像 finir（nous épanouissons）。","et":"来源不确定。同族：s'épanouir（绽放；充实）, épanouissement。","ex":[["Elle a l'air très épanouie dans son nouveau travail.","她在新工作中看起来很充实。"],["Les roses sont épanouies.","玫瑰盛开了。"],["Il ne se sent pas épanoui dans son couple.","他在感情中并不觉得幸福。"]],"co":[["se sentir épanoui","觉得充实"],["un sourire épanoui","灿烂的笑容"],["épanoui dans son travail","在工作中很满足"],["une fleur épanouie","盛开的花"]],"sy":[["heureux","courant","幸福的"],["comblé","courant","心满意足的"],["accompli","courant","有成就、充实的"]],"fq":"中频，谈生活状态时常用。","me":"épanoui：花瓣全打开了，人也完全「舒展」。","tr":{"zh":"他在工作中很满足。","fr":"Il est épanoui dans son travail.","alt":"Il se sent bien dans son travail, il est heureux.","note":"épanoui dans + 名词（工作、生活）。"}},
 "Solidaire": {"pos":"adj. 形容词，阴阳同形；复数 solidaires","s":"团结一致的，互相扶持的。être solidaire de qqn = 声援、支持某人，愿意一起承担。une économie solidaire = 互助经济。","ipa":"[sɔ.li.dɛʁ]","ph":"o 开口 [ɔ]；-aire 读 [ɛʁ]，r 要发。","pi":"不是「固体」（那是 solide）；solidaire 的意思是「互相连带、互助」。","et":"与 solide 同源（拉丁语 solidus）。同族：solidarité, solidairement。","ex":[["Nous devons être solidaires dans cette épreuve.","在这次考验中我们必须团结。"],["Nous sommes solidaires des victimes.","我们声援受害者。"],["Les voisins ont été très solidaires.","邻居们都很互相帮忙。"]],"co":[["être solidaire de quelqu'un","支持、声援某人"],["rester solidaires","保持团结"],["une économie solidaire","互助经济"],["un geste solidaire","互助的举动"]],"sy":[["uni","courant","团结在一起的"],["soudé","courant","抱成一团的"],["égoïste","courant","反义：自私的"]],"fq":"中高频，新闻和社会话题里常见。","me":"solidaire ≈ solide 的人群：大家连成一块。","tr":{"zh":"遇到困难时，朋友们要互相支持。","fr":"Dans les difficultés, les amis doivent être solidaires.","alt":"Quand ça va mal, les amis doivent se serrer les coudes.","note":"se serrer les coudes = 互相扶持。"}},
 "Responsable (pour l'environnement)": {"pos":"adj. 形容词，阴阳同形；复数 responsables；也作名词 le/la responsable（负责人）","s":"负责任的；应负责的。être responsable de = 对……负责。consommer de façon responsable = 负责任地消费（环保、道德）。un responsable = 负责人、主管。","ipa":"[ʁɛs.pɔ̃.sabl]","ph":"re [ʁɛ]；s [s]；on 鼻化 [ɔ̃]；sa [sa]；-able 读 [abl]。","pi":"这里的 s 都读 [s]，不要读成 [z]；词尾 e 不发。","et":"拉丁语 respondere（回答），responsable = 「须回答的」，即对……负责。同族：répondre, responsabilité。","ex":[["Il faut adopter un comportement responsable.","应当采取负责任的行为。"],["Il est responsable de ce projet.","他负责这个项目。"],["Il faut consommer de façon responsable.","要负责任地消费。"]],"co":[["être responsable de + 名词","对……负责"],["un comportement responsable","负责任的行为"],["consommer de façon responsable","负责任地消费"],["le responsable des ventes","销售主管"]],"sy":[["sérieux","courant","认真可靠的"],["fiable","courant","可靠的"],["coupable","courant","有过错的（不同方向）"]],"fq":"高频，日常和新闻都常用。","me":"responsable = 能「répondre」的人：出了事由他回答。","tr":{"zh":"我们应该做负责任的消费者。","fr":"Nous devons être des consommateurs responsables.","alt":"Il faut consommer de manière plus responsable.","note":"responsable 随名词变复数：responsables。"}},
 "Salarial(e)": {"pos":"adj. 形容词，阴性 salariale；阳性复数 salariaux，阴性复数 salariales","s":"工资的，薪金的：l'écart salarial = 薪酬差距；une augmentation salariale = 加薪。形容「钱」方面；指人的「雇员」是 salarié(e)。","ipa":"[sa.la.ʁjal]","ph":"ri 与 al 合成 [ʁjal]，i 变成半元音 j。","pi":"阳性复数是 salariaux，不是 *salarials；不要和 salarié（雇员）混淆。","et":"salaire（拉丁语 salarium）+ -ial。同族：salarié。","ex":[["L'écart salarial est un vrai problème.","薪酬差距是个真正的问题。"],["Nous demandons une augmentation salariale.","我们要求加薪。"],["Les charges salariales ont augmenté.","人工成本上涨了。"]],"co":[["l'écart salarial","薪酬差距"],["une augmentation salariale","加薪"],["la masse salariale","工资总额"],["les revendications salariales","薪资诉求"]],"sy":[["salarié","courant","名词/形容词：雇员（指人）"],["financier","courant","财务的，范围更宽"],["rémunération","soutenu","名词：报酬"]],"fq":"中频，工作和新闻里常见。","me":"salaire → salarial：-aire 变 -ial。","tr":{"zh":"公司同意了加薪。","fr":"L'entreprise a accepté l'augmentation salariale.","alt":"La boîte a dit oui à la hausse des salaires.","note":"augmentation 阴性 → salariale。"}},
 "Égal(e)": {"pos":"adj. 形容词，阴性 égale；阳性复数 égaux，阴性复数 égales","s":"平等的；相等的；一样的。égal à = 等于。Ça m'est égal =「我无所谓」。à égalité = 平局、同分。","ipa":"[e.gal]","ph":"é [e]；g 在 a 前读硬音 [g]；al [al]。","pi":"阳性复数是 égaux [e.go]，不是 *égals。","et":"拉丁语 aequalis，来自 aequus（平的、公平的）。同族：égalité, également, inégal。","ex":[["Tous les hommes naissent libres et égaux.","人人生而自由平等。"],["Deux plus deux est égal à quatre.","二加二等于四。"],["Ça m'est égal, choisis toi-même.","我无所谓，你自己选。"]],"co":[["égal à","等于"],["Ça m'est égal.","我无所谓。"],["à égalité","同分、平局"],["sur un pied d'égalité","平起平坐"]],"sy":[["identique","courant","完全相同的"],["équivalent","courant","相当的"],["inégal","courant","反义：不平等的"]],"fq":"极高频，日常常用。","me":"égal → égalité：连到「平等」，复数是 égaux。","tr":{"zh":"男人和女人应该平等。","fr":"Les hommes et les femmes doivent être égaux.","alt":"Les femmes et les hommes ont les mêmes droits.","note":"混合性别的主语配合阳性复数 égaux。"}},
 "Équivalent(e)": {"pos":"adj. 形容词，阴性 équivalente；复数 équivalents / équivalentes；也作名词 un équivalent","s":"相当的，等值的。équivalent à qqch = 与……相当。名词 un équivalent = 对应的东西：Il n'y a pas d'équivalent en chinois。","ipa":"[e.ki.va.lɑ̃]","ph":"é [e]；qui 读 [ki]；va [va]；-lent 读 [lɑ̃]，t 不发。","pi":"qu 读 [k]；形容词词尾是 -ent，不是 -ant；阴性 équivalente 的 t 发音。","et":"拉丁语 aequivalens（aequus 相等 + valere 值）。同族：valeur, valoir, équivalence。","ex":[["Ce diplôme est équivalent à un master.","这个文凭相当于硕士。"],["Les deux prix sont équivalents.","两个价格差不多。"],["Il n'y a pas d'équivalent exact en chinois.","中文里没有完全对应的说法。"]],"co":[["équivalent à","与……相当"],["un diplôme équivalent","同等学历"],["un équivalent en français","法语里的对应说法"],["de valeur équivalente","价值相当"]],"sy":[["égal","courant","相等的"],["comparable","courant","可比较的"],["semblable","courant","相似的"]],"fq":"中频，书面和学习中常见。","me":"équi- = 相等 + valent = 值：「值一样」。","tr":{"zh":"这两个文凭是等值的。","fr":"Ces deux diplômes sont équivalents.","alt":"Ces deux diplômes se valent.","note":"diplômes 阳性复数 → équivalents；se valoir = 价值相当。"}},
 "Timide": {"pos":"adj. 形容词，阴阳同形；复数 timides；也作名词 un/une timide","s":"害羞的，腼腆的；也指「不够大胆的」：une réforme timide, un timide sourire。","ipa":"[ti.mid]","ph":"ti [ti]；mi [mi]；d 要发 [d]；词尾 e 不发。","pi":"d 要读出来 [mid]，不能丢；阴阳同形。","et":"拉丁语 timidus，来自 timere（害怕）。同族：timidité, intimider。","ex":[["Cet enfant est très timide.","这个孩子很害羞。"],["Ne sois pas timide, viens parler !","别害羞，过来说话！"],["Un timide sourire est apparu sur son visage.","他脸上露出一丝羞涩的微笑。"]],"co":[["un enfant timide","腼腆的孩子"],["timide devant quelqu'un","在某人面前害羞"],["un sourire timide","羞涩的微笑"],["une tentative timide","小心翼翼的尝试"]],"sy":[["réservé","courant","内向、话少的"],["gêné","courant","窘迫、不好意思的"],["hardi","littéraire","反义：大胆的"]],"fq":"中高频，日常常用。","me":"timide ← timere（害怕）：怕见人，所以害羞。","tr":{"zh":"我女儿在陌生人面前很害羞。","fr":"Ma fille est très timide devant les inconnus.","alt":"Ma fille est un peu timide avec les gens qu'elle ne connaît pas.","note":"timide devant / avec + 人。"}},
 "Coupable": {"pos":"adj. 形容词，阴阳同形；复数 coupables；也作名词 un/une coupable（罪犯）","s":"有罪的；有过错的。se sentir coupable = 觉得内疚。coupable de + 名词 = 犯了……罪/错。名词：Qui est le coupable ? =「谁是罪魁祸首？」","ipa":"[ku.pabl]","ph":"cou [ku]；pa [pa]；ble 读 [bl]。","pi":"和 couper（切）无关；ou 读 [u]；词尾 e 不发。","et":"拉丁语 culpabilis，来自 culpa（过错）。同族：culpabilité, culpabiliser, disculper。","ex":[["Le juge l'a déclaré coupable.","法官宣布他有罪。"],["Je me sens coupable de ne pas l'avoir aidé.","我没帮他，觉得很内疚。"],["Qui est le coupable ?","谁是罪魁祸首？"]],"co":[["déclarer quelqu'un coupable","宣判某人有罪"],["se sentir coupable","感到内疚"],["coupable de + 名词","犯了……的罪/错"],["plaider coupable","认罪"]],"sy":[["fautif","courant","有错的，口语常用"],["responsable","courant","有责任的"],["innocent","courant","反义：无辜的"]],"fq":"中高频，日常和法律场合都常见。","me":"coupable ← culpa：「有错」，和 couper 无关。","tr":{"zh":"他知道自己有罪。","fr":"Il sait qu'il est coupable.","alt":"Il sait que c'est de sa faute.","note":"être coupable (de) = 有罪、有过错；c'est de sa faute 更口语。"}},
 "Aberrant(e)": {"pos":"adj. 形容词，阴性 aberrante；复数 aberrants / aberrantes","s":"荒谬的，离谱的，不合常理的：un prix aberrant（离谱的价格），un comportement aberrant。比 absurde 更强调「完全不合常规」。","ipa":"[a.bɛ.ʁɑ̃]","ph":"a [a]；b [b]；e [ɛ]；rr 只读一个 [ʁ]；ant 读 [ɑ̃]，t 不发。","pi":"rr 只读一个 [ʁ]；阳性词尾 t 不发，阴性 aberrante 的 t 要发。","et":"拉丁语 aberrare（ab- 离开 + errare 游荡、走偏）。同族：aberration, errer, erreur。","ex":[["C'est une situation aberrante.","这是一个荒谬的情况。"],["Ce prix est aberrant !","这个价格太离谱了！"],["Il a eu un comportement aberrant.","他的行为很离谱。"]],"co":[["un prix aberrant","离谱的价格"],["une idée aberrante","荒谬的想法"],["une décision aberrante","不合理的决定"],["une valeur aberrante","异常值"]],"sy":[["absurde","courant","荒谬的"],["insensé","courant","毫无道理的"],["délirant","familier","疯狂离谱的"]],"fq":"中频，新闻和评论里常见。","me":"ab- + errer：偏离了正道，所以「离谱」。","tr":{"zh":"这个价格太离谱了。","fr":"Ce prix est complètement aberrant.","alt":"C'est un prix absurde, personne ne va payer ça.","note":"prix 是阳性；complètement 加强语气。"}},
 "Faible": {"pos":"adj. 形容词，阴阳同形；复数 faibles；也作名词 un faible（弱点；偏爱）","s":"弱的；低的（比率、数量）；微弱的：un faible taux, une faible lumière。avoir un faible pour qqn / qqch = 偏爱某人/某物。","ipa":"[fɛbl]","ph":"f [f]；ai [ɛ]；bl [bl]；词尾 e 不发。","pi":"只有一个音节 [fɛbl]；ai 读 [ɛ]；常被误读成两个音节。","et":"古法语 feble / fleible，来自拉丁语 flebilis（可怜的）。同族：faiblesse, affaiblir。","ex":[["Le taux de réussite à cet examen est très faible.","这场考试的通过率很低。"],["Il est trop faible pour porter ça.","他太弱了，搬不动这个。"],["J'ai un faible pour le chocolat.","我特别爱吃巧克力。"]],"co":[["un faible taux","低比率"],["une faible chance","渺茫的机会"],["avoir un faible pour","偏爱"],["faible en maths","数学差"]],"sy":[["bas","courant","（数值）低的"],["fragile","courant","脆弱的"],["fort","courant","反义：强的"]],"fq":"极高频，日常常用。","me":"faible：fai + ble，一口气读完，像是气力不足。","tr":{"zh":"今年的通过率很低。","fr":"Le taux de réussite est faible cette année.","alt":"Cette année, peu de gens réussissent.","note":"说比率低：taux faible 或 bas，不说 petit。"}},
 "Pragmatique": {"pos":"adj. 形容词，阴阳同形；复数 pragmatiques","s":"务实的，讲求实际效果的：une approche pragmatique。不空谈理论，只看什么管用。","ipa":"[pʁaɡ.ma.tik]","ph":"pr [pʁ]；a [a]；g 在 a 前读硬音 [g]；qu 读 [k]；词尾 e 不发。","pi":"g 读 [g]，不是 [ʒ]；-ique 读 [ik]。","et":"希腊语 pragma（事、行动），经拉丁语进入法语。同属「做事」词族的还有 pratique。","ex":[["Il faut être pragmatique pour résoudre ce problème.","解决这个问题要务实。"],["Elle a une approche très pragmatique.","她的做法非常务实。"],["Soyons pragmatiques : combien ça coûte ?","咱们务实点：这要多少钱？"]],"co":[["une approche pragmatique","务实的做法"],["un esprit pragmatique","务实的头脑"],["une solution pragmatique","务实的解决办法"],["être pragmatique","要务实"]],"sy":[["réaliste","courant","现实的、实际的"],["concret","courant","具体的"],["idéaliste","courant","反义：理想主义的"]],"fq":"中频，工作和讨论中常见。","me":"pragma ≈ 行动：关注「做出来」的人。","tr":{"zh":"我们需要一个务实的解决办法。","fr":"Nous avons besoin d'une solution pragmatique.","alt":"Il nous faut une solution réaliste et efficace.","note":"avoir besoin de + 名词；solution 阴性，pragmatique 同形。"}},
 "Concret / Concrète": {"pos":"adj. 形容词，阴性 concrète；复数 concrets / concrètes","s":"具体的，实际的，看得见摸得着的：un exemple concret。反义 abstrait。名词 le concret = 实际。水泥/混凝土要说 béton，不说 concret。","ipa":"[kɔ̃.kʁɛ] / [kɔ̃.kʁɛt]","ph":"con [kɔ̃]；cr [kʁ]；阳性 -et 读 [ɛ]；阴性 -ète 读 [ɛt]。","pi":"阳性 t 不发，阴性 concrète 的 t 要发；阴性有重音 è。","et":"拉丁语 concretus（长在一起的、凝结的）。同族：concrétiser, concrètement。","ex":[["J'ai besoin d'un exemple concret.","我需要一个具体的例子。"],["As-tu un projet concret ?","你有具体的计划吗？"],["Concrètement, que faut-il faire ?","具体来说，该怎么做？"]],"co":[["un exemple concret","具体例子"],["un projet concret","具体计划"],["des résultats concrets","实实在在的成果"],["concrètement","具体来说"]],"sy":[["précis","courant","精确的"],["réel","courant","真实的"],["abstrait","courant","反义：抽象的"]],"fq":"高频，日常和工作中常用。","me":"concret：con-（一起）+ crescere（生长）：长成了实实在在的东西。","tr":{"zh":"你能给我一个具体的例子吗？","fr":"Pouvez-vous me donner un exemple concret ?","alt":"Tu peux me donner un exemple précis ?","note":"exemple 阳性 → concret；礼貌用 vous。"}},
 "Abstrait(e)": {"pos":"adj. 形容词，阴性 abstraite；复数 abstraits / abstraites；也作名词 l'abstrait","s":"抽象的，不具体的；难懂的。l'art abstrait = 抽象艺术；un nom abstrait = 抽象名词。反义 concret。","ipa":"[ab.stʁɛ] / [ab.stʁɛt]","ph":"ab [ab]；str 三个辅音连读 [stʁ]；ai 读 [ɛ]。","pi":"阳性 t 不发 [ab.stʁɛ]，阴性 abstraite 的 t 要发 [ab.stʁɛt]。","et":"拉丁语 abstractus（abs- 离开 + trahere 拉），意为「抽离出来的」。同族：extraire, abstraction。","ex":[["C'est un concept très abstrait.","这是个很抽象的概念。"],["L'art abstrait ne me plaît pas.","我不喜欢抽象艺术。"],["Pour moi, cette théorie reste trop abstraite.","对我来说，这个理论还是太抽象。"]],"co":[["un concept abstrait","抽象概念"],["l'art abstrait","抽象艺术"],["un nom abstrait","抽象名词"],["une idée abstraite","抽象的想法"]],"sy":[["théorique","courant","理论上的"],["vague","courant","模糊的"],["concret","courant","反义：具体的"]],"fq":"中高频，学习和讨论中常见。","me":"abs- + traire：从现实里「抽」出来。","tr":{"zh":"这个概念对孩子来说太抽象了。","fr":"Ce concept est trop abstrait pour les enfants.","alt":"C'est trop abstrait pour des enfants, il faut un exemple.","note":"trop… pour + 名词。"}},
 "Pratique": {"pos":"adj. 形容词，阴阳同形；复数 pratiques；名词 la pratique（n.f.）= 实践","s":"实用的；方便的：un outil pratique。Ce n'est pas pratique = 这不方便。名词 la pratique = 实践、练习。","ipa":"[pʁa.tik]","ph":"pr [pʁ]；a [a]；ti [ti]；qu 读 [k]；词尾 e 不发。","pi":"ti 读 [ti]，不读 [si]；qu 读 [k]。","et":"希腊语 praktikos（做事的），经拉丁语 practicus 入法语。同族：pratiquer, praticien。","ex":[["C'est un outil très pratique.","这是个很实用的工具。"],["Un sac à dos, c'est très pratique.","背包很方便。"],["Ce n'est pas pratique de prendre le bus ici.","在这里坐公交不方便。"]],"co":[["un outil pratique","实用的工具"],["C'est pratique de + 不定式","……很方便"],["en pratique","实际上"],["travaux pratiques (TP)","实践课、实验课"]],"sy":[["commode","courant","方便的"],["utile","courant","有用的"],["fonctionnel","courant","功能好、实用的"]],"fq":"极高频，日常常用。","me":"pratique：「用得上」就是 pratique。","tr":{"zh":"坐地铁很方便。","fr":"Le métro, c'est pratique.","alt":"C'est pratique de prendre le métro.","note":"C'est pratique de + 不定式。"}},
 "Logique": {"pos":"adj. 形容词，阴阳同形；复数 logiques；名词 la logique（n.f.）= 逻辑","s":"合乎逻辑的，合情合理的。C'est logique =「这很自然、理所当然」。名词 la logique = 逻辑。","ipa":"[lɔ.ʒik]","ph":"o 开口 [ɔ]；g 在 i 前读 [ʒ]；qu 读 [k]；词尾 e 不发。","pi":"g 读 [ʒ]，不是 [g]；-ique 读 [ik]。","et":"希腊语 logikos，来自 logos（话语、理性）。同族：-logie（如 biologie）。","ex":[["Sa réaction est tout à fait logique.","他的反应完全合乎逻辑。"],["Il est logique que tu sois fâché.","你生气是合理的。"],["C'est logique, il est fatigué.","很正常，他累了。"]],"co":[["C'est logique.","这很合理。"],["une suite logique","合乎逻辑的后续"],["un raisonnement logique","逻辑推理"],["il est logique que + 虚拟式","……是合理的"]],"sy":[["rationnel","courant","理性的"],["cohérent","courant","前后一致的"],["naturel","courant","自然而然的"]],"fq":"高频，日常常用。","me":"logique ← logos：有「道理」。","tr":{"zh":"他累了，所以睡了，这很合理。","fr":"Il est fatigué, alors il dort : c'est logique.","alt":"Il est crevé, donc il dort, c'est normal.","note":"C'est logique 表示「理所当然」。"}},
 "Irremplaçable": {"pos":"adj. 形容词，阴阳同形；复数 irremplaçables","s":"不可替代的，无法取代的：un ami irremplaçable。强调某人或某物独一无二的价值。","ipa":"[i.ʁɑ̃.pla.sabl]","ph":"ir [i]；rem 读 [ʁɑ̃]；pla [pla]；ça 读 [sa]；-able 读 [abl]。","pi":"ç 带软音符，读 [s]，不能写成 c；rr 读一个 [ʁ]。","et":"ir-（否定）+ remplaçable；remplacer = re- + en- + placer（place，位置）。","ex":[["Personne n'est irremplaçable.","没有人是不可替代的。"],["Ce vieux livre est irremplaçable.","这本旧书无可替代。"],["Tu es irremplaçable dans l'équipe.","你在团队里不可替代。"]],"co":[["un objet irremplaçable","无可替代的物品"],["une perte irremplaçable","无法弥补的损失"],["être irremplaçable","不可替代"],["Personne n'est irremplaçable.","人人都可被替代。"]],"sy":[["unique","courant","独一无二的"],["indispensable","courant","不可或缺的"],["remplaçable","courant","反义：可替代的"]],"fq":"中频，日常和书面都有。","me":"ir- + remplaçable：没有「place」可以让别人来占。","tr":{"zh":"这张老照片是无可替代的。","fr":"Cette vieille photo est irremplaçable.","alt":"On ne peut pas remplacer cette vieille photo.","note":"photo 阴性，irremplaçable 阴阳同形。"}},
 "Fondamental(e)": {"pos":"adj. 形容词，阴性 fondamentale；阳性复数 fondamentaux，阴性复数 fondamentales","s":"根本的，基本的，最重要的：une question fondamentale。les fondamentaux (n.m.pl.) = 基本功、基础知识。","ipa":"[fɔ̃.da.mɑ̃.tal]","ph":"fon 读 [fɔ̃]；da [da]；men 读 [mɑ̃]；tal [tal]。","pi":"中间是 -men-（读 [mɑ̃]）；阳性复数是 fondamentaux，不是 *fondamentals。","et":"拉丁语 fundamentum（基础），来自 fundus（底）。同族：fond, fondation, fonder。","ex":[["C'est une question fondamentale.","这是个根本性的问题。"],["La confiance est fondamentale.","信任是最根本的。"],["Il faut revenir aux fondamentaux.","要回到基本功上来。"]],"co":[["une question fondamentale","根本问题"],["un droit fondamental","基本权利"],["la recherche fondamentale","基础研究"],["les fondamentaux","基本功"]],"sy":[["essentiel","courant","必不可少的"],["principal","courant","主要的"],["capital","soutenu","至关重要的"]],"fq":"中高频，书面和讨论中常见。","me":"fond（底）+ -ment + -al：位于「底部」的东西。","tr":{"zh":"健康是最基本的。","fr":"La santé est fondamentale.","alt":"Ce qui compte le plus, c'est la santé.","note":"santé 阴性 → fondamentale。"}},
 "Bavard(e)": {"pos":"adj. 形容词，阴性 bavarde；复数 bavards / bavardes；也作名词 un bavard / une bavarde","s":"爱说话的，话多的；有时略带贬义（多嘴、闲聊）。动词 bavarder = 聊天、闲聊。","ipa":"[ba.vaʁ] / [ba.vaʁd]","ph":"ba [ba]；va [va]；r 要发；阳性 d 不发，阴性 -de 的 d 发音。","pi":"阳性 bavard 的 d 不发，阴性 bavarde 的 d 要发。","et":"bave（口水）+ -ard。同族：bavarder, bavardage。","ex":[["Ce petit garçon est très bavard.","这个小男孩很爱说话。"],["Elle est bavarde comme une pie.","她像喜鹊一样话多。"],["Il est trop bavard en classe.","他在课堂上话太多。"]],"co":[["bavard comme une pie","话痨"],["bavarder avec des amis","和朋友聊天"],["un enfant bavard","话多的孩子"],["un élève bavard","爱说话的学生"]],"sy":[["causant","familier","健谈的"],["loquace","soutenu","能说会道的"],["silencieux","courant","反义：安静的"]],"fq":"中频，日常口语常用。","me":"bave + -ard：话多到嘴角都要流口水了。","tr":{"zh":"我的邻居很健谈。","fr":"Ma voisine est très bavarde.","alt":"Ma voisine ne s'arrête jamais de parler.","note":"voisine 阴性 → bavarde（d 发音）。"}},
 "Riche": {"pos":"adj. 形容词，阴阳同形；复数 riches；也作名词 un riche / une riche","s":"①有钱的，富有的；②丰富的：une culture riche。riche en + 名词 = 富含……：riche en vitamines。","ipa":"[ʁiʃ]","ph":"r [ʁ]；i [i]；ch 读 [ʃ]；词尾 e 不发。","pi":"ch 读 [ʃ]，不是 [tʃ]；阴阳同形。","et":"来自法兰克语 *rīki（有权势的），古法语 riche。同族：richesse, enrichir。","ex":[["La culture chinoise est très riche.","中国文化非常丰富。"],["Ce fruit est riche en vitamines.","这种水果富含维生素。"],["Il est riche, mais il n'est pas heureux.","他有钱，但不幸福。"]],"co":[["riche en + 名词","富含……"],["un pays riche","富裕的国家"],["une culture riche","丰富的文化"],["devenir riche","变富"]],"sy":[["aisé","courant","宽裕的"],["fortuné","soutenu","家财万贯的"],["pauvre","courant","反义：穷的"]],"fq":"极高频，日常常用。","me":"riche 读 [ʁiʃ]：像「r-i-sh」，简短有力。","tr":{"zh":"这种水果富含维生素。","fr":"Ce fruit est riche en vitamines.","alt":"Ce fruit contient beaucoup de vitamines.","note":"riche en + 名词（不加冠词）。"}},
 "Absorbé(e)": {"pos":"adj. 形容词，阴性 absorbée；复数 absorbés / absorbées","s":"全神贯注的，专心的。absorbé par / dans qqch = 沉浸于……。也指「被吸收的」：absorbé par la peau。","ipa":"[ap.sɔʁ.be]","ph":"ab 在 s 前，b 读作 [p]；or 读 [ɔʁ]；bé 读 [be]。","pi":"b 在 s 前变清音 [p]：[ap.sɔʁ.be]；阴性 absorbée 读音与阳性相同。","et":"动词 absorber（拉丁语 absorbere，吞下）的过去分词。同族：absorption, absorbant。","ex":[["Cette caissière est absorbée par son travail.","这位收银员专心于工作。"],["Il est absorbé dans sa lecture.","他读书读得入神。"],["Je suis absorbé par mes pensées.","我陷入了沉思。"]],"co":[["absorbé par quelque chose","专注于某事"],["absorbé dans ses pensées","陷入沉思"],["absorbé par son travail","埋头工作"],["être absorbé dans sa lecture","读得入神"]],"sy":[["concentré","courant","专注的"],["plongé dans","courant","沉浸在……"],["distrait","courant","反义：心不在焉的"]],"fq":"中频，描写人时常见。","me":"absorbé = 被「吸」进去了，外面的事看不见。","tr":{"zh":"他全神贯注地看书。","fr":"Il est absorbé par sa lecture.","alt":"Il lit sans rien voir autour de lui.","note":"absorbé par / dans + 名词。"}},
 "Convivial(e)": {"pos":"adj. 形容词，阴性 conviviale；阳性复数 conviviaux，阴性复数 conviviales","s":"友好热闹、融洽的：多指气氛或场所，让人愿意聚在一起：une ambiance conviviale。也指软件、设备「好用易上手」。","ipa":"[kɔ̃.vi.vjal]","ph":"con 读 [kɔ̃]；vi [vi]；vial 读 [vjal]，i 变成半元音。","pi":"vial 读 [vjal]；阳性复数 conviviaux [kɔ̃.vi.vjo]。","et":"拉丁语 convivium（宴会，con- 一起 + vivere 生活）。同族：convive（赴宴的人）。","ex":[["L'ambiance dans ce restaurant est très conviviale.","这家餐厅的氛围很融洽。"],["C'est un repas convivial entre amis.","这是朋友间轻松热闹的一顿饭。"],["Ce logiciel est très convivial.","这个软件很好上手。"]],"co":[["une ambiance conviviale","融洽热闹的气氛"],["un lieu convivial","让人感到亲切的地方"],["un repas convivial","热闹的聚餐"],["un logiciel convivial","易用的软件"]],"sy":[["chaleureux","courant","热情温暖的"],["sympathique","courant","让人喜欢的"],["accueillant","courant","好客的"]],"fq":"中频，描述餐厅、聚会时常用。","me":"con- + vivre：大家「一起生活」的气氛。","tr":{"zh":"我们喜欢这家温馨的小咖啡馆。","fr":"Nous aimons ce petit café convivial.","alt":"On adore ce petit café, l'ambiance est sympa.","note":"café 阳性 → convivial。"}},
 "Sanitaire": {"pos":"adj. 形容词，阴阳同形；复数 sanitaires；les sanitaires (n.m.pl.) = 卫生间设施","s":"卫生的，公共卫生的，与健康有关的：la crise sanitaire = 公共卫生危机。les sanitaires = 厕所浴室设施。","ipa":"[sa.ni.tɛʁ]","ph":"sa [sa]；ni [ni]；-aire 读 [ɛʁ]，r 要发。","pi":"-aire 读 [ɛʁ]，r 要读出来；这里不是「干净」，而是「卫生、健康」。","et":"拉丁语 sanitas（健康），来自 sanus（健康的）。同族：santé, sain, assainir。","ex":[["La situation sanitaire s'améliore.","卫生状况正在改善。"],["Le pays traverse une crise sanitaire.","这个国家正经历公共卫生危机。"],["Les sanitaires du camping sont propres.","露营地的卫生间很干净。"]],"co":[["la situation sanitaire","卫生状况"],["la crise sanitaire","公共卫生危机"],["un pass sanitaire","健康通行证"],["les installations sanitaires","卫生设施"]],"sy":[["hygiénique","courant","讲卫生的"],["médical","courant","医疗的"],["de santé","courant","「健康的」，更日常"]],"fq":"中频，新闻和公告里常见。","me":"sanitaire ← santé：与「健康」有关。","tr":{"zh":"医院采取了严格的卫生措施。","fr":"L'hôpital a pris des mesures sanitaires strictes.","alt":"L'hôpital applique des règles d'hygiène très strictes.","note":"mesures 阴性复数；sanitaires 复数加 s。"}},
 "Flexible": {"pos":"adj. 形容词，阴阳同形；复数 flexibles","s":"灵活的：时间、规定、态度都可以。des horaires flexibles = 弹性工作时间；une personne flexible = 通融、随和的人。也可指物体可弯曲。","ipa":"[flɛk.sibl]","ph":"fle [flɛ]；x 读 [ks]；i [i]；-ble 读 [bl]。","pi":"x 读 [ks]；结尾 -ible 的 e 不发音。","et":"拉丁语 flexibilis，来自 flectere（弯曲）。同族：flexibilité, réfléchir（本义「折回」）。","ex":[["Mes horaires sont flexibles.","我的时间很灵活。"],["Mon patron est flexible.","我的老板很通融。"],["Je suis flexible sur la date.","日期我都可以。"]],"co":[["des horaires flexibles","弹性时间"],["flexible sur la date","日期方面可协调"],["un travail flexible","弹性的工作"],["une attitude flexible","灵活的态度"]],"sy":[["souple","courant","柔软、灵活的"],["adaptable","courant","能适应的"],["rigide","courant","反义：僵硬的"]],"fq":"中高频，工作场合常见。","me":"flex（弯）+ -ible：可以「弯」就是灵活。","tr":{"zh":"下周我的时间比较灵活。","fr":"Je suis flexible sur les horaires la semaine prochaine.","alt":"La semaine prochaine, mon emploi du temps est souple.","note":"flexible sur + 名词；souple 是近义词。"}},
 "Ponctuel / Ponctuelle": {"pos":"adj. 形容词，阴性 ponctuelle；复数 ponctuels / ponctuelles","s":"①准时的（人）：Il est ponctuel；②零星的，偶尔的，一次性的：une action ponctuelle = 单次行动；une aide ponctuelle = 临时帮助。","ipa":"[pɔ̃k.tɥɛl]","ph":"pon 读 [pɔ̃]；c 读 [k]；tuel 读 [tɥɛl]（u 变短半元音）。","pi":"c 要发 [k]；-uel 读 [ɥɛl]；阴性 ponctuelle 同音。","et":"来自 point（点），经拉丁语 punctum。同族：ponctuation, ponctuer, ponctualité。","ex":[["Je fais une action ponctuelle chaque mois.","我每月做一次单次行动。"],["Elle est toujours ponctuelle.","她总是很准时。"],["Je vous demande une aide ponctuelle.","我只请您临时帮一次忙。"]],"co":[["être ponctuel","守时"],["une action ponctuelle","单次行动"],["une aide ponctuelle","临时帮助"],["à titre ponctuel","偶尔、临时地"]],"sy":[["exact","courant","守时的"],["occasionnel","courant","偶尔的"],["régulier","courant","反义：定期的"]],"fq":"中频，工作中常见。","me":"ponctuel ← point：准时 = 恰好落在那个「点」上。","tr":{"zh":"请准时到，会议九点开始。","fr":"Soyez ponctuels, la réunion commence à neuf heures.","alt":"Ne soyez pas en retard, la réunion commence à neuf heures.","note":"soyez ponctuels 复数，配合 vous。"}},
 "Déçu(e)": {"pos":"adj. 形容词（décevoir 的过去分词），阴性 déçue；复数 déçus / déçues","s":"失望的。être déçu par / de qqch = 对……失望；être déçu que + 虚拟式。décevoir qqn = 让某人失望。","ipa":"[de.sy]","ph":"dé [de]；ç 读 [s]；u 读 [y]；阴性 déçue 同音。","pi":"ç 读 [s]，不是 [k]；与英语 deceive（欺骗）是假朋友，déçu 是失望。","et":"décevoir（拉丁语 decipere，欺骗、使落空）的过去分词。同族：déception, décevant。","ex":[["Je suis très déçu par ce film.","这部电影让我很失望。"],["Je suis déçu de ne pas avoir gagné.","没赢，我很失望。"],["Elle était déçue que tu ne viennes pas.","你没来，她很失望。"]],"co":[["déçu par / de quelque chose","对某事失望"],["être déçu que + 虚拟式","对……感到失望"],["décevoir quelqu'un","让某人失望"],["une déception","失望（名词）"]],"sy":[["désappointé","soutenu","失望、沮丧的"],["frustré","courant","受挫的"],["content","courant","反义：满意的"]],"fq":"高频，日常常用。","me":"déçu：de- + çu，ç 软音，发 [s]。","tr":{"zh":"我对考试成绩很失望。","fr":"Je suis déçu de mes résultats.","alt":"Mes résultats m'ont vraiment déçu.","note":"déçu de / par + 名词；女性说话者写 déçue。"}},
 "Dommage": {"pos":"n.m. 阳性名词（用于 c'est dommage）；复数 dommages = 损害，损失","s":"可惜，遗憾。C'est dommage ! / Dommage ! =「真可惜！」。C'est dommage de + 不定式 / que + 虚拟式。另一义：dommage (n.m.) = 损害；dommages et intérêts = 赔偿金。","ipa":"[dɔ.maʒ]","ph":"o 开口 [ɔ]；mm 读一个 [m]；age 读 [aʒ]，e 不发。","pi":"拼写有 mm，读音只有一个 [m]；c'est dommage 中永远不变形。","et":"古法语 damage，来自拉丁语 damnum（损失）。同族：endommager, dommageable。","ex":[["C'est vraiment dommage !","真可惜！"],["C'est dommage que tu ne puisses pas venir.","你不能来，真可惜。"],["Dommage, il pleut.","可惜，下雨了。"]],"co":[["C'est dommage !","真可惜！"],["dommage que + 虚拟式","可惜……"],["Quel dommage !","多可惜啊！"],["dommages et intérêts","损害赔偿"]],"sy":[["regrettable","soutenu","令人遗憾的"],["malheureux","courant","不幸的、可惜的"],["tant pis","courant","「算了」，没办法"]],"fq":"极高频，日常口语常用。","me":"dommage 里有两个 m，可惜的是「伤到了」。","tr":{"zh":"可惜你不能来。","fr":"C'est dommage que tu ne puisses pas venir.","alt":"Dommage que tu ne viennes pas.","note":"dommage que + 虚拟式。"}},
 "Féministe": {"pos":"adj. 形容词，阴阳同形；复数 féministes；也作名词 un/une féministe","s":"女权主义的，主张男女平等的：le mouvement féministe。名词：une féministe = 女权主义者。","ipa":"[fe.mi.nist]","ph":"fé [fe]；mi [mi]；nis 读 [nis]；s、t 都发音；词尾 e 不发。","pi":"-iste 的 s 和 t 都要发；阴阳同形：un homme féministe, une femme féministe。","et":"féminin（拉丁语 femina，女人）+ -iste。同族：féminisme, féminité, femme。","ex":[["Elle a des convictions féministes.","她有女权主义信念。"],["C'est une écrivaine féministe.","她是一位女权主义作家。"],["Il se dit féministe.","他自称是女权主义者。"]],"co":[["un mouvement féministe","女权运动"],["une militante féministe","女权活动人士"],["des idées féministes","女权主义思想"],["se dire féministe","自称女权主义者"]],"sy":[["égalitaire","courant","主张平等的"],["militant","courant","积极分子"],["machiste","courant","反义：大男子主义的"]],"fq":"中频，社会话题里常见。","me":"féminin + -iste：站在「女性」一边的主张。","tr":{"zh":"我的姐姐是女权主义者。","fr":"Ma sœur est féministe.","alt":"Ma sœur se bat pour l'égalité des femmes et des hommes.","note":"féministe 阴阳同形。"}},
 "Pour autant": {"pos":"loc. adv. 副词短语，不变","s":"尽管如此，并不因此（就）。多用于否定句或让步句：Il est riche, mais il n'est pas heureux pour autant。pour autant que + 虚拟式 =「就……而言」。","ipa":"[pu.ʁo.tɑ̃]","ph":"pour 的 r 要发，并和 autant 连成 [ʁo]；au 读 [o]；ant 读 [ɑ̃]，t 不发。","pi":"pour 的 r 不能丢；au 读 [o]；常与 ne… pas 连用。","et":"由 pour + autant（同样多）组成，字面「为了这么多」；是固定搭配。","ex":[["Il est riche, mais il n'est pas heureux pour autant.","他很有钱，但并不因此就幸福。"],["Ce n'est pas facile, mais je n'abandonne pas pour autant.","这不容易，但我也不因此放弃。"],["Pour autant que je sache, il est parti.","据我所知，他走了。"]],"co":[["pas pour autant","并不因此"],["sans pour autant + 不定式","却并没有……"],["pour autant que + 虚拟式","就……而言"],["mais pas pour autant","但并不意味着"]],"sy":[["néanmoins","soutenu","然而、尽管如此"],["cependant","courant","然而"],["pourtant","courant","可是、然而"]],"fq":"中高频，书面和谈话中常见。","me":"pour autant：「就为了这个」？不——不因此。","tr":{"zh":"他很聪明，但这并不意味着他总是对。","fr":"Il est intelligent, mais il n'a pas toujours raison pour autant.","alt":"Il est intelligent, mais ça ne veut pas dire qu'il a toujours raison.","note":"pour autant 常与 ne… pas 连用，放句尾。"}},
 "Cordialement (à la fin d'une lettre ou d'un email)": {"pos":"adv. 副词（信末套语），不变","s":"此致敬礼；顺颂时祺。书信和邮件结尾的客气用语，正式但不拘谨，介于 Bien à vous 与 Amicalement 之间。cordial = 热情友好的。","ipa":"[kɔʁ.djal.mɑ̃]","ph":"cor 读 [kɔʁ]；dia 的 i 变半元音 [dja]；le 的 e 不发；ment 读 [mɑ̃]。","pi":"-ment 读鼻化 [mɑ̃]，n 不发；邮件结尾写 Cordialement, 后面接逗号再签名。","et":"cordial（拉丁语 cor, cordis，心）+ -ment，字面「衷心地」。同族：cœur, courage。","ex":[["Cordialement, Nicolas.","此致敬礼，尼古拉。"],["Merci d'avance. Cordialement, Julie.","先谢谢您。此致敬礼，朱莉。"],["Bien cordialement, Marie Dupont.","诚挚问候，玛丽·迪邦。"]],"co":[["Bien cordialement","诚挚问候"],["Très cordialement","非常诚挚的问候"],["Cordialement vôtre","您忠实的（正式）"],["Cordialement, + 姓名","邮件结尾格式"]],"sy":[["Bien à vous","courant","祝好，略随意"],["Amicalement","courant","对熟人：友好地"],["Veuillez agréer mes salutations distinguées","soutenu","最正式的结尾"]],"fq":"极高频，工作邮件结尾必备。","me":"cor = 心：Cordialement = 「用心」问候。","tr":{"zh":"谢谢你的帮助，此致敬礼。","fr":"Merci pour votre aide. Cordialement, Paul.","alt":"Merci pour votre aide. Bien cordialement, Paul.","note":"Cordialement 之后加逗号和姓名。"}},
 "Évidemment": {"pos":"adv. 副词，不变；形容词是 évident","s":"当然，显然，不用说。用于肯定回答：—Tu viens ? —Évidemment ! 也表示「很明显」，常用于强调。","ipa":"[e.vi.da.mɑ̃]","ph":"é [e]；vi [vi]；de 读 [da]；-emment 读 [amɑ̃]。","pi":"-emment 读 [amɑ̃]，不读 [ɛmɑ̃]；拼写是 -emment。","et":"évident（拉丁语 evidens，显然的，e- + videre 看）+ -ment。同族：évidence, voir。","ex":[["Évidemment, je serai là !","当然，我会在！"],["Évidemment, tu as raison.","当然，你是对的。"],["— Tu es sûr ? — Évidemment !","——你确定吗？——当然！"]],"co":[["Évidemment !","当然！"],["évidemment pas","当然不"],["évidemment que oui / non","当然是 / 当然不是"],["Évidemment, mais…","当然，不过……"]],"sy":[["bien sûr","courant","当然，最通用"],["naturellement","courant","自然地、当然"],["forcément","courant","必然地"]],"fq":"极高频，日常口语常用。","me":"évident + -ment：「一目了然」，所以是「当然」。","tr":{"zh":"当然，我会帮你。","fr":"Évidemment, je vais t'aider.","alt":"Bien sûr que je vais t'aider.","note":"Évidemment 放句首，后加逗号。"}},
 "Uniquement": {"pos":"adv. 副词，不变","s":"仅仅，只，唯独：uniquement en ligne。比 seulement 更强调「排他」，语气稍正式。形容词是 unique。","ipa":"[y.nik.mɑ̃]","ph":"u 读 [y]；ni [ni]；que 读 [k]；ment 读 [mɑ̃]。","pi":"开头 u 读 [y]，嘴唇要圆；-ment 读 [mɑ̃]，不读 [mɛnt]。","et":"unique（拉丁语 unicus，来自 unus，一）+ -ment。同族：un, unité, union。","ex":[["Ce produit est vendu uniquement en ligne.","这个产品只在网上销售。"],["Il mange uniquement des légumes.","他只吃蔬菜。"],["Je suis là uniquement pour t'aider.","我来这里只是为了帮你。"]],"co":[["uniquement pour + 不定式","只是为了……"],["uniquement sur rendez-vous","仅限预约"],["uniquement en ligne","仅限线上"],["pas uniquement…","不只是……"]],"sy":[["seulement","courant","只，最通用"],["exclusivement","soutenu","专门地、排他地"],["simplement","courant","只是、简单地"]],"fq":"高频，日常和书面都常用。","me":"unique + -ment：「唯一地」。","tr":{"zh":"这家店只收现金。","fr":"Ce magasin accepte uniquement les espèces.","alt":"Ici, on prend seulement du liquide.","note":"uniquement 放在动词后；espèces 常用复数表示现金。"}},
 "Récemment": {"pos":"adv. 副词，不变","s":"最近，不久前。多与过去时（passé composé）连用：Je l'ai vu récemment。「近来」可说 ces derniers temps。","ipa":"[ʁe.sa.mɑ̃]","ph":"ré [ʁe]；c 在 e 前读 [s]；-emment 读 [amɑ̃]。","pi":"-emment 读 [amɑ̃]；拼写是 -emment（不是 -amment）；c 读 [s]。","et":"récent（拉丁语 recens，新近的）+ -emment。同族：récent。","ex":[["Je l'ai vu très récemment.","我最近刚见过他。"],["Récemment, j'ai changé de travail.","最近我换了工作。"],["Ils ont déménagé tout récemment.","他们刚刚搬了家。"]],"co":[["tout récemment","就在最近"],["très récemment","非常近期"],["jusqu'à récemment","直到不久前"],["récemment encore","直到最近还……"]],"sy":[["dernièrement","courant","最近、近来"],["il y a peu","courant","不久前"],["autrefois","courant","反义：从前"]],"fq":"高频，日常常用。","me":"récent → récemment：记住 emment。","tr":{"zh":"我最近搬家了。","fr":"J'ai déménagé récemment.","alt":"J'ai déménagé il n'y a pas longtemps.","note":"récemment 常放在过去时之后。"}},
 "Désormais": {"pos":"adv. 副词（不变）","s":"从今以后；今后。指从现在开始一直如此，多放在句首，后面常接将来时或现在时。比 maintenant（现在）更强调「以后都这样」。","ipa":"[de.zɔʁ.mɛ]","ph":"dé [de]；s 在 o 和 r 之间读 [z]；-ais 读 [ɛ]，结尾 s 不发音。","pi":"中间 s 读 [z]，不是 [s]；结尾的 -s 不发音。","et":"古法语 des ore mais：dès（自从）+ ore（现在）+ mais（往后）。","ex":[["Désormais, je ferai plus attention.","从现在起，我会更加注意。"],["Désormais, on se retrouve ici chaque lundi.","从今以后，我们每周一在这里碰头。"]],"co":[["désormais + 将来时","从今以后会……"],["à partir de maintenant","从现在开始"],["dès lors / dorénavant","自此；从今往后"]],"sy":[["dorénavant","soutenu","同义，更正式"],["à partir de maintenant","courant","日常说法"],["maintenant","courant","只说「现在」，不含「以后」"]],"fq":"中高频，书面和口语都用。","me":"dès + or + mais：「自此往后」。","tr":{"zh":"从今以后，我每天早上跑步。","fr":"Désormais, je cours tous les matins.","alt":"À partir de maintenant, je vais courir tous les matins.","note":"désormais 放句首，后面加逗号。"}},
 "Gratuitement": {"pos":"adv. 副词（由形容词 gratuit 加 -ment 构成）","s":"免费地；无偿地。可以修饰动词：entrer gratuitement（免费进入）、travailler gratuitement（义务工作）。形容词是 gratuit / gratuite。","ipa":"[gʁa.tɥit.mɑ̃]","ph":"u 与 i 连读成 [ɥi]；-ment 读鼻化音 [mɑ̃]，t 要发 [t]。","pi":"gratuit 的 t 发音；副词结尾 -ment 的 e 不发，t 不发，读 [mɑ̃]。","et":"gratuit（拉丁语 gratuitus，白给的）+ -ment。","ex":[["Il m'a aidé gratuitement.","他免费帮了我。"],["Le musée est ouvert gratuitement le dimanche.","博物馆星期天免费开放。"]],"co":[["entrer gratuitement","免费入场"],["travailler gratuitement","无偿工作"],["télécharger gratuitement","免费下载"]],"sy":[["gratis","familier","免费（口语）"],["sans payer","courant","不用付钱"],["bénévolement","courant","义务地，做志愿者"]],"fq":"中频，日常常用。","me":"gratuit（免费的）+ -ment：免费地。","tr":{"zh":"孩子们可以免费参观这座博物馆。","fr":"Les enfants peuvent visiter ce musée gratuitement.","alt":"Pour les enfants, la visite du musée est gratuite.","note":"gratuit 修饰名词，gratuitement 修饰动词。"}},
 "Absolument": {"pos":"adv. 副词（由 absolu 加 -ment 构成）","s":"绝对地；完全地。加强语气：absolument faux（完全错误）。单独回答 Absolument ! = 「当然！完全对！」。否定句里 absolument pas = 「绝对不」。","ipa":"[ap.sɔ.ly.mɑ̃]","ph":"b 在 s 前变清音 [p]；u 读 [y]；-ment 读 [mɑ̃]。","pi":"ab- 读 [ap]，不是 [ab]；u 是 [y]，嘴唇要圆。","et":"absolu（拉丁语 absolutus，解脱的、完全的）+ -ment。","ex":[["Je suis absolument certain de cela.","我对此绝对肯定。"],["Tu viens ? — Absolument !","你来吗？——当然！"]],"co":[["absolument pas","绝对不"],["absolument tout","一切；全部"],["il faut absolument...","一定要……"]],"sy":[["complètement","courant","完全"],["tout à fait","courant","完全（同意时常用）"],["carrément","familier","干脆；相当（口语）"]],"fq":"高频，口语和书面都常用。","me":"absolu + -ment：「绝对」的副词。","tr":{"zh":"你一定要试试这道菜！","fr":"Tu dois absolument goûter ce plat !","alt":"Il faut absolument que tu goûtes ce plat !","note":"devoir / il faut absolument = 一定要。"}},
 "Davantage": {"pos":"adv. 副词（不变）","s":"更多；更加。单独用，放在动词后：travailler davantage（更努力工作）。接名词要加 de：davantage de temps（更多时间）；接 que 表比较：davantage que moi。不修饰形容词，修饰形容词用 plus。","ipa":"[da.vɑ̃.taʒ]","ph":"an 读鼻化音 [ɑ̃]；-age 读 [aʒ]，g 读 [ʒ]，结尾 e 不发。","pi":"不能说 davantage grand，要说 plus grand；结尾 -age 读 [aʒ]。","et":"d'avantage 连写而成：de + avantage（优势、好处）。","ex":[["Il faut travailler davantage.","必须更加努力。"],["Je voudrais davantage de temps.","我想要更多时间。"]],"co":[["davantage de + 名词","更多的……"],["davantage que","比……更多"],["bien davantage","多得多"]],"sy":[["plus","courant","更多，最常用"],["encore plus","courant","还要更多"],["plus de","courant","更多的（接名词）"]],"fq":"中频，偏书面但口语也听得到。","me":"d'avantage：多一点「优势」，就是「更多」。","tr":{"zh":"我想多睡一会儿。","fr":"J'aimerais dormir davantage.","alt":"J'aimerais dormir un peu plus.","note":"davantage 放在动词后面。"}},
 "Finalement": {"pos":"adv. 副词（由 final 加 -ment 构成）","s":"最后；终于；结果。讲事情经过的最后结局，常暗含「和原来想的不一样」：Finalement, on est restés（结果我们没出去）。","ipa":"[fi.nal.mɑ̃]","ph":"i [i]；a [a]；l 要发；-ment 读 [mɑ̃]。","pi":"和 enfin 不同：enfin 是「终于、总算」，finalement 常是「结果、到头来」。","et":"final（拉丁语 finalis）+ -ment，同源：fin（结尾）。","ex":[["Finalement, nous sommes restés à la maison.","最后我们待在了家里。"],["Finalement, il a accepté.","最后他同意了。"]],"co":[["et finalement","最后；最终"],["finalement, ...","结果……"],["tout est bien qui finit bien","结果好就一切都好"]],"sy":[["enfin","courant","终于；总算"],["au final","familier","说到底"],["en fin de compte","courant","归根结底"]],"fq":"高频，日常常用。","me":"fin（结尾）→ finalement：「在结尾处」。","tr":{"zh":"最后他还是没来。","fr":"Finalement, il n'est pas venu.","alt":"En fin de compte, il n'est pas venu.","note":"venir 的复合过去时用 être：il est venu。"}},
 "Réellement": {"pos":"adv. 副词（由 réel 加 -ment 构成）","s":"真正地；确实地。强调事情是真的、不是表面或想象。Est-ce réellement possible ?（这真的可能吗？）。比 vraiment 稍正式。","ipa":"[ʁe.ɛl.mɑ̃]","ph":"ré [ʁe]；ee 分开读成 [e.ɛ]；ll 只读一个 [l]；-ment 读 [mɑ̃]。","pi":"réel 的 ee 要读成两个音节 [e.ɛl]，不要连成一个音。","et":"réel（拉丁语 realis，源自 res「事物」）+ -ment。","ex":[["Est-ce réellement nécessaire ?","这真的有必要吗？"],["Il a réellement changé.","他真的变了。"]],"co":[["réellement important","真的很重要"],["ce qui s'est réellement passé","事情真正的经过"],["pas réellement","并不真的"]],"sy":[["vraiment","courant","真的（最常用）"],["en réalité","courant","实际上"],["véritablement","soutenu","确实地，较书面"]],"fq":"中频，日常和书面都用。","me":"réel（现实）+ -ment：「现实中」的真。","tr":{"zh":"你真的想搬家吗？","fr":"Tu veux réellement déménager ?","alt":"Tu veux vraiment déménager ?","note":"副词放在动词之后，如 veux réellement。"}},
 "Tout à fait": {"pos":"loc. adv. 副词短语（不变）","s":"完全；十分。回答时说 Tout à fait ! = 「完全对！」，表示十分同意。也加强形容词：tout à fait normal（完全正常）。","ipa":"[tu.ta.fɛ]","ph":"tout 的 t 与 à 连读 [t]；fait 读 [fɛ]，结尾 t 不发。","pi":"fait 的 -ait 读 [ɛ]，结尾 t 不发；tout 与 à 要连读，说成 [tu.ta]。","et":"tout（拉丁语 totus，全部）+ à fait；fait 是 faire 的过去分词，原意「做完」，引申为「完全」。","ex":[["Je suis tout à fait d'accord avec vous.","我完全同意您。"],["Ce n'est pas tout à fait ça.","不完全是这样。"]],"co":[["tout à fait d'accord","完全同意"],["pas tout à fait","不完全；不太"],["Tout à fait !","完全对！"]],"sy":[["absolument","courant","绝对；完全"],["entièrement","courant","整个地"],["exactement","courant","正是；对"]],"fq":"高频，口语中常用来表示同意。","me":"tout + à fait：「全部做完」，所以是「完全」。","tr":{"zh":"您说得完全对。","fr":"Vous avez tout à fait raison.","alt":"Vous avez absolument raison.","note":"avoir raison = 有道理，不加冠词。"}},
 "Alors que": {"pos":"loc. conj. 连词短语","s":"而；然而；当……的时候。最常用来对比两件事：Il rit, alors que je pleure（他在笑，而我在哭）。也可表示「明明……却……」，带有责备的意味。","ipa":"[a.lɔʁ.kə]","ph":"alors 的 s 不发；o 读开口 [ɔ]；que 读 [kə]，说话时 e 常弱化。","pi":"alors 末尾 s 不发音；que 遇到元音要省音：alors qu'il。","et":"alors（à + lors，源自拉丁语 illa hora「那时」）+ que。","ex":[["Il fait froid ici, alors qu'il fait chaud dehors.","这里冷，而外面热。"],["Elle est sortie alors qu'il pleuvait.","下着雨她却出门了。"]],"co":[["alors que + 直陈式","而；然而"],["alors qu'il...","而他……（que 省音）"],["alors même que","即使……"]],"sy":[["tandis que","soutenu","而；同时（更书面）"],["pendant que","courant","当……的时候（只表时间）"],["bien que","courant","尽管（后接虚拟式，不同）"]],"fq":"高频，日常和书面都用。","me":"alors（那时）+ que：「那时……而」，两件事摆在一起对比。","tr":{"zh":"他在工作，而我在睡觉。","fr":"Il travaille, alors que je dors.","alt":"Lui, il travaille, alors que moi, je dors.","note":"alors que 后面用直陈式，不用虚拟式。"}},
 "Lorsque": {"pos":"conj. 连词","s":"当……的时候。和 quand 意思相同，但更书面、更正式。遇到元音开头的词要省音：lorsqu'il、lorsqu'elle、lorsqu'on。","ipa":"[lɔʁsk]","ph":"lors [lɔʁ]；s 在这里读 [s]；que 的 e 弱读，省音时写成 lorsqu'。","pi":"遇元音要写 lorsqu'il，不能写 lorsque il。","et":"lors（拉丁语 illa hora「那一时刻」）+ que。","ex":[["Lorsque je suis arrivé, il pleuvait.","我到的时候在下雨。"],["Lorsqu'on est fatigué, on dort mieux.","累的时候睡得更好。"]],"co":[["lorsque + 直陈式","当……时"],["lorsqu'il / lorsqu'elle","省音形式"],["dès lors que","既然；从……起"]],"sy":[["quand","courant","当……时（日常最常用）"],["au moment où","courant","在……的时候"],["alors que","courant","而；当……时（对比）"]],"fq":"中频，偏书面。","me":"lors（那时）+ que：「在那时候」，是 quand 的正式版。","tr":{"zh":"我回家的时候，他已经睡了。","fr":"Lorsque je suis rentré, il dormait déjà.","alt":"Quand je suis rentré, il dormait déjà.","note":"主句用未完成过去时 dormait 表示当时的状态。"}},
 "Puisque ...": {"pos":"conj. 连词","s":"既然；因为（对方已经知道的原因）。表示一个大家都清楚的事实：Puisque tu es là, aide-moi。和 parce que 不同，puisque 引出的理由是已知的。遇元音省音：puisqu'il。","ipa":"[pɥisk]","ph":"pui 读 [pɥi]；s 读 [s]；que 的 e 弱读，结尾不发音。","pi":"遇元音要写 puisqu'il / puisqu'elle / puisqu'on。","et":"puis（拉丁语 post「之后」）+ que。","ex":[["Puisque tu es là, aide-moi !","既然你在，就来帮我！"],["Puisqu'il pleut, restons ici.","既然下雨，我们就待在这儿吧。"]],"co":[["puisque + 直陈式","既然……"],["puisqu'il...","既然他……"],["puisque c'est comme ça","既然这样"]],"sy":[["parce que","courant","因为（新信息）"],["comme","courant","由于（放句首）"],["étant donné que","soutenu","鉴于"]],"fq":"高频，口语和书面都常用。","me":"puis + que：「既然已经这样了，那么……」。","tr":{"zh":"既然你累了，我们回家吧。","fr":"Puisque tu es fatigué, rentrons à la maison.","alt":"Comme tu es fatigué, on rentre.","note":"puisque 引出已知的理由，后接直陈式。"}},
 "Durant": {"pos":"prép. 介词","s":"在……期间。后面接表示时间的名词：durant l'été（夏天期间）、durant la nuit（整夜）。和 pendant 意思接近，但更书面。","ipa":"[dy.ʁɑ̃]","ph":"du 读 [dy]（嘴唇要圆）；r [ʁ]；-ant 读鼻化音 [ɑ̃]，t 不发。","pi":"结尾 -ant 读 [ɑ̃]，t 不发；u 读 [y]，不是 [u]。","et":"durer（拉丁语 durare，持续）的现在分词。","ex":[["Il a plu durant toute la nuit.","整晚都在下雨。"],["Durant mes études, j'ai beaucoup voyagé.","上学期间，我常去旅行。"]],"co":[["durant + 时间名词","在……期间"],["durant toute la journée","一整天"],["durant des années","许多年间"]],"sy":[["pendant","courant","在……期间（最常用）"],["au cours de","soutenu","在……过程中"]],"fq":"中频，偏书面。","me":"durer（持续）→ durant：「持续的这段时间」。","tr":{"zh":"整个假期他都在读书。","fr":"Il a lu durant toutes les vacances.","alt":"Il a lu pendant toutes les vacances.","note":"durant / pendant 后面直接接名词，不接动词。"}},
 "Poser un problème": {"pos":"loc. verbale 动词短语（poser 为第一组动词，助动词 avoir）","s":"造成问题；带来麻烦。主语通常是事物：Ça pose un problème（这是个问题）。后面常加 à quelqu'un：Cela me pose un problème。不要和 poser une question（提问）混淆。","ipa":"[po.ze.œ̃.pʁɔ.blɛm]","ph":"poser 的 s 读 [z]；un 与 problème 之间连着读；problème 结尾 -ème 读 [ɛm]。","pi":"poser 中 s 读 [z]；problème 是阳性名词：un problème。","et":"poser（拉丁语 pausare「放下」）+ problème（希腊语 problēma「摆在前面的东西」）。","ex":[["Cela ne devrait pas poser un problème.","这应该不会有问题。"],["Ce retard nous pose un gros problème.","这次迟到给我们带来大麻烦。"]],"co":[["poser un problème à quelqu'un","给某人带来问题"],["ça ne pose pas de problème","没问题"],["poser une question","提问"]],"sy":[["causer des ennuis","courant","带来麻烦"],["être un problème","courant","是个问题"],["gêner","courant","妨碍；不方便"]],"fq":"中高频，日常常用。","me":"poser = 把问题「摆」到桌上，别人就得处理。","tr":{"zh":"这个时间对我来说不成问题。","fr":"Cet horaire ne me pose pas de problème.","alt":"Cet horaire me convient très bien.","note":"否定句里用 pas de problème，un 变成 de。"}},
 "C'est parti !": {"pos":"loc. interj. 感叹短语","s":"开始吧！出发！出发信号：事情要开始了，或者已经启动。字面是「已经出发了」，用 partir 的过去分词。口语很常用。","ipa":"[sɛ.paʁ.ti]","ph":"c'est 读 [sɛ]，t 不发；parti 读 [paʁ.ti]；r 为小舌音 [ʁ]。","pi":"c'est 的 st 不发音；parti 结尾 i 要清楚读出。","et":"parti 是 partir（出发）的过去分词；partir 来自拉丁语 partire（分开）。","ex":[["Tout est prêt, c'est parti !","一切就绪，出发！"],["On commence ? Allez, c'est parti !","开始吗？来，开始吧！"]],"co":[["c'est parti pour...","要开始……了"],["c'est parti mon kiki","开始啦（口语玩笑）"],["et c'est parti !","好，开始！"]],"sy":[["allons-y","courant","走吧；我们开始"],["on y va","courant","我们走"],["go","familier","走（借自英语）"]],"fq":"高频，口语常用。","me":"parti = 已出发：一声令下，大家都「走了」。","tr":{"zh":"大家都到了，开始吧！","fr":"Tout le monde est là, c'est parti !","alt":"Tout le monde est là, allez, on y va !","note":"c'est parti 是固定说法，不随人称变化。"}},
 "Peser sur le moral": {"pos":"loc. verbale 动词短语（peser 第一组，助动词 avoir）","s":"影响情绪；让人情绪低落。主语是让人烦闷的事：le froid、le travail、la solitude。le moral 指心情、士气。后面可加 de + 人：peser sur le moral de quelqu'un。","ipa":"[pə.ze.syʁ.lə.mɔ.ʁal]","ph":"peser 中 e 读 [ə]，s 读 [z]；moral 的 -al 读 [al]，l 要发音。","pi":"moral 的 l 要发；peser 的 s 读 [z]；le moral 为阳性。","et":"peser（拉丁语 pensare，称重）+ moral（拉丁语 moralis）。","ex":[["Ce mauvais temps commence à peser sur le moral.","这种坏天气开始让人情绪低落。"],["La solitude pèse sur son moral.","孤独让他情绪低落。"]],"co":[["peser sur le moral de quelqu'un","压在某人心上，使其情绪低落"],["avoir le moral","情绪好；有精神"],["remonter le moral","鼓舞士气，让人振作"]],"sy":[["déprimer","courant","使人沮丧"],["miner le moral","courant","消磨士气"],["abattre","soutenu","使消沉"]],"fq":"中频，日常常用。","me":"peser（称重）+ moral：心情上压了「重量」。","tr":{"zh":"这份工作让我心情很沉重。","fr":"Ce travail pèse sur mon moral.","alt":"Ce travail me mine le moral.","note":"peser 变位：il pèse（e 变 è）。"}},
 "Passer un coup de fil": {"pos":"loc. verbale 动词短语（passer 第一组，助动词 avoir）","s":"打个电话。口语说法，比 téléphoner 随意。coup de fil 里的 fil 原指电话线。常说 passer un coup de fil à quelqu'un 或 donner un coup de fil。","ipa":"[pa.se.œ̃.ku.də.fil]","ph":"coup 的 p 不发 [ku]；fil 的 l 要发音 [fil]；un 读鼻化音 [œ̃]。","pi":"coup 结尾 p 不发；fil 结尾 l 要发。","et":"passer（拉丁语 passus「步」）；fil 来自拉丁语 filum（线），指电话线。","ex":[["Je dois passer un coup de fil à ma mère.","我得给我妈妈打个电话。"],["Passe-moi un coup de fil ce soir.","今晚给我打个电话。"]],"co":[["passer un coup de fil à quelqu'un","给某人打电话"],["donner un coup de fil","打个电话"],["recevoir un coup de fil","接到电话"]],"sy":[["téléphoner","courant","打电话（通用）"],["appeler","courant","呼叫；打电话"],["passer un coup de téléphone","courant","同义，稍完整"]],"fq":"高频，口语常用。","me":"fil = 电话线：「在线上拉一下」就是打电话。","tr":{"zh":"我待会儿给你打个电话。","fr":"Je te passe un coup de fil tout à l'heure.","alt":"Je t'appelle tout à l'heure.","note":"人称代词 te 放在 passe 前面。"}},
 "Avoir tendance à": {"pos":"loc. verbale 动词短语（avoir）","s":"倾向于；常常会。后面接动词原形：avoir tendance à oublier（容易忘）。说的是习惯或倾向，常含一点负面的意思。","ipa":"[a.vwaʁ.tɑ̃.dɑ̃s.a]","ph":"avoir 读 [a.vwaʁ]；tendance 的 en 和 an 都是鼻化音 [ɑ̃]；ce 读 [s]。","pi":"后面的介词是 à，不是 de；tendance 中 ten- 读 [tɑ̃]，不是 [tɛ̃]。","et":"tendance 由 tendre（拉丁语 tendere「伸向」）+ -ance 构成。","ex":[["Il a tendance à oublier ses clés.","他常常忘带钥匙。"],["J'ai tendance à trop parler quand je suis stressé.","我一紧张就容易话多。"]],"co":[["avoir tendance à + 原形","倾向于做……"],["une tendance à la hausse","上涨趋势"],["tendance à la baisse","下降趋势"]],"sy":[["avoir l'habitude de","courant","习惯于"],["être enclin à","soutenu","倾向于"],["souvent","courant","常常"]],"fq":"高频，口语和书面都常用。","me":"tendre（伸向）：心往那边「伸」，就是倾向。","tr":{"zh":"我睡前容易吃太多。","fr":"J'ai tendance à trop manger avant de dormir.","alt":"Je mange souvent trop avant de dormir.","note":"avoir tendance à + 动词原形。"}},
 "Quand même !": {"pos":"loc. adv. / 感叹语","s":"真是的！到底还是……表示不满、惊讶或「毕竟还是」。放句尾带情绪：Tu pourrais dire merci, quand même !（你好歹说声谢谢啊！）。也表示「尽管如此还是」：J'y vais quand même。","ipa":"[kɑ̃.mɛm]","ph":"quand 的 d 不发，读 [kɑ̃]；même 读 [mɛm]，结尾 e 不发。","pi":"quand 结尾 d 不发音；même 中 ê 读 [ɛ]。","et":"quand（拉丁语 quando「何时」）+ même（拉丁语 metipsimus 的演变，「同样的」）。","ex":[["Tu pourrais dire merci, quand même !","你至少可以说声谢谢！"],["Il pleut, mais j'y vais quand même.","下雨，但我还是要去。"]],"co":[["merci quand même","还是谢谢你"],["j'y vais quand même","我还是去"],["quand même !","真是的！太过分了！"]],"sy":[["tout de même","courant","同义，稍正式"],["pourtant","courant","然而"],["malgré tout","courant","尽管如此"]],"fq":"极高频，口语中常用。","me":"quand même = 「就算如此，还是……」，语气里有点不服。","tr":{"zh":"你也太晚了吧，真是的！","fr":"Tu es en retard, quand même !","alt":"T'es en retard, quand même !","note":"quand même 放句尾表达不满。"}},
 "Sortir du chapeau": {"pos":"loc. verbale 动词短语（sortir 第三组，助动词 avoir）","s":"凭空想出来；变戏法似地拿出来。像魔术师从帽子里变出东西，常指某个主意或办法来得突然、没有根据。也可指真的从帽子里取出东西。","ipa":"[sɔʁ.tiʁ.dy.ʃa.po]","ph":"sortir 结尾 r 要发 [ʁ]；du 读 [dy]；chapeau 中 ch 读 [ʃ]，eau 读 [o]。","pi":"du 是 de + le 的缩合，别说成 de le；chapeau 的复数是 chapeaux。","et":"sortir 来源不确定；chapeau 来自 chape（斗篷、罩）。比喻来自魔术师变戏法。","ex":[["Il a sorti cette idée du chapeau.","他这个主意是凭空冒出来的。"],["Le magicien sort un lapin du chapeau.","魔术师从帽子里变出一只兔子。"]],"co":[["sortir un lapin du chapeau","变出一个意外的办法"],["sortir quelque chose de son chapeau","凭空拿出某物"],["tirer un lapin d'un chapeau","从帽子里变出兔子"]],"sy":[["inventer","courant","编造；发明"],["sortir de nulle part","courant","凭空冒出来"],["sortir de sa manche","familier","从袖子里变出（类似说法）"]],"fq":"中频，口语比喻用法。","me":"魔术师把兔子从帽子里「变」出来。","tr":{"zh":"他又变出一个新办法。","fr":"Il a encore sorti une solution du chapeau.","alt":"Il nous a encore sorti une solution de son chapeau.","note":"sortir 带宾语时，复合过去时用 avoir。"}},
 "Faire ses preuves": {"pos":"loc. verbale 动词短语（faire，助动词 avoir）","s":"证明自己的能力；经受考验。ses 要跟主语一致：je fais mes preuves、il fait ses preuves。常用于新人、新方法、新产品。","ipa":"[fɛʁ.se.pʁœv]","ph":"faire 读 [fɛʁ]；ses 读 [se]；preuves 中 eu 读 [œ]，s 不发。","pi":"preuves 结尾 s 不发；ses / mes / tes 要和主语一致，不能固定用 ses。","et":"preuve 来自拉丁语 proba（试验），同源：prouver（证明）。","ex":[["Il a déjà fait ses preuves dans ce domaine.","他在这个领域已经证明了自己。"],["Ce jeune joueur doit encore faire ses preuves.","这位年轻球员还要证明自己。"]],"co":[["faire ses preuves","证明实力"],["avoir fait ses preuves","经过了考验，靠得住"],["une méthode qui a fait ses preuves","行之有效的方法"]],"sy":[["se montrer à la hauteur","courant","表现称职"],["se prouver","courant","向自己证明"],["démontrer ses compétences","soutenu","展现能力"]],"fq":"中频，日常和书面都用。","me":"preuve（证据）：拿出「证据」给大家看。","tr":{"zh":"新同事还得证明自己。","fr":"Le nouveau collègue doit encore faire ses preuves.","alt":"Le nouveau doit encore montrer ce qu'il vaut.","note":"物主形容词要和主语一致：mes / tes / ses。"}},
 "Faire partie de": {"pos":"loc. verbale 动词短语（faire，助动词 avoir）","s":"属于；是……的一员。partie 在这里不变，不加冠词。人或东西都可以：Il fait partie du club。de 遇到 le 变成 du，遇到 les 变成 des。","ipa":"[fɛʁ.paʁ.ti.də]","ph":"faire 读 [fɛʁ]；partie 读 [paʁ.ti]，结尾 e 不发；de 读 [də]。","pi":"partie 前面不加冠词，不说 faire la partie de；注意 de + le = du。","et":"partie 来自 partir 的古义「分开」，源自拉丁语 partire；同源：part、partager。","ex":[["Il fait partie de l'équipe.","他是团队的一员。"],["Ça fait partie du travail.","这是工作的一部分。"]],"co":[["faire partie de + 名词","属于……"],["faire partie du groupe","是小组成员"],["en faire partie","是其中之一"]],"sy":[["appartenir à","soutenu","属于"],["être membre de","courant","是……的成员"],["compter parmi","soutenu","位于……之列"]],"fq":"高频，日常常用。","me":"fait + partie：自己成了「一部分」。","tr":{"zh":"她是我们俱乐部的成员。","fr":"Elle fait partie de notre club.","alt":"Elle est membre de notre club.","note":"faire partie de，不要加冠词。"}},
 "Prendre son temps": {"pos":"loc. verbale 动词短语（prendre 第三组，助动词 avoir）","s":"慢慢来；不着急。son 随主语变化：je prends mon temps、tu prends ton temps。也可以说 prendre le temps de + 原形（花时间去做）。","ipa":"[pʁɑ̃dʁ.sɔ̃.tɑ̃]","ph":"prendre 读 [pʁɑ̃dʁ]；son 读 [sɔ̃]；temps 读 [tɑ̃]，p 和 s 都不发。","pi":"temps 的 p、s 不发音，读 [tɑ̃]；son / ton / mon 要和主语一致。","et":"prendre 来自拉丁语 prehendere（抓住）；temps 来自拉丁语 tempus。","ex":[["Il faut prendre son temps pour bien faire.","要慢慢来才能做好。"],["Prends ton temps, on n'est pas pressés.","慢慢来，我们不急。"]],"co":[["prendre son temps","慢慢来"],["prendre le temps de + 原形","花时间去做……"],["prends ton temps","别着急"]],"sy":[["ne pas se presser","courant","不着急"],["y aller doucement","courant","慢慢做"],["flâner","courant","闲逛"]],"fq":"高频，日常常用。","me":"把「时间」握在手里，不被它推着走。","tr":{"zh":"别着急，慢慢吃。","fr":"Ne te presse pas, prends ton temps pour manger.","alt":"Pas de souci, prends ton temps.","note":"prendre 的 tu 命令式是 prends，保留 s；son 随人称变成 ton。"}},
 "Être libre de...": {"pos":"loc. adj. 形容词短语（libre 阴阳同形，复数 libres）","s":"可以自由地做……；有权做……。后面接动词原形：Vous êtes libre de partir。强调「你有权利、没有人拦着」，是礼貌且正式的说法。","ipa":"[ɛtʁ.libʁ.də]","ph":"être 读 [ɛtʁ]；libre 读 [libʁ]，结尾 e 不发；de 读 [də]。","pi":"后面接 de + 动词原形；libre 阴阳性同形，不要写 libre 加 e 的阴性形式。","et":"libre 来自拉丁语 liber（自由的）；同源：liberté（自由）。","ex":[["Vous êtes libre de partir.","您可以自由离开。"],["Tu es libre de choisir.","你可以自己选择。"]],"co":[["être libre de + 原形","有自由去做……"],["libre à vous de...","您尽可以……"],["être libre ce soir","今晚有空"]],"sy":[["avoir le droit de","courant","有权做"],["pouvoir","courant","可以"],["être autorisé à","soutenu","获准"]],"fq":"中高频，日常和书面都用。","me":"libre → liberté：你「自由」，想做就做。","tr":{"zh":"你可以自己决定。","fr":"Tu es libre de décider.","alt":"C'est à toi de décider.","note":"être libre de + 动词原形。"}},
 "Parler de la pluie et du beau temps": {"pos":"loc. verbale 动词短语（parler，助动词 avoir）","s":"闲聊；聊些无关紧要的话题（聊天气）。le temps 既指「时间」也指「天气」：la pluie et le beau temps 是常见搭配。含「没谈正事」的意味。","ipa":"[paʁ.le.də.la.plɥi.e.dy.bo.tɑ̃]","ph":"pluie 读 [plɥi]；et 读 [e]；du 读 [dy]；beau 读 [bo]；temps 读 [tɑ̃]。","pi":"pluie 里 u 和 i 连读成 [ɥi]；et 读 [e]，t 不发；temps 的 p、s 不发。","et":"pluie 来自拉丁语 pluvia；temps 来自拉丁语 tempus。整句是惯用语，字面是「谈雨和好天气」。","ex":[["Nous avons parlé de la pluie et du beau temps.","我们聊了聊天气之类的闲话。"],["Il parle de la pluie et du beau temps pour éviter le sujet.","他东拉西扯，避开正题。"]],"co":[["parler de la pluie et du beau temps","闲聊；扯闲话"],["faire la pluie et le beau temps","呼风唤雨，说了算"],["parler pour ne rien dire","说废话"]],"sy":[["bavarder","courant","聊天"],["papoter","familier","闲聊"],["faire la conversation","courant","聊天"]],"fq":"中频，口语常用。","me":"见面先聊「下雨还是晴天」。","tr":{"zh":"我们在电梯里只聊了聊天气。","fr":"Dans l'ascenseur, nous avons seulement parlé de la pluie et du beau temps.","alt":"On a juste parlé de la pluie et du beau temps dans l'ascenseur.","note":"parler de + 名词，de la / du 是部分冠词。"}},
 "Ressouder les liens": {"pos":"loc. verbale 动词短语（ressouder 第一组，助动词 avoir）","s":"重新拉近关系；修复感情。souder 本义是焊接，ressouder les liens 好比把断了的纽带重新「焊」起来。常指家人、朋友、团队。","ipa":"[ʁə.su.de.le.ljɛ̃]","ph":"re- 读 [ʁə]；ou 读 [u]；les 读 [le]；liens 读 [ljɛ̃]，结尾 s 不发。","pi":"ressouder 里 ss 读 [s]（不是 [z]）；liens 的 s 不发音。","et":"re- + souder（拉丁语 solidare「使坚固」）；lien 来自拉丁语 ligamen（绳索）。","ex":[["Ce voyage a permis de ressouder les liens familiaux.","这次旅行让家人关系重新紧密。"],["Ils veulent ressouder les liens après la dispute.","吵架之后，他们想修复关系。"]],"co":[["ressouder les liens familiaux","修复家人关系"],["renouer les liens","重新建立联系"],["resserrer les liens","使关系更紧密"]],"sy":[["renouer","courant","重新联系"],["se réconcilier","courant","和好"],["resserrer les liens","courant","拉近关系"]],"fq":"低中频，偏书面。","me":"souder = 焊接：断了的线，重新「焊」好。","tr":{"zh":"这顿饭让我们重新亲近起来。","fr":"Ce repas nous a aidés à ressouder les liens.","alt":"Ce repas nous a rapprochés.","note":"aider à + 原形；aider 的复合过去时用 avoir。"}},
 "Mettre en lumière": {"pos":"loc. verbale 动词短语（mettre 第三组，助动词 avoir）","s":"揭示；使凸显；让人注意到。把原来不清楚的东西公开、讲明白：mettre en lumière un problème（揭示一个问题）。多见于新闻、报告。","ipa":"[mɛtʁ.ɑ̃.ly.mjɛʁ]","ph":"mettre 读 [mɛtʁ]；en 读 [ɑ̃]；lumière 读 [ly.mjɛʁ]，结尾 -ère 读 [ɛʁ]。","pi":"lumière 的 u 读 [y]，ière 读 [jɛʁ]；lumière 为阴性：la lumière。","et":"mettre（拉丁语 mittere）；lumière 来自拉丁语 luminaria，同源：lumen（光）。","ex":[["L'enquête a mis en lumière de nouveaux faits.","调查揭示了新的事实。"],["Cette étude met en lumière les risques.","这项研究凸显了风险。"]],"co":[["mettre en lumière un problème","揭示问题"],["mettre en lumière les différences","突出差异"],["mettre en évidence","使明显；突出"]],"sy":[["révéler","courant","揭露"],["mettre en évidence","courant","突出"],["souligner","courant","强调"]],"fq":"中频，偏书面。","me":"把东西放进「光」里，大家就看见了。","tr":{"zh":"这份报告揭示了一个大问题。","fr":"Ce rapport met en lumière un gros problème.","alt":"Ce rapport montre bien un gros problème.","note":"mettre 的过去分词是 mis。"}},
 "Se lancer dans...": {"pos":"loc. verbale 动词短语（代词式动词，助动词 être）","s":"投身于；开始做（较大、有风险的事）。后面接名词：se lancer dans les affaires（做生意）。动词复合时用 être：il s'est lancé dans...。","ipa":"[sə.lɑ̃.se.dɑ̃]","ph":"se 读 [sə]；lancer 读 [lɑ̃.se]，c 在 e 前读 [s]；dans 读 [dɑ̃]，s 不发。","pi":"lancer 的 c 读 [s]；dans 结尾 s 不发；复合过去时：je me suis lancé(e)。","et":"lancer 来自 lance（长矛，拉丁语 lancea）；se lancer 即「把自己投出去」。","ex":[["Il veut se lancer dans l'informatique.","他想投身于计算机领域。"],["Elle s'est lancée dans la cuisine à 40 ans.","她四十岁开始投身烹饪。"]],"co":[["se lancer dans les affaires","开始做生意"],["se lancer dans l'aventure","踏上冒险"],["se lancer un défi","给自己设下挑战"]],"sy":[["se mettre à","courant","开始做"],["s'engager dans","soutenu","投入；参与"],["se jeter à l'eau","familier","豁出去试试"]],"fq":"中频，日常常用。","me":"lance（长矛）：像把自己「投」出去。","tr":{"zh":"她打算开一家小公司。","fr":"Elle va se lancer dans la création d'une petite entreprise.","alt":"Elle va monter sa petite boîte.","note":"se lancer dans + 名词，不接动词原形。"}},
 "Croiser quelqu'un": {"pos":"loc. verbale 动词短语（croiser 第一组，助动词 avoir）","s":"碰见某人；和某人擦肩而过。多半是偶然遇到，没有约好。croiser 本义是「交叉」。不要和 rencontrer（认识、见面）混淆，croiser 更随意。","ipa":"[kʁwa.ze.kɛl.kœ̃]","ph":"croi 读 [kʁwa]；s 在元音间读 [z]；quelqu'un 读 [kɛl.kœ̃]。","pi":"croiser 的 s 读 [z]；quelqu'un 中 qu 读 [k]，un 读 [œ̃]。","et":"croiser 来自 croix（拉丁语 crux）+ -er，本义「使交叉」。","ex":[["J'ai croisé ton frère hier.","我昨天碰见了你哥哥。"],["Je l'ai croisée dans la rue.","我在街上碰见她。"]],"co":[["croiser quelqu'un dans la rue","在街上碰见某人"],["croiser les bras","抱起双臂；袖手旁观"],["croiser les doigts","祈祷好运"]],"sy":[["rencontrer","courant","遇见；认识"],["tomber sur","familier","偶然碰到"],["apercevoir","courant","瞥见"]],"fq":"中高频，日常常用。","me":"croix（十字）：两个人的路「交叉」了。","tr":{"zh":"我今早在超市碰见了老师。","fr":"J'ai croisé mon professeur au supermarché ce matin.","alt":"Je suis tombé sur mon prof au supermarché ce matin.","note":"croiser + 人，直接宾语，不加介词。"}},
 "Prendre de l'ampleur": {"pos":"loc. verbale 动词短语（prendre 第三组，助动词 avoir）","s":"规模扩大；声势变大；越来越严重。多用于运动、现象、问题：le mouvement prend de l'ampleur。可好可坏，看上下文。","ipa":"[pʁɑ̃dʁ.də.lɑ̃.plœʁ]","ph":"prendre 读 [pʁɑ̃dʁ]；de l' 读 [də.l]；ampleur 读 [ɑ̃.plœʁ]，eu 读 [œ]，r 要发。","pi":"ampleur 的 am 读鼻化音 [ɑ̃]；ampleur 是阴性名词：l'ampleur。","et":"ampleur 由 ample（拉丁语 amplus「宽大的」）+ -eur 构成。","ex":[["Le mouvement de grève prend de l'ampleur.","罢工运动正在扩大。"],["Cette idée prend de l'ampleur.","这个想法越来越有影响。"]],"co":[["prendre de l'ampleur","扩大；壮大"],["l'ampleur du problème","问题的严重程度"],["une ampleur inattendue","出乎意料的规模"]],"sy":[["s'amplifier","soutenu","增强"],["s'étendre","courant","蔓延；扩展"],["grandir","courant","变大"]],"fq":"中频，多见于新闻。","me":"ample（宽大）→ ampleur：事情越变越「宽」。","tr":{"zh":"这个问题越来越严重。","fr":"Ce problème prend de l'ampleur.","alt":"Ce problème devient de plus en plus grave.","note":"prendre de l'ampleur 是固定搭配，ampleur 前面用 de l'。"}},
 "Prendre une décision": {"pos":"loc. verbale 动词短语（prendre 第三组，助动词 avoir）","s":"做决定。法语用 prendre（拿），不用 faire。prendre une décision 是固定搭配。过去时：j'ai pris une décision。也说 prendre une décision importante / difficile。","ipa":"[pʁɑ̃.dʁyn.de.si.zjɔ̃]","ph":"prendre 读 [pʁɑ̃dʁ]，une 连读成 [pʁɑ̃.dʁyn]；décision 中 s 读 [z]，结尾读 [zjɔ̃]。","pi":"不要说 faire une décision；décision 中 s 读 [z]。","et":"décision 来自拉丁语 decisio，同源：décider（决定）。","ex":[["J'ai pris une décision importante.","我做了一个重要的决定。"],["Il faut prendre une décision rapidement.","必须尽快做出决定。"]],"co":[["prendre une décision","做决定"],["prendre la décision de + 原形","决定做……"],["une décision difficile","艰难的决定"]],"sy":[["décider","courant","决定（动词）"],["trancher","courant","作出决断"],["arrêter une décision","soutenu","拿定主意"]],"fq":"极高频，日常常用。","me":"法语里决定是「拿」(prendre)出来的，不是「做」出来的。","tr":{"zh":"我今天必须做出决定。","fr":"Je dois prendre une décision aujourd'hui.","alt":"Il faut que je décide aujourd'hui.","note":"devoir + 原形；prendre 不是 faire。"}},
 "À force de...": {"pos":"loc. prép. 介词短语","s":"由于不断……；一再……的结果。后面接动词原形或名词，强调反复做了很多次，最后出现结果：À force de travailler, il a réussi。结果可好可坏。","ipa":"[a.fɔʁs.də]","ph":"force 读 [fɔʁs]，o 为开口音，结尾 e 不发；de 读 [də]。","pi":"后面接动词原形（à force de dire），不能接变位形式；force 的 c 读 [s]。","et":"force 来自拉丁语 fortia，同源 fort（强）。","ex":[["À force de travailler, il a réussi.","由于不断努力，他成功了。"],["À force de manger du chocolat, il a grossi.","他吃了太多巧克力，结果胖了。"]],"co":[["à force de + 原形","一再……的结果"],["à force de patience","凭着耐心"],["à force de temps","时间一长"]],"sy":[["en + 现在分词","courant","通过……"],["grâce à","courant","多亏"],["à cause de","courant","因为（坏结果）"]],"fq":"中高频，日常和书面都用。","me":"force（力气）：一遍遍「用力」，终于出结果。","tr":{"zh":"他练得多，终于学会了。","fr":"À force de s'entraîner, il a fini par apprendre.","alt":"À force de s'entraîner, il y est arrivé.","note":"à force de + 动词原形。"}},
 "En dehors de": {"pos":"loc. prép. 介词短语","s":"除……之外；在……之外。可指范围、地点或时间：en dehors de la ville（城外）、en dehors des heures de travail（工作时间以外）。后面不接动词原形的变位形式。","ipa":"[ɑ̃.də.ɔʁ.də]","ph":"en 读 [ɑ̃]；dehors 读 [də.ɔʁ]，h 不发，s 不发。","pi":"dehors 的 h 不发音，s 也不发；写作 en dehors de，不是 en dehors à。","et":"dehors 由 de + hors（拉丁语 foris「在外」）构成。","ex":[["En dehors de cela, tout va bien.","除此之外，一切都好。"],["Il travaille en dehors des heures de bureau.","他在办公时间之外工作。"]],"co":[["en dehors de la ville","城外"],["en dehors du sujet","离题"],["en dehors de ça","除此之外"]],"sy":[["à part","courant","除了"],["hormis","soutenu","除……外"],["sauf","courant","除非；除……外"]],"fq":"中高频，日常常用。","me":"dehors = 外面：站在范围的「外面」。","tr":{"zh":"除了周末，我每天都工作。","fr":"En dehors du week-end, je travaille tous les jours.","alt":"À part le week-end, je travaille tous les jours.","note":"de + le = du。"}},
 "À part": {"pos":"loc. prép. 介词短语","s":"除……以外；除了。后面可直接加人或物：à part toi（除了你）。放在句首或句中都可以。也可以作形容词，指「独特的、另类的」：un cas à part。","ipa":"[a.paʁ]","ph":"à 读 [a]；part 读 [paʁ]，结尾 t 不发。","pi":"part 的 t 不发音；à 要写重音，没有重音是 a（有）。","et":"part 来自拉丁语 pars（部分）；à part 原指「放在一边」。","ex":[["À part toi, personne n'est venu.","除了你，没人来。"],["À part ça, tout va bien.","除此之外，一切都好。"]],"co":[["à part ça","除此之外"],["à part moi","除了我"],["un cas à part","特例"]],"sy":[["sauf","courant","除了"],["excepté","soutenu","除……外"],["hormis","soutenu","除……外"]],"fq":"高频，日常常用。","me":"à part = 「放到一边」，不算在内。","tr":{"zh":"除了你，我谁也不认识。","fr":"À part toi, je ne connais personne.","alt":"Je ne connais personne, sauf toi.","note":"personne 在 ne 的后面表示否定。"}},
 "En fait, ...": {"pos":"loc. adv. 副词短语","s":"其实；事实上。引出真实情况，常用来纠正或补充前面的看法。放句首，后面加逗号。语气比较轻，常用在口语里。","ipa":"[ɑ̃.fɛt]","ph":"en 读 [ɑ̃]；fait 读 [fɛ]，结尾的 t 常发 [t]，也可不发。","pi":"fait 本来 t 不发，但在 en fait 中经常读出 [t]，两种都可以。","et":"fait 来自拉丁语 factum（做过的事），同源：faire（做）。","ex":[["En fait, je ne suis pas d'accord.","其实我不同意。"],["En fait, il n'a jamais appelé.","其实他从来没打过电话。"]],"co":[["en fait, ...","其实……"],["en fait de","就……而言"],["au fait","对了（转换话题）"]],"sy":[["en réalité","courant","实际上"],["en effet","courant","确实（表示赞同，不同义）"],["à vrai dire","courant","说实话"]],"fq":"极高频，口语中常用。","me":"fait = 事实：en fait → 「在事实中」。","tr":{"zh":"其实我不饿。","fr":"En fait, je n'ai pas faim.","alt":"En réalité, je n'ai pas faim.","note":"en fait 放句首，后面用逗号。"}},
 "En raison de": {"pos":"loc. prép. 介词短语","s":"由于；因为。后面接名词：en raison du mauvais temps。比 à cause de 更正式，语气中性，不带责备。用于公告、新闻。","ipa":"[ɑ̃.ʁɛ.zɔ̃.də]","ph":"en 读 [ɑ̃]；raison 读 [ʁɛ.zɔ̃]，s 读 [z]，结尾 n 不发；de 读 [də]。","pi":"raison 的 ai 读 [ɛ]，s 读 [z]；后面接名词，不接 que。","et":"raison 来自拉丁语 ratio（理由、计算），同源：raisonner（推理）。","ex":[["Le vol est annulé en raison du mauvais temps.","由于天气不好，航班取消了。"],["Le magasin est fermé en raison de travaux.","商店因施工而关门。"]],"co":[["en raison de + 名词","由于……"],["en raison des travaux","因为施工"],["en raison d'un problème technique","因技术问题"]],"sy":[["à cause de","courant","因为（常指坏原因）"],["grâce à","courant","多亏（好原因）"],["du fait de","soutenu","由于"]],"fq":"中高频，常见于公告和新闻。","me":"raison = 理由：en raison de = 「出于……的理由」。","tr":{"zh":"由于下雨，比赛推迟了。","fr":"Le match est reporté en raison de la pluie.","alt":"Le match est reporté à cause de la pluie.","note":"en raison de + 名词；de la 保留。"}},
 "De l'ordre de": {"pos":"loc. prép. 介词短语","s":"大约；数量级为。用于数量、价格、比例：de l'ordre de 100 euros（约一百欧元）。表示粗略的估计，较书面。","ipa":"[də.lɔʁ.dʁə.də]","ph":"de l' 连读 [də.l]；ordre 读 [ɔʁdʁ]，结尾 e 轻读或不发；de 读 [də]。","pi":"ordre 为阳性名词：l'ordre；ordre 里 o 是开口音 [ɔ]。","et":"ordre 来自拉丁语 ordo（顺序、等级）。","ex":[["Le coût est de l'ordre de cent euros.","成本大约一百欧元。"],["La hausse est de l'ordre de 5 %.","涨幅大约百分之五。"]],"co":[["de l'ordre de + 数字","大约……"],["de l'ordre de quelques jours","几天左右"],["dans l'ordre de","按……的顺序"]],"sy":[["environ","courant","大约"],["autour de","courant","在……上下"],["approximativement","soutenu","大致"]],"fq":"中频，偏书面。","me":"ordre（数量级）：说的是「大概在这个量级上」。","tr":{"zh":"这次旅行大约要花一千欧元。","fr":"Ce voyage coûte de l'ordre de mille euros.","alt":"Ce voyage coûte environ mille euros.","note":"de l'ordre de 后面直接接数字。"}},
 "Si jamais...": {"pos":"loc. conj. 连词短语","s":"万一；要是……的话。条件从句，后面接直陈式的现在时，主句用命令式、现在时或将来时：Si jamais tu as besoin, appelle-moi。jamais 在这里不是否定。","ipa":"[si.ʒa.mɛ]","ph":"si 读 [si]；jamais 读 [ʒa.mɛ]，s 不发；j 读 [ʒ]。","pi":"jamais 在这里不是「从不」，句中不用 ne；si jamais il 中 si 不省音（省音只发生在 si 直接接 il 时）。","et":"jamais 由 ja（拉丁语 jam「已经」）+ mais（拉丁语 magis「更」）构成；si 来自拉丁语 si。","ex":[["Si jamais tu as besoin d'aide, appelle-moi.","万一你需要帮助，就给我打电话。"],["Si jamais il pleut, on reste ici.","万一下雨，我们就待在这儿。"]],"co":[["si jamais + 现在时","万一……"],["si jamais tu veux","要是你想的话"],["au cas où + 条件式","以防……"]],"sy":[["au cas où","courant","以防（后接条件式）"],["en cas de","courant","如果发生……"],["si par hasard","courant","如果碰巧"]],"fq":"中高频，口语常用。","me":"si + jamais（有朝一日）：「万一哪天……」。","tr":{"zh":"万一你迟到，就先给我发消息。","fr":"Si jamais tu es en retard, envoie-moi d'abord un message.","alt":"Si jamais t'es en retard, préviens-moi.","note":"si jamais 后接现在时，不用条件式。"}},
 "Non seulement ... mais en plus ...": {"pos":"loc. conj. 连词短语","s":"不仅……而且……。把两个事实叠在一起，第二项往往更强。更正式的写法是 non seulement ... mais aussi / mais encore。en plus 较口语。","ipa":"[nɔ̃.sœl.mɑ̃.mɛ.zɑ̃.plys]","ph":"non 读 [nɔ̃]；seulement 读 [sœl.mɑ̃]；mais en plus 连读 [mɛ.zɑ̃.plys]，plus 的 s 要发。","pi":"seulement 里 eu 读 [œ]；en plus 里 plus 的 s 要发音。","et":"seulement 由 seul（拉丁语 solus）+ -ment 构成；plus 来自拉丁语 plus。","ex":[["Non seulement il est en retard, mais en plus il n'a pas appelé.","他不仅迟到，而且还没打电话。"],["Non seulement c'est cher, mais en plus c'est mauvais.","不仅贵，而且还难吃。"]],"co":[["non seulement ... mais aussi","不仅……而且也……"],["non seulement ... mais encore","不仅……甚至还……"],["et en plus","而且还"]],"sy":[["non seulement ... mais aussi","courant","更正式、更通用"],["en plus de","courant","除……之外还有"],["de plus","courant","此外"]],"fq":"中高频，日常和书面都用。","me":"先说一个，「再加一个」：mais en plus。","tr":{"zh":"他不仅会英语，而且还会法语。","fr":"Non seulement il parle anglais, mais en plus il parle français.","alt":"Il parle anglais, et en plus il parle français.","note":"non seulement 放句首时，主语和动词常倒装，口语不必。"}},
 "Dans un premier temps, ...": {"pos":"loc. adv. 副词短语","s":"首先；第一阶段。把事情分步骤时用，后面常接 dans un deuxième temps（第二步）。放句首，后面加逗号。","ipa":"[dɑ̃.zœ̃.pʁə.mje.tɑ̃]","ph":"dans un 连读 [dɑ̃.zœ̃]；premier 读 [pʁə.mje]；temps 读 [tɑ̃]。","pi":"premier 读 [pʁə.mje]，结尾 r 不发；temps 的 p 和 s 不发。","et":"premier 来自拉丁语 primarius（首位的）；temps 来自拉丁语 tempus。","ex":[["Dans un premier temps, nous allons analyser la situation.","首先，我们将分析形势。"],["Dans un premier temps, lisez le texte.","第一步，先读课文。"]],"co":[["dans un premier temps","首先；第一阶段"],["dans un deuxième temps","其次；第二阶段"],["dans un second temps","第二步"]],"sy":[["tout d'abord","courant","首先"],["d'abord","courant","先"],["pour commencer","courant","首先"]],"fq":"中高频，常用于说明、演讲。","me":"把任务分成几个「时间段」：第一段、第二段。","tr":{"zh":"首先，我们要检查一下预算。","fr":"Dans un premier temps, nous devons vérifier le budget.","alt":"D'abord, on doit vérifier le budget.","note":"后面接 dans un deuxième temps。"}},
 "D'une part ... D'autre part ...": {"pos":"loc. conj. 连词短语","s":"一方面……另一方面……。列出两个方面：可以是优缺点，也可以是并列的两点。d'autre part 也可单独表示「此外」。","ipa":"[dyn.paʁ.dotʁ.paʁ]","ph":"d'une 读 [dyn]；part 读 [paʁ]，t 不发；d'autre 读 [dotʁ]，au 读 [o]。","pi":"d'une part 的 t 不发；autre 里 au 读 [o]；part 为阴性名词，所以是 une part。","et":"part 来自拉丁语 pars（部分）。","ex":[["D'une part, c'est cher, d'autre part, c'est loin.","一方面太贵，另一方面太远。"],["D'une part, je suis fatigué ; d'autre part, j'ai du travail.","一方面我很累，另一方面我还有工作。"]],"co":[["d'une part ... d'autre part ...","一方面……另一方面……"],["d'un côté ... de l'autre ...","一边……另一边……"],["d'autre part","此外；另一方面"]],"sy":[["d'un côté ... de l'autre","courant","一方面……另一方面"],["en premier lieu ... en second lieu","soutenu","首先……其次"],["par ailleurs","soutenu","此外"]],"fq":"中高频，讨论和作文常用。","me":"一边放一件事（une part），另一边再放一件。","tr":{"zh":"一方面我喜欢这份工作，另一方面薪水太低。","fr":"D'une part, j'aime ce travail ; d'autre part, le salaire est trop bas.","alt":"D'un côté, j'aime ce travail ; de l'autre, le salaire est trop bas.","note":"d'une part 和 d'autre part 要成对出现。"}},
 "Au même titre que...": {"pos":"loc. conj. 连词短语","s":"与……一样；与……同等。表示两者地位、资格相同：Il a été récompensé au même titre que les autres。titre 在这里是「资格、地位」。","ipa":"[o.mɛm.titʁ.kə]","ph":"au 读 [o]；même 读 [mɛm]；titre 读 [titʁ]，结尾 e 弱读；que 读 [kə]。","pi":"même 中 ê 读 [ɛ]；后接 que + 名词；遇元音时 que 要省音为 qu'。","et":"titre 来自拉丁语 titulus（标签、头衔）。","ex":[["Il a été récompensé au même titre que les autres.","他和其他人一样得到了奖励。"],["Elle a le droit de parler au même titre que vous.","她和你们一样有权发言。"]],"co":[["au même titre que + 名词","与……同样"],["à ce titre","就此而言"],["à titre d'exemple","举例来说"]],"sy":[["tout comme","courant","就像"],["de la même façon que","courant","以同样的方式"],["à égalité avec","soutenu","与……同等"]],"fq":"中频，偏书面。","me":"titre（资格）：大家站在同一个「头衔」上。","tr":{"zh":"他和你一样有资格参加。","fr":"Il peut participer au même titre que toi.","alt":"Il peut participer, comme toi.","note":"au même titre que 后面接名词或重读人称代词 toi。"}},
 "En toute simplicité": {"pos":"loc. adv. 副词短语","s":"简简单单地；不讲排场地。多用来描述聚会、仪式、说话的方式：un mariage en toute simplicité（简单的婚礼）。给人朴素、亲切的感觉。","ipa":"[ɑ̃.tut.sɛ̃.pli.si.te]","ph":"en 读 [ɑ̃]；toute 读 [tut]；simplicité 读 [sɛ̃.pli.si.te]，结尾 é 读 [e]。","pi":"simplicité 里 -ci- 读 [si]，不要写成 -ssi-；toute 是阴性，与 simplicité 一致。","et":"simplicité 来自拉丁语 simplicitas，同源：simple。","ex":[["Le dîner s'est déroulé en toute simplicité.","晚餐在简单的氛围中进行。"],["Ils se sont mariés en toute simplicité.","他们简简单单地结了婚。"]],"co":[["en toute simplicité","简简单单地"],["en toute franchise","说实话"],["en toute sécurité","安全地"]],"sy":[["simplement","courant","简单地"],["sans cérémonie","courant","不拘礼节"],["modestement","courant","朴素地"]],"fq":"中频，日常和书面都用。","me":"toute + simplicité：「百分之百简单」。","tr":{"zh":"我们简简单单地庆祝了生日。","fr":"Nous avons fêté l'anniversaire en toute simplicité.","alt":"On a fêté l'anniversaire simplement.","note":"en toute + 阴性名词，是一类固定说法。"}},
 "En fonction de ...": {"pos":"loc. prép. 介词短语","s":"根据……；视……而定。表示某件事随另一件事的情况而变化：en fonction du budget（视预算而定）。比 selon 更偏向「随之变化」。","ipa":"[ɑ̃.fɔ̃k.sjɔ̃.də]","ph":"en 读 [ɑ̃]；fonction 读 [fɔ̃k.sjɔ̃]，ction 读 [ksjɔ̃]；de 读 [də]。","pi":"fonction 里 ction 读 [ksjɔ̃]，c 要发 [k]；后接名词。","et":"fonction 来自拉丁语 functio（执行、职责）。","ex":[["Le prix varie en fonction de la taille.","价格根据大小而变。"],["Choisis en fonction de tes besoins.","根据你的需要来选。"]],"co":[["en fonction de + 名词","根据……"],["varier en fonction de","随……而变"],["en fonction des circonstances","视情况而定"]],"sy":[["selon","courant","根据"],["suivant","courant","按照"],["d'après","courant","据……"]],"fq":"高频，日常和书面都用。","me":"fonction（作用）：A 的「作用」决定 B 怎么变。","tr":{"zh":"价格会根据季节变化。","fr":"Le prix change en fonction de la saison.","alt":"Le prix dépend de la saison.","note":"en fonction de + 名词。"}},
 "En complément de...": {"pos":"loc. prép. 介词短语","s":"作为……的补充；除……之外还有。表示补上不足的部分：en complément de son salaire（作为薪水的补充）。complément 是阳性名词。","ipa":"[ɑ̃.kɔ̃.ple.mɑ̃.də]","ph":"en 读 [ɑ̃]；com 读鼻化音 [kɔ̃]；plé 读 [ple]；ment 读 [mɑ̃]。","pi":"complément 里 é 读 [e]，不是 [ɛ]；注意与 compliment（称赞）区分。","et":"complément 来自拉丁语 complementum，同源：compléter（补全）。","ex":[["Je prends des vitamines en complément de mon alimentation.","我吃维生素来补充饮食。"],["Il fait un petit travail en complément de ses études.","他在学业之外还做一份小工作。"]],"co":[["en complément de + 名词","作为……的补充"],["un complément alimentaire","保健品；营养补充剂"],["un complément d'information","补充信息"]],"sy":[["en plus de","courant","除……之外还有"],["en supplément de","soutenu","额外补充"],["pour compléter","courant","为了补全"]],"fq":"中频，偏书面。","me":"complét-er → complément：把缺的补满。","tr":{"zh":"他做兼职，作为生活费的补充。","fr":"Il fait un petit boulot en complément de ses études.","alt":"Il a un petit boulot en plus de ses études.","note":"en complément de + 名词。"}},
 "En action": {"pos":"loc. adv. / loc. adj. 短语","s":"在行动中；正在发挥作用。常用来说「看某人实际表现」：voir quelqu'un en action（看某人实战）。也用于标题：Le robot en action。","ipa":"[ɑ̃.nak.sjɔ̃]","ph":"en 与 action 连读成 [ɑ̃.nak]，n 往后连；action 读 [ak.sjɔ̃]。","pi":"en 和 action 要连读，n 带到后面成 [nak]；action 的 ct 里 c 要读 [k]。","et":"action 来自拉丁语 actio，同源：agir（行动）。","ex":[["Nous avons vu l'équipe en action.","我们看到了团队的实战表现。"],["Le robot est en action depuis ce matin.","机器人从早上起一直在运作。"]],"co":[["voir quelqu'un en action","看某人实际行动"],["entrer en action","开始行动"],["être en action","正在行动"]],"sy":[["en pratique","courant","在实践中"],["à l'œuvre","soutenu","正在工作；在发挥作用"],["en train d'agir","courant","正在行动"]],"fq":"中频，日常和新闻用语。","me":"en + action：一看就是「正在动」。","tr":{"zh":"今晚你们会看到这位歌手现场表演。","fr":"Ce soir, vous verrez la chanteuse en action.","alt":"Ce soir, on verra la chanteuse sur scène.","note":"en action 放在宾语后面。"}},
 "Feutre (matière)": {"pos":"n.m. 阳性名词，复数 feutres","s":"毡；毛毡（用压实的羊毛等纤维做成的厚布料）。un chapeau en feutre = 毡帽。另有 un feutre = 毡头笔、马克笔，这个意思不是本词条的「材料」。","ipa":"[føtʁ]","ph":"eu 读 [ø]；tre 读 [tʁ]，结尾 e 不发。","pi":"feutre 只有一个音节 [føtʁ]；eu 读 [ø]，不是 [œ]。","et":"来自法兰克语 *filtir，与英语 felt 同源。","ex":[["Un chapeau en feutre.","一顶毡帽。"],["Ce manteau est doublé de feutre.","这件大衣衬里是毡。"]],"co":[["un chapeau en feutre","毡帽"],["du feutre épais","厚毛毡"],["un feutre","毡头笔（另一个意思）"]],"sy":[["la laine","courant","羊毛"],["le feutre (stylo)","courant","毡头笔；同形不同义"],["le tissu","courant","布料"]],"fq":"低中频。","me":"feutre ≈ 英语 felt：一个词，两种语言。","tr":{"zh":"他戴着一顶灰色的毡帽。","fr":"Il porte un chapeau en feutre gris.","alt":"Il a un chapeau gris en feutre.","note":"en + 材料，如 en feutre。"}},
 "L'éclairage": {"pos":"n.m. 阳性名词，复数 éclairages","s":"灯光；照明。指房间、舞台、街道的光线与设备：un bon éclairage。也可比喻「看问题的角度」：sous un autre éclairage。","ipa":"[e.klɛ.ʁaʒ]","ph":"é 读 [e]；clai 读 [klɛ]；rage 读 [ʁaʒ]，g 读 [ʒ]。","pi":"-age 读 [aʒ]，结尾 e 不发；-age 的名词一般是阳性。","et":"éclairer（点亮）+ -age；éclairer 由 clair（拉丁语 clarus「明亮的」）而来。","ex":[["L'éclairage de la scène est magnifique.","舞台灯光很漂亮。"],["L'éclairage de cette pièce est trop faible.","这间房间的照明太暗了。"]],"co":[["un bon éclairage","良好的照明"],["l'éclairage public","路灯照明"],["un éclairage tamisé","柔和的灯光"]],"sy":[["la lumière","courant","光线"],["l'illumination","soutenu","照明；灯饰"],["les lumières","courant","灯光（复数）"]],"fq":"中频。","me":"clair（亮）→ éclairer → éclairage：让它变「亮」。","tr":{"zh":"这家餐厅的灯光很柔和。","fr":"L'éclairage de ce restaurant est très doux.","alt":"Dans ce restaurant, la lumière est très douce.","note":"l'éclairage 的 l' 是 le 的省音。"}},
 "Le lever de rideau (au théâtre)": {"pos":"n.m. 阳性名词，复数 levers de rideau","s":"开幕；幕启（戏剧）。指幕布拉开、演出开始的时刻。也可以指正式演出前的短节目。","ipa":"[lə.ve.də.ʁi.do]","ph":"lever 读 [lə.ve]，结尾 r 不发；rideau 读 [ʁi.do]，eau 读 [o]。","pi":"lever 在这里是名词，结尾 r 不发，读 [ve]；rideau 的 d 不要读成 t。","et":"lever 来自拉丁语 levare（举起）；rideau 来自 rider（打褶），指可褶起的布幕。","ex":[["Nous sommes arrivés juste avant le lever de rideau.","我们在开幕前刚好到。"],["Le lever de rideau est à vingt heures.","晚上八点开幕。"]],"co":[["avant le lever de rideau","开幕之前"],["le lever de rideau","开幕"],["la fin de la pièce / le baisser de rideau","戏剧结束；落幕"]],"sy":[["le début du spectacle","courant","演出开始"],["l'ouverture","courant","开场"],["la première","courant","首演"]],"fq":"低频，戏剧场合用。","me":"lever（升起）+ rideau（幕）：幕布升起。","tr":{"zh":"开幕前，大家都安静了。","fr":"Avant le lever de rideau, tout le monde s'est tu.","alt":"Avant le début du spectacle, tout le monde s'est tu.","note":"se taire 的复合过去时：s'est tu。"}},
 "Le palmarès": {"pos":"n.m. 阳性名词，复数 palmarès（不变）","s":"获奖名单；排行榜；战绩。比赛、电影节后公布的名次：le palmarès du festival。也指一个人的所有成绩：un beau palmarès。","ipa":"[pal.ma.ʁɛs]","ph":"pal 读 [pal]，l 要发；ma 读 [ma]；rès 读 [ʁɛs]，结尾 s 要发音。","pi":"palmarès 的 s 要读出来 [ɛs]；单复数同形。","et":"来自拉丁语 palmares（值得棕榈枝的），palma 是胜利的象征。","ex":[["Le palmarès du festival sera annoncé ce soir.","音乐节的获奖名单今晚公布。"],["Ce joueur a un impressionnant palmarès.","这名球员战绩惊人。"]],"co":[["le palmarès du festival","电影节/音乐节获奖名单"],["un beau palmarès","漂亮的战绩"],["au palmarès","榜上有名"]],"sy":[["le classement","courant","排名"],["la liste des gagnants","courant","获奖者名单"],["le tableau d'honneur","soutenu","荣誉榜"]],"fq":"中低频，新闻、体育常见。","me":"palma（棕榈枝）：得胜者手里拿的东西。","tr":{"zh":"明天将公布获奖名单。","fr":"Le palmarès sera annoncé demain.","alt":"On annoncera le palmarès demain.","note":"被动式 sera annoncé。"}},
 "Le premier rang": {"pos":"n.m. 阳性名词，复数 premiers rangs","s":"第一排；前排。电影院、剧院、教室里的前排座位：au premier rang。也有比喻义：être au premier rang（处于最前面、最重要的位置）。","ipa":"[lə.pʁə.mje.ʁɑ̃]","ph":"premier 读 [pʁə.mje]，r 不发；rang 读 [ʁɑ̃]，g 不发。","pi":"rang 结尾 g 不发音；premier 结尾 r 不发音，读 [mje]。","et":"premier 来自拉丁语 primarius；rang 来自古法语 reng，源于法兰克语 *hring（圈、排）。","ex":[["Nous avons des places au premier rang.","我们有第一排的座位。"],["Elle s'assoit toujours au premier rang.","她总是坐在第一排。"]],"co":[["au premier rang","在第一排"],["au deuxième rang","在第二排"],["au dernier rang","在最后一排"]],"sy":[["le devant","courant","前面"],["les premières places","courant","前排座位"],["au fond","courant","后面（反义）"]],"fq":"中频。","me":"rang 是「排」，premier 是「第一」。","tr":{"zh":"我想坐第一排。","fr":"Je voudrais m'asseoir au premier rang.","alt":"Je veux m'asseoir au premier rang.","note":"s'asseoir 的不定式形式要记牢。"}},
 "Robin des Bois": {"pos":"n.m. 阳性专有名词（人名），无复数","s":"罗宾汉（英国民间传说中劫富济贫的侠盗）。法语里的叫法是 Robin des Bois（字面「林中的罗宾」）。也可泛指「劫富济贫的人」：un Robin des Bois。","ipa":"[ʁɔ.bɛ̃.de.bwa]","ph":"Robin 读 [ʁɔ.bɛ̃]，in 为鼻化音；des 读 [de]；Bois 读 [bwa]，s 不发。","pi":"Bois 结尾 s 不发音；Robin 结尾 n 不发出，读鼻化音 [ɛ̃]。","et":"传说源自英国的 Robin Hood；法语名 Robin des Bois 中 bois 指树林（拉丁语时期的词源不确定），并非 Hood 的直译。","ex":[["Robin des Bois volait aux riches pour donner aux pauvres.","罗宾汉劫富济贫。"],["Mon fils adore l'histoire de Robin des Bois.","我儿子很爱罗宾汉的故事。"]],"co":[["Robin des Bois","罗宾汉"],["voler aux riches pour donner aux pauvres","劫富济贫"],["la forêt de Sherwood","舍伍德森林"]],"sy":[["un justicier","courant","惩恶扬善的人"],["un hors-la-loi","courant","亡命之徒"],["un bandit au grand cœur","courant","有侠义心肠的强盗"]],"fq":"中低频，故事和文化常识。","me":"Robin + des Bois：住在「树林」里的 Robin。","tr":{"zh":"孩子们喜欢听罗宾汉的故事。","fr":"Les enfants aiment écouter l'histoire de Robin des Bois.","alt":"Les enfants adorent l'histoire de Robin des Bois.","note":"aimer + 原形：aimer écouter。"}},
 "Un billet": {"pos":"n.m. 阳性名词，复数 billets","s":"票（车票、电影票、门票）；也指纸币。un billet de train = 火车票，un billet de 20 euros = 20 欧元的纸币。","ipa":"[bi.jɛ]","ph":"bil 里的 ll 读 [j]，不是 [l]；结尾 -et 读 [ɛ]，t 不发音。","pi":"ll 读 [j]（像「耶」的起音），不要读成 bi-let；结尾 t 不发音；是阳性。","et":"来自古法语 billette，与 bulle（盖章的文书，拉丁语 bulla）有关；细节不完全确定。","ex":[["Nous achetons nos billets sur internet.","我们在网上买票。"],["Un billet pour Lyon, s'il vous plaît.","请给我一张去里昂的票。"],["Je n'ai pas de petits billets.","我没有小面额的纸币。"]],"co":[["un billet de train / d'avion","火车票 / 机票"],["un billet aller-retour","往返票"],["un billet de banque","钞票"],["réserver / composter un billet","订票 / 在机器上打票"]],"sy":[["ticket","courant","小票、地铁票、收据；比 billet 更小额或更短途"],["place","courant","座位、入场名额（买 une place de cinéma）"]],"fq":"高频，日常常用。","me":"bi-llet：ll 读「耶」，想成「比耶」，手里拿着票。","tr":{"zh":"我想买两张去巴黎的票。","fr":"Je voudrais acheter deux billets pour Paris.","alt":"Je prends deux billets pour Paris, s'il vous plaît.","note":"买票用 acheter / prendre un billet；pour + 目的地。"}},
 "Un budget": {"pos":"n.m. 阳性名词，复数 budgets","s":"预算；可用的钱。可指家庭、公司、国家的预算：le budget de l'État = 国家预算。","ipa":"[byd.ʒɛ]","ph":"u 读 [y]（圆唇的「于」）；dg 在这里读 [d.ʒ]；结尾 -et 读 [ɛ]，t 不发音。","pi":"u 是 [y]，不是 [u] 或英语的 /ʌ/；结尾 t 不发音，不是英语 /bʌdʒɪt/。","et":"来自古法语 bougette（小皮袋），后经英语 budget 又借回法语。","ex":[["Le budget de ce projet est très limité.","这个项目的预算很有限。"],["Nous avons un petit budget pour les vacances.","我们的假期预算不多。"],["Il faut respecter le budget.","必须遵守预算。"]],"co":[["un budget serré / limité","紧张的 / 有限的预算"],["faire un budget","做预算"],["dépasser le budget","超出预算"],["à petit budget","低预算的"]],"sy":[["enveloppe","courant","（拨出的）经费总额"],["moyens","courant","财力、手头的钱（复数）"]],"fq":"高频，日常和工作中常用。","me":"bud-get：想成 bu-「于」-jè，钱袋（bougette）里的钱。","tr":{"zh":"我们每个月都有预算。","fr":"Nous avons un budget chaque mois.","alt":"On a un budget tous les mois.","note":"avoir un budget；chaque mois = 每个月。"}},
 "Un choc": {"pos":"n.m. 阳性名词，复数 chocs","s":"冲击；碰撞；打击；震惊。既指物理上的撞击（le choc de deux voitures），也指情绪上的打击（un choc émotionnel）。","ipa":"[ʃɔk]","ph":"ch 读 [ʃ]；o 读开口的 [ɔ]；结尾 c 读 [k]。","pi":"结尾的 c 要发 [k]，不是哑音（对比 blanc、tabac）；复数 chocs 里 s 不发音，但 c 仍发。","et":"来自动词 choquer（撞击），源自日耳曼语，细节不完全确定。同族：choquant（令人震惊的）。","ex":[["L'accident a été un grand choc pour lui.","这次事故对他是个大打击。"],["Le choc a été très violent.","撞击非常猛烈。"],["Elle est encore sous le choc.","她还没缓过神来。"]],"co":[["être sous le choc","还在震惊中"],["un choc culturel","文化冲击"],["un choc thermique","温度骤变"],["choc frontal","正面碰撞"]],"sy":[["coup","courant","打击、一下（比较泛）"],["traumatisme","soutenu","创伤；比 choc 更严重"],["collision","courant","（车辆等的）碰撞"]],"fq":"中高频，新闻和日常都常见。","me":"choc：像 chocolat 开头，一口咬下去的「冲击」。","tr":{"zh":"这个消息对她是个大冲击。","fr":"Cette nouvelle a été un grand choc pour elle.","alt":"Elle a eu un choc en apprenant la nouvelle.","note":"un choc pour + 人；avoir un choc = 受到冲击。"}},
 "Un classement": {"pos":"n.m. 阳性名词，复数 classements","s":"排名；排行榜；分类归档。体育、学校、榜单里都用：le classement général = 总排名。也可指把文件分门别类（le classement des documents）。","ipa":"[klas.mɑ̃]","ph":"cl 连读 [kl]；-ment 读鼻化的 [mɑ̃]，t 不发音；a 在 clas 里是 [a]。","pi":"结尾 -ment 不读 [mɛnt]，只读 [mɑ̃]；是阳性（-ment 结尾的名词多为阳性）。","et":"由动词 classer（分类）加后缀 -ment 构成；classe 来自拉丁语 classis。","ex":[["Son équipe est en tête du classement.","他的队伍排名第一。"],["Quel est le classement de ton école ?","你们学校排第几？"],["Je fais le classement de mes papiers.","我在整理我的文件。"]],"co":[["être en tête du classement","排名第一"],["le classement général","总排名"],["un classement mondial","世界排名"],["monter / descendre au classement","排名上升 / 下降"]],"sy":[["palmarès","soutenu","获奖名单；荣誉榜"],["hiérarchie","soutenu","等级体系"],["rang","courant","名次、位置"]],"fq":"中高频，体育和新闻里常见。","me":"classer + -ment：把大家按 classe 排好，就是 classement。","tr":{"zh":"我们队在排名里是第三。","fr":"Notre équipe est troisième au classement.","alt":"On est troisièmes au classement.","note":"au classement = 在排名中；序数词 troisième。"}},
 "Un élément": {"pos":"n.m. 阳性名词，复数 éléments","s":"要素；成分；元素；（情报中的）细节、线索。复数 des éléments 常指「资料、信息、证据」：manquer d'éléments = 缺少资料。","ipa":"[e.le.mɑ̃]","ph":"三个音节：é [e]、lé [le]、ment [mɑ̃]；-ment 的 t 不发音。","pi":"第一个 é 带重音，不要读成 [ə]；结尾是 [mɑ̃]，不是 [mɛnt]；开头元音前用 un 要注意 L'élément。","et":"来自拉丁语 elementum（基本成分）。同族：élémentaire（基础的）。","ex":[["J'ai besoin de plus d'éléments pour comprendre cette situation.","我需要更多信息才能理解这个情况。"],["L'eau est un élément essentiel.","水是一个基本要素。"],["Cet élève est un bon élément de l'équipe.","这个学生是队里的好成员。"]],"co":[["un élément important / clé","重要的 / 关键的要素"],["les éléments d'un dossier","一份材料中的各项资料"],["un élément nouveau","新情况、新线索"],["les quatre éléments","四大元素（水火土气）"]],"sy":[["composant","courant","（机器、系统的）组成部分"],["détail","courant","细节"],["information","courant","信息，比 élément 更泛"]],"fq":"高频，书面和口语都常用。","me":"élément ≈ 英语 element，只是重音符号和 -ment 结尾要记住。","tr":{"zh":"这个故事里有几个新情况。","fr":"Il y a plusieurs éléments nouveaux dans cette histoire.","alt":"Il y a du nouveau dans cette histoire.","note":"plusieurs éléments 用复数；nouveaux 修饰 éléments。"}},
 "Un extraterrestre": {"pos":"n.m. 阳性名词（也可作形容词），复数 extraterrestres","s":"外星人。口语里常缩成 un alien（英语借词）或 un E.T. 也作形容词：la vie extraterrestre = 外星生命。指女性时多说 une extraterrestre。","ipa":"[ɛk.stʁa.tɛ.ʁɛstʁ]","ph":"ex 读 [ɛks]；tr 读 [tʁ]，r 是小舌音 [ʁ]；结尾 -stre 轻轻带过，e 不发。","pi":"r 是喉部的 [ʁ]，不是中文的卷舌 r；词尾 -tre 的 e 不发音；注意两个 r 的发音。","et":"extra-（拉丁语，「在外」）+ terrestre（地球的，拉丁语 terra 土地、地球）。","ex":[["Ce film parle d'un extraterrestre.","这部电影讲一个外星人的故事。"],["Les extraterrestres arrivent sur Terre !","外星人来到地球了！"],["Crois-tu à la vie extraterrestre ?","你相信外星生命吗？"]],"co":[["un vaisseau d'extraterrestres","外星人的飞船"],["la vie extraterrestre","外星生命"],["une invasion d'extraterrestres","外星人入侵"]],"sy":[["alien","familier","外星人（英语借词，口语）"],["martien","courant","火星人；也泛指外星人"]],"fq":"中频，科幻话题里常用。","me":"extra（在外）+ terrestre（地球的）= 地球之外的人。","tr":{"zh":"孩子们在电影里看到一个外星人。","fr":"Les enfants voient un extraterrestre dans le film.","alt":"Dans le film, les enfants voient un extraterrestre.","note":"voir quelqu'un dans le film；extraterrestre 阳性名词。"}},
 "Un film d'animation": {"pos":"n.m. 阳性名词，复数 films d'animation","s":"动画电影。比 un dessin animé（卡通片，常指给孩子看的）更中性、更正式；也包括 3D 和定格动画。简称 un film d'animation，不用 un film animé。","ipa":"[film da.ni.ma.sjɔ̃]","ph":"film 读 [film]，结尾 lm 都要读；d'animation 里 d' 与后面连读 [da.ni…]；-tion 读 [sjɔ̃]。","pi":"film 不能读成 [fim]（l 要发）；-tion 读 [sjɔ̃]，不是 [ʃən]；复数只在 film 上加 s。","et":"film（英语借词）+ animation（拉丁语 anima 灵魂、生命，「赋予生命」）。","ex":[["Les enfants adorent ce film d'animation.","孩子们喜欢这部动画电影。"],["On regarde un film d'animation ce soir ?","今晚看部动画电影吗？"],["Ce film d'animation a gagné un prix.","这部动画电影得了奖。"]],"co":[["un film d'animation japonais","日本动画电影"],["un studio d'animation","动画工作室"],["un film d'animation en 3D","3D 动画电影"]],"sy":[["dessin animé","courant","卡通、动画片（常指给孩子看的）"],["animé","familier","日本动漫（口语，借自日语）"]],"fq":"中频，谈电影时常用。","me":"animation ← anima（灵魂）：给画面「注入生命」的电影。","tr":{"zh":"我想带孩子们去看动画电影。","fr":"Je veux emmener les enfants voir un film d'animation.","alt":"Je vais emmener les enfants voir un film d'animation.","note":"emmener quelqu'un + 动词原形（去做某事）。"}},
 "Un film d'auteur": {"pos":"n.m. 阳性名词，复数 films d'auteur","s":"作者电影；文艺片（由导演个人风格主导、偏艺术性的电影）。与 un film grand public（大众商业片）相对。","ipa":"[film do.tœʁ]","ph":"d'auteur 连起来读 [do.tœʁ]；au 读 [o]；eu 读 [œ]；结尾 r 读小舌音 [ʁ]。","pi":"au 读 [o]，不是 [au]；eu 读 [œ]，嘴形比 [ø] 开；结尾 r 要发。","et":"auteur 来自拉丁语 auctor（创造者、作者）。film d'auteur 是电影评论里的固定说法。","ex":[["J'adore regarder un bon film d'auteur.","我喜欢看好的文艺片。"],["Ce réalisateur ne fait que des films d'auteur.","这位导演只拍文艺片。"],["Ce film d'auteur passe au petit cinéma du quartier.","这部文艺片在街区的小电影院上映。"]],"co":[["un cinéma d'auteur","作者电影；艺术电影"],["un film d'auteur ou un blockbuster","文艺片还是商业大片"],["un réalisateur de films d'auteur","文艺片导演"]],"sy":[["film grand public","courant","大众片；与 film d'auteur 相反"],["blockbuster","courant","商业大片（英语借词）"],["film indépendant","courant","独立电影"]],"fq":"中频，谈电影时常用。","me":"auteur = 作者：这部电影有强烈的「个人签名」。","tr":{"zh":"我更喜欢文艺片，不喜欢大片。","fr":"Je préfère les films d'auteur aux blockbusters.","alt":"Moi, je préfère les films d'auteur, pas les gros blockbusters.","note":"préférer A à B = 喜欢 A 胜过 B。"}},
 "Un lexique": {"pos":"n.m. 阳性名词，复数 lexiques","s":"词汇表；词汇（某个领域或某位作者的全部用词）；书后的小词典。le lexique médical = 医学词汇。","ipa":"[lɛk.sik]","ph":"x 读 [ks]；qu 读 [k]；最后 -ique 读 [ik]，e 不发。","pi":"qu 读 [k]，不是 [kw]；x 读 [ks]，不要漏掉；是阳性，不是阴性。","et":"来自希腊语 lexikon（词的，与 lexis「词」有关）。同族：lexical（词汇的）。","ex":[["Le lexique du jeu vidéo contient beaucoup d'anglicismes.","电子游戏词汇里有很多英语借词。"],["Cherche ce mot dans le lexique à la fin du livre.","在书后的词汇表里查这个词。"],["Elle enrichit son lexique en lisant beaucoup.","她多读书来丰富自己的词汇量。"]],"co":[["enrichir son lexique","丰富词汇量"],["le lexique de la cuisine","烹饪词汇"],["un lexique français-anglais","法英词汇表"]],"sy":[["vocabulaire","courant","词汇；日常更常用"],["glossaire","soutenu","术语表"],["dictionnaire","courant","词典，更完整更大"]],"fq":"中频，学习和学术场合常见。","me":"lexique：词的「清单」，字母 x 像书页上的交叉记号。","tr":{"zh":"这本书后面有一个词汇表。","fr":"Il y a un lexique à la fin de ce livre.","alt":"À la fin du livre, il y a un petit lexique.","note":"il y a 引出存在；à la fin de + 名词。"}},
 "Un marin": {"pos":"n.m. 阳性名词，复数 marins","s":"水手；海员。也指海军士兵。形容词 marin(e) 表示「海的」：l'air marin = 海边空气。没有常用的阴性形式，女性多说 une marin 或 une marine（少见）。","ipa":"[ma.ʁɛ̃]","ph":"ma [ma]；rin 里 r 是小舌音 [ʁ]，in 读鼻化的 [ɛ̃]；结尾的 n 不发音。","pi":"结尾 in 读 [ɛ̃]，n 不发，不是 [ɪn]；与 marine（海军；阴性形容词，读 [ma.ʁin]）区分。","et":"来自拉丁语 marinus（海的），与 mer（海）同源。","ex":[["Le marin navigue sur l'océan.","水手在海洋上航行。"],["Son père était marin pêcheur.","他父亲以前是渔船海员。"],["Les marins reviennent au port.","水手们回到港口。"]],"co":[["un marin pêcheur","渔民海员"],["un vieux marin","老水手"],["un pull de marin","水手风格的毛衣"]],"sy":[["matelot","courant","普通水兵、船员"],["navigateur","courant","航海家、领航员"],["loup de mer","familier","老练的水手，老海狼"]],"fq":"中频，涉及海和船时常用。","me":"marin ← mer：靠海生活的人；结尾是鼻音 [ɛ̃]。","tr":{"zh":"水手每天都在海上工作。","fr":"Le marin travaille en mer tous les jours.","alt":"Le marin est en mer tous les jours.","note":"en mer = 在海上；tous les jours = 每天。"}},
 "Un monstre": {"pos":"n.m. 阳性名词，复数 monstres","s":"怪物；怪兽。也用来形容人：un monstre de travail = 工作狂；有时口语褒义，如 un monstre de talent = 天才。","ipa":"[mɔ̃stʁ]","ph":"on 读鼻化的 [ɔ̃]；s 要读 [s]；结尾 tre 轻读 [tʁ]，e 不发音。","pi":"s 要发音，不是 [mɔ̃.tʁ]；结尾 -tre 的 e 不发；是阳性，对女性也说 un monstre。","et":"来自拉丁语 monstrum（怪事、征兆）。同族：monstrueux（巨大的；可怕的）。","ex":[["L'enfant a peur du monstre sous son lit.","孩子害怕床下的怪物。"],["C'est un monstre de travail.","他是个工作狂。"],["Ce film est plein de monstres.","这部电影里满是怪物。"]],"co":[["un monstre marin","海怪"],["un monstre sacré","（艺术界的）泰斗、巨星"],["un monstre de + 名词","非常……的人"],["avoir peur des monstres","害怕怪物"]],"sy":[["créature","courant","生物；比 monstre 更中性"],["bête","courant","野兽、畜生"],["ogre","courant","童话里的食人魔"]],"fq":"中频，童话和电影里常见。","me":"monstre：想成 mon + stre，「我的怪物」藏在床下。","tr":{"zh":"他怕床下有怪物。","fr":"Il a peur qu'il y ait un monstre sous son lit.","alt":"Il croit qu'il y a un monstre sous son lit.","note":"avoir peur que + 虚拟式（qu'il y ait）。"}},
 "Un navire": {"pos":"n.m. 阳性名词，复数 navires","s":"船舶；大船。比 un bateau（泛指各种船）更正式，常指大型海船：un navire de guerre = 军舰，un navire marchand = 商船。","ipa":"[na.viʁ]","ph":"na [na]；vi [vi]；结尾 r 读小舌音 [ʁ]，要发。","pi":"v 是 [v]，不是 [w]；结尾 -re 读 [ʁ]，不要读成 [navir-ə]；注意与 un bateau 的用法差别。","et":"来自拉丁语 navigium（船、航行），与 navis（船）有关。同族：naviguer（航行）。","ex":[["Ce grand navire transporte des marchandises.","这艘大船运货物。"],["Le navire quitte le port demain matin.","这艘船明天早上离港。"],["Un navire de guerre est entré dans la rade.","一艘军舰驶入了港湾。"]],"co":[["un navire de guerre","军舰"],["un navire marchand","商船"],["monter à bord d'un navire","登上一艘船"],["un navire à voile","帆船（大型）"]],"sy":[["bateau","courant","船（最常用，泛指）"],["vaisseau","littéraire","舰、大船；也指宇宙飞船"],["paquebot","courant","远洋客轮"]],"fq":"中频，新闻和书面语中常见。","me":"navire ← naviguer：会「航行」的大家伙。","tr":{"zh":"这艘大船明天出发。","fr":"Ce grand navire part demain.","alt":"Ce gros navire part demain.","note":"partir = 出发；demain 放在句末。"}},
 "Un orchestre": {"pos":"n.m. 阳性名词，复数 orchestres","s":"乐团；管弦乐队；也指舞台前面的乐队席。un orchestre symphonique = 交响乐团。流行乐队多说 un groupe，一般不叫 orchestre。","ipa":"[ɔʁ.kɛstʁ]","ph":"or [ɔʁ]；ch 在这里读 [k]；结尾 -stre 读 [stʁ]，e 不发。","pi":"ch 读 [k]，不是 [ʃ]（希腊语来源的词）；r 是喉部的 [ʁ]；结尾 e 不发。","et":"来自希腊语 orkhêstra（舞台前供合唱队的位置），经拉丁语传入。","ex":[["L'orchestre symphonique va jouer ce soir.","交响乐团今晚演出。"],["Il joue du violon dans un orchestre.","他在一个乐团里拉小提琴。"],["Le chef d'orchestre lève les bras.","指挥举起了双臂。"]],"co":[["un chef d'orchestre","指挥"],["un orchestre symphonique","交响乐团"],["jouer dans un orchestre","在乐团里演奏"],["la fosse d'orchestre","乐池"]],"sy":[["groupe","courant","（流行音乐）乐队"],["fanfare","courant","铜管乐队、行进乐队"],["ensemble","soutenu","合奏团"]],"fq":"中频，音乐话题里常用。","me":"orchestre 里的 ch 读 [k]，和 chorale（合唱团）一样。","tr":{"zh":"我的姐姐在一个乐团里拉大提琴。","fr":"Ma sœur joue du violoncelle dans un orchestre.","alt":"Ma sœur est violoncelliste dans un orchestre.","note":"jouer de + 乐器；dans un orchestre。"}},
 "Un personnage": {"pos":"n.m. 阳性名词，复数 personnages","s":"人物；角色（小说、电影、游戏里的）；也指有分量的大人物（un grand personnage）。口语里 un drôle de personnage = 一个怪人。","ipa":"[pɛʁ.sɔ.naʒ]","ph":"per [pɛʁ]；son 在这里读 [sɔ]，不鼻化，因为后面有 n；结尾 -age 读 [aʒ]，e 不发。","pi":"sonn 里 on 不是鼻化音，读 [sɔ.naʒ]；是阳性（-age 结尾的名词多为阳性）；不是 personne（人；没有人）。","et":"personne + 后缀 -age；personne 来自拉丁语 persona（面具、角色）。","ex":[["Mon personnage préféré est le héros.","我最喜欢的角色是男主角。"],["Ce personnage est très drôle.","这个角色很搞笑。"],["C'est un personnage important de l'histoire.","他是历史上的重要人物。"]],"co":[["le personnage principal","主角"],["un personnage secondaire","配角"],["un personnage de roman / de film","小说里的 / 电影里的人物"],["un drôle de personnage","一个怪人"]],"sy":[["rôle","courant","（演员演的）角色"],["héros","courant","主人公；英雄"],["figure","soutenu","（知名）人物"]],"fq":"高频，谈故事、电影时常用。","me":"personnage = personne + -age：故事里的「人」。","tr":{"zh":"这个角色在整部电影里都很有趣。","fr":"Ce personnage est amusant dans tout le film.","alt":"Ce personnage est drôle pendant tout le film.","note":"dans tout le film = 在整部电影里。"}},
 "Un rapace": {"pos":"n.m. 阳性名词（也作形容词），复数 rapaces","s":"猛禽（老鹰、猫头鹰等捕食的鸟）。也可作形容词，意思是「贪婪的」（soutenu）：un animal rapace。","ipa":"[ʁa.pas]","ph":"r 是小舌音 [ʁ]；两个 a 都读 [a]；结尾 c 读 [s]。","pi":"结尾 -ce 读 [s]；r 是喉部的 [ʁ]，不是卷舌；注意不要与 rapide（快）混淆。","et":"来自拉丁语 rapax（贪婪的、抢夺的），源于 rapere（抢夺）。同族：rapt（绑架）。","ex":[["L'aigle est un oiseau rapace.","鹰是一种猛禽。"],["Un rapace tourne au-dessus du champ.","一只猛禽在田野上空盘旋。"],["Les rapaces ont de grandes serres.","猛禽有大而有力的爪子。"]],"co":[["un oiseau rapace","猛禽"],["un rapace nocturne","夜行猛禽（如猫头鹰）"],["un rapace diurne","日行猛禽（如鹰）"]],"sy":[["oiseau de proie","courant","猛禽；同义的说法"],["aigle","courant","鹰（rapace 的一种）"],["hibou","courant","猫头鹰"]],"fq":"中低频，自然、动物话题里出现。","me":"rapace ← rapere（抢夺）：像「抢」食物的鸟。","tr":{"zh":"我们在山上看见一只猛禽。","fr":"Nous avons vu un rapace dans la montagne.","alt":"On a vu un rapace dans la montagne.","note":"avons vu：voir 的复合过去时（avoir + vu）。"}},
 "Un récit": {"pos":"n.m. 阳性名词，复数 récits","s":"叙述；故事；讲述的内容。可以是真人的讲述（le récit d'un témoin），也可以是文学作品（un récit d'aventures）。比 une histoire 更书面。","ipa":"[ʁe.si]","ph":"ré [ʁe]；ci 读 [si]；结尾 t 不发音。","pi":"结尾 t 不发音，读 [ʁe.si]；é 要读 [e]；不是 recette（食谱），也不是 reçu（收据）。","et":"来自动词 réciter（讲述、背诵），拉丁语 recitare。同族：récitation（背诵）。","ex":[["Ce livre est un récit d'aventures passionnant.","这本书是一部引人入胜的冒险故事。"],["Le témoin fait le récit de l'accident.","目击者讲述事故的经过。"],["J'aime lire des récits de voyage.","我喜欢读游记。"]],"co":[["faire le récit de","讲述……的经过"],["un récit de voyage","游记"],["un récit d'aventures","冒险故事"],["un récit autobiographique","自传体叙述"]],"sy":[["histoire","courant","故事；也指历史，更口语"],["conte","courant","童话、民间故事"],["narration","soutenu","叙述（行为或手法）"]],"fq":"中频，书面语和文学话题常用。","me":"récit ← réciter：把事情一件一件「背」出来的故事。","tr":{"zh":"她给我们讲了她旅行的经过。","fr":"Elle nous a fait le récit de son voyage.","alt":"Elle nous a raconté son voyage.","note":"faire le récit de ≈ raconter（更书面）。"}},
 "Un rival": {"pos":"n.m. 阳性名词，复数 rivaux（阴性 une rivale）","s":"对手；竞争者（体育、爱情、事业上的）。阳性复数不规则：des rivaux，不是 rivals。","ipa":"[ʁi.val]","ph":"r 是小舌音 [ʁ]；i [i]；al 读 [al]，l 要发。","pi":"复数是 rivaux [ʁi.vo]，-al 变 -aux；单数结尾 l 要发音；阴性 rivale 读 [ʁi.val]。","et":"来自拉丁语 rivalis（共用同一条溪流 rivus 的人，引申为争夺者）。","ex":[["Il a battu son rival lors de la compétition.","他在比赛中击败了对手。"],["Ces deux entreprises sont rivales.","这两家公司是竞争对手。"],["Elle n'a pas de rival dans ce domaine.","她在这个领域没有对手。"]],"co":[["un rival sérieux","强劲的对手"],["sans rival","无与伦比"],["battre son rival","击败对手"],["des rivaux (pl.)","（复数）对手们"]],"sy":[["adversaire","courant","对手（比赛里）；比 rival 更中性"],["concurrent","courant","竞争者（商业里）"],["ennemi","courant","敌人，更强烈"]],"fq":"中频，体育、新闻常见。","me":"rival：-al → -aux，像 cheval → chevaux。","tr":{"zh":"他在决赛里遇到了他的对手。","fr":"Il a rencontré son rival en finale.","alt":"Il s'est retrouvé face à son rival en finale.","note":"en finale = 在决赛中；rencontrer = 遇见。"}},
 "Un terme": {"pos":"n.m. 阳性名词，复数 termes","s":"术语；词语；也指期限、终点（à court terme = 短期内）。复数 les termes 还可指（合同的）条款、措辞。","ipa":"[tɛʁm]","ph":"t [t]；e 读 [ɛ]；r 小舌音 [ʁ]；结尾 m [m]，都要发。","pi":"结尾的 rm 都要读，不是哑音；不要读成 [tɛʁ.mə]；不等于 terrain（场地）。","et":"来自拉丁语 terminus（边界、终点）。同族：terminer（结束）、terminal。","ex":[["Pouvez-vous expliquer les termes difficiles ?","您能解释一下这些难词吗？"],["Ce terme est très technique.","这个术语非常专业。"],["À long terme, c'est une bonne idée.","长远来看，这是个好主意。"]],"co":[["un terme technique","技术术语"],["à court / à long terme","短期内 / 长期来看"],["en d'autres termes","换句话说"],["mener à terme","完成、办成"]],"sy":[["mot","courant","词；比 terme 更日常"],["expression","courant","说法、短语"],["vocable","soutenu","词语（书面）"]],"fq":"高频，学习和工作中常用。","me":"terme ← terminus：词的「终点站」，正好定义一个概念。","tr":{"zh":"你能给我解释这个术语吗？","fr":"Peux-tu m'expliquer ce terme ?","alt":"Tu peux m'expliquer ce mot ?","note":"expliquer quelque chose à quelqu'un。"}},
 "Un trésor": {"pos":"n.m. 阳性名词，复数 trésors","s":"宝藏；珍宝；也用来亲昵称呼人：Mon trésor ! = 我的宝贝！le Trésor public = 国库、财政部门。","ipa":"[tʁe.zɔʁ]","ph":"tr [tʁ]；é [e]；s 在元音间读 [z]；结尾 or 读 [ɔʁ]。","pi":"s 读 [z]，不是 [s]；结尾 r 要发音；é 要读 [e]，不是 [ə]。","et":"来自拉丁语 thesaurus，再源于希腊语 thêsauros（宝库）。同族：thésauriser（积蓄）。","ex":[["Les pirates ont caché un trésor sur l'île.","海盗把宝藏藏在岛上。"],["Cet enfant est un vrai trésor.","这个孩子真是个宝贝。"],["Viens ici, mon trésor.","过来，我的宝贝。"]],"co":[["une chasse au trésor","寻宝游戏"],["une carte au trésor","藏宝图"],["un trésor national","国宝"],["mon trésor","我的宝贝（亲昵称呼）"]],"sy":[["richesse","courant","财富"],["bijou","courant","珠宝；也可指宝贝"],["chéri(e)","courant","亲爱的（称呼）"]],"fq":"中高频，故事和日常称呼里常用。","me":"trésor：s 读 [z]，听起来像「特累-zor」，一箱宝藏很重。","tr":{"zh":"孩子们在花园里找宝藏。","fr":"Les enfants cherchent un trésor dans le jardin.","alt":"Les enfants font une chasse au trésor dans le jardin.","note":"chercher + 直接宾语，不需要介词。"}},
 "Un tube (de peinture)": {"pos":"n.m. 阳性名词，复数 tubes","s":"管；（颜料、牙膏等的）软管：un tube de peinture / de dentifrice。口语里 un tube 还指「热门歌曲」（le tube de l'été = 夏日金曲）。","ipa":"[tyb]","ph":"u 读 [y]（圆唇的「于」）；结尾 b 读 [b]；e 不存在。","pi":"u 读 [y]，不是 [u]；不要读成英语的 /tjuːb/；意思上要与 tuyau（软管、水管）区分。","et":"来自拉丁语 tubus（管子）。同族：tuyau（水管）、tubulaire。","ex":[["J'ai acheté un nouveau tube de peinture rouge.","我买了一管新的红色颜料。"],["Il me faut un tube de dentifrice.","我需要一支牙膏。"],["Cette chanson est le tube de l'été.","这首歌是夏天的热门金曲。"]],"co":[["un tube de peinture / de colle","一管颜料 / 胶水"],["un tube de dentifrice","一支牙膏"],["le tube de l'été","夏日金曲"],["un tube à essai","试管"]],"sy":[["tuyau","courant","软管、水管"],["hit","familier","热门歌曲（英语借词）"],["succès","courant","成功；热门作品"]],"fq":"中高频，日常和音乐话题里都常见。","me":"tube：u 读「于」，嘴圆圆的像一根管子。","tr":{"zh":"我需要一管蓝色的颜料。","fr":"J'ai besoin d'un tube de peinture bleue.","alt":"Il me faut un tube de peinture bleue.","note":"avoir besoin de + 名词。"}},
 "Un vétéran": {"pos":"n.m. 阳性名词，复数 vétérans","s":"老兵；资深的人（职场、体育里的老手）。指女性可说 une vétérane。","ipa":"[ve.te.ʁɑ̃]","ph":"三个音节：vé [ve]、té [te]、ran [ʁɑ̃]；结尾 n 不发音，an 读鼻化 [ɑ̃]。","pi":"两个 é 都读 [e]，不是 [ə]；an 读 [ɑ̃]，结尾 n 不发；r 是小舌音 [ʁ]。","et":"来自拉丁语 veteranus（老兵），源于 vetus（老的）。","ex":[["Mon grand-père est un vétéran de la guerre.","我爷爷是战争老兵。"],["Ce joueur est un vétéran du club.","这位球员是俱乐部的老将。"],["Les vétérans défilent le 11 novembre.","老兵们在 11 月 11 日列队游行。"]],"co":[["un vétéran de la guerre","战争老兵"],["un vétéran du club","俱乐部的老将"],["un vétéran de l'armée","军队老兵"]],"sy":[["ancien combattant","courant","退伍军人"],["vieux routier","familier","老手、经验丰富的人"],["ancien","courant","老成员、前辈"]],"fq":"中低频，历史、新闻里出现。","me":"vétéran ≈ 英语 veteran，几乎同音，只是加了重音符号。","tr":{"zh":"我外公是一位老兵。","fr":"Mon grand-père est un vétéran.","alt":"Mon grand-père est un ancien combattant.","note":"职业或身份前不用冠词：est un vétéran 此处有形容修饰，要用 un。"}},
 "La foudre": {"pos":"n.f. 阴性名词，复数 foudres（少用）","s":"雷电；落雷（打在物体上的闪电）。指「闪电」的光用 un éclair；foudre 强调击中地面的雷击。也有比喻：un coup de foudre = 一见钟情。","ipa":"[fudʁ]","ph":"ou 读 [u]；dr 读 [dʁ]；结尾 e 不发音。","pi":"ou 读 [u]，不是 [o]；结尾 -dre 的 e 不发；是阴性，la foudre。","et":"来自拉丁语 fulgur（闪电）。同族：foudroyer（用雷击）、foudroyant（极快的、令人震惊的）。","ex":[["L'arbre a été frappé par la foudre.","树被雷击中了。"],["La foudre est tombée près de la maison.","雷落在房子附近。"],["Ils ont eu le coup de foudre.","他们一见钟情。"]],"co":[["être frappé par la foudre","被雷击中"],["un coup de foudre","一见钟情；晴天霹雳"],["un paratonnerre contre la foudre","防雷的避雷针"],["la foudre tombe","落雷"]],"sy":[["éclair","courant","闪电（光）"],["tonnerre","courant","雷声"],["orage","courant","雷暴"]],"fq":"中频，天气和比喻（一见钟情）都用。","me":"foudre ≈ fou（疯）+ dre：疯狂的一击；coup de foudre = 一见钟情。","tr":{"zh":"那棵树被雷击中了。","fr":"Cet arbre a été frappé par la foudre.","alt":"La foudre est tombée sur cet arbre.","note":"被动态 être frappé par；tomber sur = 落到……上。"}},
 "La noirceur": {"pos":"n.f. 阴性名词，复数 noirceurs（少用）","s":"黑暗；漆黑；比喻上的阴暗、险恶（人性、故事的黑暗面）。la noirceur de l'âme = 心灵的阴暗。","ipa":"[nwaʁ.sœʁ]","ph":"oi 读 [wa]；r 小舌音 [ʁ]；c 在 e 前读 [s]；eur 读 [œʁ]。","pi":"oi 读 [wa]，不是 [oi]；-eur 读 [œʁ]，r 要发；-eur 结尾的抽象名词多是阴性（la noirceur, la douceur）。","et":"noir（黑）+ 后缀 -eur（构成抽象名词）；noir 来自拉丁语 niger。","ex":[["Il a peur de la noirceur de la nuit.","他害怕夜晚的黑暗。"],["Ce film montre la noirceur du monde.","这部电影展现了世界的阴暗面。"],["On ne voit rien dans cette noirceur.","这么黑什么也看不见。"]],"co":[["la noirceur de la nuit","夜的漆黑"],["la noirceur de l'âme","心灵的阴暗"],["la noirceur d'un roman","一部小说的阴暗基调"]],"sy":[["obscurité","courant","昏暗；一般的黑暗"],["ténèbres","littéraire","黑暗（文学色彩）"],["noir","courant","黑暗（la nuit noire）"]],"fq":"中低频，文学和评论里更多见。","me":"noir + -eur：noirceur 就是「黑的程度」。","tr":{"zh":"他不喜欢这个故事的阴暗。","fr":"Il n'aime pas la noirceur de cette histoire.","alt":"Cette histoire est trop noire pour lui.","note":"la noirceur de + 名词；否定 ne… pas。"}},
 "La tête d'affiche": {"pos":"n.f. 阴性名词，复数 têtes d'affiche","s":"主打艺人；压轴人物；演出海报上名字排第一的人。也可比喻为在某个活动里最受瞩目的人或物。","ipa":"[tɛt da.fiʃ]","ph":"tête 读 [tɛt]，ê 读 [ɛ]；d'affiche 里 d' 与后面连读 [da.fiʃ]；ch 读 [ʃ]。","pi":"tête 的 ê 读 [ɛ]，结尾 te 读 [t]；注意 d' 的省音，不是 de；affiche 的 ch 读 [ʃ]。","et":"tête（头，拉丁语 testa 本义是陶罐）+ affiche（海报，源于 afficher 张贴）。「海报上排第一的人」。","ex":[["Ce groupe de rock est la tête d'affiche du festival.","这支摇滚乐队是音乐节的主打。"],["Elle est la tête d'affiche du spectacle.","她是这场演出的主角。"],["Qui sera en tête d'affiche cette année ?","今年谁来压轴？"]],"co":[["être en tête d'affiche","做主打、压轴"],["la tête d'affiche du festival","音乐节的主打艺人"],["une tête d'affiche internationale","国际大牌"]],"sy":[["star","courant","明星"],["vedette","courant","主角、明星（vedette 是阴性名词）"],["headliner","familier","主唱嘉宾（英语借词）"]],"fq":"中频，演出和节庆话题里常见。","me":"tête d'affiche = 海报上「排在最前面」的那个人。","tr":{"zh":"这位歌手是音乐节的主打。","fr":"Cette chanteuse est la tête d'affiche du festival.","alt":"C'est elle, la tête d'affiche du festival.","note":"la tête d'affiche 是阴性名词，即使指男性也用 la。"}},
 "Une troupe (de théâtre)": {"pos":"n.f. 阴性名词，复数 troupes","s":"剧团；一队人。une troupe de théâtre = 剧团；也指军队、部队（les troupes），或一群人（une troupe d'enfants）。","ipa":"[tʁup]","ph":"tr [tʁ]；ou 读 [u]；结尾 pe 读 [p]，e 不发。","pi":"ou 读 [u]，不是 [o]；结尾 p 要读，e 不发；不要与 troupeau（牲畜群）混淆。","et":"来自古法语 trope，可能源于日耳曼语。同族：troupeau（兽群）、attrouper（聚集）；细节不完全确定。","ex":[["Cette troupe de théâtre est très célèbre.","这个剧团很有名。"],["La troupe joue ce week-end.","剧团这个周末演出。"],["Une troupe d'enfants traverse la rue.","一群孩子穿过街道。"]],"co":[["une troupe de théâtre","剧团"],["une troupe de danse","舞团"],["une troupe d'acteurs","一队演员"],["les troupes","部队"]],"sy":[["compagnie","courant","剧团；公司"],["équipe","courant","团队"],["bande","familier","一伙人"]],"fq":"中频，戏剧和军事话题里出现。","me":"troupe：「剧团」和「部队」都是一队同行的人。","tr":{"zh":"这个剧团明天在我们的城市演出。","fr":"Cette troupe de théâtre joue demain dans notre ville.","alt":"La troupe joue demain chez nous.","note":"jouer 也指「演出」；dans notre ville = 在我们的城市。"}},
 "Une bande annonce": {"pos":"n.f. 阴性名词，复数 bandes annonces","s":"预告片。常写作 une bande-annonce（带连字符），复数 des bandes-annonces。可用于电影、电视剧、游戏。","ipa":"[bɑ̃d a.nɔ̃s]","ph":"bande 读 [bɑ̃d]，an 鼻化；annonce 读 [a.nɔ̃s]，nn 读一个 [n]，on 鼻化；c 读 [s]。","pi":"annonce 里 nn 只发一个 [n]，on 要鼻化；两个词之间轻轻连读，不用停顿；是阴性。","et":"bande（带子、胶片卷）+ annonce（预告，源自 annoncer，拉丁语 annuntiare）。","ex":[["J'ai vu la bande annonce du nouveau film.","我看了新电影的预告片。"],["La bande annonce donne envie de voir le film.","预告片让人想去看这部电影。"],["Tu as regardé la bande annonce ?","你看预告片了吗？"]],"co":[["regarder la bande annonce","看预告片"],["sortir une bande annonce","发布预告片"],["la bande annonce d'un film / d'un jeu","电影 / 游戏的预告片"]],"sy":[["trailer","familier","预告片（英语借词）"],["teaser","familier","（更短的）预告（英语借词）"],["extrait","courant","片段、节选"]],"fq":"中高频，谈电影、游戏时常用。","me":"bande（胶片）+ annonce（预告）= 先「宣布」的那一卷片。","tr":{"zh":"这部电影的预告片很有意思。","fr":"La bande annonce de ce film est très intéressante.","alt":"La bande annonce de ce film donne envie.","note":"donner envie = 令人想要。"}},
 "Une brosse, un pinceau": {"pos":"une brosse：n.f. 阴性名词，复数 brosses；un pinceau：n.m. 阳性名词，复数 pinceaux","s":"brosse 是刷子（毛较硬的：brosse à dents 牙刷、brosse à cheveux 梳子、刷衣服的刷子）；pinceau 是画笔、刷漆的刷子（毛较软、更细）。画画用 un pinceau，刷灰尘或打扫用 une brosse。","ipa":"[bʁɔs], [pɛ̃.so]","ph":"brosse：br [bʁ]，o 读开口 [ɔ]，ss 读 [s]；pinceau：in 读 [ɛ̃]，c 读 [s]，eau 读 [o]。","pi":"pinceau 复数是 pinceaux（-eau 加 x）；pin 读 [pɛ̃]，不是 [pin]；brosse 的 o 比 beau 的 eau 更开。","et":"pinceau 来自拉丁语 penicillum（小尾巴，指小刷子）；brosse 的来源不完全确定。","ex":[["J'ai besoin d'une brosse et d'un pinceau pour peindre.","我需要刷子和画笔来画画。"],["Passe un coup de brosse sur tes chaussures.","用刷子刷一下你的鞋。"],["Le peintre lave son pinceau.","画家在洗他的画笔。"]],"co":[["une brosse à dents / à cheveux","牙刷 / 梳子"],["un pinceau fin / large","细画笔 / 宽画笔"],["donner un coup de pinceau","刷一笔"],["une brosse à habits","衣刷"]],"sy":[["balai","courant","扫帚"],["spatule","courant","刮刀；画刀"],["rouleau","courant","滚筒刷"]],"fq":"中高频，生活和绘画话题里常用。","me":"brosse（硬）刷东西，pinceau（软）画画；pinceau → 英语 pencil。","tr":{"zh":"我用画笔画画，用刷子刷鞋子。","fr":"Je peins avec un pinceau et je nettoie mes chaussures avec une brosse.","alt":"Je peins au pinceau et je brosse mes chaussures.","note":"peindre avec / à + 工具；le pinceau 是阳性，la brosse 是阴性。"}},
 "Une butte": {"pos":"n.f. 阴性名词，复数 buttes","s":"土丘；小山丘。也有短语 être en butte à = 遭受（批评、攻击等）。巴黎有一处著名的丘陵叫 Montmartre，别称 la butte。","ipa":"[byt]","ph":"u 读 [y]（圆唇的「于」）；tt 读一个 [t]；结尾 e 不发。","pi":"u 读 [y]，不是 [u]；tt 只发一个 [t]；不要与 but（目的）、beurre（黄油）混淆。","et":"来自古法语 but，来源不确定（可能与日耳曼语有关），不要乱猜。","ex":[["Ils ont construit leur maison sur une petite butte.","他们在一个小土丘上建了房子。"],["Du haut de la butte, on voit toute la ville.","从丘顶可以看到整座城市。"],["Les enfants montent sur la butte pour jouer.","孩子们爬上土丘玩耍。"]],"co":[["une butte de terre","土堆"],["la butte Montmartre","蒙马特高地"],["être en butte à","遭受（批评等）"],["une butte témoin","（地理）孤丘、残丘"]],"sy":[["colline","courant","山丘，比 butte 大"],["monticule","courant","小土堆"],["tertre","soutenu","小丘（书面）"]],"fq":"中低频，描写风景时出现。","me":"butte：一小块「突起」，写时别忘了 tt。","tr":{"zh":"他们的房子建在一个小土丘上。","fr":"Leur maison est construite sur une petite butte.","alt":"Ils ont leur maison sur une petite butte.","note":"être construit(e) sur = 建在……上。"}},
 "Une console": {"pos":"n.f. 阴性名词，复数 consoles","s":"游戏机（une console de jeux）；控制台、操作台；也指靠墙的小桌（console 家具）。与 consoler（安慰）无直接联系。","ipa":"[kɔ̃.sɔl]","ph":"con 读鼻化的 [kɔ̃]；so 读 [sɔ]；结尾 l 要读。","pi":"con 里 on 鼻化 [ɔ̃]，不读 [kon]；第二个 o 读 [ɔ]，后面的 l 要发。","et":"来自动词 consoler（撑住）这一路说法，不确定；游戏机义来自英语 game console 的影响。来源不确定。","ex":[["Il joue souvent à sa console de jeux.","他常玩他的游戏机。"],["Cette console est très populaire chez les jeunes.","这台游戏机在年轻人中很受欢迎。"],["Je branche la console sur la télé.","我把游戏机接到电视上。"]],"co":[["une console de jeux","游戏机"],["jouer sur console","玩主机游戏"],["une console portable","掌上游戏机"],["brancher la console","接上游戏机"]],"sy":[["manette","courant","游戏手柄（console 的配件）"],["ordinateur","courant","电脑；对比主机游戏"],["pupitre","courant","控制台、讲台"]],"fq":"中高频，游戏和科技话题里常用。","me":"console：con + sole，想成「康-搜」手上拿着手柄。","tr":{"zh":"我们晚上玩游戏机。","fr":"Le soir, nous jouons sur la console.","alt":"Le soir, on joue à la console.","note":"jouer à la console 或 jouer sur console 都可以。"}},
 "Une gifle": {"pos":"n.f. 阴性名词，复数 gifles","s":"耳光；巴掌。也可比喻成「侮辱、打击」：une gifle pour lui = 对他是一记耳光。动词是 gifler。","ipa":"[ʒifl]","ph":"g 在 i 前读 [ʒ]；i [i]；fl 读 [fl]，结尾 e 不发音。","pi":"g 读 [ʒ]，不是 [g]；结尾 -fle 的 e 不发音；是阴性，une gifle。","et":"可能来自日耳曼语，指脸颊、下巴；来源不完全确定。同族：gifler（打耳光）。","ex":[["Il lui a donné une gifle.","他打了他一个耳光。"],["Elle a reçu une gifle.","她挨了一个耳光。"],["Cette défaite est une vraie gifle.","这次失败是一记真正的耳光。"]],"co":[["donner une gifle à quelqu'un","给某人一个耳光"],["recevoir une gifle","挨耳光"],["une gifle pour + 人","对……是一记耳光（打击）"],["gifler quelqu'un","打某人耳光"]],"sy":[["claque","familier","巴掌；更口语"],["baffe","familier","耳光（口语）"],["soufflet","littéraire","耳光（书面语）"]],"fq":"中频，动作和比喻里都常用。","me":"gifle：g 读「日」，一巴掌下去，f 像声音「啪」。","tr":{"zh":"她给了他一个耳光，然后走了。","fr":"Elle lui a donné une gifle, puis elle est partie.","alt":"Elle lui a mis une gifle et elle est partie.","note":"donner / mettre une gifle à quelqu'un。"}},
 "Une industrie": {"pos":"n.f. 阴性名词，复数 industries","s":"工业；产业；行业。une industrie lourde = 重工业；l'industrie du cinéma = 电影业。不指「勤奋」（旧义，现已很少用）。","ipa":"[ɛ̃.dys.tʁi]","ph":"in 读鼻化的 [ɛ̃]；dus 读 [dys]，u 是 [y]；tr 读 [tʁ]；i [i]。","pi":"in 读 [ɛ̃]；u 读 [y]，不是 [u]；重音在最后一个音节 -trie；和英语 industry 不同，词尾要读 [tʁi]。","et":"来自拉丁语 industria（勤奋、技艺）。同族：industriel（工业的）、industrialiser。","ex":[["L'industrie du cinéma est colossale.","电影产业规模巨大。"],["Cette ville vit de l'industrie automobile.","这个城市靠汽车工业生活。"],["L'industrie lourde pollue beaucoup.","重工业污染很重。"]],"co":[["l'industrie automobile","汽车工业"],["l'industrie du cinéma / du jeu vidéo","电影业 / 电子游戏业"],["l'industrie lourde / légère","重工业 / 轻工业"],["une industrie de pointe","尖端产业"]],"sy":[["secteur","courant","部门、行业"],["usine","courant","工厂"],["fabrication","courant","制造"]],"fq":"高频，新闻和经济话题里常用。","me":"industrie ≈ industry：把 y 换成 -ie。","tr":{"zh":"汽车工业在这个地区很重要。","fr":"L'industrie automobile est importante dans cette région.","alt":"Dans cette région, l'industrie automobile compte beaucoup.","note":"dans cette région = 在这个地区。"}},
 "Une ludothèque": {"pos":"n.f. 阴性名词，复数 ludothèques","s":"玩具图书馆；游戏图书馆（可以借玩具和桌游，或在现场玩）。主要给孩子和家庭，市镇常有。","ipa":"[ly.dɔ.tɛk]","ph":"lu 读 [ly]，u 是 [y]；do 读 [dɔ]；thè 读 [tɛ]，th 读 [t]；结尾 que 读 [k]。","pi":"u 读 [y]，不是 [u]；th 读 [t]，不是 [θ]；和 bibliothèque 一样，-thèque 读 [tɛk]。","et":"拉丁语 ludus（游戏）+ 希腊语 thêkê（存放处）。仿照 bibliothèque（图书馆）构成。","ex":[["Nous allons emprunter des jeux à la ludothèque.","我们去玩具图书馆借游戏。"],["La ludothèque est ouverte le mercredi.","玩具图书馆星期三开放。"],["Mes enfants adorent la ludothèque.","我的孩子们很喜欢玩具图书馆。"]],"co":[["emprunter un jeu à la ludothèque","从玩具图书馆借一个游戏"],["une ludothèque municipale","市立玩具图书馆"],["aller à la ludothèque","去玩具图书馆"]],"sy":[["bibliothèque","courant","图书馆；ludothèque 是它的游戏版"],["médiathèque","courant","多媒体资料馆"],["magasin de jouets","courant","玩具店"]],"fq":"低频，家庭、儿童活动话题里出现。","me":"ludo（游戏）+ thèque（馆）= 游戏馆；ludo 也是玩棋类游戏的名字。","tr":{"zh":"周六我们去玩具图书馆玩游戏。","fr":"Samedi, nous allons jouer à la ludothèque.","alt":"Samedi, on va jouer à la ludothèque.","note":"samedi 前不加冠词表示「这个星期六」；jouer à + 游戏 / 地点活动。"}},
 "Une médiatisation": {"pos":"n.f. 阴性名词，复数 médiatisations","s":"媒体曝光；媒体化。指一件事或一个人被媒体大量报道。une forte médiatisation = 受到大量媒体关注。","ipa":"[me.dja.ti.za.sjɔ̃]","ph":"五个音节：mé [me]、dia [dja]、ti [ti]、sa [za]、tion [sjɔ̃]；s 在元音间读 [z]。","pi":"s 读 [z]，不是 [s]；-tion 读 [sjɔ̃]；di 与 a 合成 [dja]；词长，要分音节慢读。","et":"média（媒体，拉丁语 medium 的复数 media）+ -iser（使……化）+ -ation（名词后缀）。","ex":[["Ce film a bénéficié d'une grande médiatisation.","这部电影得到了大量媒体报道。"],["La médiatisation de cette affaire est énorme.","这件事的媒体曝光度极大。"],["Il n'aime pas la médiatisation.","他不喜欢被媒体关注。"]],"co":[["une forte médiatisation","大量的媒体曝光"],["la médiatisation d'un événement","一个事件的媒体曝光"],["bénéficier d'une médiatisation","得到媒体关注"],["médiatiser une affaire","让一件事成为媒体焦点"]],"sy":[["couverture médiatique","courant","媒体报道；更口语"],["publicité","courant","宣传；广告"],["exposition","courant","曝光、展出"]],"fq":"中频，新闻和评论里常见。","me":"média + -iser + -ation：让某事成为「媒体的」一个过程。","tr":{"zh":"这个事件得到了大量媒体曝光。","fr":"Cet événement a eu une grande médiatisation.","alt":"Cet événement a été très médiatisé.","note":"médiatiser 的过去分词 médiatisé 可用于被动。"}},
 "Une morsure": {"pos":"n.f. 阴性名词，复数 morsures","s":"咬伤；咬痕。une morsure de serpent / de chien = 蛇咬 / 狗咬。也可指寒冷的「刺痛」（la morsure du froid）。动词是 mordre。","ipa":"[mɔʁ.syʁ]","ph":"mor 读 [mɔʁ]；su 读 [sy]，u 是 [y]；结尾 r 读 [ʁ]，e 不发。","pi":"u 读 [y]，不是 [u]；两个 r 都是喉部的 [ʁ]；-ure 读 [yʁ]，不读 [yʁə]。","et":"mordre（拉丁语 mordere）+ 后缀 -ure。同族：mordre（咬）、remords（悔恨）。","ex":[["La morsure de ce serpent est mortelle.","这条蛇的咬伤是致命的。"],["Le chien m'a fait une morsure à la jambe.","狗咬了我的腿。"],["Il sent la morsure du froid.","他感到寒冷刺骨。"]],"co":[["une morsure de serpent / de chien","蛇咬 / 狗咬"],["la morsure du froid","寒冷刺骨"],["soigner une morsure","处理咬伤"],["une morsure profonde","很深的咬伤"]],"sy":[["piqûre","courant","（昆虫、针）刺伤"],["blessure","courant","伤口"],["coup de dent","familier","一口咬（口语）"]],"fq":"中频，健康、动物话题里常见。","me":"morsure ← mordre：咬 + -ure。","tr":{"zh":"这条蛇的咬伤很危险。","fr":"La morsure de ce serpent est dangereuse.","alt":"Ce serpent a une morsure dangereuse.","note":"la morsure de + 动物。"}},
 "Une palette": {"pos":"n.f. 阴性名词，复数 palettes","s":"调色板；一系列颜色（une palette de couleurs）；也指托盘（货物用的木托盘）。比喻：une large palette de choix = 丰富的选择。","ipa":"[pa.lɛt]","ph":"pa [pa]；le 读 [lɛ]；tt 读一个 [t]；结尾 e 不发。","pi":"tt 读一个 [t]；le 里 e 读 [ɛ]，不是 [ə]；不要与 pellet 或 pelle（铲子）混淆。","et":"pale（小铲，拉丁语 pala）+ 后缀 -ette，本义是小铲状的板。","ex":[["L'artiste mélange les couleurs sur sa palette.","艺术家在调色板上调色。"],["Ce peintre utilise une palette très claire.","这位画家用的色调很明亮。"],["Le magasin propose une large palette de produits.","这家商店提供种类丰富的产品。"]],"co":[["une palette de couleurs","一组色彩、色调"],["mélanger sur la palette","在调色板上调色"],["une palette de graphiques","图形调色板"],["une large palette de choix","丰富的选择"]],"sy":[["gamme","courant","系列、范围"],["éventail","soutenu","（选择的）范围"],["nuancier","courant","色卡"]],"fq":"中频，绘画和日常比喻里都有。","me":"palette：像一块小「铲子」，用来拿颜色。","tr":{"zh":"画家在调色板上混合颜色。","fr":"Le peintre mélange les couleurs sur sa palette.","alt":"Le peintre mélange ses couleurs sur la palette.","note":"sur sa palette = 在他的调色板上。"}},
 "Une part": {"pos":"n.f. 阴性名词，复数 parts","s":"一份；份额；一块（蛋糕、披萨）。une part de gâteau = 一块蛋糕。也出现在固定短语里：pour ma part = 就我来说，à part = 除……之外。","ipa":"[paʁ]","ph":"a 读 [a]；r 读小舌音 [ʁ]；结尾 t 不发音。","pi":"结尾 t 不发音，读 [paʁ]；与 part（partir 的变位）同音同形；与 un part 不是一个词，要认清阴性 la part。","et":"来自拉丁语 pars（部分）。同族：partie（部分）、partager（分享）、départ、partenaire。","ex":[["Les femmes constituent une part importante des joueurs.","女性占玩家的很大一部分。"],["Je prends une part de gâteau.","我拿一块蛋糕。"],["Pour ma part, je préfère le thé.","就我而言，我更喜欢茶。"]],"co":[["une part de gâteau / de pizza","一块蛋糕 / 披萨"],["pour ma part","就我而言"],["faire sa part","尽自己的一份力"],["prendre part à","参加"]],"sy":[["portion","courant","一人份、份量"],["morceau","courant","一块"],["partie","courant","部分；强调整体里的一部分"]],"fq":"极高频，日常常用。","me":"part ← pars：一份就是整体的「一部分」。","tr":{"zh":"你想要一块蛋糕吗？","fr":"Tu veux une part de gâteau ?","alt":"Tu prends une part de gâteau ?","note":"une part de + 食物 = 一块……。"}},
 "Une prison": {"pos":"n.f. 阴性名词，复数 prisons","s":"监狱；牢房。envoyer en prison = 送进监狱；aller en prison = 坐牢。比喻也可说「囚笼」（la prison dorée = 金色的牢笼）。","ipa":"[pʁi.zɔ̃]","ph":"pr [pʁ]；i [i]；s 在元音间读 [z]；on 读鼻化的 [ɔ̃]，结尾 n 不发。","pi":"s 读 [z]，不是 [s]；结尾 on 读 [ɔ̃]，n 不发；是阴性，une prison。","et":"来自拉丁语 prehensio（抓住），经古法语 prison。同族：prisonnier（囚犯）、emprisonner。","ex":[["Le voleur a été envoyé en prison.","小偷被送进了监狱。"],["Il est sorti de prison hier.","他昨天出狱了。"],["Cette maison est comme une prison.","这房子像一座牢笼。"]],"co":[["aller / être en prison","坐牢 / 在监狱里"],["envoyer quelqu'un en prison","把某人送进监狱"],["sortir de prison","出狱"],["une peine de prison","徒刑"]],"sy":[["geôle","littéraire","牢房（文学用语）"],["taule","argot","牢房（俚语）"],["cachot","courant","地牢、禁闭室"]],"fq":"高频，新闻和日常对话里常用。","me":"prison：s 读 [z]，听起来像「普里-松」，一个封闭的地方。","tr":{"zh":"他因为偷东西被送进了监狱。","fr":"Il a été envoyé en prison parce qu'il a volé.","alt":"Il est allé en prison pour vol.","note":"en prison 不加冠词；pour vol = 因偷窃。"}},
 "Une réflexion": {"pos":"n.f. 阴性名词，复数 réflexions","s":"思考；反思；看法；也指（光、镜子的）反射。après réflexion = 想了想之后；faire une réflexion = 发表一句评论（有时带批评）。","ipa":"[ʁe.flɛk.sjɔ̃]","ph":"ré [ʁe]；fle 读 [flɛ]；x 读 [ks]；-tion 在这里是 -xion，读 [ksjɔ̃]。","pi":"拼写是 -xion，不是 -ction（对比英语 reflection）；x 读 [ks]；é 读 [e]。","et":"来自拉丁语 reflexio，源于 reflectere（折回）。同族：réfléchir（思考）、reflet（倒影）。","ex":[["Ce roman offre une réflexion sur la noirceur humaine.","这部小说引发对人性黑暗面的思考。"],["Après réflexion, j'accepte.","想了想之后，我接受。"],["Il m'a fait une réflexion sur mon retard.","他就我迟到的事说了我两句。"]],"co":[["après réflexion","考虑之后"],["donner matière à réflexion","令人深思"],["faire une réflexion","发表评论、说两句"],["la réflexion de la lumière","光的反射"]],"sy":[["pensée","courant","想法、思想"],["remarque","courant","评论、意见"],["méditation","soutenu","沉思"]],"fq":"高频，学习和讨论中常用。","me":"réflexion：想一想，让思绪像光一样「折回来」。","tr":{"zh":"我需要一点时间考虑一下。","fr":"J'ai besoin d'un peu de temps de réflexion.","alt":"Laisse-moi un peu de temps pour réfléchir.","note":"temps de réflexion = 考虑的时间。"}},
 "Une vengeance": {"pos":"n.f. 阴性名词，复数 vengeances","s":"复仇；报复。se venger = 报仇；par vengeance = 出于报复。谚语 La vengeance est un plat qui se mange froid 意为「复仇要沉住气，等时机」。","ipa":"[vɑ̃.ʒɑ̃s]","ph":"van 读 [vɑ̃]；ge 在这里读 [ʒ]；ance 读 [ɑ̃s]；an 都鼻化。","pi":"an 读 [ɑ̃]，不读 [an]；g 读 [ʒ]；c 读 [s]，结尾 e 不发。","et":"来自动词 venger（拉丁语 vindicare，「主张权利、报复」）。同族：se venger、vengeur。","ex":[["La vengeance est un plat qui se mange froid.","仇要冷着吃（复仇宜缓）。"],["Il agit par vengeance.","他出于报复而行动。"],["Elle rêve de vengeance.","她梦想着复仇。"]],"co":[["par vengeance","出于报复"],["assouvir sa vengeance","满足复仇心"],["une vengeance personnelle","个人恩怨的复仇"],["se venger de quelqu'un","向某人报仇"]],"sy":[["revanche","courant","扳回一局；报复"],["représailles","soutenu","报复措施（多复数）"],["rancune","courant","怨恨"]],"fq":"中频，故事和新闻里常见。","me":"vengeance ← venger：van-jans，想成 ven + 报复。","tr":{"zh":"他想为兄弟复仇。","fr":"Il veut se venger pour son frère.","alt":"Il cherche à venger son frère.","note":"venger quelqu'un = 为某人报仇；se venger de = 向……报复。"}},
 "Une victime": {"pos":"n.f. 阴性名词，复数 victimes（男女都用 une victime）","s":"受害者；遇难者。即使受害者是男性，也只用阴性：Il est une victime，常说 C'est une victime。不说 un victime。","ipa":"[vik.tim]","ph":"vic 读 [vik]；c 读 [k]；time 读 [tim]；结尾 e 不发。","pi":"永远是阴性，哪怕指男性；c 要读 [k]；不是 [viktaim]。","et":"来自拉丁语 victima（祭祀的牺牲）。","ex":[["La victime a été transportée à l'hôpital.","受害者被送往医院。"],["Il est la victime d'un vol.","他是一起盗窃案的受害者。"],["Il y a eu plusieurs victimes dans l'accident.","事故中有好几名受害者。"]],"co":[["être victime de","成为……的受害者"],["une victime innocente","无辜的受害者"],["faire des victimes","造成伤亡"],["jouer les victimes","装可怜"]],"sy":[["blessé(e)","courant","伤者"],["sinistré(e)","courant","灾民"],["martyr(e)","soutenu","殉难者；受难者"]],"fq":"高频，新闻里极常见。","me":"victime：永远阴性，哪怕受害者是男性。","tr":{"zh":"他是这起事故的受害者。","fr":"Il est la victime de cet accident.","alt":"Il a été victime de cet accident.","note":"être victime de + 名词，常不加冠词。"}},
 "Amateur": {"pos":"n.m./n.f. 名词，复数 amateurs（阴性可说 une amatrice，更常用 une amateur）","s":"爱好者；业余者。amateur de cinéma = 电影爱好者。也作形容词：业余的（un joueur amateur）。有时带轻微贬义，指不够专业。","ipa":"[a.ma.tœʁ]","ph":"三个音节：a [a]、ma [ma]、teur [tœʁ]；eur 读 [œʁ]，r 要发。","pi":"结尾 eur 读 [œʁ]，r 要发音；不要读成英语的 amateur；强调爱好者时常用 amateur de + 名词。","et":"来自拉丁语 amator（爱的人），源于 amare（爱）。同族：aimer、amour。","ex":[["Les amateurs de cinéma aiment ce festival.","电影爱好者喜欢这个电影节。"],["Il joue au foot en amateur.","他业余踢足球。"],["Je suis amateur de musique classique.","我喜欢古典音乐。"]],"co":[["amateur de + 名词","……的爱好者"],["en amateur","以业余身份"],["un photographe amateur","业余摄影师"],["une équipe amateur","业余队伍"]],"sy":[["passionné(e)","courant","狂热爱好者"],["professionnel(le)","courant","专业人士（反义）"],["dilettante","soutenu","三分钟热度的爱好者"]],"fq":"高频，日常常用。","me":"amateur ← amare：爱某件事的人。","tr":{"zh":"我是电影爱好者，每周都去电影院。","fr":"Je suis amateur de cinéma et je vais au cinéma chaque semaine.","alt":"Je suis un grand amateur de cinéma, j'y vais toutes les semaines.","note":"être amateur de + 名词；chaque semaine = 每周。"}},
 "Des applaudissements": {"pos":"n.m.pl. 阳性复数名词（单数 un applaudissement 少用）","s":"掌声。几乎总用复数：des applaudissements, sous les applaudissements。动词是 applaudir（鼓掌）。","ipa":"[a.plo.dis.mɑ̃]","ph":"ap 读 [a.p]；plau 读 [plo]；dis 读 [dis]；ment 读 [mɑ̃]，结尾 s 不发。","pi":"au 读 [o]；pp 前的 p 只读一次；结尾 -ments 读 [mɑ̃]，ts 不发；注意只有一个 l 在 applaudir。","et":"来自动词 applaudir（拉丁语 applaudere）加后缀 -ment。","ex":[["L'acteur a reçu beaucoup d'applaudissements.","演员得到了很多掌声。"],["La salle éclate en applaudissements.","大厅里响起了热烈的掌声。"],["Merci pour vos applaudissements !","谢谢大家的掌声！"]],"co":[["sous les applaudissements","在掌声中"],["recevoir des applaudissements","收到掌声"],["éclater en applaudissements","掌声雷动"],["un tonnerre d'applaudissements","雷鸣般的掌声"]],"sy":[["ovation","soutenu","热烈欢呼；起立鼓掌"],["acclamations","soutenu","欢呼声"],["bravos","courant","喝彩声"]],"fq":"中频，演出和场合里常用。","me":"applaudir → applaudissements：一边拍手一边读 a-plo-dis-mɑ̃。","tr":{"zh":"演员在掌声中走上舞台。","fr":"L'acteur monte sur scène sous les applaudissements.","alt":"L'acteur arrive sur scène sous les applaudissements.","note":"sous les applaudissements = 在掌声中。"}},
 "Les coulisses": {"pos":"n.f.pl. 阴性复数名词（单数 une coulisse）","s":"后台；幕后。dans les coulisses = 在后台；比喻成「幕后、内幕」：les coulisses du pouvoir = 权力的幕后。","ipa":"[ku.lis]","ph":"cou 读 [ku]；lis 读 [lis]；结尾 ss 读 [s]，e 不发，复数 s 不发。","pi":"ou 读 [u]；ss 读 [s]，不是 [z]；通常用复数 les coulisses，不用单数。","et":"来自 couler（滑动），因为布景在凹槽（coulisse）中滑动。同族：couler（流、滑）。","ex":[["Les acteurs se préparent dans les coulisses.","演员们在后台准备。"],["Je voudrais voir les coulisses du théâtre.","我想看看剧院的后台。"],["Dans les coulisses, tout est calme.","后台一切都很平静。"]],"co":[["dans les coulisses","在后台；在幕后"],["les coulisses du pouvoir","权力的幕后"],["visiter les coulisses","参观后台"],["rester dans les coulisses","留在幕后"]],"sy":[["arrière-scène","courant","后台、舞台后方"],["backstage","familier","后台（英语借词）"],["envers du décor","courant","事情的另一面、内幕"]],"fq":"中频，戏剧和新闻里常见。","me":"coulisses ← couler：布景在凹槽里「滑」进后台。","tr":{"zh":"我们在后台见到了演员。","fr":"Nous avons rencontré les acteurs dans les coulisses.","alt":"On a vu les acteurs dans les coulisses.","note":"dans les coulisses 一般用复数。"}},
 "Un créateur / Une créatrice": {"pos":"n.m./n.f. 名词，阳性 créateur，阴性 créatrice，复数 créateurs / créatrices","s":"创作者；创造者；设计师（尤指时装、游戏、品牌的创作者）。un créateur de mode = 时装设计师。le Créateur 首字母大写时指「造物主」。","ipa":"[kʁe.a.tœʁ] / [kʁe.a.tʁis]","ph":"cré [kʁe]；a [a]；teur 读 [tœʁ]；créatrice 读 [kʁe.a.tʁis]，c 读 [s]。","pi":"créa 是两个音节 [kʁe.a]，不要连成一个音；阴性不是 créateuse，而是 créatrice；eur 读 [œʁ]。","et":"来自拉丁语 creator，源于 creare（创造）。同族：créer、création、créatif。","ex":[["Le créateur de ce jeu est un génie.","这款游戏的创作者是个天才。"],["Elle est créatrice de mode.","她是时装设计师。"],["Les créateurs présentent leurs œuvres.","创作者们展示他们的作品。"]],"co":[["un créateur de mode","时装设计师"],["un créateur de contenu","内容创作者"],["un créateur d'entreprise","创业者"],["le créateur d'un jeu","游戏的创作者"]],"sy":[["concepteur / conceptrice","courant","设计者、研发者"],["auteur","courant","作者"],["inventeur / inventrice","courant","发明者"]],"fq":"高频，日常和媒体里常用。","me":"créateur / créatrice：-teur 变 -trice，像 acteur → actrice。","tr":{"zh":"这位设计师创作了新的服装系列。","fr":"Cette créatrice a lancé une nouvelle collection.","alt":"La créatrice a sorti une nouvelle collection.","note":"阴性 créatrice，所以用 cette créatrice。"}},
 "Un développeur / Une développeuse": {"pos":"n.m./n.f. 名词，阳性 développeur，阴性 développeuse，复数 développeurs / développeuses","s":"开发者；程序员；软件 / 游戏开发人员。un développeur web = 网页开发人员。也可指开发商（房地产等），但不如前一义常见。","ipa":"[dev.lɔ.pœʁ] / [dev.lɔ.pøz]","ph":"dé 读 [de]（重音在 dev 上，e 可轻读）；ve 读 [v]；lop 读 [lɔp]；p 读 [p]；eur 读 [œʁ]，euse 读 [øz]。","pi":"有 pp，要发一个 p；é 重音符号别漏；阴性是 développeuse，不是 développeure；eur 读 [œʁ]。","et":"développer（dé- 「解开」+ 旧词 voloper「包」，与 envelopper 同族）+ 后缀 -eur。","ex":[["Elle travaille comme développeuse web.","她是网页开发人员。"],["Mon frère est développeur de jeux vidéo.","我哥哥是游戏开发者。"],["Les développeurs corrigent les bugs.","开发人员在修复漏洞。"]],"co":[["un développeur web","网页开发人员"],["un développeur de jeux vidéo","游戏开发者"],["travailler comme développeur","做开发人员"],["un développeur informatique","软件开发人员"]],"sy":[["programmeur / programmeuse","courant","程序员"],["informaticien / informaticienne","courant","信息技术人员"],["codeur / codeuse","familier","写代码的人"]],"fq":"中高频，职业和科技话题里常用。","me":"développeur：développer（展开）+ -eur，把想法「展开」成程序。","tr":{"zh":"我姐姐是一名软件开发人员。","fr":"Ma sœur est développeuse informatique.","alt":"Ma sœur travaille comme développeuse.","note":"职业前通常不加冠词：elle est développeuse。"}},
 "Un gameur / Une gameuse (anglicismes)": {"pos":"n.m./n.f. 名词，阳性 gameur，阴性 gameuse，复数 gameurs / gameuses（英语借词）","s":"电子游戏玩家。借自英语 gamer，加上法语词尾 -eur / -euse 而成。更规范的说法是 un joueur / une joueuse de jeux vidéo。","ipa":"[ga.mœʁ] / [ga.møz]","ph":"ga 读 [ga]；me 读 [m]；eur 读 [œʁ]；阴性 euse 读 [øz]。","pi":"不读英语的 /ɡeɪmər/，而读 [ga.mœʁ]；ga 是 [ga]；eur 读 [œʁ]，r 要发。","et":"来自英语 gamer，再加上法语化的词尾 -eur。英语 game 是日耳曼语词。","ex":[["Les gameurs sont les joueurs de jeux vidéo.","「gameur」指电子游戏玩家。"],["Mon cousin est un gameur passionné.","我表哥是个狂热的游戏玩家。"],["Cette gameuse participe à un tournoi.","这位女玩家参加了一场比赛。"]],"co":[["un gameur passionné","狂热的游戏玩家"],["une gameuse professionnelle","职业女玩家"],["un gameur en ligne","网络游戏玩家"],["devenir gameur","成为游戏玩家"]],"sy":[["joueur de jeux vidéo","courant","游戏玩家，更规范的说法"],["gamer","familier","英语原词，也常用"],["joueur / joueuse","courant","玩家；泛指"]],"fq":"中频，年轻人和游戏圈里常用。","me":"gamer + -eur：英语词穿上法语词尾，读 ga-mœʁ。","tr":{"zh":"我的朋友是个电子游戏玩家。","fr":"Mon ami est un gameur de jeux vidéo.","alt":"Mon pote est un gros gameur.","note":"gameur 是借词；也可说 joueur de jeux vidéo。"}},
 "Un narrateur / Une narratrice": {"pos":"n.m./n.f. 名词，阳性 narrateur，阴性 narratrice，复数 narrateurs / narratrices","s":"叙述者；讲述故事的人。小说里指讲故事的声音（le narrateur est un jeune garçon）；电影、纪录片里指旁白。","ipa":"[na.ʁa.tœʁ] / [na.ʁa.tʁis]","ph":"na [na]；rra 读 [ʁa]，rr 读一个 [ʁ]；teur 读 [tœʁ]；narratrice 读 [na.ʁa.tʁis]。","pi":"rr 只读一个小舌音 [ʁ]；阴性是 narratrice，不是 narrateuse；eur 读 [œʁ]。","et":"来自拉丁语 narrator，源于 narrare（讲述）。同族：narration、narratif、raconter 的远亲。","ex":[["Le narrateur de l'histoire est un jeune garçon.","故事的叙述者是个小男孩。"],["La narratrice raconte son enfance.","这位叙述者讲述她的童年。"],["Le narrateur du documentaire a une voix douce.","纪录片的旁白声音很温柔。"]],"co":[["le narrateur principal","主要叙述者"],["la voix du narrateur","叙述者的声音；旁白"],["un narrateur omniscient","全知叙述者"],["un narrateur fiable","可靠的叙述者"]],"sy":[["conteur / conteuse","courant","讲故事的人，多指口头讲故事"],["voix off","courant","画外音、旁白"],["auteur","courant","作者"]],"fq":"中频，文学课和电影话题里常见。","me":"narrateur / narratrice：-teur 变 -trice，如 acteur → actrice。","tr":{"zh":"这本书的叙述者是一位老人。","fr":"Le narrateur de ce livre est un vieil homme.","alt":"Dans ce livre, c'est un vieil homme qui raconte.","note":"vieil 用在以元音开头的阳性名词前 (vieil homme)。"}},
 "Un ordinateur fixe / Un ordinateur portable": {"pos":"n.m. 阳性名词，复数 ordinateurs fixes / ordinateurs portables","s":"un ordinateur fixe = 台式电脑；un ordinateur portable = 笔记本电脑，口语简称 un portable（但 un portable 也指手机，要看语境）。","ipa":"[ɔʁ.di.na.tœʁ fiks] / [ɔʁ.di.na.tœʁ pɔʁ.tabl]","ph":"or [ɔʁ]；di [di]；na [na]；teur 读 [tœʁ]；fixe 读 [fiks]，x 读 [ks]；portable 读 [pɔʁ.tabl]，结尾 e 不发。","pi":"fixe 的 x 读 [ks]；-able 读 [abl]，结尾 e 不发；un portable 可能指手机，需看语境；ordinateur 是阳性。","et":"ordinateur 来自拉丁语 ordinare（安排），1955 年由 Jacques Perret 提议使用。portable ← porter + -able（能被携带的）。","ex":[["Je travaille sur un ordinateur fixe à la maison.","我在家用台式电脑工作。"],["J'emporte mon ordinateur portable en voyage.","我旅行时带着笔记本电脑。"],["Mon ordinateur fixe est plus puissant.","我的台式电脑性能更强。"]],"co":[["allumer / éteindre l'ordinateur","开机 / 关机"],["un ordinateur portable léger","轻便的笔记本电脑"],["travailler sur ordinateur","用电脑工作"],["réparer un ordinateur","修电脑"]],"sy":[["PC","courant","个人电脑"],["laptop","familier","笔记本电脑（英语借词）"],["tablette","courant","平板电脑"]],"fq":"极高频，日常常用。","me":"fixe = 固定在桌上；portable = 可携带（porter）。","tr":{"zh":"我在家用台式电脑，出门带笔记本电脑。","fr":"J'utilise un ordinateur fixe à la maison et un ordinateur portable en déplacement.","alt":"Chez moi, j'ai un fixe, et je prends mon portable en voyage.","note":"en déplacement = 出差、在外面；ordinateur 是阳性。"}},
 "Un organisateur / Une organisatrice": {"pos":"n.m./n.f. 名词，阳性 organisateur，阴性 organisatrice，复数 organisateurs / organisatrices","s":"组织者；主办人。l'organisateur d'un festival = 音乐节的主办人。也指整理东西的收纳盒（un organisateur，少见）。","ipa":"[ɔʁ.ga.ni.za.tœʁ] / [ɔʁ.ga.ni.za.tʁis]","ph":"or [ɔʁ]；ga [ga]；ni [ni]；sa 读 [za]，s 在元音间读 [z]；teur 读 [tœʁ]。","pi":"s 读 [z]，不是 [s]；阴性是 organisatrice，不是 organisateuse；词长，五个音节分开读。","et":"organiser + -teur；organiser 来自 organe，源于希腊语 organon（工具）经拉丁语传入。","ex":[["L'organisateur de l'événement a fait un discours.","活动组织者发表了讲话。"],["L'organisatrice du concert est très occupée.","音乐会的主办人非常忙。"],["Les organisateurs ont annulé la fête.","组织者取消了聚会。"]],"co":[["l'organisateur d'un événement","活动的组织者"],["un organisateur de voyages","旅行社、旅游组织者"],["remercier les organisateurs","感谢组织者"],["l'organisatrice de la fête","聚会的组织者"]],"sy":[["responsable","courant","负责人"],["initiateur / initiatrice","soutenu","发起人"],["maître d'œuvre","soutenu","主事者、总负责人"]],"fq":"中频，活动和工作话题里常用。","me":"organiser + -teur：把事情「排好」的人；阴性 -trice。","tr":{"zh":"活动的组织者感谢所有人。","fr":"L'organisateur de l'événement remercie tout le monde.","alt":"L'organisateur dit merci à tout le monde.","note":"remercier quelqu'un，直接宾语，不加 à。"}},
 "Un(e) puriste": {"pos":"n.m./n.f. 名词，阴阳性同形（un puriste / une puriste），复数 puristes","s":"纯粹主义者；对正统有严格要求的人（语言、音乐、料理等）。有时略带讽刺，指死板、不愿接受变化的人。","ipa":"[py.ʁist]","ph":"pu 读 [py]，u 是 [y]；ris 读 [ʁis]；结尾 -te 读 [t]，e 不发。","pi":"u 读 [y]，不是 [u]；阴阳性同形，只靠冠词区分 un / une；结尾 -iste 读 [ist]。","et":"pur（纯的，拉丁语 purus）+ 后缀 -iste（持某种主张的人）。同族：pureté、purifier。","ex":[["C'est un puriste qui n'aime pas les versions modernes.","他是个不喜欢现代版本的纯粹主义者。"],["Les puristes critiquent cet emprunt à l'anglais.","纯粹主义者批评这个英语借词。"],["Elle est puriste en matière de cuisine.","她在烹饪上是个纯粹主义者。"]],"co":[["un puriste de la langue","语言纯粹主义者"],["un puriste du jazz","爵士乐的纯粹主义者"],["être puriste","追求纯正"],["les puristes disent que…","纯粹主义者说……"]],"sy":[["perfectionniste","courant","完美主义者"],["traditionaliste","courant","传统主义者"],["intégriste","courant","原教旨主义者；贬义更强"]],"fq":"低频，评论和文化话题里出现。","me":"puriste ← pur：只要「纯」的人。","tr":{"zh":"纯粹主义者不喜欢这种新做法。","fr":"Les puristes n'aiment pas cette nouvelle façon de faire.","alt":"Les puristes ne sont pas fans de cette nouvelle méthode.","note":"façon de + 动词原形。"}},
 "Un(e) scénariste": {"pos":"n.m./n.f. 名词，阴阳同形（un scénariste / une scénariste），复数 scénaristes","s":"编剧，为电影、电视剧、动画写剧本的人。写出来的东西叫 un scénario（剧本；情节）。注意它不等于 écrivain（作家）。","ipa":"[se.na.ʁist]","ph":"sc 在 é 前读 [s]，所以 scé- = [se]；r 是小舌音 [ʁ]；-iste 读 [ist]，词尾 e 不发音。","pi":"sc 里的 c 不读 [k]；词尾 e 不读；重音落在最后一个发音的音节上。","et":"来自 scénario（意大利语 scenario）加后缀 -iste（表示从事某职业的人）。同族：scène（舞台；场景）。","ex":[["Le scénariste a écrit une histoire captivante.","编剧写了一个引人入胜的故事。"],["Elle est scénariste pour la télévision.","她是电视编剧。"]],"co":[["un scénariste de cinéma","电影编剧"],["écrire un scénario","写剧本"],["scénariste et réalisateur","编剧兼导演"]],"sy":[["auteur","courant","作者，范围更宽"],["dialoguiste","courant","专门写对白的编剧"]],"fq":"中低频，谈电影时常用。","me":"scène + -iste：写「场景」的人。","tr":{"zh":"她想成为电影编剧。","fr":"Elle veut devenir scénariste de cinéma.","alt":"Elle rêve d'être scénariste.","note":"表职业的名词作表语时通常不加冠词。"}},
 "Accueillir": {"pos":"v. 及物动词（第三组），助动词 avoir，过去分词 accueilli","s":"迎接；接待；收留。可以接人（accueillir des invités），也可以接消息或想法（accueillir une idée avec joie）。酒店、学校「接收」客人、学生也用它。","ipa":"[a.kœ.jiʁ]","ph":"ac 读 [a.k]；-ueil- 读 [œj]，u 只是为了让 c 保持 [k]；结尾 -ir 读 [iʁ]。","pi":"u 不单独发音；现在时变位像 -er 动词：j'accueille, nous accueillons；将来时 j'accueillerai。","et":"来自拉丁语 colligere（收集）加前缀 ac-（朝向）。同族：cueillir（采摘）、accueil（接待）。","ex":[["Nous allons accueillir nos invités ce soir.","今晚我们要接待客人。"],["L'hôtel accueille les enfants gratuitement.","这家酒店免费接待儿童。"]],"co":[["accueillir chaleureusement","热情地接待"],["bien / mal accueillir","欢迎 / 冷淡对待"],["un accueil","接待；欢迎"]],"sy":[["recevoir","courant","接待（客人），更日常"],["héberger","courant","提供住宿"]],"fq":"高频，日常和服务场景常用。","me":"accueil 是名词「接待处」，accueillir 就是做「接待」这件事。","tr":{"zh":"我们热情地接待了新同事。","fr":"Nous avons accueilli chaleureusement le nouveau collègue.","alt":"On a super bien accueilli le nouveau collègue.","note":"过去分词 accueilli，用 avoir。"}},
 "Apercevoir": {"pos":"v. 及物动词（第三组），助动词 avoir，过去分词 aperçu","s":"瞥见，隐约看到（不是特意看）。s'apercevoir de / que = 意识到，发现。比 voir 更强调「一眼带过」。","ipa":"[a.pɛʁ.sə.vwaʁ]","ph":"ç 读 [s]；ce 里的 c 在 e 前也读 [s]；-oir 读 [waʁ]。","pi":"j'aperçois, nous apercevons：在 o、u 前要写 ç 才仍读 [s]。不要和 percevoir（感知；收取）混淆。","et":"a- + percevoir（拉丁语 percipere，抓住，感知）。同族：perception、recevoir。","ex":[["J'ai aperçu un renard dans le jardin.","我在花园里瞥见一只狐狸。"],["Elle s'est aperçue de son erreur trop tard.","她太晚才发觉自己的错误。"]],"co":[["apercevoir au loin","远远地瞥见"],["s'apercevoir de qqch","发觉某事"],["s'apercevoir que + 直陈式","发现……"]],"sy":[["remarquer","courant","注意到"],["entrevoir","courant","隐约看见"]],"fq":"中高频，叙事常用。","me":"a + percevoir：「勉强感知到」。","tr":{"zh":"我在人群里瞥见了他。","fr":"Je l'ai aperçu dans la foule.","alt":"Je l'ai vu passer dans la foule.","note":"代词 l' 放在助动词前：je l'ai aperçu。"}},
 "Approcher": {"pos":"v. 及物/不及物动词（第一组），助动词 avoir","s":"靠近，逼近。不及物：L'hiver approche（冬天临近）；及物：approcher la chaise de la table（把椅子挪近桌子）。s'approcher de = 走近……（主语自己移动）。","ipa":"[a.pʁɔ.ʃe]","ph":"pr 连读 [pʁ]；o 读开口 [ɔ]；ch 读 [ʃ]；-er 读 [e]。","pi":"不要说 approcher à qqn；正确是 approcher qqn 或 s'approcher de qqn。","et":"晚期拉丁语 appropiare，来自 prope（靠近）。同族：proche（近的）、rapprocher。","ex":[["L'orage commence à approcher.","雷雨开始逼近。"],["Ne t'approche pas du feu !","别靠近火！"]],"co":[["s'approcher de","靠近"],["approcher de la fin","接近尾声"],["approcher qqn","接近某人"]],"sy":[["s'avancer","courant","往前走"],["se rapprocher","courant","互相靠近"]],"fq":"高频，日常常用。","me":"approcher 里藏着 proche（近）。","tr":{"zh":"夏天快到了。","fr":"L'été approche.","alt":"Les vacances approchent.","note":"不及物用法，主语是时间或事件。"}},
 "Assister": {"pos":"v. 不及物动词（第一组），助动词 avoir，assister à qqch","s":"出席，观看（会议、演出、比赛）。大陷阱：assister à = 在场参加或观看；assister qqn = 帮助某人（较正式）。不是英语 assist 的普通义。","ipa":"[a.sis.te]","ph":"ss 读 [s]；ist 读 [is]，t 单独属于后一音节 te；-er 读 [e]。","pi":"「看了一场音乐会」要说 assister à un concert，不能直接接宾语；中文容易漏掉 à。","et":"拉丁语 assistere（站在旁边）。同族：assistant、assistance。","ex":[["Elle a assisté à un concert.","她看了一场音乐会。"],["Il assiste à la réunion de lundi.","他出席周一的会议。"]],"co":[["assister à un match / un cours","观看比赛 / 听课"],["assister à une scène","目睹一个场面"],["assister qqn","协助某人"]],"sy":[["participer à","courant","参加（强调参与）"],["aider","courant","帮助，更日常"]],"fq":"高频，常考介词搭配。","me":"assister à = 站在旁边看。à 不能丢。","tr":{"zh":"你昨天参加会议了吗？","fr":"Tu as assisté à la réunion hier ?","alt":"T'étais à la réunion hier ?","note":"assister 后面必须加 à。"}},
 "Assouvir": {"pos":"v. 及物动词（第二组，-ir/-issant），助动词 avoir，过去分词 assouvi","s":"满足（强烈的欲望、饥饿、好奇、仇恨）。语气偏书面、有力，常接 faim, soif, curiosité, désir, vengeance 等名词。","ipa":"[a.su.viʁ]","ph":"ss 读 [s]；ou 读 [u]；v 读 [v]；词尾 -ir 读 [iʁ]。","pi":"ou 容易读成 [o]；第二组变位：j'assouvis, nous assouvissons。","et":"来源不确定。同族：assouvissement（满足）。","ex":[["Il veut assouvir sa vengeance.","他想一雪前耻。"],["Elle lit pour assouvir sa curiosité.","她读书是为了满足好奇心。"]],"co":[["assouvir sa faim / sa soif","解饥 / 解渴"],["assouvir sa curiosité","满足好奇心"],["assouvir un désir","满足欲望"]],"sy":[["satisfaire","courant","满足，更常见"],["rassasier","soutenu","使吃饱，也可比喻"]],"fq":"低频，多见于书面。","me":"ass-ou-vir：想像欲望被「安抚」住。","tr":{"zh":"他读书来满足自己的好奇心。","fr":"Il lit pour assouvir sa curiosité.","alt":"Il lit pour satisfaire sa curiosité.","note":"日常说话用 satisfaire 更自然。"}},
 "Attester": {"pos":"v. 及物动词（第一组），助动词 avoir","s":"证明，证实，为……作证。比 prouver 更正式，常用在书面或法律场合：attester un fait, attester que...。名词 une attestation = 证明书。","ipa":"[a.tɛs.te]","ph":"tt 读一个 [t]；e 读 [ɛ]（后面是 st）；-er 读 [e]。","pi":"tt 不要读成两个 t；Je peux en attester 里的 en 指前面提到的事。","et":"拉丁语 attestari，来自 testis（证人）。同族：attestation、testament、test。","ex":[["Je peux en attester !","我可以作证！"],["Ce document atteste son identité.","这份文件证明他的身份。"]],"co":[["attester un fait","证明一件事"],["attester que + 直陈式","证明……"],["une attestation","证明书"]],"sy":[["certifier","soutenu","证明，保证"],["prouver","courant","证明，更日常"],["témoigner","courant","作证"]],"fq":"中低频，正式场合。","me":"at-test-er：里面有 test（测验、证据）。","tr":{"zh":"这份文件证明他住在这里。","fr":"Ce document atteste qu'il habite ici.","alt":"Ce papier prouve qu'il habite ici.","note":"attester que 后面用直陈式。"}},
 "Attirer": {"pos":"v. 及物动词（第一组），助动词 avoir","s":"吸引，招来。主语可以是人、地方、物：Ce musée attire beaucoup de touristes。也可指「引来麻烦」：attirer des ennuis。","ipa":"[a.ti.ʁe]","ph":"tt 读一个 [t]；i 读 [i]；r 是小舌音 [ʁ]；-er 读 [e]。","pi":"tt 只读一个 [t]；不要和 attraper（抓住）混淆。","et":"a- + tirer（拉）。同族：attirance（吸引力）、attrayant（有吸引力的）。","ex":[["Ce musée attire beaucoup de touristes.","这座博物馆吸引很多游客。"],["Le bruit a attiré mon attention.","噪音引起了我的注意。"]],"co":[["attirer l'attention","引起注意"],["attirer des ennuis","惹麻烦"],["être attiré par","被……吸引"]],"sy":[["séduire","courant","诱惑，打动"],["repousser","courant","反义：推开，排斥"]],"fq":"高频，日常常用。","me":"a + tirer：把人「拉」过来。","tr":{"zh":"这个城市每年吸引很多游客。","fr":"Cette ville attire beaucoup de touristes chaque année.","alt":"Il y a plein de touristes qui viennent dans cette ville.","note":"attirer 的宾语是被吸引的人或物。"}},
 "Bondir": {"pos":"v. 不及物动词（第二组），助动词 avoir，过去分词 bondi","s":"猛地跳起，一跃，扑过去。常带突然、有力的动作：bondir sur sa proie（扑向猎物）。也可比喻：bondir de joie（高兴得跳起来）。","ipa":"[bɔ̃.diʁ]","ph":"bon 是鼻化元音 [ɔ̃]，n 不发音；d 读 [d]；-ir 读 [iʁ]。","pi":"bon- 的 n 不发音；第二组变位：je bondis, nous bondissons。","et":"来源不确定。同族：bond（一跃）、rebondir（反弹）、rebond。","ex":[["Le chat a bondi sur la souris.","猫扑向老鼠。"],["Elle a bondi de sa chaise.","她从椅子上跳了起来。"]],"co":[["bondir sur","扑向"],["bondir de joie","欢喜得跳起来"],["faire un bond","跳一下；猛增"]],"sy":[["sauter","courant","跳，更日常"],["foncer","familier","冲过去"]],"fq":"中低频，常见于故事。","me":"bond + -ir：像球一样「弹」起来。","tr":{"zh":"听到消息，他高兴得跳了起来。","fr":"En apprenant la nouvelle, il a bondi de joie.","alt":"Quand il a su la nouvelle, il a sauté de joie.","note":"bondir de + 情绪名词。"}},
 "Caler": {"pos":"v. 及物/不及物动词（第一组），助动词 avoir","s":"及物：垫稳，塞紧（用东西垫住桌脚）。不及物：Le moteur cale（发动机熄火）。se caler dans un fauteuil = 舒舒服服靠在椅子里。口语：être calé en maths = 数学很强。","ipa":"[ka.le]","ph":"c 在 a 前读 [k]；l 读 [l]；-er 读 [e]。","pi":"同一个词有好几个意思：垫稳 / 熄火 / 坐稳，要看上下文。","et":"来源不确定。同族：cale（楔子）、décaler（挪动）、calage（垫稳）。","ex":[["J'utilise un petit livre pour caler le pied de la chaise.","我用一本小书垫椅脚。"],["La voiture a calé au feu rouge.","车在红灯前熄火了。"]],"co":[["caler un meuble","垫稳家具"],["le moteur cale","发动机熄火"],["se caler dans","稳稳坐进"]],"sy":[["fixer","courant","固定"],["stabiliser","courant","使稳定"]],"fq":"中频，口语里很常用。","me":"cale（楔子）+ -er：塞个楔子让东西不晃。","tr":{"zh":"我用一本书垫住这张桌子。","fr":"Je cale cette table avec un livre.","alt":"Je mets un livre sous la table pour la caler.","note":"caler 的宾语是被垫稳的东西。"}},
 "Cartonner": {"pos":"v. 不及物动词（第一组，口语），助动词 avoir","s":"口语：大受欢迎，大获成功，成绩很好（cartonner au box-office / à l'examen）。另一个口语义：猛打，狠击。基本义是「用硬纸板做装订」。","ipa":"[kaʁ.tɔ.ne]","ph":"car 读 [kaʁ]；on 在这里不是鼻音，o 读 [ɔ]，nn 读 [n]；-er 读 [e]。","pi":"cartonner 里的 on 不是 [ɔ̃]，是 [ɔ] + [n]。语域是 familier，不要在正式写作里用。","et":"来自 carton（硬纸板）加 -er；carton 与 carte 同族。","ex":[["Ce nouveau film va cartonner au box-office.","这部新电影将在票房大卖。"],["Il a cartonné à l'examen.","他考得特别好。"]],"co":[["cartonner au box-office","票房大卖"],["cartonner à l'examen","考试考得很好"],["faire un carton","大获成功"]],"sy":[["marcher fort","familier","很火"],["réussir","courant","成功，中性"]],"fq":"中频，多在口语和媒体中。","me":"carton 像「奖状」：成绩一炮而红。","tr":{"zh":"这首歌火了。","fr":"Cette chanson a cartonné.","alt":"Cette chanson a eu beaucoup de succès.","note":"第一句是口语，第二句是中性说法。"}},
 "Cheminer": {"pos":"v. 不及物动词（第一组），助动词 avoir","s":"缓缓前行，沿着路走（偏文学色彩）。也可比喻想法慢慢发展：Cette idée chemine（这个想法在慢慢形成）。日常说「走」多用 marcher。","ipa":"[ʃə.mi.ne]","ph":"ch 读 [ʃ]；e 弱读 [ə]，说快时可略去；mi.ne 不是鼻音；-er 读 [e]。","pi":"-min- 不是鼻化音；ch 是 [ʃ]，不是 [k]。","et":"来自 chemin（路）加 -er。同族：cheminement（前进的路径；思路）、cheminot（铁路工人）。","ex":[["Nous avons cheminé pendant des heures dans la forêt.","我们在森林里走了好几个小时。"],["Ils cheminent le long de la rivière.","他们沿着河慢慢走。"]],"co":[["cheminer lentement","缓缓前行"],["cheminer le long de","沿着……走"],["une idée qui chemine","渐渐成形的想法"]],"sy":[["marcher","courant","走，最常用"],["avancer","courant","前进"],["déambuler","soutenu","闲逛"]],"fq":"低频，文学味重。","me":"chemin + -er：沿着「路」走。","tr":{"zh":"他们沿着小路慢慢走。","fr":"Ils cheminent lentement sur le sentier.","alt":"Ils marchent doucement sur le sentier.","note":"日常口语换成 marcher。"}},
 "Concentrer": {"pos":"v. 及物动词（第一组），助动词 avoir；se concentrer 为代词式","s":"使集中，聚集。concentrer ses efforts = 集中精力；L'Asie concentre ... = 亚洲聚集了最多……。代词式 se concentrer sur = 专心于。也指把液体浓缩。","ipa":"[kɔ̃.sɑ̃.tʁe]","ph":"con 读 [kɔ̃]；cen 读 [sɑ̃]；tr 读 [tʁ]；-er 读 [e]。","pi":"第一个 c 读 [k]，第二个 c 读 [s]；con- 和 -cen- 都是鼻音，n 不发音。","et":"con- + centre（中心）+ -er，意思是「往中心聚」。同族：concentration、centre。","ex":[["L'Asie concentre le plus de joueurs de jeux vidéo.","亚洲的电子游戏玩家最集中。"],["Je n'arrive pas à me concentrer.","我没法集中精神。"]],"co":[["se concentrer sur","专注于"],["concentrer ses efforts","集中努力"],["la concentration","专注；浓度"]],"sy":[["rassembler","courant","聚集"],["focaliser","soutenu","聚焦"]],"fq":"高频，学习和工作常用。","me":"con + centre：全都往中心集中。","tr":{"zh":"我在考试前很难集中精神。","fr":"J'ai du mal à me concentrer avant l'examen.","alt":"Je n'arrive pas à me concentrer avant l'examen.","note":"se concentrer 的 se 随主语变：je me concentre。"}},
 "Conserver": {"pos":"v. 及物动词（第一组），助动词 avoir","s":"保存，保留，保持（食物、文件、习惯、权利）。conserver 是「继续留着」，不是果酱；果酱说 la confiture。une conserve = 罐头。","ipa":"[kɔ̃.sɛʁ.ve]","ph":"con 读 [kɔ̃]；ser 读 [sɛʁ]；v 读 [v]；-er 读 [e]。","pi":"ser 在这里读 [sɛʁ]，不是 [ze]；n 不发音。","et":"拉丁语 conservare（保护，保存），con- + servare。同族：conservateur（保守的；保存者）、réserver。","ex":[["Il faut conserver ces documents précieux.","必须保存这些珍贵文件。"],["Ce fromage se conserve au frigo.","这种奶酪要放在冰箱里保存。"]],"co":[["conserver au frais","冷藏保存"],["conserver son calme","保持冷静"],["se conserver","能保存"]],"sy":[["garder","courant","留着，最常用"],["préserver","soutenu","保护，保全"]],"fq":"高频，日常和书面都用。","me":"con + servir：把东西好好「留着」。","tr":{"zh":"请把这张发票留着。","fr":"Veuillez conserver cette facture.","alt":"Garde cette facture, s'il te plaît.","note":"Veuillez + 不定式是礼貌的指示。"}},
 "Considérer": {"pos":"v. 及物动词（第一组，é→è 变化），助动词 avoir","s":"考虑，认为，看作。considérer que + 直陈式 = 认为……；considérer A comme B = 把 A 看作 B。也含「尊重」义：être très considéré = 受人尊敬。","ipa":"[kɔ̃.si.de.ʁe]","ph":"con 读 [kɔ̃]；si 读 [si]；dé 读 [de]；ré 读 [ʁe]。","pi":"变位：je considère（è），nous considérons（é）；considérer comme，不要漏 comme。","et":"拉丁语 considerare，一般认为与 sidus（星）有关，原义是观察星象。同族：considération。","ex":[["Je vais considérer cette option.","我会考虑这个选项。"],["On le considère comme un expert.","大家把他看作专家。"]],"co":[["considérer que","认为……"],["considérer comme","视为"],["tout bien considéré","总的来说"]],"sy":[["penser","courant","想，认为"],["estimer","soutenu","认为，估计"],["envisager","courant","考虑（可能性）"]],"fq":"高频，书面和日常都用。","me":"con + sidus：盯着星星仔细看，所以是「考虑」。","tr":{"zh":"我把他当作朋友。","fr":"Je le considère comme un ami.","alt":"Pour moi, c'est un ami.","note":"considérer A comme B。"}},
 "Constituer": {"pos":"v. 及物动词（第一组），助动词 avoir","s":"构成，组成，建立。A constitue B = A 就是 / 构成 B。être constitué de = 由……组成。也有「设立」义：constituer un dossier（建档）。","ipa":"[kɔ̃s.ti.tɥe]","ph":"con 读 [kɔ̃]；st 读 [st]；tu 在元音前变成半元音：-tuer 读 [tɥe]。","pi":"-tuer 只有一个音节 [tɥe]，不要读成 [ty.e] 两个音节。","et":"拉丁语 constituere，con- + statuere（放置，建立）。同族：constitution（宪法；体质）、institut、statue。","ex":[["Ces documents constituent un dossier important.","这些文件构成一份重要档案。"],["L'eau est constituée d'hydrogène et d'oxygène.","水由氢和氧组成。"]],"co":[["être constitué de","由……组成"],["constituer un dossier","建档案"],["constituer un risque","构成风险"]],"sy":[["former","courant","组成"],["composer","courant","组成"],["représenter","courant","代表，相当于"]],"fq":"中高频，偏书面。","me":"con + station：把东西「站」到一起，组成整体。","tr":{"zh":"这些元素构成一个整体。","fr":"Ces éléments constituent un tout.","alt":"Ces éléments forment un ensemble.","note":"被动形式是 être constitué de。"}},
 "Contempler": {"pos":"v. 及物动词（第一组），助动词 avoir","s":"凝视，静静观看，沉思（风景、星空、艺术品）。重点是「带着欣赏、不急不慢地看」，比 regarder 更有诗意。","ipa":"[kɔ̃.tɑ̃.ple]","ph":"con 读 [kɔ̃]；tem 读 [tɑ̃]（em 在 p 前读鼻音）；pl 读 [pl]；-er 读 [e]。","pi":"tem 是鼻音 [tɑ̃]，不要读成 [tɛm]；m 不发音。","et":"拉丁语 contemplari，与 templum（神殿，观测占卜的地方）有关。同族：contemplation、temple。","ex":[["Il aime contempler les étoiles la nuit.","他喜欢夜晚凝望星空。"],["Nous contemplons le coucher du soleil.","我们静静地看日落。"]],"co":[["contempler un paysage","凝望风景"],["contempler les étoiles","凝望星空"],["la contemplation","凝视；沉思"]],"sy":[["regarder","courant","看，最常用"],["admirer","courant","欣赏"],["observer","courant","观察"]],"fq":"中低频，偏文学。","me":"con + temple：在神殿前静静地看。","tr":{"zh":"我们在山上看日落。","fr":"Nous contemplons le coucher du soleil sur la montagne.","alt":"On regarde le coucher du soleil depuis la montagne.","note":"日常口语用 regarder 更自然。"}},
 "Déployer": {"pos":"v. 及物动词（第一组，y→i 变化），助动词 avoir","s":"展开（翅膀、地图、旗帜），铺开；部署（军队、资源）。déployer des efforts = 费力。同族 se déployer = 展开。","ipa":"[de.plwa.je]","ph":"dé 读 [de]；ploy- 读 [plwa.j]；-er 读 [e]。","pi":"变位：je déploie（y→i），nous déployons；oy 读 [waj]，不是 [ɔj]。","et":"dé- + ployer（拉丁语 plicare，折）。同族：plier（折）、employer、déplier。","ex":[["L'oiseau déploie ses ailes pour s'envoler.","鸟儿展开翅膀飞走。"],["L'armée a déployé des soldats à la frontière.","军队在边境部署了士兵。"]],"co":[["déployer ses ailes","展翅"],["déployer des efforts","付出努力"],["se déployer","展开"]],"sy":[["étendre","courant","展开，伸展"],["déplier","courant","打开（折着的）"]],"fq":"中频，书面较多。","me":"dé + plier：把折起来的东西打开。","tr":{"zh":"他展开地图看路线。","fr":"Il déploie la carte pour regarder l'itinéraire.","alt":"Il ouvre la carte pour voir le trajet.","note":"déployer 常接具体物或抽象的力量。"}},
 "Dévoiler": {"pos":"v. 及物动词（第一组），助动词 avoir","s":"揭开（面纱、雕像），公布，揭晓（秘密、新产品、计划）。公司「发布」新品常用 dévoiler。se dévoiler = 暴露出来。","ipa":"[de.vwa.le]","ph":"dé 读 [de]；voi 读 [vwa]；-ler 读 [le]。","pi":"oi 读 [wa]；不要读成 [dɛ.vɔ.lɛ]。","et":"dé- + voiler（遮盖），来自 voile（面纱，布）。反义：voiler（遮住）。","ex":[["L'entreprise va dévoiler son nouveau produit demain.","公司明天将发布新产品。"],["Le réalisateur a dévoilé le titre du film.","导演公布了电影的片名。"]],"co":[["dévoiler un secret","揭露秘密"],["dévoiler un projet","公布计划"],["dévoiler une statue","揭幕雕像"]],"sy":[["révéler","courant","揭示"],["annoncer","courant","宣布"],["cacher","courant","反义：藏起来"]],"fq":"中频，新闻和商业里常见。","me":"dé + voile：把「面纱」拿掉。","tr":{"zh":"歌手公布了新专辑的名字。","fr":"La chanteuse a dévoilé le nom de son nouvel album.","alt":"La chanteuse a annoncé le titre de son nouvel album.","note":"宣传新闻里常见 dévoiler。"}},
 "Divulguer": {"pos":"v. 及物动词（第一组），助动词 avoir","s":"泄露，透露（秘密、机密、名字）。带有不该公开的意味；中性的「公开」多用 rendre public。","ipa":"[di.vyl.ge]","ph":"di 读 [di]；vul 读 [vyl]；gue 读 [ge]，u 不发音，只让 g 保持硬音。","pi":"-gu- 的 u 不读；vu 的 u 读 [y]（嘴圆，像「于」）；变位 nous divulguons 保留 u。","et":"拉丁语 divulgare，来自 vulgus（群众，大众），意思是「向大众散播」。同族：vulgaire、vulgariser。","ex":[["Il ne faut pas divulguer ce secret.","不应该泄露这个秘密。"],["Le journal a divulgué son nom.","报纸泄露了他的名字。"]],"co":[["divulguer un secret","泄露秘密"],["divulguer des informations","泄露信息"],["la divulgation","泄露；公开"]],"sy":[["révéler","courant","透露"],["ébruiter","soutenu","把消息传开"],["garder","courant","反义：守住（秘密）"]],"fq":"低频，多见新闻和法律语境。","me":"di + vulgus：把秘密散播给「大众」。","tr":{"zh":"请不要泄露这个信息。","fr":"Veuillez ne pas divulguer cette information.","alt":"Ne dis ça à personne.","note":"divulguer 的宾语多为秘密或信息。"}},
 "Dominer": {"pos":"v. 及物/不及物动词（第一组），助动词 avoir","s":"主导，居首，控制；俯瞰（山、楼高过周围）。dominer le classement = 位居榜首。dominer ses émotions = 控制情绪。","ipa":"[dɔ.mi.ne]","ph":"do 读开口 [dɔ]；mi 读 [mi]；-ner 读 [ne]。","pi":"o 是开口音 [ɔ]，不是 [o]；m 在元音间要清楚地读。","et":"拉丁语 dominari，来自 dominus（主人）。同族：dominant、domination。","ex":[["Cet artiste domine le classement.","这位艺术家位居榜首。"],["La tour domine toute la ville.","这座塔俯视整座城市。"]],"co":[["dominer le classement","位居榜首"],["dominer la situation","掌控局面"],["dominer ses émotions","控制情绪"]],"sy":[["l'emporter","courant","占上风"],["diriger","courant","领导"],["surplomber","soutenu","居高临下"]],"fq":"中高频，新闻和运动里常见。","me":"dominus（主人）：站在最上面的人。","tr":{"zh":"我们的队伍主导了整场比赛。","fr":"Notre équipe a dominé tout le match.","alt":"Notre équipe a mené le match du début à la fin.","note":"dominer + 直接宾语，不加介词。"}},
 "Emmener": {"pos":"v. 及物动词（第一组，e→è 变化），助动词 avoir","s":"带（人）去某处，带走。重点是「把人从这里带到那里」，对象通常是人或动物。物品用 emporter（带走）。对应 amener（把人带到这里来）。","ipa":"[ɑ̃m.ne]","ph":"em 读鼻音 [ɑ̃]；m 读 [m]；e 弱读时几乎不发音，所以是 [ɑ̃m.ne]。","pi":"j'emmène, nous emmenons；人用 emmener，物用 emporter；amener = 带过来。","et":"en- + mener（引导）。同族：amener、ramener、promener、mener。","ex":[["J'emmène mon neveu au cinéma.","我带我侄子去看电影。"],["Il m'a emmenée à la gare.","他送我去了车站。"]],"co":[["emmener qqn quelque part","带某人去某地"],["emmener en voyage","带去旅行"],["emmener les enfants à l'école","送孩子上学"]],"sy":[["accompagner","courant","陪同"],["conduire","courant","开车送；引导"],["amener","courant","带来（朝说话人）"]],"fq":"高频，日常极常用。","me":"em-mener：把人「带出去」；a-mener 是「带到这边」。","tr":{"zh":"周末我带孩子们去公园。","fr":"Ce week-end, j'emmène les enfants au parc.","alt":"Samedi, je vais au parc avec les enfants.","note":"emmener 的对象是人。"}},
 "Épouser": {"pos":"v. 及物动词（第一组），助动词 avoir","s":"娶；嫁（和某人结婚）。épouser qqn 后面直接接人，不加 avec。比喻义：épouser une idée / une cause（接受并投身于某个观点或事业）。口语中常用 se marier avec。","ipa":"[e.pu.ze]","ph":"é 读 [e]；ou 读 [u]；s 在元音间读 [z]；-er 读 [e]。","pi":"s 读 [z]；épouser 后面不说 avec：il épouse Marie，不说 il épouse avec Marie。","et":"拉丁语 sponsare，来自 sponsus（未婚夫）。同族：époux、épouse。","ex":[["Il va épouser sa fiancée cet été.","他今年夏天要娶未婚妻。"],["Elle a épousé un médecin.","她嫁给了一位医生。"]],"co":[["épouser qqn","和某人结婚"],["épouser une cause","投身一项事业"],["épouser les formes","贴合形状"]],"sy":[["se marier avec","courant","和……结婚"],["marier","courant","为……主持婚礼"]],"fq":"中高频，日常常用。","me":"époux + -er：「做某人的配偶」。","tr":{"zh":"她明年要嫁给他。","fr":"Elle va l'épouser l'année prochaine.","alt":"Ils vont se marier l'année prochaine.","note":"épouser 是直接及物，不加介词。"}},
 "Éprouver": {"pos":"v. 及物动词（第一组），助动词 avoir","s":"感受到，体验到（情绪、困难、需要）：éprouver de la joie / de la peur / des difficultés。较书面。另一义：考验，使经受痛苦（être éprouvé）。","ipa":"[e.pʁu.ve]","ph":"é 读 [e]；pr 读 [pʁ]；ou 读 [u]；v 读 [v]；-er 读 [e]。","pi":"ou 读 [u]，不要读成 [o]；éprouver 和 prouver（证明）长得像，但意思是感受 / 经历。","et":"é- + prouver（拉丁语 probare，测试）。同族：épreuve（考验）、prouver、preuve。","ex":[["Il éprouve de grandes difficultés en mathématiques.","他在数学上有很大困难。"],["Elle éprouve de la joie à le revoir.","再见到他，她很开心。"]],"co":[["éprouver de la joie","感到喜悦"],["éprouver des difficultés","遇到困难"],["éprouver le besoin de","觉得有必要"]],"sy":[["ressentir","courant","感觉到"],["sentir","courant","感觉，更日常"],["connaître","courant","经历（困难）"]],"fq":"中频，偏书面。","me":"épreuve（考验）里面有 prouv-：通过考验才「体验」到。","tr":{"zh":"我感到很大的喜悦。","fr":"J'éprouve une grande joie.","alt":"Je suis très content.","note":"éprouver 后接情绪名词。"}},
 "Gâcher": {"pos":"v. 及物动词（第一组），助动词 avoir","s":"毁掉，糟蹋，浪费（心情、假期、食物、机会）。gâcher la fête = 搅了聚会；gâcher son talent = 浪费才能；gâcher de la nourriture = 浪费食物。","ipa":"[ga.ʃe]","ph":"â 读 [ɑ] 或 [a]；ch 读 [ʃ]；-er 读 [e]。","pi":"â 上的帽子不要漏写；ch 是 [ʃ]。","et":"来源不确定。同族：gâchis（浪费；乱七八糟）、gâcheur。","ex":[["La pluie a gâché nos vacances.","雨毁了我们的假期。"],["Ne gâche pas ton talent !","别浪费你的才能！"]],"co":[["gâcher la fête","扫兴"],["gâcher un repas","毁了一顿饭"],["gâcher de la nourriture","浪费食物"]],"sy":[["abîmer","courant","弄坏，损坏"],["gaspiller","courant","浪费"],["ruiner","courant","毁掉"]],"fq":"中高频，日常口语常用。","me":"gâcher：好事被搅砸，剩下 gâchis（一团糟）。","tr":{"zh":"别因为这件事毁了你的晚上。","fr":"Ne gâche pas ta soirée à cause de ça.","alt":"Laisse tomber, ne te gâche pas la soirée.","note":"物主词随主语：ta soirée。"}},
 "Inventer": {"pos":"v. 及物动词（第一组），助动词 avoir","s":"发明；编造（故事、借口）。inventer une excuse = 编个借口；Tu inventes ! = 你瞎编！。比 créer 更强调「前所未有」。","ipa":"[ɛ̃.vɑ̃.te]","ph":"in 读鼻音 [ɛ̃]；ven 读鼻音 [ɑ̃]；t 读 [t]；-er 读 [e]。","pi":"in- 和 -ven- 都是鼻音，n 不发音；不要读成 [in.vɛn.te]。","et":"拉丁语 inventare，来自 invenire（发现，找到）。同族：invention、inventaire（清单）、inventeur。","ex":[["Thomas Edison a inventé l'ampoule électrique.","爱迪生发明了电灯泡。"],["Il invente toujours une excuse.","他总是编个借口。"]],"co":[["inventer une histoire","编故事"],["inventer une excuse","编借口"],["un inventeur","发明家"]],"sy":[["créer","courant","创造"],["imaginer","courant","想像"],["fabriquer","familier","捏造（口语）"]],"fq":"高频，日常和书面都用。","me":"in + venir：想法「到来」，就是发明。","tr":{"zh":"他编了一个很蹩脚的借口。","fr":"Il a inventé une très mauvaise excuse.","alt":"Il s'est inventé une mauvaise excuse.","note":"mauvaise excuse：形容词放名词前。"}},
 "Mémoriser": {"pos":"v. 及物动词（第一组），助动词 avoir","s":"记住，背下，把……存入记忆（词汇、号码、路线）。电脑也可 mémoriser un mot de passe（保存密码）。比 apprendre par cœur 更中性。","ipa":"[me.mɔ.ʁi.ze]","ph":"mé 读 [me]；mo 读开口 [mɔ]；ri 读 [ʁi]；-ser 读 [ze]。","pi":"s 读 [z]；开头的 mé- 带重音符号，不要漏写。","et":"来自 mémoire（拉丁语 memoria）加 -iser（使……化）。同族：mémorable、mémorial。","ex":[["J'ai du mal à mémoriser les numéros de téléphone.","我很难记住电话号码。"],["Il mémorise le chemin avant de partir.","他出发前先记住路线。"]],"co":[["mémoriser un mot de passe","记住密码"],["mémoriser des mots","背单词"],["la mémoire","记忆；内存"]],"sy":[["retenir","courant","记住，更常用"],["apprendre par cœur","courant","背诵"]],"fq":"中频，学习和科技里常用。","me":"mémoire + -iser：把东西「存进记忆」。","tr":{"zh":"我在记这些新单词。","fr":"Je mémorise ces nouveaux mots.","alt":"J'essaie de retenir ces nouveaux mots.","note":"retenir 在日常里更自然。"}},
 "Minimiser": {"pos":"v. 及物动词（第一组），助动词 avoir","s":"淡化，低估，把……说得很轻（问题、风险、事实）。minimiser un problème = 把问题看轻。技术义：使最小化（minimiser les coûts）。","ipa":"[mi.ni.mi.ze]","ph":"三个 mi 都读 [mi]；-ser 读 [ze]（s 读 [z]）。","pi":"几个 mi 音节很短，别漏；s 读 [z]。","et":"来自 minimum（拉丁语，最小）加 -iser。同族：minimal、minime、diminuer。","ex":[["Il ne faut pas minimiser ce problème.","不应低估这个问题。"],["Elle minimise toujours ses succès.","她总是淡化自己的成功。"]],"co":[["minimiser un risque","低估风险"],["minimiser les coûts","把成本降到最低"],["ne pas minimiser","不要小看"]],"sy":[["sous-estimer","courant","低估"],["relativiser","courant","看淡，相对化"],["exagérer","courant","反义：夸大"]],"fq":"中频，书面和新闻里常见。","me":"mini = 迷你：把事情缩小。","tr":{"zh":"不要小看这个风险。","fr":"Il ne faut pas minimiser ce risque.","alt":"Ne sous-estime pas ce risque.","note":"il ne faut pas + 不定式 = 不该做。"}},
 "Récompenser": {"pos":"v. 及物动词（第一组），助动词 avoir","s":"奖励，给予回报（人、努力、成绩）。récompenser qqn de / pour qqch = 因某事奖励某人。名词：une récompense（奖励，奖品）。","ipa":"[ʁe.kɔ̃.pɑ̃.se]","ph":"ré 读 [ʁe]；com 读 [kɔ̃]（om 在 p 前读鼻音）；pen 读 [pɑ̃]；-ser 读 [se]。","pi":"com 和 pen 都是鼻音，m、n 不发音；s 读 [s]。","et":"ré- + compenser（拉丁语 compensare，抵偿）。同族：compensation、récompense。","ex":[["Le patron veut récompenser ses employés.","老板想奖励员工。"],["Elle est récompensée pour son travail.","她的工作得到了回报。"]],"co":[["récompenser qqn de / pour","因……奖励某人"],["être récompensé","得到奖励"],["une récompense","奖励"]],"sy":[["gratifier","soutenu","赠予，嘉奖"],["féliciter","courant","祝贺，表扬"],["punir","courant","反义：惩罚"]],"fq":"中高频，日常和工作都用。","me":"ré + compense：「再给一份补偿」，就是奖励。","tr":{"zh":"老师奖励了认真的学生。","fr":"La professeure récompense les élèves sérieux.","alt":"La prof donne une récompense aux élèves sérieux.","note":"récompenser 的宾语是被奖励的人。"}},
 "S'apprêter à": {"pos":"v. 代词式动词（第一组），助动词 être：je m'apprête","s":"准备做……，即将做……（s'apprêter à + 不定式）。比 se préparer à 更强调「马上要发生」。另一义：s'apprêter pour = 打扮好、准备出门。","ipa":"[sa.pʁɛ.te a]","ph":"s'ap 读 [sa.p]；prê 读 [pʁɛ]（ê 读 [ɛ]）；-ter 读 [te]；à 读 [a]。","pi":"s'apprêter 后面接 à + 不定式，不是 de；ê 上的帽子要写；主语多为人，也可用于物（L'avion s'apprête à décoller）。","et":"a- + prêt（准备好的）+ -er。同族：apprêt（整理，准备）、prêt、prêt-à-porter。","ex":[["L'avion s'apprête à décoller.","飞机即将起飞。"],["Je m'apprêtais à sortir quand il a appelé.","我正要出门，他就打电话来了。"]],"co":[["s'apprêter à + inf.","准备做……"],["s'apprêter à partir","准备出发"],["être prêt à","已准备好做"]],"sy":[["se préparer à","courant","为……做准备"],["être sur le point de","courant","正要……"]],"fq":"中频，书面和叙事常用。","me":"s'apprêter ≈ 让自己变得 prêt。","tr":{"zh":"火车就要开了。","fr":"Le train s'apprête à partir.","alt":"Le train va partir.","note":"s'apprêter à + 不定式；时态多用现在时或未完成过去时。"}},
 "S'essuyer": {"pos":"v. 代词式动词（第一组，y→i 变化），助动词 être：je m'essuie","s":"擦干自己（的某个部位）：s'essuyer les mains / le front / les pieds。身体部位用定冠词，不用物主词：Il s'essuie le front，不说 son front。","ipa":"[se.sɥi.je]","ph":"s' 读 [s]；es 读 [e]；suy 读 [sɥi]；-er 读 [je]（y 在这里带出 [j]）。","pi":"y→i：je m'essuie，nous nous essuyons；身体部位用 le / la / les，不用 mon / son。","et":"来源不详。同族：essuie-mains（擦手巾）、essuie-glace（雨刷）。","ex":[["Il s'essuie le front.","他擦了擦额头。"],["Essuie-toi les mains avant de manger.","吃饭前把手擦干。"]],"co":[["s'essuyer les mains","擦手"],["s'essuyer les pieds","擦脚"],["essuyer la table","擦桌子"]],"sy":[["se sécher","courant","把自己弄干"],["frotter","courant","擦，搓"]],"fq":"中频，日常用。","me":"essuie-glace 是「擦玻璃」：essuyer = 擦干。","tr":{"zh":"洗完澡，她擦干了身体。","fr":"Après la douche, elle s'essuie.","alt":"Elle se sèche après la douche.","note":"没有宾语时，s'essuyer 指擦干自己的身体。"}},
 "S'évader": {"pos":"v. 代词式动词（第一组），助动词 être：je me suis évadé(e)","s":"逃出，越狱，逃走（监狱、拘禁）。比喻：s'évader de la routine（逃离日常）。不是普通的「走」，而是从受限制的地方逃出来。","ipa":"[se.va.de]","ph":"s'é 读 [se]；va 读 [va]；-der 读 [de]。","pi":"助动词是 être，所以性数配合：elle s'est évadée；后面常接 de：s'évader de prison。","et":"拉丁语 evadere（出去，逃走），e- + vadere（走）。同族：évasion、évasif。","ex":[["Le prisonnier a réussi à s'évader.","囚犯成功越狱了。"],["Elle lit pour s'évader un peu.","她读书是为了暂时逃离现实。"]],"co":[["s'évader de prison","越狱"],["une évasion","逃跑；逃离"],["s'évader de la routine","逃离日常"]],"sy":[["s'échapper","courant","逃走，更常用"],["fuir","courant","逃跑，逃避"]],"fq":"中频，新闻和故事里常见。","me":"é-vader：走出去（evadere）。","tr":{"zh":"两个囚犯昨晚越狱了。","fr":"Deux prisonniers se sont évadés hier soir.","alt":"Deux détenus se sont échappés de prison hier soir.","note":"代词式动词，过去分词要和主语配合。"}},
 "Se dépêcher": {"pos":"v. 代词式动词（第一组），助动词 être：je me suis dépêché(e)","s":"赶紧，快点。se dépêcher de + 不定式 = 赶紧做……；Dépêche-toi ! = 快点！只表示动作加快。","ipa":"[sə.de.pɛ.ʃe]","ph":"se 读 [sə]；dé 读 [de]；pê 读 [pɛ]；ch 读 [ʃ]；-er 读 [e]。","pi":"ê 读 [ɛ]；后面用 de + 不定式；命令式是 Dépêche-toi !。","et":"与 empêcher 同族：dé- 表示解除，原义是「把阻碍拿掉」，所以走得快。","ex":[["Nous devons nous dépêcher pour ne pas rater le train.","我们得赶紧，免得错过火车。"],["Dépêche-toi, on est en retard !","快点，我们迟到了！"]],"co":[["se dépêcher de + inf.","赶紧做"],["Dépêche-toi !","快点！"],["sans se dépêcher","不慌不忙"]],"sy":[["se presser","courant","赶紧"],["se hâter","soutenu","急忙"],["filer","familier","赶紧走"]],"fq":"极高频，日常常用。","me":"dépêche ≈ 「快发出去」：dispatch。","tr":{"zh":"快点，电影马上开始了！","fr":"Dépêche-toi, le film va commencer !","alt":"Vite, le film commence !","note":"命令式肯定句：动词 + 连字符 + toi。"}},
 "Se dérouler": {"pos":"v. 代词式动词（第一组），助动词 être：il s'est déroulé","s":"发生，进行，展开（事件、活动、故事）。主语是事件，多用第三人称：La réunion se déroule à 10 h。比 avoir lieu 更强调「展开的过程」。","ipa":"[sə.de.ʁu.le]","ph":"se 读 [sə]；dé 读 [de]；rou 读 [ʁu]；-ler 读 [le]。","pi":"主语不是人，而是事件；过去分词 déroulé 要和主语配合：la fête s'est déroulée。","et":"dé- + rouler（滚，卷）；原义是把卷着的东西摊开。同族：rouler、enrouler、déroulement。","ex":[["L'histoire se déroule à Paris.","故事发生在巴黎。"],["Tout s'est bien déroulé.","一切顺利。"]],"co":[["se dérouler bien / mal","进行得顺利 / 不顺"],["le déroulement","进程"],["se dérouler à","在……举行"]],"sy":[["avoir lieu","courant","举行，发生"],["se passer","courant","发生，更口语"]],"fq":"高频，新闻、叙事里常用。","me":"dé + rouler：像摊开卷轴，故事一点点展开。","tr":{"zh":"比赛在体育馆举行。","fr":"Le match se déroule au stade.","alt":"Le match a lieu au stade.","note":"主语是事件，不是人。"}},
 "Se liguer": {"pos":"v. 代词式动词（第一组），助动词 être：ils se sont ligués","s":"联合起来（对付某人或某事）。se liguer contre qqn = 联手反对某人。多带「结成团体来对抗」的意味，不是普通的合作。","ipa":"[sə.li.ge]","ph":"se 读 [sə]；li 读 [li]；gue 读 [ge]，u 不发音；-er 读 [e]。","pi":"gu 里的 u 不读；变位 nous nous liguons 要保留 u。","et":"来自 ligue（联盟），源于意大利语，最终来自拉丁语 ligare（绑）。同族：ligue、lier。","ex":[["Les deux frères se sont ligués contre leur ennemi.","兄弟俩联合起来对付敌人。"],["Tout le village s'est ligué contre le projet.","全村联手反对这个项目。"]],"co":[["se liguer contre","联手反对"],["une ligue","联盟"],["se liguer avec","与……结盟"]],"sy":[["s'unir","courant","团结"],["s'allier","courant","结盟"],["se coaliser","soutenu","结成联盟"]],"fq":"低频，书面和新闻里。","me":"ligue（联盟）+ -er：加入联盟去对抗。","tr":{"zh":"邻居们联合起来反对这个计划。","fr":"Les voisins se sont ligués contre ce projet.","alt":"Les voisins se sont unis contre ce projet.","note":"代词式动词，过去分词与主语配合。"}},
 "Se venger": {"pos":"v. 代词式动词（第一组，g→ge 变化），助动词 être：il s'est vengé","s":"报仇，报复。se venger de qqn = 向某人报仇；se venger sur qqn = 把气撒在某人身上；se venger de qqch = 为某事报仇。名词：une vengeance。","ipa":"[sə.vɑ̃.ʒe]","ph":"se 读 [sə]；ven 读 [vɑ̃]（en 读鼻音）；g 在 e 前读 [ʒ]；-er 读 [e]。","pi":"ven 是鼻音 [vɑ̃]，n 不发音；nous nous vengeons 要保留 e 才能让 g 读 [ʒ]。","et":"拉丁语 vindicare（索取公道，报复）。同族：vengeance、vengeur、revanche（来自 revenger，再报仇）。","ex":[["Il veut se venger de ses ennemis.","他想向敌人复仇。"],["Elle s'est vengée en ne répondant pas.","她用不回信来报复。"]],"co":[["se venger de qqn","向某人报仇"],["se venger sur","拿……出气"],["une vengeance","报复"]],"sy":[["riposter","courant","还击"],["rendre la pareille","courant","以牙还牙"],["pardonner","courant","反义：原谅"]],"fq":"中频，影视和叙事常见。","me":"venger 听起来像 revenge（英语 revenge 从法语来）。","tr":{"zh":"他想向对手报仇。","fr":"Il veut se venger de son adversaire.","alt":"Il veut lui rendre la pareille.","note":"se venger de + 人。"}},
 "Traiter de": {"pos":"v. 间接及物动词（第一组），助动词 avoir；traiter de + 名词","s":"涉及，论述，讲的是（书、文章、电影的主题）：Ce livre traite de la guerre。另一义：traiter qqn de + 贬义词 = 骂某人是……（Il m'a traité d'idiot）。","ipa":"[tʁɛ.te də]","ph":"trai 读 [tʁɛ]（ai 读 [ɛ]）；-ter 读 [te]；de 读 [də]。","pi":"「讲的是」用 traiter de；「处理」用 traiter 直接接宾语；两个意思很不同。","et":"拉丁语 tractare（处理，拉扯）。同族：traité（条约；论著）、traitement。","ex":[["Ce livre traite de la Seconde Guerre mondiale.","这本书讲的是第二次世界大战。"],["Il m'a traité d'idiot.","他骂我是笨蛋。"]],"co":[["traiter de + 主题","论述……"],["traiter qqn de + 名词","骂某人是……"],["traiter un sujet","处理一个主题"],["un traité","论著；条约"]],"sy":[["parler de","courant","讲到"],["aborder","courant","谈到，涉及"],["porter sur","courant","关于"]],"fq":"中频，书面里常见。","me":"traité（论著）里的 trait-：traiter de = 写成一部「论著」。","tr":{"zh":"这篇文章讲的是环境问题。","fr":"Cet article traite des problèmes de l'environnement.","alt":"Cet article parle de l'environnement.","note":"de + les → des。"}},
 "Accessible": {"pos":"adj. 形容词，阴阳同形，复数 accessibles","s":"可到达的；容易接近的；价格合理的；通俗易懂的。accessible aux fauteuils roulants = 轮椅可进入。un prix accessible = 能负担的价格。Cet auteur est accessible = 他的作品好读。","ipa":"[ak.sɛ.sibl]","ph":"cc 在 e 前读 [ks]：ac.ces；ss 读 [s]；-ible 读 [ibl]，词尾 e 不发音，但 l 读出来。","pi":"cc 读 [ks]，不是 [k]；-ble 结尾 e 不读；阴阳同形，不加 e。","et":"拉丁语 accessibilis，来自 accedere（走近）。同族：accès、accéder、accessoire。","ex":[["Ce bâtiment est accessible aux fauteuils roulants.","这栋楼轮椅可以进入。"],["Ce livre est accessible à tous.","这本书人人都读得懂。"]],"co":[["accessible à tous","人人可用的"],["un prix accessible","合理的价格"],["facilement accessible","很容易到达的"],["l'accès","入口；使用权"]],"sy":[["abordable","courant","价格合理的"],["inaccessible","courant","反义：无法到达的"],["facile d'accès","courant","容易到达的"]],"fq":"高频，日常和新闻常用。","me":"accès + -ible：「有入口、进得去」。","tr":{"zh":"这个展览对所有人开放。","fr":"Cette exposition est accessible à tous.","alt":"Tout le monde peut visiter cette exposition.","note":"accessible à + 人。"}},
 "Apprécié / Appréciée": {"pos":"adj. 形容词，阳性 apprécié，阴性 appréciée，复数 appréciés / appréciées","s":"受欢迎的，受好评的，被赏识的。是动词 apprécier（欣赏，喜欢，评估）的过去分词用作形容词，常与 par 搭配：très apprécié par ses élèves。","ipa":"[a.pʁe.sje]","ph":"ap 读 [a.p]；pré 读 [pʁe]；ci 读 [sj]；é 读 [e]；阴性 appréciée 发音相同。","pi":"阴阳性发音一样，只在拼写上不同；apprécier 的 ci 读 [sj]，不是 [si]。","et":"apprécier 来自晚期拉丁语 appretiare，源自 pretium（价格，价值）。同族：prix、précieux。","ex":[["C'est un professeur très apprécié par ses élèves.","他是一位深受学生喜爱的老师。"],["Cette chanteuse est très appréciée en France.","这位歌手在法国很受欢迎。"]],"co":[["très apprécié(e)","很受欢迎的"],["apprécié de / par","受……喜爱"],["apprécier la musique","喜欢音乐"]],"sy":[["aimé","courant","被喜欢的"],["populaire","courant","受欢迎的"],["estimé","soutenu","受尊敬的"]],"fq":"中高频，评价人或物时常用。","me":"à + prix：被认为「值钱」，所以受欢迎。","tr":{"zh":"这家餐厅很受游客欢迎。","fr":"Ce restaurant est très apprécié des touristes.","alt":"Les touristes adorent ce restaurant.","note":"被动语态的施动者常用 par 或 de。"}},
 "Authentique": {"pos":"adj. 形容词，阴阳同形，复数 authentiques","s":"正宗的，真实的，原汁原味的。une cuisine authentique = 正宗的菜；un sourire authentique = 真诚的微笑。也可指「经认证为真迹的」。","ipa":"[o.tɑ̃.tik]","ph":"au 读 [o]；th 读 [t]，h 不发音；en 读鼻音 [ɑ̃]；-ique 读 [ik]。","pi":"au 读 [o]；th 读 [t]，不是英语的 /θ/；en 是鼻音，不读 [ɛn]；词尾 -que 读 [k]。","et":"希腊语 authentikos（有原权威的），经拉丁语进入法语。同族：authenticité、authentifier。","ex":[["Ce restaurant sert une cuisine italienne authentique.","这家餐厅供应正宗的意大利菜。"],["C'est un tableau authentique.","这是一幅真迹。"]],"co":[["une cuisine authentique","正宗的菜"],["un sourire authentique","真诚的微笑"],["un document authentique","真实的文件"]],"sy":[["vrai","courant","真的"],["véritable","soutenu","名副其实的"],["faux","courant","反义：假的"]],"fq":"中高频，评价食物、人、物品时常用。","me":"authentique ← authentic，英法几乎同形。","tr":{"zh":"我想吃正宗的法国菜。","fr":"Je voudrais manger de la cuisine française authentique.","alt":"Je veux goûter une vraie cuisine française.","note":"authentique 放名词后面。"}},
 "Contemporain(e)": {"pos":"adj. 形容词，阳性 contemporain，阴性 contemporaine；也可作名词 un(e) contemporain(e)","s":"当代的；同时代的。l'art contemporain = 当代艺术。作名词：nos contemporains = 我们同时代的人。注意不是「临时的」。","ipa":"[kɔ̃.tɑ̃.pɔ.ʁɛ̃]","ph":"con 读 [kɔ̃]；tem 读 [tɑ̃]；po 读 [pɔ]；rain 读 [ʁɛ̃]；阴性 contemporaine 读 [kɔ̃.tɑ̃.pɔ.ʁɛn]。","pi":"阴性要把最后的鼻音变成 [ɛn]；contemporain 的 tem 是鼻音 [tɑ̃]。","et":"拉丁语 contemporaneus，来自 con- + tempus（时间）。同族：temps、temporaire、tempo。","ex":[["Je n'aime pas l'art contemporain.","我不喜欢当代艺术。"],["Elle étudie la littérature contemporaine.","她学习当代文学。"]],"co":[["l'art contemporain","当代艺术"],["l'histoire contemporaine","当代史"],["nos contemporains","我们同时代的人"]],"sy":[["actuel","courant","现在的"],["moderne","courant","现代的"],["ancien","courant","反义：古老的"]],"fq":"中高频，艺术和历史里常见。","me":"con + temps：与你「同一个时代」。","tr":{"zh":"我喜欢当代音乐。","fr":"J'aime la musique contemporaine.","alt":"J'aime la musique d'aujourd'hui.","note":"形容词放在名词后，阴阳性配合。"}},
 "Demandé / Demandée": {"pos":"adj. 形容词，阳性 demandé，阴性 demandée，复数 demandés / demandées","s":"需求大的，抢手的；被要求的。Ce produit est très demandé = 这商品很抢手。作「被要求的」：le document demandé = 所要的文件。","ipa":"[də.mɑ̃.de]","ph":"de 读 [də]；man 读鼻音 [mɑ̃]；dé 读 [de]；阴性发音相同。","pi":"man 是鼻音，n 不发音；阴性 demandée 与阳性读音一样。","et":"demander 来自拉丁语 demandare（托付，委托）。同族：demande、commander。","ex":[["Ce produit est très demandé en ce moment.","这个产品最近很抢手。"],["Voici le document demandé.","这是您要的文件。"]],"co":[["très demandé(e)","很抢手的"],["le document demandé","被要求的文件"],["une demande","需求；申请"]],"sy":[["recherché","courant","受追捧的"],["populaire","courant","流行的"],["prisé","soutenu","受青睐的"]],"fq":"中频，购物和工作里常见。","me":"demande 多，所以 demandé = 有很多人要。","tr":{"zh":"这位医生非常抢手。","fr":"Ce médecin est très demandé.","alt":"Ce médecin a beaucoup de patients.","note":"demandé 与被修饰的名词配合。"}},
 "Encourageant / Encourageante": {"pos":"adj. 形容词，阳性 encourageant，阴性 encourageante，复数 encourageants / encourageantes","s":"令人鼓舞的，让人有信心的。常修饰 résultats, signes, paroles, nouvelles。动词 encourager = 鼓励。","ipa":"[ɑ̃.ku.ʁa.ʒɑ̃]","ph":"en 读鼻音 [ɑ̃]；cou 读 [ku]；ra 读 [ʁa]；g 在 e 前读 [ʒ]；-ant 读 [ɑ̃]。","pi":"-ageant 里的 e 保留，让 g 读 [ʒ]；en- 和 -ant 都是鼻音 [ɑ̃]；阴性发音为 [ɑ̃.ku.ʁa.ʒɑ̃t]。","et":"en- + courage（勇气）+ -ant。courage 来自 coeur（心），拉丁语 cor。","ex":[["Ce résultat est très encourageant.","这个结果很令人鼓舞。"],["Ses paroles sont encourageantes.","他的话很鼓舞人。"]],"co":[["un résultat encourageant","令人鼓舞的结果"],["des signes encourageants","积极的迹象"],["encourager qqn à","鼓励某人做"]],"sy":[["prometteur","courant","有前景的"],["positif","courant","积极的"],["décourageant","courant","反义：令人泄气的"]],"fq":"中频，评价结果、消息时常用。","me":"en + courage + -ant：「给人勇气」的。","tr":{"zh":"新消息令人鼓舞。","fr":"Les nouvelles sont encourageantes.","alt":"Les nouvelles sont plutôt bonnes.","note":"形容词与名词性数配合。"}},
 "Équilibré / Équilibrée": {"pos":"adj. 形容词，阳性 équilibré，阴性 équilibrée，复数 équilibrés / équilibrées","s":"均衡的，平衡的；也可形容人情绪稳定。une alimentation équilibrée = 均衡饮食；une personne équilibrée = 心理平衡的人。","ipa":"[e.ki.li.bʁe]","ph":"é 读 [e]；qui 读 [ki]（u 不发音）；li 读 [li]；bré 读 [bʁe]。","pi":"qui 里的 u 不发音，qu 读 [k]；é 开头和结尾都有重音，别漏。","et":"équilibre 来自拉丁语 aequilibrium：aequus（相等）+ libra（天平）。同族：équilibrer。","ex":[["Il est important d'avoir une alimentation équilibrée.","饮食均衡很重要。"],["C'est quelqu'un de très équilibré.","他是个很稳重的人。"]],"co":[["une alimentation équilibrée","均衡饮食"],["un budget équilibré","收支平衡的预算"],["un équilibre","平衡"]],"sy":[["stable","courant","稳定的"],["harmonieux","soutenu","和谐的"],["déséquilibré","courant","反义：失衡的"]],"fq":"中高频，饮食和健康话题常用。","me":"équi（相等）+ libra（天平）：两边一样重。","tr":{"zh":"我努力吃得均衡。","fr":"J'essaie de manger de façon équilibrée.","alt":"J'essaie d'avoir une alimentation équilibrée.","note":"形容词与名词性数配合。"}},
 "Étonnant / Étonnante": {"pos":"adj. 形容词，阳性 étonnant，阴性 étonnante，复数 étonnants / étonnantes","s":"令人惊讶的，令人惊叹的，出乎意料的。可褒可贬，要看上下文。动词 étonner = 使惊讶；s'étonner de = 对……感到惊讶。","ipa":"[e.tɔ.nɑ̃]","ph":"é 读 [e]；to 读 [tɔ]；nn 读一个 [n]；-ant 读鼻音 [ɑ̃]。","pi":"nn 只读一个 [n]；词尾 -ant 读 [ɑ̃]；阴性读 [e.tɔ.nɑ̃t]。","et":"étonner 来自晚期拉丁语 extonare（用雷击，使震惊）。同族：tonnerre（雷）、détonation。","ex":[["Ce magicien fait des tours étonnants.","这位魔术师表演令人惊叹的戏法。"],["Il est étonnant qu'elle ne soit pas venue.","她没来，真让人意外。"]],"co":[["un résultat étonnant","令人惊讶的结果"],["Il est étonnant que + 虚拟式","令人惊讶的是……"],["s'étonner de","对……感到吃惊"]],"sy":[["surprenant","courant","令人惊讶的"],["incroyable","courant","难以置信的"],["stupéfiant","soutenu","令人震惊的"]],"fq":"中高频，日常常用。","me":"étonner ← 像被雷（tonnerre）击到。","tr":{"zh":"这个结果真让人惊讶。","fr":"Ce résultat est vraiment étonnant.","alt":"C'est dingue, ce résultat !","note":"il est étonnant que 后面接虚拟式。"}},
 "Financier / Financière": {"pos":"adj. 形容词，阳性 financier，阴性 financière，复数 financiers / financières","s":"财务的，金融的，资金方面的。le succès financier = 财务上的成功；une aide financière = 经济援助。也可作名词 un financier（金融家）。","ipa":"[fi.nɑ̃.sje]","ph":"fi 读 [fi]；nan 读 [nɑ̃]（an 读鼻音）；ci 读 [sj]；阴性 financière 读 [fi.nɑ̃.sjɛʁ]。","pi":"an 是鼻音，n 不读；阳性末尾 -ier 读 [je]，阴性 -ière 读 [jɛʁ]。","et":"来自 finance（古法语 finer「支付」）加 -ier。同族：finance、financer、fin。","ex":[["Ce projet est un succès financier.","这个项目在财务上很成功。"],["Elle demande une aide financière.","她申请经济援助。"]],"co":[["une aide financière","经济援助"],["un problème financier","财务问题"],["la crise financière","金融危机"]],"sy":[["économique","courant","经济的"],["monétaire","soutenu","货币的"],["budgétaire","soutenu","预算的"]],"fq":"中高频，新闻和工作常用。","me":"finance + -ier：与「钱」有关的。","tr":{"zh":"他遇到了财务困难。","fr":"Il a des difficultés financières.","alt":"Il a des problèmes d'argent.","note":"financier / financière 放名词后。"}},
 "Fréquenté / Fréquentée": {"pos":"adj. 形容词，阳性 fréquenté，阴性 fréquentée，复数 fréquentés / fréquentées","s":"人多的，常有人去的，热闹的。un lieu très fréquenté = 很热门的地方。反义 peu fréquenté = 人烟稀少。不是「经常」，「经常」是 fréquent / fréquemment。","ipa":"[fʁe.kɑ̃.te]","ph":"fré 读 [fʁe]；quen 读 [kɑ̃]（qu 读 [k]，en 读鼻音）；té 读 [te]。","pi":"qu 读 [k]；en 读鼻音；fréquenté 形容地点或活动人多，fréquent 形容事情频繁。","et":"拉丁语 frequentare（常去），来自 frequens（频繁的）。同族：fréquent、fréquence、fréquenter。","ex":[["Ce festival est très fréquenté.","这个节日人气很旺。"],["C'est une rue peu fréquentée le soir.","这条街晚上人很少。"]],"co":[["très fréquenté(e)","人很多的"],["peu fréquenté(e)","冷清的"],["un lieu fréquenté","热门地方"]],"sy":[["animé","courant","热闹的"],["populaire","courant","受欢迎的"],["désert","courant","反义：空荡荡的"]],"fq":"中频，描述场所时常用。","me":"fréquent + -é：有「频繁到访」的人。","tr":{"zh":"这个海滩夏天人很多。","fr":"Cette plage est très fréquentée en été.","alt":"Il y a beaucoup de monde sur cette plage en été.","note":"用于地点或场所，与名词配合。"}},
 "Idéal / Idéale": {"pos":"adj. 形容词，阳性 idéal，阴性 idéale，阳性复数 idéaux（也有 idéals），阴性复数 idéales","s":"理想的，最合适的。l'endroit idéal = 理想的地点。作名词 un idéal（理想，复数 des idéaux）也很常用，比如 un idéal de vie（生活理想）。","ipa":"[i.de.al]","ph":"i 读 [i]；dé 读 [de]；al 读 [al]；三个音节：i.dé.al。","pi":"idéal 是三个音节，不是两个；阳性复数常写 idéaux，不是 idéals。","et":"来自 idée（希腊语 idea，形象，形式）加 -al。同族：idée、idéaliser、idéalisme。","ex":[["C'est l'endroit idéal pour des vacances.","这是度假的理想地点。"],["Il n'y a pas de solution idéale.","没有理想的解决办法。"]],"co":[["l'endroit idéal","理想的地方"],["la solution idéale","最佳办法"],["dans l'idéal","理想情况下"],["un idéal","理想"]],"sy":[["parfait","courant","完美的"],["optimal","soutenu","最优的"],["excellent","courant","极好的"]],"fq":"高频，日常常用。","me":"idée + al：「想法里最完美的那个」。","tr":{"zh":"对我们来说，这是理想的时间。","fr":"C'est le moment idéal pour nous.","alt":"C'est parfait pour nous.","note":"idéal 放名词后；dans l'idéal = 理想情况下。"}},
 "Impeccable": {"pos":"adj. 形容词，阴阳同形，复数 impeccables","s":"无可挑剔的，完美的，一尘不染的。un travail impeccable = 无可挑剔的工作；une chemise impeccable = 整洁的衬衫。口语里也可单独说 Impeccable ! = 太好了！","ipa":"[ɛ̃.pɛ.kabl]","ph":"im 读鼻音 [ɛ̃]；pec 读 [pɛk]；cable 读 [kabl]；词尾 -ble 的 e 不发音。","pi":"im- 是鼻音，m 不读；cc 读 [k]，不读 [ks]；-able 读 [abl]。","et":"拉丁语 impeccabilis，im-（否定）+ peccare（犯错，犯罪）。同族：pécher、péché。","ex":[["Son travail est toujours impeccable.","他的工作总是无可挑剔。"],["Tu viens à 8 h ? Impeccable !","你八点来？太好了！"]],"co":[["un travail impeccable","无可挑剔的工作"],["un français impeccable","完美的法语"],["Impeccable !","太好了！"]],"sy":[["parfait","courant","完美的"],["irréprochable","soutenu","无可指责的"],["nickel","familier","一尘不染（口语）"]],"fq":"中高频，口语和书面都用。","me":"im（没有）+ pécher（错）：没有过错。","tr":{"zh":"她的法语无可挑剔。","fr":"Son français est impeccable.","alt":"Elle parle un français parfait.","note":"impeccable 阴阳同形。"}},
 "Incontesté / Incontestée": {"pos":"adj. 形容词，阳性 incontesté，阴性 incontestée，复数 incontestés / incontestées","s":"无可争议的，公认的。le champion incontesté = 公认的冠军。比 incontestable（无法反驳的）更强调「没人提出异议」。","ipa":"[ɛ̃.kɔ̃.tɛs.te]","ph":"in 读 [ɛ̃]；con 读 [kɔ̃]；tes 读 [tɛs]；té 读 [te]；阴性发音相同。","pi":"in- 和 con- 都是鼻音；incontesté（没人质疑的）与 incontestable（不容质疑的）略有区别。","et":"in-（否定）+ contesté（contester，拉丁语 contestari，对质）。同族：contester、contestation。","ex":[["C'est le champion incontesté de sa catégorie.","他是自己级别无可争议的冠军。"],["Elle reste la leader incontestée du groupe.","她依然是团队里无可争议的领袖。"]],"co":[["un champion incontesté","无可争议的冠军"],["un leader incontesté","公认的领袖"],["une vérité incontestée","公认的事实"]],"sy":[["indiscutable","soutenu","不容置疑的"],["incontestable","courant","无法反驳的"],["contesté","courant","反义：有争议的"]],"fq":"中低频，新闻和体育里常见。","me":"in + contesté：「没人质疑」。","tr":{"zh":"他是公认的世界冠军。","fr":"C'est le champion du monde incontesté.","alt":"Personne ne conteste qu'il est le meilleur.","note":"incontesté 与被修饰的名词配合。"}},
 "Indifférent(e)": {"pos":"adj. 形容词，阴性 indifférente，复数 indifférents / indifférentes","s":"漠不关心的，无动于衷的。常用结构：être indifférent à qqch / à qqn（对……无所谓）。也可指对某人没有感情，Ça m'est indifférent = 我无所谓。","ipa":"[ɛ̃.di.fe.ʁɑ̃]","ph":"in- 读鼻化 [ɛ̃]；é 读 [e]；-ent 读鼻化 [ɑ̃]，t 不发音；阴性 indifférente 的 t 要发音 [ɑ̃t]。","pi":"词尾 -ent 不读 [ɛn]，读 [ɑ̃]；différ- 里是 ff，一个 f 的音。注意 indifférent 后接介词 à。","et":"来自拉丁语 indifferens，由否定前缀 in- + differre（有区别）构成。同源：différent、différence。","ex":[["Il est resté indifférent à mes problèmes.","他对我的问题无动于衷。"],["Ça m'est complètement indifférent.","这对我完全无所谓。"]],"co":[["indifférent à qqch","对某事漠不关心"],["rester indifférent","保持冷漠"],["laisser qqn indifférent","让某人无动于衷"]],"sy":[["insensible","courant","无感觉的，不为所动的"],["froid","courant","冷淡的"],["concerné","courant","反义：有关系的，受影响的"]],"fq":"中频，日常和书面都用。","me":"in-（不）+ différent：好坏「没有区别」，所以无所谓。","tr":{"zh":"他对政治完全不感兴趣。","fr":"Il est complètement indifférent à la politique.","alt":"La politique, ça le laisse complètement indifférent.","note":"indifférent à + 名词；laisser qqn indifférent 是固定说法。"}},
 "Individualiste": {"pos":"adj. 形容词，阴阳同形，复数 individualistes；也可作名词 un(e) individualiste","s":"个人主义的；只顾自己的。可以是中性的哲学词，也常带一点贬义，指不愿合作、只想着自己。","ipa":"[ɛ̃.di.vi.dɥa.list]","ph":"in- 读 [ɛ̃]；-ual- 读 [ɥa]（u 像短促的「于」再接 a）；结尾 -iste 读 [ist]，e 不发音。","pi":"不要读成 [ɛn]；阴阳性同形，不加 e 也不变音。","et":"individu + -iste。individu 来自拉丁语 individuus（不可分的）；-iste 表示持某种主义的人。同源：individuel、individualisme。","ex":[["Cette société est devenue très individualiste.","这个社会变得非常个人主义。"],["Elle est assez individualiste, elle préfère travailler seule.","她比较个人主义，更喜欢一个人工作。"]],"co":[["une société individualiste","个人主义的社会"],["un esprit individualiste","个人主义精神"],["être très individualiste","非常个人主义"]],"sy":[["égoïste","courant","自私的，比 individualiste 更负面"],["solitaire","courant","喜欢独处的"],["collectif","courant","反义：集体的"]],"fq":"中频，多见于谈论社会、性格。","me":"individu（单个的人）+ -iste：只信「单个的人」。","tr":{"zh":"现在的年轻人更个人主义吗？","fr":"Les jeunes d'aujourd'hui sont-ils plus individualistes ?","alt":"Les jeunes sont plus individualistes maintenant, non ?","note":"阴阳性同形；复数加 s。"}},
 "Inoubliable": {"pos":"adj. 形容词，阴阳同形，复数 inoubliables","s":"难忘的，令人无法忘记的。多形容旅行、夜晚、人、时刻。语气积极，是 oublier（忘记）的反面。","ipa":"[i.nu.bli.jabl]","ph":"in- 在元音 o 前不鼻化，读 [i.n]；ou 读 [u]；bli 之后有一个半元音 [j]；词尾 -able 读 [abl]，e 不发音。","pi":"in- 在这里不是鼻音 [ɛ̃]：读 i-nou，不是 in-ou。拼写注意 oubli-，不要漏 i。","et":"in-（不）+ oublier（忘记）+ -able（能……的）。oublier 来自俗拉丁语 oblitare。同源：oubli（遗忘）。","ex":[["Ce voyage était une expérience inoubliable.","这次旅行是难忘的经历。"],["On a passé une soirée inoubliable.","我们度过了难忘的一晚。"]],"co":[["un souvenir inoubliable","难忘的回忆"],["un moment inoubliable","难忘的时刻"],["une expérience inoubliable","难忘的经历"]],"sy":[["mémorable","soutenu","值得记住的，更书面"],["marquant","courant","令人印象深刻的"],["oubliable","courant","反义：容易被忘的"]],"fq":"中高频，评价体验时很常用。","me":"in-（不）+ oubli（遗忘）+ -able（能）：不能被忘记。","tr":{"zh":"那次演唱会真是难忘。","fr":"Ce concert était vraiment inoubliable.","alt":"Ce concert, c'était inoubliable !","note":"阴阳性同形：un soir / une soirée inoubliable。"}},
 "Initial(e)": {"pos":"adj. 形容词，阴性 initiale，阳性复数 initiaux，阴性复数 initiales","s":"最初的，开始时的。le plan initial 指最初的计划，la situation initiale 指起始情况。名词 une initiale 指首字母。","ipa":"[i.ni.sjal]","ph":"ti 读 [sj]，不是 [ti]；词尾阳性 -al 读 [al]；复数 initiaux 读 [i.ni.sjo]。","pi":"ti 读 [sj]，类似 nation。阳性复数是 initiaux，不是 initials。","et":"来自拉丁语 initialis，源于 initium（开始）。同源：initiative、initier、initiation。","ex":[["Le plan initial a été modifié.","最初的计划被修改了。"],["Mon idée initiale était différente.","我最初的想法不一样。"]],"co":[["le plan initial","最初的计划"],["à l'état initial","在初始状态"],["la lettre initiale","首字母"],["le coût initial","初始成本"]],"sy":[["premier","courant","第一的"],["original","courant","原先的，原始的"],["final","courant","反义：最终的"]],"fq":"中频，工作与书面常见。","me":"initial 像英语 initial：都是「开头的」。","tr":{"zh":"我最初的计划是八月去意大利。","fr":"Mon plan initial était d'aller en Italie en août.","alt":"À la base, je voulais aller en Italie en août.","note":"名词前后都可：le plan initial / l'idée initiale。"}},
 "Jaloux / Jalouse": {"pos":"adj. 形容词，阳性 jaloux，阴性 jalouse（阳性单复数同形）","s":"嫉妒的；吃醋的。可以指恋爱中的醋意，也可指羡慕别人的成功。常见结构：être jaloux de qqn / de qqch。","ipa":"[ʒa.lu]","ph":"j 读 [ʒ]；ou 读 [u]；词尾 x 不发音。阴性 jalouse 读 [ʒa.luz]，s 读 [z]。","pi":"词尾 -x 不发音；阴性 s 读 [z]。j 的发音是 [ʒ]，不是 [dʒ]。","et":"来自古法语 gelos，源于后期拉丁语 zelosus，和 zèle（热情）同源。","ex":[["Il est très jaloux de son succès.","他很嫉妒自己的成功。"],["Elle est jalouse de sa sœur.","她嫉妒她姐姐。"]],"co":[["jaloux de qqn","嫉妒某人"],["rendre qqn jaloux","让某人嫉妒"],["un mari jaloux","爱吃醋的丈夫"]],"sy":[["envieux","soutenu","羡慕的，较书面"],["possessif","courant","占有欲强的"],["jalousie","courant","名词：嫉妒"]],"fq":"高频，日常常用。","me":"jaloux 像「假路」：一嫉妒就走歪路。","tr":{"zh":"他对我的新车有点嫉妒。","fr":"Il est un peu jaloux de ma nouvelle voiture.","alt":"Ma nouvelle voiture le rend un peu jaloux.","note":"être jaloux de + 名词。"}},
 "Lambda": {"pos":"adj. 形容词，阴阳同形，不变化；也是希腊字母名 un lambda（n.m.）","s":"普通的，一般的，随便的。常说 un citoyen lambda、un utilisateur lambda，指「任何一个普通人」。是口语和媒体里的常用词。","ipa":"[lɑ̃b.da]","ph":"la 读 [lɑ̃]（鼻化）；m 在 b 前使前面的 a 鼻化；da 读 [da]；全词两个音节。","pi":"an/am 读鼻化 [ɑ̃]，m 本身不发音。作形容词不变化，不加 s 也不加 e。","et":"来自希腊字母 λ（lambda）。「任意的」这个含义来自数学里用 lambda 表示任一点。","ex":[["C'est un citoyen lambda.","他是个普通公民。"],["Un utilisateur lambda ne comprend pas ça.","一般用户看不懂这个。"]],"co":[["un citoyen lambda","普通公民"],["un utilisateur lambda","普通用户"],["un mec lambda","一个路人甲（口语）"]],"sy":[["moyen","courant","一般的，平均的"],["ordinaire","courant","普通的"],["quelconque","soutenu","任意的，平庸的"]],"fq":"中频，口语和媒体常见。","me":"lambda = 路人甲：随便哪一个。","tr":{"zh":"普通游客不知道这个地方。","fr":"Un touriste lambda ne connaît pas cet endroit.","alt":"Le touriste moyen ne connaît pas ce coin.","note":"lambda 不变化，放在名词后。"}},
 "Lumineux / Lumineuse": {"pos":"adj. 形容词，阳性 lumineux，阴性 lumineuse，复数 lumineux / lumineuses","s":"明亮的；发光的；（想法、微笑）灿烂的、清晰的。常说房间采光好 pièce lumineuse，也可以说 un sourire lumineux（灿烂的微笑）。","ipa":"[ly.mi.nø]","ph":"u 读 [y]（嘴圆，发「衣」）；eux 读 [ø]，x 不发音；阴性 lumineuse 读 [ly.mi.nøz]。","pi":"法语 u 读 [y]，不是「乌」；词尾 -x 不发音；阴性 s 读 [z]。","et":"来自拉丁语 luminosus，源于 lumen（光）。同源：lumière、illuminer、luminaire。","ex":[["La pièce est très lumineuse le matin.","房间早上很明亮。"],["Elle a un sourire lumineux.","她笑容灿烂。"]],"co":[["un appartement lumineux","采光好的公寓"],["une idée lumineuse","绝妙的主意"],["un sourire lumineux","灿烂的微笑"]],"sy":[["clair","courant","明亮的，清晰的"],["éclairé","courant","被照亮的"],["sombre","courant","反义：昏暗的"]],"fq":"中频，描述房子、光线时常用。","me":"lumineux 里有 lumi-：就是 lumière（光）。","tr":{"zh":"我们的新公寓很明亮。","fr":"Notre nouvel appartement est très lumineux.","alt":"Notre nouvel appart est super lumineux.","note":"阴性 lumineuse：une cuisine lumineuse。"}},
 "Marrant / Marrante": {"pos":"adj. 形容词，阳性 marrant，阴性 marrante，复数 marrants / marrantes","s":"（口语）好笑的，有趣的。比 drôle 更随意。ce n'est pas marrant = 这可不好玩，也可表示「很烦」。","ipa":"[ma.ʁɑ̃]","ph":"rr 读法语 [ʁ]（喉音）；an 读鼻化 [ɑ̃]；结尾 t 不发音；阴性 marrante 读 [ma.ʁɑ̃t]。","pi":"-ant 读 [ɑ̃]，t 不发；rr 只是一个 [ʁ]，不用发两次。","et":"来自动词 se marrer（口语，笑、开心）的现在分词；marrer 的来源不确定。","ex":[["Ce clown est vraiment marrant.","这个小丑真好笑。"],["Ce n'est pas marrant du tout !","这一点也不好玩！"]],"co":[["un type marrant","一个好玩的人（口语）"],["c'est marrant","真有意思 / 挺好笑"],["pas marrant","不好玩，烦人"]],"sy":[["drôle","courant","好笑的，通用"],["amusant","courant","有趣的，比较中性"],["rigolo","familier","搞笑的，口语"]],"fq":"高频，口语很常用。","me":"se marrer = 笑；marrant = 让人想笑的。","tr":{"zh":"你朋友真好笑！","fr":"Ton ami est vraiment marrant !","alt":"Ton pote est trop marrant !","note":"口语词，正式场合改用 drôle 或 amusant。"}},
 "Minuscule": {"pos":"adj. 形容词，阴阳同形，复数 minuscules；也是名词 une minuscule（小写字母，f.）","s":"极小的，微小的。比 petit 更强，类似 tout petit。名词 une minuscule 指小写字母，反义 une majuscule（大写字母）。","ipa":"[mi.ny.skyl]","ph":"u 都读 [y]；sc 读 [sk]；词尾 -cule 读 [kyl]，e 不发音。","pi":"两个 u 都读 [y]。阴阳性同形，不是 minuscul 也不是 minusculle。","et":"来自拉丁语 minusculus（稍小的），源于 minus（较少）。同源：minute、minimum。","ex":[["L'insecte était minuscule.","这只昆虫小得很。"],["Ils habitent dans un appartement minuscule.","他们住在很小的公寓里。"]],"co":[["un appartement minuscule","很小的公寓"],["écrire en minuscules","用小写字母写"],["une minuscule et une majuscule","一个小写和一个大写字母"]],"sy":[["minuscule","courant","极小；强于 petit"],["microscopique","soutenu","微观的，极小的"],["énorme","courant","反义：巨大的"]],"fq":"中频，日常与书面都用。","me":"mini + scule：比 mini 还小。","tr":{"zh":"这个房间小得不行。","fr":"Cette chambre est minuscule.","alt":"Cette chambre est toute petite.","note":"minuscule 本身已很强，不必再加 très。"}},
 "Monumental(e)": {"pos":"adj. 形容词，阴性 monumentale，阳性复数 monumentaux，阴性复数 monumentales","s":"宏伟的，巨大的。可以说建筑很壮观，也可口语夸张地说（une erreur monumentale = 天大的错误）。","ipa":"[mɔ.ny.mɑ̃.tal]","ph":"o 读开口 [ɔ]；u 读 [y]；-men- 读鼻化 [mɑ̃]；结尾 -al 读 [al]；复数 monumentaux 读 [mɔ.ny.mɑ̃.to]。","pi":"men 读 [mɑ̃]，不是 [mɛn]；阳性复数是 monumentaux。","et":"monument + -al。monument 来自拉丁语 monumentum，源于 monere（提醒）。同源：monument、monumental。","ex":[["Cette cathédrale est une œuvre monumentale.","这座大教堂是宏伟的作品。"],["Il a fait une erreur monumentale.","他犯了一个天大的错误。"]],"co":[["une œuvre monumentale","宏伟的作品"],["une erreur monumentale","天大的错误"],["un escalier monumental","宏伟的楼梯"]],"sy":[["imposant","courant","雄伟的，气派的"],["gigantesque","courant","巨大的"],["colossal","soutenu","庞大的"]],"fq":"中频，描写建筑、夸张时用。","me":"monument + al：像纪念碑那样大。","tr":{"zh":"这座桥非常宏伟。","fr":"Ce pont est monumental.","alt":"Ce pont est vraiment gigantesque.","note":"复数阳性：des monuments monumentaux。"}},
 "Muet / Muette": {"pos":"adj. 形容词，阳性 muet，阴性 muette；也可作名词 un muet / une muette（哑巴）","s":"哑的；说不出话的，哑口无言的。除了指失语，还常用来表示因惊讶、害怕而说不出话，也指不发音的字母（un e muet）。","ipa":"[mɥɛ]","ph":"mu 读 [mɥ]（像短促的「缪」），接 [ɛ]；t 不发音；阴性 muette 读 [mɥɛt]，t 要发。","pi":"不要读成 [mu.ɛ]；muet 是一个音节 [mɥɛ]。阴性 -ette 要双写 t。","et":"来自古法语 mu（拉丁语 mutus，哑的）+ 小称后缀 -et。同源：mutisme。","ex":[["Je suis resté muet.","我哑口无言。"],["Il est muet de naissance.","他天生是哑巴。"]],"co":[["rester muet","沉默不语"],["muet de surprise","惊讶得说不出话"],["un film muet","默片"],["un e muet","不发音的 e"]],"sy":[["silencieux","courant","安静的，不说话的"],["sans voix","courant","惊讶得说不出话"],["bavard","courant","反义：多话的"]],"fq":"中频，日常与影视常见。","me":"muet 像 mute（英语静音）：没有声音。","tr":{"zh":"听到这个消息，她惊讶得说不出话。","fr":"En apprenant la nouvelle, elle est restée muette de surprise.","alt":"Elle est restée sans voix en apprenant ça.","note":"muet de + 情绪：muet de peur / de surprise。"}},
 "Néerlandais(e)": {"pos":"adj. 形容词，阴性 néerlandaise；也作名词 un Néerlandais（荷兰人）和 le néerlandais（荷兰语，m.）","s":"荷兰的；荷兰人的。作名词，le néerlandais 是荷兰语，les Néerlandais 是荷兰人。注意：指语言时首字母小写，指人时大写。","ipa":"[ne.ɛʁ.lɑ̃.dɛ]","ph":"né 读 [ne]；er 读 [ɛʁ]；an 读 [ɑ̃]；ai 读 [ɛ]；阴性 néerlandaise 读 [ne.ɛʁ.lɑ̃.dɛz]。","pi":"ée 读 [e.ɛ]，两个元音要分开读；词尾 -ais 的 s 不发音，阴性才读 [z]。","et":"来自荷兰语 Nederland（低地之国），与 néerlandais（荷兰语）同源；neder 是「低的」。","ex":[["Il parle couramment néerlandais.","他荷兰语说得很流利。"],["Ma voisine est néerlandaise.","我邻居是荷兰人。"]],"co":[["parler néerlandais","说荷兰语"],["un Néerlandais / une Néerlandaise","荷兰男人 / 荷兰女人"],["la cuisine néerlandaise","荷兰菜"]],"sy":[["hollandais","courant","荷兰的，常见但严格只指荷兰两省"],["flamand","courant","弗拉芒的（比利时北部）"]],"fq":"中低频，谈语言、国籍时用。","me":"néer = neder = 「低」：低地之国。","tr":{"zh":"她想学荷兰语。","fr":"Elle veut apprendre le néerlandais.","alt":"Elle voudrait apprendre le néerlandais.","note":"指语言用阳性单数加冠词 le，首字母小写。"}},
 "Pétrifié(e)": {"pos":"adj. 形容词（过去分词作形容词），阴性 pétrifiée，复数 pétrifiés / pétrifiées","s":"吓呆的，僵住的；本义是变成石头的，如 bois pétrifié（石化木）。常用 pétrifié de peur（吓得发呆）。","ipa":"[pe.tʁi.fje]","ph":"é 读 [e]；tr 读 [tʁ]；fi 读 [fi]；结尾 -ié 读 [je]，这里 i 与 é 合成半元音 [j] + [e]。","pi":"词尾 -ié 读 [je]，不是 [i.e]。阴性是 pétrifiée，加 e 但发音不变。","et":"pétrifier（来自拉丁语 petra 石头 + -fier 使成为）的过去分词。同源：pierre（石头）、pétrole（石油，本义「岩石油」）。","ex":[["Il était pétrifié de peur.","他吓得呆住了。"],["Elle est restée pétrifiée devant le chien.","她在狗面前吓得动弹不得。"]],"co":[["pétrifié de peur","吓得发呆"],["rester pétrifié","僵在原地"],["une forêt pétrifiée","石化森林"]],"sy":[["paralysé","courant","吓得动不了的"],["figé","courant","僵住的"],["terrifié","courant","惊恐的，强调害怕本身"]],"fq":"中低频，多用于描述情绪。","me":"pétri- = petra 石头：吓成石头。","tr":{"zh":"他吓得一动也不敢动。","fr":"Il était pétrifié, il n'osait plus bouger.","alt":"Il était figé de peur, incapable de bouger.","note":"pétrifié de + 名词（peur, terreur）。"}},
 "Richissime": {"pos":"adj. 形容词，阴阳同形，复数 richissimes","s":"极其富有的，富得流油的。是 riche 的最高级形式，自带「非常」的意思，所以不必再加 très。","ipa":"[ʁi.ʃi.sim]","ph":"r 读 [ʁ]；ch 读 [ʃ]；ss 读 [s]，一个音；结尾 -me 读 [m]，e 不发音。","pi":"ch 读 [ʃ]，不是 [tʃ]；richissime 不加 très。阴阳性同形。","et":"riche + 拉丁式最高级后缀 -issime。同类：rarissime（极罕见）、grandissime。","ex":[["Cet homme d'affaires est richissime.","这位商人极其富有。"],["Sa famille est richissime.","他的家族富可敌国。"]],"co":[["être richissime","极其富有"],["un homme richissime","超级富豪"],["une famille richissime","富得流油的家族"]],"sy":[["riche","courant","富有的，通用"],["fortuné","soutenu","有钱的，书面"],["pauvre","courant","反义：贫穷的"]],"fq":"中低频，多见报刊和口语。","me":"riche + issime：「超级」riche。","tr":{"zh":"他的叔叔是个超级富豪。","fr":"Son oncle est richissime.","alt":"Son oncle est super riche.","note":"richissime 已是最高级，不用 très。"}},
 "Savant(e)": {"pos":"adj. 形容词，阴性 savante，复数 savants / savantes；也作名词 un savant（学者，科学家）","s":"博学的；巧妙的，精心设计的。注意：作名词 un savant 指科学家、学者。savant 修饰 mélange 时指「搭配得巧妙」。","ipa":"[sa.vɑ̃]","ph":"s 读 [s]；a 读 [a]；-vant 读鼻化 [vɑ̃]，t 不发音；阴性 savante 读 [sa.vɑ̃t]。","pi":"sa-vant 两音节；-ant 读 [ɑ̃]，不是 [ɑ̃n]。别和 savoir（知道）混淆，它来自 savoir 的旧分词。","et":"来自 savoir（知道）的旧现在分词形式 sachant（旧）。同源：savoir、savoir-faire。","ex":[["Ce film est un savant mélange d'action et de comédie.","这部电影巧妙地融合了动作和喜剧。"],["C'est un savant très connu.","他是一位著名学者。"]],"co":[["un savant mélange","巧妙的融合"],["un savant fou","疯狂科学家"],["un calcul savant","精密的计算"],["une dame savante","博学的女士"]],"sy":[["érudit","soutenu","博学的，渊博的"],["habile","courant","巧妙的，熟练的"],["ignorant","courant","反义：无知的"]],"fq":"中频，书面与媒体较常见。","me":"savant 来自 savoir：有知识就能做得巧妙。","tr":{"zh":"这道菜是各种香料的巧妙搭配。","fr":"Ce plat est un savant mélange d'épices.","alt":"Dans ce plat, les épices sont savamment mélangées.","note":"un savant mélange 是固定搭配，副词是 savamment。"}},
 "Vierge": {"pos":"adj. 形容词，阴阳同形，复数 vierges；也作名词 une vierge（处女，f.）","s":"空白的，未使用过的（page vierge, cassette vierge）；处女的；未经开发的（forêt vierge 原始森林）。la Vierge 指圣母玛利亚；Vierge 也是处女座。","ipa":"[vjɛʁʒ]","ph":"vi 读 [vj]；er 读 [ɛʁ]；g 在 e 前读 [ʒ]；结尾 -e 不发音。整个词一个音节。","pi":"只有一个音节 [vjɛʁʒ]，不要拆成两个音节；g 读 [ʒ]，不是 [g]。","et":"来自拉丁语 virgo，virginis（少女，处女）。同源：virginal、virginité。","ex":[["Il portait une toile vierge et un chevalet.","他带着一块空白画布和一个画架。"],["Cette île est encore vierge.","这座岛还没被开发。"]],"co":[["une page vierge","空白页"],["une forêt vierge","原始森林"],["un casier judiciaire vierge","无犯罪记录"],["l'huile d'olive vierge","初榨橄榄油"]],"sy":[["blanc","courant","空白的"],["intact","courant","原封未动的"],["utilisé","courant","反义：用过的"]],"fq":"中频，各种语境均用。","me":"vierge = 没被碰过：白纸、森林、橄榄油。","tr":{"zh":"我需要一张空白的纸。","fr":"J'ai besoin d'une feuille vierge.","alt":"Il me faut une feuille blanche.","note":"阴阳性同形：un CD vierge, une page vierge。"}},
 "Certainement": {"pos":"adv. 副词","s":"肯定地；当然。可以表示很有把握（Il viendra certainement），也可单独用来回答「当然可以」，比 oui 更有礼貌。","ipa":"[sɛʁ.tɛn.mɑ̃]","ph":"c 在 e 前读 [s]；ain 读 [ɛ]；-ement 里 e 是 [ɑ̃]，不是 [ɛ]；所以读 [sɛʁ.tɛn.mɑ̃]。","pi":"certain 是形容词，加 -e + -ment 变成 certainement；中间 n 要发 [n]：[tɛn]。","et":"certain + -e + -ment。certain 来自拉丁语 certus（确定的）。同源：certitude、certifier。","ex":[["Il viendra certainement à la fête.","他肯定会来参加派对。"],["Vous pouvez m'aider ? Certainement !","您能帮我吗？当然可以！"]],"co":[["très certainement","极有可能"],["certainement pas","肯定不"],["sûrement et certainement","确实无疑"]],"sy":[["sûrement","courant","一定，多半"],["assurément","soutenu","当然，确实"],["peut-être","courant","反义：也许"]],"fq":"高频，日常和书面都用。","me":"certain + ement：说「确定地」。","tr":{"zh":"他肯定已经到了。","fr":"Il est certainement déjà arrivé.","alt":"Il est sûrement déjà arrivé.","note":"放在助动词后、过去分词前。"}},
 "Certes": {"pos":"adv. 副词","s":"诚然，的确（承认一点，后面通常接 mais 转折）；有时也作回答：Certes. = 确实如此。是较书面、较正式的词。","ipa":"[sɛʁt]","ph":"c 读 [s]；er 读 [ɛʁ]；t 要发音 [t]；s 不发音。全词一个音节。","pi":"这里 t 要发 [t]，而 s 不发。不要读成 [sɛʁ]。常和 mais 配合。","et":"来自拉丁语 certe，是 certus（确定的）的副词形式；与 certain 同源。","ex":[["Certes, il est jeune, mais il est très compétent.","诚然，他很年轻，但他很有能力。"],["C'est certes difficile, mais pas impossible.","这的确难，但不是不可能。"]],"co":[["certes… mais…","诚然……但是……"],["certes oui","确实是的"],["certes pas","当然不"]],"sy":[["en effet","courant","的确"],["bien sûr","courant","当然"],["effectivement","courant","确实如此"]],"fq":"中频，书面和演讲常见。","me":"certes = 先承认，再 mais 转折。","tr":{"zh":"诚然，这很贵，但是质量很好。","fr":"Certes, c'est cher, mais la qualité est très bonne.","alt":"C'est cher, c'est vrai, mais la qualité est top.","note":"certes 后通常用 mais 引出转折。"}},
 "D'abord": {"pos":"adv. 副词（短语，d' = de 的省音）","s":"首先；起初。用来排列顺序：d'abord… ensuite… enfin。也表示「先」，如 Mange d'abord = 先吃。","ipa":"[da.bɔʁ]","ph":"d' 省音，与 abord 连读成 [da.bɔʁ]；o 读 [ɔ]；词尾 d 不发音。","pi":"结尾 d 不发音，r 要发。写作时记得撇号：d'abord，不是 dabord。","et":"de + abord；abord 来自动词 aborder（靠岸，接近），又来自 à + bord（船边）。","ex":[["D'abord, nous devons discuter du plan.","首先，我们得讨论计划。"],["Lave-toi les mains d'abord.","先去洗手。"]],"co":[["d'abord… ensuite… enfin","首先……然后……最后"],["tout d'abord","首先"],["dès l'abord","一开始"]],"sy":[["premièrement","courant","第一点，更书面"],["en premier","courant","先"],["ensuite","courant","之后，接着"]],"fq":"极高频，日常必备。","me":"d'abord：像「先靠岸」，第一步。","tr":{"zh":"首先，我们要买面包。","fr":"D'abord, nous devons acheter du pain.","alt":"Premièrement, il faut acheter du pain.","note":"d'abord 常放句首或动词后。"}},
 "En contrebas": {"pos":"adv. 短语副词；常接 de：en contrebas de","s":"在下方，在较低的位置（相对于所在或所指的地方）：La rivière est en contrebas = 河在下面。en contrebas de qqch = 在……的下方。","ipa":"[ɑ̃.kɔ̃.tʁə.ba]","ph":"en 读 [ɑ̃]；con 读 [kɔ̃]；trebas：e 轻读 [tʁə]，再 [ba]；s 不发音。","pi":"en 与 contre 之间不连读成 [n]；词尾 -bas 的 s 不发。contrebas 是一个词，不要拆成 contre bas。","et":"en + contre + bas：contre 在这里指「相对着」，bas = 低。","ex":[["La rivière coule en contrebas du village.","河流在村子下方流过。"],["Le parking est en contrebas.","停车场在下面。"]],"co":[["en contrebas de la route","在公路下方"],["en contrebas du château","在城堡下方"],["regarder en contrebas","向下看"]],"sy":[["en dessous","courant","在下面"],["en bas","courant","在下面，更通用"],["en surplomb","soutenu","反义：居高临下"]],"fq":"中低频，多见于描写景色。","me":"contre + bas：和上面「相对」的低处。","tr":{"zh":"小路在山谷下方。","fr":"Le chemin se trouve en contrebas de la vallée.","alt":"Le chemin est un peu plus bas, dans la vallée.","note":"en contrebas de + 名词。"}},
 "Miraculeusement": {"pos":"adv. 副词","s":"奇迹般地，神奇地。常用来讲死里逃生、意外好转：Il a miraculeusement survécu。也可轻松地用于小事，如「居然没坏」。","ipa":"[mi.ʁa.ky.løz.mɑ̃]","ph":"r 读 [ʁ]；u 读 [y]；eu 读 [ø]；s 读 [z]（在元音间）；-ment 读 [mɑ̃]；共六个音节。","pi":"miraculeusement 很长，要分段：mi-ra-cu-leu-se-ment；leuse 读 [løz]，s 读 [z]。","et":"miraculeux + -ment。miraculeux 来自 miracle，拉丁语 miraculum，源于 mirari（惊叹）。同源：admirer。","ex":[["Il a miraculeusement survécu à l'accident.","他奇迹般地在事故中幸存下来。"],["Miraculeusement, personne n'a été blessé.","奇迹般地，没人受伤。"]],"co":[["survivre miraculeusement","奇迹般地活下来"],["miraculeusement intact","奇迹般地完好"],["s'en sortir miraculeusement","奇迹般脱险"]],"sy":[["par miracle","courant","靠奇迹"],["heureusement","courant","幸好"],["extraordinairement","soutenu","非凡地"]],"fq":"中频，叙述事件时常见。","me":"miracle + -eusement：像神迹一样。","tr":{"zh":"奇迹般地，我们赶上了火车。","fr":"Miraculeusement, nous avons eu notre train.","alt":"Par miracle, on a eu notre train.","note":"副词可放句首，用逗号隔开。"}},
 "Notamment": {"pos":"adv. 副词","s":"尤其是，特别是；其中包括。用来在一堆内容里点出一个或几个重要的例子：notamment le football。比 surtout 更书面、更客观。","ipa":"[nɔ.ta.mɑ̃]","ph":"o 读 [ɔ]；-ment 读 [mɑ̃]。注意不是 [nɔ.tam.mɑ̃]：-amment 读 [a.mɑ̃]，所以没有额外的 m 音。","pi":"-amment 中双 m 只读一个 [m]。拼写是 notamment（-amment），不是 -emment。","et":"来自形容词 notant / noter（拉丁语 notare，标记），表示「被特别标出」。同族：note、notable。","ex":[["Il aime les sports, notamment le football.","他喜欢运动，尤其是足球。"],["Plusieurs pays, notamment la France, ont voté.","好几个国家，包括法国，投了票。"]],"co":[["notamment pour…","尤其是为了……"],["notamment grâce à…","尤其是多亏……"],["entre autres, notamment","其中尤其"]],"sy":[["surtout","courant","尤其，更口语"],["en particulier","courant","特别是"],["spécialement","soutenu","专门地，特别地"]],"fq":"中高频，书面和正式场合常见。","me":"note + amment：特别「记下」一个。","tr":{"zh":"他会说几种语言，尤其是中文。","fr":"Il parle plusieurs langues, notamment le chinois.","alt":"Il parle plusieurs langues, surtout le chinois.","note":"notamment 后面接具体例子。"}},
 "Par contre": {"pos":"adv. 短语副词（口语常用）","s":"不过；相反；另一方面。用来引出对比：Il est gentil, par contre il est lent。常被认为是口语，书面可换成 en revanche 或 en contrepartie。","ipa":"[paʁ.kɔ̃tʁ]","ph":"par 读 [paʁ]；contre 读 [kɔ̃tʁ]，结尾 e 不发音。常连读为一个短语。","pi":"有些规范语法书不鼓励 par contre，写作更常用 en revanche。注意 contre 结尾 re 要弱读。","et":"par + contre，字面意思「相反地」。16 世纪起用于商业词汇，表示「相抵」。","ex":[["Il est intelligent, par contre il est paresseux.","他很聪明，不过很懒。"],["Le plat est bon, par contre le service est lent.","菜好吃，不过服务慢。"]],"co":[["par contre…","不过……"],["mais par contre","但是相反"],["par contre, en revanche","可对比：en revanche"]],"sy":[["en revanche","soutenu","另一方面，更正式"],["mais","courant","但是"],["cependant","soutenu","然而"]],"fq":"高频，口语很常见。","me":"par + contre：先说好，再用 contre 对比。","tr":{"zh":"房间很小，不过很安静。","fr":"La chambre est petite, par contre elle est calme.","alt":"La chambre est petite, mais elle est calme.","note":"口语用法；正式写作可用 en revanche。"}},
 "Pourtant": {"pos":"adv. 副词","s":"可是，然而；却。表示结果出乎意料、与前文矛盾，比 mais 更强烈。放在句中或句末也可以：C'est pourtant vrai。","ipa":"[puʁ.tɑ̃]","ph":"ou 读 [u]；r 读 [ʁ]；-tant 读鼻化 [tɑ̃]，t 不发音。","pi":"ou 读 [u]，不是 [o]。别和 pour tant 分开写；是一个词 pourtant。","et":"pour + tant，字面意思「尽管如此」。tant 来自拉丁语 tantum（这么多）。","ex":[["Il a beaucoup étudié, pourtant il a raté l'examen.","他学了很多，可是考试还是没过。"],["C'est pourtant simple !","可这明明很简单！"]],"co":[["et pourtant","可是偏偏"],["pourtant…","然而……"],["c'est pourtant vrai","这明明是真的"]],"sy":[["cependant","soutenu","然而"],["toutefois","soutenu","不过"],["mais","courant","但是"]],"fq":"高频，口语与书面都用。","me":"pour + tant：尽管这样（所有这些）。","tr":{"zh":"他很累，可是他还在工作。","fr":"Il est fatigué, pourtant il continue à travailler.","alt":"Il est fatigué, et pourtant il continue de travailler.","note":"pourtant 比 mais 语气更强，强调出乎意料。"}},
 "Prochainement": {"pos":"adv. 副词","s":"不久，即将。多用于广告、公告，如电影预告 Prochainement au cinéma = 即将上映。语气比 bientôt 更正式。","ipa":"[pʁɔ.ʃɛn.mɑ̃]","ph":"pr 读 [pʁ]；o 读 [ɔ]；ch 读 [ʃ]；ai 读 [ɛ]；-ment 读 [mɑ̃]。","pi":"-ai- 在这里读 [ɛ]，n 要发 [n]：[ʃɛn.mɑ̃]。别和 bientôt 混淆：bientôt 更口语。","et":"prochain + -e + -ment。prochain 来自拉丁语 propeanus，源于 prope（近）。同源：proche、approcher。","ex":[["Le film sortira prochainement au cinéma.","这部电影即将上映。"],["Nous vous répondrons prochainement.","我们很快会回复您。"]],"co":[["prochainement sur vos écrans","不久即将与您见面（荧幕）"],["à paraître prochainement","即将出版"],["prochainement disponible","即将上市"]],"sy":[["bientôt","courant","很快，更口语"],["sous peu","soutenu","不久后"],["récemment","courant","反义（时间）：最近"]],"fq":"中频，公告和广告常见。","me":"prochain（下一个）+ ment：下一次就是不久。","tr":{"zh":"新店不久就会开张。","fr":"Le nouveau magasin ouvrira prochainement.","alt":"Le nouveau magasin va bientôt ouvrir.","note":"prochainement 多用于正式通知。"}},
 "Sinon": {"pos":"adv. 副词（也可作连词）","s":"否则，不然；除此之外。用于命令或警告之后：Dépêche-toi, sinon tu seras en retard。口语里也常用来转话题：Sinon, ça va ? = 对了，最近怎么样？","ipa":"[si.nɔ̃]","ph":"si 读 [si]；non 读鼻化 [nɔ̃]，n 不发音。","pi":"sinon 是一个词：si + non 合在一起；不要拆开写，拆开 si non 意思不同。","et":"si + non，字面意思「如果不」。","ex":[["Dépêche-toi, sinon nous serons en retard.","快点，否则我们要迟到了。"],["Sinon, quoi de neuf ?","对了，有什么新鲜事吗？"]],"co":[["…, sinon…","……，否则……"],["sinon quoi ?","不然呢？（口语）"],["sinon, ça va ?","除此之外，还好吗？"]],"sy":[["autrement","courant","不然"],["faute de quoi","soutenu","否则（正式）"],["à part ça","courant","除此之外"]],"fq":"极高频，口语必备。","me":"si + non：如果不是这样……","tr":{"zh":"快走吧，不然会赶不上火车。","fr":"Partons maintenant, sinon on va rater le train.","alt":"On y va, sinon on va rater le train.","note":"sinon 前常用逗号。"}},
 "Surtout": {"pos":"adv. 副词","s":"尤其，特别是；最重要的是。Surtout, ne… pas = 千万别。语气比 notamment 更强调，口语里常用。","ipa":"[syʁ.tu]","ph":"u 读 [y]；r 读 [ʁ]；ou 读 [u]；t 不发音。","pi":"u 读 [y]，ou 读 [u]：两个元音不同。surtout 里 t 不发音。不要读成 [syr.tut]。","et":"sur + tout，字面意思「在一切之上」。","ex":[["Il aime les fruits, surtout les pommes.","他喜欢水果，尤其是苹果。"],["Surtout, ne dis rien à personne !","千万别告诉任何人！"]],"co":[["surtout pas","千万别；绝对不"],["surtout pas ça","千万别那样"],["surtout si…","尤其是如果……"],["et surtout","而且最重要的是"]],"sy":[["notamment","soutenu","尤其，较书面"],["principalement","courant","主要地"],["particulièrement","courant","特别"]],"fq":"极高频，日常常用。","me":"sur + tout：在一切之上，就是「最」。","tr":{"zh":"我喜欢夏天，尤其是七月。","fr":"J'aime l'été, surtout en juillet.","alt":"J'adore l'été, surtout en juillet.","note":"surtout 后面接具体例子或时间。"}},
 "Volontiers": {"pos":"adv. 副词","s":"乐意地，很愿意。常单独用作回答：Un café ? Volontiers ! = 来杯咖啡吗？好的，乐意！语气礼貌而友好。也可表示「通常会」。","ipa":"[vɔ.lɔ̃.tje]","ph":"v 读 [v]；o 读 [ɔ]；on 读鼻化 [ɔ̃]；-tiers 读 [tje]，s 不发音。","pi":"词尾 -iers 读 [je]，s 不发音；n 不发。注意拼写 volontiers（带 s）。","et":"来自古法语 volentiers，源于拉丁语 voluntarie（出于意愿）。同源：volonté（意愿）、volontaire。","ex":[["J'accepte votre invitation volontiers.","我很乐意接受您的邀请。"],["Un thé ? Volontiers !","来杯茶吗？好啊！"]],"co":[["très volontiers","非常乐意"],["oui, volontiers","好的，乐意"],["volontiers, mais…","乐意，但是……"]],"sy":[["avec plaisir","courant","很乐意"],["de bon cœur","courant","诚心诚意地"],["à contrecœur","courant","反义：勉强地"]],"fq":"中高频，礼貌回应时常用。","me":"volonté（意愿）→ volontiers：出于自愿。","tr":{"zh":"你想喝点东西吗？好啊，乐意。","fr":"Tu veux boire quelque chose ? Volontiers.","alt":"Un petit quelque chose à boire ? Avec plaisir.","note":"volontiers 可单独回答，礼貌接受。"}},
 "Soit": {"pos":"conj. 连词（也用作副词，源于动词 être 的虚拟式）","s":"即，也就是（用来换算或解释）：La moitié, soit 35 millions。soit… soit… = 要么……要么……。也可表示「好吧」：Soit. = 就依你。","ipa":"[swa]","ph":"oi 读 [wa]；结尾 t 不发音，在多数用法里读 [swa]。","pi":"t 不发音；soit 和 soi（自己）、sois 读音一样。别和 c'est 混淆。","et":"être 的虚拟式第三人称 soit（来自拉丁语 sit）。\"soit… soit…\" 字面意思「无论是……还是……」。","ex":[["La moitié des français, soit environ 35 millions de personnes.","一半的法国人，即约三千五百万人。"],["Soit tu viens, soit tu restes.","要么你来，要么你留下。"]],"co":[["soit… soit…","要么……要么……"],["soit dit en passant","顺便说一句"],["soit","好吧（同意）"],["soit environ…","也就是大约……"]],"sy":[["c'est-à-dire","courant","也就是说"],["à savoir","soutenu","即，也就是"],["ou","courant","或者"]],"fq":"中频，书面和统计常见。","me":"soit 读 [swa]：像 swa，常用来换算「也就是」。","tr":{"zh":"他每天工作八小时，也就是每周四十小时。","fr":"Il travaille huit heures par jour, soit quarante heures par semaine.","alt":"Il travaille huit heures par jour, c'est-à-dire quarante par semaine.","note":"soit 引出换算或解释，前面用逗号。"}},
 "À l'avance": {"pos":"loc. adv. 短语副词","s":"提前，事先。à l'avance 常和 réserver、prévenir、payer 等动词连用。同义 d'avance，但 à l'avance 更常见。","ipa":"[a.la.vɑ̃s]","ph":"à l' 省音，与 avance 连读：[a.la.vɑ̃s]；an 读鼻化 [ɑ̃]；c 读 [s]。","pi":"avance 结尾 ce 读 [s]；l'avance 的 l' 读 [l]，不要漏掉。别写成 à la vance。","et":"à + l' + avance；avance 来自动词 avancer，俗拉丁语 abante（在前面）。","ex":[["Il faut réserver sa place à l'avance.","要提前订位。"],["Merci de nous prévenir à l'avance.","请提前通知我们。"]],"co":[["réserver à l'avance","提前预订"],["payer à l'avance","提前付款"],["prévenir à l'avance","提前通知"],["remercier à l'avance","先行致谢"]],"sy":[["d'avance","courant","事先，相近"],["au préalable","soutenu","事先，较书面"],["à l'improviste","courant","反义：突然地"]],"fq":"高频，日常常用。","me":"avance（前面）→ 在前面做：提前。","tr":{"zh":"你得提前订桌。","fr":"Tu dois réserver une table à l'avance.","alt":"Il faut réserver la table à l'avance.","note":"à l'avance 放在动词或宾语之后。"}},
 "À l'époque...": {"pos":"loc. adv. 短语副词（常放句首，后面用未完成过去时）","s":"那时；当时。指过去某个时期，后面常接未完成过去时（imparfait）描述当时的状态。à cette époque 与之相近。","ipa":"[a.le.pɔk]","ph":"à l' 与 époque 连读；é 读 [e]；o 读 [ɔ]；-que 读 [k]，e 不发音。","pi":"époque 以 [k] 结尾，不是 [kə]。é 带重音；l'époque 的 l' 要读。","et":"来自希腊语 epokhê（停顿，时间点），经拉丁语传入。注意：à l'époque 是固定短语。","ex":[["À l'époque, nous n'avions pas de téléphones portables.","那时我们没有手机。"],["À l'époque, il habitait à Lyon.","那时他住在里昂。"]],"co":[["à l'époque","当时"],["à cette époque-là","在那个时期"],["à l'époque de…","在……的时代"],["à l'époque où…","在……的时候"]],"sy":[["à ce moment-là","courant","那时候"],["autrefois","courant","从前"],["maintenant","courant","反义：现在"]],"fq":"极高频，讲过去必备。","me":"époque + à l'：把时间放到「那个年代」。","tr":{"zh":"那时候，我们住在乡下。","fr":"À l'époque, nous habitions à la campagne.","alt":"À ce moment-là, on vivait à la campagne.","note":"后面用 imparfait 描述当时的情况。"}},
 "À la demande de": {"pos":"loc. prép. 介词短语（后接名词或人称代词）","s":"应……的要求；按……的请求。à la demande de qqn 表示因为某人要求而做某事。à la demande générale = 应大家要求。","ipa":"[a.la.də.mɑ̃d.də]","ph":"demande 读 [də.mɑ̃d]，e 轻读；an 读鼻化 [ɑ̃]；de 之前 d 读 [d]。","pi":"demande 里 an 是 [ɑ̃]，不是 [an]；末尾 de 读弱音。别忘记最后的 de。","et":"à + la + demande + de；demande 来自动词 demander，拉丁语 demandare（托付）。","ex":[["Le concert a été annulé à la demande du chanteur.","音乐会应歌手的要求取消。"],["Je suis venu à la demande de ma mère.","我是应我妈妈的要求来的。"]],"co":[["à la demande de qqn","应某人要求"],["à la demande générale","应大家的要求"],["sur demande","按需，依请求"]],"sy":[["sur la demande de","soutenu","应……请求，较书面"],["à la requête de","soutenu","应……的请求"],["de son propre chef","soutenu","反义：自作主张"]],"fq":"中高频，正式和新闻语境多用。","me":"à la demande de：「应」某人「要求」。","tr":{"zh":"我是应老师的要求来的。","fr":"Je suis venu à la demande du professeur.","alt":"Le professeur me l'a demandé, alors je suis venu.","note":"de 后接人；du = de + le。"}},
 "À ta place... (si j'étais toi...)": {"pos":"loc. 短语，用于给建议（à ta place, je + 条件式）","s":"如果我是你……，换作是你的话。用来给建议，后面一般接条件式：À ta place, je partirais. 敬称用 à votre place。","ipa":"[a.ta.plas]","ph":"ta 读 [ta]；place 读 [plas]，c 读 [s]，e 不发音。","pi":"ta 是阴性所有格；place 是阴性，所以用 ta，不是 ton。条件式词尾 -rais 读 [ʁɛ]。","et":"à + ta + place；place 来自拉丁语 platea（街道，广场），源于希腊语 plateia。","ex":[["À ta place, je n'accepterais pas cette offre.","如果我是你，我不会接受这个提议。"],["À ta place, j'irais voir un médecin.","换作我是你，我会去看医生。"]],"co":[["à ta place, je…","如果我是你，我会……"],["à votre place","换作是您"],["si j'étais toi","如果我是你"]],"sy":[["si j'étais toi","courant","如果我是你"],["à ta place","familier","更口语的说法"],["à mon avis","courant","依我看"]],"fq":"高频，日常聊天常用。","me":"站到你的位置上 = 如果我是你。","tr":{"zh":"如果我是你，我会早点睡觉。","fr":"À ta place, je me coucherais plus tôt.","alt":"Si j'étais toi, je me coucherais plus tôt.","note":"à ta place 后接条件式 (conditionnel présent)。"}},
 "Au cas où...": {"pos":"loc. conj. 连词短语，后接条件式（au cas où + conditionnel）","s":"万一……；以防……。用于预防措施：Prends un parapluie au cas où il pleuvrait。也可单独用：Au cas où, ... = 以防万一。","ipa":"[o.ka.u]","ph":"au 读 [o]；cas 读 [ka]，s 不发音；où 读 [u]；三个音节连读 [o.ka.u]，cas 和 où 之间不连音。","pi":"au cas où 后用条件式，不是将来时或虚拟式。cas 的 s 不发音，也不要在 où 前读成 [z]。","et":"au + cas（情况，来自拉丁语 casus）+ où。","ex":[["Prends un parapluie au cas où il pleuvrait.","带把伞，以防下雨。"],["Je te donne mon numéro, au cas où.","我把号码给你，以防万一。"]],"co":[["au cas où + conditionnel","万一……"],["au cas où ça arriverait","万一发生"],["au cas où, …","以防万一"]],"sy":[["en cas de","courant","在……的情况下 + 名词"],["de peur que","soutenu","唯恐"],["si jamais","courant","万一，要是"]],"fq":"高频，日常常用。","me":"au cas où：像「万一在这个情况里」。","tr":{"zh":"带件外套，以防天冷。","fr":"Prends une veste, au cas où il ferait froid.","alt":"Prends une veste au cas où, il peut faire froid.","note":"au cas où 后用条件式。"}},
 "Au sein de": {"pos":"loc. prép. 介词短语","s":"在……之内；在……内部。多指组织、团体、机构的内部：au sein de l'équipe / de l'entreprise / de la famille。比 dans 更正式。","ipa":"[o.sɛ̃.də]","ph":"au 读 [o]；sein 读 [sɛ̃]（鼻化），ei 读 [ɛ]；de 读 [də]。","pi":"sein 读 [sɛ̃]，不要读成 [sɛn]；注意别和 sain（健康的）、saint（圣）混淆，三者都读 [sɛ̃]。","et":"sein 来自拉丁语 sinus（胸，怀抱）；au sein de 本义是「在……的怀中」。同源：sinus。","ex":[["Il y a une bonne ambiance au sein de l'équipe.","团队内部气氛很好。"],["Elle travaille au sein d'une grande entreprise.","她在一家大公司内部工作。"]],"co":[["au sein de l'entreprise","在公司内部"],["au sein de la famille","在家庭内部"],["au sein du groupe","在小组内"],["au sein de l'Union européenne","在欧盟内部"]],"sy":[["dans","courant","在……里面，更通用"],["parmi","courant","在……之中"],["en dehors de","courant","反义：在……之外"]],"fq":"中高频，正式、新闻语境常用。","me":"sein = 怀抱：在组织的「怀里」。","tr":{"zh":"公司内部有不同意见。","fr":"Il y a des opinions différentes au sein de l'entreprise.","alt":"Dans l'entreprise, les avis sont partagés.","note":"au sein de + 团体、机构名词。"}},
 "Avoir l'intention de": {"pos":"loc. verbale 动词短语（avoir，后接动词不定式或名词）","s":"打算……；有意……。avoir l'intention de + 动词原形：J'ai l'intention de partir。语气比 vouloir 更正式、更有计划。否定时表示「不打算」。","ipa":"[a.vwaʁ.lɛ̃.tɑ̃.sjɔ̃.də]","ph":"avoir 读 [a.vwaʁ]；l'in- 读 [lɛ̃]；-ten- 读 [tɑ̃]；-tion 读 [sjɔ̃]；de 读 [də]。","pi":"intention 里 -tion 读 [sjɔ̃]，不是 [tjɔn]；in- 和 -ten- 都是鼻化音，但不同：[ɛ̃] 与 [ɑ̃]。","et":"intention 来自拉丁语 intentio，源于 intendere（朝向，打算）。同源：intention、intentionnel、tendre。","ex":[["Il a l'intention de déménager l'année prochaine.","他打算明年搬家。"],["Je n'ai pas l'intention de partir.","我不打算走。"]],"co":[["avoir l'intention de + inf.","打算做某事"],["avoir de bonnes intentions","出于好意"],["sans intention de","无意于……"]],"sy":[["compter + inf.","courant","打算，较口语"],["projeter de","soutenu","计划"],["vouloir","courant","想要，更直接"]],"fq":"中高频，日常常用。","me":"intention 像英语 intention：有意做某事。","tr":{"zh":"我打算下个月去旅行。","fr":"J'ai l'intention de voyager le mois prochain.","alt":"Je compte voyager le mois prochain.","note":"avoir l'intention de + 动词原形。"}},
 "Briller en société": {"pos":"loc. verbale 动词短语（briller 是第一组规则动词）","s":"在社交场合出风头；在人前显得出色。可以是褒义（谈吐风趣）也可略带讽刺（爱炫耀）。briller = 发光；en société = 在社交场合。","ipa":"[bʁi.je.ɑ̃.sɔ.sje.te]","ph":"briller 读 [bʁi.je]；ill 读 [j]；en 读 [ɑ̃]；société 读 [sɔ.sje.te]。","pi":"briller 里 ill 读 [j]，不是 [l]；société 中 ci 读 [sj]。","et":"briller 来自意大利语 brillare（闪耀）；société 来自拉丁语 societas（结伴，社会）。","ex":[["Il utilise des mots compliqués pour briller en société.","他用复杂的词来炫耀。"],["Elle aime briller en société.","她喜欢在人前出风头。"]],"co":[["briller en société","在社交场合出风头"],["briller par son absence","因缺席而「引人注目」"],["briller de mille feux","闪闪发光"]],"sy":[["se faire remarquer","courant","引人注目"],["en mettre plein la vue","familier","炫耀"],["se montrer","courant","露面"]],"fq":"中低频，描述社交时用。","me":"briller = 发光；在人群里「发光」。","tr":{"zh":"他喜欢用幽默在聚会上出风头。","fr":"Il aime briller en société avec son humour.","alt":"Il adore briller en soirée grâce à son humour.","note":"briller en société 是固定搭配。"}},
 "Ça te dirait de... ?": {"pos":"loc. 口语句式（dire 的条件式，tu 形式）","s":"你想……吗？要不要……？用来友好地邀请：Ça te dirait de sortir ? 敬称用 Ça vous dirait de… ?","ipa":"[sa.tə.di.ʁɛ.də]","ph":"ça 读 [sa]；te 读 [tə]；dirait 读 [di.ʁɛ]，t 不发音；de 读 [də]。","pi":"dirait 的 -ait 读 [ɛ]，t 不发音。ça te dirait 里 te 是间接宾语，后面接 de + 动词原形。","et":"dire 的条件式：ça + te + dirait。字面意思「这会对你说什么吗？」，即「有吸引力吗」。","ex":[["Ça te dirait de venir avec nous ce soir ?","你今晚想和我们一起来吗？"],["Ça te dirait d'aller au cinéma ?","你想去看电影吗？"]],"co":[["ça te dirait de + inf. ?","你想……吗？"],["ça te dit ?","你感兴趣吗？"],["ça ne me dit rien","我没兴趣"]],"sy":[["tu as envie de… ?","courant","你想……吗？"],["ça te tente ?","familier","你心动吗？"],["voulez-vous… ?","soutenu","您愿意……吗？"]],"fq":"高频，口语邀请必备。","me":"ça te dirait = 这对你「说得通」吗？想去吗？","tr":{"zh":"你想去海边走走吗？","fr":"Ça te dirait de te promener au bord de la mer ?","alt":"Ça te dit d'aller faire un tour à la mer ?","note":"Ça te dirait de + 动词原形。"}},
 "Contrairement à": {"pos":"loc. prép. 介词短语（后接名词或代词）","s":"与……相反；不像……。用来对比两个人或事物：Contrairement à son frère, il est calme。注意必须后接 à。","ipa":"[kɔ̃.tʁɛʁ.mɑ̃.a]","ph":"con 读 [kɔ̃]；traire 读 [tʁɛʁ]；ment 读 [mɑ̃]；à 读 [a]。","pi":"ai 读 [ɛ]，r 读 [ʁ]；后面一定要加 à，不能只说 contrairement。","et":"contraire + -ment；contraire 来自拉丁语 contrarius，源于 contra（相对）。","ex":[["Contrairement à son frère, il est très calme.","与他哥哥相反，他很冷静。"],["Contrairement à moi, elle aime le froid.","和我不同，她喜欢冷天。"]],"co":[["contrairement à lui","和他不同"],["contrairement à ce que…","与……所说的相反"],["contrairement à l'habitude","与往常不同"]],"sy":[["à la différence de","soutenu","与……不同"],["à l'inverse de","soutenu","与……相反"],["comme","courant","反义：像"]],"fq":"高频，口语和书面都用。","me":"contraire + ment + à：和……相反。","tr":{"zh":"和我不同，我姐姐喜欢早起。","fr":"Contrairement à moi, ma sœur aime se lever tôt.","alt":"Moi, je déteste ça, mais ma sœur adore se lever tôt.","note":"contrairement à + 名词 / 代词；à 不可省。"}},
 "Du jamais-vu": {"pos":"loc. nominale 名词短语（n.m.，固定说法，不变化）","s":"前所未见的事；史无前例。名词用法，常带感叹：C'est du jamais-vu ! 可指好事或坏事。","ipa":"[dy.ʒa.mɛ.vy]","ph":"du 读 [dy]；jamais 读 [ʒa.mɛ]，s 不发音；vu 读 [vy]。","pi":"jamais 的 s 不发音；vu 是 voir 的过去分词，读 [vy]；du 与 vu 的 u 都读 [y]。","et":"jamais + vu（voir 的过去分词），名词化：「从没见过的东西」。","ex":[["Cette technologie est du jamais-vu !","这项技术前所未见！"],["C'est du jamais-vu dans l'histoire du sport.","这在体育史上前所未见。"]],"co":[["c'est du jamais-vu","前所未见"],["un spectacle du jamais-vu","史无前例的演出"],["du jamais-vu dans l'histoire","史上首例"]],"sy":[["inédit","soutenu","前所未有的"],["sans précédent","soutenu","无先例的"],["banal","courant","反义：平常的"]],"fq":"中频，媒体和口语常见。","me":"jamais vu = 从没见过。","tr":{"zh":"这样的天气真是前所未见。","fr":"Un temps pareil, c'est du jamais-vu !","alt":"Un temps pareil, on n'avait jamais vu ça !","note":"du jamais-vu 固定用法，用连字符。"}},
 "En fonction de": {"pos":"loc. prép. 介词短语","s":"取决于；根据；视……而定。表示某事随另一件事变化：Le prix varie en fonction de la saison。","ipa":"[ɑ̃.fɔ̃k.sjɔ̃.də]","ph":"en 读 [ɑ̃]；fon 读 [fɔ̃]；ction 读 [ksjɔ̃]；de 读 [də]。","pi":"fonction 中 ction 读 [ksjɔ̃]，c 和 t 都要发；en 与 fonction 之间不连读。","et":"来自 fonction，拉丁语 functio（执行，履行），源于 fungi（履行）。","ex":[["Le prix varie en fonction de la saison.","价格随季节而变。"],["Il choisit ses amis en fonction de leur humour.","他根据幽默感选朋友。"]],"co":[["en fonction de qqch","视某事而定"],["varier en fonction de","随……变化"],["en fonction des besoins","根据需要"]],"sy":[["selon","courant","根据"],["suivant","courant","按照"],["indépendamment de","soutenu","反义：不论"]],"fq":"高频，正式与工作语境常见。","me":"fonction（函数）：y 随 x 变化 → 取决于。","tr":{"zh":"票价取决于出发时间。","fr":"Le prix du billet change en fonction de l'heure de départ.","alt":"Le prix du billet dépend de l'heure de départ.","note":"en fonction de + 名词；dépendre de 是近义。"}},
 "En or": {"pos":"loc. adj. 形容词短语（不变化，放在名词后）","s":"金的；极好的，难得的。本义：une montre en or = 金表。比喻义：une occasion en or = 绝佳机会；avoir un cœur en or = 心地金子般善良。","ipa":"[ɑ̃.nɔʁ]","ph":"en 读 [ɑ̃]，与 or 连读，n 变成 [n]：[ɑ̃.nɔʁ]；o 读 [ɔ]；r 要发。","pi":"or 与 hors（外）读音相近但不同；连读时 en 的 n 要读出来。","et":"or 来自拉丁语 aurum（金）；en or 字面意思「用金做的」。","ex":[["C'est une occasion en or de rencontrer les artistes.","这是认识艺术家们的绝佳机会。"],["Elle a un cœur en or.","她心地非常善良。"]],"co":[["une occasion en or","绝佳机会"],["avoir un cœur en or","心地善良"],["une montre en or","金表"],["un rapport qualité-prix en or","超值"]],"sy":[["excellent","courant","极好的"],["en argent","courant","银质的，相近"],["magnifique","courant","极好的"]],"fq":"中频，日常和广告常见。","me":"en or = 金子做的 = 极好。","tr":{"zh":"这是个千载难逢的好机会。","fr":"C'est une occasion en or.","alt":"C'est une super occasion, une chance en or.","note":"en or 放在名词后，意思是「极好的」。"}},
 "En partie": {"pos":"loc. adv. 短语副词","s":"部分地，在一定程度上。表示不是全部：C'est en partie vrai = 有一部分是真的。反义：entièrement, totalement。","ipa":"[ɑ̃.paʁ.ti]","ph":"en 读 [ɑ̃]；par 读 [paʁ]；tie 读 [ti]，这里 t 不读 [s]。","pi":"partie 里 ti 读 [ti]，不是 [si]；别和 particulier 混淆。","et":"en + partie；partie 来自 partir 的阴性过去分词，拉丁语 partire（分开）。","ex":[["Ces chiffres s'expliquent en partie par la baisse de natalité.","这些数字部分由出生率下降解释。"],["C'est en partie ma faute.","这有一部分是我的错。"]],"co":[["en partie","部分地"],["en grande partie","在很大程度上"],["en partie vrai","部分属实"],["en partie à cause de…","部分是由于……"]],"sy":[["partiellement","soutenu","部分地，更书面"],["un peu","courant","有点"],["entièrement","courant","反义：完全地"]],"fq":"高频，日常和书面都用。","me":"partie = 一部分；en partie = 只占一部分。","tr":{"zh":"这部分是他的责任。","fr":"C'est en partie de sa responsabilité.","alt":"Il en est en partie responsable.","note":"en partie 常放在动词之后。"}},
 "En rebord de": {"pos":"loc. prép. 介词短语","s":"在……的边缘；在……的边沿上。rebord 是边缘凸起的部分，如窗台 rebord de fenêtre。en rebord de falaise = 在悬崖边上。","ipa":"[ɑ̃.ʁə.bɔʁ.də]","ph":"en 读 [ɑ̃]；re 读弱音 [ʁə]；bord 读 [bɔʁ]，d 不发音；de 读 [də]。","pi":"bord 的 d 不发音，r 要发；rebord 的第一音节 re 轻读。","et":"rebord = re- + bord（边）。bord 来自法兰克语 bord（船边）。","ex":[["La maison est située en rebord de falaise.","房子建在悬崖边上。"],["Un pot de fleurs est posé en rebord de fenêtre.","窗台上放着一盆花。"]],"co":[["en rebord de fenêtre","在窗台上"],["en rebord de falaise","在悬崖边"],["un rebord de toit","屋檐边"]],"sy":[["au bord de","courant","在……边上"],["sur le bord de","courant","在……边缘"],["au centre de","courant","反义：在……中央"]],"fq":"中低频，描写风景时用。","me":"re + bord：边上再翘起来的一圈。","tr":{"zh":"猫坐在窗台上。","fr":"Le chat est assis en rebord de fenêtre.","alt":"Le chat est sur le rebord de la fenêtre.","note":"en rebord de + 名词（无冠词）。"}},
 "Être au courant": {"pos":"loc. verbale 动词短语（être，au courant de + 名词 / que…）","s":"知情；了解情况。Je suis au courant = 我知道了。au courant de qqch = 了解某事。否定：Je ne suis pas au courant。","ipa":"[ɛtʁ.o.ku.ʁɑ̃]","ph":"être 读 [ɛtʁ]；au 读 [o]；courant 读 [ku.ʁɑ̃]，t 不发音。","pi":"courant 的 -ant 读 [ɑ̃]，t 不发音；ou 读 [u]。注意是 au courant，不是 en courant。","et":"courant 是 courir（跑）的现在分词，字面意思「在潮流中」，即跟上最新情况。","ex":[["Je ne suis pas au courant de cette situation.","我不了解这个情况。"],["Tu es au courant ? Marie se marie !","你知道吗？玛丽要结婚了！"]],"co":[["être au courant de qqch","知道某事"],["mettre qqn au courant","告诉某人"],["tenir qqn au courant","随时通知某人"],["se mettre au courant","了解情况"]],"sy":[["savoir","courant","知道"],["être informé","soutenu","已被告知"],["ignorer","soutenu","反义：不知道"]],"fq":"极高频，日常必备。","me":"courant = 流动的；跟上潮流 = 知情。","tr":{"zh":"你知道这件事吗？","fr":"Tu es au courant de cette histoire ?","alt":"Tu sais ce qui s'est passé ?","note":"être au courant de + 名词。"}},
 "Il paraît que...": {"pos":"loc. 无人称句式（paraître，后接直陈式）","s":"听说……；据说……。用来转述听来的消息，不保证真假：Il paraît que le nouveau restaurant est excellent。口语常缩成 Paraît que…","ipa":"[il.pa.ʁɛ.kə]","ph":"il 读 [il]；paraît 读 [pa.ʁɛ]，î 与 t 不发音；que 读 [kə]。","pi":"paraît 里 î 是重音符号（circonflexe），t 不发音，读 [pa.ʁɛ]。后面接直陈式，不用虚拟式。","et":"paraître 来自拉丁语 parescere（显现），与 apparaître 同源。","ex":[["Il paraît que le nouveau restaurant est excellent.","听说新餐厅很棒。"],["Il paraît qu'il va neiger demain.","听说明天要下雪。"]],"co":[["il paraît que + 直陈式","听说……"],["à ce qu'il paraît","据说"],["paraît-il","据说（书面）"]],"sy":[["on dit que","courant","有人说"],["il se dit que","soutenu","据说"],["j'ai entendu dire que","courant","我听说"]],"fq":"极高频，日常对话常用。","me":"paraître = 看起来；il paraît = 据说如此。","tr":{"zh":"听说他搬到巴黎去了。","fr":"Il paraît qu'il a déménagé à Paris.","alt":"Paraît qu'il est parti vivre à Paris.","note":"il paraît que 后接直陈式。"}},
 "Je te tiens au courant": {"pos":"loc. 完整句式（tenir au courant，直陈式现在时）","s":"我会随时告诉你；有消息就通知你。tenir qqn au courant = 让某人了解最新情况。正式说法：Je vous tiens au courant。","ipa":"[ʒə.tə.tjɛ̃.o.ku.ʁɑ̃]","ph":"je 读 [ʒə]；tiens 读 [tjɛ̃]，ens 为鼻化；au courant 读 [o.ku.ʁɑ̃]。","pi":"tiens 是 tenir 的变位，读 [tjɛ̃]，s 不发音；不要和 tient 区别：同音。别漏 te。","et":"tenir 来自拉丁语 tenere；au courant 见 être au courant。","ex":[["Je te tiens au courant dès que j'ai des nouvelles.","一有消息我就告诉你。"],["Tiens-moi au courant !","有消息告诉我！"]],"co":[["tenir qqn au courant","随时通知某人"],["tiens-moi au courant","随时告诉我"],["je vous tiens au courant","我会通知您（敬称）"]],"sy":[["je te préviens","courant","我提前通知你"],["je te fais signe","familier","我联系你"],["je vous informerai","soutenu","我会通知您"]],"fq":"极高频，日常和工作常用。","me":"tenir au courant = 一直「握」着消息给你。","tr":{"zh":"有新消息我会告诉你。","fr":"Je te tiens au courant s'il y a du nouveau.","alt":"Je te dis dès que j'en sais plus.","note":"tenir qqn au courant (de qqch)。"}},
 "Mettre à profit": {"pos":"loc. verbale 动词短语（mettre 为不规则动词，复合时态助动词 avoir：j'ai mis）","s":"充分利用；好好利用。mettre à profit son temps / une occasion = 利用时间、机会。带积极意味。也可写作 tirer profit de。","ipa":"[mɛ.tʁa.pʁɔ.fi]","ph":"mettre 读 [mɛtʁ]；à 读 [a]，与 mettre 连读为 [mɛ.tʁa]；profit 读 [pʁɔ.fi]，t 不发音。","pi":"profit 结尾 t 不发音；mettre 里 tt 读一个 [t]。","et":"mettre（拉丁语 mittere）+ à + profit（拉丁语 profectus，进步，益处）。","ex":[["Il faut mettre à profit ce temps libre pour étudier.","应该利用这段空闲时间学习。"],["Elle a mis à profit son séjour pour apprendre le français.","她利用居留期间学法语。"]],"co":[["mettre à profit son temps","好好利用时间"],["mettre à profit une occasion","利用机会"],["tirer profit de","从……获益"]],"sy":[["profiter de","courant","利用，享受"],["exploiter","courant","利用，开发"],["gaspiller","courant","反义：浪费"]],"fq":"中频，书面和正式场合用。","me":"mettre à profit = 把时间放到「有益」的地方。","tr":{"zh":"我们要好好利用这个暑假。","fr":"Nous devons mettre à profit ces vacances d'été.","alt":"Il faut bien profiter de ces vacances d'été.","note":"mettre à profit + 名词，没有 de。"}},
 "Mettre la main sur": {"pos":"loc. verbale 动词短语（mettre，复合时态用 avoir：j'ai mis）","s":"弄到手；找到；逮住。可指找到久寻不到的东西（un livre rare），也可指抓住某人（la police a mis la main sur le voleur）。","ipa":"[mɛ.tʁə.la.mɛ̃.syʁ]","ph":"mettre 读 [mɛtʁ]；la 读 [la]；main 读 [mɛ̃]；sur 读 [syʁ]；u 读 [y]。","pi":"main 读 [mɛ̃]，不是 [man]；sur 的 u 读 [y]。ai 在 main 中读鼻化 [ɛ̃]。","et":"mettre（拉丁语 mittere）+ main（拉丁语 manus 手）+ sur。字面意思「把手放在上面」。","ex":[["J'ai enfin mis la main sur ce livre rare.","我终于弄到了这本稀有的书。"],["La police a mis la main sur le voleur.","警察终于抓到了小偷。"]],"co":[["mettre la main sur qqch","弄到某物"],["mettre la main sur qqn","抓到某人"],["mettre la main à la pâte","亲自动手帮忙"]],"sy":[["trouver","courant","找到"],["dénicher","familier","找出，挖出"],["perdre","courant","反义：丢失"]],"fq":"中频，日常与叙述常见。","me":"「把手放在」东西上 = 弄到手。","tr":{"zh":"我终于找到了那把旧钥匙。","fr":"J'ai enfin mis la main sur cette vieille clé.","alt":"J'ai fini par retrouver cette vieille clé.","note":"mettre la main sur + 名词。"}},
 "Ne cesser de": {"pos":"loc. verbale 动词短语（cesser 第一组规则动词，后接 de + 动词原形）","s":"不停地……；一直……。ne cesser de + 动词原形 = 不断做某事：Il ne cesse de parler。是 continuer à 的强调说法，语气较书面。","ipa":"[nə.sɛ.se.də]","ph":"ne 读 [nə]；cesser 读 [sɛ.se]，c 读 [s]，ss 读 [s]，e 与 é 不同；de 读 [də]。","pi":"cesser 里 e 读 [ɛ]，er 读 [e]；否定只用 ne，没有 pas：Il ne cesse de rire。","et":"cesser 来自拉丁语 cessare（停止）。同源：cesse（止息）、incessant、sans cesse。","ex":[["Il ne cesse de parler de ses vacances.","他不停地谈他的假期。"],["La pluie ne cesse de tomber.","雨一直下个不停。"]],"co":[["ne cesser de + inf.","不停地做某事"],["sans cesse","不停地"],["ne pas cesser de","没有停止"]],"sy":[["continuer à","courant","继续"],["ne pas arrêter de","courant","不停地，更口语"],["arrêter de","courant","反义：停止"]],"fq":"中频，书面与正式场合。","me":"cesser = 停；ne cesser de = 停不下来。","tr":{"zh":"孩子们一直在笑。","fr":"Les enfants ne cessent de rire.","alt":"Les enfants n'arrêtent pas de rire.","note":"ne cesser de 只用 ne，不加 pas。"}},
 "Pour tous les goûts": {"pos":"loc. 固定短语（形容词性：用来说明「选择很多」）","s":"适合各种口味的；什么样的人都能找到喜欢的。常说 il y a (de tout) pour tous les goûts，指选择丰富。goût 在这里是「喜好、品味」，不只是味觉。","ipa":"[puʁ tus le ɡu]","ph":"tous 作形容词时 s 不发音：[tu]；les 后接辅音，不连读；goût 的 oû = [u]，t 不发音。","pi":"tous 在这里读 [tu]，不要读成 [tus]（tous 作代词才读 [tus]）。goût 结尾的 t 不发音。","et":"goût 来自拉丁语 gustus（品尝）。同源：goûter（尝；点心）、dégoûter。","ex":[["Il y a des activités pour tous les goûts.","这里有适合各种口味的活动。"],["Ce restaurant propose des plats pour tous les goûts.","这家餐厅有适合各种口味的菜。"]],"co":[["des films pour tous les goûts","适合各种口味的电影"],["Il y en a pour tous les goûts.","各种口味都有。"],["Des goûts et des couleurs, on ne discute pas.","各有所好，无需争论。"]],"sy":[["de tout","courant","什么都有（avoir de tout）"],["pour tous","courant","面向所有人，没有「口味」的意思"]],"fq":"中频，日常常用，广告和介绍里很多见。","me":"goût = 口味；tous les goûts = 每一种口味都照顾到。","tr":{"zh":"这家商店的东西适合各种口味。","fr":"Ce magasin a des articles pour tous les goûts.","alt":"Dans ce magasin, il y en a pour tous les goûts.","note":"pour tous les goûts 放在名词后面，作修饰。"}},
 "Près de": {"pos":"loc. prép. 介词短语（près 是副词，de 是介词）","s":"两个意思：1) 靠近、在……附近（près de la gare）；2) 将近、差不多（près de 100 euros）。后接名词或数字。","ipa":"[pʁɛ də]","ph":"près 的 è = [ɛ]，s 不发音；de 弱读 [də]，后接元音时省音成 d'（près d'ici）。","pi":"près de（靠近）和 prêt à（准备好）读音相近 [pʁɛ]，但意思完全不同：prêt à 后面接动词。près 结尾的 s 不发音。","et":"来自拉丁语 pressum（紧挨着，压在上面），与 presser（压）同源。","ex":[["Ce film a coûté près de 100 millions de dollars.","这部电影花了近一亿美元。"],["J'habite près de la gare.","我住在火车站附近。"],["Il est près de minuit.","快到午夜了。"]],"co":[["près de chez moi","在我家附近"],["près de + 数字","将近……"],["de près","近距离地"],["Il n'est pas loin, il est tout près.","他不远，就在旁边。"]],"sy":[["à côté de","courant","在旁边（强调紧挨着）"],["environ","courant","大约（不强调「差一点」）"],["loin de","courant","反义：离……远"]],"fq":"极高频，日常常用。","me":"près = 靠近；près de 100 = 靠近一百，也就是「差不多一百」。","tr":{"zh":"我家在地铁站附近。","fr":"Ma maison est près de la station de métro.","alt":"J'habite pas loin du métro.","note":"près de + 名词；元音前用 d'：près d'ici。"}},
 "Quitte à...": {"pos":"loc. 固定短语，后接动词不定式","s":"既然要……（那就……）；哪怕要……也要……。表示「反正都要这样，那就干脆这样做」。常和 autant 搭配：Quitte à partir, autant le faire maintenant.","ipa":"[kit a]","ph":"quitte 的 qu = [k]，e 不发音，tt 只读一个 [t]；后面的 à 与 quitte 轻轻连在一起。","pi":"quitte 末尾的 e 不发音，读 [kit]。后面必须接不定式（quitte à faire），不接变位动词。","et":"quitte 来自拉丁语 quietus（平静的，已解脱的），本义「已还清、无债一身轻」。同源：quitter（离开）。","ex":[["Quitte à partir, autant le faire maintenant.","既然要走，不如现在就走。"],["Quitte à être en retard, prenons un café.","既然要迟到了，不如先喝杯咖啡。"],["Je préfère payer plus cher, quitte à attendre.","我宁愿多付钱，哪怕要等。"]],"co":[["quitte à + 不定式, autant + 不定式","既然要……，不如……"],["quitte à tout perdre","哪怕要失去一切"],["Quitte à choisir...","既然要选的话……"]],"sy":[["autant","courant","不如（常与 quitte à 连用）"],["puisque","courant","既然（后接变位动词）"]],"fq":"中频，口语和书面都常用。","me":"quitte = 「两清」：既然已经豁出去了，就干脆做到底。","tr":{"zh":"既然要买，就买好的。","fr":"Quitte à acheter, autant prendre un bon produit.","alt":"Quitte à dépenser, je prends le meilleur.","note":"quitte à + 不定式，常接 autant。"}},
 "Tandis que": {"pos":"loc. conj. 连词短语，后接直陈式","s":"而（对比）；当……的时候（同时进行）。1) 对比：Il aime le thé, tandis que je préfère le café. 2) 同时：Je cuisine tandis que tu mets la table.","ipa":"[tɑ̃.di k(ə)]","ph":"tan [tɑ̃] 是鼻化元音，n 不单独发音；dis 的 s 读 [i]，结尾 s 不发音；que 在元音前省音为 qu'。","pi":"tandis 末尾的 s 不发音：[tɑ̃.di]。不要把 tan 读成「坦」加 n，应是鼻化元音 [ɑ̃]。","et":"来自古法语 tandis（tant 与 dis 的组合，意为「那段时间」）。后来由「同时」引申出「对比」。","ex":[["Il aime le thé, tandis que je préfère le café.","他喜欢茶，而我更喜欢咖啡。"],["Je prépare le dîner tandis que tu fais les courses.","你去买东西的时候，我做晚饭。"]],"co":[["tandis que + 直陈式","而……；当……时"],["Elle rit, tandis que lui pleure.","她在笑，而他在哭。"],["tandis que l'un... l'autre...","一个……而另一个……"]],"sy":[["alors que","courant","而；然而（更常用）"],["pendant que","courant","在……的时候（只表示同时）"],["tandis que","soutenu","书面感稍强"]],"fq":"中高频，书面和口语都用。","me":"tan-dis：想成「同一时间，两件不同的事」。","tr":{"zh":"我在看书，而他在看电视。","fr":"Je lis un livre tandis que lui regarde la télé.","alt":"Moi, je lis, alors que lui regarde la télé.","note":"tandis que 后接直陈式，不用虚拟式。"}},
 "Tu ferais mieux de...": {"pos":"loc. 固定句式（条件式 + de + 不定式）","s":"你最好……；你还是……比较好。语气是建议，有时带一点责备。ferais 是 faire 的条件式现在时，主语 tu。","ipa":"[ty fə.ʁɛ mjø də]","ph":"ferais 的 e 弱读 [fə]，ais = [ɛ]，结尾 s 不发音；mieux = [mjø]，x 不发音。","pi":"ferais 和 ferai（将来时）读音基本一样，但这里是条件式，表示建议。mieux 是副词，和 meilleur（形容词）别混。","et":"ferais 是 faire 的变位；mieux 来自拉丁语 melius（更好）。","ex":[["Tu ferais mieux de réviser pour l'examen.","你最好复习一下考试。"],["Tu ferais mieux de dormir un peu.","你最好睡一会儿。"],["Vous feriez mieux de partir maintenant.","你们最好现在就走。"]],"co":[["Tu ferais mieux de + 不定式","你最好……"],["Tu ferais mieux de te taire.","你最好闭嘴（比较直接）"],["Je ferais mieux de + 不定式","我最好还是……"]],"sy":[["Tu devrais...","courant","你应该……（更温和）"],["Il vaudrait mieux que...","soutenu","最好是……（后接虚拟式）"]],"fq":"中高频，日常对话常用。","me":"ferais mieux = 「会做得更好」：给对方的小建议。","tr":{"zh":"你最好早点出发。","fr":"Tu ferais mieux de partir plus tôt.","alt":"Tu devrais partir plus tôt.","note":"ferais mieux de + 不定式；对多人或客气说 vous feriez mieux de。"}},
 "Un tonnerre d'applaudissements": {"pos":"n.m. 阳性名词词组，复数 des tonnerres d'applaudissements（少用）","s":"雷鸣般的掌声。tonnerre 是「雷」，d'applaudissements 表示「大量掌声」。多用于演出、演讲、比赛结束时。","ipa":"[tɔ.nɛʁ da.plo.dis.mɑ̃]","ph":"tonnerre 的 nn 读一个 [n]，-erre = [ɛʁ]；applaudissements 的 au = [o]，-ent 在名词里读 [ɑ̃]，结尾 s 不发音。","pi":"applaudissements 末尾的 ents 不发音，只读 [mɑ̃]。tonnerre 的 on 读 [ɔ] 不是鼻音（因为后面是 nn）。","et":"tonnerre 来自拉丁语 tonitrus（雷）。applaudir 来自拉丁语 applaudere（拍手）。","ex":[["Le public a fait un tonnerre d'applaudissements.","观众报以雷鸣般的掌声。"],["Le chanteur a été accueilli par un tonnerre d'applaudissements.","歌手在雷鸣般的掌声中登场。"]],"co":[["un tonnerre d'applaudissements","雷鸣般的掌声"],["applaudir à tout rompre","热烈鼓掌"],["une salve d'applaudissements","一阵掌声"]],"sy":[["une ovation","soutenu","热烈欢呼；起立鼓掌"],["des bravos","courant","喝彩声"]],"fq":"低中频，多见于新闻和报道。","me":"掌声像打雷：tonnerre + applaudissements。","tr":{"zh":"演出结束后，大家热烈鼓掌。","fr":"À la fin du spectacle, il y a eu un tonnerre d'applaudissements.","alt":"À la fin, la salle a applaudi très fort.","note":"固定搭配 un tonnerre de + 复数名词（掌声、欢呼）。"}},
 "De l'humour": {"pos":"n.m. 阳性名词，复数 humours（很少用）；常以部分冠词 de l' 出现，表示「一些幽默感」","s":"幽默；幽默感。avoir de l'humour = 有幽默感。注意 humour 的 h 不发音（h muet），所以用 l'humour。","ipa":"[y.muʁ]","ph":"h 不发音；u = [y]（嘴唇圆，像「迂」）；ou = [u]；结尾 r = [ʁ]。","pi":"u [y] 和 ou [u] 容易混：humour 里先 [y] 后 [u]。h 不发音，所以 l'humour，且能连诵。别写成英文的 humor。","et":"借自英语 humour（18 世纪），而英语又来自古法语和拉丁语 humor（液体，体液）。","ex":[["Ce professeur a beaucoup d'humour.","这位老师很幽默。"],["Il a un humour très noir.","他的幽默很黑暗。"],["Je n'ai pas compris son humour.","我没懂他的幽默。"]],"co":[["avoir de l'humour","有幽默感"],["avoir le sens de l'humour","有幽默感"],["l'humour noir","黑色幽默"],["de bonne / mauvaise humeur","心情好 / 不好（注意：humeur ≠ humour）"]],"sy":[["drôlerie","soutenu","滑稽"],["esprit","courant","机智"],["ironie","courant","讽刺（带反话的幽默）"]],"fq":"高频，日常常用。","me":"humour 与英语 humor 同源；法语多一个 u：hum-our。","tr":{"zh":"他很有幽默感。","fr":"Il a beaucoup d'humour.","alt":"Il est très drôle.","note":"avoir de l'humour；beaucoup d'humour 中 de 省音为 d'。"}},
 "Du chou": {"pos":"n.m. 阳性名词，复数 choux（x 复数）；常以部分冠词 du 出现","s":"卷心菜；甘蓝。du chou 指「（一些）卷心菜」。还有 chou-fleur（花椰菜）、choux de Bruxelles（抱子甘蓝）。mon chou 是亲昵称呼「亲爱的」，chou à la crème 是奶油泡芙。","ipa":"[ʃu]","ph":"ch = [ʃ]；ou = [u]；x 在单数里不存在，复数 choux 的 x 也不发音。","pi":"复数是 choux，不是 chous。ch 读 [ʃ]，像「虚」的声母，不是 [tʃ]。","et":"来自拉丁语 caulis（茎，甘蓝）。","ex":[["J'ai préparé une soupe avec du chou.","我用卷心菜做了汤。"],["Elle a acheté un chou et des carottes.","她买了一棵卷心菜和一些胡萝卜。"],["Mon chou, viens manger !","宝贝，来吃饭！"]],"co":[["du chou rouge","紫甘蓝"],["un chou-fleur","花椰菜"],["un chou à la crème","奶油泡芙"],["mon chou","亲爱的（爱称）"]],"sy":[["chéri(e)","courant","亲爱的（爱称）"],["laitue","courant","生菜（不要混）"]],"fq":"中频，日常买菜、做饭常用。","me":"chou 是圆圆的菜，像一个小「虚」(ʃ) 球。","tr":{"zh":"我想买一点卷心菜。","fr":"Je voudrais acheter du chou.","alt":"Je vais prendre un chou.","note":"不可数用 du chou；一棵用 un chou。"}},
 "L'espoir": {"pos":"n.m. 阳性名词，复数 espoirs","s":"希望；期望。avoir de l'espoir = 抱有希望。un espoir 也可指「有希望的人」，如体育中的 un jeune espoir（新秀）。","ipa":"[ɛs.pwaʁ]","ph":"e 在 sp 前读 [ɛ]；oi = [wa]；结尾 r = [ʁ]。l' 与 espoir 连读。","pi":"espoir 读 [ɛs.pwaʁ]，oi 是 [wa]，不要读成「厄斯波尔」。注意不要和动词 espérer（希望）混淆拼写。","et":"由动词 espérer（来自拉丁语 sperare，希望）派生。","ex":[["Il ne faut jamais perdre espoir.","永远不要失去希望。"],["J'ai bon espoir de réussir.","我很有希望成功。"],["Elle garde espoir malgré tout.","她仍然抱有希望。"]],"co":[["perdre espoir","失去希望"],["avoir bon espoir","很有希望"],["l'espoir fait vivre","希望使人活下去"],["dans l'espoir de + 不定式","怀着……的希望"]],"sy":[["attente","courant","期待、等待"],["désespoir","courant","反义：绝望"],["espérance","soutenu","期望（更书面）"]],"fq":"高频，日常常用。","me":"espoir 里藏着 espérer：espérer → espoir。","tr":{"zh":"我们还有希望。","fr":"Nous avons encore de l'espoir.","alt":"Il nous reste de l'espoir.","note":"espoir 常用部分冠词：de l'espoir。"}},
 "Le mépris": {"pos":"n.m. 阳性名词，复数 mépris（单复数同形）","s":"轻蔑；蔑视。avec mépris = 轻蔑地。mépris de... 还表示「不顾、无视」（le mépris du danger，不顾危险）。","ipa":"[me.pʁi]","ph":"mé = [me]；pris = [pʁi]，结尾 s 不发音。","pi":"mépris 末尾 s 不发音。与 méprise（误会、误认）只差一个 e，意思不同：méprise [me.pʁiz]。","et":"由动词 mépriser（轻视）派生；mépriser = mé-（贬义前缀）+ priser（重视，来自 prix）。","ex":[["Il la regarde avec mépris.","他轻蔑地看着她。"],["Elle montre du mépris pour les autres.","她瞧不起别人。"],["Il agit au mépris du danger.","他不顾危险地行动。"]],"co":[["avec mépris","轻蔑地"],["éprouver du mépris pour qqn","对某人感到轻蔑"],["au mépris de + 名词","不顾……"],["un regard de mépris","轻蔑的眼神"]],"sy":[["dédain","soutenu","不屑"],["mépris","courant","轻蔑"],["respect","courant","反义：尊重"]],"fq":"中频，书面和口语都用。","me":"mé-（坏）+ pris（价值）：觉得别人「不值钱」。","tr":{"zh":"他对别人的意见很轻蔑。","fr":"Il a du mépris pour l'avis des autres.","alt":"Il méprise l'avis des autres.","note":"avoir du mépris pour qqn / qqch。"}},
 "Le réseautage": {"pos":"n.m. 阳性名词，复数 réseautages（少用）","s":"人脉经营；拓展人脉。主要用于魁北克法语，指为了工作和事业结识、联络人。在法国更常直接说 le networking。","ipa":"[ʁe.zo.taʒ]","ph":"ré = [ʁe]；eau = [o]，s 在元音间读 [z]；-tage = [taʒ]。","pi":"s 读 [z]，不是 [s]。eau 读 [o]，不是 [e.o]。词尾 -age 读 [aʒ]。","et":"由 réseau（网络，来自拉丁语 retiolum 小网，与 rete「网」同源）+ 后缀 -tage 构成，仿英语 networking。","ex":[["Le réseautage est important pour trouver un emploi.","人脉经营对找工作很重要。"],["Elle fait du réseautage lors des conférences.","她在会议上拓展人脉。"]],"co":[["faire du réseautage","经营人脉"],["un événement de réseautage","交流联谊活动"],["le réseautage professionnel","职场人脉"]],"sy":[["networking","familier","同义的英语借词"],["réseau","courant","人脉；网络（名词）"],["relations","courant","人际关系"]],"fq":"低中频，工作和求职话题里出现。","me":"réseau（网）+ -tage：织一张属于自己的人脉网。","tr":{"zh":"人脉经营可以帮你找到工作。","fr":"Le réseautage peut t'aider à trouver du travail.","alt":"Avoir un bon réseau t'aide à trouver du travail.","note":"faire du réseautage：用部分冠词 du。"}},
 "Le sentiment de supériorité": {"pos":"n.m. 阳性名词词组，复数 des sentiments de supériorité","s":"优越感。sentiment 是「感觉、情感」，supériorité 是「优越」。常带贬义，指觉得自己比别人高一等。反义：le complexe d'infériorité（自卑感）。","ipa":"[sɑ̃.ti.mɑ̃ də sy.pe.ʁjɔ.ʁi.te]","ph":"sentiment 里两个 en 都读 [ɑ̃]（最后的 t 不发音）；supériorité 的 u = [y]，ié 分成 [e.ʁjɔ]，以 -té [te] 结尾。","pi":"sentiment 的 en 不要读成 [ɛn]。supériorité 是长词，按 su-pé-rio-ri-té 拆音节读。","et":"sentiment 来自 sentir（拉丁语 sentire，感觉）。supériorité 来自拉丁语 superior（更高的）。","ex":[["Son sentiment de supériorité est agaçant.","他的优越感令人恼火。"],["Elle a un sentiment de supériorité envers ses collègues.","她对同事有优越感。"]],"co":[["avoir un sentiment de supériorité","有优越感"],["un complexe de supériorité","优越情结"],["se sentir supérieur(e)","觉得自己高人一等"]],"sy":[["arrogance","courant","傲慢"],["suffisance","soutenu","自负"],["infériorité","courant","反义：自卑"]],"fq":"中低频，谈论态度和性格时用。","me":"super（高）+ ior：站在「上面」看别人。","tr":{"zh":"他总有一种优越感。","fr":"Il a toujours un sentiment de supériorité.","alt":"Il se croit toujours supérieur aux autres.","note":"sentiment de + 名词：……的感觉。"}},
 "Un bénéfice": {"pos":"n.m. 阳性名词，复数 bénéfices","s":"利润；盈利（faire un bénéfice）。也指「好处、益处」（le bénéfice du doute，存疑从无；au bénéfice de，为了……的利益）。","ipa":"[be.ne.fis]","ph":"bé = [be]；né = [ne]；fice = [fis]，c 在 i 前读 [s]，e 不发音。","pi":"三个音节都清楚读：be-ne-fis。结尾 ce 读 [s]。不要读成英文的 benefit。","et":"来自拉丁语 beneficium（善行，恩惠），由 bene（好）+ facere（做）构成。同源：bienfait。","ex":[["L'entreprise a fait un bon bénéfice cette année.","公司今年盈利不错。"],["Je te laisse le bénéfice du doute.","我给你存疑从无的机会。"],["Ce traitement apporte de grands bénéfices.","这种治疗好处很大。"]],"co":[["faire un bénéfice","盈利"],["le bénéfice du doute","疑罪从无；给对方信任"],["au bénéfice de qqn","为了某人的利益"],["un bénéfice net","净利润"]],"sy":[["profit","courant","利润（更泛指）"],["avantage","courant","好处、优势"],["perte","courant","反义：亏损"]],"fq":"中高频，经济和日常话题都常见。","me":"béné- = bien（好）+ fice = fait（做）：做得好就有「好处」。","tr":{"zh":"这家公司今年有很多利润。","fr":"Cette entreprise a fait beaucoup de bénéfices cette année.","alt":"Cette société a bien gagné d'argent cette année.","note":"faire des bénéfices：赚取利润，常用复数。"}},
 "Un béret": {"pos":"n.m. 阳性名词，复数 bérets","s":"贝雷帽。圆而扁、没有帽檐的软帽，常被看作法国人的形象。也指军队中的贝雷帽（un béret rouge）。","ipa":"[be.ʁɛ]","ph":"bé = [be]；rét 的 é 在这里是 [ɛ]（t 结尾，不发音）。","pi":"结尾 t 不发音，读 [be.ʁɛ]。r 是小舌音 [ʁ]，不是舌尖的 [r]。","et":"来自béarnais（法国西南）方言 berret，与比利牛斯山区的牧民帽有关。","ex":[["Mon grand-père porte toujours un béret.","我爷爷总戴贝雷帽。"],["Il met son béret pour sortir.","他戴上贝雷帽出门。"]],"co":[["porter un béret","戴贝雷帽"],["un béret basque","巴斯克贝雷帽"],["un béret rouge / vert","红色 / 绿色贝雷帽（军队）"]],"sy":[["chapeau","courant","帽子（泛指）"],["casquette","courant","鸭舌帽"],["bonnet","courant","毛线帽"]],"fq":"低中频，与服饰和法国文化相关。","me":"béret 的结尾 t 不发音：像「贝瑞」。","tr":{"zh":"他戴着一顶红色贝雷帽。","fr":"Il porte un béret rouge.","alt":"Il a un béret rouge sur la tête.","note":"porter 表示「戴着」这一状态。"}},
 "Un chignon": {"pos":"n.m. 阳性名词，复数 chignons","s":"发髻；盘发。把头发盘在后脑或头顶。常说 un chignon bas / haut（低发髻 / 高发髻）。","ipa":"[ʃi.ɲɔ̃]","ph":"ch = [ʃ]；gn = [ɲ]，像「宁」里的 ni；-on = [ɔ̃]，鼻化元音，n 不单独发音。","pi":"gn 读 [ɲ]（一个音），不是 [g]+[n]。结尾 on 是鼻化元音，别读成「翁」加 n。","et":"可能来自古法语 chaignon（颈后、颈椎一带），与拉丁语 catena（链）有关。起源有一定推测成分。","ex":[["Elle a les cheveux attachés en chignon.","她把头发盘成发髻。"],["Elle fait un chignon avant le cours de danse.","上舞蹈课前她盘了个发髻。"]],"co":[["faire un chignon","盘发髻"],["un chignon bas / haut","低 / 高发髻"],["les cheveux en chignon","盘起来的头发"]],"sy":[["queue de cheval","courant","马尾辫"],["natte","courant","辫子"],["tresse","courant","辫子（更常说）"]],"fq":"中频，描述发型时常用。","me":"chignon 里有 gn，像「宁」：盘起来的头发。","tr":{"zh":"她今天把头发盘成了发髻。","fr":"Aujourd'hui, elle a fait un chignon.","alt":"Aujourd'hui, elle a les cheveux en chignon.","note":"en chignon：以发髻的形式。"}},
 "Un chirurgien": {"pos":"n.m. 阳性名词，阴性 une chirurgienne，复数 chirurgiens","s":"外科医生。做手术的医生。女性说 une chirurgienne。médecin 是医生的统称，chirurgien 是其中做手术的一类。","ipa":"[ʃi.ʁyʁ.ʒjɛ̃]","ph":"ch 在这里读 [ʃ]；u = [y]；g 在 i 前读 [ʒ]；-ien = [jɛ̃]。","pi":"chir- 里的 ch 读 [ʃ]，不是 [k]。-ien 读 [jɛ̃]，不是 [jɛn]。u [y] 要把嘴唇圆起来。","et":"来自希腊语 kheirourgia（手工，手术）：kheir（手）+ ergon（工作）。同源：chirurgie。","ex":[["Le chirurgien va l'opérer demain.","外科医生明天给他动手术。"],["Ma sœur est chirurgienne dans un grand hôpital.","我姐姐是一家大医院的外科医生。"]],"co":[["un chirurgien cardiaque","心脏外科医生"],["un chirurgien-dentiste","牙科医生"],["voir un chirurgien","找外科医生看"]],"sy":[["médecin","courant","医生（泛指）"],["docteur","courant","医生；称呼用语"],["praticien","soutenu","执业医生"]],"fq":"中频，医疗话题里常用。","me":"kheir（手）+ ergon（工作）= 用手工作的医生。","tr":{"zh":"这位外科医生很有经验。","fr":"Ce chirurgien a beaucoup d'expérience.","alt":"C'est un chirurgien très expérimenté.","note":"女医生：cette chirurgienne。"}},
 "Un compliment": {"pos":"n.m. 阳性名词，复数 compliments","s":"赞美；夸奖。faire un compliment à qqn = 夸某人。复数 des compliments 还可表示「致意、祝贺」（Mes compliments ! = 恭喜！）。","ipa":"[kɔ̃.pli.mɑ̃]","ph":"com = [kɔ̃]（鼻化元音）；pli = [pli]；ment = [mɑ̃]，t 不发音。","pi":"com- 读 [kɔ̃]，不读 [kɔm]；-ment 读 [mɑ̃]，t 不发音。不要和 complément（补语、补充）混淆。","et":"来自西班牙语（或意大利语）的借词，词根是拉丁语 complere（填满，完成）。原意与「礼节上的圆满」有关。","ex":[["Elle m'a fait un beau compliment sur ma robe.","她夸奖了我的裙子。"],["Merci pour le compliment !","谢谢你的夸奖！"],["Mes compliments pour ce dîner !","这顿晚饭太棒了，恭喜！"]],"co":[["faire un compliment","夸奖"],["recevoir un compliment","得到夸奖"],["Mes compliments !","恭喜你！做得好！"],["un compliment sincère","真诚的夸奖"]],"sy":[["éloge","soutenu","称赞（较正式）"],["félicitations","courant","祝贺"],["critique","courant","反义：批评"]],"fq":"高频，日常常用。","me":"com-pli-ment：让对方的脸上「堆满」笑意。","tr":{"zh":"他夸我的法语说得很好。","fr":"Il m'a fait un compliment sur mon français.","alt":"Il m'a dit que je parlais bien français.","note":"faire un compliment à qqn sur qqch。"}},
 "Un critère": {"pos":"n.m. 阳性名词，复数 critères","s":"标准；准则。用来判断、选择的依据。常见：les critères de sélection（选拔标准）。","ipa":"[kʁi.tɛʁ]","ph":"cri = [kʁi]；tère = [tɛʁ]，è = [ɛ]，结尾 e 不发音但 r 要读。","pi":"è 是 [ɛ]，结尾 r 要发出来：[kʁi.tɛʁ]。别和 critique（批评）混淆。","et":"来自希腊语 kritērion（判断的方法），源自 krinein（分辨，判断）。同源：critique、crise。","ex":[["L'expérience est un critère important pour ce poste.","经验是这个职位的重要标准。"],["Quel est votre critère de choix ?","您选择的标准是什么？"],["Le prix n'est pas mon seul critère.","价格不是我唯一的标准。"]],"co":[["un critère de sélection","选拔标准"],["répondre aux critères","符合标准"],["selon quels critères ?","按照什么标准？"],["un critère essentiel","关键标准"]],"sy":[["norme","courant","规范、标准"],["condition","courant","条件"],["repère","courant","参照点"]],"fq":"中高频，工作、学习场景常见。","me":"critère → critique：先有「判断的标准」，才有「评价」。","tr":{"zh":"价格是我最重要的标准。","fr":"Le prix est mon critère le plus important.","alt":"Pour moi, le plus important, c'est le prix.","note":"critère 是阳性：un critère。"}},
 "Un fantasme": {"pos":"n.m. 阳性名词，复数 fantasmes","s":"幻想；妄想。可以是不切实际的想象（un fantasme de réussite），也可以指性幻想。强调与现实不符。","ipa":"[fɑ̃.tasm]","ph":"fan = [fɑ̃]（鼻化元音）；tasme = [tasm]，s 读 [s]，结尾 e 不发音。","pi":"an 读鼻化元音 [ɑ̃]。结尾 -sme 读 [sm]，e 不发音，不是 [fɑ̃.ta.smə]。","et":"来自希腊语 phantasma（幻象），源自 phantazein（使显现）。同源：fantaisie、fantôme。","ex":[["La vision très romantique de la France est un fantasme, ça n'existe que dans les films.","对法国的浪漫想象只是幻想，只存在于电影里。"],["Pour lui, vivre sur une île est un fantasme.","对他来说，住在岛上是个幻想。"]],"co":[["vivre dans un fantasme","活在幻想里"],["réaliser un fantasme","实现一个幻想"],["c'est un fantasme","那只是幻想"]],"sy":[["illusion","courant","错觉、幻想"],["rêve","courant","梦想"],["chimère","littéraire","空想、妄想"]],"fq":"中频，谈论想象与现实时常用。","me":"fantasme 与 fantôme 同源：看得见却不真实。","tr":{"zh":"这只是我的幻想。","fr":"Ce n'est qu'un fantasme.","alt":"C'est juste un fantasme à moi.","note":"ne... que = 只是；fantasme 是阳性。"}},
 "Un frein": {"pos":"n.m. 阳性名词，复数 freins","s":"刹车；制动。引申为阻碍、抑制（un frein à la croissance，对增长的阻碍）。常见：un coup de frein（踩一脚刹车）。","ipa":"[fʁɛ̃]","ph":"fr = [fʁ]；ein = [ɛ̃]，鼻化元音；结尾 n 不单独发音。","pi":"ein 读 [ɛ̃]，不是 [ɛn]。r 小舌音。别和 faim [fɛ̃]（饥饿）混写，它们读音相同。","et":"来自拉丁语 frenum（马嚼子，缰绳）。同源：freiner（刹车），refréner（抑制）。","ex":[["La peur de l'échec est souvent un frein.","害怕失败往往是个阻碍。"],["Le conducteur a donné un coup de frein.","司机踩了一脚刹车。"],["Le manque de temps est un frein pour moi.","没有时间是我的一个阻碍。"]],"co":[["un coup de frein","踩刹车"],["un frein à + 名词","对……的阻碍"],["le frein à main","手刹"],["mettre un frein à qqch","遏制某事"]],"sy":[["obstacle","courant","障碍"],["blocage","courant","阻塞、卡住"],["accélérateur","courant","反义：油门；促进者"]],"fq":"中高频，开车和谈论障碍时都常用。","me":"frein [fʁɛ̃] 与 faim、fin 同音：听音时靠上下文区分。","tr":{"zh":"缺钱是个很大的阻碍。","fr":"Le manque d'argent est un gros frein.","alt":"Ne pas avoir d'argent, ça nous bloque beaucoup.","note":"être un frein à / pour qqch：对……是阻碍。"}},
 "Un grief": {"pos":"n.m. 阳性名词，复数 griefs；多用复数 des griefs","s":"不满；怨言；抱怨的理由。多用复数：exposer ses griefs（说出自己的不满）。是比较正式的词。","ipa":"[ɡʁijɛf]","ph":"gr = [ɡʁ]；ie 读 [jɛ]；f 要读出来。","pi":"结尾 f 要发音：[ɡʁijɛf]。别和英语 grief（悲痛）混：法语 grief 是「不满、怨言」，不是悲伤。","et":"来自古法语 grief（沉重的，痛苦的），源自拉丁语 gravis（重的）。同源：grave、grever。","ex":[["Les employés ont présenté leurs griefs à la direction.","员工们向管理层表达了不满。"],["Quels sont vos griefs contre lui ?","您对他有什么不满？"]],"co":[["avoir des griefs contre qqn","对某人有怨言"],["exposer ses griefs","陈述不满"],["faire grief à qqn de qqch","责怪某人某事"]],"sy":[["reproche","courant","责备"],["plainte","courant","投诉"],["doléance","soutenu","诉苦、怨言"]],"fq":"低中频，偏书面、职场和法律。","me":"grief 来自 grave（沉重）：心里压着的「重」事。","tr":{"zh":"他对老板有很多不满。","fr":"Il a beaucoup de griefs contre son patron.","alt":"Il en veut beaucoup à son patron.","note":"多用复数 griefs；faire grief à qqn de qqch。"}},
 "Un HLM": {"pos":"n.m. 阳性名词（缩略词），常用阳性，也有人说阴性 une HLM；复数 des HLM（不变）","s":"廉租房；社会福利住房。HLM 是 habitation à loyer modéré（租金适中的住房）的缩写，由国家或地方政府提供给收入较低的家庭。","ipa":"[aʃ.ɛl.ɛm]","ph":"按字母读：H [aʃ]，L [ɛl]，M [ɛm]；三个字母连读。","pi":"H 在这里读 [aʃ]，不是不发音。缩略词复数不加 s：des HLM。性别：常说 un HLM，但 habitation 是阴性，所以也有人说 une HLM。","et":"缩略词，来自 habitation à loyer modéré：habitation（住所）+ loyer（租金）+ modéré（适度的）。1950 年代起使用。","ex":[["Il a grandi dans un HLM en banlieue.","他在郊区的廉租房里长大。"],["Ils ont enfin trouvé un appartement en HLM.","他们终于找到了一套廉租房。"]],"co":[["habiter en HLM","住在廉租房"],["un immeuble HLM","廉租房楼"],["demander un HLM","申请廉租房"]],"sy":[["logement social","courant","社会住房（官方说法）"],["cité","familier","住宅区（常指郊区公寓楼群）"]],"fq":"中频，谈论住房和社会话题时常见。","me":"H-L-M：Habitation à Loyer Modéré，读三个字母。","tr":{"zh":"他们住在一套廉租房里。","fr":"Ils habitent dans un HLM.","alt":"Ils vivent en HLM.","note":"habiter dans un HLM / en HLM。"}},
 "Un jury": {"pos":"n.m. 阳性名词，复数 jurys","s":"评审团；陪审团；考试评委会。用于比赛、考试、法庭。jury 是一个集体名词，整组人；组内一个人叫 un membre du jury 或在法庭里叫 un juré。","ipa":"[ʒy.ʁi]","ph":"j = [ʒ]；u = [y]；ry = [ʁi]，y 在这里读 [i]。","pi":"u 读 [y]（圆唇），不是 [u]。别按英语读成 [dʒʊri]。","et":"借自英语 jury，源自古法语 jurée（宣誓），来自拉丁语 jurare（发誓）。","ex":[["Le jury délibère avant de donner son verdict.","评审团在宣布结果前先商议。"],["Elle est membre du jury du concours.","她是比赛评审团的成员。"]],"co":[["un membre du jury","评委"],["le jury délibère","评审团商议"],["le jury d'examen","考试评委会"],["un jury populaire","民众陪审团"]],"sy":[["comité","courant","委员会"],["jurés","courant","陪审员（法庭）"],["juge","courant","法官；评判者"]],"fq":"中频，比赛、考试、法庭话题常见。","me":"jury 与 jurer（发誓）同源：评委要「宣誓」公正。","tr":{"zh":"评审团选出了最佳作品。","fr":"Le jury a choisi la meilleure œuvre.","alt":"Le jury a élu le meilleur travail.","note":"jury 是单数集体名词，动词用单数。"}},
 "Un miroir déformant": {"pos":"n.m. 阳性名词词组，复数 des miroirs déformants","s":"哈哈镜；变形镜。也常作比喻：un miroir déformant de la réalité = 扭曲现实的镜子。déformant 是形容词，来自动词 déformer。","ipa":"[mi.ʁwaʁ de.fɔʁ.mɑ̃]","ph":"miroir 的 oi = [wa]，结尾 r 要读；déformant 的 an = [ɑ̃]，结尾 t 不发音。","pi":"déformant 末尾的 -ant 读 [ɑ̃]，t 不发音。miroir 的 r 要读出来。","et":"miroir 来自古法语 mireor，源自 mirer（看，注视）。déformant = dé-（去除、变坏）+ former（成形，拉丁语 formare）。","ex":[["Les réseaux sociaux sont parfois un miroir déformant de la réalité.","社交网络有时是现实的哈哈镜。"],["Au parc d'attractions, on rit devant le miroir déformant.","在游乐园里，大家对着哈哈镜笑。"]],"co":[["un miroir déformant","哈哈镜；扭曲的镜子"],["se regarder dans le miroir","照镜子"],["un miroir de la société","社会的镜子"]],"sy":[["glace","courant","镜子（家用）"],["reflet","courant","倒影"],["distorsion","soutenu","扭曲"]],"fq":"低中频，比喻用法比较常见。","me":"mir（看）+ oir：看自己的东西；déformant = 把你看变形。","tr":{"zh":"社交网络有时是个哈哈镜。","fr":"Les réseaux sociaux sont parfois un miroir déformant.","alt":"Les réseaux sociaux montrent parfois une image fausse de la réalité.","note":"déformant 作形容词，放在名词后。"}},
 "Un préjugé": {"pos":"n.m. 阳性名词，复数 préjugés","s":"偏见；成见。事先形成的看法，常是不公平或不正确的。avoir des préjugés sur... = 对……有偏见。","ipa":"[pʁe.ʒy.ʒe]","ph":"pré = [pʁe]；ju = [ʒy]；gé = [ʒe]。两个 g/j 都读 [ʒ]。","pi":"u 读 [y]（圆唇）。结尾 é 读 [e]，不是 [ɛ]。别和 préjudice（损害）混：préjudice [pʁe.ʒy.dis]。","et":"pré-（先）+ jugé（judicare 判断）：「事先下的判断」。同源：juger、jugement。","ex":[["Il faut lutter contre les préjugés.","必须与偏见作斗争。"],["Elle a des préjugés sur les jeunes.","她对年轻人有偏见。"],["Sans préjugé, il écoute tout le monde.","他不带偏见地听每个人说话。"]],"co":[["avoir des préjugés","有偏见"],["lutter contre les préjugés","对抗偏见"],["un préjugé tenace","根深蒂固的偏见"],["sans préjugé","不带偏见"]],"sy":[["a priori","soutenu","先入之见"],["stéréotype","courant","刻板印象"],["parti pris","courant","成见、偏袒"]],"fq":"中高频，社会话题常用。","me":"pré-（先）+ jugé（判断）= 还没了解就先判断。","tr":{"zh":"我们不应该有偏见。","fr":"Nous ne devons pas avoir de préjugés.","alt":"Il ne faut pas avoir de préjugés.","note":"否定后用 de：pas de préjugés。"}},
 "Un prix": {"pos":"n.m. 阳性名词，复数 prix（单复数同形）","s":"奖；奖项（le prix Nobel）。同一个词也是「价格」（le prix d'un billet）和「代价」（à tout prix，不惜代价）。看上下文区分。","ipa":"[pʁi]","ph":"pr = [pʁ]；ix 结尾不发音，只读 [pʁi]。","pi":"结尾 x 不发音。复数形式与单数相同：un prix, des prix。别和 prise（抓取）、pris（拿，过去分词）混。","et":"来自拉丁语 pretium（价值，价格）。「奖」是从「价值」引申而来。同源：priser、précieux。","ex":[["Le prix du meilleur auteur a été décerné hier soir.","最佳作者奖昨晚颁发。"],["Quel est le prix de ce livre ?","这本书多少钱？"],["Il a gagné le premier prix.","他获得了一等奖。"]],"co":[["remporter / gagner un prix","获奖"],["le prix Nobel","诺贝尔奖"],["à tout prix","不惜一切代价"],["un prix littéraire","文学奖"]],"sy":[["récompense","courant","奖励"],["distinction","soutenu","荣誉"],["trophée","courant","奖杯"]],"fq":"极高频，日常常用。","me":"prix 一词多义：价格、奖、代价，都是「值多少」。","tr":{"zh":"这位作家获得了一个大奖。","fr":"Cet écrivain a reçu un grand prix.","alt":"Cet auteur a gagné un prix important.","note":"prix 单复数同形：des prix。"}},
 "Un processus": {"pos":"n.m. 阳性名词，复数 processus（单复数同形）","s":"过程；程序；进程。指一系列依次发生的变化或步骤（un processus de paix，和平进程）。比 étape（阶段）更强调整体。","ipa":"[pʁɔ.se.sys]","ph":"pro = [pʁɔ]；ces = [se]；sus = [sys]，结尾 s 要读 [s]。","pi":"结尾 -us 的 s 要读出来：[sys]，这是少数末尾 s 要发音的词。u 读 [y]。","et":"来自拉丁语 processus（前进，进展），源自 procedere（向前走）。同源：procès、procédure。","ex":[["L'apprentissage d'une langue est un long processus.","学一门语言是一个漫长的过程。"],["Le processus de fabrication prend deux jours.","制造过程需要两天。"]],"co":[["un long processus","漫长的过程"],["un processus de décision","决策过程"],["un processus de paix","和平进程"],["engager un processus","开启一个进程"]],"sy":[["procédé","soutenu","方法、手段"],["étape","courant","阶段"],["évolution","courant","演变"]],"fq":"中高频，工作、科学、新闻里常见。","me":"pro-cessus：向前（pro）走（cedere）的过程。","tr":{"zh":"学法语是一个漫长的过程。","fr":"Apprendre le français est un long processus.","alt":"Apprendre le français, ça prend du temps.","note":"processus 单复数同形，结尾 s 读 [s]。"}},
 "Un profit": {"pos":"n.m. 阳性名词，复数 profits","s":"利润；好处；收益。1) 钱方面的利润（faire du profit）；2) 好处，益处（tirer profit de qqch，从中受益）。","ipa":"[pʁɔ.fi]","ph":"pro = [pʁɔ]；fit 的 t 不发音，读 [fi]。","pi":"结尾 t 不发音：[pʁɔ.fi]。别按英语 profit 读成 [ˈprɒfɪt]。","et":"来自拉丁语 profectus（进步，进展），源自 proficere（前进，有益）。同源：profiter（受益）、profitable。","ex":[["Nous reversons nos profits à une association.","我们把利润捐给一个协会。"],["Il a tiré profit de son voyage.","他从旅行中获益。"],["Elle étudie avec profit.","她学习很有收获。"]],"co":[["faire un profit","盈利"],["tirer profit de qqch","从某事中获益"],["au profit de qqn","为了某人的利益"],["sans but lucratif / à but non lucratif","非营利的"]],"sy":[["bénéfice","courant","利润（更常用于公司账目）"],["gain","courant","收益"],["avantage","courant","好处"]],"fq":"中高频，经济和日常话题都常见。","me":"profit → profiter：从中「受益」。","tr":{"zh":"公司把利润用来帮助别人。","fr":"L'entreprise utilise ses profits pour aider les autres.","alt":"La société met ses profits au service des autres.","note":"profit 多用复数表示总利润。"}},
 "Un puits": {"pos":"n.m. 阳性名词，复数 puits（单复数同形）","s":"井。取水的井，也有 un puits de pétrole（油井）。比喻用法：un puits de science（学识渊博的人）。","ipa":"[pɥi]","ph":"pu 读 [pɥ]（半元音，像「普」快速滑向 i）；its 结尾的 t、s 都不发音。","pi":"结尾 ts 都不发音，整个词只读 [pɥi]。u 与 i 连起来读 [ɥi]，不是 [py.i]。","et":"来自拉丁语 puteus（井）。","ex":[["Ils ont creusé un puits pour trouver de l'eau.","他们挖了一口井找水。"],["Il y a un vieux puits dans le jardin.","花园里有一口老井。"]],"co":[["creuser un puits","挖井"],["un puits de pétrole","油井"],["un puits de science","博学的人"],["l'eau du puits","井水"]],"sy":[["source","courant","泉水；水源"],["forage","soutenu","钻井"],["citerne","courant","蓄水池"]],"fq":"中低频，农村、历史和比喻中出现。","me":"puits 只有一个 [pɥi]：t 和 s 都是「哑巴」。","tr":{"zh":"村子里有一口老井。","fr":"Il y a un vieux puits dans le village.","alt":"Dans le village, il y a un vieux puits.","note":"puits 单复数同形。"}},
 "Un rebondissement": {"pos":"n.m. 阳性名词，复数 rebondissements","s":"剧情反转；新的转折。多指故事、案件、比赛中出人意料的新进展。字面是「又弹起来」（rebondir 弹回、重新开始）。","ipa":"[ʁə.bɔ̃.dis.mɑ̃]","ph":"re 弱读 [ʁə]；bon = [bɔ̃]；dis = [dis]；ment = [mɑ̃]，t 不发音。","pi":"bon 中的 on 是鼻化元音 [ɔ̃]。-ement 读 [mɑ̃]，t 不发音。dissement 里的 ss 读 [s]。","et":"由 rebondir（re- 再 + bondir 跳）+ -ment 构成。bondir 的更早来源不确定，这里不展开。","ex":[["Ce film est plein de rebondissements.","这部电影充满转折。"],["L'enquête a connu un nouveau rebondissement.","调查出现了新的转折。"],["Quel rebondissement !","多么出人意料的转折！"]],"co":[["un nouveau rebondissement","新的转折"],["plein de rebondissements","充满转折"],["un rebondissement inattendu","出人意料的转折"]],"sy":[["coup de théâtre","courant","戏剧性的大转折"],["revirement","soutenu","突然转变"],["péripétie","soutenu","意外事件，波折"]],"fq":"中频，谈论电影、小说、新闻时常用。","me":"re-bond：球再次弹起，故事又被带向新的方向。","tr":{"zh":"这个故事有很多转折。","fr":"Cette histoire a beaucoup de rebondissements.","alt":"Cette histoire est pleine de rebondissements.","note":"plein de + 复数名词。"}},
 "Un séjour": {"pos":"n.m. 阳性名词，复数 séjours","s":"逗留；停留；小住。指在某地住一段时间（旅行、疗养、学习）。un séjour linguistique = 语言游学。","ipa":"[se.ʒuʁ]","ph":"sé = [se]；j = [ʒ]；our = [uʁ]，r 要发音。","pi":"结尾 r 要读出来：[se.ʒuʁ]。séjour 的 é 有重音符号，别漏掉；动词是 séjourner（逗留）。","et":"来自动词 séjourner（古法语 sejorner），源自晚期拉丁语 *subdiurnare（停留一些日子）。","ex":[["J'ai passé un agréable séjour à la montagne.","我在山里度过了愉快的时光。"],["Elle fait un séjour de deux semaines à Paris.","她要在巴黎待两周。"],["Bon séjour !","旅途愉快！"]],"co":[["faire un séjour","逗留；小住"],["Bon séjour !","祝你住得愉快！"],["un séjour linguistique","语言游学"],["la durée du séjour","停留时间"]],"sy":[["voyage","courant","旅行（强调路上）"],["vacances","courant","假期"],["escale","courant","中途停靠"]],"fq":"高频，旅游、留学话题常用。","me":"séjour 里有 jour（日）：待上几个「日子」。","tr":{"zh":"我在法国待了两周。","fr":"J'ai fait un séjour de deux semaines en France.","alt":"Je suis resté deux semaines en France.","note":"faire un séjour de + 时间。"}},
 "Un stand": {"pos":"n.m. 阳性名词，复数 stands","s":"摊位；展位；展台。集市、展览会上摆东西的位置。也有 un stand de tir（射击场）。","ipa":"[stɑ̃d]","ph":"st = [st]；an = [ɑ̃]；结尾 d 要读 [d]（和 an 不连成一个鼻音）。","pi":"an 读鼻化元音 [ɑ̃]，同时结尾 d 要发音：[stɑ̃d]，不要读成 [stɑ̃]。","et":"借自英语 stand（站立处，台），19 世纪进入法语，用于展览和射击场。","ex":[["Les stands de boissons sont à côté des stands de nourriture.","饮品摊位在食品摊位旁边。"],["Venez visiter notre stand au salon !","欢迎到展会参观我们的展位！"]],"co":[["tenir un stand","守摊位"],["un stand de nourriture","食品摊位"],["un stand d'information","咨询台"],["un stand de tir","射击场"]],"sy":[["étal","courant","(市场里的)货摊"],["kiosque","courant","报亭、小亭子"],["comptoir","courant","柜台"]],"fq":"中频，展会、集市话题常用。","me":"stand 与英语 stand 同形：站在那里卖东西。","tr":{"zh":"我们的展位在入口旁边。","fr":"Notre stand est à côté de l'entrée.","alt":"Notre stand se trouve près de l'entrée.","note":"à côté de + 名词。"}},
 "Un stéréotype": {"pos":"n.m. 阳性名词，复数 stéréotypes","s":"刻板印象；老套的看法。把一群人或一件事简单化的固定想法。形容词形式：stéréotypé（千篇一律的）。","ipa":"[ste.ʁe.ɔ.tip]","ph":"sté = [ste]；ré = [ʁe]；o 单独读 [ɔ]；type = [tip]，y 读 [i]。","pi":"共五个音节，里面有 é、é、o、y 四个元音，读时别连成一团。y 读 [i]，结尾 e 不发音。","et":"来自希腊语 stereos（坚固的）+ typos（印记）。原指印刷中的固定铅版，后来引申为「固定不变的看法」。","ex":[["Ce film est plein de stéréotypes.","这部电影充满刻板印象。"],["Il faut lutter contre les stéréotypes.","要对抗刻板印象。"]],"co":[["un stéréotype sur + 名词","对……的刻板印象"],["briser un stéréotype","打破刻板印象"],["les stéréotypes de genre","性别刻板印象"],["véhiculer un stéréotype","传播刻板印象"]],"sy":[["cliché","courant","老套、陈词滥调"],["préjugé","courant","偏见"],["idée reçue","courant","人云亦云的看法"]],"fq":"中频，社会、文化话题常用。","me":"stéréo（固定）+ type（印记）：印死了的形象。","tr":{"zh":"我们要打破刻板印象。","fr":"Nous devons briser les stéréotypes.","alt":"Il faut casser les stéréotypes.","note":"briser / casser les stéréotypes。"}},
 "Un traitement de faveur": {"pos":"n.m. 阳性名词词组，复数 des traitements de faveur","s":"优待；特殊照顾。给某人比别人更好的待遇，常暗示不公平。traitement 还可指「治疗」和「薪水」。","ipa":"[tʁɛt.mɑ̃ də fa.vœʁ]","ph":"traitement 里的 ai = [ɛ]，e 不发音，结构 [tʁɛt.mɑ̃]；faveur 的 eu = [œ]，结尾 r 要读。","pi":"traitement 中间的 e 不发音：[tʁɛt.mɑ̃]。faveur 的 eu 读 [œ]，别读成 [ø]。","et":"traitement 来自 traiter（拉丁语 tractare，处理）+ -ment；faveur 来自拉丁语 favor（好感，偏爱）。","ex":[["Le patron lui accorde un traitement de faveur.","老板给他特殊照顾。"],["Je ne veux pas de traitement de faveur.","我不想要特殊待遇。"]],"co":[["accorder un traitement de faveur","给予优待"],["bénéficier d'un traitement de faveur","享受优待"],["un tarif de faveur","优惠价"]],"sy":[["privilège","courant","特权"],["passe-droit","courant","走后门的特权"],["favoritisme","courant","偏袒"]],"fq":"中低频，新闻和职场话题常见。","me":"de faveur = 因为「喜欢你」才给的特别待遇。","tr":{"zh":"他得到了特殊照顾。","fr":"Il a eu un traitement de faveur.","alt":"On l'a traité mieux que les autres.","note":"traitement de faveur：de 后无冠词。"}},
 "L'espace Schengen": {"pos":"n.m. 阳性名词词组，专有名词；espace 是阳性","s":"申根区。欧洲多国取消内部边境检查、人员可自由往来的区域。名称来自卢森堡的小村庄 Schengen，1985 年协议在那里签署。","ipa":"[ɛs.pas ʃɛŋ.ɡɛn]","ph":"espace 的 e 读 [ɛ]；ace 读 [as]；Schengen 来自德语，读 [ʃɛŋ.ɡɛn]，sch = [ʃ]，g 读 [ɡ]。","pi":"Schengen 的 sch 读 [ʃ]，不是 [sk]。g 读 [ɡ]（来自德语），也有人读成 [ʃɛ̃.ɡɛn]。","et":"espace 来自拉丁语 spatium。Schengen 是卢森堡的村庄，1985 年和 1990 年相关协议在此签署。","ex":[["L'espace Schengen facilite les voyages en Europe.","申根区方便在欧洲旅行。"],["Pour entrer dans l'espace Schengen, il faut un visa.","进入申根区需要签证。"]],"co":[["l'espace Schengen","申根区"],["un pays de l'espace Schengen","申根国家"],["sortir de l'espace Schengen","离开申根区"],["un visa Schengen","申根签证"]],"sy":[["zone Schengen","courant","申根区（同义说法）"],["Union européenne","courant","欧盟（不完全相同）"]],"fq":"中频，旅行和欧洲新闻中常见。","me":"Schengen：一个小村庄，让整个欧洲「通行」。","tr":{"zh":"申根区有很多国家。","fr":"L'espace Schengen compte beaucoup de pays.","alt":"Il y a beaucoup de pays dans l'espace Schengen.","note":"l'espace：元音前省音为 l'。"}},
 "L'Hexagone": {"pos":"n.m. 阳性名词，专有名词，常大写 H","s":"六边形；也是对法国本土的口语说法（le territoire hexagonal）。法国本土轮廓大致像六边形，所以媒体常用 l'Hexagone 代指法国，不包括海外领地。","ipa":"[ɛk.sa.ɡɔn]","ph":"h 不发音（h muet）；x 读 [ks]；a 读 [a]；g 读 [ɡ]；结尾 one 读 [ɔn]。","pi":"h 不发音，所以用 l'Hexagone 而不是 le Hexagone。x 读 [ks]，不是 [z]。","et":"来自希腊语 hexa-（六）+ gônia（角）= 六角形。","ex":[["\"L'Hexagone\" est une expression pour parler de la France.","「l'Hexagone」是指法国的说法。"],["Ce produit est fabriqué dans l'Hexagone.","这个产品在法国本土生产。"]],"co":[["dans tout l'Hexagone","整个法国本土"],["l'Hexagone et l'outre-mer","法国本土和海外领地"],["hexagonal(e)","法国本土的"]],"sy":[["la France métropolitaine","courant","法国本土（正式）"],["la France","courant","法国"]],"fq":"中频，新闻和媒体里常见。","me":"hexa（六）+ gone（角）：法国地图像一个六边形。","tr":{"zh":"整个法国本土都下雨了。","fr":"Il a plu dans tout l'Hexagone.","alt":"Il pleut partout en France.","note":"tout l'Hexagone：tout 后接 l'。"}},
 "De l'écorce": {"pos":"n.f. 阴性名词，复数 écorces；这里用部分冠词 de l'","s":"树皮；果皮。écorce d'arbre = 树皮，écorce d'orange = 橙皮。也可比喻「外表」：l'écorce terrestre（地壳）。","ipa":"[e.kɔʁs]","ph":"é = [e]；c 读 [k]；o 读 [ɔ]；rce 读 [ʁs]，结尾 e 不发音。","pi":"rc 连着读：[ʁs]，结尾 e 不发音。é 有重音符号。别漏掉开头的 é。","et":"来自晚期拉丁语 scortea（皮制品），源自 scortum（皮）；与 cortex（树皮）相近。同源动词：écorcer（剥皮）。","ex":[["L'écorce de cet arbre est très rugueuse.","这棵树的树皮很粗糙。"],["Je râpe un peu d'écorce de citron.","我磨一点柠檬皮。"]],"co":[["l'écorce d'un arbre","树皮"],["l'écorce d'orange","橙皮"],["l'écorce terrestre","地壳"]],"sy":[["peau","courant","皮肤；果皮"],["zeste","courant","果皮屑"],["pelure","familier","果皮（口语）"]],"fq":"中低频，自然和烹饪话题里常见。","me":"écorce：树的「外壳」，和 escorte 不要混。","tr":{"zh":"这棵树的树皮很粗。","fr":"L'écorce de cet arbre est épaisse.","alt":"Cet arbre a une écorce épaisse.","note":"écorce 是阴性：une écorce。"}},
 "De la fascination": {"pos":"n.f. 阴性名词，复数 fascinations；这里用部分冠词 de la","s":"着迷；迷恋；强烈的吸引力。éprouver de la fascination pour qqch = 对某事着迷。比 admiration 更强，像被「吸住」。","ipa":"[fa.si.na.sjɔ̃]","ph":"fa = [fa]；sci 中的 sc 读 [s]；na = [na]；tion = [sjɔ̃]。","pi":"sc 在 i 前读 [s]，不是 [sk]。-tion 读 [sjɔ̃]，不是 [tjɔn]。","et":"来自拉丁语 fascinatio（施魔法），源自 fascinare（使着迷，施咒）。同源：fasciner。","ex":[["J'éprouve de la fascination pour les étoiles.","我对星星着迷。"],["Il regarde le feu avec fascination.","他着迷地看着火。"]],"co":[["éprouver de la fascination","感到着迷"],["exercer une fascination","产生吸引力"],["avec fascination","着迷地"],["la fascination pour + 名词","对……的迷恋"]],"sy":[["attirance","courant","吸引"],["admiration","courant","钦佩"],["envoûtement","littéraire","迷惑，魔力"]],"fq":"中频，书面和口语都用。","me":"fascination 的词根是「魔法」：被施了咒一样移不开眼。","tr":{"zh":"孩子们对动物很着迷。","fr":"Les enfants ont de la fascination pour les animaux.","alt":"Les enfants sont fascinés par les animaux.","note":"fascination pour qqch；动词 fasciner。"}},
 "De la patate douce": {"pos":"n.f. 阴性名词词组，复数 patates douces；这里用部分冠词 de la","s":"红薯；甘薯。patate 单独使用时，口语里常指 pomme de terre（土豆）。所以要说「红薯」得带 douce。","ipa":"[pa.tat dus]","ph":"pa = [pa]；tate = [tat]，结尾 e 不发音；douce = [dus]，ou = [u]，c 在 e 前读 [s]。","pi":"tt 只读一个 [t]。douce 是 doux 的阴性，读 [dus]，不要读成 [duz]。","et":"patate 来自西班牙语 patata，源自泰诺语 batata（甘薯）。douce 来自拉丁语 dulcis（甜的）。","ex":[["On va manger de la purée de patate douce.","我们要吃红薯泥。"],["Elle fait des frites de patate douce.","她做了红薯条。"]],"co":[["une purée de patate douce","红薯泥"],["des frites de patate douce","红薯条"],["de la patate douce rôtie","烤红薯"]],"sy":[["pomme de terre","courant","土豆（容易混淆）"],["patate","familier","土豆（口语）"],["igname","courant","山药（不同的植物）"]],"fq":"中频，做饭和菜谱常用。","me":"patate + douce（甜）：甜的那种「patate」。","tr":{"zh":"我喜欢吃烤红薯。","fr":"J'aime manger de la patate douce rôtie.","alt":"J'adore la patate douce au four.","note":"patate douce 是阴性，形容词也要用阴性。"}},
 "L'originalité": {"pos":"n.f. 阴性名词，复数 originalités","s":"独创性；新颖；与众不同。形容作品、想法、人的特色。也可指奇特、古怪的一面。","ipa":"[ɔ.ʁi.ʒi.na.li.te]","ph":"o = [ɔ]；ri = [ʁi]；gi 中 g 读 [ʒ]；na = [na]；li = [li]；té = [te]。","pi":"六个音节要拆开读。g 在 i 前读 [ʒ]。-té 结尾读 [te]，t 要发音。","et":"来自 original（来自拉丁语 originalis，起源的）+ -ité。词根 origine 来自拉丁语 origo（起源）。","ex":[["Le jury a apprécié l'originalité de son projet.","评委欣赏他项目的独创性。"],["Il cherche l'originalité dans tout ce qu'il fait.","他做每件事都追求独特。"]],"co":[["faire preuve d'originalité","表现出独创性"],["manquer d'originalité","缺乏新意"],["l'originalité d'une idée","想法的独特之处"]],"sy":[["nouveauté","courant","新颖"],["créativité","courant","创造力"],["banalité","courant","反义：平庸"]],"fq":"中高频，评价作品和想法时常用。","me":"originalité ← origine：回到「起点」，才有独特。","tr":{"zh":"我喜欢这个设计的独创性。","fr":"J'aime l'originalité de ce design.","alt":"Ce design est très original, j'adore.","note":"l'originalité de + 名词。"}},
 "La chirurgie esthétique": {"pos":"n.f. 阴性名词词组，复数 des chirurgies esthétiques","s":"整形手术；美容手术。chirurgie 是「外科」，esthétique 是「美学的」。也可说 la chirurgie plastique（整形外科）。","ipa":"[ʃi.ʁyʁ.ʒi ɛs.te.tik]","ph":"ch = [ʃ]；u = [y]；g 在 i 前读 [ʒ]；esthétique 里的 th 读 [t]，h 不发音。","pi":"esthétique 中 th 读 [t]。chirurgie 里的 ch 读 [ʃ]，不是 [k]。","et":"chirurgie 来自希腊语 kheirourgia（手工）；esthétique 来自希腊语 aisthêtikos（感觉的，感知美的）。","ex":[["Elle a eu recours à la chirurgie esthétique.","她做了整形手术。"],["La chirurgie esthétique est très chère.","整形手术很贵。"]],"co":[["avoir recours à la chirurgie esthétique","求助于整形手术"],["un chirurgien esthétique","整形医生"],["une opération de chirurgie esthétique","整形手术"]],"sy":[["chirurgie plastique","courant","整形外科"],["chirurgie réparatrice","courant","修复手术（治疗目的）"],["lifting","familier","拉皮手术"]],"fq":"中频，健康和美容话题里常见。","me":"chirurgie（用手做）+ esthétique（为了美）。","tr":{"zh":"她不想做整形手术。","fr":"Elle ne veut pas de chirurgie esthétique.","alt":"Elle refuse la chirurgie esthétique.","note":"否定后用 de：pas de chirurgie。"}},
 "La circulation": {"pos":"n.f. 阴性名词，复数 circulations（少用）","s":"交通（车辆往来）；流通；循环。la circulation routière = 道路交通；la circulation du sang = 血液循环；la libre circulation = 自由流通。","ipa":"[siʁ.ky.la.sjɔ̃]","ph":"ci = [si]；r = [ʁ]；cu = [ky]；la = [la]；tion = [sjɔ̃]。","pi":"circ- 中第一个 c 读 [s]，第二个 c 在 u 前读 [k]。-tion 读 [sjɔ̃]。","et":"来自拉丁语 circulatio，源自 circulus（圆圈）。同源：circuler、cercle。","ex":[["L'espace Schengen est une zone de libre circulation.","申根区是自由流通区。"],["Il y a beaucoup de circulation ce matin.","今天早上车很多。"],["La circulation du sang est essentielle.","血液循环很重要。"]],"co":[["la libre circulation","自由流通"],["il y a beaucoup de circulation","交通繁忙"],["la circulation du sang","血液循环"],["un problème de circulation","交通问题"]],"sy":[["trafic","courant","交通流量"],["embouteillage","courant","堵车"],["flux","courant","流量"]],"fq":"高频，日常和新闻常用。","me":"circulation ← circulus：转圈，一直在流动。","tr":{"zh":"早上市中心的交通很拥堵。","fr":"Il y a beaucoup de circulation en centre-ville le matin.","alt":"Le matin, ça roule mal en ville.","note":"il y a de la circulation：交通状况。"}},
 "La diversité": {"pos":"n.f. 阴性名词，复数 diversités","s":"多样性；多元。la diversité culturelle = 文化多样性。也可表示「种类繁多」。","ipa":"[di.vɛʁ.si.te]","ph":"di = [di]；ver = [vɛʁ]；si = [si]；té = [te]。","pi":"ver 读 [vɛʁ]，r 要发。结尾 -té 读 [te]，t 要发音。别和 divers（各种各样的）读音混：divers 读 [di.vɛʁ]。","et":"来自拉丁语 diversitas，源自 divertere（转向别处，分开）。同源：divers、divertir。","ex":[["La diversité des paysages en France est incroyable.","法国风景的多样性令人难以置信。"],["La diversité culturelle est une richesse.","文化多样性是一种财富。"]],"co":[["la diversité culturelle","文化多样性"],["la diversité des opinions","意见的多样性"],["une grande diversité de + 名词","种类繁多的……"]],"sy":[["variété","courant","种类、变化"],["pluralité","soutenu","多元"],["uniformité","courant","反义：千篇一律"]],"fq":"中高频，社会和文化话题常用。","me":"diversité ← divers（多种）：「不一样」的集合。","tr":{"zh":"我喜欢这座城市的文化多样性。","fr":"J'aime la diversité culturelle de cette ville.","alt":"J'aime que cette ville soit si variée culturellement.","note":"la diversité de + 复数名词。"}},
 "La gastronomie": {"pos":"n.f. 阴性名词，复数 gastronomies（少用）","s":"美食学；烹饪艺术；饮食文化。la gastronomie française 指法国的饮食文化，2010 年入选联合国教科文组织非物质文化遗产。","ipa":"[ɡas.tʁɔ.nɔ.mi]","ph":"gas = [ɡas]；tro = [tʁɔ]；no = [nɔ]；mie = [mi]。g 在 a 前读 [ɡ]。","pi":"g 读 [ɡ]，不是 [ʒ]（因为后面是 a）。o 读 [ɔ]，别拉成 [o]。","et":"来自希腊语 gastêr（胃）+ nomos（规则，法则）。同源：gastrique（胃的）、économie。","ex":[["La gastronomie française est célèbre dans le monde entier.","法国美食闻名世界。"],["Il s'intéresse beaucoup à la gastronomie.","他对美食很感兴趣。"]],"co":[["la gastronomie française","法国美食文化"],["un guide de gastronomie","美食指南"],["la haute gastronomie","高级美食"]],"sy":[["cuisine","courant","烹饪；菜肴"],["art culinaire","soutenu","烹饪艺术"],["gourmandise","courant","贪吃，好吃"]],"fq":"中频，旅游和文化话题常见。","me":"gastro-（胃）+ nomie（规则）：吃的学问。","tr":{"zh":"我对法国美食很感兴趣。","fr":"Je m'intéresse à la gastronomie française.","alt":"La gastronomie française m'intéresse beaucoup.","note":"s'intéresser à + 名词。"}},
 "La haute-couture": {"pos":"n.f. 阴性名词词组，通常写作 la haute couture（无连字符更常见），无复数","s":"高级定制时装。由设计师为客人量身手工制作，是时尚界的最高级别，巴黎是其中心。注意 haute 的 h 是有音 h（h aspiré），要写 la haute，不能连诵。","ipa":"[ot.ku.tyʁ]","ph":"haute = [ot]，h 不发音但属于有音 h，aute 读 [ot]；couture = [ku.tyʁ]，ou = [u]，u = [y]，r 要发音。","pi":"haute 是 h 有音 h，所以说 la haute couture，不连诵（不会变成 l'haute）。u [y] 和 ou [u] 要分清：cou-tu-re。","et":"haute 来自拉丁语 altus（高的）；couture 来自 coudre（缝，拉丁语 consuere）。","ex":[["Paris est la capitale de la haute-couture.","巴黎是高级时装之都。"],["Elle rêve de travailler dans la haute couture.","她梦想在高级定制行业工作。"]],"co":[["la maison de haute couture","高级时装屋"],["une robe de haute couture","高级定制礼服"],["la semaine de la haute couture","高级定制时装周"]],"sy":[["prêt-à-porter","courant","反义：成衣"],["mode","courant","时尚"],["couture","courant","缝纫、时装业"]],"fq":"中低频，时尚话题里常见。","me":"haute（高）+ couture（缝）：做得最「高」的缝纫。","tr":{"zh":"她在一家高级定制时装屋工作。","fr":"Elle travaille dans une maison de haute couture.","alt":"Elle bosse chez un grand couturier.","note":"haute 是阴性，对应 couture（阴性）。"}},
 "La justice": {"pos":"n.f. 阴性名词，复数 justices（少用）","s":"正义；公正；司法。1) 抽象的公正（se battre pour la justice）；2) 司法体系（la justice française；rendre la justice，审判）。","ipa":"[ʒys.tis]","ph":"j = [ʒ]；u = [y]；s 读 [s]；ti 中 t 读 [t]；ce 读 [s]，结尾 e 不发音。","pi":"ju- 读 [ʒy]，不是 [dʒʌ]。结尾 -ice 读 [is]。别按英语 justice 读成 [ˈdʒʌstɪs]。","et":"来自拉丁语 justitia，源自 justus（公正的）和 jus（法，权利）。同源：juste、juge、juriste。","ex":[["Il se bat pour la justice sociale.","他为社会正义而奋斗。"],["La justice est lente dans ce pays.","这个国家的司法很慢。"],["Elle veut que justice soit rendue.","她希望伸张正义。"]],"co":[["la justice sociale","社会正义"],["rendre justice à qqn","为某人伸张正义"],["saisir la justice","诉诸法律"],["passer en justice","上法庭"]],"sy":[["équité","soutenu","公平"],["droit","courant","法律；权利"],["injustice","courant","反义：不公正"]],"fq":"高频，日常和新闻都常见。","me":"justice 和 juste（公正的，刚好的）同根。","tr":{"zh":"我们都想要公正。","fr":"Nous voulons tous la justice.","alt":"Tout le monde veut plus de justice.","note":"la justice：抽象名词前用定冠词。"}},
 "La province": {"pos":"n.f. 阴性名词，复数 provinces","s":"外省（法国巴黎以外的地方）；省。en province = 在外省。有时带一点「不如巴黎」的意味。也指加拿大等国家的「省」。","ipa":"[pʁɔ.vɛ̃s]","ph":"pro = [pʁɔ]；vin 中的 in = [ɛ̃]（鼻化元音）；ce 读 [s]。","pi":"vin 读 [vɛ̃]，鼻化元音。结尾 ce 读 [s]。不要读成英语 province [ˈprɒvɪns]。","et":"来自拉丁语 provincia（被管辖的地区，行省）。","ex":[["La \"province\" désigne toutes les villes de France en dehors de Paris.","「外省」指法国除巴黎以外的所有城市。"],["Il a grandi en province, puis il est monté à Paris.","他在外省长大，后来去了巴黎。"]],"co":[["en province","在外省"],["une ville de province","外省城市"],["monter à Paris","到巴黎去（相对于外省）"],["la vie de province","外省生活"]],"sy":[["région","courant","地区、大区"],["campagne","courant","乡下"],["capitale","courant","反义：首都"]],"fq":"中高频，在谈论法国地理和生活时常用。","me":"province：除了 Paris 之外的「全部」。","tr":{"zh":"我在外省出生，现在住在巴黎。","fr":"Je suis né en province, mais j'habite à Paris maintenant.","alt":"Je viens de province, mais je vis à Paris.","note":"en province：不加冠词。"}},
 "La réinsertion sociale": {"pos":"n.f. 阴性名词词组，复数 des réinsertions sociales","s":"社会重新融入；回归社会。帮助囚犯、失业者、无家可归者等重新回到正常社会生活。reinsertion 的 ré- 表示「再次」。","ipa":"[ʁe.ɛ̃.sɛʁ.sjɔ̃ sɔ.sjal]","ph":"ré = [ʁe]；in = [ɛ̃]；ser = [sɛʁ]；tion = [sjɔ̃]；sociale 的 ci = [sj]，结尾 e 不发音。","pi":"ré- 与后面的 in- 分成两个元音 [e.ɛ̃]。-tion 读 [sjɔ̃]。sociale 读 [sɔ.sjal]，别漏掉 [j]。","et":"ré-（再）+ insertion（来自拉丁语 inserere，插入）。social 来自拉丁语 socialis（同伴的），源自 socius（同伴）。","ex":[["Cette association aide à la réinsertion sociale des prisonniers.","这个协会帮助囚犯回归社会。"],["La réinsertion sociale est parfois difficile.","重新融入社会有时很困难。"]],"co":[["la réinsertion sociale","社会重新融入"],["la réinsertion professionnelle","重返职场"],["aider à la réinsertion","帮助重新融入"],["un programme de réinsertion","回归社会计划"]],"sy":[["réadaptation","soutenu","重新适应"],["intégration","courant","融入"],["exclusion","courant","反义：排斥"]],"fq":"中低频，社会新闻和公益话题里常见。","me":"ré-（再）+ insertion（放进去）：把人重新放回社会。","tr":{"zh":"他需要帮助才能回归社会。","fr":"Il a besoin d'aide pour sa réinsertion sociale.","alt":"Il faut l'aider à retrouver sa place dans la société.","note":"avoir besoin d'aide pour + 名词。"}},
 "La richesse": {"pos":"n.f. 阴性名词，复数 richesses","s":"财富；富有；丰富。1) 钱财（la richesse d'un pays）；2) 丰富性（la richesse d'un texte，文本的内涵丰富）。复数 les richesses 常指「资源、财产」。","ipa":"[ʁi.ʃɛs]","ph":"ri = [ʁi]；ch = [ʃ]；esse = [ɛs]，ss 读 [s]，结尾 e 不发音。","pi":"ch 读 [ʃ]，ss 读 [s]；结尾 -esse 读 [ɛs]。别漏掉 ch。","et":"由 riche（来自法兰克语 *riki，有权势的）+ -esse（表示性质）构成。","ex":[["Le monde francophone a une grande richesse culturelle.","法语世界有丰富的文化。"],["La santé est la vraie richesse.","健康才是真正的财富。"]],"co":[["la richesse culturelle","文化财富"],["la richesse d'un pays","一个国家的财富"],["les richesses naturelles","自然资源"],["une grande richesse de + 名词","非常丰富的……"]],"sy":[["fortune","courant","财产"],["abondance","soutenu","充裕"],["pauvreté","courant","反义：贫穷"]],"fq":"高频，日常和书面都常用。","me":"richesse = riche + esse：「富」的状态。","tr":{"zh":"这座城市有丰富的文化。","fr":"Cette ville a une grande richesse culturelle.","alt":"Cette ville est très riche culturellement.","note":"richesse culturelle：richesse 是阴性。"}},
 "Une banque alimentaire": {"pos":"n.f. 阴性名词词组，复数 des banques alimentaires","s":"食物银行。收集并分发食物给有需要的人的公益组织。banque 是「银行」，alimentaire 是「食品的」。","ipa":"[bɑ̃k a.li.mɑ̃.tɛʁ]","ph":"banque 的 an = [ɑ̃]，qu = [k]，结尾 e 不发音；alimentaire 的 en = [ɑ̃]，aire = [ɛʁ]。","pi":"banque 中 qu 读 [k]；alimentaire 里的 -en- 读 [ɑ̃]，-aire 读 [ɛʁ]，r 要发音。不要把 alimentaire 读成「alimentary」。","et":"banque 来自意大利语 banca（长凳，兑换台）；alimentaire 来自拉丁语 alimentum（食物），源自 alere（养育）。","ex":[["La banque alimentaire aide les familles en difficulté.","食物银行帮助有困难的家庭。"],["Je donne des conserves à la banque alimentaire.","我把罐头捐给食物银行。"]],"co":[["donner à la banque alimentaire","捐给食物银行"],["une collecte pour la banque alimentaire","食物银行募捐"],["un bénévole de la banque alimentaire","食物银行志愿者"]],"sy":[["Restos du cœur","courant","法国的慈善餐厅组织"],["épicerie solidaire","courant","互助杂货店"],["aide alimentaire","courant","食物援助"]],"fq":"中低频，公益和新闻中常见。","me":"banque（银行）存的不是钱，而是食物。","tr":{"zh":"我周末去食物银行当志愿者。","fr":"Le week-end, je suis bénévole à la banque alimentaire.","alt":"Le week-end, je fais du bénévolat à la banque alimentaire.","note":"être bénévole à / faire du bénévolat。"}},
 "Une boule de glace": {"pos":"n.f. 阴性名词，复数 boules de glace","s":"一球冰淇淋。boule 是「球」，glace 是「冰淇淋；冰」。点冰淇淋时按「球」数：deux boules = 两球。冰淇淋店的一份也常说 une boule 或 un cornet（甜筒）。","ipa":"[bul.də.glas]","ph":"ou [u]；de 弱读 [də]；glace 的 c 在 e 前读 [s]，结尾 e 不发音。","pi":"boule 的 l 要发，结尾 e 不发；glace 不是 [glɑs] 拉长音，也不要发成 glas-e 两个音节。","et":"boule 来自拉丁语 bulla（气泡；球）；glace 来自拉丁语 glacies（冰）。","ex":[["Je voudrais une boule de glace à la vanille.","我想要一球香草冰淇淋。"],["Prenez-vous deux boules ou trois ?","您要两球还是三球？"]],"co":[["une boule de glace au chocolat","一球巧克力冰淇淋"],["deux boules de glace","两球冰淇淋"],["une boule de neige","雪球"]],"sy":[["une glace","courant","冰淇淋（整体，不论几球）"],["un cornet","courant","甜筒（装冰淇淋的容器）"]],"fq":"中频，冰淇淋店常用。","me":"boule = 球，想象圆圆的冰淇淋球放在甜筒上。","tr":{"zh":"请给我两球草莓冰淇淋。","fr":"Deux boules de glace à la fraise, s'il vous plaît.","alt":"Je prends deux boules à la fraise, s'il vous plaît.","note":"口味用 à la + 名词：à la fraise、à la vanille。"}},
 "Une clôture": {"pos":"n.f. 阴性名词，复数 clôtures","s":"两个意思：1）闭幕、结束（une cérémonie de clôture 闭幕式）；2）栅栏、围栏（clôture d'un jardin）。反义词：ouverture（开幕）。","ipa":"[klo.tyʁ]","ph":"ô [o]；u [y]；r [ʁ]；结尾 -ure 读 [yʁ]。","pi":"ô 有长音符，读 [o]，不是 [u]；u 是圆唇的 [y]，不是 ou。","et":"来自中世纪拉丁语 clausitura，源自 claudere（关闭）。同族：clore、clos、conclure。","ex":[["Le dernier jour du festival, il y a une fête de clôture.","音乐节最后一天有闭幕派对。"],["Une clôture blanche entoure le jardin.","一道白色栅栏围着花园。"]],"co":[["la cérémonie de clôture","闭幕式"],["une clôture électrique","电围栏"],["la clôture des inscriptions","报名截止"]],"sy":[["fin","courant","结束（更普通）"],["barrière","courant","栏杆、栅栏"],["ouverture","courant","反义词：开幕、开始"]],"fq":"中频，活动与园艺场合都常见。","me":"clôture 想到 clore（关上）：门关上就是结束，也是围起来。","tr":{"zh":"闭幕式在晚上八点开始。","fr":"La cérémonie de clôture commence à vingt heures.","alt":"La clôture a lieu à 20 h.","note":"cérémonie 是阴性，所以 la cérémonie de clôture。"}},
 "Une dictée": {"pos":"n.f. 阴性名词，复数 dictées","s":"听写。老师念，学生写。法国学校里 la dictée 是传统的拼写练习。动词 dicter = 口述；faire une dictée = 做听写。","ipa":"[dik.te]","ph":"c 在 t 前读 [k]；-ée 读 [e]；结尾 e 不发音。","pi":"结尾 -ée 读 [e]，不要发成 [te.e]；c 要发，别漏掉 [k]。","et":"来自动词 dicter（口述），源自拉丁语 dictare；-ée 是名词后缀。同族：dictionnaire、dicton。","ex":[["Le professeur a fait faire une dictée aux élèves.","老师让学生做听写。"],["J'ai fait trois fautes dans la dictée.","我在听写里错了三处。"]],"co":[["faire une dictée","做听写"],["écrire sous la dictée","听写着写下来"],["une dictée de mots","单词听写"]],"sy":[["un exercice","courant","练习（范围更广）"],["dicter","courant","动词：口述，念给别人写"]],"fq":"中频，学校和语言学习中常见。","me":"dictée = dicter 的结果：别人念，你写。","tr":{"zh":"明天我们要做一次听写。","fr":"Demain, nous allons faire une dictée.","alt":"Demain, on a une dictée.","note":"aller + 动词原形表示近将来。"}},
 "Une faute d'orthographe": {"pos":"n.f. 阴性名词，复数 fautes d'orthographe","s":"拼写错误。faute = 错误；orthographe = 拼写（正字法）。注意：faute 指「错」，不是「缺点」；也可以说 faute de frappe（打字错误）。","ipa":"[fot.dɔʁ.tɔ.ɡʁaf]","ph":"au [o]；faute 的 t 要发；de 在元音前省音 d'；th 读 [t]；ph 读 [f]。","pi":"orthographe 中 th 读 [t]，不是 [θ]；ph 读 [f]；结尾 e 不发音。","et":"faute 来自拉丁语 fallere（出错；欺骗）；orthographe 来自希腊语 orthos（正确）+ graphein（写）。","ex":[["Il y a une faute d'orthographe dans ce mot.","这个词有一个拼写错误。"],["Je fais souvent des fautes d'orthographe.","我常常拼错字。"]],"co":[["faire une faute","犯错"],["une faute de frappe","打字错误"],["une faute de grammaire","语法错误"],["sans faute","没有错误"]],"sy":[["une erreur","courant","错误（更通用）"],["une coquille","courant","印刷或打字小错"]],"fq":"中高频，学习语言必备。","me":"faute（错）+ orthographe（拼写），一错就是拼错。","tr":{"zh":"你的邮件里有一个拼写错误。","fr":"Il y a une faute d'orthographe dans ton mail.","alt":"Tu as fait une faute d'orthographe dans ton mail.","note":"il y a + 名词表示「有……」。"}},
 "Une garde-robe": {"pos":"n.f. 阴性名词，复数 garde-robes","s":"一个人的全部衣服；衣橱。强调「所有的衣服」，不是家具。家具衣柜说 une armoire 或 un placard。refaire sa garde-robe = 换一批新衣服。","ipa":"[ɡaʁd.ʁɔb]","ph":"ar [aʁ]；d 在 r 前读 [d]；两个 r 都发 [ʁ]；结尾 e 不发音。","pi":"不要和 armoire（衣柜家具）混淆；两个词连写中间有连字符。","et":"由动词 garder（保管）+ robe（衣服）构成，字面意思「保管衣服的地方」。","ex":[["Elle doit refaire sa garde-robe pour l'hiver.","她得为冬天重置衣橱。"],["Ma garde-robe est très simple.","我的衣服很简单。"]],"co":[["refaire sa garde-robe","重新置办衣服"],["une garde-robe d'été","夏季衣物"],["renouveler sa garde-robe","更新衣橱"]],"sy":[["une armoire","courant","衣柜（家具）"],["un dressing","courant","衣帽间"],["des vêtements","courant","衣服（泛指）"]],"fq":"中频，谈论穿着时用。","me":"garde（守）+ robe（衣服）：「守着衣服」的全部集合。","tr":{"zh":"我想换一批新衣服。","fr":"Je voudrais renouveler ma garde-robe.","alt":"J'ai envie de changer toute ma garde-robe.","note":"garde-robe 是阴性：ma garde-robe。"}},
 "Une inscription": {"pos":"n.f. 阴性名词，复数 inscriptions","s":"两个意思：1）刻写或印上的文字、铭文（衣服上的字、墙上的字）；2）报名、注册（l'inscription à un cours）。看上下文判断。","ipa":"[ɛ̃.skʁip.sjɔ̃]","ph":"in 鼻化 [ɛ̃]；sc [sk]；ti 在这里读 [sj]；结尾 on 鼻化 [ɔ̃]。","pi":"-tion 读 [sjɔ̃]，不是 [tjɔ̃]；结尾的 n 不单独发音。","et":"来自拉丁语 inscriptio，in-（在上面）+ scribere（写）。同族：écrire、description。","ex":[["Il porte un t-shirt avec des inscriptions en chinois.","他穿一件印有中文字的 T 恤。"],["Les inscriptions commencent lundi.","报名从周一开始。"]],"co":[["une inscription sur un mur","墙上的字"],["les inscriptions à l'université","大学注册报名"],["s'inscrire à un cours","报名一门课"],["un formulaire d'inscription","报名表"]],"sy":[["un texte","courant","文字，泛指"],["une écriture","courant","字迹，书写"],["un enregistrement","soutenu","登记，注册"]],"fq":"中高频，报名和标语场合都常见。","me":"in + scrip：「写进去」，写在上面或写进名单。","tr":{"zh":"报名下周五截止。","fr":"Les inscriptions se terminent vendredi prochain.","alt":"Il faut s'inscrire avant vendredi prochain.","note":"「报名」意义时常用复数 les inscriptions。"}},
 "Une invention": {"pos":"n.f. 阴性名词，复数 inventions","s":"发明；发明物。也可以指「编造」，如 C'est une invention ! = 这是编的！动词是 inventer。","ipa":"[ɛ̃.vɑ̃.sjɔ̃]","ph":"in 鼻化 [ɛ̃]；en 鼻化 [ɑ̃]；-tion 读 [sjɔ̃]。","pi":"in 和 en 是两个不同的鼻化元音：[ɛ̃] 与 [ɑ̃]，不要混。","et":"来自拉丁语 inventio，invenire（发现）。同族：inventer、inventaire（清单）。","ex":[["L'imprimerie est une invention majeure.","印刷术是一项重大发明。"],["Cette histoire est une pure invention.","这个故事纯属编造。"]],"co":[["une invention géniale","绝妙的发明"],["l'invention de l'imprimerie","印刷术的发明"],["une pure invention","纯属编造"]],"sy":[["une découverte","courant","发现（原本就存在的东西）"],["une création","courant","创作、创造"],["un mensonge","courant","谎言（编造的话）"]],"fq":"中频，常用。","me":"inventer 的名词；invention ≠ découverte：发明是造出来，发现是找到。","tr":{"zh":"手机是一项了不起的发明。","fr":"Le téléphone portable est une invention formidable.","alt":"Le portable, c'est une invention géniale.","note":"发明物用阴性 une invention。"}},
 "Une liseuse numérique": {"pos":"n.f. 阴性名词，复数 liseuses numériques","s":"电子阅读器（如 Kindle 那种专门读书的设备）。liseuse 来自 lire，numérique = 数字的。口语常简称 une liseuse。","ipa":"[li.zøz.ny.me.ʁik]","ph":"liseuse 中 s 在元音间读 [z]；eu [ø]；numérique 中 u [y]，é [e]，qu [k]。","pi":"s 读 [z]；u 是 [y]（圆唇）；结尾 -que 读 [k]；不要说成 e-reader。","et":"liseuse 来自 lire + 后缀 -euse（做动作的人或物）；numérique 来自 numéro / 拉丁语 numerus（数）。","ex":[["J'adore lire sur ma liseuse numérique.","我喜欢在电子阅读器上看书。"],["Elle emporte sa liseuse en vacances.","她度假时带着电子阅读器。"]],"co":[["lire sur une liseuse","用电子阅读器看书"],["un livre numérique","电子书"],["recharger sa liseuse","给阅读器充电"]],"sy":[["un livre électronique","courant","电子书（指书，不是设备）"],["une tablette","courant","平板电脑（功能更多）"]],"fq":"中低频，现代生活常见。","me":"liseuse = lire 的「读者」：会读书的机器。","tr":{"zh":"我的电子阅读器里有两百本书。","fr":"J'ai deux cents livres dans ma liseuse numérique.","alt":"Ma liseuse contient deux cents livres.","note":"liseuse 是阴性，所以 ma liseuse。"}},
 "Une noix de coco": {"pos":"n.f. 阴性名词，复数 noix de coco（单复数同形）","s":"椰子。noix 本义是「坚果；核桃」，noix de coco = 椰子。椰子水 = l'eau de coco；椰子味 = au coco。","ipa":"[nwa.də.kɔ.ko]","ph":"noix 读 [nwa]，x 不发音；de 弱读 [də]；coco 两个 o 音不同：[kɔ.ko]。","pi":"noix 结尾的 x 不发音；单数复数都写 noix，要看冠词。","et":"noix 来自拉丁语 nux（坚果）；coco 借自葡萄牙语或西班牙语 coco。","ex":[["J'aime boire l'eau d'une noix de coco fraîche.","我喜欢喝新鲜椰子水。"],["Ce gâteau est parfumé à la noix de coco.","这个蛋糕有椰子香味。"]],"co":[["le lait de coco","椰奶"],["l'huile de noix de coco","椰子油"],["la noix de coco râpée","椰蓉"],["une noix de cajou","腰果"]],"sy":[["un coco","familier","椰子（口语省略）"],["une noix","courant","核桃（别和椰子混淆）"]],"fq":"中低频，饮食场合。","me":"noix（坚果）+ coco：长在树上的大坚果。","tr":{"zh":"我想买一个椰子。","fr":"Je voudrais acheter une noix de coco.","alt":"Je cherche une noix de coco.","note":"noix de coco 是阴性，用 une。"}},
 "Une pandémie": {"pos":"n.f. 阴性名词，复数 pandémies","s":"（全球）大流行病。比 épidémie（流行病，局部）范围更大。la pandémie 在近年多指新冠疫情。","ipa":"[pɑ̃.de.mi]","ph":"an 鼻化 [ɑ̃]；é [e]；结尾 -ie 读 [i]，e 不发音。","pi":"p-an 读鼻音 [pɑ̃]，不要发成 pan-d；-mie 读 [mi]，不是 [mje]。","et":"来自希腊语 pan（全部）+ demos（人民）。同族：épidémie（epi- 在……上）。","ex":[["Pendant la pandémie de COVID-19, de nombreux restaurants ont fermé.","新冠大流行期间，许多餐馆关门了。"],["Une pandémie touche presque tous les pays.","大流行几乎波及所有国家。"]],"co":[["une pandémie mondiale","全球大流行"],["pendant la pandémie","疫情期间"],["lutter contre une pandémie","抗击大流行"]],"sy":[["une épidémie","courant","流行病（范围较小）"],["une crise sanitaire","courant","公共卫生危机"]],"fq":"中频，近年新闻常见。","me":"pan（全）+ démie（人民）：影响所有人。","tr":{"zh":"疫情期间，我们在家工作。","fr":"Pendant la pandémie, nous avons travaillé à la maison.","alt":"Pendant la pandémie, on a fait du télétravail.","note":"Pendant + 名词表示「在……期间」。"}},
 "Une portion": {"pos":"n.f. 阴性名词，复数 portions","s":"一份（食物的份量）；一部分。点餐时用：une portion de frites = 一份薯条。也可指分配到的那一份。","ipa":"[pɔʁ.sjɔ̃]","ph":"or 读 [ɔʁ]；-tion 读 [sjɔ̃]，结尾鼻化。","pi":"-tion 读 [sjɔ̃]，不是 [ʃɔ̃]；结尾 n 不单独发音。","et":"来自拉丁语 portio（一份，部分）。同族：proportion、part。","ex":[["Je voudrais une petite portion de frites.","我想要一小份薯条。"],["Une portion suffit pour deux personnes.","一份够两个人吃。"]],"co":[["une grande / petite portion","大 / 小份"],["une portion de frites","一份薯条"],["une portion individuelle","单人份"],["une demi-portion","半份"]],"sy":[["une part","courant","一块、一份（蛋糕等）"],["une ration","courant","配给的定量"],["une assiette","courant","一盘（餐厅用语）"]],"fq":"中频，餐厅常用。","me":"portion 想到 proportion：按比例分好的一份。","tr":{"zh":"这一份够我吃了。","fr":"Cette portion me suffit.","alt":"Une portion, ça me suffit.","note":"suffire 表示「够」，后面可接间接宾语 me。"}},
 "Une priorité": {"pos":"n.f. 阴性名词，复数 priorités","s":"优先事项；首要的事。也指交通中的「先行权」：avoir la priorité = 有先行权。","ipa":"[pʁi.jɔ.ʁi.te]","ph":"pri 后面加一个轻的 [j]：[pʁi.jɔ]；ri [ʁi]；-té 读 [te]。","pi":"中间 i 与 o 连读时有 [j] 滑音；结尾 é 读 [e]，t 不是尾音。","et":"来自中世纪拉丁语 prioritas，源自 prior（更早的；更靠前的）。同族：prieur。","ex":[["La santé est ma priorité.","健康是我的首要任务。"],["Les piétons ont la priorité ici.","这里行人有先行权。"]],"co":[["une priorité absolue","头等大事"],["donner la priorité à","优先考虑"],["avoir la priorité","有先行权"],["en priorité","优先地"]],"sy":[["un objectif","courant","目标"],["une urgence","courant","紧急事（不一定重要）"]],"fq":"高频，工作和生活都常用。","me":"prior（先）+ -ité：排在第一位。","tr":{"zh":"对我来说，家人是第一位的。","fr":"Pour moi, la famille est la priorité.","alt":"Ma priorité, c'est ma famille.","note":"Ma priorité, c'est… 是口语常用强调句型。"}},
 "Une promesse": {"pos":"n.f. 阴性名词，复数 promesses","s":"承诺；诺言。动词 promettre。常说 tenir sa promesse（信守承诺）、faire une promesse（许诺）。","ipa":"[pʁɔ.mɛs]","ph":"o 读 [ɔ]；mm 不双发，这里只有一个 m；ss [s]；结尾 e 不发音。","pi":"promesse 只有一个 m，promettre 有两个 t；不要写成 promisse。","et":"来自拉丁语 promissa，源自 promittere（向前放，许诺）。同族：promettre、compromis。","ex":[["Il faut toujours tenir ses promesses.","要始终信守承诺。"],["Je te fais une promesse.","我向你保证。"]],"co":[["tenir sa promesse","信守承诺"],["faire une promesse","许下诺言"],["rompre une promesse","违背诺言"],["une fausse promesse","空头承诺"]],"sy":[["un engagement","courant","承诺、责任（更正式）"],["une parole","courant","诺言（donner sa parole）"],["un serment","soutenu","誓言"]],"fq":"中高频，日常常用。","me":"pro（向前）+ mettre（放）：把话先放出去，就要做到。","tr":{"zh":"我答应你，明天一定来。","fr":"Je te promets de venir demain.","alt":"C'est promis, je viens demain.","note":"promettre de + 动词原形；C'est promis ! 是口语保证。"}},
 "Une résolution": {"pos":"n.f. 阴性名词，复数 résolutions","s":"两个意思：1）决心、决定（prendre une bonne résolution 下决心，常指新年计划）；2）决议（联合国决议）；3）问题的解决。","ipa":"[ʁe.zɔ.ly.sjɔ̃]","ph":"ré [ʁe]；s 在元音间读 [z]；u [y]；-tion 读 [sjɔ̃]。","pi":"s 读 [z]，不是 [s]；u 是 [y]，不是 ou。","et":"来自拉丁语 resolutio，源自 resolvere（解开，解决）。同族：résoudre、solution。","ex":[["J'ai pris de bonnes résolutions pour la nouvelle année.","我为新年定下了好的决心。"],["L'ONU a adopté une résolution.","联合国通过了一项决议。"]],"co":[["prendre une résolution","下决心"],["une bonne résolution","新年愿望，好决心"],["adopter une résolution","通过决议"],["la résolution d'un problème","问题的解决"]],"sy":[["une décision","courant","决定"],["une détermination","soutenu","决心，坚定"],["une solution","courant","解决办法"]],"fq":"中频；新年时尤其常见。","me":"résoudre 的名词：把问题解开，也把心意定下。","tr":{"zh":"我的新年决心是多运动。","fr":"Ma résolution de l'année, c'est de faire plus de sport.","alt":"J'ai décidé de faire plus de sport cette année.","note":"résolution + de + 动词原形。"}},
 "Une saveur": {"pos":"n.f. 阴性名词，复数 saveurs","s":"味道；风味（口里尝到的）。也指冰淇淋或糖的口味。比 goût 更文雅、更具体。引申：la saveur d'un souvenir = 回忆的滋味。","ipa":"[sa.vœʁ]","ph":"s [s]；a [a]；v [v]；eur 读 [œʁ]。","pi":"-eur 读 [œʁ]，r 要发；saveur 是阴性（la saveur），虽然以 -eur 结尾。","et":"来自拉丁语 sapor，sapere（有味道；有智慧）。与 savoir（知道）同源。","ex":[["Ce plat a une saveur très épicée.","这道菜口味很辣。"],["Cette glace existe en plusieurs saveurs.","这种冰淇淋有好几种口味。"]],"co":[["une saveur sucrée / salée","甜味 / 咸味"],["plusieurs saveurs","多种口味"],["une saveur douce","温和的味道"],["la saveur de la vie","生活的滋味"]],"sy":[["un goût","courant","味道（最常用）"],["un parfum","courant","口味（冰淇淋）；香味"],["une odeur","courant","气味（闻到的）"]],"fq":"中频，饮食描写常用。","me":"saveur 与 savoir 同源：尝得出来才「知道」味道。","tr":{"zh":"这种水果有很甜的味道。","fr":"Ce fruit a une saveur très sucrée.","alt":"Ce fruit est très sucré.","note":"saveur 是阴性：une saveur。"}},
 "Une spécificité": {"pos":"n.f. 阴性名词，复数 spécificités","s":"特色；特殊性；某事物独有的特点。比 caractéristique 更强调「独有」。常用来谈地区、文化的特色。","ipa":"[spe.si.fi.si.te]","ph":"sp [sp]；é [e]；c 在 i 前读 [s]；每个 i 都发 [i]；结尾 é 读 [e]。","pi":"拼写较长，注意 spéci-fi-ci-té；c 读 [s]；两个 i 不要混成一个。","et":"来自 spécifique，源自拉丁语 species（种类）+ facere（做）。同族：espèce、spécial。","ex":[["La gastronomie est une spécificité française.","美食是法国的特色。"],["Chaque région a ses spécificités.","每个地区都有自己的特点。"]],"co":[["les spécificités locales","地方特色"],["une spécificité culturelle","文化特色"],["respecter les spécificités de chacun","尊重每个人的特点"]],"sy":[["une particularité","courant","特点"],["une caractéristique","courant","特征"],["un trait","courant","特征，特点（口语中也常说）"]],"fq":"中频，正式场合较多。","me":"spécifique + -ité：某事物「独有的」那一点。","tr":{"zh":"每个国家都有自己的特色。","fr":"Chaque pays a ses propres spécificités.","alt":"Chaque pays a ses particularités.","note":"chaque + 单数名词，但后面 ses 可用复数。"}},
 "Un(e) candidat(e)": {"pos":"n.m. / n.f. 名词，阳性 candidat，阴性 candidate（阴阳同音不同形：阴性发 t）","s":"候选人；应聘者；考生；参赛者。可以是求职者、选举的候选人，或考试的考生。阴性加 e，读音多一个 [t]。","ipa":"[kɑ̃.di.da] / [kɑ̃.di.dat]","ph":"an [ɑ̃]；c 在 an 前读 [k]；阳性结尾 t 不发音，阴性 -te 发 [t]。","pi":"阳性 candidat 的 t 不发音，阴性 candidate 的 t 发音。别写成 candidate 作阳性。","et":"来自拉丁语 candidatus，意思是「穿白袍的人」，因为古罗马候选人穿白袍。candidus = 白色。","ex":[["Il est le meilleur candidat pour ce poste.","他是这个职位最好的候选人。"],["Elle est candidate à l'élection.","她是这次选举的候选人。"]],"co":[["un candidat à l'élection","选举候选人"],["poser sa candidature","递交申请"],["un candidat au poste","职位应聘者"],["se porter candidat","自荐，表示参选"]],"sy":[["un postulant","soutenu","申请人"],["un concurrent","courant","参赛者，对手"],["un participant","courant","参加者"]],"fq":"中高频，求职和选举常用。","me":"candidat 原义「穿白衣」：来自拉丁语 candidus（白）。","tr":{"zh":"这位候选人很有经验。","fr":"Ce candidat a beaucoup d'expérience.","alt":"Cette candidate a beaucoup d'expérience.","note":"candidat 和 candidate 按人的性别选用。"}},
 "Un(e) francophone": {"pos":"n.m. / n.f. 名词，阴阳同形，复数 francophones；也可作形容词","s":"说法语的人；以法语为母语或常用语言的人。也作形容词：un pays francophone = 说法语的国家。la francophonie = 法语圈。","ipa":"[fʁɑ̃.kɔ.fɔn]","ph":"an [ɑ̃]；c [k]；ph [f]；结尾 -ne 读 [ɔn]，e 不发音。","pi":"ph 读 [f]；francophone 阴阳同形，用冠词 un / une 区分性别。","et":"由 franco-（法国的；法语的）+ 希腊语 phônê（声音）构成。同族：francophonie。","ex":[["Un francophone est une personne qui parle français, peu importe sa nationalité.","法语使用者是说法语的人，不论国籍。"],["Il y a beaucoup de francophones en Afrique.","非洲有很多说法语的人。"]],"co":[["un pays francophone","说法语的国家"],["la francophonie","法语圈"],["un chanteur francophone","法语歌手"]],"sy":[["un Français","courant","法国人（国籍，不等于说法语的人）"],["un locuteur du français","soutenu","法语使用者"]],"fq":"中频，谈论语言和文化时用。","me":"franco（法）+ phone（声音）：发出法语声音的人。","tr":{"zh":"加拿大有很多说法语的人。","fr":"Il y a beaucoup de francophones au Canada.","alt":"Au Canada, beaucoup de gens parlent français.","note":"francophone 可以是名词，也可以是形容词。"}},
 "Un(e) porte-parole": {"pos":"n.m. / n.f. 名词，阴阳同形，复数 porte-parole（单复数同形，也可写 porte-paroles）","s":"发言人。代表一个团体、政府或公司发声。阴阳同形：un porte-parole 或 une porte-parole。","ipa":"[pɔʁt.pa.ʁɔl]","ph":"ort 读 [ɔʁt]；parole 读 [pa.ʁɔl]，结尾 e 不发音。","pi":"porte 的 e 不发音；注意是连字符复合词，不是两个独立词。","et":"porter（携带）+ parole（话语）：「带话的人」。","ex":[["Le porte-parole du gouvernement a fait une annonce.","政府发言人发布了公告。"],["Elle est la porte-parole de l'association.","她是协会的发言人。"]],"co":[["le porte-parole du gouvernement","政府发言人"],["se faire le porte-parole de","充当……的代言人"],["un porte-parole officiel","官方发言人"]],"sy":[["un représentant","courant","代表"],["un délégué","courant","代表，委员"],["un attaché de presse","courant","新闻专员"]],"fq":"中频，新闻里常见。","me":"porte + parole：「带着话的人」。","tr":{"zh":"公司发言人明天会回答问题。","fr":"Le porte-parole de l'entreprise répondra aux questions demain.","alt":"Le porte-parole de la société va répondre demain.","note":"répondra 是 répondre 的将来时。"}},
 "Un(e) réfugié(e) politique": {"pos":"n.m. / n.f. 名词，阳性 réfugié，阴性 réfugiée；复数 réfugiés politiques","s":"政治难民；因政治原因逃离本国、在别国寻求庇护的人。réfugié 来自动词 se réfugier（避难）。réfugié 阴阳同音，只是书写多一个 e。","ipa":"[ʁe.fy.ʒje pɔ.li.tik]","ph":"ré [ʁe]；u [y]；g 在 i 前读 [ʒ]；-gié 读 [ʒje]；politique 结尾 -que 读 [k]。","pi":"réfugié 的 g 读 [ʒ]，不是 [g]；politique 结尾是 [k]。阴阳同音，靠冠词区分。","et":"来自拉丁语 refugium（避难处），fugere（逃）。同族：fuir、refuge。","ex":[["Ce pays accueille de nombreux réfugiés politiques.","这个国家接收许多政治难民。"],["Elle est réfugiée politique depuis trois ans.","她成为政治难民已有三年。"]],"co":[["demander l'asile politique","申请政治庇护"],["accueillir des réfugiés","接收难民"],["un camp de réfugiés","难民营"],["le statut de réfugié","难民身份"]],"sy":[["un exilé","courant","流亡者"],["un migrant","courant","移民，迁移者"],["un demandeur d'asile","courant","寻求庇护者"]],"fq":"中频，新闻与社会话题。","me":"ré + fuge：往回逃到「避难处」。","tr":{"zh":"他在法国申请了政治庇护。","fr":"Il a demandé l'asile politique en France.","alt":"Il a demandé l'asile en France.","note":"demander l'asile 用 passé composé（avoir）。"}},
 "Autodidacte": {"pos":"adj. / n. 形容词或名词，阴阳同形，复数 autodidactes","s":"自学成才的（人）。可作形容词（un musicien autodidacte），也可作名词（un autodidacte）。字面「自己教自己」。","ipa":"[o.to.di.dakt]","ph":"au 读 [o]；-ct 在这里两个辅音都发：[kt]；结尾 e 不发音。","pi":"au 读 [o]，不是 [ɔ] 或 [au]；词尾 -cte 的 c 和 t 都发。","et":"来自希腊语 autos（自己）+ didaktos（受教的）。同族：didactique。","ex":[["C'est un musicien autodidacte.","他是个自学成才的音乐家。"],["Elle est autodidacte en informatique.","她的电脑技术是自学的。"]],"co":[["être autodidacte","是自学成才的"],["apprendre en autodidacte","自学"],["un peintre autodidacte","自学成才的画家"]],"sy":[["un self-made-man","courant","白手起家的人（意思不同，偏事业）"],["apprendre seul","courant","自己学（更口语）"]],"fq":"中低频，描述人时用。","me":"auto（自己）+ didacte（教）：自己教自己。","tr":{"zh":"我是自学法语的。","fr":"J'apprends le français en autodidacte.","alt":"J'apprends le français tout seul.","note":"en autodidacte = 以自学的方式。"}},
 "Fondateur / Fondatrice": {"pos":"n.m. / n.f. 名词，阳性 fondateur，阴性 fondatrice；复数 fondateurs / fondatrices","s":"创始人；创办者。指创立公司、协会、国家的人。动词 fonder = 创立；fondation = 基金会；创立。","ipa":"[fɔ̃.da.tœʁ] / [fɔ̃.da.tʁis]","ph":"on 鼻化 [ɔ̃]；阳性 -teur 读 [tœʁ]；阴性 -trice 读 [tʁis]。","pi":"阴性 fondatrice 不是 fondateuse；注意 -trice 里 c 读 [s]。","et":"来自拉丁语 fundator，fundare（建立），fundus（底，基础）。同族：fond、fondation。","ex":[["Il est le fondateur de cette entreprise.","他是这家公司的创始人。"],["La fondatrice du musée a vécu à Paris.","博物馆的创始人曾住在巴黎。"]],"co":[["le fondateur de l'entreprise","公司创始人"],["un membre fondateur","创始成员"],["le père fondateur","奠基人"],["l'acte fondateur","奠基性事件"]],"sy":[["un créateur","courant","创造者"],["un initiateur","soutenu","发起人"],["un pionnier","courant","先驱"]],"fq":"中频，商业、历史场合。","me":"fonder ← fond（底）：在底部打下基础的人。","tr":{"zh":"她是这个协会的创始人。","fr":"Elle est la fondatrice de cette association.","alt":"C'est elle qui a fondé cette association.","note":"阴性用 fondatrice，不是 fondateuse。"}},
 "Francophile": {"pos":"adj. / n. 形容词或名词，阴阳同形，复数 francophiles","s":"亲法的（人）；喜爱法国和法国文化的人。反义词：francophobe（反法的）。可作名词，也可作形容词。","ipa":"[fʁɑ̃.kɔ.fil]","ph":"an [ɑ̃]；c [k]；ph 读 [f]；结尾 -le 读 [fil]，e 不发音。","pi":"ph 读 [f]；结尾 -phile 读 [fil]，不是 [faɪl]。","et":"由 franco-（法国）+ 希腊语 philos（爱，朋友）构成。反义词 francophobe。","ex":[["Mon ami américain est un vrai francophile.","我的美国朋友是个地道的亲法派。"],["Elle est francophile depuis son enfance.","她从小就喜欢法国。"]],"co":[["un vrai francophile","真正的亲法派"],["être francophile","喜欢法国"],["francophile et francophone","亲法且说法语"]],"sy":[["francophobe","courant","反义词：反法的"],["amoureux de la France","courant","热爱法国的人"]],"fq":"低频，谈文化时用。","me":"franco + phile（爱）：爱法国的人。","tr":{"zh":"我父亲是个亲法派。","fr":"Mon père est un vrai francophile.","alt":"Mon père adore la France.","note":"francophile 阴阳同形，看冠词判断性别。"}},
 "Des cosmétiques": {"pos":"n.m.pl. 阳性复数名词，单数 un cosmétique","s":"化妆品；美容护肤产品。多用复数。也可作形容词：produits cosmétiques。日常口语里也常说 le maquillage（彩妆）。","ipa":"[kɔs.me.tik]","ph":"o [ɔ]；s 在 m 前读 [s]；é [e]；结尾 -ques 读 [k]，s 不发音。","pi":"结尾 -ques 的 s 不发音；cosmétique 重音在最后一个音节，不要重读第一个。","et":"来自希腊语 kosmetikos，kosmos（秩序；装饰）。同族：cosmos、cosmopolite。","ex":[["Elle achète beaucoup de cosmétiques.","她买很多化妆品。"],["Ce magasin vend des cosmétiques naturels.","这家店卖天然化妆品。"]],"co":[["des produits cosmétiques","化妆品"],["une marque de cosmétiques","化妆品品牌"],["les cosmétiques bio","有机化妆品"],["l'industrie cosmétique","化妆品行业"]],"sy":[["le maquillage","courant","彩妆"],["les produits de beauté","courant","美容产品"],["les soins","courant","护肤品"]],"fq":"中频，购物时常见。","me":"cosm- 与 cosmos 同源：让脸「有秩序」。","tr":{"zh":"我想买一些天然化妆品。","fr":"Je voudrais acheter des cosmétiques naturels.","alt":"Je cherche des produits de beauté naturels.","note":"cosmétiques 常以复数出现，搭配 des。"}},
 "Des débris": {"pos":"n.m.pl. 阳性名词，单复数同形 un débris / des débris","s":"碎片；残骸；垃圾碎屑。指东西被打碎后的小块，如玻璃、建筑物残骸。多用复数。","ipa":"[de.bʁi]","ph":"dé [de]；bri [bʁi]；结尾 s 不发音。","pi":"结尾 s 不发音；单复数同形，要靠冠词（un débris / des débris）判断。","et":"来自动词 débriser（打碎），dé- + briser。同族：briser。","ex":[["Il y a des débris de verre sur le sol.","地上有玻璃碎片。"],["Après la tempête, la plage était couverte de débris.","暴风雨后，海滩上到处是残骸。"]],"co":[["des débris de verre","玻璃碎片"],["des débris d'avion","飞机残骸"],["ramasser les débris","收拾碎片"]],"sy":[["des morceaux","courant","碎块"],["des ruines","courant","废墟"],["des déchets","courant","废物，垃圾"]],"fq":"中频，新闻与事故报道常用。","me":"débris ← briser：被打碎后留下的东西。","tr":{"zh":"他把地上的碎片捡了起来。","fr":"Il a ramassé les débris par terre.","alt":"Il a ramassé tous les débris qui étaient par terre.","note":"ramasser = 捡起，收拾。"}},
 "Des épinards": {"pos":"n.m.pl. 阳性复数名词，单数 un épinard（少用）","s":"菠菜。做菜时几乎总是复数：des épinards。菠菜泥 = épinards à la crème。法国人常说菠菜让人强壮（如大力水手）。","ipa":"[e.pi.naʁ]","ph":"é [e]；p [p]；i [i]；na [na]；结尾 -ards 读 [aʁ]，d、s 不发音。","pi":"结尾 -ards 只发 [aʁ]；d 和 s 都不发音。","et":"来自古法语，借自阿拉伯语 isbānakh（原出波斯语）。","ex":[["Popeye mange des épinards pour être fort.","大力水手吃菠菜变强壮。"],["Je prépare des épinards avec de l'ail.","我用大蒜炒菠菜。"]],"co":[["des épinards frais","新鲜菠菜"],["des épinards à la crème","奶油菠菜"],["une salade d'épinards","菠菜沙拉"],["des épinards surgelés","冷冻菠菜"]],"sy":[["des blettes","courant","甜菜叶（外观相近，不同蔬菜）"],["des légumes verts","courant","绿色蔬菜"]],"fq":"中频，饮食常见。","me":"épinards 结尾 -ards 只读 [aʁ]：d、s 都是哑音。","tr":{"zh":"孩子们不喜欢吃菠菜。","fr":"Les enfants n'aiment pas les épinards.","alt":"Les enfants détestent les épinards.","note":"表示「喜欢」类总称用定冠词 les。"}},
 "Des poireaux": {"pos":"n.m.pl. 阳性复数名词，单数 un poireau","s":"韭葱（欧洲常见蔬菜，比大葱粗，白绿相间，用来煮汤）。注意不是中国的韭菜。poireaux vinaigrette 是法国经典前菜。","ipa":"[pwa.ʁo]","ph":"oi 读 [wa]；r [ʁ]；eau 读 [o]；结尾 x 不发音。","pi":"-eaux 读 [o]，x 不发音；poireau 和 poire（梨）长得像，但意思不同。","et":"来自拉丁语 porrum（韭葱）。poireau 是后来的形式。","ex":[["J'ai acheté des poireaux au marché.","我在市场买了韭葱。"],["Elle prépare une soupe de poireaux et de pommes de terre.","她煮一锅韭葱土豆汤。"]],"co":[["une soupe de poireaux","韭葱汤"],["des poireaux vinaigrette","油醋汁韭葱"],["une tarte aux poireaux","韭葱派"]],"sy":[["un oignon","courant","洋葱"],["une ciboulette","courant","细香葱"],["une échalote","courant","红葱头"]],"fq":"中低频，做饭时用。","me":"poireau ≠ poire：韭葱不是梨。","tr":{"zh":"我用韭葱做汤。","fr":"Je fais une soupe avec des poireaux.","alt":"Je prépare une soupe aux poireaux.","note":"做汤原料用 avec 或 aux。"}},
 "Des restes": {"pos":"n.m.pl. 阳性复数名词，单数 un reste","s":"剩菜；剩下的东西。des restes 通常指吃剩的饭菜。le reste = 其余的部分。动词是 rester。","ipa":"[ʁɛst]","ph":"e 读 [ɛ]；s 和 t 都发音 [st]；结尾的 e 和复数 s 都不发音。","pi":"reste 的 s 和 t 都要发，结尾 e 不发音；复数 s 也不发。","et":"来自动词 rester，源自拉丁语 restare（留下，站住）。","ex":[["Il y a des restes d'hier dans le frigo.","冰箱里有昨天的剩菜。"],["On mange les restes ce soir.","我们今晚吃剩菜。"]],"co":[["les restes d'hier","昨天的剩菜"],["accommoder les restes","用剩菜做新菜"],["le reste de la journée","这一天的其余时间"],["du reste","再说，此外"]],"sy":[["les déchets","courant","垃圾"],["les débris","courant","碎片"],["le surplus","courant","多余的东西"]],"fq":"中高频，日常家居常用。","me":"restes ← rester：留下来的东西。","tr":{"zh":"我今天中午吃了昨天的剩菜。","fr":"J'ai mangé les restes d'hier à midi.","alt":"À midi, j'ai fini les restes d'hier.","note":"les restes d'hier：d' 是 de 的省音。"}},
 "Les moyens": {"pos":"n.m.pl. 阳性复数名词，单数 un moyen","s":"两个意思：1）财力、经济条件（avoir les moyens de = 有钱做某事）；2）手段、方法（un moyen de transport 交通工具）。注意 les moyens 单独出现时常指「财力」。","ipa":"[mwa.jɛ̃]","ph":"oy 读 [waj]，拆成 [wa] + [j]，再接 en [ɛ̃]：[mwa.jɛ̃]；结尾 s 不发音。","pi":"moyens 中 -en 读 [ɛ̃]，不是 [ɑ̃]；中间有个 [j] 滑音，别漏掉。","et":"来自拉丁语 medianus（居中的），medius（中间）。同族：milieu、médian。","ex":[["Il a les moyens de payer un hôtel cinq étoiles.","他有财力住五星级酒店。"],["Je n'ai pas les moyens d'acheter cette voiture.","我买不起这辆车。"]],"co":[["avoir les moyens de","有财力做……"],["un moyen de transport","交通工具"],["par tous les moyens","用一切手段"],["vivre au-dessus de ses moyens","超出收入过日子"]],"sy":[["les ressources","courant","资源，财力"],["l'argent","courant","钱"],["la façon","courant","方式"]],"fq":"高频，日常常用。","me":"moyen = 中间的，手段是目的与现实之间的「中介」。","tr":{"zh":"我买不起这套房子。","fr":"Je n'ai pas les moyens d'acheter cet appartement.","alt":"Je ne peux pas me payer cet appartement.","note":"avoir les moyens de + 动词原形。"}},
 "Aduler": {"pos":"v.tr. 及物动词（第一组，-er），助动词 avoir","s":"崇拜；极度喜爱和吹捧（某人）。常指粉丝对明星、孩子对偶像的崇拜，有时带「过分」的意味。","ipa":"[a.dy.le]","ph":"a [a]；du 读 [dy]，u 是圆唇 [y]；-er 读 [e]。","pi":"u 读 [y]，不是 [u]；结尾 -er 的 r 不发音。","et":"来自拉丁语 adulari（摇尾巴；谄媚）。同族：adulation（过分奉承）。","ex":[["Les fans adulent ce chanteur.","粉丝们崇拜这位歌手。"],["Les enfants l'adulent.","孩子们很崇拜他。"]],"co":[["aduler une star","崇拜明星"],["être adulé par ses fans","被粉丝崇拜"],["aduler quelqu'un","崇拜某人"]],"sy":[["adorer","courant","热爱，崇拜（更日常）"],["idolâtrer","soutenu","偶像崇拜般地爱"],["vénérer","soutenu","敬仰，崇敬"]],"fq":"低频，多见于新闻和文学。","me":"aduler 和 adorer 都有 ad-：把人捧上天。","tr":{"zh":"年轻人崇拜这位演员。","fr":"Les jeunes adulent cet acteur.","alt":"Les jeunes adorent cet acteur.","note":"aduler 比 adorer 更强烈、更书面。"}},
 "Caractériser": {"pos":"v.tr. 及物动词（第一组，-er），助动词 avoir；代词式 se caractériser par","s":"表现……的特征；使具有特点；描述特点。X caractérise Y = X 是 Y 的特点。se caractériser par = 以……为特点。","ipa":"[ka.ʁak.te.ʁi.ze]","ph":"ch 在这里读 [k]：[ka.ʁak]；é [e]；s 在元音间读 [z]。","pi":"ch 读 [k]，不是 [ʃ]；-iser 读 [i.ze]。","et":"来自 caractère（性格；特点），源自希腊语 kharaktêr（印记）。同族：caractéristique。","ex":[["La générosité caractérise cette personne.","慷慨是这个人的特点。"],["Cette région se caractérise par son climat doux.","这个地区的特点是气候温和。"]],"co":[["se caractériser par","以……为特点"],["ce qui caractérise","……的特征所在"],["caractériser un style","描述一种风格"]],"sy":[["définir","courant","定义，界定"],["décrire","courant","描述"],["distinguer","courant","使区分，标志"]],"fq":"中低频，书面语为主。","me":"caractère（特点）+ -iser：赋予特点。","tr":{"zh":"友善是他的特点。","fr":"La gentillesse le caractérise.","alt":"Il se caractérise par sa gentillesse.","note":"se caractériser par + 名词。"}},
 "Collaborer": {"pos":"v.int. 不及物动词（第一组，-er），助动词 avoir；常接 avec / à","s":"合作；协作。collaborer avec quelqu'un = 与某人合作；collaborer à un projet = 参与一个项目。注意历史上 collaborer 还指战时通敌（la collaboration）。","ipa":"[kɔ.la.bɔ.ʁe]","ph":"o [ɔ]；两个 l 读一个 [l]；-er 读 [e]。","pi":"collaborer 的 ll 只读一个 [l]；ab 读 [ab]；r 要发。","et":"来自拉丁语 collaborare，com-（一起）+ laborare（工作）。同族：élaborer、laboratoire。","ex":[["Nous allons collaborer sur ce nouveau projet.","我们将在这个新项目上合作。"],["Elle collabore avec plusieurs artistes.","她和好几位艺术家合作。"]],"co":[["collaborer avec","与……合作"],["collaborer à un projet","参与一个项目"],["collaborer étroitement","密切合作"]],"sy":[["coopérer","courant","合作，协作"],["travailler ensemble","courant","一起工作"],["participer","courant","参与"]],"fq":"中频，工作场合常用。","me":"col-（一起）+ labor（工作）：一起干活。","tr":{"zh":"我们和这家公司合作。","fr":"Nous collaborons avec cette entreprise.","alt":"On travaille en collaboration avec cette entreprise.","note":"collaborer avec + 人或机构。"}},
 "Confectionner": {"pos":"v.tr. 及物动词（第一组，-er），助动词 avoir","s":"（认真地）制作；做。多用于做菜、做点心或缝制衣服，强调手工、费心的制作。比 faire 更讲究、更书面。","ipa":"[kɔ̃.fɛk.sjɔ.ne]","ph":"on 鼻化 [ɔ̃]；ec 读 [ɛk]；ti 读 [sj]；-er 读 [e]。","pi":"ti 读 [si]，不是 [ti]；第一个音节 con- 是鼻化 [kɔ̃]，n 不单独发音。","et":"来自 confection（制作；成衣），源自拉丁语 conficere（完成，做成）。同族：confiserie。","ex":[["Elle va confectionner une robe pour le mariage.","她要为婚礼做一条裙子。"],["Il confectionne des gâteaux pour la fête.","他为聚会做蛋糕。"]],"co":[["confectionner un repas","做一顿饭"],["confectionner un vêtement","缝制衣服"],["confectionner un gâteau","做蛋糕"]],"sy":[["fabriquer","courant","制造"],["préparer","courant","准备，做饭"],["réaliser","courant","完成，做出"]],"fq":"低频，书面语，多用于手工和烹饪。","me":"confection（成衣）→ confectionner：手工做出东西。","tr":{"zh":"她亲手做了一件毛衣。","fr":"Elle a confectionné un pull elle-même.","alt":"Elle a fait un pull elle-même.","note":"confectionner 比 faire 更正式、更手工。"}},
 "Critiquer": {"pos":"v.tr. 及物动词（第一组，-er），助动词 avoir","s":"批评；指责；评论。多指挑毛病，有时带负面意味。也可指「评论」（作品）。名词 la critique 既指「批评」，也指「评论界、评论文章」。","ipa":"[kʁi.ti.ke]","ph":"cr 读 [kʁ]；ti 读 [ti]；qu 读 [k]；-er 读 [e]。","pi":"-tiquer 读 [ti.ke]，qu 是 [k]；不要发成 [kwe]。","et":"来自希腊语 kritikos，krinein（判断，区分）。同族：critère、crise。","ex":[["Il passe son temps à critiquer les autres.","他总是批评别人。"],["Les journaux ont critiqué ce film.","报纸对这部电影提出了批评。"]],"co":[["critiquer quelqu'un","批评某人"],["critiquer un film","评论一部电影"],["critiquer sévèrement","严厉批评"],["se faire critiquer","遭到批评"]],"sy":[["reprocher","courant","责备"],["blâmer","soutenu","谴责"],["dénigrer","soutenu","贬低"]],"fq":"高频，日常对话常用。","me":"critique 里的 -tique：像 critic 的「批评家」。","tr":{"zh":"别总是批评你的朋友。","fr":"Ne critique pas toujours tes amis.","alt":"Arrête de critiquer tes amis.","note":"否定命令式：Ne + 动词 + pas。"}},
 "Débuter": {"pos":"v.int. 不及物动词（第一组，-er），助动词 avoir（或 être，随语境）","s":"开始；起步。可指事件开始（Le film débute à 20 h），也指人刚开始做某事、初入行（Il débute dans le métier）。débuter 比 commencer 稍书面，但也常用。","ipa":"[de.by.te]","ph":"dé [de]；bu 读 [by]，u 是圆唇 [y]；-er 读 [e]。","pi":"u 读 [y]，不是 [u]；débuter 通常不接直接宾语。","et":"来自名词 début（开始），débutant（新手）同族。","ex":[["Le spectacle va débuter dans cinq minutes.","演出五分钟后开始。"],["Elle a débuté comme serveuse.","她一开始是做服务员的。"]],"co":[["débuter dans le métier","刚入行"],["débuter par","以……开始"],["le film débute à","电影在……开始"],["un débutant","新手"]],"sy":[["commencer","courant","开始（最常用）"],["démarrer","courant","启动，开始"],["entamer","soutenu","开始，着手"]],"fq":"中高频，较书面。","me":"début 的动词：起点，新手 débutant 也是它的亲戚。","tr":{"zh":"会议九点开始。","fr":"La réunion débute à neuf heures.","alt":"La réunion commence à neuf heures.","note":"débuter 不接直接宾语：débuter par + 名词。"}},
 "Décerner": {"pos":"v.tr. 及物动词（第一组，-er），助动词 avoir","s":"授予（奖项、称号、勋章）；颁发。常见搭配：décerner un prix / une médaille / un titre。正式场合用语。","ipa":"[de.sɛʁ.ne]","ph":"dé [de]；c 在 e 前读 [s]；er 读 [ɛʁ]；ne 读 [ne]。","pi":"c 读 [s]；-cer- 的 e 读 [ɛ]，结尾 -er 读 [e]。","et":"来自拉丁语 decernere（判定，裁决），de- + cernere（区分）。同族：discerner。","ex":[["Le maire va décerner une médaille au héros.","市长将向英雄颁发奖章。"],["On a décerné un prix à cette jeune actrice.","他们给这位年轻女演员颁了奖。"]],"co":[["décerner un prix","颁发奖项"],["décerner une médaille","授予奖章"],["décerner un titre","授予头衔"]],"sy":[["attribuer","courant","授予，分配"],["remettre","courant","颁发，交给"],["octroyer","soutenu","给予，授予"]],"fq":"低频，正式场合。","me":"décerner 想到 discerner：判定谁该得奖。","tr":{"zh":"他们把最佳影片奖颁给了她。","fr":"On lui a décerné le prix du meilleur film.","alt":"Elle a reçu le prix du meilleur film.","note":"décerner qqch à qqn。"}},
 "Défiler": {"pos":"v.int. 不及物动词（第一组，-er），助动词 avoir","s":"1）列队走过；游行（les soldats défilent）；2）走秀（les mannequins défilent）；3）（画面）滚动、一个接一个（les images défilent）。","ipa":"[de.fi.le]","ph":"dé [de]；fi [fi]；-er 读 [e]。","pi":"三个音节，每个元音都清楚：dé-fi-ler；不要和 défier（挑战）混淆。","et":"来自 dé- + fil（线；队列），原指排成一列通过。同族：file、filer。","ex":[["Les mannequins défilent sur le podium.","模特在台上走秀。"],["Les soldats défilent dans la rue.","士兵们在街上列队走过。"]],"co":[["défiler sur un podium","在台上走秀"],["un défilé de mode","时装秀"],["le défilé du 14 juillet","七月十四日阅兵"],["faire défiler la page","滚动页面"]],"sy":[["marcher","courant","走路，行进"],["parader","courant","炫耀地走，游行"],["manifester","courant","示威游行"]],"fq":"中频，新闻和时尚里常见。","me":"défiler ← fil：排成一条线走过去。","tr":{"zh":"人们在街上游行。","fr":"Les gens défilent dans la rue.","alt":"Les gens manifestent dans la rue.","note":"défiler 不接直接宾语。"}},
 "Demeurer": {"pos":"v.int. 不及物动词（第一组，-er），助动词 être（表示「依然」）或 avoir（表示「居住」）","s":"1）依然是；保持（Le mystère demeure）；2）（书面）居住、住；3）留下。多用于书面。日常说话用 rester（留下、依然）和 habiter（住）。","ipa":"[də.mœ.ʁe]","ph":"de 弱读 [də]；eu 读 [œ]；r [ʁ]；-er 读 [e]。","pi":"第一个 e 读 [ə]（弱化）；eu 读 [œ]（开口），不是 [ø]。","et":"来自拉丁语 demorari（停留，耽搁）。同族：demeure（住所）。","ex":[["Le mystère demeure entier.","谜团依旧。"],["Elle demeure à Lyon depuis dix ans.","她在里昂住了十年。"]],"co":[["demeurer calme","保持冷静"],["demeurer sans réponse","依旧没有答案"],["il demeure que","仍然是……（事实）"],["en demeurer là","到此为止"]],"sy":[["rester","courant","留下，依然（更常用）"],["habiter","courant","居住"],["résider","soutenu","居住（正式）"]],"fq":"低频，书面语。","me":"demeure（住所）的动词：住下来，也就是留下。","tr":{"zh":"尽管如此，问题依然存在。","fr":"Malgré tout, le problème demeure.","alt":"Malgré tout, le problème reste là.","note":"demeurer 书面，口语用 rester。"}},
 "Distribuer": {"pos":"v.tr. 及物动词（第一组，-er），助动词 avoir","s":"分发；分配；派送。distribuer des tracts = 发传单；distribuer les cartes = 发牌。也指商品的销售网络（distribuer des produits）。","ipa":"[dis.tʁi.bɥe]","ph":"dis [dis]；tr [tʁ]；bu-er 读 [bɥe]，u 变半元音 [ɥ]。","pi":"-uer 读 [ɥe]，不是 [u.e]；s 在 dis- 中读 [s]，不要读成 [z]。","et":"来自拉丁语 distribuere，dis-（分开）+ tribuere（给予）。同族：contribuer、attribuer、tribu。","ex":[["L'association va distribuer des repas aux sans-abris.","协会将向无家可归者分发饭菜。"],["Il distribue des tracts devant le métro.","他在地铁站前发传单。"]],"co":[["distribuer des tracts","发传单"],["distribuer les cartes","发牌"],["distribuer le courrier","派送信件"],["la distribution","分发；配送；演员阵容"]],"sy":[["répartir","courant","分配，分摊"],["donner","courant","给"],["livrer","courant","送货"]],"fq":"中高频，常用。","me":"dis-（分开）+ tribuere（给）：分给每个人。","tr":{"zh":"老师给学生们分发了练习。","fr":"Le professeur a distribué les exercices aux élèves.","alt":"Le prof a donné les exercices à tous les élèves.","note":"distribuer qqch à qqn。"}},
 "Émouvoir": {"pos":"v.tr. 及物动词（第三组，不规则），助动词 avoir；过去分词 ému；代词式 s'émouvoir","s":"使感动；打动。用得最多的是被动形式：être ému(e) = 被感动，很动容。名词 l'émotion，形容词 émouvant = 动人的。","ipa":"[e.mu.vwaʁ]","ph":"é [e]；ou 读 [u]；voir 读 [vwaʁ]。","pi":"过去分词是 ému，不是 émouvé；变位不规则：j'émeus、nous émouvons、ils émeuvent。","et":"来自拉丁语 emovere（移出，动起来），é- + mouvoir（移动）。同族：émotion、mouvement。","ex":[["J'ai été ému par cette histoire.","这个故事让我感动。"],["Son discours a ému toute la salle.","他的演讲打动了整个大厅。"]],"co":[["être ému(e) par","被……感动"],["ému(e) aux larmes","感动得落泪"],["un film émouvant","感人的电影"],["se laisser émouvoir","被打动"]],"sy":[["toucher","courant","触动，感动"],["attendrir","courant","使心软"],["bouleverser","courant","使深受震动"]],"fq":"中频，描述情感时用。","me":"é + mouvoir：让心「动起来」。","tr":{"zh":"这首歌让我很感动。","fr":"Cette chanson m'a beaucoup ému.","alt":"Cette chanson m'a touché.","note":"女性说话用 émue：Elle est émue。"}},
 "Exercer": {"pos":"v.tr. 及物动词（第一组，-er），助动词 avoir；c 在 a/o 前写 ç，此处 exerçons","s":"1）从事（职业）：exercer la profession de médecin；2）行使（权力）、施加（影响）；3）锻炼；练习。s'exercer = 练习。","ipa":"[ɛɡ.zɛʁ.se]","ph":"ex 在元音前读 [ɛɡz]；cer 的 c 读 [s]；-er 读 [e]。","pi":"ex- 读 [ɛɡz]，不是 [ɛks]；nous exerçons 要加 ç。","et":"来自拉丁语 exercere（驱赶，使不停工作；锻炼）。同族：exercice。","ex":[["Il exerce la profession de médecin.","他从事医生职业。"],["Cette décision exerce une grande influence.","这个决定产生很大影响。"]],"co":[["exercer un métier","从事一个职业"],["exercer une influence sur","对……施加影响"],["exercer son droit","行使权利"],["s'exercer à","练习……"]],"sy":[["pratiquer","courant","从事，实践"],["travailler","courant","工作"],["s'entraîner","courant","训练"]],"fq":"中频，正式与书面常用。","me":"exercice 的动词：反复做某事。","tr":{"zh":"她在巴黎当律师。","fr":"Elle exerce la profession d'avocate à Paris.","alt":"Elle est avocate à Paris.","note":"exercer + 职业名词，口语更常说 être + 职业。"}},
 "Fantasmer": {"pos":"v.int. 不及物动词（第一组，-er），助动词 avoir；常接 sur","s":"幻想；做白日梦。fantasmer sur = 幻想（某事或某人）。有「不切实际」的意味。名词 un fantasme = 幻想。","ipa":"[fɑ̃.tas.me]","ph":"an 鼻化 [ɑ̃]；t [t]；as 读 [as]；me 读 [me]。","pi":"an 是 [ɑ̃]；s 在 t 和 m 之间读 [s]；不要读成 fantôme（鬼魂）。","et":"来自 fantasme，源自希腊语 phantasma（幻象）。同族：fantôme、fantastique。","ex":[["Il fantasme sur la vie qu'il aurait s'il était riche.","他幻想如果富有会有怎样的生活。"],["Elle fantasme sur ses prochaines vacances.","她幻想着下一个假期。"]],"co":[["fantasmer sur","幻想……"],["un fantasme","幻想，白日梦"],["fantasmer sur l'avenir","幻想未来"]],"sy":[["rêver","courant","做梦，梦想"],["imaginer","courant","想象"],["divaguer","soutenu","胡思乱想"]],"fq":"中低频。","me":"fantasme ≈ fantasy：脑子里的幻想。","tr":{"zh":"他整天幻想着中大奖。","fr":"Il fantasme toute la journée sur un gros gain à la loterie.","alt":"Il passe son temps à rêver de gagner à la loterie.","note":"fantasmer sur + 名词。"}},
 "Galvaniser": {"pos":"v.tr. 及物动词（第一组，-er），助动词 avoir","s":"激励；使振奋；使精神焕发。ce projet me galvanise = 这个项目让我充满干劲。也是技术词：镀锌。","ipa":"[ɡal.va.ni.ze]","ph":"g 在 a 前读 [ɡ]；v [v]；s 在元音间读 [z]；-er 读 [e]。","pi":"g 读 [ɡ]（硬 g）；s 读 [z]；注意不要和 organiser 混淆。","et":"来自人名 Luigi Galvani（意大利科学家）；他发现电流能使蛙腿抽动。","ex":[["Ce projet me galvanise.","这个项目让我振奋。"],["Le discours du coach a galvanisé l'équipe.","教练的讲话让团队精神大振。"]],"co":[["galvaniser une équipe","激励一个团队"],["galvaniser les foules","鼓动群众"],["se sentir galvanisé","感到振奋"]],"sy":[["motiver","courant","激励"],["stimuler","courant","刺激，鼓舞"],["électriser","soutenu","使激动，使电击般兴奋"]],"fq":"低频，书面语。","me":"来自 Galvani 的电：像被电了一下，精神一振。","tr":{"zh":"这场胜利激励了球队。","fr":"Cette victoire a galvanisé l'équipe.","alt":"Cette victoire a donné un coup de fouet à l'équipe.","note":"galvaniser qqn 直接接宾语。"}},
 "Illustrer": {"pos":"v.tr. 及物动词（第一组，-er），助动词 avoir","s":"1）举例说明；2）为书配插图；3）使著名（s'illustrer = 以……出名）。le dessinateur illustre un livre = 画家为书画插图。","ipa":"[i.lys.tʁe]","ph":"i [i]；ll 读 [l]；u [y]；str 读 [stʁ]。","pi":"词首 il- 读 [i.l]，不是 [ij]；u 是 [y]。","et":"来自拉丁语 illustrare（照亮；使清楚）。同族：illustration、lustre。","ex":[["Cet exemple permet d'illustrer mon propos.","这个例子可以说明我的观点。"],["Elle illustre des livres pour enfants.","她给儿童书画插图。"]],"co":[["illustrer un livre","为书配插图"],["illustrer un propos","说明观点"],["s'illustrer par","以……出名"],["une photo qui illustre l'article","配合文章的照片"]],"sy":[["expliquer","courant","解释"],["montrer","courant","展示"],["éclairer","soutenu","阐明"]],"fq":"中频，书面和学术常用。","me":"illustrer ← lustre（光）：用例子或图画「照亮」。","tr":{"zh":"这张图能说明我的想法。","fr":"Cette image illustre bien mon idée.","alt":"Ce dessin montre bien ce que je veux dire.","note":"illustrer 在这里等于「说明」。"}},
 "Influer sur": {"pos":"v.int. 不及物动词（第一组，-er），助动词 avoir；固定搭配 influer sur + 名词","s":"对……产生影响。后面接 sur。比 influencer（直接宾语，使受影响）更常用于事物：Le stress influe sur la santé。注意用法区别。","ipa":"[ɛ̃.flɥe syʁ]","ph":"in 鼻化 [ɛ̃]；fl [fl]；-uer 读 [ɥe]；sur 读 [syʁ]。","pi":"influer 后面一定接 sur；influencer 才直接接宾语。-uer 读 [ɥe]。","et":"来自拉丁语 influere（流入），in- + fluere（流）。同族：influence、fluide。","ex":[["Le stress peut influer sur la santé.","压力会影响健康。"],["La météo influe sur mon humeur.","天气影响我的心情。"]],"co":[["influer sur la décision","影响决定"],["influer sur le résultat","影响结果"],["influer sur le moral","影响情绪"]],"sy":[["influencer","courant","影响（直接宾语）"],["agir sur","courant","对……起作用"],["avoir un effet sur","courant","对……有影响"]],"fq":"中频，书面和新闻常用。","me":"in + fluer（流）：影响像水流进去。","tr":{"zh":"睡眠会影响你的心情。","fr":"Le sommeil influe sur ton humeur.","alt":"Dormir mal influence ton humeur.","note":"influer sur + 名词；influencer + 直接宾语。"}},
 "Initier": {"pos":"v.tr. 及物动词（第一组，-er），助动词 avoir；常接 à","s":"引导入门；使初次接触（某领域）：initier qqn à qqch。也指发起、开启（initier un projet）。s'initier à = 初学。","ipa":"[i.ni.sje]","ph":"i [i]；ni [ni]；tier 读 [sje]，t 在 i 前读 [s]。","pi":"-tier 读 [sje]，不是 [tje]；与 initial 里的 ti 同一个规律。","et":"来自拉丁语 initiare，initium（开始）。同族：initial、initiative。","ex":[["Il veut m'initier à la cuisine japonaise.","他想带我入门日本料理。"],["Elle s'initie à la peinture.","她刚开始学画画。"]],"co":[["initier qqn à","引导某人入门"],["s'initier à","开始学"],["initier un projet","发起项目"],["un initié","内行人"]],"sy":[["introduire","courant","引入，介绍"],["apprendre","courant","教，学"],["lancer","courant","发起，启动"]],"fq":"中低频。","me":"initier ← initial：从最初开始教。","tr":{"zh":"我姐姐带我入门了瑜伽。","fr":"Ma sœur m'a initié au yoga.","alt":"Ma sœur m'a fait découvrir le yoga.","note":"initier qqn à qqch。"}},
 "Livrer": {"pos":"v.tr. 及物动词（第一组，-er），助动词 avoir；常接 à","s":"送货；交付；投递。le facteur livre le colis = 邮递员送包裹。引申：livrer un secret（说出秘密）、se livrer（坦露心声）。名词 la livraison = 送货。","ipa":"[li.vʁe]","ph":"li [li]；vr [vʁ]；-er 读 [e]。","pi":"livrer 和 livre（书）的发音相近但意思不同；-er 的 r 不发音。","et":"来自拉丁语 liberare（使自由，解放），后引申为「交出」。同族：libérer、liberté。","ex":[["Le facteur va livrer le colis ce matin.","邮递员今早送包裹。"],["On livre à domicile.","我们送货上门。"]],"co":[["livrer à domicile","送货上门"],["livrer un colis","送包裹"],["se livrer à","沉溺于；坦露"],["la livraison gratuite","免费送货"]],"sy":[["apporter","courant","带来"],["remettre","courant","交给"],["expédier","courant","寄出"]],"fq":"高频，购物和服务常用。","me":"livrer ≠ livre：一个是「送货」，一个是「书」。","tr":{"zh":"你们明天能送货吗？","fr":"Vous pouvez livrer demain ?","alt":"Vous livrez demain ?","note":"livrer 后接地点用 à。"}},
 "Prévoir de": {"pos":"v.tr. 及物动词（第三组，不规则，同 voir 变位），助动词 avoir；过去分词 prévu","s":"计划；打算（做某事）。prévoir de + 动词原形 = 计划做；prévoir + 名词 = 预料；预先安排。je prévois = 现在时；将来时是 je prévoirai。","ipa":"[pʁe.vwaʁ də]","ph":"pré [pʁe]；voir 读 [vwaʁ]；de 弱读 [də]。","pi":"将来时是 je prévoirai（不像 voir 的 je verrai）；过去分词 prévu。","et":"由 pré-（预先）+ voir（看）构成，来自拉丁语 praevidere。同族：prévision、imprévu。","ex":[["Je prévois de voyager l'année prochaine.","我打算明年去旅行。"],["Qu'est-ce que tu prévois pour ce week-end ?","这个周末你有什么安排？"]],"co":[["prévoir de + 动词原形","计划做……"],["tout prévoir","考虑周全"],["comme prévu","如预期"],["prévoir le pire","预想最坏的情况"]],"sy":[["envisager de","courant","考虑做"],["projeter de","soutenu","计划做"],["avoir l'intention de","courant","打算做"]],"fq":"高频，日常常用。","me":"pré（先）+ voir（看）：先看到，也就是先安排。","tr":{"zh":"我们打算七月去西班牙。","fr":"Nous prévoyons d'aller en Espagne en juillet.","alt":"On prévoit d'aller en Espagne en juillet.","note":"prévoir de + 动词原形；nous prévoyons。"}},
 "Profiter de quelqu'un": {"pos":"v.int. 不及物动词（第一组，-er），助动词 avoir；用法：profiter de + 人或物","s":"占某人的便宜；利用某人。profiter de qqn 带负面意味。profiter de qqch 则是「好好享受；利用机会」，是中性或褒义：profiter du soleil = 享受阳光。","ipa":"[pʁɔ.fi.te də kɛl.kœ̃]","ph":"o [ɔ]；fi [fi]；-er 读 [e]；quelqu'un 读 [kɛl.kœ̃]，un 读 [œ̃]。","pi":"profiter de qqn 是负面（占便宜）；profiter de qqch 是正面（享受）。quelqu'un 的 un 是 [œ̃]。","et":"来自 profit（好处），源自拉丁语 profectus（进步）。同族：profit、profitable。","ex":[["Thomas est trop gentil, les gens profitent de lui.","托马斯太善良了，人们利用他。"],["Profitons du beau temps !","我们好好享受好天气吧！"]],"co":[["profiter de quelqu'un","占某人便宜"],["profiter de l'occasion","利用机会"],["profiter de la vie","享受生活"],["Bon appétit, profitez-en !","好好享受吧！"]],"sy":[["abuser de","courant","滥用，欺负"],["exploiter","courant","剥削，利用"],["tirer parti de","soutenu","从……中获益"]],"fq":"高频，日常常用。","me":"profit + er：从别人身上取利。","tr":{"zh":"别让别人占你的便宜。","fr":"Ne laisse pas les autres profiter de toi.","alt":"Ne te laisse pas avoir par les autres.","note":"profiter de + 人 = 占便宜；laisser + 原形。"}},
 "Puiser dans": {"pos":"v.tr.ind. 及物动词（第一组，-er），助动词 avoir；固定搭配 puiser dans + 名词","s":"1）汲取（水等）：puiser de l'eau dans un puits；2）从……中动用或汲取：puiser dans ses économies（动用积蓄）、puiser son inspiration dans（从……获得灵感）。","ipa":"[pɥi.ze dɑ̃]","ph":"pui 读 [pɥi]；s 在元音间读 [z]；-er 读 [e]；dans 读 [dɑ̃]。","pi":"ui 读 [ɥi]，不是 [ui]；s 读 [z]。","et":"来自 puits（井），源自拉丁语 puteus。同族：puits。","ex":[["Il doit puiser dans ses réserves pour finir la course.","他得动用储备才能跑完比赛。"],["Elle puise son inspiration dans la nature.","她从大自然里汲取灵感。"]],"co":[["puiser dans ses économies","动用积蓄"],["puiser de l'eau","打水"],["puiser son inspiration dans","从……汲取灵感"],["puiser des forces","汲取力量"]],"sy":[["tirer","courant","拉，取"],["utiliser","courant","使用"],["prélever","soutenu","提取，抽取"]],"fq":"中低频，书面语。","me":"puiser ← puits（井）：像从井里打水。","tr":{"zh":"我得动用我的积蓄。","fr":"Je dois puiser dans mes économies.","alt":"Je vais devoir toucher à mes économies.","note":"puiser dans + 名词。"}},
 "Rater": {"pos":"v.t./v.i. 动词，第一组 -er，助动词 avoir","s":"错过（火车、机会）；搞砸、失败（考试、蛋糕、计划）。rater un examen = 考试没过；Ça a raté = 没成功。注意：rater 是日常用词，比 échouer 口语。","ipa":"[ʁa.te]","ph":"r 是小舌音 [ʁ]；a [a]；t [t]；-er 读 [e]，r 不发音。","pi":"结尾 -er 不发 r；过去分词 raté 也读 [ʁa.te]。别和英语 rate（评分）混淆，意思完全不同。","et":"来源不确定；最初用于枪「哑火」，后来引申为「失败」。同族：un raté（失败者）。","ex":[["J'ai raté mon train ce matin.","我今早错过了火车。"],["Elle a raté son gâteau.","她把蛋糕做砸了。"],["Il a raté son examen de conduite.","他驾照考试没通过。"]],"co":[["rater un train / un bus","错过火车 / 公交"],["rater un examen","考试没过"],["rater une occasion","错过机会"],["rater son coup","没做成、失手"]],"sy":[["manquer","courant","错过（manquer un train 也可以）"],["échouer","courant","失败，考试用 échouer à"],["louper","familier","错过、搞砸，更随意"]],"fq":"高频，日常常用。","me":"r-a-ter：火车「拉」走了，你没赶上。","tr":{"zh":"我错过了最后一班地铁。","fr":"J'ai raté le dernier métro.","alt":"J'ai loupé le dernier métro.","note":"rater 后直接接宾语，不加介词。"}},
 "Réadapter": {"pos":"v.t. 动词，第一组 -er；se réadapter = 重新适应","s":"重新调整，使再次适应。réadapter qc à qc = 把某物改得适合……；se réadapter à = 重新适应（环境、生活）。偏书面，日常也说 se réhabituer à。","ipa":"[ʁe.a.dap.te]","ph":"ré [ʁe]，a [a]，dap [dap]，ter [te]。ré 和 a 分开读两个音节。","pi":"ré-a 要分成两个音节，不要连成一个音；结尾 -er 不发 r。","et":"ré-（再次）+ adapter（拉丁语 adaptare，使适合）。同族：adaptation, réadaptation。","ex":[["Il a dû réadapter son discours pour le public.","他不得不为听众重新调整演讲。"],["Après un an à l'étranger, elle a du mal à se réadapter.","在国外待了一年后，她很难重新适应。"]],"co":[["réadapter un texte / un plan","重新调整文本 / 计划"],["se réadapter à la vie normale","重新适应正常生活"],["un centre de réadaptation","康复中心"]],"sy":[["adapter","courant","使适应，没有「再次」的意思"],["se réhabituer à","courant","重新习惯于"]],"fq":"低频，偏书面。","me":"ré-（再）+ adapter：再来一次「适应」。","tr":{"zh":"回国后，他要重新适应这里的生活。","fr":"Après son retour, il doit se réadapter à la vie ici.","alt":"Il doit se réhabituer à la vie ici.","note":"se réadapter à + 名词；复合时态助动词用 être。"}},
 "Recueillir": {"pos":"v.t. 动词，第三组，助动词 avoir；过去分词 recueilli","s":"收集、汇集（证词、信息、食谱）；收留（动物、孤儿）；得到（选票、掌声）。se recueillir = 静默沉思、默哀。","ipa":"[ʁə.kœ.jiʁ]","ph":"re [ʁə]；cueil 读 [kœj]；ill 读 [j]；结尾 -ir 读 [iʁ]。","pi":"写成 cueil 是为了让 c 保持 [k] 音。别和 accueillir（接待、欢迎）搞混。变位：je recueille, nous recueillons, 将来时 je recueillerai。","et":"拉丁语 recolligere（re- + colligere，收集）。同族：cueillir（采摘）, accueillir, recueil（文集）。","ex":[["Elle a recueilli toutes les recettes de sa grand-mère.","她收集了外婆所有的食谱。"],["Nous avons recueilli un chaton abandonné.","我们收留了一只被遗弃的小猫。"],["Le journaliste recueille des témoignages.","记者在收集证词。"]],"co":[["recueillir des témoignages / des informations","收集证词 / 信息"],["recueillir un animal","收留动物"],["recueillir des voix","获得选票"],["se recueillir sur une tombe","在墓前默哀"]],"sy":[["collecter","courant","收集，偏数据、捐款"],["rassembler","courant","聚集在一起"],["accueillir","courant","易混：接待、迎接，不是收集"]],"fq":"中频，书面和新闻里常见。","me":"re + cueillir：把东西一朵朵「采」回来。","tr":{"zh":"我们收集了一些关于这个村子的信息。","fr":"Nous avons recueilli des informations sur ce village.","alt":"On a rassemblé des infos sur ce village.","note":"recueillir 要直接接宾语；别写成 recuillir。"}},
 "Rendre": {"pos":"v.t. 动词，第三组 -re，助动词 avoir；过去分词 rendu","s":"① 归还；② rendre + 形容词 = 使……变得（Ça me rend triste）；③ rendre visite à / rendre service à。se rendre à = 前往。","ipa":"[ʁɑ̃dʁ]","ph":"en 读鼻化 [ɑ̃]；d [d]；结尾 -dre 读 [dʁ]，e 不发音。","pi":"过去分词 rendu 读 [ʁɑ̃.dy]，别漏掉 d。rendre + 形容词时，形容词要和宾语一致。变位：je rends, nous rendons。","et":"拉丁语 reddere（归还），俗拉丁语 rendere。同族：rendez-vous, reddition。","ex":[["Ce film m'a rendu heureux.","这部电影让我很开心。"],["Je dois rendre ce livre à la bibliothèque.","我得把这本书还给图书馆。"],["Rendez-moi mon stylo, s'il vous plaît.","请把我的笔还给我。"]],"co":[["rendre + adjectif","使……变得……"],["rendre visite à quelqu'un","拜访某人"],["rendre service","帮忙"],["se rendre à + lieu","前往某地"]],"sy":[["restituer","soutenu","归还，用于官方场合"],["retourner","courant","退回、寄回"],["faire","courant","Ça me fait peur 用 faire + 名词；rendre 后接形容词"]],"fq":"极高频，日常常用。","me":"rendre = 把东西「交回去」，也把心情「交到」你身上。","tr":{"zh":"这个消息让她很高兴。","fr":"Cette nouvelle l'a rendue très heureuse.","alt":"Cette nouvelle lui a fait très plaisir.","note":"rendre + 形容词：形容词与宾语 la（她）一致，所以是 heureuse。"}},
 "Renouveler": {"pos":"v.t. 动词，第一组 -er，助动词 avoir","s":"更新、更换；续签、续期（护照、合同、订阅）；重复做。se renouveler = 推陈出新。比 changer 更正式。","ipa":"[ʁə.nu.və.le]","ph":"re [ʁə]；ou [u]；ve [və]；-er 读 [e]。","pi":"变位时 l 要双写：je renouvelle, ils renouvellent，将来时 je renouvellerai。别读成 [renuvle]，要保留每个音节。","et":"re- + nouveler（来自 nouveau，拉丁语 novellus「新的」）。同族：nouveau, nouvelle, innover。","ex":[["Il faut renouveler ton passeport avant le voyage.","旅行前要办理你的护照续期。"],["Elle renouvelle son abonnement chaque année.","她每年都续订。"],["Le contrat sera renouvelé en juin.","合同将在六月续签。"]],"co":[["renouveler un passeport / un contrat","办理护照续期 / 续签合同"],["renouveler un abonnement","续订"],["renouveler sa demande","重新提出申请"],["se renouveler","推陈出新"]],"sy":[["prolonger","courant","延长时间"],["reconduire","soutenu","续签（合同、协议）"],["remplacer","courant","替换成新的"]],"fq":"中高频，办事、行政常用。","me":"re + nouveau：再变「新」一次。","tr":{"zh":"我得续签我的居留证。","fr":"Je dois renouveler mon titre de séjour.","alt":"Il faut que je fasse renouveler mon titre de séjour.","note":"renouveler 后直接接宾语；l 在 je renouvelle 中要双写。"}},
 "Résumer": {"pos":"v.t. 动词，第一组 -er，助动词 avoir","s":"概括、总结（书、电影、会议、事情）。se résumer à = 归结为。En résumé = 总之。","ipa":"[ʁe.zy.me]","ph":"ré [ʁe]；s 在两个元音之间读 [z]；u [y]；-er 读 [e]。","pi":"s 读 [z]，不是 [s]；u 读 [y]，嘴唇圆而小。英语 resume（继续）在法语里是 reprendre，不是 résumer。","et":"拉丁语 resumere（再拿起、重述）。同族：un résumé（名词，摘要）。","ex":[["Pouvez-vous résumer ce livre en quelques phrases ?","你能用几句话概括这本书吗？"],["Je vais résumer l'histoire en deux mots.","我用两句话概括这个故事。"],["Pour résumer, tout va bien.","总之，一切顺利。"]],"co":[["résumer un livre / un film","概括一本书 / 一部电影"],["en résumé / pour résumer","总之"],["se résumer à","归结为"],["résumer en quelques mots","用几句话概括"]],"sy":[["synthétiser","soutenu","综合概括，更学术"],["abréger","courant","缩短、简写"],["récapituler","courant","回顾要点"]],"fq":"中高频，学习和工作常用。","me":"résumer ≈ 拿起要点「再说一遍」，别和 resume（继续）搞混。","tr":{"zh":"你能用一句话概括这部电影吗？","fr":"Peux-tu résumer ce film en une phrase ?","alt":"Tu peux me résumer ce film en une phrase ?","note":"résumer qc en + 数量：用……来概括。"}},
 "Retenir": {"pos":"v.t. 动词，第三组，助动词 avoir；过去分词 retenu","s":"拉住、留住；记住；预订（retenir une chambre）；忍住（眼泪、笑）；扣留（款项）。比 se souvenir 多一层「主动记住」的意思。","ipa":"[ʁə.tə.niʁ]","ph":"re [ʁə]；te [tə]；ni [ni]；r [ʁ]。变位时 -ien 读 [jɛ̃]：il retient [ʁə.tjɛ̃]。","pi":"变位像 tenir：je retiens, nous retenons, ils retiennent；将来时 je retiendrai。别和 se souvenir de（想起）混淆：retenir 是主动去记。","et":"拉丁语 retinere（re- + tenere，握住）。同族：tenir, retenue, rétention。","ex":[["Mon chien veut courir après un chat. Je dois le retenir.","我的狗想追猫，我得拉住它。"],["Je n'arrive pas à retenir ce numéro.","我记不住这个号码。"],["J'ai retenu une table pour huit heures.","我订了八点的位子。"]],"co":[["retenir son souffle / ses larmes","屏住呼吸 / 忍住眼泪"],["retenir une chambre / une place","预订房间 / 座位"],["retenir un nom","记住一个名字"],["retenir quelqu'un","留住某人"]],"sy":[["mémoriser","courant","背下来，记住"],["réserver","courant","预订，更常用"],["garder","courant","保留、留着"]],"fq":"高频，日常常用。","me":"re + tenir：把东西「握住不放」。","tr":{"zh":"我记不住这些单词。","fr":"Je n'arrive pas à retenir ces mots.","alt":"J'ai du mal à retenir ces mots.","note":"n'arrive pas à + 动词原形：做不到。"}},
 "Reverser": {"pos":"v.t. 动词，第一组 -er，助动词 avoir","s":"① 再倒一次、再添（reverser du café）；② 把收到的钱再转付给别人（reverser une partie des gains à une association），多见于财务、行政。书里的「捐出」只是其中一种用法。","ipa":"[ʁə.vɛʁ.se]","ph":"re [ʁə]；ver [vɛʁ]；ser [se]。s 在 r 后读 [s]。","pi":"e 在 ver 中读开口 [ɛ]；-er 的 r 不发音。别和英语 reverse（颠倒）搞混：颠倒用 inverser / renverser。","et":"re- + verser（拉丁语 versare，倒、转动）。同族：verser, versement。","ex":[["L'entreprise va reverser une partie de ses gains à une œuvre caritative.","公司将把部分收益转给慈善机构。"],["Peux-tu me reverser un peu d'eau ?","你能再给我倒点水吗？"],["Le club reverse dix pour cent des ventes à une association.","俱乐部把销售额的百分之十转给一个协会。"]],"co":[["reverser de l'argent à","把钱转付给"],["reverser une partie des bénéfices","转出部分利润"],["reverser du café / du vin","再倒咖啡 / 酒"],["le reversement","转付"]],"sy":[["transférer","courant","转账、转移"],["verser","courant","付款、倒入"],["rétrocéder","soutenu","转让、回让"]],"fq":"低频，偏财务和行政。","me":"re + verser：钱流进来，再「倒」给别人。","tr":{"zh":"这家公司把部分利润转给了一家协会。","fr":"Cette société a reversé une partie de ses bénéfices à une association.","alt":"La société donne une partie de ses bénéfices à une association.","note":"reverser qc à qn：把某物转给某人。"}},
 "Rimer": {"pos":"v.i. 动词，第一组 -er，助动词 avoir","s":"押韵。引申义：rimer avec = 与……紧密相连、总是联想到（Pour moi, dimanche rime avec repos）；ne rimer à rien = 毫无意义。","ipa":"[ʁi.me]","ph":"ri [ʁi]；mer [me]；-er 读 [e]。","pi":"i 读短 [i]，别拉长；结尾 -er 的 r 不发音。「rimer avec」后接名词，不要写成 rimer à。","et":"来自名词 rime（韵）；词源有争议，不确定。同族：rime, rimeur。","ex":[["« Chat » rime avec « rat ».","chat 和 rat 押韵。"],["Ce festival rime avec francophonie.","这个节日与法语世界紧密相连。"],["Pour moi, dimanche rime avec repos.","对我来说，星期天就意味着休息。"]],"co":[["rimer avec","与……押韵 / 紧密相连"],["ne rimer à rien","毫无意义"],["une rime riche","丰富的韵"],["des mots qui riment","押韵的词"]],"sy":[["être associé à","courant","被联想到、与……相关"],["aller de pair avec","courant","与……相伴而行"]],"fq":"中频，诗歌和比喻中常见。","me":"rime（韵）+ -r：让词和词「配成一对」。","tr":{"zh":"对我来说，夏天就是假期。","fr":"Pour moi, l'été rime avec vacances.","alt":"Pour moi, l'été, ça veut dire vacances.","note":"A rime avec B：A 总让人想到 B。"}},
 "Sublimer": {"pos":"v.t. 动词，第一组 -er，助动词 avoir","s":"使更美、更出彩、突出优点（sublimer un plat, un visage）；心理学上指「升华」（情绪转化为创造力）；化学上指「升华」。","ipa":"[sy.bli.me]","ph":"su [sy]；bli [bli]；mer [me]。","pi":"u 读 [y]；别把 su 读成 [su]。-er 的 r 不发音。","et":"拉丁语 sublimare（举高），来自 sublimis（崇高的）。同族：sublime。","ex":[["Cette robe sublime sa silhouette.","这条裙子凸显她的身材。"],["Ce plat sublime les produits de saison.","这道菜把时令食材的优点发挥到极致。"],["Il a sublimé sa colère en écrivant.","他通过写作把愤怒升华了。"]],"co":[["sublimer un visage / une silhouette","凸显容貌 / 身材"],["sublimer un plat","让一道菜更出色"],["sublimer ses émotions","升华情绪"],["la sublimation","升华"]],"sy":[["mettre en valeur","courant","突出优点，最日常"],["magnifier","soutenu","使壮丽、美化"],["embellir","courant","使更美"]],"fq":"中低频，常见于美食、时尚、心理学语境。","me":"sublime + -r：让东西变得「sublime」。","tr":{"zh":"这个酱汁把鱼的味道衬托得更好。","fr":"Cette sauce sublime le goût du poisson.","alt":"Cette sauce met bien le poisson en valeur.","note":"sublimer qc：宾语是被衬托的东西。"}},
 "Tarder à": {"pos":"v.i. 动词，第一组 -er，助动词 avoir；tarder à + 动词原形","s":"tarder à + 动词 = 迟迟不做、拖了很久才；il me tarde de + 动词 = 我迫不及待想……；sans tarder = 马上。","ipa":"[taʁ.de]","ph":"tar [taʁ]；der [de]；à 读 [a]。","pi":"后面接 à + 动词原形，别漏掉 à。il me tarde de 里用 de，不是 à。别和 retarder（推迟）混淆：tarder 是自己迟了，retarder 是把某事推迟。","et":"拉丁语 tardare，来自 tardus（慢的）。同族：tard, tardif, retard。","ex":[["Le train tarde à arriver.","火车迟迟未到。"],["Il me tarde de te revoir.","我迫不及待想再见到你。"],["Les résultats ne vont pas tarder.","结果很快就会出来。"]],"co":[["tarder à répondre","迟迟不回复"],["ne pas tarder à + inf.","很快就会……"],["il me tarde de + inf.","我迫不及待想……"],["sans tarder","立刻"]],"sy":[["mettre du temps à","courant","花了很长时间才……"],["traîner","familier","拖拖拉拉"],["être en retard","courant","迟到、晚了"]],"fq":"中频，日常和书面都会用。","me":"tarder ← tard：「变晚」而一直没发生。","tr":{"zh":"他迟迟没有回我的信息。","fr":"Il tarde à répondre à mon message.","alt":"Il met du temps à répondre à mon message.","note":"tarder à + 动词原形；répondre à qn / à qc。"}},
 "Toucher": {"pos":"v.t./v.i. 动词，第一组 -er，助动词 avoir","s":"碰、摸；触动（感动）；领取（工资、钱）；联系上。toucher à = 动、碰（Ne touche pas à ça）。","ipa":"[tu.ʃe]","ph":"ou [u]；ch [ʃ]；-er 读 [e]。","pi":"ch 读 [ʃ]，像「西」口型加圆唇，不是汉语 ch。toucher qc（碰到）和 toucher à qc（去动）意思不同。","et":"古法语 touchier，可能来自拟声的俗拉丁语 *toccare（敲击声）。同族：touche, toucher（名词，触觉）。","ex":[["Ce film m'a touché.","这部电影触动了我。"],["Ne touche pas ça, c'est chaud !","别碰这个，很烫！"],["Il touche un bon salaire.","他拿着不错的工资。"]],"co":[["toucher quelqu'un (ému)","感动某人"],["toucher à","动、碰"],["toucher un salaire","领工资"],["toucher du bois","敲敲木头（求好运）"]],"sy":[["émouvoir","soutenu","使感动"],["palper","soutenu","触摸、检查"],["percevoir","soutenu","领取、收到（款项）"]],"fq":"极高频，日常常用。","me":"toucher：像手指敲在东西上，也敲到心里。","tr":{"zh":"他的话深深触动了我。","fr":"Ses mots m'ont beaucoup touché.","alt":"Ce qu'il a dit m'a vraiment touché.","note":"toucher qn = 触动某人，不加介词。"}},
 "Tourner (une vidéo, un film)": {"pos":"v.t. 动词，第一组 -er，助动词 avoir","s":"拍摄（电影、视频、一场戏）。tourner 的基本意思是「转动、转弯」：tourner à gauche；Ça tourne 指机器运转或开拍。","ipa":"[tuʁ.ne]","ph":"tour [tuʁ]；ne [ne]；ou [u]。","pi":"tourner 拍摄只用于电影、视频；拍照是 prendre une photo。结尾 -er 的 r 不发音。","et":"拉丁语 tornare（用车床加工），来自 tornus（车床）。同族：tour, tournée, détourner。","ex":[["Ils vont tourner un film dans ma rue.","他们要在我家那条街拍电影。"],["Tourne à droite au feu.","到红绿灯向右转。"],["Silence, on tourne !","安静，开拍了！"]],"co":[["tourner un film / une scène","拍电影 / 一场戏"],["tourner à gauche / à droite","向左 / 向右转"],["tourner en rond","原地打转"],["tourner la page","翻篇"]],"sy":[["filmer","courant","拍摄视频，更口语"],["réaliser","courant","导演（一部片）"],["pivoter","courant","绕轴转动"]],"fq":"极高频，日常常用。","me":"老电影摄影机要「转」手柄：tourner = 转 = 拍。","tr":{"zh":"他们周末在公园里拍了一段视频。","fr":"Ils ont tourné une vidéo dans le parc ce week-end.","alt":"Ils ont filmé une vidéo au parc ce week-end.","note":"拍视频用 tourner une vidéo 或 filmer；拍照不用 tourner。"}},
 "Transmettre": {"pos":"v.t. 动词，第三组，像 mettre 变位，助动词 avoir；过去分词 transmis","s":"传递、转达（消息、知识）；传染（疾病）；传承。se transmettre = 被传播、被传承。","ipa":"[tʁɑ̃s.mɛtʁ]","ph":"trans [tʁɑ̃s]，an 读鼻化 [ɑ̃]，s 要发音；mettre [mɛtʁ]。","pi":"变位：je transmets, nous transmettons, ils transmettent；过去分词 transmis，结尾 s 不发音。tt 读单个 [t]。","et":"拉丁语 transmittere（trans- 跨越 + mittere 送）。同族：mettre, transmission, émettre。","ex":[["Il veut transmettre son savoir à ses enfants.","他想把知识传给孩子们。"],["Peux-tu transmettre mon message à Paul ?","你能把我的消息转告保罗吗？"],["Ce virus se transmet par l'air.","这种病毒通过空气传播。"]],"co":[["transmettre un message","转达消息"],["transmettre un savoir / une tradition","传承知识 / 传统"],["transmettre une maladie","传染疾病"],["se transmettre de génération en génération","代代相传"]],"sy":[["communiquer","courant","告知、传达"],["léguer","soutenu","遗留、传给后代"],["passer","familier","递给、转告（passe-lui le bonjour）"]],"fq":"高频，日常和书面都常用。","me":"trans（穿过）+ mettre（放）：把东西「送过去」。","tr":{"zh":"请把这封邮件转给你的同事。","fr":"Merci de transmettre ce mail à votre collègue.","alt":"Tu peux passer ce mail à ton collègue ?","note":"transmettre qc à qn。"}},
 "Tricher": {"pos":"v.i. 动词，第一组 -er，助动词 avoir","s":"作弊；耍赖、欺骗（考试、游戏、税务）。tricher sur = 在……上弄虚作假。比 frauder 日常，范围小。","ipa":"[tʁi.ʃe]","ph":"tr [tʁ]；i [i]；ch [ʃ]；-er 读 [e]。","pi":"ch 读 [ʃ]，不是汉语的 ch 或 [tʃ]。结尾 -er 的 r 不发音。作弊的人：un tricheur / une tricheuse。","et":"古法语 trichier。同族：tricherie, tricheur。与英语 trick 可能有关。","ex":[["Il est interdit de tricher pendant l'examen.","考试期间禁止作弊。"],["Il triche toujours aux cartes.","他打牌总是作弊。"],["Tu as triché ! Je t'ai vu !","你作弊了！我看见了！"]],"co":[["tricher à un examen","考试作弊"],["tricher aux cartes","打牌作弊"],["tricher sur son âge","谎报年龄"],["un tricheur / une tricheuse","作弊者"]],"sy":[["frauder","courant","欺诈，指税务、票务"],["copier","courant","抄袭，学校里"],["tromper","courant","欺骗人"]],"fq":"中高频，日常常用。","me":"tri-cher：像「变戏法」的人，规则里偷偷动手脚。","tr":{"zh":"我弟弟玩游戏总是作弊。","fr":"Mon frère triche toujours aux jeux.","alt":"Mon frère triche tout le temps quand on joue.","note":"tricher à un examen / aux cartes：介词用 à。"}},
 "S'éclater": {"pos":"v. 代词式动词，第一组；复合时态助动词 être","s":"玩得非常尽兴、乐在其中（familier）。s'éclater à + 动词 = 做某事做得很开心。注意：éclater 单独是「爆裂、爆发」。","ipa":"[se.kla.te]","ph":"é [e]；cla [kla]；ter [te]；se 在元音前缩成 s'。","pi":"过去分词要和主语一致：nous nous sommes éclatés。é 开头要读清楚 [e]。别和 éclater（爆炸）搞混。","et":"来自 éclater（爆裂、迸发），加代词 se，字面「自己迸发」。同族：éclat（光彩、碎片）。","ex":[["Hier soir, nous nous sommes éclatés !","昨晚我们玩得太嗨了！"],["Elle s'éclate dans son nouveau travail.","她在新工作里干得很起劲。"],["Je m'éclate à danser avec mes amis.","我和朋友一起跳舞，玩得很开心。"]],"co":[["s'éclater à + inf.","做某事做得很爽"],["s'éclater en vacances","度假玩得尽兴"],["on s'est bien éclatés","我们玩得很开心"]],"sy":[["s'amuser","courant","玩得开心，最日常"],["se régaler","familier","尽情享受"],["kiffer","argot","非常喜欢"]],"fq":"中高频，年轻人和口语里常用。","me":"开心到整个人「爆开」（éclater）了。","tr":{"zh":"周末我们在音乐节上玩得特别开心。","fr":"Ce week-end, on s'est éclatés au festival de musique.","alt":"Ce week-end, on s'est bien amusés au festival.","note":"on 是口语里的「我们」，过去分词仍写 éclatés。"}},
 "Se débarrasser de": {"pos":"v. 代词式动词，第一组；复合时态助动词 être；se débarrasser de + 名词","s":"摆脱、扔掉、处理掉（旧东西、坏习惯、麻烦的人）。不带 se 的 débarrasser la table = 收拾桌子。","ipa":"[sə de.ba.ʁa.se]","ph":"dé [de]；bar [ba]；ras [ʁa]；ser [se]。rr 是单个 [ʁ]。","pi":"后面必须有介词 de。过去分词要和主语一致：elle s'est débarrassée de。变位：je me débarrasse。","et":"dé-（去除）+ barrasser，与 embarrasser 同族，词根来自 barre（横木）。","ex":[["Je veux me débarrasser de ces vieux vêtements.","我想扔掉这些旧衣服。"],["Il s'est débarrassé de sa vieille voiture.","他把旧车处理掉了。"],["J'ai du mal à me débarrasser de cette habitude.","我很难改掉这个习惯。"]],"co":[["se débarrasser de ses vieux vêtements","扔掉旧衣服"],["se débarrasser d'un problème","摆脱问题"],["se débarrasser d'une habitude","改掉习惯"],["débarrasser la table","收拾餐桌"]],"sy":[["jeter","courant","扔掉"],["se défaire de","soutenu","摆脱、放弃"],["balancer","familier","随手扔掉"]],"fq":"高频，日常常用。","me":"dé-（去掉）+ barre：把挡路的东西移开。","tr":{"zh":"我们得扔掉这些没用的东西。","fr":"Nous devons nous débarrasser de ces choses inutiles.","alt":"Il faut qu'on balance ces trucs inutiles.","note":"devoir + 代词式动词：nous devons nous débarrasser。"}},
 "Se glisser dans": {"pos":"v. 代词式动词，第一组；复合时态助动词 être；se glisser dans + 名词","s":"悄悄钻进、溜进、挤进（床、人群、车里、对话）。也可以指想法、错误「悄悄混进来」：un doute s'est glissé dans mon esprit。","ipa":"[sə ɡli.se dɑ̃]","ph":"gl [ɡl]；i [i]；ss [s]；dans 读鼻化 [dɑ̃]，s 不发音。","pi":"过去分词要和主语一致：elle s'est glissée dans。dans 的 s 不发音。","et":"来源不确定。同族：glisser, glissant, glissade, glissière。","ex":[["Le chat s'est glissé dans la boîte.","猫钻进了盒子里。"],["Il s'est glissé dans la salle sans faire de bruit.","他悄悄溜进了房间。"],["Glisse-toi dans la voiture, vite !","快钻进车里！"]],"co":[["se glisser dans un lit / sous les draps","钻进被窝"],["se glisser dans la foule","挤进人群"],["se glisser dans la conversation","插进谈话"],["un doute s'est glissé dans mon esprit","我心里起了疑虑"]],"sy":[["se faufiler","courant","从缝隙中挤过去"],["s'introduire dans","soutenu","潜入、进入"],["se couler","littéraire","悄悄溜进"]],"fq":"中频，描写动作时常用。","me":"glisser = 滑；像一条滑溜的鱼钻进去。","tr":{"zh":"孩子悄悄钻进了被窝。","fr":"L'enfant s'est glissé sous la couette sans bruit.","alt":"L'enfant s'est glissé dans le lit sans faire de bruit.","note":"se glisser sous = 钻到……下面；se glisser dans = 钻到……里面。"}},
 "Se plonger dans": {"pos":"v. 代词式动词，第一组；复合时态助动词 être；se plonger dans + 名词","s":"沉浸于、一头扎进（书、工作、回忆）；也可指跳进水里。plonger 本身是「潜入、跳水」。","ipa":"[sə plɔ̃.ʒe dɑ̃]","ph":"pl [pl]；on 读鼻化 [ɔ̃]；g 在 e 前读 [ʒ]；-er 读 [e]。","pi":"nous nous plongeons，g 后加 e 保持 [ʒ] 音。过去分词要和主语一致：elle s'est plongée dans。别漏掉介词 dans。","et":"来自俗拉丁语 *plumbicare，源自 plumbum（铅），字面「像铅一样沉下去」。","ex":[["Il aime se plonger dans un bon livre.","他喜欢沉浸在一本好书中。"],["Elle s'est plongée dans le travail.","她一头扎进了工作里。"],["Je me plonge dans mes révisions.","我正埋头复习。"]],"co":[["se plonger dans un livre","沉浸在书里"],["se plonger dans le travail","埋头工作"],["se plonger dans ses pensées","陷入沉思"],["plonger dans l'eau","跳进水里"]],"sy":[["s'immerger dans","soutenu","沉浸于"],["s'absorber dans","soutenu","全神贯注于"],["se noyer dans","courant","淹没在（工作里）"]],"fq":"中高频，日常和书面都常见。","me":"plonger ← 铅：像铅块一样沉进去。","tr":{"zh":"周末我喜欢沉浸在一部好小说里。","fr":"Le week-end, j'aime me plonger dans un bon roman.","alt":"Le week-end, j'adore lire un bon roman sans m'arrêter.","note":"aimer + 代词式动词原形：me 随主语变（j'aime me plonger）。"}},
 "Se tenir": {"pos":"v. 代词式动词，第三组（像 tenir）；复合时态助动词 être；过去分词 tenu","s":"（活动）举行：Le festival se tient en août；站着、保持某姿势：se tenir droit；表现、举止：se tenir bien / mal；se tenir à = 抓住。","ipa":"[sə tə.niʁ]","ph":"se [sə]；te [tə]；nir [niʁ]。变位 il se tient 读 [il sə tjɛ̃]。","pi":"将来时 il se tiendra，不是 se tienra。变位：je me tiens, nous nous tenons, ils se tiennent。复合时态：le festival s'est tenu。","et":"拉丁语 tenere（握、持）。同族：tenir, maintenir, retenir, contenir。","ex":[["Le festival se tiendra du 5 au 7 août.","音乐节将在八月五日至七日举行。"],["Tiens-toi droit !","站直了！"],["La réunion s'est tenue à la mairie.","会议在市政厅举行。"]],"co":[["se tenir droit / debout","站直 / 站着"],["se tenir bien / mal","举止得体 / 不得体"],["se tenir au courant","随时了解情况"],["se tenir à la rampe","抓紧扶手"]],"sy":[["avoir lieu","courant","举行，最日常"],["se dérouler","courant","（过程）进行、展开"],["se comporter","courant","表现、举止"]],"fq":"高频，新闻和日常常用。","me":"se tenir = 让自己「站住、撑住」，活动也「站得住」，就是举行。","tr":{"zh":"会议将在下周二举行。","fr":"La réunion se tiendra mardi prochain.","alt":"La réunion aura lieu mardi prochain.","note":"指活动举行时，主语是事件，用第三人称。"}},
 "Abîmé(e)": {"pos":"adj. 形容词，阴性 abîmée，复数 abîmés / abîmées","s":"损坏的、磨坏的、受伤的（书、水果、衣服、头发、皮肤）。是动词 abîmer（弄坏）的过去分词，作形容词用，比 cassé（断了）更偏向「变旧、受损」。","ipa":"[a.bi.me]","ph":"a [a]；î 读 [i]（长音符只是拼写）；mé [me]。","pi":"î 上的符号不改变发音；阴性 abîmée 读音相同。形容词要和名词性数一致。","et":"来自 abîmer，源自 abîme（深渊），拉丁语 abyssus，希腊语 ábyssos「无底的」。","ex":[["Ce livre est très abîmé.","这本书损坏得很厉害。"],["Les pommes sont abîmées, je ne les achète pas.","这些苹果有磕伤，我不买。"],["Elle a les cheveux abîmés par le soleil.","她的头发被太阳晒坏了。"]],"co":[["un livre / un fruit abîmé","旧损的书 / 有磕伤的水果"],["des cheveux abîmés","受损的头发"],["s'abîmer les yeux","伤眼睛"]],"sy":[["endommagé","soutenu","受损，更正式"],["usé","courant","用旧了"],["cassé","courant","断了、坏了"]],"fq":"高频，日常常用。","me":"abîme（深渊）：东西掉进深渊就「坏」了。","tr":{"zh":"这件外套已经穿旧了。","fr":"Ce manteau est déjà très abîmé.","alt":"Ce manteau est tout abîmé.","note":"abîmé 作表语时和名词一致：une veste abîmée。"}},
 "Alimentaire": {"pos":"adj. 形容词，阴阳同形，复数 alimentaires","s":"与食物、饮食有关的。équilibre alimentaire = 饮食均衡；industrie alimentaire = 食品工业。pension alimentaire = 赡养费 / 抚养费（和吃的无关）。","ipa":"[a.li.mɑ̃.tɛʁ]","ph":"a [a]；li [li]；men 读鼻化 [mɑ̃]；taire 读 [tɛʁ]。","pi":"阴性和阳性拼写一样：un régime alimentaire, une allergie alimentaire。ai 读 [ɛ]。","et":"拉丁语 alimentarius，来自 alimentum（食物）。同族：aliment, alimentation, alimenter。","ex":[["Il faut faire attention à son équilibre alimentaire.","要注意饮食均衡。"],["Elle a une allergie alimentaire.","她有食物过敏。"],["Cette entreprise travaille dans l'industrie alimentaire.","这家公司从事食品行业。"]],"co":[["un régime alimentaire","饮食习惯 / 饮食方案"],["l'industrie alimentaire","食品工业"],["une allergie alimentaire","食物过敏"],["une pension alimentaire","赡养费"]],"sy":[["nutritionnel","courant","营养方面的"],["culinaire","courant","烹饪方面的"]],"fq":"中高频，健康和新闻里常见。","me":"aliment（食物）+ -aire：和「吃」有关的。","tr":{"zh":"医生建议他改变饮食习惯。","fr":"Le médecin lui conseille de changer ses habitudes alimentaires.","alt":"Le docteur lui dit de manger autrement.","note":"alimentaire 放在名词后，复数加 s。"}},
 "Avisé(e)": {"pos":"adj. 形容词，阴性 avisée，复数 avisés / avisées","s":"明智的、有见识的、深思熟虑的。un choix avisé = 明智的选择。反义：mal avisé = 欠考虑的（Tu serais mal avisé de + 动词）。偏书面。","ipa":"[a.vi.ze]","ph":"a [a]；vi [vi]；sé [ze]。s 在元音间读 [z]。","pi":"s 读 [z]；阴性 avisée 读音不变。注意它不是「被通知」的意思，那是 informé。","et":"来自 aviser，源自 avis（意见、看法）。同族：avis, aviser, s'aviser de。","ex":[["C'est un choix très avisé.","这是一个很明智的选择。"],["Elle est avisée, elle a tout prévu.","她很有头脑，什么都预料到了。"],["Tu serais mal avisé de refuser.","你要是拒绝就太欠考虑了。"]],"co":[["un choix avisé","明智的选择"],["bien avisé / mal avisé","明智的 / 欠考虑的"],["un conseiller avisé","经验丰富的顾问"]],"sy":[["sage","courant","明智、稳重"],["judicieux","soutenu","恰当、明智（指做法）"],["prudent","courant","谨慎"]],"fq":"中低频，书面和较正式的语境。","me":"a-vis-é：有自己的 avis（看法），所以明智。","tr":{"zh":"她是个很有见识的投资者。","fr":"C'est une investisseuse très avisée.","alt":"Elle sait très bien investir.","note":"avisé 随名词性数变化：une investisseuse avisée。"}},
 "Cabossé(e)": {"pos":"adj. 形容词，阴性 cabossée，复数 cabossés / cabossées","s":"凹陷的、凹凸不平的、被撞坏的（车、锅、金属物）。多指金属物件因碰撞凹进去，口语很常用。","ipa":"[ka.bɔ.se]","ph":"ca [ka]；bos 读 [bɔ]；sé [se]。ss 读 [s]。","pi":"o 读开口 [ɔ]，不是 [o]；ss 读 [s]，不是 [z]。阴性 cabossée 读音相同。","et":"与 bosse（凸起、肿块）同族，可能与 caboche（脑袋）有关；来源不太确定。","ex":[["Ma voiture est toute cabossée après l'accident.","事故后我的车到处是凹痕。"],["Il a une vieille casserole cabossée.","他有一口旧的、凹了的锅。"],["La portière est un peu cabossée.","车门有一点凹陷。"]],"co":[["une voiture cabossée","凹了的车"],["une casserole cabossée","凹了的锅"],["cabosser","把……撞凹"]],"sy":[["bosselé","courant","凹凸不平的"],["cassé","courant","坏了，不限于凹陷"],["défoncé","familier","被撞烂的；破损的"]],"fq":"中频，口语里描述车和器具时常用。","me":"bosse（凸起）：车身上全是「包」和凹坑。","tr":{"zh":"我的自行车被撞凹了。","fr":"Mon vélo est tout cabossé.","alt":"Mon vélo a pris un sacré coup, il est tout cabossé.","note":"tout 修饰形容词，表示「完全」。"}},
 "Chic": {"pos":"adj. 形容词，阴阳同形；复数多写 chics","s":"时髦的、优雅的、得体的。也可以指人「体贴大方」：C'est chic de ta part = 你真周到。也可作名词 le chic = 优雅。","ipa":"[ʃik]","ph":"ch [ʃ]；i [i]；c 在词尾读 [k]。","pi":"c 在词尾要发音 [k]；ch 读 [ʃ]，像「西」。阴阳同形：une robe chic, un costume chic。","et":"来源不确定，可能来自德语 Schick（技巧、风雅）。","ex":[["Elle porte une robe très chic.","她穿一条很时髦的裙子。"],["C'est un restaurant chic.","这是一家很高档的餐厅。"],["C'est chic de ta part de venir.","你能来真是太体贴了。"]],"co":[["une robe chic","时髦的裙子"],["un quartier chic","高档街区"],["c'est chic de ta part","你真周到"],["chic et décontracté","优雅又随性"]],"sy":[["élégant","courant","优雅"],["classe","familier","有格调"],["stylé","familier","有型"]],"fq":"高频，日常常用。","me":"chic：和英语一样，是「时髦」的代名词。","tr":{"zh":"这家餐厅很高档，你得穿得得体点。","fr":"Ce restaurant est très chic, habille-toi bien.","alt":"C'est un resto chic, mets quelque chose de classe.","note":"chic 不随阴阳变化：un restaurant chic, une robe chic。"}},
 "Cliché(e)": {"pos":"adj. 形容词，阴性 clichée，复数 clichés / clichées","s":"老套的、陈词滥调的。作形容词用比较口语；更常见的是名词 un cliché（陈词滥调；底片，照片）。","ipa":"[kli.ʃe]","ph":"cl [kl]；i [i]；ché [ʃe]。ch 读 [ʃ]。","pi":"ch 读 [ʃ]。阴性 clichée 读音不变。作形容词不如名词常见，需要时也可以说 banal 或 convenu。","et":"来自 clicher（印刷术语，制版），象声词，模仿浇铸时的声音。同族：un cliché（底片；套话）。","ex":[["La fin de ce film est un peu clichée.","这部电影的结尾有点老套。"],["C'est un cliché, mais c'est vrai.","这是句老话，但很对。"],["Son discours est plein de clichés.","他的演讲满是陈词滥调。"]],"co":[["un cliché","套话；刻板印象"],["tomber dans le cliché","落入俗套"],["une histoire clichée","老套的故事"]],"sy":[["banal","courant","平淡无奇"],["convenu","soutenu","老一套的"],["rebattu","littéraire","说烂了的"]],"fq":"中频，评论文章和电影里常见。","me":"和英语 cliché 完全一样。","tr":{"zh":"这个故事太老套了。","fr":"Cette histoire est trop clichée.","alt":"Cette histoire, c'est du déjà-vu.","note":"clichée 是形容词用法，更常说 pleine de clichés。"}},
 "Culinaire": {"pos":"adj. 形容词，阴阳同形，复数 culinaires","s":"烹饪的、与做菜有关的。l'art culinaire = 烹饪艺术；une découverte culinaire = 美食新发现。","ipa":"[ky.li.nɛʁ]","ph":"cu [ky]；li [li]；naire 读 [nɛʁ]。","pi":"u 读 [y]；-aire 读 [ɛʁ]。阴阳同形：un art culinaire, une spécialité culinaire。","et":"拉丁语 culinarius，来自 culina（厨房）。","ex":[["J'ai fait une belle découverte culinaire.","我有了一个很棒的美食发现。"],["Elle suit un cours culinaire le samedi.","她每周六上烹饪课。"],["La France est célèbre pour son art culinaire.","法国以烹饪艺术闻名。"]],"co":[["l'art culinaire","烹饪艺术"],["une spécialité culinaire","特色菜"],["un atelier culinaire","烹饪工作坊"]],"sy":[["gastronomique","soutenu","美食的、美馔的"],["alimentaire","courant","饮食的，不强调烹饪"]],"fq":"中频，美食和旅游语境。","me":"culinaire：和英语 culinary 几乎一样。","tr":{"zh":"这个地区以它的烹饪传统闻名。","fr":"Cette région est connue pour ses traditions culinaires.","alt":"On connaît cette région pour sa cuisine traditionnelle.","note":"culinaire 放在名词后。"}},
 "Divers / Diverses": {"pos":"adj. 形容词，阳性 divers，阴性 diverses；多用复数","s":"各种各样的、不同的。通常在名词前、不带冠词：diverses personnes = 各色人等。faits divers = 社会新闻、小新闻。","ipa":"[di.vɛʁ]","ph":"阳性 divers 读 [di.vɛʁ]，s 不发音；阴性 diverses 读 [di.vɛʁs]，s 发音。","pi":"阳性 divers 的结尾 s 不发音，阴性 diverses 的 s 要读出来。别和 diversité（多样性）混淆拼写。","et":"拉丁语 diversus（不同的）。同族：diversité, divers, diversifier。","ex":[["La journaliste a interrogé diverses personnes.","记者采访了各色人物。"],["Il lit des livres de genres divers.","他读各种类型的书。"],["J'ai plusieurs idées diverses.","我有各种不同的想法。"]],"co":[["diverses personnes / raisons","各种各样的人 / 原因"],["des faits divers","社会新闻"],["frais divers","杂费"],["à divers titres","以不同的名义"]],"sy":[["différents","courant","不同的，最日常"],["variés","courant","多种多样的"],["plusieurs","courant","几个、好几个"]],"fq":"高频，日常和新闻中常用。","me":"divers：像「分叉」的路，有很多条。","tr":{"zh":"他在不同国家做过各种工作。","fr":"Il a fait divers métiers dans plusieurs pays.","alt":"Il a fait plein de métiers différents dans plusieurs pays.","note":"divers 通常放名词前，不带冠词。"}},
 "Écrasant(e)": {"pos":"adj. 形容词，阴性 écrasante，复数 écrasants / écrasantes","s":"压倒性的、沉重的、令人难以承受的。la majorité écrasante = 压倒性多数；une victoire écrasante = 大胜；une chaleur écrasante = 酷热难耐。","ipa":"[e.kʁa.zɑ̃]","ph":"é [e]；cra [kʁa]；s 在元音间读 [z]；an 读鼻化 [ɑ̃]。","pi":"s 读 [z]；结尾 -ant 读 [ɑ̃]，t 不发音；阴性 écrasante 读 [e.kʁa.zɑ̃t]。可放名词前或后：l'écrasante majorité / une majorité écrasante。","et":"écraser 的现在分词作形容词。écraser 来源不确定。同族：écraser, écrasement。","ex":[["L'écrasante majorité des journalistes vivent à Paris.","绝大多数记者住在巴黎。"],["L'équipe a gagné par une victoire écrasante.","球队以压倒性优势获胜。"],["Il fait une chaleur écrasante aujourd'hui.","今天热得让人受不了。"]],"co":[["une majorité écrasante","压倒性多数"],["une victoire écrasante","压倒性胜利"],["une chaleur écrasante","难耐的酷热"],["un poids écrasant","沉重的负担"]],"sy":[["accablant","soutenu","令人难以承受的"],["massif","courant","大规模的、大量的"],["énorme","courant","巨大的"]],"fq":"中频，新闻和评论里常见。","me":"écraser（压扁）+ -ant：像大石头压下来。","tr":{"zh":"他以压倒性优势赢得了选举。","fr":"Il a remporté l'élection avec une majorité écrasante.","alt":"Il a gagné l'élection haut la main.","note":"avec une majorité écrasante：形容词放在名词后。"}},
 "Évolutif": {"pos":"adj. 形容词，阴性 évolutive，复数 évolutifs / évolutives","s":"可扩展的、可演进的、会发展变化的。信息技术里指 scalable：un système évolutif；医学里指病情会发展：une maladie évolutive。","ipa":"[e.vɔ.ly.tif]","ph":"é [e]；vo 读 [vɔ]；lu 读 [ly]；tif [tif]。阴性 évolutive 读 [e.vɔ.ly.tiv]。","pi":"u 读 [y]；阳性结尾 f 要读 [f]，阴性变 v：évolutif → évolutive。","et":"来自 évoluer（拉丁语 evolvere，展开）+ -if。同族：évolution, évoluer。","ex":[["C'est un système évolutif qui s'adapte aux besoins.","这是一个能适应需求的可扩展系统。"],["Le logiciel est évolutif et se met à jour tout seul.","这个软件可扩展，并会自动更新。"],["Cette maladie est évolutive.","这种病会不断发展。"]],"co":[["un système évolutif","可扩展的系统"],["un projet évolutif","可演进的项目"],["une maladie évolutive","进行性疾病"],["un contrat évolutif","可调整的合同"]],"sy":[["modulable","courant","可调整的、灵活组合的"],["flexible","courant","灵活的"],["changeant","courant","多变的"]],"fq":"中频，科技和管理语境常用。","me":"évoluer（进化）+ -if：能一直「进化」的。","tr":{"zh":"我们需要一个可以随公司一起发展的系统。","fr":"Nous avons besoin d'un système évolutif qui grandit avec l'entreprise.","alt":"Il nous faut un système qui puisse évoluer avec l'entreprise.","note":"évolutif 放名词后；阴性 évolutive。"}},
 "Francophone": {"pos":"adj. 形容词，阴阳同形，复数 francophones；也是名词 un/une francophone","s":"说法语的；法语区的。un pays francophone = 说法语的国家；les francophones = 说法语的人。也指法语文化圈（la francophonie）。","ipa":"[fʁɑ̃.kɔ.fɔn]","ph":"fran 读鼻化 [fʁɑ̃]；co 读 [kɔ]；phone 读 [fɔn]。ph 读 [f]。","pi":"ph 读 [f]；o 读开口 [ɔ]。作形容词时阴阳同形：une région francophone。","et":"franco-（法语的）+ -phone（希腊语 phōnē，声音）。同族：francophonie, anglophone, hispanophone。","ex":[["Le Québec est une région francophone.","魁北克是说法语的地区。"],["Il y a beaucoup de pays francophones en Afrique.","非洲有很多说法语的国家。"],["Elle est francophone depuis l'enfance.","她从小就说法语。"]],"co":[["un pays francophone","说法语的国家"],["la francophonie","法语国家共同体 / 法语圈"],["un locuteur francophone","法语使用者"],["la littérature francophone","法语文学"]],"sy":[["français","courant","法国的；不强调说法语"],["anglophone","courant","说英语的（对应词）"]],"fq":"中频，文化和教育语境常见。","me":"franco（法语）+ phone（声音）：发出法语声音的人。","tr":{"zh":"在非洲，有很多说法语的国家。","fr":"En Afrique, il y a beaucoup de pays francophones.","alt":"Beaucoup de pays africains parlent français.","note":"francophone 阴阳同形，复数加 s。"}},
 "Impossible": {"pos":"adj. 形容词，阴阳同形，复数 impossibles","s":"不可能的、办不到的。Il est impossible de + 动词原形 / que + 虚拟式。口语里 C'est impossible ! 也常表示「这不可能！」「真不敢相信！」","ipa":"[ɛ̃.pɔ.sibl]","ph":"im 读鼻化 [ɛ̃]；po 读 [pɔ]；ss 读 [s]；ble 读 [bl]。","pi":"im 读鼻化 [ɛ̃]，不是 [im]；ss 读 [s]。il est impossible que 后面用虚拟式（subjonctif）。","et":"拉丁语 impossibilis（in- 否定 + possibilis）。同族：possible, impossibilité。","ex":[["Il est impossible de terminer ce travail aujourd'hui.","今天不可能完成这项工作。"],["Il est impossible qu'il soit déjà là.","他不可能已经到了。"],["C'est mission impossible !","这是不可能完成的任务！"]],"co":[["il est impossible de + inf.","不可能做……"],["il est impossible que + subj.","不可能……"],["rendre impossible","使不可能"],["mission impossible","不可能完成的任务"]],"sy":[["irréalisable","soutenu","无法实现的"],["infaisable","courant","做不到的"],["inconcevable","soutenu","无法想象的"]],"fq":"极高频，日常常用。","me":"im + possible：「不」+「可能」。","tr":{"zh":"他不可能这么快就到。","fr":"Il est impossible qu'il arrive aussi vite.","alt":"Il ne peut pas arriver aussi vite.","note":"il est impossible que + 虚拟式：arrive 为虚拟式。"}},
 "Insuffisant": {"pos":"adj. 形容词，阴性 insuffisante，复数 insuffisants / insuffisantes","s":"不足的、不够的、不及格的。un salaire insuffisant = 不够的工资；un résultat insuffisant = 成绩不合格。","ipa":"[ɛ̃.sy.fi.zɑ̃]","ph":"in 读鼻化 [ɛ̃]；su 读 [sy]；ffi 读 [fi]；s 在元音间读 [z]；an 读鼻化 [ɑ̃]。","pi":"-sant 中的 s 读 [z]；ff 读单个 [f]。阴性 insuffisante 读 [ɛ̃.sy.fi.zɑ̃t]。","et":"in-（否定）+ suffisant（拉丁语 sufficiens，足够的）。同族：suffire, suffisant, insuffisance。","ex":[["Son salaire est insuffisant pour vivre à Paris.","他的工资不够在巴黎生活。"],["Les preuves sont insuffisantes.","证据不足。"],["Cette note est insuffisante.","这个分数不够及格。"]],"co":[["un salaire insuffisant","不够的工资"],["des preuves insuffisantes","证据不足"],["une quantité insuffisante","数量不足"],["insuffisant pour + inf.","不足以……"]],"sy":[["pas assez","courant","不够，最日常"],["maigre","courant","微薄的"],["lacunaire","soutenu","有缺漏的"]],"fq":"中高频，书面和日常都常用。","me":"in + suffisant：不「足」。","tr":{"zh":"这份工资对一家人来说不够。","fr":"Ce salaire est insuffisant pour une famille.","alt":"Avec ce salaire, on n'a pas assez pour une famille.","note":"insuffisant pour + 名词 / 动词原形。"}},
 "Le/La moindre": {"pos":"adj. 形容词，阴阳同形 moindre，复数 les moindres","s":"最小的；丝毫的、一点点的（常用于否定句：pas le moindre doute）。le moindre bruit = 最小的声响。le moindre mal = 最小的坏处。","ipa":"[mwɛ̃dʁ]","ph":"moin 读 [mwɛ̃]；dre 读 [dʁ]，e 不发音。","pi":"oi 读 [wa]，但 moin 里 oin 读 [wɛ̃]。le moindre 前面要有定冠词，阴性用 la moindre。","et":"拉丁语 minor（较小的）。同族：mineur, minimum, diminuer。","ex":[["Il n'y a pas le moindre doute.","毫无疑问。"],["Le moindre bruit le réveille.","一点点声音都会把他吵醒。"],["Elle s'inquiète à la moindre occasion.","她稍有风吹草动就担心。"]],"co":[["pas le moindre + 名词","一点也没有"],["à la moindre occasion","一有机会"],["le moindre mal","最小的坏处"],["la moindre chose","任何一点小事"]],"sy":[["le plus petit","courant","最小的"],["le moindre","soutenu","一点点的"],["aucun","courant","没有任何（否定句）"]],"fq":"中频，书面和日常对话中常见。","me":"moindre ← minor：「最少」的那一点点。","tr":{"zh":"我对此没有丝毫怀疑。","fr":"Je n'ai pas le moindre doute à ce sujet.","alt":"Je ne doute pas du tout de ça.","note":"pas le moindre 后面直接接名词。"}},
 "Noble": {"pos":"adj. 形容词，阴阳同形，复数 nobles","s":"高尚的、崇高的；贵族的。une noble cause = 崇高的事业；les nobles = 贵族。也指「上等的」：un matériau noble = 优质材料。","ipa":"[nɔbl]","ph":"no 读 [nɔ]；ble 读 [bl]，e 不发音。","pi":"o 读开口 [ɔ]，不是 [o]；结尾 -ble 不要读出弱 e。","et":"拉丁语 nobilis（著名的、高贵的）。同族：noblesse, anoblir。","ex":[["C'est une cause noble à défendre.","这是一个值得捍卫的崇高事业。"],["Il a un geste très noble.","他的举动很高尚。"],["Le bois est un matériau noble.","木头是一种优质材料。"]],"co":[["une noble cause","崇高的事业"],["un geste noble","高尚的举动"],["un matériau noble","优质材料"],["la noblesse","贵族"]],"sy":[["honorable","soutenu","光荣的、可敬的"],["élevé","courant","崇高的"],["généreux","courant","慷慨的"]],"fq":"中频，书面较多。","me":"和英语 noble 一样。","tr":{"zh":"这是一项崇高的事业。","fr":"C'est une noble cause.","alt":"C'est une cause très noble.","note":"noble 可放名词前，也可放后。"}},
 "Officiel / Officielle": {"pos":"adj. 形容词，阳性 officiel，阴性 officielle，复数 officiels / officielles","s":"官方的、正式的。un document officiel = 官方文件；la langue officielle = 官方语言；une visite officielle = 正式访问。","ipa":"[ɔ.fi.sjɛl]","ph":"of 读 [ɔf]；fi 读 [fi]；ciel 读 [sjɛl]。ci 读 [sj]。","pi":"ff 读单个 [f]；ci 读 [sj]。阳性和阴性读音相同：officiel = officielle。","et":"拉丁语 officialis，来自 officium（职责、公务）。同族：office, officier, officiellement。","ex":[["Ce document est officiel.","这份文件是官方的。"],["Le français est une langue officielle du Canada.","法语是加拿大的官方语言之一。"],["La réponse officielle arrivera demain.","正式答复明天到。"]],"co":[["un document officiel","官方文件"],["la langue officielle","官方语言"],["une visite officielle","正式访问"],["c'est officiel","已经正式确定了"]],"sy":[["formel","soutenu","正式的"],["public","courant","公开的、公共的"],["authentique","courant","真实的、经认证的"]],"fq":"高频，新闻和日常常用。","me":"officiel：和 office（办公室）同源，来自「机关」。","tr":{"zh":"官方消息明天公布。","fr":"L'annonce officielle sera faite demain.","alt":"Ce sera annoncé officiellement demain.","note":"annonce 是阴性，所以用 officielle。"}},
 "Participatif": {"pos":"adj. 形容词，阴性 participative，复数 participatifs / participatives","s":"参与式的、大家一起贡献的。le financement participatif = 众筹；la démocratie participative = 参与式民主；un projet participatif = 大家共同参与的项目。","ipa":"[paʁ.ti.si.pa.tif]","ph":"par [paʁ]；ti 读 [ti]；ci 读 [si]；pa [pa]；tif [tif]。","pi":"ti 读 [ti]，ci 读 [si]，不要混。阳性结尾 f 读 [f]，阴性变 v：participative。","et":"来自 participer（拉丁语 participare）+ -if。同族：participation, participant。","ex":[["Le financement participatif a aidé ce projet.","众筹帮助了这个项目。"],["On organise une démocratie participative dans la ville.","城里在推行参与式民主。"],["C'est un jardin participatif.","这是一个大家共同打理的花园。"]],"co":[["le financement participatif","众筹"],["la démocratie participative","参与式民主"],["un jardin participatif","共享花园"],["une plateforme participative","共建平台"]],"sy":[["collaboratif","courant","协作的"],["collectif","courant","集体的"],["citoyen","courant","公民参与的"]],"fq":"中频，新闻和社会话题中常见。","me":"participer + -if：让大家一起「参加」。","tr":{"zh":"这个项目靠众筹完成。","fr":"Ce projet a été réalisé grâce au financement participatif.","alt":"On a fait ce projet avec du crowdfunding.","note":"financement 是阳性，所以用 participatif。"}},
 "Péjoratif / Péjorative": {"pos":"adj. 形容词，阳性 péjoratif，阴性 péjorative，复数 péjoratifs / péjoratives","s":"贬义的、带贬低意味的。un mot péjoratif = 贬义词；un sens péjoratif = 贬义。常见搭配：de manière péjorative / au sens péjoratif。","ipa":"[pe.ʒɔ.ʁa.tif]","ph":"pé [pe]；jo 读 [ʒɔ]；ra 读 [ʁa]；tif [tif]。j 读 [ʒ]。","pi":"j 读 [ʒ]，不是 [dʒ]；o 读开口 [ɔ]；阴性变 v：péjorative。","et":"来自拉丁语 pejorare（使变坏），源自 pejor（更坏）。同族：pire, empirer。","ex":[["Ce terme est souvent utilisé de manière péjorative.","这个词常被用于贬义。"],["Le mot « gamin » n'est pas péjoratif.","gamin 这个词并不带贬义。"],["Elle l'a dit sur un ton péjoratif.","她用贬低的口气说了这句话。"]],"co":[["un mot péjoratif","贬义词"],["au sens péjoratif","在贬义上"],["de manière péjorative","以贬低的方式"],["un terme péjoratif","贬义词语"]],"sy":[["dépréciatif","soutenu","贬低的"],["négatif","courant","负面的"],["mélioratif","soutenu","褒义的（反义）"]],"fq":"中频，语言和写作中常见。","me":"péj-：像 pire（更糟），让词变「更坏」。","tr":{"zh":"这个词在这里是贬义的。","fr":"Ce mot est péjoratif ici.","alt":"Ici, ce mot a un sens péjoratif.","note":"mot 是阳性，所以用 péjoratif。"}},
 "Persuadé(e)": {"pos":"adj. 形容词，阴性 persuadée，复数 persuadés / persuadées","s":"确信的、深信的。être persuadé que + 直陈式 = 深信……；否定或疑问时后面可用虚拟式。persuader qn de qc = 说服某人。","ipa":"[pɛʁ.sɥa.de]","ph":"per 读 [pɛʁ]；sua 读 [sɥa]；dé 读 [de]。","pi":"ua 读 [ɥa]，口型从 [ɥ] 滑向 [a]。persuadé 是「确信」的状态，persuader 才是「说服」的动作。","et":"拉丁语 persuadere（per- 彻底 + suadere 劝说）。同族：persuader, persuasif。","ex":[["Je suis persuadé qu'il dit la vérité.","我确信他说的是真话。"],["Elle est persuadée d'avoir raison.","她深信自己是对的。"],["Je ne suis pas persuadé que ce soit une bonne idée.","我不确定这是个好主意。"]],"co":[["être persuadé que + indicatif","确信……"],["être persuadé de qc","深信某事"],["persuader qn de + inf.","说服某人做……"],["ne pas être persuadé que + subj.","不太相信……"]],"sy":[["convaincu","courant","相信的，最日常"],["sûr","courant","确定的"],["certain","courant","确定的"]],"fq":"中高频，日常和书面都常用。","me":"persuadé = 被说服到「心里认定」了。","tr":{"zh":"我确信她会通过考试。","fr":"Je suis persuadé qu'elle va réussir son examen.","alt":"Je suis sûr qu'elle va réussir son examen.","note":"être persuadé que + 直陈式；说话者是女性时写 persuadée。"}},
 "Poignant(e)": {"pos":"adj. 形容词，阴性 poignante，复数 poignants / poignantes","s":"令人心酸的、揪心的、感人至深的。多用于悲伤而有力的事物：un témoignage poignant, un récit poignant。比 touchant 更强烈。","ipa":"[pwa.ɲɑ̃]","ph":"poi 读 [pwa]；gn 读 [ɲ]；an 读鼻化 [ɑ̃]。","pi":"gn 读 [ɲ]（像「娘」的鼻音），不是 [g]+[n]。oi 读 [wa]。阴性 poignante 读 [pwa.ɲɑ̃t]。","et":"poindre 的现在分词，拉丁语 pungere（刺）。字面「刺痛人的」。同族：poignard（匕首）。","ex":[["Le témoignage de cette femme était poignant.","这位女士的证词令人动容。"],["C'est un film poignant sur la guerre.","这是一部关于战争的催人泪下的电影。"],["Sa lettre est très poignante.","他的信让人揪心。"]],"co":[["un témoignage poignant","令人动容的证词"],["un récit poignant","催人泪下的叙述"],["un moment poignant","揪心的时刻"]],"sy":[["touchant","courant","感人的，较轻"],["bouleversant","courant","令人震撼的"],["pathétique","soutenu","悲壮的；注意，不是「可怜」"]],"fq":"中频，新闻和文学评论里常见。","me":"poignant ← 刺：一根针扎进心里。","tr":{"zh":"这个故事让我深深感动。","fr":"Cette histoire est vraiment poignante.","alt":"Cette histoire m'a profondément touché.","note":"poignant 随名词性数变化。"}},
 "Prépondérant": {"pos":"adj. 形容词，阴性 prépondérante，复数 prépondérants / prépondérantes","s":"占主导地位的、起决定性作用的。jouer un rôle prépondérant = 起主导作用。偏书面、正式。","ipa":"[pʁe.pɔ̃.de.ʁɑ̃]","ph":"pré [pʁe]；pon 读鼻化 [pɔ̃]；dé [de]；rant 读 [ʁɑ̃]。","pi":"有两个 é，分别读 [e]。on 读 [ɔ̃]。阴性 prépondérante 读 [pʁe.pɔ̃.de.ʁɑ̃t]。","et":"拉丁语 praeponderare（压过、更重），来自 pondus（重量）。同族：pondérer, prépondérance。","ex":[["Il a joué un rôle prépondérant dans cette victoire.","他在这次胜利中发挥了主导作用。"],["Le facteur prépondérant est le prix.","决定性的因素是价格。"],["Les femmes ont une place prépondérante dans cette équipe.","女性在这个团队中占主导地位。"]],"co":[["un rôle prépondérant","主导作用"],["un facteur prépondérant","决定性因素"],["une place prépondérante","主导地位"],["avoir une voix prépondérante","有决定性一票"]],"sy":[["dominant","courant","占优势的"],["essentiel","courant","最重要的"],["déterminant","soutenu","起决定作用的"]],"fq":"中低频，偏书面。","me":"pré- + pondérer：「重量」压过其他。","tr":{"zh":"价格是决定性的因素。","fr":"Le prix est le facteur prépondérant.","alt":"C'est surtout le prix qui compte.","note":"facteur 是阳性，所以用 prépondérant。"}},
 "Présentable": {"pos":"adj. 形容词，阴阳同形，复数 présentables","s":"拿得出手的、得体的、能见人的。être présentable = 穿着打扮得体、可以见人。也指东西「能拿得出手」：un travail présentable。","ipa":"[pʁe.zɑ̃.tabl]","ph":"pré [pʁe]；sen 读鼻化 [zɑ̃]；s 在元音间读 [z]；ta 读 [ta]；ble 读 [bl]。","pi":"sen 里的 s 读 [z]；en 读 [ɑ̃]。结尾 -able 读 [abl]。阴阳同形。","et":"présenter + -able。présenter 来自拉丁语 praesentare。同族：présentation, présenter。","ex":[["Tu dois être présentable pour cet entretien.","这次面试你要穿得得体。"],["Ce rapport est présentable.","这份报告拿得出手。"],["Je ne suis pas présentable, je viens de me réveiller.","我现在没法见人，刚起床。"]],"co":[["être présentable","得体、能见人"],["un dossier présentable","拿得出手的材料"],["rendre présentable","收拾得体面"],["pas présentable","没法见人"]],"sy":[["correct","courant","还过得去的"],["convenable","courant","得体的"],["soigné","courant","整洁的"]],"fq":"中频，日常常用。","me":"présenter + able：能被「呈现」出去。","tr":{"zh":"我得先收拾一下才能见客人。","fr":"Je dois me rendre présentable avant de voir les invités.","alt":"Je dois m'arranger un peu avant que les invités arrivent.","note":"se rendre + 形容词：把自己弄成……。"}},
 "Remarquable": {"pos":"adj. 形容词，阴阳同形，复数 remarquables","s":"出色的、杰出的、值得注意的。un travail remarquable = 出色的工作；une remarquable performance。和 remarqué（被注意到）不同。","ipa":"[ʁə.maʁ.kabl]","ph":"re [ʁə]；mar [maʁ]；qua 读 [ka]；ble 读 [bl]。qu 读 [k]。","pi":"qu 读 [k]，不是 [kw]。结尾 -able 读 [abl]。阴阳同形。","et":"remarquer + -able。remarquer 由 re- 与 marquer 构成，marquer 来自日耳曼语。","ex":[["Il produit un travail remarquable.","他的工作成果出色。"],["C'est une femme remarquable.","她是一位杰出的女性。"],["Ce résultat est remarquable.","这个结果很了不起。"]],"co":[["un travail remarquable","出色的工作"],["un résultat remarquable","了不起的结果"],["une personne remarquable","杰出的人"],["remarquablement bien","出奇地好"]],"sy":[["exceptionnel","courant","非凡的"],["extraordinaire","courant","非同寻常的"],["notable","soutenu","值得一提的"]],"fq":"高频，日常和书面都常用。","me":"re-marquer + able：值得被「标记」的。","tr":{"zh":"他的演讲非常出色。","fr":"Son discours était vraiment remarquable.","alt":"Son discours était excellent.","note":"remarquable 阴阳同形。"}},
 "Créole": {"pos":"adj. 形容词，阴阳同形，复数 créoles；也是名词","s":"克里奥尔的：指带有加勒比、印度洋等地混合文化的。la cuisine créole = 克里奥尔菜；le créole = 克里奥尔语（语言）；un Créole = 克里奥尔人。作人和语言名词时首字母大写。","ipa":"[kʁe.ɔl]","ph":"cré 读 [kʁe]；o 读 [ɔ]；le 读 [l]。é 和 o 分成两个音节。","pi":"é-o 分开读，不要连成一个音。形容词放名词后，小写：la cuisine créole。","et":"来自西班牙语 criollo / 葡萄牙语 crioulo，指在殖民地出生的人。","ex":[["J'adore la cuisine créole.","我喜欢克里奥尔菜。"],["Ils parlent créole à la maison.","他们在家里说克里奥尔语。"],["Elle chante une chanson créole.","她唱了一首克里奥尔歌。"]],"co":[["la cuisine créole","克里奥尔菜"],["le créole haïtien","海地克里奥尔语"],["une chanson créole","克里奥尔歌曲"],["parler créole","说克里奥尔语"]],"sy":[["antillais","courant","安的列斯的"],["métissé","courant","混合的（文化）"]],"fq":"中低频，文化和美食语境。","me":"créole：像「克里奥」+ 乐曲，听起来像加勒比海。","tr":{"zh":"我们昨晚吃了克里奥尔菜。","fr":"Hier soir, nous avons mangé de la cuisine créole.","alt":"Hier soir, on a mangé créole.","note":"manger de la cuisine créole：de la 表示部分量。"}},
 "Favori / Favorite": {"pos":"adj. 形容词，阳性 favori，阴性 favorite，复数 favoris / favorites","s":"最喜欢的、心爱的。mon livre favori = 我最喜欢的书。名词 le favori = 夺冠热门。日常里更常说 préféré。","ipa":"[fa.vɔ.ʁi]","ph":"fa [fa]；vo 读 [vɔ]；ri 读 [ʁi]。阴性 favorite 读 [fa.vɔ.ʁit]，t 要发音。","pi":"阳性结尾 i 读 [i]，阴性 favorite 的 t 要读出来。o 读开口 [ɔ]。","et":"来自意大利语 favorito，源自 favore（偏爱）。同族：faveur, favoriser, défavorable。","ex":[["C'est mon livre favori.","这是我最喜欢的书。"],["Quelle est ta couleur favorite ?","你最喜欢什么颜色？"],["Cette équipe est la grande favorite.","这支队伍是夺冠大热门。"]],"co":[["mon livre / ma chanson favorite","我最喜欢的书 / 歌"],["la couleur favorite","最喜欢的颜色"],["le grand favori","夺冠热门"],["un plat favori","最爱的菜"]],"sy":[["préféré","courant","最喜欢的，更日常"],["chouchou","familier","宠儿"]],"fq":"中高频，日常常用。","me":"favori ← 偏爱（faveur）：你偏爱的那个。","tr":{"zh":"这是我最喜欢的咖啡馆。","fr":"C'est mon café favori.","alt":"C'est mon café préféré.","note":"café 阳性，用 favori；阴性名词用 favorite。"}},
 "Gourmand(e)": {"pos":"adj. 形容词，阴性 gourmande，复数 gourmands / gourmandes；也是名词","s":"爱吃好东西的、嘴馋的（常常爱甜食）。不一定是「贪吃」的贬义：Je suis gourmand 是说自己爱美食。gourmandise = 嘴馋；也指小零食、甜点。","ipa":"[guʁ.mɑ̃]","ph":"gour 读 [guʁ]；mand 读鼻化 [mɑ̃]，d 不发音。阴性 gourmande 读 [guʁ.mɑ̃d]，d 要发音。","pi":"阳性 d 不发音，阴性 d 发音。别和 gourmet（美食家）混淆：gourmet 懂品味，gourmand 爱吃。","et":"古法语 gormant；来源不确定。同族：gourmandise。","ex":[["Je suis très gourmand, j'adore le chocolat.","我很嘴馋，爱巧克力。"],["Elle est gourmande de desserts.","她特别爱吃甜点。"],["C'est une pâtisserie gourmande.","这是一款让人垂涎的点心。"]],"co":[["être gourmand de + 名词","爱吃……"],["une pause gourmande","吃点心的休息时间"],["un dessert gourmand","诱人的甜点"],["la gourmandise","嘴馋；甜点"]],"sy":[["friand","soutenu","爱吃（某物）"],["gourmet","courant","美食家，懂品味"],["glouton","courant","狼吞虎咽、贪吃"]],"fq":"中高频，日常和美食语境常用。","me":"gourmand：想一想法语里「口水」直流的样子。","tr":{"zh":"我妹妹很爱吃甜食。","fr":"Ma sœur est très gourmande de sucreries.","alt":"Ma sœur adore tout ce qui est sucré.","note":"sœur 是阴性，用 gourmande。"}},
 "Habitué(e)": {"pos":"adj. 形容词，阴性 habituée，复数 habitués / habituées；也是名词 un habitué","s":"习惯了的：être habitué à + 名词 / 动词原形 = 习惯于……；作名词 un habitué / une habituée = 常客、老主顾。","ipa":"[a.bi.tɥe]","ph":"h 不发音；a [a]；bi [bi]；tué 读 [tɥe]。","pi":"h 不发音；ué 读 [ɥe]。阴性 habituée 读音相同。习惯于做某事用 être habitué à + 动词原形。","et":"habituer 的过去分词，拉丁语 habituari，来自 habitus（样子、习惯）。同族：habitude, habituel。","ex":[["Je suis un habitué de ce café.","我是这家咖啡馆的常客。"],["Elle est habituée à se lever tôt.","她习惯早起。"],["Il est habitué au froid.","他习惯了寒冷。"]],"co":[["être habitué à + inf.","习惯于做……"],["un habitué de + lieu","某地的常客"],["un client habitué","老顾客"],["comme d'habitude","像往常一样"]],"sy":[["accoutumé","soutenu","习惯了"],["familier","courant","熟悉的"],["fidèle","courant","忠实的，常客"]],"fq":"高频，日常常用。","me":"habit（习惯）+ ué：已经「成习惯」了。","tr":{"zh":"我已经习惯了这里的天气。","fr":"Je suis habitué au temps d'ici.","alt":"Je me suis habitué au temps d'ici.","note":"être habitué à 表示状态，s'habituer à 表示适应的过程。"}},
 "Certains / Certaines": {"pos":"adj./代词，不定词，阳性复数 certains，阴性复数 certaines","s":"某些、有些。certains + 名词；Certains disent que... = 有些人说……；certains d'entre eux = 他们中的一些人。单数 certain 放名词前才是「某个」：un certain jour。","ipa":"[sɛʁ.tɛ̃]","ph":"阳性 certains 读 [sɛʁ.tɛ̃]，结尾 -ains 读鼻化 [ɛ̃]，s 不发音；阴性 certaines 读 [sɛʁ.tɛn]。","pi":"阳性读鼻化 [ɛ̃]，阴性变成 [ɛn]，别混。certains 是复数；作形容词放名词后（une victoire certaine）意为「确定的」。","et":"拉丁语 certanus，来自 certus（确定的）。同族：certitude, incertain, certainement。","ex":[["Certains Canadiens parlent français.","有些加拿大人说法语。"],["Certaines personnes n'aiment pas le fromage.","有些人不爱吃奶酪。"],["Certains d'entre eux sont très jeunes.","他们中有些人很年轻。"]],"co":[["certains + 名词","某些……"],["certains d'entre nous","我们中的一些人"],["dans certains cas","在某些情况下"],["à certains moments","在某些时刻"]],"sy":[["quelques","courant","几个，数量较少"],["plusieurs","courant","好几个"],["quelques-uns","courant","其中几个（代词）"]],"fq":"极高频，日常常用。","me":"certains：和英语 certain 相似，但表示「某些」。","tr":{"zh":"有些人觉得法语很难。","fr":"Certaines personnes trouvent le français difficile.","alt":"Pour certains, le français, c'est difficile.","note":"personnes 是阴性，所以用 certaines。"}},
 "Maintes": {"pos":"adj. 不定形容词，阴性复数 maintes；阳性复数 maints；偏书面","s":"许多的、好几个的。几乎只用在固定说法里：maintes fois / à maintes reprises = 多次。属于书面或较正式的词，口语里更常说 plusieurs fois。","ipa":"[mɛ̃t]","ph":"ain 读鼻化 [ɛ̃]；tes 读 [t]，e 和 s 不发音。","pi":"ain 读 [ɛ̃]，t 读出来，结尾 es 不发音。别和 maintenant（现在）搞混，两者无关。","et":"来源不确定，古法语 maint。","ex":[["Elle me l'a dit à maintes reprises.","她多次对我这么说。"],["Je l'ai vu maintes fois.","我见过他很多次。"],["Maintes personnes pensent la même chose.","许多人都这么想。"]],"co":[["à maintes reprises","多次"],["maintes fois","许多次"],["maintes personnes","许多人"],["en maintes occasions","在许多场合"]],"sy":[["plusieurs","courant","好几个"],["de nombreux","courant","许多的"],["moult","littéraire","许多（文雅或戏谑）"]],"fq":"低频，书面，固定搭配。","me":"maintes fois = 「很多次」，当成一整块记。","tr":{"zh":"我已经提醒过你好几次了。","fr":"Je te l'ai rappelé à maintes reprises.","alt":"Je te l'ai déjà rappelé plusieurs fois.","note":"à maintes reprises：固定短语，reprises 是阴性复数。"}},
 "Quelconque": {"pos":"adj. 形容词，阴阳同形，复数 quelconques","s":"任何一个的、某个（不确定）。une raison quelconque = 随便某个原因。也可以表示「平庸的」：un film quelconque = 一部平庸的电影。","ipa":"[kɛl.kɔ̃k]","ph":"quel 读 [kɛl]；con 读鼻化 [ɔ̃]；que 读 [k]。","pi":"qu 读 [k]；结尾 -que 读 [k]，e 不发音。通常放名词后：une raison quelconque；放名词前时：une quelconque raison，更书面。","et":"拉丁语 qualiscumque（任何一种）。同族：quel, quelque, n'importe quel。","ex":[["Elle n'est pas venue aujourd'hui pour une raison quelconque.","她因为某个原因今天没来。"],["Tu as une idée quelconque ?","你有什么想法吗？"],["C'est un film assez quelconque.","这是一部相当平庸的电影。"]],"co":[["une raison quelconque","某个原因"],["pour une raison quelconque","出于某种原因"],["un moyen quelconque","任何一种方法"],["sans motif quelconque","没有任何理由"]],"sy":[["n'importe quel","courant","任何一个"],["médiocre","courant","平庸的"],["banal","courant","平凡的"]],"fq":"中频，书面和日常都见。","me":"quel + que + conque：「不管哪一个」。","tr":{"zh":"你有什么办法吗？","fr":"Tu as un moyen quelconque de le contacter ?","alt":"Tu as une idée pour le joindre ?","note":"quelconque 放在名词后，与名词一致（复数加 s）。"}},
 "Tel / Telle": {"pos":"adj. 形容词，阴性 telle，复数 tels / telles","s":"这样的；那样的。un tel / une telle + 名词 =「这样的……」，放在名词前。也用于 tel que（像……那样）、tel quel（原样）。","ipa":"[tɛl]","ph":"tel 和 telle 读音相同，都是 [tɛl]；e 读 [ɛ]，结尾 l 要发音。","pi":"阳性 tel 的 l 也要发音；用 un tel 时不要再加 très。注意不要和 tellement（如此地）混用。","et":"来自拉丁语 talis（这样的）。同源：tellement、quel。","ex":[["Je n'ai jamais vu une telle chose !","我从没见过这样的事！"],["Un tel comportement est inacceptable.","这样的行为是不可接受的。"]],"co":[["un tel / une telle + 名词","这样的……"],["tel que","像……那样"],["tel quel","原样；照原来的样子"],["Tel père, tel fils.","有其父必有其子。"]],"sy":[["pareil","courant","相同的、类似的"],["semblable","soutenu","相似的，比 pareil 更书面"]],"fq":"高频，书面和口语都常见。","me":"tel ≈ 英语 such，l 要读出来：tel-l。","tr":{"zh":"我从没见过这么大的房子。","fr":"Je n'ai jamais vu une telle maison.","alt":"Je n'ai jamais vu une maison aussi grande.","note":"une telle + 名词；说「这么大」用 aussi grand 更自然。"}},
 "Différemment": {"pos":"adv. 副词（由 différent 加 -ment 构成）","s":"不同地；用不同的方式。修饰动词，常见 faire / penser / agir différemment。后面可接 de ou que：différemment de moi（和我不同地）。","ipa":"[di.fe.ʁa.mɑ̃]","ph":"-emment 读 [amɑ̃]，不是 [ɛmɑ̃]；différ- 里 e 读 [e]，ff 只读一个 [f]。","pi":"拼写是 différemment（-emment），读音却是 [amɑ̃]；ff 是双写，r 是 [ʁ] 不要卷舌；结尾 -ment 的 -nt 不发音。","et":"来自形容词 différent（拉丁语 differre，「分开、不同」）+ 后缀 -ment。同族：différence、différer。","ex":[["Il faut penser différemment pour trouver une solution.","要换个方式思考才能找到解决办法。"],["Elle s'habille différemment de sa sœur.","她的穿衣风格和她姐姐不一样。"]],"co":[["penser / agir différemment","换个方式想 / 做"],["différemment de","与……不同地"],["faire les choses différemment","用不同的方法做事"]],"sy":[["autrement","courant","用别的方式，更口语、常用"],["pareillement","courant","反义：同样地"]],"fq":"中频，日常和书面都用。","me":"différent + -ment；记住 -emment 读 [amɑ̃]，像 évidemment。","tr":{"zh":"我们得换个方式做这件事。","fr":"Nous devons faire cela différemment.","alt":"On doit faire ça autrement.","note":"副词放在动词后面；口语常用 autrement。"}},
 "Heureusement": {"pos":"adv. 副词","s":"幸好；幸运的是。放在句首或句中，表示说话人庆幸。heureusement que + 从句（口语）= 幸亏……。也可表示「幸福地」，但很少用。","ipa":"[ø.ʁøz.mɑ̃]","ph":"heureux 的 eu 读 [ø]；h 不发音；中间 s 读 [z]；结尾 -ment 读 [mɑ̃]。","pi":"h 不发音；不是 [œ]，是闭口的 [ø]；注意拼写 heureusement，不是 heureuxment。","et":"来自形容词 heureux（由 heur「好运」而来，拉丁语 augurium）+ 后缀 -ment。反义：malheureusement。","ex":[["Heureusement, il n'a pas plu.","幸好没下雨。"],["Heureusement que tu es là !","幸亏你在这里！"],["Heureusement pour lui, le train avait du retard.","他运气好，火车晚点了。"]],"co":[["Heureusement que + 从句","幸亏……"],["heureusement pour toi","你运气好"],["Heureusement, ...","幸好……（句首）"]],"sy":[["par chance","courant","碰巧、幸运地"],["malheureusement","courant","反义：不幸的是"],["fort heureusement","soutenu","非常幸运的是"]],"fq":"极高频，日常常用。","me":"heureux（幸福的）→ heureusement；反过来加 mal- 就是「不幸地」。","tr":{"zh":"幸好我带了伞。","fr":"Heureusement, j'avais un parapluie.","alt":"Heureusement que j'avais pris mon parapluie !","note":"Heureusement que 后面直接接陈述句，不用虚拟式。"}},
 "Pauvrement": {"pos":"adv. 副词","s":"贫穷地；简陋地；贫乏地。vivre pauvrement 是「过穷日子」，être pauvrement vêtu 是「穿得很寒酸」。也可以指内容贫乏。","ipa":"[pov.ʁə.mɑ̃]","ph":"au 读 [o]；pauvre 的结尾 -vre 读 [vʁ]；e 在 -ment 前常轻读或弱化；-ment 读 [mɑ̃]。","pi":"pau- 读 [po]，不是 [pau]；中间的 e 很轻；-ment 里 n 和 t 不发音，只剩鼻化元音。","et":"来自 pauvre（拉丁语 pauper）+ -ment。同族：pauvreté。","ex":[["Ils vivent très pauvrement dans ce village.","他们在这个村子里过得很贫困。"],["Il était pauvrement vêtu.","他穿得很寒酸。"]],"co":[["vivre pauvrement","过贫困的日子"],["pauvrement vêtu","衣着寒酸"],["pauvrement meublé","家具简陋"]],"sy":[["misérablement","soutenu","凄惨地、更悲惨"],["richement","courant","反义：富裕地、华丽地"]],"fq":"低频，多见于书面和描写。","me":"pauvre + ment；au 读 [o]，像 chaud。","tr":{"zh":"这个家庭过得很清贫。","fr":"Cette famille vit très pauvrement.","alt":"Cette famille vit dans la pauvreté.","note":"vivre pauvrement 或 vivre dans la pauvreté 都可以。"}},
 "Quelques-uns / Quelques-unes": {"pos":"pron. 不定代词，阳性 quelques-uns，阴性 quelques-unes","s":"几个；一些（人或物）。单独当代词用，指代前面已出现的复数名词。若前面有 en，用法是 en + 动词 + quelques-uns / quelques-unes。","ipa":"[kɛl.kə.zœ̃] / [kɛl.kə.zyn]","ph":"quelques 的 -es 不发音，但与 uns 之间要联诵，读 [z]；uns 读 [œ̃]，unes 读 [yn]。","pi":"必须联诵 [z]；阳性 uns 读 [œ̃]，阴性 unes 读 [yn]，别搞混；后面不能直接接名词（接名词用 quelques）。","et":"由 quelque（拉丁语 qualis + que）+ un 构成，复数。同族：quelqu'un、quelque chose。","ex":[["J'ai acheté des pommes, tu en veux quelques-unes ?","我买了苹果，你想要几个吗？"],["Beaucoup de livres sont vieux, quelques-uns sont neufs.","很多书都旧了，有几本是新的。"]],"co":[["en + 动词 + quelques-uns","要（其中）几个"],["quelques-uns d'entre nous","我们当中的几个人"],["quelques-unes de mes amies","我的几位女性朋友"]],"sy":[["certains","courant","有些（人）"],["plusieurs","courant","好几个，数量比 quelques 多"]],"fq":"中频，日常常用。","me":"quelques + uns：「几个」里的一，联诵时有个 [z]。","tr":{"zh":"你有书吗？我想借几本。","fr":"Tu as des livres ? Je voudrais en emprunter quelques-uns.","alt":"Tu as des livres ? J'en prendrais bien quelques-uns.","note":"代词 en 指代 livres，quelques-uns 与阳性复数一致。"}},
 "À y réfléchir...": {"pos":"loc. 固定短语（句首插入语）","s":"仔细想想……；再想一想……。说话时改变看法或想起新的想法时用，比如「仔细想想，你是对的」。书面和口语都可以。","ipa":"[a.i.ʁe.fle.ʃiʁ]","ph":"à y 读 [a.i]，两个元音相连；réfléchir 的 é 读 [e]，ch 读 [ʃ]，结尾 -ir 读 [iʁ]。","pi":"réfléchir 里有两个 é 要读 [e]，ch 读 [ʃ]，不是 [k]；结尾 r 要发。","et":"réfléchir 来自拉丁语 reflectere（折回、反射）。y 在这里指代「这件事」。","ex":[["À y réfléchir, je pense que tu as raison.","仔细想想，我觉得你是对的。"],["À y réfléchir, je ne viendrai pas demain.","再想了想，我明天不来了。"]],"co":[["À y réfléchir bien","好好想想"],["Après réflexion,","经过考虑后"],["Tout bien réfléchi,","考虑周全后"]],"sy":[["Après réflexion","courant","经过考虑之后，更常用"],["Tout bien considéré","soutenu","全面考虑后"]],"fq":"中低频，表达改变想法时常用。","me":"À y réfléchir = 「对此想一想」，y 指那件事。","tr":{"zh":"仔细想想，我们应该早点出发。","fr":"À y réfléchir, nous devrions partir plus tôt.","alt":"Réflexion faite, on devrait partir plus tôt.","note":"第一个 à y réfléchir 后用逗号，后面接完整句。"}},
 "Aux petits oignons": {"pos":"loc. 固定短语（口语）","s":"无微不至；安排得十分周到、完美。常说 aux petits oignons，指饭菜精心准备、服务周到。多用在 préparer / soigner / être 之后。","ipa":"[o.pə.ti.zɔ.ɲɔ̃]","ph":"aux 读 [o]；petits 的 -s 与 oignons 联诵，读 [z]；oi 在 oignon 里读 [ɔ]，gn 读 [ɲ]。","pi":"oignon 的 oi 不读 [wa]，读 [ɔ]；gn 读 [ɲ]，像「娘」；联诵 [z]。","et":"来自「小洋葱」做菜的意象，但确切来源不确定。可确定的是：oignon 来自拉丁语 unio。","ex":[["Il nous a préparé un repas aux petits oignons.","他为我们准备了一顿精心的饭菜。"],["Dans cet hôtel, on est soigné aux petits oignons.","在这家酒店，服务无微不至。"]],"co":[["préparer quelque chose aux petits oignons","把某事准备得十分周到"],["être aux petits oignons avec quelqu'un","对某人体贴入微"],["un service aux petits oignons","无可挑剔的服务"]],"sy":[["aux petits soins","courant","照顾得体贴入微"],["parfaitement","courant","完美地"]],"fq":"中频，口语常用，带正面语气。","me":"想像厨师用小洋葱一颗颗精心配菜：细致 = 周到。","tr":{"zh":"她把晚饭准备得无微不至。","fr":"Elle a préparé le dîner aux petits oignons.","alt":"Elle nous a préparé un dîner aux petits oignons.","note":"固定搭配，petits 和 oignons 不变。"}},
 "Avoir plus d'un tour dans son sac": {"pos":"loc. 固定短语（动词性，avoir）","s":"很有办法；有许多招数。夸一个人点子多、不会轻易认输。主语随人变，son 随主语变（mon / ton / son / notre）。","ipa":"[a.vwaʁ.ply.dœ̃.tuʁ.dɑ̃.sɔ̃.sak]","ph":"plus d'un 读 [ply.dœ̃]；tour 读 [tuʁ]，ou 是 [u]；dans son 读 [dɑ̃.sɔ̃]；sac 的 c 要读 [k]。","pi":"plus 在这里读 [ply]，s 不发；sac 结尾的 c 要发 [k]；dans 的鼻化 [ɑ̃] 和 son 的 [ɔ̃] 要分清。","et":"意象是魔术师或艺人袋子里装着很多把戏。确切来源不确定。tour 在这里是「花招、把戏」。","ex":[["Ne t'inquiète pas, il a plus d'un tour dans son sac.","别担心，他有的是办法。"],["Notre chef a plus d'un tour dans son sac.","我们的老板很有办法。"]],"co":[["avoir plus d'un tour dans son sac","很有办法"],["jouer un tour à quelqu'un","捉弄某人"],["un tour de magie","魔术"]],"sy":[["être malin","courant","机灵"],["avoir de la ressource","soutenu","足智多谋"]],"fq":"中频，口语常用，带赞赏。","me":"袋子里不止一个把戏，当然什么难题都能解决。","tr":{"zh":"别担心，我妈妈很有办法。","fr":"Ne t'inquiète pas, ma mère a plus d'un tour dans son sac.","alt":"Pas de souci, ma mère a toujours une solution.","note":"son 要跟主语变：ma mère... son sac。"}},
 "C'est pas la mer à boire": {"pos":"loc. 固定短语（口语，否定省略 ne）","s":"不是什么难事；没那么难。说话时安慰人或让人别夸大困难。完整书面形式是 Ce n'est pas la mer à boire。","ipa":"[sɛ.pa.la.mɛʁ.a.bwaʁ]","ph":"c'est 读 [sɛ]，t 不发；pas 读 [pa]；mer 读 [mɛʁ]；boire 读 [bwaʁ]。","pi":"mer（海）和 mère（母亲）读音一样，都是 [mɛʁ]；口语里省略 ne，写作时要补上。","et":"意象：把整片海都喝光是不可能的，所以这个说法反过来表示「事情没那么难」。","ex":[["Tu dois juste ranger ta chambre, c'est pas la mer à boire !","你只需整理房间，这不难！"],["Ce n'est pas la mer à boire, tu y arriveras.","这不算难，你会做到的。"]],"co":[["Ce n'est pas la mer à boire.","这没那么难。"],["C'est pas la mer à boire !","没多难！（口语）"],["Ce n'est pas la mer à boire, mais...","不算太难，但是……"]],"sy":[["Ce n'est pas compliqué.","courant","不复杂"],["C'est facile.","courant","很容易"]],"fq":"中频，口语里很常用。","me":"没人能喝光大海，所以事情「没那么难」。","tr":{"zh":"你只要打个电话，这不难。","fr":"Tu dois juste téléphoner, c'est pas la mer à boire.","alt":"Tu n'as qu'à téléphoner, ce n'est pas la mer à boire.","note":"口语省略 ne；正式写作用 Ce n'est pas。"}},
 "Ça ne casse pas trois pattes à un canard": {"pos":"loc. 固定短语（口语，否定句）","s":"没什么了不起；平平无奇。形容电影、饭菜、作品等不出彩。几乎总是用否定形式。","ipa":"[sa.nə.kas.pa.tʁwa.pat.a.œ̃.ka.naʁ]","ph":"ça ne 读 [sa.nə]；casse 读 [kas]；trois 读 [tʁwa]；pattes 读 [pat]；canard 读 [ka.naʁ]，结尾 d 不发音。","pi":"canard 的 d 不发音；pattes 的 tt 只读一个 [t]；trois 和 pattes 之间不联诵。","et":"意象：打断三条鸭腿也没什么大不了。确切来源不确定；鸭子只有两条腿，所以说法带点幽默。","ex":[["Ce restaurant est correct, mais ça ne casse pas trois pattes à un canard.","这家餐厅还行，但没什么特别。"],["Son film ne casse pas trois pattes à un canard.","他的电影没什么了不起。"]],"co":[["Ça ne casse pas trois pattes à un canard.","没什么特别。"],["Ça ne casse rien.","没什么出彩（更短的说法）"],["ne pas casser des briques","没什么了不起（同义说法）"]],"sy":[["Ça ne casse rien.","familier","没什么特别（更简短）"],["Rien d'extraordinaire.","courant","没什么特别"]],"fq":"中低频，口语，带幽默。","me":"鸭子都没被吓到，说明东西「没什么威力」。","tr":{"zh":"这部电影还可以，但没什么特别。","fr":"Ce film est bien, mais ça ne casse pas trois pattes à un canard.","alt":"Le film est correct, mais rien d'extraordinaire.","note":"几乎只用否定形式。"}},
 "Être à côté de la plaque": {"pos":"loc. 固定短语（动词性，être）","s":"完全搞错了；答非所问；没抓住重点。口语常用，说别人的回答、猜测或想法离题。","ipa":"[ɛtʁ.a.ko.te.də.la.plak]","ph":"être 读 [ɛtʁ]；côté 读 [ko.te]，ô 是 [o]；plaque 读 [plak]，结尾 -que 读 [k]。","pi":"côté 要写 ô 和 é 两个重音；plaque 的 -que 读 [k]，不读 [kə]。","et":"来源不确定；可能与靶子（plaque）有关，没射中靶心的意思，但这只是常见推测。","ex":[["Ta réponse est complètement à côté de la plaque.","你的回答完全答非所问。"],["Je crois que tu es à côté de la plaque.","我觉得你完全搞错了。"]],"co":[["être complètement à côté de la plaque","完全搞错"],["répondre à côté de la plaque","答非所问"],["Tu es à côté de la plaque.","你说得不对。"]],"sy":[["se tromper","courant","弄错"],["être hors sujet","courant","跑题"]],"fq":"中频，口语常用。","me":"没打中「牌子」，只打到旁边（à côté）。","tr":{"zh":"他的想法完全不对。","fr":"Son idée est complètement à côté de la plaque.","alt":"Il est complètement à côté de la plaque.","note":"可以修饰人，也可以修饰回答或想法。"}},
 "Le comble de": {"pos":"loc. 固定短语，n.m. + de","s":"……的极致；最过分的是……。le comble 是「顶点、极限」，常带讽刺。Le comble, c'est que... =「最荒唐的是……」。","ipa":"[lə.kɔ̃bl.də]","ph":"comble 读 [kɔ̃bl]，om 是鼻化 [ɔ̃]，结尾 -ble 读 [bl]，e 不发音。","pi":"comble 的 m 不单独发音，前面的 o 鼻化；结尾 e 不读。","et":"comble 来自拉丁语 cumulus（堆、堆尖）。同源：combler（填满）。","ex":[["Cette tenue, c'est le comble du chic.","这套装扮是时髦的极致。"],["Le comble, c'est qu'il a oublié son propre anniversaire !","最荒唐的是，他居然忘了自己的生日！"]],"co":[["le comble de l'ironie","讽刺的极致"],["Le comble, c'est que...","最离谱的是……"],["c'est un comble !","这太过分了！"],["être au comble de la joie","高兴到极点"]],"sy":[["le summum de","soutenu","……的顶点"],["le sommet de","courant","……的最高点"]],"fq":"中频，口语和书面都有。","me":"comble = 堆满到顶（cumulus）→ 极致。","tr":{"zh":"最离谱的是，他自己迟到了。","fr":"Le comble, c'est qu'il est arrivé en retard lui-même.","alt":"Le comble, c'est que c'est lui qui est en retard !","note":"Le comble, c'est que + 陈述句。"}},
 "Les mains vides": {"pos":"loc. 固定短语，n.f.pl. + adj.","s":"空手；什么也没带。arriver les mains vides 是「空着手来」。也可以比喻一无所获。","ipa":"[le.mɛ̃.vid]","ph":"les 读 [le]；mains 读 [mɛ̃]，ai 和 n 合成鼻化 [ɛ̃]；vides 读 [vid]，结尾 -es 不发音。","pi":"mains 的 s 不发音；les 与 mains 之间没有联诵；main（手）是阴性名词。","et":"main 来自拉丁语 manus；vide 的词源这里不展开。","ex":[["Il est arrivé à la fête les mains vides.","他空着手来到派对。"],["Ne repars pas les mains vides !","别空着手走！"]],"co":[["arriver les mains vides","空手而来"],["repartir les mains vides","空手而归"],["avoir les mains pleines","反义：两手满满"]],"sy":[["sans rien","courant","什么也没有"],["bredouille","familier","一无所获地（尤其打猎、钓鱼）"]],"fq":"中频，日常常用。","me":"mains + vides：两只手是空的。","tr":{"zh":"我不想空手去朋友家。","fr":"Je ne veux pas aller chez mon ami les mains vides.","alt":"Je ne veux pas arriver chez mon ami les mains vides.","note":"les mains vides 不用介词，直接放在动词后。"}},
 "Les quatre coins du monde": {"pos":"loc. 固定短语，n.m.pl.","s":"世界各地；天涯海角。aux quatre coins du monde 表示「在世界各地」。也说 aux quatre coins de la France。","ipa":"[le.katʁ.kwɛ̃.dy.mɔ̃d]","ph":"quatre 读 [katʁ]；coins 读 [kwɛ̃]，oi 读 [wɛ̃]（这里是 oin）；monde 读 [mɔ̃d]，结尾 e 不发。","pi":"coin 读 [kwɛ̃]，不是 [kɔ̃]；monde 的 on 是鼻化 [ɔ̃]，d 要发。","et":"quatre 来自拉丁语 quattuor；coin 来自拉丁语 cuneus（楔子）。「四个角」是平面地图的意象。","ex":[["Il a voyagé aux quatre coins du monde.","他走遍了世界各地。"],["Des touristes viennent des quatre coins du monde.","游客来自世界各地。"]],"co":[["aux quatre coins du monde","在世界各地"],["aux quatre coins de la ville","在城市的各个角落"],["venir des quatre coins du monde","从世界各地来"]],"sy":[["partout dans le monde","courant","世界各处"],["aux antipodes","soutenu","在地球另一端，更远"]],"fq":"中频，书面和口语都有。","me":"世界像一块方布，有四个角，角角都到过。","tr":{"zh":"这位歌手在世界各地都有粉丝。","fr":"Cette chanteuse a des fans aux quatre coins du monde.","alt":"Cette chanteuse a des fans partout dans le monde.","note":"aux = à + les；用 aux quatre coins。"}},
 "Plus difficile qu'il n'y paraît": {"pos":"loc. 固定短语（比较级结构）","s":"比看起来更难。plus + 形容词 + qu'il n'y paraît 是固定结构，也可替换形容词：plus simple / plus grand qu'il n'y paraît。","ipa":"[ply.di.fi.sil.kil.ni.pa.ʁɛ]","ph":"plus 在这里读 [ply]；difficile 读 [di.fi.sil]；qu'il 读 [kil]；n'y 读 [ni]；paraît 读 [pa.ʁɛ]。","pi":"paraître 的 î 读 [ɛ]，不是 [i]；qu'il n'y 里 n' 是赘词性的 ne，不表示否定。","et":"paraître 来自拉丁语 parescere（显现）。ne 在这里是 ne explétif（虚词），书面常保留。","ex":[["Ce jeu est plus difficile qu'il n'y paraît.","这个游戏比看起来难。"],["C'est plus simple qu'il n'y paraît.","这比看起来简单。"]],"co":[["plus + adj. + qu'il n'y paraît","比看起来更……"],["moins cher qu'il n'y paraît","比看起来便宜"],["Ça paraît facile.","看起来很容易。"]],"sy":[["Ce n'est pas aussi facile qu'on le croit.","courant","没有想像的那么容易"],["plus dur qu'on ne le pense","courant","比想的更难"]],"fq":"中频，口语和书面都有。","me":"paraît = 看起来；qu'il n'y paraît 固定在一起记。","tr":{"zh":"做饭比看起来难。","fr":"Cuisiner est plus difficile qu'il n'y paraît.","alt":"C'est plus dur qu'on ne le croit, la cuisine.","note":"il n'y paraît 里的 ne 不是否定，是虚词 ne。"}},
 "Raconter des salades": {"pos":"loc. 固定短语（动词性，familier）","s":"胡说八道；编瞎话；说假话。多指说谎或夸大。口语，不用在正式场合。","ipa":"[ʁa.kɔ̃.te.de.sa.lad]","ph":"raconter 读 [ʁa.kɔ̃.te]，on 是鼻化 [ɔ̃]，结尾 -er 读 [e]；des 读 [de]；salades 读 [sa.lad]。","pi":"r 是小舌音 [ʁ]；des 与 salades 之间不联诵（s 后面是辅音 s）；salade 在这里不是「沙拉」而是比喻。","et":"salade 来自意大利语，原指一种加调料的菜；比喻「混杂的东西、乱七八糟的话」。具体成语的来源不确定。","ex":[["Arrête de raconter des salades, je sais que tu mens.","别胡扯了，我知道你在撒谎。"],["Il raconte des salades pour nous impressionner.","他编瞎话来给我们留下印象。"]],"co":[["raconter des salades à quelqu'un","对某人胡说"],["arrête de raconter des salades","别瞎扯了"],["Tout ça, ce sont des salades.","这些都是瞎话。"]],"sy":[["mentir","courant","说谎"],["raconter des histoires","familier","编故事、说假话"],["raconter des bobards","familier","编瞎话"]],"fq":"中频，口语里常用。","me":"salade = 一盘混在一起的东西 → 胡话乱七八糟。","tr":{"zh":"别骗我，我才不信！","fr":"Arrête de me raconter des salades, je ne te crois pas !","alt":"Ne me raconte pas de salades !","note":"否定命令句里用 de salades 而不是 des。"}},
 "Un paquet de": {"pos":"loc. 固定短语，n.m. + de","s":"一包；一盒（包装好的）。un paquet de gâteaux / de cigarettes。口语里也可指「一大堆」：un paquet de problèmes。","ipa":"[œ̃.pa.kɛ.də]","ph":"un 读 [œ̃]；paquet 读 [pa.kɛ]，结尾 -et 读 [ɛ]，t 不发音；de 读 [də]。","pi":"paquet 的 t 不发音；un 是鼻化 [œ̃]，不是 [ɔ̃]；de 后接无冠词的名词：un paquet de pâtes。","et":"paquet 与 pack、packet 同源，可能来自荷兰语。来源这里不细说。","ex":[["J'ai acheté un paquet de gâteaux.","我买了一包蛋糕。"],["Il a un paquet de problèmes en ce moment.","他现在一大堆麻烦。"]],"co":[["un paquet de pâtes / de café","一包面 / 咖啡"],["un paquet de cigarettes","一包烟"],["un paquet de + 名词（familier）","一大堆……"],["un paquet-cadeau","礼品包装"]],"sy":[["une boîte de","courant","一盒"],["un tas de","familier","一大堆"]],"fq":"高频，日常常用。","me":"paquet 像英语 packet，只是 t 不读。","tr":{"zh":"我想要一包面。","fr":"Je voudrais un paquet de pâtes.","alt":"Je prendrais un paquet de pâtes, s'il vous plaît.","note":"un paquet de 后面不加冠词。"}},
 "Avoir hâte de": {"pos":"loc. 固定短语（动词性，avoir + hâte + de + 不定式）","s":"迫不及待；很期待。avoir hâte de + 动词原形，或 avoir hâte que + 虚拟式。表示期待某件快乐的事。","ipa":"[a.vwaʁ.ɑt.də]","ph":"avoir 读 [a.vwaʁ]；hâte 读 [ɑt]，h 不发音，â 读 [ɑ]；de 读 [də]。","pi":"hâte 的 h 不发音，所以是 j'ai hâte，不是 j'ai-t-hâte；avoir hâte que 后面要接虚拟式，如 J'ai hâte que tu viennes。","et":"hâte 来自法兰克语 *haisti（猛烈、匆忙）。同族：hâter、hâtif。","ex":[["J'ai hâte de te revoir !","我迫不及待想再见到你！"],["Elle a hâte que les vacances commencent.","她盼着假期快点开始。"]],"co":[["avoir hâte de + 不定式","迫不及待做……"],["avoir hâte que + 虚拟式","盼着……"],["J'ai hâte !","我好期待！"],["à la hâte","匆忙地"]],"sy":[["attendre avec impatience","courant","急切地等待"],["être impatient de","courant","迫不及待"]],"fq":"极高频，日常很常用。","me":"hâte 的帽子 â 像急匆匆赶路的人；后面 de + 动词。","tr":{"zh":"我迫不及待想去法国。","fr":"J'ai hâte d'aller en France.","alt":"Il me tarde d'aller en France.","note":"avoir hâte de + 动词原形；主语相同时不用 que。"}},
 "Avoir l'art de": {"pos":"loc. 固定短语（动词性，avoir + l'art + de + 不定式）","s":"很擅长……；有……的本事。可以是真的夸奖，也常带讽刺：有本事把事情弄糟。","ipa":"[a.vwaʁ.laʁ.də]","ph":"avoir 读 [a.vwaʁ]；l'art 读 [laʁ]，art 的 t 不发音；de 读 [də]。","pi":"art 的 t 不发音；l'art 要读成一个音节 [laʁ]；art 是阳性名词，l'art。","et":"art 来自拉丁语 ars, artis（技艺）。同族：artiste、artisan。","ex":[["Il a l'art de se mettre dans des situations compliquées.","他很擅长把自己弄进复杂的处境。"],["Elle a l'art de raconter des histoires.","她很会讲故事。"]],"co":[["avoir l'art de + 不定式","擅长做……"],["avoir l'art de la conversation","擅长聊天"],["l'art de vivre","生活艺术"]],"sy":[["savoir y faire","courant","有办法、会来事"],["avoir le don de","courant","天生有……的本事"]],"fq":"中频，书面和口语都有。","me":"art = 技艺：「有……的手艺」。","tr":{"zh":"他很会让大家笑。","fr":"Il a l'art de faire rire tout le monde.","alt":"Il sait faire rire tout le monde.","note":"avoir l'art de + 动词原形。"}},
 "Avoir son mot à dire": {"pos":"loc. 固定短语（动词性，avoir）","s":"有发言权；有权表达意见。son 随主语变化（mon / ton / son / notre / leur）。常用于决定、争论的场合。","ipa":"[a.vwaʁ.sɔ̃.mo.a.diʁ]","ph":"son 读 [sɔ̃]；mot 读 [mo]，t 不发音；à dire 读 [a.diʁ]，结尾 r 要读。","pi":"mot 的 t 不发音；son 的 n 不单发；son 的形式要跟着主语变。","et":"mot 来自晚期拉丁语 muttum（咕哝声、一句话）。dire 来自拉丁语 dicere。","ex":[["Dans cette entreprise, chaque employé a son mot à dire.","在这家公司，每个员工都有发言权。"],["Les enfants aussi ont leur mot à dire.","孩子们也有话要说。"]],"co":[["avoir son mot à dire","有发言权"],["avoir son mot à dire sur","对……有发言权"],["Je veux avoir mon mot à dire.","我也想表达意见。"]],"sy":[["avoir voix au chapitre","soutenu","有发言权，更书面"],["avoir son avis à donner","courant","有意见可说"]],"fq":"中频，日常和职场常用。","me":"「我的那一个字」：每个人都有自己的话要说。","tr":{"zh":"在家里，我也有发言权。","fr":"À la maison, j'ai aussi mon mot à dire.","alt":"Chez moi, j'ai mon mot à dire aussi.","note":"mon 跟着主语 je 变。"}},
 "Brouiller les pistes": {"pos":"loc. 固定短语（动词性）","s":"混淆视听；掩盖踪迹；让人搞不清方向。多用于故意制造混乱，比如罪犯、政治人物或写作者。","ipa":"[bʁu.je.le.pist]","ph":"brouiller 读 [bʁu.je]，ou 是 [u]，-ill- 读 [j]；pistes 读 [pist]，结尾 -es 不发音。","pi":"brouiller 里 ill 读 [j]，不是 [l]；pistes 的 s 要读（pi-st），结尾 es 不发。","et":"piste 来自意大利语 pista（足迹、道路）。brouiller 与 brouillard、brouillon 同族：弄混、搅乱。","ex":[["Le voleur a essayé de brouiller les pistes.","小偷试图混淆视听。"],["Il change de téléphone pour brouiller les pistes.","他换手机来掩盖踪迹。"]],"co":[["brouiller les pistes","掩盖踪迹"],["pour brouiller les pistes","为了混淆视听"],["brouiller les cartes","把牌搅乱，扰乱局面"]],"sy":[["égarer","soutenu","使迷路、误导"],["semer le doute","courant","制造疑云"]],"fq":"中低频，多见于新闻和叙述。","me":"piste（足迹）+ brouiller（弄乱）= 把脚印弄乱。","tr":{"zh":"他想掩盖自己的踪迹。","fr":"Il veut brouiller les pistes.","alt":"Il essaie de brouiller les pistes.","note":"les pistes 固定用复数。"}},
 "Donner un coup de main": {"pos":"loc. 固定短语（动词性，donner）","s":"帮个忙；搭把手。donner un coup de main à quelqu'un 或 donner un coup de main pour + 不定式。口语很常用。","ipa":"[dɔ.ne.œ̃.ku.də.mɛ̃]","ph":"donner 读 [dɔ.ne]；coup 读 [ku]，p 不发音；main 读 [mɛ̃]，ai 加 n 是鼻化。","pi":"coup 的 p 不发音；main 的 ai 读 [ɛ̃]；不要说成 donner une main。","et":"coup 来自拉丁语 colaphus（拳击，经通俗拉丁语 colpus）；main 来自拉丁语 manus。","ex":[["Tu peux me donner un coup de main pour déménager ?","你能帮我搬家吗？"],["Je te donne un coup de main si tu veux.","你要的话我帮你。"]],"co":[["donner un coup de main à quelqu'un","帮某人一把"],["un coup de main","帮忙、援手"],["avoir besoin d'un coup de main","需要帮忙"],["prêter main-forte","出手相助"]],"sy":[["aider","courant","帮助"],["filer un coup de main","familier","搭把手"],["prêter main-forte","soutenu","出手相助"]],"fq":"极高频，日常常用。","me":"coup de main = 伸一下手。","tr":{"zh":"你能帮我提一下箱子吗？","fr":"Tu peux me donner un coup de main avec la valise ?","alt":"Tu peux m'aider avec la valise ?","note":"me 是间接宾语，放在 donner 前面。"}},
 "Être digne de": {"pos":"loc. 固定短语（être + adj. digne + de）；digne 阴阳同形，复数 dignes","s":"值得……的；配得上……的。digne de confiance =「可信赖的」；digne de ce nom =「名副其实的」。","ipa":"[ɛtʁ.diɲ.də]","ph":"être 读 [ɛtʁ]；digne 读 [diɲ]，gn 读 [ɲ]；de 读 [də]。","pi":"digne 的 gn 读 [ɲ]，像「泥」，不是 [gn]；digne 阴阳性同形。","et":"digne 来自拉丁语 dignus。同族：dignité、indigne。","ex":[["Il est digne de confiance.","他值得信赖。"],["Cette décision est digne d'éloges.","这个决定值得赞扬。"]],"co":[["être digne de confiance","值得信任"],["digne de ce nom","名副其实的"],["être digne d'éloges","值得称赞"],["indigne de","反义：不配……"]],"sy":[["mériter","courant","值得"],["être à la hauteur de","courant","够格、胜任"]],"fq":"中频，偏书面。","me":"digne ≈ English dignity 的形容词：有尊严的 → 配得上。","tr":{"zh":"她是个值得信任的朋友。","fr":"C'est une amie digne de confiance.","alt":"C'est une amie en qui on peut avoir confiance.","note":"digne de + 名词，不加冠词（de confiance）。"}},
 "Être issu(e) de": {"pos":"loc. 固定短语（être + issu / issue + de），issu 阳性，issue 阴性，复数 issus / issues","s":"出身于……；来自……；源于……。指家庭、环境或想法的来源。注意随主语变阴阳性：il est issu / elle est issue。","ipa":"[ɛtʁ.i.sy.də]","ph":"être 读 [ɛtʁ]；issu 读 [i.sy]，u 是 [y]，嘴唇圆；issue 读 [i.sy]，读音和 issu 相同。","pi":"issu 和 issue 读音相同，只是拼写有阴阳性；u 读 [y]，不是 [u]。","et":"issu 是旧动词 issir（出来）的过去分词，来自拉丁语 exire（出去）。同族：issue（出口）。","ex":[["Elle est issue d'une famille d'artistes.","她出身艺术世家。"],["Il est issu d'un milieu modeste.","他出身普通家庭。"]],"co":[["être issu(e) de + 名词","出身于……"],["issu d'une famille de","出身于……家庭"],["un produit issu de l'agriculture bio","来自有机农业的产品"]],"sy":[["venir de","courant","来自"],["provenir de","soutenu","源于"],["descendre de","courant","是……的后代"]],"fq":"中频，多见于书面和新闻。","me":"issu = 「出来的」，issue = 出口；人从家庭「出来」。","tr":{"zh":"他出身农民家庭。","fr":"Il est issu d'une famille de paysans.","alt":"Il vient d'une famille de paysans.","note":"女性要用 issue：elle est issue de...。"}},
 "Faire bouger": {"pos":"loc. 固定短语（动词性，faire + 不定式）","s":"推动变化；让事情有进展；让人动起来。faire bouger les choses =「推动事情发展」。也可以是字面意思：移动某物。","ipa":"[fɛʁ.bu.ʒe]","ph":"faire 读 [fɛʁ]，ai 读 [ɛ]；bouger 读 [bu.ʒe]，ou 读 [u]，g 在 e 前读 [ʒ]；-er 读 [e]。","pi":"faire 不读 [fe]，读 [fɛʁ]；bouger 的 g 读 [ʒ]，像「日」；faire + 不定式表示「使」。","et":"bouger 来源不确定；同族：bougeotte（坐不住）。faire 来自拉丁语 facere。","ex":[["Nous voulons faire bouger les choses !","我们想让事情有所改变！"],["Il n'arrive pas à faire bouger la table.","他搬不动桌子。"]],"co":[["faire bouger les choses","推动事情改变"],["faire bouger les lignes","改变现有格局"],["ne pas faire bouger","不挪动"]],"sy":[["changer les choses","courant","改变现状"],["déplacer","courant","移动（字面）"],["secouer","courant","撼动"]],"fq":"中频，日常和新闻常用。","me":"faire（使）+ bouger（动）：让它动起来。","tr":{"zh":"我们要让情况有所改变。","fr":"Nous devons faire bouger les choses.","alt":"Il faut que ça bouge !","note":"faire + 动词原形，表示「使……动」。"}},
 "Faire l'affaire": {"pos":"loc. 固定短语（动词性，faire）","s":"合用；凑合能用；正好满足需要。多用来说某物「够用了」。主语可以是物，也可以是人。","ipa":"[fɛʁ.la.fɛʁ]","ph":"faire 读 [fɛʁ]；l'affaire 读 [la.fɛʁ]，ff 只读一个 [f]；affaire 的 ai 读 [ɛ]。","pi":"faire 和 affaire 的结尾都读 [fɛʁ]，别写错：affaire 双 f；faire l'affaire 不是「做生意」。","et":"affaire 来自 à faire（要做的事）。faire l'affaire 即「满足需要」。","ex":[["Ces vieilles chaussures feront l'affaire.","这双旧鞋凑合能穿。"],["Ce couteau fera l'affaire pour couper le pain.","这把刀切面包够用了。"]],"co":[["faire l'affaire","够用、合适"],["Ça fera l'affaire.","这样就行。"],["ça ne fait pas l'affaire","这不行"]],"sy":[["convenir","courant","合适"],["suffire","courant","足够"],["faire le boulot","familier","起作用、能用"]],"fq":"中频，口语里常用。","me":"affaire = à faire：能完成「要做的事」就行。","tr":{"zh":"这把椅子凑合能用。","fr":"Cette chaise fera l'affaire.","alt":"Cette chaise, ça ira très bien.","note":"l'affaire 固定不变，faire 随时态变。"}},
 "Faire preuve de": {"pos":"loc. 固定短语（动词性，faire + preuve + de + 无冠词名词）","s":"表现出；显示出（品质、能力）。后面接无冠词的抽象名词：faire preuve de courage / de patience / de bon sens。","ipa":"[fɛʁ.pʁœv.də]","ph":"faire 读 [fɛʁ]；preuve 读 [pʁœv]，eu 在这里读 [œ]，结尾 v 要读；de 读 [də]。","pi":"preuve 的 eu 读开口的 [œ]；后面名词不加冠词：faire preuve de patience，不说 de la patience。","et":"preuve 来自拉丁语 proba（证明），同族：prouver、éprouver。","ex":[["Il faut faire preuve de patience avec les enfants.","对孩子要有耐心。"],["Elle a fait preuve de courage.","她表现得很勇敢。"]],"co":[["faire preuve de courage / de patience","表现出勇气 / 耐心"],["faire preuve de bon sens","表现出常识"],["faire preuve d'initiative","主动出击"]],"sy":[["montrer","courant","显示"],["manifester","soutenu","表现出"]],"fq":"高频，书面和职场常用。","me":"preuve（证据）：用行动给出证据。","tr":{"zh":"她表现得很有耐心。","fr":"Elle a fait preuve de patience.","alt":"Elle s'est montrée très patiente.","note":"faire preuve de + 无冠词名词。"}},
 "Il s'agit de": {"pos":"loc. 固定短语（无人称动词 s'agir，只用 il）","s":"关乎……；涉及……；这是……的问题；必须……。il s'agit de + 名词 / 不定式。主语只能是 il，不能说 le livre s'agit de。","ipa":"[il.sa.ʒi.də]","ph":"il 读 [il]；s'agit 读 [sa.ʒi]，g 在 i 前读 [ʒ]，t 不发音；de 读 [də]。","pi":"主语必须是 il，不是书或人；agit 的 t 不发音；不要和 agir（行动）混用，「书讲的是……」要说 Il s'agit de。","et":"s'agir 来自 agir（拉丁语 agere，「做、行动」），只用于无人称。","ex":[["Il s'agit d'une question très importante.","这涉及一个非常重要的问题。"],["Il s'agit de travailler plus vite.","关键是要做得更快。"],["De quoi s'agit-il ?","是怎么回事？"]],"co":[["il s'agit de + 名词","涉及……"],["il s'agit de + 不定式","必须……、关键是……"],["De quoi s'agit-il ?","怎么回事？"],["Il ne s'agit pas de...","问题不在于……"]],"sy":[["Il est question de","courant","涉及、讲的是"],["Il faut","courant","必须"]],"fq":"高频，书面和口语都常用。","me":"il s'agit = 「这里面讲的是」，主语永远是 il。","tr":{"zh":"这是一个很严肃的问题。","fr":"Il s'agit d'un problème très sérieux.","alt":"C'est un problème très sérieux.","note":"d'un = de + un；主语 il 不变。"}},
 "Laisser place à": {"pos":"loc. 固定短语（动词性，laisser + place + à）","s":"让位于……；被……取代。laisser place à 或 laisser la place à：A 让位给 B，A 是主语。也常用于季节、情绪的更替。","ipa":"[le.se.plas.a]","ph":"laisser 读 [le.se]，ai 读 [e]，ss 读 [s]；place 读 [plas]；à 读 [a]。","pi":"laisser 的 -er 读 [e]；ai 读 [e]，不是 [ɛ]；place 的 c 读 [s]。","et":"place 来自拉丁语 platea（宽街）。laisser 来自拉丁语 laxare（放松、放手）。","ex":[["La colère a laissé place à la tristesse.","愤怒让位于悲伤。"],["L'été laisse place à l'automne.","夏天过去，秋天来临。"]],"co":[["laisser place à + 名词","让位于……"],["laisser la place à quelqu'un","给某人让座"],["faire place à","为……让路"]],"sy":[["céder la place à","courant","把位置让给"],["succéder à","soutenu","接替"]],"fq":"中频，书面和新闻常用。","me":"laisser（留）+ place（位置）：把位置留给后来的。","tr":{"zh":"冬天过后是春天。","fr":"L'hiver laisse place au printemps.","alt":"Après l'hiver, le printemps arrive.","note":"à + le = au；主语是退出的一方。"}},
 "Rendre ses lettres de noblesse": {"pos":"loc. 固定短语（动词性，rendre à quelqu'un / quelque chose）","s":"使恢复声誉；让……重新受尊重。rendre ses lettres de noblesse à + 事物：让某事物重获地位。ses 指「它的」，所以名词要放在 à 后面。","ipa":"[ʁɑ̃dʁ.se.lɛtʁ.də.nɔ.blɛs]","ph":"rendre 读 [ʁɑ̃dʁ]；ses 读 [se]；lettres 读 [lɛtʁ]；noblesse 读 [nɔ.blɛs]。","pi":"rendre 的 en 读 [ɑ̃]；noblesse 的 -esse 读 [ɛs]；lettres de noblesse 是复数。","et":"lettres de noblesse 原指国王授予贵族身份的文书（lettres patentes）；比喻「赋予地位」。","ex":[["Ce chef a rendu ses lettres de noblesse à la cuisine végétarienne.","这位厨师让素食重获声望。"],["Ce festival rend ses lettres de noblesse au jazz.","这个音乐节让爵士乐重获尊重。"]],"co":[["rendre ses lettres de noblesse à + 名词","使……恢复声誉"],["gagner ses lettres de noblesse","赢得地位"],["des lettres de noblesse","声望、地位"]],"sy":[["réhabiliter","soutenu","恢复名誉"],["redorer le blason","courant","重振声誉"]],"fq":"低频，多见于书面和新闻。","me":"从前国王发「贵族证书」，现在是给事物重新发一张。","tr":{"zh":"这家餐厅让传统菜重获声望。","fr":"Ce restaurant rend ses lettres de noblesse à la cuisine traditionnelle.","alt":"Ce restaurant redonne ses lettres de noblesse à la cuisine traditionnelle.","note":"ses 指被恢复的事物，放在 à 之后的名词。"}},
 "Se prêter au jeu": {"pos":"loc. 固定短语（代动词 se prêter，复合时态用 être）","s":"配合参与；愿意一起玩；顺着大家来。指别人要求或游戏、活动时愿意配合。完成时：il s'est prêté au jeu。","ipa":"[sə.pʁɛ.te.o.ʒø]","ph":"se 读 [sə]；prêter 读 [pʁɛ.te]，ê 读 [ɛ]；au 读 [o]；jeu 读 [ʒø]。","pi":"prêter 的 ê 读 [ɛ]；jeu 的 j 读 [ʒ]，eu 读 [ø]；复合时态里过去分词要与主语一致：elles se sont prêtées au jeu。","et":"prêter 来自拉丁语 praestare；jeu 来自拉丁语 iocus（玩笑）。","ex":[["Les invités se sont prêtés au jeu et ont tous dansé.","客人们配合着都跳起舞来。"],["Il ne veut pas se prêter au jeu.","他不想配合。"]],"co":[["se prêter au jeu","配合参与"],["refuser de se prêter au jeu","拒绝配合"],["accepter de se prêter au jeu","愿意配合"]],"sy":[["jouer le jeu","courant","遵守规则、认真参与"],["coopérer","courant","合作"]],"fq":"中频，日常和新闻常用。","me":"prêter（借出）自己去参加游戏：配合。","tr":{"zh":"孩子们很乐意配合这个游戏。","fr":"Les enfants se prêtent volontiers au jeu.","alt":"Les enfants jouent le jeu avec plaisir.","note":"se prêter à + 名词；au = à + le。"}},
 "Tourner en rond": {"pos":"loc. 固定短语（动词性，tourner）","s":"原地打转；兜圈子；没有进展。可指字面绕圈，也可指讨论、思考没有结果。","ipa":"[tuʁ.ne.ɑ̃.ʁɔ̃]","ph":"tourner 读 [tuʁ.ne]；en 读 [ɑ̃]；rond 读 [ʁɔ̃]，结尾 d 不发音。","pi":"rond 的 d 不发音；en 与 rond 之间不要联诵。","et":"tourner 来自拉丁语 tornare（用车床加工）；rond 来自拉丁语 rotundus。","ex":[["Nous n'avançons pas, nous tournons en rond.","我们没有进展，在原地打转。"],["Le chien tourne en rond avant de dormir.","狗睡前先转圈。"]],"co":[["tourner en rond","原地打转"],["tourner en rond dans sa chambre","在房间里来回转"],["ça tourne en rond","没有进展"]],"sy":[["piétiner","courant","原地踏步，没有进展"],["faire du surplace","courant","原地不动"]],"fq":"中频，日常常用。","me":"tourner（转）+ rond（圆）：绕圈却回到原点。","tr":{"zh":"我们一直在原地打转。","fr":"Nous tournons en rond depuis une heure.","alt":"On tourne en rond depuis une heure.","note":"depuis + 时间，与现在时连用。"}},
 "À quel point": {"pos":"loc. 固定短语（疑问或感叹副词短语）","s":"到什么程度；多么。用于间接疑问或感叹：Tu ne sais pas à quel point... 后面接陈述句，不倒装。","ipa":"[a.kɛl.pwɛ̃]","ph":"à 读 [a]；quel 读 [kɛl]；point 读 [pwɛ̃]，t 不发音。","pi":"point 的 t 不发音；间接疑问不倒装：Tu ne comprends pas à quel point je suis fatigué。","et":"quel 来自拉丁语 qualis；point 来自拉丁语 punctum。","ex":[["Tu ne comprends pas à quel point le sport est important pour moi.","你不明白运动对我有多重要。"],["À quel point tu es gentil !","你真是太好了！"]],"co":[["à quel point + 陈述句","到什么程度"],["Tu vois à quel point...","你看，……到了什么程度"],["Tu ne sais pas à quel point...","你不知道……有多么"]],"sy":[["combien","courant","多么"],["comme","courant","多么（感叹）"]],"fq":"中频，日常和书面常用。","me":"à quel point = 到哪一点？指程度的高低。","tr":{"zh":"你不知道我有多想你。","fr":"Tu ne sais pas à quel point tu me manques.","alt":"Tu ne sais pas combien tu me manques.","note":"后面是陈述句，不倒装。"}},
 "N'importe": {"pos":"loc. 固定短语（n'importe + quel / qui / quoi / où / comment / quand）","s":"任何……都行；随便。n'importe quel livre = 任何一本书；n'importe qui = 任何人；n'importe quoi = 随便什么；也可表示「胡说八道」：Tu dis n'importe quoi !","ipa":"[nɛ̃.pɔʁt]","ph":"n'importe 读 [nɛ̃.pɔʁt]，im 读鼻化 [ɛ̃]；port 的 t 要发音。","pi":"importe 的 t 要读，不是 [nɛ̃.pɔʁ]；n'importe 不能单独用，要接 quel / qui / quoi 等；Tu dis n'importe quoi 是批评语。","et":"importer 来自拉丁语 importare；n'importe = 「这不重要」，即「无所谓是哪一个」。","ex":[["N'importe quel livre fera l'affaire.","随便哪本书都行。"],["Tu dis n'importe quoi !","你在胡说八道！"],["Il peut dormir n'importe où.","他在哪里都能睡。"]],"co":[["n'importe quel + 名词","任何……"],["n'importe qui","任何人"],["n'importe quoi","随便什么；胡扯"],["n'importe où / quand / comment","任何地方 / 时候 / 方式"]],"sy":[["peu importe","courant","无所谓"],["quelconque","soutenu","任意的、随便的"]],"fq":"极高频，日常常用。","me":"n'importe = 「不重要」：哪个都一样。","tr":{"zh":"你可以随时来。","fr":"Tu peux venir n'importe quand.","alt":"Tu peux passer quand tu veux.","note":"n'importe + 疑问词，组成一个整体。"}},
 "À but lucratif / À but non lucratif": {"pos":"loc. 固定短语（形容词性，修饰 organisation / entreprise / association）","s":"营利的 / 非营利的。à but lucratif = 以赚钱为目的；à but non lucratif = 不以营利为目的，如协会、基金会。","ipa":"[a.byt.ly.kʁa.tif] / [a.byt.nɔ̃.ly.kʁa.tif]","ph":"but 读 [byt]，t 要发音；lucratif 读 [ly.kʁa.tif]，u 读 [y]，结尾 -if 读 [if]；non 读 [nɔ̃]。","pi":"but 的 t 要读；u 读 [y]，不是 [u]；but 是阳性名词，所以用阳性 lucratif，不是 lucrative。","et":"lucratif 来自拉丁语 lucrativus，源自 lucrum（利润）；but 是「目的」，来源这里不细说。","ex":[["C'est une organisation à but non lucratif.","这是一个非营利组织。"],["Cette entreprise est à but lucratif.","这家公司以营利为目的。"]],"co":[["une association à but non lucratif","非营利协会"],["à but lucratif","营利性"],["un organisme à but non lucratif","非营利机构"]],"sy":[["sans but lucratif","courant","不以营利为目的，同义说法"],["commercial","courant","商业的"]],"fq":"中频，行政、新闻和商务常用。","me":"lucratif 像英语 lucrative：赚钱的。","tr":{"zh":"这是个非营利协会。","fr":"C'est une association à but non lucratif.","alt":"C'est une association sans but lucratif.","note":"à but 是固定搭配，but 不变。"}},
 "À l'inverse": {"pos":"loc. 固定短语（副词短语）","s":"相反；反过来。放在句首或句中，对比两种情况。书面和口语都可以。","ipa":"[a.lɛ̃.vɛʁs]","ph":"l'inverse 读 [lɛ̃.vɛʁs]，in 读鼻化 [ɛ̃]；-verse 读 [vɛʁs]，结尾 -e 不发音。","pi":"inverse 里的 in 要读鼻化 [ɛ̃]，不是 [in]；s 在 -erse 里读 [s]。","et":"inverse 来自拉丁语 inversus（颠倒的）。同族：inverser、l'inverse。","ex":[["Mon frère est calme, mais moi, à l'inverse, je suis très énergique.","我哥哥很冷静，而我恰好相反，精力旺盛。"],["À l'inverse de son père, il adore le sport.","与他爸爸相反，他很爱运动。"]],"co":[["à l'inverse de + 名词","与……相反"],["à l'inverse,","相反，"],["l'inverse","相反的东西"],["au contraire","相反地"]],"sy":[["au contraire","courant","相反"],["en revanche","courant","反过来、不过"],["inversement","soutenu","反之"]],"fq":"中频，书面常用。","me":"inverse = 倒过来：像英语 inverse。","tr":{"zh":"我喜欢夏天，他则相反。","fr":"J'aime l'été ; lui, à l'inverse, préfère l'hiver.","alt":"J'aime l'été, mais lui, c'est l'inverse.","note":"à l'inverse (de) 常用逗号隔开。"}},
 "En fin de compte": {"pos":"loc. 固定短语（副词短语）","s":"归根结底；最后；说到底。放在句首总结或得出结论，也可以说 au bout du compte。","ipa":"[ɑ̃.fɛ̃.də.kɔ̃t]","ph":"en 读 [ɑ̃]；fin 读 [fɛ̃]；compte 读 [kɔ̃t]，p 不发音。","pi":"compte 里的 p 不发音；en fin 之间不联诵；compte（账、结果）与 conte（故事）、comte（伯爵）同音。","et":"compte 来自拉丁语 computare（计算）。同族：compter、décompte。意思是「算到最后」。","ex":[["En fin de compte, nous avons décidé de rester.","最后，我们决定留下。"],["En fin de compte, ce n'est pas si grave.","说到底，这没那么严重。"]],"co":[["en fin de compte,","归根结底，"],["au bout du compte","最终"],["tout compte fait","考虑一切之后"]],"sy":[["finalement","courant","最后"],["au bout du compte","courant","最终"],["somme toute","soutenu","总之"]],"fq":"高频，日常和书面都常用。","me":"「算到最后（fin）的总账（compte）」= 结论。","tr":{"zh":"说到底，这只是个小问题。","fr":"En fin de compte, ce n'est qu'un petit problème.","alt":"Au final, c'est juste un petit problème.","note":"ne ... que 表示「只是」。"}},
 "Quelque part": {"pos":"loc. 固定短语（副词短语）","s":"在某处；某个地方。用来说不确定或不想说的地点：Il est quelque part en Italie。口语里也可说「在某种程度上」。","ipa":"[kɛlk.paʁ]","ph":"quelque 读 [kɛlk]，结尾 e 不发音；part 读 [paʁ]，t 不发音。","pi":"quelque 在这里是单数形式，没有 s；part 的 t 不发音；不要和 nulle part（哪里都没有）搞混。","et":"quelque 来自 quel + que；part 来自拉丁语 pars（部分）。","ex":[["J'ai laissé mes clés quelque part, mais je ne sais plus où.","我把钥匙放在某处，想不起在哪里了。"],["Il habite quelque part près de Lyon.","他住在里昂附近的某个地方。"]],"co":[["quelque part","某处"],["nulle part","哪里都不"],["autre part","别处"],["quelque part en France","法国的某个地方"]],"sy":[["dans un endroit","courant","在一个地方"],["nulle part","courant","反义：哪里都没有"],["ailleurs","courant","别处"]],"fq":"极高频，日常常用。","me":"quelque（某）+ part（地方）。","tr":{"zh":"我的手机一定在这里的某处。","fr":"Mon téléphone est forcément quelque part ici.","alt":"Mon portable doit bien être quelque part par ici.","note":"quelque part 固定不变。"}},
 "À destination de": {"pos":"loc. 固定短语（介词短语）","s":"开往……；前往……的。用于火车、飞机、航班：le train à destination de Lyon。也可指「面向……」：un livre à destination des enfants。","ipa":"[a.dɛs.ti.na.sjɔ̃.də]","ph":"destination 读 [dɛs.ti.na.sjɔ̃]，-tion 读 [sjɔ̃]；de 读 [də]。","pi":"-tion 读 [sjɔ̃]，不读 [tjɔ̃]；à destination de 里 de 不能省。","et":"destination 来自拉丁语 destinatio；同族：destiner、destin。","ex":[["Le train à destination de Lyon va partir.","开往里昂的火车即将发车。"],["Un vol à destination de Tokyo a été annulé.","一趟飞往东京的航班被取消了。"]],"co":[["à destination de + 地名","开往……"],["en provenance de","从……来（反义）"],["à destination du public","面向公众"]],"sy":[["pour","courant","去往"],["vers","courant","朝着"]],"fq":"中频，车站和机场广播常见。","me":"destination 就是 English destination：à destination de = 目的地是……","tr":{"zh":"开往巴黎的火车晚点了。","fr":"Le train à destination de Paris a du retard.","alt":"Le train pour Paris a du retard.","note":"à destination de 比 pour 更正式。"}},
 "Au regard de": {"pos":"loc. 固定短语（介词短语，偏书面）","s":"鉴于；就……而言；与……相比。书面和行政语体里常见：au regard de la loi（依据法律）。","ipa":"[o.ʁə.gaʁ.də]","ph":"au 读 [o]；regard 读 [ʁə.gaʁ]，d 不发音；de 读 [də]。","pi":"regard 的 d 不发音；不要和 par rapport à 混淆，不过意思相近。","et":"regard 来自 regarder = re- + garder；garder 来自法兰克语。","ex":[["Au regard de la situation, nous devons agir vite.","鉴于形势，我们必须迅速行动。"],["Au regard de la loi, c'est interdit.","依据法律，这是禁止的。"]],"co":[["au regard de la loi","依据法律"],["au regard de + 名词","就……而言"],["en regard de","与……相比"]],"sy":[["compte tenu de","soutenu","考虑到"],["par rapport à","courant","相对于"],["vu","courant","鉴于"]],"fq":"中频，书面和行政文字常见。","me":"regard（目光）：用……的眼光来看。","tr":{"zh":"鉴于天气，我们取消活动。","fr":"Au regard de la météo, nous annulons l'événement.","alt":"Vu la météo, on annule l'événement.","note":"au regard de 偏书面，口语用 vu。"}},
 "Après la pluie vient le beau temps": {"pos":"loc. 谚语","s":"雨过天晴；苦尽甘来。用来安慰遇到困难的人，意思是坏事之后会有好事。","ipa":"[a.pʁɛ.la.plɥi.vjɛ̃.lə.bo.tɑ̃]","ph":"après 读 [a.pʁɛ]；pluie 读 [plɥi]，u 读 [ɥ]；vient 读 [vjɛ̃]；beau temps 读 [bo.tɑ̃]。","pi":"pluie 的 ui 读 [ɥi]，要快；vient 的 t 不发音；temps 的 ps 不发音；注意顺序：vient 在主语前（倒装）。","et":"谚语，来源不确定。pluie 来自拉丁语 pluvia。","ex":[["Ne sois pas triste, après la pluie vient le beau temps.","别难过，雨过天晴。"],["Courage, après la pluie vient le beau temps.","加油，苦尽甘来。"]],"co":[["Après la pluie, le beau temps.","雨后天晴（简短说法）"],["après la pluie vient le beau temps","苦尽甘来"],["la pluie et le beau temps","天气；能呼风唤雨的人"]],"sy":[["Après la tempête vient le calme.","courant","暴风雨后是平静"],["Tout finit par s'arranger.","courant","一切终会好起来"]],"fq":"中频，安慰人时常说。","me":"雨（pluie）之后来了好天气（beau temps）。","tr":{"zh":"别担心，苦尽甘来。","fr":"Ne t'inquiète pas, après la pluie vient le beau temps.","alt":"Courage, ça va s'arranger.","note":"谚语固定，vient 在 le beau temps 前。"}},
 "Du bitume": {"pos":"n.m. 阳性名词（du = de + le，部分冠词），复数 bitumes（少用）","s":"沥青；柏油路。常用来指铺好的路面：marcher sur le bitume。不可数名词，所以常说 du bitume。口语中也指「马路」。","ipa":"[bi.tym]","ph":"bitume 读 [bi.tym]，u 读 [y]，嘴唇圆；结尾 -e 不发音，m 读出来。","pi":"u 读 [y]，不是 [u]；m 要发音；不是 bi-tu-me 三个音节。","et":"来自拉丁语 bitumen（沥青）。","ex":[["Le bitume fond sous le soleil.","沥青在阳光下融化。"],["Les enfants jouent sur le bitume.","孩子们在柏油路上玩。"]],"co":[["du bitume","（一些）沥青"],["le bitume de la route","公路的沥青路面"],["arpenter le bitume","在街头走来走去（口语）"],["goudron","柏油（近义）"]],"sy":[["goudron","courant","柏油；焦油"],["asphalte","courant","沥青"],["macadam","soutenu","碎石路面"]],"fq":"低频，日常偶尔用。","me":"bitume 像 bitumen（沥青）。","tr":{"zh":"夏天，沥青路面很烫。","fr":"En été, le bitume est brûlant.","alt":"L'été, le bitume est très chaud.","note":"le bitume 是阳性名词，不可数。"}},
 "L'achèvement": {"pos":"n.m. 阳性名词，复数 achèvements（少用）","s":"完成；竣工；结束。指一项工作、工程的完成：l'achèvement des travaux。比 la fin 更书面，强调「做完了」。","ipa":"[a.ʃɛv.mɑ̃]","ph":"achèvement 读 [a.ʃɛv.mɑ̃]，ch 读 [ʃ]，è 读 [ɛ]；-ement 读 [mɑ̃]，e 在这里不读。","pi":"ch 读 [ʃ]，不是 [k]；è 带重音，读 [ɛ]；l'achèvement 缩读，l' 与 a 连读。","et":"来自动词 achever（来自古法语 venir à chef，「到头」，chef 来自拉丁语 caput）+ -ment。","ex":[["Nous fêtons l'achèvement des travaux.","我们庆祝工程竣工。"],["L'achèvement du livre a pris trois ans.","写完这本书花了三年。"]],"co":[["l'achèvement des travaux","工程竣工"],["en voie d'achèvement","即将完成"],["l'achèvement du projet","项目完成"]],"sy":[["la fin","courant","结束"],["l'aboutissement","soutenu","结果、成就"],["la réalisation","courant","实现"]],"fq":"低频，书面常见。","me":"achever（完成）+ -ment：做完了的状态。","tr":{"zh":"房子的竣工推迟了。","fr":"L'achèvement de la maison a été retardé.","alt":"La maison ne sera pas terminée à temps.","note":"l'achèvement de + 名词。"}},
 "L'appui de": {"pos":"n.m. 阳性名词，复数 appuis","s":"……的支持；……的帮助。l'appui de quelqu'un = 某人的支持。也指「靠托」：l'appui de fenêtre（窗台）。","ipa":"[a.pɥi]","ph":"appui 读 [a.pɥi]，pp 只读一个 [p]，ui 读 [ɥi]；l'appui de 读 [la.pɥi.də]。","pi":"ui 读 [ɥi]，要快，不是 [u.i]；pp 是双写，读一个 [p]。","et":"来自动词 appuyer，源于通俗拉丁语 *appodiare（支撑）。同族：appui-tête。","ex":[["La police a reçu l'appui de la mairie.","警方得到了市政厅的支持。"],["Elle a besoin de l'appui de sa famille.","她需要家人的支持。"]],"co":[["avec l'appui de + 名词","在……的支持下"],["recevoir l'appui de","得到……的支持"],["l'appui de fenêtre","窗台"],["prendre appui sur","以……为支点"]],"sy":[["le soutien","courant","支持"],["l'aide","courant","帮助"],["le soutien moral","courant","精神支持"]],"fq":"中频，书面和新闻常用。","me":"appui ≈ 靠着的东西：像拐杖。","tr":{"zh":"他得到了朋友们的支持。","fr":"Il a reçu l'appui de ses amis.","alt":"Ses amis l'ont soutenu.","note":"l'appui de + 名词（支持的来源）。"}},
 "L'entretien": {"pos":"n.m. 阳性名词，复数 entretiens","s":"维护；保养；会谈。l'entretien de la maison（家务打理）；un entretien d'embauche（面试）。同一个词，要看上下文。","ipa":"[ɑ̃.tʁə.tjɛ̃]","ph":"entretien 读 [ɑ̃.tʁə.tjɛ̃]，en 是鼻化 [ɑ̃]，-ien 读 [jɛ̃]；l'entretien 缩读为 l'.","pi":"ien 读 [jɛ̃]，不是 [jɛn]；entretien 中间 e 读 [ə]，较轻；要分清「维护」和「会谈」。","et":"来自动词 entretenir（entre + tenir，「保持」）。同族：maintenir。","ex":[["Qui s'occupe de l'entretien de ce parc ?","谁负责这个公园的维护？"],["Il a un entretien d'embauche demain.","他明天有一场面试。"]],"co":[["l'entretien de la maison / de la voiture","房子 / 汽车的保养"],["un entretien d'embauche","面试"],["un contrat d'entretien","维护合同"],["le produit d'entretien","清洁用品"]],"sy":[["la maintenance","courant","维护（技术、设备）"],["l'interview","courant","采访、访谈"],["la conversation","courant","谈话"]],"fq":"高频，日常和工作常见。","me":"entre + tenir：保持住 → 维护；也「保持交谈」。","tr":{"zh":"汽车需要定期保养。","fr":"La voiture a besoin d'un entretien régulier.","alt":"Il faut entretenir la voiture régulièrement.","note":"entretien 是阳性名词。"}},
 "L'immobilier": {"pos":"n.m. 阳性名词（常作集合名词，不用复数）","s":"房地产；不动产。le marché de l'immobilier = 房产市场；travailler dans l'immobilier = 在房地产行业工作。也可作形容词 immobilier / immobilière。","ipa":"[i.mɔ.bi.lje]","ph":"immobilier 读 [i.mɔ.bi.lje]，imm- 的 mm 只读一个 [m]；-ier 读 [je]。","pi":"imm- 读 [im]，不要读成鼻化 [ɛ̃m]；-ier 读 [je]；l'immobilier 里 l' 与 i 连读。","et":"来自 im- 否定前缀 + mobilier（可移动物），意思是「不可移动的」。拉丁语 immobilis。","ex":[["Le marché de l'immobilier est en crise.","房地产市场陷入危机。"],["Elle travaille dans l'immobilier.","她在房地产行业工作。"]],"co":[["le marché de l'immobilier","房地产市场"],["une agence immobilière","房产中介"],["investir dans l'immobilier","投资房地产"],["un agent immobilier","房产经纪人"]],"sy":[["la pierre","familier","房产（比喻说法）"],["le mobilier","courant","反义：家具、动产"]],"fq":"高频，经济、新闻和生活常用。","me":"im-（不）+ mobile（动）：不能搬走的东西。","tr":{"zh":"他想投资房地产。","fr":"Il veut investir dans l'immobilier.","alt":"Il veut acheter dans la pierre.","note":"investir dans + 名词。"}},
 "L'urbanisme": {"pos":"n.m. 阳性名词，复数 urbanismes（少用）","s":"城市规划；城市建设。指规划城市空间、道路和建筑的学问或工作：un plan d'urbanisme。","ipa":"[yʁ.ba.nism]","ph":"urbanisme 读 [yʁ.ba.nism]，u 读 [y]，嘴唇圆；结尾 -me 读 [m]，e 不读。","pi":"u 读 [y]；l'urbanisme 中 l' 与 u 连读；s 在 -isme 里读 [s] 的音（[nism]），不是 [z]。","et":"来自拉丁语 urbs, urbis（城市）+ -isme。同族：urbain、urbaniste。","ex":[["L'urbanisme de cette ville est très moderne.","这座城市的规划非常现代。"],["Elle étudie l'urbanisme à l'université.","她在大学学城市规划。"]],"co":[["un plan d'urbanisme","城市规划方案"],["un urbaniste","城市规划师"],["le service de l'urbanisme","城市规划部门"]],"sy":[["l'aménagement urbain","soutenu","城市整治、建设"],["l'architecture","courant","建筑学（相关但不同）"]],"fq":"中低频，多见于新闻和行政文字。","me":"urb（城）+ -isme：关于城市的学问，像英语 urban。","tr":{"zh":"她在市政府做城市规划。","fr":"Elle travaille dans l'urbanisme à la mairie.","alt":"Elle est urbaniste à la mairie.","note":"travailler dans + 行业。"}},
 "Le marché de": {"pos":"n.m. 阳性名词，复数 marchés","s":"……的市场；……行业的市场。le marché de l'emploi（就业市场）；le marché du vélo（自行车市场）。也指实体的集市：aller au marché。","ipa":"[maʁ.ʃe]","ph":"marché 读 [maʁ.ʃe]，ch 读 [ʃ]，é 读 [e]；de 读 [də]，与 le 合写时变 du / des。","pi":"marché 的 ch 读 [ʃ]；de + le = du：le marché du vélo，不是 le marché de le vélo。","et":"来自拉丁语 mercatus（买卖）。同族：commerce、marchand。","ex":[["Le marché du vélo continue de se développer.","自行车市场继续发展。"],["Le marché de l'emploi est difficile.","就业市场很困难。"]],"co":[["le marché de l'emploi","就业市场"],["le marché du travail","劳动力市场"],["le marché de l'immobilier","房地产市场"],["bon marché","便宜的"]],"sy":[["le secteur","courant","行业、领域"],["la foire","courant","集市、展销"]],"fq":"极高频，生活和经济常用。","me":"marché 就是 market 的法语兄弟。","tr":{"zh":"手机市场变化很快。","fr":"Le marché du téléphone change très vite.","alt":"Le marché des téléphones évolue vite.","note":"de + le = du。"}},
 "Le rayon d'action": {"pos":"n.m. 阳性名词，复数 rayons d'action","s":"作用半径；活动范围。指飞机、无人机、车辆能到达的距离，也比喻一个人或机构的影响范围。rayon 本义是「射线、半径」。","ipa":"[lə.ʁɛ.jɔ̃.dak.sjɔ̃]","ph":"rayon 读 [ʁɛ.jɔ̃]，ay 读 [ɛj]，-on 读 [ɔ̃]；action 读 [ak.sjɔ̃]，-tion 读 [sjɔ̃]。","pi":"rayon 里 ay 读 [ɛj]，不是 [aj]；d'action 的 d' 与 a 连读；ct 在 action 里读 [ks]。","et":"rayon 来自古法语 rai，拉丁语 radius（射线、半径）。action 来自拉丁语 actio。","ex":[["Le rayon d'action de ce drone est de 5 kilomètres.","这架无人机的作用半径是五公里。"],["Cette association a un large rayon d'action.","这个协会活动范围很广。"]],"co":[["un large rayon d'action","活动范围很广"],["le rayon d'action d'un avion","飞机的航程半径"],["limiter le rayon d'action","限制活动范围"]],"sy":[["la portée","courant","射程、范围"],["l'autonomie","courant","续航里程"],["le champ d'action","courant","行动范围"]],"fq":"中低频，技术和书面常见。","me":"rayon（半径）+ action（行动）：行动的半径。","tr":{"zh":"这辆车的续航半径有限。","fr":"Le rayon d'action de cette voiture est limité.","alt":"Cette voiture n'a pas beaucoup d'autonomie.","note":"rayon d'action 常指最大活动距离。"}},
 "Le rythme": {"pos":"n.m. 阳性名词，复数 rythmes","s":"节奏；速度；步调。le rythme de la musique（音乐节奏）；le rythme de vie（生活节奏）；à ce rythme（照这个速度）。","ipa":"[ʁitm]","ph":"rythme 读 [ʁitm]，一个音节；y 读 [i]；th 读 [t]；结尾 -me 的 e 不读。","pi":"th 读 [t]，不是 [θ]；y 读 [i]；只有一个音节，不要读成 [ʁi.təm]；拼写 rythme 易错（y、th 要记）。","et":"来自希腊语 rhythmos，经拉丁语 rhythmus 进入法语。同族：rythmique、rythmé。","ex":[["Le rythme de vie est rapide en ville.","城市的生活节奏很快。"],["À ce rythme, nous allons arriver en retard.","照这个速度，我们会迟到。"]],"co":[["le rythme de vie","生活节奏"],["à ce rythme","照这个速度"],["suivre le rythme","跟上节奏"],["à son rythme","按自己的节奏"]],"sy":[["la cadence","soutenu","节奏、速率"],["le tempo","courant","（音乐）速度"],["la vitesse","courant","速度"]],"fq":"高频，日常和音乐、工作都常用。","me":"rythme 里有 y 和 th，读起来却很简单：[ʁitm]。","tr":{"zh":"我喜欢按自己的节奏工作。","fr":"J'aime travailler à mon rythme.","alt":"Je préfère travailler à mon propre rythme.","note":"à mon rythme 固定，rythme 前不加冠词。"}},
 "Le stationnement": {"pos":"n.m. 阳性名词，复数 stationnements","s":"停车；停放。指把车停在路边或停车场这件事，也指停车位的规定。常见标识：stationnement interdit（禁止停车）、stationnement payant（收费停车）。","ipa":"[sta.sjɔn.mɑ̃]","ph":"-tion- 在这里读 [sjɔn]（n 双写，所以 n 要发出来）；结尾 -ment 读鼻化音 [mɑ̃]，t 不发。","pi":"-ment 的 m、t 都不发音，只读 [mɑ̃]；不要把 stationnement 读成 station 加 ment 两个词。","et":"来自动词 stationner（停放），加后缀 -ment；stationner 来自 station（拉丁语 statio，「停留」）。","ex":[["Le stationnement est payant dans cette rue.","这条街停车收费。"],["Le stationnement est interdit devant l'école.","学校门口禁止停车。"],["Je cherche une place de stationnement.","我在找停车位。"]],"co":[["stationnement interdit","禁止停车"],["stationnement payant / gratuit","收费 / 免费停车"],["stationnement gênant","妨碍通行的违章停车"],["une place de stationnement","一个停车位"]],"sy":[["parking","courant","停车场（地方）；stationnement 更强调「停车这个行为 / 规定」"],["garage","courant","车库"]],"fq":"中高频，路牌和日常都常见。","me":"station（站）+ -nement：车停在「站」里。","tr":{"zh":"这里禁止停车。","fr":"Le stationnement est interdit ici.","alt":"On ne peut pas se garer ici.","note":"口语多用动词 se garer（停车）；stationnement 是名词，多见于标识。"}},
 "Le stockage": {"pos":"n.m. 阳性名词，复数 stockages","s":"存储；储存；仓储。可指货物仓储，也指电脑、手机的存储空间（espace de stockage）。","ipa":"[stɔ.kaʒ]","ph":"st- 连读开头 [st]；-ck- 读 [k]；-age 读 [aʒ]，e 不发。","pi":"-age 结尾读 [aʒ]（g 是 [ʒ]），不是 [g]；ck 只读一个 [k]。","et":"stock（存货，借自英语 stock）+ 动词 stocker + 后缀 -age（表示「行为」）。","ex":[["L'espace de stockage de mon téléphone est plein.","我手机的存储空间满了。"],["Ce hangar sert au stockage des meubles.","这个仓库用来存放家具。"]],"co":[["l'espace de stockage","存储空间"],["le stockage en ligne","在线存储（云存储）"],["la capacité de stockage","存储容量"],["un local de stockage","储物间 / 仓库"]],"sy":[["entreposage","soutenu","仓储、堆放货物，更书面"],["mémoire","courant","（设备的）内存或存储"]],"fq":"中频，科技和物流场合常用。","me":"stock + -age：把「存货」放起来的动作。","tr":{"zh":"我的电脑存储空间不够了。","fr":"Mon ordinateur n'a plus assez d'espace de stockage.","alt":"Je n'ai plus de place sur mon ordinateur.","note":"plus assez de + 名词：不再有足够的……"}},
 "Le surpoids": {"pos":"n.m. 阳性名词，单复数同形（des surpoids，但多用单数）","s":"超重；体重过重。常用 être en surpoids（超重）；比 obésité（肥胖）程度轻，是中性的医学 / 日常用语。","ipa":"[syʁ.pwa]","ph":"sur- 读 [syʁ]（u 是 [y]，嘴唇圆）；poids 读 [pwa]，结尾 -ds 不发音。","pi":"poids 的 -ds 完全不发；sur- 的 u 读 [y]，不是 [u]；r 是小舌音 [ʁ]。","et":"前缀 sur-（在……之上，过度）+ poids（重量）。同类构词：surcharge、surnom。","ex":[["Il souffre de surpoids depuis l'enfance.","他从小就超重。"],["Elle est en surpoids, mais elle fait du sport.","她有点超重，但她常运动。"]],"co":[["être en surpoids","超重"],["un problème de surpoids","超重问题"],["lutter contre le surpoids","对抗超重"]],"sy":[["obésité","courant","肥胖（更严重）"],["embonpoint","soutenu","发福，婉转说法"]],"fq":"中频，健康话题里常见。","me":"sur（超过）+ poids（重量）= 超出的重量。","tr":{"zh":"医生说他有点超重。","fr":"Le médecin dit qu'il est un peu en surpoids.","alt":"Le docteur dit qu'il a quelques kilos en trop.","note":"être en surpoids 是固定说法，介词用 en。"}},
 "Le trafic (routier, féroviaire, aérien)": {"pos":"n.m. 阳性名词，复数 trafics","s":"交通流量；运输量（公路 routier、铁路 ferroviaire、航空 aérien）。另一个常见义项是非法买卖：trafic de drogue（毒品贩运）。说「道路上的车流」时，口语也常用 circulation。","ipa":"[tʁa.fik]","ph":"tr- 接小舌音 [tʁ]；a [a]；f 只写一个；结尾 -c 读 [k]。","pi":"只有一个 f（英语 traffic 是两个 f）；结尾的 c 要读出来 [k]；「铁路」的正确拼写是 ferroviaire（两个 r）。","et":"借自意大利语 traffico。同族：trafiquant（贩子）、trafiquer（做非法买卖）。","ex":[["Le trafic routier est dense aujourd'hui.","今天公路交通很拥挤。"],["Le trafic ferroviaire est perturbé par la grève.","罢工扰乱了铁路运输。"],["Il a été arrêté pour trafic de drogue.","他因贩毒被捕。"]],"co":[["le trafic routier / aérien / ferroviaire","公路 / 航空 / 铁路交通"],["un trafic de drogue","毒品贩运"],["des informations sur le trafic","路况信息"],["le trafic est fluide / dense","车流顺畅 / 拥挤"]],"sy":[["circulation","courant","道路上的车流（最常用）"],["embouteillage","courant","堵车"],["commerce","courant","（合法）买卖，注意和非法的 trafic 区分"]],"fq":"中高频，新闻和路况里常见。","me":"只有一个 f，结尾读 [k]：车流和非法买卖都叫 trafic。","tr":{"zh":"早上八点路上车很多。","fr":"Il y a beaucoup de trafic à huit heures du matin.","alt":"Ça circule mal à huit heures du matin.","note":"beaucoup de + 名词，名词前不加冠词。"}},
 "Un archipel": {"pos":"n.m. 阳性名词，复数 archipels","s":"群岛；列岛。指一群彼此靠近的岛屿，如 l'archipel des Açores（亚速尔群岛）、l'archipel japonais（日本列岛）。","ipa":"[aʁ.ʃi.pɛl]","ph":"ar- [aʁ]；ch 在这里读 [ʃ]（不是 [k]）；-el 读 [ɛl]，l 要发出来。","pi":"ch 读 [ʃ]，不是 [k]（对比 archéologie 的 ch 读 [k]）；结尾 l 要发音；e 读 [ɛ]。","et":"来自意大利语 arcipelago，原指爱琴海，字面可理解为「主要的海」（希腊语 arkhi- 「首要」+ pelagos 「海」）。","ex":[["Le Japon est un archipel.","日本是一个群岛国家。"],["Les Açores forment un archipel dans l'Atlantique.","亚速尔群岛是大西洋上的一个群岛。"]],"co":[["un archipel d'îles","一串岛屿"],["l'archipel des Açores","亚速尔群岛"],["un archipel volcanique","火山群岛"]],"sy":[["îles","courant","岛屿（复数，更口语）"],["îlot","courant","小岛"]],"fq":"中低频，地理话题里出现。","me":"arc + pel：一串像弧形排开的岛。","tr":{"zh":"这个群岛有三十多个小岛。","fr":"Cet archipel compte plus de trente petites îles.","alt":"Cet archipel a plus de trente îlots.","note":"compter = 共有；plus de + 数字。"}},
 "Un bac": {"pos":"n.m. 阳性名词，复数 bacs","s":"三个常用义：1) 渡船（过河的平底小渡轮）；2) 盆、槽、格（如 bac à sable 沙坑、bac à légumes 冰箱蔬菜格）；3) 口语里 le bac = baccalauréat（高中毕业会考），非常常用。","ipa":"[bak]","ph":"b [b]；a [a]；结尾 c 读 [k]。","pi":"结尾 c 要读 [k]；bac 作「会考」时前面用 le bac，不要和渡船混淆，看语境。","et":"来源不确定（可能和荷兰语有关）；le bac 只是 baccalauréat 的缩写。","ex":[["Nous prenons le bac pour traverser la rivière.","我们坐渡船过河。"],["Les légumes sont dans le bac du frigo.","蔬菜在冰箱的格子里。"],["Elle a eu son bac avec mention.","她会考通过了，还拿了荣誉评语。"]],"co":[["prendre le bac","坐渡船"],["un bac à sable","沙坑"],["le bac à légumes","冰箱蔬菜格"],["passer / avoir son bac","参加 / 通过会考"]],"sy":[["ferry","courant","大型渡轮"],["baccalauréat","soutenu","bac 的全称"],["bateau","courant","船（泛指）"]],"fq":"高频，日常和教育话题里常见。","me":"短短一个 bac，三个意思：船、盆、会考。","tr":{"zh":"我孩子明年参加会考。","fr":"Mon fils passe son bac l'année prochaine.","alt":"Mon fils a le bac l'année prochaine.","note":"passer un examen = 参加考试；avoir = 通过。"}},
 "Un baromètre": {"pos":"n.m. 阳性名词，复数 baromètres","s":"气压计；晴雨表。比喻义很常用：指反映某种趋势的指标，如 baromètre de l'opinion（民意晴雨表）。","ipa":"[ba.ʁɔ.mɛtʁ]","ph":"ba [ba]；ro [ʁɔ]；mè 读 [mɛ]；-tre 读 [tʁ]，结尾 e 不发。","pi":"mè 带抑音，读 [ɛ]；-tre 在词尾要连读成 [tʁ]，不要在后面加元音；r 是小舌音。","et":"希腊语 baros（重量，压力）+ metron（测量）。同族后缀 -mètre：thermomètre（温度计）、kilomètre。","ex":[["Ce sondage est un baromètre de l'opinion publique.","这项民调是舆论的风向标。"],["Le baromètre baisse, il va pleuvoir.","气压计下降了，要下雨了。"]],"co":[["le baromètre baisse / monte","气压下降 / 上升"],["un baromètre de l'opinion","民意晴雨表"],["le baromètre du moral","士气指标"]],"sy":[["indicateur","courant","指标"],["thermomètre","courant","温度计；也有「反映温度」的比喻"]],"fq":"中低频，新闻和调查报告里会见到。","me":"baro（压力）+ mètre（测量）：测「压力」的仪器。","tr":{"zh":"这项调查是社会情绪的晴雨表。","fr":"Cette enquête est un baromètre de l'humeur des gens.","alt":"Cette enquête montre bien l'humeur des gens.","note":"un baromètre de + 名词：……的指标。"}},
 "Un beffroi": {"pos":"n.m. 阳性名词，复数 beffrois","s":"钟楼；市政厅钟楼。特别指法国北部和比利时城镇的市政钟楼，是城市自治的象征（如里尔、杜埃）。普通教堂的钟楼叫 clocher。","ipa":"[be.fʁwa]","ph":"be 读 [be]；ff 只读一个 [f]；oi 读 [wa]；复数 -s 不发音。","pi":"oi 读 [wa]；ff 只是一个 [f]；不要把 beffroi 和 clocher 混用。","et":"来自古法语 berfrei，源于日耳曼语。英语 belfry 是同源词。","ex":[["Le beffroi domine la place principale.","钟楼俯瞰主广场。"],["Le beffroi de Lille est très célèbre.","里尔的钟楼非常有名。"]],"co":[["le beffroi de la ville","城市钟楼"],["les cloches du beffroi","钟楼的钟"],["monter au beffroi","登上钟楼"]],"sy":[["clocher","courant","教堂钟楼"],["campanile","soutenu","意大利式独立钟楼"],["tour de l'horloge","courant","钟塔"]],"fq":"低频，旅游和历史话题里出现。","me":"beffroi 的结尾和 roi（国王）一样读 [wa]。","tr":{"zh":"我们爬上了城里的钟楼。","fr":"Nous sommes montés au beffroi de la ville.","alt":"On est monté au beffroi de la ville.","note":"monter 的复合时态用 être。"}},
 "Un bien": {"pos":"n.m. 阳性名词，复数 biens","s":"财产；物品；商品。le bien = 好处；les biens = 财物（biens immobiliers 不动产，biens de consommation 消费品）。注意它和副词 bien（好）形同。","ipa":"[bjɛ̃]","ph":"b [b]；ien 读鼻化音 [jɛ̃]，n 不发。","pi":"-ien 读 [jɛ̃]，不是 [jɛn]；名词 un bien 与副词 bien 同形，看前面有没有冠词。","et":"来自拉丁语 bene（好地）。同族：bienfait、bienvenue。","ex":[["Le logement est un bien essentiel.","住房是必需品。"],["Il a vendu tous ses biens avant de partir.","他走之前卖掉了所有财产。"],["Je veux le bien de mes enfants.","我希望孩子们好。"]],"co":[["un bien immobilier","不动产"],["les biens de consommation","消费品"],["un bien commun","公共福祉"],["vouloir le bien de quelqu'un","为某人好"]],"sy":[["propriété","courant","所有物、地产"],["patrimoine","soutenu","家产；遗产"],["possession","courant","拥有物"]],"fq":"极高频，副词 bien 更常见，名词用法也常见。","me":"un bien = 好东西，人们拥有的「好东西」。","tr":{"zh":"孩子们的幸福最重要。","fr":"Le bien de mes enfants est le plus important.","alt":"Mes enfants, c'est ce qui compte le plus pour moi.","note":"le bien de + 名词：……的利益、福祉。"}},
 "Un brumisateur": {"pos":"n.m. 阳性名词，复数 brumisateurs","s":"喷雾器；喷雾瓶。把水喷成细雾，夏天用来给脸降温，也用于喷植物。","ipa":"[bʁy.mi.za.tœʁ]","ph":"bru 读 [bʁy]（u 是 [y]）；mi [mi]；s 在元音间读 [z]；-eur 读 [œʁ]。","pi":"bru 的 u 读 [y]，不是 [ou]；中间的 s 读 [z]；-eur 读 [œʁ]，r 要发。","et":"brume（薄雾）+ -iser + -ateur：「把水变成雾的工具」。","ex":[["J'utilise un brumisateur pour me rafraîchir.","我用喷雾降温。"],["Elle met un brumisateur dans son sac en été.","夏天她包里放一个喷雾瓶。"]],"co":[["un brumisateur d'eau","水喷雾"],["se rafraîchir avec un brumisateur","用喷雾降温"],["un brumisateur pour plantes","植物喷雾壶"]],"sy":[["vaporisateur","courant","喷雾瓶（泛指，也喷香水）"],["atomiseur","courant","细雾喷瓶"]],"fq":"低频，夏天和美容话题里出现。","me":"brume（雾）+ 制造者 -isateur：造雾机。","tr":{"zh":"天太热了，我喷了点水雾。","fr":"Il fait trop chaud, j'ai utilisé mon brumisateur.","alt":"Il fait si chaud que j'ai sorti mon brumisateur.","note":"il fait chaud 表天气；trop + 形容词。"}},
 "Un cadre (travail)": {"pos":"n.m. 阳性名词，复数 cadres；指人时男女同形（un cadre / une cadre）","s":"管理人员；干部（企业里的中高层职员）。同一个词还有「画框；框架；背景」等义，dans le cadre de = 在……范围内。","ipa":"[kadʁ]","ph":"ca 读 [ka]；-dre 读 [dʁ]，结尾 e 不发。","pi":"结尾 -dre 是 [dʁ]，不是 [dɛ] 或 [dʁə]；a 读短 [a]。","et":"借自意大利语 quadro，源于拉丁语 quadrum（方形）：「方框」→「框架」→「骨干人员」。","ex":[["Mon père est cadre.","我爸爸是管理人员。"],["Elle est cadre dans une banque.","她在一家银行当管理人员。"],["Dans le cadre de ce projet, nous travaillons ensemble.","在这个项目框架内，我们一起工作。"]],"co":[["un cadre supérieur","高级管理人员"],["un cadre moyen","中层管理人员"],["dans le cadre de","在……范围内"],["un cadre photo","相框"]],"sy":[["manager","courant","管理者，偏英语化"],["dirigeant","courant","企业领导层"],["employé","courant","普通职员（对比）"]],"fq":"高频，工作和社会话题里常用。","me":"cadre = 框：框住团队的「骨干」。","tr":{"zh":"她在一家大公司当管理人员。","fr":"Elle est cadre dans une grande entreprise.","alt":"Elle est cadre dans une grosse boîte.","note":"说职业时不加冠词：elle est cadre。"}},
 "Un collectif": {"pos":"n.m. 阳性名词，复数 collectifs（形容词：collectif / collective）","s":"集体；团体；联盟（由一群人为共同目的组成，如 un collectif d'artistes）。比 association 更松散、更偏行动。也可作形容词：集体的。","ipa":"[kɔ.lɛk.tif]","ph":"co [kɔ]；ll 读单个 [l]；ct 读 [kt]；结尾 -if 读 [if]，f 要发。","pi":"ct 两个音都要读出来 [kt]；结尾 f 要发音；不要读成 collectio。","et":"来自拉丁语 colligere（收集在一起）。同族：collection、collecte、collectivité。","ex":[["Un collectif de citoyens a organisé la manifestation.","一群公民组织了这次游行。"],["Ce collectif défend les droits des locataires.","这个团体维护租户的权利。"]],"co":[["un collectif d'artistes","艺术家团体"],["un collectif citoyen","公民团体"],["les transports collectifs","公共交通"],["un travail collectif","集体工作"]],"sy":[["association","courant","协会（更正式）"],["groupe","courant","小组"],["équipe","courant","团队"]],"fq":"中频，新闻和社会议题里常见。","me":"collect-if：大家「收」在一起的一群人。","tr":{"zh":"这个团体帮助无家可归的人。","fr":"Ce collectif aide les personnes sans domicile.","alt":"Ce groupe aide les sans-abri.","note":"aider quelqu'un：aider 后直接接人。"}},
 "Un coût": {"pos":"n.m. 阳性名词，复数 coûts","s":"成本；费用；代价。指做一件事、买一样东西的花费，比 prix（价格）更偏总体花费，也可用于抽象的「代价」。","ipa":"[ku]","ph":"û 读 [u]（和 ou 同音）；结尾 t 不发音。","pi":"coût、coup（一击）、cou（脖子）全部读 [ku]，同音异义；结尾 t 不发；û 的帽子别漏。","et":"来自动词 coûter（值多少钱），源于拉丁语 constare。同族：coûteux（昂贵的）。","ex":[["Le coût de la vie a augmenté.","生活成本上升了。"],["Quel est le coût total des travaux ?","整个工程的总费用是多少？"]],"co":[["le coût de la vie","生活成本"],["un coût élevé / faible","高 / 低成本"],["le coût de production","生产成本"],["coûte que coûte","不惜一切代价"]],"sy":[["prix","courant","价格"],["frais","courant","各项开销（常用复数）"],["tarif","courant","收费标准"]],"fq":"高频，经济话题里常用。","me":"coût 里的 û：「值多少」，同音的 coup 是「一击」。","tr":{"zh":"这个项目的成本太高了。","fr":"Le coût de ce projet est trop élevé.","alt":"Ce projet coûte trop cher.","note":"coût 是名词，coûter 是动词，口语里更爱用动词。"}},
 "Un cycliste": {"pos":"n.m./n.f. 名词，男女同形（un cycliste / une cycliste），复数 cyclistes","s":"骑自行车的人；自行车运动员。男女同形，只改冠词。形容词也可用：une piste cyclable（自行车道）。","ipa":"[si.klist]","ph":"cy 读 [si]（c 在 y 前读 [s]，y 读 [i]）；cl 里 c 读 [k]；-iste 读 [ist]，结尾 e 不发。","pi":"第一个 c 读 [s]，第二个 c 读 [k]；y 读 [i]，不是 [j]；结尾 e 不发音。","et":"cycle（自行车，源自希腊语 kuklos「圆」）+ -iste（表示做某事的人）。","ex":[["Le cycliste porte un casque.","骑车人戴着头盔。"],["Une cycliste traverse la rue au feu rouge.","一位女骑车人在红灯时过马路。"],["Les cyclistes doivent respecter le code de la route.","骑车人必须遵守交通规则。"]],"co":[["une piste cyclable","自行车道"],["un casque de cycliste","骑行头盔"],["un cycliste professionnel","职业自行车运动员"]],"sy":[["coureur cycliste","courant","竞赛选手"],["motard","courant","骑摩托的人（对比）"]],"fq":"中高频，交通和运动话题里常用。","me":"cycle + -iste：和 pianiste、touriste 一样，男女同形。","tr":{"zh":"骑车人应该走自行车道。","fr":"Les cyclistes doivent rouler sur la piste cyclable.","alt":"Les cyclistes doivent prendre la piste cyclable.","note":"devoir + 动词原形。"}},
 "Un cyprès": {"pos":"n.m. 阳性名词，复数不变（des cyprès）","s":"柏树；柏木。法国南方、地中海地区很常见，常成排种在路边或墓园，细长挺拔。","ipa":"[si.pʁɛ]","ph":"cy 读 [si]；près 读 [pʁɛ]，è 读 [ɛ]，结尾 s 不发音。","pi":"结尾的 s 不发音（单复数同形，只看冠词）；y 读 [i]；è 要带抑音符。","et":"来自拉丁语 cupressus，源于希腊语。英语 cypress 同源。","ex":[["Les cyprès bordent le chemin.","柏树排列在小路两旁。"],["On voit des cyprès partout en Provence.","在普罗旺斯到处能看到柏树。"]],"co":[["une allée de cyprès","柏树大道"],["une haie de cyprès","柏树篱笆"],["un cimetière planté de cyprès","种满柏树的墓园"]],"sy":[["conifère","courant","针叶树（更大的类别）"],["thuya","courant","侧柏"]],"fq":"低频，景色和自然描写里出现。","me":"cyprès：细高像「手指」指向天空，s 不发音。","tr":{"zh":"农舍周围有一排柏树。","fr":"Il y a une rangée de cyprès autour de la ferme.","alt":"Des cyprès entourent la ferme.","note":"une rangée de + 名词：一排……"}},
 "Un déclic": {"pos":"n.m. 阳性名词，复数 déclics","s":"「咔嗒」一声；比喻义：顿悟，突然想通的那一刻。avoir un déclic = 突然开窍，有了转折。","ipa":"[de.klik]","ph":"dé 读 [de]；clic 读 [klik]，结尾 c 要发 [k]。","pi":"结尾 c 读 [k]；dé 是 [e]，不是 [ɛ]；别忘了 é 的重音。","et":"dé-（去除，解开）+ clic（模拟「咔嗒」的拟声词）：本来是「机关松开的声音」。","ex":[["J'ai eu un déclic en lisant ce livre.","读这本书时我突然开窍了。"],["On entend le déclic de l'appareil photo.","能听到相机的咔嗒声。"]],"co":[["avoir un déclic","突然开窍"],["provoquer un déclic","引发转变"],["le déclic de l'appareil photo","相机快门声"]],"sy":[["prise de conscience","courant","意识到"],["révélation","courant","顿悟"],["électrochoc","courant","（比喻）强烈的刺激"]],"fq":"中频，口语和写作里都有。","me":"「咔嗒」一声，脑子里的开关打开了。","tr":{"zh":"那天我突然明白了。","fr":"Ce jour-là, j'ai eu un déclic.","alt":"Ce jour-là, tout d'un coup, j'ai compris.","note":"avoir un déclic：过去时用 avoir 的复合过去式。"}},
 "Un déterminant": {"pos":"n.m. 阳性名词，复数 déterminants（形容词：déterminant / déterminante）","s":"决定因素；关键因素。语法里还指限定词（le、la、un、mon、ce 等）。作形容词：决定性的（un rôle déterminant）。","ipa":"[de.tɛʁ.mi.nɑ̃]","ph":"dé [de]；ter 读 [tɛʁ]；mi [mi]；ni [ni]；-ant 读鼻化音 [ɑ̃]，t 不发。","pi":"-ant 读 [ɑ̃]，结尾 t 不发；ter 里 e 读 [ɛ]；音节较长，要分段读。","et":"来自动词 déterminer（决定），源于拉丁语 determinare（划定界限）。","ex":[["Le salaire est un déterminant clé dans le choix d'un emploi.","工资是择业的关键因素。"],["« Le », « la » et « un » sont des déterminants.","le、la、un 是限定词。"]],"co":[["un déterminant clé / majeur","关键因素"],["un déterminant de la santé","健康的决定因素"],["un rôle déterminant","决定性的作用"],["un déterminant grammatical","语法限定词"]],"sy":[["facteur","courant","因素（更常用）"],["critère","courant","标准"],["paramètre","courant","参数、变量"]],"fq":"中低频，学术、统计和语法里常见。","me":"déterminer + -ant：「决定」的东西。","tr":{"zh":"价格是我们购买的关键因素。","fr":"Le prix est un déterminant clé de notre achat.","alt":"Le prix compte beaucoup dans notre achat.","note":"un déterminant de + 名词：……的决定因素。"}},
 "Un deux-roues": {"pos":"n.m. 阳性名词，单复数同形（des deux-roues）","s":"两轮车。统称自行车、摩托车、电动滑板车等。法语里是个固定合成词，带连字符。","ipa":"[dø.ʁu]","ph":"deux 读 [dø]，x 不发音；roues 读 [ʁu]，结尾 -es 不发。","pi":"roues [ʁu] 和 rues [ʁy]（街道）只差一个音：ou 对 u；deux 的 x 不发音。","et":"deux（二）+ roue（轮子，拉丁语 rota）。","ex":[["Il se déplace toujours en deux-roues.","他总是骑两轮车出行。"],["Il y a un parking pour les deux-roues.","这里有两轮车停车处。"]],"co":[["un deux-roues motorisé","机动两轮车"],["un deux-roues électrique","电动两轮车"],["un parking pour deux-roues","两轮车停车场"]],"sy":[["vélo","courant","自行车"],["moto","courant","摩托车"],["scooter","courant","踏板摩托"]],"fq":"中频，城市交通话题里常见。","me":"deux + roues = 二 + 轮，字面就是答案。","tr":{"zh":"在巴黎我常骑两轮车上班。","fr":"À Paris, je vais souvent au travail en deux-roues.","alt":"À Paris, je vais au boulot à vélo ou en scooter.","note":"en + 交通工具：en deux-roues。"}},
 "Un drame": {"pos":"n.m. 阳性名词，复数 drames","s":"悲剧；惨事；戏剧（正剧）。日常多指不幸的事件。口语里 faire un drame de qqch = 小题大做；ce n'est pas un drame = 没什么大不了。","ipa":"[dʁam]","ph":"dr 接小舌音 [dʁ]；a [a]；m [m]，结尾 e 不发音。","pi":"只有一个音节 [dʁam]，结尾 e 不发音；注意重音在尾，别读成 drama 三个音节。","et":"来自希腊语 drama（行动，演出），经拉丁语传入。英语 drama 同源，但法语 drame 常有「悲惨」的意味。","ex":[["Il a eu un accident, c'est un vrai drame !","他出了事故，真是悲剧！"],["Ce n'est pas un drame, on recommence.","没什么大不了，重来一次。"],["Ce film est un drame familial.","这部电影是家庭剧。"]],"co":[["un drame familial","家庭悲剧 / 家庭剧"],["tourner au drame","变成悲剧"],["ce n'est pas un drame","没什么大不了"],["faire un drame de tout","什么事都小题大做"]],"sy":[["tragédie","soutenu","悲剧（更严重）"],["catastrophe","courant","灾难"],["faire tout un cinéma","familier","小题大做，夸张反应"]],"fq":"高频，新闻和口语里都常用。","me":"drame：一个音节，比 drama 短，悲惨感更强。","tr":{"zh":"别小题大做，这不算什么大事。","fr":"N'en fais pas un drame, ce n'est pas grave.","alt":"Fais pas un drame, c'est pas grave.","note":"n'en fais pas un drame：en 指代前面说的事；否定命令式。"}},
 "Un échafaudage": {"pos":"n.m. 阳性名词，复数 échafaudages","s":"脚手架。建筑工地上给工人站立的金属或木架。动词 échafauder 也有比喻义：搭建、构想（échafauder un plan = 精心策划一个计划）。","ipa":"[e.ʃa.fo.daʒ]","ph":"é [e]；ch 读 [ʃ]；fa [fa]；au 读 [o]；-age 读 [aʒ]。","pi":"ch 读 [ʃ]；au 读 [o]，不是 [au]；-age 读 [aʒ]，e 不发。词较长，分四段读。","et":"échafaud（脚手架，旧义也指断头台、刑台）+ -age。同族：échafauder。","ex":[["Les ouvriers travaillent sur l'échafaudage.","工人们在脚手架上工作。"],["Ils montent un échafaudage devant la façade.","他们在外墙前搭脚手架。"]],"co":[["monter / démonter un échafaudage","搭 / 拆脚手架"],["un échafaudage métallique","金属脚手架"],["échafauder un plan","精心策划一个计划"]],"sy":[["échafaud","soutenu","旧称；今天多指断头台"],["nacelle","courant","升降吊篮（对比）"]],"fq":"低频，施工和工地话题里出现。","me":"échafaud + age：搭起来的「架」。","tr":{"zh":"他们在大楼前搭脚手架。","fr":"Ils montent un échafaudage devant l'immeuble.","alt":"Ils installent un échafaudage devant le bâtiment.","note":"monter 在这里是及物动词：搭起。"}},
 "Un édifice": {"pos":"n.m. 阳性名词，复数 édifices","s":"大型建筑；宏伟的建筑物（教堂、宫殿、政府大楼等）。比 bâtiment 更庄重、更有分量。也可比喻：l'édifice social（社会结构）。","ipa":"[e.di.fis]","ph":"é [e]；di [di]；fi [fi]；-ce 读 [s]，e 不发。","pi":"结尾 -ce 读 [s]，不是 [k]；第一个 é 要读 [e]。","et":"来自拉丁语 aedificium（建筑物），aedificare（建造）。英语 edifice、edify 同源。","ex":[["Cet édifice date du 18ème siècle.","这座建筑建于十八世纪。"],["La cathédrale est un édifice gothique.","大教堂是一座哥特式建筑。"]],"co":[["un édifice public","公共建筑"],["un édifice religieux","宗教建筑"],["un édifice imposant","雄伟的建筑"],["l'édifice social","社会结构"]],"sy":[["bâtiment","courant","建筑（最通用）"],["immeuble","courant","多层楼房"],["monument","courant","纪念性建筑"]],"fq":"中低频，偏书面。","me":"édifice：édifier（建造）→ 建好的大楼。","tr":{"zh":"这座大教堂是十二世纪的建筑。","fr":"Cette cathédrale est un édifice du douzième siècle.","alt":"Cette cathédrale date du douzième siècle.","note":"世纪用序数词：du douzième siècle。"}},
 "Un engin": {"pos":"n.m. 阳性名词，复数 engins","s":"机械；装置；工程车辆。多指有点大的机器，如 engin de chantier（工程机械）、engin explosif（爆炸装置）。口语里 un drôle d'engin = 一个怪玩意。","ipa":"[ɑ̃.ʒɛ̃]","ph":"en 读鼻化 [ɑ̃]；gin 读 [ʒɛ̃]，g 在 i 前读 [ʒ]，in 读鼻化 [ɛ̃]，n 都不发。","pi":"两个鼻化元音：en [ɑ̃] 与 in [ɛ̃] 要分清；g 读 [ʒ]；不要读成 [ɑ̃ɡin]。","et":"来自拉丁语 ingenium（才智，巧思），后来指「巧妙的机器」。与 ingénieur 同源。","ex":[["C'est un engin très bruyant.","这是个很吵的装置。"],["Les engins de chantier arrivent à huit heures.","工程机械八点到。"]],"co":[["un engin de chantier","工程机械"],["un engin explosif","爆炸装置"],["un engin spatial","航天器"],["un engin de levage","起重设备"]],"sy":[["machine","courant","机器"],["appareil","courant","设备、器具"],["véhicule","courant","车辆"]],"fq":"中频，施工、新闻中常见。","me":"engin 和 ingénieur 同根：「工程师」造出来的东西。","tr":{"zh":"这台机器太吵了。","fr":"Cet engin est beaucoup trop bruyant.","alt":"Cette machine fait trop de bruit.","note":"engin 阳性，用 cet（元音前的 ce）。"}},
 "Un facteur": {"pos":"n.m. 阳性名词，复数 facteurs；邮递员阴性 la factrice","s":"两个义项：1) 因素；2) 邮递员（le facteur，女性 la factrice）。第一义用于 un facteur de risque / de réussite。","ipa":"[fak.tœʁ]","ph":"fa [fa]；c 和 t 都读，ct = [kt]；-eur 读 [œʁ]，r 要发。","pi":"ct 要读 [kt]；-eur 读 [œʁ]，不是 [ɔʁ]；别把 facteur 和英语 factor 混读。","et":"来自拉丁语 factor（制造者），源于 facere（做）。「做事的人」→「因素」；「送信的人」。","ex":[["Le travail est un facteur d'autonomie.","工作是自主性的一个因素。"],["Le facteur apporte le courrier à dix heures.","邮递员十点送信。"],["Le stress est un facteur de risque.","压力是风险因素。"]],"co":[["un facteur de risque","风险因素"],["un facteur clé","关键因素"],["le facteur humain","人为因素"],["le facteur est passé","邮递员来过了"]],"sy":[["élément","courant","要素"],["paramètre","courant","参数、变量"],["postier","courant","邮政工作人员（更宽泛）"]],"fq":"高频，两个意思都常用。","me":"facteur = fac(t)（做）+ -teur：做事的人，送信的人。","tr":{"zh":"睡眠是健康的重要因素。","fr":"Le sommeil est un facteur important de la santé.","alt":"Bien dormir, c'est important pour la santé.","note":"un facteur de + 名词（无冠词）：……的因素。"}},
 "Un grimpeur": {"pos":"n.m. 阳性名词，阴性 grimpeuse，复数 grimpeurs","s":"攀登者；爬山者；攀岩者。在环法自行车赛里，un grimpeur 是擅长爬坡的车手。","ipa":"[gʁɛ̃.pœʁ]","ph":"gr [gʁ]（g 读 [g]）；im 读鼻化 [ɛ̃]；p 要读 [p]；-eur 读 [œʁ]。","pi":"grimper 里的 p 要发音（对比 temps、compter）；g 读 [g]，不是 [k]；-eur 读 [œʁ]。","et":"来自动词 grimper（攀爬）+ -eur（做某事的人）。","ex":[["Ce grimpeur est très expérimenté.","这位攀登者经验丰富。"],["Dans le Tour de France, les grimpeurs aiment les cols.","在环法赛中，爬坡手喜欢山口。"]],"co":[["un grimpeur expérimenté","经验丰富的攀登者"],["un bon grimpeur","爬坡高手"],["un grimpeur de haut niveau","高水平攀登者"]],"sy":[["alpiniste","courant","登山者"],["varappeur","courant","攀岩者（岩壁）"]],"fq":"中低频，运动话题里出现。","me":"grimper + -eur：爬的人。","tr":{"zh":"这位攀登者每个周末都去爬山。","fr":"Ce grimpeur va en montagne tous les week-ends.","alt":"Ce grimpeur part en montagne chaque week-end.","note":"aller en montagne：去山里，用 en。"}},
 "Un îlot": {"pos":"n.m. 阳性名词，复数 îlots","s":"小岛。比喻义：一小块与周围不同的区域，如 un îlot de verdure（一片绿地）、l'îlot de chaleur urbain（城市热岛）；厨房里的 îlot central 是中岛。","ipa":"[i.lo]","ph":"î 读 [i]（帽子不改音）；lo [lo]；结尾 t 不发。","pi":"结尾 t 不发音；î 的帽子表示以前有个 s（île 同理）；别读成 [ilɔt]。","et":"île（岛，拉丁语 insula）+ 指小后缀 -ot：「小岛」。","ex":[["Ils ont nagé jusqu'à l'îlot.","他们游到了小岛。"],["Ce parc est un îlot de verdure en ville.","这个公园是城市里的一片绿洲。"]],"co":[["un îlot de verdure","一片绿地"],["un îlot rocheux","岩石小岛"],["un îlot de chaleur urbain","城市热岛"],["un îlot central","（厨房）中岛"]],"sy":[["île","courant","岛（更大）"],["îlet","courant","小岛（海外省常用）"]],"fq":"中低频，地理和城市话题里出现。","me":"île + ot：île 的「小号」。","tr":{"zh":"这座城市里有几片小绿地。","fr":"Il y a quelques îlots de verdure dans cette ville.","alt":"Cette ville a quelques petits coins de verdure.","note":"quelques + 复数名词。"}},
 "Un incident": {"pos":"n.m. 阳性名词，复数 incidents","s":"事件；小故障；插曲。多指不太严重的意外或问题，如 incident technique（技术故障）、incident diplomatique（外交事件）。比 accident 轻。","ipa":"[ɛ̃.si.dɑ̃]","ph":"in 读鼻化 [ɛ̃]；ci 读 [si]（c 在 i 前读 [s]）；-dent 读 [dɑ̃]，ent 读鼻化。","pi":"结尾 -ent 读 [ɑ̃]，t 不发；in 是 [ɛ̃]，不是 [in]；c 读 [s]。","et":"来自拉丁语 incidens（落到……上），incidere。英语 incident 同源。","ex":[["Un incident technique a retardé le train.","技术故障耽误了火车。"],["Il n'y a eu aucun incident pendant le match.","比赛期间没有发生任何意外。"]],"co":[["un incident technique","技术故障"],["un incident diplomatique","外交事件"],["un incident de parcours","小插曲、小挫折"],["l'incident est clos","事情到此为止"]],"sy":[["événement","courant","事件（中性）"],["accident","courant","事故（更严重）"],["problème","courant","问题"]],"fq":"中高频，新闻和日常都常用。","me":"in + cid（落下）+ ent：「落到你头上」的小事。","tr":{"zh":"昨天晚上发生了一件小事。","fr":"Un petit incident s'est produit hier soir.","alt":"Il y a eu un petit incident hier soir.","note":"se produire = 发生；il y a eu 更口语。"}},
 "Un instant": {"pos":"n.m. 阳性名词，复数 instants","s":"片刻；一瞬间。Un instant ! = 等一下！à l'instant = 刚才 / 马上；pour l'instant = 目前。比 moment 更短、更强调短暂。","ipa":"[ɛ̃.stɑ̃]","ph":"in 读鼻化 [ɛ̃]，然后 s 单独读 [s]；tant 读 [tɑ̃]，结尾 t 不发。","pi":"in 与 s 之间不连成 [ins]，是 [ɛ̃] + [stɑ̃]；结尾 t 不发音。","et":"来自拉丁语 instans（紧迫的，当下的），instare（逼近）。","ex":[["Attendez un instant, s'il vous plaît.","请稍等。"],["Je l'ai vu à l'instant.","我刚刚看见他。"],["Pour l'instant, tout va bien.","目前一切顺利。"]],"co":[["un instant !","等一下！"],["à l'instant","刚才 / 立刻"],["pour l'instant","目前"],["en un instant","转眼之间"]],"sy":[["moment","courant","时刻、片刻"],["seconde","courant","一会儿（Une seconde !）"],["minute","courant","一分钟、一会儿"]],"fq":"极高频，日常常用。","me":"instant：in + stant（站着）：时间「站」着不动的一瞬。","tr":{"zh":"请等一下，我马上回来。","fr":"Un instant, je reviens tout de suite.","alt":"Une seconde, je reviens.","note":"tout de suite = 马上。"}},
 "Un investissement": {"pos":"n.m. 阳性名词，复数 investissements","s":"投资；投入。可以是金钱，也可以是时间、精力。un bon investissement = 划算的投入。动词：investir。","ipa":"[ɛ̃.vɛs.tis.mɑ̃]","ph":"in [ɛ̃]；ves [vɛs]；tis 读 [tis]；-ment 读 [mɑ̃]。ss 读 [s]。","pi":"中间有 -iss-（来自 investir 的变位词干）；-ment 的 t 不发；in 读 [ɛ̃]。词长，要分段读。","et":"动词 investir + -issement（-ir 动词名词化）。英语 investment 有 invest，法语多一个 -iss-。","ex":[["Acheter une maison est un bon investissement.","买房是个不错的投资。"],["Ce projet demande un gros investissement.","这个项目需要大量投入。"]],"co":[["faire un investissement","做一笔投资"],["un investissement rentable","有利可图的投资"],["un investissement immobilier","房地产投资"],["un investissement à long terme","长期投资"]],"sy":[["placement","courant","理财投资（存款、基金）"],["dépense","courant","花费（对比）"],["mise de fonds","soutenu","出资"]],"fq":"中高频，经济话题里常用。","me":"invest + -iss- + -ement：记住中间多出来的 iss。","tr":{"zh":"学外语是对未来的投资。","fr":"Apprendre une langue est un investissement pour l'avenir.","alt":"Apprendre une langue, c'est un bon investissement pour plus tard.","note":"apprendre 后接直接宾语；un investissement pour l'avenir。"}},
 "Un ménage": {"pos":"n.m. 阳性名词，复数 ménages","s":"家庭；住户（统计里的家庭单位）。faire le ménage = 做家务 / 打扫；femme de ménage = 家政阿姨；un jeune ménage = 年轻夫妇。","ipa":"[me.naʒ]","ph":"mé 读 [me]；na 读 [na]；-ge 读 [ʒ]。","pi":"mé 是 [e]，不是 [ɛ]；-age 读 [aʒ]，不读 [ɑʒ]；ménage 不是英语 menage，意思很具体。","et":"来自古法语 mesnage，源于拉丁语 mansio（住所）。与 maison（房子）同源。","ex":[["Ce quartier accueille des ménages aisés.","这个街区住着富裕家庭。"],["Je fais le ménage tous les samedis.","我每个周六打扫卫生。"],["Les ménages dépensent plus en énergie.","家庭的能源开支更多了。"]],"co":[["faire le ménage","打扫卫生 / 做家务"],["une femme de ménage","家政女工"],["un jeune ménage","年轻夫妇"],["une scène de ménage","夫妻吵架"]],"sy":[["foyer","courant","家庭、住户"],["famille","courant","家庭"],["tâches ménagères","courant","家务活"]],"fq":"高频，家庭、统计、日常都常见。","me":"ménage 与 maison 同源：同一屋檐下的人。","tr":{"zh":"周末我们一起做家务。","fr":"Le week-end, nous faisons le ménage ensemble.","alt":"Le week-end, on fait le ménage à deux.","note":"faire le ménage：打扫，用 faire。"}},
 "Un moteur": {"pos":"n.m. 阳性名词，复数 moteurs","s":"发动机；马达；比喻义：推动力。moteur de recherche = 搜索引擎；le moteur de la croissance = 增长的动力。","ipa":"[mɔ.tœʁ]","ph":"mo 读 [mɔ]；-teur 读 [tœʁ]，eu 读 [œ]，r 要发。","pi":"-eur 读 [œʁ]，不是 [ɔʁ]；o 读开口 [ɔ]；别把 moteur 和 motor 的英语读音混读。","et":"来自拉丁语 motor（推动者），源于 movere（移动）。同族：mouvement、moto。","ex":[["Le moteur de ma voiture est en panne.","我的车发动机坏了。"],["Je tape ma question dans un moteur de recherche.","我把问题输入搜索引擎。"]],"co":[["démarrer le moteur","发动引擎"],["un moteur électrique","电动机"],["un moteur de recherche","搜索引擎"],["une panne de moteur","发动机故障"]],"sy":[["machine","courant","机器"],["réacteur","courant","喷气发动机"]],"fq":"高频，汽车和科技话题常用。","me":"moteur ← movere（动）：让东西「动」起来的东西。","tr":{"zh":"发动机一直有怪声。","fr":"Le moteur fait un bruit bizarre depuis ce matin.","alt":"Le moteur fait un drôle de bruit.","note":"faire un bruit：发出声响。"}},
 "Un obstacle": {"pos":"n.m. 阳性名词，复数 obstacles","s":"障碍；阻碍；障碍物。可以是具体的（路上的障碍），也可以是抽象的（困难）。faire obstacle à = 阻碍。","ipa":"[ɔp.stakl]","ph":"ob 在 s 前读 [p]：[ɔp]；sta 读 [sta]；-cle 读 [kl]，e 不发。","pi":"ob 在 s 前变成 [p]；结尾 -cle 是 [kl]，e 不发；重音在尾，别读成三个音节。","et":"来自拉丁语 obstaculum，源于 obstare（挡在前面）。英语 obstacle 同源。","ex":[["Il a dû surmonter de nombreux obstacles.","他不得不克服很多障碍。"],["La langue n'est pas un obstacle pour elle.","语言对她不是障碍。"]],"co":[["surmonter un obstacle","克服障碍"],["se heurter à un obstacle","遇到阻碍"],["une course d'obstacles","障碍赛"],["faire obstacle à","阻碍"]],"sy":[["difficulté","courant","困难"],["barrière","courant","障碍、屏障"],["frein","courant","（比喻）阻碍"]],"fq":"高频，日常和书面都常用。","me":"ob-（对着）+ stare（站）：站在你面前的东西。","tr":{"zh":"最大的障碍是时间。","fr":"Le plus grand obstacle est le temps.","alt":"Le plus gros problème, c'est le temps.","note":"le plus grand + 名词：最大的……"}},
 "Un passage": {"pos":"n.m. 阳性名词，复数 passages","s":"通道；经过；段落。le passage 可指路、通路，也指文中的一段（un passage d'un livre）。être de passage = 路过、短暂停留；au passage = 顺便。","ipa":"[pa.saʒ]","ph":"pa [pa]；ss 读 [s]（双 s 读 [s]，单 s 在元音间读 [z]）；-age 读 [aʒ]。","pi":"双写的 ss 读 [s]；-age 读 [aʒ]；不要读成 [pasaʒe]。","et":"来自动词 passer + -age；passer 源于拉丁语 passus（步）。","ex":[["Le passage est interdit aux piétons.","行人禁止通行。"],["Je suis de passage à Paris.","我在巴黎只是路过。"],["Relis ce passage du texte.","再读一遍文中这一段。"]],"co":[["un passage souterrain","地下通道"],["un passage à niveau","铁路道口"],["être de passage","路过、短暂停留"],["au passage","顺便"]],"sy":[["couloir","courant","走廊"],["traversée","courant","穿越"],["extrait","courant","（文本）节选"]],"fq":"高频，日常常用。","me":"passer + -age：「经过」的地方。","tr":{"zh":"这里是行人的通道。","fr":"C'est un passage pour les piétons.","alt":"Ici, c'est un passage réservé aux piétons.","note":"un passage pour + 名词：给……用的通道。"}},
 "Un passage piéton": {"pos":"n.m. 阳性名词，复数 passages piétons","s":"人行横道；斑马线。更口语的说法是 passage clouté，官方标识多用 passage pour piétons。","ipa":"[pa.saʒ pje.tɔ̃]","ph":"passage 读 [pa.saʒ]；piéton 读 [pje.tɔ̃]，ié 读 [je]，-on 读鼻化 [ɔ̃]。","pi":"ié 是 [je]；piéton 的 -on 读鼻化，n 不发；ss 读 [s]，-age 读 [aʒ]。","et":"passage（通道）+ piéton（行人），并列组成的复合名词。","ex":[["Il faut traverser sur le passage piéton.","必须在人行横道上过马路。"],["La voiture s'arrête devant le passage piéton.","汽车停在人行横道前。"]],"co":[["traverser sur le passage piéton","在斑马线上过马路"],["un passage piéton surélevé","凸起的人行横道"],["s'arrêter au passage piéton","在人行横道前停下"]],"sy":[["passage clouté","courant","斑马线（传统说法）"],["passage pour piétons","courant","人行横道（标识用语）"]],"fq":"中频，交通话题里常见。","me":"passage + piéton：行人的通道。","tr":{"zh":"请在人行横道上过马路。","fr":"Traversez sur le passage piéton, s'il vous plaît.","alt":"Traverse sur le passage piéton.","note":"命令式 traversez（您）/ traverse（你）。"}},
 "Un passant": {"pos":"n.m. 阳性名词，阴性 passante，复数 passants","s":"路人；行人。指走在街上、路过的人，是动词 passer 的现在分词名词化。une rue passante = 人流多的街道。","ipa":"[pa.sɑ̃]","ph":"pa [pa]；ss 读 [s]；-ant 读鼻化 [ɑ̃]，t 不发音。","pi":"结尾 -ant 读 [ɑ̃]，t 不发；别和 passager（乘客）混淆；ss 读 [s]。","et":"来自 passer（经过）的现在分词 passant，名词化。","ex":[["Il a demandé l'heure à un passant.","他向一位路人问时间。"],["Les passants se pressent sous la pluie.","路人在雨中匆匆走过。"]],"co":[["demander à un passant","问路人"],["une rue passante","人来人往的街道"],["un simple passant","一个普通路人"],["les passants pressés","匆忙的路人"]],"sy":[["piéton","courant","行人（强调步行）"],["badaud","courant","围观闲逛的人"],["promeneur","courant","散步的人"]],"fq":"中频，街头场景里常见。","me":"passer + -ant：正在「经过」的人。","tr":{"zh":"我向一个路人问路。","fr":"J'ai demandé mon chemin à un passant.","alt":"J'ai demandé la route à quelqu'un dans la rue.","note":"demander à quelqu'un：向某人问，用 à。"}},
 "Un pêcheur": {"pos":"n.m. 阳性名词，阴性 pêcheuse，复数 pêcheurs","s":"渔夫；钓鱼的人。职业渔民或垂钓爱好者都可以。注意：pécheur（罪人）读音和写法只差一个重音符。","ipa":"[pɛ.ʃœʁ]","ph":"pê 读 [pɛ]（ê 读 [ɛ]）；ch 读 [ʃ]；-eur 读 [œʁ]。","pi":"pêcheur [pɛʃœʁ]（渔夫）与 pécheur [peʃœʁ]（罪人）只差一个元音；pêche 还有「桃子」的意思。","et":"来自动词 pêcher（捕鱼）+ -eur；pêcher 源于拉丁语 piscari，同族 poisson。罪人 pécheur 来自 péché。","ex":[["Le pêcheur a attrapé un gros poisson.","渔夫钓到一条大鱼。"],["Mon grand-père est pêcheur à la ligne.","我爷爷喜欢垂钓。"]],"co":[["un pêcheur à la ligne","钓鱼爱好者"],["un village de pêcheurs","渔村"],["un bateau de pêcheur","渔船"]],"sy":[["marin-pêcheur","courant","职业渔民"],["pécheur","courant","罪人（别混淆）"]],"fq":"中频，海边和日常话题里常用。","me":"pêche 有两个意思：桃子和捕鱼；pêcheur 抓鱼。","tr":{"zh":"渔夫清晨就出海了。","fr":"Le pêcheur est parti en mer très tôt ce matin.","alt":"Le pêcheur est parti en mer à l'aube.","note":"partir 的复合时态用 être。"}},
 "Un piéton": {"pos":"n.m. 阳性名词，阴性 piétonne，复数 piétons","s":"行人；步行者。形容词 piéton / piétonne：步行的（une rue piétonne = 步行街，zone piétonne = 步行区）。","ipa":"[pje.tɔ̃]","ph":"pié 读 [pje]（i + é 连成 [je]）；ton 读鼻化 [tɔ̃]，n 不发音。","pi":"ié 是 [je]，不是两个音节；-on 读 [ɔ̃]，n 不发；注意是 piéton，不是 pitone。","et":"来自 pied（脚，拉丁语 pes, pedis）+ 后缀 -on：「用脚走的人」。","ex":[["La rue est réservée aux piétons.","这条街仅限行人。"],["Le piéton attend le feu vert.","行人在等绿灯。"]],"co":[["un passage piéton","人行横道"],["une zone piétonne","步行区"],["une rue piétonne","步行街"],["la priorité aux piétons","行人优先"]],"sy":[["passant","courant","路人"],["promeneur","courant","散步者"],["usager","courant","（交通）使用者"]],"fq":"中高频，城市交通话题常用。","me":"pied（脚）+ -on：用脚走的人。","tr":{"zh":"行人应该走人行道。","fr":"Les piétons doivent marcher sur le trottoir.","alt":"Les piétons marchent sur le trottoir.","note":"devoir + 动词原形。"}},
 "Un platane": {"pos":"n.m. 阳性名词，复数 platanes","s":"梧桐树（法国梧桐，悬铃木）。法国街道和广场上最常见的行道树，夏天提供大片树荫。","ipa":"[pla.tan]","ph":"pla 读 [pla]；ta 读 [ta]；n 要发 [n]；结尾 e 不发。","pi":"结尾 -ane 读 [an]，n 要发出来；不要读成鼻化的 [ɑ̃]。","et":"来自拉丁语 platanus，源于希腊语 platanos（可能与「宽」platus 有关，指宽大的叶子）。","ex":[["Les platanes offrent beaucoup d'ombre.","梧桐树提供大片荫凉。"],["Nous mangeons sous un vieux platane.","我们在一棵老梧桐树下吃饭。"]],"co":[["une allée de platanes","梧桐大道"],["l'ombre des platanes","梧桐树荫"],["un platane centenaire","百年梧桐"]],"sy":[["marronnier","courant","七叶树，常被误认"],["tilleul","courant","椴树"],["arbre","courant","树（泛指）"]],"fq":"低频，南法风景和自然话题里常见。","me":"platane 像 plat（扁平）+ ane：叶子又大又平。","tr":{"zh":"夏天我们在梧桐树下乘凉。","fr":"En été, nous nous reposons à l'ombre des platanes.","alt":"L'été, on se repose sous les platanes.","note":"à l'ombre de + 名词：在……的荫下。"}},
 "Un souffle": {"pos":"n.m. 阳性名词，复数 souffles","s":"呼吸；气息；一阵风；爆炸的冲击波。avoir du souffle = 气足；être à bout de souffle = 喘不过气；retrouver son souffle / un second souffle = 缓过气 / 重新来劲。","ipa":"[sufl]","ph":"sou 读 [su]；ffle 读 [fl]，结尾 e 不发。","pi":"ou 读 [u]；ffle 读 [fl]，要快速带过；单音节，e 不发。","et":"来自动词 souffler（吹），源于拉丁语 sufflare。","ex":[["Le coureur a retrouvé un second souffle.","跑步者找回了第二口气。"],["Je suis à bout de souffle.","我喘不过气了。"],["Il n'y a pas un souffle de vent.","一丝风都没有。"]],"co":[["reprendre son souffle","喘口气"],["retenir son souffle","屏住呼吸"],["à bout de souffle","上气不接下气"],["un second souffle","第二口气 / 重获活力"]],"sy":[["respiration","courant","呼吸"],["haleine","courant","口中呼出的气"],["brise","courant","微风"]],"fq":"中频，运动和描写里常见。","me":"souffle：souffler（吹）的名词，像吹出的一口气。","tr":{"zh":"跑完步，我需要喘口气。","fr":"Après la course, j'ai besoin de reprendre mon souffle.","alt":"Après la course, je dois reprendre mon souffle.","note":"avoir besoin de + 动词原形。"}},
 "Un sparadrap": {"pos":"n.m. 阳性名词，复数 sparadraps","s":"医用胶布；创可贴。严格说 sparadrap 是卷状或条状的胶布，有纱布垫的创可贴更常叫 pansement。口语里常把二者混用。","ipa":"[spa.ʁa.dʁa]","ph":"sp- 开头 [sp]；pa [spa]；ra [ʁa]；drap 读 [dʁa]，p 不发音。","pi":"结尾 p 不发（和 drap 一样）；sp- 开头辅音连读，不要在 s 和 p 之间加元音。","et":"来源不确定（中世纪拉丁语 sparadrapum）。末尾 -drap 与 drap（布）形似，只作记忆辅助，不当词源。","ex":[["J'ai mis un sparadrap sur ma coupure.","我在伤口上贴了创可贴。"],["Il faut arracher le sparadrap doucement.","撕胶布要慢慢撕。"]],"co":[["mettre un sparadrap","贴创可贴"],["arracher un sparadrap","撕下胶布"],["un rouleau de sparadrap","一卷胶布"]],"sy":[["pansement","courant","敷料、创可贴（更常用）"],["pansement adhésif","courant","自粘创可贴"]],"fq":"中低频，急救话题里出现。","me":"sparadrap：末尾 p 不发，像 drap（床单）。","tr":{"zh":"给我一张创可贴好吗？","fr":"Tu peux me donner un sparadrap, s'il te plaît ?","alt":"Tu as un pansement ?","note":"pouvoir + 动词原形，礼貌请求。"}},
 "Un square": {"pos":"n.m. 阳性名词，复数 squares","s":"街心小公园；社区小花园。注意：法语的 square 是有长椅、儿童游乐设施的小绿地，不是英语里的「正方形」（carré）或「广场」（place）。","ipa":"[skwaʁ]","ph":"sq 读 [sk]；ua 读 [wa]；r 读 [ʁ]，结尾 e 不发。","pi":"r 要发小舌音 [ʁ]；qu 在这里读 [kw]；不要读成英语 [skwɛə]。","et":"借自英语 square（19 世纪），原为英国伦敦的城市广场；在法语里意思缩小成「小花园」。","ex":[["Les enfants jouent dans le square du quartier.","孩子们在街区小公园玩。"],["Il y a des bancs et un toboggan dans ce square.","这个小公园里有长椅和滑梯。"]],"co":[["le square du quartier","街区小公园"],["aller au square","去小公园"],["un square avec des jeux pour enfants","带儿童游乐设施的小公园"]],"sy":[["parc","courant","公园（更大）"],["jardin public","courant","公共花园"],["place","courant","广场（对比）"]],"fq":"中频，城市生活里常用。","me":"square：有长椅、有滑梯的一小片绿。","tr":{"zh":"放学后我们去小公园玩。","fr":"Après l'école, nous allons jouer au square.","alt":"Après l'école, on va au square.","note":"aller au square：à + le = au。"}},
 "Un surnom": {"pos":"n.m. 阳性名词，复数 surnoms","s":"绰号；外号；昵称。可以是亲切的，也可以是调侃的。donner un surnom à qqn = 给某人起外号。","ipa":"[syʁ.nɔ̃]","ph":"sur 读 [syʁ]（u 读 [y]）；nom 读鼻化 [nɔ̃]，m 不发音。","pi":"nom 的 -om 读鼻化 [ɔ̃]，m 不发；sur 的 u 读 [y]；别把它和 prénom（名）混淆。","et":"前缀 sur-（在……之上，附加）+ nom（名字）：「附加的名字」。","ex":[["Ses amis lui ont donné un surnom amusant.","朋友们给他起了个有趣的绰号。"],["Son surnom, c'est « Petit Loup ».","他的外号是「小狼」。"]],"co":[["donner un surnom à quelqu'un","给某人起外号"],["un surnom affectueux","亲切的昵称"],["porter le surnom de","有……的外号"],["connu sous le surnom de","以……的绰号闻名"]],"sy":[["sobriquet","soutenu","外号（多带嘲弄）"],["pseudo","familier","网名"],["diminutif","courant","昵称的缩短形式"]],"fq":"中频，日常话题里常见。","me":"sur + nom：名字之上，再加一个名字。","tr":{"zh":"大家都叫他「小熊」。","fr":"Tout le monde l'appelle « Petit Ours ».","alt":"Son surnom, c'est « Petit Ours ».","note":"tout le monde 搭配单数动词。"}},
 "Un tag": {"pos":"n.m. 阳性名词，复数 tags","s":"涂鸦签名；街头涂鸦（用喷漆写的名字）。借自英语 tag，在法语里意思比英语窄，主要指街头涂鸦；动词 taguer = 涂鸦。","ipa":"[tag]","ph":"t [t]；a [a]；g 读 [g]，要发出来。","pi":"结尾 g 要读 [g]；复数 tags 读音相同，s 不发。","et":"借自英语 tag（标记）；法语意思缩窄为「涂鸦签名」。同族：tagueur（涂鸦者）、taguer。","ex":[["Il y a un nouveau tag sur le mur de l'école.","学校的墙上有新涂鸦。"],["La mairie efface les tags chaque semaine.","市政府每周清除涂鸦。"]],"co":[["faire un tag","涂鸦"],["effacer un tag","擦掉涂鸦"],["un tag sur un mur","墙上的涂鸦"]],"sy":[["graffiti","courant","涂鸦（更宽泛）"],["graff","familier","涂鸦（口语）"],["fresque","courant","壁画（对比）"]],"fq":"中频，城市话题里常见。","me":"tag：一笔留名，像在墙上「标记」自己。","tr":{"zh":"有人在墙上画了涂鸦。","fr":"Quelqu'un a fait un tag sur le mur.","alt":"Quelqu'un a tagué le mur.","note":"taguer 是动词：涂鸦。"}},
 "Un tour d'horizon": {"pos":"n.m. 阳性名词，复数 tours d'horizon","s":"概览；综述；全面浏览（对一个主题快速、全面地过一遍）。比喻用法，不是真的绕地平线转一圈。faire un tour d'horizon de qqch = 对某事做个概述。","ipa":"[tuʁ.dɔ.ʁi.zɔ̃]","ph":"tour 读 [tuʁ]；d'horizon：h 不发音，d' 与 o 连读 [dɔ]；ri [ʁi]；zon 读鼻化 [zɔ̃]。","pi":"horizon 的 h 不发音，所以是 d'horizon（缩合）；ou 读 [u]；-on 读 [ɔ̃]，n 不发。","et":"tour（转一圈）+ horizon（地平线，源于希腊语 horizon「界限」）：「环视地平线」，引申为「全面看一遍」。","ex":[["Le journaliste a fait un tour d'horizon de l'actualité.","记者对时事做了概述。"],["Voici un rapide tour d'horizon des solutions.","下面是对各种方案的简要概述。"]],"co":[["faire un tour d'horizon","做个概述"],["un rapide tour d'horizon","简要概述"],["un tour d'horizon complet","全面概览"],["un tour d'horizon de l'actualité","时事综述"]],"sy":[["panorama","courant","全景、概览"],["aperçu","courant","概要"],["synthèse","courant","综述"]],"fq":"中频，新闻、演讲和书面中常见。","me":"tour + horizon：绕一圈把全貌看一遍。","tr":{"zh":"他对本周的新闻做了概述。","fr":"Il a fait un tour d'horizon de l'actualité de la semaine.","alt":"Il a résumé les nouvelles de la semaine.","note":"faire un tour d'horizon de + 名词。"}},
 "Un trottoir": {"pos":"n.m. 阳性名词，复数 trottoirs","s":"人行道（街道两侧高出路面的步行带）。le bord du trottoir = 路缘；trottoir roulant = 自动人行道。","ipa":"[tʁɔ.twaʁ]","ph":"tr 读 [tʁ]；o 读 [ɔ]；oi 读 [wa]；r 在词尾要发 [ʁ]。","pi":"-oir 读 [waʁ]，结尾 r 要发出来；oi 读 [wa]，不是 [ɔɪ]；tt 只读一个 [t]。","et":"来自动词 trotter（小步快走）+ 后缀 -oir：「走路的地方」。","ex":[["Ne roulez pas à vélo sur le trottoir.","不要在人行道上骑车。"],["Il attend sur le trottoir d'en face.","他在对面的人行道上等。"]],"co":[["marcher sur le trottoir","在人行道上走"],["le trottoir d'en face","对面的人行道"],["le bord du trottoir","路缘"],["un trottoir roulant","自动人行道"]],"sy":[["chaussée","courant","车行道（对比）"],["bas-côté","courant","路肩"]],"fq":"中高频，街道场景里常用。","me":"trotter（小步走）+ -oir：小步走的地方。","tr":{"zh":"请走人行道，不要走马路。","fr":"Marchez sur le trottoir, pas sur la route.","alt":"Reste sur le trottoir, pas sur la route.","note":"marcher sur + 地点。"}},
 "Un tuyau": {"pos":"n.m. 阳性名词，复数 tuyaux（-au 的复数加 x）","s":"管子；软管。tuyau d'arrosage = 浇花软管；tuyau d'échappement = 排气管。口语里 un bon tuyau = 好消息、内部消息（小道消息）。","ipa":"[tɥi.jo]","ph":"tuy 读 [tɥi]（u 是半元音 [ɥ]，后接 [i]）；yau 读 [jo]，au 读 [o]。","pi":"uy 读 [ɥi]，不是 [u] 加 [i]；yau 读 [jo]，au 读 [o]；复数是 tuyaux，不是 tuyaus。","et":"来源不确定（和古法语 tuel「管」可能有关）；口语义「小道消息」来自「通过管子传递」的联想。","ex":[["L'eau fuit du tuyau.","水从管子里漏出来。"],["Il m'a donné un bon tuyau pour trouver du travail.","他给了我一个找工作的好消息。"]],"co":[["un tuyau d'arrosage","浇花软管"],["un tuyau d'échappement","排气管"],["un bon tuyau","有用的内部消息 / 窍门"],["filer un tuyau à quelqu'un","给某人透个消息（口语）"]],"sy":[["conduit","courant","管道、通道"],["canalisation","courant","（建筑里的）管线"],["tube","courant","管"]],"fq":"中频，日常和口语里常见。","me":"tuyau：水管，也是「消息」流过的管子。","tr":{"zh":"水管漏水了，快叫水管工。","fr":"Le tuyau fuit, appelle vite le plombier.","alt":"Ça fuit, appelle vite un plombier.","note":"fuir 的现在时：le tuyau fuit。"}},
 "Un vaurien": {"pos":"n.m. 阳性名词，阴性 vaurienne，复数 vauriens","s":"无赖；坏小子；淘气包。对孩子说时语气常常很温和，带有亲昵的责备，如 petit vaurien；对大人则偏贬义。","ipa":"[vo.ʁjɛ̃]","ph":"vau 读 [vo]；rien 读 [ʁjɛ̃]，ien 读鼻化 [jɛ̃]，n 不发。","pi":"au 读 [o]；-ien 读 [jɛ̃]；r 是小舌音；不要读成 [vo.ʁi.ɛn]。","et":"由 vaut（valoir，值）+ rien（没什么）而来：「什么都不值的人」。","ex":[["Ce garçon est un vrai petit vaurien.","这个男孩真是个小捣蛋。"],["Petit vaurien, rends-moi mon livre !","小坏蛋，把书还给我！"]],"co":[["un petit vaurien","小捣蛋"],["traiter quelqu'un de vaurien","骂某人是无赖"],["un vrai vaurien","地道的坏蛋"]],"sy":[["garnement","courant","淘气的孩子"],["voyou","courant","流氓，小混混（更重）"],["chenapan","familier","小无赖（带点玩笑）"]],"fq":"中低频，口语和文学里常见。","me":"vau-rien = vaut rien：什么都不值。","tr":{"zh":"这个小捣蛋又把窗户打破了。","fr":"Ce petit vaurien a encore cassé la fenêtre.","alt":"Ce petit garnement a encore cassé la vitre.","note":"encore 放在助动词后：a encore cassé。"}},
 "Un flux": {"pos":"n.m. 阳性名词，单复数同形（des flux）","s":"流量；人流；水流；数据流。可指人流、资金流、信息流。flux et reflux = 涨潮和退潮 / 起起落落。","ipa":"[fly]","ph":"fl 读 [fl]；u 读 [y]；结尾 x 不发音。","pi":"结尾 x 不发（像 prix、voix）；u 读 [y]，不是 [u]；单复数同形，只看冠词和上下文。","et":"来自拉丁语 fluxus（流动），fluere（流）。同族：fluide、influence、affluence。","ex":[["Le flux de voyageurs est constant.","旅客流量很稳定。"],["Le flux d'informations est énorme.","信息流量非常大。"]],"co":[["un flux migratoire","移民流动"],["un flux d'informations","信息流"],["le flux et le reflux","涨落、起伏"],["à flux tendu","按需供应、不留库存"]],"sy":[["flot","courant","水流、人潮"],["courant","courant","水流、电流"],["afflux","courant","涌入"]],"fq":"中频，经济、新闻和科技话题常见。","me":"flux：flu(ide) 同根，x 不发音。","tr":{"zh":"夏天游客的数量猛增。","fr":"En été, le flux de touristes augmente beaucoup.","alt":"L'été, il y a beaucoup plus de touristes.","note":"un flux de + 名词（无冠词）。"}},
 "De la brume": {"pos":"n.f. 阴性名词，复数 brumes（多用单数，不可数）","s":"薄雾；轻雾。比 brouillard（浓雾）淡，能见度较好。常见于早晨或海面。形容词：brumeux（有雾的）。","ipa":"[bʁym]","ph":"br 读 [bʁ]；u 读 [y]；m 读 [m]，结尾 e 不发音。","pi":"u 读 [y]，不是 [u]；单音节，e 不发；别和 brun（棕色，[bʁœ̃]）混淆。","et":"来自古普罗旺斯语 bruma，源于拉丁语 bruma（冬天）；同族：brumeux、brumisateur。","ex":[["Il y a de la brume ce matin.","今早有雾。"],["La brume se lève vers dix heures.","雾大约十点散去。"]],"co":[["de la brume matinale","晨雾"],["une brume légère","薄雾"],["la brume se lève","雾散去"],["de la brume sur la mer","海上的雾"]],"sy":[["brouillard","courant","浓雾"],["bruine","courant","毛毛雨（不是雾）"],["buée","courant","水汽（玻璃上的雾）"]],"fq":"中频，天气描写里常见。","me":"brume：比 brouillard 薄一层。","tr":{"zh":"海上有一层薄雾。","fr":"Il y a une brume légère sur la mer.","alt":"Il y a un peu de brume sur la mer.","note":"天气现象用 il y a。"}},
 "De la censure": {"pos":"n.f. 阴性名词，复数 censures（多用单数）","s":"审查制度；审查。指国家或机构对书、电影、新闻的检查和禁止。motion de censure = （议会）不信任动议。注意：英语 censure 是「谴责」，法语 censure 是「审查」。","ipa":"[sɑ̃.syʁ]","ph":"cen 读 [sɑ̃]（c 读 [s]，en 读鼻化 [ɑ̃]）；sure 读 [syʁ]，u 读 [y]。","pi":"c 读 [s]；en 读 [ɑ̃]，不是 [ɛn]；u 读 [y]；英语「谴责」这个义项在法语里不用 censure。","et":"来自拉丁语 censura（古罗马的 censor 职位）。同族：censeur、censurer。","ex":[["Le film a été interdit à cause de la censure.","这部电影因审查被禁。"],["Il y a beaucoup de censure dans ce pays.","这个国家有大量审查。"]],"co":[["la censure d'État","国家审查"],["échapper à la censure","躲过审查"],["lever la censure","解除审查"],["la motion de censure","不信任动议"]],"sy":[["contrôle","courant","管控"],["interdiction","courant","禁止"],["autocensure","courant","自我审查"]],"fq":"中频，新闻和文化话题常见。","me":"censure：censor（审查官）的名词。","tr":{"zh":"这本书被审查了。","fr":"Ce livre a été victime de la censure.","alt":"Ce livre a été censuré.","note":"被动语态：a été censuré。"}},
 "De la drogue": {"pos":"n.f. 阴性名词，复数 drogues","s":"毒品；麻醉品。泛指违禁药物，常带「非法」意味，注意药品叫 médicament，不是 drogue。drogue dure / douce = 硬 / 软毒品。动词：se droguer。","ipa":"[dʁɔg]","ph":"dr 读 [dʁ]；o 读 [ɔ]；-gue 读 [g]，u 不发音，e 不发音。","pi":"-gue 里的 u 不发音（只是保持 g 读 [g]）；o 读开口 [ɔ]；英语 drug 也有「药」的义，法语只指毒品。","et":"来源不确定（古法语 drogue，有人推测与荷兰语有关）；同族：droguer、drogué、droguerie（日用杂货店，非毒品店）。","ex":[["Il a été arrêté pour possession de drogue.","他因持有毒品被捕。"],["La drogue est un problème de santé publique.","毒品是公共卫生问题。"]],"co":[["consommer de la drogue","吸毒"],["la drogue dure / douce","硬 / 软毒品"],["un trafic de drogue","毒品贩运"],["lutter contre la drogue","禁毒"]],"sy":[["stupéfiant","soutenu","麻醉品、毒品（法律用语）"],["came","argot","毒品（俗语）"],["médicament","courant","药品（别混淆）"]],"fq":"中高频，新闻和社会话题常见。","me":"drogue：以 -gue 收尾，u 不发音，意思只有毒品。","tr":{"zh":"毒品对健康非常危险。","fr":"La drogue est très dangereuse pour la santé.","alt":"La drogue, c'est très dangereux pour la santé.","note":"泛指用定冠词：la drogue。"}},
 "De la verdure": {"pos":"n.f. 阴性名词，通常用单数（部分冠词 de la）","s":"绿意；绿色植物，指大片的草木、绿化。常用部分冠词 de la verdure，不说 une verdure。也可指做菜用的青菜（不太常见）。","ipa":"[vɛʁ.dyʁ]","ph":"v [v]；e 读开口 [ɛ]；r [ʁ]；u [y]；结尾 e 不发音。","pi":"u 是 [y]（嘴唇圆、舌位前），不是 [u]；注意是阴性：la verdure。","et":"来自 vert（绿）加后缀 -ure，表示「绿的东西」。","ex":[["J'ai besoin de verdure pour me ressourcer.","我需要绿色来恢复精力。"],["Il y a beaucoup de verdure dans ce parc.","这个公园里绿意盎然。"]],"co":[["un écrin de verdure","一片绿意环抱之地"],["manquer de verdure","缺少绿化"],["se perdre dans la verdure","隐没在绿荫中"]],"sy":[["végétation","courant","植被，更中性、更科学"],["espaces verts","courant","城市绿地、公园"],["feuillage","soutenu","枝叶，指树叶本身"]],"fq":"中频，常见于描写环境、城市规划。","me":"verdure = vert + -ure：「绿」的集合。","tr":{"zh":"这座城市需要更多绿化。","fr":"Cette ville a besoin de plus de verdure.","alt":"Il faudrait plus de verdure dans cette ville.","note":"verdure 不可数，用 de la / de + 名词。"}},
 "L'affluence": {"pos":"n.f. 阴性名词，复数 affluences（多用单数）","s":"人流；人潮；拥挤。指某地同时来了很多人，如 l'affluence des touristes。也说 heures d'affluence（高峰时段）。","ipa":"[a.fly.ɑ̃s]","ph":"L'affluence：l' 省音；ff 只读一个 [f]；u [y]；-en- 读鼻化 [ɑ̃]；c 在 e 前读 [s]；结尾 e 不发音。","pi":"ff 不要读两遍；-ence 读 [ɑ̃s]，不是 [ɛns]；u 读 [y]。","et":"拉丁语 affluentia，来自 affluere（流向）。同族：affluent（支流）、influence。","ex":[["L'affluence touristique est forte en été.","夏天游客很多。"],["Il y a une grande affluence au marché le samedi.","星期六集市上人很多。"]],"co":[["l'heure d'affluence","高峰时段"],["une grande affluence","大量人流"],["en cas d'affluence","人多的时候"]],"sy":[["foule","courant","人群，更口语、常用"],["fréquentation","courant","到访人数（统计）"],["désertion","soutenu","反义：无人光顾"]],"fq":"中频，新闻、旅游、交通语境常见。","me":"af-FLU-ence：像水流（flux）涌向一处。","tr":{"zh":"高峰时段地铁里人很多。","fr":"Il y a beaucoup d'affluence dans le métro aux heures de pointe.","alt":"Aux heures d'affluence, le métro est bondé.","note":"heures de pointe 和 heures d'affluence 都可以说高峰时段。"}},
 "L'autonomie": {"pos":"n.f. 阴性名词，复数 autonomies","s":"自主；独立（人、地区、机构）。也指设备的续航：l'autonomie d'une batterie / d'une voiture électrique。","ipa":"[o.tɔ.nɔ.mi]","ph":"au [o]；两个 o 都读 [ɔ]；n [n]；结尾 e 不发音；重音在最后一个音节 mi。","pi":"au 读 [o]，不是「奥」带 u；词尾 -ie 读 [i]，不要多读一个 e。","et":"希腊语 autonomia：autos（自己）+ nomos（法则），意为「自己立法」。","ex":[["Cette voiture a une grande autonomie.","这辆车续航很长。"],["Les jeunes veulent plus d'autonomie.","年轻人想要更多自主。"]],"co":[["gagner en autonomie","变得更独立"],["l'autonomie d'une batterie","电池续航"],["perdre son autonomie","丧失自理能力"]],"sy":[["indépendance","courant","独立，更强调完全不依赖"],["liberté","courant","自由"],["dépendance","courant","反义：依赖"]],"fq":"中高频，日常与新闻都常见。","me":"auto（自己）+ nomie（规则）：自己管自己。","tr":{"zh":"这部手机的续航很好。","fr":"Ce téléphone a une très bonne autonomie.","alt":"La batterie de ce téléphone tient longtemps.","note":"续航用 autonomie，是阴性名词。"}},
 "L'obésité": {"pos":"n.f. 阴性名词，不可数","s":"肥胖。医学和公共卫生用语，较正式。形容词是 obèse（男女同形）。说人胖，日常多用 gros / grosse，obèse 偏医学。","ipa":"[ɔ.be.zi.te]","ph":"o [ɔ]；b [b]；é [e]；s 在两个元音间读 [z]；结尾 é 读 [e]。","pi":"s 读 [z]，不是 [s]；重音在最后 té；注意是阴性：l'obésité（-té 结尾的名词多为阴性）。","et":"拉丁语 obesitas，来自 obesus（吃得过胖的）。","ex":[["L'obésité est un problème de santé publique.","肥胖是公共卫生问题。"],["L'obésité infantile augmente.","儿童肥胖在增加。"]],"co":[["l'obésité infantile","儿童肥胖"],["lutter contre l'obésité","对抗肥胖"],["un risque d'obésité","肥胖风险"]],"sy":[["surpoids","courant","超重，比 obésité 轻"],["embonpoint","soutenu","发福，委婉说法"],["maigreur","courant","反义：消瘦"]],"fq":"中频，新闻、健康话题常见。","me":"obèse → obésité：和 -té 结尾的阴性名词同类。","tr":{"zh":"学校在对抗儿童肥胖。","fr":"L'école lutte contre l'obésité infantile.","alt":"Les écoles se battent contre l'obésité chez les enfants.","note":"lutter contre + 名词。"}},
 "L'orientation": {"pos":"n.f. 阴性名词，复数 orientations","s":"朝向；方位（房子朝哪个方向）。也指方向感（avoir le sens de l'orientation）、人生或学业的方向选择（orientation scolaire / professionnelle）。","ipa":"[ɔ.ʁjɑ̃.ta.sjɔ̃]","ph":"o [ɔ]；r [ʁ]；-ien- 读 [jɑ̃]；t [t]；-tion 读 [sjɔ̃]；结尾鼻化。","pi":"-tion 读 [sjɔ̃]，不是「申」；-ien- 里的 en 是 [ɑ̃]，不是 [ɛn]；n 不发。","et":"来自 orienter（定向），源于 orient（东方，拉丁语 oriens「升起」），因为过去以日出的方向定位。","ex":[["L'orientation de la maison vers le sud est idéale.","房子朝南是理想的。"],["Elle n'a aucun sens de l'orientation.","她完全没有方向感。"]],"co":[["l'orientation sud / nord","朝南 / 朝北"],["le sens de l'orientation","方向感"],["l'orientation professionnelle","职业规划"]],"sy":[["exposition","courant","（房屋）朝向、日照面"],["direction","courant","方向"],["cap","courant","航向；目标方向"]],"fq":"中高频，租房、地图、教育话题常见。","me":"orient（东方）→ 找东方 = 定方向。","tr":{"zh":"这套公寓朝东，早上很亮。","fr":"Cet appartement est orienté à l'est, il est lumineux le matin.","alt":"L'orientation est à l'est, donc il y a du soleil le matin.","note":"房子「朝向」可用 être orienté(e) + 方位。"}},
 "La bourgeoisie": {"pos":"n.f. 阴性名词，复数 bourgeoisies","s":"资产阶级；中产上层。指拥有财产、经济稳定的社会阶层。le petit bourgeois、la haute bourgeoisie 常见。用法带社会史色彩，有时略带贬义。","ipa":"[buʁ.ʒwa.zi]","ph":"ou [u]；r [ʁ]；g 在 e/oi 前读 [ʒ]；-oi- 读 [wa]；s 在元音间读 [z]；结尾 -ie 读 [i]。","pi":"g 读 [ʒ]；s 读 [z]；-oisie 读 [wa.zi]；ou 不是 [o]，是 [u]。","et":"来自 bourgeois（城镇居民），bourg（城镇，日耳曼语 burg「要塞」）+ 后缀。bourgeoisie 加 -ie 表示这一群人。","ex":[["La bourgeoisie parisienne habite dans ces quartiers.","巴黎资产阶级住在这些街区。"],["Il vient d'une famille de la petite bourgeoisie.","他出身小资产阶级家庭。"]],"co":[["la haute bourgeoisie","上层资产阶级"],["la petite bourgeoisie","小资产阶级"],["la bourgeoisie et le prolétariat","资产阶级与无产阶级"]],"sy":[["classe moyenne","courant","中产阶级，更中性"],["élite","courant","精英阶层"],["prolétariat","soutenu","反义：无产阶级"]],"fq":"中频，历史、社会讨论中常见。","me":"bourg（城镇）+ -eoisie：住在城里有钱的人。","tr":{"zh":"资产阶级在十九世纪很有影响力。","fr":"La bourgeoisie avait beaucoup d'influence au XIXe siècle.","alt":"Au XIXe siècle, la bourgeoisie avait un grand pouvoir.","note":"世纪写作 XIXe siècle，读作 dix-neuvième siècle。"}},
 "La côte": {"pos":"n.f. 阴性名词，复数 côtes","s":"海岸；海滨（la Côte d'Azur）。还有：坡（une côte 上坡）、肋骨（côte）、带骨肉排（côte de porc）。看上下文区分。","ipa":"[kot]","ph":"c [k]；ô [o]（闭口）；t 要发音 [t]；结尾 e 不发音。","pi":"ô 带扬抑符，读 [o]；t 要发音；不要和 côté（旁边）混淆，côté 多一个 é。","et":"拉丁语 costa（肋骨、侧面）。同源：côté（旁边），accoster（靠岸）。","ex":[["Nous passons nos vacances sur la côte.","我们在海岸度假。"],["Le vélo monte la côte difficilement.","自行车很难爬上坡。"]],"co":[["sur la côte","在海边"],["la Côte d'Azur","蔚蓝海岸"],["une côte de bœuf","牛肋排"],["monter une côte","爬坡"]],"sy":[["littoral","soutenu","沿海地带"],["rivage","littéraire","岸边"],["plage","courant","沙滩，不等于海岸"]],"fq":"高频，地理、旅游常用。","me":"côte（海岸）= 大陆的「肋骨」边线。","tr":{"zh":"我们沿着海岸开车。","fr":"Nous roulons le long de la côte.","alt":"On conduit en suivant la côte.","note":"le long de + 名词 = 沿着。"}},
 "La disposition": {"pos":"n.f. 阴性名词，复数 dispositions","s":"布局；摆放（la disposition des meubles）。复数 des dispositions 还有「措施；规定；才能」的意思，如 prendre des dispositions（采取措施）。être à la disposition de qn = 供某人使用。","ipa":"[dis.pɔ.zi.sjɔ̃]","ph":"di [di]；s 在 dis- 后读 [s]；po [pɔ]；si 的 s 在元音间读 [z]；-tion 读 [sjɔ̃]。","pi":"dis-po-si-tion：第二个 s 读 [z]；-tion 读 [sjɔ̃]；不要把 à la disposition 说成 en disposition。","et":"拉丁语 dispositio，来自 disponere（分开摆放）：dis- + ponere（放）。同族：disposer、composition。","ex":[["La disposition des meubles rend la pièce plus grande.","家具的布局让房间显得更大。"],["Je suis à votre disposition.","听候您的吩咐。"]],"co":[["à la disposition de qn","供某人使用"],["mettre à disposition","提供使用"],["prendre des dispositions","采取措施"],["la disposition des pièces","房间布局"]],"sy":[["agencement","soutenu","布置、安排（更正式）"],["aménagement","courant","整修、布置"],["arrangement","courant","安排；整理"]],"fq":"中高频，日常与服务语境都常见。","me":"dis（分开）+ position（位置）：东西各就各位。","tr":{"zh":"我随时听候您的安排。","fr":"Je suis à votre disposition.","alt":"Je reste à votre disposition si vous avez des questions.","note":"à la disposition de + 人，客气用语。"}},
 "La gentrification": {"pos":"n.f. 阴性名词，复数 gentrifications（多用单数）","s":"绅士化：富裕阶层迁入老旧社区，房价房租上涨，原住户被挤走。是社会学、城市研究的常用词。动词 gentrifier。","ipa":"[ʒɑ̃.tʁi.fi.ka.sjɔ̃]","ph":"g 在 e 前读 [ʒ]；en 读鼻化 [ɑ̃]；tr [tʁ]；-tion 读 [sjɔ̃]。","pi":"g 读 [ʒ]，不是 [g]；-tion 读 [sjɔ̃]；en 是 [ɑ̃]，不是 [ɛn]。","et":"借自英语 gentrification（1960 年代由社会学家 Ruth Glass 提出），gentry（乡绅）派生，加 -fication。","ex":[["La gentrification du quartier fait augmenter les loyers.","街区的绅士化推高了房租。"],["La gentrification chasse les habitants modestes.","绅士化把收入不高的居民挤走了。"]],"co":[["la gentrification d'un quartier","社区绅士化"],["lutter contre la gentrification","对抗绅士化"],["un quartier en voie de gentrification","正在绅士化的街区"]],"sy":[["embourgeoisement","soutenu","中产化，更偏社会学表述"],["rénovation urbaine","courant","城市更新，不一定涉及驱逐"]],"fq":"中低频，新闻、社会讨论中常见。","me":"gentry（上流人）+ -fication（变成）：让街区变「体面」。","tr":{"zh":"房租涨得太快，因为街区在绅士化。","fr":"Les loyers montent vite à cause de la gentrification du quartier.","alt":"Le quartier se gentrifie, donc les loyers explosent.","note":"se gentrifier = 变得绅士化（代动词）。"}},
 "La périphérie": {"pos":"n.f. 阴性名词，复数 périphéries","s":"外围；市郊。指城市的边缘地带，en périphérie (de la ville)。也指几何的周边。与 banlieue 相近，但 périphérie 更中性。","ipa":"[pe.ʁi.fe.ʁi]","ph":"é 读 [e]；r [ʁ]；ph 读 [f]；结尾 -ie 读 [i]，e 不发。","pi":"ph 读 [f]；四个音节都是开口短元音；注意 é 有重音符号：périphérie。","et":"希腊语 periphereia：peri（周围）+ pherein（带、转）。同族：périmètre。","ex":[["Ils ont déménagé en périphérie de la ville.","他们搬到了城市外围。"],["Les loyers sont moins chers en périphérie.","市郊的房租更便宜。"]],"co":[["en périphérie de la ville","在城市外围"],["la périphérie de Paris","巴黎外围"],["le périphérique","环城路"]],"sy":[["banlieue","courant","郊区，常指大城市周边住宅区"],["alentours","courant","周围"],["centre","courant","反义：中心"]],"fq":"中频，城市、地理话题常见。","me":"péri（周围）+ phérie（带）：绕在外面一圈。","tr":{"zh":"大型商场都在城市外围。","fr":"Les grands centres commerciaux sont en périphérie de la ville.","alt":"Les grandes surfaces se trouvent à la périphérie.","note":"en périphérie 与 à la périphérie 都可。"}},
 "La suppression": {"pos":"n.f. 阴性名词，复数 suppressions","s":"取消；删除；撤销。指把东西去掉：la suppression d'un vol、d'un poste、d'un fichier。动词 supprimer。注意：不等于「压抑」，那是 répression。","ipa":"[sy.pʁɛ.sjɔ̃]","ph":"su [sy]；pp 只读一个 [p]；ss 读 [s]；-ion 读 [sjɔ̃]。","pi":"pp 和 ss 都是双写，只读一个音；u 读 [y]；-ion 的 n 不单独发音。","et":"拉丁语 suppressio，来自 supprimer（sub- + premere「压」）。","ex":[["La suppression de ce vol a causé des problèmes.","取消这趟航班造成了问题。"],["La suppression de 200 postes est annoncée.","宣布裁减 200 个岗位。"]],"co":[["la suppression d'un vol","航班取消"],["la suppression d'emplois","裁减岗位"],["la suppression d'un fichier","删除文件"]],"sy":[["annulation","courant","取消（活动、预订）"],["élimination","courant","消除"],["création","courant","反义：设立"]],"fq":"中高频，新闻、行政、工作中常见。","me":"sup-primer：往下「压」掉，就是去掉。","tr":{"zh":"公司宣布裁减岗位。","fr":"L'entreprise annonce la suppression de postes.","alt":"La boîte va supprimer des postes.","note":"supprimer des postes = 裁减岗位。"}},
 "La tranquillité": {"pos":"n.f. 阴性名词，不可数","s":"宁静；平静；安稳。指环境安静或心里不被打扰。en toute tranquillité = 安心地；laisser qn en paix 近义。形容词 tranquille。","ipa":"[tʁɑ̃.ki.li.te]","ph":"tr [tʁ]；an 读 [ɑ̃]；qu 读 [k]；ill 在这里读 [il]；-té 读 [te]。","pi":"tranquillité 里的 ill 读 [il]，不像 famille 的 [j]；qu 读 [k]；拼写有双 l。","et":"拉丁语 tranquillitas，来自 tranquillus（平静的）。","ex":[["Je cherche la tranquillité à la campagne.","我在乡下寻求宁静。"],["Il travaille en toute tranquillité.","他安安心心地工作。"]],"co":[["en toute tranquillité","安心地"],["la tranquillité d'esprit","心安"],["troubler la tranquillité","扰乱安宁"],["pour votre tranquillité","为了您的安心"]],"sy":[["calme","courant","安静，更常用"],["quiétude","soutenu","安宁（书面）"],["paix","courant","和平；安宁"]],"fq":"中高频，日常常用。","me":"tranquille 加 -ité：安静的状态。","tr":{"zh":"我想要一点安静。","fr":"Je voudrais un peu de tranquillité.","alt":"J'aimerais un peu de calme.","note":"un peu de + 不可数名词。"}},
 "Une abbaye": {"pos":"n.f. 阴性名词，复数 abbayes","s":"修道院（由 abbé 或 abbesse 领导的天主教修道院）。很多法国名胜是 abbaye，如 l'abbaye du Mont-Saint-Michel。比 monastère 更偏西欧中世纪。","ipa":"[a.be.i]","ph":"a [a]；bb 只读一个 [b]；-aye 读 [ei]（有时 [ɛj]）；结尾 e 不发音。","pi":"bb 读单个 [b]；-aye 不是「呀」，读 [ei]；注意是阴性。","et":"晚期拉丁语 abbatia，来自 abbas（院长），源自亚拉姆语 abba（父亲）。同族：abbé。","ex":[["Les moines vivent dans cette abbaye.","修士们住在这座修道院里。"],["Nous avons visité une abbaye du XIIe siècle.","我们参观了一座十二世纪的修道院。"]],"co":[["une abbaye bénédictine","本笃会修道院"],["l'abbé / l'abbesse","院长（男/女）"],["visiter une abbaye","参观修道院"]],"sy":[["monastère","courant","修道院，更泛指"],["couvent","courant","修道院（常指修女）"],["prieuré","soutenu","小修道院"]],"fq":"中低频，旅游、历史常见。","me":"abbé 的地方就是 abbaye。","tr":{"zh":"我们参观了一座古老的修道院。","fr":"Nous avons visité une vieille abbaye.","alt":"On a visité une très vieille abbaye.","note":"visiter 用于参观地点；rendre visite à 用于探望人。"}},
 "Une agglomération": {"pos":"n.f. 阴性名词，复数 agglomérations","s":"城市群；都市区：城市及其周边连成一片的建成区。l'agglomération parisienne = 大巴黎地区。也可指（一般意义上）聚集成块。","ipa":"[a.ɡlɔ.me.ʁa.sjɔ̃]","ph":"gg 读 [ɡl]（g + l）；o [ɔ]；é [e]；r [ʁ]；-tion 读 [sjɔ̃]。","pi":"agglo- 读 [aɡlɔ]，gg 不要读成「j」；注意 mé 的重音符号；-tion 读 [sjɔ̃]。","et":"拉丁语 agglomerare（聚成团）：ad- + glomus（团、球）。","ex":[["L'agglomération compte un million d'habitants.","都会区有一百万居民。"],["Il habite dans l'agglomération lyonnaise.","他住在里昂都市区。"]],"co":[["l'agglomération parisienne","巴黎都市区"],["une grande agglomération","大都市区"],["hors agglomération","（道路标志）城区外"]],"sy":[["métropole","courant","大都市"],["zone urbaine","courant","城市地区"],["village","courant","反义：村庄"]],"fq":"中频，地理、交通、统计中常见。","me":"a-GLO-mé：许多房子「聚成一团」。","tr":{"zh":"里昂都市区有两百万人。","fr":"L'agglomération lyonnaise compte deux millions d'habitants.","alt":"Il y a deux millions de personnes dans l'agglomération de Lyon.","note":"compter = 共有。"}},
 "Une autoroute": {"pos":"n.f. 阴性名词，复数 autoroutes","s":"高速公路（法国多数收费 péage）。en France 路标上用 A 加数字，如 l'A6。城市环线和国道不同：route nationale。","ipa":"[o.to.ʁut]","ph":"au [o]；t [t]；o [o]；ou [u]；结尾 e 不发音。","pi":"auto 读 [o.to]，两个 o 都是闭口；route 里 ou 读 [u]；是阴性：une autoroute。","et":"auto(mobile) + route 构成的合成词。","ex":[["La vitesse est limitée sur l'autoroute.","高速公路上有限速。"],["On prend l'autoroute pour aller à Lyon.","我们走高速去里昂。"]],"co":[["prendre l'autoroute","上高速"],["une autoroute à péage","收费高速"],["une aire d'autoroute","高速服务区"],["sortir de l'autoroute","下高速"]],"sy":[["voie rapide","courant","快速路，不是高速"],["route nationale","courant","国道"],["périphérique","courant","城市环路"]],"fq":"高频，日常常用。","me":"auto + route：专给汽车的路。","tr":{"zh":"我们走高速，更快。","fr":"Nous prenons l'autoroute, c'est plus rapide.","alt":"On prend l'autoroute, ça va plus vite.","note":"prendre l'autoroute = 上高速。"}},
 "Une campagne": {"pos":"n.f. 阴性名词，复数 campagnes","s":"两个常用义：1）乡村；乡下（à la campagne）。2）运动；活动；竞选（une campagne électorale / publicitaire）。看上下文区分。","ipa":"[kɑ̃.paɲ]","ph":"c [k]；-am- 读 [ɑ̃]；p [p]；-gne 读 [ɲ]；结尾 e 不发音。","pi":"gn 读 [ɲ]，像「尼」，不是 [g] + [n]；am 读 [ɑ̃]；一个词两个意思，别搞混。","et":"晚期拉丁语 campania（平原，田野），来自 campus（田野）。同族：champ、camp。","ex":[["Ce candidat prépare sa campagne politique.","这位候选人在筹备政治竞选。"],["Ils habitent à la campagne.","他们住在乡下。"]],"co":[["à la campagne","在乡下"],["une campagne électorale","选举活动"],["une campagne publicitaire","广告宣传活动"],["faire campagne pour","为……竞选或造势"]],"sy":[["province","courant","外省、非巴黎地区"],["champs","courant","田野"],["ville","courant","反义：城市"]],"fq":"极高频，日常常用。","me":"campagne = 田野；去田野里「作战」→ 竞选活动。","tr":{"zh":"他们每个周末都去乡下。","fr":"Ils vont à la campagne tous les week-ends.","alt":"Chaque week-end, ils partent à la campagne.","note":"à la campagne = 在 / 去乡下。"}},
 "Une cathédrale": {"pos":"n.f. 阴性名词，复数 cathédrales","s":"大教堂：主教（évêque）所在的主教座堂，如 Notre-Dame de Paris、la cathédrale de Chartres。比 église 更大更重要。","ipa":"[ka.te.dʁal]","ph":"th 读 [t]；é [e]；dr [dʁ]；a [a]；-le 的 e 不发，l 要读。","pi":"th 读 [t]，不是「s」；注意 é；结尾 l 要读 [l]。","et":"来自 (église) cathédrale，拉丁语 cathedra（座位），希腊语 kathedra。指主教之座所在的教堂。","ex":[["Nous avons visité une magnifique cathédrale.","我们参观了一座壮丽的大教堂。"],["La cathédrale de Reims est très célèbre.","兰斯大教堂非常有名。"]],"co":[["la cathédrale de Chartres","沙特尔大教堂"],["une cathédrale gothique","哥特式大教堂"],["visiter la cathédrale","参观大教堂"]],"sy":[["église","courant","教堂，更泛指"],["basilique","courant","圣殿，另一种大教堂"],["chapelle","courant","小教堂"]],"fq":"中频，旅游、历史语境常用。","me":"cathedra（座椅）：主教的座位所在地。","tr":{"zh":"大教堂建于十三世纪。","fr":"La cathédrale a été construite au XIIIe siècle.","alt":"Cette cathédrale date du XIIIe siècle.","note":"dater de = 追溯到（某个时期）。"}},
 "Une chapelle": {"pos":"n.f. 阴性名词，复数 chapelles","s":"小教堂；礼拜堂；大教堂或医院、学校里附设的小祈祷间。","ipa":"[ʃa.pɛl]","ph":"ch 读 [ʃ]；a [a]；-pel- 读 [pɛl]；ll 读一个 [l]；结尾 e 不发音。","pi":"ch 读 [ʃ]，不是 [k]；ll 在这里读单个 [l]；e 不发音。","et":"中世纪拉丁语 cappella，是 cappa（斗篷）的指小词。传说因圣马丁的斗篷存放在一座小圣堂中。","ex":[["Il y a une petite chapelle en haut du village.","村子高处有一座小教堂。"],["Ils se sont mariés dans une chapelle.","他们在一座小教堂里结婚。"]],"co":[["une chapelle romane","罗曼式小教堂"],["la chapelle de l'hôpital","医院的礼拜堂"],["se marier dans une chapelle","在小教堂里结婚"]],"sy":[["église","courant","教堂，更大"],["oratoire","soutenu","小祈祷室"],["cathédrale","courant","大教堂，反面对比"]],"fq":"中频，旅游、描写景观时常见。","me":"chapelle 里有 chape（披风）：小小的「披风」罩住的圣堂。","tr":{"zh":"山顶上有一座小教堂。","fr":"Il y a une petite chapelle au sommet de la colline.","alt":"En haut de la colline, il y a une petite chapelle.","note":"il y a + 名词 = 有。"}},
 "Une classe sociale": {"pos":"n.f. 阴性名词词组，复数 classes sociales","s":"社会阶层；社会阶级。classe 是阴性，sociale 是形容词，阴性。常和 classe moyenne（中产阶级）、classe ouvrière（工人阶级）一起出现。","ipa":"[klas sɔ.sjal]","ph":"cl [kl]；a [a]；ss 读 [s]；social 的 c 读 [s]，-ial 读 [jal]；结尾 -le 的 e 不发。","pi":"classe 的 e 不发音；social 的 c 读 [s]，ci 读 [sj]；形容词 sociale 要与阴性名词配合。","et":"classe 来自拉丁语 classis（等级，群体）；social 来自拉丁语 socialis，源于 socius（伙伴）。","ex":[["Les inégalités entre les classes sociales augmentent.","各社会阶层之间的不平等在加剧。"],["Il appartient à la classe moyenne.","他属于中产阶级。"]],"co":[["la classe moyenne","中产阶级"],["la classe ouvrière","工人阶级"],["appartenir à une classe sociale","属于某个阶层"],["les classes populaires","底层大众"]],"sy":[["milieu social","courant","社会环境、出身圈子"],["catégorie sociale","courant","社会类别"],["caste","soutenu","种姓；封闭阶层"]],"fq":"中频，社会话题常见。","me":"classe（等级）+ sociale（社会的）。","tr":{"zh":"不同社会阶层的孩子在同一所学校上学。","fr":"Des enfants de classes sociales différentes vont à la même école.","alt":"Les enfants de toutes les classes sociales vont à la même école.","note":"classes sociales 用复数，因为有多个阶层。"}},
 "Une clinique": {"pos":"n.f. 阴性名词，复数 cliniques","s":"私立医院；诊所（多为私营的小型医院）。注意：法国的公立大医院是 hôpital，clinique 通常是私立的。","ipa":"[kli.nik]","ph":"cl [kl]；i [i]；n [n]；-que 读 [k]；e 不发音。","pi":"最后 -que 读 [k]；法语 clinique 不是 clinic 的小诊所，常指私立医院，规模较大。","et":"希腊语 klinikos（卧床的），来自 kline（床）。原指在病床旁的医疗。","ex":[["Elle travaille dans une clinique privée.","她在私立诊所工作。"],["Il est né dans une clinique.","他出生在一家私立医院。"]],"co":[["une clinique privée","私立医院"],["une clinique vétérinaire","宠物诊所"],["entrer en clinique","住进私立医院"]],"sy":[["hôpital","courant","医院，多为公立"],["cabinet","courant","（医生的）诊室"],["centre de santé","courant","社区卫生中心"]],"fq":"中频，日常健康话题常见。","me":"clinique ← kline（床）：病人躺的床。","tr":{"zh":"他妈妈在一家私立医院工作。","fr":"Sa mère travaille dans une clinique privée.","alt":"Sa maman bosse dans une clinique privée.","note":"travailler dans + 机构。"}},
 "Une colline": {"pos":"n.f. 阴性名词，复数 collines","s":"山丘；小山。比 montagne 矮得多，坡度较缓。","ipa":"[kɔ.lin]","ph":"c [k]；o [ɔ]；ll 读 [l]（这里不是 [j]）；i [i]；n [n]；结尾 e 不发。","pi":"ll 读 [l]，不是 [j]；注意 colline 不是 montagne，高度小得多。","et":"来自意大利语 collina，源于拉丁语 collis（小山）。","ex":[["La maison est située sur une colline.","房子建在山丘上。"],["On voit la mer du haut de la colline.","从山丘上能看见大海。"]],"co":[["au sommet de la colline","在山顶"],["une colline boisée","树木覆盖的山丘"],["gravir une colline","爬上山丘"]],"sy":[["montagne","courant","山，更高"],["butte","courant","土丘，小山包"],["coteau","soutenu","山坡（常种葡萄）"]],"fq":"中频，风景描写常见。","me":"colline：像「小山」，ll 读 [l]。","tr":{"zh":"我们爬上了那座山丘。","fr":"Nous avons gravi la colline.","alt":"On est monté en haut de la colline.","note":"gravir 略书面；日常说 monter sur / grimper sur。"}},
 "Une consultation": {"pos":"n.f. 阴性名词，复数 consultations","s":"门诊；问诊（médecin 的看诊）。另指咨询、征求意见、查阅（la consultation d'un site）。le médecin est en consultation = 医生在看诊。","ipa":"[kɔ̃.syl.ta.sjɔ̃]","ph":"con 读鼻化 [kɔ̃]；su [sy]；l [l]；t [t]；-tion 读 [sjɔ̃]。","pi":"con- 的 n 不发，读鼻化 [ɔ̃]；u 读 [y]；-tion 读 [sjɔ̃]。","et":"拉丁语 consultatio，来自 consultare（商议）。动词 consulter。","ex":[["Le médecin est en consultation.","医生正在问诊。"],["Les consultations ont lieu le matin.","门诊在上午。"]],"co":[["une consultation médicale","门诊问诊"],["un cabinet de consultation","诊室"],["la consultation publique","公开征求意见"],["heures de consultation","门诊时间"]],"sy":[["rendez-vous","courant","预约（挂号）"],["visite","courant","拜访；上门看诊"],["avis","courant","意见"]],"fq":"中高频，医疗与行政语境常见。","me":"consulter le médecin → une consultation。","tr":{"zh":"我明天上午有一个门诊预约。","fr":"J'ai une consultation demain matin.","alt":"J'ai rendez-vous chez le médecin demain matin.","note":"avoir une consultation = 有门诊预约。"}},
 "Une crèche": {"pos":"n.f. 阴性名词，复数 crèches","s":"托儿所（照顾约 3 岁以下幼儿）。圣诞时还指耶稣诞生的马槽模型（la crèche de Noël）。3 岁以上去 l'école maternelle。","ipa":"[kʁɛʃ]","ph":"c [k]；r [ʁ]；è 读开口 [ɛ]；ch 读 [ʃ]；结尾 e 不发音。","pi":"ch 读 [ʃ]；è 带重音符号，读 [ɛ]；不要和 école maternelle（幼儿园）混淆。","et":"来自日耳曼语（法兰克语 *kripja「马槽」），与英语 crib 同源。","ex":[["Mon fils va à la crèche tous les matins.","我儿子每天早上去托儿所。"],["Il y a une crèche près de chez nous.","我们家附近有一家托儿所。"]],"co":[["mettre un enfant à la crèche","把孩子送托儿所"],["la crèche de Noël","圣诞马槽"],["une place en crèche","托儿所名额"]],"sy":[["garderie","courant","临时托管班"],["nounou","familier","保姆"],["école maternelle","courant","幼儿园（3-6 岁）"]],"fq":"中频，带小孩的家庭日常常用。","me":"crèche：crib（婴儿床）的亲戚。","tr":{"zh":"我的女儿九个月大，上托儿所。","fr":"Ma fille a neuf mois et elle va à la crèche.","alt":"Ma petite a neuf mois, elle est à la crèche.","note":"aller à la crèche = 上托儿所。"}},
 "Une effraction": {"pos":"n.f. 阴性名词，复数 effractions","s":"破门而入；撬门（闯入）。法律与警察用语。常说 vol avec effraction（入室盗窃）、entrer par effraction（强行闯入）。","ipa":"[e.fʁak.sjɔ̃]","ph":"e 读 [e]；ff 只读一个 [f]；r [ʁ]；a [a]；c 读 [k]；-tion 读 [sjɔ̃]。","pi":"ff 只读一个 [f]；ac 里的 c 读 [k]，不要漏掉；-tion 读 [sjɔ̃]；开头 e 读 [e]，不是 [ɛ]。","et":"来自拉丁语 effringere（打破）：ex- + frangere（折断）。同族：fracture、enfreindre。","ex":[["La police a constaté une effraction.","警方发现了撬门痕迹。"],["Il est entré par effraction.","他是破门而入的。"]],"co":[["entrer par effraction","破门而入"],["un vol avec effraction","入室盗窃"],["constater une effraction","发现撬门痕迹"]],"sy":[["cambriolage","courant","入室盗窃"],["intrusion","courant","闯入"],["vol","courant","偷窃"]],"fq":"中低频，新闻、警方通报中常见。","me":"ef-frac-tion：和 fracture（骨折）同源，「破」开。","tr":{"zh":"小偷破门而入。","fr":"Le voleur est entré par effraction.","alt":"Le cambrioleur a forcé la porte.","note":"par effraction 是固定搭配。"}},
 "Une goutte (d'eau)": {"pos":"n.f. 阴性名词，复数 gouttes","s":"（一）滴（水）。可指任何液体的一滴：une goutte de pluie、de sang。也用于比喻：une goutte d'eau dans la mer（沧海一粟）。","ipa":"[ɡut]","ph":"g [ɡ]；ou [u]；tt 读一个 [t]；结尾 e 不发音。","pi":"ou 读 [u]；tt 只读一个 [t]；g 在 ou 前读 [ɡ]，不是 [ʒ]。","et":"拉丁语 gutta（一滴）。","ex":[["Une goutte d'eau est tombée sur mon nez.","一滴水落在我的鼻子上。"],["Il pleut à grosses gouttes.","下着大雨点。"]],"co":[["une goutte de pluie","一滴雨"],["goutte à goutte","一滴一滴地"],["la goutte d'eau qui fait déborder le vase","压垮骆驼的最后一根稻草"],["une goutte d'eau dans l'océan","沧海一粟"]],"sy":[["larme","courant","眼泪"],["gouttelette","courant","小水滴"],["trace","courant","一点点"]],"fq":"中频，日常常用。","me":"gout-te：和 goutte à goutte 一起记，滴答滴答。","tr":{"zh":"雨一滴一滴地落下。","fr":"La pluie tombe goutte à goutte.","alt":"Il tombe quelques gouttes de pluie.","note":"goutte à goutte 是固定搭配。"}},
 "Une inauguration": {"pos":"n.f. 阴性名词，复数 inaugurations","s":"落成典礼；开幕仪式；揭幕。新建筑、展览、店铺的正式启用。动词 inaugurer。","ipa":"[i.no.ɡy.ʁa.sjɔ̃]","ph":"i [i]；n [n]；au 读 [o]；g 读 [ɡ]；u [y]；r [ʁ]；-tion 读 [sjɔ̃]。","pi":"in- 后面接元音 a 时，读 [i.no]，不是鼻化 [ɛ̃]；-au- 读 [o]；gu 读 [ɡy]。","et":"拉丁语 inauguratio，来自 inaugurare：古罗马占卜官（augure）看鸟的征兆后才开始新事业。","ex":[["L'inauguration du musée aura lieu demain.","博物馆的落成典礼明天举行。"],["Le maire a assisté à l'inauguration.","市长出席了落成典礼。"]],"co":[["l'inauguration d'un musée","博物馆落成典礼"],["assister à une inauguration","出席典礼"],["inaugurer un magasin","为商店剪彩"],["la cérémonie d'inauguration","落成仪式"]],"sy":[["ouverture","courant","开张、开幕，更日常"],["lancement","courant","发布、启动"],["cérémonie","courant","典礼"]],"fq":"中频，新闻、城市活动中常见。","me":"inaugurer：古罗马人先看鸟（augure）才开业。","tr":{"zh":"新图书馆明天落成。","fr":"La nouvelle bibliothèque est inaugurée demain.","alt":"L'inauguration de la nouvelle bibliothèque a lieu demain.","note":"inaugurer 是动词，被动式用 être inauguré(e)。"}},
 "Une interaction": {"pos":"n.f. 阴性名词，复数 interactions","s":"互动；相互作用。人与人的交流（interaction sociale），也用于科学、技术（interaction entre deux médicaments 药物相互作用）。形容词 interactif。","ipa":"[ɛ̃.tɛ.ʁak.sjɔ̃]","ph":"in 读鼻化 [ɛ̃]；t [t]；e 读 [ɛ]；r [ʁ]；ac 读 [ak]；-tion 读 [sjɔ̃]。","pi":"inter- 在这里读 [ɛ̃.tɛʁ]，in 是鼻化元音；-tion 读 [sjɔ̃]；是阴性。","et":"inter-（之间）+ action（行动），仿英语 interaction 形成。","ex":[["L'interaction entre les élèves est encouragée.","鼓励学生之间的互动。"],["Il y a peu d'interaction dans ce cours.","这门课互动很少。"]],"co":[["une interaction sociale","社交互动"],["l'interaction entre A et B","A 与 B 的相互作用"],["favoriser l'interaction","促进互动"]],"sy":[["échange","courant","交流"],["relation","courant","关系"],["communication","courant","沟通"]],"fq":"中频，教育、科技、社会学话题常见。","me":"inter（之间）+ action（动作）。","tr":{"zh":"老师鼓励学生互动。","fr":"Le professeur encourage l'interaction entre les élèves.","alt":"La prof pousse les élèves à interagir.","note":"动词形式是 interagir。"}},
 "Une nuisance": {"pos":"n.f. 阴性名词，常用复数 nuisances","s":"扰民；滋扰；公害。指噪音、气味、污染等让人不舒服的东西：nuisances sonores（噪音）、nuisances olfactives（异味）。动词 nuire（妨碍）。","ipa":"[nɥi.zɑ̃s]","ph":"nui 读 [nɥi]；s 在元音间读 [z]；an 读 [ɑ̃]；c 读 [s]；结尾 e 不发。","pi":"nui 读 [nɥi]，不是「努伊」；s 读 [z]，不是 [s]；-ance 读 [ɑ̃s]。","et":"来自 nuire（拉丁语 nocere）+ 后缀 -ance。同族：nuisible（有害的）。","ex":[["En ville, on souffre de nuisances sonores.","在城市里人们受噪音困扰。"],["Cette usine est une nuisance pour les voisins.","这家工厂对邻居是一种滋扰。"]],"co":[["les nuisances sonores","噪音扰民"],["les nuisances olfactives","异味污染"],["subir des nuisances","受到干扰"],["réduire les nuisances","减少扰民"]],"sy":[["gêne","courant","不便，困扰"],["dérangement","courant","打扰"],["pollution","courant","污染"]],"fq":"中频，城市、环境话题中常见。","me":"nuire → nui-sance：造成伤害的东西。","tr":{"zh":"夜里的噪音是个大问题。","fr":"Les nuisances sonores de la nuit sont un gros problème.","alt":"Le bruit la nuit, c'est un vrai problème.","note":"nuisances sonores 多用复数。"}},
 "Une ombre": {"pos":"n.f. 阴性名词，复数 ombres","s":"阴影；影子；荫凉。à l'ombre = 在阴凉处（反义 au soleil）。另有「幽灵般的身影」「一丝」的比喻：sans l'ombre d'un doute。","ipa":"[ɔ̃bʁ]","ph":"om 读鼻化 [ɔ̃]；b [b]；r [ʁ]；结尾 e 不发音，所以 [ɔ̃bʁ] 是一个音节。","pi":"om 是鼻化元音 [ɔ̃]，m 不发音；b 和 r 连读 [bʁ]，e 弱化。","et":"拉丁语 umbra（阴影）。同族：ombrelle（阳伞）、sombre（阴暗）。","ex":[["Je préfère m'asseoir à l'ombre.","我更喜欢坐在阴凉处。"],["Son ombre s'allonge sur le mur.","他的影子在墙上拉长。"]],"co":[["à l'ombre d'un arbre","在树荫下"],["sans l'ombre d'un doute","毫无疑问"],["une ombre au tableau","美中不足"],["rester dans l'ombre","躲在暗处，不出面"]],"sy":[["ombrage","soutenu","树荫"],["silhouette","courant","轮廓，剪影"],["fraîcheur","courant","凉意"]],"fq":"高频，日常常用。","me":"ombre ← umbra：和 ombrelle（遮阳小伞）同族。","tr":{"zh":"夏天我们坐在树荫下。","fr":"En été, nous nous asseyons à l'ombre d'un arbre.","alt":"L'été, on s'installe à l'ombre.","note":"s'asseoir à l'ombre = 坐在阴凉处。"}},
 "Une passerelle": {"pos":"n.f. 阴性名词，复数 passerelles","s":"人行天桥；步行桥；小桥。供行人通过的桥，如 la passerelle Simone-de-Beauvoir（巴黎）。也指船上的舷梯、飞机的登机桥。","ipa":"[pas.ʁɛl]","ph":"p [p]；a [a]；ss 读 [s]；e 在这里常弱读或不发；r [ʁ]；-elle 读 [ɛl]。","pi":"ss 读清音 [s]；-elle 读 [ɛl]，两个 l 只读一个；中间的 e 常省略，读成 [pas.ʁɛl]。","et":"词族：passer（经过）+ 指小后缀 -elle，意为「小的通道」。","ex":[["Nous avons traversé la rivière sur une passerelle.","我们走天桥过了河。"],["La passerelle est réservée aux piétons.","这座天桥只供行人通行。"]],"co":[["une passerelle piétonne","步行桥"],["traverser la passerelle","过天桥"],["jeter une passerelle","架一座桥（也比喻）"]],"sy":[["pont","courant","桥，更泛指"],["viaduc","courant","高架桥"],["échelle","courant","梯子"]],"fq":"中低频，城市、旅游话题常见。","me":"passer + -elle：「小」的「过」道。","tr":{"zh":"我们走人行天桥过铁路。","fr":"Nous traversons la voie ferrée par la passerelle.","alt":"On passe au-dessus de la voie ferrée par la passerelle.","note":"au-dessus de = 在……上方；par la passerelle = 经由天桥。"}},
 "Une péniche": {"pos":"n.f. 阴性名词，复数 péniches","s":"驳船；运河货船。在法国也常被改成住人的船屋（péniche aménagée），或做餐厅、书店等。","ipa":"[pe.niʃ]","ph":"é [e]；n [n]；i [i]；ch 读 [ʃ]；结尾 e 不发音。","pi":"ch 读 [ʃ]，不是 [k] 也不是「奇」；开头 é 读 [e]，重音符号不能漏；是阴性：une péniche。","et":"来源不确定（一般认为与英语 pinnace 有关）。","ex":[["Ils habitent sur une péniche amarrée sur la Seine.","他们住在塞纳河畔的船屋上。"],["Une péniche transporte du sable.","一条驳船运着沙子。"]],"co":[["habiter sur une péniche","住在船屋上"],["une péniche-restaurant","船上餐厅"],["un canal et ses péniches","运河与驳船"]],"sy":[["bateau","courant","船，更泛指"],["barge","soutenu","驳船（少用）"],["chaland","soutenu","平底货船"]],"fq":"中低频，旅游、描写景色时常见。","me":"péniche：沿着河运货的平底船。","tr":{"zh":"运河上有很多驳船。","fr":"Il y a beaucoup de péniches sur le canal.","alt":"On voit plein de péniches sur le canal.","note":"il y a beaucoup de + 名词。"}},
 "Une piste cyclable": {"pos":"n.f. 阴性名词词组，复数 pistes cyclables","s":"自行车道（专用车道）。piste 是「道、跑道」，cyclable 是形容词，意为「适合骑自行车的」，因此是阴性。","ipa":"[pist si.klabl]","ph":"piste：p [p]，ist 读 [ist]；cyclable：c 读 [s]，y 读 [i]，-able 读 [abl]。","pi":"cyclable 里 c 读 [s]，y 读 [i]；piste 的 s 要读，e 不发；注意形容词要和阴性名词配合。","et":"piste 借自意大利语 pista（足迹）；cyclable 由 cycle（希腊语 kuklos「圆」）+ -able 构成。","ex":[["La ville a construit une nouvelle piste cyclable.","城市修建了新的自行车道。"],["Je prends la piste cyclable pour aller au travail.","我骑自行车道去上班。"]],"co":[["rouler sur la piste cyclable","在自行车道上骑行"],["aménager des pistes cyclables","修建自行车道"],["une voie verte","绿道（步行与骑行）"]],"sy":[["voie cyclable","courant","自行车道，近义说法"],["bande cyclable","courant","路面划线的自行车道"],["trottoir","courant","人行道，不是自行车道"]],"fq":"中频，城市交通、环保话题常见。","me":"piste（道）+ cyclable（能骑车的）。","tr":{"zh":"我每天沿着自行车道骑车。","fr":"Je roule tous les jours sur la piste cyclable.","alt":"Tous les jours, je fais du vélo sur la piste cyclable.","note":"rouler sur 指在路面上行驶。"}},
 "Une préférence": {"pos":"n.f. 阴性名词，复数 préférences","s":"偏好；偏爱。avoir une préférence pour qch = 偏爱某物；de préférence = 最好是；par ordre de préférence = 按偏好顺序。动词 préférer。","ipa":"[pʁe.fe.ʁɑ̃s]","ph":"pr [pʁ]；é [e]；f [f]；é [e]；r [ʁ]；-ence 读 [ɑ̃s]。","pi":"两个 é 都读 [e]，不要漏掉第二个音节；-ence 读 [ɑ̃s]；préférence 里 f 后是 é。","et":"拉丁语 praeferre（置于……之前），pre- + ferre（带）。来自动词 préférer。","ex":[["J'ai une préférence pour le thé.","我偏爱茶。"],["Tu as une préférence entre les deux ?","这两个你更喜欢哪个？"]],"co":[["avoir une préférence pour","偏爱"],["de préférence","最好是"],["par ordre de préférence","按偏好排序"],["donner la préférence à","优先选择"]],"sy":[["goût","courant","品味，喜好"],["penchant","soutenu","倾向"],["priorité","courant","优先"]],"fq":"中高频，日常常用。","me":"préférer → préférence：先放前面的那个。","tr":{"zh":"我更喜欢乘火车，而不是坐飞机。","fr":"J'ai une préférence pour le train plutôt que l'avion.","alt":"Je préfère le train à l'avion.","note":"préférer A à B = 喜欢 A 胜过 B。"}},
 "Une programmation": {"pos":"n.f. 阴性名词，复数 programmations","s":"节目安排；排期（音乐节、电台、电影院的演出安排）；编程（informatique）。le programmeur 是程序员。","ipa":"[pʁɔ.ɡʁa.ma.sjɔ̃]","ph":"pr [pʁ]；o [ɔ]；gr [ɡʁ]；a [a]；mm 读一个 [m]；-tion 读 [sjɔ̃]。","pi":"mm 只读一个 [m]；o 读 [ɔ]；-tion 读 [sjɔ̃]；是阴性名词。","et":"由 programmer（安排）+ -ation 构成，programme 来自希腊语 programma（公告）。","ex":[["La programmation du festival est excellente.","音乐节的节目安排很棒。"],["Il apprend la programmation informatique.","他在学计算机编程。"]],"co":[["la programmation d'un festival","音乐节节目编排"],["la programmation informatique","计算机编程"],["un langage de programmation","编程语言"],["la programmation télé","电视节目表"]],"sy":[["planning","courant","日程表"],["calendrier","courant","日程，历法"],["codage","courant","编码"]],"fq":"中高频，文化、计算机领域常见。","me":"programme + -ation：把节目排进去。","tr":{"zh":"这家电影院的节目安排很好。","fr":"La programmation de ce cinéma est très bonne.","alt":"Ce cinéma a une très bonne programmation.","note":"programmation 是阴性名词。"}},
 "Une progression": {"pos":"n.f. 阴性名词，复数 progressions","s":"增长；进展；前进。可指数据增长（une progression des ventes）、学习进步、行进。和 progrès（进步）近义，但 progrès 更偏「进步」的结果。","ipa":"[pʁɔ.ɡʁɛ.sjɔ̃]","ph":"pr [pʁ]；o [ɔ]；gr [ɡʁ]；e 读 [ɛ]；ss 读 [s]；-ion 读 [jɔ̃]，即 [sjɔ̃]。","pi":"ss 读清音 [s]；注意 progression 读 [sjɔ̃]；不要把它读成 progrès。","et":"拉丁语 progressio，来自 progredi（前行）：pro- + gradi（走）。同族：progrès。","ex":[["On note une progression des ventes.","销量有所增长。"],["La progression des élèves est visible.","学生的进步很明显。"]],"co":[["en progression","在增长"],["une progression régulière","稳步增长"],["la progression des ventes","销量增长"],["être en progression constante","持续增长"]],"sy":[["augmentation","courant","增加"],["progrès","courant","进步"],["avancée","courant","进展"]],"fq":"中高频，新闻、经济、教育中常见。","me":"pro（向前）+ gress（走）：向前走。","tr":{"zh":"今年销量在增长。","fr":"Les ventes sont en progression cette année.","alt":"Cette année, les ventes progressent.","note":"être en progression = 在增长。"}},
 "Une promotion": {"pos":"n.f. 阴性名词，复数 promotions","s":"促销；打折（商品促销 en promotion）；晋升（职位升迁）；推广（promotion de la marche）。看上下文区分。","ipa":"[pʁɔ.mo.sjɔ̃]","ph":"pr [pʁ]；o [ɔ]；m [m]；o 读 [o]（闭口）；-tion 读 [sjɔ̃]。","pi":"第一个 o 读 [ɔ]，第二个 o 读 [o]；-tion 读 [sjɔ̃]；一词多义：促销、晋升、推广。","et":"拉丁语 promotio，来自 promovere（推向前）：pro- + movere（移动）。","ex":[["Ce produit est en promotion cette semaine.","这款产品本周促销。"],["Il a obtenu une promotion.","他得到了晋升。"]],"co":[["en promotion","在促销"],["obtenir une promotion","得到晋升"],["la promotion des ventes","促销活动"],["la promotion de la santé","健康推广"]],"sy":[["réduction","courant","折扣"],["avancement","courant","（职位）晋升"],["soldes","courant","季末大减价"]],"fq":"高频，日常常用。","me":"pro（向前）+ motion（动）：往前推 → 推广、晋升。","tr":{"zh":"这件外套正在促销。","fr":"Cette veste est en promotion.","alt":"Ce manteau est en promo.","note":"口语缩写 promo。"}},
 "Une ruelle": {"pos":"n.f. 阴性名词，复数 ruelles","s":"小巷；窄街。老城区的狭窄小路，多带怀旧、可爱的印象。比 rue 窄，比 impasse 通。","ipa":"[ʁɥɛl]","ph":"r [ʁ]；ue 读 [ɥɛ]（u 变成半元音 [ɥ] + [ɛ]）；ll 读 [l]；结尾 e 不发。","pi":"ru- 读 [ʁɥ]，一口气滑过去；不是 [ʁy.ɛl]；ll 读单个 [l]。","et":"rue + 指小后缀 -elle，意为「小街」。","ex":[["Nous nous sommes perdus dans les ruelles.","我们在小巷里迷了路。"],["Une ruelle étroite mène à la place.","一条窄巷通向广场。"]],"co":[["une ruelle étroite","狭窄的小巷"],["les ruelles du vieux village","老村里的小巷"],["se perdre dans les ruelles","在小巷里迷路"]],"sy":[["rue","courant","街道"],["allée","courant","林荫道，小径"],["impasse","courant","死胡同"]],"fq":"中低频，旅游、描写场景时常见。","me":"rue + -elle：「小」街。","tr":{"zh":"我们走进了一条窄小的小巷。","fr":"Nous sommes entrés dans une ruelle étroite.","alt":"On est entré dans une toute petite ruelle.","note":"entrer dans + 地点。"}},
 "Une tablée": {"pos":"n.f. 阴性名词，复数 tablées","s":"一桌人；同桌吃饭的一群人。une grande tablée = 一大桌人（热闹聚餐）。较口语化、有画面感，常用于家庭聚餐、节日。","ipa":"[ta.ble]","ph":"t [t]；a [a]；bl [bl]；-ée 读 [e]。","pi":"-ée 读 [e]，不是 [ee]；整词只有两个音节；是阴性。","et":"table + 后缀 -ée，表示「一桌所容纳的量」，如 cuillerée（一勺的量）、journée。","ex":[["C'était une grande tablée joyeuse.","那是欢乐的一大桌人。"],["La tablée a applaudi.","全桌的人都鼓掌了。"]],"co":[["une grande tablée","一大桌人"],["une tablée de convives","一桌宾客"],["toute la tablée","全桌的人"]],"sy":[["convives","courant","宾客，赴宴的人"],["invités","courant","客人"],["table","courant","桌子；一桌人"]],"fq":"低频，描写聚餐场景时用。","me":"table + -ée：像 cuillerée（一勺），「一桌」的量。","tr":{"zh":"整桌人都笑了。","fr":"Toute la tablée a ri.","alt":"Tout le monde à table a ri.","note":"tablée 当作单数，动词用单数。"}},
 "Une transition": {"pos":"n.f. 阴性名词，复数 transitions","s":"转型；过渡；转变。la transition écologique（生态转型）、une période de transition（过渡期）。也指文章里的承接、过渡句。","ipa":"[tʁɑ̃.zi.sjɔ̃]","ph":"tr [tʁ]；an 读 [ɑ̃]；s 在元音间读 [z]；-tion 读 [sjɔ̃]。","pi":"s 读 [z]，不是 [s]；an 读鼻化 [ɑ̃]；-tion 读 [sjɔ̃]。","et":"拉丁语 transitio，来自 transire（穿过）：trans- + ire（去）。","ex":[["La transition écologique est nécessaire.","生态转型是必要的。"],["Cette période est une transition difficile.","这段时间是艰难的过渡。"]],"co":[["la transition écologique","生态转型"],["une période de transition","过渡期"],["en transition","处于转变中"],["faire la transition","完成过渡"]],"sy":[["passage","courant","过渡，通过"],["changement","courant","变化"],["évolution","courant","演变"]],"fq":"中高频，新闻、政治、经济中常见。","me":"trans（穿过）+ it（去）：从一边走到另一边。","tr":{"zh":"我们正处在能源转型之中。","fr":"Nous sommes en pleine transition énergétique.","alt":"On est en train de faire la transition énergétique.","note":"en pleine + 名词 = 正处于……之中。"}},
 "Une vallée": {"pos":"n.f. 阴性名词，复数 vallées","s":"山谷；河谷。两山之间的低地，常有河流穿过：la vallée de la Loire、la vallée de Chamonix。","ipa":"[va.le]","ph":"v [v]；a [a]；ll 读 [l]；-ée 读 [e]。","pi":"ll 读单个 [l]，不是 [j]；-ée 读 [e]；第一个音节 val 不发 [valle]，读 [va.le]。","et":"val（拉丁语 vallis）+ -ée，意为「山谷」。同族：val、vallon。","ex":[["La rivière traverse la vallée.","河流穿过山谷。"],["Ce village est au fond de la vallée.","这个村子在山谷深处。"]],"co":[["la vallée de la Loire","卢瓦尔河谷"],["au fond de la vallée","在山谷深处"],["une vallée profonde","深谷"]],"sy":[["val","littéraire","山谷（多见于地名）"],["vallon","courant","小山谷"],["gorge","courant","峡谷"]],"fq":"中频，旅游、地理常见。","me":"val + -ée：山间一条「谷」。","tr":{"zh":"我们沿着山谷走。","fr":"Nous marchons le long de la vallée.","alt":"On suit la vallée à pied.","note":"le long de = 沿着。"}},
 "Un(e) gérant(e)": {"pos":"n. 名词，阳性 gérant，阴性 gérante；复数 gérants / gérantes","s":"经理；店长；管理人。一般指商店、餐厅、公寓的受托管理者，不是公司老板。动词 gérer（管理）。比 directeur 更偏「受托经营」。","ipa":"[ʒe.ʁɑ̃]","ph":"g 在 é 前读 [ʒ]；é [e]；r [ʁ]；-ant 读 [ɑ̃]，阴性 -ante 读 [ɑ̃t]。","pi":"g 读 [ʒ]；阳性词尾 -ant 的 t 不发，阴性才发 [t]；注意不要读 [ɡeʁɑ̃]。","et":"gérer（拉丁语 gerere「执行，管理」）+ -ant（做某事的人）。","ex":[["Le gérant du magasin est très sympathique.","商店经理很友好。"],["La gérante du restaurant parle anglais.","餐厅的女经理会说英语。"]],"co":[["le gérant d'un magasin","商店店长"],["un gérant d'immeuble","物业管理员"],["le gérant de la société","公司的执行经理"]],"sy":[["directeur","courant","主任，经理，权限更大"],["responsable","courant","负责人"],["patron","familier","老板"]],"fq":"中频，工作、商店场景常见。","me":"gérer + -ant：负责「管理」的人。","tr":{"zh":"店长今天不在。","fr":"Le gérant n'est pas là aujourd'hui.","alt":"Le gérant est absent aujourd'hui.","note":"女店长用 la gérante。"}},
 "Un(e) sociologue": {"pos":"n. 名词，阳阴同形，un / une sociologue；复数 sociologues","s":"社会学家；研究社会的学者。学科叫 la sociologie，形容词 sociologique。阳阴性同形，用冠词区分性别。","ipa":"[sɔ.sjɔ.lɔɡ]","ph":"so 读 [sɔ]；cio 读 [sjɔ]；lo 读 [lɔ]；-gue 读 [ɡ]；结尾 e 不发。","pi":"-gue 读 [ɡ]，不是 [ʒ]；c 在这里读 [s]；整词重音在最后一个音节。","et":"由 socio-（拉丁语 socius「伙伴」）+ -logue（希腊语 logos「学」）构成；sociologie 是孔德所造的词。","ex":[["La sociologue étudie le comportement humain.","社会学家研究人类行为。"],["Un sociologue parle à la radio.","一位社会学家在电台发言。"]],"co":[["un sociologue spécialiste de…","研究……的社会学家"],["l'avis d'un sociologue","社会学家的意见"],["un sociologue de la famille","家庭社会学家"]],"sy":[["anthropologue","courant","人类学家"],["psychologue","courant","心理学家"],["chercheur","courant","研究员"]],"fq":"中低频，学术、新闻评论中出现。","me":"socio（社会）+ logue（学者）：研究社会的人。","tr":{"zh":"这位社会学家研究城市生活。","fr":"Ce sociologue étudie la vie urbaine.","alt":"Cette sociologue travaille sur la vie en ville.","note":"职业名词阴阳同形：un / une sociologue。"}},
 "Les marées / Marée basse / Marée haute": {"pos":"n.f. 阴性名词，marée 复数 marées（多用复数 les marées）","s":"潮汐；潮水。marée basse = 退潮；marée haute = 涨潮。la marée montante / descendante = 涨潮 / 落潮。也有 marée noire（海上漏油污染）。","ipa":"[ma.ʁe]","ph":"m [m]；a [a]；r [ʁ]；-ée 读 [e]；marée basse 读 [ma.ʁe bas]，basse 的 ss 读 [s]。","pi":"-ée 读 [e]；basse 的 ss 读 [s]，e 不发音；haute 的 h 不发音，au 读 [o]，t 不发，所以 haute 读 [ot]。","et":"marée 与 mer（海）同源，来自拉丁语 mare（海），加后缀 -ée。","ex":[["Nous nous promenons à marée basse.","我们在退潮时散步。"],["À marée haute, la plage disparaît.","涨潮时，海滩消失了。"]],"co":[["à marée basse","在退潮时"],["à marée haute","在涨潮时"],["le coefficient de marée","潮汐系数"],["une marée noire","海上石油泄漏"]],"sy":[["flux et reflux","soutenu","涨与落（书面）"],["marnage","soutenu","潮差（专业词）"],["houle","courant","涌浪"]],"fq":"中频，海滨、天气、新闻常用。","me":"marée ← mer：海的「呼吸」。","tr":{"zh":"退潮时可以走到小岛上。","fr":"À marée basse, on peut aller à pied jusqu'à l'île.","alt":"Quand la marée est basse, on peut marcher jusqu'à l'île.","note":"à marée basse 前不加冠词。"}},
 "Une lampe torche / Une lampe de poche": {"pos":"n.f. 阴性名词词组，复数 lampes torches / lampes de poche","s":"手电筒。lampe torche 和 lampe de poche 都可以，前者更口语、更常用。torche 是「火把」，lampe 是「灯」。","ipa":"[lɑ̃p tɔʁʃ]","ph":"lampe：lam 读 [lɑ̃]，p 要发音 [p]；torche：to 读 [tɔ]，r [ʁ]，ch 读 [ʃ]。poche：[pɔʃ]。","pi":"lampe 的 p 要读；ch 读 [ʃ]；lampe de poche 里 de 读弱音 [də]。","et":"lampe 来自希腊语 lampas（火炬）；torche 来自拉丁语 torqua（扭成的东西，指拧成的火把）。poche 与 pocket 同族，来自日耳曼语。","ex":[["J'ai besoin d'une lampe torche dans le noir.","黑暗中我需要手电筒。"],["Prends ta lampe de poche pour la cave.","去地窖时带上手电筒。"]],"co":[["allumer la lampe torche","打开手电筒"],["une lampe torche à piles","电池手电筒"],["éclairer avec une lampe de poche","用手电筒照明"]],"sy":[["lampe frontale","courant","头灯"],["torche électrique","courant","手电筒（少用）"],["lanterne","courant","提灯，灯笼"]],"fq":"中频，日常常用。","me":"lampe torche = 灯 + 火把，拿在手里。","tr":{"zh":"没有电了，快拿手电筒。","fr":"Il n'y a plus d'électricité, prends la lampe torche !","alt":"Panne de courant, sors la lampe de poche !","note":"il n'y a plus de = 不再有。"}},
 "Des rénovations": {"pos":"n.f.pl. 阴性复数名词，单数 une rénovation","s":"翻修；整修工程。指建筑物的修缮与更新，多用复数 des rénovations。动词 rénover。des travaux 是更通用的「施工」。","ipa":"[ʁe.nɔ.va.sjɔ̃]","ph":"r [ʁ]；é [e]；n [n]；o [ɔ]；va [va]；-tion 读 [sjɔ̃]。","pi":"-tion 读 [sjɔ̃]；é 读 [e]；重音在最后一个音节。","et":"拉丁语 renovatio，来自 renovare（更新）：re-（再）+ novus（新的）。同族：nouveau、innovation。","ex":[["Des rénovations sont prévues dans l'immeuble.","大楼计划翻修。"],["Ils font des rénovations dans leur cuisine.","他们在翻修厨房。"]],"co":[["faire des rénovations","进行翻修"],["la rénovation d'un appartement","公寓翻修"],["fermé pour rénovation","因翻修关闭"],["la rénovation énergétique","节能改造"]],"sy":[["travaux","courant","工程，更泛指"],["réfection","soutenu","修复（正式）"],["restauration","courant","修复（文物）"]],"fq":"中频，房屋、城市话题常见。","me":"re（再）+ nov（新）：再次变新。","tr":{"zh":"我们要翻修客厅。","fr":"Nous allons rénover le salon.","alt":"On va faire des rénovations dans le salon.","note":"rénover 是动词，faire des rénovations 是名词说法。"}},
 "Des ruines": {"pos":"n.f.pl. 阴性复数名词，单数 une ruine","s":"废墟；遗迹。指古迹或毁坏的建筑，多用复数：les ruines romaines。单数 une ruine 也可指破产、毁灭。en ruine = 破败不堪。","ipa":"[ʁɥin]","ph":"r [ʁ]；ui 读 [ɥi]；n [n]；结尾 e 不发。","pi":"ui 读 [ɥi]，一口气滑过，不是「乌-伊」；复数 s 不发音。","et":"拉丁语 ruina（坠落），来自 ruere（倒塌）。","ex":[["On peut visiter les ruines du château.","可以参观城堡的废墟。"],["La maison est en ruine.","这座房子破败不堪。"]],"co":[["les ruines romaines","古罗马遗迹"],["tomber en ruine","倒塌成废墟"],["en ruine(s)","破败"],["visiter des ruines","参观遗迹"]],"sy":[["vestiges","soutenu","遗迹（更书面）"],["décombres","courant","瓦砾"],["restes","courant","残留物"]],"fq":"中频，旅游、历史常用。","me":"ruine：ru-ine，像「塌」下来。","tr":{"zh":"我们参观了古罗马遗迹。","fr":"Nous avons visité les ruines romaines.","alt":"On a visité des ruines romaines.","note":"ruines 常用复数。"}},
 "Des vignes": {"pos":"n.f.pl. 阴性复数名词，单数 une vigne","s":"葡萄藤；葡萄园。une vigne 是一株葡萄藤，les vignes 常指整片葡萄园。vignoble 是一个产酒地区的葡萄种植区。","ipa":"[viɲ]","ph":"v [v]；i [i]；gn 读 [ɲ]；结尾 e 不发。","pi":"gn 读 [ɲ]（像「尼」），不是 [ɡn]；e 不发音；复数 s 不发。","et":"拉丁语 vinea（葡萄园），来自 vinum（酒）。同族：vin、vigneron。","ex":[["La région est connue pour ses vignes.","这个地区以葡萄园闻名。"],["Les vignes sont belles en automne.","秋天的葡萄园很美。"]],"co":[["les vignes d'Alsace","阿尔萨斯的葡萄园"],["tailler la vigne","修剪葡萄藤"],["un vigneron","葡萄农，酿酒人"],["les vendanges","葡萄采收季"]],"sy":[["vignoble","courant","葡萄种植区，更大的范围"],["raisin","courant","葡萄（果实）"],["viticulture","soutenu","葡萄栽培业"]],"fq":"中频，旅游、美食话题常见。","me":"vigne → vin：葡萄藤酿出葡萄酒。","tr":{"zh":"秋天，我们去葡萄园采摘。","fr":"En automne, nous allons faire les vendanges dans les vignes.","alt":"À l'automne, on va aux vendanges dans les vignes.","note":"faire les vendanges = 采收葡萄。"}},
 "Les commodités": {"pos":"n.f.pl. 阴性复数名词，单数 une commodité","s":"便利设施；生活设施（商店、交通、水电等）：les commodités de la vie moderne。也有「方便」的义项（pour plus de commodité）。注意旧语里 les commodités 也可委婉指厕所。","ipa":"[kɔ.mɔ.di.te]","ph":"c [k]；o [ɔ]；mm 读一个 [m]；o [ɔ]；d [d]；i [i]；é [e]。","pi":"mm 读一个 [m]；两个 o 都读 [ɔ]；重音在最后 té；是阴性复数：les commodités。","et":"拉丁语 commoditas（方便），来自 commodus（合适的，方便的）。同族：commode（柜子；方便的）、incommoder。","ex":[["Toutes les commodités sont près de chez nous.","所有设施都在我们家附近。"],["L'hôtel offre toutes les commodités.","这家酒店设施齐全。"]],"co":[["toutes les commodités","一应俱全的设施"],["pour plus de commodité","为了更方便"],["les commodités de la vie moderne","现代生活的便利"]],"sy":[["équipements","courant","设施、设备"],["services","courant","服务"],["confort","courant","舒适设施"]],"fq":"中频，租房、旅游话题常见。","me":"commode（方便）→ commodités：让生活方便的东西。","tr":{"zh":"附近有所有生活设施。","fr":"Toutes les commodités sont à proximité.","alt":"Il y a tout ce qu'il faut à côté.","note":"commodités 用复数，配 toutes les。"}},
 "Les forces de l'ordre": {"pos":"n.f.pl. 阴性复数名词词组，单数 la force de l'ordre 很少用","s":"执法部门；警察和宪兵等执法力量。指 police 和 gendarmerie 等维护治安的人员，较正式，新闻里常见。","ipa":"[fɔʁs də lɔʁdʁ]","ph":"forces：o 读 [ɔ]，r [ʁ]，c 读 [s]，结尾 es 不发；de l'ordre：l' 省音，o 读 [ɔ]，-dre 读 [dʁ]。","pi":"ordre 里 r 和 dre 要读 [ɔʁdʁ]；forces 末尾 -es 不发音；用复数 les forces。","et":"force（拉丁语 fortis「强的」）+ ordre（拉丁语 ordo「秩序」）。","ex":[["Les forces de l'ordre sont intervenues rapidement.","执法人员迅速出动。"],["Les forces de l'ordre contrôlent la manifestation.","执法人员在管控游行。"]],"co":[["les forces de l'ordre","执法部门"],["intervenir rapidement","迅速介入"],["faire appel aux forces de l'ordre","请求执法人员协助"],["une intervention des forces de l'ordre","执法人员的出动"]],"sy":[["police","courant","警察"],["gendarmerie","courant","宪兵队"],["flics","argot","警察（俚语）"]],"fq":"中高频，新闻中极常见。","me":"force（力量）+ ordre（秩序）：维持秩序的力量。","tr":{"zh":"执法人员很快到了现场。","fr":"Les forces de l'ordre sont arrivées rapidement sur place.","alt":"La police est vite arrivée sur les lieux.","note":"sur place = 在现场。"}},
 "Les personnes à mobilité réduite": {"pos":"n.f.pl. 阴性复数名词词组，缩写 PMR","s":"行动不便者（如轮椅使用者、老人、孕妇等）。公共场所、交通中的官方用语，缩写 PMR。比 handicapés 更中性、礼貌。","ipa":"[pɛʁ.sɔn a mɔ.bi.li.te ʁe.dɥit]","ph":"personnes：per 读 [pɛʁ]，-sonnes 读 [sɔn]；à 读 [a]；mobilité：[mɔ.bi.li.te]；réduite：ui 读 [ɥi]，结尾 te 读 [t]。","pi":"réduite 里 ui 读 [ɥi]，t 要发；mobilité 重音在最后 té；personne 是阴性，所以 réduite 也用阴性。","et":"personne（拉丁语 persona「面具、人」）+ mobilité（拉丁语 mobilis，源于 movere「动」）+ réduite（réduire，拉丁语 reducere「带回、减少」）。","ex":[["Ce bus est adapté pour les personnes à mobilité réduite.","这辆公交车适合行动不便的人。"],["L'ascenseur est réservé aux personnes à mobilité réduite.","电梯专供行动不便者使用。"]],"co":[["accessible aux PMR","无障碍通行"],["une place pour personnes à mobilité réduite","无障碍车位"],["adapté aux PMR","适合行动不便者"],["une rampe d'accès","无障碍坡道"]],"sy":[["handicapés","courant","残障者，较直接"],["personnes âgées","courant","老年人"],["personnes en situation de handicap","soutenu","残障人士，更尊重的表述"]],"fq":"中频，公共服务、交通常见。","me":"PMR = personnes à mobilité réduite，标志上常见。","tr":{"zh":"地铁站为行动不便者装了电梯。","fr":"La station de métro a un ascenseur pour les personnes à mobilité réduite.","alt":"Il y a un ascenseur pour les PMR dans cette station.","note":"PMR 读作 [pe.ɛm.ɛʁ]。"}},
 "Des aménagements": {"pos":"n.m. 阳性名词，常用复数 aménagements（单数 aménagement）","s":"整治；改造；设施。指对场地、房屋、道路做的改建和布置，如 aménagements urbains（城市整治）、aménagements pour les vélos（自行车设施）。也可指制度上的调整，如 aménagement des horaires（弹性调整时间）。","ipa":"[a.me.naʒ.mɑ̃]","ph":"a-mé-nage-ment；é [e]；g 在 e 前读 [ʒ]；-ent 是名词后缀，读鼻化音 [ɑ̃]，t 不发。","pi":"结尾 -ment 读 [mɑ̃]，不发 -ent 的 e 和 t；一个 m、一个 n，别写成 amménagement。","et":"由动词 aménager 加后缀 -ment 构成；aménager 来自 à + ménage（家务、家）。同族：ménager、déménager、emménager。","ex":[["Des aménagements ont été faits pour les vélos.","已为自行车做了整治。"],["La mairie prévoit des aménagements dans le quartier.","市政府计划在这个街区做改造。"],["Nous demandons un aménagement des horaires.","我们要求调整一下时间表。"]],"co":[["des aménagements routiers","道路整治工程"],["l'aménagement du territoire","国土整治规划"],["un aménagement des horaires","时间安排的调整"],["l'aménagement intérieur","室内布置"]],"sy":[["travaux","courant","工程，施工，范围更宽"],["équipement","courant","设备，设施"],["ajustement","courant","调整（不指场地）"]],"fq":"中高频，新闻和公告里常见。","me":"aménager = 把一个地方弄得像「家」(ménage) 一样好用。","tr":{"zh":"市政府在公园里做了新的改造。","fr":"La mairie a fait de nouveaux aménagements dans le parc.","alt":"La mairie a réaménagé le parc.","note":"aménagements 常用复数；réaménager = 重新改造。"}},
 "Des lampions": {"pos":"n.m. 阳性名词，复数 lampions（单数 lampion）","s":"纸灯笼；节庆用的彩色灯笼（常挂在广场上，7月14日国庆夜的 retraite aux lampions 提灯游行）。注意：不是房间里的台灯，台灯是 lampe。","ipa":"[lɑ̃.pjɔ̃]","ph":"lam-pion；an/am [ɑ̃]；pi-on 连成 [pjɔ̃]，结尾鼻化 [ɔ̃]，n 不发。","pi":"am 读 [ɑ̃]，不是 [am]；ion 读 [jɔ̃]，不要拆成两个音节。","et":"来自意大利语 lampione（大灯），与 lampe（灯）同族。","ex":[["La place est décorée avec des lampions.","广场上装饰着纸灯笼。"],["Les enfants portent des lampions dans la rue.","孩子们在街上提着灯笼。"]],"co":[["allumer des lampions","点亮灯笼"],["la retraite aux lampions","提灯游行"],["un lampion en papier","纸灯笼"]],"sy":[["lanterne","courant","灯笼，更泛指"],["lampe","courant","灯，台灯"],["lumignon","littéraire","小灯头；烛火"]],"fq":"低频，节日话题里会出现。","me":"lamp + ion：和 lampe 一家，节日里挂起来的「大灯」。","tr":{"zh":"7月14日晚上，街上挂满了纸灯笼。","fr":"Le soir du 14 juillet, la rue est pleine de lampions.","alt":"Le 14 juillet au soir, il y a des lampions partout dans la rue.","note":"lampion 是阳性名词；灯笼在复数里常配 des。"}},
 "Des moyens": {"pos":"n.m. 阳性名词，常用复数 moyens（单数 moyen）","s":"财力；手段；方法。avoir les moyens = 有钱负担得起；les moyens de transport = 交通工具。单数 un moyen 是「办法」，复数 des moyens 常指「钱」或「能力」。","ipa":"[mwa.jɛ̃]","ph":"moy-en：oy 读 [wa] + [j]，所以 moyen 读 [mwa.jɛ̃]；en 读鼻化 [ɛ̃]；复数 s 不发。","pi":"en 在 moyen 里读 [ɛ̃]，不读 [ɑ̃]；复数 moyens 和单数发音相同。","et":"来自拉丁语 medianus（居中的），与 milieu、médian 同族。","ex":[["Je n'ai pas les moyens.","我负担不起。"],["Il y a plusieurs moyens de payer.","有好几种付款方式。"],["Ils vivent au-dessus de leurs moyens.","他们超出自己的能力过日子。"]],"co":[["avoir les moyens de + inf.","有能力（钱）做……"],["un moyen de transport","交通工具"],["les moyens financiers","财力"],["par tous les moyens","用一切办法"]],"sy":[["ressources","courant","资源，财力"],["méthode","courant","方法，侧重步骤"],["fortune","soutenu","财富，更大笔的钱"]],"fq":"极高频，日常常用。","me":"moyen = 「居中」的东西，用来到达目的的「中间手段」。","tr":{"zh":"我们没有钱买新车。","fr":"Nous n'avons pas les moyens d'acheter une voiture neuve.","alt":"On n'a pas les moyens de s'acheter une voiture neuve.","note":"avoir les moyens de + 动词原形；les 不能换成 des。"}},
 "Des reproches": {"pos":"n.m. 阳性名词，常用复数 reproches（单数 reproche）","s":"责备；指责；抱怨。faire des reproches à quelqu'un = 责备某人。动词是 reprocher qqch à qqn（因某事责怪某人）。","ipa":"[ʁə.pʁɔʃ]","ph":"re-proche：r 是小舌音 [ʁ]；re 读 [ʁə]；o 读开口 [ɔ]；ch [ʃ]。","pi":"ch 读 [ʃ]，像「西」不像 [k]；o 是 [ɔ]，不是 [o]；复数 s 不发。","et":"来自动词 reprocher；其更早的词源有争议，来源不确定。同族：irréprochable（无可指责）。","ex":[["Elle m'a fait des reproches injustifiés.","她无端责备我。"],["Il ne supporte pas les reproches.","他受不了别人的指责。"],["Je ne te fais aucun reproche.","我一点也不怪你。"]],"co":[["faire des reproches à qqn","责备某人"],["un reproche justifié / injuste","合理 / 不公的指责"],["sans reproche","无可指责的"],["Je te le reproche.","我为此怪你。"]],"sy":[["critique","courant","批评，较中性"],["blâme","soutenu","谴责，更正式"],["remontrance","soutenu","训诫（长辈对晚辈）"]],"fq":"中高频，日常人际话题里常见。","me":"re-proche：把错「拉回到眼前」说出来。","tr":{"zh":"老师没有责备他。","fr":"Le professeur ne lui a fait aucun reproche.","alt":"Le prof ne lui a pas fait de reproches.","note":"否定句里 des reproches 变成 de reproches 或 aucun reproche。"}},
 "Les bouchons (les embouteillages)": {"pos":"n.m. 阳性名词，复数 bouchons（口语中 les bouchons = 堵车；单数 bouchon = 瓶塞、堵塞）","s":"堵车；交通堵塞。口语说 Il y a des bouchons，正式说 embouteillages。单数 un bouchon 的本义是瓶塞，所以路被「塞住」也叫 bouchon。里昂一带也有 bouchon 指传统小餐馆。","ipa":"[bu.ʃɔ̃]","ph":"bou-chon：ou [u]；ch [ʃ]；on 读鼻化 [ɔ̃]，n 不发。","pi":"ch 读 [ʃ]；on 的 n 不发音；embouteillage 里的 ill 读 [j]：[ɑ̃.bu.tɛ.jaʒ]。","et":"bouchon 是 boucher（塞住）的名词形式，来自古法语 bousche（一束草）；embouteillage 来自 embouteiller（装瓶；塞住），源自 bouteille（瓶子）。","ex":[["Je suis en retard à cause des bouchons.","我因为堵车迟到了。"],["Il y a toujours des bouchons le vendredi soir.","星期五晚上总是堵车。"],["Nous sommes pris dans un bouchon.","我们被堵在路上了。"]],"co":[["être pris dans les bouchons","被堵在路上"],["Il y a des bouchons.","在堵车。"],["un bouchon sur l'autoroute","高速公路上的堵车"],["un bouchon de bouteille","瓶塞"]],"sy":[["embouteillage","courant","堵车，较正式"],["circulation dense","courant","车流量大"],["ralentissement","courant","车速变慢，没那么严重"]],"fq":"高频，日常交通话题里常用。","me":"路像瓶子被瓶塞 (bouchon) 堵住，车出不去。","tr":{"zh":"早上上班路上总是堵车。","fr":"Il y a toujours des bouchons le matin pour aller au travail.","alt":"Le matin, on est toujours dans les bouchons pour aller bosser.","note":"堵车说 des bouchons 或 des embouteillages，复数居多。"}},
 "Accéder": {"pos":"v. 不及物动词（第一组，变位同 céder），常接 à","s":"到达；进入；获得（权利、职位）；访问（网站、文件）。accéder à + 名词：accéder à un site / à un poste / à la propriété。","ipa":"[ak.se.de]","ph":"cc 在 e 前读 [ks]；é [e]；结尾 -er 读 [e]，r 不发。","pi":"cc 读 [ks]，不是 [k]；变位 j'accède，nous accédons，é 和 è 会换。","et":"来自拉丁语 accedere（走近）。同族：accès、accessible、céder。","ex":[["Comment peut-on accéder à ce dossier ?","如何才能查阅这份档案？"],["On accède au village par un petit chemin.","要走一条小路才能到这个村子。"],["Elle a accédé à la direction de l'entreprise.","她升任了公司的领导职位。"]],"co":[["accéder à un site / à un fichier","访问网站 / 文件"],["accéder à un poste","获得某个职位"],["accéder à la propriété","买到自己的房子"],["accéder à une demande","答应一项请求"]],"sy":[["atteindre","courant","到达，够到"],["entrer","courant","进入，更日常"],["parvenir à","soutenu","达到，终于抵达"]],"fq":"中高频，书面语和工作语境常见。","me":"ac-céder：往前「走近」(cedere)，就得到「通路」(accès)。","tr":{"zh":"从花园可以进入房子。","fr":"On accède à la maison par le jardin.","alt":"Pour entrer dans la maison, on passe par le jardin.","note":"accéder 后一定接 à，不能直接接宾语。"}},
 "Accumuler": {"pos":"v. 及物动词（第一组），有时用代词式 s'accumuler","s":"积累；堆积；囤积。可以指物品、经验、债务、疲劳等：accumuler des richesses / de l'expérience / du retard。代词式 s'accumuler = 越积越多。","ipa":"[a.ky.my.le]","ph":"ac-cu-mu-ler：cc 在 u 前读一个 [k]；u 读 [y]（嘴唇圆而小）；结尾 -er 读 [e]。","pi":"u 读 [y]，别读成 [u]；拼写是 accumuler（两个 c，一个 m），不要写成 acumuler。","et":"来自拉丁语 accumulare（堆起来），源自 cumulus（堆）。同族：cumul、cumulus（积云）。","ex":[["Il a tendance à accumuler les objets inutiles.","他总爱囤积无用的东西。"],["Les dettes s'accumulent.","债务越积越多。"],["Elle a accumulé beaucoup d'expérience.","她积累了很多经验。"]],"co":[["accumuler du retard","越拖越晚"],["accumuler les erreurs","错误越犯越多"],["s'accumuler","越积越多"],["accumuler de l'expérience","积累经验"]],"sy":[["amasser","courant","聚敛，常指钱和财富"],["entasser","courant","堆起来，杂乱地"],["stocker","courant","存储（物资）"]],"fq":"中频，书面语和说明文常见。","me":"cumul-：一层一层「堆」成小山。","tr":{"zh":"她攒了很多旧书。","fr":"Elle a accumulé beaucoup de vieux livres.","alt":"Elle a entassé plein de vieux livres chez elle.","note":"accumuler 是及物动词，直接接宾语。"}},
 "Advenir": {"pos":"v. 不规则动词（变位同 venir），助动词 être，多用第三人称","s":"发生；降临；变成（结果如何）。多用于非人称：il advient que...（碰巧发生……）。Que va-t-il advenir de... ? = 之后会怎么样？ 书面语，口语里更常说 arriver 或 se passer。","ipa":"[ad.və.niʁ]","ph":"ad-ve-nir：d 在这里发 [d]；ve 弱读 [və]；结尾 -ir 读 [iʁ]。","pi":"d 要发音，不要读成 [a.və.niʁ]；复合时态：il est advenu，用 être。","et":"来自拉丁语 advenire（到来）。同族：avenir（未来）、venir、événement。","ex":[["Que va-t-il advenir de ce vieux bâtiment ?","这栋老建筑会变成什么样？"],["Quoi qu'il advienne, je reste.","无论发生什么，我都留下。"],["Il est advenu un accident étrange.","发生了一起奇怪的事故。"]],"co":[["Qu'est-il advenu de... ?","……后来怎么样了？"],["advienne que pourra","听天由命；该来的总会来"],["quoi qu'il advienne","无论发生什么"],["il advient que + 直陈式","碰巧……"]],"sy":[["arriver","courant","发生，口语常用"],["se produire","courant","发生（事件）"],["survenir","soutenu","突然发生"]],"fq":"低频，书面语，新闻和文学里出现。","me":"ad + venir：「朝你走来」的事，也就是将要发生的事 (avenir)。","tr":{"zh":"不知道这家店后来怎么样了。","fr":"Je ne sais pas ce qu'il est advenu de ce magasin.","alt":"Je me demande ce que ce magasin est devenu.","note":"advenir 用 être；口语常换成 devenir 或 arriver。"}},
 "Alerter": {"pos":"v. 及物动词（第一组）","s":"发出警报；通知；使警觉。alerter les secours / la police = 通知救援 / 报警；alerter l'opinion = 引起舆论注意。","ipa":"[a.lɛʁ.te]","ph":"a-ler-ter：e 读开口 [ɛ]；r 小舌音；结尾 -er 读 [e]。","pi":"e 读 [ɛ]，不读 [ə]；与英语 alert 同形，但这里是动词。","et":"来自名词 alerte，源于意大利语 all'erta（「在高处」，即警戒着）。","ex":[["Il faut alerter les secours immédiatement.","必须立即通知救援。"],["Le voisin a alerté la police.","邻居报了警。"],["Les médias alertent le public sur ce danger.","媒体提醒公众注意这个危险。"]],"co":[["alerter la police / les pompiers","报警 / 通知消防员"],["alerter l'opinion publique","引起舆论注意"],["donner l'alerte","发出警报"],["alerter qqn sur qqch","提醒某人注意某事"]],"sy":[["avertir","courant","告知，警告"],["prévenir","courant","通知，提前告知"],["signaler","courant","报告，指出"]],"fq":"中频，新闻和突发事件里常见。","me":"alerter = 发出 alerte！像英语 alert 一样。","tr":{"zh":"他看到火，马上通知了消防员。","fr":"Il a vu le feu et il a tout de suite alerté les pompiers.","alt":"Il a vu le feu, alors il a prévenu les pompiers.","note":"alerter 直接接人或机构，不加 à。"}},
 "Avancer": {"pos":"v. 第一组动词（nous avançons，ç 在 a/o 前）","s":"前进；向前移动；有进展；提前；垫付（钱）。J'avance = 我在往前走 / 进展不错；ma montre avance = 我的表走快了；avancer de l'argent = 垫钱。","ipa":"[a.vɑ̃.se]","ph":"a-van-cer：an 读鼻化 [ɑ̃]；c 在 e 前读 [s]；结尾 -er 读 [e]。","pi":"an 读 [ɑ̃]，不是 [an]；nous avançons 要加 cédille ç；及物与不及物都能用。","et":"来自拉丁语 abante，后演变出 avant（前面）；因此 avancer = 向前。同族：avance、avant。","ex":[["Le projet commence à avancer.","项目开始有进展。"],["Ma montre avance de cinq minutes.","我的表快了五分钟。"],["Peux-tu m'avancer cinquante euros ?","你能先借我垫五十欧元吗？"]],"co":[["avancer vite / lentement","进展快 / 慢"],["avancer dans son travail","工作有进展"],["avancer de l'argent à qqn","给某人垫钱"],["La montre avance.","表走快了。"]],"sy":[["progresser","courant","进步，进展"],["reculer","courant","后退，反义"],["s'avancer","courant","向前走近（代词式）"]],"fq":"极高频，日常常用。","me":"avancer = 往「前」(avant) 走。","tr":{"zh":"我的工作进展得不错。","fr":"Mon travail avance bien.","alt":"Je suis en train de bien avancer dans mon travail.","note":"avancer 作「有进展」讲时用不及物；用 bien / vite 修饰。"}},
 "Concilier": {"pos":"v. 及物动词（第一组）","s":"使协调；使兼顾；使调和。concilier A et B = 让 A 与 B 并存，如 concilier travail et famille。也可指使两个对立的人或意见达成一致。","ipa":"[kɔ̃.si.lje]","ph":"con-ci-lier：on 读鼻化 [ɔ̃]；c 在 i 前读 [s]；-lier 读 [lje]。","pi":"ci 读 [si]，不是 [ki]；-lier 读 [lje]；nous concilions 读 [kɔ̃.si.ljɔ̃]，i 和 ons 连成 [jɔ̃]。","et":"来自拉丁语 conciliare（联合），源自 concilium（会议）。同族：concile、conciliation、réconcilier。","ex":[["Il est difficile de concilier vie familiale et professionnelle.","兼顾家庭和职业很难。"],["Elle essaie de concilier ses études et son travail.","她努力兼顾学习和工作。"]],"co":[["concilier A et B","兼顾 A 和 B"],["concilier des opinions","调和不同意见"],["se concilier la sympathie de qqn","赢得某人好感"],["concilier vie privée et vie professionnelle","平衡私人与职业生活"]],"sy":[["réconcilier","courant","使和好（人与人）"],["harmoniser","courant","使协调一致"],["allier","soutenu","把……结合起来"]],"fq":"中频，常见于正式和工作话题。","me":"con + cilier：把不同的事「聚在一起」开会 (concile) 达成共识。","tr":{"zh":"她很难兼顾工作和孩子。","fr":"Elle a du mal à concilier son travail et ses enfants.","alt":"C'est dur pour elle de jongler entre le travail et les enfants.","note":"concilier A et B，A 和 B 之间用 et。"}},
 "Condamner": {"pos":"v. 及物动词（第一组）","s":"封死；封堵；判刑；谴责。condamner une porte = 把门封死；condamner qqn à + 刑罚 = 判某人……；condamner un acte = 谴责某种行为。","ipa":"[kɔ̃.da.ne]","ph":"con-dam-ner：mn 里的 m 不发音，只读 [n]；on 读鼻化 [ɔ̃]；-ner 读 [ne]。","pi":"m 不发音：condamner 读 [kɔ̃.da.ne]，不是 [kɔ̃.dam.ne]；同样的有 damner。","et":"来自拉丁语 condemnare（判罪），源自 damnum（损失）。同族：damner、dommage。","ex":[["La porte du fond a été condamnée.","后面的门被封死了。"],["Le tribunal l'a condamné à deux ans de prison.","法院判他两年监禁。"],["Tout le monde condamne cette violence.","大家都谴责这种暴力。"]],"co":[["condamner une porte / une fenêtre","封死门 / 窗"],["condamner qqn à une amende","判某人罚款"],["condamner un acte","谴责某种行为"],["être condamné à + inf.","被迫……；注定要……"]],"sy":[["dénoncer","courant","揭发，谴责"],["blâmer","soutenu","指责"],["murer","courant","用墙封住"]],"fq":"中高频，新闻和法律语境常见。","me":"con-damn：被「判」(damnum 损失)，也可以把门「判死刑」封掉。","tr":{"zh":"这扇窗被封死了，打不开。","fr":"Cette fenêtre est condamnée, on ne peut pas l'ouvrir.","alt":"On a condamné cette fenêtre, elle ne s'ouvre plus.","note":"被动式：être condamné(e)；过去分词要与主语一致。"}},
 "Craindre": {"pos":"v. 不规则动词（第三组）：je crains, nous craignons, craint","s":"害怕；担心；怕（天气、东西）。craindre de + 动词原形 / craindre que + 虚拟式：je crains qu'il ne vienne pas。语气比 avoir peur 稍正式。","ipa":"[kʁɛ̃dʁ]","ph":"crain-dre：ain 读 [ɛ̃]；结尾 -dre 读 [dʁ]，轻读，没有额外的 e。","pi":"变位里 n 的变化：je crains（ɛ̃）、nous craignons（ɲɔ̃）；过去分词 craint 的 t 不发。","et":"来自通俗拉丁语 *cremere，由拉丁语 tremere（发抖）演变；同族：crainte、craintif。","ex":[["Elle craint de rater son examen.","她害怕考试失败。"],["Je crains qu'il ne soit trop tard.","我担心已经太晚了。"],["Cette plante craint le froid.","这种植物怕冷。"]],"co":[["craindre de + inf.","怕做……"],["craindre que + subj.","担心……"],["craindre le froid / la chaleur","怕冷 / 怕热"],["Ne craignez rien.","什么都不用怕。"]],"sy":[["avoir peur","courant","害怕，最日常"],["redouter","soutenu","畏惧，很担心"],["appréhender","soutenu","忧虑，预感不好"]],"fq":"中频，书面和正式语气居多。","me":"crain-dre：害怕时人会发抖 (tremere)，音也像 trembler。","tr":{"zh":"我担心他今晚不会来。","fr":"Je crains qu'il ne vienne pas ce soir.","alt":"J'ai peur qu'il ne vienne pas ce soir.","note":"craindre que 后用虚拟式；ne 是可省的虚词。"}},
 "Décéder": {"pos":"v. 不及物动词（第一组，变位同 céder），助动词 être","s":"去世；逝世。比 mourir 正式，常见于讣告、公文、新闻：il est décédé。不用于动物（动物用 mourir 或 crever）。","ipa":"[de.se.de]","ph":"dé-cé-der：两个 é 都读 [e]，c 在 é 前读 [s]；结尾 -er 读 [e]。","pi":"助动词用 être：il est décédé，不是 il a décédé；名词是 décès [de.sɛ]，不是 décéder 的写法。","et":"来自拉丁语 decedere（离开、退去）。同族：décès、céder。","ex":[["Son grand-père est décédé l'année dernière.","他的祖父去年去世了。"],["Elle est décédée à l'hôpital.","她在医院去世了。"],["Mon oncle est décédé hier soir.","我叔叔昨晚去世了。"]],"co":[["être décédé(e)","去世了"],["la personne décédée","逝者"],["décéder d'une maladie","因病去世"],["un acte de décès","死亡证明"]],"sy":[["mourir","courant","死，最通用"],["s'éteindre","soutenu","安详离世（委婉）"],["disparaître","soutenu","逝世（委婉说法）"]],"fq":"中频，正式与书面场合。","me":"dé-céder：从人世「退走」(cedere)。","tr":{"zh":"我的外婆三年前去世了。","fr":"Ma grand-mère est décédée il y a trois ans.","alt":"Ma grand-mère est morte il y a trois ans.","note":"décéder 用 être，过去分词与主语一致：décédée。"}},
 "Dédier à": {"pos":"v. 及物动词（第一组），常用结构 dédier qqch à qqn / à qqch","s":"献给；题献；专用于。dédier un livre à sa mère = 把书献给母亲；un parc dédié aux enfants = 专为孩子设立的公园。比 consacrer 更偏「献词、纪念」。","ipa":"[de.dje]","ph":"dé-dier：é [e]；-dier 连成 [dje]；结尾 -er 读 [e]。","pi":"ie 读 [je]，别读成两个音节 [di.e]；dédier 与 dédicacer（签名题赠）意思不同。","et":"来自拉丁语 dedicare（奉献，宣告）。同族：dédicace、dédicacer。","ex":[["Ce parc est dédié aux enfants.","这个公园是献给孩子们的。"],["Il a dédié son livre à sa famille.","他把书献给了家人。"],["Ce monument est dédié aux soldats morts.","这座纪念碑是献给阵亡士兵的。"]],"co":[["dédier un livre à qqn","把书献给某人"],["être dédié(e) à qqch","专用于……；献给……"],["dédier sa vie à + nom / inf.","把一生献给……"],["une chanson dédiée à qqn","献给某人的歌"]],"sy":[["consacrer","courant","奉献，用于"],["offrir","courant","赠送"],["vouer","soutenu","献身于"]],"fq":"中低频，书面语和文化话题。","me":"dédier ≈ dedicate：把东西「宣告」属于某人。","tr":{"zh":"她把这首歌献给她的朋友。","fr":"Elle a dédié cette chanson à son amie.","alt":"Elle a fait cette chanson pour son amie.","note":"dédier qqch à qqn；à 后接人或对象。"}},
 "Définir": {"pos":"v. 及物动词（第二组，-issons）：je définis, nous définissons","s":"下定义；确定；规定。définir un mot = 给词下定义；définir un objectif / des règles = 确定目标 / 规则。代词式 se définir = 给自己定位。","ipa":"[de.fi.niʁ]","ph":"dé-fi-nir：é [e]；i [i]；-ir 读 [iʁ]。变位 nous définissons 读 [de.fi.ni.sɔ̃]。","pi":"第二组动词，要加 -iss-：nous définissons，不是 nous définons。","et":"来自拉丁语 definire（划定界限），源自 finis（界限）。同族：fini、finir、défini、définition。","ex":[["Pouvez-vous définir ce mot ?","您能定义这个词吗？"],["Il faut définir les règles du jeu.","必须确定游戏规则。"],["Elle se définit comme une artiste.","她把自己定位为艺术家。"]],"co":[["définir un mot","给词下定义"],["définir un objectif","确定目标"],["bien défini(e)","界定清楚的"],["se définir comme + nom","把自己定义为……"]],"sy":[["préciser","courant","说明得更精确"],["fixer","courant","确定（日期、价格）"],["caractériser","soutenu","描述特征"]],"fq":"中高频，学习、工作场合常用。","me":"dé-finir：给事情划下「边界」(fin)。","tr":{"zh":"请先确定你的目标。","fr":"Définissez d'abord votre objectif, s'il vous plaît.","alt":"Commencez par définir votre objectif.","note":"命令式：définis / définissons / définissez。"}},
 "Dégrader": {"pos":"v. 及物动词（第一组），代词式 se dégrader","s":"破坏；损毁；使恶化；贬低。dégrader un bâtiment = 损坏建筑；la situation se dégrade = 局势恶化。词的力度比 endommager 更强，带有「越来越糟」的意味。","ipa":"[de.ɡʁa.de]","ph":"dé-gra-der：g 在 r 前读 [ɡ]；é [e]；-er 读 [e]。","pi":"不要读成 [de.ɡʁa.dɛʁ]；结尾 er 不发 r；和英语 degrade 意思相近但更偏「损坏」。","et":"来自拉丁语 degradare（降级），源自 gradus（台阶、等级）。同族：grade、dégradation、gradation。","ex":[["Les vandales ont dégradé l'arrêt de bus.","破坏者损毁了公交站。"],["La situation se dégrade vite.","形势恶化得很快。"],["Le mauvais temps dégrade les routes.","坏天气损坏道路。"]],"co":[["dégrader un bien public","破坏公共财物"],["se dégrader","变坏；恶化"],["la dégradation de l'environnement","环境恶化"],["des conditions de vie dégradées","恶化的生活条件"]],"sy":[["abîmer","courant","弄坏，最日常"],["détériorer","soutenu","使变坏"],["endommager","courant","损坏（较中性）"]],"fq":"中频，新闻里常见。","me":"dé-grader：从高处「降级」(gradus 台阶) 往下掉。","tr":{"zh":"天气变坏，路况也变差了。","fr":"Avec le mauvais temps, l'état des routes se dégrade.","alt":"Le mauvais temps a abîmé les routes.","note":"状态变差用代词式 se dégrader。"}},
 "Dépendre de": {"pos":"v. 不及物动词（第三组，变位同 vendre）：je dépends, il dépend","s":"取决于；依靠；隶属于。Ça dépend. = 看情况。dépendre de + 名词 / 代词 / 疑问词：Ça dépend du prix / de toi / de ce qu'il dit。","ipa":"[de.pɑ̃dʁ]","ph":"dé-pen-dre：en 读鼻化 [ɑ̃]；结尾 -dre 读 [dʁ]，d 不是重读。","pi":"常与 dépenser（花钱）混淆；dépendre 之后必须有 de；il dépend，d 不发音。","et":"来自拉丁语 dependere（悬挂在……上），源自 pendere（悬）。同族：pendre、suspendre、dépendant、indépendant。","ex":[["Tout va dépendre de la météo.","一切取决于天气。"],["Ça dépend de toi.","这取决于你。"],["Ça dépend, je ne sais pas encore.","看情况，我还不知道。"]],"co":[["Ça dépend.","看情况。"],["dépendre de qqn / qqch","取决于某人 / 某事"],["dépendre d'un parent","靠父母供养"],["Ça dépend de ce que...","要看……"]],"sy":[["reposer sur","soutenu","建立在……之上"],["tenir à","courant","在于，归因于"],["relever de","soutenu","属于……管辖"]],"fq":"极高频，日常常用。","me":"dé-pendre：像东西「挂」(pendre) 在别的东西上面，自己做不了主。","tr":{"zh":"能不能出门要看天气。","fr":"Sortir ou non, ça dépend du temps.","alt":"On verra, ça dépend de la météo.","note":"dépendre de；de 与 le 缩合为 du。"}},
 "Descendre": {"pos":"v. 第三组动词（变位同 vendre）；不及物用 être，及物用 avoir","s":"下去；下来；下车；下降；把……拿下来。Je descends. = 我下去 / 我下车。及物时：il a descendu les escaliers（他下了楼梯），复合时态改用 avoir。","ipa":"[de.sɑ̃dʁ]","ph":"des-cen-dre：sc 在 e 前读 [s]；en 读 [ɑ̃]；结尾 -dre 读 [dʁ]。","pi":"不及物用 être：elle est descendue；及物用 avoir：elle a descendu la valise；sc 读 [s]，别读成 [sk]。","et":"来自拉丁语 descendere（走下），由 de- + scandere（攀登）构成。同族：descendant、ascendant。","ex":[["Fais attention en descendant les escaliers.","下楼梯要小心。"],["Je descends au prochain arrêt.","我在下一站下车。"],["Elle a descendu la valise de la chambre.","她把行李箱从房间拿下来了。"]],"co":[["descendre l'escalier","下楼梯"],["descendre du bus / du train","下公交 / 火车"],["descendre à l'hôtel","住进旅馆"],["La température descend.","气温下降。"]],"sy":[["monter","courant","上去，反义"],["baisser","courant","降低（价格、温度）"],["dévaler","soutenu","急速冲下"]],"fq":"极高频，日常常用。","me":"descendre = de + scandere：与「上升」(monter) 相反，走下台阶。","tr":{"zh":"我在下一站下车。","fr":"Je descends au prochain arrêt.","alt":"Moi, c'est le prochain arrêt, je descends.","note":"不及物时助动词用 être：je suis descendu(e)。"}},
 "Diviser": {"pos":"v. 及物动词（第一组），代词式 se diviser","s":"分开；分割；使分裂；除（数学）。diviser un gâteau en parts = 把蛋糕分成几份；ce sujet divise les gens = 这个话题让人意见分歧；dix divisé par deux = 十除以二。","ipa":"[di.vi.ze]","ph":"di-vi-ser：两个 i 读 [i]；s 在元音之间读 [z]；-er 读 [e]。","pi":"s 读 [z]，不是 [s]；数学说 diviser A par B，不是 de。","et":"来自拉丁语 divisus（dividere 的过去分词，分开）。同族：division、divisible、indivisible。","ex":[["Ce sujet divise les gens.","这个话题让人们产生分歧。"],["Divisez le gâteau en huit parts.","把蛋糕切成八份。"],["Dix divisé par deux font cinq.","十除以二等于五。"]],"co":[["diviser en parts","分成若干份"],["diviser A par B","A 除以 B"],["se diviser en deux groupes","分成两组"],["diviser pour mieux régner","分而治之"]],"sy":[["partager","courant","分享，分开给别人"],["séparer","courant","分开，使分离"],["fractionner","soutenu","分成小块"]],"fq":"高频，日常和数学都常用。","me":"diviser ≈ divide：切开成几份，数学里就是「除」。","tr":{"zh":"我们把蛋糕分成六份。","fr":"Nous divisons le gâteau en six parts.","alt":"On coupe le gâteau en six parts.","note":"diviser A en N parts；除法用 diviser A par B。"}},
 "Éblouir": {"pos":"v. 及物动词（第二组，-issons）：j'éblouis, nous éblouissons","s":"使目眩；使看不见（光太强）；使惊叹、倾倒。Le soleil m'éblouit. = 阳光刺得我睁不开眼。也用于比喻：éblouir le public（让观众惊艳）。","ipa":"[e.blu.iʁ]","ph":"é-blou-ir：ou [u]，后面 i 另成一个音节，读 [blu.iʁ]；é [e]。","pi":"ou 和 i 分开读：[blu.iʁ]，不要读成 [blwiʁ]；第二组动词，加 -iss-。","et":"来自古法语 esblouir，更早的来源不确定。同族：éblouissant、éblouissement。","ex":[["Le soleil m'éblouit.","阳光刺眼。"],["Les phares m'ont ébloui.","车灯晃得我睁不开眼。"],["Son talent a ébloui le public.","她的才华让观众惊艳。"]],"co":[["être ébloui(e) par la lumière","被强光晃到"],["éblouir le public","让观众惊艳"],["une lumière éblouissante","耀眼的光"],["se laisser éblouir par qqch","被……迷住"]],"sy":[["aveugler","courant","使失明，晃瞎"],["fasciner","courant","使着迷"],["émerveiller","soutenu","使惊叹"]],"fq":"中频，日常和文学里都有。","me":"éblouir ≈ 眼前一片「白」被光「打晕」。","tr":{"zh":"对面来的车灯晃到我了。","fr":"Les phares de la voiture d'en face m'ont ébloui.","alt":"Les phares d'en face m'ont aveuglé.","note":"第二组，复合过去时：j'ai ébloui。"}},
 "Économiser": {"pos":"v. 及物动词（第一组）","s":"节省；省钱；存钱。économiser de l'argent / de l'énergie / de l'eau。不及物也可用：Il économise pour ses vacances。也可以指省去（时间、力气）。","ipa":"[e.kɔ.nɔ.mi.ze]","ph":"é-co-no-mi-ser：é [e]；o 读开口 [ɔ]；s 在元音间读 [z]；-er 读 [e]。","pi":"s 读 [z]；o 是开口的 [ɔ]，不是 [o]；别和 épargner（存钱，偏金融）混用。","et":"来自 économie，源自希腊语 oikonomia（家政管理）。同族：économe、économique、économiste。","ex":[["J'essaie d'économiser de l'argent pour mes vacances.","我努力为假期存钱。"],["Éteins la lumière pour économiser l'électricité.","关灯，节约用电。"],["Cette machine nous fait économiser du temps.","这台机器帮我们省时间。"]],"co":[["économiser de l'argent","存钱，省钱"],["économiser de l'énergie","节能"],["économiser pour + nom","为……攒钱"],["économiser son souffle","省点力气不说话"]],"sy":[["épargner","courant","储蓄，金融语境"],["mettre de côté","courant","存起来"],["dépenser","courant","花钱，反义"]],"fq":"高频，日常常用。","me":"économie → économiser：像管家一样把钱「管得省一点」。","tr":{"zh":"我想存钱去旅行。","fr":"Je veux économiser de l'argent pour voyager.","alt":"Je mets de l'argent de côté pour partir en voyage.","note":"économiser de l'argent，de 加不定冠词意义的名词。"}},
 "Embêter": {"pos":"v. 及物动词（第一组），代词式 s'embêter（觉得无聊）","s":"打扰；烦人；使为难。Arrête de m'embêter ! = 别烦我！属于口语，比 déranger 随意。s'embêter = 觉得无聊；ne pas s'embêter = 不费心。","ipa":"[ɑ̃.bɛ.te]","ph":"em-bê-ter：em 读 [ɑ̃]；ê 读 [ɛ]；-ter 读 [te]；最后 -er 读 [e]。","pi":"em 读 [ɑ̃]，不是 [ɛm]；ê 读 [ɛ]，不是 [e]。口语，不太适合在很正式的场合。","et":"由 en- + bête（笨，兽）构成，意思是使人「烦」。同族：bête、embêtant、embêtement。","ex":[["Arrête de m'embêter avec tes questions !","别再用你的问题烦我了！"],["Ça m'embête de te demander ça.","我很不好意思问你这个。"],["Je m'embête à la maison.","我在家很无聊。"]],"co":[["embêter qqn","烦某人"],["Ça m'embête.","这让我为难 / 烦。"],["s'embêter","无聊"],["ne pas s'embêter avec qqch","不用费心管……"]],"sy":[["déranger","courant","打扰，较礼貌"],["agacer","courant","惹恼"],["casser les pieds","familier","烦人，很口语"]],"fq":"高频，口语常用。","me":"em-bêter：被弄得像「傻瓜」一样烦。","tr":{"zh":"别烦我，我在工作。","fr":"Arrête de m'embêter, je travaille.","alt":"Fiche-moi la paix, je bosse.","note":"arrêter de + 动词原形：别再……。"}},
 "Emmagasiner": {"pos":"v. 及物动词（第一组）","s":"储存；存放；积蓄（热量、知识、能量）。emmagasiner de la chaleur / des provisions / des connaissances。比 stocker 稍书面。","ipa":"[ɑ̃.ma.ɡa.zi.ne]","ph":"em-ma-ga-zi-ner：em 读 [ɑ̃]；双 m 只读一个 [m]；s 在元音间读 [z]。","pi":"emm- 读 [ɑ̃m]，不是 [ɛm]；记住 magasin 的 s 读 [z]。","et":"由 en- + magasin 构成；magasin 来自阿拉伯语 makhāzin（仓库，makhzan 的复数）。","ex":[["Le bitume emmagasine la chaleur.","沥青储存热量。"],["Les fourmis emmagasinent de la nourriture.","蚂蚁储存食物。"],["Il emmagasine beaucoup de connaissances.","他积累了很多知识。"]],"co":[["emmagasiner de la chaleur","蓄热"],["emmagasiner des provisions","储存食物"],["emmagasiner des connaissances","积累知识"],["emmagasiner de l'énergie","储存能量"]],"sy":[["stocker","courant","储存，最常用"],["entreposer","soutenu","存放在仓库"],["accumuler","courant","积累"]],"fq":"低频，书面语和科学文章。","me":"em-magasin-er：放进「仓库」(magasin) 里。","tr":{"zh":"夏天，墙会储存热量。","fr":"En été, les murs emmagasinent la chaleur.","alt":"L'été, les murs stockent la chaleur.","note":"emmagasiner 是及物动词，直接接宾语。"}},
 "Encadrer": {"pos":"v. 及物动词（第一组）","s":"给……装框；围在两侧；指导、带领；规范、限制。encadrer un tableau = 给画装框；encadrer des élèves = 带学生；encadrer les loyers = 对房租设上限。","ipa":"[ɑ̃.ka.dʁe]","ph":"en-ca-drer：en 读 [ɑ̃]；c 在 a 前读 [k]；-drer 读 [dʁe]。","pi":"en 读 [ɑ̃]，不是 [ɛ̃]；注意与 cadre 一样 c 读 [k]。","et":"由 en- + cadre 构成；cadre 来自意大利语 quadro（方形），源自拉丁语 quadrum。","ex":[["Il faut encadrer les loyers.","必须限制房租。"],["Un moniteur encadre les enfants.","一位辅导员带着孩子们。"],["Elle a fait encadrer la photo.","她把照片装了框。"]],"co":[["encadrer un tableau / une photo","给画 / 照片装框"],["encadrer des élèves","指导、管理学生"],["encadrer les prix","规范价格"],["être bien encadré(e)","有人好好带领"]],"sy":[["réglementer","soutenu","制定规则管理"],["superviser","courant","监督，指导"],["limiter","courant","限制"]],"fq":"中频，新闻和管理话题。","me":"en + cadre：给事情「套上框架」，就是管起来。","tr":{"zh":"我们需要有人来带这些学生。","fr":"Il faut quelqu'un pour encadrer ces élèves.","alt":"On a besoin d'un adulte pour s'occuper de ces élèves.","note":"encadrer 直接接宾语；Il faut + 名词 / 动词原形。"}},
 "Endommager": {"pos":"v. 及物动词（第一组）：nous endommageons","s":"损坏；弄坏；使受损。多指物件、建筑、车辆：endommager le toit / la voiture。过去分词 endommagé(e) 常作形容词，「受损的」。","ipa":"[ɑ̃.dɔ.ma.ʒe]","ph":"en-dom-ma-ger：en 读 [ɑ̃]；mm 只读一个 [m]；g 在 e 前读 [ʒ]。","pi":"mm 读 [m]，不重读；变位 nous endommageons，要保留 e 才能读 [ʒ]。","et":"由 en- + dommage 构成；dommage 来自古法语 damage，源自拉丁语 damnum（损失）。同族：dommage、dédommager。","ex":[["La tempête a endommagé le toit.","风暴损坏了屋顶。"],["La voiture a été endommagée dans l'accident.","车在事故中受损了。"],["Ne l'endommage pas, c'est fragile.","别弄坏它，很易碎。"]],"co":[["endommager un bâtiment","损坏建筑"],["être gravement endommagé(e)","严重受损"],["endommager un appareil","损坏设备"],["des biens endommagés","受损的财物"]],"sy":[["abîmer","courant","弄坏，最日常"],["détériorer","soutenu","使变坏"],["dégrader","courant","损毁，带破坏意味"]],"fq":"中频，新闻和保险话题。","me":"en + dommage + er：造成「损害」(dommage)。","tr":{"zh":"雨水损坏了地板。","fr":"La pluie a endommagé le plancher.","alt":"La pluie a abîmé le plancher.","note":"过去分词 endommagé 作被动时要与主语一致。"}},
 "Ériger": {"pos":"v. 及物动词（第一组）：nous érigeons","s":"竖立；建立；使成为。ériger une statue / un monument = 立一座雕像 / 纪念碑；ériger en principe = 把……定为原则；s'ériger en juge = 以法官自居。书面语。","ipa":"[e.ʁi.ʒe]","ph":"é-ri-ger：é [e]；g 在 i 前读 [ʒ]；-er 读 [e]。","pi":"nous érigeons 要有 e，才能保持 [ʒ]；这是正式词，不用于日常谈话。","et":"来自拉丁语 erigere（竖起），由 ex- + regere（引导）构成。同族：érection、régir。","ex":[["Une statue a été érigée sur la place.","广场上竖起了一座雕像。"],["On a érigé un monument à sa mémoire.","人们为纪念他立了一座碑。"],["Il s'érige en défenseur des pauvres.","他自诩为穷人的保护者。"]],"co":[["ériger une statue / un monument","立雕像 / 纪念碑"],["ériger en principe","定为原则"],["s'ériger en + nom","自封为……"],["ériger un mur","筑起一道墙"]],"sy":[["dresser","courant","竖起，较日常"],["bâtir","courant","建造"],["édifier","soutenu","修建（大型建筑）"]],"fq":"低频，书面、新闻和历史文本。","me":"ériger ≈ erect：把东西「竖直」立起来。","tr":{"zh":"他们在村子中间竖起了一座雕像。","fr":"Ils ont érigé une statue au centre du village.","alt":"On a dressé une statue au milieu du village.","note":"被动：une statue a été érigée。"}},
 "Escalader": {"pos":"v. 及物动词（第一组）","s":"攀登；攀爬；翻越。escalader une montagne / un mur / une clôture。强调要用手脚一起用力往上爬，比 monter 费劲。","ipa":"[ɛs.ka.la.de]","ph":"es-ca-la-der：e 读开口 [ɛ]；sc 在 a 前读 [sk]；-er 读 [e]。","pi":"sc 在 a 前读 [sk]，不读 [s]；与 escale（停靠）、escalier（楼梯）同族但意思不同。","et":"来自名词 escalade，源自意大利语 scalata（攀登），与 scala（梯子）有关。同族：escalier、échelle。","ex":[["Ils ont décidé d'escalader la montagne.","他们决定攀登这座山。"],["Le garçon a escaladé le mur.","男孩翻过了那堵墙。"],["Elle aime escalader des rochers.","她喜欢攀岩。"]],"co":[["escalader une montagne","攀登一座山"],["escalader un mur / une clôture","翻墙 / 翻栅栏"],["l'escalade","攀岩；攀登"],["faire de l'escalade","做攀岩运动"]],"sy":[["grimper","courant","爬，更日常"],["gravir","soutenu","攀登（高处）"],["franchir","courant","越过，跨过"]],"fq":"中频，运动和户外话题。","me":"escalade：像沿着「梯子」(scala) 往上爬。","tr":{"zh":"我们周末去攀那座山。","fr":"Ce week-end, nous allons escalader cette montagne.","alt":"Ce week-end, on va grimper sur cette montagne.","note":"escalader 直接接宾语，不加介词。"}},
 "Estimer": {"pos":"v. 及物动词（第一组）","s":"估计；估价；认为；尊重。estimer le prix à... = 估价为……；j'estime que... = 我认为……；estimer qqn = 看重某人。常用于正式表达观点。","ipa":"[ɛs.ti.me]","ph":"es-ti-mer：e 读开口 [ɛ]；s 在 t 前读 [s]；-mer 读 [me]。","pi":"e 读 [ɛ]，不是 [e]；估价意义里常加 à：estimer à 1 000 euros。","et":"来自拉丁语 aestimare（估价）。同族：estime、estimation、sous-estimer、surestimer。","ex":[["Les experts estiment les dégâts à un million d'euros.","专家估计损失为一百万欧元。"],["J'estime que tu as raison.","我认为你是对的。"],["Je l'estime beaucoup.","我很敬重他。"]],"co":[["estimer à + 数额","估价为……"],["estimer que + 直陈式","认为……"],["s'estimer heureux / chanceux","觉得自己幸运"],["sous-estimer / surestimer","低估 / 高估"]],"sy":[["évaluer","courant","评估，估算"],["penser","courant","想，认为"],["juger","courant","判断，认为"]],"fq":"高频，工作和新闻语境常用。","me":"estimer ≈ estimate：给事物「估一个数」。","tr":{"zh":"我认为这个价格太贵了。","fr":"J'estime que ce prix est trop élevé.","alt":"Je trouve que c'est trop cher.","note":"肯定句中 estimer que 后用直陈式。"}},
 "Établir": {"pos":"v. 及物动词（第二组，-issons），代词式 s'établir","s":"建立；制定；确定；证明。établir une règle / un contact / un record = 制定规则 / 建立联系 / 创纪录；s'établir à Lyon = 在里昂定居。","ipa":"[e.ta.bliʁ]","ph":"é-ta-blir：é [e]；t [t]；bl 连读 [bl]；-ir 读 [iʁ]。","pi":"第二组动词，nous établissons；拼写 é 开头，别漏掉重音。","et":"来自拉丁语 stabilire（使稳固），源自 stabilis。词首的 s 在法语里变成了 é：établir ≈ stable、état 同族。","ex":[["Ils ont établi de nouvelles règles.","他们制定了新规则。"],["Elle s'est établie à Lyon en 2020.","她2020年在里昂定居。"],["La police a établi les faits.","警方查明了事实。"]],"co":[["établir des règles","制定规则"],["établir un contact","建立联系"],["établir un record","创纪录"],["s'établir à + 地点","在某地定居"]],"sy":[["fonder","courant","创立"],["créer","courant","创造，新建"],["instaurer","soutenu","确立，实行"]],"fq":"高频，正式和书面场合常用。","me":"établir ≈ establish：把东西「稳」(stable) 地立起来。","tr":{"zh":"我们要制定新的规则。","fr":"Nous devons établir de nouvelles règles.","alt":"On doit mettre en place de nouvelles règles.","note":"établir 是第二组动词，nous établissons。"}},
 "Exclure": {"pos":"v. 不规则动词（第三组）：j'exclus, nous excluons, 过去分词 exclu","s":"排除；开除；不包括；排斥。exclure qqn d'un groupe = 把某人排除在团体之外；exclure une possibilité = 排除一种可能。","ipa":"[ɛk.sklyʁ]","ph":"ex-clure：ex 在这里读 [ɛks]；cl 连读；u 读 [y]；结尾 -re 读 [ʁ]。","pi":"u 读 [y]；过去分词 exclu 不是 excluse，阴性才加 e：exclue；变位 j'exclus 的 s 不发。","et":"来自拉丁语 excludere（关在门外），由 ex- + claudere（关）构成。同族：inclure、conclure、clore。","ex":[["Il ne faut exclure personne du groupe.","不应该把任何人排除在团体之外。"],["Cet élève a été exclu du lycée.","这个学生被学校开除了。"],["On ne peut pas exclure cette hypothèse.","我们不能排除这种假设。"]],"co":[["exclure qqn de qqch","把某人排除在……之外"],["exclure une possibilité","排除一种可能"],["être exclu(e) de l'école","被开除出校"],["tout est exclu / rien n'est exclu","一切都不排除 / 什么都有可能"]],"sy":[["écarter","courant","排除，拨开"],["renvoyer","courant","开除，解雇"],["inclure","courant","包括，反义"]],"fq":"中高频，新闻和正式场合。","me":"ex-clure：ex = 外，clure = 关：关在门外。","tr":{"zh":"我们不能把任何孩子排除在游戏之外。","fr":"On ne peut exclure aucun enfant du jeu.","alt":"On ne doit laisser aucun enfant de côté dans le jeu.","note":"exclure qqn de qqch；否定里用 aucun。"}},
 "Expulser": {"pos":"v. 及物动词（第一组）","s":"驱逐；赶走；开除（球员出场）。expulser un locataire = 把房客赶出去；expulser un étranger = 驱逐出境；expulser un joueur = 罚下球员。","ipa":"[ɛks.pyl.se]","ph":"ex-pul-ser：ex 读 [ɛks]；u 读 [y]；l 和 s 连读；-er 读 [e]。","pi":"x 读 [ks]；u 读 [y]；与英语 expel 对应但词形不同。","et":"来自拉丁语 expulsare（反复驱赶），源自 expellere（赶出去）。同族：expulsion、pulsion、impulsion。","ex":[["Le locataire a été expulsé de son appartement.","房客被赶出了公寓。"],["Le joueur a été expulsé du terrain.","这名球员被罚下场。"],["Le pays a expulsé deux diplomates.","该国驱逐了两名外交官。"]],"co":[["expulser un locataire","驱逐房客"],["expulser un étranger du pays","把外国人驱逐出境"],["expulser un joueur","罚下球员"],["l'expulsion","驱逐；罚下"]],"sy":[["chasser","courant","赶走，较日常"],["renvoyer","courant","遣返，解雇"],["bannir","soutenu","放逐，禁止入境"]],"fq":"中频，新闻和法律话题。","me":"ex + pulser：把人「推」(pulsion) 到外面去。","tr":{"zh":"房东把房客赶出去了。","fr":"Le propriétaire a expulsé le locataire.","alt":"Le propriétaire a mis le locataire dehors.","note":"expulser qqn de + 地点。"}},
 "Faillir": {"pos":"v. 不规则动词（第三组），几乎只用于 j'ai failli + 动词原形","s":"差点……（但最终没有）。J'ai failli tomber. = 我差点摔倒（实际没摔）。固定结构 faillir + 动词原形，几乎只用复合过去时和简单过去时。书面语里 faillir à ses devoirs = 不尽职责。","ipa":"[fa.jiʁ]","ph":"fa-illir：ai 读 [a]；ill 读 [j]：[fa.jiʁ]；-ir 读 [iʁ]。","pi":"ill 读 [j]，不是 [l]；差点做某事用 faillir + inf.，别说成 j'ai failli ne pas...。意思是「没做成」，不是「做了」。","et":"来自通俗拉丁语 *fallire，源自拉丁语 fallere（欺骗，不够）。同族：faute、défaillir、falloir。英语 fail 同源。","ex":[["J'ai failli être en retard !","我差点迟到！"],["Il a failli tomber dans l'escalier.","他差点在楼梯上摔倒。"],["Nous avons failli rater le train.","我们差点错过火车。"]],"co":[["faillir + inf.","差点……（没发生）"],["j'ai failli tomber","我差点摔倒"],["faillir à son devoir","没尽到责任"],["sans faillir","毫不动摇地"]],"sy":[["manquer de","soutenu","也可表示差点（书面）"],["être sur le point de","courant","正要……，还没发生"],["rater","familier","错过，没做成"]],"fq":"中高频，口语里常用 j'ai failli。","me":"j'ai failli = 差一点「失败」(fail)，但其实没出事。","tr":{"zh":"我昨天差点忘了你的生日。","fr":"J'ai failli oublier ton anniversaire hier.","alt":"Hier, j'ai failli oublier ton anniversaire.","note":"faillir + 动词原形，表示「差点」，事情没有发生。"}},
 "Favoriser": {"pos":"v. 及物动词（第一组）","s":"有利于；促进；偏袒；优待。favoriser le développement = 促进发展；favoriser un enfant = 偏爱某个孩子；Le beau temps favorise les récoltes. 是中性用法。","ipa":"[fa.vɔ.ʁi.ze]","ph":"fa-vo-ri-ser：o 读开口 [ɔ]；s 在元音间读 [z]；-er 读 [e]。","pi":"s 读 [z]；o 是 [ɔ]；favoriser 既可以是「促进」（中性），也可以是「偏袒」（贬义），看上下文。","et":"来自 favori，源自意大利语 favorito，与拉丁语 favor（好感）同族。同族：faveur、favorable、favori。","ex":[["Le beau temps favorise les récoltes.","好天气有利于收成。"],["Ce système favorise les plus riches.","这个制度对最富的人有利。"],["Le professeur favorise toujours le même élève.","老师总是偏袒同一个学生。"]],"co":[["favoriser le développement","促进发展"],["favoriser l'emploi","促进就业"],["être favorisé(e)","有优势的；受优待的"],["favoriser qqn","偏袒某人"]],"sy":[["encourager","courant","鼓励，促进"],["avantager","courant","给予优势"],["faciliter","courant","使容易"]],"fq":"中高频，新闻和工作话题。","me":"favoriser = 给谁「好感」(faveur) 就偏向谁。","tr":{"zh":"运动有利于健康。","fr":"Le sport favorise la bonne santé.","alt":"Faire du sport, c'est bon pour la santé.","note":"favoriser 直接接宾语。"}},
 "Fréquenter": {"pos":"v. 及物动词（第一组）","s":"常去；经常来往；与……交往。fréquenter un café / une bibliothèque = 常去某个地方；fréquenter qqn = 常和某人来往，有时指「在交往，谈恋爱」。","ipa":"[fʁe.kɑ̃.te]","ph":"fré-quen-ter：é [e]；qu 读 [k]；en 读鼻化 [ɑ̃]；-ter 读 [te]。","pi":"qu 读 [k]；不是英语形容词 frequent；fréquenter 是及物动词，不加介词：fréquenter ce café，不是 à ce café。","et":"来自拉丁语 frequentare（频繁去），源自 frequens（频繁的）。同族：fréquent、fréquence、fréquentation。","ex":[["Elle fréquente souvent cette bibliothèque.","她常去这家图书馆。"],["Il fréquente de mauvaises personnes.","他和一些坏人来往。"],["Ils se fréquentent depuis un an.","他们交往一年了。"]],"co":[["fréquenter un lieu","常去某地"],["fréquenter qqn","和某人常来往"],["se fréquenter","彼此交往；谈恋爱"],["un lieu très fréquenté","人很多的地方"]],"sy":[["aller souvent à","courant","常去，最日常"],["côtoyer","soutenu","与……接触、相处"],["sortir avec","familier","和……约会"]],"fq":"中高频，日常常用。","me":"fréquenter ≈ frequent：「频繁」(fréquent) 地去。","tr":{"zh":"我常去这家咖啡馆。","fr":"Je fréquente souvent ce café.","alt":"Je vais souvent dans ce café.","note":"fréquenter 直接接地点，不加 à。"}},
 "Frôler": {"pos":"v. 及物动词（第一组）","s":"轻轻擦过；擦身而过；险些遭遇。frôler la catastrophe / la mort = 差点出大事 / 差点丧命；frôler le mur = 贴着墙擦过。比 toucher 更轻，只是「掠过」。","ipa":"[fʁo.le]","ph":"frô-ler：ô 读闭口 [o]；fr 连读 [fʁ]；-ler 读 [le]。","pi":"ô 读 [o]，不读 [ɔ]；frôler 不是真碰到，而是「几乎碰到」。","et":"来自古法语，来源不确定，可能与拟声有关。同族：frôlement。","ex":[["Nous avons frôlé la catastrophe !","我们差点酿成灾难！"],["La voiture a frôlé le mur.","车子擦着墙过去了。"],["Elle frôle la quarantaine.","她快四十岁了。"]],"co":[["frôler la catastrophe","险些酿成灾难"],["frôler la mort","与死神擦肩"],["frôler qqn","擦过某人身边"],["frôler la perfection","近乎完美"]],"sy":[["effleurer","soutenu","轻触，掠过"],["raser","courant","擦着……掠过"],["friser","soutenu","差不多，接近"]],"fq":"中频，新闻和日常描写。","me":"frôler 读起来轻轻的，就像轻轻「擦」过去。","tr":{"zh":"那辆车差点撞到我。","fr":"La voiture m'a frôlé de très près.","alt":"La voiture est passée à un cheveu de moi.","note":"frôler 用于「擦过」，不一定有碰撞。"}},
 "Garantir": {"pos":"v. 及物动词（第二组，-issons）：nous garantissons","s":"保证；担保；保修。garantir la qualité = 保证质量；garantir que... = 保证……；un produit garanti deux ans = 保修两年的产品。","ipa":"[ɡa.ʁɑ̃.tiʁ]","ph":"ga-ran-tir：g 在 a 前读 [ɡ]；an 读 [ɑ̃]；-tir 读 [tiʁ]。","pi":"第二组：nous garantissons，不是 nous garantons；an 读 [ɑ̃]。","et":"来自 garant（担保人），源自日耳曼语（法兰克语）。同族：garant、garantie。","ex":[["Le vendeur garantit la qualité du produit.","卖家保证产品质量。"],["Cet appareil est garanti deux ans.","这台机器保修两年。"],["Je vous garantis que tout ira bien.","我向您保证一切都会顺利。"]],"co":[["garantir la qualité","保证质量"],["garantir que + 直陈式","保证……"],["être garanti(e) deux ans","保修两年"],["garantir un droit","保障一项权利"]],"sy":[["assurer","courant","保证，使确信"],["certifier","soutenu","证明，保证"],["promettre","courant","承诺"]],"fq":"高频，购物和工作话题常用。","me":"garant + ir：站出来做「担保人」。","tr":{"zh":"商店保证这台电脑质量很好。","fr":"Le magasin garantit la qualité de cet ordinateur.","alt":"Le magasin nous assure que cet ordinateur est de bonne qualité.","note":"第二组动词；garantir que 后接直陈式。"}},
 "Grignoter": {"pos":"v. 及物 / 不及物动词（第一组）","s":"吃零食；小口小口地啃；一点点蚕食。grignoter entre les repas = 两餐之间吃零食；grignoter un biscuit = 啃饼干。比喻义：grignoter du terrain = 一点点占地盘。","ipa":"[ɡʁi.ɲɔ.te]","ph":"gri-gno-ter：gn 读 [ɲ]（像「娘」的鼻音）；o 读开口 [ɔ]；-ter 读 [te]。","pi":"gn 读 [ɲ]，不要分开读成 [ɡ.n]；grignoter 指零食或小口吃，不是正餐。","et":"来自古法语，来源不确定。同族：grignotage、grignotement。","ex":[["J'ai l'habitude de grignoter entre les repas.","我习惯在两餐之间吃零食。"],["Il grignote des biscuits devant la télé.","他边看电视边啃饼干。"],["La souris a grignoté le fromage.","老鼠啃了奶酪。"]],"co":[["grignoter entre les repas","两餐之间吃零食"],["grignoter un biscuit","啃饼干"],["grignoter du terrain","一点点蚕食"],["quelque chose à grignoter","可以吃的小点心"]],"sy":[["manger","courant","吃，泛指"],["picorer","courant","一点一点啄着吃"],["croquer","courant","咬着吃，脆的"]],"fq":"中频，日常口语。","me":"grignoter：一口一口「嘎吱嘎吱」啃。","tr":{"zh":"晚饭前不要吃零食。","fr":"Ne grignote pas avant le dîner.","alt":"Ne mange pas de petits trucs avant le dîner.","note":"否定命令：Ne + 动词 + pas。"}},
 "Grimper": {"pos":"v. 第一组动词；不及物助动词多用 avoir（也可用 être 表状态）","s":"爬；攀；攀升。grimper à un arbre / sur un mur = 爬树 / 爬墙；les prix grimpent = 价格飙升。比 monter 更费力，强调手脚并用。","ipa":"[ɡʁɛ̃.pe]","ph":"grim-per：im 读鼻化 [ɛ̃]；p 要发音；-per 读 [pe]。","pi":"im 读 [ɛ̃]，不是 [im]；grimper 后用 à 或 sur：grimper à l'arbre / sur le toit。","et":"来源不确定，可能与日耳曼语有关。同族：grimpeur、grimpette。","ex":[["Le chat a grimpé à l'arbre.","猫爬上了树。"],["Les prix grimpent depuis un an.","价格这一年一直在涨。"],["Les enfants grimpent sur le mur.","孩子们爬上了墙。"]],"co":[["grimper à un arbre","爬树"],["grimper sur un mur","爬墙"],["grimper en flèche","猛涨"],["grimper une côte","爬坡"]],"sy":[["escalader","courant","攀登（山、墙）"],["monter","courant","上去，较中性"],["gravir","soutenu","攀登"]],"fq":"高频，日常常用。","me":"grimper：手脚并用，一路「爬」上去。","tr":{"zh":"孩子们爬到了树上。","fr":"Les enfants ont grimpé dans l'arbre.","alt":"Les enfants sont montés sur l'arbre.","note":"grimper dans / à / sur l'arbre 都可以。"}},
 "Haïr": {"pos":"v. 不规则动词（第二组）：je hais, nous haïssons","s":"憎恨；恨；很讨厌。Je hais le mensonge. = 我痛恨谎言。语气比 détester 更重，带强烈感情。也可接动词原形：haïr attendre。","ipa":"[a.iʁ]","ph":"ha-ïr：h 是送气 h (h aspiré)，不能连读、不能省音；a-ï 分成两个音节 [a.iʁ]；je hais 读 [ʒə ɛ]；il hait 读 [il ɛ]。","pi":"h 是送气 h，所以 je hais（不是 j'hais）、le haïr（不是 l'haïr）；单数 hais / hait 读 [ɛ]，没有 tréma；复数 haïssons 读 [a.i.sɔ̃]。","et":"来自法兰克语 *hatjan（憎恨）。同英语 hate 同一日耳曼语根。同族：haine（恨）、haineux。","ex":[["Il dit haïr l'injustice.","他说他痛恨不公。"],["Je hais les lundis matin.","我讨厌星期一早上。"],["Ils se haïssent depuis des années.","他们互相憎恨多年了。"]],"co":[["haïr l'injustice","痛恨不公"],["haïr qqn à mort","恨某人入骨"],["se haïr","互相憎恨"],["la haine","恨；仇恨"]],"sy":[["détester","courant","讨厌，最常用"],["exécrer","soutenu","极端厌恶"],["ne pas supporter","courant","无法忍受"]],"fq":"中频，书面和强烈情感。","me":"haïr ≈ hate：日耳曼语里同一个根，表示恨。","tr":{"zh":"我最讨厌说谎。","fr":"Je hais le mensonge.","alt":"Je déteste qu'on me mente.","note":"h 是送气 h，je hais 不省略。"}},
 "Héberger": {"pos":"v. 及物动词（第一组）：nous hébergeons","s":"留宿；收留；安置；托管（网站、数据）。héberger un ami = 让朋友借住；héberger un site web = 托管网站。","ipa":"[e.bɛʁ.ʒe]","ph":"hé-ber-ger：h 不发音（哑音 h，可连读）；é [e]；ber 读 [bɛʁ]；g 在 e 前读 [ʒ]。","pi":"h 不发音，可以说 j'héberge、l'hébergement；nous hébergeons 要保留 e 才能读 [ʒ]。","et":"来自法兰克语 *heriberga（军队的营地），与 auberge（旅店）同源。","ex":[["Je peux t'héberger pour la nuit.","我可以收留你一晚。"],["Cette famille héberge des réfugiés.","这家人收留难民。"],["Ce site est hébergé en France.","这个网站托管在法国。"]],"co":[["héberger un ami","让朋友借住"],["héberger des réfugiés","安置难民"],["l'hébergement","住宿；安置"],["héberger un site web","托管网站"]],"sy":[["loger","courant","供……住宿"],["accueillir","courant","接待，欢迎"],["recueillir","soutenu","收留"]],"fq":"中频，旅游和新闻话题。","me":"héberger ←→ auberge：同一个词根，都是「落脚处」。","tr":{"zh":"你今晚可以住我家。","fr":"Tu peux dormir chez moi ce soir, je t'héberge.","alt":"Je peux te loger chez moi cette nuit.","note":"héberger qqn，直接接人。"}},
 "Ignorer": {"pos":"v. 及物动词（第一组）","s":"不知道；不了解；无视。J'ignore la réponse. = 我不知道答案（比 je ne sais pas 正式）；ignorer qqn = 对某人视而不见。注意：并不总是「忽视」，更常是「不知道」。","ipa":"[i.ɲɔ.ʁe]","ph":"i-gno-rer：gn 读 [ɲ]；o 读开口 [ɔ]；-rer 读 [ʁe]。","pi":"最大陷阱：ignorer 常常是「不知道」，不是英语 ignore 的「无视」；gn 读 [ɲ]。","et":"来自拉丁语 ignorare（不知道）。同族：ignorant、ignorance；与 connaître 的词根 (g)nō- 同属「知道」一类。","ex":[["Il a choisi d'ignorer mes remarques.","他选择无视我的评论。"],["J'ignore où il est parti.","我不知道他去哪了。"],["Elle m'ignore depuis hier.","她从昨天起就不理我。"]],"co":[["ignorer qqn","无视某人"],["ignorer la réponse","不知道答案"],["ne pas ignorer que...","清楚知道……"],["Nul n'est censé ignorer la loi.","任何人都不得以不知法为由。"]],"sy":[["méconnaître","soutenu","不了解，轻视"],["négliger","courant","忽视"],["ne pas savoir","courant","不知道，日常"]],"fq":"高频，日常和书面都常用。","me":"ignorer 和 ignorant 一家：先想到「不知道」，再想到「不理」。","tr":{"zh":"我不知道他住在哪里。","fr":"J'ignore où il habite.","alt":"Je ne sais pas où il habite.","note":"ignorer 比 ne pas savoir 正式。"}},
 "Impacter": {"pos":"v. 及物动词（第一组），较新的用法","s":"对……产生影响；冲击。impacter l'économie = 冲击经济。是 impact 派生出的新动词，在新闻和职场里常用，但一些人觉得带英语味，规范说法是 avoir un impact sur。","ipa":"[ɛ̃.pak.te]","ph":"im-pac-ter：im 读 [ɛ̃]；c 在 t 前读 [k]；-ter 读 [te]。","pi":"im 读 [ɛ̃]；写作时有人不鼓励用，可以改成 avoir un impact sur / affecter。","et":"由名词 impact 派生；impact 来自拉丁语 impactus（撞击）。是现代新词，类似英语 impact（动词）的影响。","ex":[["La crise a fortement impacté l'économie.","危机严重冲击了经济。"],["Ces changements vont impacter notre travail.","这些变化会影响我们的工作。"],["Le bruit impacte la santé.","噪音影响健康。"]],"co":[["impacter l'économie","冲击经济"],["être impacté(e) par qqch","受……影响"],["un impact fort","强烈的影响"],["avoir un impact sur","对……有影响"]],"sy":[["affecter","courant","影响，更规范"],["influencer","courant","对……施加影响"],["toucher","courant","波及，影响到"]],"fq":"中频，新闻和职场里越来越常见。","me":"impact + er：被「撞击」到，就是受影响。","tr":{"zh":"涨价影响到了很多家庭。","fr":"La hausse des prix a impacté beaucoup de familles.","alt":"La hausse des prix a touché beaucoup de familles.","note":"常用被动：être impacté par。"}},
 "Impliquer": {"pos":"v. 及物动词（第一组），代词式 s'impliquer","s":"牵涉；使卷入；意味着；需要。impliquer qqn dans une affaire = 把某人牵扯进一件事；Cela implique que... = 这意味着……；s'impliquer dans = 投入、积极参与。","ipa":"[ɛ̃.pli.ke]","ph":"im-pli-quer：im 读 [ɛ̃]；qu 读 [k]；-er 读 [e]。","pi":"im 读 [ɛ̃]；qu 读 [k]；不是英语 imply 的完全对应，还有「卷入」这层意思。","et":"来自拉丁语 implicare（卷入），由 in- + plicare（折叠）构成。同族：impliqué、implicite、compliquer。","ex":[["Ce projet implique beaucoup de responsabilités.","这个项目意味着很多责任。"],["Il est impliqué dans cette affaire.","他牵涉进了这件事。"],["Elle s'implique beaucoup dans l'association.","她很投入地参与协会工作。"]],"co":[["impliquer qqn dans qqch","把某人牵扯进……"],["Cela implique que...","这意味着……"],["s'impliquer dans un projet","投入一个项目"],["être impliqué(e) dans","牵涉到……"]],"sy":[["entraîner","courant","引起，带来"],["mêler","courant","使卷入"],["supposer","courant","预设；以……为前提"]],"fq":"高频，新闻和工作话题。","me":"im + pli：把东西「折」(pli) 进去，就是牵连在内。","tr":{"zh":"这份工作意味着很多责任。","fr":"Ce travail implique beaucoup de responsabilités.","alt":"Ce poste, c'est beaucoup de responsabilités.","note":"impliquer + 名词 / que 从句。"}},
 "Insulter": {"pos":"v. 及物动词（第一组），代词式 s'insulter","s":"侮辱；辱骂；冒犯。insulter qqn = 骂某人；Il m'a insulté. = 他骂了我。名词 une insulte = 辱骂的话。","ipa":"[ɛ̃.syl.te]","ph":"in-sul-ter：in 读 [ɛ̃]；u 读 [y]；l 和 t 连读；-ter 读 [te]。","pi":"in 读 [ɛ̃]，不是 [in]；u 读 [y]；insulter 指言语冒犯，不是肢体攻击。","et":"来自拉丁语 insultare（跳上去，侮辱）。同族：insulte、insultant。英语 insult 同源。","ex":[["Il est interdit d'insulter l'arbitre.","禁止辱骂裁判。"],["Il m'a insulté devant tout le monde.","他当着大家的面骂我。"],["Ne m'insulte pas !","别骂我！"]],"co":[["insulter qqn","辱骂某人"],["une insulte grave","严重的辱骂"],["se faire insulter","被人辱骂"],["des insultes racistes","种族辱骂"]],"sy":[["injurier","soutenu","辱骂，更正式"],["offenser","soutenu","冒犯"],["traiter de","courant","骂……是……"]],"fq":"中频，日常和新闻里常见。","me":"insulter ≈ insult：两种语言几乎一样。","tr":{"zh":"不要在比赛里辱骂别人。","fr":"Il ne faut pas insulter les autres pendant le match.","alt":"On n'insulte pas les gens pendant un match.","note":"insulter qqn，直接接人。"}},
 "Intervenir": {"pos":"v. 不规则动词（变位同 venir），助动词 être","s":"介入；干预；出面；发言；动手术。La police est intervenue. = 警察出面了；intervenir dans un débat = 在辩论中发言；le médecin doit intervenir = 医生必须出手处理。","ipa":"[ɛ̃.tɛʁ.və.niʁ]","ph":"in-ter-ve-nir：in 读 [ɛ̃]；er 读 [ɛʁ]；ve 弱读 [və]；-ir 读 [iʁ]。","pi":"助动词用 être：elle est intervenue；变位像 venir：j'interviens，nous intervenons。","et":"来自拉丁语 intervenire（走到中间），由 inter- + venire（来）构成。同族：intervention、venir、prévenir。","ex":[["La police est intervenue.","警方出面干预。"],["Le directeur est intervenu dans la discussion.","主任插话参加了讨论。"],["Il faut intervenir rapidement.","必须迅速介入。"]],"co":[["intervenir dans qqch","介入、参与某事"],["intervenir auprès de qqn","向某人说情、出面"],["Les pompiers sont intervenus.","消防员出动了。"],["une intervention chirurgicale","外科手术"]],"sy":[["s'en mêler","familier","插手"],["agir","courant","采取行动"],["s'interposer","soutenu","从中调停"]],"fq":"高频，新闻里很常见。","me":"inter + venir：「来到」(venir) 两者「之间」(inter)。","tr":{"zh":"消防员很快就赶到了。","fr":"Les pompiers sont intervenus très vite.","alt":"Les pompiers sont arrivés vite sur place.","note":"intervenir 用 être：ils sont intervenus。"}},
 "Modéliser": {"pos":"v. 及物动词（第一组）","s":"建模；用模型表示。modéliser un phénomène / le climat = 对某种现象 / 气候建立模型。科学、工程和数据话题里用，日常基本不用。","ipa":"[mɔ.de.li.ze]","ph":"mo-dé-li-ser：o 读开口 [ɔ]；é [e]；s 在元音间读 [z]；-er 读 [e]。","pi":"s 读 [z]；o 是 [ɔ]；不要和 moderniser（使现代化）混淆。","et":"由 modèle + -iser 构成；modèle 来自意大利语 modello，源自拉丁语 modulus（尺度）。同族：modèle、modélisation。","ex":[["Les scientifiques ont modélisé le changement climatique.","科学家们对气候变化进行了建模。"],["Cette équipe modélise le trafic routier.","这个团队为道路交通建模。"],["On peut modéliser ce problème avec un ordinateur.","可以用电脑为这个问题建模。"]],"co":[["modéliser un phénomène","给现象建模"],["la modélisation","建模"],["un modèle mathématique","数学模型"],["modéliser en 3D","做 3D 建模"]],"sy":[["simuler","courant","模拟"],["représenter","courant","表示"],["schématiser","soutenu","用示意图表示"]],"fq":"低频，科技和学术。","me":"modèle + iser：把东西「做成模型」。","tr":{"zh":"他们用电脑为交通建立模型。","fr":"Ils modélisent la circulation avec un ordinateur.","alt":"Ils font un modèle de la circulation sur ordinateur.","note":"modéliser 是及物动词，不要与 moderniser 混淆。"}},
 "Modérer": {"pos":"v. 及物动词（第一组，变位同 céder）：je modère, nous modérons","s":"减轻；节制；放慢；调解（讨论区）。modérer sa vitesse = 减速；modérer ses dépenses = 控制开支；modérer un forum = 管理论坛。","ipa":"[mɔ.de.ʁe]","ph":"mo-dé-rer：o 读开口 [ɔ]；é [e]；-rer 读 [ʁe]。","pi":"变位里 é 变 è：je modère；别写成 modere。","et":"来自拉丁语 moderari（调节），源自 modus（尺度）。同族：modéré、modération、modeste、mode。","ex":[["Vous devez modérer votre vitesse.","您必须减速。"],["Il faut modérer ses dépenses ce mois-ci.","这个月要控制开支。"],["Elle modère le forum de discussion.","她负责管理讨论区。"]],"co":[["modérer sa vitesse","减速"],["modérer ses dépenses","控制开支"],["modérer ses propos","收敛措辞"],["se modérer","克制自己"]],"sy":[["réduire","courant","减少"],["tempérer","soutenu","缓和"],["limiter","courant","限制"]],"fq":"中频，书面和提醒语里。","me":"modérer ← modus（尺度）：保持在「适度」的范围内。","tr":{"zh":"您必须控制开支。","fr":"Vous devez modérer vos dépenses.","alt":"Vous devriez faire attention à vos dépenses.","note":"modérer + 名词；变位 je modère。"}},
 "Pêcher": {"pos":"v. 及物 / 不及物动词（第一组）","s":"钓鱼；捕鱼；捞到。pêcher à la ligne = 用钓竿钓鱼；pêcher des crevettes = 捞虾。口语 pêcher qqch = 弄到、找到。","ipa":"[pɛ.ʃe]","ph":"pê-cher：ê 读 [ɛ]；ch 读 [ʃ]；-er 读 [e]。","pi":"形近词：pêcher（钓鱼）、pécher（犯戒）、pêche（桃子；钓鱼）、péché（罪），注意 ê / é 的区别。","et":"来自拉丁语 piscari（捕鱼），源自 piscis（鱼）。同族：pêcheur、piscine、poisson。","ex":[["Il aime pêcher le dimanche matin.","他喜欢星期天早上钓鱼。"],["Nous avons pêché cinq poissons.","我们钓到了五条鱼。"],["Mon père pêche à la ligne au bord du lac.","我父亲在湖边钓鱼。"]],"co":[["aller à la pêche","去钓鱼"],["pêcher à la ligne","用钓竿钓鱼"],["pêcher en mer","海钓"],["la pêche","钓鱼；桃子"]],"sy":[["attraper","courant","抓到"],["capturer","soutenu","捕获"],["chasser","courant","打猎，陆地上的对应词"]],"fq":"高频，日常和爱好话题。","me":"pêcher ← piscis（鱼）：和 piscine（游泳池）同根。","tr":{"zh":"周末我们去河边钓鱼。","fr":"Ce week-end, nous allons pêcher au bord de la rivière.","alt":"Ce week-end, on va à la pêche près de la rivière.","note":"pêcher 是 pêche（钓鱼）的动词；别与 pécher 混淆。"}},
 "Pourrir": {"pos":"v. 第二组动词（-issons）：nous pourrissons","s":"腐烂；变质；变坏。Les fruits pourrissent. = 水果烂了；laisser pourrir une situation = 任局势恶化。及物时：pourrir un enfant = 把孩子惯坏（口语）。","ipa":"[pu.ʁiʁ]","ph":"pour-rir：ou 读 [u]；rr 读一个 [ʁ]；-ir 读 [iʁ]。","pi":"rr 是一个 [ʁ]；第二组：nous pourrissons；过去分词 pourri 作形容词意思是「烂的」，口语也可以说「糟糕的」。","et":"来自通俗拉丁语 *putrire，源自拉丁语 putrere（腐烂）。同族：pourri、pourriture、putride。","ex":[["Les fruits ont commencé à pourrir.","水果开始腐烂。"],["N'oublie pas ces pommes, elles vont pourrir.","别忘了这些苹果，它们会烂掉的。"],["Le bois pourrit sous la pluie.","木头在雨里会腐烂。"]],"co":[["pourrir sur pied","（果实）烂在树上；（局势）一直恶化"],["laisser pourrir la situation","任局势恶化"],["un fruit pourri","烂了的水果"],["la pourriture","腐烂；腐败"]],"sy":[["moisir","courant","发霉"],["se décomposer","soutenu","腐败分解"],["se gâter","courant","变质，变坏"]],"fq":"中频，日常话题。","me":"pourrir ≈ putride：同一个拉丁根，一样「臭」。","tr":{"zh":"水果放太久，已经烂了。","fr":"Les fruits sont restés trop longtemps et ils ont pourri.","alt":"Les fruits ont traîné trop longtemps, ils sont pourris.","note":"第二组：pourrir / ils pourrissent；pourri(e) 作形容词。"}},
 "Pousser": {"pos":"v.t./v.i. 动词（第一组 -er，助动词 avoir）","s":"推；推动；（植物）生长。pousser la porte = 推门；pousser un cri = 发出一声叫喊；Les fleurs poussent. = 花在长。pousser qqn à + inf. = 促使某人做某事。","ipa":"[pu.se]","ph":"ou [u]；ss 读 [s]；结尾 -er 读 [e]，r 不发音。","pi":"ou 是 [u]，不要读成 [aʊ]；-er 结尾的 r 不发音。pousser 的「推」和 tirer（拉）相反，门上写 Poussez / Tirez。","et":"来自拉丁语 pulsare（反复推、敲），与 pellere（推）同源。同族词：poussée（推力）、poussette（婴儿推车）。","ex":[["Il faut pousser la porte pour entrer.","进去要推门。"],["Les tomates poussent bien en été.","夏天番茄长得很好。"],["Ses amis l'ont poussé à parler.","朋友们推着他开口说话。"]],"co":[["pousser la porte","推门"],["pousser un cri","大叫一声"],["pousser qqn à + inf.","促使某人做某事"],["pousser un soupir","叹一口气"]],"sy":[["pousser","courant","推；反义词 tirer（拉）"],["inciter","soutenu","促使、怂恿，比 pousser à 更正式"],["bousculer","courant","推搡、撞"]],"fq":"极高频，日常常用。","me":"Poussez / Tirez：门上的两个字，推 = pousser。","tr":{"zh":"请推门，不要拉。","fr":"Poussez la porte, ne la tirez pas.","alt":"Pousse la porte, ne tire pas.","note":"命令式 poussez（您/你们）、pousse（你）。"}},
 "Préserver": {"pos":"v.t. 及物动词（第一组 -er，助动词 avoir）","s":"保护；使免受（伤害）；保存。préserver qqch de qqch = 使某物免受某事物之害；préserver l'environnement = 保护环境。比 protéger 更强调「保持原样、不被破坏」。","ipa":"[pʁe.zɛʁ.ve]","ph":"pré [pʁe]；s 在元音间读 [z]；-er 读 [e]。","pi":"ser 里的 s 读 [z]，不读 [s]；注意 r 是小舌音 [ʁ]。préserver 和 conserver（保存）、réserver（预订）形近，别混。","et":"来自晚期拉丁语 praeservare（prae- 预先 + servare 守护）。同族词：préservatif（避孕套）、préservation、conserver、réserver。","ex":[["Il est important de préserver la nature.","保护自然很重要。"],["Cette crème préserve la peau du soleil.","这款面霜保护皮肤免受阳光伤害。"]],"co":[["préserver l'environnement","保护环境"],["préserver qqn / qqch de qqch","使某人/某物免受某事物之害"],["préserver sa santé","保护健康"]],"sy":[["protéger","courant","保护，最常用的词"],["sauvegarder","soutenu","维护、保全（权利、遗产）"],["conserver","courant","保存、保留"]],"fq":"中高频，常见于新闻与环保话题。","me":"pré- 预先 + servir/servare 守护：提前守住，不让它坏。","tr":{"zh":"我们必须保护这片森林。","fr":"Nous devons préserver cette forêt.","alt":"Il faut qu'on protège cette forêt.","note":"devoir + 动词原形；préserver 直接带宾语。"}},
 "Prétexter": {"pos":"v.t. 及物动词（第一组 -er，助动词 avoir）","s":"以……为借口。prétexter qqch = 拿某事当借口；prétexter que + 句子 = 借口说……。名词是 un prétexte（借口）。通常暗示理由不是真的。","ipa":"[pʁe.tɛk.ste]","ph":"pré [pʁe]；x 在这里拼作 xt，读 [kst]；结尾 -er 读 [e]。","pi":"tex 要读 [tɛks]，不要漏掉 k 和 s；名词 prétexte 带 e，动词多了 -r。","et":"来自 prétexte（借口），源自拉丁语 praetextus（prae- 在前 + texere 编织：披在前面的「幌子」）。","ex":[["Il a prétexté une maladie pour ne pas venir.","他以生病为借口没来。"],["Elle prétexte qu'elle est fatiguée.","她借口说自己累了。"]],"co":[["prétexter une maladie","以生病为借口"],["prétexter que + indicatif","借口说……"],["sous prétexte de / que","以……为借口"]],"sy":[["invoquer","soutenu","援引（理由），不一定是假的"],["alléguer","soutenu","提出（理由、论据），较书面"],["feindre","soutenu","假装"]],"fq":"中低频，书面和口语均可。","me":"prétexte 的动词：给自己「披」一个理由。","tr":{"zh":"他借口太忙，没有来。","fr":"Il a prétexté qu'il était trop occupé pour venir.","alt":"Il a dit qu'il était trop occupé, mais c'était juste un prétexte.","note":"prétexter que 后接直陈式。"}},
 "Prioriser": {"pos":"v.t. 及物动词（第一组 -er，助动词 avoir）","s":"给……排优先顺序；把……放在首位。多用于工作、管理场合：prioriser les tâches = 给任务排优先级。比较新，部分人觉得是职场用语。","ipa":"[pʁi.jɔ.ʁi.ze]","ph":"pri [pʁi]；io 读 [jɔ]；ri [ʁi]；结尾 -er 读 [e]。","pi":"四个音节 pri-o-ri-ser，别读成三个；s 读 [z]。","et":"来自 priorité / prioritaire（拉丁语 prior「更早的、更重要的」）+ 动词后缀 -iser。同族词：priorité、prioritaire。","ex":[["Nous devons prioriser nos tâches.","我们必须给任务排优先级。"],["Priorise ce dossier, il est urgent.","先处理这个文件，它很急。"]],"co":[["prioriser les tâches","给任务排优先级"],["prioriser les besoins","优先满足需求"],["savoir prioriser","懂得分清轻重"]],"sy":[["hiérarchiser","soutenu","按等级排序"],["donner la priorité à","courant","把优先权给……"],["privilégier","courant","优先考虑、偏重"]],"fq":"中频，职场常用。","me":"priorité + -iser：把某事「变成」优先。","tr":{"zh":"先把最紧急的事做完。","fr":"Priorise les choses les plus urgentes.","alt":"Commence par ce qui est urgent.","note":"口语里常用 donner la priorité à 代替。"}},
 "Privilégier": {"pos":"v.t. 及物动词（第一组 -er，助动词 avoir）","s":"优先考虑；偏重；给予特权。privilégier qqch = 把某事物放在首位。注意 -ier 动词：nous privilégions，vous privilégiez。","ipa":"[pʁi.vi.le.ʒje]","ph":"pri [pʁi]；vi [vi]；lé [le]；gi 读 [ʒj]；结尾 -er 读 [e]。","pi":"g 在 gi 前读 [ʒ]（像 je），不是 [g]；é 两点要标对；不要和 privilège 的 è 混。","et":"来自 privilège，拉丁语 privilegium（privus「个人的」+ lex「法律」：只对某人适用的法律）。同族词：privilège、privilégié。","ex":[["Il faut privilégier les transports en commun.","应当优先发展公共交通。"],["Je privilégie la qualité à la quantité.","我重质量而不是数量。"]],"co":[["privilégier A par rapport à B","把 A 看得比 B 重要"],["privilégier la qualité","重视质量"],["les personnes privilégiées","有特权的人"]],"sy":[["favoriser","courant","偏向、有利于"],["préférer","courant","更喜欢"],["prioriser","courant","给优先级"]],"fq":"中高频，新闻与写作常用。","me":"privilège + -ier：赋予「特权」，所以排在最前。","tr":{"zh":"我更看重质量，而不是价格。","fr":"Je privilégie la qualité plutôt que le prix.","alt":"Pour moi, la qualité passe avant le prix.","note":"privilégier A plutôt que / par rapport à B。"}},
 "Réagir": {"pos":"v.i. 不及物动词（第二组 -ir，助动词 avoir）","s":"反应；回应；起反作用。réagir à qqch = 对某事做出反应；réagir contre = 反抗；药物或化学物质也可以 réagir。名词 une réaction。","ipa":"[ʁe.a.ʒiʁ]","ph":"ré [ʁe] 与 a [a] 分开读，中间不连音；g 在 i 前读 [ʒ]；结尾 r 读 [ʁ]。","pi":"ré-a-gir 是三个音节，é 与 a 都要清楚读出；第二组变位：il réagit，nous réagissons。","et":"ré-（再、反）+ agir（行动，拉丁语 agere）。同族词：réaction、réactif、agir。","ex":[["Comment a-t-il réagi à la nouvelle ?","他对这个消息有什么反应？"],["Il faut réagir vite en cas d'urgence.","紧急情况下必须迅速反应。"]],"co":[["réagir à qqch","对某事做出反应"],["réagir violemment","反应激烈"],["réagir contre","反抗"],["bien / mal réagir","反应良好 / 不好"]],"sy":[["répondre","courant","回答、回应"],["riposter","soutenu","反击、还击"],["se rebeller","courant","反抗"]],"fq":"高频，日常常用。","me":"ré- 反 + agir 行动：对一件事「反过来做点什么」。","tr":{"zh":"听到这个消息，她马上做出了反应。","fr":"En apprenant la nouvelle, elle a tout de suite réagi.","alt":"Elle a réagi tout de suite à la nouvelle.","note":"réagir à + 名词；复合过去时用 avoir。"}},
 "Réglementer": {"pos":"v.t. 及物动词（第一组 -er，助动词 avoir）","s":"制定规章管理；规范；管制。réglementer un secteur = 对一个行业立规矩。名词 une réglementation（规定、法规）。","ipa":"[ʁeɡ.lə.mɑ̃.te]","ph":"ré [ʁe]；gle 读 [ɡlə]；men 读鼻化元音 [mɑ̃]；结尾 -er 读 [e]。","pi":"men 是鼻化音 [mɑ̃]，不发 n；第一个音节写 ré（不是 rè），拼写别和 règle 搞混。","et":"来自 règlement（规章），再加动词后缀；règle 来自拉丁语 regula（尺、规则）。同族词：règle、règlement、réglementation、régulier。","ex":[["Le gouvernement veut réglementer ce secteur.","政府想规范这个行业。"],["La vente d'alcool est strictement réglementée.","酒的销售受到严格管制。"]],"co":[["réglementer la circulation","管制交通"],["strictement réglementé","受严格管制"],["la réglementation en vigueur","现行法规"]],"sy":[["encadrer","courant","加以规范、设框架"],["réguler","soutenu","调节、调控"],["interdire","courant","禁止，比 réglementer 强"]],"fq":"中频，新闻与法律语境。","me":"règle → règlement → réglementer：给事情立规则。","tr":{"zh":"这个行业应该受到更好的管制。","fr":"Ce secteur devrait être mieux réglementé.","alt":"Il faudrait mieux encadrer ce secteur.","note":"被动形式 être réglementé；devrait 为条件式，表建议。"}},
 "Regretter": {"pos":"v.t. 及物动词（第一组 -er，助动词 avoir）","s":"后悔；遗憾；怀念。regretter de + 动词原形 = 后悔做了某事；regretter que + 虚拟式 = 遗憾……；Je regrette. = 对不起、很遗憾（比 désolé 更正式一点）。","ipa":"[ʁə.ɡʁɛ.te]","ph":"re 轻读 [ʁə]；gr [ɡʁ]；e 在 tt 前读 [ɛ]；tt 读单个 [t]。","pi":"双写 tt 只读一个 [t]；第一音节 re 是轻音 [ʁə]，不要读成 [ʁe]。","et":"来源不确定，可能与古北欧语 grāta「哭」有关。同族词：regret（后悔，名词）、regrettable（令人遗憾的）。","ex":[["Je regrette de ne pas être venu.","我后悔没来。"],["Nous regrettons que vous ne puissiez pas venir.","我们很遗憾您不能来。"],["Elle regrette sa ville natale.","她怀念自己的家乡。"]],"co":[["regretter de + inf.","后悔做某事"],["regretter que + subjonctif","遗憾……"],["je ne regrette rien","我一点也不后悔"],["regretter le passé","怀念过去"]],"sy":[["être désolé","courant","抱歉、遗憾，较口语"],["déplorer","soutenu","痛惜、哀叹"],["se repentir","littéraire","悔改、忏悔"]],"fq":"高频，日常常用。","me":"re- + 古语「哭泣」：事后想起来，忍不住哭一下。","tr":{"zh":"我不后悔我的决定。","fr":"Je ne regrette pas ma décision.","alt":"Je ne regrette rien de ma décision.","note":"regretter qqch 或 regretter de + 动词原形。"}},
 "Respirer": {"pos":"v.i./v.t. 动词（第一组 -er，助动词 avoir）","s":"呼吸；吸入。respirer profondément = 深呼吸；respirer l'air pur = 呼吸新鲜空气。也可表示「松口气」：Ouf, je respire ! 名词 la respiration。","ipa":"[ʁɛs.pi.ʁe]","ph":"res [ʁɛs]；pi [pi]；ra 在这里读 [ʁe]（-er 结尾）；两个 r 都是 [ʁ]。","pi":"一个词里有两个小舌音 [ʁ]；第一音节 res 读 [ʁɛs]，不是 [ʁə]。","et":"来自拉丁语 respirare（re- + spirare「呼吸」）。同族词：respiration、inspirer（吸气；启发）、expirer（呼气）、esprit。","ex":[["J'ai besoin de respirer l'air pur de la montagne.","我需要呼吸山里的新鲜空气。"],["Respirez profondément, ça va aller.","深呼吸，会好的。"]],"co":[["respirer profondément","深呼吸"],["respirer l'air frais","呼吸新鲜空气"],["avoir du mal à respirer","呼吸困难"]],"sy":[["inspirer","courant","吸气（反义词 expirer 呼气）"],["souffler","courant","吹气、喘口气"],["haleter","soutenu","喘气"]],"fq":"高频，日常常用。","me":"re- + spirer：不断地「再」吸气，也是 esprit（灵魂）的近亲。","tr":{"zh":"打开窗户，我想呼吸一下。","fr":"Ouvre la fenêtre, j'ai besoin de respirer.","alt":"Ouvre la fenêtre, j'étouffe.","note":"avoir besoin de + 动词原形。"}},
 "Restaurer": {"pos":"v.t. 及物动词（第一组 -er，助动词 avoir）","s":"修复；修复（建筑、画作）；恢复（秩序、信任）。restaurer un tableau = 修复一幅画；restaurer la confiance = 恢复信任。se restaurer 是书面用法「吃点东西恢复体力」。","ipa":"[ʁɛs.to.ʁe]","ph":"res [ʁɛs]；tau 读 [to]；ra 在 -er 前读 [ʁe]。","pi":"au 读 [o]，不是 [aʊ]；名词 restaurant 来自同一个词，别混淆。","et":"来自拉丁语 restaurare（修复、重建）。同族词：restauration、restaurant（让人恢复体力的地方）、restaurateur。","ex":[["Ils vont restaurer ce vieux tableau.","他们要修复这幅旧画。"],["Le gouvernement veut restaurer la confiance.","政府想恢复信任。"]],"co":[["restaurer un bâtiment","修复建筑"],["restaurer l'ordre","恢复秩序"],["restaurer la confiance","恢复信任"]],"sy":[["réparer","courant","修理（日常物品）"],["rénover","courant","翻新"],["rétablir","soutenu","重建、恢复"]],"fq":"中频，多见于艺术、建筑与新闻。","me":"restaurant = 让人恢复体力的地方，所以 restaurer = 恢复。","tr":{"zh":"他们在修复这座旧教堂。","fr":"Ils restaurent cette vieille église.","alt":"Ils sont en train de restaurer cette vieille église.","note":"être en train de + 动词原形：正在做。"}},
 "Revendre": {"pos":"v.t. 及物动词（第三组，同 vendre；过去分词 revendu，助动词 avoir）","s":"转卖；再卖；倒卖。revendre qqch à qqn = 把某物转卖给某人；revendre d'occasion = 卖二手。名词 la revente。","ipa":"[ʁə.vɑ̃dʁ]","ph":"re 轻读 [ʁə]；ven 读鼻化元音 [vɑ̃]；dre 结尾读 [dʁ]。","pi":"ven 里的 n 不发音，是鼻化元音；变位同 vendre：je revends，nous revendons。","et":"re-（再）+ vendre（拉丁语 vendere）。同族词：revente、vendeur、vente。","ex":[["Il veut revendre sa voiture d'occasion.","他想转卖他的二手车。"],["J'ai revendu mon vieux vélo en ligne.","我在网上把旧自行车卖掉了。"]],"co":[["revendre qqch à qqn","把某物转卖给某人"],["revendre d'occasion","卖二手"],["revendre avec profit","转卖获利"]],"sy":[["vendre","courant","卖"],["brader","courant","甩卖"],["céder","soutenu","转让"]],"fq":"中频，日常常用。","me":"re- 再 + vendre 卖：买来再卖。","tr":{"zh":"她把旧手机转卖了。","fr":"Elle a revendu son vieux téléphone.","alt":"Elle a vendu son vieux téléphone d'occasion.","note":"复合过去时：avoir + revendu。"}},
 "Revoir": {"pos":"v.t. 及物动词（第三组，同 voir；过去分词 revu，助动词 avoir）","s":"再见到；重看；复习；重新检查。Au revoir ! = 再见。revoir un film = 重看一部电影；revoir ses notes = 复习笔记；revoir un plan = 修改计划。","ipa":"[ʁə.vwaʁ]","ph":"re 轻读 [ʁə]；oi 读 [wa]；结尾 r 读 [ʁ]。","pi":"oi 读 [wa]，不是 [oi]；au revoir 中 revoir 是同一个词。注意：je reverrai（将来时）有两个 r。","et":"re-（再）+ voir（拉丁语 videre）。同族词：au revoir、revue（杂志；检阅）、revisiter。","ex":[["Je suis content de te revoir.","再见到你我很高兴。"],["Il faut revoir le plan du projet.","必须重新审视项目计划。"],["Je vais revoir mes notes avant l'examen.","考试前我要复习笔记。"]],"co":[["au revoir","再见"],["revoir ses notes","复习笔记"],["revoir sa copie","修改答卷、重新考虑"],["à revoir","需要重新检查"]],"sy":[["réviser","courant","复习；修订"],["réexaminer","soutenu","重新审查"],["retrouver","courant","重新见到、找回"]],"fq":"极高频，日常常用。","me":"re- 再 + voir 看：「再看一遍」= 再见 = 复习。","tr":{"zh":"我想再看一遍这部电影。","fr":"J'aimerais revoir ce film.","alt":"Je voudrais le revoir, ce film.","note":"aimer 的条件式 j'aimerais 表示礼貌的愿望。"}},
 "S'arrêter": {"pos":"v. 代词式动词（第一组 -er，助动词 être）","s":"停下；停止；停留。s'arrêter de + 动词原形 = 停止做某事；s'arrêter à / chez = 在某处停留。复合时态用 être：Il s'est arrêté。及物动词 arrêter 则是「使停下；逮捕」。","ipa":"[sa.ʁɛ.te]","ph":"s' 与 a 连读 [sa]；rr 读一个 [ʁ]；ê 读 [ɛ]；-er 读 [e]。","pi":"rr 只读一个 [ʁ]；ê 要读 [ɛ]；复合过去时过去分词要与主语一致：Elle s'est arrêtée。","et":"来自晚期拉丁语 *arrestare（ad- + restare「停留」）。同族词：arrêt（停靠站）、arrêter、rester。","ex":[["Le bus vient de s'arrêter.","公共汽车刚停下。"],["Elle s'est arrêtée devant la vitrine.","她在橱窗前停了下来。"],["Il ne s'arrête jamais de parler.","他说个不停。"]],"co":[["s'arrêter de + inf.","停止做某事"],["s'arrêter net","突然停住"],["s'arrêter chez qqn","顺路去某人家"],["ne pas s'arrêter là","不止于此"]],"sy":[["cesser","soutenu","停止，较书面"],["stopper","familier","停下、刹住"],["faire une pause","courant","休息一下"]],"fq":"极高频，日常常用。","me":"arrêt（车站牌）：s'arrêter = 停在站牌前。","tr":{"zh":"火车在这一站不停。","fr":"Le train ne s'arrête pas dans cette gare.","alt":"Le train ne s'arrête pas ici.","note":"代词式动词：s' 随主语变化（je m'arrête, il s'arrête）。"}},
 "S'effondrer": {"pos":"v. 代词式动词（第一组 -er，助动词 être）","s":"倒塌；崩溃；（价格、人）一蹶不振。物体：Le toit s'est effondré。人：Elle s'est effondrée en larmes。经济：Les prix s'effondrent。","ipa":"[se.fɔ̃.dʁe]","ph":"s'e 读 [se]；f [f]；on 读鼻化元音 [ɔ̃]；dr [dʁ]；-er 读 [e]。","pi":"on 是鼻化元音 [ɔ̃]，n 不发；effondrer 的 ff 只读一个 [f]。","et":"来自古法语 esfondrer（es- 向外 + fond「底」，拉丁语 fundus）：「垮到底」。同族词：fond、fondation、s'enfoncer、effondrement。","ex":[["Le vieux mur s'est effondré pendant la nuit.","旧墙在夜里倒塌了。"],["Elle s'est effondrée en apprenant la nouvelle.","听到这个消息，她崩溃了。"]],"co":[["s'effondrer en larmes","崩溃大哭"],["le toit s'effondre","屋顶塌了"],["les prix s'effondrent","价格暴跌"]],"sy":[["s'écrouler","courant","倒塌，最常见近义词"],["craquer","familier","崩溃（心理）"],["s'affaisser","soutenu","塌陷、瘫软"]],"fq":"中频，新闻与日常都有。","me":"ef-fond-rer：fond 是「底」，一路垮到底。","tr":{"zh":"桥在暴雨中坍塌了。","fr":"Le pont s'est effondré pendant l'orage.","alt":"Le pont s'est écroulé sous la tempête.","note":"s'effondrer 复合时态用 être。"}},
 "S'émanciper": {"pos":"v. 代词式动词（第一组 -er，助动词 être）","s":"摆脱束缚；获得自主；解放自己。s'émanciper de qqch / qqn = 从某事物/某人的控制下解放出来。常用于家庭、社会、女性主义语境。","ipa":"[se.mɑ̃.si.pe]","ph":"é [e]；man 读 [mɑ̃]；ci 读 [si]；-per 读 [pe]。","pi":"an 是鼻化元音 [ɑ̃]；c 在 i 前读 [s]；émanciper 里的 p 要发音。","et":"来自拉丁语 emancipare（e- 出 + manus 手 + capere 拿：把孩子从家长的「手」中放出）。同族词：émancipation。","ex":[["Il cherche à s'émanciper de sa famille.","他想摆脱家庭。"],["Les femmes se sont émancipées au XXe siècle.","妇女在二十世纪获得了解放。"]],"co":[["s'émanciper de qqn / qqch","摆脱某人/某事物"],["s'émanciper financièrement","经济上独立"],["l'émancipation des femmes","妇女解放"]],"sy":[["se libérer","courant","获得自由"],["s'affranchir","soutenu","摆脱、挣脱"],["devenir indépendant","courant","变得独立"]],"fq":"中低频，书面与社会话题。","me":"e-manus：从「手」里放出去，不再被牵着。","tr":{"zh":"她想经济上独立。","fr":"Elle veut s'émanciper financièrement.","alt":"Elle veut devenir indépendante financièrement.","note":"s'émanciper de + 人或事物。"}},
 "S'expatrier": {"pos":"v. 代词式动词（第一组 -er，助动词 être）","s":"移居国外；侨居。s'expatrier au Canada / en Chine。常指为工作或生活长期去国外。名词 un expatrié（外派人员、侨民）。","ipa":"[sɛk.spa.tʁi.je]","ph":"s'ex 读 [sɛks]（这里 s'e 与 x 连成 [sɛk]）；pa [pa]；tri [tʁi]；é-r 读 [je]。","pi":"-trier 读 [tʁi.je]；ex- 的 x 读 [ks]，前面 s' 连读成 [sɛk.s]。","et":"ex-（出）+ patrie（祖国，拉丁语 patria）。同族词：patrie、patriote、rapatrier、expatrié。","ex":[["Ils ont décidé de s'expatrier au Canada.","他们决定移居加拿大。"],["Beaucoup de jeunes s'expatrient pour trouver du travail.","很多年轻人去国外找工作。"]],"co":[["s'expatrier au / en + pays","移居某国"],["un expatrié","外派人员、侨民"],["s'expatrier pour le travail","为工作移居国外"]],"sy":[["émigrer","courant","移民（离开本国）"],["partir à l'étranger","courant","去国外"],["s'exiler","soutenu","流亡"]],"fq":"中低频，社会话题。","me":"ex- 出 + patrie 祖国：走出祖国。","tr":{"zh":"我想以后移居日本。","fr":"Je voudrais m'expatrier au Japon plus tard.","alt":"Plus tard, j'aimerais partir vivre au Japon.","note":"国名前的介词：au Japon、en France、aux États-Unis。"}},
 "S'inscrire": {"pos":"v. 代词式动词（第三组，同 écrire；过去分词 inscrit，助动词 être）","s":"报名；注册；登记。s'inscrire à un cours / à l'université。也可表示「属于……范围，符合……」：Ce projet s'inscrit dans une démarche écologique。","ipa":"[sɛ̃.skʁiʁ]","ph":"s'in 读 [sɛ̃]；scr 读 [skʁ]；结尾 r 读 [ʁ]。","pi":"in 是鼻化元音 [ɛ̃]；变位同 écrire：je m'inscris，nous nous inscrivons。","et":"来自拉丁语 inscribere（in- 在……上 + scribere 写）。同族词：inscription（报名）、écrire、décrire。","ex":[["Je m'inscris à un cours de danse.","我报名参加舞蹈课。"],["Ce projet s'inscrit dans les rénovations du quartier.","这个项目属于街区翻新计划的一部分。"]],"co":[["s'inscrire à un cours","报名上课"],["s'inscrire en ligne","网上注册"],["s'inscrire dans + 名词","属于……之列"],["s'inscrire sur une liste","登记在名单上"]],"sy":[["s'enregistrer","courant","登记、注册"],["adhérer","soutenu","加入（组织）"],["faire partie de","courant","属于"]],"fq":"高频，日常常用。","me":"in + scribe（写）：把名字「写进去」。","tr":{"zh":"我已经在网上报名了。","fr":"Je me suis déjà inscrit en ligne.","alt":"Je me suis inscrit sur Internet.","note":"s'inscrire 复合时态用 être，过去分词与主语一致。"}},
 "Saccager": {"pos":"v.t. 及物动词（第一组 -er，助动词 avoir；nous saccageons）","s":"洗劫；糟蹋；破坏。saccager un magasin / un jardin = 把店铺/花园弄得一片狼藉。可指人为暴力破坏，也可指风暴把东西毁坏。名词 le saccage。","ipa":"[sa.ka.ʒe]","ph":"sa [sa]；cc 里 c 读 [k]（saccager 只有 cc 读 [k]）；g 在 e 前读 [ʒ]；-er 读 [e]。","pi":"cc 只读一个 [k]；变位时 g 后加 e：nous saccageons，才保持 [ʒ]。","et":"来自 sac（意为「洗劫」，源自意大利语 sacco，如 mettre à sac）+ 后缀。同族词：sac（洗劫义）、saccage。","ex":[["Les cambrioleurs ont saccagé l'appartement.","窃贼把公寓洗劫一空。"],["La tempête a saccagé le jardin.","风暴把花园毁了。"]],"co":[["saccager un appartement","把公寓弄得一团糟"],["saccager des cultures","毁坏庄稼"],["mettre à sac","洗劫"]],"sy":[["dévaster","soutenu","破坏、荒废"],["ravager","soutenu","蹂躏、肆虐"],["piller","courant","抢劫、掠夺"]],"fq":"中低频，新闻常见。","me":"sac-cager：「把一切都掏空」，像强盗翻箱倒柜。","tr":{"zh":"暴风雨毁了我们的花园。","fr":"La tempête a saccagé notre jardin.","alt":"L'orage a détruit tout notre jardin.","note":"saccager 比 détruire 更强调乱砸乱毁。"}},
 "Se blesser": {"pos":"v. 代词式动词（第一组 -er，助动词 être）","s":"受伤；弄伤自己。se blesser au genou / à la main = 伤到膝盖/手。及物 blesser qqn = 伤到某人；也可指伤人感情：Ses mots m'ont blessé。","ipa":"[sə.blɛ.se]","ph":"se [sə]；bl [bl]；e 在 ss 前读 [ɛ]；ss 读 [s]；-er 读 [e]。","pi":"身体部位前用定冠词 le/la/les，不是所有格：Il s'est blessé au genou，不说 son genou。","et":"来源不确定，可能来自法兰克语；同族词：blessure（伤口）、blessé（受伤的）。","ex":[["Il s'est blessé au genou en tombant.","他摔倒时伤了膝盖。"],["Elle s'est blessée avec un couteau.","她被刀划伤了。"]],"co":[["se blesser au genou","伤到膝盖"],["se blesser légèrement / gravement","轻伤 / 重伤"],["blesser qqn dans son amour-propre","伤了某人自尊"]],"sy":[["se faire mal","courant","弄疼自己，最口语"],["s'écorcher","courant","擦伤、划破皮"],["se casser","familier","弄断（骨头）"]],"fq":"高频，日常常用。","me":"blessure（伤口）：se blesser = 自己弄出伤口。","tr":{"zh":"她在滑雪时伤了脚。","fr":"Elle s'est blessée au pied en faisant du ski.","alt":"Elle s'est fait mal au pied en skiant.","note":"身体部位前用 au / à la，过去分词与主语一致。"}},
 "Se cacher": {"pos":"v. 代词式动词（第一组 -er，助动词 être）","s":"躲藏；藏起来。se cacher derrière / sous / dans。也可表示「隐瞒自己」：se cacher de qqn = 瞒着某人。游戏 cache-cache = 捉迷藏。","ipa":"[sə.ka.ʃe]","ph":"se [sə]；ca [ka]；ch 读 [ʃ]；-er 读 [e]。","pi":"ch 读 [ʃ]（像 sh），不是 [tʃ]，也不是 [k]；复合过去时：Elle s'est cachée。","et":"来源不确定，可能来自晚期拉丁语 *coacticare。同族词：cachette（藏身处）、cache-cache（捉迷藏）、cache-nez。","ex":[["Les enfants aiment se cacher.","孩子们爱捉迷藏。"],["Il se cache derrière l'arbre.","他躲在树后面。"],["Elle se cache de ses parents.","她瞒着父母。"]],"co":[["jouer à cache-cache","玩捉迷藏"],["se cacher derrière qqch","躲在某物后面"],["se cacher de qqn","瞒着某人"],["une cachette","藏身处"]],"sy":[["se dissimuler","soutenu","隐藏起来"],["se planquer","familier","躲起来"],["se réfugier","courant","躲进、避难"]],"fq":"高频，日常常用。","me":"cache-cache：一个词重复两遍，捉迷藏。","tr":{"zh":"小猫躲在沙发下面。","fr":"Le chat se cache sous le canapé.","alt":"Le chat est caché sous le canapé.","note":"se cacher 是动作；être caché 是状态。"}},
 "Se déguiser": {"pos":"v. 代词式动词（第一组 -er，助动词 être）","s":"化装；打扮成……。se déguiser en + 名词 = 扮成……：se déguiser en pirate = 扮成海盗。名词 un déguisement（化装服）。","ipa":"[sə.de.ɡi.ze]","ph":"se [sə]；dé [de]；gui 读 [ɡi]（u 不发音）；s 在元音间读 [z]；-er 读 [e]。","pi":"gui 里的 u 不读，g 读 [ɡ]；s 读 [z]；介词用 en：se déguiser en clown，不是 comme。","et":"dé-（改变）+ guise（法兰克/日耳曼语 wisa「方式」）：改变外观。英语 disguise 与它同源。","ex":[["Les enfants aiment se déguiser pour Carnaval.","孩子们喜欢在狂欢节打扮。"],["Il s'est déguisé en pirate.","他扮成了海盗。"]],"co":[["se déguiser en + 名词","扮成……"],["une fête déguisée","化装舞会"],["un déguisement","化装服"],["déguiser la vérité","掩饰真相"]],"sy":[["se costumer","courant","穿上戏服"],["se travestir","soutenu","乔装、女扮男装"],["se maquiller","courant","化妆"]],"fq":"中频，日常常用。","me":"guise → disguise：英语词一模一样地藏在里面。","tr":{"zh":"万圣节我要扮成吸血鬼。","fr":"À Halloween, je vais me déguiser en vampire.","alt":"Pour Halloween, je me déguise en vampire.","note":"aller + 动词原形：近将来时。"}},
 "Se garer": {"pos":"v. 代词式动词（第一组 -er，助动词 être）","s":"停车；把车停好。se garer devant / près de / dans la rue。及物 garer sa voiture = 把车停好。比 stationner 更口语。名词 un garage、une gare。","ipa":"[sə.ɡa.ʁe]","ph":"se [sə]；ga [ɡa]；r [ʁ]；-er 读 [e]。","pi":"g 在 a 前读 [ɡ]，不是 [ʒ]；与 gare（火车站）同族，不要混；复合时态 être：Je me suis garé。","et":"来自古法语 garer，源自日耳曼语 wārōn「注意、保护」。同族词：gare（火车站）、garage、garer。","ex":[["Il est difficile de se garer en centre-ville.","市中心很难停车。"],["Je me suis garé devant la boulangerie.","我把车停在面包店前面。"]],"co":[["se garer en double file","双排停车"],["se garer sur le trottoir","停在人行道上"],["une place pour se garer","停车位"]],"sy":[["stationner","courant","停放，较正式"],["parquer","soutenu","把车停放"],["se ranger","courant","靠边停"]],"fq":"高频，日常常用。","me":"garer ~ gare：把车「放进车站」，停好。","tr":{"zh":"你可以把车停在这里。","fr":"Tu peux te garer ici.","alt":"Gare-toi ici, c'est bon.","note":"代词式动词命令式：Gare-toi !（你）。"}},
 "Se plaindre de": {"pos":"v. 代词式动词（第三组，同 craindre；过去分词 plaint，助动词 être）","s":"抱怨；诉苦。se plaindre de qqch = 抱怨某事；se plaindre à qqn = 向某人投诉；se plaindre que + 虚拟式/直陈式。变位：je me plains，nous nous plaignons。","ipa":"[sə.plɛ̃dʁ də]","ph":"se [sə]；plain 读 [plɛ̃]；dre 读 [dʁ]；de 轻读 [də]。","pi":"ain 读鼻化 [ɛ̃]；变位 nous nous plaignons 里出现 gn [ɲ]；介词用 de，不是 sur。","et":"来自拉丁语 plangere（「捶胸」，表示悲痛）。同族词：plainte（投诉）、plaintif、complainte。","ex":[["Il passe son temps à se plaindre de la météo.","他总在抱怨天气。"],["Je me plains de mon voisin au propriétaire.","我向房东投诉我的邻居。"]],"co":[["se plaindre de qqch","抱怨某事"],["se plaindre à qqn","向某人投诉"],["porter plainte","起诉、报案"],["ne pas se plaindre","不抱怨"]],"sy":[["râler","familier","发牢骚"],["se lamenter","soutenu","哀叹"],["protester","courant","抗议"]],"fq":"高频，日常常用。","me":"plainte（投诉）：se plaindre = 发出「plainte」。","tr":{"zh":"他总是抱怨工作。","fr":"Il se plaint toujours de son travail.","alt":"Il râle tout le temps à cause de son travail.","note":"se plaindre de + 名词；向谁抱怨用 à。"}},
 "Se révéler": {"pos":"v. 代词式动词（第一组 -er，助动词 être；je me révèle）","s":"结果是；显现出是；被证明。se révéler + 形容词 = 事后看来是……：Ce voyage s'est révélé difficile。也可指「显露才华」。注意：je me révèle，nous nous révélons。","ipa":"[sə.ʁe.ve.le]","ph":"se [sə]；ré [ʁe]；vé [ve]；lé [le]；-er 读 [e]。","pi":"变位时 é 变 è：je révèle；révélé 的过去分词要与主语一致：Elle s'est révélée utile。","et":"来自拉丁语 revelare（re- 去除 + velum「面纱」：揭开面纱）。同族词：révélation、révélateur、voile。","ex":[["Ce voyage s'est révélé difficile.","这次旅行事实证明很艰难。"],["Le nouveau directeur s'est révélé très compétent.","新主管被证明非常能干。"]],"co":[["se révéler utile / efficace","被证明有用/有效"],["se révéler faux","结果是假的"],["se révéler être + 名词","事实上是……"]],"sy":[["s'avérer","soutenu","被证明是……（更书面）"],["apparaître","courant","显得、出现"],["se montrer","courant","表现出"]],"fq":"中频，书面语较多。","me":"re + velum（面纱）：把面纱揭开，才看到真面目。","tr":{"zh":"这个办法被证明很有效。","fr":"Cette méthode s'est révélée très efficace.","alt":"Cette méthode a fini par être très efficace.","note":"révélée 与阴性主语一致。"}},
 "Se saisir de": {"pos":"v. 代词式动词（第二组 -ir，助动词 être；nous nous saisissons）","s":"抓住；夺取；着手处理（问题、案件）。se saisir d'un objet = 抓起一件东西；se saisir d'un dossier / d'une question = 接手一个案子/着手处理一个问题。比 prendre 更正式有力。","ipa":"[sə.sɛ.ziʁ də]","ph":"se [sə]；sai 读 [sɛ]；si 里 s 读 [z]；r 读 [ʁ]；de 轻读 [də]。","pi":"saisir 中间的 s 读 [z]；ai 读 [ɛ]；de 后遇元音要省音：se saisir d'un problème。","et":"来自中世纪拉丁语 sacire，可能源自法兰克语；确切来源不确定。同族词：saisie（扣押）、saisissant（惊人的）、dessaisir。","ex":[["Le gouvernement doit se saisir de ce problème.","政府必须着手解决这个问题。"],["Il s'est saisi de son sac et il est parti.","他抓起包就走了。"]],"co":[["se saisir de qqch","抓住/着手处理某事"],["se saisir d'un dossier","接手一个案子"],["saisir l'occasion","抓住机会"]],"sy":[["s'emparer de","soutenu","夺取、占据"],["attraper","courant","抓住"],["prendre en charge","courant","接手处理"]],"fq":"中低频，新闻和行政语境。","me":"saisir = 抓住；se saisir de = 把它抓在自己手里。","tr":{"zh":"市长决定着手处理这个问题。","fr":"Le maire a décidé de se saisir du problème.","alt":"Le maire va s'occuper du problème.","note":"de + le = du：se saisir du problème。"}},
 "Soupirer": {"pos":"v.i. 不及物动词（第一组 -er，助动词 avoir）","s":"叹气；叹息。soupirer de soulagement / de fatigue。soupirer après qqch（书面）= 渴望某物。名词 un soupir。","ipa":"[su.pi.ʁe]","ph":"ou [u]；pi [pi]；ra 在 -er 前读 [ʁe]。","pi":"ou 读 [u]；与 respirer 形近（都含 spirare），注意拼写 sou-pirer。","et":"来自拉丁语 suspirare（sub- 从下面 + spirare 呼吸：从心底出气）。同族词：soupir、respirer、inspirer。","ex":[["Elle a soupiré de soulagement.","她松了口气。"],["Il soupire en regardant l'horloge.","他看着钟叹了口气。"]],"co":[["soupirer de soulagement","松了口气"],["pousser un soupir","叹一口气"],["soupirer d'ennui","无聊地叹气"]],"sy":[["gémir","soutenu","呻吟"],["souffler","courant","吁一口气"],["se lamenter","soutenu","哀叹"]],"fq":"中频，叙述与文学中常见。","me":"sou-pirer ≈ sous + respirer：从胸口底下出一口气。","tr":{"zh":"他叹了口气，关上了书。","fr":"Il a soupiré et il a fermé le livre.","alt":"Il a poussé un soupir et il a fermé son livre.","note":"soupirer 是不及物动词，常加 de + 情绪。"}},
 "Subir": {"pos":"v.t. 及物动词（第二组 -ir，助动词 avoir；nous subissons）","s":"遭受；承受；忍受；经历（不愉快的变化）。subir une opération = 接受手术；subir une défaite = 遭到失败；subir des changements = 经历变化。主语通常是被动承受的一方。","ipa":"[sy.biʁ]","ph":"su 读 [sy]（舌位在前，嘴唇圆）；bir 读 [biʁ]；r 读 [ʁ]。","pi":"u 读 [y]，不是 [u]；与英语 subir 无关，不要读成「萨比」；第二组变位：il subit，nous subissons。","et":"来自拉丁语 subire（sub- 在下面 + ire 去：「走到下面」，即承受）。同族词：subissement、subi。","ex":[["Les ménages défavorisés subissent cette situation.","弱势家庭承受着这种处境。"],["Il a subi une opération au genou.","他做了膝盖手术。"]],"co":[["subir une opération","接受手术"],["subir une défaite","遭受失败"],["subir les conséquences","承担后果"],["subir un examen","接受检查/考试"]],"sy":[["endurer","soutenu","忍受（痛苦）"],["supporter","courant","忍受、承受"],["essuyer","courant","遭受（失败、批评）"]],"fq":"高频，日常与新闻常用。","me":"sub-（在下面）+ ire（去）：走到重量下面，被压着。","tr":{"zh":"这家公司遭受了巨大的损失。","fr":"Cette entreprise a subi de lourdes pertes.","alt":"Cette entreprise a perdu beaucoup d'argent.","note":"subir 后接宾语，不用介词。"}},
 "Suer": {"pos":"v.i. 不及物动词（第一组 -er，助动词 avoir）","s":"出汗；流汗。Il fait chaud, je sue。也可表示「费力」：suer sang et eau = 拼命辛苦。比 transpirer 更口语，也更直接。名词 la sueur（汗水）。","ipa":"[sɥe]","ph":"su 读 [sɥ]（半元音 ɥ + e），整个词只有一个音节；变位 je sue [sy]。","pi":"u + e 连成 [sɥe]，不要分成两个音节；je sue 读 [sy]，ils suent 读 [sy]。","et":"来自拉丁语 sudare（出汗）。同族词：sueur（汗）、suant、sudation。","ex":[["Il fait trop chaud, je sue.","太热了，我出汗了。"],["Il a sué sang et eau pour finir ce travail.","他费尽力气才完成这项工作。"]],"co":[["suer à grosses gouttes","汗如雨下"],["suer sang et eau","拼命辛苦"],["faire suer qqn","让某人心烦"],["une sueur froide","冷汗"]],"sy":[["transpirer","courant","出汗，较中性"],["être en nage","courant","浑身是汗"],["ruisseler","soutenu","汗流如注"]],"fq":"中频，日常常用。","me":"sueur（汗水）：suer 就是「流 sueur」。","tr":{"zh":"跑完步，我浑身是汗。","fr":"Après la course, je suais à grosses gouttes.","alt":"Après le jogging, j'étais en nage.","note":"suais 为未完成过去时。"}},
 "Surplomber": {"pos":"v.t. 及物动词（第一组 -er，助动词 avoir）","s":"俯瞰；高悬于……之上；凌空突出。Le balcon surplombe la mer = 阳台俯瞰着大海。常用于描写悬崖、塔楼、房屋位置。","ipa":"[syʁ.plɔ̃.be]","ph":"sur [syʁ]；plom 读鼻化 [plɔ̃]；b [b]；-er 读 [e]。","pi":"om 在 b 前是鼻化 [ɔ̃]，m 不发；sur 里 u 读 [y]；m 不读。","et":"sur-（在上）+ plomb（铅锤；à plomb = 垂直）：像铅锤线一样垂在上面。同族词：plomb、plomber、aplomb。","ex":[["Le balcon surplombe la mer.","阳台俯瞰大海。"],["Le château surplombe le village.","城堡高高俯瞰着村庄。"]],"co":[["surplomber la mer","俯瞰大海"],["surplomber la vallée","俯视山谷"],["un rocher qui surplombe","突出的岩石"]],"sy":[["dominer","courant","俯视、位居……之上"],["donner sur","courant","朝向、面对"],["dépasser","courant","高出、超过"]],"fq":"中低频，描写景色时常用。","me":"sur + plomb：垂在上方的铅锤线。","tr":{"zh":"这座房子俯瞰着整个山谷。","fr":"Cette maison surplombe toute la vallée.","alt":"De cette maison, on domine toute la vallée.","note":"surplomber 直接接宾语，不加介词。"}},
 "Suspendre": {"pos":"v.t. 及物动词（第三组，同 vendre；过去分词 suspendu，助动词 avoir）","s":"暂停；中止；悬挂。suspendre les vols = 暂停航班；suspendre un employé = 停职；suspendre une lampe au plafond = 把灯挂在天花板上。","ipa":"[sys.pɑ̃dʁ]","ph":"sus [sys]；pen 读鼻化 [pɑ̃]；dre [dʁ]。","pi":"s 在这里读 [s]，两个 s 之间的 p 要读；en 读 [ɑ̃]，n 不发；变位同 vendre：je suspends，nous suspendons。","et":"来自拉丁语 suspendere（sub- 下 + pendere 悬挂）。同族词：suspension、suspens、pendre、pendule。","ex":[["Ils ont décidé de suspendre les vols.","他们决定暂停航班。"],["Elle suspend son manteau à la patère.","她把大衣挂在衣钩上。"]],"co":[["suspendre un vol / un service","暂停航班/服务"],["suspendre une séance","休会"],["suspendre qqch au plafond","把某物挂在天花板上"],["un pont suspendu","吊桥"]],"sy":[["interrompre","courant","打断、中断"],["accrocher","courant","挂上"],["arrêter","courant","停止"]],"fq":"中高频，新闻常用。","me":"sus + pendre：悬在半空，所以「暂停」。","tr":{"zh":"因为大雪，学校暂停了上课。","fr":"À cause de la neige, l'école a suspendu les cours.","alt":"Avec la neige, les cours sont suspendus.","note":"被动形式 être suspendu：les cours sont suspendus。"}},
 "Trancher": {"pos":"v.t./v.i. 动词（第一组 -er，助动词 avoir）","s":"切；切断；做出决断；拍板。trancher du pain = 切面包；trancher une question = 裁决；trancher entre A et B = 在 A 和 B 之间做决定。也可表示「形成鲜明对比」：trancher sur。","ipa":"[tʁɑ̃.ʃe]","ph":"tr [tʁ]；an 读 [ɑ̃]；ch 读 [ʃ]；-er 读 [e]。","pi":"an 是鼻化元音，n 不发；ch 读 [ʃ]，不是 [k]。","et":"来自古法语 trenchier，来源不确定。同族词：tranche（片）、tranchant（锋利的）、tranchoir。","ex":[["Entre Paris et Lille, j'ai tranché : j'ai choisi d'aller à Lille.","在巴黎和里尔之间我选了里尔。"],["Il tranche le pain avec un grand couteau.","他用大刀切面包。"],["Le juge a tranché en sa faveur.","法官做出了对他有利的裁决。"]],"co":[["trancher une question","裁决问题"],["trancher entre A et B","在 A 和 B 之间做选择"],["trancher le pain","切面包"],["trancher sur","与……形成对比"]],"sy":[["décider","courant","决定"],["couper","courant","切"],["choisir","courant","选择"]],"fq":"中高频，日常与新闻都有。","me":"tranche（切片）：trancher = 一刀切下去，不再犹豫。","tr":{"zh":"我们得尽快做决定。","fr":"Nous devons trancher rapidement.","alt":"Il faut qu'on décide vite.","note":"devoir + 动词原形，表示必须。"}},
 "Transpirer": {"pos":"v.i. 不及物动词（第一组 -er，助动词 avoir）","s":"出汗；流汗。比 suer 更中性、更文雅。也有比喻义：L'information a transpiré = 消息泄露出来了。名词 la transpiration。","ipa":"[tʁɑ̃s.pi.ʁe]","ph":"trans 读 [tʁɑ̃s]（n 不发，s 要读 [s]）；pi [pi]；-ra 在 -er 前读 [ʁe]。","pi":"trans- 后的 s 与 p 相接，读 [tʁɑ̃s.pi]；不要读成 [tʁɑ̃z]。","et":"来自中世纪拉丁语 transpirare（trans- 穿过 + spirare 呼出：气从皮肤透出）。同族词：transpiration、respirer。","ex":[["Il commence à transpirer après l'effort.","运动后他开始出汗。"],["Je transpire beaucoup en été.","我夏天出汗很多。"]],"co":[["transpirer abondamment","大量出汗"],["la transpiration","出汗；汗"],["l'information a transpiré","消息泄露了"]],"sy":[["suer","familier","出汗，更口语"],["être en sueur","courant","浑身是汗"],["perler","littéraire","（汗珠）冒出"]],"fq":"中频，日常常用。","me":"trans + spirer：气息「透过」皮肤出来。","tr":{"zh":"天气很热，我出了很多汗。","fr":"Il fait très chaud, je transpire beaucoup.","alt":"Avec cette chaleur, je suis en sueur.","note":"transpirer 是不及物动词，不带宾语。"}},
 "Traverser": {"pos":"v.t. 及物动词（第一组 -er，助动词 avoir）","s":"穿过；横过；经历（困难时期）。traverser la rue = 过马路；traverser une crise = 经历危机。直接带宾语，不加介词 à 或 de。","ipa":"[tʁa.vɛʁ.se]","ph":"tra [tʁa]；ver 读 [vɛʁ]；se [se]；两个 r 都是小舌音 [ʁ]。","pi":"ver 里 e 读 [ɛ]，r 要发；不用介词：traverser la rue，不是 traverser à la rue。","et":"来自拉丁语 transversare（trans- 穿过 + versus 转向）。同族词：traversée（横渡）、travers（à travers）、transversal。","ex":[["Il faut faire attention avant de traverser la rue.","过马路前要小心。"],["Nous avons traversé la ville à vélo.","我们骑车穿过了城市。"]],"co":[["traverser la rue","过马路"],["traverser une période difficile","经历困难时期"],["traverser à pied","步行穿过"],["à travers","穿过、透过"]],"sy":[["franchir","soutenu","越过（障碍、边界）"],["passer","courant","经过"],["parcourir","courant","走遍、跑遍"]],"fq":"高频，日常常用。","me":"trans-vers：横着走过去。","tr":{"zh":"绿灯亮了才能过马路。","fr":"On traverse la rue quand le feu est vert.","alt":"Tu traverses seulement quand c'est vert.","note":"on = 人们/我们，口语里常用。"}},
 "Verbaliser": {"pos":"v.i./v.t. 动词（第一组 -er，助动词 avoir）","s":"（警察）开罚单；给……开违章通知。verbaliser un conducteur = 给司机开罚单。也有「用语言表达出来」的意思：verbaliser ses émotions。","ipa":"[vɛʁ.ba.li.ze]","ph":"ver [vɛʁ]；ba [ba]；li [li]；s 读 [z]；-er 读 [e]。","pi":"s 读 [z]；第一个音节 ver 读 [vɛʁ]，r 要发。","et":"来自 procès-verbal（笔录，罚单）中的 verbal（拉丁语 verbum「词」）+ -iser。同族词：verbal、verbe、procès-verbal。","ex":[["Le policier a décidé de verbaliser le conducteur.","警察决定给司机开罚单。"],["Il a été verbalisé pour excès de vitesse.","他因超速被开了罚单。"]],"co":[["verbaliser un automobiliste","给驾驶员开罚单"],["se faire verbaliser","被开罚单"],["verbaliser ses émotions","说出自己的感受"]],"sy":[["mettre une amende","courant","罚款"],["dresser un procès-verbal","soutenu","开具笔录/罚单"],["exprimer","courant","表达"]],"fq":"中低频，交通和管理场合。","me":"procès-verbal：警察写的「笔录」，verbaliser = 写下来。","tr":{"zh":"我因为停错地方被开了罚单。","fr":"Je me suis fait verbaliser parce que j'étais mal garé.","alt":"J'ai eu une amende, j'étais mal garé.","note":"se faire + 动词原形：被动含义。"}},
 "Adossé(e)": {"pos":"adj. 形容词，阴性 adossée，复数 adossés / adossées","s":"背靠……的；靠着……建的。adossé à un mur = 背靠着墙。可指人（背靠着）或建筑（靠着墙、山而建）。来自动词 adosser。","ipa":"[a.dɔ.se]","ph":"a [a]；do 读 [dɔ]（开口 o）；ss 读 [s]；é 读 [e]。","pi":"ss 读 [s]；dos（背）单独说时 s 不发音，但在 adossé 里读 [s]；拼写别漏掉双 s。","et":"来自 adosser（à- + dos「背」，拉丁语 dorsum）。同族词：dos、dossier、endosser。","ex":[["La cabane est adossée au mur.","小屋靠着墙。"],["Il est adossé à un arbre.","他背靠着一棵树。"]],"co":[["adossé à un mur","背靠着墙"],["adossé à la montagne","依山而建"],["s'adosser à qqch","靠在某物上"]],"sy":[["appuyé","courant","倚靠的"],["collé à","courant","紧贴着"],["contre","courant","靠着（介词）"]],"fq":"中低频，描写位置时用。","me":"à + dos（背）：用背靠着。","tr":{"zh":"我们的房子是靠着山建的。","fr":"Notre maison est adossée à la montagne.","alt":"Notre maison est construite contre la montagne.","note":"adossée 与阴性主语一致。"}},
 "Aisé(e)": {"pos":"adj. 形容词，阴性 aisée，复数 aisés / aisées","s":"宽裕的；富裕的；（书面）容易的。une famille aisée = 家境宽裕的家庭。也可表示「轻松自如的」：un style aisé。比 riche 更含蓄、更礼貌。","ipa":"[ɛ.ze]","ph":"ai 读 [ɛ]；s 在元音间读 [z]；é 读 [e]。","pi":"ai 读 [ɛ]；s 读 [z]；与 aise [ɛz] 同音近，aisé 末尾是 [e]。","et":"来自 aise（舒适、宽裕），来源不确定；同族词：aise、aisance、malaise、à l'aise。","ex":[["Ils viennent d'une famille aisée.","他们来自一个富裕的家庭。"],["Ce n'est pas aisé de trouver un appartement ici.","在这里找公寓不容易。"]],"co":[["une famille aisée","富裕家庭"],["les classes aisées","富裕阶层"],["il n'est pas aisé de + inf.","做……并不容易"]],"sy":[["riche","courant","有钱的，更直接"],["fortuné","soutenu","有财产的"],["facile","courant","容易的"]],"fq":"中频，书面和新闻常见。","me":"à l'aise：生活舒适，不愁钱。","tr":{"zh":"她出身于一个家境宽裕的家庭。","fr":"Elle vient d'une famille aisée.","alt":"Elle vient d'une famille qui a de l'argent.","note":"aisée 与阴性名词 famille 一致。"}},
 "Apaisé(e)": {"pos":"adj. 形容词，阴性 apaisée，复数 apaisés / apaisées","s":"平静下来的；被安抚的；缓和了的。se sentir apaisé = 感到平静；un climat apaisé = 缓和的气氛。动词是 apaiser（使平静）。","ipa":"[a.pɛ.ze]","ph":"a [a]；pai 读 [pɛ]；s 读 [z]；é 读 [e]。","pi":"ai 读 [ɛ]；s 在元音间读 [z]，不是 [s]；只有一个 p，别写成 appaisé。","et":"来自 apaiser（à- + paix「和平」，拉丁语 pax）。同族词：paix、paisible、apaisement。","ex":[["Il se sent plus apaisé après ses vacances.","度假后他感觉更平静了。"],["Le bébé est enfin apaisé.","宝宝终于安静下来了。"]],"co":[["se sentir apaisé","感到平静"],["un climat apaisé","缓和的气氛"],["un regard apaisé","平静的眼神"]],"sy":[["calme","courant","安静的"],["serein","soutenu","安详的"],["rassuré","courant","安心的"]],"fq":"中频，书面和日常都有。","me":"à + paix：回到和平的状态。","tr":{"zh":"听完音乐，我感觉很平静。","fr":"Après avoir écouté de la musique, je me sens apaisé.","alt":"Avec la musique, je me sens plus calme.","note":"après avoir + 过去分词：做完之后。"}},
 "Commode": {"pos":"adj. 形容词，阴阳同形；复数 commodes（另有名词：une commode 五斗柜）","s":"方便的；舒适的；好用的。C'est commode = 这很方便。常用否定：Ce n'est pas commode。也作名词 la commode = 带抽屉的矮柜；不要与「厕所」混淆。","ipa":"[kɔ.mɔd]","ph":"c 读 [k]；两个 o 都读 [ɔ]；m [m]；结尾 -de 读 [d]，e 不发音。","pi":"结尾 e 不发音；commode 作形容词阴阳同形，作名词则是阴性 une commode（五斗柜）。","et":"来自拉丁语 commodus（合适的、便利的）。同族词：commodité、accommoder、incommode；英语 commodious、accommodate。","ex":[["Le manque de transports publics n'est vraiment pas commode.","缺少公共交通真的很不方便。"],["C'est commode d'habiter près du métro.","住在地铁附近很方便。"]],"co":[["c'est commode","这很方便"],["pas très commode","不太方便"],["une commode","五斗柜"],["la commodité","便利"]],"sy":[["pratique","courant","实用的，最常见"],["facile","courant","容易的"],["confortable","courant","舒适的"]],"fq":"中频，日常常用，多用于否定。","me":"commode ← 与 accommoder 同族：方便 = 容易让人适应。","tr":{"zh":"住在车站附近很方便。","fr":"C'est commode d'habiter près de la gare.","alt":"C'est pratique d'habiter près de la gare.","note":"C'est + 形容词 + de + 动词原形。"}},
 "Constant(e)": {"pos":"adj. 形容词，阴性 constante，复数 constants / constantes","s":"持续的；不断的；稳定的；恒定的。des efforts constants = 持续的努力；une température constante = 恒温。也有名词 une constante（常数、不变因素）。","ipa":"[kɔ̃.stɑ̃]","ph":"con 读鼻化 [kɔ̃]；st [st]；an 读 [ɑ̃]；阴性 constante 读 [kɔ̃.stɑ̃t]，t 要发音。","pi":"阳性 constant 结尾 t 不发音；阴性 constante 的 t 要发音。","et":"来自拉丁语 constans（constare「站稳」）。同族词：constance、constamment、stable、instant。","ex":[["Ses efforts sont constants.","他的努力是持续不断的。"],["La température reste constante toute l'année.","全年气温保持恒定。"]],"co":[["des efforts constants","持续的努力"],["une température constante","恒温"],["une progression constante","稳步增长"],["constamment","不断地"]],"sy":[["continu","courant","连续的"],["stable","courant","稳定的"],["régulier","courant","规律的、均匀的"]],"fq":"中高频，日常与书面都有。","me":"con + stare（站）：一直站着不动，所以「恒定」。","tr":{"zh":"她一直在不断进步。","fr":"Elle fait des progrès constants.","alt":"Elle progresse sans arrêt.","note":"形容词放在名词后，与名词一致（progrès 复数 → constants）。"}},
 "Convaincu(e)": {"pos":"adj. 形容词，阴性 convaincue，复数 convaincus / convaincues","s":"确信的；被说服的；坚信的。être convaincu de qqch / que + 直陈式 = 确信……。也指「信念坚定的」：un militant convaincu。动词 convaincre（说服）的过去分词。","ipa":"[kɔ̃.vɛ̃.ky]","ph":"con 读 [kɔ̃]；vain 读 [vɛ̃]；cu 读 [ky]；结尾 u 读 [y]，不发 c。","pi":"结尾 -cu 读 [ky]，u 读 [y]，不是 [u]；ain 读鼻化 [ɛ̃]，n 不发；注意拼写 -aincu。","et":"来自拉丁语 convincere（con- 完全 + vincere 战胜：完全说服）。同族词：convaincre、vaincre、victoire、convincing（英）。","ex":[["Je suis convaincu qu'il dit la vérité.","我确信他说的是真话。"],["Elle n'est pas convaincue par cette explication.","她并没有被这个解释说服。"]],"co":[["être convaincu de qqch","确信某事"],["être convaincu que + indicatif","确信……"],["un partisan convaincu","坚定的支持者"],["pas convaincu","不信服"]],"sy":[["certain","courant","确定的"],["persuadé","courant","深信的"],["sûr","courant","有把握的"]],"fq":"中高频，日常与书面常用。","me":"con-vincu：被「战胜」了，也就是被说服了。","tr":{"zh":"我确信这个方案是最好的。","fr":"Je suis convaincu que c'est la meilleure solution.","alt":"Je suis sûr que c'est la meilleure solution.","note":"être convaincu que + 直陈式；否定时可用虚拟式。"}},
 "Décrié(e)": {"pos":"adj. 形容词，阴性 décriée，复数 décriés / décriées","s":"被贬低的；饱受批评的；名声不佳的。un système très décrié = 备受诟病的制度。多用于书面语；来自动词 décrier（公开指责）。","ipa":"[de.kʁi.e]","ph":"dé [de]；cri 读 [kʁi]；é 读 [e]，三个音节。","pi":"结尾 -é 读 [e]；cri 与 é 分开读成两个音节 [kʁi.e]；阴性 décriée 有两个 e。","et":"来自 décrier（dé-：反向 + crier「叫喊」，拉丁语 quiritare）；意为「喊着贬低」。同族词：cri、crier、décri。","ex":[["C'est un auteur très décrié par la critique.","这位作家饱受评论界诟病。"],["Cette réforme est très décriée.","这项改革饱受批评。"]],"co":[["très décrié","饱受批评"],["décrié par la critique","被评论界贬低"],["un système décrié","名声不好的制度"]],"sy":[["critiqué","courant","被批评的"],["discrédité","soutenu","名誉受损的"],["contesté","courant","有争议的"]],"fq":"中低频，书面语。","me":"dé-cri-é：被人「大喊反对」的。","tr":{"zh":"这项政策饱受批评。","fr":"Cette politique est très décriée.","alt":"Tout le monde critique cette politique.","note":"décriée 与阴性名词 politique 一致。"}},
 "Diurne": {"pos":"adj. 形容词，阴阳同形；复数 diurnes","s":"昼行的；白天活动的（动物）；白天的。un oiseau diurne = 白天活动的鸟。反义词 nocturne（夜行的）。多用于生物学与科学语境。","ipa":"[djyʁn]","ph":"di 读 [dj]；ur 读 [yʁ]；n [n]；结尾 e 不发音；整个词一个音节。","pi":"ur 读 [yʁ]（u 圆唇前舌音）；结尾 e 不发音，所以是一个音节。","et":"来自拉丁语 diurnus（dies「日」）。同族词：jour、journée、journal、quotidien；英语 diurnal。","ex":[["Contrairement au hibou, cet oiseau est diurne.","与猫头鹰相反，这种鸟是昼行性的。"],["Les papillons sont des insectes diurnes.","蝴蝶是昼行性昆虫。"]],"co":[["un animal diurne","昼行性动物"],["un rapace diurne","日间猛禽"],["diurne / nocturne","昼行 / 夜行"]],"sy":[["nocturne","soutenu","夜行的（反义词）"],["de jour","courant","白天的"],["journalier","soutenu","每天的"]],"fq":"低频，科学与自然类文章。","me":"diurne ≈ jour（日）：白天的，夜行的则是 nocturne。","tr":{"zh":"猫头鹰是夜行动物，不是昼行动物。","fr":"Le hibou est un animal nocturne, pas diurne.","alt":"Le hibou sort la nuit, pas le jour.","note":"diurne 与 nocturne 是一对反义词。"}},
 "Éclectique": {"pos":"adj. 形容词，阴阳同形；复数 éclectiques","s":"兼收并蓄的；多元的；不拘一格的。des goûts éclectiques = 多元的品味；une bibliothèque éclectique = 涉猎很广的藏书。通常含褒义，表示广博而不单一。","ipa":"[e.klɛk.tik]","ph":"é [e]；cl [kl]；ec 读 [ɛk]；ti 读 [tik]；结尾 -que 读 [k]。","pi":"c 在这里读 [k]；结尾 -que 读 [k]，e 不发音；不要读成「艾克来克蒂克」。","et":"来自希腊语 eklektikos（「挑选的」，ek- 出 + legein 选）。同族词：éclectisme；英语 eclectic。","ex":[["Il a des goûts musicaux très éclectiques.","他的音乐品味非常多元。"],["Le menu du restaurant est assez éclectique.","这家餐厅的菜单很多元。"]],"co":[["des goûts éclectiques","多元的品味"],["une collection éclectique","风格多样的收藏"],["un style éclectique","混搭风格"]],"sy":[["varié","courant","多样的"],["divers","courant","各种各样的"],["hétéroclite","soutenu","杂七杂八的"]],"fq":"中低频，书面语和文化话题。","me":"e-clect-ique：从各处「挑选」(élire) 一点。","tr":{"zh":"她的朋友圈很多元。","fr":"Elle a un groupe d'amis très éclectique.","alt":"Ses amis viennent de milieux très variés.","note":"éclectique 阴阳同形。"}},
 "Emblématique": {"pos":"adj. 形容词，阴阳同形；复数 emblématiques","s":"标志性的；象征性的；有代表性的。un monument emblématique = 标志性建筑；être emblématique de qqch = 是某事物的象征。名词 un emblème（象征，标志）。","ipa":"[ɑ̃.ble.ma.tik]","ph":"em 读鼻化 [ɑ̃]；blé [ble]；ma [ma]；tique [tik]，共五个音节。","pi":"em 是鼻化元音 [ɑ̃]，不是 [ɛm]；e-bl-é 中间的 é 不要漏掉。","et":"来自 emblème，拉丁语 emblema，源自希腊语 emblēma（镶嵌物，装饰）。同族词：emblème、emblématique。","ex":[["La Tour Eiffel est emblématique de Paris.","埃菲尔铁塔是巴黎的象征。"],["C'est un joueur emblématique de l'équipe.","他是球队的标志性球员。"]],"co":[["emblématique de + 名词","是……的象征"],["un lieu emblématique","标志性地点"],["une figure emblématique","代表性人物"]],"sy":[["symbolique","courant","象征性的"],["représentatif","courant","有代表性的"],["typique","courant","典型的"]],"fq":"中频，新闻与文化话题。","me":"emblème（标志）+ -atique：成为标志的。","tr":{"zh":"这座桥是这个城市的标志。","fr":"Ce pont est emblématique de la ville.","alt":"Ce pont est le symbole de la ville.","note":"emblématique de + 名词。"}},
 "Entretenu(e)": {"pos":"adj. 形容词，阴性 entretenue，复数 entretenus / entretenues","s":"维护良好的；保养得好的。un jardin bien entretenu = 打理得很好的花园。常与副词 bien / mal 搭配。动词 entretenir（保养；维持）的过去分词。","ipa":"[ɑ̃t.ʁə.tə.ny]","ph":"en 读 [ɑ̃]；tre 读 [tʁə]；te 读 [tə]；nu 读 [ny]。","pi":"en 是鼻化元音；u 读 [y]；阴性 entretenue 结尾 e 不发音。","et":"来自 entretenir（entre + tenir，拉丁语 tenere「握住」）：保持住、维持。同族词：entretien（保养；面谈）、tenir、maintenir。","ex":[["Ce bâtiment est bien entretenu.","这栋楼维护得很好。"],["Le parc est mal entretenu.","这个公园管理得不好。"]],"co":[["bien / mal entretenu","维护好 / 不好"],["un jardin entretenu","打理好的花园"],["l'entretien","保养；面谈"]],"sy":[["soigné","courant","整洁的、精心的"],["bien tenu","courant","管理得好的"],["négligé","courant","疏于打理的（反义词）"]],"fq":"中频，日常常用。","me":"entre + tenu：「保持住」不让它坏。","tr":{"zh":"这条街打扫得很干净。","fr":"Cette rue est bien entretenue.","alt":"Cette rue est toujours propre.","note":"entretenue 与阴性名词 rue 一致。"}},
 "Éphémère": {"pos":"adj. 形容词，阴阳同形；复数 éphémères","s":"短暂的；转瞬即逝的。un bonheur éphémère = 短暂的幸福。也有名词 une éphémère（蜉蝣）。文学与日常均可使用。","ipa":"[e.fe.mɛʁ]","ph":"é [e]；phé 读 [fe]（ph = f）；mère 读 [mɛʁ]。","pi":"ph 读 [f]，不是 [p]；mère 里的 è 读 [ɛ]，结尾 r 要发音。","et":"来自希腊语 ephēmeros（epi- 在 + hēmera 日：只持续一天）。同族词：éphéméride（日历）；英语 ephemeral。","ex":[["La beauté de cette fleur est éphémère.","这朵花的美是短暂的。"],["C'est un succès éphémère.","这是昙花一现的成功。"]],"co":[["un bonheur éphémère","短暂的幸福"],["un succès éphémère","昙花一现"],["l'art éphémère","转瞬即逝的艺术"]],"sy":[["passager","courant","暂时的"],["fugace","soutenu","一闪而过的"],["bref","courant","短的"]],"fq":"中频，书面与文化话题。","me":"ephemeros：只有「一天」(hémera) 的寿命。","tr":{"zh":"快乐是短暂的。","fr":"Le bonheur est éphémère.","alt":"Le bonheur ne dure pas longtemps.","note":"éphémère 阴阳同形。"}},
 "Escarpé(e)": {"pos":"adj. 形容词，阴性 escarpée，复数 escarpés / escarpées","s":"陡峭的；险峻的。un chemin escarpé = 陡峭的小路；une falaise escarpée = 陡崖。多用于山地、海岸、道路。","ipa":"[ɛs.kaʁ.pe]","ph":"es 读 [ɛs]；car 读 [kaʁ]；pé 读 [pe]；r 读 [ʁ]。","pi":"es- 不要读成 [e]，s 要发音；r 要发。","et":"来自意大利语 scarpa（斜坡），法语 escarpe（斜坡）与其有关；确切路径不太确定。同族词：escarpement（陡坡）。","ex":[["Le sentier est très escarpé.","这条小路很陡。"],["Ils ont escaladé une falaise escarpée.","他们爬上了一道陡崖。"]],"co":[["un chemin escarpé","陡路"],["une pente escarpée","陡坡"],["une côte escarpée","陡峭的海岸/山坡"]],"sy":[["raide","courant","陡的"],["abrupt","soutenu","陡峭的"],["pentu","courant","坡度大的"]],"fq":"中低频，描写地形时使用。","me":"es-carpé：想象一条几乎垂直的山路。","tr":{"zh":"通往山顶的路非常陡。","fr":"Le chemin vers le sommet est très escarpé.","alt":"La route vers le sommet est très raide.","note":"escarpé 与阳性名词 chemin 一致。"}},
 "Étouffant(e)": {"pos":"adj. 形容词，阴性 étouffante，复数 étouffants / étouffantes","s":"闷热的；令人窒息的；压抑的。une chaleur étouffante = 闷热。也指气氛、环境令人压抑：une ambiance étouffante。动词 étouffer 的现在分词作形容词。","ipa":"[e.tu.fɑ̃]","ph":"é [e]；tou 读 [tu]；ffan 读 [fɑ̃]；阴性 étouffante 读 [e.tu.fɑ̃t]。","pi":"ou 读 [u]；ff 只读一个 [f]；阳性结尾 t 不发音，阴性 t 要发音。","et":"来自 étouffer，来源不确定。同族词：étouffer（窒息）、étouffement。","ex":[["La chaleur est étouffante aujourd'hui.","今天热得让人喘不过气。"],["L'ambiance dans la salle était étouffante.","房间里的气氛让人窒息。"]],"co":[["une chaleur étouffante","闷热"],["une ambiance étouffante","压抑的气氛"],["un air étouffant","窒闷的空气"]],"sy":[["suffocant","soutenu","令人窒息的"],["oppressant","soutenu","压抑的"],["lourd","courant","闷的（天气）"]],"fq":"中频，天气和感受描写。","me":"étouffer → étouffant：热得让你喘不过气。","tr":{"zh":"房间里很闷热。","fr":"Il fait une chaleur étouffante dans la pièce.","alt":"On étouffe dans cette pièce.","note":"étouffer 也可直接用作动词：on étouffe。"}},
 "Évident(e)": {"pos":"adj. 形容词，阴性 évidente，复数 évidents / évidentes","s":"显而易见的；明显的。C'est évident ! = 这很明显！il est évident que + 直陈式 = 显然……。口语里 Évident ! 可以表示「当然！」。名词 une évidence。","ipa":"[e.vi.dɑ̃]","ph":"é [e]；vi [vi]；dent 读 [dɑ̃]；-ent 不发 t（阳性）；阴性 évidente 读 [e.vi.dɑ̃t]。","pi":"-ent 读 [ɑ̃]，不是 [ɛnt]；阳性词尾的 t 和 n 都不发。","et":"来自拉丁语 evidens（e- 出 + videre 看：一眼就看出来）。同族词：évidence、évidemment、voir。","ex":[["C'est évident qu'il ment.","他显然在撒谎。"],["Il est évident que tu as raison.","显然你是对的。"]],"co":[["c'est évident","这很明显"],["il est évident que + 直陈式","显然……"],["évidemment","当然、显然"],["une évidence","显而易见的事"]],"sy":[["clair","courant","清楚的"],["manifeste","soutenu","明显的"],["flagrant","soutenu","显眼的、明目张胆的"]],"fq":"极高频，日常常用。","me":"e-vid-ent ≈ 英语 evident：看得一清二楚。","tr":{"zh":"很明显，他不想来。","fr":"Il est évident qu'il ne veut pas venir.","alt":"C'est clair, il n'a pas envie de venir.","note":"il est évident que 后接直陈式。"}},
 "Exposé(e)": {"pos":"adj. 形容词，阴性 exposée，复数 exposés / exposées；也作名词 un exposé（报告、陈述）","s":"暴露在……下的；朝向……的；展出的。exposé au soleil / au vent = 暴晒/迎风；une maison exposée au sud = 朝南的房子。名词 un exposé = 课堂报告、陈述。","ipa":"[ɛk.spo.ze]","ph":"ex 读 [ɛk]；s 与 p 相连读 [sp]；o 读 [o]；sé 读 [ze]。","pi":"x 读 [ks]；po 里的 o 是闭口 [o]；s 读 [z]；与 exposer（展出；暴露；陈述）同族，注意一词多义。","et":"来自 exposer（拉丁语 exponere：ex- 出 + ponere 放，受 poser 影响）。同族词：exposition（展览）、exposé、poser。","ex":[["Les cours d'écoles sont exposées au soleil.","校园操场暴晒在阳光下。"],["Cette maison est exposée plein sud.","这栋房子正朝南。"]],"co":[["exposé au soleil","暴晒"],["exposé au danger","面临危险"],["plein sud","正朝南"],["faire un exposé","做报告"]],"sy":[["orienté","courant","朝向……的"],["soumis à","soutenu","受……影响的"],["vulnérable","soutenu","易受攻击的"]],"fq":"中高频，日常与学术都有。","me":"ex + poser：被「放在外面」，没有遮挡。","tr":{"zh":"我的房间朝南。","fr":"Ma chambre est exposée au sud.","alt":"Ma chambre donne plein sud.","note":"exposée 与阴性名词 chambre 一致。"}},
 "Fulgurant(e)": {"pos":"adj. 形容词，阴性 fulgurante，复数 fulgurants / fulgurantes","s":"原指像闪电一样的；现在多指“来得极快、突飞猛进”的东西：une progression fulgurante（飞速进步）、un succès fulgurant。也可指突然袭来的剧痛：une douleur fulgurante。偏书面语。","ipa":"[fyl.ɡy.ʁɑ̃]","ph":"u 读 [y]（嘴圆如吹口哨）；g 在 u 前读 [ɡ]；-ant 读鼻化音 [ɑ̃]，t 不发音。阴性 fulgurante 读 [fyl.ɡy.ʁɑ̃t]，t 要发。","pi":"ful- 的 u 是 [y]，不是汉语的“乌”；结尾 -ant 不发 n 和 t；不要和 brillant（闪亮）混用，fulgurant 强调“快”。","et":"来自拉丁语 fulgur（闪电）和 fulgurare（闪电般发光）。","ex":[["Son succès a été fulgurant.","他的成功来得极快。"],["Elle a fait des progrès fulgurants en français.","她的法语进步神速。"],["Une douleur fulgurante lui a traversé le dos.","一阵剧痛窜过他的背。"]],"co":[["un succès fulgurant","迅速的成功"],["une progression fulgurante","飞速增长"],["une douleur fulgurante","剧烈的刺痛"],["une ascension fulgurante","火箭般的上升"]],"sy":[["foudroyant","soutenu","如雷击般的，更强调“致命、突然”"],["rapide","courant","快的，最普通的说法"],["éclair","courant","名词，“闪电式的”：une visite éclair（短暂拜访）"]],"fq":"中频，书面和新闻里常见。","me":"fulgur = 闪电：fulgurant 就是“快如闪电”。","tr":{"zh":"这家小公司的成功来得极快。","fr":"Le succès de cette petite entreprise a été fulgurant.","alt":"Cette petite entreprise a eu un succès fulgurant.","note":"fulgurant 修饰名词时放在名词后面；succès 是阳性，所以不加 e。"}},
 "Glauque": {"pos":"adj. 形容词，阴阳同形，复数 glauques","s":"本义是灰绿色（像浑浊的水）。口语里常指“阴森的、让人不舒服的、有点肮脏可疑的”：un quartier glauque（治安差的阴暗街区）、une ambiance glauque。","ipa":"[ɡlok]","ph":"gl 读 [ɡl]；au 读 [o]；-que 读 [k]，结尾 e 不发音。","pi":"au 是 [o]，不是“奥”；-que 读 [k]，不要读成 [kə]；阴阳同形，不加 e。","et":"来自拉丁语 glaucus，源自希腊语 glaukos（蓝绿色、灰蓝色）。“阴森”的比喻义是现代才有的。","ex":[["Ce film a une atmosphère un peu glauque.","这部电影氛围有点阴森。"],["Je n'aime pas ce bar, il est glauque.","我不喜欢这家酒吧，阴沉沉的。"],["L'eau du lac était glauque.","湖水是浑浊的灰绿色。"]],"co":[["une ambiance glauque","阴森的气氛"],["un quartier glauque","阴暗可疑的街区"],["une histoire glauque","令人不适的故事"],["un hôtel glauque","破旧阴暗的旅馆"]],"sy":[["sinistre","courant","阴森的，较正式"],["sordide","soutenu","肮脏、卑劣的，更重"],["lugubre","soutenu","凄凉的、像丧事的"]],"fq":"中频，口语很常用，带负面色彩。","me":"glauque 听起来像“grr…”，让人起鸡皮疙瘩：阴森。","tr":{"zh":"我不想去那家旅馆，太阴森了。","fr":"Je ne veux pas aller dans cet hôtel, il est trop glauque.","alt":"Cet hôtel est glauque, j'y vais pas.","note":"口语里否定常省略 ne：j'y vais pas。"}},
 "Grandissant(e)": {"pos":"adj. 形容词（grandir 的现在分词），阴性 grandissante，复数 grandissants / grandissantes","s":"日益增长的、越来越大的：un intérêt grandissant（越来越浓的兴趣）、une inquiétude grandissante。用来说抽象的东西逐步增加，不说人的身高。","ipa":"[ɡʁɑ̃.di.sɑ̃]","ph":"gr 读 [ɡʁ]；an 读 [ɑ̃]；ss 读 [s]；-ant 读 [ɑ̃]。阴性 grandissante 读 [ɡʁɑ̃.di.sɑ̃t]。","pi":"d 在 grand- 里要发音（grandir），但 grand 单独时 d 不发；-ant 的 n、t 不发；放在名词后面。","et":"来自 grandir，源于拉丁语 grandire（变大），和 grand（大）同源。-issant 是第二组动词（-ir）的现在分词词尾。","ex":[["Il y a un intérêt grandissant pour l'écologie.","人们对生态的兴趣越来越大。"],["Elle sent une inquiétude grandissante.","她感到越来越不安。"],["Le rôle grandissant d'Internet change nos habitudes.","互联网日益重要的作用改变了我们的习惯。"]],"co":[["un intérêt grandissant","日益增长的兴趣"],["une inquiétude grandissante","与日俱增的担忧"],["un nombre grandissant de…","越来越多的……"],["une popularité grandissante","日益走红"]],"sy":[["croissant","soutenu","不断增长的，更书面"],["de plus en plus grand","courant","越来越大，日常说法"],["montant","courant","上升的：une tension montante"]],"fq":"中频，新闻和书面常见。","me":"grand + -issant：正在“变大”的东西。","tr":{"zh":"越来越多的人对这个话题感兴趣。","fr":"Un nombre grandissant de personnes s'intéressent à ce sujet.","alt":"De plus en plus de gens s'intéressent à ce sujet.","note":"un nombre de personnes 后动词常用复数。"}},
 "Grossier / Grossière": {"pos":"adj. 形容词，阳性 grossier，阴性 grossière，复数 grossiers / grossières","s":"粗鲁的、没礼貌的（说话或举止）：un mot grossier（脏话）。也可指粗糙的、粗制的：un tissu grossier；或明显的错误：une erreur grossière（低级错误）。","ipa":"[ɡʁo.sje] / [ɡʁo.sjɛʁ]","ph":"gr 读 [ɡʁ]；o 读 [o]；ss 读 [s]；-ier 读 [je]；阴性 -ière 读 [jɛʁ]，r 要发。","pi":"阳性 -ier 的 r 不发音，阴性 -ière 的 r 要发音，别混；gros 的 s 不发，但 grossier 里的 ss 读 [s]；不要和 gros（胖的、大的）混淆。","et":"来自 gros（大的、粗的），源于晚期拉丁语 grossus，加后缀 -ier。","ex":[["Son comportement a été très grossier.","他的举止很粗鲁。"],["Ne dis pas de mots grossiers devant les enfants.","别在孩子面前说脏话。"],["C'est une erreur grossière.","这是个低级错误。"]],"co":[["un mot grossier","脏话"],["un personnage grossier","粗俗的人"],["une erreur grossière","明显的错误"],["être grossier avec quelqu'un","对某人无礼"]],"sy":[["impoli","courant","没礼貌的，较温和"],["vulgaire","courant","粗俗的，强调品味低"],["malpoli","familier","没规矩的，口语"]],"fq":"中高频，日常常用。","me":"gros + -ier：“粗大”的人，举止也粗。","tr":{"zh":"他对服务员很粗鲁。","fr":"Il a été très grossier avec le serveur.","alt":"Il a été super malpoli avec le serveur.","note":"être grossier avec / envers quelqu'un。"}},
 "Historique": {"pos":"adj. 形容词，阴阳同形，复数 historiques","s":"历史的；有历史意义的、历史上重要的：un moment historique（历史性时刻）。也指真实存在于历史中的：un fait historique（史实）。名词 un historique 指“事件经过、沿革”，如浏览记录 l'historique。","ipa":"[is.tɔ.ʁik]","ph":"h 不发音；his- 读 [is]；-que 读 [k]。","pi":"h 不发音，冠词要省音：l'historique（不是 le historique）；开头读 [is]，不是“嘿斯”。","et":"来自拉丁语 historicus，源于希腊语 historikos，和 histoire（历史、故事）同源。","ex":[["C'est un village historique.","这是一个有历史意义的村庄。"],["Ce match est un moment historique pour le club.","这场比赛对俱乐部来说是历史性的时刻。"],["Je consulte l'historique de mes achats.","我查看我的购买记录。"]],"co":[["un monument historique","历史古迹"],["un moment historique","历史性时刻"],["le centre historique","历史老城区"],["un roman historique","历史小说"]],"sy":[["ancien","courant","古老的，只说年代久"],["mémorable","courant","难忘的"],["marquant","courant","有重大影响的"]],"fq":"高频，日常和书面都常用。","me":"histoire → historique：“有 histoire 的”。","tr":{"zh":"我们参观了城市的历史老城区。","fr":"Nous avons visité le centre historique de la ville.","alt":"On a visité le vieux centre de la ville.","note":"historique 放在名词后面。"}},
 "Inabordable": {"pos":"adj. 形容词，阴阳同形，复数 inabordables","s":"（价格）贵得买不起的，常说房子、商品：des prix inabordables。也可指难以接近的人，或难以接触的话题，但这个意思较少用。","ipa":"[i.na.bɔʁ.dabl]","ph":"in- 读 [i.n]，这里是 i + na，不是鼻化音；abord 读 [a.bɔʁ]，-able 读 [dabl]（d 与后面的 able 连在一起）；结尾 le 不发音。","pi":"in- 后面是元音 a，不鼻化，读 [i.na]，不是 [ɛ̃]；-able 读 [abl]，结尾 le 不发音。","et":"in-（否定）+ abordable，来自 aborder（接近、靠岸），而 aborder 来自 à + bord（边、岸）。","ex":[["Les logements à Paris deviennent inabordables.","巴黎的住房变得负担不起。"],["Ces tomates sont inabordables en hiver.","这些番茄冬天贵得买不起。"],["Ce sujet est inabordable en famille.","这个话题在家里没法谈。"]],"co":[["des prix inabordables","买不起的价格"],["un loyer inabordable","付不起的房租"],["devenir inabordable","变得负担不起"],["un sujet inabordable","不能碰的话题"]],"sy":[["cher","courant","贵，最普通"],["hors de prix","courant","贵得离谱"],["abordable","courant","反义词：价格合理的"]],"fq":"中频，新闻里谈房价、物价时常见。","me":"in- + abordable：不能“靠岸”的价格，够不着。","tr":{"zh":"现在大城市的房租贵得付不起。","fr":"Aujourd'hui, les loyers sont inabordables dans les grandes villes.","alt":"De nos jours, les loyers sont hors de prix dans les grandes villes.","note":"inabordable 常和 devenir / être 连用。"}},
 "Inconscient(e)": {"pos":"adj. 形容词，阴性 inconsciente，复数 inconscients / inconscientes","s":"两个意思：1) 不顾后果的、莽撞的（人或行为）；2) 失去知觉的、昏迷的。还可指无意识的：un geste inconscient。名词 l'inconscient 是心理学的“潜意识”。","ipa":"[ɛ̃.kɔ̃.sjɑ̃]","ph":"in- 读 [ɛ̃]；con- 读 [kɔ̃]；sc 在 i 前读 [s]；-ient 读 [jɑ̃]。阴性 inconsciente 读 [ɛ̃.kɔ̃.sjɑ̃t]。","pi":"两个鼻化音 [ɛ̃] 和 [kɔ̃] 不要加 n；-ient 读 [jɑ̃]，不是 [jɛ̃]；注意拼写 sc。","et":"in-（否定）+ conscient，来自拉丁语 conscius（知道的）。","ex":[["J'étais jeune et inconscient.","我年轻又莽撞。"],["Il est resté inconscient pendant une heure.","他昏迷了一个小时。"],["Conduire sans ceinture, c'est inconscient !","不系安全带开车，太不顾后果了！"]],"co":[["être inconscient du danger","对危险毫无意识"],["rester inconscient","昏迷不醒"],["un geste inconscient","无意识的动作"],["l'inconscient","潜意识（名词）"]],"sy":[["irresponsable","courant","不负责任的"],["imprudent","courant","不谨慎的，较轻"],["évanoui","courant","晕倒的，只表示失去知觉"]],"fq":"中高频，日常常用。","me":"in + conscient：没有“意识”到后果。","tr":{"zh":"他太莽撞了，没意识到有危险。","fr":"Il est inconscient, il ne se rend pas compte du danger.","alt":"Il est complètement inconscient : il ne voit pas le danger.","note":"se rendre compte de + 名词 = 意识到。"}},
 "Inédit(e)": {"pos":"adj. 形容词，阴性 inédite，复数 inédits / inédites","s":"前所未有的、全新的，也指从未发表或出版过的：un texte inédit（未发表的文章）。说情况时 une situation inédite 表示“史无前例的”，不一定是好事。","ipa":"[i.ne.di]","ph":"in- 在 é 前读 [i.n]，不鼻化；é 读 [e]；结尾 t 不发音；阴性 inédite 读 [i.ne.dit]，t 要发。","pi":"不鼻化：[i.ne.di]；阳性结尾 -it 的 t 不发，阴性 inédite 才发 [dit]；é 别漏掉重音符号。","et":"来自拉丁语 ineditus（in- 否定 + editus，出版的），本义是“未出版的”。","ex":[["C'est une situation inédite.","这是前所未有的情况。"],["On a découvert un texte inédit de Proust.","人们发现了一篇普鲁斯特未发表的文章。"],["Ce chanteur propose un son inédit.","这位歌手推出了全新的声音。"]],"co":[["une situation inédite","史无前例的情况"],["un texte inédit","未发表的文本"],["une expérience inédite","全新的体验"],["un record inédit","前所未有的纪录"]],"sy":[["nouveau","courant","新的，最普通"],["sans précédent","soutenu","史无前例，较正式"],["original","courant","独特的"]],"fq":"中频，新闻和书面常见。","me":"in + édit（出版的）：没出版过 = 全新。","tr":{"zh":"疫情带来了一个前所未有的情况。","fr":"La pandémie a créé une situation inédite.","alt":"La pandémie nous a mis dans une situation inédite.","note":"inédit 放在名词后面。"}},
 "Innovant(e)": {"pos":"adj. 形容词（innover 的现在分词），阴性 innovante，复数 innovants / innovantes","s":"创新的、有创意的，多形容产品、公司、方法：une idée innovante。比 nouveau 更强调“有新意、领先”。","ipa":"[i.nɔ.vɑ̃]","ph":"in- 在元音前读 [i.n]；o 读开口 [ɔ]；v 读 [v]；-ant 读 [ɑ̃]。阴性 innovante 读 [i.nɔ.vɑ̃t]。","pi":"innov- 开头读 [i.nɔ]，不是鼻化；注意拼写双 n；结尾 -ant 不发 n、t。","et":"来自动词 innover，源于拉丁语 innovare（更新），in- + novus（新的）。","ex":[["Cette entreprise propose des produits innovants.","这家公司提供创新的产品。"],["C'est une méthode très innovante.","这是个很有创意的方法。"],["Il cherche des solutions innovantes.","他在寻找创新的解决办法。"]],"co":[["un produit innovant","创新产品"],["une idée innovante","创新的想法"],["une start-up innovante","创新型初创公司"],["une technologie innovante","创新技术"]],"sy":[["novateur","soutenu","开创性的，多形容人"],["original","courant","独特的"],["moderne","courant","现代的"]],"fq":"中频，工作、科技、广告里很常见。","me":"in + nov（新）+ -ant：带来“新”的东西。","tr":{"zh":"这家公司想找创新的方法。","fr":"Cette entreprise cherche des méthodes innovantes.","alt":"Cette boîte cherche des idées innovantes.","note":"形容词与名词性数配合：méthodes → innovantes。"}},
 "Interminable": {"pos":"adj. 形容词，阴阳同形，复数 interminables","s":"没完没了的、冗长的，多说时间长得让人厌烦：une attente interminable（漫长的等待）、une réunion interminable。","ipa":"[ɛ̃.tɛʁ.mi.nabl]","ph":"in- 读鼻化 [ɛ̃]；ter 读 [tɛʁ]；mi 读 [mi]；-nable 读 [nabl]，结尾 le 不发音。","pi":"这里 in- 要鼻化 [ɛ̃]（后面是辅音 t），和 inédit 不同；重音在最后一个音节 -nable；不要把 -able 读成英语 able。","et":"来自拉丁语 interminabilis，由 in-（否定）+ terminare（结束）而来，与 terminer（结束）同源。","ex":[["La réunion a été interminable.","会议没完没了。"],["Nous avons fait une queue interminable.","我们排了一条望不到头的队。"],["Le film était interminable.","这部电影长得没完。"]],"co":[["une attente interminable","漫长的等待"],["une queue interminable","长得没头的队伍"],["des discussions interminables","没完没了的讨论"],["un voyage interminable","漫长的旅程"]],"sy":[["très long","courant","很长，最简单"],["sans fin","courant","没有尽头的"],["éternel","familier","（夸张）永远的"]],"fq":"中频，日常抱怨时常用。","me":"in + terminer：一直不 terminé = 没完没了。","tr":{"zh":"我们在医院等了很久，等得没完没了。","fr":"Nous avons eu une attente interminable à l'hôpital.","alt":"À l'hôpital, l'attente était interminable.","note":"interminable 阴阳同形，不用加 e。"}},
 "Las": {"pos":"adj. 形容词，阴性 lasse，复数 las / lasses","s":"疲倦的、厌倦的，常指心里累，对某事腻了：être las de quelque chose（对某事厌烦）。偏书面，日常多说 fatigué 或 en avoir marre。","ipa":"[la]","ph":"阳性 las 读 [la]，s 不发音；阴性 lasse 读 [las]，ss 读 [s]。","pi":"阳性的 s 不发音，阴性才发；常用 las de + 名词/动词原形；不要和 la（阴性定冠词）搞混，意思完全不同。","et":"来自拉丁语 lassus（疲倦的）。感叹词 hélas（唉）里也有这个词：hé + las，原意“可怜的我”。","ex":[["Je suis las de mon travail.","我对工作厌倦了。"],["Elle est lasse de répéter la même chose.","她厌倦了老是重复同样的话。"],["Il a dit non, d'un air las.","他一脸倦意地说了不。"]],"co":[["être las de","对……厌倦"],["d'un air las","带着倦意地"],["un regard las","疲惫的眼神"],["las de tout","对一切都厌倦"]],"sy":[["fatigué","courant","累的，最常用，多指身体"],["épuisé","courant","筋疲力尽"],["blasé","soutenu","看腻了、麻木的"]],"fq":"中低频，书面和文学里多见。","me":"las 听起来像“啦”：累得说不动，只剩“啦”。","tr":{"zh":"我对等待厌倦了。","fr":"Je suis las d'attendre.","alt":"J'en ai marre d'attendre.","note":"las de + 动词原形；口语换成 en avoir marre de。"}},
 "Métallique": {"pos":"adj. 形容词，阴阳同形，复数 métalliques","s":"金属的、金属制的，也指像金属的（声音、颜色、味道）：un bruit métallique（金属撞击声）、une couleur métallique。","ipa":"[me.ta.lik]","ph":"mé 读 [me]；ta 读 [ta]；ll 读 [l]；-que 读 [k]。","pi":"ll 只读一个 [l]（不是 [j]）；注意 é 的重音符号；-ique 结尾 e 不发音；重音在最后 -lique。","et":"来自 métal（金属）加后缀 -ique。métal 来自拉丁语 metallum，源于希腊语 metallon（矿）。","ex":[["J'ai entendu un bruit métallique.","我听到金属的声音。"],["Le toit est en structure métallique.","屋顶是金属结构。"],["Ce vin a un goût métallique.","这酒有一股金属味。"]],"co":[["un bruit métallique","金属声"],["une structure métallique","金属结构"],["un goût métallique","金属味"],["gris métallique","金属灰"]],"sy":[["en métal","courant","金属制的，说材料"],["en fer","courant","铁制的"],["acier","courant","名词，钢"]],"fq":"中频，日常和技术都常用。","me":"métal + -ique：和金属有关的。","tr":{"zh":"我听到一阵金属声，是从车库传来的。","fr":"J'ai entendu un bruit métallique venant du garage.","alt":"J'ai entendu un bruit de métal dans le garage.","note":"venant de = 来自（现在分词）。"}},
 "Motorisé(e)": {"pos":"adj. 形容词（motoriser 的过去分词），阴性 motorisée，复数 motorisés / motorisées","s":"有发动机的、机动的：un véhicule motorisé（机动车）。口语里 être motorisé 还可指“有车、有交通工具”。","ipa":"[mɔ.tɔ.ʁi.ze]","ph":"两个 o 都读开口 [ɔ]；r 读 [ʁ]；s 在元音间读 [z]；-é 读 [e]。","pi":"s 在两个元音之间读 [z]，不是 [s]；开头 mo- 是 [mɔ]，不是 [mo]；阴性 motorisée 末尾 e 不发音，读音与阳性一样。","et":"来自 moteur（发动机），拉丁语 motor（推动者）；动词 motoriser，加后缀 -iser。","ex":[["L'accès est interdit aux véhicules motorisés.","机动车禁止通行。"],["Tu es motorisé ce week-end ?","这个周末你有车吗？"],["Nous préférons les transports non motorisés.","我们更喜欢非机动交通。"]],"co":[["un véhicule motorisé","机动车"],["non motorisé","非机动的"],["être motorisé","有车（口语）"],["un engin motorisé","机动设备"]],"sy":[["à moteur","courant","带发动机的：un bateau à moteur"],["automobile","courant","汽车的"],["mécanique","courant","机械的"]],"fq":"中频，路牌、通告里常见。","me":"motor（发动机）+ -isé：被装上“马达”的。","tr":{"zh":"公园里禁止机动车。","fr":"Les véhicules motorisés sont interdits dans le parc.","alt":"On n'a pas le droit de rouler en véhicule motorisé dans le parc.","note":"être interdit à / dans：禁止。"}},
 "Nocturne": {"pos":"adj. 形容词，阴阳同形，复数 nocturnes","s":"夜间的；夜行的（动物）：un animal nocturne。也指夜间举办的：une nocturne（名词，如博物馆晚间延长开放）。","ipa":"[nɔk.tyʁn]","ph":"no 读开口 [nɔ]；c 读 [k]；u 读 [y]；rn 读 [ʁn]；结尾 e 不发音。","pi":"u 是 [y]，嘴圆；ct 要两个都发 [kt]；结尾只有一个音节 [tyʁn]，不要读成 [ty.ʁə.nə]。","et":"来自拉丁语 nocturnus，源于 nox, noctis（夜）。同源：nuit（夜）。","ex":[["C'est un animal nocturne.","这是夜行动物。"],["Le musée ouvre en nocturne le jeudi.","博物馆星期四有夜间开放。"],["Le hibou est un oiseau nocturne.","猫头鹰是夜行的鸟。"]],"co":[["un animal nocturne","夜行动物"],["la vie nocturne","夜生活"],["en nocturne","晚间开放（场次）"],["un match nocturne","夜场比赛"]],"sy":[["de nuit","courant","夜里的，日常说法"],["diurne","soutenu","反义词：昼行的"],["noctambule","soutenu","夜猫子（名词）"]],"fq":"中频，科普、旅游里常见。","me":"nocturne ← nox（夜）：像 nuit（夜）。","tr":{"zh":"猫头鹰是夜行动物。","fr":"Le hibou est un animal nocturne.","alt":"Le hibou vit la nuit : c'est un animal nocturne.","note":"nocturne 阴阳同形。"}},
 "Ombragé(e)": {"pos":"adj. 形容词（ombrager 的过去分词），阴性 ombragée，复数 ombragés / ombragées","s":"有树荫的、阴凉的：un jardin ombragé、une terrasse ombragée。强调有树或遮阳物挡住阳光。","ipa":"[ɔ̃.bʁa.ʒe]","ph":"om 读鼻化 [ɔ̃]，b 单独发；a 读 [a]；g 在 é 前读 [ʒ]；-é 读 [e]。","pi":"om 是鼻化音 [ɔ̃]，后面接 b，要发 b；g 读 [ʒ] 不是 [ɡ]；阳性阴性读音相同。","et":"来自动词 ombrager，源于 ombre（阴影），拉丁语 umbra（影子）。","ex":[["Nous avons trouvé un coin ombragé pour pique-niquer.","我们找到一处阴凉的地方野餐。"],["Le jardin est bien ombragé en été.","夏天花园里很阴凉。"],["Je préfère une terrasse ombragée.","我更喜欢有遮阳的露台。"]],"co":[["un coin ombragé","阴凉处"],["une terrasse ombragée","有遮阳的露台"],["un jardin ombragé","树荫浓密的花园"],["bien ombragé","树荫很好"]],"sy":[["à l'ombre","courant","在阴凉处，副词短语"],["frais","courant","凉爽的"],["ensoleillé","courant","反义词：阳光充足的"]],"fq":"中低频，旅游和房屋描述中常见。","me":"ombre（影子）→ ombragé：被影子盖住的。","tr":{"zh":"我们想在阴凉的地方吃午饭。","fr":"Nous voulons déjeuner dans un endroit ombragé.","alt":"On veut manger à l'ombre, dans un coin ombragé.","note":"endroit 是阳性，所以 ombragé 不加 e。"}},
 "Ouvert(e) d'esprit": {"pos":"loc. adj. 形容词短语，阴性 ouverte d'esprit，复数 ouverts / ouvertes d'esprit","s":"思想开明的、心胸开阔的，愿意接受不同的想法。只有 ouvert(e) 变性数，d'esprit 不变：Elle est ouverte d'esprit。","ipa":"[u.vɛʁ.dɛs.pʁi]","ph":"ouvert 读 [u.vɛʁ]，t 不发；阴性 ouverte 读 [u.vɛʁt]；d'esprit 读 [dɛs.pʁi]，t 不发。","pi":"ouvert 的 t 在阳性不发、阴性要发；esprit 末尾 t 不发；d'esprit 里的 d' 是省音，不是 des。","et":"ouvert 是 ouvrir（打开）的过去分词，esprit 来自拉丁语 spiritus（气息、精神）。字面是“思想是打开的”。","ex":[["Il est très ouvert d'esprit et tolérant.","他思想开放而且宽容。"],["Mes parents sont ouverts d'esprit.","我父母思想很开明。"],["Il faut être ouvert d'esprit pour voyager.","旅行需要有开阔的心胸。"]],"co":[["être ouvert d'esprit","思想开明"],["avoir l'esprit ouvert","头脑开放"],["tolérant","宽容的（常与之连用）"],["fermé d'esprit","思想封闭的（反义）"]],"sy":[["tolérant","courant","宽容的，侧重容忍别人"],["libéral","soutenu","开放的，但也有政治含义"],["borné","courant","反义：狭隘的、死脑筋的"]],"fq":"中频，描述性格时常用。","me":"ouvert + esprit：头脑像一扇打开的门。","tr":{"zh":"我的老师思想很开明。","fr":"Mon professeur est très ouvert d'esprit.","alt":"Mon prof a vraiment l'esprit ouvert.","note":"professeur 是阳性所以用 ouvert；若是女老师则用 ouverte d'esprit。"}},
 "Paradoxal(e)": {"pos":"adj. 形容词，阴性 paradoxale，复数 paradoxaux / paradoxales（阳性复数 -aux）","s":"矛盾的、似是而非的，指表面上自相矛盾却可能是真的：un effet paradoxal。常用句型 Il est paradoxal de + 动词原形。","ipa":"[pa.ʁa.dɔk.sal]","ph":"pa-ra-do-xal：x 在这里读 [ks]；o 读开口 [ɔ]；-al 读 [al]，l 要发。","pi":"x 读 [ks]，不是 [z]；阳性复数是 paradoxaux [pa.ʁa.dɔk.so]，不是 paradoxals；l 要发音。","et":"来自 paradoxe，源于希腊语 paradoxos（para 反对 + doxa 意见），即“违反常识的”。","ex":[["C'est paradoxal de vouloir maigrir en mangeant des bonbons.","想吃糖减肥是矛盾的。"],["Son comportement est paradoxal.","他的行为很矛盾。"],["Un effet paradoxal est apparu.","出现了一个反常的效果。"]],"co":[["un effet paradoxal","反常的效果"],["il est paradoxal de…","……很矛盾"],["une situation paradoxale","矛盾的处境"],["un comportement paradoxal","自相矛盾的行为"]],"sy":[["contradictoire","courant","互相矛盾的，较中性"],["absurde","courant","荒谬的，带批评"],["illogique","courant","不合逻辑的"]],"fq":"中频，书面、讨论中常见。","me":"para（反）+ doxa（意见）：和常识相反。","tr":{"zh":"一边抽烟一边想保持健康，很矛盾。","fr":"Il est paradoxal de vouloir rester en bonne santé en fumant.","alt":"C'est paradoxal : il veut rester en forme mais il fume.","note":"Il est paradoxal de + 动词原形。"}},
 "Prématuré(e)": {"pos":"adj. 形容词，阴性 prématurée，复数 prématurés / prématurées","s":"过早的、提前的：une mort prématurée（早逝）、un bébé prématuré（早产儿）。也说草率提前做的决定：une décision prématurée。","ipa":"[pʁe.ma.ty.ʁe]","ph":"pré 读 [pʁe]；ma 读 [ma]；tu 读 [ty]，u 是 [y]；ré 读 [e]。","pi":"u 是 [y]，嘴圆；两个 é 都读 [e]，注意重音符号；阴性 prématurée 读音不变。","et":"来自拉丁语 praematurus（prae 之前 + maturus 成熟的），与 mûr（成熟的）同源。","ex":[["La pollution de l'air cause des décès prématurés.","空气污染导致过早死亡。"],["Leur bébé est prématuré.","他们的宝宝是早产儿。"],["Il est prématuré de conclure.","现在下结论还为时过早。"]],"co":[["un décès prématuré","过早去世"],["un bébé prématuré","早产儿"],["il est prématuré de…","现在……为时过早"],["une décision prématurée","草率的决定"]],"sy":[["précoce","courant","早熟的、早发的"],["hâtif","soutenu","仓促的"],["tardif","courant","反义：晚的"]],"fq":"中频，新闻和日常都常见。","me":"pré + mature：在“成熟”之前。","tr":{"zh":"现在下结论还为时过早。","fr":"Il est prématuré de tirer des conclusions.","alt":"C'est trop tôt pour conclure.","note":"tirer des conclusions = 得出结论。"}},
 "Rafraîchissant(e)": {"pos":"adj. 形容词（rafraîchir 的现在分词），阴性 rafraîchissante，复数 rafraîchissants / rafraîchissantes","s":"清爽的、使人凉快的：une boisson rafraîchissante。也可比喻让人耳目一新：une idée rafraîchissante。","ipa":"[ʁa.fʁɛ.ʃi.sɑ̃]","ph":"ra 读 [ʁa]；fraî 读 [fʁɛ]；ch 读 [ʃ]；-issant 读 [i.sɑ̃]。î 上的帽子不改变读音。","pi":"ch 读 [ʃ]，不是 [k]；î 读 [ɛ]；-ant 不发 n、t；这个词长，拆成 ra-fraî-chis-sant 记。","et":"来自 rafraîchir：re- + a- + frais（凉的，来自法兰克语 frisc）。","ex":[["Cette boisson est très rafraîchissante.","这种饮料很清爽。"],["Une douche froide, c'est rafraîchissant.","冲个冷水澡很清爽。"],["Son humour est rafraîchissant.","他的幽默让人耳目一新。"]],"co":[["une boisson rafraîchissante","清凉饮料"],["un goût rafraîchissant","清爽的味道"],["une brise rafraîchissante","凉爽的微风"],["rafraîchissant(e) pour l'esprit","让人耳目一新"]],"sy":[["frais","courant","凉的、新鲜的"],["désaltérant","soutenu","解渴的"],["revigorant","soutenu","令人振奋的"]],"fq":"中频，饮料、天气、广告中常见。","me":"frais（凉）+ 前后缀：让东西重新变 frais。","tr":{"zh":"夏天喝冰茶很清爽。","fr":"En été, le thé glacé est très rafraîchissant.","alt":"L'été, un thé glacé, c'est rafraîchissant.","note":"thé glacé = 冰茶。"}},
 "Réticent(e)": {"pos":"adj. 形容词，阴性 réticente，复数 réticents / réticentes","s":"不情愿的、有保留的、犹豫的：être réticent à + 动词原形（对做某事不太情愿）。语气比 refuser 轻，只是不愿意或不确定。","ipa":"[ʁe.ti.sɑ̃]","ph":"ré 读 [ʁe]；ti 在这里读 [ti]；c 在 e 前读 [s]；-ent 读 [ɑ̃]。阴性 réticente 读 [ʁe.ti.sɑ̃t]。","pi":"ti 读 [ti]，不是 [si]；c 读 [s]；-ent 在形容词里读鼻化 [ɑ̃]，t 不发；要用 réticent à + 动词，介词是 à，不是 de。","et":"来自拉丁语 reticens（reticere 保持沉默），原意“沉默、不说出来”，所以引申为有保留。","ex":[["Il est réticent à l'idée de changer de travail.","他不愿意换工作。"],["Elle reste réticente face à ce projet.","她对这个项目仍有保留。"],["Je suis un peu réticent à y aller seul.","我有点不愿意一个人去。"]],"co":[["être réticent à + inf.","不愿意做……"],["réticent à l'idée de…","对……这个想法有顾虑"],["se montrer réticent","表现得不情愿"],["un peu réticent","有点犹豫"]],"sy":[["hésitant","courant","犹豫的"],["réservé","courant","有保留的"],["opposé","courant","反对的，更强"]],"fq":"中频，书面和工作场合常见。","me":"réticent ≈ 把想法“压在心里”，不太想说也不太想做。","tr":{"zh":"他不太愿意参加这次旅行。","fr":"Il est réticent à participer à ce voyage.","alt":"Il n'a pas trop envie de venir à ce voyage.","note":"réticent à + 动词原形（介词是 à）。"}},
 "Rural(e)": {"pos":"adj. 形容词，阴性 rurale，复数 ruraux / rurales（阳性复数 -aux）","s":"乡村的、农村的：le milieu rural、l'exode rural（人口外流到城市）。和 urbain（城市的）相对。","ipa":"[ʁy.ʁal]","ph":"两个 r 都读 [ʁ]；u 读 [y]；-al 读 [al]，l 要发。","pi":"u 是 [y]，嘴圆；两个 r 连续，要发清楚；阳性复数是 ruraux [ʁy.ʁo]，不是 rurals。","et":"来自拉丁语 ruralis，源于 rus, ruris（乡间）。英语 rural 同源。","ex":[["J'aime le calme du milieu rural.","我喜欢乡村的宁静。"],["Elle habite dans une commune rurale.","她住在一个乡村镇。"],["Les écoles rurales ferment.","乡村学校正在关闭。"]],"co":[["le milieu rural","农村环境"],["l'exode rural","农村人口外流"],["une zone rurale","农村地区"],["le monde rural","农村世界"]],"sy":[["campagnard","courant","乡下的，带生活气息"],["agricole","courant","农业的"],["urbain","courant","反义：城市的"]],"fq":"中频，新闻和社会话题常见。","me":"rural ← rus（乡间）：和英语 rural 一样。","tr":{"zh":"我更喜欢住在乡村。","fr":"Je préfère vivre en milieu rural.","alt":"Moi, je préfère vivre à la campagne.","note":"milieu rural 前用 en。"}},
 "Souterrain(e)": {"pos":"adj. 形容词，阴性 souterraine，复数 souterrains / souterraines；也作阳性名词 un souterrain（地下通道）","s":"地下的：un passage souterrain、un parking souterrain。名词 un souterrain 指古堡、城堡里的地下通道。","ipa":"[su.tɛ.ʁɛ̃]","ph":"sou 读 [su]；ter 读 [tɛ]；-rain 读 [ʁɛ̃]。阴性 souterraine 读 [su.tɛ.ʁɛn]，n 要发。","pi":"ter 读 [tɛ]，r 在后一个音节；-ain 读鼻化 [ɛ̃]，不是“ain”；阴性 -aine 的 n 要发。","et":"来自 sous（下）+ terre（地）+ -ain，字面是“在地下的”。","ex":[["Ils ont découvert un passage souterrain.","他们发现了一条地下通道。"],["Je gare ma voiture dans le parking souterrain.","我把车停在地下停车场。"],["Une rivière souterraine passe ici.","这里有一条地下河。"]],"co":[["un passage souterrain","地下通道"],["un parking souterrain","地下停车场"],["une rivière souterraine","地下河"],["le métro souterrain","地下铁"]],"sy":[["enterré","courant","被埋的"],["en sous-sol","courant","在地下室"],["aérien","soutenu","反义：架空的、空中的"]],"fq":"中频，城市和旅游中常见。","me":"sous + terre：在地的下面。","tr":{"zh":"你可以把车停在地下停车场。","fr":"Tu peux garer ta voiture dans le parking souterrain.","alt":"Tu peux te garer au parking souterrain.","note":"garer sa voiture = 停车；se garer = 把车停好。"}},
 "Sublime": {"pos":"adj. 形容词，阴阳同形，复数 sublimes","s":"绝美的、极其崇高的，用于风景、人物、艺术：un paysage sublime。比 beau 强很多，是夸奖的最高级之一。","ipa":"[sy.blim]","ph":"su 读 [sy]，u 是 [y]；blime 读 [blim]，结尾 e 不发音。","pi":"u 是 [y]，嘴圆，不是“苏”；-ime 读 [im]，不是 [aim]；重音在最后一个音节。","et":"来自拉丁语 sublimis（高耸的、崇高的）。","ex":[["Le paysage est sublime.","风景绝美。"],["Elle a une voix sublime.","她的嗓音美极了。"],["Cette robe est sublime !","这条裙子美极了！"]],"co":[["un paysage sublime","绝美的风景"],["une vue sublime","绝美的景色"],["du sublime au ridicule","从崇高到可笑"],["sublime de beauté","美得令人赞叹"]],"sy":[["magnifique","courant","很美，最常用"],["splendide","courant","壮丽的"],["superbe","courant","极好的"]],"fq":"中频，赞美时常用。","me":"sub（下）+ lime：从下往上“高耸”的美。","tr":{"zh":"从这里看，风景绝美。","fr":"D'ici, la vue est sublime.","alt":"La vue d'ici, elle est magnifique.","note":"sublime 阴阳同形。"}},
 "Successif / Successive": {"pos":"adj. 形容词，阳性 successif，阴性 successive，复数 successifs / successives","s":"连续的、相继的：trois victoires successives（连赢三场）。常放在数词后，也表示“一个接一个的”：les gouvernements successifs（历届政府）。","ipa":"[syk.sɛ.sif] / [syk.sɛ.siv]","ph":"cc 在 e 前读 [ks]；ss 读 [s]；阳性 -if 读 [if]；阴性 -ive 读 [iv]。","pi":"cc 读 [ks]，不是 [k]；阳性 f、阴性 v，注意区分（-if / -ive）；u 读 [y]。","et":"来自拉丁语 successivus，源于 succedere（接着来）。同源：succéder, succès。","ex":[["Il a remporté trois victoires successives.","他连续赢得三场胜利。"],["Les gouvernements successifs ont échoué.","历届政府都失败了。"],["Il a eu plusieurs emplois successifs.","他先后做过几份工作。"]],"co":[["trois jours successifs","连续三天"],["des victoires successives","连胜"],["les gouvernements successifs","历届政府"],["des étapes successives","接连的阶段"]],"sy":[["consécutif","courant","连续的，最常用于时间"],["de suite","courant","连着：trois jours de suite"],["suivant","courant","后面的"]],"fq":"中频，书面和新闻常见。","me":"succéder → successif：一个接一个。","tr":{"zh":"我们连续三天下雨。","fr":"Il a plu trois jours successifs.","alt":"Il a plu trois jours de suite.","note":"口语更常说 trois jours de suite 或 consécutifs。"}},
 "Symétrique": {"pos":"adj. 形容词，阴阳同形，复数 symétriques","s":"对称的：un dessin symétrique。名词 la symétrie 指对称。也可指双方互相对应的：une relation symétrique。","ipa":"[si.me.tʁik]","ph":"sy 读 [si]（y 在这里读 [i]）；mé 读 [me]；tri 读 [tʁi]；-que 读 [k]。","pi":"y 读 [i]，不是 [y]；sy- 开头读 [si]；-que 读 [k]，不是 [kə]。","et":"来自希腊语 symmetria（syn 一起 + metron 测量），“有共同尺度的”。","ex":[["Le visage humain n'est pas parfaitement symétrique.","人的脸并不完全对称。"],["Dessine une figure symétrique.","画一个对称的图形。"],["Les deux ailes du bâtiment sont symétriques.","建筑的两翼是对称的。"]],"co":[["parfaitement symétrique","完全对称"],["une figure symétrique","对称图形"],["l'axe de symétrie","对称轴"],["symétrique par rapport à…","相对于……对称"]],"sy":[["équilibré","courant","均衡的"],["régulier","courant","规则的"],["asymétrique","courant","反义：不对称的"]],"fq":"中频，数学、设计里常见。","me":"sy + mètre：两边“量起来一样”。","tr":{"zh":"这座楼的两边是对称的。","fr":"Les deux côtés du bâtiment sont symétriques.","alt":"Le bâtiment est symétrique des deux côtés.","note":"symétrique par rapport à… = 相对于……对称。"}},
 "Urbain(e)": {"pos":"adj. 形容词，阴性 urbaine，复数 urbains / urbaines","s":"城市的、都市的：la vie urbaine、le paysage urbain。与 rural（乡村的）相对。也有人名 Urbain，不要混。","ipa":"[yʁ.bɛ̃]","ph":"ur 读 [yʁ]；-bain 读 [bɛ̃]。阴性 urbaine 读 [yʁ.bɛn]，n 要发。","pi":"开头 u 是 [y]，嘴圆；-ain 读鼻化 [ɛ̃]；阴性 -aine 读 [ɛn]，不鼻化；不要和英语 urban 的读音混。","et":"来自拉丁语 urbanus，源于 urbs（城市）。","ex":[["Le paysage urbain évolue rapidement.","城市风貌变化很快。"],["Elle préfère la vie urbaine.","她更喜欢城市生活。"],["La zone urbaine s'agrandit.","市区在扩大。"]],"co":[["le paysage urbain","城市景观"],["la vie urbaine","城市生活"],["une zone urbaine","市区"],["l'espace urbain","城市空间"]],"sy":[["citadin","courant","城里的，也指城里人"],["de la ville","courant","城市的，口语说法"],["rural","courant","反义：乡村的"]],"fq":"中频，社会、新闻常见。","me":"urbain ← urbs：英语 urban 的法语形式。","tr":{"zh":"我更喜欢城市生活。","fr":"Je préfère la vie urbaine.","alt":"Moi, j'aime mieux la vie en ville.","note":"préférer + 定冠词 + 名词。"}},
 "Hype": {"pos":"adj. 形容词，阴阳同形，不变（复数 hypes，少见）；也可作名词 le hype","s":"（来自英语）很潮的、时髦的、很受追捧的：un bar hype。用于地方、人、风格。口语，带点“网络用语”感。","ipa":"[ajp]","ph":"按英语读：h 不发，读 [ajp]；结尾 p 要发。","pi":"按英语发音 [ajp]，不要读成 [hip]；h 不发；是借词，没有特别的阴性形式。","et":"英语借词 hype，常被认为是 hyperbole（夸张）的缩略，“炒作”。法语借用后意义偏向“很潮”。","ex":[["C'est un quartier hype.","这是个很潮的街区。"],["Ce café est devenu très hype.","这家咖啡馆变得很潮。"],["Elle a toujours des vêtements hype.","她总穿时髦的衣服。"]],"co":[["un endroit hype","潮的地方"],["un resto hype","网红餐厅"],["être hype","很潮"],["un look hype","时髦造型"]],"sy":[["branché","familier","时髦的，较早的说法"],["tendance","courant","流行的，最普通"],["à la mode","courant","时髦的"]],"fq":"中频，年轻人口语中常见。","me":"hype = 潮，一听就是英语。","tr":{"zh":"这家餐厅现在很潮。","fr":"Ce restaurant est très hype en ce moment.","alt":"Ce resto est super hype en ce moment.","note":"hype 不变，不加 e 也不加 s。"}},
 "Autrefois": {"pos":"adv. 副词","s":"从前、过去（和现在不一样的时候）。常和 imparfait（未完成过去时）连用，描述过去的习惯或状态：Autrefois, on écrivait des lettres。","ipa":"[o.tʁə.fwa]","ph":"au 读 [o]；tre 中的 e 读弱音 [ə]（快读时常省略）；fois 读 [fwa]，ois 读 [wa]。","pi":"au 是 [o]；fois 的 s 不发，读 [fwa]，注意和 foie（肝）同音；不要和 autre fois（另一次）混淆，autrefois 是一个词。","et":"autre（别的）+ fois（次）：字面是“另一次”，指和现在不同的时候。","ex":[["Autrefois, les gens n'avaient pas de téléphone portable.","从前人们没有手机。"],["Autrefois, il habitait à Lyon.","从前他住在里昂。"],["Ce café était autrefois une banque.","这家咖啡馆从前是一家银行。"]],"co":[["autrefois, on…","从前，人们……"],["comme autrefois","和以前一样"],["les gens d'autrefois","过去的人"],["le temps d'autrefois","往昔"]],"sy":[["jadis","littéraire","往昔，书面"],["avant","courant","以前，日常"],["naguère","littéraire","不久前（书面）"]],"fq":"中高频，讲过去时常用。","me":"autre + fois = “另一个时候”，也就是从前。","tr":{"zh":"从前这里有一个小村子。","fr":"Autrefois, il y avait un petit village ici.","alt":"Avant, il y avait un petit village ici.","note":"描述过去常用 imparfait：il y avait。"}},
 "D'ailleurs": {"pos":"adv. 副词短语（d' + ailleurs）","s":"1) 顺便说、说起来：补充一个相关的信息；2) 再说、况且：加强前面的论点。语气自然，常放在句首。","ipa":"[da.jœʁ]","ph":"d'ail 读 [da.j]，ill 读 [j]；-eurs 读 [œʁ]，s 不发。","pi":"ailleurs 里 ill 读 [j]，整体 [a.jœʁ]；结尾 -eurs 的 s 不发；d'ailleurs 的 d' 是省音，不是 de ailleurs。","et":"d'（de）+ ailleurs（别处），字面是“从别处来的”，引申为“另外、此外”。ailleurs 源于拉丁语 aliorsum。","ex":[["J'ai entendu parler d'un nouveau restaurant. D'ailleurs, il est midi ! Tu veux aller manger ?","我听说有家新餐厅。顺便说，已经中午了！要去吃饭吗？"],["Il est sympa. D'ailleurs, je le connais bien.","他很友好。说起来，我很了解他。"],["Je n'ai pas faim. D'ailleurs, je viens de manger.","我不饿。再说，我刚吃过。"]],"co":[["et d'ailleurs…","再说……"],["d'ailleurs, …","顺便说一句，……"],["il est d'ailleurs vrai que…","此外确实……"],["d'ailleurs je t'avais dit","我早就跟你说过"]],"sy":[["à propos","courant","对了、顺便"],["en outre","soutenu","此外，较正式"],["de plus","courant","再说、而且"]],"fq":"极高频，口语和书面都很常用。","me":"d' + ailleurs：“从别处”再补一句。","tr":{"zh":"我不去，再说我也没时间。","fr":"Je n'y vais pas, et d'ailleurs, je n'ai pas le temps.","alt":"J'y vais pas, d'ailleurs j'ai pas le temps.","note":"d'ailleurs 常放在句首或补充句中。"}},
 "Durablement": {"pos":"adv. 副词（由 durable + -ment 构成）","s":"持久地、长期地；在环保语境中也可译为“可持续地”：consommer durablement。","ipa":"[dy.ʁa.blə.mɑ̃]","ph":"du 读 [dy]，u 是 [y]；ra 读 [ʁa]；-blement 读 [blə.mɑ̃]；结尾 -ment 读 [mɑ̃]，t 不发。","pi":"u 是 [y]；-ment 读鼻化 [mɑ̃]，t 不发；durable 中的 e 在 durablement 里读弱音 [ə]，快读常省略。","et":"durable + -ment（副词后缀）。durable 来自拉丁语 durabilis，源于 durare（持续）。","ex":[["Il faut régler ce problème durablement.","必须持久地解决这个问题。"],["Cette décision change durablement notre vie.","这个决定长久地改变了我们的生活。"],["Il veut s'installer durablement à Lyon.","他想长期定居在里昂。"]],"co":[["régler durablement","持久地解决"],["s'installer durablement","长期定居"],["durablement affecté","受到长久影响"],["agir durablement","做出长远的行动"]],"sy":[["longtemps","courant","很久，日常"],["de façon durable","courant","以持久的方式"],["pour longtemps","courant","长久地"]],"fq":"中频，新闻、环保话题中常见。","me":"durable + ment：像 dur（持续）的东西。","tr":{"zh":"我们要持久地解决这个问题。","fr":"Nous voulons résoudre ce problème durablement.","alt":"On veut régler ce problème pour de bon.","note":"副词放在动词或宾语后面。"}},
 "Progressivement": {"pos":"adv. 副词（由 progressif + -ment 构成）","s":"逐步地、渐渐地：La situation s'améliore progressivement。强调一步一步，有过程。","ipa":"[pʁɔ.ɡʁɛ.si.və.mɑ̃]","ph":"pro 读 [pʁɔ]；gre 读 [ɡʁɛ]；ssi 读 [si]；ve 读 [və]；-ment 读 [mɑ̃]。","pi":"ss 读 [s]；gr 读 [ɡʁ]；-ment 读鼻化 [mɑ̃]，t 不发；词很长，慢慢拆成音节读。","et":"来自 progressif 加 -ment。progressif 源于拉丁语 progredi（向前走），同源：progrès。","ex":[["La situation s'améliore progressivement.","情况在逐渐改善。"],["Il faut augmenter la dose progressivement.","剂量要逐步增加。"],["Elle reprend le sport progressivement.","她在逐步恢复运动。"]],"co":[["augmenter progressivement","逐步增加"],["reprendre progressivement","逐步恢复"],["s'habituer progressivement","慢慢习惯"],["progressivement, …","渐渐地，……"]],"sy":[["peu à peu","courant","一点一点，日常"],["petit à petit","courant","渐渐地"],["graduellement","soutenu","按等级逐步"]],"fq":"中高频，日常和书面都常用。","me":"progrès + -ment：一步一步向前。","tr":{"zh":"孩子们逐渐习惯了新学校。","fr":"Les enfants s'habituent progressivement à leur nouvelle école.","alt":"Les enfants s'habituent petit à petit à leur nouvelle école.","note":"s'habituer à + 名词。"}},
 "Sans quoi": {"pos":"loc. conj. 连词短语，不变","s":"否则、不然：前面是建议、命令或条件，后面说不照做的后果。比 sinon 稍正式。","ipa":"[sɑ̃.kwa]","ph":"sans 读 [sɑ̃]，s 不发；quoi 读 [kwa]，qu 读 [k]，oi 读 [wa]。","pi":"sans 的 s 不发（但后接元音时可连读）；quoi 读 [kwa]，不是 [kwɔ]；quoi 指前面所说的事。","et":"sans（没有）+ quoi（什么，指代前面的事）：字面是“没有这个的话”。","ex":[["Dépêche-toi, sans quoi nous allons rater le train.","快点，否则我们会错过火车。"],["Il faut payer avant lundi, sans quoi il y aura une pénalité.","要在星期一前付款，否则会有罚款。"],["Prends ton parapluie, sans quoi tu seras mouillé.","带上伞，不然你会淋湿。"]],"co":[["sans quoi + 后果","否则会……"],["fais-le, sans quoi…","你得做，不然……"],["sans quoi on risque de…","否则就有可能……"],["sans quoi… (sinon)","要不然……"]],"sy":[["sinon","courant","否则，最日常"],["faute de quoi","soutenu","否则，更正式"],["autrement","courant","不然"]],"fq":"中频，书面和口语都用。","me":"sans quoi = “没有这件事的话”。","tr":{"zh":"快点，不然我们会迟到。","fr":"Dépêche-toi, sans quoi nous serons en retard.","alt":"Dépêche-toi, sinon on sera en retard.","note":"sans quoi 后接将来或条件的后果。"}},
 "À l'encontre de": {"pos":"loc. prép. 介词短语，不变","s":"与……相悖、违背：Cela va à l'encontre de nos principes。固定搭配 aller à l'encontre de，也可用 à l'encontre de + 名词表示“针对”。偏书面。","ipa":"[a.lɑ̃.kɔ̃.tʁə.də]","ph":"à 读 [a]；l'en 读 [lɑ̃]；contre 读 [kɔ̃tʁ]，常在这里多读一个弱 [ə]；de 读 [də]。","pi":"en 读 [ɑ̃]，contre 读 [kɔ̃]：两个鼻化音不同；l'encontre 是省音；不要拼成 à l'en-contre。","et":"由 en + contre 构成，来自晚期拉丁语 incontra（迎面），与 contre 同源。","ex":[["Cette décision va à l'encontre de nos principes.","这个决定违背我们的原则。"],["Ça va à l'encontre de ce que je pensais.","这和我原来想的相反。"],["Il agit à l'encontre des règles.","他的做法违反规定。"]],"co":[["aller à l'encontre de","违背"],["à l'encontre des règles","违反规则"],["à l'encontre de l'opinion générale","与普遍看法相反"],["agir à l'encontre de","违背……行事"]],"sy":[["contre","courant","反对，日常"],["contrairement à","courant","与……相反"],["en contradiction avec","soutenu","与……矛盾"]],"fq":"中低频，书面和正式场合多见。","me":"en + contre：“迎面撞上”，所以是相悖。","tr":{"zh":"这个想法违背了我们的原则。","fr":"Cette idée va à l'encontre de nos principes.","alt":"Cette idée, c'est contre nos principes.","note":"aller à l'encontre de + 名词，de 会与 les 变成 des。"}},
 "Auprès de": {"pos":"loc. prép. 介词短语，不变","s":"三个常用意思：1) 在……旁边（书面）；2) 向……（提出请求、咨询）：se renseigner auprès de l'office de tourisme；3) 在……中间、受……欢迎：populaire auprès des jeunes。","ipa":"[o.pʁɛ.də]","ph":"au 读 [o]；près 读 [pʁɛ]；de 读 [də]。","pi":"près 的 s 不发；auprès 的 è 是 [ɛ]；不要和 après（在……之后）混淆，au- 与 a- 区别很大。","et":"由 au + près（à + près，“靠近”）构成，与 près 同源，拉丁语 pressus（紧靠）。","ex":[["Ce quartier est populaire auprès des touristes.","这个街区在游客中很受欢迎。"],["Renseignez-vous auprès de l'accueil.","请向前台询问。"],["Elle s'est assise auprès de sa mère.","她坐在母亲身边。"]],"co":[["se renseigner auprès de","向……打听"],["populaire auprès de","在……中受欢迎"],["s'informer auprès de","向……了解"],["être auprès de quelqu'un","守在某人身边"]],"sy":[["près de","courant","靠近"],["chez","courant","在……那里（群体中）"],["à côté de","courant","在……旁边"]],"fq":"中频，书面和办事场合常见。","me":"au + près：靠近 → 向某人 / 在某人那里。","tr":{"zh":"你可以向前台打听。","fr":"Tu peux te renseigner auprès de l'accueil.","alt":"Demande à l'accueil, ils te renseigneront.","note":"auprès de 常接人或机构。"}},
 "Contre": {"pos":"prép. 介词；也可作副词 / 名词 le contre（反对）","s":"最常用：反对、对着：voter contre。另外：1) 紧靠：contre le mur；2) 换取：échanger contre；3) 对比：10 % contre 60 % autrefois（现在百分之十，过去百分之六十），表示“与……相比”。","ipa":"[kɔ̃tʁ]","ph":"con 读 [kɔ̃]；tre 读 [tʁ]，结尾 e 不发。","pi":"con 是鼻化 [kɔ̃]，n 不发；-tre 是一个很轻的 [tʁ]，不要读成 [tʁə]；注意与 pour（赞成）相对。","et":"来自拉丁语 contra（相对、反对）。同源：contraire, contraste。","ex":[["Moins de 10 % de la population est ouvrière contre les deux tiers il y a quarante ans.","工人占人口不到百分之十，四十年前是三分之二。"],["Je vote contre cette loi.","我投票反对这项法律。"],["Elle s'est appuyée contre le mur.","她靠在墙上。"]],"co":[["contre toute attente","出乎意料"],["pour ou contre","赞成还是反对"],["échanger contre","交换成"],["par contre","不过、相反"]],"sy":[["face à","courant","面对"],["versus","soutenu","对阵，书面或体育"],["en échange de","courant","作为交换"]],"fq":"极高频，日常必用。","me":"contre 与 pour 相对：pour 赞成，contre 反对。","tr":{"zh":"你赞成还是反对这个计划？","fr":"Tu es pour ou contre ce projet ?","alt":"T'es pour ou contre ce projet ?","note":"être pour / contre quelque chose。"}},
 "D'après": {"pos":"prép. 介词（d' + après）","s":"根据、据……说：d'après la police（据警方）。也指“仿照”：un film d'après un roman（根据小说改编的电影）。","ipa":"[da.pʁɛ]","ph":"d'a 读 [da]；près 读 [pʁɛ]，s 不发。","pi":"d'après 要省音（d'），不能写 de après；après 的 s 不发；注意与 selon 用法类似。","et":"d'（de）+ après（后），本义“从……之后”，引申为“根据”。","ex":[["D'après la police, personne n'a été blessé.","据警方说，没有人受伤。"],["D'après moi, il a raison.","依我看，他是对的。"],["Ce film est tourné d'après un roman célèbre.","这部电影根据一部名著改编。"]],"co":[["d'après moi","依我看"],["d'après lui","据他说"],["d'après un roman","根据一部小说"],["d'après ce que j'ai compris","据我所了解"]],"sy":[["selon","courant","根据，更中性"],["suivant","soutenu","按照"],["à en croire","courant","照……的说法"]],"fq":"极高频，日常常用。","me":"d' + après：“从后面的信息得知”。","tr":{"zh":"据天气预报，明天会下雨。","fr":"D'après la météo, il va pleuvoir demain.","alt":"Selon la météo, il va pleuvoir demain.","note":"d'après + 人 / 来源。"}},
 "Hormis": {"pos":"prép. 介词，不变","s":"除……之外：Tout le monde est venu, hormis Paul。比 sauf 和 excepté 更书面一点。","ipa":"[ɔʁ.mi]","ph":"h 不发音；or 读 [ɔʁ]；mis 读 [mi]，s 不发。","pi":"h 不发音，从 [ɔʁ] 开始读；mis 里 s 不发；不要和 hors（在……之外）读错。","et":"由 hors（外）+ mis（mettre 的过去分词，放置）构成，字面是“放到外面”。","ex":[["Tout le monde est venu, hormis Paul.","除了保罗，大家都来了。"],["Hormis le prix, tout est parfait.","除了价格，一切都很完美。"],["Je mange de tout, hormis le poisson.","我什么都吃，除了鱼。"]],"co":[["hormis + 名词","除……外"],["hormis le fait que…","除了……这一点"],["hormis quelques exceptions","除了少数例外"],["tous, hormis lui","除了他，所有人"]],"sy":[["sauf","courant","除了，最常用"],["excepté","soutenu","除……外"],["à part","courant","除了，口语"]],"fq":"中频，书面和新闻常见。","me":"hors + mis：被“放到外面”的人或事。","tr":{"zh":"除了周日，商店每天都开门。","fr":"Les magasins sont ouverts tous les jours, hormis le dimanche.","alt":"Les magasins sont ouverts tous les jours sauf le dimanche.","note":"hormis + 名词；口语换成 sauf。"}},
 "C'est pas près de s'arrêter": {"pos":"loc. 口语短语（否定省略 ne：ce n'est pas près de…）","s":"指事情一时半会儿不会结束：c'est pas près de finir / de s'arrêter。pas près de + 动词原形 = 离……还远着呢。常用于抱怨雨、噪音、麻烦。","ipa":"[sɛ.pa.pʁɛ.də.sa.ʁɛ.te]","ph":"c'est 读 [sɛ]；pas 读 [pa]；près 读 [pʁɛ]；s'arrêter 读 [sa.ʁɛ.te]。口语里 ne 省略。","pi":"près 的 s 不发；près de 读 [pʁɛ.də]；不要和 prêt（准备好）[pʁɛ] 混：prêt à 是“准备好”，près de 是“靠近”。","et":"près de + 动词原形 = 将要，否定后“离……还远”。是法语的常见口语结构，不是固定的古语。","ex":[["Il pleut beaucoup, et c'est pas près de s'arrêter.","雨下得很大，而且一时半会儿停不了。"],["La grève, c'est pas près de finir.","罢工一时半会儿结束不了。"],["Les travaux, c'est pas près de s'arrêter.","施工一时半会儿停不了。"]],"co":[["c'est pas près de finir","一时半会儿完不了"],["c'est pas près d'arriver","离发生还早着呢"],["il n'est pas près de…","他离……还远"],["c'est pas près de changer","一时半会儿变不了"]],"sy":[["ça va durer","courant","还会持续一阵"],["ce n'est pas demain la veille","familier","离那一天还远，口语"],["on n'est pas sortis de l'auberge","familier","麻烦还没完"]],"fq":"中频，口语里用得多。","me":"près de = 靠近；pas près de = 离得还远。","tr":{"zh":"这场雨一时半会儿停不了。","fr":"C'est pas près de s'arrêter, cette pluie.","alt":"Cette pluie n'est pas près de s'arrêter.","note":"正式写法要有 ne：Ce n'est pas près de…。"}},
 "Ça ne vaut rien": {"pos":"loc. 短语（valoir 的第三人称单数）","s":"一文不值、不值钱、没用：Ça ne vaut rien。说东西质量差、没价值。也可说 Ça ne vaut pas grand-chose（没多大价值）。","ipa":"[sa.nə.vo.ʁjɛ̃]","ph":"ça 读 [sa]；ne 读 [nə]；vaut 读 [vo]，aut 读 [o]，t 不发；rien 读 [ʁjɛ̃]。","pi":"vaut 的 aut 读 [o]，t 不发，与 veau（小牛）、vos（你们的）同音；rien 读 [ʁjɛ̃]，n 不发；ça 的 ç 读 [s]。","et":"valoir 来自拉丁语 valere（有价值、强壮）。同源：valeur, valable。","ex":[["Cette vieille montre est cassée, ça ne vaut rien.","这块旧表坏了，一文不值。"],["Ce vieux canapé ne vaut rien.","这个旧沙发一文不值。"],["Son avis ne vaut rien pour moi.","他的意见对我没价值。"]],"co":[["ne rien valoir","一文不值"],["ça ne vaut pas grand-chose","没多大价值"],["ça ne vaut pas la peine","不值得"],["ça vaut le coup","值得（反义）"]],"sy":[["c'est nul","familier","太差了"],["ça ne sert à rien","courant","没用"],["ça vaut zéro","familier","毫无价值"]],"fq":"中频，口语里常用。","me":"valoir（值）+ rien（没有）：值“零”。","tr":{"zh":"这块旧表坏了，一文不值。","fr":"Cette vieille montre est cassée, elle ne vaut rien.","alt":"Cette vieille montre est cassée, ça vaut rien.","note":"口语里 ne 常省略。"}},
 "En plein cagnard": {"pos":"loc. 口语短语，不变","s":"在烈日下、大太阳底下：Il fait chaud, on est en plein cagnard。cagnard 指炎热的大太阳，多用于法国南部口语，不用于正式场合。","ipa":"[ɑ̃.plɛ̃.ka.ɲaʁ]","ph":"en 读 [ɑ̃]；plein 读 [plɛ̃]；cagnard 读 [ka.ɲaʁ]，gn 读 [ɲ]，d 不发。","pi":"gn 读 [ɲ]（像“尼”），不是 [ɡn]；cagnard 末尾 d 不发，r 要发；plein 的 -ein 读 [ɛ̃]。","et":"cagnard 的来源不确定（可能和南部方言有关）。plein 来自拉丁语 plenus（满的）。en plein + 名词 = 在……正中。","ex":[["Ne reste pas en plein cagnard sans chapeau.","别没戴帽子待在烈日下。"],["On a marché en plein cagnard pendant deux heures.","我们在烈日下走了两个小时。"],["Ils travaillent en plein cagnard.","他们在烈日下干活。"]],"co":[["en plein soleil","在太阳下（普通说法）"],["en plein cagnard","在烈日下（口语）"],["en plein été","盛夏"],["en plein air","户外"]],"sy":[["en plein soleil","courant","太阳直射下，日常"],["sous le soleil","courant","在阳光下"],["à l'ombre","courant","反义：在阴凉处"]],"fq":"低频，南部口语。","me":"plein + cagnard：整个人被烈日“填满”。","tr":{"zh":"我们在烈日下等了一个小时。","fr":"Nous avons attendu une heure en plein cagnard.","alt":"On a attendu une heure en plein soleil.","note":"en plein + 名词 = 在……正当中。"}},
 "Et j'en passe": {"pos":"loc. 固定短语，不变","s":"列举几项后加上，表示“还有很多我就不说了”，诸如此类：des pommes, des poires, et j'en passe。有时带一点抱怨、夸张的语气。","ipa":"[e.ʒɑ̃.pas]","ph":"et 读 [e]；j'en 读 [ʒɑ̃]；passe 读 [pas]，结尾 e 不发。","pi":"j'en 读 [ʒɑ̃]，en 的 n 不发（鼻化）；et 的 t 不发；en 代替前面列举的那些东西，不能漏掉。","et":"j'en passe 字面是“我略过其中一些”：passer（略过）+ en（其中的）。","ex":[["Il y avait des pommes, des poires, des bananes, et j'en passe.","有苹果、梨、香蕉等等。"],["Il y a le bruit, la pollution, et j'en passe.","有噪音、有污染，还有很多我就不说了。"],["Elle a visité Rome, Paris, Londres, et j'en passe.","她去过罗马、巴黎、伦敦，还有很多别的地方。"]],"co":[["et j'en passe","等等、还有很多"],["et j'en passe, et des meilleures","更精彩的我就不说了"],["et tout le reste","和其余的一切"],["et ainsi de suite","依此类推"]],"sy":[["et cetera","courant","等等，缩写 etc."],["et ainsi de suite","courant","依此类推"],["et tout le tralala","familier","诸如此类，口语"]],"fq":"中频，口语和写作都用。","me":"j'en passe = “其余的我跳过”。","tr":{"zh":"有噪音、有污染，还有很多别的问题。","fr":"Il y a le bruit, la pollution, et j'en passe.","alt":"Entre le bruit et la pollution, et j'en passe, c'est dur.","note":"j'en passe 放在列举后面。"}},
 "Il était temps !": {"pos":"loc. 感叹句，固定短语","s":"总算来了！终于！表示等了很久、事情终于发生，略带不耐烦或松口气：Tu es enfin là, il était temps !","ipa":"[i.le.te.tɑ̃]","ph":"il 读 [i.l]，和 était 连读成 [i.le.te]；temps 读 [tɑ̃]，ps 不发。","pi":"temps 读 [tɑ̃]，p 和 s 都不发；était 读 [e.te]，t 不发；固定用 imparfait（était），不是 est。","et":"il était temps 字面是“已是时候了”，用 imparfait 表示“早该如此”。","ex":[["Tu es enfin là, il était temps !","你终于来了，总算！"],["Le bus arrive. Il était temps !","公交车来了，总算来了！"],["Il a enfin fini son travail ! Il était temps !","他总算做完了！真是时候了！"]],"co":[["il était temps !","总算！"],["il est temps de…","是时候……了"],["il était grand temps","早就该了"],["il était temps que + subj.","早该……了"]],"sy":[["enfin !","courant","终于！"],["c'est pas trop tôt","familier","也不算早"],["ce n'est pas trop tôt","courant","不算早了"]],"fq":"中高频，口语常用。","me":"il était temps = “已经是时候了”，等了好久。","tr":{"zh":"你总算到了！我们等了很久。","fr":"Te voilà enfin, il était temps ! On t'attendait depuis longtemps.","alt":"Ah, te voilà ! C'est pas trop tôt !","note":"整个表达用 imparfait；il est temps 是现在时。"}},
 "L'heure a sonné": {"pos":"loc. 固定短语（sonner 的 passé composé）","s":"时候到了、该……的时刻来了：L'heure a sonné de + 动词原形。多用于重大决定、行动的时刻，偏书面。","ipa":"[lœ.ʁa.sɔ.ne]","ph":"l'heure 读 [lœʁ]，h 不发，l' 与 heure 连成 [lœʁ]；a 读 [a]；sonné 读 [sɔ.ne]。","pi":"h 是哑音，l'heure 读 [lœʁ]，r 与 a 连读成 [lœ.ʁa]；sonner 的助动词是 avoir，所以是 a sonné。","et":"字面是“钟敲响了”。heure 来自拉丁语 hora（小时）。","ex":[["L'heure a sonné de prendre une décision.","该做决定的时候到了。"],["L'heure a sonné, il faut partir.","时间到了，该走了。"],["Pour lui, l'heure de la retraite a sonné.","对他来说，退休的时刻到了。"]],"co":[["l'heure a sonné","时候到了"],["l'heure de la vérité","决定性时刻"],["à l'heure","准时"],["l'heure est venue de…","是时候……了"]],"sy":[["le moment est venu","courant","时候到了"],["il est temps de","courant","该……了"],["l'heure H","soutenu","行动的约定时刻"]],"fq":"中低频，书面、新闻里多见。","me":"钟声响起：l'heure sonne，时候到了。","tr":{"zh":"我们离开的时候到了。","fr":"L'heure a sonné de partir.","alt":"Il est temps de partir.","note":"l'heure a sonné de + 动词原形。"}},
 "Le moins qu'on puisse dire, ...": {"pos":"loc. 固定短语，句首插入语","s":"至少可以说、说得客气一点：Le moins qu'on puisse dire, c'est que + 句子。用来委婉表达较强的评价，意思常比字面更强。","ipa":"[lə.mwɛ̃.kɔ̃.pɥis.diʁ]","ph":"moins 读 [mwɛ̃]；qu'on 读 [kɔ̃]；puisse 读 [pɥis]，ui 读 [ɥi]；dire 读 [diʁ]。","pi":"moins 读 [mwɛ̃]，s 不发；puisse 是 pouvoir 的虚拟式（subjonctif），不要用 peut；ui 读 [ɥi]。","et":"固定的省略说法，puisse 是虚拟式，因为前面有最高级 le moins。","ex":[["Le moins qu'on puisse dire, c'est qu'il fait froid.","至少可以说，天气很冷。"],["Le moins qu'on puisse dire, c'est qu'il n'est pas content.","至少可以说，他不高兴。"],["Le moins qu'on puisse dire, c'est que ce repas était long.","至少可以说，这顿饭很长。"]],"co":[["le moins qu'on puisse dire","至少可以说"],["c'est le moins qu'on puisse dire","这只是最轻的说法"],["pour le moins","至少"],["tout au moins","至少"]],"sy":[["c'est peu dire","courant","说轻了"],["pour dire le moins","soutenu","说得最保守一点"],["c'est un euphémisme","courant","这是委婉说法"]],"fq":"中频，口语和书面都用。","me":"le moins qu'on puisse dire = 能说的“最少”也已经这么多。","tr":{"zh":"至少可以说，这顿饭很长。","fr":"Le moins qu'on puisse dire, c'est que ce repas était long.","alt":"Ce repas était long, c'est le moins qu'on puisse dire.","note":"puisse 是 pouvoir 的虚拟式。"}},
 "Si seulement ...": {"pos":"loc. 固定短语（si + imparfait 或 plus-que-parfait）","s":"要是……就好了：表达遗憾或愿望。si seulement + imparfait 表示现在的愿望；si seulement + plus-que-parfait 表示对过去的遗憾。","ipa":"[si.sœl.mɑ̃]","ph":"si 读 [si]；seule 读 [sœl]；-ment 读 [mɑ̃]。si 在 il 前变 s'。","pi":"si 后不能直接用条件式（-rais）；只能是 imparfait / plus-que-parfait；seulement 的 t 不发；si + il = s'il。","et":"si（如果）+ seulement（只是）：字面是“要是只……”。","ex":[["Si seulement j'avais plus de temps !","要是我有更多时间就好了！"],["Si seulement il pleuvait moins !","要是雨少一点就好了！"],["Si seulement j'avais écouté mes parents !","要是我听了父母的话就好了！"]],"co":[["si seulement + imparfait","要是……就好了（现在）"],["si seulement + plus-que-parfait","要是当初……就好了"],["si seulement je pouvais…","要是我能……"],["si seulement tu savais","要是你知道就好了"]],"sy":[["ah, si…","courant","要是……"],["j'aimerais que","courant","我希望"],["plût au ciel que","littéraire","但愿（书面）"]],"fq":"中高频，口语常用。","me":"si seulement：愿望 + 遗憾，动词退一格用过去式。","tr":{"zh":"要是我会说法语就好了！","fr":"Si seulement je parlais français !","alt":"Ah, si seulement je parlais bien français !","note":"si seulement + imparfait。"}},
 "Y'a pas photo !": {"pos":"loc. 口语短语（il n'y a pas photo 的省略说法）","s":"没得比、毫无疑问，一眼就看出谁更好：Y'a pas photo ! 说明两者差距明显。非常口语，不用于正式场合。","ipa":"[ja.pa.fɔ.to]","ph":"y'a 读 [ja]（il y a 的口语缩读）；pas 读 [pa]；photo 读 [fɔ.to]，ph 读 [f]。","pi":"ph 读 [f]，不是 [p]；y'a 是 il y a 的缩略，不是 ya；pas 的 s 不发。","et":"常被解释为来自赛马中的“终点摄影”：差距大到不用看照片也知道谁赢，但这个说法的来源不能完全确定。","ex":[["Ce gâteau est bien meilleur, y'a pas photo !","这个蛋糕好多了，没得比！"],["Entre les deux équipes, y'a pas photo.","这两队之间，高下立判。"],["Pour le goût, y'a pas photo.","说味道，那是没得比的。"]],"co":[["y'a pas photo","没得比"],["il n'y a pas photo","毫无疑问（完整形式）"],["y'a pas à hésiter","不用犹豫"],["c'est évident","很明显"]],"sy":[["c'est évident","courant","显而易见"],["sans aucun doute","courant","毫无疑问"],["y'a pas match","familier","没得比，口语"]],"fq":"中频，非常口语。","me":"photo-finish：不用看照片，结果一目了然。","tr":{"zh":"这家店的咖啡好太多了，没得比！","fr":"Le café de ce bar est bien meilleur, y'a pas photo !","alt":"Ce café est vraiment meilleur, y'a pas photo !","note":"口语缩略，写作中用 il n'y a pas photo。"}},
 "Pas l'ombre de": {"pos":"loc. 固定短语，不变","s":"一点也没有、没有一丝：Il n'y a pas l'ombre d'un doute（毫无疑问）。后面常接 de + 名词，多用于否定，强调“丝毫没有”。","ipa":"[pa.lɔ̃bʁ.də]","ph":"pas 读 [pa]；l'ombre 读 [lɔ̃bʁ]，om 读 [ɔ̃]；de 读 [də]。","pi":"ombre 里的 om 读鼻化 [ɔ̃]；pas 的 s 不发；常和 ne…pas 连用，注意完整否定。","et":"ombre（阴影）来自拉丁语 umbra；这里“影子”比喻“一点点痕迹”。","ex":[["Il n'y a pas l'ombre d'un doute.","没有丝毫怀疑。"],["Il n'avait pas l'ombre d'une chance.","他一点机会也没有。"],["Elle n'a pas l'ombre d'un regret.","她丝毫不后悔。"]],"co":[["pas l'ombre d'un doute","毫无疑问"],["pas l'ombre d'une chance","毫无机会"],["pas l'ombre d'un remords","没有一点悔意"],["sans l'ombre d'un doute","无可置疑地"]],"sy":[["aucun","courant","没有任何"],["pas une once de","soutenu","没有一丝"],["pas la moindre","courant","一点也没有"]],"fq":"中频，书面和新闻常见。","me":"连“影子”都没有：pas l'ombre = 一丝也没有。","tr":{"zh":"我对这个决定毫无疑问。","fr":"Je n'ai pas l'ombre d'un doute sur cette décision.","alt":"Je n'ai pas le moindre doute sur cette décision.","note":"pas l'ombre d'un + 名词。"}},
 "Bon sang !": {"pos":"interj. 感叹词，不变","s":"天哪！该死！表示生气、惊讶、懊恼：Bon sang ! J'ai oublié mes clés ! 比 mince 稍重，但不算粗口。","ipa":"[bɔ̃.sɑ̃]","ph":"bon 读 [bɔ̃]；sang 读 [sɑ̃]，g 不发音。","pi":"sang 的 g 不发，读 [sɑ̃]，与 sans、cent 同音；bon 的 n 不发；没有连读。","et":"sang（血）来自拉丁语 sanguis。bon sang 常被看作一个较温和的感叹，来源不完全确定。","ex":[["Bon sang ! J'ai encore oublié mes clés !","天哪！我又忘带钥匙了！"],["Bon sang, tu m'as fait peur !","天哪，你吓了我一跳！"],["Mais bon sang, qu'est-ce que tu fais ?","天哪，你到底在干什么？"]],"co":[["bon sang de bois !","天杀的！（更口语的加强）"],["mais bon sang !","天哪，到底怎么回事！"],["bon sang de bonsoir !","天哪！（更夸张）"],["bon sang ne saurait mentir","血脉相承（谚语）"]],"sy":[["mince !","familier","糟了！温和"],["zut !","familier","糟糕！"],["purée !","familier","天哪！"]],"fq":"中频，口语常用。","me":"bon sang = 好血：天哪！","tr":{"zh":"天哪！我又迟到了！","fr":"Bon sang ! Je suis encore en retard !","alt":"Zut ! Je suis encore en retard !","note":"Bon sang 放句首，后面接惊叹句。"}},
 "À même de": {"pos":"loc. 固定短语（à même de + 动词原形）","s":"有能力做……、能够：être à même de + 动词原形。常用在书面：Il est à même de répondre（他有能力回答）。比 capable de 稍正式。","ipa":"[a.mɛm.də]","ph":"à 读 [a]；même 读 [mɛm]；de 读 [də]。","pi":"même 里 ê 读 [ɛ]，结尾 m 要发；à même de 后面必须接动词原形；不要与 être capable 的意思混淆，这个表达更书面。","et":"à même de：même 在这里的意思是“有条件、在位置上”；是固定搭配，字面义不重要。","ex":[["Les petites villes sont plus à même de satisfaire le besoin de nature.","小城镇更能满足人们对自然的需求。"],["Je ne suis pas à même de répondre.","我没法回答。"],["Il est à même de réussir.","他有能力成功。"]],"co":[["être à même de + inf.","有能力做……"],["mettre quelqu'un à même de","使某人能够……"],["plus à même de","更有能力"],["pas à même de","不能"]],"sy":[["capable de","courant","能够，日常"],["en mesure de","soutenu","有能力做"],["apte à","soutenu","适合做"]],"fq":"中低频，书面、工作场合多见。","me":"à même de：站在“可以直接做”的位置上。","tr":{"zh":"他有能力回答这个问题。","fr":"Il est à même de répondre à cette question.","alt":"Il est capable de répondre à cette question.","note":"être à même de + 动词原形。"}},
 "À mains nues": {"pos":"loc. 固定短语，不变","s":"赤手空拳、徒手：不用工具或手套。à mains nues 或 les mains nues：Il a grimpé le mur à mains nues。","ipa":"[a.mɛ̃.ny]","ph":"à 读 [a]；mains 读 [mɛ̃]，ai 读 [ɛ̃]，s 不发；nues 读 [ny]，u 是 [y]，es 不发。","pi":"mains 读 [mɛ̃]，与 main（手）同音，所以复数听不出来；nues 是复数形容词，加 s；u 是 [y]，嘴圆。","et":"à + mains（手，复数）+ nues（光着的）。nu 来自拉丁语 nudus（裸的），同源：nudité。","ex":[["Il a grimpé le mur à mains nues.","他徒手爬墙。"],["Il a combattu à mains nues.","他赤手空拳搏斗。"],["On ne doit pas toucher ça à mains nues.","不能徒手碰这个。"]],"co":[["à mains nues","徒手"],["les mains nues","空着双手"],["se battre à mains nues","赤手搏斗"],["à mains nues contre…","赤手对付……"]],"sy":[["sans gants","courant","没戴手套"],["à la main","courant","用手"],["sans outil","courant","不用工具"]],"fq":"中低频，描述动作时用。","me":"mains + nues：光着的手，没有任何东西。","tr":{"zh":"他徒手抓住了那条蛇。","fr":"Il a attrapé le serpent à mains nues.","alt":"Il a attrapé le serpent les mains nues.","note":"à mains nues 中 mains 用复数。"}},
 "À perte de vue": {"pos":"loc. adv. 副词短语，固定搭配","s":"一望无际，一直延伸到看不见的地方。常接 s'étendre（延伸）、s'étaler 等动词，描写田野、海、沙漠、队伍。字面是「到视线丢失为止」。","ipa":"[a pɛʁt də vy]","ph":"perte 里 e 不发音尾音，t 要读出 [pɛʁt]；de 轻读 [də]；vue [vy]（u 是圆唇的 [y]）。","pi":"vue 的 u 是 [y]，不是 [u]；perte 的 -rte 要读出 r 和 t，不要吞掉。","et":"perte 来自拉丁语 perdita（失去），与动词 perdre 同源；vue 是 voir 的名词形式。","ex":[["Des champs de blé s'étendent à perte de vue.","麦田一望无际。"],["La plage continue à perte de vue.","海滩一直延伸到看不到尽头。"]],"co":[["s'étendre à perte de vue","一望无际地延伸"],["un désert à perte de vue","一望无际的沙漠"],["perdre de vue","看不见；失去联系"]],"sy":[["à l'infini","courant","无限地，没有尽头"],["à l'horizon","courant","在地平线上，只是「远处」"]],"fq":"中频，描写风景时常用。","me":"「看到丢了」：视线（vue）都丢了（perte），所以是一望无际。","tr":{"zh":"从山顶上看，森林一望无际。","fr":"Du haut de la montagne, la forêt s'étend à perte de vue.","alt":"Du sommet, on voit la forêt à perte de vue.","note":"à perte de vue 是固定短语，vue 前无冠词。"}},
 "À priori": {"pos":"loc. adv. 副词短语（拉丁语借词），也可作名词 un a priori「先入之见」","s":"乍看之下；按理说；事先。表示「在没有细查之前的初步判断」，口语里常说 à priori, … 来给出一个暂时的看法。也作名词：avoir des a priori 指「有成见」。","ipa":"[a pʁi.jɔ.ʁi]","ph":"priori 读成四个音节 [pʁi.jɔ.ʁi]；r 是喉音 [ʁ]。常见拼写 a priori 或 à priori，两种都能看到。","pi":"不要读成英语的 a-prior-eye；结尾 i 要清楚地读 [i]。它对应的反义是 a posteriori（事后）。","et":"拉丁语 a priori，字面「从前面的东西出发」，哲学术语，后来进入日常用语。","ex":[["À priori, la réunion est maintenue.","按理说会议照常举行。"],["Je n'ai rien contre lui, à priori.","乍看我对他没什么意见。"]],"co":[["à priori, …","乍看起来，……"],["un jugement a priori","先入为主的判断"],["avoir des a priori","有成见"],["a posteriori","事后；事后看来"]],"sy":[["en principe","courant","原则上，理论上"],["de prime abord","soutenu","乍一看，第一眼"],["apparemment","courant","看起来，表面上"]],"fq":"较高频，口语和写作都常用。","me":"a priori =「先于（priori）经验」：还没看就先下判断。","tr":{"zh":"乍看之下，这个计划没有问题。","fr":"À priori, ce projet ne pose pas de problème.","alt":"À priori, y a pas de souci avec ce projet.","note":"à priori 常放句首，后面加逗号。"}},
 "À proximité": {"pos":"loc. adv. 副词短语；常用 à proximité de + 名词","s":"在附近，近处。单独用 = 就在附近；后接 de 表示「在……附近」：à proximité de la gare。比 près 稍正式，常见于广告、指示牌。","ipa":"[a pʁɔk.si.mi.te]","ph":"x 读 [ks]：prox-i-mi-té，共四音节；结尾 é 读 [e]。","pi":"x 在这里读 [ks]，不要读成 [s] 或 [z]；注意 proximité 是阴性名词（la proximité）。","et":"来自拉丁语 proximitas，与 proche（近的）、proximus（最近的）同源。","ex":[["Il y a un supermarché à proximité.","附近有一家超市。"],["L'hôtel est à proximité de la gare.","酒店就在火车站附近。"]],"co":[["à proximité de + 名词","在……附近"],["commerces à proximité","附近的商店"],["à proximité immédiate","紧邻"]],"sy":[["près (de)","courant","近，最常用，较口语"],["à côté (de)","courant","在旁边，更近一点"],["dans les environs","courant","在周边一带"]],"fq":"高频，租房、旅游、广告里很常见。","me":"proximité 像英语 proximity（邻近），一看就懂。","tr":{"zh":"我想租一个离地铁站很近的公寓。","fr":"Je cherche un appartement à proximité du métro.","alt":"Je voudrais un appartement près du métro.","note":"à proximité de + 名词；de 与 le 缩合为 du。"}},
 "De bon coeur": {"pos":"loc. adv. 副词短语（cœur，阳性名词）","s":"真心实意地；欣然地，心甘情愿地。形容做事出于善意、不勉强，常接 aider、donner、rire（笑）等动词。de bon cœur 也可指「大笑得痛快」：rire de bon cœur。","ipa":"[də bɔ̃ kœʁ]","ph":"bon 是鼻化元音 [bɔ̃]，n 不发音；cœur 的 œu 读 [œ]，结尾 r 读 [ʁ]。","pi":"cœur 的 œu 不是 [u]，也不是 [ø]；写法 cœur 与 coeur 都常见，正式写作用 cœur。","et":"cœur 来自拉丁语 cor（心）；bon 是「好」。整体是「怀着好心」。","ex":[["Elle m'a aidé de bon cœur.","她真心实意地帮了我。"],["Je vous remercie de bon cœur.","我衷心感谢你们。"],["Ils ont ri de bon cœur.","他们开怀大笑。"]],"co":[["aider de bon cœur","欣然帮忙"],["rire de bon cœur","开怀大笑"],["de tout cœur","全心全意；衷心地"],["à contrecœur","不情愿地"]],"sy":[["volontiers","courant","乐意地，很愿意"],["avec plaisir","courant","高兴地，乐意"],["de bonne grâce","soutenu","心甘情愿，大方地"]],"fq":"中频，日常和书面都有。","me":"bon + cœur =「好心」去做，反义：à contrecœur（违心）。","tr":{"zh":"邻居真心实意地借给了我他的梯子。","fr":"Mon voisin m'a prêté son échelle de bon cœur.","alt":"Mon voisin m'a prêté son échelle avec plaisir.","note":"de bon cœur 是副词短语，放在动词后面。"}},
 "En bons termes": {"pos":"loc. adv. 副词短语；常与 être / rester / se quitter 连用","s":"关系融洽地，彼此相处得好。多说 être en bons termes avec qqn（和某人关系不错）、se quitter en bons termes（好聚好散）。反义是 en mauvais termes。","ipa":"[ɑ̃ bɔ̃ tɛʁm]","ph":"en 读鼻化音 [ɑ̃]；bons 的 n 不发音，s 也不发音；termes 的 -es 不发音，读 [tɛʁm]。","pi":"bons 和 termes 末尾的 s 都不发音；注意 termes 用复数，不说 en bon terme。","et":"terme 来自拉丁语 terminus（界限，界标），在这里引申为「彼此之间的关系、措辞」。","ex":[["Ils se sont séparés en bons termes.","他们好聚好散。"],["Je suis en bons termes avec mes voisins.","我和邻居相处融洽。"]],"co":[["être en bons termes avec qqn","和某人关系好"],["rester en bons termes","保持良好关系"],["se quitter en bons termes","好聚好散"],["en mauvais termes","关系不好"]],"sy":[["en bons rapports","courant","关系良好"],["s'entendre bien","courant","相处得好，更口语"],["en froid","courant","（反义）关系冷淡，闹僵"]],"fq":"中频，书面和口语都用。","me":"terme = 彼此的「措辞/关系」；bons termes = 好的关系。","tr":{"zh":"离婚以后，他们依然关系融洽。","fr":"Après leur divorce, ils sont restés en bons termes.","alt":"Même après le divorce, ils s'entendent bien.","note":"rester en bons termes：termes 要用复数。"}},
 "Les uns après les autres": {"pos":"loc. adv. 副词短语（不定代词 les uns / les autres）","s":"一个接一个地，依次地。指一群人或事物逐个出现或发生，不是同时。les uns 和 les autres 都用复数，要和主语的数配合；如果对象是阴性，说 les unes après les autres。","ipa":"[le.zœ̃ a.pʁɛ le.zotʁ]","ph":"les uns 和 les autres 前都要联诵：[le.zœ̃]、[le.zotʁ]；après 的 è 读 [ɛ]，s 不发音。","pi":"联诵 z 很容易漏；uns 的 un 是鼻化元音 [œ̃]；autres 末尾 -es 不读。","et":"由 un（一）+ après（在……之后）+ autre（另一个）组合，没有特别的词源，是纯粹的构词。","ex":[["Ils sont entrés les uns après les autres.","他们一个接一个地进来。"],["Les jours passent les uns après les autres.","日子一天接一天地过去。"],["Les fleurs sont tombées les unes après les autres.","花一朵接一朵地落了。"]],"co":[["les unes après les autres","（阴性）一个接一个"],["l'un après l'autre","一个接一个（只有两个）"],["les uns à côté des autres","一个挨一个地"],["les uns avec les autres","彼此之间"]],"sy":[["à la file","courant","排成一列、依次"],["successivement","soutenu","相继地，依次"],["tous en même temps","courant","（反义）同时，一起"]],"fq":"中高频，日常常用。","me":"uns 先、autres 后：一个（un）完了，下一个（autre）接上。","tr":{"zh":"孩子们一个接一个地下了车。","fr":"Les enfants sont descendus du bus les uns après les autres.","alt":"Les enfants sont descendus un par un.","note":"un par un 是更短的说法；对女孩们用 les unes après les autres。"}},
 "Par dessus tout": {"pos":"loc. adv. 副词短语，规范拼写 par-dessus tout","s":"最重要的是，尤其，胜过一切。用来强调「最喜欢、最看重、最需要」的东西。通常放在句尾或动词后；动词 aimer、vouloir、détester 很常用。","ipa":"[paʁ də.sy tu]","ph":"par [paʁ]；dessus [də.sy]，注意 dessus 里 u 是 [y]；tout 的 t 在这里不发音，读 [tu]。","pi":"dessus 的 -us 读 [y]，s 不读；tout 作副词/代词，这里是 [tu]。常见错误：拼成 par dessus-tout。","et":"由 par + dessus（在上面）+ tout（一切）组成，字面「在一切之上」。dessus 是 de + sus（上面）。","ex":[["J'aime la musique par-dessus tout.","我最爱音乐。"],["Il veut par-dessus tout la paix.","他最想要的是和平。"]],"co":[["aimer par-dessus tout","爱胜过一切"],["par-dessus tout, …","最重要的是，……"],["avant tout","首先，最重要的是"],["par-dessus tout, il faut…","最重要的是必须……"]],"sy":[["avant tout","courant","首要的是，侧重「先」"],["surtout","courant","尤其是，更日常的说法"],["plus que tout","courant","胜过一切"]],"fq":"中频，偏书面，表达强调。","me":"par + 「在……之上」(dessus) + 「全部」(tout) = 压在一切之上。","tr":{"zh":"最重要的是，别忘了你的护照。","fr":"Par-dessus tout, n'oublie pas ton passeport.","alt":"Surtout, n'oublie pas ton passeport.","note":"par-dessus tout 比 surtout 更强调、稍正式。"}},
 "Pour le moins": {"pos":"loc. adv. 副词短语，常修饰形容词","s":"至少可以说；说得保守一点。作「轻描淡写」用：pour le moins surprenant 其实是「相当令人惊讶」。也能直接表示「至少」，如 pour le moins dix personnes。","ipa":"[puʁ lə mwɛ̃]","ph":"pour [puʁ]；moins 读 [mwɛ̃]，oi 是 [wa]，但这里 oin 读 [wɛ̃]，s 不发音。","pi":"moins 的 oin 是 [wɛ̃]，不是 [mwa]；注意这个短语是在淡化语气，意思比字面要强。","et":"由 pour + le + moins（较少）组成，字面「至少」。moins 来自拉丁语 minus。","ex":[["Sa réaction est pour le moins surprenante.","他的反应说得轻点也很令人惊讶。"],["Cette idée est pour le moins étrange.","这个想法至少也算奇怪。"]],"co":[["pour le moins surprenant / étrange","至少算得上令人惊讶 / 奇怪"],["pour le moins deux fois","至少两次"],["c'est le moins que l'on puisse dire","这已经是最保守的说法了"]],"sy":[["au moins","courant","至少，日常用"],["à tout le moins","soutenu","至少，更书面"],["tout au moins","courant","起码"]],"fq":"中频，偏书面，评论文章常见。","me":"「为了最少」(pour le moins)：话说得最保守，实际更强。","tr":{"zh":"他的回答说得轻点也很奇怪。","fr":"Sa réponse est pour le moins étrange.","alt":"Sa réponse est, c'est le moins qu'on puisse dire, étrange.","note":"pour le moins + 形容词，表达委婉的强调。"}},
 "Sans cesse": {"pos":"loc. adv. 副词短语","s":"不停地，一直。表示动作反复、持续，常带有「烦人」的意味：se plaindre sans cesse（老是抱怨）。比 toujours 更强调「不间断」。","ipa":"[sɑ̃ sɛs]","ph":"sans 读 [sɑ̃]，ns 中 n 属鼻化音，s 不发音；cesse 读 [sɛs]，结尾 -e 不发音。","pi":"cesse 前不加冠词，不能说 sans la cesse；结尾 -e 不发音，ss 读 [s]。","et":"cesse 来自动词 cesser，源于拉丁语 cessare（停止）；sans = 没有。字面「没有停止」。","ex":[["Il se plaint sans cesse.","他不停地抱怨。"],["La pluie tombe sans cesse depuis hier.","从昨天起雨一直下个不停。"]],"co":[["parler / travailler sans cesse","不停地说 / 工作"],["sans cesse plus","越来越……"],["sans arrêt","不停地（更口语）"],["sans relâche","不松懈地"]],"sy":[["sans arrêt","familier","不停，非常口语"],["continuellement","courant","持续不断地"],["sans relâche","soutenu","不懈地，努力不停"]],"fq":"高频，日常和书面都常用。","me":"sans（没有）+ cesse（停止）：永远不停。","tr":{"zh":"我的猫不停地叫。","fr":"Mon chat miaule sans cesse.","alt":"Mon chat miaule sans arrêt.","note":"sans cesse 放在动词后面。"}},
 "Une fois pour toutes": {"pos":"loc. adv. 副词短语；une fois 阴性","s":"一劳永逸地；彻底地、最终地。用来说「只做这一次、之后不再重复」，也常用来强调最后通牒：Je te le dis une fois pour toutes。","ipa":"[yn fwa puʁ tut]","ph":"une [yn]；fois 读 [fwa]，s 不发音；toutes 读 [tut]，t 要发音，-es 不发音。","pi":"toutes 要用阴性复数（与 fois 相配），t 读出来 [tut]；不要写成 pour tout。","et":"由 une fois（一次）+ pour toutes（为了所有的次数）组成，意思是「这一次抵所有次」。","ex":[["Je te le dis une fois pour toutes : non !","我一次性告诉你：不行！"],["Réglons ce problème une fois pour toutes.","我们把这个问题彻底解决吧。"]],"co":[["régler une fois pour toutes","彻底解决"],["décider une fois pour toutes","一次定下来"],["une fois de plus","再一次"],["pour de bon","真正地，彻底地"]],"sy":[["définitivement","courant","彻底地，最终地"],["pour de bon","familier","真的，彻底地"],["une bonne fois pour toutes","courant","加强版，强调彻底"]],"fq":"中高频，日常常用。","me":"「一次」(une fois) 顶「所有次」(pour toutes)。","tr":{"zh":"让我们把这个问题一次说清楚吧。","fr":"Réglons cette question une fois pour toutes.","alt":"On règle ça une bonne fois pour toutes.","note":"常见加强版 une bonne fois pour toutes。"}},
 "Dès lors que": {"pos":"loc. conj. 连词短语；后接直陈式（indicatif）","s":"既然；一旦；只要。可表时间（一旦……就）、原因（既然）、条件（只要……）。dès lors 单独用 = 从那时起；因此。","ipa":"[dɛ lɔʁ kə]","ph":"dès 读 [dɛ]；lors 读 [lɔʁ]，s 不发音；que 在这里读 [kə]，轻读。","pi":"只有 dès 带重音符号 è；后接 indicatif，不接 subjonctif；不要与 dès que 弄混（dès que 只表时间）。","et":"dès 与 lors 都表示时间点；lors 来自拉丁语 illa hora（那一时刻）。字面「从那时起（dès lors）+ que」。","ex":[["Dès lors que tu as fini, tu peux partir.","既然你做完了，就可以走了。"],["Dès lors qu'il pleut, je reste à la maison.","只要下雨，我就待在家里。"]],"co":[["dès lors que + 直陈式","既然；一旦"],["dès lors","从那时起；因此"],["dès que","一……就（表时间）"],["à partir du moment où","从……时起；只要"]],"sy":[["puisque","courant","既然，原因"],["dès que","courant","一……就，纯时间"],["du moment que","courant","只要，条件"]],"fq":"中频，偏书面。","me":"dès（从）+ lors（那时）+ que：「从那时起」，推出结果。","tr":{"zh":"既然你已经决定了，我就支持你。","fr":"Dès lors que tu as décidé, je te soutiens.","alt":"Puisque tu as décidé, je te soutiens.","note":"dès lors que + 直陈式；口语常用 puisque。"}},
 "Au coeur de": {"pos":"loc. prép. 介词短语；cœur 阳性名词","s":"在……的中心；在……的核心。可指地点（au cœur de la ville 市中心），也可指抽象的核心（au cœur du débat 辩论的核心、au cœur du problème 问题的症结）。","ipa":"[o kœʁ də]","ph":"au [o]；cœur 读 [kœʁ]，œu 是圆唇的 [œ]；de [də]。","pi":"œu 不要读成 [u] 或 [ø]；注意是 au cœur de + 名词，后面总有 de。","et":"cœur 来自拉丁语 cor（心）。au = à + le。","ex":[["L'hôtel est situé au cœur de la ville.","酒店位于市中心。"],["Le sujet est au cœur du débat.","这个话题是辩论的核心。"],["Nous sommes au cœur de l'été.","我们正值盛夏。"]],"co":[["au cœur de la ville","在市中心"],["au cœur du problème","在问题的核心"],["au cœur de l'hiver","在隆冬"],["au centre de","在……中央"]],"sy":[["au centre de","courant","在中心，较中性"],["au milieu de","courant","在中间"],["au sein de","soutenu","在……内部"]],"fq":"高频，新闻和旅游文字中很常见。","me":"cœur = 心脏，身体的中心；au cœur de = 在……的心脏位置。","tr":{"zh":"这家餐厅在老城区的中心。","fr":"Ce restaurant est au cœur de la vieille ville.","alt":"Ce restaurant est en plein centre de la vieille ville.","note":"au cœur de + 名词，抽象和具体地点都能用。"}},
 "Au pied de": {"pos":"loc. prép. 介词短语；pied 阳性名词，复数 pieds","s":"在……脚下；在……底部。常指山、墙、树、楼梯、床的底部，au pied de la montagne / du lit / de l'arbre。","ipa":"[o pje də]","ph":"pied 读 [pje]，d 不发音，ie 读作 [je]；au [o]。","pi":"pied 末尾的 d 不发音；不要读成 [pid]。表示「在山下」要说 au pied de，不是 sous la montagne。","et":"pied 来自拉丁语 pes, pedis（脚）。同源词：piéton、pédale。","ex":[["Le village se trouve au pied de la montagne.","村子在山脚下。"],["Le chat dort au pied du lit.","猫睡在床脚边。"]],"co":[["au pied de la montagne","在山脚下"],["au pied de l'arbre","在树下"],["au pied du mur","无路可退，面对难题"],["mettre à pied","停职；解雇"]],"sy":[["sous","courant","在……下面，更泛"],["en bas de","courant","在……下面，更日常"],["à la base de","courant","在……的底部"]],"fq":"中高频，描写位置时常用。","me":"pied = 脚，山也有「脚」。","tr":{"zh":"我们在塔脚下等你。","fr":"On t'attend au pied de la tour.","alt":"On se retrouve en bas de la tour.","note":"au pied de + 名词；de + le 要缩合为 du。"}},
 "Au profit de": {"pos":"loc. prép. 介词短语；profit 阳性名词，复数 profits","s":"为了……的利益；让给……；向……倾斜。可以是「义演、募捐给某人」：un concert au profit des enfants；也可以是「牺牲 A 来让 B 得利」：renoncer à A au profit de B。","ipa":"[o pʁɔ.fi də]","ph":"profit 读 [pʁɔ.fi]，结尾 t 不发音；au [o]。","pi":"profit 的 t 不发音，与英语 profit 不同；不要读成 [pʁɔ.fit]。","et":"profit 来自拉丁语 profectus（进步，收益），与动词 profiter 同源。","ex":[["Il a renoncé à son poste au profit de son collègue.","他放弃职位，让给了同事。"],["Ce concert est organisé au profit des enfants malades.","这场音乐会是为患病儿童义演。"]],"co":[["au profit de qqn","为了某人的利益"],["un concert au profit de","为……义演的音乐会"],["renoncer à qqch au profit de","为了……而放弃"],["tirer profit de","从……中获利"]],"sy":[["en faveur de","courant","有利于，支持"],["pour le bien de","courant","为了……好处"],["à l'avantage de","soutenu","对……有利"]],"fq":"中频，偏书面，新闻中常见。","me":"profit（利益）+ au：把利益归给对方。","tr":{"zh":"这场义卖的收入将捐给慈善组织。","fr":"La recette de la vente ira au profit d'une association.","alt":"L'argent sera donné à une association.","note":"au profit de + 名词，常用于捐款和让位。"}},
 "Dans le cadre de": {"pos":"loc. prép. 介词短语；cadre 阳性名词，复数 cadres","s":"在……框架内；作为……的一部分；在……范围内。非常常用的书面和公文用语，说明「某事属于哪一个活动或计划」。cadre 本义是「框、画框」，也指「管理干部」。","ipa":"[dɑ̃ lə kadʁ də]","ph":"dans 读 [dɑ̃]，s 不发音；cadre 读 [kadʁ]，结尾 -e 不发音，-dre 要读出 d 和 r。","pi":"cadre 末尾的 e 不发音，但 dr 要读清楚 [kadʁ]；注意 dans le cadre de 不接动词原形。","et":"cadre 借自意大利语 quadro（方形），最终来自拉丁语 quadrum（方形，四方）。","ex":[["Il a voyagé au Japon dans le cadre de son travail.","他因工作去了日本。"],["Cet événement a lieu dans le cadre du festival.","这项活动是音乐节的一部分。"]],"co":[["dans le cadre de + 名词","在……框架内；作为……的一部分"],["dans le cadre de la loi","在法律框架内"],["dans ce cadre","在这个框架下"],["un cadre","画框；管理干部"]],"sy":[["à l'occasion de","courant","在……之际"],["lors de","courant","在……时"],["au titre de","soutenu","以……名义"]],"fq":"高频，工作、新闻、公文中很常用。","me":"cadre = 框；dans le cadre de = 在框里做事。","tr":{"zh":"我们在这次项目的框架内开了一个会。","fr":"Nous avons organisé une réunion dans le cadre de ce projet.","alt":"On a fait une réunion pour ce projet.","note":"dans le cadre de + 名词，不能直接接动词。"}},
 "En matière de": {"pos":"loc. prép. 介词短语；matière 阴性名词，复数 matières","s":"在……方面；就……而言。引出一个领域：en matière d'écologie / de sécurité / de santé。matière 本义是「物质；科目」。","ipa":"[ɑ̃ ma.tjɛʁ də]","ph":"en 读 [ɑ̃]；matière 读 [ma.tjɛʁ]，ti 读 [tj]；è 读 [ɛ]；元音开头的词前 de 要省音：en matière d'écologie。","pi":"matière 是阴性名词，所以不能写成 en matier；de 遇到元音开头要写 d'。","et":"matière 来自拉丁语 materia（物质，木料）。同源词：matériel、matériau。","ex":[["En matière d'écologie, Thomas sait tout.","在生态方面，托马斯什么都懂。"],["Il est exigeant en matière de qualité.","他对质量要求很高。"]],"co":[["en matière de + 名词","在……方面"],["en matière de sécurité","在安全方面"],["en matière d'éducation","在教育方面"],["en la matière","在这方面"]],"sy":[["dans le domaine de","courant","在……领域"],["quant à","courant","至于"],["côté + 名词","familier","在……方面，口语"]],"fq":"中高频，评论和公文常见。","me":"matière = 物质/科目；en matière de = 在这一「科目」上。","tr":{"zh":"在饮食方面，他很讲究。","fr":"En matière de nourriture, il est très exigeant.","alt":"Côté nourriture, il est très exigeant.","note":"en matière de + 名词；元音前写作 d'。"}},
 "Consister à": {"pos":"v. 第一组动词，-er 动词；consister à + 动词原形 / consister en + 名词","s":"在于；就是（做某事）。consister à + 不定式 = 「内容就是做……」；consister en + 名词 = 「由……组成」；consister dans + 名词 = 「在于……」。","ipa":"[kɔ̃.sis.te a]","ph":"con 读鼻化音 [kɔ̃]；sis 的 s 读 [s]；动词变位 il consiste [kɔ̃.sist]，ils consistent [kɔ̃.sist]（-ent 不发音）。","pi":"介词容易混：consister à + 动词，consister en + 名词；不要说 consister de。","et":"来自拉丁语 consistere（站住，停留，由……构成）。同源：consistance（稠度；稳定）。","ex":[["Mon travail consiste à répondre aux clients.","我的工作就是回答客户。"],["La solution consiste à attendre.","办法就是等待。"],["Le menu consiste en trois plats.","套餐由三道菜组成。"]],"co":[["consister à + 不定式","在于做某事"],["consister en + 名词","由……组成"],["en quoi consiste…?","……具体是什么？"],["consister dans + 名词","在于……"]],"sy":[["être constitué de","courant","由……组成"],["se résumer à","courant","归结为"],["comporter","soutenu","包含，包括"]],"fq":"中高频，说明工作内容、方法时常用。","me":"con + sister：和（con）立在一起：「内容站在……上」。","tr":{"zh":"我的工作就是安排会议。","fr":"Mon travail consiste à organiser des réunions.","alt":"En gros, mon boulot, c'est d'organiser des réunions.","note":"consister à + 动词原形。"}},
 "Donner la parole à": {"pos":"loc. verbale；donner 第一组动词，助动词 avoir；parole 阴性名词","s":"让……发言，请……讲话。主持人、老师、主席常用。donner la parole à qqn；反义 retirer la parole à qqn（不让某人再说）。parole 在这里是「发言权」，不是「语言」。","ipa":"[dɔ.ne la pa.ʁɔl a]","ph":"donner [dɔ.ne]；parole 读 [pa.ʁɔl]，o 是开口的 [ɔ]；à 与后面名词连读时不额外加音。","pi":"donner la parole à + 人，不说 donner la parole de；parole 的 r 是喉音 [ʁ]。","et":"parole 来自晚期拉丁语 parabola（比喻，后来指「话」）；与 parler 同源。","ex":[["Le professeur donne la parole aux élèves.","老师让学生发言。"],["Je donne la parole à Madame Martin.","我请马丁女士发言。"],["Il demande la parole.","他请求发言。"]],"co":[["donner la parole à qqn","让某人发言"],["prendre la parole","发言"],["demander la parole","请求发言"],["couper la parole à qqn","打断某人说话"]],"sy":[["faire parler","courant","让……说话"],["inviter à s'exprimer","soutenu","请……发表意见"]],"fq":"中频，会议、课堂常用。","me":"parole = 说话的权利，像「把麦克风给某人」。","tr":{"zh":"主持人把发言权交给了第一位客人。","fr":"Le présentateur donne la parole au premier invité.","alt":"Le présentateur laisse parler le premier invité.","note":"donner la parole à + 人；à + le 缩合为 au。"}},
 "Entrer par effraction": {"pos":"loc. verbale；entrer 第一组动词，助动词 être；effraction 阴性名词","s":"破门而入，撬门闯入。指小偷、闯入者通过打破门窗、撬锁进入。entrer 是移动动词，复合过去时用 être：ils sont entrés。","ipa":"[ɑ̃.tʁe paʁ ɛ.fʁak.sjɔ̃]","ph":"entrer [ɑ̃.tʁe]；effraction 读 [ɛ.fʁak.sjɔ̃]，ff 只读一个 f，tion 读 [sjɔ̃]。","pi":"effraction 双 f 但只读一个 [f]；entrer 的复合过去时用 être；tion 在这里读 [sjɔ̃]，不是 [ʃɔ̃]。","et":"effraction 来自拉丁语 effractio，源于 effringere（打碎，撬开）。同源：fracture（骨折）。","ex":[["Les voleurs sont entrés par effraction.","小偷破门而入。"],["La police enquête sur un vol avec effraction.","警方在调查一起撬锁盗窃案。"]],"co":[["entrer par effraction dans + 地点","破门闯入某处"],["un vol avec effraction","入室盗窃（撬门）"],["porte forcée","被撬开的门"],["cambrioler","入室盗窃"]],"sy":[["cambrioler","courant","入室盗窃（动词）"],["s'introduire de force","soutenu","强行进入"],["forcer la porte","courant","撞开门"]],"fq":"中频，新闻和法律场合常见。","me":"effraction 里有 fract，像 fracture：把东西「弄碎」再进去。","tr":{"zh":"有人昨晚破门进了我们的商店。","fr":"Quelqu'un est entré par effraction dans notre magasin hier soir.","alt":"Hier soir, des gens ont cambriolé notre magasin.","note":"entrer 用 être；effraction 前面不加冠词。"}},
 "Essuyer des critiques": {"pos":"loc. verbale；essuyer 第一组动词，助动词 avoir（现在时 j'essuie，u→ui 变化）","s":"遭到批评，挨骂。essuyer 本义是「擦干」，引申为「承受（不好的事）」：essuyer un refus, un échec, une défaite。后面常接负面的东西。","ipa":"[e.sɥi.je de kʁi.tik]","ph":"essuyer 读 [e.sɥi.je]（uy = [ɥi]），变位 j'essuie [e.sɥi]；critiques 读 [kʁi.tik]，qu = [k]。","pi":"essuyer 变位时 y 变 i（j'essuie, tu essuies, nous essuyons）；critique 与英语 critic 相近，别拼成 critic。","et":"essuyer 来自俗拉丁语 *exsuctare，原义「除去水分」；critique 来自希腊语 kritikos（判断的）。","ex":[["Le maire a essuyé de nombreuses critiques.","市长遭到了许多批评。"],["L'équipe a essuyé une lourde défaite.","球队遭受了惨败。"]],"co":[["essuyer des critiques","遭到批评"],["essuyer un échec / un refus","遭遇失败 / 被拒绝"],["essuyer un orage","遇上暴风雨"],["essuyer la table","擦桌子"]],"sy":[["subir","courant","承受，遭受"],["encaisser","familier","忍受打击，扛住"],["recevoir","courant","接受，更中性"]],"fq":"中频，新闻评论常用。","me":"essuyer = 擦；把「别人扔来的批评」也一并接住。","tr":{"zh":"这个新政策遭到了很多批评。","fr":"La nouvelle politique a essuyé beaucoup de critiques.","alt":"La nouvelle politique s'est fait critiquer.","note":"essuyer 用 avoir；同类宾语：un échec, un refus。"}},
 "Être dépourvu(e) de": {"pos":"loc. adj. 形容词短语；dépourvu，阴性 dépourvue；后接 de + 名词","s":"缺乏……，没有……。形容词 dépourvu 的搭配：être dépourvu de qqch。书面语，语气偏正式；阴性用 dépourvue，复数 dépourvus / dépourvues。","ipa":"[ɛtʁ de.puʁ.vy də]","ph":"être [ɛtʁ]；dépourvu [de.puʁ.vy]，ou = [u]，u = [y]；阴性 dépourvue 读音相同。","pi":"dépourvu(e) 要与主语的性数配合；de 之后常不加冠词（dépourvu d'humour）。","et":"由 dé-（去除）+ pourvu（pourvoir 的过去分词，提供）组成，字面「没被提供」。","ex":[["Cette pièce est dépourvue de fenêtres.","这个房间没有窗户。"],["Il est totalement dépourvu d'humour.","他一点幽默感都没有。"]],"co":[["être dépourvu de + 名词","缺乏……"],["dépourvu de sens","没有意义"],["dépourvu d'humour","毫无幽默感"],["au dépourvu","措手不及"]],"sy":[["manquer de","courant","缺少，最日常"],["être privé de","courant","被剥夺，没有"],["sans","courant","没有，最简单"]],"fq":"中频，偏书面。","me":"dé- + pourvu：没有被「配备」的东西。","tr":{"zh":"这条路完全没有路灯。","fr":"Cette route est complètement dépourvue d'éclairage.","alt":"Sur cette route, il n'y a aucune lumière.","note":"dépourvu(e) 与主语性数配合；de 后面通常不加冠词。"}},
 "Être en demande de": {"pos":"loc. verbale；demande 阴性名词，être 为助动词","s":"对……有需求；在寻求……；在要求……。主语多是人或群体，表示「他们想要某物、需要某物」：être en demande de reconnaissance（渴望被认可）。与 demande 的英语近义词不同，这里不是「需求量」。","ipa":"[ɛtʁ ɑ̃ də.mɑ̃d də]","ph":"en 读 [ɑ̃]；demande 读 [də.mɑ̃d]，an = [ɑ̃]，结尾 d 要读出；第二个 de 轻读。","pi":"demande 末尾的 d 要读出来（阴性词），别读成 [də.mɑ̃]；这个短语较新，偏媒体和心理学语言。","et":"demande 是动词 demander 的名词形式，来自拉丁语 demandare（托付，委托）。短语本身是较新的构式。","ex":[["Les citoyens sont en demande de plus d'espaces verts.","市民要求更多绿地。"],["Les jeunes sont en demande de reconnaissance.","年轻人渴望得到认可。"]],"co":[["être en demande de + 名词","渴望；需要"],["être demandeur de","表达需求，想要"],["une forte demande","需求旺盛"],["répondre à une demande","满足需求"]],"sy":[["être demandeur de","courant","有需求，想要"],["réclamer","courant","要求，呼吁"],["avoir besoin de","courant","需要，最日常"]],"fq":"中低频，新闻、社会话题中出现。","me":"en demande = 处于「提出需求」的状态。","tr":{"zh":"学生们希望有更多的实践课。","fr":"Les étudiants sont en demande de plus de cours pratiques.","alt":"Les étudiants voudraient plus de cours pratiques.","note":"être en demande de + 名词；日常口语多用 vouloir。"}},
 "Faire l'unanimité": {"pos":"loc. verbale；faire 不规则动词，助动词 avoir；unanimité 阴性名词","s":"获得一致认同，让所有人都赞同。最常见的是否定形式：ne pas faire l'unanimité =「并非人人赞同，有争议」。","ipa":"[fɛʁ ly.na.ni.mi.te]","ph":"faire 读 [fɛʁ]；l'unanimité 读 [ly.na.ni.mi.te]，l' 与 u 连读；unanimité 四个音节。","pi":"faire 的 ai 读 [ɛ]，不是 [e] 也不是 [ɛj]；用 l'unanimité，不是 une unanimité。","et":"unanimité 来自拉丁语 unanimitas，由 unus（一）+ animus（心，精神）组成，字面「一条心」。","ex":[["Ce projet ne fait pas l'unanimité.","这个项目没有获得一致认同。"],["Cette décision fait l'unanimité.","这个决定得到所有人的赞同。"],["Le nouveau directeur ne fait pas l'unanimité.","新主管并不是人人都认可。"]],"co":[["ne pas faire l'unanimité","不是人人都赞同"],["à l'unanimité","全票通过，一致地"],["voter à l'unanimité","一致表决通过"],["faire consensus","达成共识"]],"sy":[["faire consensus","courant","形成共识"],["être consensuel","soutenu","能让各方接受的"],["diviser","courant","（反义）引起分歧"]],"fq":"中高频，新闻评论常用，多用否定。","me":"unanimité = un + âme：大家「一条心」。","tr":{"zh":"这部新电影并不是人人都喜欢。","fr":"Ce nouveau film ne fait pas l'unanimité.","alt":"Tout le monde n'aime pas ce nouveau film.","note":"ne pas faire l'unanimité 是新闻里的固定说法。"}},
 "Faire la queue": {"pos":"loc. verbale；faire 助动词 avoir；queue 阴性名词，复数 queues","s":"排队。queue 本义是「尾巴」，引申为「队伍的尾部」。faire la queue 是排队等候；也说 la file d'attente（等候的队伍）。","ipa":"[fɛʁ la kø]","ph":"queue 读 [kø]，qu = [k]，eu = [ø]，后面的 ue 不读。","pi":"queue 拼写有 5 个字母但只读 [kø]；不要读成 [kø.ə]。别和 file（队伍）混用：faire la queue / faire la file 都可以说。","et":"queue 来自拉丁语 cauda（尾巴）。","ex":[["Nous avons dû faire la queue pendant une heure.","我们不得不排了一小时队。"],["Il y a beaucoup de monde qui fait la queue.","有很多人在排队。"]],"co":[["faire la queue","排队"],["une longue queue","长长的队伍"],["à la queue leu leu","排成一路纵队"],["la queue du chat","猫的尾巴"]],"sy":[["faire la file","courant","排队（也可）"],["patienter","soutenu","耐心等候"]],"fq":"极高频，日常生活必备。","me":"queue = 尾巴：站在队伍的「尾巴」上。","tr":{"zh":"周六早上，面包店门口总是在排队。","fr":"Le samedi matin, il y a toujours la queue devant la boulangerie.","alt":"Le samedi matin, les gens font la queue devant la boulangerie.","note":"il y a la queue = 有人排队，也是常见说法。"}},
 "Faire le mur": {"pos":"loc. verbale，familier；faire 助动词 avoir","s":"翻墙溜出去，偷偷跑出去（学校、宿舍、军营等）。多指未成年人或学生不告诉家长或老师就溜走。口语，偏幽默。","ipa":"[fɛʁ lə myʁ]","ph":"mur 读 [myʁ]，u = [y]，r 为喉音 [ʁ]，不是 [mu]。","pi":"mur 的 u 是 [y]，别读成 [muʁ]；注意与 mûr（成熟的）同音但不同拼写。","et":"mur 来自拉丁语 murus（墙）。短语源自学生或士兵翻墙溜出去的说法；确切来历不确定。","ex":[["L'adolescent a fait le mur pour aller à la fête.","青少年翻墙去参加派对。"],["Il a fait le mur de l'internat hier soir.","他昨晚溜出了寄宿学校。"]],"co":[["faire le mur","翻墙偷偷出去"],["faire le mur de l'internat","翻墙溜出寄宿学校"],["sauter par-dessus le mur","跳过墙去"]],"sy":[["s'échapper","courant","逃出去，更中性"],["s'esquiver","soutenu","悄悄溜走"],["se faire la belle","argot","越狱；溜走"]],"fq":"中频，口语。","me":"字面「做墙」：其实是翻过那堵墙。","tr":{"zh":"他半夜翻墙溜出去找朋友。","fr":"Il a fait le mur en pleine nuit pour retrouver ses amis.","alt":"Il s'est échappé en douce la nuit pour voir ses amis.","note":"faire le mur 是口语，作文里少用。"}},
 "Faire polémique": {"pos":"loc. verbale；faire 助动词 avoir；polémique 阴性名词","s":"引起争议，引发争论。事件、言论、电影、政策等「掀起公开争论」。也说 faire débat；polémique 本身是「论战，争论」，常带有火药味。","ipa":"[fɛʁ pɔ.le.mik]","ph":"polémique 读 [pɔ.le.mik]，é 读 [e]，qu = [k]，结尾 -e 不读。","pi":"polémique 的 é 带重音；qu 读 [k]；别和英语 polemic 的读音混淆。","et":"来自希腊语 polemikos（战争的），源于 polemos（战争）。","ex":[["Ce film a fait polémique à sa sortie.","这部电影上映时引起争议。"],["Ses propos ont fait polémique.","他的话引发了争议。"]],"co":[["faire polémique","引起争议"],["alimenter la polémique","加剧争论"],["une polémique enfle","争论越闹越大"],["éviter la polémique","避免争论"]],"sy":[["faire débat","courant","引发辩论（语气较温和）"],["faire scandale","courant","引发丑闻"],["susciter la controverse","soutenu","引起争议"]],"fq":"中高频，新闻常见。","me":"polémique 的词根 polem- 是「战争」：吵起来像打仗。","tr":{"zh":"他在电视上的发言引起了争议。","fr":"Ses propos à la télé ont fait polémique.","alt":"Ce qu'il a dit à la télé a fait scandale.","note":"faire polémique 前后不加冠词。"}},
 "Jouer sur": {"pos":"loc. verbale；jouer 第一组动词，助动词 avoir；后接 sur + 名词","s":"利用（情绪、弱点、因素）；在……上做文章；玩弄。jouer sur les mots（玩文字游戏）、jouer sur les émotions（利用情绪）、jouer sur les deux tableaux（两头押注）。","ipa":"[ʒwe syʁ]","ph":"jouer 读 [ʒwe]，ou = [w]；sur 读 [syʁ]，u = [y]，r 是喉音。","pi":"jouer 与 sur 之间不连读；sur 的 u 是 [y]；jouer à 是玩游戏、jouer de 是演奏乐器，jouer sur 是「利用」。","et":"jouer 来自拉丁语 iocari（开玩笑，玩耍），与 joie 不同源。","ex":[["Les publicités jouent sur nos émotions.","广告利用我们的情绪。"],["Il joue sur les mots.","他在玩文字游戏。"],["Ce politicien joue sur la peur.","这位政客利用恐惧。"]],"co":[["jouer sur les mots","玩文字游戏，咬文嚼字"],["jouer sur les émotions","利用情绪"],["jouer sur les deux tableaux","两头讨好"],["jouer sur la peur","利用恐惧"]],"sy":[["exploiter","courant","利用，开发"],["manipuler","courant","操纵"],["tirer parti de","courant","充分利用"]],"fq":"中频，常用于评论。","me":"jouer sur = 在某个「弦」上弹：拨动对方的情绪。","tr":{"zh":"这则广告利用了孩子们的好奇心。","fr":"Cette publicité joue sur la curiosité des enfants.","alt":"Cette pub exploite la curiosité des enfants.","note":"jouer sur + 名词 = 利用；jouer à / de 意思不同。"}},
 "N'en pas finir de...": {"pos":"loc. verbale；ne… pas en finir de + 不定式（常见顺序：n'en finit pas de）","s":"没完没了地……，老是……。多带有「烦、久」的意思：Il n'en finit pas de parler。en 在这里指代「这件事」，不要去掉。","ipa":"[nɑ̃ fi.ni pa də]","ph":"n'en finit 读 [nɑ̃.fi.ni]，en = [ɑ̃]，finit 的 t 不读；pas [pa]；de 轻读 [də]。","pi":"en 不能省：n'en finit pas de；ne 和 pas 把 en finit 夹在中间；不要说 n'est pas fini de。","et":"finir 来自拉丁语 finire（结束），与 fin 同源。en 在此指「这件事」，是习惯用法。","ex":[["Il n'en finit pas de parler.","他说个没完。"],["Les travaux n'en finissent pas de durer.","施工没完没了。"]],"co":[["n'en plus finir","没完没了"],["ne pas en finir de + 不定式","没完没了地做某事"],["à n'en plus finir","没完没了的"],["des files d'attente à n'en plus finir","长得没头的队伍"]],"sy":[["ne pas arrêter de","courant","不停地做某事"],["continuer à","courant","继续做"],["ne cesser de","soutenu","不断地，书面"]],"fq":"中频，口语和写作都用。","me":"en finir = 结束这件事；ne… pas = 总也结束不了。","tr":{"zh":"她说个没完，真让人受不了。","fr":"Elle n'en finit pas de parler, c'est insupportable.","alt":"Elle ne s'arrête pas de parler, c'est insupportable.","note":"n'en finit pas de + 不定式；en 不可省。"}},
 "N'être bon qu'à...": {"pos":"loc. verbale；ne… que 限制结构 + à + 不定式","s":"只配……，只能用来……。多含贬义：Ce vieil outil n'est bon qu'à être jeté。ne… que 表示「只」，bon à + 不定式表示「适合做」，合在一起是「只适合做」。","ipa":"[nɛtʁ bɔ̃ ka]","ph":"n'est 读 [nɛ]；bon 鼻化 [bɔ̃]；qu'à 读 [ka]；整体连读，qu 读 [k]。","pi":"ne… que 不是否定，是「只」；qu'à 要缩写，a 前面加 qu'；bon 读鼻化元音，n 不读。","et":"由 ne… que（只）+ bon à（适合）组成，是固定的限定结构。","ex":[["Ce vieil outil n'est bon qu'à être jeté.","这件旧工具只能扔掉。"],["Cette voiture n'est bonne qu'à la casse.","这辆车只配报废。"]],"co":[["n'être bon qu'à + 不定式","只配做某事"],["n'être bon à rien","一无是处"],["bon à jeter","该扔掉的"],["n'être capable que de","只会"]],"sy":[["n'être bon à rien","courant","一无是处，更强"],["ne servir qu'à","courant","只能用来"],["bon pour la poubelle","familier","只配扔进垃圾桶"]],"fq":"中低频，口语带贬义。","me":"ne… que + bon à：只有「去……」这件事才好用。","tr":{"zh":"这台旧电脑只配拿去回收了。","fr":"Ce vieil ordinateur n'est bon qu'à être recyclé.","alt":"Ce vieil ordi ne sert plus qu'à être recyclé.","note":"n'être bon qu'à + 动词原形，带贬义。"}},
 "Porter/Déposer une plainte": {"pos":"loc. verbale；porter plainte（不带冠词）/ déposer une plainte（带冠词），两者都是第一组动词，助动词 avoir","s":"报案；提出控告。porter plainte contre qqn（控告某人）、porter plainte pour vol（为盗窃报案）；déposer une plainte 稍正式，常去警察局（au commissariat）办理。","ipa":"[pɔʁ.te plɛ̃t]","ph":"porter [pɔʁ.te]；plainte 读 [plɛ̃t]，ain = [ɛ̃]，t 要读出；déposer 读 [de.po.ze]。","pi":"porter plainte 中 plainte 不带冠词，déposer une plainte 带冠词；plainte 末尾的 t 要读出。","et":"plainte 是 plaindre 的名词形式，来自拉丁语 plangere（捶胸痛哭），与「抱怨」同源。","ex":[["Elle a décidé de porter plainte pour vol.","她决定为盗窃报案。"],["Il a déposé une plainte contre son voisin.","他控告了他的邻居。"]],"co":[["porter plainte contre qqn","控告某人"],["porter plainte pour vol","为盗窃报案"],["déposer une plainte","提出控告"],["retirer sa plainte","撤诉"]],"sy":[["poursuivre en justice","soutenu","起诉"],["signaler","courant","报告，举报"],["dénoncer","courant","揭发"]],"fq":"中高频，生活和新闻常用。","me":"plainte（呻吟、抱怨）→ 正式把抱怨「递」（déposer）出去。","tr":{"zh":"他们去警察局报了案。","fr":"Ils sont allés porter plainte au commissariat.","alt":"Ils ont déposé une plainte au commissariat.","note":"porter plainte 不带冠词；déposer une plainte 带冠词。"}},
 "Pouvoir se le permettre": {"pos":"loc. verbale；pouvoir 不规则动词；se permettre qqch（代动词）","s":"负担得起；经得起（花费或后果）。le 可指代前面提到的东西，视情况换成 la、les：Je ne peux pas me la permettre。后面也可接 de + 不定式：je ne peux pas me permettre de partir。","ipa":"[pu.vwaʁ sə lə pɛʁ.mɛtʁ]","ph":"pouvoir [pu.vwaʁ]；se [sə]；le [lə]；permettre 读 [pɛʁ.mɛtʁ]，tt 读一个 t，结尾 -tre 读 [tʁ]。","pi":"permettre 的 tt 只读一个 [t]；le/la/les 要与被指代的名词一致；动词 pouvoir 与 se permettre 的顺序要对。","et":"permettre 来自拉丁语 permittere（放行，允许）。se permettre 字面「允许自己」。","ex":[["Cet hôtel est trop cher, je ne peux pas me le permettre.","这家酒店太贵，我负担不起。"],["Elle ne peut pas se permettre d'acheter une voiture.","她买不起车。"],["Vous pouvez vous le permettre ?","您负担得起吗？"]],"co":[["ne pas pouvoir se le / la / les permettre","负担不起"],["se permettre de + 不定式","冒昧去做；敢于做"],["se permettre un luxe","享受奢侈"],["avoir les moyens de","有能力负担"]],"sy":[["avoir les moyens de","courant","有能力，有钱做"],["se payer","familier","给自己买，花钱买"],["s'offrir","courant","给自己买"]],"fq":"中高频，谈论钱和选择时常用。","me":"permettre = 允许；se permettre = 允许自己，也就是「负担得起」。","tr":{"zh":"我不能买这辆车，太贵了。","fr":"Je ne peux pas me permettre cette voiture, elle est trop chère.","alt":"Cette voiture est trop chère, je ne peux pas me la payer.","note":"me permettre + 宾语；指代时用 le / la / les。"}},
 "Prendre l'initiative": {"pos":"loc. verbale；prendre 不规则动词，助动词 avoir；initiative 阴性名词","s":"主动（做某事）；带头。prendre l'initiative de + 不定式 = 主动去做；也说 avoir de l'initiative（有主动性）、par sa propre initiative（自己主动）。","ipa":"[pʁɑ̃dʁ li.ni.sja.tiv]","ph":"prendre [pʁɑ̃dʁ]；initiative 读 [i.ni.sja.tiv]，ti = [sj]（不是 [ti]），l' 与它连读。","pi":"initiative 里的 ti 读 [sj]；prendre 的 en 读 [ɑ̃]；要说 prendre l'initiative de + 动词原形，不是 prendre l'initiative à。","et":"initiative 来自拉丁语 initium（开始），与 initial、initier 同源。","ex":[["Elle a pris l'initiative d'organiser la réunion.","她主动组织了会议。"],["Il manque d'initiative.","他缺乏主动性。"]],"co":[["prendre l'initiative de + 不定式","主动做某事"],["avoir de l'initiative","有主动性"],["à l'initiative de qqn","由某人发起"],["de sa propre initiative","自己主动地"]],"sy":[["prendre les devants","courant","抢先，先发制人"],["se lancer","courant","大胆开始"]],"fq":"中高频，职场和日常都常用。","me":"initiative 从 initium（开始）来：你是「开头的人」。","tr":{"zh":"他主动给客户打了电话。","fr":"Il a pris l'initiative d'appeler le client.","alt":"C'est lui qui a appelé le client en premier.","note":"prendre l'initiative de + 动词原形。"}},
 "Tenir à coeur": {"pos":"loc. verbale；tenir 不规则动词，助动词 avoir；cœur 阳性名词","s":"放在心上；对某人来说很重要。常用结构 qqch tient à cœur à qqn；也说 avoir qqch à cœur（把……放在心上）、prendre à cœur（认真对待，很上心）。","ipa":"[tə.niʁ a kœʁ]","ph":"tenir [tə.niʁ]，e 轻读 [ə]；à 单独读 [a]；cœur [kœʁ]。变位：il tient [tjɛ̃]，ils tiennent [tjɛn]。","pi":"tenir 的变位易错：il tient / ils tiennent；cœur 的 œu 是 [œ]；表达里 cœur 不加冠词。","et":"tenir 来自拉丁语 tenere（握住）；cœur 来自拉丁语 cor。字面「抓在心上」。","ex":[["Ce projet me tient à cœur.","这个项目对我很重要。"],["Sa réussite lui tient à cœur.","他很看重自己的成功。"],["Prends tes études à cœur.","要认真对待学习。"]],"co":[["tenir à cœur à qqn","对某人很重要"],["avoir qqch à cœur","把某事放在心上"],["prendre qqch à cœur","认真对待；很上心"],["tenir à","珍惜；坚持要"]],"sy":[["importer","soutenu","要紧，重要"],["compter beaucoup","courant","很重要"],["être important pour","courant","对……很重要"]],"fq":"中高频，日常表达情感常用。","me":"tenir = 抓；à cœur = 在心上：紧紧抓在心里的事。","tr":{"zh":"这件事对我非常重要。","fr":"Cette affaire me tient vraiment à cœur.","alt":"Cette affaire est vraiment importante pour moi.","note":"me / lui tient à cœur：谁在乎，就用间接宾语代词。"}},
 "De l'hélium": {"pos":"n.m. 阳性名词，不可数（用部分冠词 de l'）","s":"氦（气）。一种很轻的惰性气体，用于气球、飞艇，也用于医学和低温实验。作不可数名词，前面用 de l'：de l'hélium。","ipa":"[e.ljɔm]","ph":"h 不发音；é 读 [e]；lium 读 [ljɔm]，um 在这里读 [ɔm]，不是 [œm]。","pi":"h 不发音，所以用 l'；hélium 的 -um 读 [ɔm]；不要读成英语 helium 的 [iː]。","et":"来自希腊语 hēlios（太阳），因为这种元素最早在太阳光谱中被发现；词尾 -ium 是元素名常见后缀。","ex":[["Le ballon est rempli d'hélium.","气球里充满了氦气。"],["L'hélium est plus léger que l'air.","氦气比空气轻。"]],"co":[["un ballon gonflé à l'hélium","充氦气的气球"],["de l'hélium liquide","液氦"],["un gaz rare","稀有气体"],["gonfler à l'hélium","充氦气"]],"sy":[["gaz rare","courant","稀有气体（类别）"],["hydrogène","courant","氢气（不同，更易燃）"]],"fq":"中低频，科学、节日气球场景。","me":"hélium ← hélios（太阳）：太阳里先找到它。","tr":{"zh":"孩子们的气球里充了氦气。","fr":"Les ballons des enfants sont gonflés à l'hélium.","alt":"On a rempli les ballons des enfants avec de l'hélium.","note":"de l'hélium 是不可数的部分冠词形式。"}},
 "Du CO2": {"pos":"n.m. 阳性名词，不可数（部分冠词 du）；读作 cé-o-deux","s":"二氧化碳。化学式 CO₂，也说 le dioxyde de carbone（正式名称）。常出现在环保、气候变化的话题里：émissions de CO2（二氧化碳排放）。","ipa":"[se.o.dø]","ph":"按字母读 C-O-deux：cé [se]、o [o]、deux [dø]；整体连读成 [se.o.dø]。","pi":"不要读成 co-deux；du 是阳性部分冠词；deux 的 x 不发音，eu = [ø]。","et":"化学符号：C = 碳（carbone），O₂ = 两个氧原子；dioxyde = di-（二）+ oxyde（氧化物）。","ex":[["Les voitures émettent du CO2.","汽车排放二氧化碳。"],["Il faut réduire les émissions de CO2.","必须减少二氧化碳排放。"]],"co":[["émissions de CO2","二氧化碳排放"],["réduire le CO2","减少二氧化碳"],["empreinte carbone","碳足迹"],["dioxyde de carbone","二氧化碳（正式名称）"]],"sy":[["dioxyde de carbone","soutenu","二氧化碳，正式名称"],["gaz carbonique","courant","碳酸气，日常叫法"]],"fq":"中高频，环保新闻常见。","me":"C-O-deux：像念字母，和英文 C-O-two 对应。","tr":{"zh":"工厂排放大量二氧化碳。","fr":"Les usines émettent beaucoup de CO2.","alt":"Les usines rejettent beaucoup de gaz carbonique.","note":"CO2 读 cé-o-deux；前面用 du 或 beaucoup de。"}},
 "Du matériel": {"pos":"n.m. 阳性名词，常作不可数（部分冠词 du）；复数 matériels 少见","s":"器材；设备；用品。指做某项活动所需的工具总称：du matériel de sport / de bureau / informatique。不可数，所以用 du，不说 des matériels。matériel 也可作形容词「物质的」。","ipa":"[ma.te.ʁjɛl]","ph":"matériel 读 [ma.te.ʁjɛl]，é = [e]，ie 在这里读 [jɛ]；结尾 -el 读 [ɛl]，l 要发音。","pi":"和 matériaux（材料，复数）不同；不要把 matériel 当作可数名词；末尾 l 要读出来。","et":"来自拉丁语 materialis，源于 materia（物质，木料）。同源：matière、matériau。","ex":[["J'ai acheté du matériel de sport.","我买了体育器材。"],["Le matériel est cher.","这批设备很贵。"],["Apportez votre propre matériel.","请自带器材。"]],"co":[["du matériel de bureau","办公用品"],["du matériel informatique","电脑设备"],["du matériel de camping","露营装备"],["louer du matériel","租用设备"]],"sy":[["équipement","courant","装备，设备"],["outils","courant","工具"],["fournitures","courant","办公或学习用品"]],"fq":"高频，日常常用。","me":"matér- 像 material：做事要用的「材料」。","tr":{"zh":"我们需要更多的实验器材。","fr":"Nous avons besoin de plus de matériel de laboratoire.","alt":"On a besoin de plus de matériel pour le labo.","note":"du / de plus de matériel：不可数，不加复数 s。"}},
 "L'air": {"pos":"n.m. 阳性名词，复数 airs（意义多用于「神态；曲调」）","s":"空气；风；神态；曲调。最常见：l'air（空气）、en plein air（户外）、avoir l'air + 形容词（看起来）、un air de musique（曲子）。","ipa":"[ɛʁ]","ph":"ai 读 [ɛ]，r 是喉音 [ʁ]；l'air 读 [lɛʁ]，只有一个音节。","pi":"和 aire（面积；休息区）、ère（时代）、hère 同音，要看拼写区分；air 不是阴性。","et":"来自拉丁语 aer，源于希腊语 aēr（空气）。同源：aérien（空中的）、aéroport。","ex":[["L'air est pur à la montagne.","山里的空气很清新。"],["Tu as l'air fatigué.","你看起来很累。"],["Ouvre la fenêtre, j'ai besoin d'air.","把窗户打开，我需要透透气。"]],"co":[["en plein air","在户外"],["avoir l'air + 形容词","看起来……"],["prendre l'air","出去透透气"],["l'air conditionné","空调"]],"sy":[["atmosphère","soutenu","大气；氛围"],["apparence","courant","外观，神态"],["mélodie","courant","曲调"]],"fq":"极高频，日常必备。","me":"air ≈ aérien / aéroport 里的 aér-：和「天空」有关。","tr":{"zh":"我想出去透透气。","fr":"J'ai envie de prendre l'air.","alt":"J'ai besoin de sortir prendre l'air.","note":"prendre l'air = 出去透气。"}},
 "L'équivalent de": {"pos":"n.m. 阳性名词，复数 équivalents；后接 de","s":"相当于……；……的对应物。用于比较价值、数量或词语：Cela coûte l'équivalent de 10 euros。équivalent 也可作形容词「相等的」，阴性 équivalente。","ipa":"[e.ki.va.lɑ̃ də]","ph":"équivalent 读 [e.ki.va.lɑ̃]，qu = [k]，结尾 -ent 为鼻化 [ɑ̃]，t 不发音；de [də]。","pi":"équi- 中 qu 读 [k]，不是 [kw]；结尾 -ent 不是动词词尾，读 [ɑ̃]。","et":"来自拉丁语 aequivalens，由 aequus（相等的）+ valere（值）组成，字面「价值相等」。","ex":[["Cela coûte l'équivalent de dix euros.","这相当于十欧元。"],["Il n'y a pas d'équivalent en français.","法语里没有对应的词。"]],"co":[["l'équivalent de + 名词","相当于……"],["avoir son équivalent","有对应物"],["un équivalent en français","法语里的对应词"],["équivaloir à","相当于（动词）"]],"sy":[["l'équivalence","soutenu","等值；等同性"],["le pendant","soutenu","对应的另一方"],["pareil","courant","相同的，口语"]],"fq":"中高频，比较数量或词义时常用。","me":"équi- = 相等，valent = 值：价值相等。","tr":{"zh":"这个价格相当于一个月的房租。","fr":"Ce prix est l'équivalent d'un mois de loyer.","alt":"Ça coûte autant qu'un mois de loyer.","note":"l'équivalent de + 名词；de + un 变 d'un。"}},
 "L'espace": {"pos":"n.m. 阳性名词，复数 espaces","s":"太空；空间；间隔；场所。l'espace 可指宇宙空间（voyager dans l'espace）、空间（avoir de l'espace）；un espace vert（绿地）、un espace de travail（工作空间）。","ipa":"[ɛs.pas]","ph":"es 读 [ɛs]，p 要读出；pace 读 [pas]，结尾 e 不发音。","pi":"不要读成 [e.spas]；在印刷领域 espace 是阴性（une espace，字距），日常用阳性。","et":"来自拉丁语 spatium（空间，距离）。同源：spatial（空间的）。","ex":[["Il voyage dans l'espace.","他在太空旅行。"],["Il n'y a pas assez d'espace ici.","这里空间不够。"],["La ville a beaucoup d'espaces verts.","这座城市有很多绿地。"]],"co":[["l'espace (extra-atmosphérique)","外太空"],["un espace vert","绿地"],["un espace de travail","工作空间"],["gagner de l'espace","腾出空间"]],"sy":[["place","courant","地方，空位，更日常"],["cosmos","soutenu","宇宙"],["univers","courant","宇宙"]],"fq":"极高频，日常常用。","me":"espace ← spatium：像 space，太空与「空间」同一个词。","tr":{"zh":"我们的客厅空间很大。","fr":"Notre salon a beaucoup d'espace.","alt":"On a beaucoup de place dans notre salon.","note":"espace 与 place：espace 更抽象，place 更日常。"}},
 "Le coucher de soleil": {"pos":"n.m. 阳性名词，复数 couchers de soleil；也说 le coucher du soleil","s":"日落；落日时分。le coucher de soleil 指太阳落山的时间或景象；反义 le lever du soleil（日出）。coucher 作名词时指「就寝；落山」。","ipa":"[ku.ʃe də sɔ.lɛj]","ph":"coucher 读 [ku.ʃe]，ou = [u]，ch = [ʃ]；soleil 读 [sɔ.lɛj]，-eil = [ɛj]。","pi":"soleil 末尾 -eil 读 [ɛj]，l 不单独读；coucher 的 er 读 [e]。","et":"coucher 来自拉丁语 collocare（安放）；soleil 来自俗拉丁语 *soliculus，源于 sol（太阳）。","ex":[["Le coucher de soleil est beau.","日落很美。"],["Nous avons dîné face au coucher de soleil.","我们面对落日吃了晚饭。"]],"co":[["au coucher du soleil","在日落时分"],["un beau coucher de soleil","美丽的日落"],["le lever du soleil","日出"],["admirer le coucher de soleil","欣赏日落"]],"sy":[["crépuscule","littéraire","黄昏，暮色"],["tombée de la nuit","courant","天黑时"],["lever du soleil","courant","（反义）日出"]],"fq":"中频，旅游和日常叙述常见。","me":"coucher = 躺下：太阳也要去「睡觉」了。","tr":{"zh":"我们在海边看日落。","fr":"Nous regardons le coucher de soleil au bord de la mer.","alt":"On admire le coucher de soleil sur la plage.","note":"du / de soleil 两种形式都可以。"}},
 "Le décollage": {"pos":"n.m. 阳性名词，复数 décollages","s":"（飞机、火箭）起飞；（经济）起步。le décollage de l'avion 是飞机起飞；décollage économique 指经济腾飞。反义 l'atterrissage（降落）。","ipa":"[de.kɔ.laʒ]","ph":"décollage 读 [de.kɔ.laʒ]，é = [e]，o 在这里是开口的 [ɔ]，ll 读一个 l，结尾 -age = [aʒ]。","pi":"ll 读一个 [l]；-age 读 [aʒ]，不是 [ɑ̃ʒ]。décollage 与 collage（粘贴）不同。","et":"由 dé-（脱离）+ coller（粘）+ -age 构成：字面「从地上脱离」。coller 来自 colle（胶水），源于希腊语 kolla。","ex":[["Le décollage est prévu à huit heures.","起飞时间定在八点。"],["Le décollage de la fusée est retardé.","火箭起飞被推迟了。"]],"co":[["l'heure de décollage","起飞时间"],["autorisation de décollage","起飞许可"],["piste de décollage","起飞跑道"],["décollage économique","经济腾飞"]],"sy":[["envol","soutenu","起飞，起势"],["départ","courant","出发"],["atterrissage","courant","（反义）降落"]],"fq":"中频，机场、新闻用语。","me":"dé + coller：把「粘住地面」的状态撕掉。","tr":{"zh":"起飞前请系好安全带。","fr":"Attachez votre ceinture avant le décollage.","alt":"Mettez votre ceinture avant le décollage.","note":"décollage 反义是 atterrissage。"}},
 "Le dépaysement": {"pos":"n.m. 阳性名词，复数 dépaysements","s":"换环境的新鲜感；到陌生地方的离乡感。常是积极的：旅行带来 dépaysement（异国新鲜感）。也可能带有「不适应」的意思。动词 dépayser 指「使换个环境」。","ipa":"[de.pe.iz.mɑ̃]","ph":"dépaysement 读 [de.pe.iz.mɑ̃]，ay 读 [e.i]，s 在元音间读 [z]，ment 读 [mɑ̃]。","pi":"pays 的 ay 读 [e.i]；s 读 [z]；结尾 -ment 的 t 不发音。","et":"由 dé-（去除）+ pays（国家，地方）+ -ement（名词后缀）组成：把人从自己的「地方」带走。","ex":[["Le dépaysement est total.","完全换了个环境。"],["Ce voyage m'a apporté un vrai dépaysement.","这次旅行给了我真正的新鲜感。"]],"co":[["un sentiment de dépaysement","离乡的陌生感"],["chercher le dépaysement","追求换环境的新鲜感"],["dépaysement garanti","保证换个环境"],["être dépaysé(e)","不适应，换了环境"]],"sy":[["changement d'air","courant","换换空气，换个环境"],["exotisme","soutenu","异国情调"],["désorientation","soutenu","迷失方向感"]],"fq":"中频，旅游、广告常用。","me":"dé + pays：离开「自己的国家」带来的新鲜感。","tr":{"zh":"去沙漠旅行，你会有完全不同的新鲜感。","fr":"Un voyage dans le désert vous offre un dépaysement total.","alt":"Un voyage dans le désert, ça change complètement d'air.","note":"dépaysement 常与 total、garanti 连用。"}},
 "Le grand départ": {"pos":"n.m. 阳性名词；一个固定表达，复数 les grands départs","s":"大出发；动身的时刻。可指长途旅行或搬家开始的那一天：Demain, c'est le grand départ !。复数 les grands départs 指假期大迁徙（成群结队出发的日子）。","ipa":"[ɡʁɑ̃ de.paʁ]","ph":"grand 读 [ɡʁɑ̃]，d 不发音；départ 读 [de.paʁ]，结尾 t 不发音。","pi":"grand 和 départ 末尾的 d、t 都不发音；les grands départs 复数时 s 也不读。","et":"départ 是 partir 的名词形式，来自拉丁语 partire（分开）。grand = 大。","ex":[["Demain, c'est le grand départ !","明天就是大出发！"],["Les grands départs en vacances commencent vendredi.","假期大出行从星期五开始。"]],"co":[["le grand départ","大出发"],["les grands départs","假期大迁徙"],["le jour du départ","出发那天"],["prendre le départ","出发，起跑"]],"sy":[["le départ","courant","出发，最普通"],["le jour J","courant","决定性的日子"],["l'appareillage","soutenu","（船）起航"]],"fq":"中频，旅行、新闻中出现。","me":"grand + départ：很大的一次「离开」。","tr":{"zh":"明天是我们去日本的大出发。","fr":"Demain, c'est le grand départ pour le Japon !","alt":"Demain, on part au Japon !","note":"c'est le grand départ：表示激动的启程。"}},
 "Le lendemain": {"pos":"n.m. 阳性名词，复数 lendemains；常作副词用","s":"第二天；次日。指「过去或将来某个时间点之后的那一天」，不是「明天」。le lendemain matin（第二天早上）、le lendemain de la fête（派对后的第二天）。","ipa":"[lɑ̃d.mɛ̃]","ph":"lendemain 读 [lɑ̃d.mɛ̃]，en = [ɑ̃]，ain = [ɛ̃]，d 要读出。","pi":"demain 是「明天」（相对现在），lendemain 是「过去/将来某天的次日」；不要混用。le 与 lendemain 连在一起时 l' 不省略。","et":"来自古法语 l'endemain，由 le + endemain 融合而成，而 endemain 是 en + demain。","ex":[["Nous partirons le lendemain.","我们第二天出发。"],["Le lendemain matin, il neigeait.","第二天早上下雪了。"],["Le lendemain de la fête, tout le monde était fatigué.","派对第二天，大家都很累。"]],"co":[["le lendemain matin / soir","第二天早上 / 晚上"],["le lendemain de + 名词","……的第二天"],["du jour au lendemain","一夜之间"],["sans lendemain","没有后续的"]],"sy":[["le jour suivant","courant","次日，较中性"],["le surlendemain","courant","后天（再次一天）"],["la veille","courant","（反义）前一天"]],"fq":"高频，讲故事和计划时常用。","me":"le + en + demain：「在明天」被说成一个词。","tr":{"zh":"第二天，我们去了海边。","fr":"Le lendemain, nous sommes allés à la plage.","alt":"Le jour suivant, on est allés à la plage.","note":"le lendemain 讲述过去或将来；demain 讲从现在起的明天。"}},
 "Le marché noir": {"pos":"n.m. 阳性名词，复数 marchés noirs","s":"黑市；非法交易场所。指违法买卖受管制或稀缺的东西，如票、药品、外汇。au marché noir = 在黑市上。","ipa":"[maʁ.ʃe nwaʁ]","ph":"marché 读 [maʁ.ʃe]，ch = [ʃ]；noir 读 [nwaʁ]，oi = [wa]。","pi":"marché 的 ch 是 [ʃ]；不要和 marcher（走路）混淆，虽同音但意义不同；noir 在阳性名词后不变形。","et":"marché 来自拉丁语 mercatus（集市，买卖）；noir 表示「非法、秘密」，隐喻黑暗中的交易。","ex":[["Il a acheté ce billet au marché noir.","他在黑市买了这张票。"],["Pendant la guerre, le marché noir fleurissait.","战争期间，黑市十分猖獗。"]],"co":[["acheter au marché noir","在黑市购买"],["le marché noir des billets","票的黑市"],["travail au noir","非法打工"],["le marché parallèle","地下市场"]],"sy":[["marché parallèle","courant","地下市场"],["trafic","courant","走私，非法买卖"],["contrebande","courant","走私"]],"fq":"中频，新闻和历史话题。","me":"marché + noir：见不得光的黑色买卖。","tr":{"zh":"他把演唱会的票卖到了黑市上。","fr":"Il a revendu ses billets de concert au marché noir.","alt":"Il a vendu ses places de concert au marché noir.","note":"au marché noir 是固定搭配。"}},
 "Le son": {"pos":"n.m. 阳性名词，复数 sons","s":"声音；音质；音响。le son de la musique = 音乐的音质；monter le son（调大音量）；le son et la lumière（声光秀）。注意同音异义词：son（他的）、sont（是，être 的第三人称复数）。","ipa":"[sɔ̃]","ph":"son 读 [sɔ̃]，o + n 构成鼻化元音 [ɔ̃]，n 不单独发音。","pi":"son（声音）、son（他的，所有格）、sont（是）三个词同音；son 还指「麸皮」。要靠词性和语境区分。","et":"来自拉丁语 sonus（声音）。同源：sonore、sonner（响）、résonner。","ex":[["Le son de la musique est bon.","音乐的音质很好。"],["Baisse le son, s'il te plaît.","请把声音调小一点。"],["Je n'aime pas le son de sa voix.","我不喜欢他的嗓音。"]],"co":[["monter / baisser le son","调大 / 调小音量"],["un bon son","好的音质"],["le son d'une cloche","钟声"],["à grand son de trompe","大张旗鼓地"]],"sy":[["bruit","courant","噪音，杂音，指没有意义的声音"],["volume","courant","音量"],["note","courant","音符，音"]],"fq":"极高频，日常常用。","me":"son ≈ sonner：「发声」，且和 sont、son 同音。","tr":{"zh":"请把电视的声音调小一点。","fr":"Baisse le son de la télé, s'il te plaît.","alt":"Tu peux baisser le son de la télé ?","note":"baisser / monter le son 是调音量。"}},
 "Le tourisme de masse": {"pos":"n.m. 阳性名词，不可数；masse 阴性名词","s":"大众旅游；批量化的旅游。常带有批评意味：游客涌入、污染、本地人被挤走。反义 le tourisme durable（可持续旅游）、le tourisme responsable。","ipa":"[tu.ʁism də mas]","ph":"tourisme 读 [tu.ʁism]，ou = [u]，s 读 [s]，e 不发音；masse 读 [mas]。","pi":"tourisme 里的 ou 读 [u]；s 在 -isme 里读 [s]，不是 [z]；de masse 不是 de masses。","et":"tourisme 来自 tour（旅行，一圈）+ -isme；tour 源于拉丁语 tornus（车床），后指「转一圈」。","ex":[["Le tourisme de masse pollue.","大众旅游造成污染。"],["Ces plages souffrent du tourisme de masse.","这些海滩饱受大众旅游之苦。"]],"co":[["lutter contre le tourisme de masse","抵制大众旅游"],["le tourisme durable","可持续旅游"],["le tourisme culturel","文化旅游"],["les effets du tourisme de masse","大众旅游的影响"]],"sy":[["tourisme durable","courant","（反义）可持续旅游"],["surtourisme","courant","过度旅游"],["tourisme responsable","courant","负责任的旅游"]],"fq":"中频，新闻和环保话题。","me":"tourisme + masse：一大群人涌过去。","tr":{"zh":"大众旅游给这座小城带来了很多问题。","fr":"Le tourisme de masse pose beaucoup de problèmes à cette petite ville.","alt":"Avec le tourisme de masse, cette petite ville a des difficultés.","note":"de masse 表示「大规模的」，masse 用单数。"}},
 "Le virus du voyage": {"pos":"n.m. 阳性名词（virus 阳性，复数 virus）","s":"旅行瘾；爱旅行的毛病。把「爱上旅行」比作被病毒感染：avoir le virus du voyage / attraper le virus du voyage。幽默、口语化的说法。","ipa":"[vi.ʁys dy vwa.jaʒ]","ph":"virus 读 [vi.ʁys]，结尾 s 要读出；voyage 读 [vwa.jaʒ]，oy = [waj]，结尾 -age = [aʒ]。","pi":"virus 末尾 s 要读出 [vi.ʁys]；单复数形式相同；voyage 的 oy 读 [waj]。","et":"virus 来自拉丁语 virus（毒液，毒）；voyage 来自拉丁语 viaticum（旅途所需），与 voie 同源。","ex":[["J'ai attrapé le virus du voyage.","我染上了旅行瘾。"],["Depuis ce voyage, il a le virus du voyage.","自从那次旅行，他就迷上了旅行。"]],"co":[["avoir le virus du voyage","迷上旅行"],["attraper le virus de + 名词","迷上……"],["la passion du voyage","对旅行的热爱"],["le goût du voyage","旅行的爱好"]],"sy":[["le goût du voyage","courant","喜欢旅行"],["la bougeotte","familier","待不住，爱到处跑"],["l'envie de partir","courant","想出发的冲动"]],"fq":"低频，口语的比喻说法。","me":"voyage 是一种「病毒」：一旦染上就停不下来。","tr":{"zh":"自从去过意大利，我就染上了旅行瘾。","fr":"Depuis mon séjour en Italie, j'ai attrapé le virus du voyage.","alt":"Depuis l'Italie, j'ai la bougeotte.","note":"attraper le virus de + 名词，是比喻。"}},
 "Ulysse": {"pos":"n.m. 专有名词（人名），阳性","s":"尤利西斯；奥德修斯（Odysseus 的拉丁/法语名）。荷马史诗《奥德赛》中的希腊英雄，攻下特洛伊后漂流十年才回到家乡 Ithaque（伊萨卡）。常用来象征「漫长的旅行者」。","ipa":"[y.lis]","ph":"Ulysse 读 [y.lis]，u = [y]，y 读 [i]，ss 读 [s]，结尾 e 不读。","pi":"第一个 u 是 [y]，不是 [u]；第二个 y 读 [i]；不要读成 [u.lis]。","et":"拉丁语 Ulixes，是希腊语 Odysseus 的变体；法语沿用拉丁语形式。","ex":[["Ulysse est un héros grec.","尤利西斯是希腊英雄。"],["Ulysse a mis dix ans à rentrer chez lui.","尤利西斯花了十年才回到家。"]],"co":[["Ulysse et les sirènes","尤利西斯与海妖"],["l'Odyssée d'Ulysse","尤利西斯的奥德赛"],["le voyage d'Ulysse","尤利西斯的旅程"],["Heureux qui, comme Ulysse, a fait un beau voyage","杜贝莱的名句：像尤利西斯那样完成美好旅程的人是幸福的"]],"sy":[["Odysseus","littéraire","希腊语原名"],["l'Odyssée","courant","史诗名称，也指漫长的旅程"]],"fq":"中低频，文学和文化话题。","me":"Ulysse 听起来像「尤利西斯」，漂流的英雄。","tr":{"zh":"尤利西斯回家用了十年。","fr":"Ulysse a mis dix ans pour rentrer chez lui.","alt":"Il a fallu dix ans à Ulysse pour rentrer chez lui.","note":"mettre + 时间 + pour + 动词原形。"}},
 "Un ambassadeur": {"pos":"n.m. 阳性名词，阴性 une ambassadrice，复数 ambassadeurs","s":"大使；使节。也可指「形象代言人，推广者」：ambassadeur de la marque（品牌大使）。阴性 ambassadrice 指女大使，旧时也指大使夫人。","ipa":"[ɑ̃.ba.sa.dœʁ]","ph":"ambassadeur 读 [ɑ̃.ba.sa.dœʁ]，am = [ɑ̃]，-eur 读 [œʁ]，r 要读出。","pi":"am 在 b 前读鼻化 [ɑ̃]，不读 [am]；ss 读 [s]，不是 [z]；结尾 -eur 的 r 要发音。","et":"来自意大利语 ambasciatore / 奥克语，最终源头不完全确定；与 ambassade（大使馆）同源。","ex":[["Il est ambassadeur de France.","他是法国大使。"],["Elle est l'ambassadrice de cette marque.","她是这个品牌的形象大使。"],["L'ambassadeur rencontre le ministre.","大使会见部长。"]],"co":[["un ambassadeur de France","法国大使"],["l'ambassadeur de France auprès de l'ONU","法国驻联合国大使"],["un ambassadeur de la paix","和平使者"],["l'ambassade","大使馆"]],"sy":[["émissaire","soutenu","使者，特使"],["diplomate","courant","外交官"],["représentant","courant","代表"]],"fq":"中频，新闻、外交场景。","me":"ambassadeur ↔ ambassade：在大使馆（ambassade）工作的人。","tr":{"zh":"新大使明天抵达巴黎。","fr":"Le nouvel ambassadeur arrive demain à Paris.","alt":"Le nouvel ambassadeur débarque demain à Paris.","note":"阴性用 ambassadrice。"}},
 "Un argument": {"pos":"n.m. 阳性名词，复数 arguments","s":"论据；论点；理由。用来说服别人的理由，常和 donner / avancer / trouver 搭配。也指商品的「卖点」：un argument de vente。","ipa":"[aʁ.gy.mɑ̃]","ph":"ar [aʁ]；gu 在这里读 [g] 加 u [y]；结尾 -ent 读鼻化元音 [ɑ̃]，t 不发音。","pi":"结尾 -ent 读 [ɑ̃]，不发 t；r 是小舌音 [ʁ]；u 读 [y]，不是 [u]。","et":"来自拉丁语 argumentum（证明、论据），源于 arguere（表明、证明）。","ex":[["C'est un argument solide.","这是个有力的论据。"],["Il n'a pas d'argument contre mon idée.","他没有反驳我想法的论据。"]],"co":[["un argument de vente","卖点"],["avancer un argument","提出一个论据"],["un bon argument","一个好理由"]],"sy":[["raison","courant","理由，更日常"],["preuve","courant","证据；argument 是说理，preuve 是证明"]],"fq":"中高频，讨论和写作常用。","me":"argument 像英语 argument，但法语主要指「理由」，不一定是吵架。","tr":{"zh":"你的论据不够有力。","fr":"Ton argument n'est pas assez solide.","alt":"Ton argument ne tient pas vraiment la route.","note":"solide 修饰 argument，阳性不变形。"}},
 "Un astronaute": {"pos":"n.m./n.f. 名词，男女同形：un / une astronaute，复数 astronautes","s":"宇航员；太空人。阴阳同形，女宇航员说 une astronaute。法国官方也说 spationaute，欧洲航天局常用 astronaute。","ipa":"[as.tʁɔ.not]","ph":"as-tro-naute；au 读 [o]；结尾 e 不发音，t 要发出。","pi":"au 读 [o]，不是 [au]；结尾 t 要读出来 [t]；女性不用改形，只改冠词。","et":"希腊语词根：astron（星）+ nautês（水手、航行者），字面是「星际航行者」。","ex":[["L'astronaute va sur la lune.","宇航员飞往月球。"],["Cette astronaute a passé six mois dans l'espace.","这位宇航员在太空待了六个月。"]],"co":[["devenir astronaute","成为宇航员"],["une astronaute française","一位法国女宇航员"],["une combinaison d'astronaute","宇航服"]],"sy":[["spationaute","courant","法语特有说法，同义"],["cosmonaute","courant","俄罗斯的宇航员"]],"fq":"中频，新闻和科普里常见。","me":"astro（星）+ naute（航海者）：像 nautique 的「航海」。","tr":{"zh":"我想当宇航员。","fr":"Je voudrais devenir astronaute.","alt":"Plus tard, je veux être astronaute.","note":"表示职业时，devenir / être 后常省略冠词。"}},
 "Un attrait": {"pos":"n.m. 阳性名词，复数 attraits","s":"吸引力；魅力。多指事物让人想要的那一点，较书面。常见 l'attrait de + 名词，或 avoir de l'attrait pour qqn。复数 des attraits 也可指（女性的）魅力。","ipa":"[a.tʁɛ]","ph":"att 双写 t 只读一个 [t]；ait 读 [ɛ]；结尾 t 不发音。","pi":"结尾 -ait 读 [ɛ]，t 不发；注意和动词 attraire 的形式区分。拼写是 tt。","et":"来自动词 attraire（吸引），拉丁语 attrahere。同族：attirer、attractif。","ex":[["Cette ville a un grand attrait.","这座城市很有魅力。"],["L'attrait de la nouveauté est fort.","新鲜事物的吸引力很强。"]],"co":[["l'attrait de la nouveauté","新鲜感的吸引力"],["avoir de l'attrait pour","对……有吸引力"],["perdre son attrait","失去吸引力"]],"sy":[["charme","courant","魅力，更常用"],["attirance","courant","吸引（多指对人的好感）"],["séduction","soutenu","诱惑力"]],"fq":"中频，偏书面。","me":"attrait 和 attirer 同根：被「拉」过去的力量。","tr":{"zh":"这个地方的魅力在于它的安静。","fr":"L'attrait de cet endroit, c'est son calme.","alt":"Ce qui attire ici, c'est le calme.","note":"l'attrait de + 名词 表示吸引人的地方。"}},
 "Un ballon": {"pos":"n.m. 阳性名词，复数 ballons","s":"气球；球（足球、篮球等较大的球）。小球用 une balle（网球、乒乓球）；足球、橄榄球、排球、篮球用 un ballon。生日气球也是 un ballon。","ipa":"[ba.lɔ̃]","ph":"ll 在这里读 [l]；结尾 -on 读鼻化元音 [ɔ̃]，n 不发音。","pi":"区分 ballon（大球）和 balle（小球）；结尾不发 n；ll 不是 [j]。","et":"由 balle（球）加后缀 -on 构成，意为「大球」。同族：ballot。","ex":[["L'enfant joue avec un ballon.","孩子在玩球。"],["Le ballon est rouge et rond.","气球又红又圆。"],["Il tape dans le ballon.","他在踢球。"]],"co":[["un ballon de football","足球"],["un ballon d'eau chaude","热水器（水箱）"],["gonfler un ballon","给气球 / 球充气"],["un ballon de rouge","一杯红酒（口语）"]],"sy":[["balle","courant","小球"],["globe","soutenu","球体；地球仪"]],"fq":"高频，日常常用。","me":"ballon = balle + on：大一号的球。","tr":{"zh":"孩子们在院子里玩球。","fr":"Les enfants jouent au ballon dans la cour.","alt":"Les enfants tapent dans le ballon dans la cour.","note":"jouer au ballon 是玩球的固定说法。"}},
 "Un Boeing": {"pos":"n.m. 阳性名词，复数 des Boeing（不变）或 Boeings","s":"波音飞机。品牌名变成普通名词，指波音公司生产的客机，如 un Boeing 747。口语里常直接说 un Boeing 代指大型客机。","ipa":"[bo.iŋ]","ph":"oe 在这里分开读：[o] + [i]，结尾 -ng 读 [ŋ]（外来词读法）。","pi":"不要读成 [bwa]；拼写有 oe，法语常见错拼是 Boing；结尾 g 读 [ŋ]，不是鼻化元音。","et":"来自美国公司名 Boeing，创始人为 William Boeing。","ex":[["Nous volons dans un Boeing.","我们乘坐波音飞机。"],["Il a piloté un Boeing 747.","他驾驶过波音 747。"]],"co":[["un Boeing 747","波音 747"],["prendre un Boeing","乘波音飞机"],["un Boeing de la compagnie","公司的一架波音"]],"sy":[["avion","courant","飞机，通用词"],["Airbus","courant","空中客车，欧洲的竞争品牌"],["long-courrier","courant","长途客机"]],"fq":"低频，航空话题里用到。","me":"Bo-ing：像英语 Boeing，只是首音读 [bo]。","tr":{"zh":"这架波音飞机很大。","fr":"Ce Boeing est très grand.","alt":"Ce Boeing est énorme.","note":"品牌名作名词，用阳性 un / ce。"}},
 "Un boulot": {"pos":"n.m. 阳性名词，复数 boulots（口语）","s":"工作；活儿（口语）。比 travail 随意，指具体的工作、职位或一件活。常见 un petit boulot = 零工；boulot, dodo 形容「上班睡觉」的单调生活。","ipa":"[bu.lo]","ph":"ou 读 [u]；结尾 -ot 读 [o]，t 不发音。","pi":"结尾 t 不发音；ou 是 [u]；口语词，写正式文章要换成 travail 或 emploi。","et":"来源不确定，是口语词；常见搭配 petit boulot、métro-boulot-dodo。","ex":[["Tu fais quoi comme boulot ?","你做什么工作？"],["J'ai trop de boulot cette semaine.","这周我活儿太多了。"]],"co":[["un petit boulot","零工，兼职"],["chercher un boulot","找工作"],["métro, boulot, dodo","地铁、上班、睡觉（日复一日）"]],"sy":[["travail","courant","工作，通用"],["job","familier","也很口语"],["emploi","soutenu","岗位，较正式"]],"fq":"高频，口语很常用。","me":"métro, boulot, dodo：地铁、上班、睡觉，一天就过去了。","tr":{"zh":"我今天有很多活要干。","fr":"J'ai beaucoup de boulot aujourd'hui.","alt":"J'ai du boulot par-dessus la tête aujourd'hui.","note":"avoir du boulot = 有活干 / 很忙。"}},
 "Un camping-car": {"pos":"n.m. 阳性名词，复数 camping-cars","s":"房车；露营车。带床和厨房的车，可开去旅行过夜。法国人很爱说 voyager en camping-car。带连字符。","ipa":"[kɑ̃.piŋ.kaʁ]","ph":"cam 读 [kɑ̃]；-ing 读 [iŋ]（英语借词）；car 读 [kaʁ]。","pi":"camping 的 -ing 读 [iŋ]，不读 [in]；car 是 [kaʁ]，r 要发；注意连字符。","et":"由 camping（英语借词）和 car（autocar 的缩写）组成，法语自造的「英语式」词。","ex":[["Nous voyageons en camping-car.","我们开房车旅行。"],["Ils ont acheté un vieux camping-car.","他们买了一辆旧房车。"]],"co":[["voyager en camping-car","开房车旅行"],["louer un camping-car","租房车"],["une aire de camping-car","房车营地"]],"sy":[["caravane","courant","拖挂式露营车，要靠别的车拉"],["autocaravane","soutenu","房车的官方说法"]],"fq":"中频，旅游话题里常见。","me":"camping（露营）+ car（车）：露营的车。","tr":{"zh":"夏天我们想租一辆房车。","fr":"L'été, nous voulons louer un camping-car.","alt":"Cet été, on veut louer un camping-car.","note":"en camping-car：交通工具前用 en。"}},
 "Un carnet de commande": {"pos":"n.m. 阳性名词，复数 carnets de commandes（常用复数 commandes）","s":"订单簿；在手订单。商业用语，指公司已有的订单总量。le carnet de commandes est plein = 订单排满了，生意很好。注意：习惯写成 carnet de commandes（commandes 带 s）。","ipa":"[kaʁ.nɛ də kɔ.mɑ̃d]","ph":"carnet 的 t 不发音，读 [kaʁ.nɛ]；commande 里 mm 读一个 [m]，-an- 读 [ɑ̃]，结尾 e 不发音但 d 要读出。","pi":"carnet 结尾 t 不发音；commande 的 d 要读 [d]；常见写法有 s：carnets de commandes。","et":"carnet（小本子，carne 的指小词）+ de + commande（commander 的名词）。同族：commander、recommander。","ex":[["Le carnet de commande est plein.","订单排得满满的。"],["Leur carnet de commandes est vide.","他们的订单是空的。"]],"co":[["un carnet de commandes bien rempli","订单满满"],["remplir le carnet de commandes","把订单簿填满"],["passer une commande","下订单"]],"sy":[["commandes","courant","订单，较短的说法"],["portefeuille de commandes","soutenu","订单组合，较正式"]],"fq":"低频，经济和商业新闻里用到。","me":"carnet（本子）里记满 commandes（订单）：生意兴隆。","tr":{"zh":"这家工厂的订单排到明年。","fr":"Le carnet de commandes de l'usine est plein jusqu'à l'an prochain.","alt":"L'usine a du travail jusqu'à l'an prochain.","note":"être plein 表示满；jusqu'à + 时间。"}},
 "Un circuit (de voyage)": {"pos":"n.m. 阳性名词，复数 circuits","s":"旅行线路；环游行程。旅行社的「团游」，路线固定，一路参观多个地方。circuit 也指赛车道、电路：un circuit électrique。","ipa":"[siʁ.kɥi]","ph":"c 在 i 前读 [s]；cu 读 [kɥ]（半元音）；结尾 t 不发音。","pi":"结尾 t 不发音；-cuit 读 [kɥi]，不是 [kui] 或 [kyit]；一词多义：电路、赛道、旅行线路。","et":"来自拉丁语 circuitus（绕圈），circum（周围）+ ire（走）。","ex":[["Nous faisons un circuit en Italie.","我们去意大利环游。"],["Le circuit dure dix jours.","这条线路为期十天。"]],"co":[["faire un circuit","走一条线路"],["un circuit touristique","旅游线路"],["un circuit électrique","电路"],["le circuit de Monaco","摩纳哥赛道"]],"sy":[["voyage organisé","courant","跟团游"],["tour","familier","兜一圈"],["parcours","courant","路线，行程"]],"fq":"中频，旅游话题里常见。","me":"circuit 和 circle（圈）同源：绕一圈走完。","tr":{"zh":"我们要在法国南部环游八天。","fr":"Nous faisons un circuit de huit jours dans le sud de la France.","alt":"On part huit jours en circuit dans le sud de la France.","note":"un circuit de + 天数 表示行程长度。"}},
 "Un contexte": {"pos":"n.m. 阳性名词，复数 contextes","s":"背景；语境；上下文。词语的前后文，也指事件发生的环境，如 le contexte politique。常说 dans ce contexte（在这种背景下）。","ipa":"[kɔ̃.tɛkst]","ph":"con 读鼻化元音 [kɔ̃]；x 读 [ks]；-xte 读 [kst]，结尾 e 不发音。","pi":"x 读 [ks]；辅音连读 [kst] 对中文母语者较难，要读完整；n 不单独发音。","et":"来自拉丁语 contextus（连接、编织），con-（一起）+ texere（织）。同族：texte、tissu。","ex":[["Il faut comprendre le contexte.","必须了解背景。"],["Hors contexte, cette phrase est bizarre.","脱离上下文，这句话很奇怪。"]],"co":[["dans ce contexte","在这种背景下"],["hors contexte","脱离上下文"],["le contexte historique","历史背景"],["remettre en contexte","放回原来的语境"]],"sy":[["situation","courant","情况，范围更窄"],["cadre","courant","框架，环境"],["circonstances","soutenu","情形，条件"]],"fq":"高频，讨论和写作常用。","me":"con + texte：和「文字」放在一起的东西。","tr":{"zh":"你得结合背景来理解这句话。","fr":"Il faut comprendre cette phrase dans son contexte.","alt":"Cette phrase, il faut la replacer dans son contexte.","note":"dans son contexte：所有格 son 指这句话的背景。"}},
 "Un contrat": {"pos":"n.m. 阳性名词，复数 contrats","s":"合同；契约。签合同 signer un contrat，工作合同 un contrat de travail。CDI 是无固定期限合同，CDD 是定期合同。","ipa":"[kɔ̃.tʁa]","ph":"con 读 [kɔ̃]；tr 连读 [tʁ]；结尾 -at 读 [a]，t 不发音。","pi":"结尾 t 不发音；-at 读 [a]，不是 [at]；con 是鼻化元音，不要读成 [kɔn]。","et":"来自拉丁语 contractus（约定），源于 contrahere（缔结）。同族：contracter。","ex":[["J'ai signé un nouveau contrat.","我签了一份新合同。"],["Son contrat finit en juin.","他的合同六月到期。"]],"co":[["signer un contrat","签合同"],["un contrat de travail","劳动合同"],["un contrat à durée déterminée (CDD)","定期合同"],["rompre un contrat","解除合同"]],"sy":[["accord","courant","协议，不一定书面"],["convention","soutenu","协约"],["engagement","courant","承诺"]],"fq":"高频，工作和生活常用。","me":"con-trat：大家「拉」在一起签的东西。","tr":{"zh":"我下个月要签新合同。","fr":"Je signe un nouveau contrat le mois prochain.","alt":"Le mois prochain, je signe mon nouveau contrat.","note":"近将来可用现在时加 le mois prochain。"}},
 "Un diapo (diaporama)": {"pos":"n.m. 阳性名词（diaporama 为阳性）；diapo 作 diapositive 的简称时常为阴性：une diapo","s":"幻灯片；幻灯片放映。diaporama 是整套放映，diapo 是 diapositive 的口语简称，指单张幻灯片。规范用法：un diaporama，une diapo（单张）。","ipa":"[dja.pɔ.ʁa.ma]","ph":"dia 读 [dja]；diapo 读 [dja.po]；diaporama 读 [dja.pɔ.ʁa.ma]。","pi":"dia 是两个音 [dja]，不是 [di.a]；diaporama 是阳性，diapo 常为阴性，要注意冠词。","et":"diaporama 由 diapositive（dia- 「透过」+ positive）加 panorama 构成；diapo 是其缩写。","ex":[["Il a préparé un beau diaporama.","他准备了一份漂亮的幻灯片。"],["Je montre dix diapos pendant l'exposé.","我在报告里放十张幻灯片。"]],"co":[["préparer un diaporama","做幻灯片"],["projeter un diaporama","放映幻灯片"],["passer à la diapo suivante","切到下一张"]],"sy":[["présentation","courant","演示文稿"],["PowerPoint","familier","口语里常指幻灯片"],["slide","familier","借自英语"]],"fq":"中频，学习和工作里常见。","me":"diaporama = dia（透过光）+ panorama：一连串画面。","tr":{"zh":"明天我要放一份幻灯片。","fr":"Demain, je présente un diaporama.","alt":"Demain, je montre mon diaporama.","note":"diaporama 为阳性：un diaporama。"}},
 "Un duo": {"pos":"n.m. 阳性名词，复数 duos","s":"二人组；二重唱 / 二重奏。两个人合作，常用于音乐、搭档、喜剧组合。en duo = 两人一起。","ipa":"[dy.o]","ph":"du 读 [dy]，o 读 [o]，两个音节分开：du-o。","pi":"不要连成一个音 [dwo]；u 是 [y]（圆唇前元音）；复数加 s 但不发音。","et":"来自意大利语 duo，源自拉丁语 duo（二）。同族：deux、double。","ex":[["Ils forment un beau duo.","他们是一对好搭档。"],["Elles chantent en duo.","她们二重唱。"]],"co":[["en duo","两人一起"],["chanter en duo","二重唱"],["un duo comique","喜剧二人组"]],"sy":[["couple","courant","一对，多指情侣"],["paire","courant","一对（物品）"],["binôme","courant","搭档，学习或工作伙伴"]],"fq":"中频，音乐和娱乐里常见。","me":"duo = 「二」：想想 deux。","tr":{"zh":"他们俩是很棒的搭档。","fr":"Eux deux forment un super duo.","alt":"Tous les deux, ils font un super duo.","note":"former un duo = 组成搭档。"}},
 "Un duvet": {"pos":"n.m. 阳性名词，复数 duvets","s":"睡袋（露营用，常说 sac de couchage / duvet）；羽绒；鸟类的绒毛。在比利时、瑞士，duvet 还指羽绒被。有羽绒的东西才叫 duvet。","ipa":"[dy.vɛ]","ph":"du 读 [dy]；ve 读 [vɛ]；结尾 t 不发音。","pi":"结尾 t 不发音；u 是 [y]，不是 [u]；注意 duvet 本义是羽绒，不只是睡袋。","et":"古法语 dumet，指小词，源于北欧语（古诺尔斯语 dúnn，鸟的绒毛）。","ex":[["J'ai chaud dans mon duvet.","我在睡袋里很暖和。"],["Ce duvet est parfait pour la montagne.","这个睡袋很适合爬山。"]],"co":[["un sac de couchage","睡袋（更标准）"],["un duvet d'oie","鹅绒"],["un duvet en plume","羽绒被 / 羽绒睡袋"]],"sy":[["sac de couchage","courant","睡袋的标准说法"],["couette","courant","被子"]],"fq":"中频，露营和寝具话题里常见。","me":"du-vet：软软的「羽绒」，像鸭子的绒毛 duvet。","tr":{"zh":"山上很冷，带上你的睡袋。","fr":"Il fait froid en montagne, prends ton duvet.","alt":"En montagne, il fait froid : n'oublie pas ton duvet.","note":"prendre / emporter 都可以表示带上。"}},
 "Un Ehpad": {"pos":"n.m. 阳性名词（缩写词），复数 des Ehpad（不变）","s":"养老院；护理型老人院。全称 Établissement d'hébergement pour personnes âgées dépendantes，为需要照护的老人提供住宿和护理。常写大写 EHPAD，读作一个词。","ipa":"[e.pad]","ph":"按单词读：e-pad，不拼字母；h 不发音。","pi":"h 不发音；整体读 [e.pad]，不是逐个字母读；作为缩写词，复数不变。","et":"缩写：Établissement d'hébergement pour personnes âgées dépendantes，法国的专门机构名称。","ex":[["Mon grand-père vit dans un Ehpad.","我爷爷住在养老院。"],["Elle travaille dans un Ehpad.","她在养老院工作。"]],"co":[["vivre en Ehpad","住在养老院"],["travailler dans un Ehpad","在养老院工作"],["une place en Ehpad","养老院的床位"]],"sy":[["maison de retraite","courant","养老院，更通用的说法"],["foyer","courant","（老人）公寓或宿舍"]],"fq":"中频，法国社会新闻里常见。","me":"E-H-P-A-D 读成一个词 [e.pad]，像一个名字。","tr":{"zh":"我奶奶住在养老院里。","fr":"Ma grand-mère vit dans un Ehpad.","alt":"Ma grand-mère est en Ehpad.","note":"être en Ehpad 是口语简说。"}},
 "Un enjeu": {"pos":"n.m. 阳性名词，复数 enjeux","s":"关键问题；利害关系；赌注。指「在这件事里能赢或能输的东西」。les enjeux = 利害、风险，常见于新闻、政治、环境。","ipa":"[ɑ̃.ʒø]","ph":"en 读鼻化元音 [ɑ̃]；j 读 [ʒ]；eu 读 [ø]。","pi":"复数 enjeux 里 x 不发音；en 不要拆成 [ɛn]；eu 是 [ø]，嘴唇圆。","et":"由 en + jeu（游戏、赌局）构成，本义是「投进赌局的钱」。同族：jouer。","ex":[["C'est un enjeu important.","这是一个重要的问题。"],["L'enjeu de ce match est énorme.","这场比赛利害重大。"]],"co":[["un enjeu majeur","重大议题"],["les enjeux de la société","社会议题"],["être l'enjeu de","是……的焦点"]],"sy":[["défi","courant","挑战"],["question","courant","问题，较泛"],["risque","courant","风险"]],"fq":"中高频，新闻和写作常用。","me":"en + jeu：放进「游戏」里的赌注。","tr":{"zh":"气候是今天最大的问题。","fr":"Le climat est l'enjeu majeur de notre époque.","alt":"Aujourd'hui, le grand enjeu, c'est le climat.","note":"enjeu majeur 是新闻常用搭配。"}},
 "Un établissement": {"pos":"n.m. 阳性名词，复数 établissements","s":"机构；场所；单位。学校、医院、银行、公司、商店都可以叫 un établissement；un établissement scolaire = 学校。比 entreprise、école 更正式、更泛。","ipa":"[e.ta.blis.mɑ̃]","ph":"é 读 [e]；bl 连读；-ment 读 [mɑ̃]，nt 不发音。","pi":"-ment 读 [mɑ̃]，不读 [mɛnt]；开头 é 有重音符；词较长，分音节读：é-ta-blis-se-ment，中间的 e 不发音。","et":"établir（拉丁语 stabilire，使稳定）+ -ment。同族：stable、s'établir。","ex":[["C'est un grand établissement.","这是一所大机构。"],["Cet établissement ferme à dix-huit heures.","这个场所六点关门。"]],"co":[["un établissement scolaire","学校"],["un établissement public","公共机构"],["un établissement bancaire","银行"],["un établissement de santé","医疗机构"]],"sy":[["institution","soutenu","机构，较正式"],["organisme","courant","组织"],["lieu","courant","地方，更泛"]],"fq":"中高频，行政和新闻常用。","me":"établir 一个地方，得到 établissement。","tr":{"zh":"这所学校条件很好。","fr":"Cet établissement scolaire est très bien équipé.","alt":"Cette école est très bien équipée.","note":"établissement 阳性，équipé 跟着阳性。"}},
 "Un feu de forêt": {"pos":"n.m. 阳性名词，复数 feux de forêt","s":"森林火灾；山火。夏天干燥的地区常见。也说 un incendie de forêt（更正式）。feu 本义是火。","ipa":"[fø də fɔ.ʁɛ]","ph":"feu 读 [fø]；de 读 [də]；forêt 读 [fɔ.ʁɛ]，ê 读 [ɛ]，t 不发音。","pi":"feu 的 eu 是 [ø]；forêt 结尾 t 不发音；复数 feux，x 不发音。","et":"feu 来自拉丁语 focus（炉灶、火）；forêt 来自中世纪拉丁语 foresta。","ex":[["Un feu de forêt a détruit les arbres.","森林火灾烧毁了树木。"],["Les pompiers luttent contre le feu de forêt.","消防员在扑灭森林大火。"]],"co":[["éteindre un feu de forêt","扑灭森林火灾"],["un risque de feu de forêt","山火风险"],["lutter contre les feux de forêt","对抗山火"]],"sy":[["incendie de forêt","soutenu","正式说法"],["incendie","courant","火灾（泛指）"]],"fq":"中频，夏季新闻里常见。","me":"feu（火）+ forêt（森林）：字面意思就是「森林的火」。","tr":{"zh":"夏天南方有森林火灾。","fr":"En été, il y a des feux de forêt dans le sud.","alt":"L'été, le sud brûle souvent.","note":"feux 为复数，x 不发音。"}},
 "Un fléau": {"pos":"n.m. 阳性名词，复数 fléaux（-eau 的复数加 x）","s":"灾祸；祸害；灾难。指严重的灾害，如瘟疫、战争、污染。也可夸张地用于小麻烦：Ce voisin, c'est un fléau ! 本义是脱粒用的连枷。","ipa":"[fle.o]","ph":"fl 连读；é 读 [e]；au 读 [o]，两个音节：flé-au。","pi":"复数 fléaux，不是 fléaus；é 带重音；au 读 [o]，在这里与 é 分开成两个音节。","et":"来自拉丁语 flagellum（鞭子），本义是脱粒用的连枷，后来比喻「灾难」。","ex":[["La pollution est un fléau.","污染是祸害。"],["Cette maladie est un fléau mondial.","这种疾病是全球性的灾祸。"]],"co":[["un fléau mondial","全球性灾祸"],["lutter contre un fléau","对抗灾祸"],["un fléau social","社会问题"]],"sy":[["catastrophe","courant","灾难"],["calamité","soutenu","灾祸"],["plaie","familier","讨厌的东西 / 人"]],"fq":"中频，新闻和书面常见。","me":"fléau 和 flagellum（鞭子）同源：像被鞭打的灾难。","tr":{"zh":"噪音是大城市的祸害。","fr":"Le bruit est un fléau dans les grandes villes.","alt":"Dans les grandes villes, le bruit est un vrai fléau.","note":"un vrai fléau：强调程度。"}},
 "Un lever de soleil": {"pos":"n.m. 阳性名词，复数 levers de soleil","s":"日出。反义词是 un coucher de soleil（日落）。也可说 l'aube（黎明）。lever 在这里是名词，来自动词 se lever / lever。","ipa":"[lə.ve də sɔ.lɛj]","ph":"lever 读 [lə.ve]，结尾 r 不发音；soleil 读 [sɔ.lɛj]，-eil 读 [ɛj]。","pi":"lever 结尾 r 不发音（-er 读 [e]）；soleil 的 -eil 读 [ɛj]，不要读成 [ɛl]。","et":"lever ← 拉丁语 levare（抬起）；soleil ← 拉丁语 soliculus（sol 的指小词，太阳）。","ex":[["Le lever de soleil est magnifique.","日出很美。"],["Nous regardons le lever de soleil sur la plage.","我们在海滩看日出。"]],"co":[["au lever du soleil","日出时"],["regarder le lever de soleil","看日出"],["un lever de soleil sur la mer","海上日出"]],"sy":[["aube","littéraire","黎明，更文学"],["aurore","littéraire","晨曦"],["coucher de soleil","courant","反义：日落"]],"fq":"中频，旅游和风景描写中常见。","me":"lever（升起）+ soleil（太阳）：太阳升起。","tr":{"zh":"我们五点起床看日出。","fr":"Nous nous levons à cinq heures pour voir le lever de soleil.","alt":"On se lève à cinq heures pour voir le soleil se lever.","note":"au lever du soleil = 日出时。"}},
 "Un matelas": {"pos":"n.m. 阳性名词，复数 matelas（单复数同形）","s":"床垫。躺在床上的那块厚垫子。un matelas pneumatique = 充气床垫（露营、游泳池用）。","ipa":"[mat.la]","ph":"ma-te-las 常快读成 [mat.la]；e 在口语里不发；结尾 s 不发音。","pi":"结尾 s 不发音；复数不变，单复数同形 matelas；e 通常被吞掉。","et":"经意大利语 materasso，来自阿拉伯语（意为「垫子、放下的东西」）。","ex":[["Ce matelas est confortable.","这张床垫很舒服。"],["Nous dormons sur un matelas pneumatique.","我们睡在充气床垫上。"]],"co":[["un matelas pneumatique","充气床垫"],["un matelas ferme / mou","硬 / 软床垫"],["changer de matelas","换床垫"]],"sy":[["sommier","courant","床架，床垫下面的部分"],["couchage","courant","铺位"]],"fq":"中频，家居和露营话题里常见。","me":"ma-te-las：躺下去的 las（软）。","tr":{"zh":"我想换一张更硬的床垫。","fr":"Je veux changer pour un matelas plus ferme.","alt":"Il me faut un matelas plus ferme.","note":"plus ferme：比较级，plus + 形容词。"}},
 "Un minima": {"pos":"n.m. 阳性名词（minimum 的拉丁语复数形式）；单数 un minimum，复数 des minima 或 des minimums","s":"最低标准；最低限度。标准单数是 un minimum，复数是 minima（拉丁式）或 minimums。minima 多用于官方、社会福利和体育（les minima sociaux 低保；les minima = 参赛资格最低成绩）。","ipa":"[mi.ni.ma]","ph":"mi-ni-ma；单数 minimum 读 [mi.ni.mɔm]。","pi":"单数是 minimum，不是 minima；minimum 的 -um 读 [ɔm]；常见错误是把 minima 当单数用。","et":"拉丁语 minimum（最小的），minimus 的中性形式。同族：minime、diminuer。","ex":[["Ils ne respectent pas les minima européens.","他们不遵守欧洲最低标准。"],["Il faut un minimum de politesse.","至少要有基本的礼貌。"]],"co":[["les minima sociaux","社会最低保障"],["un minimum de","最起码的"],["au minimum","至少"],["le minimum vital","最低生活保障"]],"sy":[["minimum","courant","标准单数形式"],["seuil","courant","门槛"],["plancher","courant","下限"]],"fq":"低频，多见于官方、社会和新闻用语。","me":"minima = 复数的 minimum：mini（小）。","tr":{"zh":"你至少要做到最低的要求。","fr":"Il faut au moins respecter le minimum exigé.","alt":"Tu dois faire au moins le minimum.","note":"minimum 是单数，复数 minima。"}},
 "Un mode de transport": {"pos":"n.m. 阳性名词，复数 modes de transport","s":"交通方式；交通工具类型。一类出行方式，如步行、骑车、地铁、火车、飞机。mode 在这里是阳性（le mode = 方式）；la mode 才是时尚。","ipa":"[mɔd də tʁɑ̃s.pɔʁ]","ph":"mode 读 [mɔd]，d 要发；transport 读 [tʁɑ̃s.pɔʁ]，trans 是鼻化元音 [tʁɑ̃s]，结尾 t 不发音。","pi":"mode 阳性是「方式」，阴性 la mode 是「时尚」；transport 结尾 t 不发音；复数 modes de transport，transport 不加 s。","et":"mode ← 拉丁语 modus（方式）；transport ← transporter ← 拉丁语 transportare（trans- + portare 搬运）。","ex":[["Le vélo est un bon mode de transport.","自行车是一种好的交通方式。"],["Quel mode de transport préfères-tu ?","你更喜欢哪种交通方式？"]],"co":[["un mode de transport écologique","环保的交通方式"],["choisir un mode de transport","选择交通方式"],["les transports en commun","公共交通"]],"sy":[["moyen de transport","courant","交通工具，更常用"],["véhicule","courant","车辆"]],"fq":"中高频，生活和环保话题里常见。","me":"mode（方式）+ transport（运输）：怎么去。","tr":{"zh":"地铁是我最常用的交通方式。","fr":"Le métro est mon mode de transport préféré.","alt":"Je prends surtout le métro pour me déplacer.","note":"mode 阳性，préféré 也用阳性。"}},
 "Un panneau solaire": {"pos":"n.m. 阳性名词，复数 panneaux solaires（panneau 的复数加 x，solaire 加 s）","s":"太阳能板。装在屋顶上发电或加热水的板子。panneau 还指路标、告示牌：un panneau de signalisation。","ipa":"[pa.no sɔ.lɛʁ]","ph":"panneau 读 [pa.no]（nn 读一个 n，eau 读 [o]）；solaire 读 [sɔ.lɛʁ]，-aire 读 [ɛʁ]。","pi":"panneau 复数 panneaux，x 不发音；solaire 的 r 要发；-eau 读 [o]。","et":"panneau ← 古法语 pan（一块布）+ -eau，来自拉丁语 pannus（布）；solaire ← 拉丁语 solaris（sol，太阳）。","ex":[["J'ai installé un panneau solaire.","我安装了太阳能板。"],["Ils mettent des panneaux solaires sur le toit.","他们在屋顶装太阳能板。"]],"co":[["installer des panneaux solaires","安装太阳能板"],["l'énergie solaire","太阳能"],["un panneau de signalisation","路标"]],"sy":[["capteur solaire","soutenu","集热器，技术说法"],["panneau photovoltaïque","soutenu","光伏板"]],"fq":"中频，能源和环保话题里常见。","me":"panneau（板）+ solaire（太阳的）：太阳板。","tr":{"zh":"我们的屋顶上有太阳能板。","fr":"Il y a des panneaux solaires sur notre toit.","alt":"On a mis des panneaux solaires sur le toit.","note":"Il y a + 复数 名词。"}},
 "Un paquebot": {"pos":"n.m. 阳性名词，复数 paquebots","s":"远洋客轮；邮轮。载着很多乘客跨洋或巡游的大船。比 bateau（泛指船）更具体，如 le Titanic 是 un paquebot。","ipa":"[pak.bo]","ph":"pa-que-bot 读成 [pak.bo]；qu 读 [k]；结尾 t 不发音。","pi":"qu 读 [k]；结尾 t 不发音；bot 读 [bo]，不是 [bɔt]。","et":"来自英语 packet-boat（邮件船），后来指客轮。","ex":[["Le paquebot traverse l'océan.","客轮横渡大洋。"],["Nous partons en croisière sur un grand paquebot.","我们乘大邮轮去巡游。"]],"co":[["un paquebot de croisière","邮轮"],["monter à bord d'un paquebot","登上客轮"],["traverser l'Atlantique en paquebot","乘客轮横渡大西洋"]],"sy":[["navire","soutenu","较大的船，较正式"],["bateau","courant","船，通用词"],["croiseur","courant","巡洋舰；或游轮"]],"fq":"低频，旅游和历史话题里。","me":"paque + bot：从「邮件船」变成大客轮。","tr":{"zh":"这艘客轮载着一千名乘客。","fr":"Ce paquebot transporte mille passagers.","alt":"Ce paquebot peut accueillir mille passagers.","note":"transporter 表示运送。"}},
 "Un parc à thème": {"pos":"n.m. 阳性名词，复数 parcs à thème","s":"主题乐园。像迪士尼乐园（Disneyland Paris）这样围绕一个主题的游乐园。也说 un parc d'attractions（游乐园，更泛）。","ipa":"[paʁk a tɛm]","ph":"parc 结尾 c 要发 [paʁk]；thème 的 th 读 [t]；è 读 [ɛ]。","pi":"parc 的 c 要发音 [k]（注意 banc 的 c 不发）；th 读 [t]，不是 [θ]；thème 是阳性。","et":"仿照英语 theme park；thème ← 希腊语 thema（所设置的东西）。","ex":[["Nous allons dans un parc à thème.","我们去主题乐园。"],["Ce parc à thème est ouvert tout l'été.","这个主题乐园整个夏天开放。"]],"co":[["aller dans un parc à thème","去主题乐园"],["un parc d'attractions","游乐园"],["un parc zoologique","动物园"]],"sy":[["parc d'attractions","courant","游乐园，更常用"],["Disneyland","courant","最有名的例子"]],"fq":"中频，旅游话题里。","me":"parc（园）+ thème（主题）：有主题的公园。","tr":{"zh":"周末我们去主题乐园玩。","fr":"Ce week-end, nous allons dans un parc à thème.","alt":"Ce week-end, on va dans un parc à thème.","note":"aller dans + 地点。"}},
 "Un passager": {"pos":"n.m. 阳性名词；阴性 une passagère，复数 passagers","s":"乘客；旅客（飞机、船、车上的人）。阴性 passagère。un passager clandestin = 偷渡者 / 逃票的人。公共交通的乘客也常说 voyageur。","ipa":"[pa.sa.ʒe]","ph":"pa-sa-ger：ss 读 [s]；g 在 e 前读 [ʒ]；-er 读 [e]。","pi":"ss 读 [s]，不读 [z]；-er 读 [e]，r 不发；阴性 passagère 读 [pa.sa.ʒɛʁ]。","et":"由 passage（passer 的名词）加 -er 构成。同族：passer、passant。","ex":[["Le passager attend son vol.","乘客在等航班。"],["Les passagers montent dans l'avion.","乘客们登上飞机。"]],"co":[["un passager clandestin","偷渡者；逃票者"],["un passager de l'avion","飞机乘客"],["une passagère","女乘客"]],"sy":[["voyageur","courant","旅客，火车 / 地铁常用"],["usager","courant","使用者，公共服务的用户"]],"fq":"高频，交通话题常用。","me":"passager = 经过的人：passer + -er。","tr":{"zh":"乘客们在登机口排队。","fr":"Les passagers font la queue à la porte d'embarquement.","alt":"Les passagers attendent à la porte d'embarquement.","note":"faire la queue = 排队。"}},
 "Un périple": {"pos":"n.m. 阳性名词，复数 périples","s":"漫长而曲折的旅程；远行。比 voyage 更有冒险感，常指绕行很多地方的长途旅行。一般用在书面或叙述中。","ipa":"[pe.ʁipl]","ph":"pé 读 [pe]；ri 读 [ʁi]；结尾 -ple 读 [pl]，e 不发音。","pi":"结尾 -ple 读 [pl]，e 不发；é 有重音；r 小舌音；不要和 périphérique 混淆。","et":"来自希腊语 periplous（环航），peri（周围）+ plous（航行）。同族：périmètre、périphérique。","ex":[["Ce fut un long périple.","这是一次漫长的旅程。"],["Leur périple a duré trois mois.","他们的旅程持续了三个月。"]],"co":[["un long périple","漫长的旅程"],["entreprendre un périple","踏上旅程"],["au terme d'un périple","走完一段旅程之后"]],"sy":[["voyage","courant","旅行，通用词"],["odyssée","littéraire","漫长冒险之旅"],["expédition","soutenu","远征，探险"]],"fq":"低频，书面和叙述里。","me":"péri（周围）+ ple（航行）：绕一大圈。","tr":{"zh":"他的旅程从巴黎到北京。","fr":"Son périple l'a mené de Paris à Pékin.","alt":"Il est allé de Paris à Pékin, quel périple !","note":"mener qqn de A à B。"}},
 "Un pilote": {"pos":"n.m./n.f. 名词，男女同形：un / une pilote，复数 pilotes","s":"飞行员；驾驶员；赛车手。飞机的 pilote 是飞行员，赛车手也叫 pilote。男女同形，说 une pilote。动词 piloter = 驾驶、操纵。","ipa":"[pi.lɔt]","ph":"pi-lo-te：o 读开口的 [ɔ]；结尾 e 不发音，t 要发出。","pi":"t 要读出来 [t]；o 是开口 [ɔ]，不是 [o]；女性仍写 pilote，只改冠词。","et":"来自意大利语 pilota，原指船上的领航员，后来扩展到飞机。","ex":[["Le pilote dirige l'avion.","飞行员驾驶飞机。"],["Elle est pilote de ligne.","她是民航飞行员。"]],"co":[["un pilote de ligne","民航飞行员"],["un pilote de course","赛车手"],["piloter un avion","驾驶飞机"]],"sy":[["aviateur","soutenu","飞行家，较文雅"],["conducteur","courant","司机（车辆）"]],"fq":"中高频，交通和职业话题里。","me":"pilote 里有 pilot：和英语 pilot 几乎一样。","tr":{"zh":"她想当飞行员。","fr":"Elle veut devenir pilote.","alt":"Elle rêve d'être pilote d'avion.","note":"职业前常省略冠词。"}},
 "Un plafond": {"pos":"n.m. 阳性名词，复数 plafonds","s":"天花板；上限。房间的顶。也比喻「最高限额」：un plafond de dépenses。反义：plancher（地板、下限）。","ipa":"[pla.fɔ̃]","ph":"pla 读 [pla]；fond 读 [fɔ̃]，鼻化元音，d 不发音。","pi":"结尾 -ond 读 [ɔ̃]，d 不发音；复数 plafonds 里 s 也不发音。","et":"来自古法语 plat fond（平的顶）。同族：plat、fond、plafonner（达到上限）。","ex":[["Le plafond est très haut.","天花板很高。"],["Il y a une araignée au plafond.","天花板上有只蜘蛛。"]],"co":[["au plafond","在天花板上"],["un plafond de verre","玻璃天花板"],["fixer un plafond","设定上限"],["sauter au plafond","气得跳起来（口语）"]],"sy":[["plancher","courant","地板；下限（反义）"],["limite","courant","上限，界限"],["maximum","courant","最大值"]],"fq":"高频，日常常用。","me":"plat（平）+ fond（底）：房间平平的「底」，倒过来是顶。","tr":{"zh":"这个房间的天花板很低。","fr":"Le plafond de cette pièce est très bas.","alt":"Ce plafond est vraiment bas.","note":"bas / haut 形容天花板，与名词阳性一致。"}},
 "Un rapport": {"pos":"n.m. 阳性名词，复数 rapports","s":"报告；关系；联系。1) 报告：un rapport de police / de stage。2) 关系：avoir de bons rapports avec qqn。3) 比率；与……有关：par rapport à = 相对于，关于。","ipa":"[ʁa.pɔʁ]","ph":"ra 读 [ʁa]；port 读 [pɔʁ]，r 要发，结尾 t 不发音。","pi":"结尾 t 不发音，r 要发；拼写 pp 双写，不是 raport；常用词组 par rapport à 要记。","et":"由 rapporter（re- + apporter）派生，意思是「带回来、汇报」。同族：apporter、porter。","ex":[["Selon un rapport de cette association, ...","据这个协会的报告……"],["Je n'ai aucun rapport avec lui.","我和他没有任何关系。"]],"co":[["par rapport à","相对于；关于"],["un rapport de stage","实习报告"],["avoir un rapport avec","与……有关系"],["sous tous les rapports","各方面"]],"sy":[["compte rendu","courant","汇报，记录"],["lien","courant","联系"],["relation","courant","关系"]],"fq":"极高频，工作和学习中常用。","me":"rap + port：把消息「带」回来的东西。","tr":{"zh":"我正在写实习报告。","fr":"J'écris mon rapport de stage.","alt":"Je suis en train de rédiger mon rapport de stage.","note":"être en train de + 动词原形：正在做。"}},
 "Un spot": {"pos":"n.m. 阳性名词，复数 spots","s":"地点；热门景点（常指冲浪、潜水、滑板等的好去处）；也指聚光灯 / 广告短片：un spot publicitaire。英语借词。","ipa":"[spɔt]","ph":"s 与 p 连读 [sp]；o 读 [ɔ]；结尾 t 要发 [t]（外来词）。","pi":"结尾 t 要读出来 [t]，和一般法语词不同；不要加元音变成 [ə.spɔt]。","et":"借自英语 spot（点、地方）。同族：un spot publicitaire（广告短片）。","ex":[["C'est un célèbre spot de surf.","这是著名的冲浪地点。"],["On a vu un spot publicitaire à la télé.","我们在电视上看到了一条广告。"]],"co":[["un spot de surf","冲浪点"],["un spot publicitaire","广告短片"],["un bon spot","好地方"]],"sy":[["endroit","courant","地方"],["lieu","courant","场所"],["coin","familier","好去处"]],"fq":"中频，口语和网络用语常见。","me":"spot：英语借词，原样用。","tr":{"zh":"这里是潜水的好地方。","fr":"C'est un super spot pour la plongée.","alt":"Ici, c'est un très bon spot de plongée.","note":"spot pour + 名词 / spot de + 活动。"}},
 "Un style de vie": {"pos":"n.m. 阳性名词，复数 styles de vie","s":"生活方式；生活风格。指一个人日常的习惯和选择，如饮食、运动、消费。也说 un mode de vie（更常用）；style de vie 带英语 lifestyle 的味道。","ipa":"[stil də vi]","ph":"style 读 [stil]，y 读 [i]；de 读 [də]；vie 读 [vi]。","pi":"style 里 y 读 [i]；注意不是 [staɪl]；vie 读 [vi]。","et":"style ← 拉丁语 stilus（尖笔）；vie ← 拉丁语 vita。表达与英语 lifestyle 对应。","ex":[["J'aime son style de vie.","我喜欢他的生活方式。"],["Un style de vie sain est important.","健康的生活方式很重要。"]],"co":[["un style de vie sain","健康的生活方式"],["changer de style de vie","改变生活方式"],["un mode de vie","生活方式（更常用）"]],"sy":[["mode de vie","courant","生活方式，更常用"],["train de vie","courant","生活水准（开支）"],["habitudes","courant","习惯"]],"fq":"中频，生活和杂志类话题里。","me":"style（风格）+ de + vie（生活）：生活的风格。","tr":{"zh":"她想过更健康的生活。","fr":"Elle veut adopter un style de vie plus sain.","alt":"Elle veut vivre plus sainement.","note":"adopter un style de vie = 采用某种生活方式。"}},
 "Un tirage au sort": {"pos":"n.m. 阳性名词，复数 tirages au sort","s":"抽签；抽奖；随机抽取。用抽签的方式决定。tirer au sort = 抽签决定。抽奖也可说 tombola 或 loterie。","ipa":"[ti.ʁaʒ o sɔʁ]","ph":"tirage 读 [ti.ʁaʒ]，g 读 [ʒ]；au 读 [o]；sort 读 [sɔʁ]，r 要发，t 不发音。","pi":"sort 结尾的 t 不发，r 要发；tirage 结尾是 [aʒ]，不要读 [aʒə]；au 读 [o]。","et":"tirer（拉）+ -age 构成 tirage；sort ← 拉丁语 sors, sortis（命运、抽签）。同族：sortilège、assortir。","ex":[["Il y a eu un tirage au sort.","进行了抽签。"],["Les gagnants sont choisis par tirage au sort.","获奖者通过抽签选出。"]],"co":[["par tirage au sort","通过抽签"],["tirer au sort","抽签决定"],["gagner au tirage au sort","抽中奖"]],"sy":[["loterie","courant","彩票，抽奖"],["tombola","courant","联欢会抽奖"]],"fq":"中频，活动和新闻里。","me":"tirer（抽）+ sort（命运）：抽出命运。","tr":{"zh":"获奖者通过抽签产生。","fr":"Les gagnants sont choisis par tirage au sort.","alt":"On tire les gagnants au sort.","note":"par + 名词：表示方式。"}},
 "Un voilier": {"pos":"n.m. 阳性名词，复数 voiliers","s":"帆船。靠风帆前进的船，用于旅行或运动。voile 有两个意思：la voile（帆，阴性）和 le voile（面纱，阳性）；voilier 指帆船。","ipa":"[vwa.lje]","ph":"voi 读 [vwa]；lier 读 [lje]，-ier 读 [je]。","pi":"voi 读 [vwa]；-ier 读 [je]，r 不发音；voile 阴性（帆）和阳性（面纱）易混。","et":"由 voile（拉丁语 vela，帆）加后缀 -ier 构成。同族：voile、faire de la voile。","ex":[["Il a acheté un beau voilier.","他买了一艘漂亮的帆船。"],["Nous naviguons en voilier tout l'été.","我们整个夏天乘帆船航行。"]],"co":[["naviguer en voilier","乘帆船航行"],["louer un voilier","租帆船"],["faire de la voile","玩帆船运动"]],"sy":[["bateau à voile","courant","帆船，说法更展开"],["yacht","courant","游艇"],["navire","soutenu","大船"]],"fq":"中频，旅游和运动话题里。","me":"voile（帆）+ ier：有帆的船。","tr":{"zh":"这个夏天我们租了一艘帆船。","fr":"Cet été, nous avons loué un voilier.","alt":"Cet été, on a loué un voilier.","note":"louer 在这里是租入。"}},
 "De l'altitude": {"pos":"n.f. 阴性名词，复数 altitudes（常以 de l' 部分冠词形式出现）","s":"海拔；高度。山或飞机的高度。prendre de l'altitude = 爬升高度；比喻「拉开距离、看得更远」。mal d'altitude = 高原反应。","ipa":"[al.ti.tyd]","ph":"al 读 [al]；ti 读 [ti]；tude 读 [tyd]，u 是 [y]，d 要发，结尾 e 不发音。","pi":"结尾 -tude 读 [tyd]，不是 [tud]；u 读 [y]；t 在这里读 [t]，不是 [s]。","et":"来自拉丁语 altitudo（高度），源于 altus（高的）。同族：haut、hauteur。","ex":[["Nous prenons de l'altitude.","我们在爬升高度。"],["À cette altitude, il fait très froid.","在这个高度，很冷。"]],"co":[["prendre de l'altitude","爬升；拉开距离"],["à haute altitude","在高海拔地区"],["le mal d'altitude","高原反应"],["perdre de l'altitude","下降高度"]],"sy":[["hauteur","courant","高度，更日常"],["élévation","soutenu","海拔，较书面"]],"fq":"中频，登山和飞行话题里。","me":"alti-tude：和 altitude（英语）几乎一样。","tr":{"zh":"这座村子海拔一千米。","fr":"Ce village est à mille mètres d'altitude.","alt":"Le village se trouve à mille mètres d'altitude.","note":"à + 数字 + mètres d'altitude。"}},
 "De l'énergie": {"pos":"n.f. 阴性名词，复数 énergies","s":"能量；精力；能源。可指身体的精力（avoir de l'énergie = 精力充沛），也指电、风、太阳能等能源（les énergies renouvelables）。","ipa":"[e.nɛʁ.ʒi]","ph":"é 读 [e]；ner 读 [nɛʁ]；gie 读 [ʒi]，g 在 i 前读 [ʒ]。","pi":"g 读 [ʒ]，不读 [g]；开头 é 重音；和英语 energy 的重音位置不同。","et":"来自希腊语 energeia（活动、力量），经晚期拉丁语进入法语。同族：énergique。","ex":[["Il a beaucoup d'énergie.","他精力充沛。"],["Nous utilisons de l'énergie solaire.","我们用太阳能。"]],"co":[["avoir de l'énergie","精力充沛"],["les énergies renouvelables","可再生能源"],["économiser l'énergie","节约能源"],["une boisson énergisante","能量饮料"]],"sy":[["force","courant","力量"],["vitalité","soutenu","活力"],["pep","familier","干劲，活力"]],"fq":"极高频，日常和新闻常用。","me":"énergie：像 energy，但 g 读 [ʒ]。","tr":{"zh":"我今天没什么精力。","fr":"Je n'ai pas beaucoup d'énergie aujourd'hui.","alt":"Aujourd'hui, je n'ai pas la pêche.","note":"avoir la pêche = 有精神（口语）。"}},
 "De l'essence": {"pos":"n.f. 阴性名词，复数 essences","s":"汽油。给汽车加油：mettre de l'essence。essence 还有「本质」和「（树木）种类」的意思，此处指燃料。柴油是 le gazole（le diesel）。","ipa":"[e.sɑ̃s]","ph":"e 读 [e]；ss 读 [s]；-ence 读 [ɑ̃s]，鼻化元音，结尾 e 不发音。","pi":"-ence 读 [ɑ̃s]，不读 [ɛns]；ss 读 [s]；英语 gasoline 对应法语 essence，不是 gas（le gaz 是气体）。","et":"来自拉丁语 essentia（本质），源于 esse（是、存在）。「汽油」是引申义，指蒸馏出来的挥发物。","ex":[["Je dois mettre de l'essence dans ma voiture.","我得给车加油。"],["L'essence coûte cher en ce moment.","最近汽油很贵。"]],"co":[["faire le plein d'essence","加满油"],["une panne d'essence","没油了"],["une station-essence","加油站"],["de l'essence sans plomb","无铅汽油"]],"sy":[["carburant","courant","燃料，更泛"],["gazole","courant","柴油，另一种燃料"],["super","familier","高标号汽油"]],"fq":"高频，开车话题里常用。","me":"essence ← essentia：提炼出来的「精华」，就是汽油。","tr":{"zh":"我们快没油了。","fr":"Nous n'avons presque plus d'essence.","alt":"On est presque en panne d'essence.","note":"ne… plus de + 名词：没有了。"}},
 "De la fierté": {"pos":"n.f. 阴性名词，复数 fiertés","s":"自豪；骄傲。多是正面的：avoir de la fierté = 感到自豪。注意 fier 可以指「自豪的」也可指「傲慢的」，要看上下文。","ipa":"[fjɛʁ.te]","ph":"fi 读 [fj]；er 读 [ɛʁ]；té 读 [te]。","pi":"fi 读 [fj]，一个音节；r 要发；注意 fierté 有重音符 é。","et":"由 fier（拉丁语 ferus，野的、凶猛的）加 -té 构成。同族：fier、fièrement。","ex":[["Il ressent beaucoup de fierté.","他感到很自豪。"],["Elle regarde son fils avec fierté.","她自豪地看着儿子。"]],"co":[["avec fierté","自豪地"],["ressentir de la fierté","感到自豪"],["être la fierté de","是……的骄傲"],["une fierté légitime","正当的自豪"]],"sy":[["orgueil","soutenu","傲气，多含贬义"],["satisfaction","courant","满足"],["dignité","soutenu","尊严"]],"fq":"中频，情感表达常用。","me":"fier + té：一种「fier」的状态。","tr":{"zh":"她为儿子感到自豪。","fr":"Elle est pleine de fierté pour son fils.","alt":"Elle est très fière de son fils.","note":"fier / fière de qqn：口语里更自然。"}},
 "L'apesanteur": {"pos":"n.f. 阴性名词，通常不加复数","s":"失重；零重力。宇航员在太空漂浮的状态。en apesanteur = 处于失重状态。比喻「轻飘飘的感觉」也可用。","ipa":"[a.pə.zɑ̃.tœʁ]","ph":"a-pe-san-teur：s 在元音间读 [z]；-an- 读 [ɑ̃]；-eur 读 [œʁ]。","pi":"s 读 [z]，不读 [s]；-eur 读 [œʁ]，r 要发；pesanteur 的 e 读 [ə]（轻）。","et":"a-（无）+ pesanteur（重量，来自 peser）。同族：peser、pesant。","ex":[["Les astronautes sont en apesanteur.","宇航员处于失重状态。"],["En apesanteur, on flotte dans l'air.","失重时人会在空中飘浮。"]],"co":[["en apesanteur","处于失重状态"],["flotter en apesanteur","在失重中漂浮"],["un vol en apesanteur","失重飞行"]],"sy":[["gravité","courant","重力，反义"],["pesanteur","courant","重力；反义词"]],"fq":"低频，科学话题里。","me":"a（没有）+ pesanteur（重量）：没有重量。","tr":{"zh":"在太空里一切都在飘浮。","fr":"Dans l'espace, tout flotte en apesanteur.","alt":"Dans l'espace, il n'y a plus de pesanteur : tout flotte.","note":"en apesanteur 表示状态。"}},
 "L'essence de": {"pos":"n.f. 阴性名词，复数 essences；常用结构 l'essence de + 名词","s":"……的本质；精髓。essence 在抽象意义上指事物最核心的东西：l'essence de la vie。注意与「汽油」同形，靠上下文区分。","ipa":"[e.sɑ̃s də]","ph":"essence 读 [e.sɑ̃s]，ss 读 [s]；de 读 [də]。","pi":"-ence 读 [ɑ̃s]；和「汽油」同形，靠搭配区分；l'essence de 后面接名词，不是 d'essence。","et":"拉丁语 essentia，源于 esse（是）。同族：essentiel、quintessence。","ex":[["L'essence du voyage est dans le déplacement, pas dans la destination.","旅行的本质在于路上，而不在目的地。"],["C'est l'essence même de la démocratie.","这正是民主的本质。"]],"co":[["l'essence même de","……的真正本质"],["par essence","本质上"],["saisir l'essence de","抓住……的本质"]],"sy":[["nature","courant","本性"],["cœur","courant","核心，实质"],["quintessence","littéraire","精髓"]],"fq":"中频，书面和讨论里。","me":"essence ← être：事物「是」什么，就是它的本质。","tr":{"zh":"这就是这个故事的本质。","fr":"C'est l'essence de cette histoire.","alt":"Voilà ce qui fait l'essence de cette histoire.","note":"l'essence de + 名词：……的本质。"}},
 "L'Europe de l'Est": {"pos":"n.f. 阴性专有名词，不加复数；L'Europe de l'Est","s":"东欧。Europe 是阴性，国家名 / 地区名前用 en：en Europe de l'Est（在东欧）。反义：l'Europe de l'Ouest（西欧）。","ipa":"[ø.ʁɔp də lɛst]","ph":"Europe 读 [ø.ʁɔp]，eu 读 [ø]；de l'Est 里 Est 读 [ɛst]，st 都要发。","pi":"eu 读 [ø]，不读 [ju]；Est 的 s、t 都发音 [ɛst]；用 en Europe，不用 à。","et":"Europe ← 希腊语 Eurōpē（神话中的公主）；est 来自日耳曼语（法兰克语 *ôst）。","ex":[["Je visite l'Europe de l'Est.","我游览东欧。"],["Ils voyagent en Europe de l'Est cet été.","他们今年夏天去东欧旅行。"]],"co":[["en Europe de l'Est","在东欧"],["les pays d'Europe de l'Est","东欧国家"],["l'Europe de l'Ouest","西欧"],["l'Europe centrale","中欧"]],"sy":[["Europe orientale","soutenu","东欧，较书面"],["pays de l'Est","courant","东方国家"]],"fq":"中频，地理和旅游话题里。","me":"Est：像英语 east，e-s-t 都要读。","tr":{"zh":"今年夏天我想去东欧。","fr":"Cet été, je veux aller en Europe de l'Est.","alt":"Cet été, j'ai envie de partir en Europe de l'Est.","note":"地区名阴性，前面用 en。"}},
 "L'exploration": {"pos":"n.f. 阴性名词，复数 explorations","s":"探索；勘探；考察。去陌生地方发现新东西。l'exploration de l'espace = 太空探索；也可指对问题的研究。","ipa":"[ɛk.splɔ.ʁa.sjɔ̃]","ph":"ex 读 [ɛk]；pl 连读 [spl] 中的 s 和 p：[ɛk.splɔ]；-tion 读 [sjɔ̃]。","pi":"-tion 读 [sjɔ̃]，不是 [ʃən]；ex 后接辅音读 [ɛk]；pl 要连读。","et":"来自拉丁语 exploratio，源于 explorare（探查）。同族：explorer、explorateur。","ex":[["L'exploration de l'espace est fascinante.","太空探索令人着迷。"],["L'exploration de cette grotte a pris deux jours.","考察这个山洞花了两天。"]],"co":[["l'exploration spatiale","太空探索"],["partir à l'exploration de","出发去探索"],["l'exploration d'une région","对一个地区的考察"]],"sy":[["découverte","courant","发现"],["recherche","courant","研究，寻找"],["prospection","soutenu","勘探（矿产）"]],"fq":"中频，科学和旅游话题里。","me":"explor + ation：像英语 exploration。","tr":{"zh":"我喜欢探索新的城市。","fr":"J'aime l'exploration de nouvelles villes.","alt":"J'adore explorer de nouvelles villes.","note":"口语里常直接用动词 explorer。"}},
 "L'hospitalité": {"pos":"n.f. 阴性名词，不加复数（一般不可数）","s":"好客；款待。对客人热情接待。le sens de l'hospitalité = 好客之道。hôpital（医院）和 hôte（主人 / 客人）同族。","ipa":"[ɔs.pi.ta.li.te]","ph":"h 不发音（哑 h），所以 l'hospitalité 要省音；os 读 [ɔs]；-té 读 [te]。","pi":"h 不发音，用 l' 而不是 la；开头 o 读 [ɔ]；五个音节，别漏掉 [li]。","et":"来自拉丁语 hospitalitas，源于 hospes（主人、客人）。同族：hôte、hôtel、hôpital。","ex":[["L'hospitalité de ce pays est connue.","这个国家的好客众所周知。"],["Merci pour votre hospitalité.","谢谢您的款待。"]],"co":[["remercier pour son hospitalité","感谢款待"],["offrir l'hospitalité","提供款待 / 留宿"],["l'hospitalité légendaire","著名的好客"],["une chambre d'hôtes","民宿"]],"sy":[["accueil","courant","接待，欢迎"],["générosité","courant","慷慨"],["convivialité","courant","亲切融洽的气氛"]],"fq":"中频，旅游话题里。","me":"hospi-talité：hôtel、hôpital、hôte 一家子。","tr":{"zh":"谢谢你们的热情款待。","fr":"Merci pour votre hospitalité.","alt":"Merci de nous avoir si bien accueillis.","note":"merci pour + 名词。"}},
 "L'Odyssée": {"pos":"n.f. 阴性专有名词；也可作普通名词 une odyssée（漫长的冒险旅程）","s":"《奥德赛》，荷马的史诗，讲 Ulysse（奥德修斯）回家的漫长旅程。小写 une odyssée = 漫长而曲折的冒险。","ipa":"[ɔ.di.se]","ph":"o 读 [ɔ]；dy 读 [di]；ssée 读 [se]，ss 读 [s]。","pi":"y 读 [i]；ssée 读 [se]，不读 [sɛ]；作书名时大写 L'Odyssée。","et":"来自希腊语 Odusseia，荷马史诗，以主人公 Odysseus 命名。","ex":[["L'Odyssée est le célèbre livre d'Homère.","《奥德赛》是荷马的著名作品。"],["Leur voyage fut une véritable odyssée.","他们的旅行简直是一场史诗般的冒险。"]],"co":[["une véritable odyssée","一场真正的漫长冒险"],["l'Iliade et l'Odyssée","《伊利亚特》与《奥德赛》"],["une odyssée spatiale","太空奥德赛"]],"sy":[["périple","courant","漫长旅程"],["aventure","courant","冒险"],["épopée","littéraire","史诗"]],"fq":"低频，文学和文化话题里。","me":"Odyssée ← Ulysse：回家路上的大冒险。","tr":{"zh":"我正在读《奥德赛》。","fr":"Je lis L'Odyssée en ce moment.","alt":"En ce moment, je lis L'Odyssée d'Homère.","note":"书名大写，L'Odyssée。"}},
 "La banquise": {"pos":"n.f. 阴性名词，复数 banquises","s":"浮冰；海冰；冰层。极地海面上结冰的大块冰。la banquise fond = 海冰正在融化，是气候变化的常见话题。","ipa":"[bɑ̃.kiz]","ph":"ban 读 [bɑ̃]；qui 读 [ki]；se 读 [z]，s 在元音间读 [z]。","pi":"qu 读 [k]；s 读 [z]；-an- 读 [ɑ̃]；和 banque（银行）读音接近但不同：banque [bɑ̃k]。","et":"来源不确定；与 banc（长凳、冰排）可能有关，但不能完全肯定。","ex":[["La banquise fond.","浮冰在融化。"],["Les ours polaires vivent sur la banquise.","北极熊住在海冰上。"]],"co":[["la fonte de la banquise","海冰融化"],["sur la banquise","在海冰上"],["la banquise arctique","北极海冰"]],"sy":[["glace","courant","冰"],["iceberg","courant","冰山，是脱落的冰块"],["glacier","courant","冰川（陆地）"]],"fq":"中频，环保和极地话题里。","me":"banquise ≠ banque：一个在银行，一个在极地。","tr":{"zh":"北极的海冰越来越薄。","fr":"La banquise de l'Arctique devient de plus en plus fine.","alt":"La banquise arctique s'amincit chaque année.","note":"de plus en plus + 形容词：越来越。"}},
 "La basse/haute saison": {"pos":"n.f. 阴性名词，复数 basses saisons / hautes saisons","s":"淡季 / 旺季。旅游业用语：la haute saison 价格高、人多；la basse saison 价格低、人少。haute 的 h 是哑 h，不能连读。","ipa":"[bas sɛ.zɔ̃ / ot sɛ.zɔ̃]","ph":"basse 读 [bas]；haute 读 [ot]，h 不发音但不能连读；saison 读 [sɛ.zɔ̃]，s 读 [z]。","pi":"haute 的 h 是哑 h（h aspiré），所以 la haute，不可省音；saison 里 ai 读 [ɛ]，s 读 [z]；ai 不读 [ai]。","et":"saison ← 拉丁语 satio（播种）；basse ← bas；haute ← haut（拉丁语 altus）。","ex":[["Les prix augmentent en haute saison.","旺季价格上涨。"],["En basse saison, la plage est vide.","淡季时海滩空无一人。"]],"co":[["en haute saison","旺季时"],["en basse saison","淡季时"],["la pleine saison","旺季高峰"],["hors saison","淡季，非当季"]],"sy":[["hors saison","courant","淡季，非旺季"],["pleine saison","courant","旺季高峰"]],"fq":"中频，旅游话题里。","me":"haute = 高（高价）；basse = 低（低价）。","tr":{"zh":"我们想在淡季去旅行，更便宜。","fr":"Nous voulons voyager en basse saison, c'est moins cher.","alt":"On préfère partir hors saison, c'est moins cher.","note":"en basse saison：en + 时期。"}},
 "La conception": {"pos":"n.f. 阴性名词，复数 conceptions","s":"设计；构想；观念。1) 产品的设计：la conception d'un logiciel。2) 观点、看法：ma conception de la vie。3) 怀孕（受孕，科学用语）。","ipa":"[kɔ̃.sɛp.sjɔ̃]","ph":"con 读 [kɔ̃]；cep 读 [sɛp]；tion 读 [sjɔ̃]。","pi":"con 是鼻化元音 [kɔ̃]；-tion 读 [sjɔ̃]；p 要发音 [sɛp]，不要漏掉。","et":"来自拉丁语 conceptio，源于 concipere（容纳、构想）。同族：concevoir、concept。","ex":[["La conception de ce projet a pris du temps.","这个项目的设计花了很长时间。"],["Nous n'avons pas la même conception du travail.","我们对工作的看法不同。"]],"co":[["la conception d'un produit","产品设计"],["une conception du monde","世界观"],["être conçu pour","为……而设计"],["la conception assistée par ordinateur","计算机辅助设计"]],"sy":[["design","courant","设计（外观）"],["idée","courant","想法"],["vision","courant","看法"]],"fq":"中高频，工作和讨论里。","me":"conception ← concevoir：把一个想法「怀」出来。","tr":{"zh":"这个玩具的设计很简单。","fr":"La conception de ce jouet est très simple.","alt":"Ce jouet est conçu de façon très simple.","note":"concevoir 的过去分词 conçu。"}},
 "La démocratisation": {"pos":"n.f. 阴性名词，复数 démocratisations","s":"普及化；民主化。1) 让更多人能用到：la démocratisation du voyage。2) 政治上变得民主。第一个意思在日常谈话里更常见。","ipa":"[de.mɔ.kʁa.ti.za.sjɔ̃]","ph":"dé 读 [de]；mo 读 [mɔ]；cra 读 [kʁa]；ti 读 [ti]；sa 读 [za]；tion 读 [sjɔ̃]。","pi":"词很长，六个音节，分开读；-sa- 的 s 读 [z]；-tion 读 [sjɔ̃]。","et":"由 démocratie（希腊语 dêmos 人民 + kratos 权力）→ démocratiser（动词）→ -ation。","ex":[["La démocratisation d'internet est rapide.","互联网的普及很快。"],["La démocratisation de l'avion a changé les voyages.","飞机的普及改变了旅行。"]],"co":[["la démocratisation de l'accès","（某物）使用权的普及"],["la démocratisation du voyage","旅行的大众化"],["une démocratisation rapide","迅速的普及"]],"sy":[["généralisation","courant","普遍化"],["vulgarisation","courant","（知识）通俗化"],["popularisation","courant","大众化"]],"fq":"中低频，书面和新闻里。","me":"démocratie → démocratiser → démocratisation，一步一步加长。","tr":{"zh":"智能手机的普及很快。","fr":"La démocratisation du smartphone a été très rapide.","alt":"Tout le monde a un smartphone maintenant : ça s'est répandu très vite.","note":"a été：passé composé de être。"}},
 "La destruction": {"pos":"n.f. 阴性名词，复数 destructions","s":"破坏；毁灭。la destruction de la forêt = 森林被毁。可指故意或自然的破坏，常见于环保、战争话题。动词是 détruire。","ipa":"[dɛs.tʁyk.sjɔ̃]","ph":"des 读 [dɛs]；truc 读 [tʁyk]，c 读 [k]；tion 读 [sjɔ̃]。","pi":"c 读 [k]（truc 里的 c）；-tion 读 [sjɔ̃]；u 读 [y]；与动词 détruire 拼写不同。","et":"来自拉丁语 destructio，源于 destruere（de- + struere 建造 → 拆毁）。同族：détruire、construction。","ex":[["La destruction de la forêt est triste.","森林被毁令人难过。"],["La destruction du pont a pris une journée.","拆毁那座桥花了一天。"]],"co":[["la destruction de l'environnement","对环境的破坏"],["des armes de destruction massive","大规模杀伤性武器"],["la destruction d'un bâtiment","拆毁建筑"]],"sy":[["démolition","courant","拆除（建筑）"],["ravage","soutenu","严重破坏"],["dégât","courant","损害"]],"fq":"中高频，新闻和环保话题里。","me":"de（反）+ struction（建造）：反着建造，就是破坏。","tr":{"zh":"森林被毁让他很伤心。","fr":"La destruction de la forêt le rend triste.","alt":"Voir la forêt détruite le rend triste.","note":"rendre qqn + 形容词：使某人……"}},
 "La diaspora": {"pos":"n.f. 阴性名词，复数 diasporas","s":"散居群体，侨民；指一个民族离开故土、分散在世界各地的人群。常说 la diaspora chinoise / juive / irlandaise。","ipa":"[dja.spɔ.ʁa]","ph":"dia 读 [dja]；sp 连读；结尾 -a 读 [a]，不发多余音。","pi":"重音在最后一个音节 [ʁa]；r 是小舌擦音 [ʁ]；注意是阴性：la diaspora。","et":"希腊语 diaspora（分散、撒播）。","ex":[["La diaspora irlandaise est grande.","爱尔兰侨民很多。"],["Une partie de la diaspora revient chaque été.","一部分侨民每年夏天回来。"]],"co":[["la diaspora chinoise","华人侨民群体"],["au sein de la diaspora","在侨民群体中"],["la diaspora africaine","非洲裔散居群体"]],"sy":[["émigrés","courant","移居国外的人"],["communauté","courant","社群（范围更宽）"]],"fq":"中低频，新闻和历史里常见。","me":"dia-spora：像撒种子一样「撒」向各地的人。","tr":{"zh":"他们属于一个很大的侨民群体。","fr":"Ils font partie d'une grande diaspora.","alt":"Ils appartiennent à une diaspora très importante.","note":"faire partie de + 名词 = 属于。"}},
 "La faune": {"pos":"n.f. 阴性名词（通常用单数）","s":"某地区的动物群，野生动物的总称。常与 la flore（植物群）成对出现：la faune et la flore。不指单个动物。","ipa":"[fon]","ph":"au 读 [o]；n 后的 e 不发音；整词一个音节。","pi":"au 读 [o]，不是「奥乌」；结尾 e 不发音。","et":"拉丁语 Faunus（罗马神话中的森林之神），后来指一地的动物群。","ex":[["La faune locale est riche.","当地野生动物丰富。"],["Dans ce parc, on protège la faune et la flore.","这个公园保护动植物。"]],"co":[["la faune et la flore","动物群与植物群"],["la faune sauvage","野生动物"],["la faune marine","海洋动物"]],"sy":[["animaux","courant","动物（泛指，更日常）"],["flore","courant","反义对照：植物群"]],"fq":"中频，自然、旅游、环保话题常用。","me":"faune ≈ fauna：和 flore（植物）是一对。","tr":{"zh":"这个公园保护野生动物。","fr":"Ce parc protège la faune sauvage.","alt":"Dans ce parc, on protège les animaux sauvages.","note":"la faune 用单数，带定冠词。"}},
 "La législation": {"pos":"n.f. 阴性名词，复数 législations","s":"立法；（某一领域的）法规总体。la législation du travail = 劳动法规。不是单一的一条法律（那是 une loi）。","ipa":"[le.ʒis.la.sjɔ̃]","ph":"lé [le]；g 在 i 前读 [ʒ]；-tion 读 [sjɔ̃]。","pi":"-tion 读 [sjɔ̃]，不是 [ʃən]；g 读 [ʒ]。","et":"拉丁语 legis latio（提出法律）。同源：légal、législateur。","ex":[["La législation a changé.","法规变了。"],["La législation sur le travail est stricte en France.","法国的劳动法规很严格。"]],"co":[["la législation en vigueur","现行法规"],["la législation du travail","劳动法规"],["durcir la législation","收紧法规"]],"sy":[["loi","courant","一条具体的法律"],["réglementation","courant","规章、条例"],["droit","courant","法律（学科或体系）"]],"fq":"中频，新闻、法律、工作场合常见。","me":"lég- = 法（légal）；législation = 法的总和。","tr":{"zh":"新的法规明年生效。","fr":"La nouvelle législation entre en vigueur l'année prochaine.","alt":"La nouvelle loi s'applique dès l'an prochain.","note":"entrer en vigueur = 生效。"}},
 "La mobilité": {"pos":"n.f. 阴性名词，复数 mobilités","s":"流动性；出行能力。可指人的出行（la mobilité urbaine 城市出行）、职业流动（la mobilité professionnelle）或行动能力（la mobilité réduite 行动不便）。","ipa":"[mɔ.bi.li.te]","ph":"o 读开口 [ɔ]；-é 读 [e]；四个音节。","pi":"重音在最后；不要把 mobilité 读成「莫比利提」带重读 t 的样子，t 轻、e 是 [e]。","et":"拉丁语 mobilitas，来自 mobilis（可动的）。同源：mobile、immobile。","ex":[["La mobilité est importante en ville.","城市里出行很重要。"],["Les personnes à mobilité réduite ont besoin d'une rampe.","行动不便的人需要坡道。"]],"co":[["la mobilité urbaine","城市出行"],["la mobilité professionnelle","职业流动"],["à mobilité réduite","行动不便的"],["la mobilité douce","绿色出行（步行、骑车）"]],"sy":[["déplacement","courant","具体的一次出行"],["transport","courant","交通、运输"]],"fq":"中频，交通、社会话题常见。","me":"mobile + -ité：能「动」的特性。","tr":{"zh":"绿色出行对城市有好处。","fr":"La mobilité douce est bonne pour la ville.","alt":"Se déplacer à pied ou à vélo, c'est bon pour la ville.","note":"mobilité douce 指步行、骑车等低碳出行。"}},
 "La planification": {"pos":"n.f. 阴性名词，复数 planifications","s":"规划；计划的制定与安排。指系统地做计划（la planification familiale 计划生育，la planification urbaine 城市规划）。比 plan（一个具体计划）更抽象。","ipa":"[pla.ni.fi.ka.sjɔ̃]","ph":"-tion 读 [sjɔ̃]；c 在 a 前读 [k]；五个音节。","pi":"c 读 [k]；-tion 读 [sjɔ̃]；音节多，分段读。","et":"由 plan + planifier（-ifier 构成动词）+ -ation 构成。","ex":[["La planification est essentielle.","规划至关重要。"],["Une bonne planification évite les erreurs.","好的规划能避免错误。"]],"co":[["la planification familiale","计划生育"],["la planification urbaine","城市规划"],["une bonne planification","良好的规划"]],"sy":[["organisation","courant","组织、安排"],["programmation","courant","安排日程、编程"],["plan","courant","具体的计划"]],"fq":"中低频，工作和行政场合用。","me":"plan → planifier → planification：一步步变长。","tr":{"zh":"旅行前需要好好规划。","fr":"Avant le voyage, il faut bien planifier.","alt":"Pour ce voyage, une bonne planification est nécessaire.","note":"动词 planifier = 规划，名词 la planification。"}},
 "La reprise économique": {"pos":"n.f. 阴性名词词组，复数 reprises économiques","s":"经济复苏。reprise 指「重新开始、回升」，économique 为形容词，放在名词后。la reprise 也可指电影重映、剧目重演、接手店铺。","ipa":"[ʁə.pʁiz e.kɔ.nɔ.mik]","ph":"reprise 中 s 读 [z]；économique 中 é 读 [e]，qu 读 [k]；两词可连读。","pi":"reprise 的 s 是 [z]；économique 重音在 -mique；r 是小舌音。","et":"reprise 来自 reprendre（re- + prendre，重新拿起）；économique 来自希腊语 oikonomia（管理家务）。","ex":[["La reprise économique est lente.","经济复苏缓慢。"],["On attend la reprise économique depuis deux ans.","我们等经济复苏已经两年了。"]],"co":[["une reprise lente / rapide","缓慢 / 快速的复苏"],["la reprise de l'activité","业务恢复"],["soutenir la reprise","支持复苏"]],"sy":[["relance","courant","重振、刺激（政府的举措）"],["rebond","courant","反弹"]],"fq":"中频，新闻里常见。","me":"re-prise：重新「拿起」经济。","tr":{"zh":"经济复苏比预期慢。","fr":"La reprise économique est plus lente que prévu.","alt":"L'économie repart plus lentement que prévu.","note":"plus … que prévu = 比预期更……"}},
 "La restriction": {"pos":"n.f. 阴性名词，复数 restrictions","s":"限制；约束。多指官方的限制（les restrictions d'eau 限水，les restrictions de circulation 交通管制）。sans restriction = 无限制地。","ipa":"[ʁɛs.tʁik.sjɔ̃]","ph":"re 在 s 前读开口 [ɛ]；-ct- 读 [kt]；-tion 读 [sjɔ̃]。","pi":"re- 在这里读 [ʁɛ]，不是 [ʁə]；-tion 读 [sjɔ̃]。","et":"拉丁语 restrictio，来自 restringere（收紧）。同源：restreindre、restrictif。","ex":[["Cette restriction est sévère.","这项限制很严格。"],["Il y a des restrictions d'eau cet été.","今年夏天有限水措施。"]],"co":[["lever les restrictions","解除限制"],["sans restriction","无限制"],["des restrictions budgétaires","预算紧缩"]],"sy":[["limitation","courant","限制（更中性）"],["interdiction","courant","禁止（更强）"]],"fq":"中频，新闻和公告常见。","me":"re-strict：越收越「严」。","tr":{"zh":"今年夏天有限水措施。","fr":"Il y a des restrictions d'eau cet été.","alt":"Cet été, on doit économiser l'eau, c'est obligatoire.","note":"restriction 多用复数表示一系列措施。"}},
 "La stratosphère": {"pos":"n.f. 阴性名词，复数 stratosphères","s":"平流层，大气层中对流层之上的一层。口语里 dans la stratosphere 也可比喻价格、数字「高得离谱」。","ipa":"[stʁa.tɔs.fɛʁ]","ph":"str 连读；o 读开口 [ɔ]；ph 读 [f]；结尾 -ère 读 [ɛʁ]。","pi":"ph 读 [f]；结尾 r 要发出；重音在最后一个音节。","et":"希腊语 stratos（层）+ sphaira（球），词形上仿 atmosphère。","ex":[["L'avion vole dans la stratosphère.","飞机在平流层飞行。"],["La stratosphère protège la Terre grâce à la couche d'ozone.","平流层靠臭氧层保护地球。"]],"co":[["la couche d'ozone de la stratosphère","平流层的臭氧层"],["monter dans la stratosphère","升到平流层"],["la stratosphère et la troposphère","平流层与对流层"]],"sy":[["atmosphère","courant","大气层（整体）"],["troposphère","soutenu","对流层（下层）"]],"fq":"低频，科学话题用。","me":"strato = 层；sphère = 球：一层「球壳」。","tr":{"zh":"臭氧层在平流层里。","fr":"La couche d'ozone est dans la stratosphère.","alt":"L'ozone se trouve dans la stratosphère.","note":"dans la + 名词，表示位于某层之中。"}},
 "La tentation": {"pos":"n.f. 阴性名词，复数 tentations","s":"诱惑；想做某事的冲动。céder à la tentation = 经不住诱惑。常用 résister à la tentation（抵制诱惑）。","ipa":"[tɑ̃.ta.sjɔ̃]","ph":"en 读 [ɑ̃]；-tion 读 [sjɔ̃]；t 都读 [t]。","pi":"en 读鼻化 [ɑ̃]，不发 n；与 tension 区分：tentation（诱惑）≠ tension（紧张）。","et":"拉丁语 tentatio，来自 temptare / tentare（试探）。同源：tenter（试探；诱惑）。","ex":[["La tentation est grande.","诱惑很大。"],["Je n'ai pas résisté à la tentation de goûter le gâteau.","我没忍住尝了一口蛋糕。"]],"co":[["céder à la tentation","经不住诱惑"],["résister à la tentation","抵制诱惑"],["succomber à la tentation","屈服于诱惑"],["avoir la tentation de + inf.","很想做……"]],"sy":[["envie","courant","想要、冲动"],["appel","courant","召唤，较弱"]],"fq":"中频，日常和文学中都常用。","me":"tenter（试探）→ tentation：被「试」一下就想要。","tr":{"zh":"我没能抵住诱惑。","fr":"Je n'ai pas résisté à la tentation.","alt":"J'ai cédé à la tentation.","note":"résister à + 名词。"}},
 "La veille": {"pos":"n.f. 阴性名词，复数 veilles","s":"前一天；（节日、事件的）前夕。la veille de Noël = 平安夜；la veille au soir = 前一天晚上。也指不睡觉、守夜；也指资讯监测（la veille technologique）。","ipa":"[vɛj]","ph":"-eille 读 [ɛj]；两个 l 合起来是半元音 [j]。","pi":"-eille 读 [ɛj]，不要读出 l；与 la vieille（老妇人，[vjɛj]）易混。","et":"拉丁语 vigilia（守夜），同源 vigile、veiller（熬夜；照看）。","ex":[["Je suis arrivé la veille du départ.","我在出发的前一天到达。"],["La veille de Noël, on mange en famille.","平安夜我们和家人一起吃饭。"]],"co":[["la veille de + 名词","……的前一天"],["la veille au soir","前一天晚上"],["la veille de Noël","平安夜"],["à la veille de","临近……之际"]],"sy":[["lendemain","courant","反义：后一天"],["avant-veille","courant","前天（前两天）"]],"fq":"中高频，日常常用。","me":"veille ↔ lendemain：前一天 / 后一天。","tr":{"zh":"考试前一天我睡得很早。","fr":"La veille de l'examen, je me suis couché tôt.","alt":"La veille de l'examen, je suis allé me coucher de bonne heure.","note":"la veille de + 名词；复合过去时 je me suis couché。"}},
 "La vision": {"pos":"n.f. 阴性名词，复数 visions","s":"视力；视野；看法、眼光。avoir une bonne vision = 视力好。也指对事物的看法（sa vision de l'avenir 他对未来的看法）。也指幻象。","ipa":"[vi.zjɔ̃]","ph":"s 在两个元音之间读 [z]；-ion 读 [jɔ̃]。","pi":"s 读 [z]，不是 [s]；与 vue 不同：vision 偏「视力、看法」。","et":"拉丁语 visio，来自 videre（看）。同源：visible、télévision。","ex":[["Il a une bonne vision.","他视力很好。"],["Elle a une vision claire de l'avenir.","她对未来有清楚的看法。"]],"co":[["avoir une bonne / mauvaise vision","视力好 / 差"],["une vision globale","整体视角"],["la vision de l'avenir","对未来的看法"],["la vision nocturne","夜视"]],"sy":[["vue","courant","视力、景色"],["conception","soutenu","观念、构想"]],"fq":"中频。","me":"vision = 看见（vid-）：télé-vision。","tr":{"zh":"她对公司的发展有清楚的看法。","fr":"Elle a une vision claire de l'avenir de l'entreprise.","alt":"Elle voit bien où va l'entreprise.","note":"avoir une vision de + 名词。"}},
 "La vue": {"pos":"n.f. 阴性名词，复数 vues","s":"景色；视觉；视力。une chambre avec vue sur la mer = 看得到海的房间。en vue de = 为了。à vue d'œil = 目测。","ipa":"[vy]","ph":"u 读 [y]：嘴唇圆起来发「衣」的音。","pi":"u [y] 不是 ou [u]：vue ≠ vou；与 vu（看见的过去分词）同音。","et":"来自动词 voir 的过去分词阴性（vue，看到的东西）。同源：revue、aperçu。","ex":[["La vue est magnifique d'ici.","从这里看风景很美。"],["Nous avons une chambre avec vue sur la mer.","我们有一间能看到海的房间。"]],"co":[["avec vue sur la mer","能看到海景"],["perdre la vue","失明"],["en vue de","为了；以……为目的"],["à première vue","乍一看"]],"sy":[["paysage","courant","风景"],["vision","courant","视力、看法"],["panorama","soutenu","全景"]],"fq":"极高频。","me":"vue 的 u = 嘟起嘴发「衣」。","tr":{"zh":"我们的房间能看到海。","fr":"Notre chambre a vue sur la mer.","alt":"De notre chambre, on voit la mer.","note":"avoir vue sur = 能看到（景）。"}},
 "Une alternative": {"pos":"n.f. 阴性名词，复数 alternatives","s":"替代方案；另一种选择。在法语里 alternative 就是「别的办法」，不要求只有两个选项。形容词 alternatif 如 énergie alternative。","ipa":"[al.tɛʁ.na.tiv]","ph":"al [al]；ter 读 [tɛʁ]；-tive 读 [tiv]。","pi":"重音在最后一个音节 [tiv]；t 都读 [t]；阴性名词 une alternative。","et":"拉丁语 alternare（轮换）。同源：alterner、alternance。","ex":[["C'est une bonne alternative.","这是个好的替代方案。"],["Il n'y a pas d'autre alternative.","没有别的选择了。"]],"co":[["une alternative à + 名词","……的替代方案"],["sans alternative","别无选择"],["chercher une alternative","寻找替代方案"]],"sy":[["solution","courant","解决办法"],["option","courant","选项"],["choix","courant","选择"]],"fq":"中频，工作和新闻里常用。","me":"alter-native：「另一个」(alter) 方案。","tr":{"zh":"你有别的办法吗？","fr":"Tu as une autre solution ?","alt":"Est-ce qu'il y a une alternative ?","note":"une alternative à + 名词。"}},
 "Une approche": {"pos":"n.f. 阴性名词，复数 approches","s":"方法；思路；接近。une approche du problème = 看待、处理问题的方式。也可指「靠近」（à l'approche de l'hiver 临近冬天时）。","ipa":"[a.pʁɔʃ]","ph":"pp 只读一个 [p]；o 读开口 [ɔ]；ch 读 [ʃ]。","pi":"双 p 只读一次；ch 读 [ʃ]；结尾 e 不发音。","et":"来自动词 approcher（拉丁语 ad + prope，靠近）。","ex":[["C'est une bonne approche du problème.","这是个好的解决思路。"],["À l'approche de l'hiver, les jours raccourcissent.","临近冬天，白天变短。"]],"co":[["une approche du problème","处理问题的思路"],["à l'approche de","临近……时"],["une nouvelle approche","新的方法"],["facile d'approche","容易接近的"]],"sy":[["méthode","courant","方法"],["démarche","courant","做法、步骤"],["manière","courant","方式"]],"fq":"中高频。","me":"approche = ad-proche：靠近到问题旁边。","tr":{"zh":"我们需要新的思路。","fr":"Nous avons besoin d'une nouvelle approche.","alt":"Il nous faut une autre façon de voir les choses.","note":"avoir besoin de + 名词。"}},
 "Une ascension": {"pos":"n.f. 阴性名词，复数 ascensions","s":"攀登；上升。l'ascension du Mont Blanc = 攀登勃朗峰。也指社会地位的上升（une ascension sociale）。l'Ascension（大写）是基督教的耶稣升天节。","ipa":"[a.sɑ̃.sjɔ̃]","ph":"sc 在 e/i 前读 [s]；en 读 [ɑ̃]；-ion 读 [jɔ̃]。","pi":"sc 读 [s]，不读 [sk]；en 读鼻化 [ɑ̃]。","et":"拉丁语 ascensio，来自 ascendere（爬上去）。同源：ascenseur（电梯）。","ex":[["L'ascension de cette montagne est difficile.","攀登这座山很难。"],["Son ascension sociale a été rapide.","他的社会地位上升得很快。"]],"co":[["faire l'ascension de","攀登……"],["une ascension sociale","社会地位的上升"],["l'ascension d'une montagne","登山"]],"sy":[["escalade","courant","攀爬，攀岩"],["montée","courant","上坡、上升"],["grimpée","familier","爬坡（口语）"]],"fq":"中低频。","me":"ascension ≈ ascenseur（电梯）：都是往上。","tr":{"zh":"我们明天攀登这座山。","fr":"Demain, nous faisons l'ascension de cette montagne.","alt":"Demain, on monte tout en haut de cette montagne.","note":"faire l'ascension de + 山。"}},
 "Une barre d'immeuble": {"pos":"n.f. 阴性名词词组，复数 des barres d'immeubles","s":"条形（长条状）高层公寓楼，多见于郊区大型住宅区（les cités）。une barre 是「长条」，immeuble 是「楼房」。带一点贬义的城市景观词。","ipa":"[baʁ di.mœbl]","ph":"d'immeuble 中 d' 要和 immeuble 连读：[di.mœbl]；-eu- 读 [œ]；结尾 -ble 的 e 轻读。","pi":"immeuble 的 mm 只读一个 [m]；eu 读 [œ]；une barre 的 r 要发。","et":"barre（长条）+ immeuble（楼房）；immeuble 来自拉丁语 immobilis（不可移动的，即不动产）。","ex":[["Il habite dans une barre d'immeuble.","他住在一栋长条形的公寓楼里。"],["On a démoli plusieurs barres d'immeubles dans la banlieue.","郊区拆除了几栋长条楼。"]],"co":[["habiter dans une barre","住在条形楼里"],["une cité de barres","条形楼住宅区"],["démolir une barre","拆除一栋条形楼"]],"sy":[["tour","courant","塔楼，高楼"],["HLM","courant","廉租房（社会住房）"],["immeuble","courant","楼房（泛指）"]],"fq":"中低频，谈城市和社会时用。","me":"barre = 长条：像一根横躺的「杆子」。","tr":{"zh":"他从小住在郊区的条形楼里。","fr":"Il a grandi dans une barre d'immeuble en banlieue.","alt":"Petit, il habitait dans une grande barre en banlieue.","note":"grandir 的复合过去时用 avoir：il a grandi。"}},
 "Une bonne action": {"pos":"n.f. 阴性名词词组，复数 de bonnes actions","s":"善举，好事。faire une bonne action = 做件好事。注意 bonne 在名词前，复数时 de bonnes actions（前面用 de）。une B.A. 是童子军说法。","ipa":"[bɔn ak.sjɔ̃]","ph":"bonne 的 nn 读 [n]，前面 o 读 [ɔ]；action 读 [ak.sjɔ̃]；une bonne action 可连读。","pi":"bonne 不是鼻化音（和 bon 不同），n 要发出来；-tion 读 [sjɔ̃]。","et":"bon（拉丁语 bonus）+ action（拉丁语 actio，来自 agere 做）。","ex":[["Il a fait une bonne action.","他做了件好事。"],["Aider ce voisin, c'est une bonne action.","帮这位邻居是件好事。"]],"co":[["faire une bonne action","做件好事"],["une bonne action du jour","今天的善行"],["de bonnes actions","一些善举"]],"sy":[["geste","courant","举动（可好可坏）"],["bienfait","soutenu","恩惠、善行"],["B.A.","familier","童子军说法的「好事」"]],"fq":"中频，日常常用。","me":"bonne = 阴性，n 要发；action = 行为。","tr":{"zh":"今天我想做件好事。","fr":"Aujourd'hui, je veux faire une bonne action.","alt":"Aujourd'hui, j'ai envie de rendre service à quelqu'un.","note":"vouloir + 动词原形。"}},
 "Une carte": {"pos":"n.f. 阴性名词，复数 cartes","s":"地图；卡片；菜单；纸牌。une carte de la ville = 城市地图；une carte bancaire = 银行卡；la carte d'un restaurant = 菜单；jouer aux cartes = 打牌。","ipa":"[kaʁt]","ph":"c 在 a 前读 [k]；r 是小舌音 [ʁ]；结尾 t 要发。","pi":"结尾 -rte 的 t 要读出；一词多义，要看语境。","et":"拉丁语 charta（纸），经古法语。同源：charte、carton。","ex":[["Je me repère avec une carte.","我用地图辨别方向。"],["Peux-tu me montrer la carte, s'il vous plaît ?","请把菜单给我看看，好吗？"]],"co":[["une carte bancaire","银行卡"],["une carte d'identité","身份证"],["jouer aux cartes","打牌"],["une carte postale","明信片"]],"sy":[["plan","courant","市区平面图"],["menu","courant","套餐（不同于 la carte 菜单）"]],"fq":"极高频。","me":"carte = 一张「纸」：地图、卡片、菜单都是纸。","tr":{"zh":"你有这座城市的地图吗？","fr":"Tu as une carte de la ville ?","alt":"Tu as un plan de la ville ?","note":"地图可说 carte，市区图常说 plan。"}},
 "Une catastrophe": {"pos":"n.f. 阴性名词，复数 catastrophes","s":"灾难；大祸。也夸张地说「糟透了」：C'est une catastrophe ! 一场考试没考好也可说 une catastrophe。en catastrophe = 紧急地。","ipa":"[ka.ta.stʁɔf]","ph":"ca [ka]；str 连读；o 读 [ɔ]；ph 读 [f]。","pi":"ph 读 [f]；r 为小舌音；重音在最后一个音节。","et":"希腊语 katastrophē（颠覆、结局）。","ex":[["Cette tempête est une catastrophe.","这场风暴是灾难。"],["Mon examen, c'est une catastrophe !","我的考试糟透了！"]],"co":[["une catastrophe naturelle","自然灾害"],["en catastrophe","紧急地，匆忙地"],["courir à la catastrophe","走向灾难"],["éviter la catastrophe","避免灾难"]],"sy":[["désastre","courant","灾难"],["drame","courant","悲剧"],["tragédie","soutenu","惨剧"]],"fq":"中高频，新闻和口语里都常用。","me":"cata-strophe：整个「翻转」崩塌了。","tr":{"zh":"这场地震是一场灾难。","fr":"Ce tremblement de terre est une catastrophe.","alt":"Ce séisme est un vrai désastre.","note":"une catastrophe 是阴性。"}},
 "Une chute": {"pos":"n.f. 阴性名词，复数 chutes","s":"摔倒；下降；落下。faire une chute = 摔了一跤；la chute des prix = 价格下跌；les chutes d'eau 瀑布；la chute des feuilles 落叶。","ipa":"[ʃyt]","ph":"ch 读 [ʃ]；u 读 [y]（嘴圆）；结尾 t 要读。","pi":"u [y] 不是 ou [u]；结尾 t 要发；chute ≠ shoot。","et":"来自古法语动词 choir（落下），拉丁语 cadere。同源：déchéance、chance。","ex":[["J'ai fait une chute au ski.","我滑雪时摔了一跤。"],["La chute des prix aide les clients.","价格下跌对顾客有利。"]],"co":[["faire une chute","摔一跤"],["une chute de neige","降雪"],["la chute des prix","价格下跌"],["une chute libre","自由落体"]],"sy":[["tomber","courant","动词：摔倒"],["baisse","courant","下降"],["dégringolade","familier","暴跌"]],"fq":"中高频。","me":"chute 的 ch [ʃ]：「嘘」——一声就摔下去了。","tr":{"zh":"他在冰上摔了一跤。","fr":"Il a fait une chute sur la glace.","alt":"Il est tombé sur la glace.","note":"faire une chute / tomber 都可以。"}},
 "Une conception": {"pos":"n.f. 阴性名词，复数 conceptions","s":"观念；构想；设计。sa conception de la vie = 他的人生观。也指怀孕（la conception d'un enfant）和产品设计。conception assistée par ordinateur = 电脑辅助设计。","ipa":"[kɔ̃.sɛp.sjɔ̃]","ph":"on 读 [ɔ̃]；ce 读 [sɛ]；p 要发 [p]；-tion 读 [sjɔ̃]。","pi":"con 为鼻化 [ɔ̃]；p 要读出，是 [kɔ̃.sɛp.sjɔ̃]；与 concept 同族。","et":"拉丁语 conceptio，来自 concipere（接受、构想）。同源：concevoir、concept、conceptuel。","ex":[["J'aime sa conception de la vie.","我喜欢他的人生观。"],["La conception de ce bâtiment est moderne.","这栋楼的设计很现代。"]],"co":[["une conception de la vie","人生观"],["la conception d'un produit","产品设计"],["dès la conception","从设计之初"],["une conception moderne","现代的理念"]],"sy":[["idée","courant","想法"],["vision","courant","看法"],["design","courant","设计（外来词）"]],"fq":"中频，写作、讨论中常用。","me":"concevoir → conception：在头脑里「受孕」出一个想法。","tr":{"zh":"我们对教育的看法不同。","fr":"Nous n'avons pas la même conception de l'éducation.","alt":"On ne voit pas l'éducation de la même façon.","note":"pas le / la même + 名词（否定后保留 la même）。"}},
 "Une courbure": {"pos":"n.f. 阴性名词，复数 courbures","s":"曲率；弯曲度。常用于科学和技术：la courbure de la Terre（地球的曲率）、la courbure du dos（背部的弧度）。比 courbe（曲线）更偏「弯曲程度」。","ipa":"[kuʁ.byʁ]","ph":"ou 读 [u]；ur 读 [yʁ]；两个 r 都要发小舌音。","pi":"ou [u] 和 u [y] 同时出现：cour-bure；结尾 r 要读。","et":"由 courber（弯曲）+ -ure 构成；courber 来自拉丁语 curvare。同源：courbe。","ex":[["On peut voir la courbure de la Terre depuis l'espace.","从太空可以看到地球的曲率。"],["La courbure de ce pont est élégante.","这座桥的弧度很优美。"]],"co":[["la courbure de la Terre","地球的曲率"],["la courbure du dos","背部的弧度"],["une forte courbure","明显的弯曲"]],"sy":[["courbe","courant","曲线"],["arrondi","courant","圆弧形"]],"fq":"低频，科学、技术用语。","me":"courb(e) + -ure：弯的「程度」。","tr":{"zh":"从飞机上能看到地球的曲率。","fr":"On voit la courbure de la Terre depuis l'avion.","alt":"Depuis l'avion, la Terre a l'air un peu courbe.","note":"depuis + 地点 = 从……（看）。"}},
 "Une croisière": {"pos":"n.f. 阴性名词，复数 croisières","s":"游轮旅行，乘船巡游。partir en croisière = 去乘游轮。也指河上游船（une croisière sur le Nil）。","ipa":"[kʁwa.zjɛʁ]","ph":"oi 读 [wa]；s 在元音间读 [z]；-ière 读 [jɛʁ]。","pi":"oi 读 [wa]，不是「欧伊」；s 读 [z]；结尾 r 要读。","et":"来自动词 croiser（原义：沿着交叉的航线巡航），croiser 又来自 croix。","ex":[["Nous partons en croisière.","我们去乘游轮。"],["Ils ont fait une croisière en Méditerranée.","他们在地中海坐了游轮。"]],"co":[["partir en croisière","去乘游轮"],["faire une croisière","乘游轮旅行"],["un bateau de croisière","游轮"],["la vitesse de croisière","巡航速度"]],"sy":[["voyage en bateau","courant","乘船旅行"],["traversée","courant","横渡"]],"fq":"中频，旅游话题常见。","me":"croisière：在海上不断「交叉」地巡游。","tr":{"zh":"明年夏天我们去坐游轮。","fr":"L'été prochain, nous partons en croisière.","alt":"L'été prochain, on part faire une croisière.","note":"partir en croisière，不用冠词。"}},
 "Une escale": {"pos":"n.f. 阴性名词，复数 escales","s":"中途停留；中转。航班、轮船途中停靠一站：faire escale à Dubaï。un vol sans escale = 直飞航班。","ipa":"[ɛs.kal]","ph":"es 读 [ɛs]；c 在 a 前读 [k]；结尾 e 不发音。","pi":"es 读 [ɛs]，不是 [e]；注意是阴性：une escale。","et":"来自意大利语 / 普罗旺斯语 scala（港口、停靠处），拉丁语 scala 原义为梯子。","ex":[["L'avion fait une escale à Dubaï.","飞机在迪拜中转。"],["Il y a une escale de deux heures à Paris.","在巴黎要中转两小时。"]],"co":[["faire escale à","在……中转 / 停靠"],["un vol sans escale","直飞航班"],["une escale de deux heures","两小时的中转"]],"sy":[["correspondance","courant","转乘、换乘的班次"],["étape","courant","旅途中的一站"],["halte","courant","小憩，停一下"]],"fq":"中频，旅行话题常用。","me":"escale ≈ échelle（梯子）：上岸的「踏板」。","tr":{"zh":"我们在伊斯坦布尔转机。","fr":"Nous faisons escale à Istanbul.","alt":"On a une escale à Istanbul.","note":"faire escale à + 城市。"}},
 "Une excursion": {"pos":"n.f. 阴性名词，复数 excursions","s":"短途旅行；远足；出游。通常当天来回：une excursion en montagne。也可指团体游览（une excursion en car）。","ipa":"[ɛk.sky.ʁsjɔ̃]","ph":"ex 在这里读 [ɛks]；-ion 读 [jɔ̃]。","pi":"ex 读 [ɛks]；-sion 读 [sjɔ̃]；r 不要漏掉。","et":"拉丁语 excursio，来自 excurrere（跑出去）。","ex":[["Nous faisons une excursion en montagne.","我们去山里远足。"],["L'école organise une excursion au musée.","学校组织去博物馆的出游。"]],"co":[["faire une excursion","出游"],["une excursion en montagne","山里远足"],["une excursion d'une journée","一日游"]],"sy":[["balade","familier","散步"],["randonnée","courant","徒步"],["sortie","courant","外出"]],"fq":"中频。","me":"ex-cur-sion：跑 (cur-) 出去 (ex-)。","tr":{"zh":"周日我们去海边玩一天。","fr":"Dimanche, nous faisons une excursion d'une journée à la mer.","alt":"Dimanche, on va passer la journée au bord de la mer.","note":"une excursion d'une journée = 一日游。"}},
 "Une expédition": {"pos":"n.f. 阴性名词，复数 expéditions","s":"探险；远征。une expédition polaire = 极地探险。也指货物的发送（l'expédition d'un colis）。","ipa":"[ɛks.pe.di.sjɔ̃]","ph":"ex 读 [ɛks]；é 读 [e]；-tion 读 [sjɔ̃]。","pi":"ex 读 [ɛks]；-tion 读 [sjɔ̃]；与 exposition（展览）不要混。","et":"拉丁语 expeditio，来自 expedire（使畅通；派出）。同源：expédier（寄送）。","ex":[["C'est une grande expédition.","这是一次大探险。"],["L'expédition part pour le pôle Nord.","探险队前往北极。"]],"co":[["partir en expédition","出发去探险"],["une expédition polaire","极地探险"],["l'expédition d'un colis","包裹的寄送"]],"sy":[["voyage","courant","旅行"],["exploration","soutenu","勘探"],["envoi","courant","寄送"]],"fq":"中低频。","me":"expédier（寄出）→ expédition：派人出发。","tr":{"zh":"他们准备一次去北极的探险。","fr":"Ils préparent une expédition au pôle Nord.","alt":"Ils organisent un voyage d'exploration au pôle Nord.","note":"au pôle Nord：au = à + le。"}},
 "Une foule": {"pos":"n.f. 阴性名词，复数 foules","s":"人群。une foule immense = 人山人海。une foule de + 名词 = 大批……（une foule de questions）。","ipa":"[ful]","ph":"ou 读 [u]；l 要发；结尾 e 不发音。","pi":"ou [u]，不是 u [y]；注意 l 要发；是阴性词。","et":"来自古法语 fouler（踩、挤压），原义为被挤压的人群。","ex":[["Il y a une foule immense.","人山人海。"],["Il y a toujours foule le samedi au marché.","周六市场里总是人很多。"]],"co":[["une foule immense","人山人海"],["une foule de + 名词","大批……"],["il y a foule","人很多"],["fendre la foule","穿过人群"]],"sy":[["monde","familier","人多（il y a du monde）"],["cohue","soutenu","混乱拥挤的人群"],["public","courant","观众"]],"fq":"中高频。","me":"foule ≈ fouler（踩踏）：挤到被踩。","tr":{"zh":"周六集市上人很多。","fr":"Il y a foule au marché le samedi.","alt":"Le samedi, il y a un monde fou au marché.","note":"il y a foule / du monde = 人很多。"}},
 "Une fusée": {"pos":"n.f. 阴性名词，复数 fusées","s":"火箭；烟花火箭。lancer une fusée = 发射火箭。une fusée de détresse = 求救信号弹。","ipa":"[fy.ze]","ph":"u 读 [y]；s 在元音间读 [z]；-ée 读 [e]。","pi":"u [y] 嘴圆；s 读 [z]；结尾 -ée 读 [e]，不发 e 之后的音。","et":"来自古法语 fusee，与 fuseau（纺锤）相关，以形状得名；词源细节不太确定。","ex":[["La fusée décolle ce soir.","火箭今晚发射。"],["Les enfants regardent les fusées du feu d'artifice.","孩子们看烟花火箭。"]],"co":[["lancer une fusée","发射火箭"],["une fusée de détresse","求救信号弹"],["une fusée spatiale","航天火箭"]],"sy":[["missile","courant","导弹"],["engin spatial","soutenu","航天器"]],"fq":"中频。","me":"fusée 的 u [y]：嘴圆，像火箭「嗖」。","tr":{"zh":"火箭明天早上发射。","fr":"La fusée décolle demain matin.","alt":"Demain matin, on lance la fusée.","note":"décoller = 起飞，也用于火箭。"}},
 "Une immersion": {"pos":"n.f. 阴性名词，复数 immersions","s":"沉浸；浸入。une immersion totale = 完全沉浸（如语言学习）。也指浸入水中（l'immersion dans l'eau）。","ipa":"[i.mɛʁ.sjɔ̃]","ph":"im 在这里读 [i.m]（不是鼻化）；ersion 读 [ɛʁ.sjɔ̃]；-sion 读 [sjɔ̃]。","pi":"im- 不是鼻化音，读 [im]，两个 m 只读一个；-sion 读 [sjɔ̃]。","et":"拉丁语 immersio，来自 immergere（浸入）。同源：immerger、submerger。","ex":[["C'est une immersion totale.","这是完全的沉浸体验。"],["Je pars en immersion en France pour apprendre le français.","我去法国沉浸式学法语。"]],"co":[["une immersion totale","完全沉浸"],["en immersion","沉浸式地"],["une immersion linguistique","语言沉浸"],["l'immersion dans l'eau","浸入水中"]],"sy":[["plongée","courant","潜水；扎进去"],["bain linguistique","courant","语言环境"]],"fq":"中低频。","me":"im-mersion：「进入 (im-) + 浸 (merger)」。","tr":{"zh":"我想在法国沉浸式地学习一个月。","fr":"Je veux faire un mois d'immersion en France.","alt":"Je voudrais passer un mois en immersion en France.","note":"un mois d'immersion = 一个月的沉浸。"}},
 "Une montgolfière": {"pos":"n.f. 阴性名词，复数 montgolfières","s":"热气球。得名于法国 Montgolfier 兄弟，1783 年他们发明了热气球。monter en montgolfière = 乘热气球上天。","ipa":"[mɔ̃.gɔl.fjɛʁ]","ph":"mont 读 [mɔ̃]（t 不发音）；g 读 [g]；-ière 读 [jɛʁ]。","pi":"mont 的 t 不发音；golf 的 f 要读；词长，分段读。","et":"来自发明者 Montgolfier 兄弟的姓氏，加后缀 -ière。","ex":[["Nous volons en montgolfière.","我们坐热气球飞行。"],["Le vol en montgolfière commence au lever du soleil.","热气球之旅从日出时开始。"]],"co":[["voler en montgolfière","坐热气球飞行"],["un vol en montgolfière","热气球飞行"],["une fête de la montgolfière","热气球节"]],"sy":[["ballon","courant","气球"],["aérostat","soutenu","航空器（学名）"]],"fq":"低频，旅游话题用。","me":"Montgolfier + -ière = 以兄弟姓氏命名的气球。","tr":{"zh":"我们明早坐热气球。","fr":"Demain matin, nous montons en montgolfière.","alt":"Demain matin, on fait un tour en montgolfière.","note":"en montgolfière 不用冠词。"}},
 "Une opportunité": {"pos":"n.f. 阴性名词，复数 opportunités","s":"机会，良机。une belle opportunité = 好机会。与 une occasion 近义；opportunité 多用于工作和商业，语气稍正式。","ipa":"[ɔ.pɔʁ.ty.ni.te]","ph":"pp 读 [p]；o 开口 [ɔ]；u 读 [y]；-é 读 [e]。","pi":"u 读 [y]；双 p 只读一个；五个音节，重音在最后。","et":"拉丁语 opportunitas，原义「靠近港口、合适」（ob + portus）。","ex":[["C'est une belle opportunité.","这是个好机会。"],["Cette offre est une opportunité à ne pas manquer.","这个优惠是不容错过的机会。"]],"co":[["saisir une opportunité","抓住机会"],["une belle opportunité","好机会"],["manquer une opportunité","错过机会"],["une opportunité de travail","工作机会"]],"sy":[["occasion","courant","机会（日常更常用）"],["chance","courant","运气、机会"],["possibilité","courant","可能性"]],"fq":"中高频，工作场合常用。","me":"opportun(e) + -ité：恰好合适的时刻。","tr":{"zh":"这是一次学习的好机会。","fr":"C'est une belle opportunité pour apprendre.","alt":"C'est une super occasion d'apprendre.","note":"une opportunité pour + 原形动词。"}},
 "Une page": {"pos":"n.f. 阴性名词，复数 pages（注意：un page 是阳性，指侍童）","s":"页，页面。une page du livre = 书的一页；tourner la page = 翻页，也可比喻「翻篇、告别过去」。une page web = 网页。","ipa":"[paʒ]","ph":"p 读 [p]；a 读 [a]；g 在 e 前读 [ʒ]；结尾 e 不发音。","pi":"g 读 [ʒ]，不是 [g]；阴性 la page；阳性 le page 是另一个词。","et":"拉丁语 pagina（页面）。同源：paginer、paginé。","ex":[["Tourne la page du livre.","翻到书的下一页。"],["Lis la page vingt-trois, s'il vous plaît.","请读第二十三页。"]],"co":[["tourner la page","翻页 / 翻篇"],["à la page 12","在第 12 页"],["une page web","网页"],["une page blanche","白纸；创作瓶颈"]],"sy":[["feuille","courant","一张纸"],["écran","courant","屏幕、页面"]],"fq":"极高频。","me":"page ≈ 英语 page：g 读 [ʒ]。","tr":{"zh":"请翻到第十页。","fr":"Ouvrez le livre à la page dix.","alt":"Allez à la page dix, s'il vous plaît.","note":"à la page + 数字。"}},
 "Une parution": {"pos":"n.f. 阴性名词，复数 parutions","s":"出版；问世；发行。la parution du livre = 书的出版。比 publication 更侧重「面世的时刻」。","ipa":"[pa.ʁy.sjɔ̃]","ph":"pa [pa]；ru 读 [ʁy]；-tion 读 [sjɔ̃]。","pi":"u [y] 嘴圆；-tion 读 [sjɔ̃]；r 为小舌音。","et":"来自动词 paraître（出现；出版）的 parution。","ex":[["La parution du livre est prévue pour demain.","这本书预计明天出版。"],["La parution du magazine a lieu chaque mois.","这本杂志每月出版一次。"]],"co":[["la date de parution","出版日期"],["dès sa parution","一出版就……"],["une parution mensuelle","月刊"],["une nouvelle parution","新书 / 新刊"]],"sy":[["publication","courant","出版、发表"],["sortie","courant","上市、发行"]],"fq":"中低频，出版和媒体相关。","me":"paraître → parution：「出现」在读者眼前。","tr":{"zh":"新书下周出版。","fr":"La parution du nouveau livre a lieu la semaine prochaine.","alt":"Le nouveau livre sort la semaine prochaine.","note":"avoir lieu = 举行、发生。"}},
 "Une plus-value": {"pos":"n.f. 阴性名词，复数 plus-values","s":"附加值；增值；（资产的）升值收益。apporter une plus-value = 带来附加价值。也指资本利得（la plus-value sur une vente）。","ipa":"[ply.va.ly]","ph":"plus 在此读 [ply]（s 不发音）；value 读 [va.ly]；u 都是 [y]。","pi":"plus-value 里的 plus 读 [ply]，s 不发音；两个 u 都读 [y]；结尾 e 不发音。","et":"plus（更多）+ value（价值，来自 valoir 的过去分词阴性）。","ex":[["Cela apporte une plus-value.","这带来了附加值。"],["Il a réalisé une belle plus-value en vendant sa maison.","他卖房子赚了一大笔升值收益。"]],"co":[["apporter une plus-value","带来附加值"],["la plus-value d'un produit","产品的附加值"],["réaliser une plus-value","获得增值收益"]],"sy":[["valeur ajoutée","soutenu","附加值（更正式）"],["bénéfice","courant","利润"],["gain","courant","收益"]],"fq":"中低频，经济和商业用语。","me":"plus + value = 多出来的价值。","tr":{"zh":"会外语为你的简历增加价值。","fr":"Parler une langue étrangère est une plus-value pour ton CV.","alt":"Une langue étrangère, ça apporte un plus à ton CV.","note":"parler + 语言，作主语用原形动词。"}},
 "Une PME (Petites et Moyennes Entreprises)": {"pos":"n.f. 阴性名词（缩写），复数 des PME（不变）","s":"中小企业，是 Petite et Moyenne Entreprise 的缩写；une PME 指一家中小企业，复数写 des PME。字母读法：[pe.ɛm.ø]。","ipa":"[pe.ɛm.ø]","ph":"按字母读：P [pe]、M [ɛm]、E [ø]；三个音节分开读。","pi":"字母 E 读 [ø]，不是英语的「衣」；缩写复数不加 s：des PME。","et":"缩写：Petite et Moyenne Entreprise；entreprise 来自 entreprendre（着手做）。","ex":[["Il travaille dans une PME.","他在中小企业工作。"],["Les PME créent beaucoup d'emplois en France.","中小企业在法国创造了很多就业。"]],"co":[["travailler dans une PME","在中小企业工作"],["créer une PME","创办中小企业"],["les PME françaises","法国中小企业"]],"sy":[["entreprise","courant","公司"],["start-up","courant","初创公司"],["TPE","courant","微型企业"]],"fq":"中频，经济话题常见。","me":"P-M-E：三个字母，三个字母音。","tr":{"zh":"我叔叔在一家中小企业当会计。","fr":"Mon oncle est comptable dans une PME.","alt":"Mon oncle fait la comptabilité dans une PME.","note":"职业名词前常省略冠词：il est comptable。"}},
 "Une renommée": {"pos":"n.f. 阴性名词，复数 renommées","s":"名声，声誉（多指好名声）。avoir une grande renommée = 声名远扬。de renommée mondiale = 世界知名。","ipa":"[ʁə.nɔ.me]","ph":"re 读 [ʁə]；nn 读一个 [n]；o 开口 [ɔ]；-ée 读 [e]。","pi":"mm 只读一个 [m]；é 读 [e]；不要与 renommer（重新命名）的变位混淆。","et":"来自动词 renommer（re- + nommer，反复被说起名字）的过去分词阴性。","ex":[["Ce restaurant a une grande renommée.","这家餐厅声名远扬。"],["Un chef de renommée mondiale est venu.","一位世界知名的厨师来了。"]],"co":[["de renommée mondiale","世界知名的"],["avoir une bonne renommée","口碑好"],["acquérir une renommée","获得名声"],["la renommée d'un chef","主厨的名声"]],"sy":[["réputation","courant","声誉（可好可坏）"],["célébrité","courant","名气"],["gloire","soutenu","荣耀"]],"fq":"中频。","me":"re-nommée：名字被「重复」说出。","tr":{"zh":"这位歌手享誉世界。","fr":"Cette chanteuse est de renommée mondiale.","alt":"Cette chanteuse est connue dans le monde entier.","note":"être de renommée mondiale，renommée 不加冠词。"}},
 "Une start-up": {"pos":"n.f. 阴性名词（外来词），复数 des start-up（常不变）","s":"初创公司，尤指科技类。词来自英语，法语中读作 [staʁ.tœp]，通常阴性：une start-up。复数常写 des start-up，也见 des start-ups。","ipa":"[staʁ.tœp]","ph":"star 读 [staʁ]；结尾 up 读 [œp]，不是英语的 [ʌp]。","pi":"法语里 up 读 [œp]；r 为小舌音；通常用阴性。","et":"来自英语 start-up。","ex":[["Il travaille dans une start-up.","他在一家初创公司工作。"],["Cette start-up a levé dix millions d'euros.","这家初创公司融到了一千万欧元。"]],"co":[["créer une start-up","创办初创公司"],["lancer une start-up","推出一家初创公司"],["une start-up française","法国初创公司"]],"sy":[["jeune pousse","soutenu","初创公司（官方推荐用语）"],["entreprise","courant","公司"],["PME","courant","中小企业"]],"fq":"中频，科技、商业话题常用。","me":"start-up 读成 [staʁ.tœp]，不是英语读法。","tr":{"zh":"她和朋友创办了一家初创公司。","fr":"Elle a créé une start-up avec des amis.","alt":"Avec des amis, elle a monté une start-up.","note":"créer une start-up，start-up 通常为阴性。"}},
 "Une surprise": {"pos":"n.f. 阴性名词，复数 surprises","s":"惊喜；意外。faire une surprise à quelqu'un = 给某人一个惊喜。不一定指坏事：une bonne / mauvaise surprise。une fête surprise = 惊喜派对。","ipa":"[syʁ.pʁiz]","ph":"u 读 [y]；r 为小舌音；s 在 -ise 中读 [z]；结尾 e 不发音。","pi":"u [y]、i [i]、s [z]；不要读成 sur-prize 的英语音。","et":"由 sur- + prise（prendre 的过去分词阴性）构成：被「抓住」没防备。","ex":[["J'ai une surprise pour toi.","我给你准备了惊喜。"],["Quelle bonne surprise de te voir !","见到你真是惊喜！"]],"co":[["faire une surprise à qqn","给某人一个惊喜"],["une bonne / mauvaise surprise","惊喜 / 惊吓"],["à ma grande surprise","令我大吃一惊的是"],["une fête surprise","惊喜派对"]],"sy":[["étonnement","soutenu","惊讶"],["stupeur","soutenu","惊愕"]],"fq":"极高频，日常常用。","me":"sur + prise：「被抓个正着」。","tr":{"zh":"我想给妈妈一个惊喜。","fr":"Je veux faire une surprise à ma mère.","alt":"J'ai envie de surprendre ma mère.","note":"faire une surprise à + 人。"}},
 "Une tente": {"pos":"n.f. 阴性名词，复数 tentes","s":"帐篷。dormir sous la tente = 睡帐篷；monter la tente = 搭帐篷。也指大型活动帐篷（une tente de réception）。","ipa":"[tɑ̃t]","ph":"en 读 [ɑ̃]；t 在结尾要读；结尾 e 不发音。","pi":"en 读鼻化 [ɑ̃]，但结尾 t 要读出，所以是 [tɑ̃t]；与 tendre（柔软；伸出）区分。","et":"来自拉丁语 tendere（拉开、张开）的过去分词 tenta（拉开的布）。同源：tendre、tension。","ex":[["Je dors dans une tente.","我睡在帐篷里。"],["Nous montons la tente près du lac.","我们在湖边搭帐篷。"]],"co":[["monter / planter une tente","搭帐篷"],["dormir sous la tente","睡在帐篷里"],["faire du camping sous la tente","露营"],["plier la tente","收帐篷"]],"sy":[["chapiteau","courant","大帐篷（马戏团）"],["abri","courant","遮蔽处"]],"fq":"中频。","me":"tente ← tendre：一块被「拉开」的布。","tr":{"zh":"我们在森林里搭帐篷。","fr":"Nous montons la tente dans la forêt.","alt":"On plante la tente dans la forêt.","note":"monter la tente = 搭帐篷。"}},
 "Une vision du monde": {"pos":"n.f. 阴性名词词组，复数 des visions du monde","s":"世界观；看待世界的方式。chacun a sa vision du monde = 每个人有自己的世界观。比 philosophie 更口语。","ipa":"[vi.zjɔ̃ dy mɔ̃d]","ph":"vision 的 s 读 [z]；du 读 [dy]；monde 的 n 与 o 一起鼻化为 [ɔ̃]，结尾 d 要读。","pi":"s 读 [z]；monde 结尾的 d 要发出 [mɔ̃d]；du 的 u 为 [y]。","et":"vision（拉丁语 visio，来自 videre）+ monde（拉丁语 mundus）。","ex":[["Chacun a sa vision du monde.","每个人都有自己的世界观。"],["Voyager change notre vision du monde.","旅行改变我们的世界观。"]],"co":[["avoir une vision du monde","有一种世界观"],["changer sa vision du monde","改变世界观"],["une vision du monde différente","不同的世界观"]],"sy":[["philosophie","courant","哲学、人生观"],["mentalité","courant","思维方式"],["conception du monde","soutenu","世界观"]],"fq":"中频，写作和讨论中用。","me":"vision（看） + monde（世界）：看世界的方式。","tr":{"zh":"旅行改变了我的世界观。","fr":"Voyager a changé ma vision du monde.","alt":"Mes voyages m'ont fait voir le monde autrement.","note":"Voyager 作主语时用原形。"}},
 "Une voie": {"pos":"n.f. 阴性名词，复数 voies","s":"道路；车道；途径；轨道。une voie rapide = 快速路；la voie ferrée = 铁路；suivre sa propre voie = 走自己的路。也指方法、途径（la voie de la sagesse）。","ipa":"[vwa]","ph":"oi 读 [wa]；e 不读。","pi":"voie [vwa] 与 voix（声音，[vwa]）、voit（看见，[vwa]）同音；拼写要分清。","et":"拉丁语 via（路）。同源：voyage、envoyer、voirie。","ex":[["Il suit sa propre voie.","他走自己的路。"],["Le train est sur la voie 3.","火车在第三站台轨道。"]],"co":[["suivre sa voie","走自己的路"],["une voie rapide","快速路"],["la voie ferrée","铁路"],["en voie de + 名词","在……的过程中"]],"sy":[["chemin","courant","小路"],["route","courant","公路"],["piste","courant","线索，轨迹"]],"fq":"中高频。","me":"voie / voix / voit 三个同音词，拼写靠记忆。","tr":{"zh":"她走了一条与别人不同的路。","fr":"Elle a suivi une voie différente.","alt":"Elle a choisi un autre chemin que les autres.","note":"suivre une voie = 走一条路。"}},
 "CSP+ / CSP- (Catégorie Socio-Professionnelle)": {"pos":"n.f. 阴性名词（缩写：catégorie socio-professionnelle）","s":"社会职业类别，是法国统计和营销里用的分类。CSP+ 指较高收入和较高社会地位的群体，CSP- 指较低的群体。读作 [se.ɛs.pe plys] / [se.ɛs.pe mwɛ̃].","ipa":"[se.ɛs.pe plys]","ph":"按字母读 C [se]、S [ɛs]、P [pe]；+ 读 plus [plys]（此处 s 要发）；- 读 moins [mwɛ̃]。","pi":"+ 读 plus，且 s 要发音 [plys]；- 读 moins [mwɛ̃]；多用于统计和广告。","et":"缩写：catégorie（希腊语 katēgoria）+ socio-professionnelle（社会的 + 职业的）。","ex":[["Il appartient à une CSP+.","他属于高阶社会职业类别。"],["Cette publicité vise les CSP+.","这个广告面向 CSP+ 群体。"]],"co":[["appartenir à une CSP+","属于 CSP+"],["cibler les CSP+","瞄准 CSP+ 人群"],["les CSP-","较低社会职业类别"]],"sy":[["classe sociale","courant","社会阶层"],["milieu social","courant","社会环境"],["catégorie","courant","类别"]],"fq":"低频，统计、市场营销常用。","me":"CSP+ 读 plus，- 读 moins：加号与减号。","tr":{"zh":"这家店的顾客大多是 CSP+。","fr":"Les clients de ce magasin sont surtout des CSP+.","alt":"Ce magasin attire surtout des CSP+.","note":"缩写名词：des CSP+。"}},
 "Des chemins de traverse": {"pos":"n.m.pl. 阳性复数名词词组，单数 un chemin de traverse","s":"小路；近道，抄近路的路。prendre des chemins de traverse 也比喻「绕开常规、走旁门」。字面是穿过田野、不走大路的小路。","ipa":"[ʃə.mɛ̃ də tʁa.vɛʁs]","ph":"ch 读 [ʃ]；min 读 [mɛ̃]；de 读 [də]；traverse 的 -se 读 [ʁs]，s 要读。","pi":"chemin 的 in 为鼻化 [ɛ̃]；traverse 结尾 s 要读 [vɛʁs]；ch 读 [ʃ]。","et":"chemin（高卢语 / 拉丁语 caminus）+ traverse（拉丁语 transversus，横穿的）。","ex":[["Prenons des chemins de traverse.","我们走小路吧。"],["Il a pris des chemins de traverse pour arriver plus vite.","他走小路好更快到达。"]],"co":[["prendre un chemin de traverse","抄近路"],["par des chemins de traverse","通过小路 / 曲折的方式"],["un chemin de traverse","一条近道"]],"sy":[["raccourci","courant","捷径"],["sentier","courant","小径"],["détour","courant","绕路"]],"fq":"中低频，带比喻色彩。","me":"traverse：横穿过去的路。","tr":{"zh":"我们走小路，会更快。","fr":"Prenons un chemin de traverse, ce sera plus rapide.","alt":"Passons par les petits chemins, on ira plus vite.","note":"Prenons… 是 nous 的命令式。"}},
 "Des exportations": {"pos":"n.f.pl. 阴性复数名词，单数 une exportation","s":"出口；出口商品。les exportations ont augmenté = 出口增加了。反义：les importations（进口）。多用复数，指某国或某行业的出口总量。","ipa":"[ɛks.pɔʁ.ta.sjɔ̃]","ph":"ex 读 [ɛks]；or 读 [ɔʁ]；-tion 读 [sjɔ̃]；des 后接元音不连读（词首是 ex）。","pi":"des exportations：des 与 ex 连读，s 读 [z]：[de.zɛks…]；-tion 读 [sjɔ̃]。","et":"拉丁语 exportare（运出去）：ex（外）+ portare（运）。同源：porter、importer。","ex":[["Les exportations ont augmenté.","出口增加了。"],["La France fait de grosses exportations de vin.","法国有大量葡萄酒出口。"]],"co":[["les exportations et les importations","进出口"],["augmenter les exportations","增加出口"],["les exportations de vin","葡萄酒出口"],["une baisse des exportations","出口下降"]],"sy":[["importations","courant","反义：进口"],["commerce extérieur","soutenu","对外贸易"]],"fq":"中频，经济新闻常见。","me":"ex-port：运出（port）去（ex-）。","tr":{"zh":"今年出口下降了。","fr":"Les exportations ont baissé cette année.","alt":"Cette année, on exporte moins.","note":"exportations 多用复数。"}},
 "Des particules fines": {"pos":"n.f.pl. 阴性复数名词词组，单数 une particule fine","s":"细颗粒物（空气污染中的 PM2.5、PM10）。particules fines 指飘在空气中的微小颗粒，常用于环保、健康新闻。","ipa":"[paʁ.ti.kyl fin]","ph":"particule 读 [paʁ.ti.kyl]；-cule 中 c 读 [k]；fines 读 [fin]（s 不发音）。","pi":"fines 的 s 不发音；particule 的 u 为 [y]；des 后接 p 不连读。","et":"particule 来自拉丁语 particula（小部分，pars 的指小形式）；fin 来自拉丁语 finis，意为「细」。","ex":[["La pollution émet des particules fines.","污染排放细颗粒物。"],["Les particules fines sont dangereuses pour la santé.","细颗粒物对健康有害。"]],"co":[["l'émission de particules fines","细颗粒物排放"],["un pic de particules fines","细颗粒物峰值"],["les particules fines PM2,5","PM2.5 细颗粒物"]],"sy":[["poussière","courant","灰尘"],["pollution","courant","污染"],["microparticule","soutenu","微粒"]],"fq":"中频，环保与健康新闻中常见。","me":"particule（小部分）+ fine（细）。","tr":{"zh":"今天空气里细颗粒物很多。","fr":"Il y a beaucoup de particules fines dans l'air aujourd'hui.","alt":"Aujourd'hui, l'air est plein de particules fines.","note":"beaucoup de + 名词。"}},
 "Des recettes": {"pos":"n.f.pl. 阴性复数名词，单数 une recette","s":"收入，收益（尤指营业收入）；另有「食谱」之意（une recette de cuisine）。les recettes de l'État = 国家财政收入。注意 recette 在复数时多指钱。","ipa":"[ʁə.sɛt]","ph":"re [ʁə]；ce 读 [sɛ]；tt 读一个 [t]；结尾 e 不发音。","pi":"tt 只读一个 [t]；des 和 r 之间不连读；一词多义：食谱 / 收入。","et":"拉丁语 recepta，来自 recipere（接收）。同源：recevoir、réception。","ex":[["Cette entreprise fait d'énormes recettes.","这家公司收入很高。"],["Les recettes du cinéma ont augmenté.","电影院的收入增加了。"]],"co":[["les recettes de l'État","国家财政收入"],["recettes et dépenses","收入和支出"],["une recette de cuisine","食谱"],["faire recette","大受欢迎，很赚钱"]],"sy":[["revenus","courant","收入（个人）"],["bénéfices","courant","利润"],["gains","courant","盈利"]],"fq":"中频。","me":"recevoir → recette：「收进来」的钱。","tr":{"zh":"我们的收入今年增加了。","fr":"Nos recettes ont augmenté cette année.","alt":"Cette année, on gagne plus d'argent qu'avant.","note":"recettes 作「收入」时用复数。"}},
 "Des remparts": {"pos":"n.m.pl. 阳性复数名词，单数 un rempart","s":"城墙，城垣。les remparts de la ville = 城市的城墙。也比喻屏障（un rempart contre la violence）。","ipa":"[ʁɑ̃.paʁ]","ph":"em 读 [ɑ̃]；p 读 [p]；结尾 t 不发音；复数 s 也不发音。","pi":"rempart 结尾 t 不发音，读 [ʁɑ̃.paʁ]；des 与 r 不连读。","et":"来自 remparer（re- + emparer，加固防守）；词源细节简化为：从动词 remparer 派生。","ex":[["Les remparts de la ville sont anciens.","城市的城墙很古老。"],["On se promène sur les remparts au coucher du soleil.","日落时我们在城墙上散步。"]],"co":[["les remparts de la ville","城墙"],["faire le tour des remparts","绕城墙走一圈"],["un rempart contre","……的屏障"]],"sy":[["muraille","soutenu","城墙"],["fortification","courant","防御工事"],["barrière","courant","障碍，屏障"]],"fq":"中低频，旅游和历史话题常见。","me":"rem-part ≈ re + part：围起来保护的那一圈。","tr":{"zh":"我们沿着城墙散步。","fr":"Nous nous promenons sur les remparts.","alt":"On se balade sur les remparts.","note":"se promener sur + 地方。"}},
 "Des tracas": {"pos":"n.m.pl. 阳性复数名词，单数 un tracas","s":"烦恼；麻烦；琐碎的烦心事。多用复数：avoir des tracas = 有一些烦心事。比 problèmes 轻，多指日常小麻烦。","ipa":"[tʁa.ka]","ph":"tr 连读；a [a]；结尾 s 不发音。","pi":"tracas 结尾 s 不发音，别读成 [tʁa.kas]；重音在最后。","et":"来自动词 tracasser（使烦恼）；词源不确定。","ex":[["Il a beaucoup de tracas en ce moment.","他最近有很多烦心事。"],["Je n'ai pas de tracas, tout va bien.","我没有烦心事，一切都好。"]],"co":[["avoir des tracas","有烦心事"],["des tracas quotidiens","日常烦恼"],["des tracas administratifs","行政上的麻烦"],["sans tracas","无忧无虑"]],"sy":[["soucis","courant","烦恼，忧虑"],["ennuis","courant","麻烦"],["problèmes","courant","问题"]],"fq":"中低频，略书面。","me":"tracas ← tracasser：小烦恼一个接一个。","tr":{"zh":"最近他有很多烦心事。","fr":"En ce moment, il a beaucoup de tracas.","alt":"Ces derniers temps, il a plein de soucis.","note":"beaucoup de + 名词，不加冠词。"}},
 "Ses derniers jours": {"pos":"n.m.pl. 阳性复数名词词组，单数 son dernier jour","s":"他 / 她的最后日子；临终的日子。ses 是 son / sa 的复数，所指的人要看语境。vivre ses derniers jours = 度过最后的日子。","ipa":"[se dɛʁ.nje ʒuʁ]","ph":"ses 读 [se]；dernier 读 [dɛʁ.nje]；jours 读 [ʒuʁ]，结尾 s 不发音。","pi":"ses [se] 不是 ces [se]（意义不同，同音）；ier 读 [je]；jours 的 s 不发音。","et":"dernier 来自古法语 derrain（拉丁语 de retro，在后面）；jour 来自拉丁语 diurnum。","ex":[["Il vit ses derniers jours.","他正度过最后的日子。"],["Elle a passé ses derniers jours chez elle.","她在家中度过了最后的日子。"]],"co":[["ses derniers jours","他 / 她的最后日子"],["les derniers jours de l'été","夏天的最后几天"],["passer ses derniers jours","度过最后的日子"]],"sy":[["derniers moments","soutenu","最后时刻"],["fin de vie","soutenu","临终（医疗用语）"]],"fq":"中频，叙述、新闻里可见，情感上较重。","me":"ses derniers jours：dernier ≈ 最后的。","tr":{"zh":"他在家中度过了最后的日子。","fr":"Il a passé ses derniers jours chez lui.","alt":"Il a vécu ses derniers jours à la maison.","note":"passer ses jours = 度过日子。"}},
 "Un boomer / Une boomeuse": {"pos":"n. 名词，阳性 un boomer，阴性 une boomeuse（也有人说 une boomer）","s":"婴儿潮一代（略带戏谑）。来自英语 baby boomer，指二战后出生的一代。网络上 OK boomer 带讽刺，说年轻人觉得老一辈观念过时。","ipa":"[bu.mœʁ]","ph":"boomer 读 [bu.mœʁ]：oo 读 [u]；-er 读 [œʁ]（不是英语的 [ɚ]）。阴性 boomeuse 读 [bu.møz]。","pi":"oo 读 [u]；-er 读 [œʁ]，不像英语；带玩笑甚至贬义，使用要看对象。","et":"来自英语 baby boomer（婴儿潮一代），词形按法语 -eur / -euse 化。","ex":[["Mon père est un boomer.","我爸爸是婴儿潮一代。"],["Ma tante est une vraie boomeuse, elle adore la radio.","我姑姑是个典型的婴儿潮世代，她爱听广播。"]],"co":[["un boomer","一位婴儿潮世代的人"],["OK boomer","行啊，老古董"],["la génération des boomers","婴儿潮一代"]],"sy":[["baby-boomer","courant","婴儿潮一代（中性）"],["vieux","familier","老家伙，不礼貌"],["senior","courant","年长者"]],"fq":"中低频，口语、网络用语，略带调侃。","me":"boom + er：「爆发期」出生的那一代。","tr":{"zh":"我爷爷是婴儿潮一代。","fr":"Mon grand-père est un boomer.","alt":"Mon grand-père, c'est un vrai boomer.","note":"c'est un boomer / il est boomer 均可，口语用。"}},
 "Un contributeur / Une contributrice": {"pos":"n.m./n.f. 名词，阳性 contributeur，阴性 contributrice，复数 contributeurs / contributrices","s":"贡献者；出力的人；投稿人。可指给项目、网站、维基、开源代码出力的人，也可指交税、出资的人（un contributeur = 纳税人，较正式）。","ipa":"[kɔ̃.tʁi.by.tœʁ]","ph":"con 读鼻化 [ɔ̃]；tri [tʁi]；bu [by]（u 读 [y]）；-eur [œʁ]。阴性 -trice 读 [tʁis]。","pi":"u 是 [y]（嘴圆、舌尖在前），不是 [u]；结尾 -eur 读 [œʁ]，r 要发；阴性词尾变成 -trice。","et":"来自拉丁语 contribuere（con- 一起 + tribuere 分配、给予）。同源：contribution，tribu。","ex":[["Il est un grand contributeur au projet.","他是这个项目的重要贡献者。"],["Elle est contributrice sur ce site.","她是这个网站的投稿人。"]],"co":[["un contributeur au projet","项目的贡献者"],["un gros contributeur","出力很多的人 / 大户"],["un contributeur net","净贡献者（出得比拿得多）"]],"sy":[["participant","courant","参与者，不一定有贡献"],["donateur","courant","捐赠者，只出钱"]],"fq":"中频，常见于新闻、网络和工作场合。","me":"contribuer + -eur：「出力的人」。和英语 contributor 几乎一样。","tr":{"zh":"她是这个项目的重要贡献者。","fr":"Elle est une grande contributrice du projet.","alt":"C'est elle qui aide le plus sur le projet.","note":"女性用 contributrice。"}},
 "Un influenceur / Une influenceuse": {"pos":"n.m./n.f. 名词，阳性 influenceur，阴性 influenceuse，复数 influenceurs / influenceuses","s":"网红；社交媒体上有影响力、会带货的人（Instagram、TikTok、YouTube）。常带商业含义，因为他们靠推荐产品赚钱。","ipa":"[ɛ̃.fly.ɑ̃.sœʁ]","ph":"in 读鼻化 [ɛ̃]；flu [fly]；en 读鼻化 [ɑ̃]；-eur [œʁ]。阴性 -euse 读 [øz]。","pi":"两个鼻化元音 [ɛ̃] 和 [ɑ̃] 不要混；u 读 [y]；不要把 en 读成 [ɛ̃]。","et":"influencer（影响，来自 influence）+ -eur。influence 来自拉丁语 influentia（流入）。","ex":[["C'est un influenceur connu.","他是知名网红。"],["Cette influenceuse a un million d'abonnés.","这位网红有一百万粉丝。"]],"co":[["un influenceur mode / voyage","时尚 / 旅行类网红"],["suivre un influenceur","关注一位网红"],["faire appel à des influenceurs","找网红合作"]],"sy":[["blogueur","courant","博主，更偏写作"],["youtubeur","courant","YouTube 视频博主"]],"fq":"中高频，社交媒体时代常用。","me":"influence + -eur：影响别人的人。","tr":{"zh":"这位网红有很多粉丝。","fr":"Cette influenceuse a beaucoup d'abonnés.","alt":"Cette influenceuse est suivie par plein de gens.","note":"粉丝 = abonnés（关注者）。"}},
 "Un(e) créateur/créatrice de contenu": {"pos":"n.m./n.f. 名词，阳性 créateur de contenu，阴性 créatrice de contenu","s":"内容创作者；在网上做视频、播客、文章、图片的人。contenu 是「内容」，在这里不加复数 s。","ipa":"[kʁe.a.tœʁ də kɔ̃t.ny]","ph":"créa- 分成 cré-a [kʁe.a]；-teur [tœʁ]；contenu 里 en 之前的 on 读 [ɔ̃]，u 读 [y]。","pi":"créateur 里的 é 和 a 要分开读 [e.a]；contenu 的 u 读 [y]；de 弱读 [də]。","et":"créateur 来自拉丁语 creator（creare 创造）；contenu 是 contenir（包含）的过去分词名词化，拉丁语 continere。","ex":[["Elle est créatrice de contenu sur YouTube.","她是 YouTube 内容创作者。"],["Mon frère veut devenir créateur de contenu.","我哥哥想成为内容创作者。"]],"co":[["créer du contenu","制作内容"],["un créateur de contenu vidéo","视频内容创作者"],["vivre de la création de contenu","靠做内容生活"]],"sy":[["youtubeur","courant","只做 YouTube 视频的人"],["influenceur","courant","偏重影响力和带货"]],"fq":"中频，近年常见。","me":"créateur（创造者）+ de contenu（内容的）。","tr":{"zh":"我想成为内容创作者。","fr":"Je veux devenir créateur de contenu.","alt":"Moi, je rêve de créer du contenu en ligne.","note":"devenir + 职业名词，不加冠词。"}},
 "Un(e) expert(e)": {"pos":"n.m./n.f. 名词，阳性 expert，阴性 experte，复数 experts / expertes","s":"专家。常用 un expert en + 领域。也可作形容词：être expert en la matière（在这方面很内行）。女性可说 une experte，也常见 une expert（口语）。","ipa":"[ɛks.pɛʁ]","ph":"ex 读 [ɛks]；p 要发音；结尾的 t 不发（阳性 expert 读 [ɛks.pɛʁ]），阴性 experte 读 [ɛks.pɛʁt]，t 要发。","pi":"t 在阳性里不发，在阴性 experte 里要发；p 不是哑音。","et":"来自拉丁语 expertus（experiri 尝试、经历的过去分词）：有经验的人。同源：expérience。","ex":[["C'est un expert en informatique.","他是信息技术专家。"],["Elle est experte en droit.","她是法律专家。"]],"co":[["un expert en…","……方面的专家"],["faire appel à un expert","请专家帮忙"],["l'avis d'un expert","专家意见"]],"sy":[["spécialiste","courant","专门人员，范围更窄"],["connaisseur","soutenu","行家，懂欣赏的人"],["novice","courant","反义：新手"]],"fq":"高频，日常常用。","me":"expert ← experiri（试过的人）：经验多就是专家。","tr":{"zh":"他是电脑方面的专家。","fr":"C'est un expert en informatique.","alt":"Il s'y connaît très bien en ordinateurs.","note":"expert en + 领域。"}},
 "Un(e) veinard(e)": {"pos":"n.m./n.f. 名词，阳性 veinard，阴性 veinarde，复数 veinards / veinardes","s":"幸运儿；运气好的人（口语、友好的羡慕语气）。常用于感叹：Quel veinard ! = 真走运！也可作形容词，意为「运气好的」。","ipa":"[vɛ.naʁ]","ph":"ei 读 [ɛ]；n 单独发 [n]；结尾 d 不发，阳性读 [vɛ.naʁ]，阴性 veinarde 读 [vɛ.naʁd]。","pi":"veine 里的 ei 是 [ɛ]；阳性 veinard 的 d 不发；不要读成 [vɛ̃]。","et":"来自 veine（法语口语里 avoir de la veine = 走运）+ -ard。veine 本义是「血管」，作「运气」讲是俗语用法。","ex":[["C'est un petit veinard !","他真是个幸运儿！"],["Tu as gagné ? Quelle veinarde !","你赢了？真走运！"]],"co":[["quel veinard !","真走运！"],["avoir de la veine","走运"],["un sacré veinard","超级幸运的家伙"]],"sy":[["chanceux","courant","运气好的人，更中性"],["verni","familier","运气好的人"],["malchanceux","courant","反义：运气差的人"]],"fq":"中低频，口语。","me":"veine（运气）+ -ard：「有运气的家伙」。","tr":{"zh":"你中奖了？真走运！","fr":"Tu as gagné ? Quel veinard !","alt":"T'as gagné ? Quel chanceux !","note":"对女生说 Quelle veinarde !"}},
 "Une mémé / Une mamie": {"pos":"n.f. 阴性名词，复数 mémés / mamies","s":"奶奶；外婆（亲昵口语）。mamie 比 mémé 更常用于称呼自己的祖母，也可泛指老太太；mémé 有时带「老土、老太婆」的意味，称呼时要看语气。正式场合说 grand-mère。","ipa":"[me.me] / [ma.mi]","ph":"mémé：两个 é 都读 [e]；mamie：a 读 [a]，ie 在这里读 [i]。","pi":"mémé 和 même（[mɛm]，同样的）不同：mémé 读 [me.me]；mamie 的 ie 不是 [je]。","et":"儿语叠音词（mémé 来自 mère 的儿语形式）；mamie 来自 maman + 昵称词尾 -ie。","ex":[["Ma mamie fait de bons gâteaux.","我奶奶做的蛋糕很好吃。"],["Mémé habite à la campagne.","奶奶住在乡下。"]],"co":[["aller chez mamie","去奶奶家"],["les mamies et les papis","老奶奶们和老爷爷们"],["une gentille mamie","和蔼的老奶奶"]],"sy":[["grand-mère","courant","标准说法，奶奶、外婆都用"],["papi","familier","对应的男性：爷爷"],["mamy","familier","mamie 的另一种拼法"]],"fq":"高频，家庭口语。","me":"和 papi（爷爷）成对记：mamie ~ papi。","tr":{"zh":"我周末去奶奶家。","fr":"Ce week-end, je vais chez mamie.","alt":"Samedi, je rends visite à ma mamie.","note":"aller chez + 人。"}},
 "Apprivoiser": {"pos":"v. 及物动词，第一组（-er），助动词 avoir；apprivoiser qqn / qqch","s":"驯服（动物）；使人熟悉、亲近；使人习惯（某事）。可用于动物，也可比喻：apprivoiser la peur（克服恐惧）。《小王子》里的 apprivoiser 意为「建立联系」。","ipa":"[a.pʁi.vwa.ze]","ph":"pp 读一个 [p]；oi 读 [wa]；s 在元音间读 [z]；结尾 -er 读 [e]。","pi":"oi 是 [wa]，不是 [oi]；s 读 [z]；pp 只读一个 p。","et":"来自 à + privé（拉丁语 privatus，私人的、家里的）：把野的变成「家里的」。","ex":[["Il a réussi à apprivoiser le renard.","他成功驯服了狐狸。"],["Il faut apprivoiser sa peur.","要学会和恐惧相处。"]],"co":[["apprivoiser un animal","驯服动物"],["s'apprivoiser","彼此熟悉"],["apprivoiser la peur","克服恐惧"]],"sy":[["dompter","courant","制服（猛兽），更强硬"],["domestiquer","soutenu","驯化（整个物种）"]],"fq":"中频，文学和日常都有。","me":"a + privé：让野的变成「自家的」。","tr":{"zh":"我想驯服这只小猫。","fr":"Je voudrais apprivoiser ce petit chat.","alt":"J'aimerais que ce chaton me fasse confiance.","note":"apprivoiser + 直接宾语。"}},
 "Argumenter": {"pos":"v. 动词，第一组（-er），助动词 avoir","s":"论证；提出论据；争辩。argumenter qqch = 为某事提供理由（argumenter son choix）；argumenter pour / contre = 为……/反对……辩论。","ipa":"[aʁ.ɡy.mɑ̃.te]","ph":"gu 在 e 以外的 u 前读 [ɡy]（这里 u 要发）；en 读鼻化 [ɑ̃]；结尾 -er 读 [e]。","pi":"u 要发 [y]，不是 gu+e 那种不发 u；en 读 [ɑ̃]。","et":"来自拉丁语 argumentari，由 argumentum（论据）而来。名词：un argument。","ex":[["Tu dois argumenter ton choix.","你得为自己的选择提出论据。"],["Il argumente bien pendant le débat.","他在辩论中论证得很好。"]],"co":[["argumenter son choix","为自己的选择提供理由"],["argumenter pour / contre","为……/反对……而辩论"],["bien argumenter","论证有力"]],"sy":[["justifier","courant","说明理由"],["débattre","courant","辩论，更强调交流"],["se disputer","courant","吵架，不是论证"]],"fq":"中频，学习、工作常用。","me":"argument + -er：拿出论据来说话。","tr":{"zh":"你要为你的意见提出论据。","fr":"Tu dois argumenter ton opinion.","alt":"Il faut que tu expliques pourquoi tu penses ça.","note":"argumenter 直接带宾语。"}},
 "Arpenter": {"pos":"v. 及物动词，第一组（-er），助动词 avoir；arpenter + 地点","s":"大步走遍；来回踱步。arpenter la ville = 走遍全城；arpenter le couloir = 在走廊里来回踱步（焦虑、等待时）。步子大而有力。","ipa":"[aʁ.pɑ̃.te]","ph":"ar [aʁ]；en 读鼻化 [ɑ̃]；t 读 [t]；结尾 -er 读 [e]。","pi":"en 读 [ɑ̃]，不是 [ɛ̃]；不是 -ent 的动词变位，结尾是 -er。","et":"来自 arpent（旧时的土地面积单位），本义是「用步子量土地」。","ex":[["Il aime arpenter la ville.","他喜欢漫步城市各处。"],["Il arpente le couloir en attendant.","他在走廊里一边等一边踱步。"]],"co":[["arpenter les rues","走遍街道"],["arpenter le couloir","在走廊来回踱步"],["arpenter la montagne","走遍山间"]],"sy":[["parcourir","courant","走遍，更中性"],["faire les cent pas","courant","来回踱步（短语）"]],"fq":"中低频，偏文学和书面。","me":"arpent（地块）+ -er：用脚「量」地。","tr":{"zh":"他等的时候在走廊里来回踱步。","fr":"Il arpente le couloir en attendant.","alt":"Il fait les cent pas dans le couloir.","note":"arpenter + 地点，直接宾语。"}},
 "Arrêter": {"pos":"v. 动词，第一组（-er），助动词 avoir；反身 s'arrêter（助动词 être）","s":"停止；使停下；逮捕。arrêter de + 动词原形 = 不再做某事；arrêter qqn = 逮捕某人；s'arrêter = （自己）停下来。","ipa":"[a.ʁɛ.te]","ph":"ê 读 [ɛ]；rr 读一个 [ʁ]；结尾 -er 读 [e]。","pi":"arrêter de + 原形，不是 à；arrêter 和 s'arrêter 不一样：il arrête de fumer（他戒烟）/ il s'arrête（他停下）。","et":"来自俗拉丁语 *arrestare（ad- + restare 停留），与 rester 同源。","ex":[["Il faut arrêter de fumer.","必须戒烟。"],["La police a arrêté le voleur.","警察逮捕了小偷。"],["Le bus s'arrête devant l'école.","公交车在学校前面停下。"]],"co":[["arrêter de + 原形","不再……"],["arrêter un voleur","逮捕小偷"],["s'arrêter de + 原形","停止做某事"],["Arrête !","住手！别闹了！"]],"sy":[["cesser","soutenu","停止，更书面"],["stopper","familier","停下、制止"],["continuer","courant","反义：继续"]],"fq":"极高频，日常常用。","me":"a + rester：让人「留」在原地，所以停下。","tr":{"zh":"我想戒糖。","fr":"Je veux arrêter le sucre.","alt":"J'aimerais arrêter de manger du sucre.","note":"arrêter + 名词 / arrêter de + 原形。"}},
 "Attirer l'attention": {"pos":"v. 短语，attirer（第一组 -er，助动词 avoir）+ l'attention（n.f.）","s":"引人注意；吸引注意力。attirer l'attention de qqn = 引起某人注意；attirer l'attention sur qqch = 让人注意到某事。可褒可贬（爱出风头）。","ipa":"[a.ti.ʁe la.tɑ̃.sjɔ̃]","ph":"attirer：tt 读一个 [t]；l'attention：l' 与 a 连读，tion 读 [sjɔ̃]；en 读 [ɑ̃]。","pi":"attention 的 tion 读 [sjɔ̃]，不是 [tjɔ̃]；l'attention 要省音（l'），不要读 le attention。","et":"attirer：à + tirer（拉）：拉过来。attention 来自拉丁语 attentio（attendere 注意）。","ex":[["Il aime attirer l'attention.","他喜欢吸引注意力。"],["Ce bruit a attiré notre attention.","这个声音引起了我们的注意。"]],"co":[["attirer l'attention de qqn","引起某人注意"],["attirer l'attention sur…","让人注意到……"],["attirer tous les regards","吸引所有目光"]],"sy":[["se faire remarquer","courant","引起注意，常带贬义"],["capter l'attention","courant","抓住注意力"]],"fq":"中高频，日常常用。","me":"attirer = 拉过来；把别人的注意拉到自己身上。","tr":{"zh":"这个广告吸引了我的注意。","fr":"Cette publicité a attiré mon attention.","alt":"Cette pub m'a tapé dans l'œil.","note":"attirer l'attention de + 人。"}},
 "Avoir tort": {"pos":"v. 短语，avoir（不规则动词，助动词 avoir）+ tort（n.m.）","s":"错了；不对。反义：avoir raison（对）。avoir tort de + 原形 = 做……是错的。tort 在这个短语里不加冠词。","ipa":"[a.vwaʁ tɔʁ]","ph":"avoir 读 [a.vwaʁ]；tort 里 t 结尾不发，r 要发：[tɔʁ]。","pi":"说「我错了」用 j'ai tort，不是 je suis tort；不要用 être；tort 不加 un / le。","et":"tort 来自拉丁语 tortum（扭曲的，由 torquere 扭转而来）：「歪的」所以是错的。同源：tordre。","ex":[["Tu as tort de penser cela.","你这样想是错的。"],["Je n'ai pas tort, non ?","我没错吧？"]],"co":[["avoir tort de + 原形","做……是错的"],["à tort","错误地"],["donner tort à qqn","认为某人错"],["avoir tort ou raison","对错"]],"sy":[["se tromper","courant","弄错，指具体错误"],["avoir raison","courant","反义：对"]],"fq":"高频，日常常用。","me":"tort ← 扭曲：歪了就是错。","tr":{"zh":"你错了，会议是明天。","fr":"Tu as tort, la réunion est demain.","alt":"Tu te trompes, la réunion, c'est demain.","note":"avoir tort，不要用 être。"}},
 "Changer d'air": {"pos":"v. 短语，changer（第一组 -er，助动词 avoir）+ d'air","s":"换换环境；出去透透气。字面是「换空气」，指去别的地方休息、散心。changer d'air 后面的 air 不加冠词。","ipa":"[ʃɑ̃.ʒe dɛʁ]","ph":"ch 读 [ʃ]；an 读 [ɑ̃]；g 在 e 前读 [ʒ]；d'air：d' 与 air 连读，air 读 [ɛʁ]。","pi":"changer 的 g 读 [ʒ]；an 读 [ɑ̃]；不要说 changer l'air。","et":"changer 来自拉丁语 cambiare（交换）；air 来自拉丁语 aer（空气，原为希腊语）。","ex":[["J'ai besoin de changer d'air.","我需要换换环境。"],["Partons à la mer pour changer d'air.","我们去海边换换环境吧。"]],"co":[["avoir besoin de changer d'air","需要换换环境"],["changer d'avis","改变主意"],["changer de vie","换种生活"]],"sy":[["se dépayser","courant","换个新环境，有异国感"],["prendre l'air","courant","出去透气"]],"fq":"中频，口语常用。","me":"changer + air：换口新鲜空气。","tr":{"zh":"周末我们去乡下换换环境吧。","fr":"Ce week-end, allons à la campagne pour changer d'air.","alt":"Ce week-end, on va à la campagne, ça nous changera d'air.","note":"changer de + 无冠词名词。"}},
 "Coller": {"pos":"v. 动词，第一组（-er），助动词 avoir","s":"粘；贴；粘贴（电脑）。也指「紧贴」：coller à la peau（紧贴皮肤）。口语里 coller = 让学生留校（être collé）；ça colle = 合得上，行。","ipa":"[kɔ.le]","ph":"c 在 o 前读 [k]；ll 读一个 [l]；结尾 -er 读 [e]。","pi":"coller 的 ll 只读一个 l；不要和 colère（愤怒）混。","et":"来自 colle（胶水），后者来自希腊语 kolla（胶）。同源：collage。","ex":[["Il faut coller ces deux feuilles.","要把这两张纸粘在一起。"],["Copie le texte, puis colle-le ici.","复制文字，然后粘贴到这里。"]],"co":[["coller une affiche","贴海报"],["copier-coller","复制粘贴"],["coller à…","紧贴着……"],["ça colle","合得来，行得通"]],"sy":[["fixer","courant","固定"],["décoller","courant","反义：撕下，起飞"]],"fq":"中高频，日常常用。","me":"colle（胶）+ -er：用胶「粘」。","tr":{"zh":"把这张照片贴在这里。","fr":"Colle cette photo ici.","alt":"Mets de la colle et fixe la photo ici.","note":"命令式 colle 无 s。"}},
 "Composer (un numéro)": {"pos":"v. 及物动词，第一组（-er），助动词 avoir；composer un numéro","s":"拨（电话号码）。composer 另有：组成；作曲；写（诗、音乐）。composer le numéro de qqn = 拨某人的号码。","ipa":"[kɔ̃.po.ze]","ph":"com 读鼻化 [ɔ̃]；o 读 [o]；s 在元音间读 [z]；结尾 -er 读 [e]。","pi":"composer 的 s 读 [z]；不要用 appeler 的「打电话」意思混淆：composer 只表示按键拨号。","et":"来自拉丁语 componere（con- + ponere 放置），同源 poser。","ex":[["Je compose son numéro.","我拨他的号码。"],["Composez le 15 pour le SAMU.","拨 15 联系急救中心。"],["Il compose de la musique.","他作曲。"]],"co":[["composer un numéro","拨号码"],["composer un code","输入密码"],["composer de la musique","作曲"],["être composé de…","由……组成"]],"sy":[["appeler","courant","打电话（整个动作）"],["téléphoner","courant","打电话"],["taper","courant","输入、按键"]],"fq":"中频，日常常用。","me":"com + poser：把数字一个个「放」在一起，就是拨号。","tr":{"zh":"你拨号前要先拨零。","fr":"Tu dois composer le zéro avant le numéro.","alt":"Il faut d'abord taper le zéro, puis le numéro.","note":"composer + 号码，直接宾语。"}},
 "Conclure": {"pos":"v. 不规则及物动词，第三组，助动词 avoir；过去分词 conclu","s":"总结；结束；得出结论；达成（协议）。conclure un accord = 达成协议；conclure que… = 得出……的结论；pour conclure = 最后。","ipa":"[kɔ̃.klyʁ]","ph":"con 读 [ɔ̃]；clu 读 [kly]；结尾 -re 的 e 不发，r 读 [ʁ]。","pi":"u 读 [y]；变位：je conclus，nous concluons，过去分词 conclu。","et":"来自拉丁语 concludere（con- + claudere 关闭）：把话「关上」就是结束。","ex":[["Il est temps de conclure la réunion.","是时候结束会议了。"],["Ils ont conclu un accord.","他们达成了协议。"]],"co":[["conclure un accord / un contrat","达成协议 / 签合同"],["conclure que…","得出……的结论"],["pour conclure","最后"],["en conclure que…","由此推断……"]],"sy":[["terminer","courant","结束"],["finir","courant","完成"],["déduire","soutenu","推断"]],"fq":"中高频，正式和书面场合常用。","me":"con + clure：一起「关上」；clôturer 同源。","tr":{"zh":"最后，我想谢谢大家。","fr":"Pour conclure, je voudrais remercier tout le monde.","alt":"Pour finir, merci à tous.","note":"pour conclure 放在句首。"}},
 "Contribuer à": {"pos":"v. 不及物动词，第一组（-er），助动词 avoir；contribuer à + 名词 / 原形","s":"为……作出贡献；有助于。contribuer à qqch = 对某事起作用；contribuer à + 原形 = 有助于做某事。也可 contribuer pour + 金额（出钱）。","ipa":"[kɔ̃.tʁi.bɥe]","ph":"con 读 [ɔ̃]；tri [tʁi]；bu 读 [bɥ]（u + e 连成半元音 [ɥ]）；结尾 -er 读 [e]。","pi":"后面接 à，不是 de 或 pour（除非说钱）；u 读 [ɥ]/[y]，不是 [u]。","et":"来自拉丁语 contribuere（con- + tribuere 分配）。同源：tribu，attribuer。","ex":[["Chacun doit contribuer à l'effort.","每个人都要为此出力。"],["Le sport contribue à la bonne santé.","运动有助于健康。"]],"co":[["contribuer à un projet","为项目出力"],["contribuer à améliorer…","有助于改善……"],["contribuer financièrement","出资"]],"sy":[["participer à","courant","参加"],["aider à","courant","帮助做"],["favoriser","courant","促进"]],"fq":"中高频，正式场合常用。","me":"con + tribuer：大家一起「分」一份力。","tr":{"zh":"每个人都应该为这个项目出力。","fr":"Chacun doit contribuer à ce projet.","alt":"Tout le monde doit participer à ce projet.","note":"contribuer à + 名词。"}},
 "Crapahuter": {"pos":"v. 不及物动词，第一组（-er），助动词 avoir","s":"跋涉；爬山涉水；吃力地走（崎岖的路）。口语，带有累但有趣的意味。原为军队俚语，指在野外艰难行进。","ipa":"[kʁa.pa.y.te]","ph":"cra [kʁa]；pa [pa]；hu 中 h 不发，u 读 [y]，分成 [pa.y.te]；结尾 -er 读 [e]。","pi":"h 不发音，注意 [pa.y] 两个音节；不是 [kʁa.pɑ.yt]；动词变位用 j'ai crapahuté。","et":"来源不确定（19 世纪的军队俚语）。可能与 crapaud（蟾蜍）有联想，但无定论。","ex":[["Nous avons crapahuté toute la journée.","我们跋涉了一整天。"],["Ils crapahutent dans la montagne.","他们在山里爬山涉水。"]],"co":[["crapahuter dans la montagne","在山里跋涉"],["crapahuter sur des sentiers","走小路"],["crapahuter toute la journée","走一整天"]],"sy":[["randonner","courant","徒步"],["trimer","familier","辛苦地干"],["marcher","courant","走路"]],"fq":"低频，口语。","me":"听起来像「爬、爬、哈」：气喘吁吁地爬坡。","tr":{"zh":"我们在山里跋涉了一天。","fr":"Nous avons crapahuté toute la journée dans la montagne.","alt":"On a marché dur toute la journée en montagne.","note":"passé composé 用 avoir。"}},
 "Découler de": {"pos":"v. 不及物动词，第一组（-er），助动词 être 或 avoir 均可；découler de qqch","s":"源于；产生于；由……推出。后果、结论从某个原因或事实中来。多用第三人称：cela découle de…；il en découle que…。","ipa":"[de.ku.le]","ph":"dé [de]；cou 读 [ku]；结尾 -er 读 [e]。","pi":"后面接 de；不要和 couler（流）混为同一个用法；通常只用第三人称。","et":"dé- + couler（流，来自拉丁语 colare 过滤）：「从……流出来」。","ex":[["Ces problèmes découlent de sa décision.","这些问题源于他的决定。"],["Il en découle que nous devons attendre.","由此可知我们得等。"]],"co":[["découler de qqch","源于某事"],["il en découle que…","由此得出……"],["les conséquences qui en découlent","由此产生的后果"]],"sy":[["résulter de","soutenu","来自、是……的结果"],["provenir de","soutenu","来源于"],["venir de","courant","来自"]],"fq":"中频，书面、正式。","me":"dé + couler：从上面「流下来」的结果。","tr":{"zh":"这些问题都源于一个错误。","fr":"Tous ces problèmes découlent d'une erreur.","alt":"Tous ces problèmes viennent d'une seule erreur.","note":"de + une → d'une。"}},
 "Décrocher (un prix)": {"pos":"v. 及物动词，第一组（-er），助动词 avoir；décrocher un prix","s":"摘得（奖项）；拿到（工作、合同、学位）。本义是「取下、摘下」，如 décrocher le téléphone = 接电话/摘下话筒。口语里 décrocher un job = 拿到工作。","ipa":"[de.kʁɔ.ʃe]","ph":"dé [de]；cro 读 [kʁɔ]；ch 读 [ʃ]；结尾 -er 读 [e]。","pi":"ch 读 [ʃ]；不要和 raccrocher（挂断）混：décrocher 是接起，raccrocher 是挂断。","et":"dé- + crocher（钩住，来自 croc 钩子）：把挂着的东西「取下来」。","ex":[["Elle a décroché un prix prestigieux.","她获得了一个著名奖项。"],["Il a décroché un super travail.","他拿到了一份很棒的工作。"]],"co":[["décrocher un prix / un contrat","拿到奖 / 合同"],["décrocher un emploi","找到工作"],["décrocher le téléphone","接电话"],["décrocher son diplôme","拿到文凭"]],"sy":[["obtenir","courant","获得"],["remporter","courant","赢得"],["gagner","courant","赢"]],"fq":"中频，口语和新闻常用。","me":"dé + croc：从钩子上把奖「摘下来」。","tr":{"zh":"他拿到了第一名。","fr":"Il a décroché la première place.","alt":"Il a remporté la première place.","note":"过去时用 avoir。"}},
 "Démarrer": {"pos":"v. 动词，第一组（-er），助动词 avoir；可及物或不及物","s":"启动（车、机器）；开始（项目、活动）。la voiture démarre = 车子发动了；démarrer un projet = 开始一个项目。也有「起步、起飞」的意思。","ipa":"[de.ma.ʁe]","ph":"dé [de]；ma [ma]；rr 读一个 [ʁ]；结尾 -er 读 [e]。","pi":"rr 只读一个 [ʁ]；不要说 démarrer le voiture（voiture 是阴性，la voiture 自己启动不需要宾语）。","et":"dé- + amarrer（系泊）：本义是「解开缆绳」，船开出去，后来泛指启动。","ex":[["La voiture démarre vite.","汽车启动很快。"],["Le projet démarre lundi.","项目周一开始。"]],"co":[["démarrer une voiture","启动汽车"],["démarrer un projet","启动项目"],["démarrer en trombe","猛地发动"],["bien démarrer","开了个好头"]],"sy":[["commencer","courant","开始"],["lancer","courant","发起、启动"],["arrêter","courant","反义：停止"]],"fq":"高频，日常常用。","me":"dé + amarrer：解开缆绳，船就走了。","tr":{"zh":"车子冷的时候发动不了。","fr":"La voiture ne démarre pas quand il fait froid.","alt":"Quand il fait froid, la voiture refuse de démarrer.","note":"démarrer 不需要宾语时指机器启动。"}},
 "Démissionner": {"pos":"v. 不及物动词，第一组（-er），助动词 avoir","s":"辞职；辞去（职务）。démissionner de son poste = 辞去职位。也可比喻「放弃、不管了」（口语：Les parents ont démissionné）。","ipa":"[de.mi.sjɔ.ne]","ph":"dé [de]；mi [mi]；ssion 读 [sjɔ̃]，但在 -ner 前读 [sjɔ.ne]，ss 读 [s]；结尾 -er 读 [e]。","pi":"ss 是清音 [s]，不是 [z]；démission（名词）和 démissionner 都要拼双 s、双 n。","et":"来自 démission（拉丁语 demissio，放下）+ -er。","ex":[["Il a décidé de démissionner.","他决定辞职。"],["Elle a démissionné de son poste.","她辞去了职务。"]],"co":[["démissionner de son poste","辞去职位"],["donner sa démission","提交辞职"],["lettre de démission","辞职信"]],"sy":[["quitter son travail","courant","离开工作"],["partir","courant","离开"],["renvoyer","courant","反义：被开除（是公司的行为）"]],"fq":"中频，工作场合常用。","me":"démission + -er：交出「职位」，辞职。","tr":{"zh":"我下个月要辞职。","fr":"Je vais démissionner le mois prochain.","alt":"Je vais quitter mon travail le mois prochain.","note":"aller + 原形 = 近将来。"}},
 "Détruire": {"pos":"v. 不规则及物动词，第三组，助动词 avoir；过去分词 détruit","s":"摧毁；毁掉；破坏。可用于具体事物（房子、森林）和抽象事物（希望、名声、健康）。","ipa":"[de.tʁɥiʁ]","ph":"dé [de]；truire 读 [tʁɥiʁ]（ui 为半元音 + i）。","pi":"ui 读 [ɥi]，不是 [wi]；变位：je détruis，nous détruisons，过去分词 détruit。","et":"来自拉丁语 destruere（de- + struere 堆建）：把建好的拆掉。同源：construire。","ex":[["Le feu a détruit la maison.","大火烧毁了房子。"],["Cette décision va détruire sa carrière.","这个决定会毁掉他的事业。"]],"co":[["détruire un bâtiment","拆毁建筑"],["détruire des preuves","销毁证据"],["détruire la santé","损害健康"],["détruit(e) par…","被……毁掉的"]],"sy":[["démolir","courant","拆毁（建筑）"],["anéantir","soutenu","彻底摧毁"],["construire","courant","反义：建造"]],"fq":"高频，日常和新闻常用。","me":"de + (con)struire：construire 的反面。","tr":{"zh":"暴风雨毁了我们的花园。","fr":"La tempête a détruit notre jardin.","alt":"La tempête a tout cassé dans notre jardin.","note":"passé composé：a détruit。"}},
 "Embarquer": {"pos":"v. 动词，第一组（-er），助动词 avoir；及物或不及物","s":"登上（飞机、船）；装载上船。embarquer à bord = 登机/登船。口语里也有「带走」「逮捕」（la police l'a embarqué）。","ipa":"[ɑ̃.baʁ.ke]","ph":"em 读鼻化 [ɑ̃]；bar [baʁ]；qu 读 [k]；结尾 -er 读 [e]。","pi":"em 读 [ɑ̃]，不是 [ɛm]；qu 读 [k]；和 débarquer（下船/到达）成反义。","et":"en- + barque（小船）：「放上船」。同源：débarquer，embarcation。","ex":[["Nous allons embarquer dans l'avion.","我们要登机了。"],["Les passagers embarquent à midi.","乘客中午登船。"]],"co":[["embarquer à bord","登机 / 登船"],["embarquer sur un bateau","上船"],["embarquer des bagages","装行李"],["embarquement immédiat","立即登机"]],"sy":[["monter","courant","上去"],["débarquer","courant","反义：下船、下机"],["charger","courant","装载"]],"fq":"中频，旅行常用。","me":"em + barque：踏上「小船」。","tr":{"zh":"乘客现在可以登机了。","fr":"Les passagers peuvent embarquer maintenant.","alt":"Les passagers peuvent monter à bord maintenant.","note":"embarquer 常用在机场和港口。"}},
 "Embaucher": {"pos":"v. 及物动词，第一组（-er），助动词 avoir","s":"雇用；录用；招聘员工。embaucher qqn = 雇某人。名词：l'embauche（雇佣）。反义：licencier（解雇）。","ipa":"[ɑ̃.bo.ʃe]","ph":"em 读 [ɑ̃]；au 读 [o]；ch 读 [ʃ]；结尾 -er 读 [e]。","pi":"au 是 [o]；ch 是 [ʃ]；不要和 embaucher 里的 em 读成 [ɛm]。","et":"来源不确定。结构：em-（en-）+ 词根 -bauche；注意与 débaucher 相对。","ex":[["L'entreprise va embaucher de nouveaux employés.","公司将雇用新员工。"],["Elle a été embauchée la semaine dernière.","她上周被录用了。"]],"co":[["embaucher du personnel","招人"],["être embauché(e)","被录用"],["l'embauche","雇佣"],["on embauche","招聘（告示）"]],"sy":[["recruter","courant","招聘，更正式"],["engager","courant","聘用"],["licencier","courant","反义：解雇"]],"fq":"中高频，工作场合常用。","me":"embaucher = 给人「一份活」。","tr":{"zh":"这家公司在招人。","fr":"Cette entreprise embauche en ce moment.","alt":"Cette boîte recrute en ce moment.","note":"embaucher 可不带宾语（泛指招人）。"}},
 "Émettre": {"pos":"v. 不规则及物动词，第三组（像 mettre），助动词 avoir；过去分词 émis","s":"排放；发出（光、声音、信号）；发行（票据、货币）；发表（意见）。émettre un avis = 提出意见；émettre des gaz = 排放气体。","ipa":"[e.mɛtʁ]","ph":"é [e]；mettre 读 [mɛtʁ]，tt 只读一个 [t]，结尾 e 不发。","pi":"变位像 mettre：j'émets，nous émettons，过去分词 émis；é 要带重音。","et":"来自拉丁语 emittere（e- 向外 + mittere 送出），与 mettre 同源。","ex":[["Cette usine émet des gaz.","这座工厂排放气体。"],["La banque émet de nouveaux billets.","银行发行新钞票。"]],"co":[["émettre des gaz","排放气体"],["émettre un signal","发出信号"],["émettre un avis","表达意见"],["émettre un chèque","开支票"]],"sy":[["dégager","courant","释放、散发"],["rejeter","courant","排出"],["recevoir","courant","反义：接收"]],"fq":"中频，新闻和书面常用。","me":"é + mettre：向外「放出去」。","tr":{"zh":"汽车会排放有害气体。","fr":"Les voitures émettent des gaz nocifs.","alt":"Les voitures rejettent des gaz nocifs.","note":"émettre 是 mettre 的变位。"}},
 "Enlever": {"pos":"v. 及物动词，第一组（-er），助动词 avoir；变位 j'enlève，nous enlevons","s":"拿走；脱掉；取下；去除。最常用的意思是「脱、拿走」：enlever son manteau（脱外套）。另有「绑架」：enlever un enfant。书上义项（绑架）是次要意义，日常多用 kidnapper。","ipa":"[ɑ̃l.ve]","ph":"en 读鼻化 [ɑ̃]；l 与 e 轻读，e 常常不发：[ɑ̃l.ve]。","pi":"变位时 e 变 è：j'enlève，不要写 j'enlêve；en 读 [ɑ̃]。","et":"en- + lever（拉丁语 levare 抬起）：把东西「抬走」。","ex":[["Le fils de cette célébrité a été enlevé !","这位名人的儿子被绑架了！"],["Enlève ton manteau, il fait chaud.","把外套脱了，很热。"]],"co":[["enlever son manteau","脱外套"],["enlever une tache","去掉污渍"],["se faire enlever","被绑架"],["enlever le sel","去掉盐"]],"sy":[["retirer","courant","取下、拿走"],["kidnapper","courant","绑架（更常用）"],["mettre","courant","反义：穿上"]],"fq":"高频，日常常用。","me":"en + lever：把东西「抬起来拿走」。","tr":{"zh":"进屋前请把鞋脱了。","fr":"Enlève tes chaussures avant d'entrer.","alt":"Retire tes chaussures avant d'entrer.","note":"命令式 enlève，不加 s。"}},
 "Être marqué par": {"pos":"v. 短语，être + marqué（过去分词，marquer 的被动形式）+ par","s":"深受……影响；被……留下印记；对……印象深刻。être marqué par un événement = 某事给人留下深刻印象。也可指脸上、身体有痕迹：être marqué par la fatigue（脸上带着倦容）。","ipa":"[ɛtʁ maʁ.ke paʁ]","ph":"être [ɛtʁ]；marqué [maʁ.ke]；qu 读 [k]；par [paʁ]。","pi":"marqué 要和主语一致：elle est marquée par…；par 不是 de，不要写 marqué de。","et":"marquer 来自 marque，源自日耳曼语（与英语 mark 同源）。","ex":[["J'ai été marqué par cet événement.","这件事给我留下了深刻印象。"],["Elle est très marquée par son enfance.","她深受童年影响。"]],"co":[["être marqué(e) par un événement","被某事深深影响"],["un visage marqué par la fatigue","带着倦容的脸"],["une époque marquée par…","以……为特征的时代"]],"sy":[["être touché par","courant","被触动"],["être influencé par","courant","受……影响"],["être frappé par","courant","被……震撼"]],"fq":"中频，书面和口语都用。","me":"marque（印记）：事件在心里留下「记号」。","tr":{"zh":"这部电影给我留下了很深的印象。","fr":"J'ai été très marqué par ce film.","alt":"Ce film m'a vraiment marqué.","note":"被动式：être + 过去分词 + par。"}},
 "Faire comme si": {"pos":"v. 短语，faire（不规则动词）+ comme si；si 后面接直陈式","s":"假装……；装作……。comme si 后面常用未完成过去时或愈过去时：faire comme si de rien n'était = 装作什么都没发生。","ipa":"[fɛʁ kɔm si]","ph":"faire 读 [fɛʁ]；comme 读 [kɔm]，结尾 e 不发；si 读 [si]。","pi":"comme si 之后不要用虚拟式；si 遇到 il 要省音为 s'il，但 comme si + 其他不省音。","et":"faire 来自拉丁语 facere；comme si 为固定连词结构。","ex":[["Il fait comme si de rien n'était.","他装作若无其事。"],["Fais comme si tu ne savais rien.","你就装作什么也不知道。"]],"co":[["faire comme si de rien n'était","装作若无其事"],["comme si + 未完成过去时","好像……（不真实）"],["faire comme chez soi","不要拘束，当自己家"]],"sy":[["prétendre","soutenu","假称"],["faire semblant (de)","courant","假装"],["simuler","soutenu","模拟、伪装"]],"fq":"高频，日常常用。","me":"faire + comme si：做出「好像」的样子。","tr":{"zh":"他假装没听见。","fr":"Il fait comme s'il n'avait rien entendu.","alt":"Il fait semblant de ne rien avoir entendu.","note":"si + il → s'il；comme si 后用愈过去时。"}},
 "Faire du bivouac / Bivouaquer": {"pos":"v. 短语 / 动词，faire du bivouac；bivouaquer（第一组 -er，助动词 avoir）","s":"野营；露营（不带固定营地，通常一夜）。bivouac（n.m.）= 临时营地、野营。徒步、登山、军队常用。比 faire du camping 更野、更简单。","ipa":"[fɛʁ dy bi.vwak] / [bi.vwa.ke]","ph":"bi [bi]；vouac 读 [vwak]（ou 在这里读 [w]，ac 读 [ak]）；bivouaquer：qu 读 [k]。","pi":"vouac 里的 ou 读 [w]；bivouac 最后的 c 要发 [k]；动词带 qu：bivouaquer。","et":"借自德语（瑞士德语 biwacht，意为「夜里加岗」）。军队词汇，后来泛指野营。","ex":[["Nous allons bivouaquer ce soir.","今晚我们野营。"],["Ils font du bivouac en montagne.","他们在山里露营。"]],"co":[["faire du bivouac","野营"],["bivouaquer en montagne","在山里野营"],["un lieu de bivouac","野营地点"]],"sy":[["camper","courant","露营，较普通"],["faire du camping","courant","去营地露营"],["dormir à la belle étoile","courant","露天睡"]],"fq":"中低频，户外活动用。","me":"bi-vouac：想象一夜在山里搭帐篷。","tr":{"zh":"夏天我们在山里露营。","fr":"En été, nous faisons du bivouac en montagne.","alt":"L'été, on bivouaque en montagne.","note":"faire du + 活动名词。"}},
 "Faire du stop": {"pos":"v. 短语，faire（不规则动词）+ du stop；口语","s":"搭便车；竖大拇指拦车。是 faire de l'auto-stop 的口语缩写。也可说 faire du stop pour aller à…（搭车去……）。","ipa":"[fɛʁ dy stɔp]","ph":"faire [fɛʁ]；du [dy]；stop 读 [stɔp]，p 要发。","pi":"stop 的 p 要发；du 的 u 读 [y]，不是 [u]。","et":"stop 借自英语 stop；auto-stop 是 auto + stop 的合成词。","ex":[["Nous avons fait du stop pour rentrer.","我们搭便车回家。"],["Il fait du stop depuis Lyon.","他从里昂开始搭便车。"]],"co":[["faire du stop","搭便车"],["prendre un auto-stoppeur","载搭便车的人"],["un auto-stoppeur","搭便车的人"]],"sy":[["faire de l'auto-stop","courant","搭便车（完整形式）"],["covoiturer","courant","拼车"]],"fq":"中低频，口语。","me":"站在路边对车说「stop」：请停一下。","tr":{"zh":"我们搭便车去了海边。","fr":"Nous avons fait du stop pour aller à la mer.","alt":"On est allés à la mer en stop.","note":"faire du stop 没有冠词变化。"}},
 "Faire la moue": {"pos":"v. 短语，faire（不规则动词）+ la moue（n.f.）","s":"撅嘴；噘着嘴（不高兴、不满意或撒娇）。可以是孩子气的，也可以是不满：faire la moue devant un plat（对菜不满意）。","ipa":"[fɛʁ la mu]","ph":"faire [fɛʁ]；moue 读 [mu]，ou 读 [u]，结尾 -e 不发。","pi":"moue 读 [mu]，和 mou（软的）读音相同；不要读成 [mue]。","et":"来源不确定，可能是日耳曼语。","ex":[["L'enfant fait la moue.","孩子撅起了嘴。"],["Elle a fait la moue en voyant le menu.","她看到菜单就撅起了嘴。"]],"co":[["faire la moue","撅嘴"],["une petite moue","嘟嘟嘴"],["faire la moue devant…","对……不满意"]],"sy":[["bouder","courant","生闷气"],["grimacer","courant","做鬼脸"]],"fq":"中低频，日常口语。","me":"moue 听起来像 mou（软）：嘴唇软软地噘起来。","tr":{"zh":"孩子不想吃，就撅起嘴来。","fr":"L'enfant ne veut pas manger et fait la moue.","alt":"Le petit ne veut pas manger, il boude.","note":"faire la moue 带定冠词 la。"}},
 "Flâner": {"pos":"v. 不及物动词，第一组（-er），助动词 avoir","s":"闲逛；漫步；悠闲地走。没有目的，只为享受。名词：un flâneur / une flâneuse（闲逛的人）。法国文化中很有代表性的活动。","ipa":"[flɑ.ne]","ph":"â 读 [ɑ]（长音）；n 读 [n]；结尾 -er 读 [e]。","pi":"â 要读深一点的 [ɑ]；动词变位 je flâne；不要写成 flaner（缺帽子）。","et":"来源不确定，可能来自古斯堪的纳维亚语。名词 flâneur 后来被英语借用。","ex":[["J'aime flâner dans les rues.","我喜欢在街上闲逛。"],["Nous avons flâné au bord de la Seine.","我们在塞纳河边闲逛。"]],"co":[["flâner dans les rues","在街上闲逛"],["flâner au bord de l'eau","在水边漫步"],["un flâneur","闲逛的人"]],"sy":[["se promener","courant","散步，最常用"],["errer","littéraire","漫无目的地走"],["traîner","familier","磨蹭、晃荡"]],"fq":"中频，旅游和文学常用。","me":"flâner：像在巴黎街头慢慢「飘」。","tr":{"zh":"周日我喜欢在市中心闲逛。","fr":"Le dimanche, j'aime flâner dans le centre-ville.","alt":"Le dimanche, j'adore me balader en ville.","note":"flâner 不及物，后面加地点。"}},
 "Fragiliser": {"pos":"v. 及物动词，第二组（-ir，像 finir），助动词 avoir；过去分词 fragilisé","s":"使脆弱；削弱；使不稳。fragiliser l'économie = 削弱经济；fragiliser qqn = 让某人更脆弱。","ipa":"[fʁa.ʒi.li.ze]","ph":"fra [fʁa]；gi 读 [ʒi]；li [li]；s 读 [z]；结尾 -er 读 [e]。","pi":"g 在 i 前读 [ʒ]；它是 -er 动词（第一组），不是 -ir 动词：je fragilise，nous fragilisons；s 读 [z]。","et":"fragile（拉丁语 fragilis，易碎）+ -iser。同源：fragilité。","ex":[["Cette décision va fragiliser l'économie.","这个决定会削弱经济。"],["La maladie l'a fragilisé.","疾病让他变得虚弱。"]],"co":[["fragiliser l'économie","削弱经济"],["fragiliser une situation","使局势不稳"],["être fragilisé(e)","被削弱"]],"sy":[["affaiblir","courant","削弱，更常用"],["renforcer","courant","反义：加强"]],"fq":"中频，新闻和书面常用。","me":"fragile + -iser：让东西变得「易碎」。","tr":{"zh":"这场危机削弱了公司。","fr":"La crise a fragilisé l'entreprise.","alt":"La crise a affaibli la boîte.","note":"fragiliser 带直接宾语。"}},
 "Freiner": {"pos":"v. 动词，第一组（-er），助动词 avoir；及物或不及物","s":"刹车；减速；阻碍。不及物：freiner brusquement（急刹车）；及物：freiner la croissance（抑制增长）。名词：le frein（刹车）。","ipa":"[fʁɛ.ne]","ph":"frei 读 [fʁɛ]（ei 读 [ɛ]）；n 读 [n]；结尾 -er 读 [e]。","pi":"ei 读 [ɛ]，不是 [ei]；它是「刹车」，不是「冷冻」（那是 congeler）。","et":"来自 frein（拉丁语 frenum，马嚼子）+ -er。","ex":[["Il faut freiner avant le virage.","转弯前要刹车。"],["Cette loi freine la croissance.","这项法律抑制了增长。"]],"co":[["freiner brusquement","急刹车"],["freiner la croissance","抑制增长"],["un coup de frein","一脚刹车"],["freiner des quatre fers","拼命抵制"]],"sy":[["ralentir","courant","减速"],["entraver","soutenu","阻碍"],["accélérer","courant","反义：加速"]],"fq":"中频，开车和新闻常用。","me":"frein（刹车）+ -er：踩刹车。","tr":{"zh":"看到红灯时要刹车。","fr":"Il faut freiner quand on voit un feu rouge.","alt":"Quand le feu est rouge, on freine.","note":"freiner 常不带宾语。"}},
 "Halluciner": {"pos":"v. 动词，第一组（-er），助动词 avoir；h 不送气（按元音处理，省音：j'hallucine）","s":"产生幻觉；口语里指「惊呆了、不敢相信」：J'hallucine ! = 我不敢相信！我惊呆了！这个口语义非常常见。","ipa":"[a.ly.si.ne]","ph":"h 不发音；a [a]；llu 读 [ly]；ci 读 [si]；结尾 -er 读 [e]。","pi":"h 不发音；ll 在这里读 [l]（不是 [j]）；c 在 i 前读 [s]；与英语 hallucinate 拼写相近。","et":"来自拉丁语 hallucinari（想象、胡思乱想）。名词：hallucination。","ex":[["J'ai halluciné en voyant ça !","我看到时惊呆了！"],["Il hallucine à cause de la fièvre.","他因发烧而产生幻觉。"]],"co":[["J'hallucine !","我不敢相信！"],["halluciner sur qqch","对某事惊讶"],["avoir des hallucinations","有幻觉"]],"sy":[["être stupéfait","courant","惊呆"],["délirer","courant","说胡话、发狂"],["rêver","courant","做梦"]],"fq":"中频，口语里常用。","me":"J'hallucine ! = 我是不是在做梦？","tr":{"zh":"我不敢相信你说的话！","fr":"J'hallucine ! Tu as vraiment dit ça ?","alt":"Je rêve ! Tu as vraiment dit ça ?","note":"J'hallucine 是口语惊叹。"}},
 "Inculquer": {"pos":"v. 及物动词，第一组（-er），助动词 avoir；inculquer qqch à qqn","s":"灌输；使牢记（价值观、习惯、知识）。常指父母、老师向孩子灌输：inculquer des valeurs à un enfant。含有长期、反复的教导的意思。","ipa":"[ɛ̃.kyl.ke]","ph":"in 读鼻化 [ɛ̃]；cul 读 [kyl]；qu 读 [k]；结尾 -er 读 [e]。","pi":"in 读 [ɛ̃]；u 读 [y]；qu 读 [k]；句型是 inculquer qqch à qqn。","et":"来自拉丁语 inculcare（in- + calcare 踩、压）：把东西「踩进去」。","ex":[["On lui a inculqué de bonnes valeurs.","大人给他灌输了良好的价值观。"],["Elle inculque le goût de la lecture à ses enfants.","她让孩子们养成爱读书的习惯。"]],"co":[["inculquer des valeurs","灌输价值观"],["inculquer le goût de…","培养对……的爱好"],["inculquer une idée à qqn","向某人灌输一个观念"]],"sy":[["enseigner","courant","教"],["transmettre","courant","传授"],["instiller","soutenu","一点点灌输"]],"fq":"低中频，书面和教育话题常用。","me":"in + 踩（calcare）：一点点「踩」进脑子里。","tr":{"zh":"父母要向孩子灌输尊重。","fr":"Les parents doivent inculquer le respect à leurs enfants.","alt":"Les parents doivent apprendre le respect à leurs enfants.","note":"inculquer qqch à qqn。"}},
 "Intensifier": {"pos":"v. 及物动词，第一组（-er），助动词 avoir；反身 s'intensifier","s":"加强；加大；使更强烈。intensifier les efforts = 加大努力；s'intensifier = 变得更强烈（如风、疼痛、竞争）。","ipa":"[ɛ̃.tɑ̃.si.fje]","ph":"in 读 [ɛ̃]；ten 读 [tɑ̃]；si [si]；fier 读 [fje]，结尾 -er 读 [e]：[fje]。","pi":"in 读 [ɛ̃]，ten 读 [tɑ̃]，别混；动词结尾 -ifier 读 [i.fje]。","et":"来自 intense（拉丁语 intensus，拉紧的）+ -ifier（使成为）。","ex":[["Il faut intensifier nos efforts.","必须加大我们的努力。"],["La pluie s'intensifie ce soir.","今晚雨越来越大。"]],"co":[["intensifier ses efforts","加大努力"],["s'intensifier","变强烈"],["intensifier les contrôles","加强检查"]],"sy":[["renforcer","courant","加强"],["augmenter","courant","增加"],["réduire","courant","反义：减少"]],"fq":"中频，书面和新闻常用。","me":"intense + -ifier：让它变得更「强烈」。","tr":{"zh":"我们必须加强训练。","fr":"Nous devons intensifier l'entraînement.","alt":"Il faut qu'on s'entraîne plus dur.","note":"devoir + 原形。"}},
 "Marquer": {"pos":"v. 动词，第一组（-er），助动词 avoir","s":"标记；写下；留下印记；（体育）得分。marquer un but = 进球；marquer qqn = 给某人留下深刻印象；marquer son nom = 写下姓名。","ipa":"[maʁ.ke]","ph":"mar [maʁ]；qu 读 [k]；结尾 -er 读 [e]。","pi":"qu 读 [k]，不是 [kw]；变位：je marque，nous marquons。","et":"来自 marque，源于日耳曼语（与英语 mark 同源）。","ex":[["J'ai marqué mon numéro sur cette feuille.","我把号码写在这张纸上。"],["Il a marqué deux buts.","他进了两个球。"]],"co":[["marquer un but","进球"],["marquer un événement","纪念一个事件"],["marquer sa différence","表明不同"],["marquer la page","做记号"]],"sy":[["noter","courant","记下"],["écrire","courant","写"],["effacer","courant","反义：擦掉"]],"fq":"高频，日常常用。","me":"marque（记号）+ -er：留下「记号」。","tr":{"zh":"他在比赛中进了一个球。","fr":"Il a marqué un but pendant le match.","alt":"Il a mis un but pendant le match.","note":"marquer un but，but 是阳性。"}},
 "Mettre en scène": {"pos":"v. 短语，mettre（不规则动词，助动词 avoir）+ en scène；过去分词 mis","s":"导演；搬上舞台；执导（电影、戏剧）；精心安排（场面）。名词：la mise en scène（导演手法、场景调度）。","ipa":"[mɛtʁ ɑ̃ sɛn]","ph":"mettre [mɛtʁ]；en [ɑ̃]；scène 读 [sɛn]（sc 读 [s]），结尾 e 不发。","pi":"scène 里 sc 读 [s]，不是 [sk]；变位：je mets，nous mettons，过去分词 mis。","et":"mettre 来自拉丁语 mittere；scène 经拉丁语来自希腊语 skēnē（帐篷、舞台）。","ex":[["Le réalisateur va mettre en scène ce film.","导演将执导这部电影。"],["Elle met en scène une pièce de théâtre.","她在导演一部话剧。"]],"co":[["mettre en scène un film / une pièce","导演电影 / 话剧"],["la mise en scène","导演手法"],["un metteur en scène","导演（戏剧）"]],"sy":[["réaliser","courant","拍摄（电影）"],["diriger","courant","指导"],["monter","courant","排演（戏剧）"]],"fq":"中频，文化话题常用。","me":"mettre + en scène：把故事「放到舞台上」。","tr":{"zh":"她将执导这部新话剧。","fr":"Elle va mettre en scène cette nouvelle pièce.","alt":"C'est elle qui dirige cette nouvelle pièce.","note":"mettre en scène + 作品。"}},
 "Mettre X de côté": {"pos":"v. 短语，mettre（不规则动词，助动词 avoir）+ X + de côté；过去分词 mis","s":"把 X 存起来；留出；放在一边。mettre de l'argent de côté = 存钱；mettre qqch de côté pour qqn = 给某人留着。也用于把问题暂时放一边。","ipa":"[mɛtʁ də ko.te]","ph":"mettre [mɛtʁ]；de [də]；côté 读 [ko.te]，ô 读 [o]。","pi":"côté 的重音 ô 不要漏；X 放在 mettre 和 de côté 中间：mettre 2000 € de côté。","et":"mettre 来自拉丁语 mittere；côté 来自拉丁语 costa（肋骨、侧面）。","ex":[["Nous avons mis 2000€ de côté.","我们存了两千欧元。"],["Peux-tu me mettre ce pain de côté ?","你能帮我把这个面包留着吗？"]],"co":[["mettre de l'argent de côté","存钱"],["mettre qqch de côté","留出某物"],["mettre un problème de côté","把问题放一边"]],"sy":[["économiser","courant","节省、存钱"],["épargner","soutenu","储蓄"],["garder","courant","保留"]],"fq":"高频，日常常用。","me":"mettre + côté：放到「旁边」，留着以后用。","tr":{"zh":"每个月我都存一点钱。","fr":"Chaque mois, je mets un peu d'argent de côté.","alt":"Tous les mois, je mets un peu de sous de côté.","note":"X 放在 mettre 和 de côté 之间。"}},
 "Monétiser": {"pos":"v. 及物动词，第一组（-er），助动词 avoir","s":"变现；让……赚钱；货币化。monétiser un blog / une vidéo / un site = 通过广告、会员等方式靠它赚钱。网络和商业用语。","ipa":"[mɔ.ne.ti.ze]","ph":"mo [mɔ]；né [ne]；ti 读 [ti]；s 读 [z]；结尾 -er 读 [e]。","pi":"ti 读 [ti]，不是 [si]；s 读 [z]；é 要带重音。","et":"来自 monnaie（拉丁语 moneta，钱币）的词干 + -iser（使成为）。","ex":[["Il cherche à monétiser son blog.","他想让博客赚钱。"],["Elle monétise ses vidéos grâce à la publicité.","她靠广告让视频变现。"]],"co":[["monétiser un site","让网站赚钱"],["monétiser son audience","把受众变现"],["la monétisation","变现"]],"sy":[["rentabiliser","courant","使赚钱"],["gagner de l'argent avec","courant","靠……赚钱"]],"fq":"低中频，网络和商业话题。","me":"monnaie + -iser：把东西变成「钱」。","tr":{"zh":"她想靠视频赚钱。","fr":"Elle veut monétiser ses vidéos.","alt":"Elle veut gagner de l'argent avec ses vidéos.","note":"monétiser + 直接宾语。"}},
 "Naviguer": {"pos":"v. 不及物动词，第一组（-er），助动词 avoir","s":"航行；上网浏览；（在界面里）操作。naviguer sur la mer = 在海上航行；naviguer sur Internet = 上网。","ipa":"[na.vi.ɡe]","ph":"na [na]；vi [vi]；gu 读 [ɡ]（u 不发）；结尾 -er 读 [e]。","pi":"gu 的 u 不发，读 [ɡe]；变位 nous naviguons（u 保留）；上网用 sur Internet。","et":"来自拉丁语 navigare（navis 船 + agere 驱动）。同源：navire，navigation。","ex":[["J'aime naviguer sur la mer.","我喜欢在海上航行。"],["Elle navigue sur Internet toute la soirée.","她整晚都在上网。"]],"co":[["naviguer sur Internet","上网"],["naviguer à voile","驾驶帆船"],["naviguer entre deux choix","在两个选择间权衡"]],"sy":[["surfer","familier","上网冲浪"],["voguer","littéraire","航行"]],"fq":"高频，日常和网络常用。","me":"navire（船）+ -er：开船，也像开着「船」上网。","tr":{"zh":"晚上我常常上网浏览。","fr":"Le soir, je navigue souvent sur Internet.","alt":"Le soir, je surfe souvent sur le net.","note":"naviguer sur + 网络。"}},
 "Négocier": {"pos":"v. 动词，第一组（-er），助动词 avoir；及物或不及物","s":"谈判；磋商；谈（价钱、合同）。négocier le prix = 讨价还价；négocier avec qqn = 与某人谈判。","ipa":"[ne.ɡɔ.sje]","ph":"né [ne]；go 读 [ɡɔ]；ci 读 [sj]；结尾 -er 读 [e]：[ne.ɡɔ.sje]。","pi":"gé 常被误读：这里是 go [ɡɔ]，不是 [ʒ]；ci 读 [sj]。","et":"来自拉丁语 negotiari，源自 negotium（neg- 不 + otium 闲暇：「不闲」就是做生意）。","ex":[["Il faut négocier le prix.","必须谈价钱。"],["Les deux pays négocient un accord.","两国正在谈判一项协议。"]],"co":[["négocier le prix","谈价钱"],["négocier un contrat","谈合同"],["négocier avec…","与……谈判"],["une négociation","谈判"]],"sy":[["marchander","courant","讨价还价（买东西）"],["discuter","courant","商量"]],"fq":"中高频，商务和日常常用。","me":"neg + otium：「没空闲」的人在做生意、谈判。","tr":{"zh":"我想谈一下价格。","fr":"Je voudrais négocier le prix.","alt":"On peut discuter du prix ?","note":"négocier + 直接宾语。"}},
 "Nuancer": {"pos":"v. 及物动词，第一组（-er），助动词 avoir；变位 nous nuançons","s":"使有所保留；细化；使有差别、不那么绝对。nuancer son propos = 把话说得不那么绝对；nuancer un jugement = 使判断更细致。","ipa":"[nɥɑ̃.se]","ph":"nu 与 an 连成 [nɥɑ̃]（u 为半元音 [ɥ]）；c 在 e 前读 [s]；结尾 -er 读 [e]。","pi":"变位时 nous nuançons 要加 ç；nuance 里的 an 读 [ɑ̃]；u 读 [ɥ]。","et":"来自 nuance（源于 nuer，指云彩般渐变的颜色，nue 即云）+ -er。","ex":[["Il faut nuancer ce propos.","这个说法要有所保留。"],["Je voudrais nuancer ce que j'ai dit.","我想对我说的话做些补充和修正。"]],"co":[["nuancer un propos / un jugement","让说法 / 判断更有分寸"],["sans nuancer","不加保留地"],["une nuance","细微差别"]],"sy":[["préciser","courant","说清楚"],["modérer","courant","缓和"],["généraliser","courant","反义：一概而论"]],"fq":"中频，书面和讨论中常用。","me":"nuance（色差）+ -er：让黑白变成「灰色」。","tr":{"zh":"我想稍微修正一下我的说法。","fr":"Je voudrais nuancer un peu mon propos.","alt":"Je voudrais corriger un peu ce que j'ai dit.","note":"propos 作「话、说法」时常单数。"}},
 "Parcourir": {"pos":"v. 不规则及物动词，第三组（像 courir），助动词 avoir；过去分词 parcouru","s":"走遍；跑遍；游历；浏览（文字）。parcourir 10 km = 走了十公里；parcourir un texte = 快速浏览一遍。","ipa":"[paʁ.ku.ʁiʁ]","ph":"par [paʁ]；cou [ku]；rir 读 [ʁiʁ]（结尾 r 要发）。","pi":"变位像 courir：je parcours，nous parcourons，过去分词 parcouru；不要和 par cœur 混。","et":"par- + courir（拉丁语 currere 跑）：从头到尾「跑一遍」。","ex":[["Nous allons parcourir le monde.","我们要走遍世界。"],["Il a parcouru le journal rapidement.","他很快浏览了一遍报纸。"]],"co":[["parcourir des kilomètres","走很多公里"],["parcourir le monde","游历世界"],["parcourir un article","粗略浏览文章"],["un parcours","路线、历程"]],"sy":[["arpenter","soutenu","大步走遍"],["traverser","courant","穿过"],["feuilleter","courant","翻阅"]],"fq":"中高频，日常和书面常用。","me":"par + courir：从头到尾跑一遍。","tr":{"zh":"他一天走了二十公里。","fr":"Il a parcouru vingt kilomètres en une journée.","alt":"Il a marché vingt kilomètres dans la journée.","note":"过去分词 parcouru，没有 s。"}},
 "Passer à table": {"pos":"v. 短语，passer（第一组，助动词 être 或 avoir）+ à table","s":"入席；开饭；坐下来吃饭。常用命令句：À table ! 或 On passe à table ! = 开饭了！也可口语表示「坦白、招供」。","ipa":"[pa.se a tabl]","ph":"passer [pa.se]（ss 读 [s]）；à [a]；table 读 [tabl]，结尾 e 不发。","pi":"table 不发结尾 e：[tabl]；à 要有重音，别和 a（有）混；passer 用于「走过」时助动词 être，表示完成动作时 être。","et":"passer 来自俗拉丁语 *passare（passus 步子）；table 来自拉丁语 tabula（板）。","ex":[["Il est l'heure de passer à table.","该吃饭了。"],["On passe à table dans cinq minutes.","五分钟后开饭。"]],"co":[["passer à table","入席 / 开饭"],["À table !","开饭了！"],["se mettre à table","入席；招供"],["mettre la table","摆桌子"]],"sy":[["se mettre à table","courant","坐下吃饭（也可指招供）"],["dîner","courant","吃晚饭"],["manger","courant","吃"]],"fq":"高频，日常常用。","me":"passer（走到）+ à table：从厨房走到桌边。","tr":{"zh":"孩子们，开饭了！","fr":"Les enfants, à table !","alt":"Les enfants, on passe à table !","note":"À table ! 是固定感叹。"}},
 "Passer un message": {"pos":"v. 短语，passer（第一组，助动词 avoir）+ un message（n.m.）","s":"传达信息；转告；传递讯息。passer un message à qqn = 给某人传话；faire passer un message = 把观点传达出去（媒体、广告、公益）。","ipa":"[pa.se œ̃ me.saʒ]","ph":"passer [pa.se]；un 读 [œ̃]；message 读 [me.saʒ]，ge 读 [ʒ]。","pi":"message 的结尾 ge 读 [ʒ]，不是 [dʒ]；un message 是阳性。","et":"passer 来自俗拉丁语 *passare；message 来自拉丁语 missaticum（mittere 送）。","ex":[["Cette association fait passer des messages importants.","这个协会传递重要信息。"],["Peux-tu passer un message à Paul ?","你能给保罗传句话吗？"]],"co":[["passer un message à qqn","给某人传话"],["faire passer un message","传达观点"],["laisser un message","留言"],["un message important","重要信息"]],"sy":[["transmettre","courant","转达"],["communiquer","courant","传达"],["dire","courant","说"]],"fq":"中高频，日常常用。","me":"把信息像球一样「传」过去。","tr":{"zh":"请转告他我明天来。","fr":"Peux-tu lui passer le message que je viens demain ?","alt":"Dis-lui que je viens demain.","note":"passer un message à qqn。"}},
 "Pédaler": {"pos":"v. 不及物动词，第一组（-er），助动词 avoir","s":"蹬（踏板）；骑自行车。pédaler dur = 使劲蹬。口语里 pédaler dans la semoule = 白费力气，没有进展。","ipa":"[pe.da.le]","ph":"pé [pe]；da [da]；结尾 -er 读 [e]。","pi":"é 要带重音；重音在最后一个音节；pédale（n.f.）读 [pe.dal]。","et":"来自 pédale（意大利语 pedale，源自拉丁语 pes，pedis「脚」）+ -er。","ex":[["Il faut pédaler pour avancer.","要蹬才能前进。"],["Elle pédale vite dans la côte.","她在坡上蹬得很快。"]],"co":[["pédaler fort","使劲蹬"],["pédaler dans la semoule","白费力气"],["une pédale","踏板"],["à vélo","骑自行车"]],"sy":[["rouler","courant","骑行、行驶"],["faire du vélo","courant","骑自行车"]],"fq":"中频，日常和运动话题。","me":"pédale ← pes（脚）：用脚来「蹬」。","tr":{"zh":"上坡时要使劲蹬。","fr":"Dans la montée, il faut pédaler fort.","alt":"Pour monter, il faut vraiment pédaler.","note":"pédaler 不及物。"}},
 "Plafonner": {"pos":"v. 动词，第一组（-er），助动词 avoir；及物或不及物","s":"达到顶峰；到顶；设上限。不及物：les prix plafonnent = 价格触顶；及物：plafonner les loyers = 给房租设上限。plafonner à + 数字 = 最高到……。","ipa":"[pla.fɔ.ne]","ph":"pla [pla]；fo 读 [fɔ]；n 读 [n]；结尾 -er 读 [e]。","pi":"o 读开口 [ɔ]；plafond 的 d 不发，但 plafonner 里没有 d；别误写成 plafonder。","et":"来自 plafond（plat + fond，「平的底」）+ -er。","ex":[["Les prix vont plafonner.","价格将触顶。"],["Le salaire plafonne à 3000 euros.","工资最高到三千欧元。"]],"co":[["plafonner à + 数字","最高到……"],["plafonner les loyers","给房租设上限"],["un plafond","上限、天花板"]],"sy":[["culminer","soutenu","达到最高点"],["stagner","courant","停滞不前"],["limiter","courant","限制"]],"fq":"中低频，新闻和经济话题。","me":"plafond（天花板）+ -er：碰到「天花板」，到顶了。","tr":{"zh":"这个月房租最高到八百欧元。","fr":"Ce mois-ci, le loyer plafonne à huit cents euros.","alt":"Ce mois-ci, le loyer ne dépasse pas huit cents euros.","note":"plafonner à + 数字。"}},
 "Planifier": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir","s":"规划；安排计划。常接具体对象：planifier son budget / ses vacances / une réunion。比 prévoir（预见、预计）更强调「系统地排出计划」。","ipa":"[pla.ni.fje]","ph":"pla [pla]；ni [ni]；-fier 读 [fje]，结尾 -er 不发音，读 [e]。","pi":"结尾 -er 读 [e]，不发 r；fi 与 er 连成 [fje] 一个音节。","et":"plan（计划，来自拉丁语 planus「平的」）+ 动词后缀 -ifier；同族：planification（规划）。","ex":[["Je dois planifier ma semaine.","我得规划我的一周。"],["Ils ont planifié leur voyage en détail.","他们详细规划了旅行。"]],"co":[["planifier son emploi du temps","安排日程"],["planifier à l'avance","提前计划"],["une réunion planifiée","已排定的会议"]],"sy":[["organiser","courant","组织、安排，范围更广"],["prévoir","courant","预见、预定，不一定有详细计划"]],"fq":"中频，工作和日常都用。","me":"plan + -ifier：把事情「做成一张 plan」。","tr":{"zh":"周末我要先规划好行程。","fr":"Je vais planifier mon programme du week-end.","alt":"Je prépare mon week-end à l'avance.","note":"planifier 是及物动词，后面直接接宾语。"}},
 "Prendre l'air": {"pos":"v. 固定短语，动词 prendre（第三组，avoir）","s":"出去透透气，到户外走走。字面是「吸取空气」。也可指飞机、鸟儿等「升空」，但日常多指人出门透气。","ipa":"[pʁɑ̃dʁ.lɛʁ]","ph":"prendre 读 [pʁɑ̃dʁ]，词尾 e 不发音；l'air 省音连读，air 读 [ɛʁ]。","pi":"prendre 中 en 读鼻化音 [ɑ̃]；air 读 [ɛʁ]，不要读成 [aiʁ]。","et":"prendre 来自拉丁语 prehendere（抓取）；air 来自拉丁语 aer。字面义「取空气」。","ex":[["Je vais prendre l'air.","我去透透气。"],["On est restés enfermés, allons prendre l'air !","我们一直关在屋里，出去透透气吧！"]],"co":[["sortir prendre l'air","出去透透气"],["prendre l'air un moment","出去呼吸一会儿"],["prendre l'air de la montagne","呼吸山里的空气"]],"sy":[["se promener","courant","散步"],["s'aérer","courant","透气、换换空气"],["se changer les idées","courant","换换心情"]],"fq":"中频，口语常用。","me":"prendre + air：像「吸一口空气」。","tr":{"zh":"我头疼，想出去透透气。","fr":"J'ai mal à la tête, je vais prendre l'air.","alt":"J'ai mal à la tête, je sors prendre l'air.","note":"prendre l'air 中 air 不加冠词前缀，固定用法。"}},
 "Prévaloir": {"pos":"v.i. 不及物动词，第三组，助动词 avoir；过去分词 prévalu","s":"占上风；占优势；被优先考虑。多用于书面语：La raison doit prévaloir。se prévaloir de = 借口、拿……来炫耀（另一用法）。","ipa":"[pʁe.va.lwaʁ]","ph":"pré [pʁe]；va [va]；loir 读 [lwaʁ]；词尾 r 要发音。","pi":"变位像 valoir，但虚拟式 que je prévale（与 valoir 的 vaille 不同）。书面词，日常口语少用。","et":"拉丁语 praevalere（更强、更有力）：pré-（在前）+ valoir（值、有力）。","ex":[["La raison doit prévaloir.","理智必须占上风。"],["Dans ce cas, l'intérêt des enfants prévaut.","在这种情况下，孩子的利益优先。"]],"co":[["faire prévaloir son point de vue","使自己的观点占上风"],["l'emporter / prévaloir sur","胜过……"],["se prévaloir de","以……为凭借"]],"sy":[["l'emporter","courant","获胜、占上风"],["dominer","courant","占主导"],["primer","soutenu","优先于"]],"fq":"中低频，书面语和正式场合。","me":"pré（先）+ valoir（有价值）：价值更高的先赢。","tr":{"zh":"在这件事上，安全必须优先。","fr":"Dans cette affaire, la sécurité doit prévaloir.","alt":"Ici, la sécurité passe avant tout.","note":"prévaloir 不及物，常与 sur 搭配：prévaloir sur qch。"}},
 "Prévenir (un risque)": {"pos":"v.t. 及物动词，第三组（像 venir），助动词 avoir；过去分词 prévenu","s":"预防（风险、疾病、事故）；也可指「事先通知、警告某人」：prévenir quelqu'un。Il vaut mieux prévenir que guérir = 预防胜于治疗。","ipa":"[pʁe.və.niʁ]","ph":"pré [pʁe]；ve 轻读 [və]；nir 读 [niʁ]，r 发音。","pi":"两个意思容易混：prévenir un risque（预防）与 prévenir quelqu'un（通知某人）。不要和 éviter（避免）完全等同。","et":"拉丁语 praevenire（先到、抢先）：pré-（先）+ venir（来）。同族：prévention（预防）。","ex":[["Il vaut mieux prévenir que guérir.","预防胜于治疗。"],["Préviens-moi si tu arrives en retard.","如果你迟到，请提前告诉我。"]],"co":[["prévenir un accident","预防事故"],["prévenir quelqu'un de qch","把某事告知某人"],["prévenir les risques","预防风险"]],"sy":[["éviter","courant","避免"],["avertir","courant","警告、通知"],["empêcher","courant","阻止"]],"fq":"高频，日常和新闻都常见。","me":"pré（先）+ venir（来）：先一步到，风险就来不了。","tr":{"zh":"刷牙可以预防蛀牙。","fr":"Se brosser les dents permet de prévenir les caries.","alt":"Se laver les dents, ça évite les caries.","note":"prévenir 的变位同 venir，但助动词是 avoir。"}},
 "Promouvoir": {"pos":"v.t. 及物动词，第三组（像 mouvoir），助动词 avoir；过去分词 promu","s":"推广；促进；提拔。promouvoir un produit / la paix / un employé。常见于商业、政治和公共语境。","ipa":"[pʁɔ.mu.vwaʁ]","ph":"pro [pʁɔ]；mou [mu]；voir [vwaʁ]；r 发音。","pi":"变位不规则：il promeut；过去分词 promu（不是 promouvé）。不是 promotion 的动词形式 promotionner。","et":"拉丁语 promovere（向前推）：pro-（向前）+ movere（移动）。同族：promotion（推广；晋升；促销）。","ex":[["Il faut promouvoir ce produit.","必须推广这个产品。"],["Cette ville promeut le tourisme vert.","这座城市推广绿色旅游。"]],"co":[["promouvoir un produit","推广产品"],["promouvoir la paix","促进和平"],["être promu directeur","被提拔为主管"]],"sy":[["favoriser","courant","促进"],["encourager","courant","鼓励"],["lancer","courant","推出"]],"fq":"中频，工作和新闻常见。","me":"pro（向前）+ mouvoir（移动）：把东西往前推。","tr":{"zh":"这家公司想推广环保产品。","fr":"Cette entreprise veut promouvoir des produits écologiques.","alt":"Cette société cherche à faire connaître ses produits verts.","note":"过去分词 promu；被动：être promu。"}},
 "Ralentir": {"pos":"v. 动词，第二组（-ir），助动词 avoir；过去分词 ralenti","s":"减速；放慢。可作及物（ralentir le pas）也可作不及物（La voiture ralentit）。反义：accélérer。","ipa":"[ʁa.lɑ̃.tiʁ]","ph":"ra [ʁa]；len 读鼻化音 [lɑ̃]；tir [tiʁ]。r 是小舌音 [ʁ]。","pi":"len 的 en 读 [ɑ̃]，不发 n；注意 r 在词首和词尾都要发音。","et":"来自 lent（慢，拉丁语 lentus）加前缀 re- 和 a-、后缀 -ir。同族：lentement（慢慢地）。","ex":[["Il faut ralentir en voiture.","开车要减速。"],["La croissance ralentit depuis deux ans.","增长两年来在放缓。"]],"co":[["ralentir le pas","放慢脚步"],["ralentir près d'une école","经过学校附近要减速"],["le trafic ralentit","车流变慢"]],"sy":[["freiner","courant","刹车、减缓"],["accélérer","courant","加速（反义）"]],"fq":"高频，日常常用。","me":"lent（慢）+ -ir：变慢，听起来也慢吞吞。","tr":{"zh":"前面有学校，请减速。","fr":"Il y a une école devant, ralentis.","alt":"École devant, ralentis un peu.","note":"命令式 ralentis 带 s（第二组 -ir）。"}},
 "Recharger ses batteries": {"pos":"v. 固定短语，动词 recharger（第一组，avoir）","s":"给自己「充电」；休息恢复精力。字面是给电池充电，比喻人休息后恢复体力。常指假期、周末休息。","ipa":"[ʁə.ʃaʁ.ʒe.se.ba.tʁi]","ph":"ch [ʃ]；g 在 e 前读 [ʒ]；ses 读 [se]，与 batteries 之间可轻微连读；batteries 读 [ba.tʁi]。","pi":"ses batteries 要用复数，主语变了就用 mes / ses / nos 等对应。ch 读 [ʃ]，不是 [k]。","et":"re-（再）+ charger（装载、充电，来自晚期拉丁语 carricare，源于 carrus「车」）。batterie 来自 battre（打）。","ex":[["J'ai vraiment besoin de vacances pour recharger mes batteries.","我真的需要假期来充电。"],["Le week-end, il recharge ses batteries à la campagne.","周末他去乡下恢复精力。"]],"co":[["recharger ses batteries","给自己充电，恢复精力"],["recharger son téléphone","给手机充电"],["pour recharger les batteries","为了恢复精力"]],"sy":[["se reposer","courant","休息"],["se ressourcer","courant","找回活力"],["souffler","familier","喘口气"]],"fq":"中频，口语很常用。","me":"人像手机：电量低了就要 recharger。","tr":{"zh":"我想去海边休息充电。","fr":"Je veux aller au bord de la mer pour recharger mes batteries.","alt":"J'ai envie de partir à la mer, histoire de me ressourcer.","note":"所有格要随主语变化：mes / tes / ses。"}},
 "Relancer": {"pos":"v.t. 及物动词，第一组，助动词 avoir；过去分词 relancé","s":"重新启动；振兴；再次推出。relancer l'économie / un projet / un débat。也可指「再次联系、催促」：relancer un client（跟进客户）。","ipa":"[ʁə.lɑ̃.se]","ph":"re 轻读 [ʁə]；lan 读鼻化 [lɑ̃]；cer 读 [se]（c 在 e 前读 [s]）。","pi":"lan 的 an 读 [ɑ̃]；变位 nous relançons，c 下面加软音符 ç 保持 [s]。","et":"re-（再）+ lancer（扔、发射，来自 lance「长矛」）。","ex":[["Il faut relancer l'économie.","必须重振经济。"],["Je vais relancer le client par mail.","我要发邮件再跟进一下客户。"]],"co":[["relancer l'économie","刺激经济复苏"],["relancer un débat","重新引起讨论"],["relancer un client","跟进客户"]],"sy":[["redémarrer","courant","重启"],["ranimer","soutenu","使复苏"],["relancer","courant","催促、再次联系"]],"fq":"中频，经济、工作场合常用。","me":"re（再）+ lancer（发射）：再发射一次。","tr":{"zh":"新政府想重振经济。","fr":"Le nouveau gouvernement veut relancer l'économie.","alt":"Le gouvernement cherche à faire redémarrer l'économie.","note":"nous relançons：加 ç 保持 [s] 音。"}},
 "Remonter à": {"pos":"v.i. 不及物动词，第一组；表示时间时助动词 avoir，过去分词 remonté","s":"追溯到；起源于（某个时期）。后面接时间：remonter à 1783 / au Moyen Âge / à l'époque romaine。主语是物或事件，不是人。","ipa":"[ʁə.mɔ̃.te.a]","ph":"re [ʁə]；mon 读鼻化 [mɔ̃]；ter 读 [te]；à 单独读 [a]。","pi":"介词用 à（不是 de，也不是 en）；主语常是事物：Cette église remonte au XIIe siècle。","et":"re-（再）+ monter（上去，来自拉丁语 mons「山」）。字面「往回爬」到过去。","ex":[["Le vol en ballon remonte à 1783.","热气球飞行可以追溯到 1783 年。"],["Cette maison remonte au XVIIe siècle.","这栋房子可追溯到十七世纪。"]],"co":[["remonter à + 年份 / 世纪","追溯到某个年代"],["remonter dans le temps","回溯时间"],["remonter à la source","追溯到源头"]],"sy":[["dater de","courant","始于（日期）"],["provenir de","soutenu","源于"]],"fq":"中频，历史、文化话题常用。","me":"re + monter：沿着时间「往上爬」回到过去。","tr":{"zh":"这座桥可追溯到中世纪。","fr":"Ce pont remonte au Moyen Âge.","alt":"Ce pont date du Moyen Âge.","note":"remonter à = dater de，两者后面介词不同。"}},
 "Remplir": {"pos":"v.t. 及物动词，第二组（-ir），助动词 avoir；过去分词 rempli","s":"装满；填写（表格）；完成（任务、条件）。remplir un verre / un formulaire / une condition。反义：vider（倒空）。","ipa":"[ʁɑ̃.pliʁ]","ph":"rem 读鼻化 [ʁɑ̃]；plir 读 [pliʁ]；r 发音。","pi":"rem 的 em 读 [ɑ̃]；变位 je remplis, nous remplissons（第二组）。","et":"re-（再）+ emplir（填满）；emplir 来自拉丁语 implere，同根 plein（满的）。","ex":[["Je vais remplir mon verre.","我去把杯子倒满。"],["Il faut remplir ce formulaire.","必须填写这张表格。"]],"co":[["remplir un formulaire","填表"],["remplir un verre de + 名词","往杯里倒满……"],["remplir les conditions","符合条件"],["être rempli de","充满……"]],"sy":[["emplir","littéraire","装满，更书面"],["compléter","courant","补全、填写"],["vider","courant","倒空（反义）"]],"fq":"极高频，日常常用。","me":"和 plein（满）同根：remplir = 再次变 plein。","tr":{"zh":"请填写这张表格，然后签名。","fr":"Remplissez ce formulaire, puis signez.","alt":"Vous remplissez ce formulaire et vous signez en bas.","note":"「填表」用 remplir，不用 écrire。"}},
 "Repartir de zéro": {"pos":"v. 固定短语，动词 repartir（第三组，助动词 être）","s":"从零开始；重新来过。多用于生活、工作、感情重新开始。注意 repartir（再出发）与 répartir（分配）只差一个重音。","ipa":"[ʁə.paʁ.tiʁ.də.ze.ʁo]","ph":"zéro 读 [ze.ʁo]，z 是浊音，é 读 [e]，o 读 [o]；de 轻读 [də]。","pi":"repartir（再出发）与 répartir（分配）不同；repartir 的助动词是 être：il est reparti。","et":"re-（再）+ partir（出发，来自拉丁语 partire「分开」）；zéro 来自意大利语 zero，源于阿拉伯语。","ex":[["Nous allons repartir de zéro.","我们要从头来过。"],["Après l'échec, elle a décidé de repartir de zéro.","失败之后，她决定从零开始。"]],"co":[["repartir de zéro","从头再来"],["repartir à zéro","归零重来"],["tout recommencer","全部重来"]],"sy":[["recommencer","courant","重新开始"],["repartir à zéro","courant","同义说法"],["tout reprendre","courant","全部重做"]],"fq":"中频，口语常用。","me":"re（再）+ partir（出发）+ de zéro：从 0 出发。","tr":{"zh":"项目失败了，我们得从头来过。","fr":"Le projet a échoué, nous devons repartir de zéro.","alt":"Le projet est un échec, il faut tout recommencer.","note":"repartir 用 être：nous sommes repartis。"}},
 "Réserver des surprises": {"pos":"v. 固定搭配，réserver（第一组，avoir）","s":"带来（惊喜、意外）；「留给你一些惊喜」。réserver qch à qn：给某人留着某物。主语常是旅行、命运、日子等。","ipa":"[ʁe.zɛʁ.ve.de.syʁ.pʁiz]","ph":"réserver 读 [ʁe.zɛʁ.ve]；des 读 [de]，和 surprises 之间不连读；surprises 读 [syʁ.pʁiz]，词尾 s 读 [z]（因为 s 在 i 后的 se 里）。","pi":"surprise 中间的 s 读 [z]，不要读 [s]；u 读 [y]，不是 [u]。","et":"réserver 来自拉丁语 reservare（保留）；surprise 来自 surprendre，由 sur + prendre。","ex":[["Ce voyage nous a réservé quelques surprises !","这次旅行给了我们一些惊喜！"],["La vie nous réserve parfois de belles surprises.","生活有时会给我们美好的惊喜。"]],"co":[["réserver une surprise à quelqu'un","给某人留个惊喜"],["réserver une table","订位"],["réserver un accueil chaleureux","给予热情的欢迎"]],"sy":[["apporter","courant","带来"],["offrir","courant","提供、赠予"],["garder en réserve","courant","留着备用"]],"fq":"中频，描述旅行和生活时常用。","me":"réserver = 「留着」：旅行给你留了惊喜。","tr":{"zh":"这次旅行给了我们不少惊喜。","fr":"Ce voyage nous a réservé beaucoup de surprises.","alt":"Ce voyage nous a réservé de belles surprises.","note":"réserver 的间接宾语 nous 放在助动词前。"}},
 "Restreindre": {"pos":"v.t. 及物动词，第三组（像 craindre），助动词 avoir；过去分词 restreint","s":"限制；缩小范围；使减少。restreindre l'accès / la consommation / ses dépenses。比 limiter 更书面、更正式。","ipa":"[ʁɛs.tʁɛ̃dʁ]","ph":"res [ʁɛs]；treindre 读 [tʁɛ̃dʁ]，ein 读鼻化 [ɛ̃]，结尾 dre 的 e 不发音。","pi":"ein 读 [ɛ̃]，不是 [ɛ.in]；变位 nous restreignons，gn 读 [ɲ]；过去分词 restreint，t 不发音。","et":"拉丁语 restringere（捆紧、限制）。同族：restriction（限制）、étroit（窄的）。","ex":[["Il faut restreindre nos dépenses.","必须限制我们的开支。"],["L'accès au parc est restreint.","公园的出入受到限制。"]],"co":[["restreindre ses dépenses","缩减开支"],["un accès restreint","有限制的通行"],["restreindre la liberté de","限制……的自由"]],"sy":[["limiter","courant","限制，更常用"],["réduire","courant","减少"],["élargir","courant","扩大（反义）"]],"fq":"中频，正式场合和新闻常见。","me":"restreindre 和 étroit（窄）同族：让范围变窄。","tr":{"zh":"政府决定限制使用塑料袋。","fr":"Le gouvernement a décidé de restreindre l'usage des sacs en plastique.","alt":"Le gouvernement limite l'usage des sacs plastiques.","note":"变位同 craindre：nous restreignons。"}},
 "Revêtir": {"pos":"v.t. 及物动词，第三组（像 vêtir），助动词 avoir；过去分词 revêtu","s":"穿上（多指特殊服装）；覆盖；具有（某种性质、形式）。revêtir un uniforme / revêtir une grande importance。书面语，日常多用 mettre。","ipa":"[ʁə.vɛ.tiʁ]","ph":"re [ʁə]；vê 读 [vɛ]；tir [tiʁ]；ê 读开口 [ɛ]。","pi":"ê 带重音，读 [ɛ]；变位不规则：je revêts，nous revêtons。日常「穿」用 mettre 更自然。","et":"拉丁语 revestire：re-（再）+ vestire（给……穿衣），同族 vêtement（衣服）。","ex":[["Il va revêtir son manteau.","他要穿上大衣。"],["Cette décision revêt une grande importance.","这个决定具有重要意义。"]],"co":[["revêtir un uniforme","穿上制服"],["revêtir une importance","具有重要性"],["revêtir un caractère","具有……的性质"]],"sy":[["mettre","courant","穿上，最常用"],["enfiler","courant","套上、很快穿上"],["endosser","soutenu","披上、承担"]],"fq":"中低频，书面语为主。","me":"re + vêtir：同 vêtement（衣服）。","tr":{"zh":"法官穿上黑色长袍。","fr":"Le juge revêt sa robe noire.","alt":"Le juge met sa robe noire.","note":"口语里用 mettre 更自然。"}},
 "Revivre": {"pos":"v. 动词，第三组（像 vivre），助动词 avoir；过去分词 revécu","s":"重获生机；重新感到活力；再经历一遍。Ça me fait revivre = 让我重新有了活力。及物时指「重温」：revivre un souvenir。","ipa":"[ʁə.vivʁ]","ph":"re [ʁə]；vivre 读 [vivʁ]，结尾 re 的 e 不发音。","pi":"vivre 词尾 -vre 读 [vʁ]，不发 e；变位同 vivre：je revis, nous revivons。","et":"re-（再）+ vivre（活，拉丁语 vivere）。同族：vie（生命）、vivant（活着的）。","ex":[["Ce voyage m'a fait revivre.","这次旅行让我重获生机。"],["Il aimerait revivre ce moment.","他希望能重温那一刻。"]],"co":[["faire revivre","使复苏；使重现"],["revivre un souvenir","重温回忆"],["se sentir revivre","感觉重获新生"]],"sy":[["renaître","soutenu","重生"],["ressusciter","soutenu","复活"],["revivifier","littéraire","使恢复生气"]],"fq":"中频，表达感受时常用。","me":"re（再）+ vivre（活）：又活过来了。","tr":{"zh":"春天来了，我感觉重新有了活力。","fr":"Avec le printemps, je me sens revivre.","alt":"Au printemps, je revis !","note":"faire revivre 里 faire 后接不定式。"}},
 "S'envoler": {"pos":"v.pr. 代词式动词，第一组，助动词 être；过去分词 envolé","s":"飞走；飞起来；（时间、价格等）飞逝、飙升。L'oiseau s'envole = 鸟飞走了。比喻义：Les prix s'envolent（价格飙升）。","ipa":"[sɑ̃.vɔ.le]","ph":"s'en 读 [sɑ̃]；vo [vɔ]；ler 读 [le]。","pi":"代词式动词要加 se / me / te：je m'envole；复合时态用 être：il s'est envolé。","et":"en-（离开）+ voler（飞，拉丁语 volare），加反身代词 se。","ex":[["L'oiseau s'envole.","鸟儿飞走了。"],["Le temps s'envole quand on s'amuse.","玩得开心时时间过得飞快。"]],"co":[["s'envoler vers","飞向……"],["les prix s'envolent","物价飙升"],["les souvenirs s'envolent","回忆飘散"]],"sy":[["décoller","courant","起飞"],["partir en flèche","courant","飙升"],["s'évanouir","soutenu","消散"]],"fq":"中频，日常和文学都用。","me":"en（离开）+ voler（飞）：飞离开。","tr":{"zh":"鸽子飞走了。","fr":"Les pigeons se sont envolés.","alt":"Les pigeons sont partis dans le ciel.","note":"过去分词要与主语一致：envolés。"}},
 "S'éteindre (mourir)": {"pos":"v.pr. 代词式动词，第三组（像 éteindre），助动词 être；过去分词 éteint","s":"（婉转地说）去世，安详离世。字面指「熄灭」，如灯、火、火焰熄灭。婉转表达 elle s'est éteinte 比 elle est morte 柔和。","ipa":"[se.tɛ̃dʁ]","ph":"é [e]；teindre 读 [tɛ̃dʁ]，ein 读鼻化 [ɛ̃]，词尾 e 不发音。","pi":"过去分词要和主语一致：elle s'est éteinte；ein 不要读成 [ein]。","et":"拉丁语 exstinguere（熄灭）。同族：éteint、extinction（灭绝；熄灭）。","ex":[["Ma grand-mère s'est éteinte à 101 ans.","我外婆在一百零一岁时去世了。"],["Le feu s'éteint doucement.","火慢慢熄灭了。"]],"co":[["s'éteindre paisiblement","安详离世"],["la lumière s'éteint","灯灭了"],["s'éteindre à l'âge de","在……岁去世"]],"sy":[["décéder","soutenu","逝世，正式用语"],["mourir","courant","死"],["disparaître","courant","离开人世（委婉）"]],"fq":"中频，讣告和日常委婉说法。","me":"像一盏灯慢慢熄灭：安静地离世。","tr":{"zh":"他爷爷昨晚安详地去世了。","fr":"Son grand-père s'est éteint paisiblement hier soir.","alt":"Son grand-père est décédé dans la paix hier soir.","note":"主语是女性时：elle s'est éteinte。"}},
 "S'offrir": {"pos":"v.pr. 代词式动词，第三组（像 ouvrir），助动词 être；过去分词 offert","s":"犒劳自己；给自己买（想要的东西）；送给自己。s'offrir un voyage / un petit plaisir。也可指「自己献上、出现在眼前」：Un beau paysage s'offre à nous。","ipa":"[sɔ.fʁiʁ]","ph":"o 在 s'offrir 中读开口 [ɔ]；ff 读单个 [f]；frir 读 [fʁiʁ]。","pi":"offrir 的变位像 ouvrir：j'offre（带 -e），不是 j'offris；过去分词 offert，t 不发音。","et":"拉丁语 offerre（呈献），晚期拉丁语 offerire。同族：offre（报价；优惠）。","ex":[["Je vais m'offrir un beau cadeau.","我要送自己一份好礼物。"],["Elle s'est offert un week-end à Paris.","她给自己买了个巴黎周末游。"]],"co":[["s'offrir un cadeau","送自己礼物"],["s'offrir un voyage","犒劳自己一次旅行"],["s'offrir un petit plaisir","给自己一点小享受"]],"sy":[["se faire plaisir","courant","让自己开心"],["se payer","familier","买给自己，口语"],["se gâter","courant","宠宠自己"]],"fq":"中频，口语常用。","me":"s'offrir：自己当送礼的人，也是收礼的人。","tr":{"zh":"我想给自己买一本好书。","fr":"J'ai envie de m'offrir un beau livre.","alt":"Je vais me faire plaisir avec un beau livre.","note":"s'est offert 中直接宾语在后时，过去分词不变。"}},
 "Se comporter": {"pos":"v.pr. 代词式动词，第一组，助动词 être；过去分词 comporté","s":"表现；举止；做人。强调行为方式：Il se comporte bien / mal。也可指事物「表现」：Cette voiture se comporte bien sur la route。","ipa":"[sə.kɔ̃.pɔʁ.te]","ph":"com 读鼻化 [kɔ̃]；por 读 [pɔʁ]；ter 读 [te]。","pi":"com 的 om 读 [ɔ̃]；别和 se conduire（品行）混为一谈。后面常接副词（bien / mal / comme）。","et":"拉丁语 comportare（带来）；se comporter 指「自己带着」行为。同族：comportement（行为）。","ex":[["Il se comporte bien.","他表现很好。"],["Les enfants se sont mal comportés.","孩子们举止不好。"]],"co":[["se comporter bien / mal","表现好 / 差"],["se comporter en adulte","像个成年人那样行事"],["se comporter comme","表现得像……"]],"sy":[["se conduire","courant","举止、表现"],["agir","courant","行动"],["se tenir","courant","举止（常用于礼貌）"]],"fq":"高频，日常常用。","me":"comportement（行为）的动词：自己的行为方式。","tr":{"zh":"他在学校表现很好。","fr":"Il se comporte très bien à l'école.","alt":"À l'école, il est sage.","note":"se comporter 后面常接副词。"}},
 "Se jeter à l'eau": {"pos":"v.pr. 固定短语，se jeter（第一组，助动词 être）","s":"下定决心去做（冒险的事）；跳进水里。字面指「跳入水中」，比喻鼓起勇气做一件难事：Il faut se jeter à l'eau。","ipa":"[sə.ʒə.te.a.lo]","ph":"jeter 读 [ʒə.te]；à l'eau 读 [a.lo]（eau 读 [o]）。","pi":"jeter 的变位：je jette，nous jetons（t 变化）；eau 读 [o]，不要读成 [eau]。","et":"jeter 来自拉丁语 jactare（扔）；eau 来自拉丁语 aqua。字面「把自己扔进水里」。","ex":[["Il est temps de se jeter à l'eau.","是时候下定决心了。"],["Elle s'est jetée à l'eau et a ouvert son restaurant.","她下定决心开了自己的餐厅。"]],"co":[["se jeter à l'eau","豁出去；下决心"],["il faut se jeter à l'eau","该鼓起勇气了"],["se lancer","courant"]],"sy":[["se lancer","courant","放手去做"],["oser","courant","敢于"],["sauter le pas","courant","迈出那一步"]],"fq":"中频，口语常用。","me":"像第一次下水游泳：先跳了再说。","tr":{"zh":"别犹豫了，下决心试试吧。","fr":"N'hésite plus, jette-toi à l'eau.","alt":"Arrête d'hésiter, lance-toi !","note":"命令式：jette-toi（代词放后）。"}},
 "Se mériter": {"pos":"v.pr. 代词式动词（被动意义），第一组，助动词 être","s":"值得争取；要靠努力才能获得。La victoire se mérite = 胜利要靠自己努力。这是被动含义的代词式用法，不是「自己配得上自己」。","ipa":"[sə.me.ʁi.te]","ph":"mé [me]；ri [ʁi]；ter [te]。","pi":"这里的 se 是被动义，主语是事物（la victoire / le succès）。人配得上某物用 mériter qch，不用 se mériter。","et":"拉丁语 meritare，源自 meritum（功劳、应得）。同族：mérite（功劳；价值）。","ex":[["La victoire se mérite.","胜利需要努力赢得。"],["Un bon café, ça se mérite !","一杯好咖啡可是要等的！"]],"co":[["ça se mérite","这是要争取的"],["la confiance se mérite","信任要靠赢得"],["mériter son succès","配得上自己的成功"]],"sy":[["se gagner","courant","靠赢得"],["valoir la peine","courant","值得"],["mériter","courant","应得、值得"]],"fq":"中低频，口语常用于夸张语气。","me":"mérite 的被动：好东西「被配得上」才会到手。","tr":{"zh":"信任是要靠争取的。","fr":"La confiance, ça se mérite.","alt":"On ne gagne pas la confiance sans effort.","note":"se mériter 是被动含义，主语常是事物。"}},
 "Se pencher sur": {"pos":"v.pr. 代词式动词，第一组，助动词 être；过去分词 penché","s":"研究；深入探讨（问题）；俯身看。比喻义：se pencher sur un problème。字面义：se pencher par la fenêtre（探出窗外）。","ipa":"[sə.pɑ̃.ʃe.syʁ]","ph":"pen 读 [pɑ̃]；ch 读 [ʃ]；sur 读 [syʁ]，u 读 [y]。","pi":"介词用 sur（研究某问题）；探出窗外用 par 或 à。sur 的 u 是 [y]，不是 [u]。","et":"来自俗拉丁语 *pendicare，与 pendre（悬挂）同族；se pencher 指「身体倾斜、前倾」。","ex":[["Les ingénieurs se sont penchés sur ce problème.","工程师们研究了这个问题。"],["Elle se penche sur le berceau.","她俯身看着摇篮。"]],"co":[["se pencher sur un problème","研究一个问题"],["se pencher par la fenêtre","探出窗外"],["se pencher en avant","向前倾"]],"sy":[["étudier","courant","研究"],["examiner","courant","审查"],["s'intéresser à","courant","关注"]],"fq":"中频，工作与新闻用语。","me":"penche（倾斜）→ 身体前倾去看：专心研究。","tr":{"zh":"我们得认真研究这个问题。","fr":"Nous devons nous pencher sérieusement sur ce problème.","alt":"Il faut qu'on étudie ce problème de près.","note":"se pencher sur + 名词。"}},
 "Se remettre en forme": {"pos":"v.pr. 固定短语，se remettre（第三组，助动词 être）；过去分词 remis","s":"恢复状态；重新找回体力、体型。常指运动、休息后恢复。se remettre de = 从（病、打击）中恢复。","ipa":"[sə.ʁə.mɛtʁ.ɑ̃.fɔʁm]","ph":"remettre 读 [ʁə.mɛtʁ]；en 读 [ɑ̃]，与 forme 之间不连读；forme 读 [fɔʁm]。","pi":"remettre 变位像 mettre：je me remets，nous nous remettons；过去分词 remis，s 不发音。","et":"re-（再）+ mettre（放，拉丁语 mittere）；forme 来自拉丁语 forma（形状）。","ex":[["Je fais du sport pour me remettre en forme.","我做运动来恢复状态。"],["Après la maladie, il se remet en forme peu à peu.","病后，他一点一点恢复状态。"]],"co":[["se remettre en forme","恢复状态"],["être en forme","状态好"],["se remettre d'une maladie","病后康复"]],"sy":[["retrouver la forme","courant","找回状态"],["se rétablir","courant","康复"],["se refaire une santé","courant","养好身体"]],"fq":"中频，日常常用。","me":"remettre + forme：把自己放回「好状态」里。","tr":{"zh":"新年后我想重新运动，恢复状态。","fr":"Après les fêtes, je veux me remettre en forme.","alt":"Après les fêtes, je me remets au sport.","note":"en forme 是固定表达，不加冠词。"}},
 "Se remettre en question": {"pos":"v.pr. 固定短语，se remettre（第三组，助动词 être）；过去分词 remis","s":"反思自己；质疑自己的做法、想法。对自己的看法和行为重新审视，是积极意义。remettre qch en question = 重新质疑某事。","ipa":"[sə.ʁə.mɛtʁ.ɑ̃.kɛs.tjɔ̃]","ph":"question 读 [kɛs.tjɔ̃]，qu 读 [k]，ti 读 [tj]；en 读 [ɑ̃]。","pi":"question 中 qu 读 [k]；ti 读 [tj]，不是 [ti] 或 [sj]。也可写 remettre en cause，意思相近。","et":"re-（再）+ mettre（放）+ en question（成为疑问）；question 来自拉丁语 quaestio（询问）。","ex":[["Il faut parfois se remettre en question.","有时需要反思自己。"],["Elle a remis ses choix en question.","她重新审视了自己的选择。"]],"co":[["se remettre en question","反思自己"],["remettre en question","重新质疑"],["une remise en question","反思；重新审视"]],"sy":[["remettre en cause","courant","质疑、重新审议"],["s'interroger","courant","自问"],["faire son autocritique","soutenu","自我批评"]],"fq":"中频，谈论成长和观点时常用。","me":"把自己「放回问号里」：重新审视一遍。","tr":{"zh":"犯错之后，他学会了反思自己。","fr":"Après son erreur, il a appris à se remettre en question.","alt":"Après son erreur, il s'est mis à se poser des questions.","note":"remettre en question 与 remettre en cause 同义。"}},
 "Soigner": {"pos":"v.t. 及物动词，第一组，助动词 avoir；过去分词 soigné","s":"治疗；照料；精心对待。soigner un malade / une grippe / son apparence。过去分词可作形容词：un repas soigné（精心准备的饭菜）。","ipa":"[swa.ɲe]","ph":"oi 读 [wa]；gn 读 [ɲ]（像「尼」）；er 读 [e]。","pi":"gn 读 [ɲ]，不是 [g] + [n]；oi 读 [wa]。soigner 不等于 guérir（治愈）：soigner 是「治疗」过程。","et":"来自法兰克语 *sunnjōn（关心、照顾）；同族：soin（照料；用心）。","ex":[["Le médecin soigne le patient.","医生给病人治疗。"],["Elle soigne ses plantes tous les jours.","她每天精心照料自己的植物。"]],"co":[["soigner un malade","治疗病人"],["se soigner","给自己治病；保养"],["soigner son image","注重自己的形象"],["prendre soin de","照顾……"]],"sy":[["guérir","courant","治愈（结果）"],["traiter","courant","治疗、处理"],["s'occuper de","courant","照料"]],"fq":"高频，日常常用。","me":"soin（照料）的动词：用心照顾。","tr":{"zh":"护士细心地照顾病人。","fr":"L'infirmière soigne les malades avec attention.","alt":"L'infirmière s'occupe bien des malades.","note":"soigner qn（治疗）与 guérir（治愈）不同。"}},
 "Soutenir": {"pos":"v.t. 及物动词，第三组（像 tenir），助动词 avoir；过去分词 soutenu","s":"支持；支撑；坚持（观点）；承受。soutenir un ami / une cause / une opinion。soutenir que… = 坚称……。","ipa":"[sut.niʁ]","ph":"sou 读 [su]；te 常省音；nir 读 [niʁ]，r 发音。","pi":"变位像 tenir：je soutiens，nous soutenons；过去分词 soutenu，同时也是形容词「正式的」（langue soutenue）。","et":"拉丁语 sustinere（从下面撑住）：sous- + tenir。同族：soutien（支持）。","ex":[["Je soutiens cette association.","我支持这个协会。"],["Ses parents le soutiennent toujours.","他的父母一直支持他。"]],"co":[["soutenir quelqu'un","支持某人"],["soutenir une thèse","答辩论文"],["soutenir que + 直陈式","坚称……"],["le soutien moral","精神支持"]],"sy":[["appuyer","courant","支持、依靠"],["encourager","courant","鼓励"],["défendre","courant","捍卫"]],"fq":"高频，日常和新闻常用。","me":"sou-（下）+ tenir（撑）：从下面撑住你。","tr":{"zh":"我的家人一直支持我。","fr":"Ma famille me soutient toujours.","alt":"Ma famille est toujours derrière moi.","note":"变位同 tenir：ils soutiennent。"}},
 "Surprendre": {"pos":"v.t. 及物动词，第三组（像 prendre），助动词 avoir；过去分词 surpris","s":"使惊讶；给……惊喜；撞见、当场发现。surprendre qn = 让人吃惊；surprendre qn en train de faire qch = 撞见某人在做某事。","ipa":"[syʁ.pʁɑ̃dʁ]","ph":"sur 读 [syʁ]；prendre 读 [pʁɑ̃dʁ]；词尾 e 不发音。","pi":"过去分词 surpris，s 和 t 都不发音；变位像 prendre：nous surprenons，ils surprennent。","et":"sur-（在上）+ prendre（拿）：「当场抓住」，引申为「使吃惊」。同族：surprise（惊喜）。","ex":[["Il aime surprendre ses amis.","他喜欢给朋友们惊喜。"],["Cette nouvelle m'a surpris.","这个消息让我很意外。"]],"co":[["surprendre quelqu'un","使某人惊讶"],["surprendre en train de","当场撞见……"],["être surpris de + 不定式","对……感到惊讶"],["Ça me surprend.","这让我吃惊。"]],"sy":[["étonner","courant","使吃惊"],["stupéfier","soutenu","使目瞪口呆"],["choquer","courant","使震惊（负面）"]],"fq":"高频，日常常用。","me":"sur + prendre：当场「抓到」你，让你惊讶。","tr":{"zh":"我想在她生日那天给她一个惊喜。","fr":"Je veux la surprendre le jour de son anniversaire.","alt":"Je veux lui faire une surprise pour son anniversaire.","note":"surprendre 的宾语是人，用直接宾语 la。"}},
 "Surveiller": {"pos":"v.t. 及物动词，第一组，助动词 avoir；过去分词 surveillé","s":"监督；看管；留意。surveiller les enfants / un examen / sa santé。和 regarder（看）不同：surveiller 有「负责盯着」的责任。","ipa":"[syʁ.vɛ.je]","ph":"sur [syʁ]；veil 读 [vɛj]；ller 读 [je]，il 听起来像 [j]。","pi":"-ill- 读 [j]，不是 [l]；surveiller 不是 regarder，带有「负责看管」的意思。","et":"sur-（在上）+ veiller（守夜，拉丁语 vigilare）。同族：surveillance（监视；看管）。","ex":[["Il faut surveiller les enfants.","必须看管孩子们。"],["Le professeur surveille l'examen.","老师监考。"]],"co":[["surveiller les enfants","看管孩子"],["surveiller sa santé","关注自己的健康"],["surveiller un examen","监考"],["sous surveillance","在监视下"]],"sy":[["observer","courant","观察"],["garder","courant","看守、照看"],["contrôler","courant","检查、控制"]],"fq":"高频，日常常用。","me":"sur（在上）+ veiller（守着）：站在上面盯着。","tr":{"zh":"你能帮我看一下孩子吗？","fr":"Tu peux surveiller les enfants, s'il te plaît ?","alt":"Tu peux jeter un œil aux enfants, s'il te plaît ?","note":"surveiller qn 为直接宾语，没有介词。"}},
 "Tirer avantage de": {"pos":"v. 固定短语，tirer（第一组，avoir）","s":"利用……（获利）；从……中得到好处。tirer avantage de la situation / de ses qualités。也可带贬义：占便宜。","ipa":"[ti.ʁe.a.vɑ̃.taʒ.də]","ph":"tirer 读 [ti.ʁe]；avantage 读 [a.vɑ̃.taʒ]，g 读 [ʒ]；de 轻读 [də]。","pi":"介词用 de；avantage 里 an 读 [ɑ̃]，ge 读 [ʒ]。tirer 本义是「拉；射」，此处是固定搭配。","et":"tirer（拉，来源不确定）+ avantage（来自 avant「前面」，意为「占先」）。","ex":[["Il sait tirer avantage de la situation.","他懂得利用形势。"],["Nous voulons tirer avantage de cette offre.","我们想利用这个优惠。"]],"co":[["tirer avantage de","从……中获益"],["tirer profit de","从……获利"],["tirer parti de","利用"],["tirer le meilleur de","发挥……的最大优势"]],"sy":[["profiter de","courant","利用、享受"],["tirer parti de","courant","充分利用"],["exploiter","courant","利用（可带贬义）"]],"fq":"中频，工作和正式场合常见。","me":"tirer（拉）+ avantage（优势）：把好处「拉」过来。","tr":{"zh":"我们应该利用这次机会。","fr":"Nous devons tirer avantage de cette occasion.","alt":"Il faut profiter de cette occasion.","note":"tirer avantage de + 名词。"}},
 "Tout plaquer": {"pos":"v. 固定短语，plaquer（第一组，avoir）","s":"抛下一切；说走就走。plaquer 在口语中是「甩掉、抛弃」：plaquer son travail / son copain。tout plaquer 常指放弃工作和生活去追求新生活。","ipa":"[tu.pla.ke]","ph":"tout 读 [tu]，t 不发音；plaquer 读 [pla.ke]，qu 读 [k]。","pi":"tout 里 -t 不发音；plaquer 是口语（familier），正式场合少用；与 plaque（板）同形近。","et":"plaquer 与 plaque（薄板）同族，本义「贴上、按住」，后来引申为「甩下」；具体来源不确定。","ex":[["J'ai tout plaqué pour partir vivre dans la forêt.","我抛下一切去森林生活。"],["Elle a tout plaqué et elle est partie au Canada.","她抛下一切去了加拿大。"]],"co":[["tout plaquer","抛下一切"],["plaquer son travail","辞掉工作"],["plaquer quelqu'un","甩掉某人"],["tout quitter","离开一切"]],"sy":[["tout quitter","courant","离开一切"],["laisser tomber","familier","放弃"],["abandonner","courant","抛弃"]],"fq":"中频，口语常用。","me":"plaquer 像把东西「啪」地甩在桌上：全扔下。","tr":{"zh":"他抛下一切去了乡下。","fr":"Il a tout plaqué pour aller à la campagne.","alt":"Il a tout quitté pour vivre à la campagne.","note":"tout 在这里是直接宾语，放在 plaquer 之前，过去分词不变。"}},
 "Viser à": {"pos":"v.t.ind. 间接及物动词，第一组，助动词 avoir；过去分词 visé","s":"旨在……；目标是……。viser à + 不定式：Ce projet vise à réduire la pollution。viser 直接接名词时是「瞄准」：viser une cible。","ipa":"[vi.ze.a]","ph":"vi [vi]；s 在元音间读 [z]；ser 读 [ze]；à 读 [a]。","pi":"viser à + 不定式 / 名词；s 读 [z]，不是 [s]。区分：viser une cible（瞄准）与 viser à（旨在）。","et":"拉丁语 visare（看，visus 的频繁体）。同族：vue、visée（目标）。","ex":[["Ce projet vise à réduire la pollution.","这个项目旨在减少污染。"],["Cette loi vise à protéger les enfants.","这项法律旨在保护儿童。"]],"co":[["viser à + 不定式","旨在……"],["viser un objectif","以某目标为目的"],["viser haut","目标定得高"],["viser la perfection","追求完美"]],"sy":[["avoir pour but de","courant","以……为目标"],["chercher à","courant","试图"],["tendre à","soutenu","趋向于"]],"fq":"中频，书面和正式场合常用。","me":"viser = 瞄准：先瞄，再射。","tr":{"zh":"这个计划旨在帮助年轻人。","fr":"Ce programme vise à aider les jeunes.","alt":"Ce programme a pour but d'aider les jeunes.","note":"viser à + 不定式。"}},
 "Accro": {"pos":"adj. 形容词（阴阳性同形），复数 accros；也可作名词","s":"上瘾的；迷恋的。口语：être accro au café / aux séries / au sport。形容对某物着迷停不下来。阴阳性同形。","ipa":"[a.kʁo]","ph":"ac 读 [a.k]；cro 读 [kʁo]，o 读 [o]。","pi":"口语词（familier），正式场合少用；词尾 o 读 [o]；介词常用 à：accro à qch。","et":"accro 是 accroché（被钩住）的缩略，口语产生；比喻「被钩住离不开」。","ex":[["Il est accro au chocolat.","他对巧克力上瘾。"],["Elle est accro à son téléphone.","她离不开手机。"]],"co":[["être accro à","对……上瘾"],["un accro du sport","运动成瘾的人"],["accro aux séries","迷上电视剧"]],"sy":[["dépendant","courant","依赖的"],["fan de","familier","狂热爱好者"],["passionné","courant","热衷的"]],"fq":"高频，口语常用。","me":"accro：像被钩子钩住，摘不下来。","tr":{"zh":"我儿子特别迷游戏。","fr":"Mon fils est accro aux jeux vidéo.","alt":"Mon fils ne peut plus se passer des jeux vidéo.","note":"accro 阴阳同形，介词用 à。"}},
 "Aérien(ne)": {"pos":"adj. 形容词，阴性 aérienne，复数 aériens / aériennes","s":"空中的；航空的；轻盈的。le transport aérien / la compagnie aérienne / une démarche aérienne（轻盈的步态）。","ipa":"[a.e.ʁjɛ̃]","ph":"a [a]；é [e]；rien 读 [ʁjɛ̃]，ien 读鼻化 [jɛ̃]；阴性 aérienne 读 [ʁjɛn]，n 要发音。","pi":"阳性 aérien 的 -ien 读鼻化 [jɛ̃]；阴性 -ienne 读 [jɛn]，不鼻化。拼写 aé 要分开读。","et":"拉丁语 aerius（空气的），来自希腊语 aēr（空气）。同族：air。","ex":[["C'est un transport aérien.","这是空中运输。"],["La compagnie aérienne annonce un retard.","航空公司宣布延误。"]],"co":[["le transport aérien","航空运输"],["une compagnie aérienne","航空公司"],["le trafic aérien","空中交通"],["par voie aérienne","通过空运"]],"sy":[["aéronautique","soutenu","航空的"],["léger","courant","轻盈的"],["terrestre","courant","陆地的（反义）"]],"fq":"中频，交通与新闻常用。","me":"aér-（空气）+ -ien：和 air 同根，属于空中。","tr":{"zh":"空运比海运更快。","fr":"Le transport aérien est plus rapide que le transport maritime.","alt":"L'avion va plus vite que le bateau.","note":"形容词放在名词后，并与之一致。"}},
 "Affecté(e)": {"pos":"adj. 形容词，阴性 affectée，复数 affectés / affectées","s":"受影响的；受冲击的；被派往的。être affecté par qch = 受某事影响（情绪或健康）。另有「被分配到某岗位」：affecté à un service。","ipa":"[a.fɛk.te]","ph":"a [a]；ffec 读 [fɛk]；té 读 [te]。","pi":"ff 读单个 [f]；注意与 affectueux（亲切的）区分；形容词要与名词性数一致。","et":"拉丁语 affectare（努力追求、影响），过去分词形容词化。同族：affecter、affection。","ex":[["Il a été très affecté par cette nouvelle.","这个消息对他影响很大。"],["Les régions affectées par la sécheresse.","受干旱影响的地区。"]],"co":[["être affecté par","受……影响"],["profondément affecté","深受打击"],["affecté à un poste","被派到某岗位"]],"sy":[["touché","courant","受影响的"],["ébranlé","soutenu","被动摇的"],["bouleversé","courant","被震撼的"]],"fq":"中频，新闻和谈论情绪时常见。","me":"a + ffect：被「影响」到的人。","tr":{"zh":"这场暴风雨影响了很多家庭。","fr":"Beaucoup de familles ont été affectées par la tempête.","alt":"La tempête a touché beaucoup de familles.","note":"被动式：être affecté par + 名词。"}},
 "Bon marché": {"pos":"loc. adj. 形容词性短语，不变化（阴阳性、单复数同形）","s":"便宜的；价格低的。bon marché 不变化：des chaussures bon marché。可作副词用法：acheter bon marché（便宜地买）。比 pas cher 稍微正式。","ipa":"[bɔ̃.maʁ.ʃe]","ph":"bon 读鼻化 [bɔ̃]；marché 读 [maʁ.ʃe]，ch 读 [ʃ]。","pi":"bon marché 不变化，不能写 bons marchés 当形容词；反义词是 cher（贵）。注意 bon 为鼻化 [ɔ̃]。","et":"bon + marché（市场，拉丁语 mercatus）：字面「好买卖」。","ex":[["Ce restaurant est bon marché.","这家餐厅很便宜。"],["Ces chaussures sont bon marché.","这些鞋很便宜。"]],"co":[["bon marché","便宜"],["des vêtements bon marché","便宜的衣服"],["acheter bon marché","便宜买入"],["meilleur marché","更便宜（比较级）"]],"sy":[["pas cher","courant","不贵，口语最常用"],["économique","courant","经济实惠"],["cher","courant","贵（反义）"]],"fq":"高频，日常常用。","me":"bon marché = 「好价钱」：便宜。","tr":{"zh":"这家商店的东西很便宜。","fr":"Les produits de ce magasin sont bon marché.","alt":"Dans ce magasin, c'est pas cher.","note":"bon marché 不随名词变化；比较级用 meilleur marché。"}},
 "Bondé(e)": {"pos":"adj. 形容词，阴性 bondée，复数 bondés / bondées","s":"拥挤的；挤满人的。le métro est bondé / une salle bondée。比 plein 更强调「挤得水泄不通」。","ipa":"[bɔ̃.de]","ph":"bon 读鼻化 [bɔ̃]；dé 读 [de]；阴性 bondée 读法相同。","pi":"bon 的 on 读 [ɔ̃]，不发 n；é 带重音，读 [e]。","et":"来自 bonde（桶塞，桶口）：「装到桶口」，即满得不能再满。","ex":[["Le train est bondé.","火车上挤满了人。"],["Le métro était bondé ce matin.","今早地铁挤爆了。"]],"co":[["un train bondé","挤满人的火车"],["bondé de monde","人山人海"],["une salle bondée","座无虚席的大厅"]],"sy":[["plein","courant","满的"],["comble","courant","满座的"],["désert","courant","空无一人（反义）"]],"fq":"中频，口语常用。","me":"bonde（桶塞）：装满到桶口。","tr":{"zh":"周末商场里人挤人。","fr":"Le centre commercial est bondé le week-end.","alt":"Le week-end, il y a un monde fou au centre commercial.","note":"bondé 常与 de monde 搭配。"}},
 "Bref / Brève": {"pos":"adj. 形容词，阳性 bref，阴性 brève，复数 brefs / brèves","s":"简短的；短暂的。un bref séjour / une brève réponse。副词用法：bref ! = 总之；一句话。","ipa":"[bʁɛf] / [bʁɛv]","ph":"阳性 bref 读 [bʁɛf]，f 发音；阴性 brève 读 [bʁɛv]，v 发音。","pi":"阳性词尾是 -f，阴性变 -ve：bref → brève，并加重音。f 要发音。","et":"拉丁语 brevis（短的）。同族：abréger（缩短）、brièvement（简短地）。","ex":[["Ce fut un bref moment.","那是短暂的一刻。"],["Sois bref, s'il te plaît.","请简短点。"]],"co":[["en bref","总之"],["un bref séjour","短期停留"],["à bref délai","在短期内"],["Bref !","总之！一句话！"]],"sy":[["court","courant","短的"],["concis","soutenu","简洁的"],["long","courant","长（反义）"]],"fq":"高频，日常常用。","me":"bref / brève：f 变 v，像 neuf / neuve。","tr":{"zh":"请简单说一下你的想法。","fr":"Donne-moi ton avis en quelques mots, sois bref.","alt":"Dis-moi vite ce que tu penses, en bref.","note":"阴性 brève：une brève réponse。"}},
 "Consécutif / Consécutive": {"pos":"adj. 形容词，阳性 consécutif，阴性 consécutive，复数 consécutifs / consécutives","s":"连续的；紧接着的。trois jours consécutifs。也可表示「由……引起的」：consécutif à un accident。","ipa":"[kɔ̃.se.ky.tif] / [kɔ̃.se.ky.tiv]","ph":"con 读鼻化 [kɔ̃]；sé 读 [se]；cu 读 [ky]；tif / tive 读 [tif] / [tiv]。","pi":"cu 读 [ky]，u 是 [y]；阴性 -tive 读 [tiv]，f 变 v。","et":"中世纪拉丁语 consecutivus，来自 consequi（跟随）。同族：conséquence（后果）。","ex":[["C'est sa troisième victoire consécutive.","这是他连续第三次获胜。"],["Il pleut depuis cinq jours consécutifs.","已经连续下了五天雨。"]],"co":[["trois jours consécutifs","连续三天"],["consécutif à","由……引起的"],["la troisième fois consécutive","连续第三次"]],"sy":[["successif","courant","相继的"],["d'affilée","courant","接连地（副词）"],["de suite","courant","连续地"]],"fq":"中频，新闻和书面常见。","me":"consécutif ← conséquence：一个接一个。","tr":{"zh":"他连续三天迟到了。","fr":"Il est arrivé en retard trois jours consécutifs.","alt":"Il est arrivé en retard trois jours de suite.","note":"consécutif 放在被修饰名词后并一致。"}},
 "D'exception": {"pos":"loc. adj. 形容词性短语，不变化","s":"非凡的；特别的；例外的。des moments d'exception / un talent d'exception / une mesure d'exception。后接名词，用来形容品质出众。","ipa":"[dɛk.sɛp.sjɔ̃]","ph":"d' 省音；ex 读 [ɛk.s]；ception 读 [sɛp.sjɔ̃]，ti 读 [sj]。","pi":"ex 读 [ɛk] 而不是 [ɛg]；ception 中 -tion 读 [sjɔ̃]。d'exception 不变化。","et":"拉丁语 exceptio（除外），来自 excipere（取出）。d'exception：字面义「属于例外的」。","ex":[["Nous avons passé des moments d'exception.","我们度过了非凡的时光。"],["C'est un artiste d'exception.","他是一位杰出的艺术家。"]],"co":[["un talent d'exception","非凡的才华"],["une journée d'exception","难忘的一天"],["une mesure d'exception","例外措施"],["l'état d'exception","紧急状态"]],"sy":[["exceptionnel","courant","杰出的，最常用"],["extraordinaire","courant","非凡的"],["remarquable","soutenu","卓越的"]],"fq":"中频，书面和赞美时常用。","me":"d'exception：属于「例外」的那一类，所以很特别。","tr":{"zh":"她是一位非凡的老师。","fr":"C'est une enseignante d'exception.","alt":"C'est une prof exceptionnelle.","note":"d'exception 放名词后，不变化。"}},
 "Dépaysé(e)": {"pos":"adj. 形容词，阴性 dépaysée，复数 dépaysés / dépaysées","s":"离开熟悉环境而感到陌生的；换了环境有新鲜感的。se sentir dépaysé = 有异乡感。可褒可贬：新奇、也可能不适应。","ipa":"[de.pe.i.ze]","ph":"dé [de]；pay 读 [pe.i]（a 与 y 变成 [ɛ.i]）；sé 读 [ze]（s 在元音间读 [z]）。","pi":"pay 读 [pe.i]，不是 [pai]；s 读 [z]。中文「水土不服」只是部分对应，更多是「陌生新鲜感」。","et":"dé-（离开）+ pays（国家、乡土）+ -é：「离开故土」。同族：dépaysement（换环境的新鲜感）。","ex":[["Je me sens un peu dépaysé.","我有点水土不服（有陌生感）。"],["On est complètement dépaysés au Japon.","在日本我们完全像到了另一个世界。"]],"co":[["se sentir dépaysé","感到陌生新鲜"],["le dépaysement","换环境的新鲜感"],["un voyage dépaysant","令人耳目一新的旅行"]],"sy":[["désorienté","courant","迷失方向的"],["perdu","courant","迷茫的"],["exotique","courant","异国情调的"]],"fq":"中频，旅行话题常用。","me":"dé-（离开）+ pays（国家）：离开家乡的感觉。","tr":{"zh":"刚到北京的时候，我觉得很陌生。","fr":"Quand je suis arrivé à Pékin, je me sentais dépaysé.","alt":"En arrivant à Pékin, je ne me sentais pas chez moi.","note":"dépaysé 是形容词，与主语性数一致。"}},
 "Discret / Discrète": {"pos":"adj. 形容词，阳性 discret，阴性 discrète，复数 discrets / discrètes","s":"低调的；不张扬的；谨慎的。une personne discrète / un maquillage discret。也指「保守秘密」：Il est discret = 他不会乱说。","ipa":"[dis.kʁɛ] / [dis.kʁɛt]","ph":"阳性 discret 读 [dis.kʁɛ]，t 不发音；阴性 discrète 读 [dis.kʁɛt]，t 发音。","pi":"阳性末尾 -et 不发音；阴性 -ète 要读 t。注意不是英语 discrete（离散的）的意思。","et":"拉丁语 discretus（分开的、有辨别力的）。同族：discrétion（谨慎）、discrètement（悄悄地）。","ex":[["Elle est très discrète.","她很低调。"],["Il a fait un geste discret.","他做了一个不引人注意的手势。"]],"co":[["une personne discrète","低调谨慎的人"],["rester discret","保持低调"],["en toute discrétion","完全保密地"]],"sy":[["réservé","courant","内敛的"],["effacé","courant","不爱出风头的"],["indiscret","courant","多事的（反义）"]],"fq":"中频，日常常用。","me":"discret：低调，不让人注意；阴性 discrète 读出 t。","tr":{"zh":"请你低调一点，别说出去。","fr":"Sois discret, ne le dis à personne.","alt":"Reste discret et garde ça pour toi.","note":"对女性说：Sois discrète。"}},
 "Durable": {"pos":"adj. 形容词（阴阳性同形），复数 durables","s":"可持续的；持久的；耐用的。développement durable = 可持续发展；une relation durable = 长久的关系。","ipa":"[dy.ʁabl]","ph":"du 读 [dy]，u 为 [y]；rable 读 [ʁabl]，词尾 e 不发音。","pi":"u 读 [y]，不是 [u]；词尾 -ble 读 [bl]。注意与英语 durable 的拼写相似但用法更广（含可持续）。","et":"拉丁语 durabilis，来自 durare（持续）。同族：durée（时间长度）、durer（持续）。","ex":[["C'est un développement durable.","这是可持续发展。"],["Il cherche une solution durable.","他在找一个长久的解决办法。"]],"co":[["le développement durable","可持续发展"],["une solution durable","持久的解决办法"],["un produit durable","耐用的产品"],["la mode durable","可持续时尚"]],"sy":[["pérenne","soutenu","长久的"],["résistant","courant","结实的"],["éphémère","courant","短暂的（反义）"]],"fq":"高频，环保和新闻常见。","me":"dure（持续）+ able：能持续下去。","tr":{"zh":"我们需要一个长久的解决办法。","fr":"Nous avons besoin d'une solution durable.","alt":"Il nous faut une solution qui tienne dans le temps.","note":"阴阳性同形，只加 s 变复数。"}},
 "Écolo": {"pos":"adj. 形容词（阴阳性同形），复数 écolos；也可作名词","s":"环保的；关心生态的。口语，由 écologiste 缩略。un geste écolo / un projet écolo。作名词指环保人士：un écolo。","ipa":"[e.kɔ.lo]","ph":"é [e]；co 读 [kɔ]；lo 读 [lo]。","pi":"口语（familier）；在正式文体里用 écologique。词尾 o 读 [o]，复数 s 不发音。","et":"écologiste 的缩略；écologie 来自希腊语 oikos（家）+ logos（学问）。","ex":[["C'est un projet très écolo.","这是一个很环保的项目。"],["Mes voisins sont assez écolos.","我的邻居们很环保。"]],"co":[["un geste écolo","环保举动"],["devenir écolo","变得环保"],["un mode de vie écolo","环保的生活方式"]],"sy":[["écologique","courant","环保的，标准说法"],["vert","courant","绿色的"],["respectueux de l'environnement","soutenu","尊重环境的"]],"fq":"中频，口语常用。","me":"écolo = 把 écologique 剪短：口语味。","tr":{"zh":"骑车上班很环保。","fr":"Aller au travail à vélo, c'est écolo.","alt":"Venir à vélo, c'est bon pour la planète.","note":"écolo 是口语，阴阳性同形。"}},
 "Émouvant": {"pos":"adj. 形容词，阴性 émouvante，复数 émouvants / émouvantes","s":"感人的；动人的。un film émouvant / un discours émouvant。émouvant 指「让人动情」；ému 指「被感动的」，主语不同。","ipa":"[e.mu.vɑ̃]","ph":"é [e]；mou [mu]；vant 读鼻化 [vɑ̃]；阴性 émouvante 读 [e.mu.vɑ̃t]，t 发音。","pi":"émouvant（让人感动的）与 ému（被感动的）要区分。阳性 -ant 的 t 不发音；阴性才读 t。","et":"émouvoir（拉丁语 emovere，推动、使激动）的现在分词。同族：émotion（情感）。","ex":[["Ce film est très émouvant.","这部电影非常感人。"],["Son histoire est émouvante.","他的故事很感人。"]],"co":[["un film émouvant","感人的电影"],["un moment émouvant","感人的时刻"],["un témoignage émouvant","动人的见证"]],"sy":[["touchant","courant","动人的"],["bouleversant","courant","令人震撼的"],["poignant","soutenu","令人揪心的"]],"fq":"中频，日常评论电影书籍时常用。","me":"é-（出）+ mouvoir（动）：让心动起来。","tr":{"zh":"这首歌让人很感动。","fr":"Cette chanson est très émouvante.","alt":"Cette chanson me touche beaucoup.","note":"émouvant 要与名词性数一致。"}},
 "Étoilé(e)": {"pos":"adj. 形容词，阴性 étoilée，复数 étoilés / étoilées","s":"星光灿烂的；布满星星的；（餐厅）获米其林星级的。un ciel étoilé / un restaurant étoilé。","ipa":"[e.twa.le]","ph":"é [e]；toi 读 [twa]；lé 读 [le]。","pi":"oi 读 [wa]；étoile 与 étoilé 都有 oi；阴性 étoilée 读音不变。","et":"étoile（拉丁语 stella）+ -é。同族：étoile、constellation（星座）。","ex":[["Le ciel est étoilé ce soir.","今晚天空繁星点点。"],["Ils dînent dans un restaurant étoilé.","他们在一家星级餐厅吃饭。"]],"co":[["un ciel étoilé","繁星满天的夜空"],["une nuit étoilée","星光之夜"],["un restaurant étoilé","获星级的餐厅"],["un chef étoilé","星级大厨"]],"sy":[["constellé","soutenu","缀满……的"],["brillant","courant","闪亮的"],["nuageux","courant","多云的（反义）"]],"fq":"中频，描写夜空时常用。","me":"étoile + -é：满是星星的。","tr":{"zh":"我们在星空下露营。","fr":"Nous avons campé sous un ciel étoilé.","alt":"On a dormi à la belle étoile, sous les étoiles.","note":"étoilé 与名词性数一致。"}},
 "Être complice": {"pos":"loc. adj. 形容词性短语（être + complice），complice 阴阳性同形，复数 complices","s":"默契的；亲密的、心有灵犀的。Ils sont complices = 他们很有默契。complice 另有「共犯」之意：le complice d'un crime。要看语境。","ipa":"[ɛtʁ.kɔ̃.plis]","ph":"être 读 [ɛtʁ]；com 读鼻化 [kɔ̃]；plice 读 [plis]，c 在 i 前读 [s]。","pi":"complice 有双重意义：亲密默契（褒）与共犯（贬）。com 的 om 读 [ɔ̃]，c 读 [s]。","et":"拉丁语 complex, complicis（相互缠绕的、同谋者）。同族：complicité（默契；同谋）。","ex":[["Ils sont très complices.","他们非常有默契。"],["Les deux sœurs sont complices depuis l'enfance.","这对姐妹从小就很亲密。"]],"co":[["être très complices","非常有默契"],["un regard complice","会意的眼神"],["la complicité","默契；共谋"]],"sy":[["proche","courant","亲近的"],["uni","courant","团结的"],["inséparable","courant","形影不离的"]],"fq":"中频，描写关系时常用。","me":"com（一起）+ plic（折）：两个人「折在一起」，心意相通。","tr":{"zh":"他们俩特别有默契。","fr":"Ces deux-là sont vraiment complices.","alt":"Ils s'entendent à merveille, ces deux-là.","note":"être complice 用于指关系亲密，也要和「共犯」区分。"}},
 "Flottant(e)": {"pos":"adj. 形容词，阴性 flottante，复数 flottants / flottantes","s":"漂浮的；浮动的；飘动的。un marché flottant / une île flottante / un taux flottant（浮动汇率）。也可形容衣服宽松飘动。","ipa":"[flɔ.tɑ̃]","ph":"flo 读 [flɔ]；t 读单个 [t]；ant 读鼻化 [ɑ̃]；阴性 flottante 读 [flɔ.tɑ̃t]。","pi":"tt 只读一个 [t]；-ant 为鼻化 [ɑ̃]，阴性才读 t。","et":"flotter 的现在分词。flotter 的最终来源不确定，可能与日耳曼语或拉丁语 fluctuare 有关。同族：flotte（舰队）。","ex":[["C'est un marché flottant.","这是水上市场。"],["Elle porte une robe flottante.","她穿着一条飘逸的裙子。"]],"co":[["un marché flottant","水上市场"],["un pont flottant","浮桥"],["un taux de change flottant","浮动汇率"]],"sy":[["flottant","courant","漂浮的"],["fluide","courant","流畅的、飘逸的"],["immobile","courant","不动的（反义）"]],"fq":"中频，旅行和经济领域常用。","me":"flotter（漂）+ -ant：正在漂的。","tr":{"zh":"湖上有一家水上餐厅。","fr":"Il y a un restaurant flottant sur le lac.","alt":"Sur le lac, il y a un restaurant sur l'eau.","note":"flottant 要和名词性数一致。"}},
 "Géant(e)": {"pos":"adj. 形容词，阴性 géante，复数 géants / géantes；也可作名词","s":"巨大的；超大的。un arbre géant / un écran géant。作名词指「巨人」：un géant / une géante。","ipa":"[ʒe.ɑ̃]","ph":"g 在 é 前读 [ʒ]；éant 读 [e.ɑ̃]，两个元音分开读；阴性 géante 读 [ʒe.ɑ̃t]。","pi":"g 读 [ʒ]，不是 [g]；éa 分成两个音节 [e.ɑ̃]，不是 [jɑ̃]。","et":"拉丁语 gigas, gigantem，来自希腊语 gigas（巨人）。同族：gigantesque（巨大的）。","ex":[["C'est un arbre géant.","这是一棵巨树。"],["Ils ont installé un écran géant sur la place.","他们在广场上装了一块巨型屏幕。"]],"co":[["un écran géant","巨型屏幕"],["un panda géant","大熊猫"],["un pas de géant","一大步"],["un géant de l'industrie","行业巨头"]],"sy":[["énorme","courant","巨大的"],["gigantesque","courant","庞大的"],["minuscule","courant","微小的（反义）"]],"fq":"中频，日常常用。","me":"géant 与英语 giant 对应。","tr":{"zh":"广场上有一棵巨树。","fr":"Il y a un arbre géant sur la place.","alt":"Sur la place, il y a un arbre énorme.","note":"géant 通常放在名词后。"}},
 "Hexagonal(e)": {"pos":"adj. 形容词，阳性 hexagonal，阴性 hexagonale，复数 hexagonaux / hexagonales","s":"六边形的；（口语）法国本土的。l'Hexagone 指法国本土，因轮廓像六边形。le marché hexagonal = 法国国内市场。","ipa":"[ɛg.za.gɔ.nal]","ph":"hex 读 [ɛgz]，h 不发音，x 读 [gz]；a [a]；go [gɔ]；nal [nal]。","pi":"h 不发音；x 读 [gz]。阳性复数 hexagonaux（al → aux）。","et":"希腊语 hexa-（六）+ gōnia（角），+ -al。l'Hexagone = 法国的昵称。","ex":[["Le marché hexagonal est en croissance.","法国本土市场在增长。"],["Une boîte hexagonale.","一个六边形盒子。"]],"co":[["le marché hexagonal","法国国内市场"],["l'Hexagone","法国本土"],["une forme hexagonale","六边形"]],"sy":[["français","courant","法国的"],["métropolitain","soutenu","本土的"],["national","courant","全国的"]],"fq":"中低频，新闻中常用。","me":"hexa（六）+ gone（角）：法国像六边形。","tr":{"zh":"法国国内市场很重要。","fr":"Le marché hexagonal est très important.","alt":"Le marché français est important.","note":"复数阳性 hexagonaux。"}},
 "Ibérique": {"pos":"adj. 形容词（阴阳性同形），复数 ibériques","s":"伊比利亚的；伊比利亚半岛的。la péninsule ibérique 指西班牙和葡萄牙所在的半岛。也可指伊比利亚的人或文化。","ipa":"[i.be.ʁik]","ph":"i [i]；bé [be]；rique 读 [ʁik]，qu 读 [k]。","pi":"qu 读 [k]；词首 i 读 [i]；首字母小写（形容词），地名 Ibérie 首字母大写。","et":"拉丁语 Iberia，来自古希腊语 Ibēria（伊比利亚）。同族：Ibérie。","ex":[["La péninsule ibérique est belle.","伊比利亚半岛很美。"],["Le jambon ibérique est célèbre.","伊比利亚火腿很有名。"]],"co":[["la péninsule ibérique","伊比利亚半岛"],["le jambon ibérique","伊比利亚火腿"],["le lynx ibérique","伊比利亚猞猁"]],"sy":[["espagnol","courant","西班牙的"],["portugais","courant","葡萄牙的"],["hispanique","soutenu","西班牙语系的"]],"fq":"低频，地理、历史和旅游话题常见。","me":"Ibérique ≈ Iberian（英语 Iberian）。","tr":{"zh":"我们去伊比利亚半岛旅行。","fr":"Nous voyageons dans la péninsule ibérique.","alt":"On part en voyage en Espagne et au Portugal.","note":"ibérique 用作形容词，首字母小写。"}},
 "Inexploré": {"pos":"adj. 形容词，阴性 inexplorée，复数 inexplorés","s":"未被探索的；没有人去过、研究过的。可指地方（un territoire inexploré），也可指领域、思路（des pistes inexplorées）。","ipa":"[i.nɛk.splɔ.ʁe]","ph":"in- 后面是元音，所以不鼻化，读 [i.n]；x 读 [ks]；结尾 é 读 [e]。","pi":"in- 在元音前不是 [ɛ̃]；阴性 -ée 读音不变。","et":"前缀 in-（否定）+ exploré（拉丁语 explorare，探索）。同源：explorer, explorateur。","ex":[["C'est un territoire inexploré.","这是未被探索的领域。"],["Il reste des pistes inexplorées.","还有一些没探索过的思路。"]],"co":[["un territoire inexploré","未知领域"],["une piste inexplorée","尚未探索的思路"],["des régions inexplorées","未勘探的地区"]],"sy":[["inconnu","courant","未知的、不认识的"],["vierge","courant","未开发的（forêt vierge 原始森林）"],["exploré","courant","反义：已被探索的"]],"fq":"中频，偏书面。","me":"in-（不）+ exploré（探索过）= 没被探索过。","tr":{"zh":"这个岛上有一片还没被人探索过的森林。","fr":"Il y a une forêt inexplorée sur cette île.","alt":"Sur cette île, il y a une forêt que personne n'a encore explorée.","note":"形容词放在名词后，性数要一致。"}},
 "Léger / Légère": {"pos":"adj. 形容词，阳性 léger，阴性 légère，复数 légers / légères","s":"轻的（重量）；轻微的；清淡的。除了 un sac léger，还有 un repas léger（清淡的一餐）、une blessure légère（轻伤）、un café léger（淡咖啡）。","ipa":"[le.ʒe] / [le.ʒɛʁ]","ph":"g 在 e 前读 [ʒ]；léger 结尾 -er 读 [e]；légère 的 -ère 读 [ɛʁ]。","pi":"léger 不发 r，légère 要发 r；两个重音符号别搞错（é…è）。","et":"来自通俗拉丁语 leviarius，源自 levis（轻）。同源：alléger（减轻）, légèreté（轻盈）。","ex":[["Ce sac est très léger.","这个包很轻。"],["Il a une légère fièvre.","他有点低烧。"],["Je prends un repas léger le soir.","我晚上吃得清淡。"]],"co":[["léger comme une plume","轻如羽毛"],["un repas léger","清淡的一餐"],["prendre quelque chose à la légère","不把某事当回事"]],"sy":[["lourd","courant","反义：重的"],["mince","courant","薄的；纤细的"]],"fq":"高频，日常常用。","me":"léger = 像一根羽毛（plume）那样轻。","tr":{"zh":"我想吃点清淡的。","fr":"Je voudrais quelque chose de léger.","alt":"Je veux manger léger.","note":"quelque chose de + 形容词（阳性）。"}},
 "Localisé(e)": {"pos":"adj. 形容词，阴性 localisée，复数 localisés / localisées","s":"局部的；集中在某处的。localisé dans / à / sur = 集中在……。常用于医学和新闻：une douleur localisée（局部疼痛）、un incendie localisé（被限制在局部的火灾）。","ipa":"[lɔ.ka.li.ze]","ph":"c 在 a 前读 [k]；s 在两个元音之间读 [z]；结尾 é 读 [e]。","pi":"s 读 [z]，不是 [s]；拼写是 -is-，不是 -iz-。","et":"local（拉丁语 localis，源自 locus 地方）+ -iser + -é（过去分词）。同源：localiser, localisation。","ex":[["La douleur est localisée dans le dos.","疼痛集中在背部。"],["Le feu est resté localisé dans la cuisine.","火势只局限在厨房。"]],"co":[["une douleur localisée","局部疼痛"],["localisé dans / à + 地点","位于、集中在某处"],["un incendie localisé","被控制在局部的火灾"]],"sy":[["local","courant","本地的；局部的"],["limité","courant","有限的、局限的"],["général","courant","反义：普遍的"]],"fq":"中频，偏书面、科技。","me":"local + -isé：被「放」到某个 lieu（地方）里的。","tr":{"zh":"疼痛只集中在左脚。","fr":"La douleur est localisée dans le pied gauche.","alt":"J'ai mal seulement au pied gauche.","note":"localisé dans + 身体部位或地点。"}},
 "Lointain(e)": {"pos":"adj. 形容词，阴性 lointaine，复数 lointains / lointaines","s":"遥远的（距离或时间）。un pays lointain（遥远的国家）；un souvenir lointain（久远的记忆）；un cousin lointain（远房表亲）。也可作名词：dans le lointain（在远处）。","ipa":"[lwɛ̃.tɛ̃]","ph":"oin 读 [wɛ̃]；ain 读 [ɛ̃]；两个 n 都不单独发音（鼻化元音）。阴性 lointaine 读 [lwɛ̃.tɛn]。","pi":"oin 不是 [wa]+n，而是一个鼻化的 [wɛ̃]；阳性结尾不发 n。","et":"与 loin（拉丁语 longe，远地）同源，由晚期拉丁语 longitanus 演变而来。同源：loin, éloigner。","ex":[["C'est un pays lointain.","这是一个遥远的国家。"],["Ce n'est qu'un souvenir lointain.","那只是一个久远的记忆。"],["Il a un cousin lointain au Canada.","他在加拿大有个远房表亲。"]],"co":[["un pays lointain","遥远的国家"],["un parent lointain","远亲"],["un passé lointain","遥远的过去"],["dans un avenir pas si lointain","在不太远的将来"]],"sy":[["éloigné","courant","偏远的；疏远的"],["proche","courant","反义：近的"],["reculé","soutenu","偏僻的；久远的"]],"fq":"中频，日常常用。","me":"loin（远）+ -tain：非常 loin。","tr":{"zh":"他住在一个很遥远的城市。","fr":"Il habite dans une ville lointaine.","alt":"Il habite très loin d'ici.","note":"lointain 修饰名词；说「离这里很远」用副词 loin。"}},
 "Maritime": {"pos":"adj. 形容词（阴阳同形），复数 maritimes","s":"海的；海上的；沿海的。une voie maritime（海上航线）；le transport maritime（海运）；une ville maritime（海滨城市）。和 marin 区分：marin 偏「海里的」（animaux marins）。","ipa":"[ma.ʁi.tim]","ph":"r 是小舌音 [ʁ]；-time 读 [tim]，m 要发出来；结尾 e 不发。","pi":"-time 的 m 要读 [m]，不要读成鼻化音；i 读 [i]，不是英语的 /aɪ/。","et":"拉丁语 maritimus，源自 mare（海）。同源：mer, marin, marine。","ex":[["C'est une voie maritime.","这是一条海上航线。"],["Le transport maritime est moins cher.","海运更便宜。"],["Marseille est une ville maritime.","马赛是一座海滨城市。"]],"co":[["le transport maritime","海运"],["une voie maritime","海上航线"],["le climat maritime","海洋性气候"],["un port maritime","海港"]],"sy":[["marin","courant","海里的；与海有关的"],["naval","courant","船舶的；海军的"],["côtier","courant","沿海的"]],"fq":"中频。","me":"mare 是拉丁语的「海」：mari-time = 与海有关。","tr":{"zh":"大部分货物走海运。","fr":"La plupart des marchandises voyagent par voie maritime.","alt":"Presque tout arrive par bateau.","note":"par voie maritime = 走海运；la plupart des + 复数名词。"}},
 "Méconnu(e)": {"pos":"adj. 形容词，阴性 méconnue，复数 méconnus / méconnues","s":"鲜为人知的；没有得到应有认可的。强调「价值被忽视」：un artiste méconnu 是「被埋没的艺术家」。动词 méconnaître = 不了解；低估。","ipa":"[me.kɔ.ny]","ph":"é 读 [e]；o 读开口的 [ɔ]；结尾 u 读 [y]（嘴唇圆而紧）。","pi":"结尾 u 读 [y]，不是 [u]；别和 inconnu（未知的）混淆。","et":"前缀 mé-（表示错误、否定）+ connu（connaître 的过去分词，拉丁语 cognoscere）。反义：reconnu（被认可的）。","ex":[["C'est un artiste méconnu.","他是个不被人了解的艺术家。"],["Ce village est méconnu des touristes.","游客很少知道这个村子。"],["C'est un talent méconnu.","这是一种被埋没的才华。"]],"co":[["un artiste méconnu","被埋没的艺术家"],["un chef-d'œuvre méconnu","被埋没的杰作"],["méconnu du grand public","大众不太了解"]],"sy":[["inconnu","courant","未知的、不认识的（没有「被低估」的意思）"],["obscur","soutenu","默默无闻的"],["reconnu","courant","反义：被认可的"]],"fq":"中低频，偏书面。","me":"mé-（错）+ connu：别人「看错了」他的价值。","tr":{"zh":"这是一位被埋没的诗人。","fr":"C'est un poète méconnu.","alt":"Ce poète n'est pas assez connu.","note":"méconnu 放在名词后，性数与名词一致。"}},
 "Mondial(e)": {"pos":"adj. 形容词，阴性 mondiale，阳性复数 mondiaux，阴性复数 mondiales","s":"全球的；世界性的。la population mondiale（世界人口）；un record mondial（世界纪录）；la Seconde Guerre mondiale（第二次世界大战）。","ipa":"[mɔ̃.djal]","ph":"on 读鼻化 [ɔ̃]；di + a 连成 [dja]；l 要发。阳性复数 mondiaux 读 [mɔ̃.djo]。","pi":"阳性复数是 mondiaux，不是 mondials；di-a 是一个音节 [dja]。","et":"来自 monde（拉丁语 mundus，世界）+ 后缀 -ial。同源：mondialisation。","ex":[["C'est un événement mondial.","这是一场全球性活动。"],["Il a battu le record mondial.","他打破了世界纪录。"],["La population mondiale augmente.","世界人口在增长。"]],"co":[["la population mondiale","世界人口"],["un record mondial","世界纪录"],["la Seconde Guerre mondiale","第二次世界大战"],["à l'échelle mondiale","在全球范围内"]],"sy":[["global","courant","整体的；全球的"],["international","courant","国际的"],["universel","courant","普遍的、通用的"]],"fq":"高频，新闻和日常常用。","me":"monde → mondial：「整个 monde」的。","tr":{"zh":"他打破了世界纪录。","fr":"Il a battu le record mondial.","alt":"Il a battu le record du monde.","note":"record mondial 与 record du monde 都对。"}},
 "Mondialisé(e)": {"pos":"adj. 形容词，阴性 mondialisée，复数 mondialisés / mondialisées","s":"全球化的；已被纳入全球范围的。un monde mondialisé = 全球化的世界。动词 mondialiser，名词 la mondialisation（全球化）。","ipa":"[mɔ̃.dja.li.ze]","ph":"on 读 [ɔ̃]；dia 读 [dja]；s 在元音间读 [z]；结尾 é 读 [e]。","pi":"s 读 [z]；音节较多，慢读：mon-dia-li-sé。","et":"monde + -ial + -iser + -é，一层层加后缀。同源：mondialisation。","ex":[["Nous vivons dans un monde mondialisé.","我们生活在全球化的世界。"],["L'économie est de plus en plus mondialisée.","经济越来越全球化。"],["Le marché de la mode est mondialisé.","时尚市场是全球化的。"]],"co":[["un monde mondialisé","全球化的世界"],["une économie mondialisée","全球化的经济"],["un marché mondialisé","全球化的市场"]],"sy":[["globalisé","courant","与 mondialisé 基本同义，多用于经济"],["international","courant","国际的"],["local","courant","反义：本地的"]],"fq":"中频，偏新闻和论述。","me":"monde → mondial → mondialisé：世界越变越「连在一起」。","tr":{"zh":"如今经济是全球化的。","fr":"Aujourd'hui, l'économie est mondialisée.","alt":"De nos jours, tout est mondialisé.","note":"作表语时与主语性数一致（économie → mondialisée）。"}},
 "Plein (complet)": {"pos":"adj. 形容词，阴性 pleine，复数 pleins / pleines","s":"满的；坐满的、客满的。航班、车厢、停车场满员可说 plein 或 complet。plein de + 名词 = 很多……（plein d'amis）。名词：faire le plein = 加满油。","ipa":"[plɛ̃]","ph":"ein 读鼻化 [ɛ̃]；阳性 n 不发；阴性 pleine 读 [plɛn]。","pi":"阳性 [plɛ̃] 与阴性 [plɛn] 读音不同；鼻化元音别读成 [ɛn]。","et":"拉丁语 plenus（满）。同源：remplir（装满）, plénitude, plenty（英语）。","ex":[["Les vols sont tous pleins.","航班全部满员。"],["Le bus est plein à craquer.","公交车挤得满满的。"],["Il a la tête pleine d'idées.","他脑子里全是想法。"]],"co":[["plein de + 名词","很多……"],["faire le plein","加满油"],["en plein air","在户外"],["en plein milieu de","正中间"]],"sy":[["complet","courant","客满、满员（酒店、航班、剧场）"],["rempli","courant","被填满的"],["vide","courant","反义：空的"]],"fq":"极高频，日常常用。","me":"plein ← plenus；英语 plenty 同源。","tr":{"zh":"今天所有的火车都满了。","fr":"Tous les trains sont pleins aujourd'hui.","alt":"Aujourd'hui, les trains sont complets.","note":"订满的座位更常说 complet。"}},
 "Poétique": {"pos":"adj. 形容词（阴阳同形），复数 poétiques","s":"诗的；有诗意的。un texte poétique（诗意的文字）；une licence poétique（诗的破格）。名词 la poésie = 诗歌。","ipa":"[pɔ.e.tik]","ph":"三个音节：o 读开口 [ɔ]，é 读 [e]，要分开读；qu 读 [k]。","pi":"po 和 é 要分成两个音节，不要连成 [pwe]；结尾 -que 读 [k]。","et":"希腊语 poiêtikos → 拉丁语 poeticus；源自 poiein（制作、创作）。同源：poème, poète, poésie。","ex":[["Ce texte est très poétique.","这篇文字很有诗意。"],["Elle a une vision poétique du monde.","她用诗意的眼光看世界。"]],"co":[["un texte poétique","诗意的文字"],["la licence poétique","诗的破格"],["un langage poétique","诗意的语言"]],"sy":[["lyrique","soutenu","抒情的"],["romantique","courant","浪漫的"],["prosaïque","soutenu","反义：平淡乏味的"]],"fq":"中频。","me":"poète → poétique：-ique 变成形容词。","tr":{"zh":"这座城市夜里很有诗意。","fr":"Cette ville est très poétique la nuit.","alt":"La nuit, cette ville est pleine de poésie.","note":"阴阳同形，poétique 不加 e。"}},
 "Précieux / Précieuse": {"pos":"adj. 形容词，阳性 précieux，阴性 précieuse，阴性复数 précieuses","s":"珍贵的；宝贵的。可指贵重物品（une pierre précieuse 宝石），也可指有价值的东西（un conseil précieux 宝贵的建议）。形容人或文风时可指「矫揉造作的」。","ipa":"[pʁe.sjø] / [pʁe.sjøz]","ph":"c 在 i 前读 [s]；ieu 读 [jø]；阳性 x 不发音，阴性 -se 读 [z]。","pi":"阳性 précieux 的 x 不发音，阴性 précieuse 才有 [z]；阳性复数仍是 précieux。","et":"拉丁语 pretiosus，源自 pretium（价格、价值）。同源：prix, apprécier。","ex":[["C'est un objet précieux.","这是件珍贵的物品。"],["Merci pour ton conseil précieux.","谢谢你宝贵的建议。"],["Le temps est précieux.","时间是宝贵的。"]],"co":[["une pierre précieuse","宝石"],["un métal précieux","贵金属"],["un conseil précieux","宝贵的建议"],["le temps est précieux","时间宝贵"]],"sy":[["de valeur","courant","有价值的"],["inestimable","soutenu","无价的"],["rare","courant","稀有的"]],"fq":"中频，日常和书面都常用。","me":"précieux ← pretium → prix：值钱的。","tr":{"zh":"时间比金钱更宝贵。","fr":"Le temps est plus précieux que l'argent.","alt":"Le temps vaut plus que l'argent.","note":"plus + 形容词 + que 表示比较。"}},
 "Progressif / Progressive": {"pos":"adj. 形容词，阳性 progressif，阴性 progressive，复数 progressifs / progressives","s":"逐步的；渐进的。un changement progressif（逐步的变化）；une augmentation progressive（逐渐上升）。也用于 un impôt progressif（累进税）。","ipa":"[pʁɔ.gʁe.sif] / [pʁɔ.gʁe.siv]","ph":"g 在 r 前读 [g]；ss 读 [s]；阳性 -f 读 [f]，阴性 -ve 读 [v]。","pi":"阳性 -if 的 f 要发出来；阴性是 f → v 的变化（-ive）。","et":"来自拉丁语 progressus（前进），动词 progresser。同源：progrès, progressivement。","ex":[["C'est un changement progressif.","这是逐步的变化。"],["Il y a une reprise progressive du travail.","工作在逐步恢复。"]],"co":[["un changement progressif","逐步的变化"],["une augmentation progressive","逐渐上升"],["un impôt progressif","累进税"],["une reprise progressive","逐步恢复"]],"sy":[["graduel","soutenu","渐进的"],["lent","courant","缓慢的"],["brusque","courant","反义：突然的"]],"fq":"中频，偏书面、新闻。","me":"progrès → progressif：一步一步地「前进」。","tr":{"zh":"他的法语在逐步进步。","fr":"Son français s'améliore de façon progressive.","alt":"Son français progresse petit à petit.","note":"de façon progressive = 逐步地；petit à petit 更口语。"}},
 "Propre": {"pos":"adj. 形容词（阴阳同形），复数 propres","s":"有两个主要意思：①放在名词前 = 自己的（ma propre voiture 我自己的车）；②放在名词后 = 干净的（une chemise propre 一件干净的衬衫）。另有 le sens propre（本义）、propre à（……特有的）。","ipa":"[pʁɔpʁ]","ph":"o 读开口 [ɔ]；词尾 e 不发音，但 p 和 r 都要读出来 [pʁ]。","pi":"位置决定意思：mon propre appartement（我自己的公寓）≠ mon appartement propre（我那间干净的公寓）；r 是小舌音。","et":"拉丁语 proprius（自己的、特有的）。同源：propriété, propriétaire, approprié（合适的）。","ex":[["Je fabrique ma propre énergie.","我自己生产能源。"],["Ma chemise est propre.","我的衬衫是干净的。"],["Chacun a sa propre opinion.","每个人都有自己的看法。"]],"co":[["ma propre voiture","我自己的车"],["une chambre propre","干净的房间"],["le sens propre","本义"],["propre à + 名词","……特有的"]],"sy":[["net","courant","干净、整洁的"],["sale","courant","反义：脏的"],["personnel","courant","个人的（≈ 自己的）"]],"fq":"极高频，日常常用。","me":"前自己，后干净：propre 在名词前 = 自己的，在名词后 = 干净的。","tr":{"zh":"我想有一个属于自己的房间。","fr":"Je veux avoir ma propre chambre.","alt":"Je veux une chambre à moi.","note":"propre 放在所有格和名词之间，强调「自己的」。"}},
 "Regardant": {"pos":"adj. 形容词，阴性 regardante，复数 regardants / regardantes","s":"挑剔的；斤斤计较的。多用否定：pas très regardant = 不太计较、不太讲究。常指花钱或规则：être regardant sur la dépense = 在开销上抠门。和现在分词 regardant（正在看）形式相同。","ipa":"[ʁə.gaʁ.dɑ̃]","ph":"re 读 [ʁə]；g 在 a 前读 [g]；-ant 读鼻化 [ɑ̃]，t 不发音。","pi":"作形容词时多说 pas regardant / très regardant，别按字面理解成「看」。","et":"来自动词 regarder（re- + garder）的现在分词，引申为「在意细节的」。","ex":[["Les autorités n'ont pas été très regardantes sur ce sujet.","当局在这个问题上不太计较。"],["Il n'est pas regardant sur le prix.","他不太在乎价钱。"]],"co":[["être regardant sur + 名词","在……上计较"],["pas très regardant","不太讲究"],["regardant sur la dépense","花钱抠门"]],"sy":[["pointilleux","courant","吹毛求疵的"],["exigeant","courant","要求高的"],["radin","familier","小气的（只指钱）"]],"fq":"中低频，常用否定式。","me":"regarder de près：什么都「看」得很仔细的人。","tr":{"zh":"他对吃的不太讲究。","fr":"Il n'est pas très regardant sur la nourriture.","alt":"Il n'est pas difficile sur la nourriture.","note":"être regardant sur + 名词。"}},
 "Réjouissant": {"pos":"adj. 形容词，阴性 réjouissante，复数 réjouissants / réjouissantes","s":"令人高兴的；令人欣慰的。une nouvelle réjouissante（好消息）。常带一点书面感。常见反话：Ce n'est pas très réjouissant. = 这可不怎么让人开心。","ipa":"[ʁe.ʒwi.sɑ̃]","ph":"é 读 [e]；j 读 [ʒ]；oui 读 [wi]；ss 读 [s]；-ant 读 [ɑ̃]。","pi":"j 读 [ʒ]（不是 [dʒ]）；oui 读 [wi]；结尾 t 不发音。","et":"来自动词 réjouir（re- + 古法语 joir）的现在分词，与 joie（喜悦）同源。","ex":[["C'est une nouvelle réjouissante.","这是个令人高兴的消息。"],["Ce n'est pas très réjouissant.","这可不怎么让人高兴。"],["Ces résultats sont réjouissants.","这些结果令人欣慰。"]],"co":[["une nouvelle réjouissante","令人高兴的消息"],["une perspective réjouissante","令人欣喜的前景"],["ce n'est pas réjouissant","这可不怎么让人高兴"]],"sy":[["encourageant","courant","令人鼓舞的"],["réconfortant","courant","令人欣慰的"],["déprimant","courant","反义：令人沮丧的"]],"fq":"中低频，偏书面。","me":"ré-joui-ssant：带来 joie（喜悦）的。","tr":{"zh":"这是个令人欣慰的结果。","fr":"C'est un résultat réjouissant.","alt":"Ce résultat fait plaisir.","note":"réjouissant 说事物，说人用 se réjouir（高兴）。"}},
 "Solaire": {"pos":"adj. 形容词（阴阳同形），复数 solaires","s":"太阳的；太阳能的。l'énergie solaire（太阳能）；un panneau solaire（太阳能板）；la crème solaire（防晒霜）；le système solaire（太阳系）。","ipa":"[sɔ.lɛʁ]","ph":"o 读开口 [ɔ]；-aire 读 [ɛʁ]，r 要发。","pi":"-aire 读 [ɛʁ]，不是 [air]；ensoleillé（阳光充足的）不是「太阳能的」。","et":"拉丁语 solaris，源自 sol（太阳）。同源：soleil, solarium。","ex":[["Il utilise un vélo solaire.","他用太阳能自行车。"],["Mets de la crème solaire.","涂点防晒霜。"],["Cette maison a des panneaux solaires.","这栋房子装了太阳能板。"]],"co":[["l'énergie solaire","太阳能"],["un panneau solaire","太阳能板"],["la crème solaire","防晒霜"],["le système solaire","太阳系"]],"sy":[["photovoltaïque","soutenu","光伏的（技术用语）"],["ensoleillé","courant","阳光充足的（天气、地方）"],["lunaire","courant","月亮的（对比）"]],"fq":"中频。","me":"sol 在拉丁语是「太阳」：soleil, solaire。","tr":{"zh":"我们家屋顶上有太阳能板。","fr":"Nous avons des panneaux solaires sur le toit.","alt":"Il y a des panneaux solaires sur notre toit.","note":"复数名词配复数形容词 solaires。"}},
 "Sonore": {"pos":"adj. 形容词（阴阳同形），复数 sonores","s":"声音的；响亮的；有声的。le volume sonore（音量）；la pollution sonore（噪音污染）；un signal sonore（提示音）；une bande sonore（配乐、音轨）。","ipa":"[sɔ.nɔʁ]","ph":"两个 o 都读开口 [ɔ]；结尾 r 要发 [ʁ]；e 不发音。","pi":"结尾的 r 要读出来；别和 sombre（昏暗的）混淆。","et":"拉丁语 sonorus，源自 sonus（声音）。同源：son, sonner, résonner, sonnerie。","ex":[["Le volume sonore est trop fort.","音量太大了。"],["Il y a un signal sonore quand la porte s'ouvre.","门一开就有提示音。"],["La pollution sonore est forte en ville.","城市里噪音污染严重。"]],"co":[["le volume sonore","音量"],["la pollution sonore","噪音污染"],["une bande sonore","配乐、音轨"],["un signal sonore","提示音"]],"sy":[["bruyant","courant","吵闹的（带负面）"],["audible","soutenu","听得见的"],["silencieux","courant","反义：安静的"]],"fq":"中频。","me":"son（声音）+ -ore：与声音有关的。","tr":{"zh":"这里的噪音水平太高了。","fr":"Le niveau sonore est trop élevé ici.","alt":"Il y a trop de bruit ici.","note":"niveau sonore = 噪音或音量水平。"}},
 "Spontané(e)": {"pos":"adj. 形容词，阴性 spontanée，复数 spontanés / spontanées","s":"自发的；自然而然的；不做作的。une réaction spontanée（自发反应）；une personne spontanée（率真的人）；une candidature spontanée（自荐求职，不是回应招聘）。","ipa":"[spɔ̃.ta.ne]","ph":"on 读鼻化 [ɔ̃]；结尾 é 读 [e]；开头 sp 连读。","pi":"on 读 [ɔ̃]，不是 [ɔn]；英语 spontaneous 的 -eous，法语是 -é。","et":"拉丁语 spontaneus，源自 sponte（自愿地）。同源：spontanéité, spontanément。","ex":[["C'est une réaction spontanée.","这是自发的反应。"],["Elle est très spontanée.","她非常率真。"],["J'ai envoyé une candidature spontanée.","我投了一份自荐求职信。"]],"co":[["une réaction spontanée","自发的反应"],["un geste spontané","自然的举动"],["une candidature spontanée","自荐求职"],["une personne spontanée","率真的人"]],"sy":[["naturel","courant","自然的"],["instinctif","courant","本能的"],["réfléchi","courant","反义：深思熟虑的"]],"fq":"中频。","me":"和英语 spontaneous 几乎一样：去掉 -eous，加 -é。","tr":{"zh":"他的笑是自然流露的。","fr":"Son rire est spontané.","alt":"Il rit de façon spontanée.","note":"作表语时形容词与主语性数一致。"}},
 "Surprenant(e)": {"pos":"adj. 形容词，阴性 surprenante，复数 surprenants / surprenantes","s":"令人惊讶的；出乎意料的。形容事物让人吃惊：un résultat surprenant。和 surpris(e)（感到吃惊的人）区分：C'est surprenant. / Je suis surpris.","ipa":"[syʁ.pʁə.nɑ̃]","ph":"u 读 [y]；pre 里的 e 读弱 [ə]；-ant 读 [ɑ̃]；两个 r 都是小舌音。","pi":"surprenant（令人惊讶的）≠ surpris（感到惊讶的）；-ant 的 t 不发音。","et":"surprendre（sur- + prendre）的现在分词 -ant。同源：surprise, prendre。","ex":[["C'est un résultat surprenant.","这是一个令人惊讶的结果。"],["Ce n'est pas surprenant.","这并不奇怪。"],["Il a une force surprenante.","他的力气大得惊人。"]],"co":[["un résultat surprenant","令人惊讶的结果"],["ce n'est pas surprenant","这不奇怪"],["il est surprenant que + 虚拟式","令人惊讶的是……"]],"sy":[["étonnant","courant","令人吃惊的（几乎同义）"],["étrange","courant","奇怪的"],["prévisible","soutenu","反义：可预见的"]],"fq":"高频，日常常用。","me":"surprise + -nant：造成 surprise 的。","tr":{"zh":"这个结果真让人吃惊。","fr":"Ce résultat est vraiment surprenant.","alt":"Franchement, ce résultat m'a surpris.","note":"surprenant 说事，surpris 说人。"}},
 "Virtuel(le)": {"pos":"adj. 形容词，阴性 virtuelle，复数 virtuels / virtuelles","s":"虚拟的；潜在的。un monde virtuel（虚拟世界）；la réalité virtuelle（虚拟现实）；une réunion virtuelle（线上会议）。哲学上也指「潜在的、可能的」。","ipa":"[viʁ.tɥɛl]","ph":"r 小舌音 [ʁ]；tu 在这里是半元音 [tɥ]；-el 读 [ɛl]。阴性 -elle 读音相同。","pi":"-uel 读 [ɥɛl]（嘴唇先圆后展），不是 [uel]；阴性只多一个 l 和 e，读音不变。","et":"中世纪拉丁语 virtualis，源自 virtus（力量、能力）。同源：vertu（美德）。","ex":[["C'est un monde virtuel.","这是一个虚拟世界。"],["Nous faisons une réunion virtuelle.","我们开线上会议。"]],"co":[["un monde virtuel","虚拟世界"],["la réalité virtuelle","虚拟现实"],["une visite virtuelle","线上参观"],["un assistant virtuel","虚拟助手"]],"sy":[["numérique","courant","数字的"],["en ligne","courant","线上的"],["réel","courant","反义：真实的"]],"fq":"中高频，数字生活常用。","me":"和英语 virtual 几乎同形，只是读 [viʁ.tɥɛl]。","tr":{"zh":"我们周三开线上会议。","fr":"Nous avons une réunion virtuelle mercredi.","alt":"On fait une réunion en ligne mercredi.","note":"星期几前不加冠词，表示「这个周三」。"}},
 "Visuel(le)": {"pos":"adj. 形容词，阴性 visuelle，复数 visuels / visuelles","s":"视觉的；看得见的。la mémoire visuelle（视觉记忆）；les arts visuels（视觉艺术）；un support visuel（视觉辅助材料）。作名词 un visuel = 配图、视觉素材（广告用语）。","ipa":"[vi.zɥɛl]","ph":"s 在元音间读 [z]；-uel 读 [ɥɛl]。","pi":"s 读 [z]，不是 [s]；-uel 与 virtuel 一样读 [ɥɛl]。","et":"晚期拉丁语 visualis，源自 visus（视觉），来自 videre（看）。同源：voir, vision, visible。","ex":[["J'ai une mémoire visuelle.","我有视觉记忆。"],["Il apprend avec des supports visuels.","他靠视觉材料学习。"],["Les arts visuels sont très variés.","视觉艺术种类繁多。"]],"co":[["la mémoire visuelle","视觉记忆"],["les arts visuels","视觉艺术"],["un support visuel","视觉辅助材料"],["un trouble visuel","视觉障碍"]],"sy":[["optique","soutenu","光学的；视觉的"],["auditif","courant","对比：听觉的"],["oculaire","soutenu","眼睛的"]],"fq":"中频。","me":"vis- 和 voir、vision 同根：看。","tr":{"zh":"我是视觉型的学习者。","fr":"Je suis un apprenant visuel.","alt":"J'apprends mieux avec des images.","note":"女生说 une apprenante visuelle。"}},
 "À peine": {"pos":"loc. adv. 副词短语","s":"几乎不；勉强；刚刚。①Il a à peine mangé = 他几乎没吃；②à peine arrivé = 刚到；③句首 À peine… que… = 刚……就……（书面，常主谓倒装）。","ipa":"[a.pɛn]","ph":"à 读 [a]；peine 里 ei 读 [ɛ]，所以是 [pɛn]；词尾 e 不发。","pi":"ei 读 [ɛ]，不是 [e]；à peine 本身含否定意味，不要再加 ne…pas。","et":"peine 来自拉丁语 poena（惩罚；痛苦、困难）；à peine 字面「带着困难」。","ex":[["Il a à peine mangé.","他几乎没吃东西。"],["À peine étions-nous rentrées qu'elle voulait déjà repartir.","我们刚回来她就又想走。"],["Je comprends à peine.","我几乎听不懂。"]],"co":[["à peine arrivé(e)","刚到"],["à peine… que…","刚……就……"],["il y a à peine un an","仅仅一年前"],["à peine visible","几乎看不见"]],"sy":[["presque pas","courant","几乎不"],["tout juste","courant","刚好、勉强"],["guère","soutenu","几乎不（常与 ne 搭配）"]],"fq":"高频，口语和书面都常用。","me":"「带着 peine（困难）」才做到 = 勉强 = 几乎不。","tr":{"zh":"我几乎听不见你。","fr":"Je t'entends à peine.","alt":"Je t'entends presque pas.","note":"à peine 放在动词后，不用 ne…pas。"}},
 "En particulier": {"pos":"loc. adv. 副词短语","s":"尤其；特别是。J'aime les fruits, en particulier les pommes. 另有「私下地、单独地」的意思：parler à quelqu'un en particulier。","ipa":"[ɑ̃.paʁ.ti.ky.lje]","ph":"en 读 [ɑ̃]；u 读 [y]；-ier 读 [lje]；r 小舌音。","pi":"en 是 [ɑ̃]，不是 [ɛ̃]；particulier 的 u 读 [y]。","et":"particulier 来自拉丁语 particularis（部分的），源自 particula（小部分）。同源：partie, particule。","ex":[["J'aime les fruits, en particulier les pommes.","我喜欢水果，尤其是苹果。"],["Cette ville est belle, en particulier la vieille ville.","这座城市很美，尤其是老城区。"],["Je voudrais te parler en particulier.","我想单独和你谈谈。"]],"co":[["en particulier","尤其"],["rien de particulier","没什么特别的"],["un cas particulier","特殊情况"],["signe particulier","特征（身份证上的）"]],"sy":[["notamment","soutenu","特别是"],["surtout","courant","尤其、主要"],["spécialement","courant","特别地"]],"fq":"高频，日常常用。","me":"从一堆里「点名」挑出一个 particulier（特别的）。","tr":{"zh":"我喜欢动物，尤其是猫。","fr":"J'aime les animaux, en particulier les chats.","alt":"J'aime les animaux, surtout les chats.","note":"en particulier 前后用逗号隔开。"}},
 "Énormément": {"pos":"adv. 副词","s":"极其；非常多；大大地。修饰动词：Il a énormément grandi。énormément de + 名词（de 后不加冠词）= 非常多的……：énormément de monde。不能直接修饰形容词（不说 énormément grand）。","ipa":"[e.nɔʁ.me.mɑ̃]","ph":"é 读 [e]；o 读开口 [ɔ]；-mé- 读 [me]；-ment 读 [mɑ̃]。","pi":"修饰形容词要用 très / vraiment，不能用 énormément；énormément de 后不加冠词。","et":"énorme + -ment；énorme 来自拉丁语 enormis（e- 「离开」+ norma 「规范」），即「超出常规」。同源：norme, normal。","ex":[["Il a énormément grandi.","他长高了很多。"],["J'ai énormément de travail.","我有非常多的工作。"],["Merci énormément.","非常感谢。"]],"co":[["énormément de + 名词","非常多的……"],["aimer énormément","非常喜欢"],["énormément de monde","好多人"],["ça m'a énormément plu","我非常喜欢"]],"sy":[["beaucoup","courant","很多（最常用）"],["extrêmement","courant","极其（也能修饰形容词）"],["vachement","familier","超级（口语）"]],"fq":"高频，口语很常用。","me":"énorme + -ment：「巨大地」。","tr":{"zh":"我非常想念你。","fr":"Tu me manques énormément.","alt":"Tu me manques beaucoup.","note":"manquer 的主语是被想念的人。"}},
 "Pas forcément": {"pos":"loc. adv. 副词短语","s":"不一定；未必。部分否定：Ce n'est pas forcément vrai。口语常省略 ne；也可单独作答：— C'est cher ? — Pas forcément.","ipa":"[pa.fɔʁ.se.mɑ̃]","ph":"pas 的 s 不发；forcément 里 c 在 e 前读 [s]，é 读 [e]，-ment 读 [mɑ̃]。","pi":"pas 的 s 不发音；是部分否定，不等于「完全不」；é 不能漏。","et":"forcément = forcé（被迫的、必然的）+ -ment，字面「必然地」；前加 pas 表示「不一定」。","ex":[["Ce n'est pas forcément vrai.","这不一定是真的。"],["Pas forcément, ça dépend.","不一定，看情况。"],["Les plus chers ne sont pas forcément les meilleurs.","最贵的不一定最好。"]],"co":[["pas forcément","不一定"],["ce n'est pas forcément + 形容词","不一定……"],["pas forcément le meilleur","不一定是最好的"]],"sy":[["pas nécessairement","soutenu","不一定（更正式）"],["pas toujours","courant","不总是"],["forcément","courant","反义：必然地"]],"fq":"高频，口语很常用。","me":"不被 force（强力）逼成「必然」= 不一定。","tr":{"zh":"贵的不一定好。","fr":"Ce qui est cher n'est pas forcément bon.","alt":"C'est pas forcément mieux parce que c'est cher.","note":"口语常省略 ne。"}},
 "Moi-même / Toi-même / Soi-même / ....": {"pos":"pron. 加强代词；复数 nous-mêmes / vous-mêmes / eux-mêmes / elles-mêmes","s":"我自己 / 你自己 / 他自己……，强调「亲自、本人」。全套：moi-même, toi-même, lui-même, elle-même, soi-même, nous-mêmes, vous-même(s), eux-mêmes, elles-mêmes。soi-même 用于泛指（on, chacun, il faut）。","ipa":"[mwa.mɛm]","ph":"moi 读 [mwa]；même 读 [mɛm]；连字符不读。toi-même [twa.mɛm]，soi-même [swa.mɛm]。","pi":"必须有连字符；nous-mêmes 要加 s；对一个人说 vous-même 不加 s；泛指用 soi-même，不用 lui-même。","et":"moi + même；même 来自晚期拉丁语 metipsimus（强调「自己」的形式，源自 ipse）。","ex":[["Je l'ai fait moi-même.","我是自己做的。"],["Tu peux le faire toi-même.","你可以自己做。"],["Il faut le voir soi-même.","得亲眼去看。"]],"co":[["le faire soi-même","自己动手做"],["Fais-le toi-même !","你自己做！"],["par lui-même","靠他自己"],["être soi-même","做自己"]],"sy":[["en personne","courant","亲自"],["tout seul","courant","独自（强调没人帮）"],["personnellement","courant","亲自；就我个人而言"]],"fq":"高频，日常常用。","me":"même = 「同一个」：moi + même = 就是我本人。","tr":{"zh":"你自己试试！","fr":"Essaie toi-même !","alt":"Teste-le toi-même !","note":"toi-même 放句末强调。"}},
 "Une fois": {"pos":"loc. conj. 连词短语（+ 过去分词 / 形容词 / 名词）","s":"一旦；等到……之后。Une fois + 过去分词 / 形容词 / 名词，可以不带动词：Une fois adulte, … / Une fois rentré, … 。后接完整句子要加 que：Une fois que + 直陈式。另外 une fois 也表示「一次」。","ipa":"[yn.fwa]","ph":"une 读 [yn]；fois 读 [fwa]，s 不发。","pi":"fois 的 s 不发音；une fois que 后用直陈式，不用虚拟式；省略动词时，隐含主语必须与主句主语一致。","et":"fois 来自拉丁语 vicem（次、轮换）。une fois 本是「一次」，引申为「一旦」。","ex":[["Une fois adulte, j'aurai une voiture.","等我成年，我就会有一辆车。"],["Une fois rentré, il a mangé.","回到家后，他就吃饭了。"],["Une fois que tu auras fini, appelle-moi.","你一做完就给我打电话。"]],"co":[["une fois que + 直陈式","一旦……"],["une fois + 过去分词","……之后"],["une fois pour toutes","一劳永逸"],["une fois de plus","再一次"]],"sy":[["dès que","courant","一……就"],["après que","courant","……之后"],["quand","courant","当……时"]],"fq":"极高频，日常常用。","me":"「一次」做完，就进入下一步 = 一旦。","tr":{"zh":"一旦做完作业，我就去玩。","fr":"Une fois mes devoirs finis, je vais jouer.","alt":"Une fois que j'aurai fini mes devoirs, j'irai jouer.","note":"alt 用 une fois que + 先将来时，更完整。"}},
 "Lors de": {"pos":"loc. prép. 介词短语（+ 名词）","s":"在……时；在……期间。后接带冠词的事件名词：lors de la réunion, lors de mon voyage。相当于 pendant / au moment de，但更书面。连词是 lorsque + 句子。","ipa":"[lɔʁ.də]","ph":"lors 的 s 不发，读 [lɔʁ]；de 读 [də]。","pi":"lors 的 s 不发音；lors de + 名词，lorsque + 完整句子，别混用。","et":"lors 来自古法语 lors，源自拉丁语 illa hora（那一刻）。","ex":[["Je l'ai vu lors de la réunion.","会议期间我见到了他。"],["Lors de notre voyage, il a plu tous les jours.","我们旅行期间，天天下雨。"],["Lors de la fête, il y avait beaucoup de monde.","派对上人很多。"]],"co":[["lors de + 名词","在……时"],["lors de la réunion","在会议上"],["lors de mon dernier voyage","在我上次旅行时"],["dès lors","从那时起"]],"sy":[["pendant","courant","在……期间（最常用）"],["au cours de","soutenu","在……的过程中"],["à l'occasion de","soutenu","在……之际"]],"fq":"中高频，偏书面。","me":"lors ≈ 「那一刻」：lors de = 在那一刻。","tr":{"zh":"会议期间我见到了他的老板。","fr":"J'ai rencontré son patron lors de la réunion.","alt":"J'ai vu son patron pendant la réunion.","note":"lors de 后接名词，不接动词。"}},
 "Bien des": {"pos":"dét. 不定限定词（+ 复数名词）","s":"许多；不少。bien des + 复数名词：bien des gens, bien des fois。比 beaucoup de 书面。不可数名词用 bien du / bien de la：bien du temps, bien de la chance。","ipa":"[bjɛ̃.de]","ph":"bien 读 [bjɛ̃]；des 读 [de]，s 不发。后接元音时连读 [z]：bien des amis [bjɛ̃.de.za.mi]。","pi":"bien des 后名词前不再加 de（不是 bien de gens）；谓语动词用复数。","et":"bien 来自拉丁语 bene（好；引申为「很」）+ des。","ex":[["Une aventure peut revêtir bien des formes.","冒险可以有许多形式。"],["Bien des gens pensent comme toi.","不少人和你想的一样。"],["Je l'ai vu bien des fois.","我见过他很多次。"]],"co":[["bien des fois","很多次"],["bien des gens","很多人"],["bien des années plus tard","很多年之后"],["bien du monde","不少人"]],"sy":[["beaucoup de","courant","很多（口语更常用）"],["de nombreux","soutenu","众多的"],["pas mal de","familier","不少"]],"fq":"中频，偏书面。","me":"bien（很）+ des（若干）= 好些。","tr":{"zh":"他去过好多国家。","fr":"Il a visité bien des pays.","alt":"Il a visité beaucoup de pays.","note":"bien des + 复数名词；口语换 beaucoup de。"}},
 "À deux pas de": {"pos":"loc. prép. 介词短语","s":"离……只有几步远；就在……旁边。表示很近，不一定真的两步：J'habite à deux pas de l'école。单用 à deux pas 也可以。","ipa":"[a.dø.pa.də]","ph":"deux 读 [dø]，x 不发；pas 读 [pa]，s 不发；de 读 [də]。","pi":"deux 和 pas 的结尾辅音都不发；这里的 pas 是「步」，不是否定词。","et":"pas 来自拉丁语 passus（步），与否定词 pas 同源。","ex":[["J'habite à deux pas de l'école.","我住在学校旁边几步远。"],["L'hôtel est à deux pas de la gare.","旅馆离车站只有几步。"],["Le café est à deux pas d'ici.","咖啡馆离这儿很近。"]],"co":[["à deux pas d'ici","离这儿很近"],["à deux pas de chez moi","离我家很近"],["à deux pas de la gare","离车站很近"]],"sy":[["tout près de","courant","很近"],["à proximité de","soutenu","在……附近"],["loin de","courant","反义：远离"]],"fq":"中频，日常常用。","me":"走「两步」就到：two steps = 很近。","tr":{"zh":"面包店离我家很近。","fr":"La boulangerie est à deux pas de chez moi.","alt":"La boulangerie est juste à côté de chez moi.","note":"de + chez moi 不缩合。"}},
 "À la belle étoile": {"pos":"loc. adv. 副词短语","s":"露天（在星空下）；在户外过夜。几乎只与 dormir / passer la nuit 搭配：dormir à la belle étoile = 露宿。étoile 用单数。","ipa":"[a.la.bɛ.le.twal]","ph":"belle 读 [bɛl]，étoile 读 [e.twal]；belle 与 étoile 连读成 [bɛ.le.twal]；oi 读 [wa]。","pi":"belle étoile 要连读；étoile 是阴性，所以用 belle。","et":"étoile 来自拉丁语 stella（星）。这个短语的确切来历不确定，字面意思是「在美丽的星星下」。","ex":[["Nous dormons à la belle étoile.","我们露宿在星空下。"],["En été, j'aime dormir à la belle étoile.","夏天我喜欢露宿。"],["Ils ont passé la nuit à la belle étoile.","他们在户外过了一夜。"]],"co":[["dormir à la belle étoile","露宿"],["passer la nuit à la belle étoile","在户外过夜"],["coucher à la belle étoile","露天睡觉"]],"sy":[["en plein air","courant","户外"],["dehors","courant","外面"],["sous la tente","courant","对比：睡帐篷"]],"fq":"中低频，固定短语。","me":"头顶只有一颗「美丽的星」当屋顶。","tr":{"zh":"夏天我们喜欢露宿。","fr":"L'été, nous aimons dormir à la belle étoile.","alt":"En été, on aime dormir dehors, sous les étoiles.","note":"l'été / en été 都可以表示「夏天」。"}},
 "À mon/ton/son/... niveau": {"pos":"loc. prép. 介词短语（所有格随人称变化）","s":"在我（你、他……）的层面上；凭我的能力或位置。à mon niveau = 在我这个层面；chacun à son niveau = 各人在各人的层面。所有格要与人称一致：à ton niveau, à son niveau, à notre niveau, à leur niveau。","ipa":"[a.mɔ̃.ni.vo]","ph":"mon 读 [mɔ̃]；niveau 读 [ni.vo]，eau 读 [o]。","pi":"所有格要随人称变：mon, ton, son, notre, votre, leur；chacun 搭配 son，不搭配 leur。","et":"niveau 来自古法语 livel（水平仪），源自拉丁语 libella（小天平、水平仪）。","ex":[["On peut tous aider, chacun à notre niveau.","我们每个人都能在自己的层面帮忙。"],["À mon niveau, je ne peux pas décider.","以我的职位，我无法决定。"],["Chacun fait ce qu'il peut à son niveau.","每个人在自己的层面尽力而为。"]],"co":[["chacun à son niveau","各人在各人的层面"],["à mon niveau","以我的能力、在我这个层面"],["à tous les niveaux","在各个层面"],["au niveau de + 名词","在……方面；达到……水平"]],"sy":[["à ma façon","courant","以我的方式"],["à mon échelle","courant","在我的范围内"],["de mon côté","courant","从我这边"]],"fq":"中频，口语和书面都常用。","me":"每个人站在自己的「水平仪」(niveau) 上做事。","tr":{"zh":"每个人都能在自己的层面做点事。","fr":"Chacun peut faire quelque chose à son niveau.","alt":"Chacun peut agir à son échelle.","note":"chacun 配 son；on / nous 配 notre。"}},
 "Au jour le jour": {"pos":"loc. adv. 副词短语","s":"过一天算一天；一天天地。vivre au jour le jour = 不做长远打算；也表示按天处理：gérer au jour le jour。","ipa":"[o.ʒuʁ.lə.ʒuʁ]","ph":"au 读 [o]；jour 读 [ʒuʁ]，j 是 [ʒ]，ou 是 [u]；le 读 [lə]。","pi":"两个 jour 都用单数，固定短语；ou 读 [u]，不是 [o]。","et":"jour 来自晚期拉丁语 diurnum（日）；重复 jour 表示「一天接一天」。","ex":[["Je vis au jour le jour.","我过一天算一天。"],["On gère la situation au jour le jour.","我们走一步看一步地处理局面。"],["Ils vivent au jour le jour, sans projet.","他们过一天算一天，没有计划。"]],"co":[["vivre au jour le jour","过一天算一天"],["gérer au jour le jour","按天处理"],["prendre la vie au jour le jour","过一天算一天"]],"sy":[["jour après jour","courant","日复一日"],["sans rien prévoir","courant","不做计划"],["à long terme","courant","反义：长期"]],"fq":"中频，日常常用。","me":"「日(jour)接日(jour)」，只看今天。","tr":{"zh":"我什么都不计划，过一天算一天。","fr":"Je ne prévois rien, je vis au jour le jour.","alt":"Je ne fais pas de projets, je vis au jour le jour.","note":"否定后 pas de + 名词，不用冠词。"}},
 "Au tournant de": {"pos":"loc. prép. 介词短语","s":"在……之交；在……的转折点。au tournant du siècle = 世纪之交；au tournant des années 2000 = 2000 年代之交。也指道路的转弯处：au tournant de la route。","ipa":"[o.tuʁ.nɑ̃.də]","ph":"au 读 [o]；tournant 读 [tuʁ.nɑ̃]，t 不发；de 读 [də]。","pi":"后接 le / les 时要缩合：au tournant du siècle、au tournant des années；-ant 读 [ɑ̃]。","et":"tournant 是动词 tourner（拉丁语 tornare，「车削」）的现在分词，作名词。同源：tour, détour。","ex":[["Au tournant des années 2000, la musique pop était très populaire.","二十一世纪之交，流行音乐很火。"],["Il y a eu un grand changement au tournant du siècle.","世纪之交发生了很大的变化。"],["La maison est au tournant de la route.","房子在路的拐弯处。"]],"co":[["au tournant du siècle","世纪之交"],["au tournant de l'histoire","历史转折点"],["un tournant décisif","关键转折"]],"sy":[["à la charnière de","soutenu","处在……的交界点"],["à l'aube de","soutenu","在……的开端"],["vers","courant","大约在……时候"]],"fq":"中频，偏书面、新闻。","me":"tournant = 拐弯处：时代在这里「拐了个弯」。","tr":{"zh":"世纪之交，一切都变了。","fr":"Au tournant du siècle, tout a changé.","alt":"Vers l'an 2000, tout a changé.","note":"au + tournant du 是固定缩合：de + le = du。"}},
 "Avoir le vent en poupe": {"pos":"loc. verb. 动词短语（avoir 变位）","s":"顺风顺水；势头正旺。来自航海：vent en poupe = 从船尾吹来的顺风，让船走得快。用于人、公司、潮流：Cette entreprise a le vent en poupe。","ipa":"[a.vwaʁ.lə.vɑ̃.ɑ̃.pup]","ph":"vent 读 [vɑ̃]，t 不发；en 读 [ɑ̃]；poupe 读 [pup]，ou 是 [u]，e 不发。","pi":"poupe（船尾）读 [pup]，不是 [pop]；vent 和 en 之间不连读。","et":"poupe 来自拉丁语 puppis（船尾）。航海比喻：风从船尾吹来，船走得更快。","ex":[["Cette entreprise a le vent en poupe.","这家公司势头正旺。"],["Ce chanteur a le vent en poupe.","这位歌手正当红。"],["Le vélo électrique a le vent en poupe.","电动自行车现在很火。"]],"co":[["avoir le vent en poupe","顺风顺水"],["avoir le vent en poupe en ce moment","现在正红火"],["avoir le vent en poupe grâce à + 名词","靠……走红"]],"sy":[["être en pleine ascension","courant","正处在上升期"],["avoir la cote","familier","很受欢迎"],["être à la mode","courant","流行"]],"fq":"中频，新闻中常见。","me":"想象风从船「后面」推着你走。","tr":{"zh":"电动自行车现在很火。","fr":"Le vélo électrique a le vent en poupe.","alt":"Le vélo électrique est très à la mode en ce moment.","note":"主语多是事物、公司或人，短语固定不变。"}},
 "En référence à": {"pos":"loc. prép. 介词短语","s":"参照……；就……而言；指的是……。en référence à ce livre = 参照那本书。书信、邮件中常用：En référence à votre message du 5 mars, …","ipa":"[ɑ̃.ʁe.fe.ʁɑ̃s.a]","ph":"en 读 [ɑ̃]；référence 读 [ʁe.fe.ʁɑ̃s]，-ence 读 [ɑ̃s]；à 读 [a]。","pi":"-ence 读 [ɑ̃s]，不是 [ɛ̃s]；拼写是 référence，一个 f、两个 r。","et":"référence 来自动词 référer（拉丁语 referre，「带回、提及」）。同源：se référer à, référent。","ex":[["Il parle en référence à ce livre.","他是参照那本书说的。"],["En référence à votre mail, voici ma réponse.","关于您的邮件，这是我的答复。"],["Le titre est écrit en référence à un film célèbre.","这个标题是向一部名片致意。"]],"co":[["faire référence à + 名词","提到、指的是"],["en référence à votre message","关于您的来信"],["se référer à","参考、查阅"],["un ouvrage de référence","参考书"]],"sy":[["par rapport à","courant","相对于；关于"],["à propos de","courant","关于"],["au sujet de","courant","就……而言"]],"fq":"中频，偏书面、公文。","me":"référence 里有 refer（英语）：refer to = en référence à。","tr":{"zh":"关于你昨天的问题，我来回答。","fr":"En référence à ta question d'hier, voici ma réponse.","alt":"Pour répondre à ta question d'hier, voici ma réponse.","note":"en référence à 偏书面；口语常用 pour répondre à。"}},
 "Histoire de": {"pos":"loc. conj. 连词短语（+ 动词原形，口语）","s":"只是为了……；就为了（随便做点什么）。语气随意：Je sors, histoire de prendre l'air。histoire de + 动词原形，表示不那么重要的目的。","ipa":"[is.twaʁ.də]","ph":"h 不发音；histoire 读 [is.twaʁ]，oi 读 [wa]；de 读 [də]。","pi":"h 不发音；这个用法口语，后面接动词原形，不接名词。","et":"histoire 来自拉丁语 historia（历史、叙述）。这个口语用法的具体演变过程来源不确定。","ex":[["Je sors, histoire de prendre un peu l'air.","我出去只是为了透透气。"],["Je t'appelle, histoire de prendre des nouvelles.","我给你打电话，就是问问近况。"],["Il a mis un pull, histoire de ne pas avoir froid.","他穿了件毛衣，免得冷。"]],"co":[["histoire de + 原形","只是为了……"],["histoire de rire","图个乐"],["histoire de voir","只是看看"]],"sy":[["pour","courant","为了（最常用）"],["afin de","soutenu","为了"],["juste pour","courant","只是为了"]],"fq":"中频，口语常用。","me":"「随便讲个 histoire」般随意：只是找个由头。","tr":{"zh":"我去看看他，就是想问个好。","fr":"Je vais le voir, histoire de dire bonjour.","alt":"Je passe le voir, juste pour lui dire bonjour.","note":"histoire de 后接动词原形。"}},
 "Joindre l'utile à l'agréable": {"pos":"loc. verb. 动词短语（joindre 第三组：je joins, nous joignons；过去分词 joint）","s":"既做有用的事，又享受乐趣；一举两得。比如出差顺便旅游，边玩边学。固定习语，utile 与 agréable 前都带 l'。","ipa":"[ʒwɛ̃dʁ.ly.ti.la.la.gʁe.abl]","ph":"joindre 读 [ʒwɛ̃dʁ]，oin 是 [wɛ̃]，d 要发；l'utile à 连读成 [ly.ti.la]；agréable 读 [a.gʁe.abl]。","pi":"joindre 的变位容易错：je joins, il joint, nous joignons；oin 读 [wɛ̃]；l'utile à l'agréable 有两次省音。","et":"joindre 来自拉丁语 jungere（连接）；utile 来自 utilis；agréable 来自 agréer。字面「把有用的和愉快的连起来」。同源：jonction, conjoint, joint。","ex":[["Il faut joindre l'utile à l'agréable.","应该把实用与愉快结合起来。"],["Il apprend le français en regardant des films : il joint l'utile à l'agréable.","他看电影学法语：寓学于乐。"]],"co":[["joindre l'utile à l'agréable","一举两得"],["joindre qqn par téléphone","打电话联系到某人"],["joindre un fichier","附上文件"],["joindre les deux bouts","勉强维持生计"]],"sy":[["faire d'une pierre deux coups","courant","一举两得"],["allier travail et plaisir","courant","工作与乐趣结合"]],"fq":"中低频，固定习语。","me":"把 utile（有用）和 agréable（愉快）「连」(joindre) 在一起。","tr":{"zh":"我边听歌边学法语，一举两得。","fr":"J'apprends le français en écoutant des chansons : je joins l'utile à l'agréable.","alt":"J'écoute des chansons pour apprendre le français : ça fait d'une pierre deux coups.","note":"faire d'une pierre deux coups 更口语。"}},
 "La nuit des temps": {"pos":"loc. nom. 名词短语，阴性（la nuit des temps）","s":"远古；太古时代。几乎只用在 depuis la nuit des temps（自古以来）、remonter à la nuit des temps（追溯到远古），夸张地表示「久远得没人记得」。","ipa":"[la.nɥi.de.tɑ̃]","ph":"nuit 读 [nɥi]；des 读 [de]，s 不发；temps 读 [tɑ̃]，p、s 都不发。","pi":"temps 的 ps 不发音；nuit 里的 ui 是半元音 [ɥi]，不是 [nwi]。","et":"nuit 来自拉丁语 noctem；temps 来自拉丁语 tempus。字面「时间之夜」：古老到像沉入黑夜。","ex":[["Cela existe depuis la nuit des temps.","从远古时代就存在。"],["Cette légende remonte à la nuit des temps.","这个传说可以追溯到远古。"],["Les hommes regardent les étoiles depuis la nuit des temps.","人类自古以来就仰望星空。"]],"co":[["depuis la nuit des temps","自古以来"],["remonter à la nuit des temps","追溯到远古"],["de tout temps","自古以来"]],"sy":[["de tout temps","soutenu","自古以来"],["depuis toujours","courant","一直以来"],["depuis des siècles","courant","好几个世纪以来"]],"fq":"中低频，固定短语。","me":"时间的「黑夜」：古老到看不清起点。","tr":{"zh":"人类自古以来就在讲故事。","fr":"Les humains racontent des histoires depuis la nuit des temps.","alt":"Les gens racontent des histoires depuis toujours.","note":"depuis + 时间，动词用现在时。"}},
 "Pour ou contre ?": {"pos":"loc. 固定问句；pour 介词，contre 介词/副词","s":"赞成还是反对？Es-tu pour ou contre ? 直接问立场。pour / contre 可单独作答：Je suis pour. / Je suis contre. 名词：le pour et le contre = 利与弊。","ipa":"[pu.ʁu.kɔ̃tʁ]","ph":"pour 读 [puʁ]，与 ou 连读成 [pu.ʁu]；contre 读 [kɔ̃tʁ]，on 是鼻化 [ɔ̃]，词尾 e 不发。","pi":"pour ou 要连读成 [pu.ʁu]；contre 的 on 是 [ɔ̃]，不是 [ɔn]。","et":"pour 来自拉丁语 pro（为了、支持）；contre 来自拉丁语 contra（相对、反对）。","ex":[["Es-tu pour ou contre cette idée ?","你赞成还是反对这个主意？"],["Vous êtes pour ou contre ? Moi, je suis pour.","您赞成还是反对？我赞成。"],["Je suis pour, mais ma sœur est contre.","我赞成，但我姐姐反对。"]],"co":[["être pour / être contre","赞成 / 反对"],["le pour et le contre","利弊"],["peser le pour et le contre","权衡利弊"],["voter pour / contre","投赞成 / 反对票"]],"sy":[["d'accord ou pas d'accord","courant","同意还是不同意"],["favorable ou opposé","soutenu","赞成还是反对"],["partant","familier","愿意参加的（Je suis partant）"]],"fq":"高频，讨论时常用。","me":"pour = 站在这一边；contre = 站在对面。","tr":{"zh":"你支持还是反对这个计划？","fr":"Tu es pour ou contre ce projet ?","alt":"T'es pour ou t'es contre ce projet ?","note":"pour / contre 后可直接接名词。"}},
 "Rien que": {"pos":"loc. adv. 副词短语","s":"仅仅；光是……就……。rien que + 名词 / 动词原形：Rien que prendre l'avion une fois pollue déjà beaucoup。也表示「只有」：rien que la vérité。Rien que ça ! 常是反话，意为「就这么点要求啊！」。","ipa":"[ʁjɛ̃.kə]","ph":"rien 读 [ʁjɛ̃]，ien 是 [jɛ̃]；que 读 [kə]。","pi":"ien 读 [jɛ̃]；这里的 rien 不表示否定，句中不需要 ne。","et":"rien 来自拉丁语 rem（res「事物」的宾格）；que 表示「只」；字面「没有别的事物，只有……」。","ex":[["Rien que prendre l'avion une fois pollue déjà beaucoup.","光是坐一次飞机就已经污染很多。"],["Rien que d'y penser, j'ai peur.","光是想想我就害怕。"],["Rien que ce sac coûte deux cents euros.","光这个包就要两百欧元。"]],"co":[["rien que pour toi","就为了你"],["rien que ça !","光这个就……（常是反话）"],["rien que la vérité","只有真相"],["rien que d'y penser","光是想想"]],"sy":[["seulement","courant","只是"],["uniquement","courant","仅仅"],["juste","courant","只是、刚好"]],"fq":"中高频，口语常用。","me":"「什么(rien)都不多，只有(que)」……","tr":{"zh":"光是这个价格就让我害怕。","fr":"Rien que le prix me fait peur.","alt":"Le prix seul me fait peur.","note":"rien que 放在被强调的成分前。"}},
 "Sans oublier que": {"pos":"loc. conj. 连词短语（+ 陈述句）","s":"更不用说……；别忘了……。用来补充一个额外的理由：Sans oublier que nous devons partir tôt。后接名词时说 sans oublier + 名词。","ipa":"[sɑ̃.zu.bli.je.kə]","ph":"sans 读 [sɑ̃]，s 与 oublier 连读成 [z]；oublier 读 [u.bli.je]；que 读 [kə]。","pi":"sans 在 oublier 前要连读 [z]；que 后接直陈式（nous devons），不用虚拟式。","et":"sans（没有）+ oublier + que；oublier 来自晚期拉丁语 oblitare。","ex":[["Sans oublier que nous devons partir tôt.","更不用说我们得早点出发。"],["Il est gentil, sans oublier qu'il est très drôle.","他人很好，而且还很有趣。"],["C'est cher, sans oublier que c'est loin.","又贵，更别说还很远。"]],"co":[["sans oublier que + 句子","更不用说……"],["sans oublier + 名词","还有……"],["sans compter que","再说……"],["sans parler de + 名词","更别提……"]],"sy":[["sans compter que","courant","再说"],["d'autant plus que","soutenu","尤其因为"],["et puis","familier","再说了"]],"fq":"中频，论述和说话中常用。","me":"sans oublier = 「别忘了」，再补一个理由。","tr":{"zh":"这家餐厅很好吃，更不用说它很便宜。","fr":"Ce restaurant est très bon, sans oublier qu'il est bon marché.","alt":"Ce restaurant est très bon, et en plus il n'est pas cher.","note":"bon marché 是不变形的固定形容词。"}},
 "Tous les 36 du mois": {"pos":"loc. adv. 副词短语（诙谐固定说法）","s":"极少；难得一次。字面「每个月的 36 号」，但一个月没有 36 号，所以 = 几乎从不。也写作 tous les trente-six du mois。语气诙谐，偏口语。","ipa":"[tu.le.tʁɑ̃t.si.dy.mwa]","ph":"tous 在这里读 [tu]，s 不发；trente-six 里的 six 在辅音前读 [si]；mois 读 [mwa]，s 不发。","pi":"这是玩笑话，别当真；别与 tous les jours（每天）混淆。","et":"来源不确定。这是诙谐夸张：一个月最多 31 天，36 号根本不存在，借此表示「几乎不会发生」。","ex":[["Il vient me voir tous les 36 du mois.","他很少来看我。"],["On se voit tous les 36 du mois, c'est dommage.","我们很少见面，真可惜。"],["Elle écrit tous les 36 du mois.","她很少写信。"]],"co":[["tous les 36 du mois","极少"],["tous les quatre matins","非常频繁（反义）"],["une fois par an","一年一次"],["rarement","很少"]],"sy":[["rarement","courant","很少"],["de temps en temps","courant","偶尔"],["tous les quatre matins","familier","反义：动不动就"]],"fq":"低频，口语、诙谐。","me":"月历上根本没有 36 号：所以几乎不会发生。","tr":{"zh":"我哥哥很少给我打电话。","fr":"Mon frère m'appelle tous les 36 du mois.","alt":"Mon frère m'appelle très rarement.","note":"诙谐口语；正式场合用 rarement。"}},
 "Une floppée de": {"pos":"loc. 名词短语，阴性（une floppée de + 名词）","s":"一大堆；一大群。口语，数量很多：une floppée de gens / de questions。更常见的拼写是 une flopée（一个 p），floppée 是少见的写法。de 后接名词，不加冠词。","ipa":"[yn.flɔ.pe.də]","ph":"une 读 [yn]；flo 读 [flɔ]；pée 读 [pe]；de 读 [də]。","pi":"常规拼写是 flopée，双 p 较少见；这个词很口语，写作文时慎用。","et":"来源不确定（口语词）。","ex":[["Il y a une floppée de gens ici.","这里有一大群人。"],["J'ai une floppée de questions.","我有一大堆问题。"],["Il a une floppée de copains.","他有一大帮朋友。"]],"co":[["une floppée de gens","一大群人"],["une floppée de questions","一大堆问题"],["une floppée d'amis","一大帮朋友"]],"sy":[["un tas de","familier","一大堆"],["plein de","familier","很多"],["beaucoup de","courant","很多（中性）"]],"fq":"低频，口语。","me":"想象一大堆东西「啪啦」一下全倒出来。","tr":{"zh":"他有一大堆朋友。","fr":"Il a une floppée d'amis.","alt":"Il a plein d'amis.","note":"une floppée de + 名词，de 后不加冠词。"}},
 "Voir du pays": {"pos":"loc. verb. 动词短语（voir 第三组：je vois, nous voyons）","s":"见世面；到处走走；去很多地方。强调通过旅行了解不同地方：J'aime voyager pour voir du pays。du 是部分冠词，固定不变。","ipa":"[vwaʁ.dy.pe.i]","ph":"voir 读 [vwaʁ]；du 读 [dy]；pays 读两个音节 [pe.i]。","pi":"pays 是两个音节 [pe.i]，不是 [pe]；du 里的 u 读 [y]。","et":"voir 来自拉丁语 videre；pays 来自晚期拉丁语 pagensis（乡野、地区），源自 pagus（乡村）。","ex":[["J'aime voyager pour voir du pays.","我喜欢旅行去见世面。"],["Il a beaucoup voyagé, il a vu du pays.","他走过很多地方，见多识广。"],["Les jeunes veulent voir du pays avant de travailler.","年轻人想在工作前先去见见世面。"]],"co":[["voir du pays","见世面"],["voir du monde","多接触人"],["avoir vu du pays","见多识广"]],"sy":[["voyager","courant","旅行"],["parcourir le monde","courant","走遍世界"],["rester chez soi","courant","反义：待在家"]],"fq":"中低频，口语。","me":"看（voir）「一块 pays（地方）」。","tr":{"zh":"我想趁年轻多见见世面。","fr":"Je veux voir du pays pendant que je suis jeune.","alt":"Je veux voyager et voir du pays tant que je suis jeune.","note":"pendant que / tant que 后接直陈式。"}},
 "Dieu (avec un D majuscule et pas d'article)": {"pos":"n.m. 阳性名词，大写 Dieu（不加冠词）；复数 dieux（众神），阴性 déesse","s":"上帝（一神教的神，大写，不加冠词）。小写 un dieu / des dieux = 某个神、众神。常见感叹：Mon Dieu !（天哪）、Dieu merci（谢天谢地）。","ipa":"[djø]","ph":"d + ieu 读 [djø]，单音节；ieu 的嘴唇要圆。","pi":"ieu 读 [jø]，不是 [ju]；表示「上帝」时大写 D 且常不加冠词；复数 dieux 的 x 不发音。","et":"拉丁语 deus（神）。同源：divin, adieu（字面「交托给神」）。","ex":[["Les fidèles prient Dieu dans ce lieu de culte.","信徒们在这个礼拜场所祈祷上帝。"],["Mon Dieu, quelle surprise !","天哪，真是个惊喜！"],["Les Grecs avaient beaucoup de dieux.","古希腊人有很多神。"]],"co":[["Mon Dieu !","天哪！"],["Dieu merci","谢天谢地"],["Dieu sait…","天知道……"],["croire en Dieu","信上帝"]],"sy":[["Seigneur","soutenu","主（宗教语境）"],["le Créateur","littéraire","造物主"],["divinité","soutenu","神灵"]],"fq":"中频，宗教和感叹语中常见。","me":"adieu = à + Dieu：告别时「交给上帝」。","tr":{"zh":"谢天谢地，你没事！","fr":"Dieu merci, tu vas bien !","alt":"Heureusement que tu n'as rien !","note":"Dieu merci 是固定表达。"}},
 "Du gaz": {"pos":"n.m. 阳性名词，单复数同形 gaz","s":"气体；天然气；煤气。du gaz = 一些天然气（部分冠词）。le gaz naturel（天然气）、le gaz carbonique（二氧化碳）、une cuisinière à gaz（煤气灶）。","ipa":"[gaz]","ph":"g 在 a 前读 [g]；结尾 z 要读出来 [z]。","pi":"复数仍是 gaz（不加 s）；结尾 z 要发音，不像很多词尾辅音不发；du 是部分冠词。","et":"17 世纪由荷兰化学家范·赫尔蒙特（Van Helmont）根据希腊语 khaos（混沌）造出。","ex":[["Cette maison est chauffée avec du gaz naturel.","这栋房子用天然气取暖。"],["Il faut fermer le gaz.","要把煤气关上。"],["La facture de gaz a augmenté.","煤气费涨了。"]],"co":[["le gaz naturel","天然气"],["une cuisinière à gaz","煤气灶"],["fermer le gaz","关煤气"],["une bouteille de gaz","煤气罐"]],"sy":[["vapeur","courant","蒸汽（不是 gaz）"],["pétrole","courant","石油"]],"fq":"高频，日常和新闻常用。","me":"gaz 末尾的 z 要发：像漏气的「嘶——」。","tr":{"zh":"出门前别忘了关煤气。","fr":"N'oublie pas de fermer le gaz avant de partir.","alt":"Pense à couper le gaz avant de sortir.","note":"oublier de + 动词原形；penser à + 动词原形。"}},
 "Du pétrole": {"pos":"n.m. 阳性名词，复数 pétroles","s":"石油；原油。du pétrole = 一些石油（部分冠词）。le pétrole brut（原油）、un puits de pétrole（油井）、un pays producteur de pétrole（产油国）。注意：汽油是 l'essence，不是 pétrole。","ipa":"[pe.tʁɔl]","ph":"é 读 [e]；tr 读 [tʁ]；o 读开口 [ɔ]；结尾 l 要发；e 不发。","pi":"汽油是 l'essence，不是 pétrole；-trole 的 o 读 [ɔ]，不是 [o]。","et":"中世纪拉丁语 petroleum，由 petra（石）+ oleum（油）构成，字面「岩石之油」。同源：pétrolier（油轮）, pierre, huile。","ex":[["Le prix du pétrole a augmenté cette année.","今年石油价格上涨。"],["Ce pays produit beaucoup de pétrole.","这个国家产很多石油。"],["Le pétrole est vendu en barils.","石油按桶出售。"]],"co":[["le prix du pétrole","石油价格"],["un puits de pétrole","油井"],["le pétrole brut","原油"],["une compagnie pétrolière","石油公司"]],"sy":[["or noir","littéraire","黑金（石油的美称）"],["essence","courant","汽油（精炼后的燃料）"],["gasoil","courant","柴油"]],"fq":"高频，新闻常用。","me":"pétr-（石）+ -ole（油）：从岩石里出来的油。","tr":{"zh":"石油价格涨得很快。","fr":"Le prix du pétrole monte très vite.","alt":"Le pétrole devient de plus en plus cher.","note":"prix du pétrole：du = de + le。"}},
 "Du/Le capital": {"pos":"n.m. 阳性名词，复数多用 capitaux（资金）","s":"资本；本金；财富。le capital d'une entreprise（公司资本）；investir son capital（投资本金）。引申：le capital santé（健康资本）、le capital humain（人力资本）。注意：capital 作形容词 = 至关重要的；la capitale = 首都。","ipa":"[ka.pi.tal]","ph":"c 在 a 前读 [k]；结尾 l 要发；复数 capitaux 读 [ka.pi.to]。","pi":"阳性 le capital（资本）≠ 阴性 la capitale（首都）；复数 -aux 读 [o]。","et":"晚期拉丁语 capitalis（主要的），源自 caput（头）。同源：chef, capitale, capitaine。","ex":[["Il est riche, il a un gros capital.","他很富有，资本雄厚。"],["Il a investi tout son capital dans son restaurant.","他把全部本金都投进了他的餐厅。"],["Elle prend soin de son capital santé.","她很注意保护自己的健康本钱。"]],"co":[["le capital d'une entreprise","公司资本"],["investir un capital","投资本金"],["les capitaux étrangers","外资"],["le capital humain","人力资本"]],"sy":[["fonds","courant","资金"],["patrimoine","soutenu","财产、遗产"],["argent","courant","钱（最口语）"]],"fq":"中频，经济、新闻常用。","me":"capital ← caput（头）：「头号」的钱，本金。","tr":{"zh":"他把全部资本都投进了这家店。","fr":"Il a investi tout son capital dans ce magasin.","alt":"Il a mis toutes ses économies dans cette boutique.","note":"investir … dans + 名词。"}},
 "L'apprentissage": {"pos":"n.m. 阳性名词，复数 apprentissages","s":"学习（掌握一门技能）；学徒期、学徒制。l'apprentissage d'une langue（语言学习）；un contrat d'apprentissage（学徒合同）；être en apprentissage（在做学徒）。比 étude 更强调「学会做」。","ipa":"[a.pʁɑ̃.ti.saʒ]","ph":"pp 只读一个 [p]；en 读 [ɑ̃]；ss 读 [s]；-age 读 [aʒ]。去掉 l' 后单词以 a 开头。","pi":"pp 只发一个 [p]；-tissage 里 ti 读 [ti]，不是 [si]；-age 的 g 读 [ʒ]。","et":"由 apprenti（学徒）加后缀构成；apprenti 源自古法语 aprentis，来自 apprendre。同源：apprendre, apprenti。","ex":[["L'apprentissage d'un métier commence dès les premiers cours pratiques.","学一门手艺从最初的实践课开始。"],["L'apprentissage du français prend du temps.","学法语需要时间。"],["Il fait un apprentissage de cuisinier.","他在当厨师学徒。"]],"co":[["l'apprentissage d'une langue","语言学习"],["un contrat d'apprentissage","学徒合同"],["être en apprentissage","在做学徒"],["faire son apprentissage","学艺、打基础"]],"sy":[["formation","courant","培训、教育"],["étude","courant","学习、研究"],["enseignement","courant","教学（老师的角度）"]],"fq":"中频，教育、职场常见。","me":"apprendre → apprenti → apprentissage：学徒学艺的过程。","tr":{"zh":"学语言需要耐心。","fr":"L'apprentissage d'une langue demande de la patience.","alt":"Apprendre une langue demande de la patience.","note":"l'apprentissage de + 名词；apprendre + 原形可替代。"}},
 "L'encadrement": {"pos":"n.m. 阳性名词，复数 encadrements","s":"（对学生、员工的）指导与管理；也指「编制的管理人员、师资」，还可指给画装框。la qualité de l'encadrement = 指导/师资的质量。","ipa":"[ɑ̃.kadʁ.mɑ̃]","ph":"en [ɑ̃]；c 在 a 前读 [k]；-ment 读鼻化 [mɑ̃]，t 不发音。","pi":"en 和 an 都读 [ɑ̃]；结尾 -ment 不发 t；注意 dr 连读 [dʁ]。","et":"来自 encadrer（en- + cadre 框架）加后缀 -ement。cadre 来自意大利语 quadro。","ex":[["L'encadrement des étudiants est assuré par des tuteurs.","学生的指导由导师负责。"],["Les enfants ont besoin d'un bon encadrement.","孩子们需要好的看管与引导。"]],"co":[["l'encadrement pédagogique","教学指导"],["le taux d'encadrement","师生比 / 管理人员比例"],["l'encadrement des loyers","房租管制"]],"sy":[["suivi","courant","跟进、辅导"],["supervision","soutenu","监督（较书面）"],["direction","courant","领导、管理"]],"fq":"中高频，教育与职场常用。","me":"en + cadre：把人放进一个「框架」里管着、带着。","tr":{"zh":"这所学校对新生的指导很好。","fr":"Cette école offre un bon encadrement aux nouveaux étudiants.","alt":"Dans cette école, les nouveaux sont bien encadrés.","note":"动词 encadrer 的被动：être bien encadré = 被很好地带领。"}},
 "L'enseignement supérieur": {"pos":"n.m. 阳性名词词组（enseignement 阳性），无复数用法","s":"高等教育，指大学、大学校（grandes écoles）、BTS 等高中毕业以后的所有教育。enseignement 单独用时是「教学；教育」。","ipa":"[ɑ̃.sɛɲ.mɑ̃ sy.pe.ʁjœʁ]","ph":"ei 读 [ɛ]，gn 读 [ɲ]；supérieur 里 eu 读 [œ]，结尾 r 要发。","pi":"enseignement 里 g 不发 [g]，是 [ɲ]；supérieur 结尾 -eur 读 [œʁ]，r 不能丢。","et":"enseigner 来自拉丁语 insignare（做标记、教），加 -ement；supérieur 来自拉丁语 superior（更高的）。","ex":[["Elle souhaite poursuivre ses études dans l'enseignement supérieur.","她想继续读高等教育。"],["L'enseignement supérieur est en pleine évolution.","高等教育正在快速变化。"]],"co":[["faire des études dans le supérieur","上大学 / 读高等院校"],["un établissement d'enseignement supérieur","高等院校"],["l'enseignement supérieur et la recherche","高等教育与科研"]],"sy":[["les études supérieures","courant","高等学业"],["l'université","courant","大学（只是高等教育的一种）"],["le supérieur","familier","上大学（口语简称）"]],"fq":"中高频，新闻、学校话题常见。","me":"enseigner + 「更高的」：高中之上的教学。","tr":{"zh":"在法国，高等教育的学费不高。","fr":"En France, l'enseignement supérieur ne coûte pas très cher.","alt":"En France, les études supérieures sont assez peu chères.","note":"ne… pas très cher：不太贵；coûter 表示「花费」。"}},
 "Le baccalauréat (le bac)": {"pos":"n.m. 阳性名词，复数 baccalauréats；缩写 bac，复数 bacs","s":"法国高中毕业会考，通过后可进大学，是中学的最后一个文凭。口语几乎都说 le bac。passer le bac = 参加会考；avoir son bac = 通过了。","ipa":"[ba.ka.lɔ.ʁe.a]","ph":"cc 在 a 前是 [k]（不是 [ks]）；au 读 [ɔ]；éa 分开读 [e.a]。bac 读 [bak]，c 要发音。","pi":"bac 的 c 要发 [k]，别像 un banc 那样读鼻音；拼写有两个 c，一个 l。","et":"来自中世纪拉丁语 baccalaureatus，与 bachelier（学士）同源。","ex":[["Il a révisé toute l'année pour réussir le bac.","他复习了一整年，为了通过会考。"],["Elle a eu son bac avec mention bien.","她会考得了良（mention bien）。"]],"co":[["passer le bac","参加会考"],["avoir / réussir son bac","通过会考"],["un bac pro / un bac général","职业会考 / 普通会考"],["rater son bac","会考没过"]],"sy":[["le bachot","familier","bac 的旧口语说法"],["le diplôme","courant","文凭（泛指）"]],"fq":"高频，法国教育中必学词。","me":"bac 读 [bak]，像「巴克」，别和 banc（长凳）混。","tr":{"zh":"她明年要参加会考。","fr":"Elle passe le bac l'année prochaine.","alt":"L'année prochaine, elle a son bac à passer.","note":"passer le bac = 参加考试，不等于通过；通过用 réussir / avoir。"}},
 "Le communautarisme": {"pos":"n.m. 阳性名词，复数 communautarismes","s":"社群主义。在法语里常带贬义：指人们只认自己的族群、宗教等小团体，不愿融入整个社会。和法国共和国「大家都是公民」的理念相对。","ipa":"[kɔ.my.no.ta.ʁism]","ph":"每个 o 和 u 分开读：co [kɔ]，mu [my]；-isme 读 [ism]，e 不发音。","pi":"u 读 [y]（嘴唇圆、发 i 的音），不是 [u]；词很长，按 co-mu-nau-ta-ris-me 分音节。","et":"communauté（共同体，来自拉丁语 communitas）+ -isme。","ex":[["L'école républicaine cherche à éviter le communautarisme.","共和制学校努力避免社群分裂。"],["Certains politiques dénoncent le communautarisme.","有些政客批评社群主义。"]],"co":[["lutter contre le communautarisme","反对社群主义"],["un risque de communautarisme","社群分裂的风险"],["le communautarisme religieux","宗教社群主义"]],"sy":[["le repli identitaire","soutenu","缩回自己的身份圈子"],["le séparatisme","courant","分离主义"],["l'universalisme","soutenu","反义：普遍主义"]],"fq":"中频，政治、新闻、社会话题。","me":"communauté + isme：把「小圈子」放在第一位。","tr":{"zh":"有人担心社群主义会分裂社会。","fr":"Certains craignent que le communautarisme divise la société.","alt":"Certains ont peur du communautarisme, qui divise la société.","note":"craindre que + 虚拟式（subjonctif）：divise 虚拟式与直陈式同形。"}},
 "Le décrochage scolaire": {"pos":"n.m. 阳性名词词组，复数 décrochages scolaires","s":"辍学；中途放弃学业。指学生没拿到文凭就离开学校，或严重跟不上。décrocher 本义是「取下、摘下」。","ipa":"[de.kʁɔ.ʃaʒ skɔ.lɛʁ]","ph":"ch 读 [ʃ]；-age 读 [aʒ]；scolaire 里 sc 读 [sk]，-aire 读 [ɛʁ]。","pi":"ch 读 [ʃ]，不是 [k]；décrochage 里 é 读 [e]，不要读成 [ɛ]。","et":"décrocher（dé- 去掉 + croc 钩子）+ -age，本义是「从钩子上取下」，后来用于「脱离」。scolaire 来自拉丁语 scholaris。","ex":[["Le lycée met en place des aides contre le décrochage scolaire.","高中采取措施防止辍学。"],["Le décrochage scolaire touche surtout les adolescents.","辍学主要影响青少年。"]],"co":[["lutter contre le décrochage scolaire","防止辍学"],["un élève en décrochage","快要辍学的学生"],["un taux de décrochage","辍学率"]],"sy":[["l'abandon scolaire","courant","放弃学业"],["l'échec scolaire","courant","学业失败（不一定离校）"]],"fq":"中频，教育新闻中常见。","me":"décrocher = 摘下挂钩：学生从学校「掉线」。","tr":{"zh":"老师想帮助那个快要辍学的学生。","fr":"Le professeur veut aider l'élève en décrochage scolaire.","alt":"Le prof veut aider l'élève qui est en train de décrocher.","note":"décrocher 也可单独使用，意思是「脱离、掉队」。"}},
 "Le marché du travail": {"pos":"n.m. 阳性名词词组，复数 marchés du travail","s":"劳动力市场；就业市场。指所有求职者与招聘岗位的整体情况。entrer / arriver sur le marché du travail = 开始进入职场。","ipa":"[maʁ.ʃe dy tʁa.vaj]","ph":"ch 读 [ʃ]；marché 结尾 é 读 [e]；travail 里 -ail 读 [aj]，l 不单独发。","pi":"travail 的 ail 读 [aj]，不要读成 [ail] 或 [al]；marché 的 t 不存在，是 ch。","et":"marché 来自拉丁语 mercatus（集市）；travail 来源有争议，一般认为来自后期拉丁语 tripalium（一种刑具），但不完全确定。","ex":[["Les jeunes diplômés cherchent à s'insérer sur le marché du travail.","应届毕业生想进入就业市场。"],["Le marché du travail est difficile en ce moment.","现在就业市场不好。"]],"co":[["arriver sur le marché du travail","进入就业市场"],["s'insérer sur le marché du travail","融入就业市场"],["un marché du travail tendu","就业形势紧张"]],"sy":[["l'emploi","courant","就业；工作岗位"],["le monde du travail","courant","职场世界"]],"fq":"高频，经济、求职话题。","me":"marché（集市）+ travail（工作）：「工作」摆在集市上买卖。","tr":{"zh":"找第一份工作在这里不容易。","fr":"Trouver un premier emploi n'est pas facile sur le marché du travail.","alt":"Pour un premier job, le marché du travail est compliqué.","note":"不定式 Trouver… 可作句子的主语。"}},
 "Le savoir-être": {"pos":"n.m. 阳性名词，复数不变 des savoir-être","s":"软技能；待人接物的素养，如礼貌、守时、合作、沟通。和 le savoir-faire（技能）、le savoir（知识）并列。常用于招聘和教育。","ipa":"[sa.vwaʁ ɛtʁ]","ph":"savoir 里 oi 读 [wa]；être 里 ê 读 [ɛ]，结尾 -tre 读 [tʁ]。","pi":"oi 读 [wa]；être 的 ê 是开口 [ɛ]，不是 [e]；注意连字符，写成 savoir-être。","et":"仿照 savoir-faire 造出来的新词，由动词 savoir（知道）和 être（是、存在）组成。","ex":[["Le savoir-être en entreprise est aussi important que les compétences techniques.","职场里的软技能和技术能力一样重要。"],["Le recruteur évalue aussi le savoir-être du candidat.","招聘人员也会评估应聘者的软技能。"]],"co":[["le savoir, le savoir-faire et le savoir-être","知识、技能和素养"],["développer son savoir-être","培养软技能"],["avoir un bon savoir-être","为人处世得体"]],"sy":[["les soft skills","familier","软技能（借自英语，职场常用）"],["les compétences comportementales","soutenu","行为能力"],["le savoir-faire","courant","对比：实际技能"]],"fq":"中频，招聘、教育话题。","me":"知道怎样「做人」：savoir（会）+ être（是）。","tr":{"zh":"公司更看重软技能而不只是文凭。","fr":"L'entreprise valorise le savoir-être, pas seulement le diplôme.","alt":"Pour l'entreprise, le savoir-être compte autant que le diplôme.","note":"pas seulement = 不只是；valoriser = 看重。"}},
 "Un amphithéâtre": {"pos":"n.m. 阳性名词，复数 amphithéâtres","s":"阶梯教室；大学的大教室（口语常缩写 un amphi）。也可指古罗马的圆形竞技场。大学里「上大课」就是在 amphi 里。","ipa":"[ɑ̃.fi.te.ɑtʁ]","ph":"am 读 [ɑ̃]；ph 读 [f]；th 读 [t]；â 读 [ɑ]；结尾 -tre 读 [tʁ]。","pi":"ph 是 [f]，th 是 [t]（不是英语的 θ）；注意 â 上的长音符号，拼写不要漏。","et":"来自拉丁语 amphitheatrum，由希腊语 amphi（周围）+ theatron（剧场）构成，意思是「四周都是座位的剧场」。","ex":[["Le cours magistral a lieu dans un grand amphithéâtre.","大课在大阶梯教室上。"],["On se retrouve à l'amphi à huit heures.","八点在阶梯教室见。"]],"co":[["un cours en amphi","在阶梯教室上的大课"],["un amphithéâtre romain","古罗马圆形竞技场"],["l'amphi A / l'amphi B","A 号 / B 号阶梯教室"]],"sy":[["amphi","familier","amphithéâtre 的口语缩写"],["la salle de cours","courant","普通教室"],["l'arène","littéraire","竞技场"]],"fq":"中频，大学生活常用。","me":"amphi（周围）+ théâtre：四周坐满人的剧场。","tr":{"zh":"阶梯教室里坐满了学生。","fr":"L'amphithéâtre est plein d'étudiants.","alt":"L'amphi est bondé.","note":"bondé = 挤满了（口语）；amphi 是缩写。"}},
 "Un BTS": {"pos":"n.m. 阳性名词，复数不变 des BTS","s":"BTS = Brevet de technicien supérieur，高中毕业后读两年的职业文凭，在高中或专门学校里上课，目标是直接就业。口语中直接说 un BTS。","ipa":"[be.te.ɛs]","ph":"按字母读：B [be]，T [te]，S [ɛs]。","pi":"字母读法要用法语：T 读 [te]，S 读 [ɛs]，别用英语 [ti]、[ɛs]。","et":"缩写，全称 Brevet de technicien supérieur。","ex":[["Elle a fait un BTS management après le lycée.","她高中毕业后读了管理 BTS。"],["Il prépare un BTS en informatique.","他在读信息技术 BTS。"]],"co":[["faire / préparer un BTS","读 BTS"],["un BTS en deux ans","两年制 BTS"],["un BTS comptabilité","会计 BTS"]],"sy":[["un DUT","courant","类似的两年职业文凭（现为 BUT）"],["un CAP","courant","更低一级的职业证书"]],"fq":"中频，法国教育体系专用词。","me":"B-T-S：Brevet（证书）+ Technicien（技术员）+ Supérieur（高级）。","tr":{"zh":"他想读两年的 BTS，然后直接工作。","fr":"Il veut faire un BTS de deux ans, puis travailler directement.","alt":"Il veut faire un BTS, et après il travaille tout de suite.","note":"BTS 是缩写词，用阳性冠词 un。"}},
 "Un CAP": {"pos":"n.m. 阳性名词，复数不变 des CAP","s":"CAP = Certificat d'aptitude professionnelle，职业能力证书，学手艺的初级职业文凭，如烘焙师、美发师、木工。通常学两年。","ipa":"[se.a.pe]","ph":"按字母读：C [se]，A [a]，P [pe]。","pi":"字母要用法语读音：C 读 [se]，P 读 [pe]；别读成英语单词 cap，也别用英语字母 [si]。","et":"缩写，全称 Certificat d'aptitude professionnelle（aptitude 来自拉丁语 aptitudo，适合）。","ex":[["Il a fait un CAP boulangerie car il n'avait pas le bac.","他没有高中文凭，读了烘焙 CAP。"],["Elle prépare un CAP coiffure.","她在读美发 CAP。"]],"co":[["passer un CAP","参加 CAP 考试"],["un CAP cuisine / pâtisserie","烹饪 / 糕点 CAP"],["avoir un CAP","拥有 CAP"]],"sy":[["un BEP","courant","旧的类似职业文凭，现已并入"],["un BTS","courant","更高一级（高中后）"]],"fq":"中频，职业教育话题。","me":"C-A-P：学手艺的「第一张证」。","tr":{"zh":"她读了美发 CAP，现在在沙龙工作。","fr":"Elle a un CAP de coiffure et travaille dans un salon.","alt":"Elle a passé un CAP coiffure, et maintenant elle bosse dans un salon.","note":"bosser 是 travailler 的口语。"}},
 "Un cerveau": {"pos":"n.m. 阳性名词，复数 cerveaux","s":"大脑；脑。比喻「头脑」「主谋」（le cerveau d'un projet = 项目的头脑）。un cerveau 也可指聪明的人。","ipa":"[sɛʁ.vo]","ph":"c 在 e 前读 [s]；er 读 [ɛʁ]；eau 读 [o]。","pi":"复数是 cerveaux（-eau + x），x 不发音；c 读 [s]，不是 [k]。","et":"来自拉丁语 cerebellum（cerebrum「脑」的指小词）。","ex":[["Le sommeil est essentiel pour reposer notre cerveau.","睡眠对让大脑休息至关重要。"],["C'est lui le cerveau de l'équipe.","他是团队的头脑。"]],"co":[["le cerveau humain","人脑"],["avoir un cerveau brillant","头脑聪明"],["la fuite des cerveaux","人才外流"],["se creuser le cerveau","绞尽脑汁"]],"sy":[["la cervelle","familier","脑子、脑浆（也指食物）"],["la tête","courant","头、脑袋"],["l'esprit","soutenu","思想、头脑"]],"fq":"高频，日常、科学都用。","me":"cerveau 读 [sɛʁ.vo]，开头像「塞」；复数 -eaux，和 beau → beaux 一样。","tr":{"zh":"咖啡能让大脑更清醒。","fr":"Le café aide le cerveau à rester éveillé.","alt":"Le café, ça réveille un peu le cerveau.","note":"aider qqn à + 不定式：帮助某人做某事。"}},
 "Un challenge": {"pos":"n.m. 阳性名词，复数 challenges","s":"挑战；竞赛。借自英语，在法语中主要指「有难度的目标」，口语和商业里很常用。比 défi 更偏职场、运动。也可指一次竞赛。","ipa":"[ʃa.lɑ̃ʒ]","ph":"ch 读 [ʃ]；-an- 读 [ɑ̃]；-ge 读 [ʒ]，按法语读，不是英语 [tʃæ]。","pi":"不要按英语读 [ˈtʃælɪndʒ]；法语读 [ʃa.lɑ̃ʒ]，a 读鼻音 [ɑ̃]，最后是 [ʒ]。","et":"借自英语 challenge，英语又源自古法语 chalenge（质疑，挑战）。","ex":[["Ce nouveau poste représente un beau challenge.","这个新职位是个很好的挑战。"],["J'aime relever les challenges.","我喜欢迎接挑战。"]],"co":[["relever un challenge","迎接挑战"],["un challenge sportif","体育竞赛"],["un beau challenge","很棒的挑战"]],"sy":[["défi","courant","更常用的法语词：挑战"],["épreuve","courant","考验、考试"],["gageure","soutenu","近乎不可能的挑战"]],"fq":"中频，职场与体育常用。","me":"英语借词，但读法语音 [ʃa.lɑ̃ʒ]。","tr":{"zh":"这个项目对团队是一个大挑战。","fr":"Ce projet est un gros challenge pour l'équipe.","alt":"Ce projet, c'est un vrai défi pour l'équipe.","note":"relever un challenge / un défi：迎接挑战。"}},
 "Un complexe": {"pos":"n.m. 阳性名词，复数 complexes；也是形容词 complexe（阴阳同形）","s":"①情结（complexe d'infériorité 自卑情结）；②综合体，大型建筑群（un complexe sportif 体育中心）。作形容词 complexe = 复杂的。","ipa":"[kɔ̃.plɛks]","ph":"om 读鼻化 [ɔ̃]；x 读 [ks]；结尾 -e 要发出 [ɛks]。","pi":"x 读 [ks]；开头不是 com [kɔm]，而是鼻音 [kɔ̃]。","et":"来自拉丁语 complexus（交织在一起），com- + plectere（编织）。","ex":[["Il a un complexe d'infériorité par rapport à ses camarades.","他对同学有自卑情结。"],["La ville a construit un nouveau complexe sportif.","这座城市建了新的体育中心。"]],"co":[["un complexe d'infériorité","自卑情结"],["un complexe sportif","体育中心"],["un complexe hôtelier","酒店综合体"],["avoir des complexes","自卑、有心理负担"]],"sy":[["un ensemble","courant","建筑群、整体"],["un blocage","courant","心理障碍"],["compliqué","courant","（形容词）复杂的，用于事物或人"]],"fq":"中高频，心理与城市话题。","me":"com + plexe：交织在一起，所以「复杂」又「情结」。","tr":{"zh":"他个子小，所以有点自卑。","fr":"Il est petit, alors il a un peu des complexes.","alt":"Comme il est petit, il a des complexes.","note":"avoir des complexes：口语，有自卑感。"}},
 "Un défi": {"pos":"n.m. 阳性名词，复数 défis","s":"挑战；考验。relever un défi = 迎接挑战；lancer un défi à qqn = 向某人发起挑战。也可指「挑衅」。","ipa":"[de.fi]","ph":"é 读 [e]；结尾 i 读 [i]，f 在中间要发。","pi":"复数 défis 的 s 不发音；不要把 défi 读成 [de.fiʃ]。","et":"来自动词 défier（古法语 desfier，不信任、挑战），含前缀 dé-。","ex":[["Réussir cette année est un vrai défi pour lui.","要在这一年成功，对他是个真正的挑战。"],["Il a lancé un défi à son frère.","他向哥哥发起了挑战。"]],"co":[["relever un défi","迎接挑战"],["lancer un défi","发起挑战"],["un défi à la raison","违背常理的事"],["les défis de l'avenir","未来的挑战"]],"sy":[["challenge","courant","借自英语，更偏职场/体育"],["épreuve","courant","考验"],["provocation","courant","挑衅（带攻击性）"]],"fq":"高频，日常和新闻都常用。","me":"défi → défier：向困难「宣战」。","tr":{"zh":"学一门新语言是一个挑战。","fr":"Apprendre une nouvelle langue est un défi.","alt":"Apprendre une langue, c'est tout un défi.","note":"Apprendre… est 作主语，用单数 est。"}},
 "Un dispositif": {"pos":"n.m. 阳性名词，复数 dispositifs","s":"措施；机制；装置。在行政和教育里指「一套安排好的方案或制度」，如 un dispositif d'aide（援助机制）。也可指技术装置。","ipa":"[dis.pɔ.zi.tif]","ph":"s 在两个元音间读 [z]（-po-si-），所以是 [pɔ.zi]；-tif 里 f 要发。","pi":"中间的 s 读 [z]；结尾 f 要发 [f]，不是 [if]。","et":"来自拉丁语 dispositus，动词 disposer（布置、安排）的同族词，加后缀 -if。","ex":[["La région met en place un dispositif d'aide au logement étudiant.","大区设立了学生住房援助机制。"],["Un dispositif de sécurité a été installé.","安装了一套安全装置。"]],"co":[["mettre en place un dispositif","建立一套机制"],["un dispositif d'aide","援助机制"],["un dispositif de sécurité","安全装置"]],"sy":[["système","courant","系统"],["mesure","courant","措施（单项）"],["appareil","courant","仪器、设备"]],"fq":"中高频，行政与新闻用语。","me":"disposer：把东西摆好，摆好的整套东西就是 dispositif。","tr":{"zh":"政府设立了一套帮助年轻人的机制。","fr":"Le gouvernement a mis en place un dispositif pour aider les jeunes.","alt":"Le gouvernement a créé un dispositif d'aide pour les jeunes.","note":"mettre en place：设立，建立。"}},
 "Un doctorat": {"pos":"n.m. 阳性名词，复数 doctorats","s":"博士学位；博士阶段。faire un doctorat = 读博士；soutenir sa thèse = 答辩。和医学「博士」docteur 是同族词，但 docteur 常指医生。","ipa":"[dɔk.tɔ.ʁa]","ph":"oc 读 [ɔk]；结尾 -at 读 [a]，t 不发音。","pi":"结尾 t 不发音；o 是开口 [ɔ]，不是 [o]。","et":"来自 docteur（拉丁语 doctor，教师，源自 docere 教）+ -at。","ex":[["Elle a obtenu un doctorat en biologie après cinq ans de recherche.","她做了五年研究后获得生物学博士学位。"],["Il prépare un doctorat en histoire.","他在读历史博士。"]],"co":[["préparer un doctorat","攻读博士"],["obtenir un doctorat","获得博士学位"],["un doctorat en droit","法学博士"],["soutenir sa thèse de doctorat","博士论文答辩"]],"sy":[["une thèse","courant","博士论文"],["un PhD","familier","借自英语的说法"],["un master","courant","硕士（低一级）"]],"fq":"中频，高等教育话题。","me":"docteur + -at：成为 docteur 的那个「学位」。","tr":{"zh":"她想读完博士后当研究员。","fr":"Elle veut devenir chercheuse après son doctorat.","alt":"Après son doctorat, elle veut faire de la recherche.","note":"devenir + 无冠词的职业名称。"}},
 "Un foie": {"pos":"n.m. 阳性名词，复数 foies","s":"肝；肝脏。也指做菜的肝，如 foie gras（鹅肝）、foie de veau（小牛肝）。avoir mal au foie / une crise de foie = 吃撑了难受（口语）。","ipa":"[fwa]","ph":"oi 读 [wa]，所以 foie = [fwa]；结尾 -e 不发音。","pi":"和 fois（次，[fwa]）、foi（信仰，[fwa]）同音，靠上下文区分；拼写 foie 有 ie。","et":"来自拉丁语 (iecur) ficatum，意思是「用无花果喂肥的肝」，所以 fig 与 foie 同源。","ex":[["Le foie est un organe vital du corps humain.","肝是人体的重要器官。"],["Je ne mange pas de foie gras.","我不吃鹅肝。"]],"co":[["le foie gras","鹅肝 / 肥肝"],["une crise de foie","吃多了不舒服"],["avoir mal au foie","肝痛、消化不好"],["le foie de veau","小牛肝"]],"sy":[["l'organe","courant","器官（泛指）"],["la fois","courant","同音词：次"],["la foi","courant","同音词：信仰"]],"fq":"中频，身体与饮食话题。","me":"foie = fois = foi，三个词同音 [fwa]。","tr":{"zh":"他的肝不好，不能喝酒。","fr":"Il a mal au foie, il ne peut pas boire d'alcool.","alt":"Son foie est fragile, alors il ne boit pas d'alcool.","note":"ne… pas de + 名词：否定后用 de。"}},
 "Un héritage": {"pos":"n.m. 阳性名词，复数 héritages","s":"遗产；也比喻「文化遗产，传承」。hériter de = 继承。un héritage culturel = 文化传承。","ipa":"[e.ʁi.taʒ]","ph":"h 不发音（哑 h）；é [e]；-age 读 [aʒ]。","pi":"开头 h 不发音，所以 l'héritage 要省音；结尾 -age 读 [aʒ]，g 是 [ʒ]。","et":"来自 hériter（拉丁语 hereditare，源自 heres「继承人」）+ -age。","ex":[["Ils ont reçu un héritage de leurs parents.","他们从父母那里得到一笔遗产。"],["Ce monument fait partie de notre héritage culturel.","这座建筑是我们文化遗产的一部分。"]],"co":[["recevoir un héritage","得到遗产"],["laisser un héritage","留下遗产"],["un héritage culturel","文化遗产"],["faire un héritage","继承遗产（口语）"]],"sy":[["un patrimoine","courant","财产；文化遗产（更大）"],["une succession","soutenu","继承、遗产（法律）"],["un legs","soutenu","遗赠"]],"fq":"中高频，家庭与文化话题。","me":"héritier（继承人）→ héritage：继承人得到的东西。","tr":{"zh":"他从祖母那里得到一笔遗产。","fr":"Il a reçu un héritage de sa grand-mère.","alt":"Sa grand-mère lui a laissé un héritage.","note":"laisser qqch à qqn：留给某人。"}},
 "Un idiome": {"pos":"n.m. 阳性名词，复数 idiomes","s":"①某个地区或群体特有的语言、方言；②（语言学）特定语言；英语里的 idiom（习语）法语通常叫 une expression idiomatique。","ipa":"[i.djɔm]","ph":"i-di-o-me：这里 io 合读 [jɔ]，m 要发，结尾 e 不发音。","pi":"不是英语 idiom 的 [ˈɪdiəm]；法语是 [i.djɔm]，重音在最后。","et":"来自希腊语 idiōma（特性、独特的说法），经拉丁语进入法语；同族词 idiot 原意是「个人的」。","ex":[["Ce linguiste étudie un idiome parlé dans une petite région.","这位语言学家研究一个小地区的方言。"],["Le breton est un idiome celtique.","布列塔尼语是一种凯尔特语言。"]],"co":[["un idiome local","地方方言"],["un idiome rare","稀有语言"],["une expression idiomatique","习语（惯用表达）"]],"sy":[["un dialecte","courant","方言"],["une langue","courant","语言"],["un patois","courant","土话（带贬义）"]],"fq":"低频，语言学用语。","me":"idiome ≠ 英语 idiom：法语里更像「某种土语」。","tr":{"zh":"这个村子说一种古老的方言。","fr":"Ce village parle un vieil idiome.","alt":"Dans ce village, on parle un très vieil idiome.","note":"on parle：口语里的「人们说」。"}},
 "Un label": {"pos":"n.m. 阳性名词，复数 labels","s":"标签；认证标志；（音乐）唱片公司。un label qualité 指由机构颁发的质量认证。一般不指商品上的小布标，那个叫 une étiquette。","ipa":"[la.bɛl]","ph":"a 读 [a]；e 读开口 [ɛ]；结尾 l 要发。","pi":"按法语读 [la.bɛl]，不要读英语的 [ˈleɪbəl]；它不是商品标签（étiquette）。","et":"借自英语 label，英语又来自古法语 label（带子、饰条）。","ex":[["Cette école possède un label de qualité reconnu.","这所学校拥有被认可的质量认证。"],["Ce chanteur vient de signer avec un nouveau label.","这位歌手刚和新唱片公司签约。"]],"co":[["un label de qualité","质量认证"],["le label bio","有机认证标志"],["un label de musique","唱片公司"],["obtenir un label","获得认证"]],"sy":[["une étiquette","courant","商品标签"],["une certification","soutenu","认证"],["une marque","courant","品牌"]],"fq":"中频，质量、商业与音乐话题。","me":"label ≠ étiquette：label 是「认证」，étiquette 是「小标签」。","tr":{"zh":"这家餐厅得到了一个质量认证。","fr":"Ce restaurant a obtenu un label de qualité.","alt":"Le restaurant a reçu un label qualité.","note":"obtenir 的过去分词 obtenu，助动词 avoir。"}},
 "Un mécanisme": {"pos":"n.m. 阳性名词，复数 mécanismes","s":"机制；机械装置；运作原理。可指机器的构造，也可比喻抽象的运作方式（le mécanisme du marché 市场机制）。","ipa":"[me.ka.nism]","ph":"é 读 [e]；c 在 a 前读 [k]；-isme 读 [ism]，结尾 e 不发音。","pi":"第一个 é 读 [e]，不要读成 [mɛ]；-isme 里 s 读 [s]，不是 [z]。","et":"来自拉丁语 mechanicus，希腊语 mēkhanē（机器、工具），同族词 mécanique、machine。","ex":[["Nous devons comprendre le mécanisme de cette formule.","我们必须理解这个公式的原理。"],["Le mécanisme de la montre est cassé.","手表的机芯坏了。"]],"co":[["le mécanisme de défense","防御机制"],["un mécanisme complexe","复杂的机制"],["comprendre le mécanisme","了解运作原理"],["un mécanisme d'horlogerie","钟表机芯"]],"sy":[["fonctionnement","courant","运作方式"],["système","courant","系统"],["rouage","soutenu","齿轮，比喻机构中的一环"]],"fq":"中高频，科学与社会话题。","me":"mécanique + isme：背后「怎样转起来」。","tr":{"zh":"我想理解这台机器的运作方式。","fr":"Je veux comprendre le mécanisme de cette machine.","alt":"Je voudrais comprendre comment fonctionne cette machine.","note":"voudrais 比 veux 更客气。"}},
 "Un pic": {"pos":"n.m. 阳性名词，复数 pics","s":"①尖峰；山峰；②（数据、人流的）高峰，如 un pic de pollution（污染高峰）。à pic = 陡直地；arriver à pic = 来得正好（口语）。","ipa":"[pik]","ph":"p [p]，i [i]，c [k] 都要发，一个音节。","pi":"结尾 c 要发 [k]，不是无声；复数 pics 的 s 不发音。","et":"词源不确定，可能与 pique / piquer（刺）有关。","ex":[["Les inscriptions atteignent un pic à la rentrée de septembre.","九月开学时注册人数达到高峰。"],["Il y a un pic de pollution aujourd'hui.","今天出现污染高峰。"]],"co":[["un pic de pollution","污染高峰"],["atteindre un pic","达到顶峰"],["à pic","陡直地；正好"],["un pic montagneux","山峰"]],"sy":[["sommet","courant","山顶，顶点"],["maximum","courant","最大值"],["apogée","soutenu","巅峰"]],"fq":"中频，天气、数据、登山。","me":"pic：像一根尖尖的刺 [pik]。","tr":{"zh":"晚上七点是交通高峰。","fr":"Il y a un pic de circulation à dix-neuf heures.","alt":"À 19 h, c'est le pic de circulation.","note":"il y a un pic de + 名词：出现……高峰。"}},
 "Un point fort": {"pos":"n.m. 阳性名词词组，复数 points forts","s":"优点；强项；长处。反义词 un point faible（弱点）。简历、面试和评价里都很常用。","ipa":"[pwɛ̃ fɔʁ]","ph":"point：oi 读 [wɛ̃]，不是 [wa]；t 不发音；fort：r 要发，t 不发音。","pi":"point 读 [pwɛ̃]，不是 [pɔint]；fort 的 t 不发音；复数两个词都加 s（points forts）。","et":"由 point（点，来自拉丁语 punctum）和 fort（强）组成。","ex":[["La créativité est un point fort de sa personnalité.","创造力是她性格的强项。"],["Quels sont vos points forts ?","您的强项是什么？"]],"co":[["un point fort et un point faible","强项和弱项"],["avoir des points forts","有长处"],["mettre en avant ses points forts","突出自己的强项"]],"sy":[["atout","courant","优势"],["qualité","courant","优点"],["point faible","courant","反义：弱点"]],"fq":"中高频，面试与评价。","me":"point（点）+ fort（强）：最「强」的那个点。","tr":{"zh":"我的强项是认真和耐心。","fr":"Mes points forts sont le sérieux et la patience.","alt":"Je suis sérieux et patient : c'est mon point fort.","note":"主语是复数 points forts，所以动词用 sont。"}},
 "Un précepte": {"pos":"n.m. 阳性名词，复数 préceptes","s":"准则；训诫；格言式的规则。多指道德、宗教或教育上的原则，语气较书面。","ipa":"[pʁe.sɛpt]","ph":"pré 读 [pʁe]；cep 读 [sɛp]；结尾 pt 中 p 发音、t 也发音：[sɛpt]。","pi":"pt 里的 p 要发出来（不像 compter）；c 在 e 前读 [s]。","et":"来自拉丁语 praeceptum（命令、教导），由 prae-（先）+ capere（拿）相关动词 praecipere 而来。","ex":[["Il applique toujours ce grand précepte de sagesse.","他总是遵循这条智慧准则。"],["Les préceptes de ses parents l'ont guidé.","父母的教诲曾引导过他。"]],"co":[["suivre un précepte","遵循准则"],["un précepte moral","道德准则"],["les préceptes religieux","宗教教规"]],"sy":[["principe","courant","原则"],["règle","courant","规则"],["maxime","soutenu","格言"]],"fq":"低频，书面语。","me":"pré + cept：事先「拿」给你的规矩。","tr":{"zh":"他一直遵守这条道德准则。","fr":"Il suit toujours ce précepte moral.","alt":"Il respecte toujours ce principe moral.","note":"suivre un précepte：遵守准则。"}},
 "Un premier de la classe": {"pos":"n.m. 阳性名词词组；阴性 une première de la classe，复数 des premiers de la classe","s":"班里的第一名；成绩最好的学生。有时带点讽刺，指「好学生、乖学生」。阴性：une première de la classe。","ipa":"[pʁə.mje də la klɑs]","ph":"premier：e 弱读 [ə]，ier 读 [je]，r 不发音；classe：a 读 [ɑ]（或 [a]），e 不发音。","pi":"premier 结尾 r 不发音；注意阴性 première 读 [pʁə.mjɛʁ]，r 要发。","et":"premier 来自拉丁语 primarius（第一的），classe 来自拉丁语 classis（等级、分类）。","ex":[["Il a toujours été le premier de la classe au collège.","他初中时一直是班里第一。"],["Elle n'est pas la première de la classe, mais elle travaille bien.","她不是班里第一名，但学习努力。"]],"co":[["être le premier de la classe","是班里第一名"],["le dernier de la classe","班里倒数第一"],["un bon élève","好学生"],["le chouchou du prof","老师的宠儿"]],"sy":[["un bon élève","courant","好学生"],["un fort en thème","familier","书呆子式的好学生，略带讽刺"],["un major de promotion","courant","年级第一（大学）"]],"fq":"中频，学校、日常。","me":"premier + classe：排在全班最前面。","tr":{"zh":"我姐姐总是班里第一名。","fr":"Ma sœur est toujours la première de la classe.","alt":"Ma sœur, elle est toujours première de la classe.","note":"女生用阴性 la première。"}},
 "Un projet": {"pos":"n.m. 阳性名词，复数 projets","s":"项目；计划；打算。avoir un projet = 有个计划；un projet de loi = 法案；un projet de fin d'études = 毕业设计。","ipa":"[pʁɔ.ʒɛ]","ph":"pr [pʁ]；o 读 [ɔ]；j 读 [ʒ]；et 读 [ɛ]，t 不发音。","pi":"结尾 -et 读 [ɛ]，t 不发音；复数 projets 的 ts 都不发音。","et":"来自拉丁语 projectum（向前抛），pro-（向前）+ jacere（抛），同族词 projeter。","ex":[["Ils travaillent ensemble sur un projet de fin d'études.","他们一起做毕业项目。"],["J'ai un projet pour les vacances.","我暑假有个计划。"]],"co":[["un projet de fin d'études","毕业设计"],["faire des projets","做计划"],["un projet de loi","法案草案"],["mener un projet à bien","把项目做成"]],"sy":[["plan","courant","计划"],["programme","courant","安排、方案"],["dessein","littéraire","意图"]],"fq":"极高频，日常与职场通用。","me":"pro + jet：把想法「抛」到前面去。","tr":{"zh":"我们有一个新项目要开始。","fr":"Nous avons un nouveau projet à commencer.","alt":"On a un nouveau projet à lancer.","note":"avoir qqch à + 不定式：有……要做。"}},
 "Un snob": {"pos":"n.m. 阳性名词（也可 une snob）；也是形容词 snob（阴阳同形，不变）","s":"势利的人；爱摆架子、看不起「没品位」的人。作形容词：Elle est un peu snob. 比 prétentieux 更强调「看不起大众」。","ipa":"[snɔb]","ph":"sn 连读 [sn]；o 读 [ɔ]；b 要发。","pi":"b 要发音 [b]；形容词阴性 snob 不变，不加 e。","et":"借自英语 snob，英语 19 世纪使用，更早来源不确定。","ex":[["Il a une attitude snob avec les gens qu'il ne connaît pas.","他对不认识的人态度很势利。"],["Ne sois pas snob, ce film est très bien.","别摆架子，这部电影很好。"]],"co":[["faire le snob","摆架子"],["avoir l'air snob","看起来势利"],["une attitude snob","势利的态度"]],"sy":[["prétentieux","courant","自命不凡的"],["hautain","soutenu","傲慢的"],["bobo","familier","新潮中产（略带讽刺）"]],"fq":"中频，日常评价人。","me":"snob：英语借词，法语里也读 [snɔb]。","tr":{"zh":"别这么势利，大家都能进来。","fr":"Ne sois pas snob, tout le monde peut entrer.","alt":"Fais pas le snob, tout le monde peut entrer.","note":"否定祈使：Ne sois pas + 形容词。"}},
 "Un sondage": {"pos":"n.m. 阳性名词，复数 sondages","s":"民意调查；抽样调查。常见 un sondage d'opinion。动词 sonder = 探测，调查。selon un sondage = 根据一项调查。","ipa":"[sɔ̃.daʒ]","ph":"on 读鼻化 [ɔ̃]；-age 读 [aʒ]。","pi":"on 是鼻音，不读 [ɔn]；-age 里 g 读 [ʒ]；sondage ≠ sandwich，只有开头相近。","et":"来自动词 sonder（探测）加后缀 -age，sonder 本义是「测深」，其起源不确定。","ex":[["Selon ce sondage, les étudiants sont optimistes pour leur avenir.","根据这项调查，学生对未来很乐观。"],["Un sondage a été réalisé auprès de mille personnes.","对一千人做了调查。"]],"co":[["selon un sondage","根据一项调查"],["réaliser un sondage","进行调查"],["un sondage d'opinion","民意调查"],["les résultats du sondage","调查结果"]],"sy":[["enquête","courant","调查（更广）"],["étude","courant","研究"],["questionnaire","courant","问卷"]],"fq":"高频，新闻中常见。","me":"sonder：像把一根探测杆放下去，测一测民意。","tr":{"zh":"根据最新民调，大多数人支持这项改革。","fr":"Selon le dernier sondage, la plupart des gens soutiennent cette réforme.","alt":"D'après le dernier sondage, la majorité soutient cette réforme.","note":"la plupart des + 复数名词，动词用复数。"}},
 "Un témoignage": {"pos":"n.m. 阳性名词，复数 témoignages","s":"证词；见证；经验分享。法庭上是证词；日常里是别人讲述自己的经历。apporter son témoignage = 讲述自己的经历。","ipa":"[te.mwa.ɲaʒ]","ph":"é 读 [e]；oi 读 [wa]；gn 读 [ɲ]；-age 读 [aʒ]。","pi":"gn 是 [ɲ]，像「宁」；oi 是 [wa]，所以 -moi- 读 [mwa]。","et":"来自 témoin（证人，拉丁语 testimonium）+ -age。","ex":[["Un ancien élève est venu apporter son témoignage sur son métier.","一位校友来分享他的职业经历。"],["Son témoignage a été très émouvant.","他的讲述让人很感动。"]],"co":[["apporter son témoignage","分享自己的经历"],["un témoignage poignant","感人的见证"],["un faux témoignage","伪证"],["recueillir des témoignages","收集证词"]],"sy":[["récit","courant","叙述"],["déposition","soutenu","（法庭）证词"],["preuve","courant","证据"]],"fq":"中高频，新闻与法律场合。","me":"témoin + -age：证人说出的内容。","tr":{"zh":"她的讲述让大家都很感动。","fr":"Son témoignage a ému tout le monde.","alt":"Son témoignage a beaucoup touché tout le monde.","note":"émouvoir 的过去分词是 ému。"}},
 "Un thésard": {"pos":"n.m. 阳性名词，阴性 une thésarde，复数 thésards","s":"博士生；正在写博士论文的人。口语，比 doctorant 更随意。","ipa":"[te.zaʁ]","ph":"th 读 [t]；é 读 [e]；s 在元音间读 [z]；-ard 读 [aʁ]，d 不发音。","pi":"th 读 [t]，不是英语的 θ；s 读 [z]；结尾 d 不发音，r 要发。","et":"来自 thèse（论文）加口语后缀 -ard。thèse 来自希腊语 thesis（放置，论点）。","ex":[["Le thésard passe ses journées à la bibliothèque universitaire.","博士生整天泡在大学图书馆。"],["Ma sœur est thésarde en chimie.","我姐姐是化学博士生。"]],"co":[["être thésard(e)","是博士生"],["un thésard en histoire","历史博士生"],["un thésard à Lyon","在里昂读博的人"]],"sy":[["doctorant","courant","博士生（正式）"],["étudiant en doctorat","courant","读博士的学生"],["chercheur","courant","研究员"]],"fq":"低中频，校园口语。","me":"thèse + -ard：整天「写论文」的人。","tr":{"zh":"我朋友是博士生，一直在写论文。","fr":"Mon ami est thésard, il écrit sa thèse toute la journée.","alt":"Mon pote est thésard : il passe son temps à écrire.","note":"pote 是 ami 的口语。"}},
 "Un tutorat": {"pos":"n.m. 阳性名词，复数 tutorats","s":"辅导；导师制；学长学姐帮助新生的学习制度。也有法律意义上的「监护」，但教育里最常用的是辅导。","ipa":"[ty.tɔ.ʁa]","ph":"u 读 [y]；o 读 [ɔ]；-at 读 [a]，t 不发音。","pi":"第一个 u 读 [y]，不是 [u]；结尾 t 不发音。","et":"来自拉丁语 tutor（保护者，监护人），加后缀 -at。","ex":[["Le tutorat aide les nouveaux étudiants à s'intégrer.","辅导帮助新生融入。"],["Elle assure du tutorat en mathématiques.","她负责数学辅导。"]],"co":[["assurer un tutorat","负责辅导"],["le tutorat étudiant","学生互助辅导"],["un tuteur / une tutrice","导师"]],"sy":[["soutien scolaire","courant","课后辅导"],["mentorat","soutenu","导师指导"],["parrainage","courant","新老生结对"]],"fq":"中频，大学与职场。","me":"tuteur + -at：做 tuteur 这件事。","tr":{"zh":"学校为新生提供辅导。","fr":"L'école propose un tutorat aux nouveaux étudiants.","alt":"L'école met en place un tutorat pour les nouveaux.","note":"proposer qqch à qqn：向某人提供某物。"}},
 "De la rigueur": {"pos":"n.f. 阴性名词，常用部分冠词 de la rigueur，无复数","s":"严谨；严格；认真一丝不苟。也可指（气候）严酷：la rigueur de l'hiver。avoir de la rigueur = 做事严谨。","ipa":"[ʁi.gœʁ]","ph":"r 在词首为小舌音 [ʁ]；gu 里 u 不发音，读 [g]；eu 读 [œ]，结尾 r 要发。","pi":"gu 读 [g]，u 是哑的；eur 读 [œʁ]，r 要发；别读成 [ʁi.gœ]。","et":"来自拉丁语 rigor（坚硬、严格），同族词 rigide、rigoureux。","ex":[["Ce projet scientifique exige beaucoup de rigueur.","这个科学项目要求十分严谨。"],["La rigueur de l'hiver surprend les touristes.","冬天的严寒让游客吃惊。"]],"co":[["travailler avec rigueur","严谨地工作"],["manquer de rigueur","缺乏严谨"],["la rigueur scientifique","科学的严谨"],["en toute rigueur","严格说来"]],"sy":[["sérieux","courant","认真"],["précision","courant","精确"],["sévérité","courant","严厉"]],"fq":"中频，学业与职场。","me":"rigueur ≈ rigide：做事像尺子一样直。","tr":{"zh":"做研究需要严谨。","fr":"Faire de la recherche demande de la rigueur.","alt":"Pour faire de la recherche, il faut de la rigueur.","note":"il faut de la + 名词：需要……"}},
 "L'accessibilité": {"pos":"n.f. 阴性名词，复数 accessibilités（很少用）","s":"可及性；无障碍；容易获得。指地点、服务或内容让所有人都用得上，如 l'accessibilité pour les personnes handicapées。","ipa":"[ak.sɛ.si.bi.li.te]","ph":"cc 在 e 前读 [ks]：ac-ces → [ak.sɛ]；-bi-li-té 每个音节都清楚。","pi":"cc 读 [ks]，不是 [k]；词尾 é 重读 [e]。","et":"accessible（拉丁语 accessibilis，源于 accedere 接近）+ -ité。","ex":[["L'accessibilité des cours en ligne facilite le travail à distance.","在线课程便于获取，方便远程学习。"],["L'accessibilité du bâtiment est excellente.","这栋楼的无障碍设施很好。"]],"co":[["l'accessibilité des transports","交通的便利性"],["l'accessibilité aux personnes handicapées","残障无障碍"],["améliorer l'accessibilité","改善可及性"]],"sy":[["facilité d'accès","courant","容易到达"],["commodité","soutenu","便利"],["disponibilité","courant","可得性"]],"fq":"中频，社会与技术话题。","me":"accéder（到达）+ ibilité：能被「到达」的程度。","tr":{"zh":"这座城市的交通便利性很高。","fr":"L'accessibilité des transports est très bonne dans cette ville.","alt":"Dans cette ville, les transports sont très accessibles.","note":"名词 accessibilité 对应形容词 accessible。"}},
 "L'adaptation": {"pos":"n.f. 阴性名词，复数 adaptations","s":"适应；改编。s'adapter à = 适应；une adaptation d'un roman = 小说改编（电影、剧）。","ipa":"[a.dap.ta.sjɔ̃]","ph":"ad 读 [ad]；pt 里 p 要发 [p]；-tion 读 [sjɔ̃]。","pi":"-tion 读 [sjɔ̃]，不是 [tion]；中间 pt 要发 [pt]。","et":"来自动词 adapter（拉丁语 adaptare，ad- 向 + aptus 合适）+ -ation。","ex":[["L'adaptation à la vie universitaire demande un effort.","适应大学生活需要努力。"],["Ce film est une adaptation d'un roman célèbre.","这部电影改编自一本名著。"]],"co":[["s'adapter à","适应……"],["une période d'adaptation","适应期"],["capacité d'adaptation","适应能力"],["l'adaptation d'un roman","小说改编"]],"sy":[["acclimatation","soutenu","适应环境"],["intégration","courant","融入"],["ajustement","courant","调整"]],"fq":"高频，学习与职场。","me":"adapter + -tion：让自己变得「合适」。","tr":{"zh":"新生需要一段时间适应。","fr":"Les nouveaux ont besoin d'un peu de temps pour s'adapter.","alt":"Il faut un peu de temps aux nouveaux pour s'adapter.","note":"avoir besoin de + 名词 / 不定式。"}},
 "L'ambition": {"pos":"n.f. 阴性名词，复数 ambitions","s":"雄心；抱负；野心。可褒可贬：avoir de l'ambition 是积极的；quelqu'un d'ambitieux 有时指「爱爬」。","ipa":"[ɑ̃.bi.sjɔ̃]","ph":"am 读鼻化 [ɑ̃]；-tion 读 [sjɔ̃]。","pi":"am 在 b 前读 [ɑ̃]，m 不单独发；-tion 读 [sjɔ̃]，不是 [tjɔ̃]。","et":"来自拉丁语 ambitio，源自 ambire（四处走动拉选票）。","ex":[["Son ambition est d'ouvrir son propre cabinet d'avocat.","她的雄心是开自己的律师事务所。"],["Il n'a pas beaucoup d'ambition.","他没有太大野心。"]],"co":[["avoir de l'ambition","有抱负"],["avoir l'ambition de","怀有……的志向"],["sans ambition","没有野心"],["une grande ambition","远大志向"]],"sy":[["aspiration","soutenu","渴望"],["objectif","courant","目标"],["rêve","courant","梦想"]],"fq":"高频，人生与工作话题。","me":"ambition 像英语 ambition，但 -tion 读 [sjɔ̃]。","tr":{"zh":"她的志向是当医生。","fr":"Son ambition est de devenir médecin.","alt":"Elle rêve de devenir médecin.","note":"Son ambition est de + 不定式。"}},
 "L'antiquité": {"pos":"n.f. 阴性名词，复数 antiquités（意为古董）","s":"古代；古典时代（古希腊、古罗马）。大写 l'Antiquité 指古希腊罗马时期。复数 antiquités = 古董。","ipa":"[ɑ̃.ti.ki.te]","ph":"an 读 [ɑ̃]；qu 读 [k]；-té 读 [te]。","pi":"qu 读 [k]，不是 [kw]；an 读鼻音 [ɑ̃]。","et":"来自拉丁语 antiquitas，源自 antiquus（古老的），同族词 antique。","ex":[["Elle se passionne pour l'histoire de la Grèce dans l'Antiquité.","她迷上了古希腊史。"],["Il vend des antiquités au marché aux puces.","他在跳蚤市场卖古董。"]],"co":[["dans l'Antiquité","在古代"],["l'Antiquité grecque / romaine","古希腊 / 古罗马"],["un magasin d'antiquités","古董店"],["de toute antiquité","自古以来"]],"sy":[["l'histoire ancienne","courant","古代史"],["le passé","courant","过去"],["l'ancien temps","courant","古时候"]],"fq":"中频，历史话题。","me":"antique + ité：古老的东西，古老的时代。","tr":{"zh":"我们在课上学习古代史。","fr":"En cours, nous étudions l'histoire de l'Antiquité.","alt":"En classe, on étudie l'Antiquité.","note":"一般大写 Antiquité 指古希腊罗马时期。"}},
 "L'estime de soi": {"pos":"n.f. 阴性名词词组，无复数","s":"自尊；自我肯定。指对自己价值的看法。avoir une bonne / mauvaise estime de soi = 自我评价高 / 低。","ipa":"[ɛs.tim də swa]","ph":"es 读 [ɛs]；-ti- 读 [ti]；soi 读 [swa]，oi = [wa]。","pi":"estime 里 t 读 [t]，不是 [s]；soi 读 [swa]，别和 soie（丝）搞混，其实同音。","et":"estime 来自 estimer（拉丁语 aestimare，评价）。soi 是自反代词。","ex":[["Les encouragements aident à développer l'estime de soi.","鼓励有助于培养自尊。"],["Il manque d'estime de soi.","他缺乏自尊心。"]],"co":[["avoir confiance en soi","对自己有信心"],["manquer d'estime de soi","缺乏自尊"],["renforcer l'estime de soi","增强自尊"]],"sy":[["confiance en soi","courant","自信"],["amour-propre","soutenu","自尊心"],["fierté","courant","自豪"]],"fq":"中频，心理话题。","me":"estime（评价）+ de soi（自己）：自己给自己打的分。","tr":{"zh":"孩子需要有自尊才能成长。","fr":"Les enfants ont besoin d'estime de soi pour grandir.","alt":"Pour grandir, un enfant a besoin d'avoir de l'estime pour lui-même.","note":"avoir besoin de + 无冠词名词（estime）。"}},
 "L'exploitation": {"pos":"n.f. 阴性名词，复数 exploitations","s":"开发；经营；利用。①自然资源开发；②农场、企业经营 une exploitation agricole（农场）；③剥削、利用别人（常带贬义）。","ipa":"[ɛk.splwa.ta.sjɔ̃]","ph":"x 读 [ks]：ex-plo → [ɛk.spl]；oi 读 [wa]；-tion 读 [sjɔ̃]。","pi":"x 读 [ks]；-ploi- 里 oi 读 [wa]；-tion 读 [sjɔ̃]。","et":"来自动词 exploiter（古法语 esploitier），加 -ation；这一词族的最终来源较复杂，此处不展开。","ex":[["L'exploitation des ressources naturelles doit être responsable.","自然资源的开发必须负责任。"],["Ses parents ont une exploitation agricole.","他父母有一个农场。"]],"co":[["une exploitation agricole","农场"],["l'exploitation des ressources","资源开发"],["l'exploitation d'un site","景点 / 场地的运营"],["l'exploitation de l'homme par l'homme","人对人的剥削"]],"sy":[["utilisation","courant","使用"],["gestion","courant","管理"],["abus","courant","滥用"]],"fq":"中高频，经济与环境话题。","me":"ex + ploit：把资源「用到极致」。","tr":{"zh":"他的家人经营一个小农场。","fr":"Sa famille a une petite exploitation agricole.","alt":"Sa famille tient une petite ferme.","note":"tenir une ferme：经营农场。"}},
 "La culture générale": {"pos":"n.f. 阴性名词词组，无复数","s":"常识；基本文化素养。指历史、地理、文学、科学等广泛的知识。考试和面试里常有「culture générale」题。","ipa":"[kyl.tyʁ ʒe.ne.ʁal]","ph":"cul 读 [kyl]，u 读 [y]；ture 读 [tyʁ]；générale：g 读 [ʒ]，é 读 [e]。","pi":"两个 u 都读 [y]；g 在 é 前读 [ʒ]；结尾 -ale 读 [al]，e 不发音。","et":"culture 来自拉丁语 cultura（耕作），colere；générale 来自拉丁语 generalis。","ex":[["Ce quiz teste votre culture générale sur l'histoire.","这个测验考察你的历史常识。"],["Il a beaucoup de culture générale.","他的常识很丰富。"]],"co":[["avoir de la culture générale","有文化素养"],["un test de culture générale","常识测验"],["manquer de culture générale","缺乏常识"]],"sy":[["connaissances générales","courant","一般知识"],["érudition","soutenu","博学"],["savoir","courant","知识"]],"fq":"中频，考试与交流。","me":"culture（耕耘）+ générale：什么都懂一点。","tr":{"zh":"读书可以提高常识水平。","fr":"Lire permet d'améliorer sa culture générale.","alt":"En lisant, on améliore sa culture générale.","note":"permettre de + 不定式。"}},
 "La facilité": {"pos":"n.f. 阴性名词，复数 facilités","s":"轻松；容易；天赋。avoir de la facilité = 学得轻松；复数 les facilités de paiement = 分期付款的便利。","ipa":"[fa.si.li.te]","ph":"c 在 i 前读 [s]；每个元音分开读；结尾 é 读 [e]。","pi":"c 读 [s]，不是 [k]；注意结尾 é 要读足。","et":"来自拉丁语 facilitas，源自 facilis（容易的），同族词 facile。","ex":[["Elle a une grande facilité pour apprendre les langues.","她学外语很有天赋。"],["Il parle avec facilité devant le public.","他在公众面前讲话很轻松。"]],"co":[["avoir de la facilité","学东西容易"],["avec facilité","轻松地"],["facilités de paiement","分期付款"],["par facilité","图省事"]],"sy":[["aisance","courant","从容"],["talent","courant","才华"],["simplicité","courant","简单"]],"fq":"中高频，日常。","me":"facile + -ité：「容易」这个性质。","tr":{"zh":"她学数学很轻松。","fr":"Elle a beaucoup de facilité en mathématiques.","alt":"Elle apprend les maths très facilement.","note":"avoir de la facilité en + 学科。"}},
 "La flexibilité": {"pos":"n.f. 阴性名词，复数 flexibilités（少用）","s":"灵活性；弹性。可指时间、规则、身体柔韧或性格随和。la flexibilité des horaires = 弹性工时。","ipa":"[flɛk.si.bi.li.te]","ph":"x 读 [ks]：fle-xi → [flɛk.si]；每个元音清楚；结尾 é 读 [e]。","pi":"x 读 [ks]，不是 [gz]；fl 连读；结尾 -té 读 [te]。","et":"来自拉丁语 flexibilis（可弯曲的），源自 flectere（弯曲）。","ex":[["La flexibilité des horaires est un avantage pour les étudiants.","时间灵活对学生是个优势。"],["Ce travail demande de la flexibilité.","这份工作需要灵活。"]],"co":[["la flexibilité des horaires","弹性工时"],["faire preuve de flexibilité","表现出灵活性"],["manquer de flexibilité","缺乏弹性"]],"sy":[["souplesse","courant","灵活、柔软"],["adaptabilité","soutenu","适应力"],["rigidité","courant","反义：僵硬"]],"fq":"中频，职场用语。","me":"flex（弯）+ ibilité：可以弯一弯。","tr":{"zh":"这份工作的时间很灵活。","fr":"Les horaires de ce travail sont très flexibles.","alt":"Dans ce travail, il y a beaucoup de flexibilité sur les horaires.","note":"flexibilité 对应形容词 flexible。"}},
 "La maintenance": {"pos":"n.f. 阴性名词，无复数（通常）","s":"维护；保养；检修。多用于机器、设备、网站、系统：la maintenance d'un ascenseur = 电梯检修。","ipa":"[mɛ̃.tə.nɑ̃s]","ph":"main 读 [mɛ̃]；te 弱读 [tə]；nance 读 [nɑ̃s]。","pi":"ain 读 [ɛ̃]；-ance 读 [ɑ̃s]；第二个音节 te 常被弱读。","et":"来自 maintenir（main 手 + tenir 握住）+ -ance。","ex":[["La maintenance des machines est effectuée chaque semaine.","机器每周维护一次。"],["Le site est en maintenance jusqu'à demain.","网站维护到明天。"]],"co":[["la maintenance informatique","IT 维护"],["en maintenance","维护中"],["un contrat de maintenance","维保合同"],["un technicien de maintenance","维修技术员"]],"sy":[["entretien","courant","保养、打扫"],["réparation","courant","修理"],["dépannage","courant","应急修理"]],"fq":"中频，技术与工作。","me":"main + tenir：用手握住，让它继续运转。","tr":{"zh":"电梯正在维修。","fr":"L'ascenseur est en maintenance.","alt":"L'ascenseur est en cours de réparation.","note":"être en maintenance：正在维护。"}},
 "La pédagogie": {"pos":"n.f. 阴性名词，复数 pédagogies","s":"教学法；教育学；教学能力。avoir de la pédagogie = 善于讲解、会教。une pédagogie active = 主动式教学。","ipa":"[pe.da.gɔ.ʒi]","ph":"é 读 [e]；g 在 o 前读 [g]（gɔ），-gie 里 g 读 [ʒ]。","pi":"有两个 g：第一个读 [g]，第二个读 [ʒ]；结尾 -ie 读 [i]。","et":"来自希腊语 paidagōgia（教育孩子），paidos 孩子 + agein 引导。","ex":[["Ce professeur utilise une pédagogie moderne et interactive.","这位老师使用现代、互动的教学法。"],["Il a beaucoup de pédagogie pour expliquer.","他讲解很有方法。"]],"co":[["avoir de la pédagogie","善于教学"],["une pédagogie active","主动式教学"],["la pédagogie Montessori","蒙台梭利教学法"],["manquer de pédagogie","不会教"]],"sy":[["didactique","soutenu","教学法（专门）"],["enseignement","courant","教学"],["méthode","courant","方法"]],"fq":"中频，教育话题。","me":"paid（孩子）+ agogie（引导）：带孩子走路。","tr":{"zh":"这位老师很会讲解。","fr":"Cette professeure a beaucoup de pédagogie.","alt":"Cette prof sait très bien expliquer.","note":"avoir de la pédagogie = 善于教。"}},
 "La physique": {"pos":"n.f. 阴性名词，无复数（学科）；形容词 physique = 身体的","s":"物理（学）。作学科名；形容词 physique 指身体的，如 l'éducation physique（体育）。le physique（阳性）= 外貌，体格。","ipa":"[fi.zik]","ph":"ph 读 [f]；y 读 [i]；s 在元音间读 [z]；-que 读 [k]。","pi":"ph 读 [f]；s 读 [z]，所以 physique = [fi.zik]，不是 [fi.sik]。","et":"来自希腊语 physikē，physis（自然）。同族词 physicien（物理学家）。","ex":[["Elle étudie la physique à l'université de Lyon.","她在里昂大学学物理。"],["Il adore la physique et les maths.","他很喜欢物理和数学。"]],"co":[["faire de la physique","学物理"],["la physique quantique","量子物理"],["un professeur de physique","物理老师"],["l'éducation physique","体育课"]],"sy":[["la chimie","courant","化学（相邻学科）"],["les sciences","courant","科学"],["la mécanique","courant","力学"]],"fq":"高频，学校与科学。","me":"physique 里有个 s 的 [z]：像 [fi.zik]。","tr":{"zh":"我最喜欢的科目是物理。","fr":"Ma matière préférée, c'est la physique.","alt":"Ce que je préfère, c'est la physique.","note":"c'est 强调结构：Ma matière préférée, c'est…"}},
 "La réussite": {"pos":"n.f. 阴性名词，复数 réussites","s":"成功；成就。la réussite scolaire = 学业成功。réussir à = 成功做到；réussir un examen = 通过考试。","ipa":"[ʁe.y.sit]","ph":"ré 读 [ʁe]；u 读 [y]；ss 读 [s]；-ite 读 [it]，e 不发音。","pi":"éu 分开读 [e.y]；ss 读 [s]；结尾 e 不发音。","et":"来自动词 réussir（借自意大利语 riuscire，「出来」）加后缀 -ite。","ex":[["Le travail régulier est la clé de la réussite.","持之以恒是成功的关键。"],["Félicitations pour votre réussite !","祝贺您的成功！"]],"co":[["la clé de la réussite","成功的关键"],["la réussite scolaire","学业成功"],["un taux de réussite","通过率"],["une belle réussite","漂亮的成就"]],"sy":[["succès","courant","成功（更常用）"],["victoire","courant","胜利"],["échec","courant","反义：失败"]],"fq":"高频，学习与工作。","me":"réussir → réussite：-ir 变 -ite。","tr":{"zh":"努力是成功的关键。","fr":"L'effort est la clé de la réussite.","alt":"Pour réussir, il faut travailler dur.","note":"la clé de + 名词：……的关键。"}},
 "La révolution française": {"pos":"n.f. 阴性名词词组，复数 révolutions","s":"法国大革命，1789 年开始。作历史事件常写作 la Révolution française（首字母大写）。révolution 也可指转动或剧变。","ipa":"[ʁe.vɔ.ly.sjɔ̃ fʁɑ̃.sɛz]","ph":"ré [ʁe]；vo [vɔ]；lu [ly]；-tion [sjɔ̃]；française：ai 读 [ɛ]，ç 读 [s]，结尾 s 读 [z]。","pi":"lu 读 [ly]；française 里 ai 读 [ɛ]，不是 [e]；-çaise 读 [sɛz]。","et":"révolution 来自拉丁语 revolutio（旋转，revolvere 转动）。","ex":[["La Révolution française a débuté en 1789.","法国大革命始于 1789 年。"],["Nous étudions la Révolution française en cours d'histoire.","我们在历史课上学习法国大革命。"]],"co":[["en 1789","1789 年"],["la prise de la Bastille","攻占巴士底狱"],["une révolution industrielle","工业革命"],["la Déclaration des droits de l'homme","人权宣言"]],"sy":[["les événements de 1789","courant","1789 年的事件"],["la Terreur","courant","恐怖统治（革命一阶段）"],["la Commune","courant","巴黎公社（另一场运动）"]],"fq":"中频，历史话题。","me":"1789，革命 révolution：「转」个大圈。","tr":{"zh":"法国大革命改变了欧洲。","fr":"La Révolution française a changé l'Europe.","alt":"La Révolution française a transformé toute l'Europe.","note":"changer 的过去分词 changé，助动词 avoir。"}},
 "La SNCF": {"pos":"n.f. 阴性名词（缩写），无复数，因为 Société 阴性","s":"SNCF = Société nationale des chemins de fer français，法国国家铁路公司。口语里 prendre la SNCF / le train。TGV 是它的高铁。","ipa":"[ɛs.ɛn.se.ɛf]","ph":"按字母逐个读：S [ɛs]，N [ɛn]，C [se]，F [ɛf]。","pi":"每个字母都用法语读：C 读 [se]，别读成英语 [si]；用 la，不是 le。","et":"缩写。名称由 société（公司）+ nationale（国家的）+ chemins de fer（铁路）+ français 组成。","ex":[["Je prends le train de la SNCF pour aller à Paris.","我坐 SNCF 的火车去巴黎。"],["La SNCF annonce une grève demain.","SNCF 宣布明天罢工。"]],"co":[["un billet SNCF","SNCF 车票"],["une grève de la SNCF","SNCF 罢工"],["la gare SNCF","SNCF 火车站"],["l'application SNCF","SNCF 应用"]],"sy":[["le TGV","courant","高速列车"],["le train","courant","火车"],["la RATP","courant","巴黎地铁公交公司"]],"fq":"极高频，在法国出行必备。","me":"S-N-C-F：法国的铁路 = 一串字母。","tr":{"zh":"SNCF 明天有罢工，火车会晚点。","fr":"Il y a une grève de la SNCF demain, les trains seront en retard.","alt":"Demain, grève à la SNCF : les trains auront du retard.","note":"grève de la SNCF：罢工；seront 是 être 的将来时。"}},
 "La spontanéité": {"pos":"n.f. 阴性名词，无复数","s":"自发性；自然、不做作的态度。指不事先计划、直接表达，如 répondre avec spontanéité。多是褒义。","ipa":"[spɔ̃.ta.ne.i.te]","ph":"sp 连读；on 读 [ɔ̃]；né-i 分开读 [ne.i]；结尾 é [e]。","pi":"-néi- 要分成两个音节 [ne.i]；on 读鼻音，不要读 [ɔn]。","et":"来自拉丁语 spontaneus（自愿的），源于 sponte（出于自愿），加 -ité。","ex":[["Sa spontanéité rend ses présentations orales très vivantes.","他的自然随性让口头报告很生动。"],["J'aime sa spontanéité et sa bonne humeur.","我喜欢她的率真和好心情。"]],"co":[["avec spontanéité","自然地"],["manquer de spontanéité","缺乏自然"],["la spontanéité d'un enfant","孩子的率真"]],"sy":[["naturel","courant","自然"],["franchise","courant","坦率"],["improvisation","courant","即兴"]],"fq":"中低频，性格与表达。","me":"spontané + ité：不用想就脱口而出。","tr":{"zh":"孩子们的率真让人开心。","fr":"La spontanéité des enfants fait plaisir.","alt":"On aime la spontanéité des enfants.","note":"faire plaisir (à qqn)：让人高兴。"}},
 "La vulgarisation": {"pos":"n.f. 阴性名词，无复数","s":"普及；科普。把专业知识用通俗的话讲给大众：la vulgarisation scientifique = 科普。不是「粗俗化」。","ipa":"[vyl.ga.ʁi.za.sjɔ̃]","ph":"vul 读 [vyl]；ga 读 [ga]；ri 读 [ʁi]；sa 读 [za]；-tion 读 [sjɔ̃]。","pi":"u 读 [y]；g 在 a 前读 [g]；s 读 [z]，-tion 读 [sjɔ̃]。","et":"来自动词 vulgariser（vulgaire 通俗的，拉丁语 vulgus 民众）+ -ation。","ex":[["La vulgarisation scientifique rend la physique accessible à tous.","科普使物理让每个人都能理解。"],["Il écrit des livres de vulgarisation.","他写科普书。"]],"co":[["la vulgarisation scientifique","科普"],["un livre de vulgarisation","科普读物"],["un travail de vulgarisation","科普工作"]],"sy":[["popularisation","soutenu","大众化"],["diffusion","courant","传播"],["simplification","courant","简化"]],"fq":"中低频，知识与媒体。","me":"vulgus（民众）：把知识送给大众。","tr":{"zh":"这本书是给大众看的科普书。","fr":"Ce livre est un ouvrage de vulgarisation pour le grand public.","alt":"C'est un livre de vulgarisation, fait pour tout le monde.","note":"le grand public：大众。"}},
 "Marianne": {"pos":"n.f. 阴性专有名词（人名，也是象征）","s":"玛丽安娜：法兰西共和国的拟人象征，常见为戴弗里吉亚帽的女性头像，出现在市政厅、邮票和硬币上。也是常见女名。","ipa":"[ma.ʁjan]","ph":"ma [ma]；r 小舌音 [ʁ]；ia 读 [ja]；nn 读一个 [n]；结尾 e 不发音。","pi":"nn 只读一个 [n]；结尾 e 不发音；ia 读 [ja]。","et":"名字由 Marie 和 Anne 组合而来，是 18 世纪常见的女名；成为共和国象征，与法国大革命相关。","ex":[["Marianne est le symbole de la République française.","玛丽安娜是法兰西共和国的象征。"],["Le buste de Marianne se trouve dans toutes les mairies.","所有市政厅里都有玛丽安娜的半身像。"]],"co":[["le buste de Marianne","玛丽安娜半身像"],["un symbole de la République","共和国的象征"],["le bonnet phrygien","弗里吉亚帽"],["une mairie","市政厅"]],"sy":[["la République","courant","共和国"],["le coq gaulois","courant","高卢雄鸡（另一个象征）"],["le drapeau tricolore","courant","三色旗"]],"fq":"中频，法国文化。","me":"Marianne = Marie + Anne：共和国的「脸」。","tr":{"zh":"你在市政厅里能看到玛丽安娜。","fr":"On peut voir Marianne à la mairie.","alt":"Marianne est dans toutes les mairies.","note":"on peut + 不定式：能够。"}},
 "Une \"grande école\" (école d'ingénieur, école de commerce)": {"pos":"n.f. 阴性名词，复数 grandes écoles","s":"法国的精英高等院校，如工程师学校、商学院、高等师范学校。要通过选拔考试（concours）才能进，通常先读两年预备班。和普通大学 université 不同。","ipa":"[gʁɑ̃d.e.kɔl]","ph":"grande 读 [gʁɑ̃d]，an 鼻化，d 要发音，词尾 e 不发音；école 读 [e.kɔl]，é [e]，ole 里 o 读 [ɔ]。","pi":"grande 里 d 要发音；école 读 [e.kɔl]，不是 [ɛ.kol]。注意 grande école 是阴性：une grande école。","et":"école 来自拉丁语 schola（学校），源自希腊语 skholē（闲暇、学习）。grande = 大的。","ex":[["Il prépare le concours pour entrer dans une grande école.","他备考进入一所大学校。"],["Elle est ingénieure, diplômée d'une grande école.","她是工程师，毕业于一所大学校。"]],"co":[["entrer dans une grande école","进入大学校"],["une école d'ingénieur","工程师学校"],["une école de commerce","商学院"],["passer un concours","参加选拔考试"]],"sy":[["université","courant","综合大学，入学相对不用考试选拔"],["école supérieure","courant","高等专业学院"]],"fq":"中频，谈教育时常用。","me":"grande école = 「大学校」：先过竞考（concours）这道窄门。","tr":{"zh":"他想考进一所大学校。","fr":"Il veut entrer dans une grande école.","alt":"Il vise une grande école.","note":"entrer dans + 学校；viser = 瞄准（口语）。"}},
 "Une allégorie": {"pos":"n.f. 阴性名词，复数 allégories","s":"寓意；象征性的形象。用一个人物或画面来表示抽象概念，如天平象征正义。常用于艺术、文学。","ipa":"[a.le.gɔ.ʁi]","ph":"é [e]；g 在 o 前读 [g]；r 是小舌音；词尾 ie 读 [i]。","pi":"g 读 [g]，不是 [ʒ]；重音在最后一个音节 -ri。","et":"来自希腊语 allêgoria，由 allos（别的）+ agoreuein（说）构成，字面是「用别的方式说」。","ex":[["Cette statue est une allégorie de la liberté.","这座雕像是自由的象征。"],["Le poème est une allégorie de la vie.","这首诗是对人生的寓意。"]],"co":[["une allégorie de + 抽象名词","……的象征"],["sous forme d'allégorie","以寓意的形式"],["une allégorie politique","政治寓意"]],"sy":[["symbole","courant","象征，更常见、更宽泛"],["métaphore","courant","隐喻，是一种修辞，范围更小"]],"fq":"中低频，多用于艺术和文学。","me":"alle(autre) + gorie(parler)：用「另一种说法」讲道理。","tr":{"zh":"这幅画是和平的象征。","fr":"Ce tableau est une allégorie de la paix.","alt":"Ce tableau symbolise la paix.","note":"une allégorie de + 概念；动词 symboliser 更口语。"}},
 "Une attestation": {"pos":"n.f. 阴性名词，复数 attestations","s":"证明（文件）。由学校、公司或机关开出的书面证明，如在读证明、工作证明。比 certificat 更偏「证实某件事」。","ipa":"[a.tɛs.ta.sjɔ̃]","ph":"tt 读一个 [t]；es [ɛs]；-tion 读 [sjɔ̃]；结尾 on 鼻化，不发 n。","pi":"-tion 读 [sjɔ̃]，不是 [tjɔ̃]；最后的 n 不发音。","et":"来自动词 attester（证实），拉丁语 attestari（ad- + testari 作证）。同源：témoin（见证人）、testament。","ex":[["Le secrétariat m'a délivré une attestation de réussite.","办公室给我开了一张通过证明。"],["J'ai besoin d'une attestation de travail.","我需要一张工作证明。"]],"co":[["délivrer une attestation","开具证明"],["une attestation de domicile","住址证明"],["une attestation sur l'honneur","声明书（自己保证属实）"],["demander une attestation","申请证明"]],"sy":[["certificat","courant","证书，如医疗证明、毕业证书"],["justificatif","courant","证明材料、凭证"]],"fq":"中频，办手续时很常用。","me":"attester（证实）+ -ation：一张「证实」的纸。","tr":{"zh":"请给我开一张住址证明。","fr":"Pouvez-vous me délivrer une attestation de domicile ?","alt":"Il me faut une attestation de domicile, s'il vous plaît.","note":"délivrer 比 donner 正式；Il me faut = 我需要。"}},
 "Une bourse": {"pos":"n.f. 阴性名词，复数 bourses","s":"奖学金；助学金（une bourse d'études）。另有两个意思：la Bourse = 证券交易所，股市；une bourse = 钱包（小钱袋，较旧）。","ipa":"[buʁs]","ph":"ou [u]；r 是小舌音；s 要发 [s]，e 不发音。","pi":"ou 读 [u]，类似汉语「乌」；结尾 -rse 读 [ʁs]，s 要发音。区分 bourse（奖学金）和 la Bourse（股市）。","et":"来自中世纪拉丁语 bursa（皮袋），再源于希腊语 byrsa（兽皮）。最初指钱袋，后来指发给人的钱。","ex":[["Elle a demandé une bourse d'études pour financer son master.","她申请奖学金支付硕士学费。"],["Il a perdu de l'argent à la Bourse.","他在股市亏了钱。"]],"co":[["obtenir une bourse","获得奖学金"],["une bourse d'études","奖学金"],["demander une bourse","申请奖学金"],["la Bourse de Paris","巴黎证券交易所"]],"sy":[["aide financière","courant","经济资助"],["subvention","courant","补贴，多给机构或项目"]],"fq":"高频，教育话题中很常用。","me":"bourse 原是装钱的小皮袋：从袋里拿钱给学生。","tr":{"zh":"他拿到了一笔奖学金。","fr":"Il a obtenu une bourse.","alt":"Il a décroché une bourse.","note":"décrocher = 拿到（口语）。"}},
 "Une deuxième chance": {"pos":"n.f. 阴性名词词组，复数 deuxièmes chances","s":"第二次机会。指失败后重新来过的机会，如考试补考、重新开始。deuxième 和 second 都可用。","ipa":"[dø.zjɛm ʃɑ̃s]","ph":"deuxième 里 x 读 [z]；ième 读 [jɛm]；chance 的 ch [ʃ]，an [ɑ̃]，c 读 [s]，e 不发音。","pi":"deuxième 的 x 读 [z]，不是 [ks]；chance 不是英语 [tʃ] 的音，读 [ʃ]。","et":"deux（二）+ -ième 序数后缀；chance 来自古法语 cheance，源于拉丁语 cadentia（掉落、骰子落下）。","ex":[["Cette école offre une deuxième chance aux élèves en difficulté.","这所学校给困难学生第二次机会。"],["Je veux donner une deuxième chance à notre projet.","我想给我们的项目第二次机会。"]],"co":[["donner une deuxième chance","给第二次机会"],["avoir une deuxième chance","有第二次机会"],["la seconde chance","第二次机会（较正式）"],["saisir sa chance","抓住机会"]],"sy":[["seconde chance","soutenu","同义，second 更书面"],["nouvelle chance","courant","新的机会"]],"fq":"中频，日常常用。","me":"deux + chance：失败后的「再来一次」。","tr":{"zh":"每个人都应该有第二次机会。","fr":"Tout le monde mérite une deuxième chance.","alt":"Chacun devrait avoir une deuxième chance.","note":"tout le monde 后动词用单数；mériter = 值得拥有。"}},
 "Une distinction": {"pos":"n.f. 阴性名词，复数 distinctions","s":"荣誉；奖项；勋章（recevoir une distinction）。另一意思是「区别、区分」（faire une distinction entre A et B），还有「优雅、气质」。","ipa":"[dis.tɛ̃k.sjɔ̃]","ph":"in [ɛ̃] 鼻化；c 读 [k]；-tion 读 [sjɔ̃]；结尾 on 鼻化。","pi":"distinction 中 c 要发 [k]，与 nct 相连；-tion 读 [sjɔ̃]；不要把 in 读成 [in]。","et":"来自拉丁语 distinctio，动词 distinguere（区分）。同源：distinguer、distinct。","ex":[["Il a reçu une distinction pour ses travaux de recherche.","他因研究成果获得荣誉。"],["Il faut faire une distinction entre ces deux mots.","要区分这两个词。"]],"co":[["recevoir une distinction","获得荣誉"],["faire la distinction entre A et B","区分 A 和 B"],["sans distinction","不加区别地"],["une distinction honorifique","荣誉称号"]],"sy":[["récompense","courant","奖励，更宽泛"],["différence","courant","区别，表示「区分」时可替换"]],"fq":"中频，书面和正式场合较多。","me":"distinguer（区分）→ 把一个人「区分出来」→ 给他荣誉。","tr":{"zh":"她因工作成绩获得荣誉。","fr":"Elle a reçu une distinction pour son travail.","alt":"On lui a décerné une distinction pour son travail.","note":"décerner = 授予（正式）。"}},
 "Une enquête": {"pos":"n.f. 阴性名词，复数 enquêtes","s":"调查。可以是警察的侦查（une enquête de police）、记者的调查报道，也可以是问卷调查（une enquête auprès de 1000 personnes）。","ipa":"[ɑ̃.kɛt]","ph":"en 读鼻化 [ɑ̃]；ê [ɛ]；-quête 里 qu 读 [k]；结尾 e 不发音，t 要发。","pi":"en 是鼻元音，不要发出 n；ê 带扬抑符，读 [ɛ]；qu 读 [k]。","et":"来自拉丁语 inquaesita（被查问的事），动词 inquirere（调查）。同源：enquêter、quête。","ex":[["Le journal a publié une enquête sur les universités.","报纸发表了一篇关于大学的调查。"],["La police ouvre une enquête.","警方展开调查。"]],"co":[["mener une enquête","进行调查"],["ouvrir une enquête","立案调查"],["une enquête de satisfaction","满意度调查"],["enquêter sur","调查……"]],"sy":[["sondage","courant","民意调查，通常很简短"],["investigation","soutenu","深入调查，较书面"]],"fq":"高频，新闻里常见。","me":"en + quête（寻找）：去「寻找」真相。","tr":{"zh":"警方正在调查这件事。","fr":"La police mène une enquête sur cette affaire.","alt":"La police enquête sur cette affaire.","note":"mener une enquête = enquêter。"}},
 "Une formation en alternance": {"pos":"n.f. 阴性名词词组，复数 formations en alternance","s":"工学交替培训：一部分时间在学校上课，一部分时间在企业工作，通常有合同和工资（contrat d'apprentissage 或 de professionnalisation）。口语常简称 alternance。","ipa":"[fɔʁ.ma.sjɔ̃ ɑ̃.nal.tɛʁ.nɑ̃s]","ph":"formation 读 [fɔʁ.ma.sjɔ̃]；en 与 alternance 之间读 [ɑ̃.nal...]（en 后接元音，仍读 [ɑ̃]，再与 a 相连）；-ance 读 [ɑ̃s]。","pi":"-tion 读 [sjɔ̃]；alternance 结尾 -ance 读 [ɑ̃s]，e 不发音；en 后没有 n 的音，但连读时听起来像 [ɑ̃n]。","et":"formation 来自动词 former（拉丁语 formare，塑造）；alternance 来自 alterner，拉丁语 alternare（轮流）。","ex":[["Il a choisi une formation en alternance pour acquérir de l'expérience.","他选择了工学交替培训来积累经验。"],["Elle est en alternance dans une banque.","她在一家银行做工学交替。"]],"co":[["être en alternance","处于工学交替培训中"],["un contrat en alternance","交替培训合同"],["faire son master en alternance","以工学交替方式读硕士"],["un(e) alternant(e)","交替培训学员"]],"sy":[["apprentissage","courant","学徒制，常指职业教育"],["alternance","courant","简称，更口语"]],"fq":"中频，在法国高等教育和求职话题中很常见。","me":"alterner：一周学校，一周公司，轮流来。","tr":{"zh":"我想做工学交替培训。","fr":"Je voudrais faire une formation en alternance.","alt":"Je veux faire de l'alternance.","note":"faire de l'alternance 是口语说法。"}},
 "Une fouille": {"pos":"n.f. 阴性名词，复数 fouilles","s":"挖掘；发掘（考古常用复数 les fouilles）；也指搜查、搜身（la fouille des bagages）。","ipa":"[fuj]","ph":"f-ou-ille：ou [u]，-ille 读 [j]，整体只有一个音节 [fuj]；结尾 e 不发音。","pi":"-ille 里 ll 读 [j]，不是 [l]：fouille 不是 [fu.lə]。考古场景常用复数 les fouilles。","et":"来自动词 fouiller（挖、翻找），与 fouir（挖掘）有关，拉丁语 fodere（挖）。","ex":[["Une fouille a permis de trouver des objets anciens.","一次发掘找到了古代物品。"],["Les fouilles archéologiques durent depuis trois ans.","考古发掘已经持续三年了。"]],"co":[["des fouilles archéologiques","考古发掘"],["faire des fouilles","进行发掘"],["la fouille des bagages","行李检查"],["fouiller dans un sac","翻包"]],"sy":[["excavation","soutenu","挖掘，较书面、技术性"],["perquisition","soutenu","（警方）搜查住所"]],"fq":"中频，考古和警务话题常见。","me":"fouille 读 [fuj]：「呼」一声挖开土。","tr":{"zh":"考古学家正在这个地方发掘。","fr":"Les archéologues font des fouilles sur ce site.","alt":"Les archéologues fouillent ce site.","note":"fouiller 可直接接地点作宾语。"}},
 "Une mention (bien, très bien, ...)": {"pos":"n.f. 阴性名词，复数 mentions","s":"毕业或考试的荣誉等级：mention assez bien（及格偏上）、bien（良）、très bien（优）。另有「提及；注明」的意思：faire mention de。","ipa":"[mɑ̃.sjɔ̃]","ph":"men 读鼻化 [mɑ̃]；-tion 读 [sjɔ̃]；结尾 on 鼻化，不发 n。","pi":"men- 读 [mɑ̃]，不读 [mɛ̃]；-tion 读 [sjɔ̃]。","et":"来自拉丁语 mentio（提及）。同族：mentionner。","ex":[["Elle a obtenu son bac avec mention \"très bien\".","她以「优」的成绩通过了高考。"],["Il n'y a aucune mention de ce sujet.","没有提到这个话题。"]],"co":[["avoir une mention","获得荣誉等级"],["avec mention très bien","以优等成绩"],["faire mention de","提到"],["mention passable","及格"]],"sy":[["appréciation","courant","评语、评价"],["mentionner","courant","提及（动词）"]],"fq":"中频，谈考试和文凭时常用。","me":"mention ≈ 给成绩「点个名」：bien、très bien。","tr":{"zh":"她以优等成绩拿到了毕业会考文凭。","fr":"Elle a eu son bac avec mention très bien.","alt":"Elle a décroché son bac avec mention très bien.","note":"avoir son bac = 通过高中毕业会考。"}},
 "Une mesure": {"pos":"n.f. 阴性名词，复数 mesures","s":"措施；办法（prendre des mesures）；尺寸、测量（la mesure d'une table）；分寸、适度。sur mesure = 量身定做。","ipa":"[mə.zyʁ]","ph":"me 的 e 读弱音 [ə]；s 在元音间读 [z]；u 读 [y]；r 是小舌音。","pi":"s 读 [z]，不是 [s]；u 读 [y]（嘴圆，发「衣」的音），不是 [u]。","et":"来自拉丁语 mensura（测量），动词 metiri（量）。同源：mesurer。","ex":[["L'administration a pris des mesures pour lutter contre la triche.","校方采取措施打击作弊。"],["Ce costume est fait sur mesure.","这套西装是量身定做的。"]],"co":[["prendre des mesures","采取措施"],["sur mesure","量身定做"],["dans la mesure du possible","尽可能"],["au fur et à mesure","随着、逐步"]],"sy":[["disposition","soutenu","规定、措施（官方）"],["démarche","courant","办法、手续"]],"fq":"极高频，新闻和日常都很常用。","me":"mesure：量一量再决定怎么做，所以是「措施」。","tr":{"zh":"政府采取了新的措施。","fr":"Le gouvernement a pris de nouvelles mesures.","alt":"Le gouvernement a pris des mesures.","note":"prendre des mesures = 采取措施。"}},
 "Une qualification": {"pos":"n.f. 阴性名词，复数 qualifications","s":"资格；职业能力（avoir une qualification）；也指体育比赛里的「晋级」（la qualification pour la finale）。","ipa":"[ka.li.fi.ka.sjɔ̃]","ph":"qu 读 [k]；-tion 读 [sjɔ̃]；结尾 on 鼻化；每个音节都清楚，重音在最后。","pi":"qu 读 [k]，不读 [kw]；-tion 读 [sjɔ̃]。","et":"来自动词 qualifier（使具有某种性质），拉丁语 qualis（怎样的）+ facere（做）。","ex":[["Il a obtenu une qualification professionnelle reconnue dans tout le pays.","他获得了全国认可的职业资格。"],["L'équipe a gagné sa qualification pour la finale.","球队获得了决赛资格。"]],"co":[["avoir une qualification","具备资格"],["une qualification professionnelle","职业资格"],["un manque de qualification","缺乏资格"],["la qualification pour la finale","晋级决赛"]],"sy":[["compétence","courant","能力"],["diplôme","courant","文凭"]],"fq":"中频，工作和教育话题常见。","me":"qualifié（合格的）+ -ation：拥有的「品质」。","tr":{"zh":"这份工作需要专业资格。","fr":"Ce poste demande une qualification professionnelle.","alt":"Pour ce poste, il faut une qualification.","note":"demander = 要求；il faut + 名词 = 需要。"}},
 "Une remise à niveau": {"pos":"n.f. 阴性名词词组，复数 remises à niveau","s":"补习；进修，把已有水平补到要求的水平。常用于开学前补课或重返学习、工作前的短期培训。","ipa":"[ʁə.miz a ni.vo]","ph":"remise 的 s 读 [z]；à 单独读 [a]；niveau 的 eau 读 [o]。remise 与 à 之间读 [ʁə.mi.za]。","pi":"remise 的 s 读 [z]，不是 [s]；niveau 的 -eau 读 [o]。","et":"remise（放回，源自 remettre）+ à niveau（达到标准）。niveau 来自古法语 livel，拉丁语 libella（水平仪）。","ex":[["Il suit une remise à niveau en mathématiques avant la rentrée.","开学前他上数学补习班。"],["Elle fait une remise à niveau en anglais.","她在补英语。"]],"co":[["suivre une remise à niveau","参加补习"],["une remise à niveau en + 科目","某科目补习"],["remettre à niveau","使达到标准"],["mise à niveau","升级（同义，也用于电脑）"]],"sy":[["rattrapage","courant","补课、补考"],["mise à niveau","courant","同义说法"]],"fq":"中低频，教育话题常见。","me":"remise à niveau = 把水位「重新放回」标准线。","tr":{"zh":"我需要补一下数学。","fr":"J'ai besoin d'une remise à niveau en maths.","alt":"Il me faut une remise à niveau en maths.","note":"maths 是 mathématiques 的口语简称。"}},
 "Une spécialité": {"pos":"n.f. 阴性名词，复数 spécialités","s":"专业方向；专长；特色菜或特产（une spécialité régionale）。法国高中会考有 spécialités（选修专业方向）。","ipa":"[spe.sja.li.te]","ph":"sp 连读 [sp]；é [e]；-cia- 读 [sja]；结尾 é 读 [e]。","pi":"c 在 i 前读 [s]；重音在最后一个音节 -té；词尾 -ité 读 [ite]。","et":"来自拉丁语 specialitas，形容词 specialis（特别的），species（种类）。同源：spécial、spécialiste。","ex":[["Au lycée, il a choisi la spécialité mathématiques.","高中时他选了数学专业方向。"],["Le couscous est la spécialité de ce restaurant.","库斯库斯是这家餐厅的招牌菜。"]],"co":[["choisir une spécialité","选专业方向"],["une spécialité régionale","地方特产"],["la spécialité de la maison","本店招牌"],["se spécialiser en","专攻"]],"sy":[["domaine","courant","领域"],["filière","courant","学科方向"]],"fq":"高频，教育和餐饮话题都常用。","me":"spécial + -ité：「特别」的那一项。","tr":{"zh":"你选了什么专业方向？","fr":"Quelle spécialité as-tu choisie ?","alt":"T'as choisi quelle spécialité ?","note":"宾语在前，过去分词 choisie 要加 e 配合。"}},
 "Une subvention": {"pos":"n.f. 阴性名词，复数 subventions","s":"补贴；资助。政府或机构给协会、企业、项目的钱（accorder une subvention）。不是个人的奖学金（那是 bourse）。","ipa":"[syb.vɑ̃.sjɔ̃]","ph":"su 读 [sy]，b 读 [b]，音节 syb-vɑ̃-sjɔ̃；ven 读鼻化 [vɑ̃]；-tion 读 [sjɔ̃]。","pi":"sub- 里 u 读 [y]，不是 [ʌ]；ven 读 [vɑ̃]，不读 [vɛ̃]。","et":"来自拉丁语 subventio（援助），动词 subvenire（sub- 下面 + venire 来，赶来帮助）。同源：subventionner。","ex":[["L'université a reçu une subvention pour financer ce projet.","大学获得资助来支持这个项目。"],["La mairie accorde une subvention à l'association.","市政府给协会发放补贴。"]],"co":[["accorder une subvention","发放补贴"],["recevoir une subvention","获得资助"],["demander une subvention","申请补贴"],["subventionner un projet","资助一个项目"]],"sy":[["aide","courant","帮助、援助"],["financement","courant","出资、资金"]],"fq":"中频，新闻和行政话题较常见。","me":"sub(下面) + venir(来)：钱从下面「赶来帮忙」。","tr":{"zh":"这个协会得到了市政府的补贴。","fr":"L'association a reçu une subvention de la mairie.","alt":"La mairie a donné une subvention à l'association.","note":"de la mairie 说明来源；mairie 是阴性。"}},
 "Une tâche": {"pos":"n.f. 阴性名词，复数 tâches","s":"任务；工作（一项具体的事）：les tâches ménagères = 家务。注意和 une tache（污点）区别，只差一个扬抑符。","ipa":"[tɑʃ]","ph":"â 读长音 [ɑ]；ch 读 [ʃ]；结尾 e 不发音。","pi":"tâche（任务）与 tache（污点）拼写读音接近：tâche 有 â，读 [tɑʃ]，tache 读 [taʃ]。","et":"来自古法语 tasche，与 taxe（税、定额）同源。意思是「规定要完成的工作」。","ex":[["Le manager répartit les tâches dans l'équipe.","经理在团队里分配任务。"],["Les tâches ménagères prennent du temps.","家务要花时间。"]],"co":[["accomplir une tâche","完成一项任务"],["répartir les tâches","分配任务"],["les tâches ménagères","家务"],["une tâche difficile","一项艰巨的任务"]],"sy":[["mission","courant","使命、差事"],["travail","courant","工作，更宽泛"],["corvée","familier","苦差事、讨厌的活"]],"fq":"高频，工作和家庭里常用。","me":"tâche 有帽子 â：背着帽子干活的「任务」；tache 没帽子=污点。","tr":{"zh":"我们要分一下任务。","fr":"Nous devons répartir les tâches.","alt":"On doit se partager les tâches.","note":"se partager = 彼此分担；on 在口语里相当于 nous。"}},
 "Une thèse": {"pos":"n.f. 阴性名词，复数 thèses","s":"博士论文（écrire / soutenir une thèse）；也指论点、观点（la thèse de l'auteur）。硕士论文常称 mémoire，不叫 thèse。","ipa":"[tɛz]","ph":"th 读 [t]，h 不发音；è [ɛ]；s 在 è 后读 [z]；结尾 e 不发音。","pi":"th 读 [t]，不是英语的 [θ]；结尾 se 读 [z]。thèse 的 è 带抑音符。","et":"来自希腊语 thesis（放置、论点），动词 tithenai（放置）。同源：synthèse、hypothèse。","ex":[["Il rédige sa thèse sur l'intelligence artificielle.","他在写人工智能方面的论文。"],["Elle soutiendra sa thèse en juin.","她将在六月答辩博士论文。"]],"co":[["rédiger une thèse","撰写论文"],["soutenir une thèse","答辩博士论文"],["un directeur de thèse","博士导师"],["défendre une thèse","提出并捍卫一个观点"]],"sy":[["mémoire","courant","硕士论文或毕业论文"],["dissertation","courant","课堂作文式的论述"]],"fq":"中频，学术话题里常见。","me":"thèse = 把一个观点「放」在桌上，然后去证明它。","tr":{"zh":"她正在写博士论文。","fr":"Elle écrit sa thèse.","alt":"Elle est en train de rédiger sa thèse.","note":"être en train de = 正在做。"}},
 "Les classes préparatoires (classe prépa)": {"pos":"n.f.pl. 阴性复数名词，单数 classe préparatoire","s":"预备班，简称 prépa，通常两年，为考大学校（grandes écoles）做准备，学习压力大、内容密集。","ipa":"[klas pʁe.pa.ʁa.twaʁ]","ph":"classes 的 -es 不发音，a 读 [a]；préparatoires 读 [pʁe.pa.ʁa.twaʁ]；oi 读 [wa]；结尾 -res 不发音。","pi":"classes 结尾 s 不发音；préparatoires 的 oi 读 [wa]，r 是小舌音；常说 prépa（[pʁe.pa]）。","et":"classe 来自拉丁语 classis（等级、班）；préparatoire 来自 préparer，拉丁语 praeparare（预先准备）。","ex":[["Il a passé deux ans en classe prépa pour préparer les concours.","他读了两年预科准备竞考。"],["Elle entre en classe préparatoire après le bac.","她高中毕业后进预备班。"]],"co":[["être en prépa","在读预备班"],["intégrer une prépa","进入预备班"],["une prépa scientifique","理科预备班"],["les classes préparatoires aux grandes écoles","大学校预备班"]],"sy":[["prépa","familier","预备班的简称"],["CPGE","courant","正式缩写（classes préparatoires aux grandes écoles）"]],"fq":"中频，谈法国教育时必会。","me":"prépa = préparatoire：为「大门」做准备的两年。","tr":{"zh":"他在读预备班。","fr":"Il est en classe prépa.","alt":"Il fait une prépa.","note":"être en + 班级；faire une prépa 也很常见。"}},
 "Les études supérieures": {"pos":"n.f.pl. 阴性复数名词，单数 étude supérieure（极少用）","s":"高等教育；大学阶段的学习，指高中毕业之后的所有学业（大学、大学校等）。études 通常用复数；faire des études = 求学。","ipa":"[e.tyd sy.pe.ʁjœʁ]","ph":"études 读 [e.tyd]，é [e]，u [y]，d 要发音，结尾 -es 不发音；supérieures 读 [sy.pe.ʁjœʁ]，eu 读 [œ]。","pi":"études 的 d 要发音；supérieures 里 eu 读 [œ]，不是 [ø]；结尾 -ures 不发音。","et":"étude 来自拉丁语 studium（热心、学习）；supérieur 来自拉丁语 superior（更高的），super（在上）。","ex":[["Les études supérieures demandent beaucoup d'autonomie.","高等教育需要很强的自主性。"],["Il veut faire des études supérieures à Lyon.","他想在里昂读大学。"]],"co":[["faire des études supérieures","接受高等教育"],["poursuivre ses études","继续学业"],["arrêter ses études","中断学业"],["l'enseignement supérieur","高等教育"]],"sy":[["enseignement supérieur","courant","高等教育（体系）"],["fac","familier","大学（faculté 的简称）"]],"fq":"高频，教育话题常用。","me":"études 复数：学习是一连串的事，所以用复数。","tr":{"zh":"她想继续读高等教育。","fr":"Elle veut poursuivre des études supérieures.","alt":"Elle veut continuer ses études après le bac.","note":"études 总用复数；poursuivre = 继续。"}},
 "Un bachelier / Une bachelière": {"pos":"n.m./n.f. 名词，阳性 bachelier，阴性 bachelière；复数 bacheliers / bachelières","s":"高中毕业会考（baccalauréat）的通过者，即刚拿到 bac 的高中毕业生。多用于统计和新闻中：les nouveaux bacheliers。","ipa":"[baʃ.ə.lje] / [baʃ.ə.ljɛʁ]","ph":"ch 读 [ʃ]；e 读弱音 [ə]，有时省略；阳性词尾 -ier 读 [je]，阴性 -ière 读 [jɛʁ]（r 要发）。","pi":"ch 读 [ʃ]，不是 [k]；阳性结尾 r 不发音，阴性 -ière 的 r 要发音。","et":"来源不确定（中世纪指年轻骑士或见习者）；同一词族：bac、baccalauréat。","ex":[["Les nouveaux bacheliers célèbrent la fin du lycée.","新的高中毕业生庆祝中学生活结束。"],["Cette bachelière a obtenu la mention très bien.","这位女毕业生拿到了优等成绩。"]],"co":[["un bachelier de + 年份","某年的会考毕业生"],["les nouveaux bacheliers","应届高中毕业生"],["une bachelière brillante","优秀的女毕业生"]],"sy":[["lycéen","courant","高中生（还没毕业）"],["étudiant","courant","大学生"]],"fq":"中低频，教育统计和新闻里多见。","me":"bac → bachelier：拿到 bac 的人。","tr":{"zh":"今年有很多新的高中毕业生。","fr":"Il y a beaucoup de nouveaux bacheliers cette année.","alt":"Cette année, les bacheliers sont nombreux.","note":"女性用 bachelières；混合用阳性复数。"}},
 "Un boursier / Une boursière": {"pos":"n.m./n.f. 名词，阳性 boursier，阴性 boursière；复数 boursiers / boursières","s":"奖学金（助学金）获得者。也可作形容词：un étudiant boursier。另一意思是「证券交易所的」：le marché boursier（股市）。","ipa":"[buʁ.sje] / [buʁ.sjɛʁ]","ph":"ou [u]；s 在辅音 r 后读 [s]；阳性 -ier 读 [je]，阴性 -ière 读 [jɛʁ]。","pi":"阳性词尾 r 不发音，阴性 -ière 的 r 要发音；ou 读 [u]。","et":"来自 bourse（钱袋；奖学金）+ -ier（表示从事者）。","ex":[["En tant que boursier, il bénéficie d'une aide mensuelle.","作为奖学金生，他每月获得补助。"],["Cette boursière étudie à Paris grâce à l'État.","这位女奖学金生靠国家资助在巴黎读书。"]],"co":[["un étudiant boursier","奖学金生"],["être boursier","领奖学金"],["un boursier du gouvernement","政府奖学金生"]],"sy":[["bénéficiaire","courant","受益人"],["étudiant aidé","courant","受资助的学生"]],"fq":"中频，教育话题里常见。","me":"bourse + -ier：拿 bourse 的人。","tr":{"zh":"她是奖学金生。","fr":"Elle est boursière.","alt":"Elle a une bourse.","note":"职业或身份名词作表语时不加冠词。"}},
 "Un dieu / Une déesse": {"pos":"n.m./n.f. 名词，阳性 dieu（复数 dieux），阴性 déesse（复数 déesses）","s":"神；女神。指神话里的神，如希腊诸神。Dieu（大写）= 一神教的上帝。常用感叹：Mon Dieu ! = 天哪！","ipa":"[djø] / [de.ɛs]","ph":"dieu 读 [djø]，ieu 是 [jø]；déesse 读 [de.ɛs]，é [e] 与 e [ɛ] 分开读，ss 读 [s]。","pi":"dieu 的复数 dieux 读音相同，x 不发音；déesse 中 é 和 e 是两个音节。","et":"dieu 来自拉丁语 deus，déesse 由拉丁语 dea + 后缀 -esse 构成。","ex":[["Athéna est la déesse de la sagesse dans la mythologie.","雅典娜是神话中的智慧女神。"],["Les Grecs adoraient plusieurs dieux.","希腊人崇拜多位神。"]],"co":[["Mon Dieu !","天哪！"],["un dieu grec","希腊神"],["Dieu merci !","谢天谢地！"],["la déesse de l'amour","爱神"]],"sy":[["divinité","soutenu","神灵，较正式"],["idole","courant","偶像"]],"fq":"高频，文化和宗教话题常见。","me":"dieu 读 [djø]，像「爹吾」；déesse = dieu 的阴性。","tr":{"zh":"维纳斯是爱神。","fr":"Vénus est la déesse de l'amour.","alt":"Vénus, c'est la déesse de l'amour.","note":"神话人物前用定冠词；女神用 déesse。"}},
 "Un(e) archéologue": {"pos":"n.m./n.f. 名词，阴阳同形，复数 archéologues","s":"考古学家。阴阳性同形：un archéologue（男）/ une archéologue（女），只靠冠词区分。","ipa":"[aʁ.ke.ɔ.lɔg]","ph":"ch 读 [k]；é [e]；o 读 [ɔ]；g 在词尾读 [g]；结尾 ue 里 u 不发音，e 不发音。","pi":"arché- 里 ch 读 [k]，不是 [ʃ]；-gue 读 [g]，不读 [ʒ]。","et":"由希腊语 arkhaios（古老的）+ logos（学问）构成，与 archéologie 同族。","ex":[["L'archéologue a découvert une tombe romaine.","考古学家发现了一座罗马墓。"],["Cette archéologue travaille en Égypte.","这位女考古学家在埃及工作。"]],"co":[["un archéologue amateur","业余考古学家"],["une équipe d'archéologues","考古队"],["le travail d'un archéologue","考古工作"]],"sy":[["historien","courant","历史学家，研究历史文献"],["chercheur","courant","研究员"]],"fq":"中低频，文化类话题中出现。","me":"archéo（古）+ logue（学者）：研究古物的人。","tr":{"zh":"考古学家在沙漠里工作。","fr":"L'archéologue travaille dans le désert.","alt":"L'archéologue bosse dans le désert.","note":"bosser 是口语，意思是「干活」。"}},
 "Un(e) bourgeois(e)": {"pos":"n.m./n.f. 名词，阳性 bourgeois，阴性 bourgeoise；复数 bourgeois / bourgeoises","s":"资产阶级人士；中产或富裕阶层的人，法国历史上指城镇里有产者。常带贬义（有钱但保守的人）。也作形容词：une famille bourgeoise。","ipa":"[buʁ.ʒwa] / [buʁ.ʒwaz]","ph":"ou [u]；g 在 e 前读 [ʒ]；eoi 里 e 不发音，oi 读 [wa]；阴性 -oise 读 [waz]。","pi":"bourgeois 的 g 读 [ʒ]；阳性 s 不发音，阴性 -oise 的 s 要发 [z]。","et":"由 bourg（有城墙的小镇）+ -ois 构成；bourg 来自晚期拉丁语 burgus（要塞），借自日耳曼语。","ex":[["Ce roman décrit la vie d'une famille bourgeoise au dix-neuvième siècle.","这部小说描写十九世纪一个资产阶级家庭的生活。"],["C'est un quartier de bourgeois.","这是个中产阶层住的街区。"]],"co":[["la petite / grande bourgeoisie","小 / 大资产阶级"],["un quartier bourgeois","中产街区"],["une famille bourgeoise","资产阶级家庭"],["un bourgeois","资产阶级人士"]],"sy":[["riche","courant","有钱人"],["bobo","familier","波波族（bourgeois-bohème）"]],"fq":"中频，历史和社会话题常见。","me":"bourg（城镇）+ -ois：住在城里、有产业的人。","tr":{"zh":"他们是一个资产阶级家庭。","fr":"C'est une famille bourgeoise.","alt":"Ils viennent d'une famille bourgeoise.","note":"bourgeois / bourgeoise 作形容词要配合阴阳性。"}},
 "Un(e) doctorant(e)": {"pos":"n.m./n.f. 名词，阳性 doctorant，阴性 doctorante；复数 doctorants / doctorantes","s":"博士生，正在写博士论文的人。拿到学位后才是 docteur。口语里常说 en thèse。","ipa":"[dɔk.tɔ.ʁɑ̃] / [dɔk.tɔ.ʁɑ̃t]","ph":"o 读 [ɔ]；c 读 [k]；an 读鼻化 [ɑ̃]；阳性 t 不发音，阴性 -ante 的 t 要发 [t]。","pi":"阴性 doctorante 的 t 要发出；doctorant 结尾 an 鼻化，不发 n 和 t。","et":"来自 doctorat（博士学位）+ -ant；docteur 来自拉丁语 doctor（教师），docere（教）。","ex":[["Cette doctorante prépare une thèse sur le climat.","这位博士生在写气候方面的论文。"],["Les doctorants travaillent souvent dans un laboratoire.","博士生常在实验室工作。"]],"co":[["un contrat doctoral","博士合同"],["un doctorant en + 学科","某学科博士生"],["être doctorant","读博士"],["une école doctorale","博士院"]],"sy":[["thésard","familier","博士生（口语）"],["étudiant en thèse","courant","写论文的学生"]],"fq":"中低频，学术话题里出现。","me":"doctorat + -ant：正在读博的人。","tr":{"zh":"她是物理学博士生。","fr":"Elle est doctorante en physique.","alt":"Elle fait un doctorat en physique.","note":"身份名词作表语不加冠词。"}},
 "Un(e) immigré(e)": {"pos":"n.m./n.f. 名词，阳性 immigré，阴性 immigrée；复数 immigrés / immigrées","s":"移民；在外国定居的人。也可作形容词。与 émigré（从本国移出的人）相对：immigré 是从目的国角度看。","ipa":"[i.mi.gʁe]","ph":"两个 i 分开读 [i.mi]；g 读 [g]；é [e]；阴性 -ée 读音相同。","pi":"g 在 r 前读 [g]；immigré 和 émigré 只差一个字母，意思不同：到达 vs 离开。","et":"来自拉丁语 immigrare（in 进入 + migrare 迁移）。同源：migration、émigrer。","ex":[["Cette association propose des cours de français pour les personnes immigrées.","这个协会为移民提供法语课。"],["Son père est un immigré italien.","他父亲是意大利移民。"]],"co":[["un immigré italien","意大利移民"],["les personnes immigrées","移民人群"],["l'immigration","移民（现象）"],["immigrer en France","移民到法国"]],"sy":[["émigré","courant","移出者，与 immigré 视角相反"],["migrant","courant","迁移者，更宽泛"]],"fq":"高频，新闻和社会话题常见。","me":"im-（进）：immigré 是「进来」的人；é-（出）。","tr":{"zh":"她的祖父是移民。","fr":"Son grand-père est un immigré.","alt":"Son grand-père a immigré en France.","note":"immigrer 是动词，也可以说 est immigré en France。"}},
 "Un(e) individu": {"pos":"n.m. 阳性名词，复数 individus（指男或女都用阳性）","s":"个人；个体。有时带贬义，指不明身份的人：un individu suspect = 可疑人物。在社会学里与 société（社会）相对。","ipa":"[ɛ̃.di.vi.dy]","ph":"in 读鼻化 [ɛ̃]；d [d]；i [i]；v [v]；u 读 [y]。","pi":"in 读 [ɛ̃]，不读 [in]；u 读 [y]；结尾 s（复数）不发音。","et":"来自拉丁语 individuus（不可分割的），in-（不）+ dividere（分）。","ex":[["Chaque individu a sa propre façon d'apprendre.","每个人都有自己的学习方式。"],["La police recherche un individu dangereux.","警方在找一个危险人物。"]],"co":[["un individu suspect","可疑人物"],["l'individu et la société","个人与社会"],["chaque individu","每个人"],["individuel / individuelle","个人的"]],"sy":[["personne","courant","人，最常用、中性"],["type","familier","家伙"],["sujet","soutenu","个体、对象"]],"fq":"中频，书面和新闻里常见。","me":"individu = 不能再分（divisé）的最小单位：一个人。","tr":{"zh":"每个人都有权利发言。","fr":"Chaque individu a le droit de s'exprimer.","alt":"Tout le monde a le droit de s'exprimer.","note":"chaque + 单数名词；avoir le droit de + 动词原形。"}},
 "Un(e) salarié(e)": {"pos":"n.m./n.f. 名词，阳性 salarié，阴性 salariée；复数 salariés / salariées","s":"雇员；领工资的人，与老板（employeur）、自由职业者（indépendant）相对。也作形容词：être salarié。","ipa":"[sa.la.ʁje]","ph":"sa-la-rié：每个音节清楚，结尾 -ié 读 [je]；阴性 -iée 读音相同。","pi":"-ié 读 [je]，不读 [i.e]；结尾的 é 是重读音节，读 [e]。","et":"来自 salaire（工资），拉丁语 salarium（发给士兵买盐的钱），sal（盐）。","ex":[["Chaque salarié de l'entreprise a droit à des congés payés.","公司每位员工都享有带薪休假。"],["Elle est salariée depuis dix ans.","她当了十年雇员。"]],"co":[["un salarié à temps plein","全职雇员"],["devenir salarié","成为雇员"],["les droits des salariés","员工权益"],["un salarié en CDI","无固定期限合同雇员"]],"sy":[["employé","courant","职员，职位较基层"],["travailleur","courant","工人、劳动者"]],"fq":"高频，工作话题里常用。","me":"salarié = 拿 salaire 的人。","tr":{"zh":"我是一家公司的雇员。","fr":"Je suis salarié dans une entreprise.","alt":"Je travaille comme salarié dans une boîte.","note":"boîte 是口语，「公司」。"}},
 "Aboutir": {"pos":"v.i. 不及物动词，第二组（-ir，aboutissant），助动词 avoir","s":"达成；取得结果；导致。常说 aboutir à + 名词/动词原形。没有成功的结果时则用否定：ne pas aboutir（没成）。","ipa":"[a.bu.tiʁ]","ph":"a-bou-tir：ou 读 [u]；结尾 -ir 读 [iʁ]，r 要发音。","pi":"ou 读 [u]；注意第二组变位：il aboutit，nous aboutissons。","et":"由 à + bout（端、头）+ -ir 构成，字面是「到头」。","ex":[["Ses efforts vont bientôt aboutir à un résultat concret.","他的努力很快会有具体成果。"],["Les négociations n'ont pas abouti.","谈判没有成功。"]],"co":[["aboutir à","导致、达到"],["ne pas aboutir","没有成功"],["faire aboutir un projet","使项目成功"],["ça n'aboutira à rien","这没什么用"]],"sy":[["réussir","courant","成功"],["conduire à","courant","通向、导致"],["mener à","courant","通向"]],"fq":"中高频，书面和新闻里常见。","me":"à + bout + ir：走到「头」了，才有结果。","tr":{"zh":"这个项目终于成功了。","fr":"Ce projet a enfin abouti.","alt":"Le projet a fini par aboutir.","note":"aboutir 的复合时态用 avoir。"}},
 "Acquérir": {"pos":"v.t. 及物动词，第三组，不规则，助动词 avoir；j'acquiers，nous acquérons，过去分词 acquis","s":"获得；取得（知识、经验、财产）：acquérir de l'expérience / une maison。比 obtenir 更偏「逐步获得、拥有」。","ipa":"[a.ke.ʁiʁ]","ph":"acqu- 读 [ak]，其中 cq 读一个 [k]；é [e]；结尾 -ir 读 [iʁ]。","pi":"cq 读 [k]，不是 [kk]；变位不规则：j'acquiers，nous acquérons，ils acquièrent，acquis。","et":"来自拉丁语 acquirere（ad- + quaerere 寻求），同源：requérir、conquérir、question。","ex":[["Ce cours aide à acquérir des connaissances solides.","这门课帮助获得扎实的知识。"],["Elle a acquis une petite maison à la campagne.","她在乡下买了一座小房子。"]],"co":[["acquérir de l'expérience","积累经验"],["acquérir des connaissances","获取知识"],["acquérir une maison","购置房子"],["un droit acquis","既得权利"]],"sy":[["obtenir","courant","获得，更一般"],["gagner","courant","赢得"],["se procurer","courant","弄到"]],"fq":"中频，书面和学习话题里常见。","me":"acquérir ≈ 一点点「求」来（quaerere）。","tr":{"zh":"他在这里积累了很多经验。","fr":"Il a acquis beaucoup d'expérience ici.","alt":"Il a pris pas mal d'expérience ici.","note":"acquérir 的过去分词是 acquis；beaucoup de + 名词。"}},
 "Alterner": {"pos":"v.t./v.i. 动词，第一组（-er），助动词 avoir","s":"交替；轮流（alterner A et B）。可及物：alterner les cours et le travail；也可不及物：Les saisons alternent。","ipa":"[al.tɛʁ.ne]","ph":"al [al]；ter 读 [tɛʁ]，r 要发音；结尾 -er 读 [e]，r 不发音。","pi":"中间的 -er- 读 [ɛʁ]，r 要发音；结尾 -er 读 [e]，r 不发音。","et":"来自拉丁语 alternare，alter（另一个）。同源：alternance、alternatif。","ex":[["Son cursus permet d'alterner les cours et le travail en entreprise.","他的课程让上课和企业实践交替进行。"],["Elle alterne entre le français et l'anglais.","她在法语和英语之间切换。"]],"co":[["alterner A et B","让 A 和 B 交替"],["alterner entre A et B","在 A 与 B 之间轮换"],["en alternance","轮流地"],["alterner les couleurs","交替使用颜色"]],"sy":[["se succéder","courant","相继出现"],["tourner","courant","轮流"]],"fq":"中频，多见于书面和教育话题。","me":"alter（另一个）：一个接一个换。","tr":{"zh":"他轮流用两种语言。","fr":"Il alterne entre deux langues.","alt":"Il passe d'une langue à l'autre.","note":"alterner entre A et B。"}},
 "Appréhender": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir","s":"1) 担忧、害怕（appréhender un examen）。2) 理解、把握（appréhender un problème）。3) 逮捕（police）。第一个意思最常见，注意不是「理解」的唯一意思。","ipa":"[a.pʁe.ɑ̃.de]","ph":"ap-pré-hen-der：pp 读一个 [p]；h 不发音；en 读 [ɑ̃]；结尾 -er 读 [e]。","pi":"h 不发音，pré 和 en 是两个音节 [pʁe.ɑ̃]；它常被误当作「理解」，实际多指「担心」。","et":"来自拉丁语 apprehendere（抓住），ad- + prehendere。同源：appréhension（担心）、comprendre。","ex":[["Il appréhende son premier jour dans cette grande université.","他担心在这所大学的第一天。"],["Elle appréhende l'examen de demain.","她担心明天的考试。"]],"co":[["appréhender un examen","担心考试"],["appréhender de + 动词原形","担心做某事"],["appréhender la situation","理解情况"],["appréhender un suspect","逮捕嫌疑人"]],"sy":[["craindre","courant","害怕"],["redouter","soutenu","畏惧"],["comprendre","courant","理解"]],"fq":"中频，书面语较多。","me":"apprendre 的亲戚：「抓住」→ 抓不住就会「担心」。","tr":{"zh":"我有点担心明天的面试。","fr":"J'appréhende un peu l'entretien de demain.","alt":"J'ai un peu peur de l'entretien de demain.","note":"appréhender + 直接宾语；口语可用 avoir peur de。"}},
 "Assimiler": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir","s":"吸收；消化（知识）：assimiler une leçon。另指「同化」（assimiler des immigrés）或「把……等同于」（assimiler A à B）。","ipa":"[a.si.mi.le]","ph":"ss 读 [s]；i [i]；m [m]；l [l]；结尾 -er 读 [e]。","pi":"ss 读 [s]；比较 simuler [si.my.le]，不要混；assimiler 的 ss 不读 [z]。","et":"来自拉丁语 assimilare（使相似），ad- + similis（相似的）。同源：similaire、ressembler。","ex":[["Il faut du temps pour assimiler toutes ces nouvelles connaissances.","需要时间来吸收这些新知识。"],["On ne peut pas assimiler ces deux situations.","不能把这两种情况等同起来。"]],"co":[["assimiler une leçon","掌握一课内容"],["assimiler A à B","把 A 等同于 B"],["s'assimiler à","融入、被同化"],["difficile à assimiler","难以消化"]],"sy":[["absorber","courant","吸收"],["intégrer","courant","融入、纳入"],["digérer","familier","消化（比喻）"]],"fq":"中频，学习话题常用。","me":"as + similar：把新知识变得和自己「相似」，就是吸收。","tr":{"zh":"我很难吸收这么多信息。","fr":"J'ai du mal à assimiler autant d'informations.","alt":"J'arrive pas à assimiler tout ça.","note":"avoir du mal à + 动词原形 = 很难做到。"}},
 "Atteindre": {"pos":"v.t. 及物动词，第三组，不规则，助动词 avoir；j'atteins，nous atteignons，过去分词 atteint","s":"达到；到达；够得着：atteindre un objectif / le sommet。也指「触及；影响到」：Cette maladie atteint surtout les enfants。","ipa":"[a.tɛ̃dʁ]","ph":"a-tein-dre：ein 读 [ɛ̃]；结尾 -dre 读 [dʁ]，e 不发音。变位中 nous atteignons 读 [a.tɛ.ɲɔ̃]。","pi":"ein 读 [ɛ̃]；变位 gn 出现在复数：nous atteignons，ils atteignent；过去分词 atteint，t 不发音。","et":"来自拉丁语 attingere（碰到），俗拉丁语作 *attangere；tangere = 触摸。变位方式与 peindre、éteindre 类似。","ex":[["Il a fait de gros efforts pour atteindre son objectif.","他付出很大努力来达成目标。"],["Nous avons atteint le sommet à midi.","我们中午到达了山顶。"]],"co":[["atteindre un objectif","达成目标"],["atteindre le sommet","到达山顶"],["atteindre l'âge de + 数字","到了某个年龄"],["être atteint de","患上（病）"]],"sy":[["parvenir à","soutenu","达到、成功做到"],["arriver à","courant","到达、做到"],["réaliser","courant","实现"]],"fq":"高频，日常和书面都常用。","me":"atteindre ← 「碰到」（tangere）目标的那一下。","tr":{"zh":"她终于达到了目标。","fr":"Elle a enfin atteint son but.","alt":"Elle a fini par atteindre son but.","note":"过去分词 atteint；finir par = 终于。"}},
 "Bénéficier de": {"pos":"v.t.ind. 间接及物动词，第一组（-er），后接 de，助动词 avoir","s":"享受；受益于（权利、优惠、条件）：bénéficier d'une réduction / d'un tarif。强调从某种条件中得到好处。","ipa":"[be.ne.fi.sje]","ph":"bé-né-fi-cier：c 在 i 前读 [s]；-ier 读 [sje]；每个音节清楚。","pi":"必须接 de：bénéficier de，不能直接接宾语；c 读 [s]，不是 [k]。","et":"来自拉丁语 beneficium（恩惠），bene（好）+ facere（做）。同源：bénéfice（利润）、bienfait。","ex":[["Les étudiants peuvent bénéficier de réductions sur les transports.","学生可以享受交通折扣。"],["Elle bénéficie d'un bon salaire.","她享有不错的薪水。"]],"co":[["bénéficier de + 名词","享受……"],["bénéficier d'une réduction","享受折扣"],["bénéficier d'un congé","享有假期"],["le bénéfice","利润、好处"]],"sy":[["profiter de","courant","利用、享受"],["jouir de","soutenu","享有"],["avoir droit à","courant","有权享有"]],"fq":"中高频，行政和新闻里很常见。","me":"bene（好）+ facere：从中得到「好处」，要用 de。","tr":{"zh":"老年人可以享受优惠价格。","fr":"Les seniors peuvent bénéficier d'un tarif réduit.","alt":"Les seniors ont droit à un tarif réduit.","note":"bénéficier de + 名词。"}},
 "Colorier": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir","s":"涂色；给……上色，多指给图画涂色（colorier un dessin），孩子常做的事。不指染发（那是 colorer / teindre）。","ipa":"[kɔ.lɔ.ʁje]","ph":"o 读 [ɔ]；-ier 读 [je]；r 是小舌音。","pi":"不要读成 [ko.lo.ʁi.e]；-rier 读 [ʁje]。注意与 colorer（染上颜色）的区别。","et":"来自拉丁语 color（颜色），与 couleur 同源，加动词后缀 -ier。","ex":[["Elle adore colorier des dessins avec des feutres.","她喜欢用马克笔给画涂色。"],["Les enfants colorient un lapin.","孩子们在给一只兔子涂色。"]],"co":[["colorier un dessin","给画涂色"],["un cahier de coloriage","涂色本"],["des crayons de couleur","彩色铅笔"],["colorier en rouge","涂成红色"]],"sy":[["peindre","courant","画（用颜料）"],["colorer","soutenu","使带上颜色"]],"fq":"中频，和儿童、绘画有关时常用。","me":"color + -ier：让线条里面有颜色。","tr":{"zh":"孩子们在涂色。","fr":"Les enfants colorient un dessin.","alt":"Les enfants font du coloriage.","note":"faire du coloriage = 涂色（名词用法）。"}},
 "Concevoir": {"pos":"v.t. 及物动词，第三组，不规则，助动词 avoir；je conçois，nous concevons，过去分词 conçu","s":"设计；构思；想象、理解（Je ne conçois pas qu'il…）。也指「怀孕」。concevoir un projet = 构思项目。","ipa":"[kɔ̃.sə.vwaʁ]","ph":"con 读鼻化 [kɔ̃]；c 读 [s]；e 读弱音 [ə]；-voir 读 [vwaʁ]。变位 je conçois 里 ç 读 [s]。","pi":"变位时 c 变 ç：je conçois，nous concevons，conçu；con 是鼻元音。","et":"来自拉丁语 concipere（接受、怀孕、构想），cum + capere（拿）。同源：concept、conception。","ex":[["L'ingénieur va concevoir un nouveau moteur électrique.","工程师将设计一款新的电动发动机。"],["Je ne conçois pas la vie sans musique.","我无法想象没有音乐的生活。"]],"co":[["concevoir un projet","构思项目"],["bien conçu / mal conçu","设计得好 / 不好"],["concevoir que + 虚拟式","理解、想象"],["la conception","设计、构想"]],"sy":[["imaginer","courant","想象"],["créer","courant","创造"],["élaborer","soutenu","精心制定"]],"fq":"中高频，书面和技术语境常见。","me":"con + cevoir：把想法「拿」在一起，就设计出来了。","tr":{"zh":"他们设计了一个新的应用程序。","fr":"Ils ont conçu une nouvelle application.","alt":"Ils ont créé une nouvelle appli.","note":"过去分词 conçu；appli 是 application 的口语。"}},
 "Confier": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；confier A à B","s":"托付；交给（任务、孩子、秘密）：confier un secret à un ami。se confier à = 向……倾诉。","ipa":"[kɔ̃.fje]","ph":"con 读鼻化 [kɔ̃]；fi 与 er 合成 [fje]；r 不发音。","pi":"con- 是鼻元音；结尾 -er 读 [e]，r 不发音。confier 与 confiance 同源，但拼写不同。","et":"来自拉丁语 confidere（信任），cum + fidere。同源：confiance、fidèle。","ex":[["Le directeur lui a confié un nouveau dossier important.","主任把一份重要的新档案交给了他。"],["Elle m'a confié un secret.","她向我吐露了一个秘密。"]],"co":[["confier A à B","把 A 托付给 B"],["confier un secret","吐露秘密"],["se confier à quelqu'un","向某人倾诉"],["confier ses enfants à","把孩子托付给"]],"sy":[["charger de","courant","责成"],["remettre","courant","交给"],["se livrer","soutenu","倾诉"]],"fq":"中频，日常和书面都用。","me":"con + fier（信任）：把东西放心地交出去。","tr":{"zh":"我把钥匙交给了邻居。","fr":"J'ai confié mes clés à ma voisine.","alt":"J'ai laissé mes clés à ma voisine.","note":"confier A à B；laisser 更口语。"}},
 "Confronter": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir","s":"对照；对质；使面对：confronter A à / avec B。se confronter à = 面对（困难）。être confronté à = 面临。","ipa":"[kɔ̃.fʁɔ̃.te]","ph":"con 读 [kɔ̃]；fron 读 [fʁɔ̃]；结尾 -er 读 [e]。","pi":"con 和 fron 都是鼻元音 [ɔ̃]；不要读成英语 confront。","et":"来自中世纪拉丁语 confrontare，cum + frons（额头）：面对面。同源：front、affronter。","ex":[["Ce stage permet de confronter la théorie à la pratique.","这次实习可以让理论与实践对照。"],["Il est confronté à un choix difficile.","他面临一个艰难的选择。"]],"co":[["confronter A à B","把 A 与 B 对照"],["être confronté à","面临"],["se confronter à","直面"],["une confrontation","对质、对抗"]],"sy":[["comparer","courant","比较"],["affronter","courant","正面对抗"],["opposer","courant","使对立"]],"fq":"中频，书面语较多。","me":"con + front：额头对额头，面对面。","tr":{"zh":"我们要面对这个问题。","fr":"Nous devons nous confronter à ce problème.","alt":"On doit affronter ce problème.","note":"se confronter à / affronter 都可以。"}},
 "Contester": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir","s":"质疑；提出异议；不接受（contester une décision / une note）。也可指对社会现状表示反对。","ipa":"[kɔ̃.tɛs.te]","ph":"con 读鼻化 [kɔ̃]；tes 读 [tɛs]；结尾 -er 读 [e]。","pi":"con 是鼻元音；与 constater（确认）易混：contester = 反对，constater = 发现。","et":"来自拉丁语 contestari（作证对立），cum + testis（证人）。同源：témoin。","ex":[["L'élève a décidé de contester sa note auprès du professeur.","学生决定向老师质疑他的分数。"],["Personne ne conteste ce résultat.","没人质疑这个结果。"]],"co":[["contester une décision","对决定提出异议"],["contester une note","对分数有异议"],["il est contesté","他备受争议"],["une contestation","异议、抗议"]],"sy":[["remettre en cause","courant","质疑"],["discuter","courant","争论"],["réfuter","soutenu","驳斥"]],"fq":"中频，新闻和学校话题里出现。","me":"contre + tester：站在对面「作证」，所以是反对。","tr":{"zh":"他不接受这个决定。","fr":"Il conteste cette décision.","alt":"Il n'est pas d'accord avec cette décision.","note":"contester + 直接宾语。"}},
 "Décortiquer": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir","s":"剥壳；仔细剖析：décortiquer une crevette（剥虾壳）；décortiquer un texte（逐句分析文章）。比喻义很常用。","ipa":"[de.kɔʁ.ti.ke]","ph":"dé [de]；cor 读 [kɔʁ]；ti 读 [ti]，这里 t 读 [t]；qu 读 [k]；结尾 -er 读 [e]。","pi":"tiqu- 里 qu 读 [k]，不是 [kw]；五个音节都要读清楚。","et":"来自拉丁语 decorticare，de- + cortex（树皮、外壳）。同源：écorce。","ex":[["Le professeur décortique le poème vers par vers.","老师逐句剖析这首诗。"],["Il décortique une crevette avec les doigts.","他用手剥虾壳。"]],"co":[["décortiquer un texte","剖析文章"],["décortiquer une crevette","剥虾壳"],["décortiquer un problème","细究问题"],["décortiquer les chiffres","分析数字"]],"sy":[["analyser","courant","分析"],["éplucher","courant","削皮；仔细检查"],["disséquer","soutenu","解剖、剖析"]],"fq":"中低频，口语和学习中常用。","me":"de + écorce：把「外壳」拿掉，看到里面。","tr":{"zh":"我们要逐句分析这篇文章。","fr":"Nous allons décortiquer ce texte phrase par phrase.","alt":"On va analyser ce texte phrase par phrase.","note":"aller + 动词原形 表示近将来。"}},
 "Découper": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir","s":"剪下；切开；切成块：découper du papier / un poulet。比 couper 更强调「沿着线剪」或「切成几份」。","ipa":"[de.ku.pe]","ph":"dé [de]；cou 读 [ku]；pé 或 per 读 [pe]；结尾 -er 读 [e]。","pi":"ou 读 [u]；découper 和 couper 的区别：dé- 表示切成多块。","et":"由 dé- + couper 构成；couper 来自 coup（击打），拉丁语 colaphus，希腊语 kolaphos。","ex":[["L'enfant apprend à découper une feuille de papier.","孩子学着剪纸。"],["Il découpe le poulet en morceaux.","他把鸡切成块。"]],"co":[["découper en morceaux","切成块"],["découper une image","剪下图片"],["découper suivant les pointillés","沿虚线剪开"],["un découpage","剪裁、划分"]],"sy":[["couper","courant","切，更一般"],["trancher","courant","切成片"],["détailler","soutenu","切开、详述"]],"fq":"中频，生活和手工场景常用。","me":"dé + couper：沿着线把东西「拆开切」。","tr":{"zh":"把这张图剪下来。","fr":"Découpe cette image.","alt":"Découpe-moi cette image.","note":"命令式第二人称单数没有 s。"}},
 "Élargir": {"pos":"v.t. 及物动词，第二组（-ir，élargissant），助动词 avoir","s":"拓宽；扩大；放宽：élargir une route / son horizon / ses connaissances。s'élargir = 变宽。","ipa":"[e.laʁ.ʒiʁ]","ph":"é [e]；lar 读 [laʁ]；g 在 i 前读 [ʒ]；结尾 -ir 读 [iʁ]。","pi":"g 读 [ʒ]；第二组变位：il élargit，nous élargissons；与 large（宽）相关。","et":"由 é-（向外）+ large（宽）+ -ir 构成。","ex":[["Voyager permet d'élargir ses horizons culturels.","旅行可以拓宽文化视野。"],["On a élargi la rue pour les vélos.","为了自行车，路被拓宽了。"]],"co":[["élargir ses horizons","拓宽视野"],["élargir une route","拓宽道路"],["élargir ses connaissances","扩大知识面"],["s'élargir","变宽"]],"sy":[["agrandir","courant","扩大"],["étendre","courant","扩展"],["ouvrir","courant","开放、拓展"]],"fq":"中频，书面和学习话题常用。","me":"é + large：把范围弄得更「large」。","tr":{"zh":"旅行拓宽了我的视野。","fr":"Voyager a élargi mes horizons.","alt":"Les voyages m'ont ouvert l'esprit.","note":"主语可以是动词原形：Voyager…"}},
 "Enrichir": {"pos":"v.t. 及物动词，第二组（-ir，enrichissant），助动词 avoir","s":"丰富；使富有：enrichir son vocabulaire（丰富词汇）。s'enrichir = 变富、变丰富。","ipa":"[ɑ̃.ʁi.ʃiʁ]","ph":"en 读 [ɑ̃]；ri 读 [ʁi]；chir 读 [ʃiʁ]；ch 读 [ʃ]。","pi":"ch 读 [ʃ]；en 是鼻元音；第二组变位：il enrichit，nous enrichissons。","et":"由 en- + riche + -ir 构成；riche 来自法兰克语 *rīki（强大）。","ex":[["Cette lecture va enrichir son vocabulaire.","这次阅读会丰富他的词汇。"],["Ce voyage m'a beaucoup enrichi.","这次旅行让我受益很多。"]],"co":[["enrichir son vocabulaire","丰富词汇"],["s'enrichir","致富；变丰富"],["enrichir une recette","丰富食谱"],["un enrichissement","丰富、充实"]],"sy":[["améliorer","courant","改善"],["compléter","courant","补充"],["nourrir","courant","滋养"]],"fq":"中频，学习和文化话题常用。","me":"en + riche：让它变得「更富」。","tr":{"zh":"阅读丰富了我的词汇。","fr":"La lecture a enrichi mon vocabulaire.","alt":"Lire m'a permis d'enrichir mon vocabulaire.","note":"enrichir + 直接宾语。"}},
 "Étaler": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir","s":"铺开；摊开；涂开；把时间或付款分散开：étaler du beurre / ses révisions / un paiement。s'étaler = 铺开，延伸。","ipa":"[e.ta.le]","ph":"é [e]；ta [ta]；ler 读 [le]，r 不发音。","pi":"结尾 -er 读 [e]，r 不发音；étaler 与 étalage（陈列）同族。","et":"来自 étal（摊位、台子），源于法兰克语 *stal；原意是「摆出来」。","ex":[["Il préfère étaler ses révisions sur plusieurs semaines.","他更喜欢把复习分散到几个星期。"],["Elle étale du beurre sur son pain.","她把黄油涂在面包上。"]],"co":[["étaler du beurre","涂黄油"],["étaler ses révisions","分散复习"],["étaler un paiement","分期付款"],["s'étaler sur","分布在……"]],"sy":[["répartir","courant","分配、分散"],["étendre","courant","摊开"],["exposer","courant","陈列"]],"fq":"中频，生活里常用。","me":"étal（摊位）：把东西摆开在摊上。","tr":{"zh":"她把复习分散在一个月里。","fr":"Elle étale ses révisions sur un mois.","alt":"Elle répartit ses révisions sur un mois.","note":"étaler ... sur + 时间段。"}},
 "Exploser": {"pos":"v.i. 不及物动词，第一组（-er），助动词 avoir","s":"爆炸；爆发；激增：Les prix explosent（价格暴涨）。也指情绪突然爆发：exploser de colère / de rire。","ipa":"[ɛk.splo.ze]","ph":"ex 读 [ɛks]；plo 读 [plo]；s 在元音间读 [z]；结尾 -er 读 [e]。","pi":"s 读 [z]，不读 [s]；ex- 读 [ɛk]，随后连读 [splo]。","et":"来自 explosion，拉丁语 explodere（用拍手驱赶）：ex- + plaudere（鼓掌）。","ex":[["Le nombre de candidatures vient d'exploser cette année.","今年申请人数激增。"],["Il a explosé de colère.","他怒气爆发了。"]],"co":[["exploser de colère","勃然大怒"],["exploser de rire","爆笑"],["les prix explosent","价格暴涨"],["une explosion","爆炸"]],"sy":[["éclater","courant","爆裂、爆发"],["augmenter","courant","增加"],["flamber","familier","（价格）飙升"]],"fq":"中高频，新闻里很常见。","me":"ex + plode：往外「炸」开。","tr":{"zh":"房价猛涨。","fr":"Les prix de l'immobilier explosent.","alt":"Les prix des logements flambent.","note":"immobilier = 房地产；prix 复数时动词也用复数。"}},
 "Fixer / Se fixer": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；se fixer 为代词式动词，助动词 être","s":"固定；规定、确定（fixer un rendez-vous / un prix）。se fixer des objectifs = 给自己定目标。fixer 也指盯着看。","ipa":"[fik.se]","ph":"x 读 [ks]；结尾 -er 读 [e]；代词式 se 读 [sə]。","pi":"x 读 [ks]，不是 [z]；代词式过去时：je me suis fixé des objectifs，过去分词常不变。","et":"来自拉丁语 fixus（固定的），figere（钉住）。同源：fixe、fixation。","ex":[["Je dois me fixer des objectifs.","我得给自己设定目标。"],["Nous avons fixé un rendez-vous pour lundi.","我们把约会定在周一。"]],"co":[["se fixer des objectifs","给自己定目标"],["fixer un rendez-vous","约定会面"],["fixer un prix","定价"],["fixer quelqu'un du regard","盯着某人看"]],"sy":[["établir","soutenu","确定、制定"],["décider","courant","决定"],["arrêter","soutenu","确定（日期）"]],"fq":"高频，日常常用。","me":"fixer = 钉住（figere）一个目标不动。","tr":{"zh":"我们把会议定在周五。","fr":"Nous avons fixé la réunion à vendredi.","alt":"On a fixé la réunion à vendredi.","note":"fixer ... à + 日期。"}},
 "Inciter": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；inciter qqn à + 动词原形","s":"鼓励；促使；怂恿：inciter quelqu'un à faire quelque chose。语气可正面（鼓励）也可中性或负面（引发）。","ipa":"[ɛ̃.si.te]","ph":"in 读鼻化 [ɛ̃]；c 在 i 前读 [s]；结尾 -er 读 [e]。","pi":"in 读 [ɛ̃]，不读 [in]；c 读 [s]；固定结构 inciter à，不能说 inciter de。","et":"来自拉丁语 incitare（使动起来），in- + citare（驱使）。同源：citer、solliciter。","ex":[["Les professeurs incitent les élèves à lire régulièrement.","老师们鼓励学生定期阅读。"],["Ce prix incite à acheter plus.","这个价格促使人多买。"]],"co":[["inciter à + 动词原形","促使做……"],["une incitation","鼓励、刺激"],["inciter les jeunes à voter","鼓励年轻人投票"],["inciter à la prudence","促使谨慎"]],"sy":[["encourager","courant","鼓励"],["pousser","courant","推动"],["stimuler","soutenu","激励"]],"fq":"中频，书面和新闻常见。","me":"in + citer：把人往某个方向「推动」。","tr":{"zh":"老师鼓励我们多读书。","fr":"Le professeur nous incite à lire davantage.","alt":"Le prof nous pousse à lire plus.","note":"inciter qqn à + 动词原形。"}},
 "Inverser": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir","s":"扭转；颠倒；调换：inverser une tendance / les rôles / l'ordre。s'inverser = 反过来。","ipa":"[ɛ̃.vɛʁ.se]","ph":"in 读 [ɛ̃]；ver 读 [vɛʁ]；s 在 r 后读 [s]；结尾 -er 读 [e]。","pi":"in 读鼻元音 [ɛ̃]；ver 的 r 要发；与 inverse（相反的）、envers（反面）同族。","et":"来自拉丁语 invertere（翻转），in- + vertere（转）；也受 inverse 影响。","ex":[["Il faut inverser cette tendance négative au plus vite.","必须尽快扭转这种负面趋势。"],["Nous avons inversé les rôles.","我们把角色调换了。"]],"co":[["inverser une tendance","扭转趋势"],["inverser les rôles","调换角色"],["inverser l'ordre","颠倒顺序"],["l'inverse","相反"]],"sy":[["renverser","courant","推翻、扭转"],["intervertir","soutenu","颠倒、对调"],["retourner","courant","翻转"]],"fq":"中频，书面和新闻常用。","me":"in + verser：把方向「倒」过来。","tr":{"zh":"我们必须扭转这个趋势。","fr":"Nous devons inverser cette tendance.","alt":"Il faut qu'on inverse cette tendance.","note":"devoir + 动词原形；il faut que + 虚拟式。"}},
 "Lutter contre": {"pos":"v.i. 不及物动词，第一组（-er），后接 contre，助动词 avoir","s":"对抗；反对；与……斗争：lutter contre la pauvreté / le racisme。也可单用：lutter pour qch（为……奋斗）。","ipa":"[ly.te kɔ̃tʁ]","ph":"lutter 读 [ly.te]，tt 读一个 [t]，u 读 [y]；contre 读 [kɔ̃tʁ]，结尾 e 不发音。","pi":"u 读 [y]；tt 只读一个 t；不要说 lutter à。反义是 lutter pour。","et":"来自拉丁语 luctari（摔跤，斗争）。同族：lutte（斗争）、lutteur（摔跤手）。","ex":[["Nous devons lutter contre les inégalités scolaires.","我们必须与教育不平等作斗争。"],["Il lutte contre une maladie grave.","他在与重病作斗争。"]],"co":[["lutter contre + 名词","与……作斗争"],["lutter pour + 名词","为……而奋斗"],["la lutte contre la pauvreté","反贫困斗争"],["lutter contre le froid","抵御寒冷"]],"sy":[["combattre","soutenu","战斗、与……斗争"],["se battre contre","courant","与……搏斗"],["résister à","courant","抵抗"]],"fq":"中高频，新闻和公共话题常用。","me":"lutter ← luctari：像摔跤手一样「contre」对抗。","tr":{"zh":"我们应该反对浪费。","fr":"Nous devons lutter contre le gaspillage.","alt":"Il faut lutter contre le gaspillage.","note":"lutter contre + 名词。"}},
 "Maîtriser": {"pos":"v.t. 及物动词（-er 动词，助动词 avoir）","s":"掌握；精通（语言、技术、知识）。也可指控制住、压住（情绪、火势、局面）：maîtriser sa colère 控制怒气。","ipa":"[mɛ.tʁi.ze]","ph":"aî 读 [ɛ]；-ser 中 s 在元音间读 [z]；结尾 -er 读 [e]，r 不发音。","pi":"î 上的帽子不改变发音；不要把 maîtriser 的 s 读成 [s]。别和 maître（老师、主人）的拼写混淆，maîtriser 有 -iser。","et":"来自 maître（拉丁语 magister）+ 后缀 -iser。同族词：maîtrise（掌握；硕士学位）、maîtrisé。","ex":[["Il faut des années pour maîtriser parfaitement une langue.","要多年才能完全掌握一门语言。"],["Les pompiers ont maîtrisé l'incendie.","消防员控制住了火势。"],["Elle n'arrive pas à maîtriser sa colère.","她控制不住自己的怒气。"]],"co":[["maîtriser une langue","掌握一门语言"],["maîtriser ses émotions","控制情绪"],["maîtriser la situation","掌控局面"],["bien maîtriser un sujet","对某个主题很熟练"]],"sy":[["dominer","courant","精通；支配，语气更强"],["contrôler","courant","控制，多指管控"],["posséder","soutenu","精通（书面）"]],"fq":"中高频，学习、工作、新闻里常用。","me":"maître（大师）+ -iser：把一门技艺变成「大师级」。","tr":{"zh":"她完全掌握了法语。","fr":"Elle maîtrise parfaitement le français.","alt":"Elle parle français comme une vraie Française.","note":"maîtriser 直接带宾语，不加介词。"}},
 "Opérer": {"pos":"v.t./v.i. 及物兼不及物动词（-er 动词，助动词 avoir）","s":"进行、实施（opérer un changement）；做手术（opérer un malade）；起作用、见效（le médicament opère）。书面、正式场合比 faire 更庄重。","ipa":"[ɔ.pe.ʁe]","ph":"o 读 [ɔ]；é 读 [e]；结尾 -er 读 [e]，r 不发音。","pi":"变位时重音符号会变：j'opère [ɔ.pɛʁ]，nous opérons，j'opérerai。别把 opérer 和 opérer qqn（给人做手术）弄混成「操作机器」，操作机器多说 utiliser / faire fonctionner。","et":"来自拉丁语 operari（工作、劳动），源于 opus, operis（作品、工作）。同族词：opération、opérateur、coopérer。","ex":[["Il opère la maintenance sur le site d'Angers.","他在昂热工地做维护工作。"],["Le chirurgien va opérer demain matin.","外科医生明天早上做手术。"],["Ce médicament opère très vite.","这种药见效很快。"]],"co":[["opérer un changement","实施一项改变"],["opérer un malade","给病人做手术"],["se faire opérer","去做手术"],["opérer un choix","做出选择"]],"sy":[["réaliser","courant","实现、完成"],["effectuer","soutenu","执行、进行（正式）"],["faire","courant","做，最日常"]],"fq":"中频，偏正式、工作和医疗语境。","me":"opérer ← opus（工作）：「把工作做出来」，医生做的就是手术。","tr":{"zh":"医生下周给他做手术。","fr":"Le médecin va l'opérer la semaine prochaine.","alt":"Il se fait opérer la semaine prochaine.","note":"给人做手术用 opérer qqn；去做手术说 se faire opérer。"}},
 "Opposer": {"pos":"v.t. 及物动词（-er 动词，助动词 avoir）；s'opposer à 反对","s":"使对立、使对抗；让两方比赛、对阵：Ce match oppose Paris à Lyon。反身形式 s'opposer à qqch 表示反对、抵制。","ipa":"[ɔ.po.ze]","ph":"o 读 [ɔ]；pp 只发一个 [p]；s 在元音间读 [z]；-er 读 [e]。","pi":"pp 不要读成两个 p；s 读 [z]，不是 [s]。注意 opposer qqn à qqn（使对抗）和 s'opposer à（反对）的结构不同。","et":"来自拉丁语 opponere（放在对面，ob- + ponere），后受 poser 影响。同族词：opposition、opposé、poser。","ex":[["On ne devrait pas opposer théorie et pratique.","不应该把理论和实践对立起来。"],["Ce match oppose deux grandes équipes.","这场比赛是两支强队对阵。"],["Mes parents s'opposent à ce projet.","我父母反对这个计划。"]],"co":[["opposer A à B","使 A 与 B 对立"],["s'opposer à qqch","反对某事"],["opposer un refus","予以拒绝"],["être opposé à","反对、不赞成"]],"sy":[["comparer","courant","比较，不一定对立"],["s'élever contre","soutenu","强烈反对"],["refuser","courant","拒绝，更日常"]],"fq":"中频，书面和讨论中常见。","me":"op- + poser：把两样东西「放在对面」，就是对立。","tr":{"zh":"这场比赛是两个老对手之间的对决。","fr":"Ce match oppose deux vieux rivaux.","alt":"C'est un match entre deux vieux rivaux.","note":"opposer 的主语常是比赛、事件。"}},
 "Paniquer": {"pos":"v.i. 不及物动词（-er 动词，助动词 avoir）；也可及物（paniquer qqn）","s":"惊慌，恐慌。日常很常用：Ne panique pas ! 别慌！。口语里也可以说 se paniquer（较少见），及物用法 paniquer qqn = 让某人惊慌。","ipa":"[pa.ni.ke]","ph":"qu 读 [k]；i 读 [i]；-er 读 [e]，r 不发音。","pi":"qu 读 [k]，不是 [kw]；变位时保留 qu：nous paniquons，不是 nous panicons。","et":"来自 panique，源自希腊语 panikos（与牧神 Pan 有关的，突然的恐惧）。","ex":[["Il ne faut pas paniquer avant les résultats d'examen.","成绩公布前不要惊慌。"],["Ne panique pas, on a encore le temps.","别慌，我们还有时间。"],["Elle panique dès qu'elle voit une araignée.","她一看到蜘蛛就慌了。"]],"co":[["Ne panique pas !","别慌！"],["paniquer pour rien","无缘无故地慌张"],["être paniqué(e)","惊慌失措"],["un mouvement de panique","一阵恐慌"]],"sy":[["s'affoler","courant","慌乱，较书面"],["flipper","familier","吓得发慌，很口语"],["garder son calme","courant","保持冷静（反义）"]],"fq":"高频，日常口语常用。","me":"Pan 神突然出现，人们就 panique：吓得乱成一团。","tr":{"zh":"考试前别慌。","fr":"Ne panique pas avant l'examen.","alt":"Pas de panique avant l'examen !","note":"命令式 ne panique pas，对 tu 说；对 vous 是 ne paniquez pas。"}},
 "Plier": {"pos":"v.t./v.i. 及物兼不及物动词（-er 动词，助动词 avoir）","s":"折叠（纸、衣服）；弯曲（膝盖）；屈服、让步（plier devant qqn）。口语 plier bagage = 收拾行李走人。","ipa":"[pli.je]","ph":"pl 连读成一个辅音群；结尾 -ier 读 [je]，r 不发音。","pi":"不要把 plier 和 plie 读成一样：plier 末尾有 [je]，je plie 末尾读 [pli]。别和 plaire（讨人喜欢）混淆。变位中 nous plions，imparfait 是 nous pliions。","et":"来自拉丁语 plicare（折叠）。同族词：pli（折痕）、plier、replier、déplier、appliquer。","ex":[["Il faut plier la feuille en deux pour faire la carte.","把纸对折来做卡片。"],["Elle plie ses vêtements avant de les ranger.","她先把衣服叠好再收起来。"],["Il a plié les genoux pour ramasser la clé.","他弯下膝盖捡起钥匙。"]],"co":[["plier une feuille en deux","把纸对折"],["plier ses vêtements","叠衣服"],["plier les genoux","弯膝盖"],["plier bagage","收拾东西走人"]],"sy":[["replier","courant","再折叠、收拢"],["courber","soutenu","使弯曲"],["céder","courant","屈服、让步"]],"fq":"中频，生活里常用。","me":"plier ← pli：先有「折痕」pli，再有「折」plier。","tr":{"zh":"请把这张纸对折。","fr":"Pliez cette feuille en deux, s'il vous plaît.","alt":"Tu peux plier cette feuille en deux ?","note":"plier en deux = 对折。"}},
 "Poursuivre": {"pos":"v.t./v.i. 及物兼不及物动词（第三组，助动词 avoir，过去分词 poursuivi）","s":"继续（poursuivre ses études）；追赶、追捕；追求（目标、梦想）。在法律语境中还有「起诉」。变位同 suivre：je poursuis, nous poursuivons。","ipa":"[puʁ.sɥivʁ]","ph":"ou 读 [u]；ui 读 [ɥi]；-ivre 中 e 不发音，结尾 [vʁ]。","pi":"ui 是快速的 [ɥi]，不是 [u-i]；结尾 -re 的 e 不发音。je poursuis 的 s 不读。","et":"pour- + suivre（拉丁语 sequi，跟随）。同族词：suite、suivre、poursuite。","ex":[["Elle compte poursuivre ses études à l'étranger.","她打算继续到国外深造。"],["La police poursuit le voleur.","警察在追捕小偷。"],["Il poursuit son rêve depuis l'enfance.","他从小就一直追求自己的梦想。"]],"co":[["poursuivre ses études","继续学业"],["poursuivre un objectif","追求一个目标"],["poursuivre son chemin","继续前行"],["poursuivre en justice","起诉"]],"sy":[["continuer","courant","继续，最日常"],["persévérer","soutenu","坚持不懈"],["rechercher","courant","寻求"]],"fq":"中高频，学习、工作场合常见。","me":"pour + suivre：一直「跟着」不放，就是继续或追求。","tr":{"zh":"我想继续学法语。","fr":"Je veux poursuivre mes études de français.","alt":"Je veux continuer à apprendre le français.","note":"poursuivre + 名词；continuer à + 动词原形。"}},
 "Procéder à": {"pos":"v.t.ind. 间接及物动词（procéder à + 名词；助动词 avoir）","s":"着手进行、办理（正式、行政语境）：procéder à un vote 进行投票。后面接动作名词，很少接具体物品。另一个意思 procéder de = 源自。","ipa":"[pʁɔ.se.de a]","ph":"c 在 é 前读 [s]；两个 é 都读 [e]；注意 procède 中 è 读 [ɛ]。","pi":"变位时重音变化：je procède [pʁɔ.sɛd]，nous procédons，je procéderai。必须带介词 à，不要直接加宾语。","et":"来自拉丁语 procedere（向前走，pro- + cedere）。同族词：procédure、processus、procès。","ex":[["L'administration va procéder à l'inscription des nouveaux élèves.","行政部门将办理新生注册。"],["On va procéder au vote.","我们要进行投票了。"],["La police a procédé à plusieurs arrestations.","警方逮捕了好几个人。"]],"co":[["procéder à un vote","进行投票"],["procéder à une vérification","进行核查"],["procéder à une arrestation","实施逮捕"],["procéder par étapes","分步骤进行"]],"sy":[["effectuer","soutenu","执行"],["réaliser","courant","完成、实现"],["faire","courant","做，最日常"]],"fq":"中频，偏行政、书面。","me":"pro- 向前 + céder：向前推进，开始办事。","tr":{"zh":"我们现在进行投票。","fr":"Nous allons procéder au vote.","alt":"On va passer au vote maintenant.","note":"procéder à + le = procéder au。"}},
 "Profiter de": {"pos":"v.t.ind. 间接及物动词（profiter de + 名词/动词；助动词 avoir）","s":"利用（机会、时间）；享受（假期、好天气）。profiter de qqn 有「占某人便宜」的贬义。另有 profiter à qqn = 对某人有益。","ipa":"[pʁɔ.fi.te də]","ph":"o 读 [ɔ]；-er 读 [e]；de 弱读 [də]。","pi":"必须说 profiter de，不要说 profiter 直接加宾语。注意 profiter de qqn（利用某人）有贬义。","et":"来自 profit（利益，拉丁语 profectus 进步、收益）+ -er。同族词：profit、profitable。","ex":[["Il faut profiter de ces vacances pour bien se reposer.","要利用假期好好休息。"],["Profitez du beau temps !","好好享受好天气吧！"],["Il profite de sa gentillesse.","他在利用她的善良。"]],"co":[["profiter de l'occasion","抓住机会"],["profiter du soleil","享受阳光"],["profiter de la vie","享受生活"],["en profiter pour + inf.","趁机做某事"]],"sy":[["utiliser","courant","使用"],["jouir de","soutenu","享有、享受"],["exploiter","courant","利用，常带贬义"]],"fq":"高频，日常常用。","me":"profiter = 从 profit（好处）里「拿到好处」。","tr":{"zh":"趁天气好，我们去散步吧。","fr":"Profitons du beau temps pour aller nous promener.","alt":"Il fait beau, on en profite pour se balader.","note":"en profiter pour + 动词原形 = 趁机做。"}},
 "Recruter": {"pos":"v.t. 及物动词（-er 动词，助动词 avoir）","s":"招聘、招募（员工、士兵、会员）。公司、学校、协会都可以用：recruter des étudiants。名词是 le recrutement（招聘）、le recruteur（招聘人）。","ipa":"[ʁə.kʁy.te]","ph":"re 弱读 [ʁə]；u 读 [y]（嘴唇收圆）；-er 读 [e]。","pi":"u 读 [y]，不是 [u]；r 是小舌音。别把 recruter 和 recrutement 的 t 漏掉。","et":"来自 recrue（新兵），其词根与 croître（生长）有关，原义「再长出来的人」。较深的来源不很确定。同族词：recrutement、recrue。","ex":[["Cette entreprise veut recruter de nouveaux diplômés.","这家公司想招聘新毕业生。"],["L'hôpital recrute des infirmières.","医院在招聘护士。"],["On recrute pour l'été.","夏季招人。"]],"co":[["recruter du personnel","招聘员工"],["recruter des jeunes diplômés","招聘应届毕业生"],["se faire recruter","被录用"],["campagne de recrutement","招聘活动"]],"sy":[["embaucher","courant","雇用，签合同"],["engager","courant","聘用"],["licencier","courant","解雇（反义）"]],"fq":"中高频，工作场合常见。","me":"recruter → recrue（新人）：把新人招进来。","tr":{"zh":"我们在招一名新秘书。","fr":"Nous recrutons une nouvelle secrétaire.","alt":"On cherche une nouvelle secrétaire.","note":"recruter 直接带宾语。"}},
 "Remplacer": {"pos":"v.t. 及物动词（-er 动词，助动词 avoir）","s":"替换、取代（物）；顶替、代班（人）：remplacer un collègue。remplacer A par B = 用 B 换掉 A。","ipa":"[ʁɑ̃.pla.se]","ph":"em 读鼻化元音 [ɑ̃]；c 在 e 前读 [s]；-er 读 [e]。","pi":"em 在这里读 [ɑ̃]，不读 [ɛm]；变位 nous remplaçons 要加软音符 ç。remplacer A par B，不要说 par A。","et":"re- + emplacer（en- + place）。place 来自拉丁语 platea（宽街）。同族词：remplacement、place、déplacer。","ex":[["Un nouveau professeur va remplacer notre enseignante malade.","一位新老师将顶替生病的老师。"],["Il faut remplacer la batterie.","要换电池了。"],["Je remplace ma collègue cette semaine.","这个星期我替同事代班。"]],"co":[["remplacer A par B","用 B 取代 A"],["remplacer un collègue","替同事的班"],["remplacer une pièce","更换零件"],["se faire remplacer","找人代替自己"]],"sy":[["changer","courant","更换，较日常"],["substituer","soutenu","替换（书面）"],["suppléer","soutenu","代理"]],"fq":"高频，日常和工作都常用。","me":"re- 再次 + en-place：「重新放一个在原位」。","tr":{"zh":"我得换一个新手机。","fr":"Je dois remplacer mon téléphone.","alt":"Il faut que je change de téléphone.","note":"remplacer A par B；nous remplaçons 加 ç。"}},
 "Répartir": {"pos":"v.t. 及物动词（第二组，助动词 avoir，过去分词 réparti）","s":"分配、分摊（任务、钱、人）；分成几部分。répartir A entre B et C = 把 A 分给 B 和 C。注意：另一个动词 repartir（再出发，第三组）发音几乎相同。","ipa":"[ʁe.paʁ.tiʁ]","ph":"é 读 [e]；ar 读 [aʁ]；结尾 -ir 读 [iʁ]，r 要读出。","pi":"répartir（分配）和 repartir（再出发）很容易混淆，注意 é。répartir 按第二组变位：je répartis, nous répartissons。","et":"re- + partir（古义「分开」）。partir 来自拉丁语 partire（分）。同族词：répartition、partie、partager。","ex":[["Le professeur veut répartir le travail entre tous les élèves.","老师想把工作分配给所有学生。"],["Ils se répartissent les tâches ménagères.","他们分担家务。"],["Les élèves sont répartis en trois groupes.","学生被分成三个组。"]],"co":[["répartir le travail","分配工作"],["répartir entre","分给……之间"],["se répartir les tâches","分工"],["être réparti(e) en groupes","被分成小组"]],"sy":[["distribuer","courant","分发"],["partager","courant","分享、分担"],["diviser","courant","分开"]],"fq":"中频，工作、学习中常见。","me":"ré + partir：把整体「分开」成几份。","tr":{"zh":"我们把任务分给每个人吧。","fr":"Répartissons les tâches entre tout le monde.","alt":"On se partage les tâches.","note":"répartir A entre B。"}},
 "Réussir": {"pos":"v.t./v.i. 及物兼不及物动词（第二组，助动词 avoir）；réussir à + 动词原形","s":"成功；考试通过（réussir un examen）；做成（réussir un plat）。réussir à + 动词 = 成功做到。注意 réussir 不是「重复」。","ipa":"[ʁe.y.siʁ]","ph":"é 与 u 分开读 [e.y]；ss 读 [s]；结尾 [siʁ]。","pi":"réussir 中的 é 和 u 要分成两个音节，不能读成 [ʁø]。常误说 réussir de + 动词，正确是 réussir à。","et":"来自意大利语 riuscire（再出来，成功）。","ex":[["Elle espère réussir tous ses examens du premier coup.","她希望一次通过所有考试。"],["Il a réussi à ouvrir la porte.","他成功打开了门。"],["Ce gâteau est vraiment réussi.","这个蛋糕做得真成功。"]],"co":[["réussir à + inf.","成功做到"],["réussir un examen","通过考试"],["réussir sa vie","活得成功"],["réussir du premier coup","一次成功"]],"sy":[["y arriver","courant","做到，很口语"],["échouer","courant","失败（反义）"],["parvenir à","soutenu","设法做到"]],"fq":"极高频，日常常用。","me":"réussir ≈ 意大利语「再次走出来」：走出难关，就是成功。","tr":{"zh":"我终于通过了驾照考试。","fr":"J'ai enfin réussi mon permis de conduire.","alt":"J'ai enfin eu mon permis !","note":"réussir un examen，不加介词。"}},
 "S'assurer de": {"pos":"v.pron. 代词式动词（s'assurer de + 名词/动词原形；复合时态助动词 être）","s":"确认、查明（s'assurer de l'heure）；确保（s'assurer que + 虚拟式/直陈式）。也可指给自己买保险（s'assurer contre）。","ipa":"[sa.sy.ʁe də]","ph":"s' 与 a 连读 [sa]；ss 读 [s]；u 读 [y]；-er 读 [e]。","pi":"u 读 [y]，不是 [u]；复合时态要用 être：Je me suis assuré(e) de ça。后面接名词用 de，接从句用 que。","et":"assurer ← à- + sûr，来自拉丁语 securus（无忧的）。同族词：sûr、sûreté、sécurité、assurance。","ex":[["Pense à t'assurer de la date limite avant d'envoyer ton dossier.","寄材料前记得确认截止日期。"],["Je m'assure que tout est prêt.","我在确认一切准备好了。"],["Assure-toi de fermer la porte à clé.","务必把门锁好。"]],"co":[["s'assurer de qqch","确认某事"],["s'assurer que + ind.","确认……"],["s'assurer de + inf.","确保做到……"],["Assure-toi que…","你要确保……"]],"sy":[["vérifier","courant","核实、检查"],["se renseigner","courant","打听、了解"],["veiller à","soutenu","注意确保"]],"fq":"中高频，日常和工作常用。","me":"s'assurer = 让自己变 sûr（确定）。","tr":{"zh":"出门前确认一下门关好了。","fr":"Avant de partir, assure-toi que la porte est fermée.","alt":"Avant de partir, vérifie que la porte est bien fermée.","note":"s'assurer que 后接直陈式；命令式 assure-toi。"}},
 "S'engager": {"pos":"v.pron. 代词式动词（-er 动词，复合时态助动词 être）","s":"承诺、保证（s'engager à + 动词）；投身、参与（s'engager dans une association）；入伍（s'engager dans l'armée）。一般含有「认真承担」的意思。","ipa":"[sɑ̃.ɡa.ʒe]","ph":"s'en 读 [sɑ̃]；g 在 a 前读 [ɡ]；ge 读 [ʒ]。","pi":"一个单词里 g 读两个音：engager 中 g 先 [ɡ] 后 [ʒ]。nous nous engageons 要保留 e。","et":"en- + gage（抵押、保证）。同族词：engagement、gage、dégager。","ex":[["De nombreux étudiants décident de s'engager dans une association.","许多学生决定参加协会。"],["Je m'engage à finir ce travail demain.","我保证明天做完这项工作。"],["Il s'est engagé dans l'armée à dix-huit ans.","他十八岁入伍。"]],"co":[["s'engager à + inf.","承诺做某事"],["s'engager dans","投身于"],["s'engager pour une cause","为某项事业奔走"],["s'engager dans l'armée","入伍"]],"sy":[["promettre","courant","答应、保证"],["s'investir","courant","投入精力"],["participer","courant","参加"]],"fq":"中高频，学习、工作、社会话题常见。","me":"en + gage：把自己「押」进去，就是投身。","tr":{"zh":"她决心投身环境保护。","fr":"Elle s'engage pour la protection de l'environnement.","alt":"Elle s'investit pour l'environnement.","note":"s'engager pour = 为……投身；à 后接动词原形。"}},
 "S'entraider": {"pos":"v.pron. 代词式动词（互相动作，-er 动词，复合时态助动词 être）","s":"互相帮助。只用于复数主语（nous, vous, ils, les gens）。名词是 l'entraide（互助）。","ipa":"[sɑ̃.tʁɛ.de]","ph":"s'en 读 [sɑ̃]；ai 读 [ɛ]；-er 读 [e]。","pi":"ai 读 [ɛ]；r 要发小舌音。注意是 s'entraider，不是 s'entre-aider 的写法。主语必须是复数。","et":"entre + aider（拉丁语 adiutare，帮助）。同族词：aide、entraide、aider。","ex":[["Les étudiants doivent s'entraider pour réviser les examens.","学生们应该互相帮助复习。"],["Les voisins s'entraident quand il neige.","下雪时邻居们互相帮忙。"],["Il faut s'entraider dans la vie.","人生中要互相帮助。"]],"co":[["l'entraide","互助"],["s'entraider entre voisins","邻里互助"],["l'entraide entre collègues","同事间的互助"],["un esprit d'entraide","互助精神"]],"sy":[["se soutenir","courant","互相支持"],["coopérer","soutenu","合作"],["se donner un coup de main","familier","互相搭把手"]],"fq":"中低频，日常也用。","me":"entre + aider：「在彼此之间」帮助。","tr":{"zh":"我们应该互相帮助。","fr":"Nous devons nous entraider.","alt":"On doit se donner un coup de main.","note":"s'entraider 表示互相，主语要是复数。"}},
 "S'épanouir": {"pos":"v.pron. 代词式动词（第二组，复合时态助动词 être，过去分词 épanoui）","s":"（花）盛开；（人）得到充分发展、感到幸福充实。s'épanouir dans son travail = 在工作中感到充实。形容词 épanoui(e) = 开朗、舒展的。","ipa":"[se.pa.nwiʁ]","ph":"é 读 [e]；ou+i 连成 [wi]；结尾 [iʁ]。","pi":"ou+i 读 [wi]，是一个音节；按第二组变位：nous nous épanouissons。","et":"来自古法语，较早的形式的具体来源不够确定。同族词：épanoui、épanouissement。","ex":[["Elle s'épanouit pleinement dans ses études artistiques.","她在艺术学习中充分成长。"],["Les fleurs s'épanouissent au printemps.","花在春天绽放。"],["Il s'épanouit dans son nouveau travail.","他在新工作中过得很充实。"]],"co":[["s'épanouir dans son travail","在工作中得到发展"],["un enfant épanoui","一个开朗舒展的孩子"],["s'épanouir pleinement","充分发展"],["l'épanouissement personnel","个人成长"]],"sy":[["s'accomplir","soutenu","自我实现"],["fleurir","courant","开花、繁荣"],["se réaliser","courant","实现自我"]],"fq":"中频，谈学习、工作、人生时常用。","me":"像花一样 s'épanouit：慢慢打开，长到最好。","tr":{"zh":"她在新学校里过得很好。","fr":"Elle s'épanouit dans sa nouvelle école.","alt":"Elle se sent bien dans sa nouvelle école.","note":"s'épanouir dans + 地点/事物。"}},
 "S'orienter": {"pos":"v.pron. 代词式动词（-er 动词，复合时态助动词 être）","s":"辨明方向（在城市、地图上）；选择专业或职业方向（s'orienter vers les sciences）。学校语境里经常出现：orientation = 升学指导。","ipa":"[sɔ.ʁjɑ̃.te]","ph":"s'o 读 [sɔ]；ien 读 [jɑ̃]；-er 读 [e]。","pi":"ien 在这里读 [jɑ̃]，不是 [jɛ̃]（orient 与 bien 不同）。后面的 vers 不要漏掉。","et":"来自 orient（东方，拉丁语 oriens，「升起」，指日出方向）。原义是「找出东方 = 辨明方向」。同族词：orientation、orient。","ex":[["Après le bac, elle a décidé de s'orienter vers le droit.","高考后她决定转向法律。"],["Je n'arrive pas à m'orienter dans cette ville.","我在这座城市里辨不清方向。"],["Il s'oriente vers une carrière scientifique.","他在往科研职业方向发展。"]],"co":[["s'orienter vers","转向、选择……方向"],["s'orienter dans une ville","在城里辨明方向"],["l'orientation scolaire","升学指导"],["se faire orienter","接受指导"]],"sy":[["se diriger","courant","朝……走、走向"],["choisir","courant","选择"],["se spécialiser","courant","专攻"]],"fq":"中频，谈学业和职业规划时常见。","me":"orient（东方）：找到太阳升起的方向，就是 s'orienter。","tr":{"zh":"我想选择文学方向。","fr":"Je veux m'orienter vers la littérature.","alt":"Je veux faire des études de lettres.","note":"s'orienter vers + 方向。"}},
 "Se cultiver": {"pos":"v.pron. 代词式动词（-er 动词，复合时态助动词 être）","s":"提高文化修养、增长学识（读书、看展览、旅行）。je me cultive = 我在充实自己。注意不要和 cultiver la terre（种地）弄混。","ipa":"[sə.kyl.ti.ve]","ph":"se 弱读 [sə]；u 读 [y]；-er 读 [e]。","pi":"u 读 [y]，不是 [u]。se cultiver 的 cultiver 本身是「种植、培养」，反身形式才是「提高修养」。","et":"来自拉丁语 colere（耕种、培养）。同族词：culture、cultivateur、cultivé。","ex":[["Aller au musée permet de se cultiver facilement.","去博物馆能轻松提升文化修养。"],["Elle lit beaucoup pour se cultiver.","她读很多书来充实自己。"],["Voyager, c'est aussi une façon de se cultiver.","旅行也是一种增长见识的方式。"]],"co":[["se cultiver en lisant","通过阅读提高修养"],["une personne cultivée","有文化修养的人"],["cultiver la terre","耕地"],["cultiver un jardin","种菜、打理花园"]],"sy":[["s'instruire","soutenu","增长知识"],["apprendre","courant","学习"],["s'enrichir","courant","丰富自己"]],"fq":"中频，谈学习、兴趣时常用。","me":"cultiver 本是「耕地」，现在是「耕自己的头脑」。","tr":{"zh":"我喜欢读书来充实自己。","fr":"J'aime lire pour me cultiver.","alt":"Je lis beaucoup pour apprendre des choses.","note":"se cultiver 是反身动词，me 随主语变化。"}},
 "Se focaliser sur": {"pos":"v.pron. 代词式动词（se focaliser sur + 名词；-er 动词，复合时态助动词 être）","s":"把注意力集中在……；盯着某一点。有时带一点「过分只盯着」的意味：Ne te focalise pas sur les détails。比 se concentrer sur 更口语化、更现代。","ipa":"[sə.fɔ.ka.li.ze syʁ]","ph":"o 读 [ɔ]；ca 读 [ka]；s 在 i 与 e 间读 [z]；sur 读 [syʁ]。","pi":"focaliser 中 s 读 [z]；sur 的 u 读 [y]，不是 [u]。介词要用 sur，不是 à。","et":"来自 focal（焦点的），源于拉丁语 focus（炉火，后来指焦点）+ -iser。同族词：foyer、focal。","ex":[["Nous devons nous focaliser sur nos priorités actuelles.","我们必须专注于当前的优先事项。"],["Elle se focalise trop sur ses défauts.","她太盯着自己的缺点了。"],["Concentre-toi : focalise-toi sur l'essentiel.","集中精神，抓住重点。"]],"co":[["se focaliser sur l'essentiel","抓住重点"],["se focaliser sur un détail","盯着一个细节"],["se focaliser sur ses objectifs","专注于目标"],["Ne te focalise pas sur…","别老盯着……"]],"sy":[["se concentrer sur","courant","集中精力于"],["se fixer sur","courant","盯着、固守于"],["s'obséder de","soutenu","着迷、念念不忘"]],"fq":"中频，口语和书面都用，近年很常见。","me":"focus + -iser：把光聚到一个「焦点」上。","tr":{"zh":"我们先专注于最重要的事。","fr":"Focalisons-nous d'abord sur l'essentiel.","alt":"Concentrons-nous d'abord sur l'essentiel.","note":"命令式 focalisons-nous。"}},
 "Valoriser": {"pos":"v.t. 及物动词（-er 动词，助动词 avoir）","s":"提升……的价值；使显得更有价值；肯定、重视（valoriser le travail）。也指开发利用、变废为宝。se valoriser = 提升自己的形象。","ipa":"[va.lɔ.ʁi.ze]","ph":"o 读 [ɔ]；s 在 i 与 e 间读 [z]；-er 读 [e]。","pi":"s 读 [z]；valoriser 的 o 是开口的 [ɔ]。注意 valoriser（提升价值）≠ valider（验证）。","et":"来自 valeur（拉丁语 valere，值得、有力量）+ -iser。同族词：valeur、valable、valorisation。","ex":[["Ce projet met en valeur et valorise les compétences des élèves.","这个项目突出并提升了学生的能力。"],["Cette expérience valorise ton CV.","这段经历让你的简历更有分量。"],["Il faut valoriser le travail des enseignants.","应该重视教师的工作。"]],"co":[["valoriser un CV","让简历更有分量"],["valoriser le travail de qqn","肯定某人的工作"],["se sentir valorisé(e)","感到被认可"],["la valorisation des déchets","垃圾的回收利用"]],"sy":[["mettre en valeur","courant","突出、凸显"],["rehausser","soutenu","提高、增色"],["dévaloriser","courant","贬低（反义）"]],"fq":"中频，工作、学习、新闻中常见。","me":"valeur + -iser：让它的「价值」变大。","tr":{"zh":"这次实习会让你的简历更有分量。","fr":"Ce stage va valoriser ton CV.","alt":"Ce stage, c'est un plus pour ton CV.","note":"valoriser 直接带宾语。"}},
 "Varier": {"pos":"v.t./v.i. 及物兼不及物动词（-er 动词，助动词 avoir）","s":"变化、有差异（Les prix varient）；使多样化、变换（varier les menus）。形容词 varié(e) = 多样的。","ipa":"[va.ʁje]","ph":"结尾 -ier 读 [je]；r 是小舌音。","pi":"nous variions（半过去时）有两个 i；varier 不等于 changer，强调「有变化、不单调」。","et":"来自拉丁语 variare（使多样），源于 varius（各色的）。同族词：variété、variable、variation。","ex":[["Il est conseillé de varier ses méthodes de révision.","建议变换复习方法。"],["Les prix varient selon les saisons.","价格随季节变化。"],["Pour varier, on mange chinois ce soir.","换换口味，今晚吃中餐。"]],"co":[["varier selon","随……而变化"],["varier les plaisirs","变换花样、寻求多样"],["pour varier","为了换换花样"],["varier les menus","变换菜单"]],"sy":[["changer","courant","改变"],["diversifier","soutenu","使多样化"],["fluctuer","soutenu","波动"]],"fq":"中频，日常和书面都用。","me":"vari-：variété 的动词，让东西不单一。","tr":{"zh":"你应该变换一下菜单。","fr":"Tu devrais varier tes menus.","alt":"Change un peu tes menus.","note":"varier 可以是及物，也可以是不及物。"}},
 "Vomir": {"pos":"v.t./v.i. 及物兼不及物动词（第二组，助动词 avoir）","s":"呕吐；吐出。口语也可以说 rendre / dégueuler（很粗俗）。比喻义：vomir qqn = 厌恶透顶。je vomis, nous vomissons。","ipa":"[vɔ.miʁ]","ph":"v 读 [v]；o 读 [ɔ]；结尾 -ir 读 [iʁ]。","pi":"vomir 按第二组变位：nous vomissons，不是 nous vomons。o 读 [ɔ]。","et":"来自拉丁语 vomere（呕吐）。同族词：vomissement、vomitif。","ex":[["Il est malade et n'arrête pas de vomir.","他生病了，不停地呕吐。"],["J'ai envie de vomir.","我想吐。"],["Le bébé a vomi sur mon pull.","宝宝吐在我的毛衣上了。"]],"co":[["avoir envie de vomir","想吐"],["vomir son repas","把饭吐出来"],["se faire vomir","催吐"],["un vomissement","一次呕吐"]],"sy":[["rendre","familier","吐（口语）"],["dégueuler","argot","吐（粗俗）"],["régurgiter","soutenu","反刍、吐出"]],"fq":"中频，生病、身体话题。","me":"vomir 与英语 vomit 几乎一样，很好记。","tr":{"zh":"我吃坏了东西，想吐。","fr":"J'ai mal mangé, j'ai envie de vomir.","alt":"J'ai mangé un truc pas frais, j'ai envie de vomir.","note":"avoir envie de + 动词原形 = 想要。"}},
 "Vulgariser": {"pos":"v.t. 及物动词（-er 动词，助动词 avoir）","s":"普及；把专业内容讲得通俗易懂（vulgariser la science）。在法语里是褒义：不是「粗俗化」。另一个意思是使变得平庸、粗俗，少用。","ipa":"[vyl.ɡa.ʁi.ze]","ph":"u 读 [y]；g 在 a 前读 [ɡ]；s 在 i 与 e 间读 [z]。","pi":"vulgariser 常被中国学生误以为「使粗俗」，其实多指「科普、通俗化」。u 读 [y]。","et":"来自 vulgaire（拉丁语 vulgus，大众、普通人）+ -iser。同族词：vulgaire、vulgarisation。","ex":[["Ce chercheur sait vulgariser des concepts très complexes.","这位研究员善于把复杂的概念讲通俗。"],["Elle vulgarise la science dans ses vidéos.","她在视频里科普科学。"],["Un bon professeur sait vulgariser.","好老师懂得深入浅出。"]],"co":[["vulgariser la science","科普科学"],["vulgariser un concept","把概念讲通俗"],["la vulgarisation scientifique","科学普及"],["un livre de vulgarisation","科普书"]],"sy":[["simplifier","courant","简化"],["expliquer","courant","解释"],["populariser","soutenu","使大众化"]],"fq":"中低频，科普、教学语境。","me":"vulgus = 大众：让大家都能懂。","tr":{"zh":"他把物理讲得很通俗。","fr":"Il sait vulgariser la physique.","alt":"Il explique la physique de façon simple.","note":"vulgariser 是褒义，意为通俗易懂地讲。"}},
 "Alternatif / Alternative": {"pos":"adj. 形容词，阴性 alternative，复数 alternatifs / alternatives；另有名词 une alternative（选择）","s":"可替代的；另类的、非主流的（médecine alternative 替代医学）。名词 une alternative 指「两者择一的选择」，注意英语 alternative 常指「别的办法」。","ipa":"[al.tɛʁ.na.tif]","ph":"al 读 [al]；ter 读 [tɛʁ]；阳性结尾 -if 读 [if]，阴性 -ive 读 [iv]。","pi":"阳性 -if，阴性 -ive，注意读音 [f] 与 [v] 的差别；结尾的 r 要读小舌音。","et":"来自拉丁语 alternare（交替），源于 alter（另一个）。同族词：alterner、alternance、alterner。","ex":[["On parle de plus en plus de consommation alternative.","人们越来越多地谈论替代消费。"],["Il suit une médecine alternative.","他在接受替代医学治疗。"],["Il faut chercher une solution alternative.","要找一个替代方案。"]],"co":[["une solution alternative","替代方案"],["médecine alternative","替代医学"],["énergie alternative","替代能源"],["sans alternative","别无选择"]],"sy":[["de remplacement","courant","替代的"],["parallèle","courant","并行的、另类的"],["marginal","courant","边缘的、非主流的"]],"fq":"中频，新闻、讨论中常见。","me":"alter（另一个）：另一条路。","tr":{"zh":"我们需要一个替代方案。","fr":"Nous avons besoin d'une solution alternative.","alt":"Il nous faut un plan B.","note":"solution 是阴性，所以用 alternative。"}},
 "Anglo-saxon": {"pos":"adj. 形容词，阴性 anglo-saxonne，复数 anglo-saxons","s":"盎格鲁-撒克逊的；泛指英美等英语国家的（文化、体制）：le monde anglo-saxon。法语中常用来笼统指英语世界，不是严格的历史概念。","ipa":"[ɑ̃.ɡlo.sak.sɔ̃]","ph":"an 读 [ɑ̃]；g 读 [ɡ]；x 在 saxon 中读 [ks]；结尾 -on 读 [ɔ̃]。","pi":"x 读 [ks]；阴性是 anglo-saxonne（n 要读出）。可以写成连字符。","et":"由 Angles（盎格鲁人）与 Saxons（撒克逊人）两个日耳曼部族名合成。","ex":[["Le modèle universitaire anglo-saxon privilégie les campus intégrés.","盎格鲁-撒克逊的大学模式偏重一体化校园。"],["Il aime la culture anglo-saxonne.","他喜欢英美文化。"],["Les pays anglo-saxons ont un système différent.","英语国家的体制不一样。"]],"co":[["le monde anglo-saxon","英语世界"],["la culture anglo-saxonne","英美文化"],["le modèle anglo-saxon","英美模式"],["les pays anglo-saxons","英语国家"]],"sy":[["anglophone","courant","说英语的"],["britannique","courant","英国的"],["américain","courant","美国的"]],"fq":"中频，新闻、评论中常见。","me":"Anglo + saxon：像「英美」的合称。","tr":{"zh":"英美的体制不太一样。","fr":"Le système anglo-saxon est un peu différent.","alt":"Dans les pays anglo-saxons, c'est un peu différent.","note":"阴性 anglo-saxonne，复数 anglo-saxons。"}},
 "Archéologique": {"pos":"adj. 形容词，阴阳同形，复数 archéologiques","s":"考古的；考古学的：un site archéologique 考古遗址，des fouilles archéologiques 考古发掘。名词 l'archéologie 考古学，un archéologue 考古学家。","ipa":"[aʁ.ke.ɔ.lɔ.ʒik]","ph":"ch 读 [k]；é 读 [e]；o 读 [ɔ]；g 读 [ʒ]；结尾 -ique 读 [ik]。","pi":"ch 读 [k]，不是 [ʃ]；阴性不变。词较长，按音节慢慢读。","et":"来自希腊语 arkhaios（古老的）+ logos（学问），加后缀 -ique。同族词：archéologie、archéologue、archaïque。","ex":[["Ce site archéologique attire beaucoup de touristes.","这个考古遗址吸引了很多游客。"],["Les fouilles archéologiques ont commencé en mai.","考古发掘五月开始了。"],["Elle visite un musée archéologique.","她在参观考古博物馆。"]],"co":[["un site archéologique","考古遗址"],["des fouilles archéologiques","考古发掘"],["un musée archéologique","考古博物馆"],["une découverte archéologique","考古发现"]],"sy":[["ancien","courant","古老的"],["historique","courant","历史的"],["archéologue","courant","考古学家（名词）"]],"fq":"中低频，旅游和文化话题。","me":"archéo-（古老）+ logique：研究古物的学问。","tr":{"zh":"我们参观了一个考古遗址。","fr":"Nous avons visité un site archéologique.","alt":"On a visité un site de fouilles.","note":"archéologique 阴阳同形。"}},
 "Bilingue": {"pos":"adj./n. 形容词兼名词，阴阳同形，复数 bilingues","s":"双语的；会说两种语言的人（un bilingue）。école bilingue = 双语学校。","ipa":"[bi.lɛ̃ɡ]","ph":"bi 读 [bi]；-lingue 读 [lɛ̃ɡ]，u 不发音。","pi":"-gue 中的 u 不发音，g 读 [ɡ]；ngu 里 n 使前面的 i 变鼻化 [ɛ̃]。阴性不变。","et":"来自拉丁语 bilinguis：bi-（两个）+ lingua（舌头、语言）。同族词：langue、linguistique、trilingue。","ex":[["Elle a grandi au Canada et est parfaitement bilingue.","她在加拿大长大，完全双语。"],["Mon fils va dans une école bilingue.","我儿子上双语学校。"],["Ce dictionnaire est bilingue.","这本词典是双语的。"]],"co":[["être bilingue","会两种语言"],["une école bilingue","双语学校"],["un dictionnaire bilingue","双语词典"],["un enfant bilingue","双语孩子"]],"sy":[["plurilingue","soutenu","多语的"],["trilingue","courant","三语的"],["monolingue","courant","单语的（反义）"]],"fq":"中频，教育和语言话题。","me":"bi（二）+ lingue（舌）：两种「舌头」。","tr":{"zh":"我的孩子是双语的。","fr":"Mes enfants sont bilingues.","alt":"Mes enfants parlent deux langues.","note":"bilingue 阴阳同形，复数加 s。"}},
 "Cérébral(e)": {"pos":"adj. 形容词，阳性 cérébral，阴性 cérébrale，阳性复数 cérébraux","s":"大脑的：activité cérébrale 大脑活动。也可形容人理智、偏用脑的：un travail cérébral 脑力工作。阳性复数是 cérébraux，不是 cérébrals。","ipa":"[se.ʁe.bʁal]","ph":"c 在 é 前读 [s]；é 读 [e]；结尾 -al 读 [al]。","pi":"阳性复数 cérébraux；c 读 [s]，不是 [k]。两个 é 重音方向一致。","et":"来自拉丁语 cerebrum（大脑）+ -al。同族词：cerveau、cérébralité。","ex":[["La lecture stimule notre activité cérébrale.","阅读能刺激大脑活动。"],["Il a eu une lésion cérébrale.","他有脑部损伤。"],["C'est un travail très cérébral.","这是很费脑力的工作。"]],"co":[["l'activité cérébrale","大脑活动"],["une lésion cérébrale","脑损伤"],["un travail cérébral","脑力工作"],["la mort cérébrale","脑死亡"]],"sy":[["mental","courant","头脑的、心理的"],["intellectuel","courant","智力的"],["rationnel","courant","理性的"]],"fq":"中低频，医学和学习话题。","me":"cerveau（大脑）→ cérébral：同一个根。","tr":{"zh":"阅读有助于大脑活动。","fr":"La lecture aide l'activité cérébrale.","alt":"Lire, ça fait travailler le cerveau.","note":"阳性复数 cérébraux。"}},
 "Économique": {"pos":"adj. 形容词，阴阳同形，复数 économiques；也有「省钱的」意思","s":"经济的（la crise économique）；经济实惠的、省钱的（une voiture économique）。名词 l'économie 既是「经济」也是「节约」，les économies = 储蓄。","ipa":"[e.kɔ.nɔ.mik]","ph":"é 读 [e]；c 读 [k]；两个 o 都读 [ɔ]；结尾 -ique 读 [ik]。","pi":"économique 的 é 是起首重音；不要读成「ecologique」；阴阳同形。economique 有 -ique 而非 -ic。","et":"来自希腊语 oikonomia：oikos（家）+ nomos（规则、管理）。同族词：économie、économiser、économiste。","ex":[["Le pays traverse une période de croissance économique.","该国正处于经济增长期。"],["C'est une voiture très économique.","这是一辆很省油（省钱）的车。"],["La situation économique est difficile.","经济形势很困难。"]],"co":[["la croissance économique","经济增长"],["la crise économique","经济危机"],["la situation économique","经济形势"],["une solution économique","省钱的办法"]],"sy":[["financier","courant","财政的、金融的"],["bon marché","courant","便宜的"],["avantageux","courant","划算的"]],"fq":"极高频，新闻和日常常用。","me":"oikos（家）+ nomos（管理）：「管家」之学。","tr":{"zh":"经济形势很复杂。","fr":"La situation économique est compliquée.","alt":"Côté économie, la situation est compliquée.","note":"économique 阴阳同形。"}},
 "Gouvernemental(e)": {"pos":"adj. 形容词，阴性 gouvernementale，阳性复数 gouvernementaux","s":"政府的：une décision gouvernementale。用于政策、机构、官员。阳性复数 gouvernementaux。","ipa":"[ɡu.vɛʁ.nə.mɑ̃.tal]","ph":"ou 读 [u]；er 读 [ɛʁ]；e 弱读 [ə]；en 读 [ɑ̃]；结尾 -al 读 [al]。","pi":"词很长，容易漏音节：gou-ver-ne-men-tal；阳性复数 gouvernementaux。","et":"来自 gouvernement ← gouverner（拉丁语 gubernare，驾驶船只，源自希腊语 kybernan）+ -al。","ex":[["Une nouvelle décision gouvernementale soutient les étudiants.","政府的一项新决定支持学生。"],["Le plan gouvernemental sera annoncé demain.","政府的计划明天公布。"],["Il travaille dans une agence gouvernementale.","他在一个政府机构工作。"]],"co":[["une décision gouvernementale","政府的决定"],["un plan gouvernemental","政府计划"],["une aide gouvernementale","政府补助"],["une agence gouvernementale","政府机构"]],"sy":[["étatique","soutenu","国家的"],["public","courant","公共的"],["officiel","courant","官方的"]],"fq":"中频，新闻常见。","me":"gouvernement + -al：「政府的」。","tr":{"zh":"政府的这项决定很重要。","fr":"Cette décision gouvernementale est importante.","alt":"La décision du gouvernement est importante.","note":"decision 为阴性，所以用 gouvernementale。"}},
 "Homogène": {"pos":"adj. 形容词，阴阳同形，复数 homogènes","s":"同质的；均匀的；一致的。un groupe homogène = 水平、性质相近的群体；un mélange homogène = 均匀的混合物。反义词 hétérogène。","ipa":"[ɔ.mɔ.ʒɛn]","ph":"h 不发音；o 读 [ɔ]；g 读 [ʒ]；è 读 [ɛ]；结尾 n 要读出来。","pi":"h 不发音；结尾 -gène 的 n 读出来，e 不发音；阴阳同形。","et":"来自希腊语 homogenes：homos（相同）+ genos（种类）。同族词：hétérogène、genre、génétique。","ex":[["La classe forme un groupe de niveau très homogène.","这个班水平非常一致。"],["Mélangez jusqu'à obtenir une pâte homogène.","搅拌到面糊均匀为止。"],["Le groupe est assez homogène.","这个群体相当一致。"]],"co":[["un groupe homogène","同质的群体"],["un mélange homogène","均匀的混合物"],["une population homogène","同质的人口"],["un niveau homogène","水平一致"]],"sy":[["uniforme","courant","统一的"],["régulier","courant","有规律的"],["hétérogène","courant","不同质的（反义）"]],"fq":"中频，学术和烹饪语境都有。","me":"homo（相同）+ gène：「同一类」。","tr":{"zh":"我们班的水平很一致。","fr":"Notre classe est très homogène.","alt":"Dans notre classe, tout le monde a le même niveau.","note":"homogène 阴阳同形。"}},
 "Hypocrite": {"pos":"adj./n. 形容词兼名词，阴阳同形，复数 hypocrites","s":"虚伪的；伪善的；表里不一的（人）。un hypocrite = 虚伪的人。名词 l'hypocrisie（虚伪）。","ipa":"[i.pɔ.kʁit]","ph":"h 不发音；y 读 [i]；o 读 [ɔ]；结尾 -ite 读 [it]。","pi":"h 不发音，所以开头是 [i]，前面要用 un hypocrite（连读）；y 读 [i]，不读 [ɛ]。","et":"来自希腊语 hypokrites（演员，演戏的人）。同族词：hypocrisie。","ex":[["C'est une attitude hypocrite de dire le contraire de ce que l'on pense.","说违心的话是虚伪的态度。"],["Il est gentil devant moi, mais hypocrite.","他当着我的面很好，其实很虚伪。"],["Je déteste les gens hypocrites.","我讨厌虚伪的人。"]],"co":[["un sourire hypocrite","虚伪的笑"],["une attitude hypocrite","虚伪的态度"],["l'hypocrisie","虚伪"],["être hypocrite avec qqn","对某人虚伪"]],"sy":[["faux","courant","虚假的"],["fourbe","soutenu","奸诈的"],["sincère","courant","真诚的（反义）"]],"fq":"中频，日常评价人时常用。","me":"hypocrite = 希腊语「演员」：在演戏的人。","tr":{"zh":"我不喜欢虚伪的人。","fr":"Je n'aime pas les gens hypocrites.","alt":"Je déteste les hypocrites.","note":"hypocrite 阴阳同形。"}},
 "Individuel(le)": {"pos":"adj. 形容词，阴性 individuelle，复数 individuels / individuelles","s":"个人的；个别的；单独的。chambre individuelle = 单人房；sport individuel = 个人项目。反义词 collectif。","ipa":"[ɛ̃.di.vi.dɥɛl]","ph":"in 读 [ɛ̃]；uel 读 [ɥɛl]；阳性阴性读音一样。","pi":"阳性 individuel 和阴性 individuelle 读音相同，l 都读出来；uel 读 [ɥɛl]，不是 [yɛl]。","et":"来自 individu（拉丁语 individuus，不可分的）+ -el。同族词：individu、individualisme、divisible。","ex":[["Chaque élève reçoit un accompagnement individuel.","每个学生都得到个别辅导。"],["Je préfère une chambre individuelle.","我更喜欢单人房。"],["Le tennis est un sport individuel.","网球是个人项目。"]],"co":[["une chambre individuelle","单人房"],["un sport individuel","个人项目"],["un cours individuel","一对一课程"],["à titre individuel","以个人名义"]],"sy":[["personnel","courant","个人的"],["particulier","courant","特别的、个别的"],["collectif","courant","集体的（反义）"]],"fq":"中高频，日常和正式场合都常用。","me":"individu（个人）+ -el：属于「一个人」的。","tr":{"zh":"我想订一间单人房。","fr":"Je voudrais réserver une chambre individuelle.","alt":"Je voudrais une chambre pour une personne.","note":"chambre 为阴性，所以 individuelle。"}},
 "Labellisé": {"pos":"adj. 形容词（来自过去分词），阴性 labellisée，复数 labellisés","s":"获得认证标志的、被官方认可的：un produit labellisé 有认证标志的产品。动词是 labelliser。","ipa":"[la.bɛ.li.ze]","ph":"bel 读 [bɛl]；ll 读一个 [l]；s 读 [z]；结尾 -é 读 [e]。","pi":"l 双写但只发一个 [l]；读音 [z] 不是 [s]；阴性 labellisée 读音不变。","et":"来自 label（标签，英语 label，源于古法语）+ -iser。","ex":[["Ce diplôme est labellisé par le ministère.","这个文凭由教育部认证。"],["Ce fromage est labellisé bio.","这款奶酪有有机认证。"],["Une école labellisée « éco-école ».","一所获得环保学校认证的学校。"]],"co":[["un produit labellisé","认证产品"],["être labellisé bio","获得有机认证"],["un diplôme labellisé","认证文凭"],["le label","标志、认证"]],"sy":[["certifié","courant","经过认证的"],["agréé","soutenu","获批的"],["homologué","soutenu","获官方认可的"]],"fq":"中低频，行政和商业语境。","me":"label（标签）：贴了标签就是认可。","tr":{"zh":"这家餐厅有官方认证。","fr":"Ce restaurant est labellisé.","alt":"Ce restaurant a un label.","note":"labellisé 来自过去分词，要和名词一致。"}},
 "Lent(e)": {"pos":"adj. 形容词，阴性 lente，复数 lents / lentes","s":"慢的；缓慢的。也可形容人反应迟缓：Il est lent à comprendre。副词是 lentement。","ipa":"[lɑ̃]","ph":"len 读鼻化元音 [lɑ̃]；t 不发音；阴性 lente 读 [lɑ̃t]，t 要读出。","pi":"阳性 t 不发音 [lɑ̃]，阴性 t 发音 [lɑ̃t]；en 读 [ɑ̃]，不读 [ɛ̃]。","et":"来自拉丁语 lentus（缓慢的，黏的）。同族词：lentement、ralentir、lenteur。","ex":[["Le train avance à une allure très lente.","火车行驶得很慢。"],["Il est lent à réagir.","他反应很慢。"],["La connexion internet est lente aujourd'hui.","今天网速很慢。"]],"co":[["une allure lente","缓慢的速度"],["lent à + inf.","做某事很慢"],["une mort lente","缓慢的死亡"],["à feu doux / à feu lent","文火慢炖"]],"sy":[["tranquille","courant","平稳的"],["rapide","courant","快的（反义）"],["paresseux","courant","懒散的"]],"fq":"高频，日常常用。","me":"lent → ralentir：想到慢下来。","tr":{"zh":"今天的网络很慢。","fr":"Internet est lent aujourd'hui.","alt":"Ça rame aujourd'hui, Internet.","note":"lent(e) 阳性 t 不发音，阴性发音。"}},
 "Mental(e)": {"pos":"adj. 形容词，阴性 mentale，阳性复数 mentaux","s":"精神的；心理的；头脑中的：santé mentale 心理健康。calcul mental = 心算。名词 le mental 指心理素质。","ipa":"[mɑ̃.tal]","ph":"men 读 [mɑ̃]；结尾 -al 读 [al]。","pi":"men 读 [mɑ̃]，不是 [mɛ̃] 或 [mɛn]；阳性复数是 mentaux。","et":"来自拉丁语 mentalis，源于 mens, mentis（心智）。同族词：mentalité、mentalement。","ex":[["Le calcul mental est un bon entraînement pour l'esprit.","心算是很好的头脑训练。"],["Il faut prendre soin de sa santé mentale.","要关心自己的心理健康。"],["Il fait du calcul mental.","他在做心算。"]],"co":[["le calcul mental","心算"],["la santé mentale","心理健康"],["une maladie mentale","精神疾病"],["un effort mental","脑力付出"]],"sy":[["psychologique","courant","心理的"],["intellectuel","courant","智力的"],["physique","courant","身体的（反义）"]],"fq":"中频，健康、学习话题。","me":"mens（心智）→ mental：与英语 mental 同源。","tr":{"zh":"心理健康很重要。","fr":"La santé mentale est très importante.","alt":"Il faut prendre soin de sa santé mentale.","note":"santé 为阴性，所以 mentale。"}},
 "Néfaste": {"pos":"adj. 形容词，阴阳同形，复数 néfastes","s":"有害的；不利的；招来不幸的。多接 effet / influence / conséquence：un effet néfaste。比 mauvais 更书面。","ipa":"[ne.fast]","ph":"é 读 [e]；f 读 [f]；-aste 读 [ast]，s 要读出，结尾 e 不发音。","pi":"néfaste 中 s 要读出 [s]；不要读成 [ne.fas]；阴阳同形。","et":"来自拉丁语 nefastus（不吉利的），ne-（不）+ fas（神法允许）。","ex":[["Le manque de sommeil a un effet néfaste sur la mémoire.","睡眠不足对记忆有害。"],["Le tabac est néfaste pour la santé.","烟草对健康有害。"],["Cette décision a eu des conséquences néfastes.","这个决定造成了不良后果。"]],"co":[["un effet néfaste","有害的影响"],["néfaste pour la santé","对健康有害"],["une influence néfaste","不良影响"],["des conséquences néfastes","不良后果"]],"sy":[["nuisible","courant","有害的"],["nocif","courant","有毒的、有害的"],["bénéfique","courant","有益的（反义）"]],"fq":"中低频，书面和新闻常用。","me":"ne-fast：ne = 不，fas = 允许：「不被允许」的坏事。","tr":{"zh":"熬夜对健康有害。","fr":"Veiller tard est néfaste pour la santé.","alt":"Se coucher tard, c'est mauvais pour la santé.","note":"néfaste pour + 名词。"}},
 "Parallèle": {"pos":"adj. 形容词，阴阳同形，复数 parallèles；也是名词 le parallèle（对比）/ la parallèle（平行线）","s":"平行的；并行的；同时进行的；另类的（marché parallèle 黑市）。en parallèle = 同时、并行。名词 un parallèle = 对比。","ipa":"[pa.ʁa.lɛl]","ph":"è 读 [ɛ]；ll 读 [l]；结尾 -le 的 e 不发音。","pi":"ll 在 parallèle 中读一个 [l]（不是 [j]）；拼写 ll 在 è 之后；阴阳同形。","et":"来自希腊语 parallêlos：para（旁边）+ allêlôn（彼此）。","ex":[["Elle mène une activité sportive en parallèle de ses études.","她在学习的同时进行体育活动。"],["Ces deux rues sont parallèles.","这两条街是平行的。"],["Il faut faire un parallèle entre les deux cas.","要把这两个情况做个对比。"]],"co":[["en parallèle","同时、并行"],["des lignes parallèles","平行线"],["un marché parallèle","黑市"],["faire un parallèle","做对比"]],"sy":[["simultané","soutenu","同时的"],["équivalent","courant","相当的"],["perpendiculaire","courant","垂直的（反义）"]],"fq":"中频，学习、工作、数学都用。","me":"para（旁边）+ allêlon：「并肩而行」。","tr":{"zh":"她一边工作一边学习。","fr":"Elle travaille en parallèle de ses études.","alt":"Elle étudie et travaille en même temps.","note":"en parallèle de + 名词。"}},
 "Ralenti(e)": {"pos":"adj. 形容词（来自 ralentir 的过去分词），阴性 ralentie，复数 ralentis","s":"放慢了的；减速了的。也作名词 le ralenti = 慢动作：au ralenti 慢速；une scène au ralenti。","ipa":"[ʁa.lɑ̃.ti]","ph":"ra 读 [ʁa]；len 读 [lɑ̃]；结尾 -ti 读 [ti]；阴性 ralentie 读音不变。","pi":"不要把 ralenti 读成 [ʁa.lɛn.ti]；en 读 [ɑ̃]；阴性不变读音。","et":"来自 ralentir：re- + a- + lent + -ir。同族词：lent、lentement、ralentissement。","ex":[["La circulation est ralentie à cause des travaux.","因为施工，交通变慢了。"],["Le film passe au ralenti.","电影在慢放。"],["La croissance est ralentie.","增长放缓了。"]],"co":[["au ralenti","慢速地、放慢"],["circulation ralentie","交通缓慢"],["tourner au ralenti","慢速运转"],["un rythme ralenti","放缓的节奏"]],"sy":[["freiné","courant","被减速的"],["lent","courant","慢的"],["accéléré","courant","加速的（反义）"]],"fq":"中频，交通、新闻中常见。","me":"ralenti → lent：由「慢」派生。","tr":{"zh":"因为下雨，交通变慢了。","fr":"La circulation est ralentie à cause de la pluie.","alt":"Ça roule lentement à cause de la pluie.","note":"circulation 为阴性，所以 ralentie。"}},
 "Réaliste": {"pos":"adj./n. 形容词兼名词，阴阳同形，复数 réalistes","s":"现实的；务实的；写实的。être réaliste = 看清现实、不抱不切实际的幻想。名词 réalisme、反义词 irréaliste。","ipa":"[ʁe.a.list]","ph":"ré 读 [ʁe]；a 单独一个音节 [a]；-iste 读 [ist]，s 要读出。","pi":"ré-a 要分开读成两个音节，不要连成 [ʁja]；s 读出；英语 realistic 以 -ic 结尾，法语是 -iste。","et":"来自 réel（拉丁语 res，事物）+ -iste。同族词：réalité、réalisme、réaliser。","ex":[["Il faut se fixer des objectifs de révision réalistes.","应该设定现实的复习目标。"],["Sois réaliste, ce n'est pas possible.","现实一点，这不可能。"],["C'est un film très réaliste.","这是一部很写实的电影。"]],"co":[["un objectif réaliste","现实的目标"],["Sois réaliste !","现实一点！"],["un projet réaliste","可行的计划"],["un portrait réaliste","写实的肖像"]],"sy":[["pragmatique","soutenu","务实的"],["concret","courant","具体的"],["irréaliste","courant","不现实的（反义）"]],"fq":"中高频，日常评价常用。","me":"réel（真实）+ -iste：站在「真实」一边。","tr":{"zh":"你的目标要现实一点。","fr":"Il faut fixer des objectifs réalistes.","alt":"Vise des objectifs réalistes.","note":"réaliste 阴阳同形。"}},
 "Récurrent(e)": {"pos":"adj. 形容词，阴性 récurrente，复数 récurrents / récurrentes","s":"反复出现的；经常发生的。un problème récurrent = 老是出现的问题。名词 la récurrence。","ipa":"[ʁe.ky.ʁɑ̃]","ph":"é 读 [e]；u 读 [y]；-rrent 读 [ʁɑ̃]，rr 读一个 [ʁ]，结尾 -nt 不发音；阴性 [ʁɑ̃t]。","pi":"rr 读一个 [ʁ]；u 读 [y]；阳性 -ent 读 [ɑ̃]，t 不发音；阴性 t 发音。","et":"来自拉丁语 recurrere（跑回来），re- + currere（跑）。同族词：courir、récurrence、concurrent。","ex":[["C'est un problème récurrent dans notre organisation.","这是我们机构里反复出现的问题。"],["Il fait des cauchemars récurrents.","他反复做噩梦。"],["Ce thème est récurrent dans son œuvre.","这个主题在他的作品里反复出现。"]],"co":[["un problème récurrent","反复出现的问题"],["un thème récurrent","反复出现的主题"],["une erreur récurrente","常犯的错误"],["de façon récurrente","反复地"]],"sy":[["répété","courant","重复的"],["fréquent","courant","频繁的"],["persistant","soutenu","持续的"]],"fq":"中频，书面和新闻中常见。","me":"re + courir：一次又一次「跑回来」。","tr":{"zh":"这是一个老问题。","fr":"C'est un problème récurrent.","alt":"C'est un problème qui revient tout le temps.","note":"problème 为阳性，所以 récurrent。"}},
 "Scolaire": {"pos":"adj. 形容词，阴阳同形，复数 scolaires","s":"学校的；与学校教育相关的：l'année scolaire 学年，le matériel scolaire 学习用品，les vacances scolaires 学校假期。","ipa":"[skɔ.lɛʁ]","ph":"sc 读 [sk]；o 读 [ɔ]；-aire 读 [ɛʁ]，r 要读出。","pi":"sc 读 [sk]，不是 [s]；结尾 -aire 读 [ɛʁ]；阴阳同形。","et":"来自拉丁语 scholaris，源于 schola（学校，原为希腊语 skholê，闲暇）。同族词：école、scolarité。","ex":[["Le calendrier scolaire prévoit deux semaines de vacances.","校历安排两周假期。"],["Les enfants ont leur matériel scolaire.","孩子们有自己的学习用品。"],["Les vacances scolaires commencent demain.","学校假期明天开始。"]],"co":[["l'année scolaire","学年"],["les vacances scolaires","学校假期"],["le matériel scolaire","学习用品"],["la rentrée scolaire","开学"]],"sy":[["universitaire","courant","大学的"],["éducatif","courant","教育的"],["académique","soutenu","学术的"]],"fq":"高频，学校话题里很常用。","me":"école ← schola：scolaire 保留了 sc 的拼写。","tr":{"zh":"学校假期从下周开始。","fr":"Les vacances scolaires commencent la semaine prochaine.","alt":"Les vacances commencent la semaine prochaine.","note":"scolaire 阴阳同形。"}},
 "Sur-mesure": {"pos":"adj. 形容词，不变；也作名词 le sur-mesure","s":"量身定制的；按需定做的：une formation sur-mesure。常见写法 sur mesure 或 sur-mesure。可用于服装、课程、服务。","ipa":"[syʁ.mə.zyʁ]","ph":"sur 读 [syʁ]；me 弱读 [mə]；s 在元音间读 [z]；结尾 -ure 读 [yʁ]。","pi":"两个 u 都读 [y]；s 读 [z]；做形容词时通常不变（des services sur-mesure）。","et":"由 sur（在……上）+ mesure（尺寸）组成，原指裁缝的「按尺寸做」。","ex":[["L'institut propose une formation sur-mesure pour chaque étudiant.","学院为每个学生提供量身定制的培训。"],["Il porte un costume sur mesure.","他穿一套量身定做的西装。"],["Cette agence offre un voyage sur mesure.","这家旅行社提供定制旅行。"]],"co":[["un costume sur mesure","定制西装"],["une formation sur-mesure","定制培训"],["un service sur-mesure","定制服务"],["faire du sur-mesure","做定制"]],"sy":[["personnalisé","courant","个性化的"],["adapté","courant","适应的"],["standard","courant","标准化的（反义）"]],"fq":"中频，商业和教育语境。","me":"sur + mesure：照着你的「尺寸」来做。","tr":{"zh":"我们提供定制服务。","fr":"Nous proposons un service sur mesure.","alt":"On fait du sur-mesure.","note":"sur-mesure 作形容词不变化。"}},
 "Universitaire": {"pos":"adj./n. 形容词兼名词，阴阳同形，复数 universitaires","s":"大学的：l'année universitaire 学年，la vie universitaire 大学生活。名词 un(e) universitaire = 大学老师或研究人员。","ipa":"[y.ni.vɛʁ.si.tɛʁ]","ph":"u 读 [y]；i 读 [i]；ver 读 [vɛʁ]；结尾 -aire 读 [ɛʁ]。","pi":"第一个 u 读 [y]，不是 [u]；结尾 r 要读出；阴阳同形。","et":"来自 université（拉丁语 universitas，整体、团体）+ -aire。同族词：université、univers。","ex":[["L'année universitaire commence en septembre.","大学学年九月开始。"],["Il fait des études universitaires.","他在上大学。"],["La vie universitaire est très riche.","大学生活很丰富。"]],"co":[["l'année universitaire","大学学年"],["des études universitaires","大学学业"],["un diplôme universitaire","大学文凭"],["une cité universitaire","大学生宿舍区"]],"sy":[["scolaire","courant","学校的"],["académique","soutenu","学术的"],["estudiantin","littéraire","大学生的"]],"fq":"高频，大学话题里常用。","me":"université + -aire：「大学的」。","tr":{"zh":"大学学年九月开始。","fr":"L'année universitaire commence en septembre.","alt":"La rentrée à l'université est en septembre.","note":"universitaire 阴阳同形。"}},
 "Scrupuleusement": {"pos":"adv. 副词，不变","s":"一丝不苟地；严格地；认真地：suivre scrupuleusement les consignes。形容词 scrupuleux / scrupuleuse，名词 le scrupule。","ipa":"[skʁy.py.lø.zə.mɑ̃]","ph":"scr 读 [skʁ]；u 读 [y]；eu 读 [ø]；s 读 [z]；-ment 读 [mɑ̃]。","pi":"词很长：scru-pu-leu-se-ment；scr 读 [skʁ]，别漏 k；-ment 读 [mɑ̃]，t 不发音。","et":"来自 scrupuleux ← scrupule（拉丁语 scrupulus，小尖石子，引申为不安）+ -ment。","ex":[["Elle suit scrupuleusement les consignes de sécurité.","她一丝不苟地遵守安全规定。"],["Il vérifie scrupuleusement chaque détail.","他认真核对每个细节。"],["Les règles sont scrupuleusement respectées.","规则被严格遵守。"]],"co":[["respecter scrupuleusement","严格遵守"],["suivre scrupuleusement","严格遵循"],["vérifier scrupuleusement","仔细核查"],["sans scrupule","毫无顾忌"]],"sy":[["rigoureusement","soutenu","严格地"],["minutieusement","courant","细致地"],["strictement","courant","严格地"]],"fq":"中低频，书面、正式场合。","me":"scrupule（小石子）：连一颗小石子也要管。","tr":{"zh":"请严格遵守规定。","fr":"Respectez scrupuleusement le règlement, s'il vous plaît.","alt":"Merci de bien respecter le règlement.","note":"scrupuleusement 修饰动词。"}},
 "Toutefois": {"pos":"adv. 副词，不变（连接性副词）","s":"然而；不过；但是。表示转折，比 mais 更书面、更温和：Le test est difficile ; toutefois, il reste abordable。常放在句首或句中，后面常有逗号。","ipa":"[tu.tə.fwa]","ph":"ou 读 [u]；te 弱读 [tə]；oi 读 [wa]；结尾 s 不发音。","pi":"toutefois 末尾 s 不发音；不要和 tout à fait（完全）混淆；toutefois ≠ toujours（总是）。","et":"由 tout + fois 组成，原义「每一次」，后来变成转折义。","ex":[["Le test est difficile, toutefois il reste abordable.","考试很难，然而还是可以应对的。"],["Je viendrai ; toutefois, je ne resterai pas longtemps.","我会来，不过不会待很久。"],["C'est cher ; toutefois, la qualité est excellente.","价格贵，但质量极好。"]],"co":[["Toutefois, …","然而，……"],["sans toutefois + inf.","但并不……"],["toutefois il faut noter que…","不过要注意……"],["mais toutefois","不过话说回来"]],"sy":[["cependant","soutenu","然而"],["pourtant","courant","可是"],["néanmoins","soutenu","尽管如此"]],"fq":"中频，书面和正式场合常见。","me":"tout + fois：「无论如何」。","tr":{"zh":"价格贵，不过质量很好。","fr":"C'est cher ; toutefois, la qualité est très bonne.","alt":"C'est cher, mais la qualité est très bonne.","note":"toutefois 前面常用分号或逗号。"}},
 "De sorte que": {"pos":"loc.conj. 连词短语，后接直陈式或虚拟式","s":"以便；结果；以至于。后接直陈式表示结果（如此以至于），后接虚拟式表示目的（以便）：Il s'est organisé de sorte qu'il ait du temps libre。","ipa":"[də sɔʁt kə]","ph":"de 读 [də]；sorte 读 [sɔʁt]，r 要读；que 读 [kə]，元音前缩略为 qu'。","pi":"表示目的要用虚拟式（qu'il ait），表示结果用直陈式（qu'il a）；别和 de sorte à + 动词原形混淆。","et":"sorte 来自拉丁语 sors（命运、份额），后来变成「种类、方式」。","ex":[["Il s'est organisé de sorte qu'il ait du temps libre le soir.","他安排好时间，晚上有空闲。"],["Parle fort de sorte que tout le monde t'entende.","大声说，让大家都听得到。"],["Il a plu toute la nuit, de sorte que la route est inondée.","下了一整夜雨，结果路被淹了。"]],"co":[["de sorte que + subj.","以便（目的）"],["de sorte que + ind.","因此，结果（结果）"],["de sorte à + inf.","为了（动词原形）"],["en sorte que","使得"]],"sy":[["afin que","soutenu","以便（目的，接虚拟式）"],["pour que","courant","为了"],["si bien que","courant","所以（结果）"]],"fq":"中频，书面和正式场合常见。","me":"sorte = 方式：「以这种方式……」。","tr":{"zh":"我提前出门，以便不迟到。","fr":"Je pars tôt de sorte que je ne sois pas en retard.","alt":"Je pars tôt pour ne pas être en retard.","note":"表目的时 de sorte que 后用虚拟式。"}},
 "In fine": {"pos":"loc. 拉丁语短语，副词性，不变","s":"最终；到最后；总之。来自拉丁语，书面和正式场合使用，常放句首：In fine, c'est le jury qui décide。","ipa":"[in.fi.ne]","ph":"in 读 [in]，不是鼻化元音 [ɛ̃]（拉丁语读法）；fine 读 [fi.ne]，e 读 [e]。","pi":"这是拉丁语，in 读 [in]，fine 读 [fi.ne]，不要读成法语的 [fin]；不能拆开用。","et":"拉丁语 in fine，意为「在末尾」，in（在）+ finis（末尾）。同族词：fin、finir、final。","ex":[["In fine, c'est le jury qui prendra la décision finale.","最终由评审团做最后决定。"],["In fine, tout dépend de toi.","归根结底，一切取决于你。"],["Le projet sera validé in fine par le directeur.","项目最后由主管批准。"]],"co":[["In fine, …","最终，……"],["décider in fine","最后决定"],["valider in fine","最终批准"],["in fine = en fin de compte","即「归根结底」"]],"sy":[["finalement","courant","最后"],["en fin de compte","courant","归根结底"],["en définitive","soutenu","总而言之"]],"fq":"低频，书面、法律、学术用语。","me":"in fine ≈ fin：到「最后」。","tr":{"zh":"最后由经理决定。","fr":"In fine, c'est le directeur qui décide.","alt":"En fin de compte, c'est le directeur qui décide.","note":"in fine 是书面语，口语多说 finalement。"}},
 "À défaut": {"pos":"loc.adv. 副词短语，常用 à défaut de + 名词/动词原形","s":"若没有……；没有的话就……；退而求其次。à défaut de qqch = 如果没有某物；à défaut = 若不行的话。","ipa":"[a de.fo]","ph":"à 读 [a]；dé 读 [de]；faut 读 [fo]，aut 读 [o]，t 不发音。","pi":"défaut 的 t 不发音；别拼成 defau；à défaut de 后面接名词或动词原形，不要加冠词 le（à défaut du 才对 le 的缩合）。","et":"défaut 来自 défaillir（缺乏），拉丁语 fallere（欺骗、使失败）。同族词：faute、défaillir、falloir。","ex":[["À défaut de trouver un stage, il suivra des cours d'été.","找不到实习的话，他就上暑期课。"],["On peut prendre le bus, à défaut de train.","没有火车就坐公交。"],["Je prends du thé, à défaut de café.","没有咖啡，我就喝茶。"]],"co":[["à défaut de qqch","如果没有某物"],["à défaut de + inf.","无法做某事的话"],["à défaut, …","否则，……"],["faire défaut","缺乏"]],"sy":[["faute de","soutenu","由于缺少"],["sinon","courant","否则"],["en l'absence de","soutenu","在没有……的情况下"]],"fq":"中频，书面和正式场合常见。","me":"défaut = 缺：「缺了它，就用别的」。","tr":{"zh":"没有地铁，就坐公交。","fr":"À défaut de métro, on prendra le bus.","alt":"Pas de métro ? On prend le bus.","note":"à défaut de + 名词，de 后不加冠词。"}},
 "À la lettre": {"pos":"loc.adv. 副词短语，不变","s":"一字不差地；严格按字面。prendre qqch à la lettre = 照字面理解；suivre les consignes à la lettre = 一丝不苟地执行。","ipa":"[a la lɛtʁ]","ph":"à 读 [a]；lettre 读 [lɛtʁ]，tt 读一个 [t]，结尾 e 不发音。","pi":"lettre 的 tt 读一个 [t]；e 不发音；别和 lecture 混淆。lettre 是阴性，所以是 à la lettre。","et":"lettre 来自拉丁语 littera（字母）。同族词：littéral、littérature、lettré。","ex":[["Il a respecté les instructions à la lettre.","他严格遵守了指示。"],["Ne prends pas tout à la lettre.","别什么都照字面理解。"],["Elle suit la recette à la lettre.","她严格按食谱做。"]],"co":[["suivre à la lettre","严格遵循"],["prendre à la lettre","照字面理解"],["respecter à la lettre","严格遵守"],["au pied de la lettre","完全照字面"]],"sy":[["mot à mot","courant","逐字地"],["scrupuleusement","soutenu","一丝不苟地"],["littéralement","courant","字面上"]],"fq":"中频，日常和正式都用。","me":"lettre = 字母：一个字母一个字母地照做。","tr":{"zh":"他严格按说明书做。","fr":"Il suit le mode d'emploi à la lettre.","alt":"Il fait tout exactement comme c'est écrit.","note":"à la lettre 前不加冠词变化。"}},
 "Avoir l'embarras du choix": {"pos":"loc. verbale 动词短语（avoir + l'embarras 阳性名词）","s":"选择太多，反而难以决定。embarras 这里指「因太多而为难」，不是「尴尬」。常用 On a l'embarras du choix. = 选择多得挑花了眼。","ipa":"[a.vwaʁ lɑ̃.ba.ʁa dy ʃwa]","ph":"l'embarras 是 l' + embarras，em 读鼻化元音 [ɑ̃]；embarras 结尾 s 不发音；choix 的 x 不发音，读 [ʃwa]。","pi":"embarras 最后的 -as 不发音；choix 末尾 x 不发音；不要把 embarras 当成「尴尬」的意思来理解整个短语。","et":"embarras 由动词 embarrasser（使为难、堵住）派生；短语意思是「选择多到令人为难」。具体词源来源不确定。","ex":[["Avec tous ces programmes, on a l'embarras du choix.","有这么多项目，选择太多了。"],["Au marché, on a l'embarras du choix.","在市场里，什么都有，挑不过来。"]],"co":[["avoir l'embarras du choix","选择多得难以决定"],["On a l'embarras du choix.","任君挑选"],["l'embarras du choix","选择困难"]],"sy":[["avoir beaucoup de choix","courant","选择很多，比较平淡"],["avoir plein de choix","familier","选择多得很，口语"]],"fq":"中频，日常和商店、旅游场景常用。","me":"embarras = 被太多东西「堵住」，所以「挑不出来」。","tr":{"zh":"这家餐厅的菜太多了，选择困难。","fr":"Dans ce restaurant, on a l'embarras du choix.","alt":"Il y a tellement de plats qu'on ne sait pas quoi choisir.","note":"常用 on a / j'ai / vous avez l'embarras du choix，固定搭配不拆开。"}},
 "Avoir un pied dans": {"pos":"loc. verbale 动词短语（avoir + un pied + dans）","s":"字面「有一只脚在……里」，比喻已经进入某个领域、已经入了门。后面接 dans + 名词：avoir un pied dans le monde du travail。也有「身处两个世界」的用法：avoir un pied dans chaque camp。","ipa":"[a.vwaʁ œ̃ pje dɑ̃]","ph":"pied 读 [pje]，结尾 d 不发音；dans 读 [dɑ̃]，ns 不发音；un 读鼻化 [œ̃]。","pi":"pied 末尾 d 不发音；dans [dɑ̃] 和 dent [dɑ̃] 同音；短语本身不完整，后面必须接具体的领域。","et":"pied 来自拉丁语 pes, pedis（脚）；同源词 pédale（踏板）、piéton（行人）。","ex":[["Avec ce stage, il a déjà un pied dans le monde professionnel.","通过这次实习，他已踏入职场。"],["Elle a un pied dans la mode et un pied dans le cinéma.","她一只脚在时尚圈，一只脚在电影圈。"]],"co":[["avoir un pied dans la porte","（谈判中）已经有了切入口"],["avoir un pied dans le monde du travail","已踏入职场"],["avoir un pied dans chaque camp","脚踏两边"]],"sy":[["être entré dans","courant","已经进入（更平淡）"],["avoir le pied à l'étrier","soutenu","已经起步、有了好的开端"]],"fq":"中低频，口语和新闻中偶见。","me":"想象一只脚已经跨进门槛，人还没完全进去。","tr":{"zh":"她已经踏入了出版行业。","fr":"Elle a déjà un pied dans le monde de l'édition.","alt":"Elle a déjà mis un pied dans l'édition.","note":"avoir un pied dans + 领域名词，dans 后面要加冠词。"}},
 "Boire \"cul sec\"": {"pos":"loc. verbale 动词短语（boire + cul sec）","s":"一口气喝完杯里的酒，干杯到底。cul sec 是口语用语，通常在聚会、喝酒时说。也可以单独喊 Cul sec ! = 干杯、一口闷！","ipa":"[bwaʁ kyl sɛk]","ph":"boire 读 [bwaʁ]；cul 读 [ky]，l 在这里与后面连读，所以 cul sec 通常读 [kyl sɛk]；sec 结尾 c 要发 [k]。","pi":"cul 的 l 在这个固定用语里要发音 [kyl]；cul 在日常里是粗俗词（屁股），所以这个短语属于较随便的口语，正式场合不用。","et":"cul = 屁股、底部（拉丁语 culus）；sec = 干的。字面意思是「喝到杯底干了」。","ex":[["Lors de la fête, ils ont bu leur verre cul sec.","聚会上他们一口喝干了杯子。"],["Il a bu son shot cul sec.","他一口干了那杯烈酒。"]],"co":[["boire cul sec","一饮而尽"],["Cul sec !","干杯！一口闷！"],["boire d'un trait","一口气喝完"]],"sy":[["boire d'un trait","courant","一口气喝完，中性"],["vider son verre","courant","喝光杯子"],["boire d'une traite","courant","一口气喝完"]],"fq":"中频，只用于口语和聚会。","me":"cul = 杯底，sec = 干：喝到杯底都干了。","tr":{"zh":"他把整杯啤酒一口喝干了。","fr":"Il a bu toute sa bière cul sec.","alt":"Il a vidé sa bière d'un trait.","note":"cul sec 放在宾语后面，像副词一样修饰 boire。"}},
 "Coucher ensemble / Coucher avec quelqu'un": {"pos":"loc. verbale 动词短语（coucher 第一组动词，用 avoir 变位）","s":"委婉地说「发生性关系」，睡在一起。coucher avec quelqu'un 比 coucher ensemble 更直接。注意 dormir ensemble 只是「一起睡觉」，不一定有性关系。","ipa":"[ku.ʃe ɑ̃.sɑ̃.blə] / [ku.ʃe a.vɛk kɛl.kœ̃]","ph":"coucher 读 [ku.ʃe]，ch 读 [ʃ]；ensemble 读 [ɑ̃.sɑ̃.blə]，en 和 em 都是鼻化 [ɑ̃]；quelqu'un 读 [kɛl.kœ̃]。","pi":"ensemble 里两个鼻音都是 [ɑ̃]，不要读成 [ɛn]；coucher avec 在意思上很直白，用在口语和朋友之间，长辈或正式场合应避免；复合过去时用 avoir：ils ont couché ensemble。","et":"coucher 来自拉丁语 collocare（放置、安放），后来变为「放平、躺下」；同源词 se coucher（躺下睡觉）。","ex":[["Ils se sont rencontrés hier et ont couché ensemble.","他们昨天才认识，就睡在了一起。"],["Elle ne veut pas coucher avec lui.","她不想和他发生关系。"]],"co":[["coucher avec quelqu'un","和某人发生性关系"],["coucher ensemble","睡在一起"],["se coucher","上床睡觉"]],"sy":[["faire l'amour","courant","做爱，中性、较委婉"],["dormir ensemble","courant","只是一起睡，不一定有性关系"],["se taper quelqu'un","argot","（俚语、粗俗）和某人上床"]],"fq":"高频，日常口语常用，语气较随便。","me":"coucher = 放平；两个人「一起放平」= 睡在一起。","tr":{"zh":"他们在一起三个月了，还没有睡在一起。","fr":"Ils sont ensemble depuis trois mois, mais ils n'ont pas encore couché ensemble.","alt":"Ça fait trois mois qu'ils sont ensemble, mais ils n'ont pas encore couché.","note":"复合过去时 ont couché 用 avoir；sont ensemble 指「在一起、交往」。"}},
 "De A à Z": {"pos":"loc. adverbiale 副词短语","s":"从头到尾，从A到Z，一个环节都不漏。常修饰动词：gérer / préparer / organiser de A à Z。","ipa":"[də a a zɛd]","ph":"A 读 [a]，à 也读 [a]，Z 的字母名读 [zɛd]；de 读 [də]。三个元音 a-a 连在一起，要分开读。","pi":"字母 Z 在法语里读 [zɛd]，不是英语的 zee；à 的重音不要漏写。","et":"A 和 Z 是字母表的第一个和最后一个字母；意思是「从第一个字母到最后一个」。","ex":[["Elle a géré l'organisation de l'événement de A à Z.","她从头到尾负责活动的组织。"],["J'ai lu le livre de A à Z.","我把这本书从头到尾读了一遍。"]],"co":[["organiser quelque chose de A à Z","从头到尾组织某事"],["connaître quelque chose de A à Z","对某事了如指掌"],["tout expliquer de A à Z","从头到尾解释一遍"]],"sy":[["du début à la fin","courant","从头到尾，更中性"],["de bout en bout","courant","从头到尾，强调完整"],["de fond en comble","courant","彻底地（常用于打扫、翻找）"]],"fq":"中高频，日常常用。","me":"字母表从 A 到 Z：整个流程，不留遗漏。","tr":{"zh":"他从头到尾亲自做了这个项目。","fr":"Il a fait ce projet lui-même, de A à Z.","alt":"Ce projet, il l'a fait tout seul du début à la fin.","note":"de A à Z 放在句末或动词之后，像副词一样用。"}},
 "Dresser le portrait de": {"pos":"loc. verbale 动词短语（dresser 第一组动词，用 avoir 变位）","s":"描绘某人（或某事）的形象，写出人物特写。可以是画像，也可以是文字描写，多用于文章、报道、采访。后面接 de + 人。","ipa":"[dʁe.se lə pɔʁ.tʁɛ də]","ph":"dresser 读 [dʁe.se]，ss 读 [s]，er 结尾读 [e]；portrait 读 [pɔʁ.tʁɛ]，ai 读 [ɛ]，结尾 t 不发音。","pi":"portrait 结尾的 t 不发音；dresser 的 ss 读清音 [s]；注意 dresser 在这里是「建立、勾画」，不是「训练动物」。","et":"dresser 来自拉丁语 directiare（拉直、使笔直），与 droit（直的）同源；portrait 来自动词 portraire（画出），是 pourtraire 的变体。","ex":[["L'article dresse le portrait d'un étudiant brillant.","这篇文章描绘了一位优秀学生的形象。"],["Le journaliste dresse le portrait de la ministre.","记者给女部长画了一幅人物特写。"]],"co":[["dresser le portrait de quelqu'un","描绘某人的形象"],["dresser un tableau de la situation","描述现状"],["un portrait fidèle","逼真的描写"]],"sy":[["décrire","courant","描述，更日常"],["brosser le portrait de","soutenu","勾勒……的形象，书面常用"],["peindre","littéraire","描绘，文学色彩强"]],"fq":"中频，常见于新闻和书面语。","me":"dresser = 把形象「立起来」，一笔一笔勾出一个人。","tr":{"zh":"这本书描绘了一位年轻艺术家的形象。","fr":"Ce livre dresse le portrait d'un jeune artiste.","alt":"Dans ce livre, l'auteur fait le portrait d'un jeune artiste.","note":"dresser le portrait de + 人，常用于第三人称现在时。"}},
 "En avoir assez / \"J'en ai assez !\"": {"pos":"loc. verbale 动词短语（avoir 变位 + en + assez）","s":"受够了，烦透了。en 代替「这件事」，后面可加 de + 名词或不定式：J'en ai assez de ce bruit。语气比 J'en ai marre ! 稍正式一点。","ipa":"[ɑ̃.na.vwaʁ a.se]","ph":"J'en ai 读 [ʒɑ̃.ne]，en 与 ai 连读；assez 读 [a.se]，ss 读 [s]，结尾 z 不发音。","pi":"assez 末尾 z 不发音；en 在句子里不能省；assez 在这里是「够了」，意思是「太多了」，不是「还算不错」。","et":"assez 来自拉丁语 ad satis（足够），satis 同源于 satisfaire（使满足）；en 是代词，代替前面提到的事。","ex":[["J'en ai assez de répéter toujours la même chose !","我受够了总是重复同样的话！"],["Il en a assez de son travail.","他受够了自己的工作。"]],"co":[["en avoir assez de + 名词 / 不定式","受够了……"],["J'en ai assez !","我受够了！"],["en avoir assez de tout","对一切都厌倦了"]],"sy":[["en avoir marre","familier","烦死了，口语最常说"],["en avoir ras le bol","familier","受够了，非常口语"],["ne plus supporter","courant","再也受不了"]],"fq":"高频，日常口语很常用。","me":"assez = 够了；对某事「已经够了」，所以受够了。","tr":{"zh":"我受够了这场雨！","fr":"J'en ai assez de cette pluie !","alt":"J'en ai marre de cette pluie !","note":"en avoir assez de + 名词；de 后面可以接不定式。"}},
 "En vue de": {"pos":"loc. prép. 介词短语","s":"为了……，为……做准备。后面接名词或不定式，说明目标：en vue de l'examen / en vue de préparer。比 pour 更书面、更强调「为之做准备」。另外 en vue 单独用有「看得见、在视野内」的意思。","ipa":"[ɑ̃ vy də]","ph":"en 读鼻化 [ɑ̃]；vue 读 [vy]，u 是 [y]（嘴唇圆而紧）；结尾 e 不发音。","pi":"vue 里的 u 读 [y]，不要读成 [u]（ou）；vue 结尾的 e 不发音；en vue de 后面不接从句，要接名词或不定式。","et":"vue 是动词 voir（看）的名词，来自过去分词 vu(e)；字面意思是「着眼于」。","ex":[["Il s'entraîne tous les jours en vue de l'examen.","他每天训练，为了准备考试。"],["Elle économise en vue de ses vacances.","她为了度假而存钱。"]],"co":[["en vue de + 名词","为了……"],["en vue de + 不定式","为了做……"],["en vue d'un changement","为了某个改变"]],"sy":[["pour","courant","为了，最常用最简单"],["dans le but de","courant","目的是……"],["afin de","soutenu","为了（书面）"]],"fq":"中频，书面和正式场合较常见。","me":"vue = 视线：把目标放在「眼前」，朝它去做准备。","tr":{"zh":"她为了考试而每天复习。","fr":"Elle révise tous les jours en vue de l'examen.","alt":"Elle révise tous les jours pour préparer l'examen.","note":"en vue de + 名词 / 不定式，不接从句。"}},
 "Et si... ?": {"pos":"loc. 固定短语，句首用法（et + si）","s":"「要是……会怎样？」或「要不……吧？」两种用法：一是提出假设（Et si elle ne vient pas ?），二是提建议（Et si on allait au cinéma ?）。提建议时动词用未完成过去时。","ipa":"[e si]","ph":"et 读 [e]，t 不发音；si 读 [si]；两个词之间不连读，在句子里有明显停顿，声调上扬。","pi":"提建议时 si 后面用未完成过去时（on allait），不是现在时；et 的 t 不发音；si 遇到 il / ils 会变成 s'il / s'ils。","et":"et 来自拉丁语 et（和）；si 来自拉丁语 si（如果）；合起来表示在对话中顺势抛出一个设想。","ex":[["Et si on allait étudier à la bibliothèque aujourd'hui ?","要不我们今天去图书馆学习？"],["Et si elle refusait ?","要是她拒绝了呢？"]],"co":[["Et si on + 未完成过去时 ?","要不我们……？"],["Et si + 假设 ?","如果……怎么办？"],["Et si tu essayais ?","你要不要试试？"]],"sy":[["Si on + 未完成过去时 ?","courant","要不……（不带 et，更短）"],["Pourquoi ne pas + 不定式 ?","courant","为什么不……呢"],["Que dirais-tu de + 不定式 ?","soutenu","你觉得……如何？"]],"fq":"极高频，日常对话非常常用。","me":"Et si… = 「要不……？」，后面动词用 -ais / -ait 的未完成式。","tr":{"zh":"要不我们明天去爬山？","fr":"Et si on allait faire une randonnée demain ?","alt":"On pourrait aller faire une randonnée demain, non ?","note":"提建议：et si + on + 未完成过去时（allait）。"}},
 "Être au service de": {"pos":"loc. verbale 动词短语（être + au service de）","s":"为……服务，供……使用，为……所用。主语可以是人、团队或机构：L'équipe est au service des usagers。也常说 mettre quelque chose au service de quelqu'un（把……用来为某人服务）。","ipa":"[ɛtʁ o sɛʁ.vis də]","ph":"être 读 [ɛtʁ]；au 读 [o]；service 读 [sɛʁ.vis]，c 在这里不出现，ce 读 [s]；结尾 e 不发音。","pi":"service 里的 r 要发 [ʁ]，不要省略；au = à + le，合并成 au；de 后面接复数时变 des：au service des usagers。","et":"service 来自拉丁语 servitium（奴役、服务），与 servir（服务）、serviteur（仆人）同源。","ex":[["L'équipe est au service des usagers tous les jours.","团队每天为用户服务。"],["Cette application est au service des étudiants.","这个应用是为学生服务的。"]],"co":[["être au service de quelqu'un","为某人服务"],["mettre quelque chose au service de","把……用于为……服务"],["à votre service","愿为您效劳"],["au service du public","为公众服务"]],"sy":[["servir","courant","为……服务，更简单"],["être dédié à","courant","专门用于"],["être à la disposition de","soutenu","供……随时使用"]],"fq":"中频，机构介绍和正式场合常见。","me":"service = 服务：站在「服务」的一边，为对方所用。","tr":{"zh":"这家医院为所有居民服务。","fr":"Cet hôpital est au service de tous les habitants.","alt":"Cet hôpital sert tous les habitants.","note":"au service de + 名词；de 与复数名词连用要变成 des。"}},
 "Être destiné à": {"pos":"loc. verbale 动词短语（être + destiné，形容词随主语变化：destiné/e/s/es）","s":"专为……而设，是给……用的；也可表示「注定要……」：Il est destiné à réussir。后面接名词或不定式，主语的阴阳性、单复数会影响 destiné 的形式。","ipa":"[ɛtʁ dɛs.ti.ne a]","ph":"destiné 读 [dɛs.ti.ne]，e 读 [ɛ]，ti 读 [ti]，é 读 [e]；à 读 [a]。","pi":"destiné 的 -é 结尾读 [e]，阴性加 e 读音不变；复数加 s 不发音：destinés、destinées 都读 [dɛs.ti.ne]；à 后面如果接 le / les 要变成 au / aux：destiné aux étudiants。","et":"destiné 来自动词 destiner，源自拉丁语 destinare（决定、指定）；同源词 destin（命运）、destination（目的地）。","ex":[["Ce programme est destiné aux étudiants boursiers.","这个项目面向获得奖学金的学生。"],["Ce cadeau est destiné à ma sœur.","这份礼物是给我姐姐的。"]],"co":[["être destiné à + 名词","专为……而设"],["être destiné à + 不定式","注定要……"],["destiné aux enfants","面向儿童的"],["un message destiné à","发给……的信息"]],"sy":[["être fait pour","courant","是为……做的"],["être réservé à","courant","仅限……使用"],["s'adresser à","courant","面向……（人群）"]],"fq":"中高频，产品说明和正式文本常用。","me":"destiné ≈ destin：命运已经安排它去「某处」或「某人」。","tr":{"zh":"这门课是为初学者设计的。","fr":"Ce cours est destiné aux débutants.","alt":"Ce cours est fait pour les débutants.","note":"destiné à + le/les → destiné au / aux；阴性单数写 destinée。"}},
 "Faire le buzz": {"pos":"loc. verbale 动词短语（faire + le buzz，buzz 阳性名词）","s":"引发热议，在网上走红，一下子被很多人谈论。buzz 来自英语。多用于视频、新闻、广告。faire le buzz 强调「引起轰动」，不一定是好事。","ipa":"[fɛʁ lə bœz]","ph":"faire 读 [fɛʁ]，ai 读 [ɛ]；buzz 在法语里读 [bœz]，不是 [bʌz]，u 读 [œ]，zz 读 [z]。","pi":"buzz 的 u 读 [œ]，不读英语的 [ʌ]，也不读 [y]；faire 的 ai 读 [ɛ]，不是 [e]；注意用 le buzz，不能省略冠词。","et":"来自英语 buzz（嗡嗡声、流言），20 世纪后期进入法语，随互联网流行。","ex":[["Sa vidéo sur les astuces d'études a fait le buzz sur internet.","他关于学习技巧的视频在网上火了。"],["Cette publicité a fait le buzz.","这则广告引起了热议。"]],"co":[["faire le buzz","走红，引起轰动"],["un buzz médiatique","媒体热议"],["faire le buzz sur les réseaux sociaux","在社交网络上火起来"]],"sy":[["devenir viral","courant","走红（病毒式传播）"],["faire parler de soi","courant","让人谈论自己"],["faire sensation","soutenu","引起轰动"]],"fq":"中频，网络和媒体常用，带年轻感。","me":"buzz = 嗡嗡声：大家都在议论，一片嗡嗡。","tr":{"zh":"这首歌在网上火了。","fr":"Cette chanson a fait le buzz sur internet.","alt":"Cette chanson est devenue virale sur internet.","note":"faire le buzz 的复合过去时：a fait le buzz。"}},
 "Faire un/le point": {"pos":"loc. verbale 动词短语（faire + un point / le point，point 阳性名词）","s":"总结目前情况，盘点进展。faire le point (sur) = 就某事做一次小结。faire un point 是口语里更随意的说法，常用于工作会议。","ipa":"[fɛʁ œ̃ pwɛ̃] / [fɛʁ lə pwɛ̃]","ph":"faire 读 [fɛʁ]；point 读 [pwɛ̃]，oi 读 [wa] 这里与 n 合成 [wɛ̃]；结尾 t 不发音。","pi":"point 结尾的 t 不发音，oin 读 [wɛ̃]；faire le point 不是「得分」；后面常接 sur：faire le point sur la situation。","et":"point 来自拉丁语 punctum（点、刺点）；这里「点」指航海中在海图上标出船位，后来引申为「弄清现状」。","ex":[["Nous faisons le point sur la situation chaque lundi matin.","每周一早上我们总结一下情况。"],["On fait un point rapide avant la réunion ?","开会前我们快速碰一下情况吧？"]],"co":[["faire le point sur","就……做总结"],["faire un point rapide","快速碰个头"],["faire le point de la situation","盘点现状"],["un point d'étape","阶段性小结"]],"sy":[["résumer","courant","概括、总结"],["dresser un bilan","soutenu","做总结（常指结果）"],["se mettre à jour","courant","互相更新情况"]],"fq":"高频，工作和学习中非常常用。","me":"point：在地图上点一个点，弄清自己现在在哪里。","tr":{"zh":"我们每个月总结一次进展。","fr":"Nous faisons le point sur le projet chaque mois.","alt":"On fait un point tous les mois sur l'avancement.","note":"faire le point sur + 名词；口语也说 faire un point。"}},
 "Mettre à disposition": {"pos":"loc. verbale 动词短语（mettre 不规则动词，用 avoir 变位）","s":"提供……使用，供……使用，让别人随时可以用。结构：mettre quelque chose à la disposition de quelqu'un / mettre à disposition quelque chose。常见于机构、学校、公司的服务介绍。","ipa":"[mɛtʁ a dis.po.zi.sjɔ̃]","ph":"mettre 读 [mɛtʁ]，ett 读 [ɛt]；disposition 读 [dis.po.zi.sjɔ̃]，s 在元音间读 [z]，-tion 读 [sjɔ̃]。","pi":"disposition 中第二个 s 读 [z]，-tion 读 [sjɔ̃]，不是 [tjɔ̃]；mettre 的 -tre 结尾 e 轻读或不发音；去掉冠词时可以说 à disposition，保留冠词时是 à la disposition de。","et":"disposition 来自拉丁语 dispositio（安排、布置）；mettre 来自拉丁语 mittere（放、送）；同源词 permettre、promettre。","ex":[["Le campus met à disposition des ordinateurs pour les élèves.","校园为学生提供电脑。"],["La ville met des vélos à disposition des habitants.","城市向居民提供自行车。"]],"co":[["mettre à disposition","提供使用"],["mettre à la disposition de quelqu'un","供某人使用"],["à votre disposition","随时为您提供"],["être à disposition","可供使用"]],"sy":[["fournir","courant","提供"],["proposer","courant","提供、提议"],["offrir","courant","（免费）提供、赠送"]],"fq":"中高频，服务、行政和公告里常见。","me":"mettre（放）+ disposition（可支配）：把东西「放在你可支配的范围内」。","tr":{"zh":"图书馆向学生提供免费电脑。","fr":"La bibliothèque met des ordinateurs gratuits à disposition des étudiants.","alt":"La bibliothèque met à la disposition des étudiants des ordinateurs gratuits.","note":"mettre à disposition + 宾语；对象用 de / des 引出。"}},
 "Mettre en application": {"pos":"loc. verbale 动词短语（mettre 不规则动词，用 avoir 变位）","s":"付诸应用，把学到的知识、规则、计划用到实践中。常见宾语：des connaissances, une méthode, une règle。比 mettre en pratique 稍书面。","ipa":"[mɛtʁ ɑ̃ a.pli.ka.sjɔ̃]","ph":"mettre 读 [mɛtʁ]；en 读 [ɑ̃]，和 application 之间有轻微连读感；application 读 [a.pli.ka.sjɔ̃]，-tion 读 [sjɔ̃]。","pi":"application 里 -tion 读 [sjɔ̃]；en 与后面的 a 之间不要加 [n]，直接读 [ɑ̃ a]；不要把 application 误认为「手机应用」，在这里是「运用」。","et":"application 来自拉丁语 applicatio，动词 appliquer 来自 applicare（贴近、使用）；同源词 applicable（可应用的）。","ex":[["Les élèves mettent en application ce qu'ils ont appris en classe.","学生们把课堂所学付诸实践。"],["Il faut mettre ces conseils en application.","要把这些建议付诸实施。"]],"co":[["mettre en application","付诸应用"],["mettre une règle en application","实施一项规则"],["la mise en application","实施，应用"]],"sy":[["mettre en pratique","courant","付诸实践，更常用"],["appliquer","courant","运用"],["mettre en oeuvre","courant","实施，更偏计划和措施"]],"fq":"中频，学习、工作和书面语里常见。","me":"en application：知识从书本里「走进」实际操作。","tr":{"zh":"我想把这些建议付诸实践。","fr":"Je veux mettre ces conseils en application.","alt":"Je veux mettre ces conseils en pratique.","note":"mettre + 宾语 + en application：宾语放在中间。"}},
 "Mettre en oeuvre": {"pos":"loc. verbale 动词短语（mettre 不规则动词，用 avoir 变位；正式拼写 œuvre）","s":"实施，落实，执行（计划、措施、方案、政策）。mettre en œuvre un plan = 执行一个计划。名词形式 la mise en œuvre = 实施。适合正式场合。","ipa":"[mɛtʁ ɑ̃.nœvʁ]","ph":"mettre 读 [mɛtʁ]；en œuvre 连读，读 [ɑ̃.nœvʁ]；œuvre 读 [œvʁ]，œu 读 [œ]；结尾 -vre 里的 e 不发音。","pi":"œuvre 的 œu 读 [œ]（接近「厄」），不读 [u]；en œuvre 要做连诵（liaison），中间加 [n]；正式拼写是 œuvre，书里写 oeuvre 是简写。","et":"œuvre 来自拉丁语 opera（工作、作品）；mettre en œuvre 字面是「把……投入工作」；同源词 opération、manœuvre。","ex":[["L'équipe va mettre en oeuvre un nouveau plan d'action.","团队将实施新的行动计划。"],["La mairie a mis en œuvre plusieurs mesures.","市政府实施了几项措施。"]],"co":[["mettre en œuvre un plan","实施计划"],["la mise en œuvre","实施，落实"],["mettre en œuvre des moyens","投入手段"],["mettre tout en œuvre pour","竭尽全力去……"]],"sy":[["appliquer","courant","运用、实施"],["réaliser","courant","实现"],["exécuter","soutenu","执行（命令、计划）"]],"fq":"中高频，书面语和工作场合常见。","me":"œuvre = 作品、工作：把计划真正「投入工作」。","tr":{"zh":"公司将落实这项新政策。","fr":"L'entreprise va mettre en œuvre cette nouvelle politique.","alt":"L'entreprise va appliquer cette nouvelle politique.","note":"mettre en œuvre + 宾语；名词为 la mise en œuvre。"}},
 "Monter en compétences": {"pos":"loc. verbale 动词短语（monter 第一组动词，此处作不及物，复合时态用 être：il est monté en compétences）","s":"提升技能，能力不断提高。这是近些年常见的职场用语，指通过培训、实践增强能力。用复数 compétences。","ipa":"[mɔ̃.te ɑ̃ kɔ̃.pe.tɑ̃s]","ph":"monter 读 [mɔ̃.te]，on 读鼻化 [ɔ̃]；en 读 [ɑ̃]；compétences 读 [kɔ̃.pe.tɑ̃s]，c 在 om 前读 [k]，结尾 ce 读 [s]。","pi":"on [ɔ̃] 和 en [ɑ̃] 两个鼻音容易混淆；compétences 结尾的 -nces 读 [ɑ̃s]，注意 e 不发音；monter 后面是 en，不是 de。","et":"monter 来自拉丁语 mons（山）；compétence 来自拉丁语 competentia（适合、相当）；「爬山」的比喻延伸为「能力上升」。","ex":[["Cette formation permet de monter en compétences rapidement.","这个培训能快速提升技能。"],["Il veut monter en compétences avant de changer de poste.","他想先提升能力再换岗位。"]],"co":[["monter en compétences","提升技能"],["monter en puissance","逐步增强"],["la montée en compétences","能力提升"],["développer ses compétences","发展技能"]],"sy":[["se perfectionner","courant","精进、提高"],["progresser","courant","进步"],["développer ses compétences","courant","发展能力"]],"fq":"中频，职场和教育场景近年常用。","me":"monter = 往上爬；爬的是「能力」这座山。","tr":{"zh":"我想通过这个培训提升自己的技能。","fr":"Je veux monter en compétences grâce à cette formation.","alt":"Je veux développer mes compétences avec cette formation.","note":"monter en + 抽象名词表示在某方面「提升」；不加冠词。"}},
 "Quel que soit": {"pos":"loc. 固定短语（quel 随后面名词变化：quel / quelle / quels / quelles + que soit / que soient）","s":"无论……，不管是什么……。quel 要与后面的名词性数一致：quelle que soit la situation, quels que soient les problèmes。后面用虚拟式 soit。","ipa":"[kɛl kə swa]","ph":"quel 读 [kɛl]，que 读 [kə]，soit 读 [swa]，结尾 t 不发音；三个词连着读，quel 的 l 要发音。","pi":"quel 要和名词一致：quelle / quels / quelles；soit 在复数时变成 soient（读音仍是 [swa]）；quel que 分写，不要和 quelque 合写。","et":"quel 来自拉丁语 qualis（什么样的）；soit 是动词 être 的虚拟式第三人称单数；整体是「不管它是什么样」。","ex":[["Quel que soit votre niveau, vous pouvez vous inscrire à cet atelier.","无论你水平如何，都可以报名这个工作坊。"],["Quelle que soit la raison, c'est interdit.","不管是什么原因，这都被禁止。"]],"co":[["quel que soit + 单数名词","无论是……"],["quels que soient + 复数名词","无论是……（复数）"],["quelle que soit la situation","无论情况如何"],["quoi qu'il arrive","不管发生什么"]],"sy":[["peu importe","courant","不管，口语更常用"],["n'importe quel","courant","任何一个"],["quoi qu'il en soit","soutenu","无论如何（总结时）"]],"fq":"中高频，书面语和正式口语常见。","me":"quel que soit：quel 跟着名词变，soit 跟着名词变数。","tr":{"zh":"无论天气如何，我们都会去。","fr":"Quel que soit le temps, nous irons.","alt":"Peu importe le temps, on y va.","note":"quel 与 temps 一致，用阳性单数 quel。"}},
 "Relever un défi": {"pos":"loc. verbale 动词短语（relever 第一组动词，用 avoir 变位）","s":"迎接挑战，接受挑战并努力完成。relever 在这里是「接起来」，类似「拾起对方扔下的手套」。常用于工作、比赛、学习。défi 是阳性名词。","ipa":"[ʁə.lve œ̃ de.fi]","ph":"relever 读 [ʁə.lve]，第一个 e 读弱元音 [ə]，r 读小舌音 [ʁ]；défi 读 [de.fi]，结尾 i 读 [i]。","pi":"relever 是 e 变 è 的动词：il relève，nous relevons；défi 末尾无需发音；relever 还有「指出（错误）」「扶起」等意思，要看搭配。","et":"relever 由 re- + lever（举起、抬起）构成，拉丁语 levare；défi 来自动词 défier（挑战），最早的意思是「向对方挑战决斗」。","ex":[["Elle est prête à relever ce défi avec son équipe.","她准备好与团队迎接这个挑战。"],["Il a relevé le défi avec courage.","他勇敢地接受了挑战。"]],"co":[["relever un défi","迎接挑战"],["lancer un défi à quelqu'un","向某人发起挑战"],["un défi de taille","巨大的挑战"],["être prêt à relever le défi","准备好迎接挑战"]],"sy":[["affronter","courant","面对"],["accepter un défi","courant","接受挑战"],["se lancer un défi","courant","给自己立目标"]],"fq":"中高频，工作、体育、新闻里常见。","me":"relever = 重新举起来：把落在地上的「挑战书」捡起来。","tr":{"zh":"我们准备好迎接这个挑战。","fr":"Nous sommes prêts à relever ce défi.","alt":"On est prêts à relever le défi.","note":"relever un défi 是固定搭配，relever 不要换成 lever。"}},
 "Se mettre dans le bain": {"pos":"loc. verbale 代词式动词短语（se mettre，用 être 变位，复合时态过去分词与主语一致）","s":"进入状态，渐渐适应新工作、新环境。字面「泡进浴缸里」，引申为开始融入、投入某件事。常说 se mettre dans le bain = 慢慢找到感觉。","ipa":"[sə mɛtʁ dɑ̃ lə bɛ̃]","ph":"mettre 读 [mɛtʁ]；dans 读 [dɑ̃]，结尾 ns 不发音；bain 读 [bɛ̃]，ain 读鼻化 [ɛ̃]，结尾不发 n。","pi":"bain 的 ain 读 [ɛ̃]，不读 [ɑ̃]；dans 的 an 读 [ɑ̃]，二者容易混淆；代词式动词复合时态用 être：je me suis mis(e) dans le bain。","et":"bain 来自拉丁语 balneum（浴室）；比喻意思是「跳进水里开始游」，引申为投入一件事。","ex":[["Il m'a fallu deux jours pour me mettre dans le bain au travail.","我花了两天才在工作中进入状态。"],["Après les vacances, il est difficile de se remettre dans le bain.","放假之后，很难重新进入状态。"]],"co":[["se mettre dans le bain","进入状态"],["se remettre dans le bain","重新进入状态"],["être dans le bain","已经融入、已经投入"],["mettre quelqu'un dans le bain","让某人尽快上手"]],"sy":[["s'adapter","courant","适应"],["se mettre au rythme","courant","跟上节奏"],["prendre ses marques","courant","熟悉环境、找到位置"]],"fq":"中频，口语常用。","me":"泡进浴缸：身体慢慢适应水温，也就是慢慢进入状态。","tr":{"zh":"我花了一周才适应新工作。","fr":"Il m'a fallu une semaine pour me mettre dans le bain dans mon nouveau travail.","alt":"J'ai mis une semaine à me mettre dans le bain au boulot.","note":"se mettre dans le bain：me / te / se 随主语变化。"}},
 "Se replier sur soi": {"pos":"loc. verbale 代词式动词短语（se replier 第一组动词，用 être 变位）","s":"封闭自己，缩进自己的小世界，不与外界交流。多指情绪低落、受挫后的状态，也可说 se replier sur soi-même。此处的 soi 是重读代词，泛指「自己」。","ipa":"[sə ʁə.pli.e syʁ swa]","ph":"replier 读 [ʁə.pli.e]，ier 读 [je] 或分成 [i.e]；sur 读 [syʁ]，u 读 [y]；soi 读 [swa]。","pi":"sur 的 u 读 [y]，不读 [u]；soi 是重读代词，不是 se；主语是 je 时要说 me replier sur moi-même，不能写 sur soi；soi 一般与不定式、泛指（on, il faut）搭配。","et":"replier = re- + plier（折叠），拉丁语 plicare；字面「把自己折回来」；同源词 pli（褶）、plier（折）。","ex":[["Il ne faut pas se replier sur soi en cas de difficultés.","遇到困难不要封闭自己。"],["Depuis son échec, elle se replie sur elle-même.","自从失败之后，她把自己封闭起来。"]],"co":[["se replier sur soi","封闭自我"],["se replier sur soi-même","把自己封闭起来"],["un repli sur soi","自我封闭"],["éviter le repli sur soi","避免自我封闭"]],"sy":[["s'isoler","courant","孤立自己"],["se renfermer","courant","把自己关起来，不愿交流"],["se couper du monde","courant","与世隔绝"]],"fq":"中低频，多见于书面和心理、社会话题。","me":"replier = 折叠；把自己像纸一样折起来，不对外打开。","tr":{"zh":"不要把自己封闭起来，要和朋友聊聊。","fr":"Il ne faut pas se replier sur soi, il faut parler à ses amis.","alt":"Ne te replie pas sur toi-même, parle à tes amis.","note":"泛指用 soi，指具体的人要用 moi-même / toi-même 等。"}},
 "Sur le terrain": {"pos":"loc. adverbiale 副词短语（terrain 阳性名词）","s":"在现场，在一线，在实地。指不在办公室而在实际工作的地点：travailler sur le terrain。也可指运动场地：Les joueurs sont sur le terrain。","ipa":"[syʁ lə te.ʁɛ̃]","ph":"sur 读 [syʁ]；terrain 读 [te.ʁɛ̃]，ain 读鼻化 [ɛ̃]，结尾 n 不发音。","pi":"terrain 的 ain 读 [ɛ̃]，不读 [ɑ̃]；sur 的 u 读 [y]；不是「地球」，也不是「土地」，而是「场地、现场」。","et":"terrain 来自拉丁语 terrenum（土地的），源自 terra（土地、大地）；同源词 terre、territoire。","ex":[["Les apprentis apprennent leur métier directement sur le terrain.","学徒们直接在一线学习技能。"],["Les journalistes sont sur le terrain depuis ce matin.","记者们从今早起一直在现场。"]],"co":[["travailler sur le terrain","在一线工作"],["aller sur le terrain","去现场"],["l'expérience du terrain","实地经验"],["un homme de terrain","一线工作者"]],"sy":[["sur place","courant","在当地、在现场"],["en situation réelle","courant","在真实情境中"],["en pratique","courant","实际上、在实践中"]],"fq":"高频，工作、新闻、体育里常用。","me":"terrain ≈ terre：脚踩在真实的土地上。","tr":{"zh":"她多年在一线做志愿者。","fr":"Elle est bénévole sur le terrain depuis des années.","alt":"Ça fait des années qu'elle travaille comme bénévole sur le terrain.","note":"sur le terrain 放句末，修饰整个动作。"}},
 "Tout au long de": {"pos":"loc. prép. 介词短语","s":"整个……期间，贯穿……始终。后面接表示时间段的名词：tout au long de l'année / de sa vie / du voyage。强调「从头到尾持续」。也可用于空间：tout au long de la rivière（沿着整条河）。","ipa":"[tu o lɔ̃ də]","ph":"tout 读 [tu]，结尾 t 不发音；au 读 [o]；long 读 [lɔ̃]，g 不发音；de 读 [də]。","pi":"long 结尾的 g 不发音；tout 结尾的 t 不发音；tout au long de 后面要加冠词：tout au long de l'année，不能省略；这里 long 不变形。","et":"long 来自拉丁语 longus（长的）；字面意思是「完全沿着……的长度」，同源词 longueur（长度）、allonger（拉长）。","ex":[["Le professeur accompagne les élèves tout au long de l'année.","老师全年陪伴学生。"],["Il a travaillé dur tout au long de sa carrière.","他整个职业生涯都很努力。"]],"co":[["tout au long de l'année","全年"],["tout au long de la journée","一整天"],["tout au long de sa vie","一生"],["tout au long du chemin","一路上"]],"sy":[["pendant","courant","在……期间，更简单"],["durant","soutenu","在……期间（书面）"],["du début à la fin","courant","从头到尾"]],"fq":"高频，日常和书面都常用。","me":"tout + long：整条线「全长」，不漏掉任何一段。","tr":{"zh":"整个夏天他都在这里工作。","fr":"Il a travaillé ici tout au long de l'été.","alt":"Il a travaillé ici pendant tout l'été.","note":"tout au long de + 定冠词 + 名词。"}},
 "Un gage de": {"pos":"loc. nominale 名词短语（gage 阳性名词，复数 gages）","s":"……的保证，……的证明或象征。gage 本意是「抵押物、押金」，引申为「保证」。un gage de qualité = 质量的保证。也可指恋人之间的信物：un gage d'amour。","ipa":"[œ̃ gaʒ də]","ph":"un 读 [œ̃]；gage 读 [gaʒ]，g 在 a 前读 [g]，第二个 g 在 e 前读 [ʒ]，结尾 e 不发音；de 读 [də]。","pi":"gage 里两个 g 读音不同：第一个 [g]，第二个 [ʒ]；gage 是阳性名词（un gage）；不要和 garage 混淆。","et":"gage 来自古法兰克语（日耳曼语）*wadi，意思是「抵押」；同源词 engager（使承诺）、gageure（打赌）。","ex":[["Ce diplôme d'État est un gage de compétence.","这个国家文凭是能力的保证。"],["Cette marque est un gage de qualité.","这个牌子是质量的保证。"]],"co":[["un gage de qualité","质量的保证"],["un gage de confiance","信任的凭证"],["un gage d'amitié","友谊的信物"],["en gage de","作为……的证明"]],"sy":[["une garantie","courant","保证、担保"],["une preuve","courant","证明"],["un témoignage","soutenu","见证、表示"]],"fq":"中频，书面和广告里常见。","me":"gage = 押下去的东西，用它「保证」你说的话是真的。","tr":{"zh":"这个标签是质量的保证。","fr":"Ce label est un gage de qualité.","alt":"Ce label garantit la qualité.","note":"un gage de + 无冠词的抽象名词（qualité, confiance）。"}},
 "Vis à vis de": {"pos":"loc. prép. 介词短语（标准写法 vis-à-vis de）","s":"对于……，对……而言，关于……。常用于说明对某人的态度或责任：avoir des devoirs vis-à-vis de quelqu'un。也可指「面对面、在……对面」，名词 un vis-à-vis = 对面的人。","ipa":"[vi.za.vi də]","ph":"vis 的 s 与后面的 à 连读，读 [z]，整个读 [vi.za.vi]；de 读 [də]。","pi":"vis à vis 中的 s 要连读成 [z]，读 [vi.za.vi]；标准拼写要加连字符：vis-à-vis；vis-à-vis de 后面接名词或人称重读代词（vis-à-vis de lui）。","et":"vis 是古法语 vis（脸），来自拉丁语 visus（视线、面容）；字面意思是「脸对着脸」，同源词 visage（脸）。","ex":[["Il a des devoirs vis à vis de ses camarades d'équipe.","他对队友有责任。"],["Elle est honnête vis-à-vis de ses clients.","她对客户很诚实。"]],"co":[["vis-à-vis de quelqu'un","对某人"],["avoir des devoirs vis-à-vis de","对……有责任"],["se sentir responsable vis-à-vis de","对……感到有责任"],["un vis-à-vis","对面的人"]],"sy":[["envers","courant","对……，更简单"],["à l'égard de","soutenu","对于……，更书面"],["par rapport à","courant","相对于、与……相比"]],"fq":"中高频，书面和正式口语常见。","me":"vis-à-vis = 脸对脸：站在对方面前，有所交代。","tr":{"zh":"他对客户很诚实。","fr":"Il est honnête vis-à-vis de ses clients.","alt":"Il est honnête envers ses clients.","note":"vis-à-vis de + 名词；de 后接 le / les 要缩合成 du / des。"}}
});
